n    Keypad2 = 614,\n    Keypad3 = 615,\n    Keypad4 = 616,\n    Keypad5 = 617,\n    Keypad6 = 618,\n    Keypad7 = 619,\n    Keypad8 = 620,\n    Keypad9 = 621,\n    KeypadDecimal = 622,\n    KeypadDivide = 623,\n    KeypadMultiply = 624,\n    KeypadSubtract = 625,\n    KeypadAdd = 626,\n    KeypadEnter = 627,\n    KeypadEqual = 628,\n    AppBack = 629,\n    AppForward = 630,\n    GamepadStart = 631,\n    GamepadBack = 632,\n    GamepadFaceLeft = 633,\n    GamepadFaceRight = 634,\n    GamepadFaceUp = 635,\n    GamepadFaceDown = 636,\n    GamepadDpadLeft = 637,\n    GamepadDpadRight = 638,\n    GamepadDpadUp = 639,\n    GamepadDpadDown = 640,\n    GamepadL1 = 641,\n    GamepadR1 = 642,\n    GamepadL2 = 643,\n    GamepadR2 = 644,\n    GamepadL3 = 645,\n    GamepadR3 = 646,\n    GamepadLStickLeft = 647,\n    GamepadLStickRight = 648,\n    GamepadLStickUp = 649,\n    GamepadLStickDown = 650,\n    GamepadRStickLeft = 651,\n    GamepadRStickRight = 652,\n    GamepadRStickUp = 653,\n    GamepadRStickDown = 654,\n    MouseLeft = 655,\n    MouseRight = 656,\n    MouseMiddle = 657,\n    MouseX1 = 658,\n    MouseX2 = 659,\n    MouseWheelX = 660,\n    MouseWheelY = 661,\n    COUNT = 666,\n    ModCtrl = 4096,\n    ModShift = 8192,\n    ModAlt = 16384,\n    ModSuper = 32768,\n    KeyPadEnter = 627,\n}\n\n\n---@enum Mod\nImGui.Mod = {\n    None = 0,\n    Ctrl = 4096,\n    Shift = 8192,\n    Alt = 16384,\n    Super = 32768,\n    Shortcut = 2048,\n    Mask_ = 63488,\n}\n\n\n---@param key Key\n---@return boolean\nfunction ImGui.IsKeyDown(key) end\n\n\n---@param key Key\n---@return boolean\nfunction ImGui.IsKeyPressed(key) end\n\n---@param key Key\n---@param repeat_ boolean\n---@return boolean\nfunction ImGui.IsKeyPressed(key, repeat_) end\n\n\n---@param key Key\n---@return boolean\nfunction ImGui.IsKeyReleased(key) end\n\n\n---@param key Key\n---@param repeat_delay number\n---@param rate number\n---@return integer\nfunction ImGui.GetKeyPressedAmount(key, repeat_delay, rate) end\n\n\n-