ne_surface,,,,,,,,,表层砂岩,,,,,,,,,,,,,,,\nmat_shock_powder,,,,,,,,,电击粉末,,,,,,,,,,,,,,,\nmat_slime,,,,,,,,,黏液,,,,,,,,,,,,,,,\nmat_slime_yellow,,,,,,,,,黄色黏液,,,,,,,,,,,,,,,\nmat_snow_sticky,,,,,,,,,黏雪,,,,,,,,,,,,,,,\nmat_soil_dark,,,,,,,,,黑土,,,,,,,,,,,,,,,\nmat_soil_lush_dark,,,,,,,,,葱郁黑土,,,,,,,,,,,,,,,\nmat_spark_blue_dark,,,,,,,,,暗蓝火花,,,,,,,,,,,,,,,\nmat_spark_green_bright,,,,,,,,,亮绿火花,,,,,,,,,,,,,,,\nmat_spark_purple_bright,,,,,,,,,亮紫火花,,,,,,,,,,,,,,,\nmat_spark_red_bright,,,,,,,,,亮红火花,,,,,,,,,,,,,,,\nmat_spark_white_bright,,,,,,,,,亮白火花,,,,,,,,,,,,,,,\nmat_spore_pod_stalk,,,,,,,,,孢子茎秆,,,,,,,,,,,,,,,\nmat_steam_trailer,,,,,,,,,开场动画用的蒸汽,,,,,,,,,,,,,,,\nmat_steel_grey_static,,,,,,,,,灰钢,,,,,,,,,,,,,,,\nmat_steel_rusted_no_holes,,,,,,,,,锈蚀钢铁,,,,,,,,,,,,,,,\nmat_sulphur_box2d,,,,,,,,,硫磺块,,,,,,,,,,,,,,,\nmat_templebrick_box2d_edgetiles,,,,,,,,,边缘砖墙,,,,,,,,,,,,,,,\nmat_templebrick_static_broken,,,,,,,,,破碎砖墙,,,,,,,,,,,,,,,\nmat_templebrick_static_soft,,,,,,,,,柔软砖墙,,,,,,,,,,,,,,,\nmat_templebrick_thick_static_noedge,,,,,,,,,无缝致密砖墙,,,,,,,,,,,,,,,\nmat_templerock_soft,,,,,,,,,柔软石砖,,,,,,,,,,,,,,,\nmat_tnt_static,,,,,,,,,TNT,,,,,,,,,,,,,,,\nmat_wood_burns_forever,,,,,,,,,永燃木材,,,,,,,,,,,,,,,\nmat_wood_prop_noplayerhit,,,,,,,,,木材,,,,,,,,,,,,,,,\nmat_wood_tree,,,,,,,,,古木,,,,,,,,,,,,,,,\nmat_fungi_yellow,,,,,,,,,黄色真菌,,,,,,,,,,,,,,,\nmat_just_death,,,,,,,,,即死魔药,,,,,,,,,,,,,,,\nmat_magic_liquid_weakness,,,,,,,,,虚弱魔药,,,,,,,,,,,,,,,\nmat_meat_static,,,,,,,,,肉,,,,,,,,,,,,,,,\nmat_grass_darker,,,,,,,,,黑草,,,,,,,,,,,,,,,\nmat_plant_material_dark,,,,,,,,,深色灌木,,,,,,,,,,,,,,,\nmat_rock_box2d_nohit_heavy,,,,,,,,,奇石,,,,,,,,,,,,,,,\n,,,,,,,,,,,,,,,,,,,,,,,,\nanimal bubbleshot,,,,,,,,,泡泡火花,,,,,,,,,,,,,,,\nanimal basebot sentry,,,,,,,,,机械哨兵,,,,,,,,,,,,,,,\nanimal basebot hidden,,,,,,,,,机械间谍,,,,,,,,,,,,,,,\nanimal basebot neutralizer,,,,,,,,,机械拦截兵,,,,,,,,,,,,,,,"
_TWWE_VFS["mods/better_chinese/init.lua"] = "dofile_once(\"data/better_chinese/pre_book.lua\")\n\nlocal function OverrideFile(orig, new)\n    ModTextFileSetContent(orig, ModTextFileGetContent(new))\nend\n\nlocal translation = ModTextFileGetContent(\"data/translations/common.csv\") .. PreTranslation(ModTextFileGetContent(\"data/translations/common_base.csv\"))\nif ModSettingGet(\"better_chinese.use_pixel_chinese_font\") then\n    OverrideFile(\"data/translations/zh-cn.xml\", \"data/better_chinese/zh-cn-pixel.xml\")\nelse\n    OverrideFile(\"data/translations/zh-cn.xml\", \"data/better_chinese/zh-cn.xml\")\nend\nModTextFileSetContent(\"data/translations/common.csv\", translation)\n\nlocal nxml = dofile(\"mods/better_chinese/nxml.lua\")\nlocal materials = ModTextFileGetContent(\"data/materials.xml\")\nlocal materials_xml = nxml.parse(materials)\nfor element in materials_xml:each_child() do\n    if(element.attr.name ~= nil) then\n        element.attr.ui_name = \"$mat_\" .. element.attr.name\n    end\nend\nModTextFileSetContent(\"data/materials.xml\", tostring(materials_xml))\n\n\nfunction OnWorldPostUpdate() \n  if _alchemy_main then _alchemy_main() end\nend\n\nfunction OnPlayerSpawned( player_entity )\n  dofile(\"data/alchemyrecipes/alchemy.lua\")\nend\n"
_TWWE_VFS["mods/better_chinese/mod.xml"] = "<Mod\n	name=\"Better Chinese\"\n	description=\"完全汉化V2.5.5-伟大之作汉化组(适配更新Jan 25 2025版本)\\nNoita游戏交流,问题反馈QQ群:665 106 616 \\n像素字体或炼金配方请按Esc键--选项--在模组设置中打开/关闭\"\n	request_no_api_restrictions=\"0\"\n	tags=\"gameplay,translations,quality of life,alchemy\"\n	>\n</Mod>\n"
_TWWE_VFS["mods/better_chinese/mod_id.txt"] = "better_chinese"
_TWWE_VFS["mods/better_chinese/nxml.lua"] = "local ffi = nil\nif require then\n    pcall(function()\n        ffi = require(\"ffi\")\n    end)\nend\n\nlocal str_sub\nlocal str_index\nlocal str_normalize\n\nif ffi then\n    str_normalize = function(str)\n        return ffi.cast(\"const char*\", str)\n    end\n\n    str_sub = function(ptr, start_idx, len)\n        return ffi.string(ptr + start_idx, len)\n    end\n\n    str_index = function(ptr, idx)\n        return ptr[idx]\n    end\nelse\n    str_normalize = function(str) return str end\n\n    str_sub = function(str, start_idx, len)\n        return str:sub(start_idx + 1, start_idx + len)\n    end\n\n    str_index = function(str, idx)\n        return string.byte(str:sub(idx + 1, idx + 1))\n    end\nend\n\n--[[\n * The following is a Lua port of the NXML parser:\n * https://github.com/xwitchproject/nxml\n *\n * The NXML Parser is heavily based on code from poro\n * https://github.com/gummikana/poro\n * \n * The poro project is licensed under the Zlib license:\n * \n * --------------------------------------------------------------------------\n * Copyright (c) 2010-2019 Petri Purho, Dennis Belfrage\n * Contributors: Martin Jonasson, Olli Harjola\n * This software is provided 'as-is', without any express or implied\n * warranty.  In no event will the authors be held liable for any damages\n * arising from the use of this software.\n * Permission is granted to anyone to use this software for any purpose,\n * including commercial applications, and to alter it and redistribute it\n * freely, subject to the following restrictions:\n * 1. The origin of this software must not be misrepresented; you must not\n *    claim that you wrote the original software. If you use this software\n *    in a product, an acknowledgment in the product documentation would be\n *    appreciated but is not required.\n * 2. Altered source versions must be plainly marked as such, and must not be\n *    misrepresented as being the original software.\n * 3. This notice may not be removed or altered from any source distribution.\n * --------------------------------------------------------------------------\n]]\n\nlocal nxml = {}\n\nlocal TOKENIZER_FUNCS = {}\nlocal TOKENIZER_MT = {\n    __index = TOKENIZER_FUNCS,\n    __tostring = function(self) return \"natif.nxml.tokenizer\" end\n}\n\nlocal function new_tokenizer(cstring, len)\n    return setmetatable({\n        data = cstring,\n        cur_idx = 0,\n        cur_row = 1,\n        cur_col = 1,\n        prev_row = 1,\n        prev_col = 1,\n        len = len\n    }, TOKENIZER_MT)\nend\n\nlocal ws = {\n    [string.byte(\" \")] = true,\n    [string.byte(\"\\t\")] = true,\n    [string.byte(\"\\n\")] = true,\n    [string.byte(\"\\r\")] = true\n}\n\nfunction TOKENIZER_FUNCS:is_whitespace(char)\n    local n = tonumber(char)\n    return ws[n] or false\nend\n\nlocal punct = {\n    [string.byte(\"<\")] = true,\n    [string.byte(\">\")] = true,\n    [string.byte(\"=\")] = true,\n    [string.byte(\"/\")] = true,\n}\n\nfunction TOKENIZER_FUNCS:is_whitespace_or_punctuation(char)\n    local n = tonumber(char)\n    return self:is_whitespace(n) or punct[n] or false\nend\n\nfunction TOKENIZER_FUNCS:move(n)\n    n = n or 1\n    local prev_idx = self.cur_idx\n    self.cur_idx = self.cur_idx + n\n    if self.cur_idx >= self.len then\n        self.cur_idx = self.len\n        return\n    end\n    for i = prev_idx, self.cur_idx - 1 do\n        if str_index(self.data, i) == string.byte(\"\\n\") then\n            self.cur_row = self.cur_row + 1\n            self.cur_col = 1\n        else\n            self.cur_col = self.cur_col + 1\n        end\n    end\nend\n\nfunction TOKENIZER_FUNCS:peek(n)\n    n = n or 1\n    local idx = self.cur_idx + n\n    if idx >= self.len then return 0 end\n\n    return str_index(self.data, idx)\nend\n\nfunction TOKENIZER_FUNCS:match_string(str)\n    local len = #str\n    str = str_normalize(str)\n    \n    for i = 0, len - 1 do\n        if self:peek(i) ~= str_index(str, i) then return false end\n    end\n    return true\nend\n\nfunction TOKENIZER_FUNCS:eof()\n    return self.cur_idx >= self.len\nend\n\nfunction TOKENIZER_FUNCS:cur_char()\n    if self:eof() then return 0 end\n    return tonumber(str_index(self.data, self.cur_idx))\nend\n\nfunction TOKENIZER_FUNCS:skip_whitespace()\n    while not self:eof() do\n        if self:is_whitespace(self:cur_char()) then\n            self:move()\n        elseif self:match_string(\"<!--\") then\n            self:move(4)\n            while not self:eof() and not self:match_string(\"-->\") do\n                self:move()\n            end\n\n            if self:match_string(\"-->\") then\n                self:move(3)\n            end\n        elseif self:cur_char() == string.byte(\"<\") and self:peek(1) == string.byte(\"!\") then\n            self:move(2)\n            while not self:eof() and self:cur_char() ~= string.byte(\">\") do\n                self:move()\n            end\n            if self:cur_char() == string.byte(\">\") then\n                self:move()\n            end\n\n        elseif self:match_string(\"<?\") then\n            self:move(2)\n            while not self:eof() and not self:match_string(\"?>\") do\n                self:move()\n            end\n            if self:match_string(\"?>\") then\n                self:move(2)\n            end\n        else\n            break\n        end\n    end\nend\n\nfunction TOKENIZER_FUNCS:read_quoted_string()\n    local start_idx = self.cur_idx\n    local len = 0\n\n    while not self:eof() and self:cur_char() ~= string.byte(\"\\\"\") do\n        len = len + 1\n        self:move()\n    end\n\n    self:move() -- skip \"\n    return str_sub(self.data, start_idx, len)\nend\n\nfunction TOKENIZER_FUNCS:read_unquoted_string()\n    local start_idx = self.cur_idx - 1 -- first char is move()d\n    local len = 1\n\n    while not self:eof() and not self:is_whitespace_or_punctuation(self:cur_char()) do\n        len = len + 1\n        self:move()\n    end\n\n    return str_sub(self.data, start_idx, len)\nend\n\nlocal C_NULL = 0\nlocal C_LT = string.byte(\"<\")\nlocal C_GT = string.byte(\">\")\nlocal C_SLASH = string.byte(\"/\")\nlocal C_EQ = string.byte(\"=\")\nlocal C_QUOTE = string.byte(\"\\\"\")\n\nfunction TOKENIZER_FUNCS:next_token()\n    self:skip_whitespace()\n\n    self.prev_row = self.cur_row\n    self.prev_col = self.cur_col\n\n    if self:eof() then return nil end\n\n    local c = self:cur_char()\n    self:move()\n\n    if c == C_NULL then return nil\n    elseif c == C_LT then return { type = \"<\" }\n    elseif c == C_GT then return { type = \">\" }\n    elseif c == C_SLASH then return { type = \"/\" }\n    elseif c == C_EQ then return { type = \"=\" }\n    elseif c == C_QUOTE then return { type = \"string\", value = self:read_quoted_string() }\n    else return { type = \"string\", value = self:read_unquoted_string() }\n    end\nend\n\nlocal PARSER_FUNCS = {}\nlocal PARSER_MT = {\n    __index = PARSER_FUNCS,\n    __tostring = function(self) return \"natif.nxml.parser\" end\n}\n\nlocal function new_parser(tokenizer, error_reporter)\n    return setmetatable({\n        tok = tokenizer,\n        errors = {},\n        error_reporter = error_reporter or function(type, msg) print(\"parser error: [\" .. type .. \"] \" .. msg) end\n    }, PARSER_MT)\nend\n\nlocal XML_ELEMENT_FUNCS = {}\nlocal XML_ELEMENT_MT = {\n    __index = XML_ELEMENT_FUNCS,\n    __tostring = function(self)\n        return nxml.tostring(self)\n    end,\n}\n\nfunction PARSER_FUNCS:report_error(type, msg)\n    self.error_reporter(type, msg)\n    table.insert(self.errors, { type = type, msg = msg, row = self.tok.prev_row, col = self.tok.prev_col })\nend\n\n\nfunction PARSER_FUNCS:parse_attr(attr_table, name)\n    local tok = self.tok:next_token()\n    if tok.type == \"=\" then\n        tok = self.tok:next_token()\n\n        if tok.type == \"string\" then\n            attr_table[name] = tok.value\n        else\n            self:report_error(\"missing_attribute_value\", string.format(\"parsing attribute '%s' - expected a string after =, but did not find one\"), name)\n        end\n    else\n        self:report_error(\"missing_equals_sign\", string.format(\"parsing attribute '%s' - did not find equals sign after attribute name\", name))\n    end\nend\n\nfunction PARSER_FUNCS:parse_element(skip_opening_tag)\n    local tok\n    if not skip_opening_tag then\n        tok = self.tok:next_token()\n        if tok.type ~= \"<\" then\n            self:report_error(\"missing_tag_open\", \"couldn't find a '<' to start parsing with\")\n        end\n    end\n\n    tok = self.tok:next_token()\n    if tok.type ~= \"string\" then\n        self:report_error(\"missing_element_name\", \"expected an element name after '<'\")\n    end\n\n    local elem_name = tok.value\n    local elem = nxml.new_element(elem_name)\n    local content_idx = 0\n\n    local self_closing = false\n\n    while true do\n        tok = self.tok:next_token()\n\n        if tok == nil then\n            return elem\n        elseif tok.type == \"/\" then\n            if self.tok:cur_char() == C_GT then\n                self.tok:move()\n                self_closing = true\n            end\n            break\n        elseif tok.type == \">\" then\n            break\n        elseif tok.type == \"string\" then\n            self:parse_attr(elem.attr, tok.value)\n        end\n    end\n\n    if self_closing then return elem end\n\n    while true do\n        tok = self.tok:next_token()\n\n        if tok == nil then\n            return elem\n        elseif tok.type == \"<\" then\n            if self.tok:cur_char() == C_SLASH then\n                self.tok:move()\n\n                local end_name = self.tok:next_token()\n                if end_name.type == \"string\" and end_name.value == elem_name then\n                    local close_greater = self.tok:next_token()\n\n                    if close_greater.type == \">\" then\n                        return elem\n                    else\n                        self:report_error(\"missing_element_close\", string.format(\"no closing '>' found for element '%s'\", elem_name))\n                    end\n                else\n                    self:report_error(\"mismatched_closing_tag\", string.format(\"closing element is in wrong order - expected '</%s>', but instead got '%s'\", elem_name, tostring(end_name.value)))\n                end\n                return elem\n            else\n                local child = self:parse_element(elem, true)\n                table.insert(elem.children, child)\n            end\n        else\n            if not elem.content then\n                elem.content = {}\n            end\n            \n            content_idx = content_idx + 1\n            elem.content[content_idx] = tok.value or tok.type\n        end\n    end\nend\n\nfunction PARSER_FUNCS:parse_elements()\n    local tok = self.tok:next_token()\n    local elems = {}\n    local elems_i = 1\n\n    while tok and tok.type == \"<\" do\n        elems[elems_i] = self:parse_element(true)\n        elems_i = elems_i + 1\n\n        tok = self.tok:next_token()\n    end\n\n    return elems\nend\n\nlocal function is_punctuation(str)\n    return str == \"/\" or str == \"<\" or str == \">\" or str == \"=\"\nend\n\nfunction XML_ELEMENT_FUNCS:text()\n    local content_count = #self.content\n\n    if self.content == nil or content_count == 0 then\n        return \"\"\n    end\n\n    local text = self.content[1]\n    for i = 2, content_count do\n        local elem = self.content[i]\n        local prev = self.content[i - 1]\n\n        if is_punctuation(elem) or is_punctuation(prev) then\n            text = text .. elem\n        else\n            text = text .. \" \" .. elem\n        end\n    end\n\n    return text\nend\n\nfunction XML_ELEMENT_FUNCS:add_child(child)\n    self.children[#self.children + 1] = child\nend\n\nfunction XML_ELEMENT_FUNCS:add_children(children)\n    local children_i = #self.children + 1\n    for i = 1, #children do\n        self.children[children_i] = children[i]\n        children_i = children_i + 1\n    end\nend\n\nfunction XML_ELEMENT_FUNCS:remove_child(child)\n    for i = 1, #self.children do\n        if self.children[i] == child then\n            table.remove(self.children, i)\n            break\n        end\n    end\nend\n\nfunction XML_ELEMENT_FUNCS:remove_child_at(index)\n    table.remove(self.children, index)\nend\n\nfunction XML_ELEMENT_FUNCS:clear_children()\n    self.children = {}\nend\n\nfunction XML_ELEMENT_FUNCS:clear_attrs()\n    self.attr = {}\nend\n\nfunction XML_ELEMENT_FUNCS:first_of(element_name)\n    local i = 0\n    local n = #self.children\n\n    while i < n do\n        i = i + 1\n        local c = self.children[i]\n\n        if c.name == element_name then return c end\n    end\n\n    return nil\nend\n\nfunction XML_ELEMENT_FUNCS:each_of(element_name)\n    local i = 1\n    local n = #self.children\n\n    return function()\n        while i <= n and self.children[i].name ~= element_name do\n            i = i + 1\n        end\n        i = i + 1\n        return self.children[i - 1]\n    end\nend\n\nfunction XML_ELEMENT_FUNCS:all_of(element_name)\n    local table = {}\n    local i = 1\n    for elem in self:each_of(element_name) do\n        table[i] = elem\n        i = i + 1\n    end\n    return table\nend\n\nfunction XML_ELEMENT_FUNCS:each_child()\n    local i = 0\n    local n = #self.children\n\n    return function()\n        while i <= n do\n            i = i + 1\n            return self.children[i]\n        end\n    end\nend\n\nfunction nxml.parse(data)\n    local data_len = #data\n    local tok = new_tokenizer(str_normalize(data), data_len)\n    local parser = new_parser(tok)\n    \n    local elem = parser:parse_element(false)\n    \n    if not elem or (elem.errors and #elem.errors > 0) then\n        error(\"parser encountered errors\")\n    end\n\n    return elem\nend\n\nfunction nxml.parse_many(data)\n    local data_len = #data\n    local tok = new_tokenizer(str_normalize(data), data_len)\n    local parser = new_parser(tok)\n    \n    local elems = parser:parse_elements(false)\n    \n    for i = 1, #elems do\n        local elem = elems[i]\n\n        if elem.errors and #elem.errors > 0 then\n            error(\"parser encountered errors\")\n        end\n    end\n\n    return elems\nend\n\nfunction nxml.new_element(name, attrs)\n    return setmetatable({\n        name = name,\n        attr = attrs or {},\n        children = {},\n        content = nil\n    }, XML_ELEMENT_MT)\nend\n\nlocal function attr_value_to_str(value)\n    local t = type(value)\n    if t == \"string\" then return value end\n    if t == \"boolean\" then return value and \"1\" or \"0\" end\n\n    return tostring(value)\nend\n\nfunction nxml.tostring(elem, packed, indent_char, cur_indent)\n    indent_char = indent_char or \"\\t\"\n    cur_indent = cur_indent or \"\"\n    local s = \"<\" .. elem.name\n    local self_closing = #elem.children == 0 and (not elem.content or #elem.content == 0)\n\n    for k, v in pairs(elem.attr) do\n        s = s .. \" \" .. k .. \"=\\\"\" .. attr_value_to_str(v) .. \"\\\"\"\n    end\n\n    if self_closing then\n        s = s .. \" />\"\n        return s\n    end\n\n    s = s .. \">\"\n\n    local deeper_indent = cur_indent .. indent_char\n\n    if elem.content and #elem.content ~= 0 then\n        if not packed then s = s .. \"\\n\" .. deeper_indent end\n        s = s .. elem:text()\n    end\n\n    if not packed then s = s .. \"\\n\" end\n\n    for i, v in ipairs(elem.children) do\n        if not packed then s = s .. deeper_indent end\n        s = s .. nxml.tostring(v, packed, indent_char, deeper_indent)\n        if not packed then s = s .. \"\\n\" end\n    end\n\n    s = s .. cur_indent .. \"</\" .. elem.name .. \">\"\n\n    return s\nend\n\nreturn nxml\n"
_TWWE_VFS["mods/better_chinese/settings.lua"] = "dofile(\"data/scripts/lib/mod_settings.lua\")\n\nfunction mod_setting_bool_custom( mod_id, gui, in_main_menu, im_id, setting )\n	local value = ModSettingGetNextValue( mod_setting_get_id(mod_id,setting) )\n	local text = setting.ui_name .. \" - \" .. GameTextGet( value and \"$option_on\" or \"$option_off\" )\n\n	if GuiButton( gui, im_id, mod_setting_group_x_offset, 0, text ) then\n		ModSettingSetNextValue( mod_setting_get_id(mod_id,setting), not value, false )\n	end\n\n	mod_setting_tooltip( mod_id, gui, in_main_menu, setting )\nend\n\nfunction mod_setting_change_callback( mod_id, gui, in_main_menu, setting, old_value, new_value  )\n	print( tostring(new_value) )\nend\n\nlocal mod_id = \"better_chinese\"\nmod_settings_version = 1\nmod_settings = \n{\n    {\n        id = \"use_pixel_chinese_font\",\n        ui_name = \"中文使用像素字体（改动重启生效）\",\n        ui_description = \"默认开启，改动会在重启游戏后生效\",\n        value_default = true,\n        scope = MOD_SETTING_SCOPE_RUNTIME_RESTART,\n    },\n    -- {\n    --     id = \"align_fix\",\n    --     ui_name = \"翡翠石板缩放显示修正（改动重启生效）\",\n    --     ui_description = \"默认50，缩放用于石板面板，字体大小不可改，改动在重启游戏后生效\",\n    --     value_default = 10,\n    --     value_min = 0,\n    --     value_max = 40,\n    --     value_display_multiplier = 5,\n    --     scope = MOD_SETTING_SCOPE_RUNTIME_RESTART,\n    -- },\n    {\n        id =\"created_gui\",\n        ui_name =\"中文炼金配方左上角图标显示\",\n        ui_description = \"默认开启，开启后点击左上角烧瓶图案切换显示\",\n        value_default = true,\n        scope = MOD_SETTING_SCOPE_RUNTIME_RESTART,\n    }\n}\n\nfunction ModSettingsUpdate( init_scope )\n	local old_version = mod_settings_get_version( mod_id )\n	mod_settings_update( mod_id, mod_settings, init_scope )\nend\n\nfunction ModSettingsGuiCount()\n	return mod_settings_gui_count( mod_id, mod_settings )\nend\n\nfunction ModSettingsGui( gui, in_main_menu )\n	mod_settings_gui( mod_id, mod_settings, gui, in_main_menu )\nend\n"
_TWWE_VFS["mods/cheatgui/compatibility.xml"] = "<Mod _format_version=\"0\" version_built_with=\"7\" >\n\n</Mod>\n\n"
_TWWE_VFS["mods/cheatgui/data/hax/alchemy.lua"] = "local function hax_prng_next(v)\n  local hi = math.floor(v / 127773.0)\n  local lo = v % 127773\n  v = 16807 * lo - 2836 * hi\n  if v <= 0 then\n    v = v + 2147483647\n  end\n  return v\nend\n\nlocal function shuffle(arr, seed)\n  local v = math.floor(seed / 2) + 0x30f6\n  v = hax_prng_next(v)\n  for i = #arr, 1, -1 do\n    v = hax_prng_next(v)\n    local fidx = v / 2^31\n    local target = math.floor(fidx * i) + 1\n    arr[i], arr[target] = arr[target], arr[i]\n  end\nend\n\nlocal LIQUIDS = {\"acid\",\n\"alcohol\",\n\"blood\",\n\"blood_fungi\",\n\"blood_worm\",\n\"cement\",\n\"lava\",\n\"magic_liquid_berserk\",\n\"magic_liquid_charm\",\n\"magic_liquid_faster_levitation\",\n\"magic_liquid_faster_levitation_and_movement\",\n\"magic_liquid_invisibility\",\n\"magic_liquid_mana_regeneration\",\n\"magic_liquid_movement_faster\",\n\"magic_liquid_protection_all\",\n\"magic_liquid_teleportation\",\n\"magic_liquid_unstable_polymorph\",\n\"magic_liquid_unstable_teleportation\",\n\"magic_liquid_worm_attractor\",\n\"material_confusion\",\n\"mud\",\n\"oil\",\n\"poison\",\n\"radioactive_liquid\",\n\"swamp\",\n\"urine\"  ,\n\"water\",\n\"water_ice\",\n\"water_swamp\",\n\"magic_liquid_random_polymorph\"}\n\nlocal ORGANICS = {\"bone\",\n\"brass\",\n\"coal\",\n\"copper\",\n\"diamond\",\n\"fungi\",\n\"gold\",\n\"grass\",\n\"gunpowder\",\n\"gunpowder_explosive\",\n\"rotten_meat\",\n\"sand\",\n\"silver\",\n\"slime\",\n\"snow\",\n\"soil\",\n\"wax\",\n\"honey\"}\n\nlocal function copy_arr(arr)\n  local ret = {}\n  for k, v in pairs(arr) do ret[k] = v end\n  return ret\nend\n\nlocal function random_material(v, mats)\n  for _ = 1, 1000 do\n    v = hax_prng_next(v)\n    local rval = v / 2^31\n    local sel_idx = math.floor(#mats * rval) + 1\n    local selection = mats[sel_idx]\n    if selection then\n      mats[sel_idx] = false\n      return v, selection\n    end\n  end\nend\n\nlocal function random_recipe(rand_state, seed)\n  local liqs = copy_arr(LIQUIDS)\n  local orgs = copy_arr(ORGANICS)\n  local m1, m2, m3, m4 = \"?\", \"?\", \"?\", \"?\"\n  rand_state, m1 = random_material(rand_state, liqs)\n  rand_state, m2 = random_material(rand_state, liqs)\n  rand_state, m3 = random_material(rand_state, liqs)\n  rand_state, m4 = random_material(rand_state, orgs)\n  local combo = {m1, m2, m3, m4}\n\n  rand_state = hax_prng_next(rand_state)\n  local prob = 10 + math.floor((rand_state / 2^31) * 91)\n  rand_state = hax_prng_next(rand_state)\n\n  shuffle(combo, seed)\n  return rand_state, {combo[1], combo[2], combo[3]}, prob\nend\n\nfunction get_alchemy()\n  local seed = tonumber(StatsGetValue(\"world_seed\"))\n  local rand_state = math.floor(seed * 0.17127000 + 1323.59030000)\n\n  for i = 1, 6 do\n    rand_state = hax_prng_next(rand_state)\n  end\n\n  local lc_combo, ap_combo = {\"?\"}, {\"?\"}\n  rand_state, lc_combo, lc_prob = random_recipe(rand_state, seed)\n  rand_state, ap_combo, ap_prob = random_recipe(rand_state, seed)\n\n  return lc_combo, ap_combo, lc_prob, ap_prob\nend"
_TWWE_VFS["mods/cheatgui/data/hax/cheatgui.lua"] = "dofile_once(\"data/scripts/lib/coroutines.lua\")\ndofile_once(\"data/scripts/lib/utilities.lua\")\ndofile_once(\"data/scripts/perks/perk.lua\")\ndofile_once(\"data/scripts/gun/gun_actions.lua\")\ndofile_once(\"data/hax/materials.lua\")\ndofile_once(\"data/hax/alchemy.lua\")\ndofile_once(\"data/hax/spawnables.lua\")\ndofile_once(\"data/hax/special_spawnables.lua\")\ndofile_once(\"data/hax/fungal.lua\")\ndofile_once(\"data/hax/gun_builder.lua\")\ndofile_once(\"data/hax/superhackykb.lua\")\ndofile_once(\"data/hax/utils.lua\")\n\nlocal CHEATGUI_VERSION = \"1.5.0\"\nlocal CHEATGUI_TITLE = \"cheatgui \" .. CHEATGUI_VERSION\nlocal console_connected = false\n\nif _keyboard_present then\n  -- have FFI\n  dofile_once(\"data/hax/console.lua\")\nelse\n  CHEATGUI_TITLE = CHEATGUI_TITLE .. \"S\" \nend\n\nlocal created_gui = false\n\nlocal _next_available_id = 100\nlocal function reset_id()\n  _next_available_id = 100\nend\nlocal function next_id(n)\n  n = n or 1\n  local ret = _next_available_id\n  _next_available_id = _next_available_id + n\n  return ret\nend\n\nlocal _type_target = nil\nlocal _shift_target = nil\n\nlocal function handle_typing()\n  local type_target = _type_target\n  local req_shift = false\n  if type_target == nil then \n    type_target = _shift_target\n    req_shift = true\n  end\n  if not type_target then return end\n  local prev_val = type_target.value\n  local hit_enter = false\n  type_target.value, hit_enter = hack_type(prev_val, not req_shift)\n  if (prev_val ~= type_target.value) and (type_target.on_change) then\n    type_target:on_change()\n  end\n  if hit_enter and (type_target.on_hit_enter) then\n    type_target:on_hit_enter()\n  end\nend\n\nlocal function set_type_target(target)\n  if not _keyboard_present then return end\n  if _type_target and _type_target.on_lose_focus then\n    _type_target:on_lose_focus()\n  end\n  _type_target = target\n  if _type_target and _type_target.on_gain_focus then\n    _type_target:on_gain_focus()\n  end\nend\n\nlocal function set_type_default(target)\n  _shift_target = target\nend\n\nif not _cheat_gui then\n  print(\"Creating cheat GUI\")\n  _cheat_gui = GuiCreate()\n  _gui_frame_function = nil\n  created_gui = true\nelse\n  print(\"Reloading onto existing GUI\")\nend\n\nlocal gui = _cheat_gui\n\nlocal closed_panel, perk_panel, cards_panel, menu_panel, flasks_panel\nlocal wands_panel, builder_panel, always_cast_panel, teleport_panel, info_panel\nlocal health_panel, money_panel, spawn_panel, console_panel\n\nlocal function Panel(options)\n  if not options.name then\n    options.name = options[1]\n  end\n  if not options.func then\n    options.func = options[2]\n  end\n  return options\nend\n\nlocal panel_stack = {}\nlocal _active_panel = nil\n\nlocal function _change_active_panel(panel)\n  if panel == _active_panel then return end\n  set_type_default(nil)\n  set_type_target(nil)\n  _gui_frame_function = panel.func\nend\n\nlocal function prev_panel()\n  if #panel_stack < 2 then\n    _change_active_panel(closed_panel)\n    panel_stack = {}\n  else\n    -- pop off last panel\n    panel_stack[#panel_stack] = nil\n    _change_active_panel(panel_stack[#panel_stack])\n  end\nend\n\nlocal function jump_back_panel(idx)\n  if #panel_stack <= idx then return end\n  for i = idx+1, #panel_stack do\n    panel_stack[i] = nil\n  end\n  _change_active_panel(panel_stack[#panel_stack])\nend\n\nlocal function enter_panel(panel)\n  panel_stack[#panel_stack+1] = panel\n  _change_active_panel(panel)\nend\n\nlocal function hide_gui()\n  _change_active_panel(closed_panel)\nend\n\nlocal function goto_subpanel(panel)\n  panel_stack = {}\n  enter_panel(menu_panel)\n  enter_panel(panel)\nend\n\nlocal function show_gui()\n  if #panel_stack == 0 then\n    enter_panel(menu_panel)\n  else\n    _change_active_panel(panel_stack[#panel_stack])\n  end\nend\n\nlocal function breadcrumbs(x, y)\n  GuiLayoutBeginHorizontal(gui, x, y)\n  if GuiButton( gui, 0, 0, \"[-]\", next_id()) then\n    hide_gui()\n  end\n  for idx, panel in ipairs(panel_stack) do\n    if GuiButton( gui, 0, 0, panel.name .. \">\", next_id()) then\n      jump_back_panel(idx)\n    end\n  end\n  GuiLayoutEnd(gui)\n  GuiLayoutBeginHorizontal( gui, x, y+3)\n  if #panel_stack > 1 and GuiButton( gui, 0, 0, \"< back\", next_id()) then\n    prev_panel()\n  end\n  GuiLayoutEnd( gui )\nend\n\nlocal _info_widgets = {}\nlocal _sorted_info_widgets = {}\nlocal _all_info_widgets = {}\n\nlocal function _update_info_widgets()\n  _sorted_info_widgets = {}\n  for wname, widget in pairs(_info_widgets) do\n    table.insert(_sorted_info_widgets, {wname, widget})\n  end\n  table.sort(_sorted_info_widgets, function(a, b)\n    return a[1] < b[1]\n  end)\nend\n\nlocal function add_info_widget(wname, w)\n  _info_widgets[wname] = w\n  _update_info_widgets()\nend\n\nlocal function remove_info_widget(wname)\n  _info_widgets[wname] = nil\n  _update_info_widgets()\nend\n\nlocal function register_widget(wname, w)\n  table.insert(_all_info_widgets, {wname, w})\nend\n\nclosed_panel = Panel{\"[+]\", function()\n  GuiLayoutBeginHorizontal( gui, 1, 0 )\n  if GuiButton( gui, 0, 0, \"[+]\", next_id() ) then\n    show_gui()\n  end\n  GuiLayoutEnd( gui )\n  local col_pos = 5\n  for idx, winfo in ipairs(_sorted_info_widgets) do\n    local wname, widget = unpack(winfo)\n    GuiLayoutBeginHorizontal(gui, col_pos, 0)\n    local text = widget:text()\n    if idx > 1 then text = \"| \" .. text end\n    if GuiButton( gui, 0, 0, text, next_id() ) then\n      widget:on_click()\n    end\n    GuiLayoutEnd( gui )\n    col_pos = col_pos + (widget.width or 10)\n  end\nend}\n\nlocal function wrap_spawn(path)\n  return function() spawn_item(path) end\nend\n\nlocal function maybe_call(s_or_f, opt)\n  if type(s_or_f) == 'function' then \n    return s_or_f(opt)\n  else\n    return s_or_f\n  end\nend\n\nlocal function get_option_text(opt)\n  return maybe_call(opt.text or opt[1], opt)\nend\n\nlocal function grid_layout(options, col_width, callback)\n  local num_options = #options\n  local col_size = 28\n  local ncols = math.ceil(num_options / col_size)\n  local xoffset = col_width or 25\n  local xpos = 5\n  local opt_pos = 1\n  for col = 1, ncols do\n    if not options[opt_pos] then break end\n    GuiLayoutBeginVertical( gui, xpos, 11 )\n    for row = 1, col_size do\n      if not options[opt_pos] then break end\n      local opt = options[opt_pos]\n      local text = get_option_text(opt)\n      if GuiButton( gui, 0, 0, text, next_id() ) then\n        (callback or opt.f or opt[2])(opt)\n      end\n      opt_pos = opt_pos + 1\n    end\n    GuiLayoutEnd( gui)\n    xpos = xpos + xoffset\n  end\nend\n\nlocal function grid_panel(title, options, col_width, callback)\n  breadcrumbs(1, 0)\n  grid_layout(options, col_width, callback)\nend\n\nlocal function filter_options(options, str)\n  local ret = {}\n  for _, opt in ipairs(options) do\n    local text = maybe_call(opt.text, opt):lower()\n    if text:find(str) then\n      table.insert(ret, opt)\n    end\n  end\n  return ret\nend\n\nlocal function create_radio(title, options, default, x_spacing)\n  if not default then default = options[1][2] end\n  local selected = default --1\n  -- for i, v in ipairs(options) do\n  --   if v[2] == default then selected = i end\n  -- end\n  local wrapper = {\n    index = selected, \n    value = options[selected][2],\n    reset = function(_self)\n      _self.index = default\n      _self.value = options[default][2]\n    end\n  }\n  return function(xpos, ypos)\n    GuiLayoutBeginHorizontal(gui, xpos, ypos)\n    GuiText(gui, 0, 0, title)\n    GuiLayoutEnd(gui)\n    GuiLayoutBeginHorizontal(gui, xpos+(x_spacing or 12), ypos)\n    for idx, option in ipairs(options) do\n      local text = option[1]\n      if idx == wrapper.index then text = \"[\" .. text .. \"]\" end\n      if GuiButton( gui, 0, 0, text, next_id() ) then\n        wrapper.index = idx\n        wrapper.value = option[2]\n      end\n    end\n    GuiLayoutEnd(gui)\n  end, wrapper\nend\n\nlocal function alphabetize(options, do_it)\n  if not do_it then return options end\n  local keys = {}\n  for idx, opt in ipairs(options) do\n    keys[idx] = {get_option_text(opt):lower(), opt}\n  end\n  table.sort(keys, function(a, b) return a[1] < b[1] end)\n  local sorted = {}\n  for idx, v in ipairs(keys) do\n    sorted[idx] = v[2]\n  end\n  return sorted\nend\n\nlocal alphabetize_widget, alphabetize_val = create_radio(\"Alphabetize:\", {\n  {\"Yes\", true}, {\"No\", false}\n}, 2, 16)\n\nlocal function breakup_pages(options, page_size)\n  local pages = {}\n  local npages = math.ceil(#options / page_size)\n  local opt_pos = 1\n  for page = 1, npages do\n    if not options[opt_pos] then break end\n    pages[page] = {}\n    for idx = 1, page_size do\n      if not options[opt_pos] then break end\n      table.insert(pages[page], options[opt_pos])\n      opt_pos = opt_pos + 1\n    end\n  end\n  return pages\nend\n\nlocal function wrap_paginate(title, options, page_size, callback)\n  page_size = page_size or 28*4\n  local cur_page = 1\n  local pages = breakup_pages(options, page_size)\n\n  local prev_alphabetize = false\n  local filtered_set = options\n  local filter_thing = {\n    value = \"\", on_change = function(_self)\n      filtered_set = alphabetize(\n        filter_options(options, _self.value), \n        alphabetize_val.value\n      )\n    end\n  }\n  return function(force_refilter)\n    if force_refilter or (prev_alphabetize ~= alphabetize_val.value) then\n      force_refilter = true\n      pages = breakup_pages(\n        alphabetize(options, alphabetize_val.value), page_size\n      )\n    end\n    prev_alphabetize = alphabetize_val.value\n    set_type_default(filter_thing)\n    local filter_str = filter_thing.value\n    local filter_text = \"[shift+type to filter]\"\n    if filter_str and (filter_str ~= \"\") then\n      filter_text = filter_str\n    end\n\n    if _keyboard_present then\n      GuiLayoutBeginVertical( gui, 61, 0)\n      GuiText(gui, 0, 0, \"Filter:\")\n      GuiLayoutEnd( gui )\n      GuiLayoutBeginVertical( gui, 61 + 11, 0 )\n      if GuiButton( gui, 0, 0, filter_text, next_id() ) then\n        filter_thing.value = \"\"\n      end\n      GuiLayoutEnd( gui)\n    end\n    alphabetize_widget(31, 0)\n\n    if (not filter_str) or (filter_str == \"\") then\n      grid_panel(title, pages[cur_page], nil, callback)\n      if cur_page > 1 then\n        GuiLayoutBeginHorizontal(gui, 46, 96)\n        if GuiButton( gui, 0, 0, \"<-\", next_id() ) then\n          cur_page = cur_page - 1\n        end\n        GuiLayoutEnd(gui)\n      end\n      if #pages > 1 then\n        GuiLayoutBeginHorizontal(gui, 48, 96)\n        GuiText( gui, 0, 0, (\"%d/%d\"):format(cur_page, #pages))\n        GuiLayoutEnd(gui)\n      end\n      if cur_page < #pages then\n        GuiLayoutBeginHorizontal(gui, 51, 96)\n        if GuiButton( gui, 0, 0, \"->\", next_id() ) then\n          cur_page = cur_page + 1\n        end\n        GuiLayoutEnd(gui)\n      end\n    else\n      if force_refilter then\n        filtered_set = alphabetize(\n          filter_options(options, filter_str), \n          alphabetize_val.value\n        )\n      end\n      grid_panel(title, filtered_set, nil, callback)\n    end\n  end\nend\n\nlocal num_types = {\n  float = {function(x) return x end, \"%0.2f\", 1.0},\n  int = {function(x) return round(x) end, \"%d\", 1.0},\n  frame = {function(x) return round(x) end, \"%0.2f\", 1.0/60.0},\n  mills = {function(x) return round(x) end, \"%0.2f\", 1.0/1000.0},\n  hearts = {function(x) return x end, \"%d\", 25.0}\n}\n\nlocal function create_numerical(title, increments, default, kind)\n  local validate, fstr, multiplier = unpack(num_types[kind or \"float\"])\n\n  local text_wrapper = {\n    value = \"\",\n    on_change = function(_self)\n      -- eh?\n    end,\n    on_gain_focus = function(_self)\n      _self.has_focus = true\n      _self.value = _self.numeric:display_val()\n    end,\n    set_value = function(_self)\n      local temp = tonumber(_self.value)\n      if temp then\n        _self.numeric.value = validate(temp / multiplier)\n      end\n    end,\n    on_lose_focus = function(_self)\n      _self.has_focus = false\n      _self:set_value()\n    end,\n    on_hit_enter = function(_self)\n      _self:set_value()\n      set_type_target(nil)\n    end,\n    display_val = function(_self)\n      if not _self.has_focus then return nil end\n      return _self.value .. \"_\"\n    end\n  }\n\n  local wrapper = {\n    text = text_wrapper,\n    value = default or 0.0,\n    display_val = function(_self)\n      return fstr:format(_self.value * multiplier)\n    end,\n    temp_val = \"\",\n    reset = function(_self)\n      _self.value = default\n    end\n  }\n\n  text_wrapper.numeric = wrapper\n\n  return function(xpos, ypos)\n    GuiLayoutBeginHorizontal(gui, xpos, ypos)\n      GuiText(gui, 0, 0, title)\n    GuiLayoutEnd(gui)\n    GuiLayoutBeginHorizontal(gui, xpos + 12, ypos)\n      for idx = #increments, 1, -1 do\n        local s = \"[\" .. string.rep(\"-\", idx) .. \"]\"\n        if GuiButton( gui, 0, 0, s, next_id() ) then\n          wrapper.value = wrapper.value - increments[idx]\n        end\n      end\n      if GuiButton(gui, 0, 0, \"\" .. (text_wrapper:display_val() or wrapper:display_val()), next_id() ) then\n        if text_wrapper.has_focus then\n          set_type_target(nil)\n        else\n          set_type_target(text_wrapper)\n        end\n      end\n      for idx = 1, #increments do\n        local s = \"[\" .. string.rep(\"+\", idx) .. \"]\"\n        if GuiButton( gui, 0, 0, s, next_id() ) then\n          wrapper.value = wrapper.value + increments[idx]\n        end\n      end\n    GuiLayoutEnd(gui)\n  end, wrapper\nend\n\nlocal localization_widget, localization_val = create_radio(\"Show localized names:\", {\n  {\"Yes\", true}, {\"No\", false}\n}, 2, 16)\n\nlocal shuffle_widget, shuffle_val = create_radio(\"Shuffle\", {\n  {\"Yes\", true}, {\"No\", false}\n}, 2)\n\nlocal mana_widget, mana_val = create_numerical(\"Mana\", {50, 500}, 300, 'int')\nlocal mana_rec_widget, mana_rec_val = create_numerical(\"Mana Recharge\", {10, 100}, 100, 'int')\nlocal slots_widget, slots_val = create_numerical(\"Slots\", {1, 5}, 5, 'int')\nlocal multi_widget, multi_val = create_numerical(\"Multicast\", {1}, 1, 'int')\nlocal reload_widget, reload_val = create_numerical(\"Reload\", {1, 10}, 30, 'frame')\nlocal delay_widget, delay_val = create_numerical(\"Delay\", {1, 10}, 30, 'frame')\nlocal spread_widget, spread_val = create_numerical(\"Spread\", {0.1, 1}, 0.0, 'float')\nlocal speed_widget, speed_val = create_numerical(\"Speed\", {0.01, 0.1}, 1.0, 'float')\n\n--local always_cast_choice = nil\nlocal MAX_ALWAYS_CASTS=10 -- eh\nlocal always_cast_index = 1\nlocal always_casts = {}\nlocal function compact_always_casts()\n  local new_always_casts = {}\n  for idx = 1, MAX_ALWAYS_CASTS do\n    if always_casts[idx] then\n      table.insert(new_always_casts, always_casts[idx])\n    end\n  end\n  always_casts = new_always_casts\nend\n\nlocal builder_widgets = {\n  {shuffle_widget, shuffle_val},\n  {mana_widget, mana_val},\n  {mana_rec_widget, mana_rec_val},\n  {slots_widget, slots_val},\n  {multi_widget, multi_val},\n  {reload_widget, reload_val},\n  {delay_widget, delay_val},\n  {spread_widget, spread_val},\n  {speed_widget, speed_val}\n}\n\nbuilder_panel = Panel{\"wand builder\", function()\n  breadcrumbs(1, 0)\n\n  for idx, widget in ipairs(builder_widgets) do\n    widget[1](1, 8 + idx*4)\n  end\n\n  GuiLayoutBeginVertical(gui, 1, 48)\n  for idx = 1, MAX_ALWAYS_CASTS do\n    local label = \"Always cast\"\n    if idx > 1 then label = label .. \" (\" .. idx .. \")\" end\n    if GuiButton( gui, 0, 0, label .. \": \" .. (always_casts[idx] or \"None\"), next_id() ) then\n      always_cast_index = idx\n      enter_panel(always_cast_panel)\n    end\n    if not always_casts[idx] then break end\n  end\n  if GuiButton( gui, 0, 0, \"[Reset all]\", next_id() ) then\n    for _, widget in ipairs(builder_widgets) do\n      widget[2]:reset()\n    end\n    always_casts = {}\n    always_cast_index=1\n  end\n  if GuiButton( gui, 0, 4, \"[Spawn]\", next_id() ) then\n    local x, y = get_player_pos()\n    local gun = {\n      deck_capacity = slots_val.value,\n      actions_per_round = multi_val.value,\n      reload_time = reload_val.value,\n      shuffle_deck_when_empty = (shuffle_val.value and 1) or 0,\n      fire_rate_wait = delay_val.value,\n      spread_degrees = spread_val.value,\n      speed_multiplier = speed_val.value,\n      mana_max = mana_val.value,\n      mana_charge_speed = mana_rec_val.value,\n      always_casts = always_casts --always_cast_choice\n    }\n    build_gun(x, y, gun)\n  end\n  GuiLayoutEnd(gui)\nend}\n\nlocal xpos_widget, xpos_val = create_numerical(\"X\", {100, 1000, 10000}, 0, 'int')\nlocal ypos_widget, ypos_val = create_numerical(\"Y\", {100, 1000, 10000}, 0, 'int')\n\nlocal SPECIAL_LOCATIONS = {\n  [\"$biome_lava\"] = {x=2300}\n}\n\nlocal quick_teleports = nil\nlocal function find_quick_teleports()\n  if quick_teleports then return quick_teleports end\n  quick_teleports = {}\n  local temp_mountains = {}\n  local prev_biome = \"?\"\n  for y = 0, 15000, 500 do\n    local cur_biome = BiomeMapGetName(0, y)\n    if cur_biome == \"$biome_holymountain\" then\n      temp_mountains[prev_biome] = y\n    else\n      prev_biome = cur_biome\n    end\n  end\n  local function refine_position(y0)\n    for y = y0, y0+500, 10 do\n      local cur_biome = BiomeMapGetName(0, y)\n      if cur_biome ~= \"$biome_holymountain\" then\n        return y-10, cur_biome\n      end\n    end\n  end\n  local mountains = {}\n  for biome, y in pairs(temp_mountains) do\n    local teleport_y, next_biome = refine_position(y)\n    teleport_y = teleport_y-200\n    local teleport_x = -200\n    if SPECIAL_LOCATIONS[next_biome] then\n      teleport_x = SPECIAL_LOCATIONS[next_biome].x or teleport_x\n      teleport_y = SPECIAL_LOCATIONS[next_biome].y or teleport_y\n    end\n    local label = (\"%s (%d, %d)\"):format(GameTextGet(next_biome), teleport_x, teleport_y)\n    table.insert(quick_teleports, {label, teleport_x, teleport_y})\n  end\n  table.sort(quick_teleports, function(a, b) return a[3] < b[3] end)\n  return quick_teleports\nend\n\nteleport_panel = Panel{\"teleport\", function()\n  xpos_widget(1, 12)\n  ypos_widget(1, 16)\n\n  breadcrumbs(1, 0)\n\n  GuiLayoutBeginVertical(gui, 1, 20)\n  if GuiButton( gui, 0, 0, \"[Get current position]\", next_id() ) then\n    local x, y = get_player_pos()\n    xpos_val.value, ypos_val.value = math.floor(x), math.floor(y)\n  end\n  if GuiButton( gui, 0, 0, \"[Zero position]\", next_id() ) then\n    xpos_val.value, ypos_val.value = 0, 0\n  end\n  if GuiButton( gui, 0, 0, \"[Teleport]\", next_id() ) then\n    GamePrint((\"Attempting to teleport to (%d, %d)\"):format(xpos_val.value, ypos_val.value))\n    teleport(xpos_val.value, ypos_val.value)\n  end\n  GuiText(gui, 0, 0, \" \") -- just a spacer\n  GuiText(gui, 0, 0, \"----Quick Teleports----\")\n  for i, location in ipairs(find_quick_teleports()) do\n    local label, x, y = unpack(location)\n    if GuiButton(gui, 0, 0, label, next_id() ) then\n      GamePrint((\"Attempting to teleport to (%d, %d)\"):format(x, y))\n      teleport(x, y)\n    end\n  end\n  GuiLayoutEnd(gui)\nend}\n\nlocal cur_hp_widget, cur_hp_val = create_numerical(\"HP\", {1, 4}, 4, 'hearts')\nlocal max_hp_widget, max_hp_val = create_numerical(\"Max HP\", {1, 4}, 4, 'hearts')\n\nhealth_panel = Panel{\"health\", function()\n  cur_hp_widget(1, 12)\n  max_hp_widget(1, 16)\n\n  breadcrumbs(1, 0)\n\n  GuiLayoutBeginVertical(gui, 1, 20)\n  if GuiButton( gui, 0, 0, \"[Get current health]\", next_id() ) then\n    cur_hp_val.value, max_hp_val.value = get_health()\n  end\n  if GuiButton( gui, 0, 0, \"[Apply health changes]\", next_id() ) then\n    set_health(cur_hp_val.value, max_hp_val.value)\n  end\n  GuiText(gui, 0, 0, \" \") -- just a spacer\n  GuiText(gui, 0, 0, \"----Quick health----\")\n  if GuiButton( gui, 0, 0, \"[Add +25 max HP]\", next_id() ) then\n    cur_hp_val.value, max_hp_val.value = get_health()\n    cur_hp_val.value, max_hp_val.value = cur_hp_val.value+1, max_hp_val.value+1\n    set_health(cur_hp_val.value, max_hp_val.value)\n  end\n  if GuiButton( gui, 0, 0, \"[Add +100 max HP]\", next_id() ) then\n    cur_hp_val.value, max_hp_val.value = get_health()\n    cur_hp_val.value, max_hp_val.value = cur_hp_val.value+4, max_hp_val.value+4\n    set_health(cur_hp_val.value, max_hp_val.value)\n  end\n  GuiLayoutEnd(gui)\nend}\n\nlocal money_widget, money_val = create_numerical(\"Gold\", {10, 100, 1000}, 0, 'int')\n\nmoney_panel = Panel{\"gold\", function()\n  money_widget(1, 12)\n  breadcrumbs(1, 0)\n\n  GuiLayoutBeginVertical(gui, 1, 20)\n  if GuiButton( gui, 0, 0, \"[Get current gold]\", next_id() ) then\n    money_val.value = get_money()\n  end\n  if GuiButton( gui, 0, 0, \"[Set current gold]\", next_id() ) then\n    set_money(money_val.value)\n  end\n  GuiText(gui, 0, 0, \" \") -- just a spacer\n  GuiText(gui, 0, 0, \"----Quick cash----\")\n  if GuiButton( gui, 0, 0, \"[+100 Gold]\", next_id() ) then\n    money_val.value = get_money()+100\n    set_money(money_val.value)\n  end\n  if GuiButton( gui, 0, 0, \"[+500 Gold]\", next_id() ) then\n    money_val.value = get_money()+500\n    set_money(money_val.value)\n  end\n  if GuiButton( gui, 0, 0, \"[+2000 Gold]\", next_id() ) then\n    money_val.value = get_money()+2000\n    set_money(money_val.value)\n  end\n  GuiLayoutEnd(gui)\nend}\n\n-- build these button lists once so we aren't rebuilding them every frame\nlocal function localized_name(thing)\n  if localization_val.value then return thing.ui_name else return thing.id end\nend\n\nlocal function spawn_spell_button(card)\n  local x, y = get_player_pos()\n  GamePrint( \"Attempting to spawn \" .. card.id)\n  CreateItemActionEntity( card.id, x, y )\nend\n\nlocal function set_always_cast(card)\n  always_casts[always_cast_index] = (card and card.id) or nil\n  compact_always_casts()\n  prev_panel()\nend\n\nlocal spell_options = {}\nlocal always_cast_options = {\n  {\n    text = \"None\", \n    f = function()\n      set_always_cast(nil)\n    end\n  }\n}\n\nfor idx, card in ipairs(actions) do\n  local ui_name = resolve_localized_name(card.name)\n  local id = card.id:lower()\n  if (not ui_name) or (ui_name == \"\") then ui_name = id end\n  spell_options[idx] = {\n    text = localized_name,\n    id = id, ui_name = ui_name,\n    f = spawn_spell_button\n  }\n  always_cast_options[idx+1] = {\n    text = localized_name,\n    id = id, ui_name = ui_name,\n    f = set_always_cast\n  }\nend\n\nlocal function spawn_perk_button(perk)\n  GamePrint( \"Attempting to spawn \" .. perk.id)\n  spawn_perk(perk.id, get_player())\nend\n\nlocal perk_options = {}\nfor idx, perk in ipairs(perk_list) do\n  perk_options[idx] = {\n    text = localized_name, \n    id = perk.id,\n    ui_name = resolve_localized_name(perk.ui_name, perk.id), \n    f = spawn_perk_button\n  }\nend\n\nlocal quantity_widget, quantity_val = create_numerical(\"Quantity mult:\", {100, 1000}, 1000, 'mills')\nlocal container_widget, container_val = create_radio(\"Container:\", {\n  {\"Potion\", \"potion\"}, {\"Pouch\", \"pouch\"}\n}, 1)\n\nlocal function spawn_potion_button(potion)\n  GamePrint( \"Attempting to spawn potion of \" .. potion.id)\n  spawn_potion(potion.id, quantity_val.value, container_val.value)\nend\n\nlocal potion_options = {}\nfor idx, matinfo in ipairs(materials_list) do\n  local material, translated_material = unpack(matinfo)\n  if material:sub(1,1) ~= \"-\" then\n    potion_options[idx] = {\n      text = localized_name, \n      ui_name = translated_material, id = material,\n      f = spawn_potion_button\n    }\n  else\n    potion_options[idx] = {text = material, f = function() end}\n  end\nend\n\nlocal wand_options = {}\nfor i = 1, 5 do\n  wand_options[i] = {\n    \"Wand Level \" .. i, \n    wrap_spawn(\"data/entities/items/wand_level_0\" .. i .. \".xml\")\n  }\nend\ntable.insert(wand_options, {\"Haxx\", wrap_spawn(\"data/hax/wand_hax.xml\")})\n\nlocal tourist_mode_on = false\nlocal function toggle_tourist_mode()\n  tourist_mode_on = not tourist_mode_on\n  set_tourist_mode(tourist_mode_on)\n  GamePrint(\"Tourist mode: \" .. tostring(tourist_mode_on))\nend\n\nlocal function open_console()\n  local auth_token = listen_console_connections()\n  console_connected = true\n  os.execute(\"start http://localhost:8777/index.html?token=\" .. (auth_token or \"none\"))\nend\n\nlocal seedval = \"?\"\nSetRandomSeed(0, 0)\nseedval = tostring(Random() * 2^31)\n\nlocal LC, AP, LC_prob, AP_prob = get_alchemy()\n\nlocal function format_combo(combo, prob, localize)\n  local ret = {}\n  for idx, mat in ipairs(combo) do\n    ret[idx] = (localize and localize_material(mat)) or mat\n  end\n  return table.concat(ret, \", \") .. \" (\" .. prob .. \"%)\"\nend\n\nlocal alchemy_combos = {\n  AP = {\n    [false]=format_combo(AP, AP_prob, false),\n    [true]=format_combo(AP, AP_prob, true)\n  },\n  LC = {\n    [false]=format_combo(LC, LC_prob, false),\n    [true]=format_combo(LC, LC_prob, true)\n  }\n}\n\nlocal extra_buttons = {}\nfunction register_cheat_button(title, f)\n  table.insert(extra_buttons, {title, f})\nend\n\nlocal function draw_extra_buttons()\n  for _, button in ipairs(extra_buttons) do\n    local title, f = button[1], button[2]\n    if type(title) == 'function' then title = title() end\n    if f then\n      if GuiButton( gui, 0, 0, title, next_id() ) then\n        f()\n      end\n    else\n      GuiText( gui, 0, 0, title)\n    end\n  end\nend\n\nlocal function wrap_localized(f)\n  local prev_localization = false\n  return function()\n    localization_widget(31, 3)\n    local localization_changed = (prev_localization ~= localization_val.value)\n    prev_localization = localization_val.value\n    f(localization_changed)\n  end\nend\n\nlocal _flask_base = wrap_localized(wrap_paginate(\"Select a flask to spawn:\", potion_options))\nlocal function flask_panel_func()\n  quantity_widget(61, 3)\n  container_widget(31, 6)\n  _flask_base()\nend\n\nlocal gui_grid_ref_panel = Panel{\"gui grid ref.\", function()\n  breadcrumbs(1, 0)\n  for row = 0, 100, 10 do\n    for col = 0, 100, 10 do\n      GuiLayoutBeginHorizontal(gui, col, row)\n      GuiText(gui, 0, 0, (\"(%d,%d)\"):format(col, row))\n      GuiLayoutEnd(gui)\n    end\n  end\nend}\n\nlocal function spawn_item_button(item)\n  GamePrint(\"Attempting to spawn \" .. item.path)\n  spawn_item(item.path)\nend\n\n-- merge special spawns into the base spawnlist\nfor _, v in ipairs(special_spawnables) do\n  table.insert(spawn_list, v)\nend\n\n-- generate spawn item options\nlocal spawn_options = {}\nfor idx, item in ipairs(spawn_list) do\n  spawn_options[idx] = {\n    text = localized_name,\n    path = item.path,\n    id = item.xml,\n    ui_name = item.name, \n    f = spawn_item_button\n  }\nend\n\nalways_cast_panel = Panel{\"always cast\", wrap_localized(wrap_paginate(\"Select a spell: \", always_cast_options))}\ncards_panel = Panel{\"spells\", wrap_localized(wrap_paginate(\"Select a spell to spawn:\", spell_options))}\nperk_panel = Panel{\"perks\", wrap_localized(wrap_paginate(\"Select a perk to spawn:\", perk_options))}\nflasks_panel = Panel{\"flasks\", flask_panel_func}\nspawn_panel = Panel{\"items\", wrap_localized(wrap_paginate(\"Select an item to spawn:\", spawn_options))}\n\nwands_panel = Panel{\"wands\", function()\n  grid_panel(\"Select a wand to spawn:\", wand_options)\nend}\n\ninfo_panel = Panel{\"widgets\", function()\n  breadcrumbs(1, 0)\n  GuiLayoutBeginVertical(gui, 1, 11)\n  for idx, winfo in ipairs(_all_info_widgets) do\n    local wname, w = unpack(winfo)\n    local enabled = _info_widgets[wname] ~= nil\n    local text = w:text()\n    if enabled then\n      if GuiButton(gui, 0, 0, \"[*] \" .. text, next_id() ) then\n        remove_info_widget(wname)\n      end\n    else\n      if GuiButton(gui, 0, 0, \"[ ] \" .. text, next_id() ) then\n        GamePrint(\"Adding \" .. wname .. \" to info bar (minimize cheatgui to see)\")\n        add_info_widget(wname, w)\n      end\n    end\n  end\n  GuiLayoutEnd(gui)\nend}\n\nlocal fungal_conv = {from=\"blood\", to=\"blood\"}\nlocal fungal_index\n\nlocal function choose_fungal_material(mat)\n  fungal_conv[fungal_index] = mat.id\n  prev_panel()\nend\n\nlocal fungal_material_panel = Panel{\"shift material\", \n  wrap_localized(wrap_paginate(\"Select a material: \", potion_options, nil, choose_fungal_material))}\n\nlocal function predict_nth_shift(n)\n  local shift_from, shift_to = fungal_predict_transform(n or 0)\n  if shift_from and shift_to then\n    return tostring((shift_from or \"?\")) .. \" -> \" \n        .. tostring((shift_to or \"?\"))\n  else\n    return \"No effect (same material chosen as src and dest)\"\n  end\nend\n\nlocal fungal_panel = Panel{\"fungal\", function()\n  breadcrumbs(1, 0)\n  GuiLayoutBeginVertical(gui, 1, 12)\n  GuiText(gui, 0, 0, \"Next shift: \" .. predict_nth_shift(0))\n  GuiText(gui, 0, 0, \"Next shift+1: \" .. predict_nth_shift(1))\n  GuiText(gui, 0, 0, \"Next shift+2: \" .. predict_nth_shift(2))\n  if GuiButton( gui, 0, 0, \"FROM: \" .. fungal_conv.from, next_id() ) then\n    fungal_index = \"from\"\n    enter_panel(fungal_material_panel)\n  end\n  if GuiButton( gui, 0, 0, \"TO: \" .. fungal_conv.to, next_id() ) then\n    fungal_index = \"to\"\n    enter_panel(fungal_material_panel)\n  end\n  if GuiButton( gui, 0, 0, \"[Force convert]\", next_id()) then\n    GamePrint(\"Would convert: \" .. fungal_conv.from .. \" -> \" .. fungal_conv.to)\n    fungal_force_convert(fungal_conv.from, fungal_conv.to)\n  end\n  GuiLayoutEnd(gui)\nend}\n\n\nconsole_panel = Panel{\"console\", function()\n  breadcrumbs(1, 0)\n  GuiLayoutBeginVertical(gui, 1, 11)\n  if console_connected then\n    if GuiButton( gui, 0, 0, \"[Close console host]\", next_id() ) then\n      close_console_connections()\n      console_connected = false\n    end\n  else\n    if GuiButton( gui, 0, 0, \"[Open console host]\", next_id() ) then\n      listen_console_connections()\n      console_connected = true\n    end\n  end\n  if GuiButton( gui, 0, 0, \"[Open new console]\", next_id() ) then\n    open_console()\n  end\n  GuiText(gui, 0, 0, \" \") -- just a spacer\n  GuiText(gui, 0, 0, \"----Active connections (click to close)----\")\n  local conns = get_console_connections()\n  local sorted_conns = {}\n  for addr, client in pairs(conns) do\n    table.insert(sorted_conns, addr)\n  end\n  table.sort(sorted_conns)\n  for _, addr in ipairs(sorted_conns) do\n    local conn = conns[addr] or {stat_out=-1, stat_in=-1}\n    local text = (\"%s [in: %d, out: %d]\"):format(addr, conn.stat_in or 0, conn.stat_out or 0)\n    if GuiButton( gui, 0, 0, text, next_id() ) then\n      if conns[addr] then conns[addr]:close() end\n    end\n  end\n  GuiLayoutEnd(gui)\nend}\n\nlocal main_panels = {\n  perk_panel, cards_panel, flasks_panel, wands_panel, spawn_panel,\n  builder_panel, health_panel, money_panel,\n  teleport_panel, fungal_panel, info_panel, gui_grid_ref_panel\n}\n\nif _keyboard_present then table.insert(main_panels, console_panel) end\n\nlocal function draw_main_panels()\n  for idx, panel in ipairs(main_panels) do\n    if GuiButton( gui, 0, 0, panel.name .. \"->\", next_id() ) then\n      enter_panel(panel)\n    end\n  end\nend\n\nmenu_panel = Panel{CHEATGUI_TITLE, function()\n  breadcrumbs(1, 0)\n  GuiLayoutBeginVertical( gui, 1, 11 )\n  draw_main_panels()\n  draw_extra_buttons()\n  GuiLayoutEnd(gui)\nend}\n\nregister_cheat_button(\"[edit wands everywhere]\", function()\n  spawn_perk(\"EDIT_WANDS_EVERYWHERE\", get_player())\nend)\n\nregister_cheat_button(\"[spell refresh]\", function()\n  GameRegenItemActionsInPlayer(get_player())\nend)\n\nregister_cheat_button(\"[full heal]\", function() quick_heal() end)\n\nregister_cheat_button(\"[end fungal trip]\", function()\n  EntityRemoveIngestionStatusEffect(get_player(), \"TRIP\" )\nend)\n\nregister_cheat_button(\"[reset fungal shift timer]\", function()\n  GlobalsSetValue(\"fungal_shift_last_frame\", \"-1000000\")\nend)\n\nregister_cheat_button(function()\n  return \"[\" .. ((tourist_mode_on and \"disable\") or \"enable\") .. \" tourist mode]\"\nend, toggle_tourist_mode)\n\nregister_cheat_button(\"[spawn orbs]\", function()\n  local x, y = get_player_pos()\n  for i = 0, 13 do\n    EntityLoad((\"data/entities/items/orbs/orb_%02d.xml\"):format(i), x+(i*15), y - (i*5))\n  end\nend)\n\nif _keyboard_present then\n  register_cheat_button(\"[open console]\", function()\n    open_console()\n    enter_panel(console_panel)\n  end)\nend\n\nenter_panel(menu_panel)\n\n-- widgets\nlocal function StatsWidget(dispname, keyname, extra_pad)\n  local width = math.ceil(#dispname * 0.9) + (extra_pad or 3)\n  return {\n    text = function()\n      return (\"%s: %s\"):format(dispname, StatsGetValue(keyname) or \"?\")\n    end,\n    on_click = function()\n      goto_subpanel(info_panel)\n    end,\n    width = width\n  }\nend\n\nregister_widget(\"playtime\", StatsWidget(\"Playtime\", \"playtime_str\", 6))\nregister_widget(\"visited\", StatsWidget(\"Visited\", \"places_visited\"))\nregister_widget(\"gold\", StatsWidget(\"Gold\", \"gold_all\"))\nregister_widget(\"hearts\", StatsWidget(\"Hearts\", \"heart_containers\"))\nregister_widget(\"items\", StatsWidget(\"Items\", \"items\"))\nregister_widget(\"projectiles\", StatsWidget(\"Shot\", \"projectiles_shot\", 3))\nregister_widget(\"kicks\", StatsWidget(\"Kicked\", \"kicks\"))\nregister_widget(\"kills\", StatsWidget(\"Kills\", \"enemies_killed\"))\nregister_widget(\"damage\", StatsWidget(\"Damage taken\", \"damage_taken\"))\nregister_widget(\"frame\", {\n  text = function()\n    return (\"Frame: %08d\"):format(GameGetFrameNum())\n  end,\n  on_click = function()\n    goto_subpanel(info_panel)\n  end,\n  width = 16\n})\n\nregister_widget(\"position\", {\n  text = function()\n    local x, y = get_player_pos()\n    return (\"X: %d, Y: %d\"):format(x, y)\n  end,\n  on_click = function()\n    goto_subpanel(info_panel)\n  end,\n  width = 15\n})\n\nlocal localize_alchemy = false\n\nfor _, recipe in ipairs{\"LC\", \"AP\"} do\n  local maxwidth = math.max(\n    #(alchemy_combos[recipe][true]), \n    #(alchemy_combos[recipe][false])\n  )\n\n  register_widget(recipe, {\n    text = function()\n      return (\"%s: %s\"):format(recipe, alchemy_combos[recipe][localize_alchemy])\n    end,\n    on_click = function()\n      localize_alchemy = not localize_alchemy\n    end,\n    width = math.ceil(maxwidth * 0.75)\n  })\nend\n\nfunction _cheat_gui_main()\n  if gui ~= nil then\n    GuiStartFrame( gui )\n  end\n\n  if _gui_frame_function ~= nil then\n    reset_id()\n    handle_typing()\n    local happy, errstr = pcall(_gui_frame_function)\n    if not happy then\n      print(\"Gui error: \" .. errstr)\n      GamePrint(\"cheatgui err: \" .. errstr)\n      if console_connected then\n        send_all_consoles(errstr .. \":\" .. debug.traceback())\n      end\n      hide_gui()\n    end\n  end\n\n  wake_up_waiting_threads(1) -- from coroutines.lua\n  if console_connected and _socket_update then _socket_update() end\nend\n\nhide_gui()"
_TWWE_VFS["mods/cheatgui/data/hax/console.lua"] = "dofile_once(\"data/hax/lib/pollnet.lua\")\ndofile_once(\"data/scripts/lib/coroutines.lua\")\n\n-- this empty table is used as a special value that will suppress\n-- printing any kind of \"RES>\" value (normally \"[no value]\" would print)\nlocal UNPRINTABLE_RESULT = {}\n\n-- (from http://lua-users.org/wiki/SplitJoin)\nlocal strfind = string.find\nlocal tinsert = table.insert\nlocal strsub = string.sub\nlocal function strsplit(text, delimiter)\n  local list = {}\n  local pos = 1\n  if strfind(\"\", delimiter, 1) then -- this would result in endless loops\n    error(\"Delimiter matches empty string!\")\n  end\n  while 1 do\n    local first, last = strfind(text, delimiter, pos)\n    if first then -- found?\n      tinsert(list, strsub(text, pos, first-1))\n      pos = last+1\n    else\n      tinsert(list, strsub(text, pos))\n      break\n    end\n  end\n  return list\nend\n\nlocal function is_localhost(addr)\n  local parts = strsplit(addr, \":\")\n  return parts[1] == \"127.0.0.1\" -- IPV6?\nend\n\nlocal function reload_utils(console_env)\n  local env_utils, err = loadfile(\"data/hax/utils.lua\")\n  if type(env_utils) ~= \"function\" then\n    console_env.print(\"Error loading utils: \" .. tostring(err))\n    return\n  end\n  setfenv(env_utils, console_env)\n  local happy, err = pcall(env_utils)\n  if not happy then\n    console_env.print(\"Error executing utils: \" .. tostring(err))\n  end\n  console_env.print(\"Utils loaded.\")\nend\n\nlocal _help_info = nil\nlocal function reload_help(fn)\n  fn = fn or \"tools_modding/lua_api_documentation.txt\"\n  local f, err = io.open(fn)\n  if not f then error(\"Couldn't open \" .. fn) end\n  local res = f:read(\"*a\")\n  f:close()\n  if not res then error(\"Couldn't read \" .. fn) end\n  _help_info = {}\n  res = res:gsub(\"\\r\", \"\") -- get rid of horrible carriage returns\n  local lines = strsplit(res, \"\\n\")\n  for _, line in ipairs(lines) do\n    local paren_idx = line:find(\"%(\")\n    if paren_idx then\n      local funcname = line:sub(1, paren_idx-1)\n      _help_info[funcname] = line\n    end\n  end\nend\n\nlocal function help_str(funcname)\n  if not _help_info then reload_help() end\n  return _help_info[funcname]\nend\n\nlocal function _strinfo(v)\n  if v == nil then return \"nil\" end\n  local vtype = type(v)\n  if vtype == \"number\" then\n    return (\"%0.4f\"):format(v)\n  elseif vtype == \"string\" then\n    return '\"' .. v .. '\"'\n  elseif vtype == \"boolean\" then\n    return tostring(v)\n  else\n    return (\"[%s] %s\"):format(vtype, tostring(v))\n  end\nend\n\nlocal function strinfo(...)\n  local frags = {}\n  local nargs = select('#', ...)\n  if nargs == 0 then\n    return \"[no value]\"\n  end\n  if nargs == 1 and select(1, ...) == UNPRINTABLE_RESULT then\n    return UNPRINTABLE_RESULT\n  end\n  for idx = 1, nargs do\n    frags[idx] = _strinfo(select(idx, ...))\n  end\n  return table.concat(frags, \", \")\nend\n\nlocal function make_complete(console_env)\n  return function(s)\n    local opts = {}\n\n    local parts = strsplit(s, \"%.\") -- strsplit takes a pattern, so have to escape \".\"\n    local cur = console_env\n    local prefix = \"\"\n    for idx = 1, (#parts) - 1 do\n      cur = cur[parts[idx]]\n      if not cur then return UNPRINTABLE_RESULT end\n      prefix = prefix .. parts[idx] .. \".\"\n    end\n    if type(cur) ~= \"table\" then return UNPRINTABLE_RESULT end\n    local lastpart = parts[#parts]\n    if not lastpart then return UNPRINTABLE_RESULT end\n    for k, _ in pairs(cur) do\n      if k:find(lastpart) == 1 then\n        table.insert(opts, k)\n      end\n    end\n    if #opts > 0 then\n      table.sort(opts)\n      console_env.send(\"COM>\" .. prefix .. \" \" .. table.concat(opts, \",\"))\n    end\n    return UNPRINTABLE_RESULT\n  end\nend\n\nlocal function make_console_env(client)\n  local console_env = {}\n  for k, v in pairs(getfenv()) do\n    console_env[k] = v\n  end\n  for k, v in pairs(cheatgui_stash) do\n    if not console_env[k] then console_env[k] = v end\n  end\n\n  function console_env.print(...)\n    local msg = table.concat({...}, \" \")\n    client:send(\"GAME> \" .. msg)\n    return UNPRINTABLE_RESULT\n  end\n\n  function console_env.err_print(...)\n    local msg = table.concat({...}, \" \")\n    client:send(\"ERR> \" .. msg)\n    return UNPRINTABLE_RESULT\n  end\n\n  function console_env.send(msg)\n    client:send(msg)\n  end\n\n  function console_env.print_table(t)\n    local s = {}\n    for k, v in pairs(t) do\n      table.insert(s, k .. \": \" .. type(v))\n    end\n    console_env.print(table.concat(s, \"\\n\"))\n  end\n\n  function console_env.log(...)\n    local msg = table.concat({...}, \" \")\n    print(client.addr .. \": \" .. msg)\n  end\n\n  function console_env.info(...)\n    console_env.print(strinfo(...))\n    return UNPRINTABLE_RESULT\n  end\n\n  function console_env.dofile(fn)\n    local s = loadfile(fn)\n    if type(s) == 'string' then\n      -- work around Noita's broken loadfile that returns error\n      -- message as first argument rather than as second\n      error(fn .. \": \" .. s)\n    end\n    setfenv(s, console_env)\n    return s()\n  end\n\n  function console_env.help(funcname)\n    console_env.send(\"HELP> \" .. (help_str(funcname) or (funcname .. \"-> [no help available]\")))\n    return UNPRINTABLE_RESULT\n  end\n\n  -- Hmm maybe it's just better to use regular async for this?\n  --[[\n  console_env._persistent_funcs = {}\n\n  function console_env.add_persistent_func(name, f)\n    console_env._persistent_funcs[name] = f\n  end\n\n  function console_env.remove_persistent_func(name)\n    console_env._persistent_funcs[name] = nil\n  end\n\n  function console_env.run_persistent_funcs()\n    for fname, f in pairs(console_env._persistent_funcs) do\n      local happy, err = pcall(f, fname)\n      if not happy then console_env.err_print(err or \"?\") end\n    end\n  end\n  ]]\n\n  console_env.complete = make_complete(console_env)\n  console_env.add_persistent_func = add_persistent_func\n  console_env.set_persistent_func = add_persistent_func -- alias\n  console_env.remove_persistent_func = remove_persistent_func\n  console_env.strinfo = strinfo\n  console_env.help_str = help_str\n  console_env.UNPRINTABLE_RESULT = UNPRINTABLE_RESULT\n  \n  reload_utils(console_env)\n\n  return console_env\nend\n\nlocal function _collect(happy, ...)\n  if happy then\n    return happy, strinfo(...)\n  else\n    return happy, ...\n  end\nend\n\nlocal SCRATCH_SIZE = 1000000 -- might as well have a safe meg of space\nlocal ws_server_socket = nil\nlocal http_server = nil\nlocal ws_clients = {}\n\nlocal TOKEN_FN = \"mods/cheatgui/token.json\"\nlocal TOKEN_EXPIRATION = 6*3600 -- tokens expire after six hours\n\nlocal function read_raw_file(filename)\n  local f, err = io.open(filename)\n  if not f then return nil end\n  local res = f:read(\"*a\")\n  f:close()\n  return res\nend\n\nlocal function write_raw_file(filename, data)\n  local f, err = io.open(filename, \"w\")\n  if not f then error(\"Couldn't write \" .. filename .. \": \" .. err) end\n  f:write(data)\n  f:close()\nend\n\nlocal auth_token = nil\nlocal function generate_token()\n  print(\"Cheatgui webconsole: generating new token.\")\n  auth_token = lib_pollnet.nanoid()\n  write_raw_file(TOKEN_FN, JSON:encode_pretty{\n    token = auth_token,\n    expiration = os.time() + TOKEN_EXPIRATION\n  })\n  return auth_token\nend\n\nlocal function get_token()\n  if not auth_token then\n    if not JSON then dofile_once(\"data/hax/lib/json.lua\") end\n    local tdata = read_raw_file(TOKEN_FN)\n    if tdata then \n      tdata = JSON:decode(tdata) \n      print(\"Got existing token: \" .. tdata.token .. \" -- \" .. tdata.expiration)\n    end\n    if tdata and tdata.expiration and (tdata.expiration > os.time()) then\n      auth_token = tdata.token\n    else\n      if tdata then\n        print(\"Token expired? \" .. tdata.expiration .. \" vs. \" .. os.time())\n      else \n        print(\"No token; generating new.\")\n      end\n      auth_token = generate_token()\n    end\n  end\n  return auth_token\nend\n\nlocal function close_client(client)\n  if client.sock then\n    client.sock:close()\n    client.sock = nil\n  end\n  ws_clients[client.addr] = nil\nend\n\nlocal function client_send(client, msg)\n  if client.sock then\n    client.stat_out = (client.stat_out or 0) + 1\n    client.sock:send(msg)\n  else\n    client:close()\n  end\nend\n\nlocal function on_new_client(sock, addr)\n  print(\"New client: \" .. addr)\n  if ws_clients[addr] then ws_clients[addr].sock:close() end\n  local new_client = {addr = addr, sock = sock, authorized = false, close = close_client, send = client_send, stat_in=0, stat_out=0}\n  new_client.console_env = make_console_env(new_client)\n  ws_clients[addr] = new_client\nend\n\nfunction listen_console_connections()\n  lib_pollnet.link()\n  if not ws_server_socket then\n    ws_server_socket = lib_pollnet.listen_ws(\"127.0.0.1:9777\", SCRATCH_SIZE)\n    ws_server_socket:on_connection(on_new_client)\n    http_server = lib_pollnet.serve_http(\"127.0.0.1:8777\", \"mods/cheatgui/www\")\n  end\n  return get_token()\nend\n\nfunction get_console_connections()\n  return ws_clients\nend\n\nfunction close_console_connections()\n  for _, sock in pairs(ws_clients) do sock:close() end\n  ws_clients = {}\n  if ws_server_socket then ws_server_socket:close() end\n  ws_server_socket = nil\n  if http_server then http_server:close() end\n  http_server = nil\nend\n\nfunction send_all_consoles(msg)\n  for _, sock in pairs(ws_clients) do\n    sock:send(\"ERR>\" .. msg)\n  end\nend\n\nlocal function check_authorization(client, msg)\n  if not is_localhost(client.addr) then\n    client.sock:send(\"SYS> UNAUTHORIZED: NOT LOCALHOST!\")\n    client.sock:close()\n    client.sock = nil\n    return\n  end\n\n  if msg:find(get_token()) then\n    client.authorized = true\n    client.sock:send(\"SYS> AUTHORIZED\")\n    GamePrint(\"Accepted console connection: \" .. client.addr)\n  else\n    client.sock:send(\"SYS> UNAUTHORIZED: INVALID TOKEN\")\n    client.sock:close()\n    client.sock = nil\n  end\nend\n\nlocal function _handle_client_message(client, msg)\n  if not client.authorized then\n    return check_authorization(client, msg)\n  end\n\n  client.stat_in = (client.stat_in or 0) + 1\n  local f, err = nil, nil\n  if not msg:find(\"\\n\") then\n    -- if this is a single line, try putting \"return \" in front\n    -- (convenience to allow us to inspect values)\n    f, err = loadstring(\"return \" .. msg)\n  end\n  if not f then -- multiline, or not an expression\n    f, err = loadstring(msg)\n    if not f then\n      client:send(\"ERR> Parse error: \" .. tostring(err))\n      return\n    end\n  end\n  setfenv(f, client.console_env)\n  local happy, retval = _collect(pcall(f))\n  if happy then\n    if retval ~= UNPRINTABLE_RESULT then\n      client:send(\"RES> \" .. tostring(retval))\n    end\n  else\n    client:send(\"ERR> \" .. tostring(retval))\n  end\nend\n\nlocal count = 0\nfunction _socket_update()\n  if not ws_server_socket then return end\n  local happy, msg = ws_server_socket:poll()\n  if not happy then\n    print(\"Main WS server closed?\")\n    close_console_connections()\n    return\n  end\n\n  for addr, client in pairs(ws_clients) do\n    if client.sock then\n      local happy, msg = client.sock:poll()\n      if not happy then\n        print(\"Sock error: \" .. tostring(msg))\n        client.sock:close()\n        client.sock = nil\n        ws_clients[addr] = nil\n      elseif msg then\n        _handle_client_message(client, msg)\n      end\n    else\n      ws_clients[addr] = nil\n    end\n  end\n\n  if (count % 60 == 0) and http_server then\n    local happy, errmsg = http_server:poll()\n    if not happy then\n      print(\"HTTP server closed: \" .. tostring(errmsg))\n      http_server:close()\n      http_server = nil\n    end\n  end\n\n  count = count + 1\nend"
_TWWE_VFS["mods/cheatgui/data/hax/fungal.lua"] = "local fungal_env = nil\nlocal _predict_transform = nil\n\nlocal STASH = cheatgui_stash\n\nif not loadstring then\n  local VIRT_PATH = \"mods/cheatgui/_fake_fungal_shift.lua\"\n  function loadstring(buf)\n    STASH.ModTextFileSetContent(VIRT_PATH, buf)\n    return loadfile(VIRT_PATH)\n  end\nend\n\nSTASH.loadstring = loadstring\n\nlocal function _dofile(fn)\n  local src = STASH.ModTextFileGetContent(fn)\n  if not src then return nil end\n  src = STASH.loadstring(src)\n  if not src then return nil end\n  setfenv(src, fungal_env)\n  return src()\nend\n\nlocal _done_files = {}\nlocal function _dofile_once(fn)\n  if _done_files[fn] then return _done_files[fn] end\n  _done_files[fn] = _dofile(fn)\n  return _done_files[fn]\nend\n\nlocal MOCKED_FUNCTIONS = {\n  \"GlobalsSetValue\",\n  \"GameCreateParticle\",\n  \"GamePrintImportant\",\n  \"GamePrint\",\n  \"EntityCreateNew\",\n  \"EntityAddComponent\",\n  \"EntityAddChild\",\n  \"GameTriggerMusicFadeOutAndDequeueAll\",\n  \"GameTriggerMusicEvent\",\n  \"EntityLoad\",\n  \"EntityRemoveIngestionStatusEffect\",\n  \"print\", -- stop fungal_shift from spamming the log!!!\n}\n\nlocal _fungal_iteration = 0\nlocal function load_fungal_env()\n  fungal_env = {}\n\n  for k, v in pairs(cheatgui_stash) do fungal_env[k] = v end\n  fungal_env.dofile = _dofile\n  fungal_env.dofile_once = _dofile_once\n  setfenv(_dofile, fungal_env)\n  setfenv(_dofile_once, fungal_env)\n\n  for _, v in ipairs(MOCKED_FUNCTIONS) do\n    fungal_env[v] = function(...)\n      -- haha do nothing\n    end\n  end\n\n  fungal_env.GlobalsGetValue = function(v, ...)\n    if v == \"fungal_shift_last_frame\" then\n      -- force it to always give an answer\n      return -10000\n    elseif v == \"fungal_shift_iteration\" then\n      -- allow us to manipulate the iteration\n      return tostring(_fungal_iteration)\n    else\n      return GlobalsGetValue(v, ...)\n    end\n  end\n\n  local fungal_script_src = cheatgui_stash.ModTextFileGetContent(\"data/scripts/magic/fungal_shift.lua\")\n  local fscript = loadstring(fungal_script_src)\n  setfenv(fscript, fungal_env)\n  fscript()\nend\n\nlocal function get_player()\n  return (EntityGetWithTag( \"player_unit\" ) or {})[1]\nend\n\nlocal function get_player_pos()\n  local player = get_player()\n  if not player then return 0, 0 end\n  return EntityGetTransform(player)\nend\n\nlocal function predict_transform(iter_offset)\n  _fungal_iteration = tonumber(GlobalsGetValue(\"fungal_shift_iteration\", \"0\")) + iter_offset\n  local _from, _to = nil, nil\n  fungal_env.ConvertMaterialEverywhere = function(from_material, to_material)\n    _from = CellFactory_GetUIName(from_material) --:gsub(\"$\", \"\")\n    _to = CellFactory_GetUIName(to_material) --:gsub(\"$\", \"\")\n  end\n  pcall(fungal_env.fungal_shift, get_player(), get_player_pos())\n  return _from, _to\nend\n\nlocal function to_material_int_type(v)\n  if type(v) ~= \"number\" then\n    v = CellFactory_GetType(v)\n  end\n  return v\nend\n\nfunction fungal_force_convert(from, to)\n  ConvertMaterialEverywhere(\n    to_material_int_type(from),\n    to_material_int_type(to)\n  )\nend\n\nfunction fungal_predict_transform(iter_offset)\n  if not fungal_env then load_fungal_env() end\n  if not fungal_env then return nil end\n  return predict_transform(iter_offset)\nend"
_TWWE_VFS["mods/cheatgui/data/hax/gun_builder.lua"] = "dofile(\"data/scripts/gun/procedural/gun_procedural.lua\")\n\nfunction build_gun(x, y, gun)\n  local entity_id = EntityLoad(\"data/hax/wand_empty.xml\", x, y)\n	local ability_comp = EntityGetFirstComponent( entity_id, \"AbilityComponent\" )\n\n  gun.cost = gun.cost or 0\n  gun.deck_capacity = gun.deck_capacity or 5\n  gun.actions_per_round = gun.actions_per_round or 1\n  gun.reload_time = gun.reload_time or 30\n  gun.shuffle_deck_when_empty = gun.shuffle_deck_when_empty or 0\n  gun.fire_rate_wait = gun.fire_rate_wait or 30\n  gun.spread_degrees = gun.spread_degrees or 0\n  gun.speed_multiplier = gun.speed_multiplier or 1\n  gun.prob_unshuffle = gun.prob_unshuffle or 0.1\n  gun.prob_draw_many = gun.prob_draw_many or 0.15\n  gun.mana_charge_speed = gun.mana_charge_speed or 10000\n  gun.mana_max = gun.mana_max or 10000\n  gun.force_unshuffle = gun.force_unshuffle or 1\n\n  local name = \"HAXXXX\" --ComponentGetValue( ability_comp, \"ui_name\" )\n\n  ComponentSetValue( ability_comp, \"ui_name\", name )\n  ComponentObjectSetValue( ability_comp, \"gun_config\", \"actions_per_round\", gun[\"actions_per_round\"] )\n  ComponentObjectSetValue( ability_comp, \"gun_config\", \"reload_time\", gun[\"reload_time\"] )\n  ComponentObjectSetValue( ability_comp, \"gun_config\", \"deck_capacity\", gun[\"deck_capacity\"] )\n  ComponentObjectSetValue( ability_comp, \"gun_config\", \"shuffle_deck_when_empty\", gun[\"shuffle_deck_when_empty\"] )\n  ComponentObjectSetValue( ability_comp, \"gunaction_config\", \"fire_rate_wait\", gun[\"fire_rate_wait\"] )\n  ComponentObjectSetValue( ability_comp, \"gunaction_config\", \"spread_degrees\", gun[\"spread_degrees\"] )\n  ComponentObjectSetValue( ability_comp, \"gunaction_config\", \"speed_multiplier\", gun[\"speed_multiplier\"] )\n  ComponentSetValue( ability_comp, \"mana_charge_speed\", gun[\"mana_charge_speed\"])\n  ComponentSetValue( ability_comp, \"mana_max\", gun[\"mana_max\"])\n  ComponentSetValue( ability_comp, \"mana\", gun[\"mana_max\"])\n  ComponentSetValue( ability_comp, \"item_recoil_recovery_speed\", 15.0 ) -- TODO: implement logic for setting this\n  \n  local always_casts = gun[\"always_casts\"] or {gun[\"always_cast\"]} or {}\n  for _, spell_id in ipairs(always_casts) do\n    AddGunActionPermanent( entity_id, spell_id )\n  end\n\n\n  local wand = GetWand( gun )\n  SetWandSprite( entity_id, ability_comp, wand.file, wand.grip_x, wand.grip_y, (wand.tip_x - wand.grip_x), (wand.tip_y - wand.grip_y) )\nend"
_TWWE_VFS["mods/cheatgui/data/hax/lib/json.lua"] = "-- This file is huge and Noita doesn't have real requires, so\n-- manually guard against multiple dofiles\nif JSON then return end\n\n-- -*- coding: utf-8 -*-\n--\n-- Simple JSON encoding and decoding in pure Lua.\n--\n-- Copyright 2010-2017 Jeffrey Friedl\n-- http://regex.info/blog/\n-- Latest version: http://regex.info/blog/lua/json\n--\n-- This code is released under a Creative Commons CC-BY \"Attribution\" License:\n-- http://creativecommons.org/licenses/by/3.0/deed.en_US\n--\n-- It can be used for any purpose so long as:\n--    1) the copyright notice above is maintained\n--    2) the web-page links above are maintained\n--    3) the 'AUTHOR_NOTE' string below is maintained\n--\nlocal VERSION = '20170927.26' -- version history at end of file\nlocal AUTHOR_NOTE = \"-[ JSON.lua package by Jeffrey Friedl (http://regex.info/blog/lua/json) version 20170927.26 ]-\"\n\n--\n-- The 'AUTHOR_NOTE' variable exists so that information about the source\n-- of the package is maintained even in compiled versions. It's also\n-- included in OBJDEF below mostly to quiet warnings about unused variables.\n--\nlocal OBJDEF = {\n   VERSION      = VERSION,\n   AUTHOR_NOTE  = AUTHOR_NOTE,\n}\n\n\n--\n-- Simple JSON encoding and decoding in pure Lua.\n-- JSON definition: http://www.json.org/\n--\n--\n--   JSON = assert(loadfile \"JSON.lua\")() -- one-time load of the routines\n--\n--   local lua_value = JSON:decode(raw_json_text)\n--\n--   local raw_json_text    = JSON:encode(lua_table_or_value)\n--   local pretty_json_text = JSON:encode_pretty(lua_table_or_value) -- \"pretty printed\" version for human readability\n--\n--\n--\n-- DECODING (from a JSON string to a Lua table)\n--\n--\n--   JSON = assert(loadfile \"JSON.lua\")() -- one-time load of the routines\n--\n--   local lua_value = JSON:decode(raw_json_text)\n--\n--   If the JSON text is for an object or an array, e.g.\n--     { \"what\": \"books\", \"count\": 3 }\n--   or\n--     [ \"Larry\", \"Curly\", \"Moe\" ]\n--\n--   the result is a Lua table, e.g.\n--     { what = \"books\", count = 3 }\n--   or\n--     { \"Larry\", \"Curly\", \"Moe\" }\n--\n--\n--   The encode and decode routines accept an optional second argument,\n--   \"etc\", which is not used during encoding or decoding, but upon error\n--   is passed along to error handlers. It can be of any type (including nil).\n--\n--\n--\n-- ERROR HANDLING DURING DECODE\n--\n--   With most errors during decoding, this code calls\n--\n--      JSON:onDecodeError(message, text, location, etc)\n--\n--   with a message about the error, and if known, the JSON text being\n--   parsed and the byte count where the problem was discovered. You can\n--   replace the default JSON:onDecodeError() with your own function.\n--\n--   The default onDecodeError() merely augments the message with data\n--   about the text and the location (and, an 'etc' argument had been\n--   provided to decode(), its value is tacked onto the message as well),\n--   and then calls JSON.assert(), which itself defaults to Lua's built-in\n--   assert(), and can also be overridden.\n--\n--   For example, in an Adobe Lightroom plugin, you might use something like\n--\n--          function JSON:onDecodeError(message, text, location, etc)\n--             LrErrors.throwUserError(\"Internal Error: invalid JSON data\")\n--          end\n--\n--   or even just\n--\n--          function JSON.assert(message)\n--             LrErrors.throwUserError(\"Internal Error: \" .. message)\n--          end\n--\n--   If JSON:decode() is passed a nil, this is called instead:\n--\n--      JSON:onDecodeOfNilError(message, nil, nil, etc)\n--\n--   and if JSON:decode() is passed HTML instead of JSON, this is called:\n--\n--      JSON:onDecodeOfHTMLError(message, text, nil, etc)\n--\n--   The use of the 'etc' argument allows stronger coordination between\n--   decoding and error reporting, especially when you provide your own\n--   error-handling routines. Continuing with the the Adobe Lightroom\n--   plugin example:\n--\n--          function JSON:onDecodeError(message, text, location, etc)\n--             local note = \"Internal Error: invalid JSON data\"\n--             if type(etc) = 'table' and etc.photo then\n--                note = note .. \" while processing for \" .. etc.photo:getFormattedMetadata('fileName')\n--             end\n--             LrErrors.throwUserError(note)\n--          end\n--\n--            :\n--            :\n--\n--          for i, photo in ipairs(photosToProcess) do\n--               :             \n--               :             \n--               local data = JSON:decode(someJsonText, { photo = photo })\n--               :             \n--               :             \n--          end\n--\n--\n--\n--   If the JSON text passed to decode() has trailing garbage (e.g. as with the JSON \"[123]xyzzy\"),\n--   the method\n--\n--       JSON:onTrailingGarbage(json_text, location, parsed_value, etc)\n--\n--   is invoked, where:\n--\n--       'json_text' is the original JSON text being parsed,\n--       'location' is the count of bytes into 'json_text' where the garbage starts (6 in the example),\n--       'parsed_value' is the Lua result of what was successfully parsed ({123} in the example),\n--       'etc' is as above.\n--\n--   If JSON:onTrailingGarbage() does not abort, it should return the value decode() should return,\n--   or nil + an error message.\n--\n--     local new_value, error_message = JSON:onTrailingGarbage()\n--\n--   The default JSON:onTrailingGarbage() simply invokes JSON:onDecodeError(\"trailing garbage\"...),\n--   but you can have this package ignore trailing garbage via\n--\n--      function JSON:onTrailingGarbage(json_text, location, parsed_value, etc)\n--         return parsed_value\n--      end\n--\n--\n-- DECODING AND STRICT TYPES\n--\n--   Because both JSON objects and JSON arrays are converted to Lua tables,\n--   it's not normally possible to tell which original JSON type a\n--   particular Lua table was derived from, or guarantee decode-encode\n--   round-trip equivalency.\n--\n--   However, if you enable strictTypes, e.g.\n--\n--      JSON = assert(loadfile \"JSON.lua\")() --load the routines\n--      JSON.strictTypes = true\n--\n--   then the Lua table resulting from the decoding of a JSON object or\n--   JSON array is marked via Lua metatable, so that when re-encoded with\n--   JSON:encode() it ends up as the appropriate JSON type.\n--\n--   (This is not the default because other routines may not work well with\n--   tables that have a metatable set, for example, Lightroom API calls.)\n--\n--\n-- ENCODING (from a lua table to a JSON string)\n--\n--   JSON = assert(loadfile \"JSON.lua\")() -- one-time load of the routines\n--\n--   local raw_json_text    = JSON:encode(lua_table_or_value)\n--   local pretty_json_text = JSON:encode_pretty(lua_table_or_value) -- \"pretty printed\" version for human readability\n--   local custom_pretty    = JSON:encode(lua_table_or_value, etc, { pretty = true, indent = \"|  \", align_keys = false })\n--\n--   On error during encoding, this code calls:\n--\n--     JSON:onEncodeError(message, etc)\n--\n--   which you can override in your local JSON object. Also see \"HANDLING UNSUPPORTED VALUE TYPES\" below.\n--\n--   The 'etc' in the error call is the second argument to encode() and encode_pretty(), or nil if it wasn't provided.\n--\n--\n--\n--\n-- ENCODING OPTIONS\n--\n--   An optional third argument, a table of options, can be provided to encode().\n--\n--       encode_options =  {\n--           -- options for making \"pretty\" human-readable JSON (see \"PRETTY-PRINTING\" below)\n--           pretty         = true,   -- turn pretty formatting on\n--           indent         = \"   \",  -- use this indent for each level of an array/object\n--           align_keys     = false,  -- if true, align the keys in a way that sounds like it should be nice, but is actually ugly\n--           array_newline  = false,  -- if true, array elements become one to a line rather than inline\n--           \n--           -- other output-related options\n--           null           = \"\\0\",   -- see \"ENCODING JSON NULL VALUES\" below\n--           stringsAreUtf8 = false,  -- see \"HANDLING UNICODE LINE AND PARAGRAPH SEPARATORS FOR JAVA\" below\n--       }\n--  \n--       json_string = JSON:encode(mytable, etc, encode_options)\n--\n--\n--\n-- For reference, the defaults are:\n--\n--           pretty         = false\n--           null           = nil,\n--           stringsAreUtf8 = false,\n--\n--\n--\n-- PRETTY-PRINTING\n--\n--   Enabling the 'pretty' encode option helps generate human-readable JSON.\n--\n--     pretty = JSON:encode(val, etc, {\n--                                       pretty = true,\n--                                       indent = \"   \",\n--                                       align_keys = false,\n--                                     })\n--\n--   encode_pretty() is also provided: it's identical to encode() except\n--   that encode_pretty() provides a default options table if none given in the call:\n--\n--       { pretty = true, indent = \"  \", align_keys = false, array_newline = false }\n--\n--   For example, if\n--\n--      JSON:encode(data)\n--\n--   produces:\n--\n--      {\"city\":\"Kyoto\",\"climate\":{\"avg_temp\":16,\"humidity\":\"high\",\"snowfall\":\"minimal\"},\"country\":\"Japan\",\"wards\":11}\n--\n--   then\n--\n--      JSON:encode_pretty(data)\n--\n--   produces:\n--\n--      {\n--        \"city\": \"Kyoto\",\n--        \"climate\": {\n--          \"avg_temp\": 16,\n--          \"humidity\": \"high\",\n--          \"snowfall\": \"minimal\"\n--        },\n--        \"country\": \"Japan\",\n--        \"wards\": 11\n--      }\n--\n--   The following lines all return identical strings:\n--       JSON:encode_pretty(data)\n--       JSON:encode_pretty(data, nil, { pretty = true, indent = \"  \", align_keys = false, array_newline = false})\n--       JSON:encode_pretty(data, nil, { pretty = true, indent = \"  \" })\n--       JSON:encode       (data, nil, { pretty = true, indent = \"  \" })\n--\n--   An example of setting your own indent string:\n--\n--     JSON:encode_pretty(data, nil, { pretty = true, indent = \"|    \" })\n--\n--   produces:\n--\n--      {\n--      |    \"city\": \"Kyoto\",\n--      |    \"climate\": {\n--      |    |    \"avg_temp\": 16,\n--      |    |    \"humidity\": \"high\",\n--      |    |    \"snowfall\": \"minimal\"\n--      |    },\n--      |    \"country\": \"Japan\",\n--      |    \"wards\": 11\n--      }\n--\n--   An example of setting align_keys to true:\n--\n--     JSON:encode_pretty(data, nil, { pretty = true, indent = \"  \", align_keys = true })\n--  \n--   produces:\n--   \n--      {\n--           \"city\": \"Kyoto\",\n--        \"climate\": {\n--                     \"avg_temp\": 16,\n--                     \"humidity\": \"high\",\n--                     \"snowfall\": \"minimal\"\n--                   },\n--        \"country\": \"Japan\",\n--          \"wards\": 11\n--      }\n--\n--   which I must admit is kinda ugly, sorry. This was the default for\n--   encode_pretty() prior to version 20141223.14.\n--\n--\n--  HANDLING UNICODE LINE AND PARAGRAPH SEPARATORS FOR JAVA\n--\n--    If the 'stringsAreUtf8' encode option is set to true, consider Lua strings not as a sequence of bytes,\n--    but as a sequence of UTF-8 characters.\n--\n--    Currently, the only practical effect of setting this option is that Unicode LINE and PARAGRAPH\n--    separators, if found in a string, are encoded with a JSON escape instead of being dumped as is.\n--    The JSON is valid either way, but encoding this way, apparently, allows the resulting JSON\n--    to also be valid Java.\n--\n--  AMBIGUOUS SITUATIONS DURING THE ENCODING\n--\n--   During the encode, if a Lua table being encoded contains both string\n--   and numeric keys, it fits neither JSON's idea of an object, nor its\n--   idea of an array. To get around this, when any string key exists (or\n--   when non-positive numeric keys exist), numeric keys are converted to\n--   strings.\n--\n--   For example, \n--     JSON:encode({ \"one\", \"two\", \"three\", SOMESTRING = \"some string\" }))\n--   produces the JSON object\n--     {\"1\":\"one\",\"2\":\"two\",\"3\":\"three\",\"SOMESTRING\":\"some string\"}\n--\n--   To prohibit this conversion and instead make it an error condition, set\n--      JSON.noKeyConversion = true\n--\n--\n-- ENCODING JSON NULL VALUES\n--\n--   Lua tables completely omit keys whose value is nil, so without special handling there's\n--   no way to represent JSON object's null value in a Lua table.  For example\n--      JSON:encode({ username = \"admin\", password = nil })\n--\n--   produces:\n--\n--      {\"username\":\"admin\"}\n--\n--   In order to actually produce\n--\n--      {\"username\":\"admin\", \"password\":null}\n--\n\n--   one can include a string value for a \"null\" field in the options table passed to encode().... \n--   any Lua table entry with that value becomes null in the JSON output:\n--\n--      JSON:encode({ username = \"admin\", password = \"xyzzy\" }, -- First arg is the Lua table to encode as JSON.\n--                  nil,                                        -- Second arg is the 'etc' value, ignored here\n--                  { null = \"xyzzy\" })                         -- Third arg is th options table\n--\n--   produces:\n--\n--      {\"username\":\"admin\", \"password\":null}\n--\n--   Just be sure to use a string that is otherwise unlikely to appear in your data.\n--   The string \"\\0\" (a string with one null byte) may well be appropriate for many applications.\n--\n--   The \"null\" options also applies to Lua tables that become JSON arrays.\n--      JSON:encode({ \"one\", \"two\", nil, nil })\n--\n--   produces\n--\n--      [\"one\",\"two\"]\n--\n--   while\n--\n--      NullPlaceholder = \"\\0\"\n--      encode_options = { null = NullPlaceholder }\n--      JSON:encode({ \"one\", \"two\", NullPlaceholder, NullPlaceholder}, nil, encode_options)\n--   produces\n--\n--      [\"one\",\"two\",null,null]\n--\n--\n--\n-- HANDLING LARGE AND/OR PRECISE NUMBERS\n--\n--\n--   Without special handling, numbers in JSON can lose precision in Lua.\n--   For example:\n--   \n--      T = JSON:decode('{  \"small\":12345, \"big\":12345678901234567890123456789, \"precise\":9876.67890123456789012345  }')\n--\n--      print(\"small:   \",  type(T.small),    T.small)\n--      print(\"big:     \",  type(T.big),      T.big)\n--      print(\"precise: \",  type(T.precise),  T.precise)\n--   \n--   produces\n--   \n--      small:          number  12345\n--      big:            number  1.2345678901235e+28\n--      precise:        number  9876.6789012346\n--\n--   Precision is lost with both 'big' and 'precise'.\n--\n--   This package offers ways to try to handle this better (for some definitions of \"better\")...\n--\n--   The most precise method is by setting the global:\n--   \n--      JSON.decodeNumbersAsObjects = true\n--   \n--   When this is set, numeric JSON data is encoded into Lua in a form that preserves the exact\n--   JSON numeric presentation when re-encoded back out to JSON, or accessed in Lua as a string.\n--\n--   This is done by encoding the numeric data with a Lua table/metatable that returns\n--   the possibly-imprecise numeric form when accessed numerically, but the original precise\n--   representation when accessed as a string.\n--\n--   Consider the example above, with this option turned on:\n--\n--      JSON.decodeNumbersAsObjects = true\n--      \n--      T = JSON:decode('{  \"small\":12345, \"big\":12345678901234567890123456789, \"precise\":9876.67890123456789012345  }')\n--\n--      print(\"small:   \",  type(T.small),    T.small)\n--      print(\"big:     \",  type(T.big),      T.big)\n--      print(\"precise: \",  type(T.precise),  T.precise)\n--   \n--   This now produces:\n--   \n--      small:          table   12345\n--      big:            table   12345678901234567890123456789\n--      precise:        table   9876.67890123456789012345\n--   \n--   However, within Lua you can still use the values (e.g. T.precise in the example above) in numeric\n--   contexts. In such cases you'll get the possibly-imprecise numeric version, but in string contexts\n--   and when the data finds its way to this package's encode() function, the original full-precision\n--   representation is used.\n--\n--   You can force access to the string or numeric version via\n--        JSON:forceString()\n--        JSON:forceNumber()\n--   For example,\n--        local probably_okay = JSON:forceNumber(T.small) -- 'probably_okay' is a number\n--\n--   Code the inspects the JSON-turned-Lua data using type() can run into troubles because what used to\n--   be a number can now be a table (e.g. as the small/big/precise example above shows). Update these\n--   situations to use JSON:isNumber(item), which returns nil if the item is neither a number nor one\n--   of these number objects. If it is either, it returns the number itself. For completeness there's\n--   also JSON:isString(item).\n--\n--   If you want to try to avoid the hassles of this \"number as an object\" kludge for all but really\n--   big numbers, you can set JSON.decodeNumbersAsObjects and then also set one or both of\n--            JSON:decodeIntegerObjectificationLength\n--            JSON:decodeDecimalObjectificationLength\n--   They refer to the length of the part of the number before and after a decimal point. If they are\n--   set and their part is at least that number of digits, objectification occurs. If both are set,\n--   objectification occurs when either length is met.\n--\n--   -----------------------\n--\n--   Even without using the JSON.decodeNumbersAsObjects option, you can encode numbers in your Lua\n--   table that retain high precision upon encoding to JSON, by using the JSON:asNumber() function:\n--\n--      T = {\n--         imprecise =                123456789123456789.123456789123456789,\n--         precise   = JSON:asNumber(\"123456789123456789.123456789123456789\")\n--      }\n--\n--      print(JSON:encode_pretty(T))\n--\n--   This produces:\n--\n--      { \n--         \"precise\": 123456789123456789.123456789123456789,\n--         \"imprecise\": 1.2345678912346e+17\n--      }\n--\n--\n--   -----------------------\n--\n--   A different way to handle big/precise JSON numbers is to have decode() merely return the exact\n--   string representation of the number instead of the number itself. This approach might be useful\n--   when the numbers are merely some kind of opaque object identifier and you want to work with them\n--   in Lua as strings anyway.\n--   \n--   This approach is enabled by setting\n--\n--      JSON.decodeIntegerStringificationLength = 10\n--\n--   The value is the number of digits (of the integer part of the number) at which to stringify numbers.\n--   NOTE: this setting is ignored if JSON.decodeNumbersAsObjects is true, as that takes precedence.\n--\n--   Consider our previous example with this option set to 10:\n--\n--      JSON.decodeIntegerStringificationLength = 10\n--      \n--      T = JSON:decode('{  \"small\":12345, \"big\":12345678901234567890123456789, \"precise\":9876.67890123456789012345  }')\n--\n--      print(\"small:   \",  type(T.small),    T.small)\n--      print(\"big:     \",  type(T.big),      T.big)\n--      print(\"precise: \",  type(T.precise),  T.precise)\n--\n--   This produces:\n--\n--      small:          number  12345\n--      big:            string  12345678901234567890123456789\n--      precise:        number  9876.6789012346\n--\n--   The long integer of the 'big' field is at least JSON.decodeIntegerStringificationLength digits\n--   in length, so it's converted not to a Lua integer but to a Lua string. Using a value of 0 or 1 ensures\n--   that all JSON numeric data becomes strings in Lua.\n--\n--   Note that unlike\n--      JSON.decodeNumbersAsObjects = true\n--   this stringification is simple and unintelligent: the JSON number simply becomes a Lua string, and that's the end of it.\n--   If the string is then converted back to JSON, it's still a string. After running the code above, adding\n--      print(JSON:encode(T))\n--   produces\n--      {\"big\":\"12345678901234567890123456789\",\"precise\":9876.6789012346,\"small\":12345}\n--   which is unlikely to be desired.\n--\n--   There's a comparable option for the length of the decimal part of a number:\n--\n--      JSON.decodeDecimalStringificationLength\n--\n--   This can be used alone or in conjunction with\n--\n--      JSON.decodeIntegerStringificationLength\n--\n--   to trip stringification on precise numbers with at least JSON.decodeIntegerStringificationLength digits after\n--   the decimal point. (Both are ignored if JSON.decodeNumbersAsObjects is true.)\n--\n--   This example:\n--\n--      JSON.decodeIntegerStringificationLength = 10\n--      JSON.decodeDecimalStringificationLength =  5\n--\n--      T = JSON:decode('{  \"small\":12345, \"big\":12345678901234567890123456789, \"precise\":9876.67890123456789012345  }')\n--      \n--      print(\"small:   \",  type(T.small),    T.small)\n--      print(\"big:     \",  type(T.big),      T.big)\n--      print(\"precise: \",  type(T.precise),  T.precise)\n--\n--  produces:\n--\n--      small:          number  12345\n--      big:            string  12345678901234567890123456789\n--      precise:        string  9876.67890123456789012345\n--\n--\n--  HANDLING UNSUPPORTED VALUE TYPES\n--\n--   Among the encoding errors that might be raised is an attempt to convert a table value that has a type\n--   that this package hasn't accounted for: a function, userdata, or a thread. You can handle these types as table\n--   values (but not as table keys) if you supply a JSON:unsupportedTypeEncoder() method along the lines of the\n--   following example:\n--        \n--        function JSON:unsupportedTypeEncoder(value_of_unsupported_type)\n--           if type(value_of_unsupported_type) == 'function' then\n--              return \"a function value\"\n--           else\n--              return nil\n--           end\n--        end\n--        \n--   Your unsupportedTypeEncoder() method is actually called with a bunch of arguments:\n--\n--      self:unsupportedTypeEncoder(value, parents, etc, options, indent, for_key)\n--\n--   The 'value' is the function, thread, or userdata to be converted to JSON.\n--\n--   The 'etc' and 'options' arguments are those passed to the original encode(). The other arguments are\n--   probably of little interest; see the source code. (Note that 'for_key' is never true, as this function\n--   is invoked only on table values; table keys of these types still trigger the onEncodeError method.)\n--\n--   If your unsupportedTypeEncoder() method returns a string, it's inserted into the JSON as is.\n--   If it returns nil plus an error message, that error message is passed through to an onEncodeError invocation.\n--   If it returns only nil, processing falls through to a default onEncodeError invocation.\n--\n--   If you want to handle everything in a simple way:\n--\n--        function JSON:unsupportedTypeEncoder(value)\n--           return tostring(value)\n--        end\n--\n--\n-- SUMMARY OF METHODS YOU CAN OVERRIDE IN YOUR LOCAL LUA JSON OBJECT\n--\n--    assert\n--    onDecodeError\n--    onDecodeOfNilError\n--    onDecodeOfHTMLError\n--    onTrailingGarbage\n--    onEncodeError\n--    unsupportedTypeEncoder\n--\n--  If you want to create a separate Lua JSON object with its own error handlers,\n--  you can reload JSON.lua or use the :new() method.\n--\n---------------------------------------------------------------------------\n\nlocal default_pretty_indent  = \"  \"\nlocal default_pretty_options = { pretty = true, indent = default_pretty_indent, align_keys = false, array_newline = false }\n\nlocal isArray  = { __tostring = function() return \"JSON array\"         end }  isArray.__index  = isArray\nlocal isObject = { __tostring = function() return \"JSON object\"        end }  isObject.__index = isObject\n\nfunction OBJDEF:newArray(tbl)\n   return setmetatable(tbl or {}, isArray)\nend\n\nfunction OBJDEF:newObject(tbl)\n   return setmetatable(tbl or {}, isObject)\nend\n\n\n\n\nlocal function getnum(op)\n   return type(op) == 'number' and op or op.N\nend\n\nlocal isNumber = {\n   __tostring = function(T)  return T.S        end,\n   __unm      = function(op) return getnum(op) end,\n\n   __concat   = function(op1, op2) return tostring(op1) .. tostring(op2) end,\n   __add      = function(op1, op2) return getnum(op1)   +   getnum(op2)  end,\n   __sub      = function(op1, op2) return getnum(op1)   -   getnum(op2)  end,\n   __mul      = function(op1, op2) return getnum(op1)   *   getnum(op2)  end,\n   __div      = function(op1, op2) return getnum(op1)   /   getnum(op2)  end,\n   __mod      = function(op1, op2) return getnum(op1)   %   getnum(op2)  end,\n   __pow      = function(op1, op2) return getnum(op1)   ^   getnum(op2)  end,\n   __lt       = function(op1, op2) return getnum(op1)   <   getnum(op2)  end,\n   __eq       = function(op1, op2) return getnum(op1)   ==  getnum(op2)  end,\n   __le       = function(op1, op2) return getnum(op1)   <=  getnum(op2)  end,\n}\nisNumber.__index = isNumber\n\nfunction OBJDEF:asNumber(item)\n\n   if getmetatable(item) == isNumber then\n      -- it's already a JSON number object.\n      return item\n   elseif type(item) == 'table' and type(item.S) == 'string' and type(item.N) == 'number' then\n      -- it's a number-object table that lost its metatable, so give it one\n      return setmetatable(item, isNumber)\n   else\n      -- the normal situation... given a number or a string representation of a number....\n      local holder = {\n         S = tostring(item), -- S is the representation of the number as a string, which remains precise\n         N = tonumber(item), -- N is the number as a Lua number.\n      }\n      return setmetatable(holder, isNumber)\n   end\nend\n\n--\n-- Given an item that might be a normal string or number, or might be an 'isNumber' object defined above,\n-- return the string version. This shouldn't be needed often because the 'isNumber' object should autoconvert\n-- to a string in most cases, but it's here to allow it to be forced when needed.\n--\nfunction OBJDEF:forceString(item)\n   if type(item) == 'table' and type(item.S) == 'string' then\n      return item.S\n   else\n      return tostring(item)\n   end\nend\n\n--\n-- Given an item that might be a normal string or number, or might be an 'isNumber' object defined above,\n-- return the numeric version.\n--\nfunction OBJDEF:forceNumber(item)\n   if type(item) == 'table' and type(item.N) == 'number' then\n      return item.N\n   else\n      return tonumber(item)\n   end\nend\n\n--\n-- If the given item is a number, return it. Otherwise, return nil.\n-- This, this can be used both in a conditional and to access the number when you're not sure its form.\n--\nfunction OBJDEF:isNumber(item)\n   if type(item) == 'number' then\n      return item\n   elseif type(item) == 'table' and type(item.N) == 'number' then\n      return item.N\n   else\n      return nil\n   end\nend\n\nfunction OBJDEF:isString(item)\n   if type(item) == 'string' then\n      return item\n   elseif type(item) == 'table' and type(item.S) == 'string' then\n      return item.S\n   else\n      return nil\n   end\nend\n\n\nlocal function unicode_codepoint_as_utf8(codepoint)\n   --\n   -- codepoint is a number\n   --\n   if codepoint <= 127 then\n      return string.char(codepoint)\n\n   elseif codepoint <= 2047 then\n      --\n      -- 110yyyxx 10xxxxxx         <-- useful notation from http://en.wikipedia.org/wiki/Utf8\n      --\n      local highpart = math.floor(codepoint / 0x40)\n      local lowpart  = codepoint - (0x40 * highpart)\n      return string.char(0xC0 + highpart,\n                         0x80 + lowpart)\n\n   elseif codepoint <= 65535 then\n      --\n      -- 1110yyyy 10yyyyxx 10xxxxxx\n      --\n      local highpart  = math.floor(codepoint / 0x1000)\n      local remainder = codepoint - 0x1000 * highpart\n      local midpart   = math.floor(remainder / 0x40)\n      local lowpart   = remainder - 0x40 * midpart\n\n      highpart = 0xE0 + highpart\n      midpart  = 0x80 + midpart\n      lowpart  = 0x80 + lowpart\n\n      --\n      -- Check for an invalid character (thanks Andy R. at Adobe).\n      -- See table 3.7, page 93, in http://www.unicode.org/versions/Unicode5.2.0/ch03.pdf#G28070\n      --\n      if ( highpart == 0xE0 and midpart < 0xA0 ) or\n         ( highpart == 0xED and midpart > 0x9F ) or\n         ( highpart == 0xF0 and midpart < 0x90 ) or\n         ( highpart == 0xF4 and midpart > 0x8F )\n      then\n         return \"?\"\n      else\n         return string.char(highpart,\n                            midpart,\n                            lowpart)\n      end\n\n   else\n      --\n      -- 11110zzz 10zzyyyy 10yyyyxx 10xxxxxx\n      --\n      local highpart  = math.floor(codepoint / 0x40000)\n      local remainder = codepoint - 0x40000 * highpart\n      local midA      = math.floor(remainder / 0x1000)\n      remainder       = remainder - 0x1000 * midA\n      local midB      = math.floor(remainder / 0x40)\n      local lowpart   = remainder - 0x40 * midB\n\n      return string.char(0xF0 + highpart,\n                         0x80 + midA,\n                         0x80 + midB,\n                         0x80 + lowpart)\n   end\nend\n\nfunction OBJDEF:onDecodeError(message, text, location, etc)\n   if text then\n      if location then\n         message = string.format(\"%s at byte %d of: %s\", message, location, text)\n      else\n         message = string.format(\"%s: %s\", message, text)\n      end\n   end\n\n   if etc ~= nil then\n      message = message .. \" (\" .. OBJDEF:encode(etc) .. \")\"\n   end\n\n   if self.assert then\n      self.assert(false, message)\n   else\n      assert(false, message)\n   end\nend\n\nfunction OBJDEF:onTrailingGarbage(json_text, location, parsed_value, etc)\n   return self:onDecodeError(\"trailing garbage\", json_text, location, etc)\nend\n\nOBJDEF.onDecodeOfNilError  = OBJDEF.onDecodeError\nOBJDEF.onDecodeOfHTMLError = OBJDEF.onDecodeError\n\nfunction OBJDEF:onEncodeError(message, etc)\n   if etc ~= nil then\n      message = message .. \" (\" .. OBJDEF:encode(etc) .. \")\"\n   end\n\n   if self.assert then\n      self.assert(false, message)\n   else\n      assert(false, message)\n   end\nend\n\nlocal function grok_number(self, text, start, options)\n   --\n   -- Grab the integer part\n   --\n   local integer_part = text:match('^-?[1-9]%d*', start)\n                     or text:match(\"^-?0\",        start)\n\n   if not integer_part then\n      self:onDecodeError(\"expected number\", text, start, options.etc)\n      return nil, start -- in case the error method doesn't abort, return something sensible\n   end\n\n   local i = start + integer_part:len()\n\n   --\n   -- Grab an optional decimal part\n   --\n   local decimal_part = text:match('^%.%d+', i) or \"\"\n\n   i = i + decimal_part:len()\n\n   --\n   -- Grab an optional exponential part\n   --\n   local exponent_part = text:match('^[eE][-+]?%d+', i) or \"\"\n\n   i = i + exponent_part:len()\n\n   local full_number_text = integer_part .. decimal_part .. exponent_part\n\n   if options.decodeNumbersAsObjects then\n\n      local objectify = false\n\n      if not options.decodeIntegerObjectificationLength and not options.decodeDecimalObjectificationLength then\n         -- no options, so objectify\n         objectify = true\n\n      elseif (options.decodeIntegerObjectificationLength\n          and\n         (integer_part:len() >= options.decodeIntegerObjectificationLength or exponent_part:len() > 0))\n\n          or\n         (options.decodeDecimalObjectificationLength \n          and\n          (decimal_part:len() >= options.decodeDecimalObjectificationLength  or exponent_part:len() > 0))\n      then\n         -- have options and they are triggered, so objectify\n         objectify = true\n      end\n\n      if objectify then\n         return OBJDEF:asNumber(full_number_text), i\n      end\n      -- else, fall through to try to return as a straight-up number\n\n   else\n\n      -- Not always decoding numbers as objects, so perhaps encode as strings?\n\n      --\n      -- If we're told to stringify only under certain conditions, so do.\n      -- We punt a bit when there's an exponent by just stringifying no matter what.\n      -- I suppose we should really look to see whether the exponent is actually big enough one\n      -- way or the other to trip stringification, but I'll be lazy about it until someone asks.\n      --\n      if (options.decodeIntegerStringificationLength\n          and\n         (integer_part:len() >= options.decodeIntegerStringificationLength or exponent_part:len() > 0))\n\n          or\n\n         (options.decodeDecimalStringificationLength \n          and\n          (decimal_part:len() >= options.decodeDecimalStringificationLength or exponent_part:len() > 0))\n      then\n         return full_number_text, i -- this returns the exact string representation seen in the original JSON\n      end\n\n   end\n\n\n   local as_number = tonumber(full_number_text)\n\n   if not as_number then\n      self:onDecodeError(\"bad number\", text, start, options.etc)\n      return nil, start -- in case the error method doesn't abort, return something sensible\n   end\n\n   return as_number, i\nend\n\n\nlocal function grok_string(self, text, start, options)\n\n   if text:sub(start,start) ~= '\"' then\n      self:onDecodeError(\"expected string's opening quote\", text, start, options.etc)\n      return nil, start -- in case the error method doesn't abort, return something sensible\n   end\n\n   local i = start + 1 -- +1 to bypass the initial quote\n   local text_len = text:len()\n   local VALUE = \"\"\n   while i <= text_len do\n      local c = text:sub(i,i)\n      if c == '\"' then\n         return VALUE, i + 1\n      end\n      if c ~= '\\\\' then\n         VALUE = VALUE .. c\n         i = i + 1\n      elseif text:match('^\\\\b', i) then\n         VALUE = VALUE .. \"\\b\"\n         i = i + 2\n      elseif text:match('^\\\\f', i) then\n         VALUE = VALUE .. \"\\f\"\n         i = i + 2\n      elseif text:match('^\\\\n', i) then\n         VALUE = VALUE .. \"\\n\"\n         i = i + 2\n      elseif text:match('^\\\\r', i) then\n         VALUE = VALUE .. \"\\r\"\n         i = i + 2\n      elseif text:match('^\\\\t', i) then\n         VALUE = VALUE .. \"\\t\"\n         i = i + 2\n      else\n         local hex = text:match('^\\\\u([0123456789aAbBcCdDeEfF][0123456789aAbBcCdDeEfF][0123456789aAbBcCdDeEfF][0123456789aAbBcCdDeEfF])', i)\n         if hex then\n            i = i + 6 -- bypass what we just read\n\n            -- We have a Unicode codepoint. It could be standalone, or if in the proper range and\n            -- followed by another in a specific range, it'll be a two-code surrogate pair.\n            local codepoint = tonumber(hex, 16)\n            if codepoint >= 0xD800 and codepoint <= 0xDBFF then\n               -- it's a hi surrogate... see whether we have a following low\n               local lo_surrogate = text:match('^\\\\u([dD][cdefCDEF][0123456789aAbBcCdDeEfF][0123456789aAbBcCdDeEfF])', i)\n               if lo_surrogate then\n                  i = i + 6 -- bypass the low surrogate we just read\n                  codepoint = 0x2400 + (codepoint - 0xD800) * 0x400 + tonumber(lo_surrogate, 16)\n               else\n                  -- not a proper low, so we'll just leave the first codepoint as is and spit it out.\n               end\n            end\n            VALUE = VALUE .. unicode_codepoint_as_utf8(codepoint)\n\n         else\n\n            -- just pass through what's escaped\n            VALUE = VALUE .. text:match('^\\\\(.)', i)\n            i = i + 2\n         end\n      end\n   end\n\n   self:onDecodeError(\"unclosed string\", text, start, options.etc)\n   return nil, start -- in case the error method doesn't abort, return something sensible\nend\n\nlocal function skip_whitespace(text, start)\n\n   local _, match_end = text:find(\"^[ \\n\\r\\t]+\", start) -- [http://www.ietf.org/rfc/rfc4627.txt] Section 2\n   if match_end then\n      return match_end + 1\n   else\n      return start\n   end\nend\n\nlocal grok_one -- assigned later\n\nlocal function grok_object(self, text, start, options)\n\n   if text:sub(start,start) ~= '{' then\n      self:onDecodeError(\"expected '{'\", text, start, options.etc)\n      return nil, start -- in case the error method doesn't abort, return something sensible\n   end\n\n   local i = skip_whitespace(text, start + 1) -- +1 to skip the '{'\n\n   local VALUE = self.strictTypes and self:newObject { } or { }\n\n   if text:sub(i,i) == '}' then\n      return VALUE, i + 1\n   end\n   local text_len = text:len()\n   while i <= text_len do\n      local key, new_i = grok_string(self, text, i, options)\n\n      i = skip_whitespace(text, new_i)\n\n      if text:sub(i, i) ~= ':' then\n         self:onDecodeError(\"expected colon\", text, i, options.etc)\n         return nil, i -- in case the error method doesn't abort, return something sensible\n      end\n\n      i = skip_whitespace(text, i + 1)\n\n      local new_val, new_i = grok_one(self, text, i, options)\n\n      VALUE[key] = new_val\n\n      --\n      -- Expect now either '}' to end things, or a ',' to allow us to continue.\n      --\n      i = skip_whitespace(text, new_i)\n\n      local c = text:sub(i,i)\n\n      if c == '}' then\n         return VALUE, i + 1\n      end\n\n      if text:sub(i, i) ~= ',' then\n         self:onDecodeError(\"expected comma or '}'\", text, i, options.etc)\n         return nil, i -- in case the error method doesn't abort, return something sensible\n      end\n\n      i = skip_whitespace(text, i + 1)\n   end\n\n   self:onDecodeError(\"unclosed '{'\", text, start, options.etc)\n   return nil, start -- in case the error method doesn't abort, return something sensible\nend\n\nlocal function grok_array(self, text, start, options)\n   if text:sub(start,start) ~= '[' then\n      self:onDecodeError(\"expected '['\", text, start, options.etc)\n      return nil, start -- in case the error method doesn't abort, return something sensible\n   end\n\n   local i = skip_whitespace(text, start + 1) -- +1 to skip the '['\n   local VALUE = self.strictTypes and self:newArray { } or { }\n   if text:sub(i,i) == ']' then\n      return VALUE, i + 1\n   end\n\n   local VALUE_INDEX = 1\n\n   local text_len = text:len()\n   while i <= text_len do\n      local val, new_i = grok_one(self, text, i, options)\n\n      -- can't table.insert(VALUE, val) here because it's a no-op if val is nil\n      VALUE[VALUE_INDEX] = val\n      VALUE_INDEX = VALUE_INDEX + 1\n\n      i = skip_whitespace(text, new_i)\n\n      --\n      -- Expect now either ']' to end things, or a ',' to allow us to continue.\n      --\n      local c = text:sub(i,i)\n      if c == ']' then\n         return VALUE, i + 1\n      end\n      if text:sub(i, i) ~= ',' then\n         self:onDecodeError(\"expected comma or ']'\", text, i, options.etc)\n         return nil, i -- in case the error method doesn't abort, return something sensible\n      end\n      i = skip_whitespace(text, i + 1)\n   end\n   self:onDecodeError(\"unclosed '['\", text, start, options.etc)\n   return nil, i -- in case the error method doesn't abort, return something sensible\nend\n\n\ngrok_one = function(self, text, start, options)\n   -- Skip any whitespace\n   start = skip_whitespace(text, start)\n\n   if start > text:len() then\n      self:onDecodeError(\"unexpected end of string\", text, nil, options.etc)\n      return nil, start -- in case the error method doesn't abort, return something sensible\n   end\n\n   if text:find('^\"', start) then\n      return grok_string(self, text, start, options.etc)\n\n   elseif text:find('^[-0123456789 ]', start) then\n      return grok_number(self, text, start, options)\n\n   elseif text:find('^%{', start) then\n      return grok_object(self, text, start, options)\n\n   elseif text:find('^%[', start) then\n      return grok_array(self, text, start, options)\n\n   elseif text:find('^true', start) then\n      return true, start + 4\n\n   elseif text:find('^false', start) then\n      return false, start + 5\n\n   elseif text:find('^null', start) then\n      return options.null, start + 4\n\n   else\n      self:onDecodeError(\"can't parse JSON\", text, start, options.etc)\n      return nil, 1 -- in case the error method doesn't abort, return something sensible\n   end\nend\n\nfunction OBJDEF:decode(text, etc, options)\n   --\n   -- If the user didn't pass in a table of decode options, make an empty one.\n   --\n   if type(options) ~= 'table' then\n      options = {}\n   end\n\n   --\n   -- If they passed in an 'etc' argument, stuff it into the options.\n   -- (If not, any 'etc' field in the options they passed in remains to be used)\n   --\n   if etc ~= nil then\n      options.etc = etc\n   end\n\n\n   if type(self) ~= 'table' or self.__index ~= OBJDEF then\n      local error_message = \"JSON:decode must be called in method format\"\n      OBJDEF:onDecodeError(error_message, nil, nil, options.etc)\n      return nil, error_message -- in case the error method doesn't abort, return something sensible\n   end\n\n   if text == nil then\n      local error_message = \"nil passed to JSON:decode()\"\n      self:onDecodeOfNilError(error_message, nil, nil, options.etc)\n      return nil, error_message -- in case the error method doesn't abort, return something sensible\n\n   elseif type(text) ~= 'string' then\n      local error_message = \"expected string argument to JSON:decode()\"\n      self:onDecodeError(string.format(\"%s, got %s\", error_message, type(text)), nil, nil, options.etc)\n      return nil, error_message -- in case the error method doesn't abort, return something sensible\n   end\n\n   if text:match('^%s*$') then\n      -- an empty string is nothing, but not an error\n      return nil\n   end\n\n   if text:match('^%s*<') then\n      -- Can't be JSON... we'll assume it's HTML\n      local error_message = \"HTML passed to JSON:decode()\"\n      self:onDecodeOfHTMLError(error_message, text, nil, options.etc)\n      return nil, error_message -- in case the error method doesn't abort, return something sensible\n   end\n\n   --\n   -- Ensure that it's not UTF-32 or UTF-16.\n   -- Those are perfectly valid encodings for JSON (as per RFC 4627 section 3),\n   -- but this package can't handle them.\n   --\n   if text:sub(1,1):byte() == 0 or (text:len() >= 2 and text:sub(2,2):byte() == 0) then\n      local error_message = \"JSON package groks only UTF-8, sorry\"\n      self:onDecodeError(error_message, text, nil, options.etc)\n      return nil, error_message -- in case the error method doesn't abort, return something sensible\n   end\n\n   --\n   -- apply global options\n   --\n   if options.decodeNumbersAsObjects == nil then\n      options.decodeNumbersAsObjects = self.decodeNumbersAsObjects\n   end\n   if options.decodeIntegerObjectificationLength == nil then\n      options.decodeIntegerObjectificationLength = self.decodeIntegerObjectificationLength\n   end\n   if options.decodeDecimalObjectificationLength == nil then\n      options.decodeDecimalObjectificationLength = self.decodeDecimalObjectificationLength\n   end\n   if options.decodeIntegerStringificationLength == nil then\n      options.decodeIntegerStringificationLength = self.decodeIntegerStringificationLength\n   end\n   if options.decodeDecimalStringificationLength == nil then\n      options.decodeDecimalStringificationLength = self.decodeDecimalStringificationLength\n   end\n\n\n   --\n   -- Finally, go parse it\n   --\n   local success, value, next_i = pcall(grok_one, self, text, 1, options)\n\n   if success then\n\n      local error_message = nil\n      if next_i ~= #text + 1 then\n         -- something's left over after we parsed the first thing.... whitespace is allowed.\n         next_i = skip_whitespace(text, next_i)\n\n         -- if we have something left over now, it's trailing garbage\n         if next_i ~= #text + 1 then\n            value, error_message = self:onTrailingGarbage(text, next_i, value, options.etc)\n         end\n      end\n      return value, error_message\n\n   else\n\n      -- If JSON:onDecodeError() didn't abort out of the pcall, we'll have received\n      -- the error message here as \"value\", so pass it along as an assert.\n      local error_message = value\n      if self.assert then\n         self.assert(false, error_message)\n      else\n         assert(false, error_message)\n      end\n      -- ...and if we're still here (because the assert didn't throw an error),\n      -- return a nil and throw the error message on as a second arg\n      return nil, error_message\n\n   end\nend\n\nlocal function backslash_replacement_function(c)\n   if c == \"\\n\" then\n      return \"\\\\n\"\n   elseif c == \"\\r\" then\n      return \"\\\\r\"\n   elseif c == \"\\t\" then\n      return \"\\\\t\"\n   elseif c == \"\\b\" then\n      return \"\\\\b\"\n   elseif c == \"\\f\" then\n      return \"\\\\f\"\n   elseif c == '\"' then\n      return '\\\\\"'\n   elseif c == '\\\\' then\n      return '\\\\\\\\'\n   else\n      return string.format(\"\\\\u%04x\", c:byte())\n   end\nend\n\nlocal chars_to_be_escaped_in_JSON_string\n   = '['\n   ..    '\"'    -- class sub-pattern to match a double quote\n   ..    '%\\\\'  -- class sub-pattern to match a backslash\n   ..    '%z'   -- class sub-pattern to match a null\n   ..    '\\001' .. '-' .. '\\031' -- class sub-pattern to match control characters\n   .. ']'\n\n\nlocal LINE_SEPARATOR_as_utf8      = unicode_codepoint_as_utf8(0x2028)\nlocal PARAGRAPH_SEPARATOR_as_utf8 = unicode_codepoint_as_utf8(0x2029)\nlocal function json_string_literal(value, options)\n   local newval = value:gsub(chars_to_be_escaped_in_JSON_string, backslash_replacement_function)\n   if options.stringsAreUtf8 then\n      --\n      -- This feels really ugly to just look into a string for the sequence of bytes that we know to be a particular utf8 character,\n      -- but utf8 was designed purposefully to make this kind of thing possible. Still, feels dirty.\n      -- I'd rather decode the byte stream into a character stream, but it's not technically needed so\n      -- not technically worth it.\n      --\n      newval = newval:gsub(LINE_SEPARATOR_as_utf8, '\\\\u2028'):gsub(PARAGRAPH_SEPARATOR_as_utf8,'\\\\u2029')\n   end\n   return '\"' .. newval .. '\"'\nend\n\nlocal function object_or_array(self, T, etc)\n   --\n   -- We need to inspect all the keys... if there are any strings, we'll convert to a JSON\n   -- object. If there are only numbers, it's a JSON array.\n   --\n   -- If we'll be converting to a JSON object, we'll want to sort the keys so that the\n   -- end result is deterministic.\n   --\n   local string_keys = { }\n   local number_keys = { }\n   local number_keys_must_be_strings = false\n   local maximum_number_key\n\n   for key in pairs(T) do\n      if type(key) == 'string' then\n         table.insert(string_keys, key)\n      elseif type(key) == 'number' then\n         table.insert(number_keys, key)\n         if key <= 0 or key >= math.huge then\n            number_keys_must_be_strings = true\n         elseif not maximum_number_key or key > maximum_number_key then\n            maximum_number_key = key\n         end\n      elseif type(key) == 'boolean' then\n         table.insert(string_keys, tostring(key))\n      else\n         self:onEncodeError(\"can't encode table with a key of type \" .. type(key), etc)\n      end\n   end\n\n   if #string_keys == 0 and not number_keys_must_be_strings then\n      --\n      -- An empty table, or a numeric-only array\n      --\n      if #number_keys > 0 then\n         return nil, maximum_number_key -- an array\n      elseif tostring(T) == \"JSON array\" then\n         return nil\n      elseif tostring(T) == \"JSON object\" then\n         return { }\n      else\n         -- have to guess, so we'll pick array, since empty arrays are likely more common than empty objects\n         return nil\n      end\n   end\n\n   table.sort(string_keys)\n\n   local map\n   if #number_keys > 0 then\n      --\n      -- If we're here then we have either mixed string/number keys, or numbers inappropriate for a JSON array\n      -- It's not ideal, but we'll turn the numbers into strings so that we can at least create a JSON object.\n      --\n\n      if self.noKeyConversion then\n         self:onEncodeError(\"a table with both numeric and string keys could be an object or array; aborting\", etc)\n      end\n\n      --\n      -- Have to make a shallow copy of the source table so we can remap the numeric keys to be strings\n      --\n      map = { }\n      for key, val in pairs(T) do\n         map[key] = val\n      end\n\n      table.sort(number_keys)\n\n      --\n      -- Throw numeric keys in there as strings\n      --\n      for _, number_key in ipairs(number_keys) do\n         local string_key = tostring(number_key)\n         if map[string_key] == nil then\n            table.insert(string_keys , string_key)\n            map[string_key] = T[number_key]\n         else\n            self:onEncodeError(\"conflict converting table with mixed-type keys into a JSON object: key \" .. number_key .. \" exists both as a string and a number.\", etc)\n         end\n      end\n   end\n\n   return string_keys, nil, map\nend\n\n--\n-- Encode\n--\n-- 'options' is nil, or a table with possible keys:\n--\n--    pretty         -- If true, return a pretty-printed version.\n--\n--    indent         -- A string (usually of spaces) used to indent each nested level.\n--\n--    align_keys     -- If true, align all the keys when formatting a table. The result is uglier than one might at first imagine.\n--                      Results are undefined if 'align_keys' is true but 'pretty' is not.\n--\n--    array_newline  -- If true, array elements are formatted each to their own line. The default is to all fall inline.\n--                      Results are undefined if 'array_newline' is true but 'pretty' is not.\n--\n--    null           -- If this exists with a string value, table elements with this value are output as JSON null.\n--\n--    stringsAreUtf8 -- If true, consider Lua strings not as a sequence of bytes, but as a sequence of UTF-8 characters.\n--                      (Currently, the only practical effect of setting this option is that Unicode LINE and PARAGRAPH\n--                       separators, if found in a string, are encoded with a JSON escape instead of as raw UTF-8.\n--                       The JSON is valid either way, but encoding this way, apparently, allows the resulting JSON\n--                       to also be valid Java.)\n--\n--\nlocal function encode_value(self, value, parents, etc, options, indent, for_key)\n\n   --\n   -- keys in a JSON object can never be null, so we don't even consider options.null when converting a key value\n   --\n   if value == nil or (not for_key and options and options.null and value == options.null) then\n      return 'null'\n\n   elseif type(value) == 'string' then\n      return json_string_literal(value, options)\n\n   elseif type(value) == 'number' then\n      if value ~= value then\n         --\n         -- NaN (Not a Number).\n         -- JSON has no NaN, so we have to fudge the best we can. This should really be a package option.\n         --\n         return \"null\"\n      elseif value >= math.huge then\n         --\n         -- Positive infinity. JSON has no INF, so we have to fudge the best we can. This should\n         -- really be a package option. Note: at least with some implementations, positive infinity\n         -- is both \">= math.huge\" and \"<= -math.huge\", which makes no sense but that's how it is.\n         -- Negative infinity is properly \"<= -math.huge\". So, we must be sure to check the \">=\"\n         -- case first.\n         --\n         return \"1e+9999\"\n      elseif value <= -math.huge then\n         --\n         -- Negative infinity.\n         -- JSON has no INF, so we have to fudge the best we can. This should really be a package option.\n         --\n         return \"-1e+9999\"\n      else\n         return tostring(value)\n      end\n\n   elseif type(value) == 'boolean' then\n      return tostring(value)\n\n   elseif type(value) ~= 'table' then\n\n      if self.unsupportedTypeEncoder then\n         local user_value, user_error = self:unsupportedTypeEncoder(value, parents, etc, options, indent, for_key)\n         -- If the user's handler returns a string, use that. If it returns nil plus an error message, bail with that.\n         -- If only nil returned, fall through to the default error handler.\n         if type(user_value) == 'string' then\n            return user_value\n         elseif user_value ~= nil then\n            self:onEncodeError(\"unsupportedTypeEncoder method returned a \" .. type(user_value), etc)\n         elseif user_error then\n            self:onEncodeError(tostring(user_error), etc)\n         end\n      end\n\n      self:onEncodeError(\"can't convert \" .. type(value) .. \" to JSON\", etc)\n\n   elseif getmetatable(value) == isNumber then\n      return tostring(value)\n   else\n      --\n      -- A table to be converted to either a JSON object or array.\n      --\n      local T = value\n\n      if type(options) ~= 'table' then\n         options = {}\n      end\n      if type(indent) ~= 'string' then\n         indent = \"\"\n      end\n\n      if parents[T] then\n         self:onEncodeError(\"table \" .. tostring(T) .. \" is a child of itself\", etc)\n      else\n         parents[T] = true\n      end\n\n      local result_value\n\n      local object_keys, maximum_number_key, map = object_or_array(self, T, etc)\n      if maximum_number_key then\n         --\n         -- An array...\n         --\n         local key_indent\n         if options.array_newline then\n            key_indent = indent .. tostring(options.indent or \"\")\n         else\n            key_indent = indent\n         end\n\n         local ITEMS = { }\n         for i = 1, maximum_number_key do\n            table.insert(ITEMS, encode_value(self, T[i], parents, etc, options, key_indent))\n         end\n\n         if options.array_newline then\n            result_value = \"[\\n\" .. key_indent .. table.concat(ITEMS, \",\\n\" .. key_indent) .. \"\\n\" .. indent .. \"]\"\n         elseif options.pretty then\n            result_value = \"[ \" .. table.concat(ITEMS, \", \") .. \" ]\"\n         else\n            result_value = \"[\"  .. table.concat(ITEMS, \",\")  .. \"]\"\n         end\n\n      elseif object_keys then\n         --\n         -- An object\n         --\n         local TT = map or T\n\n         if options.pretty then\n\n            local KEYS = { }\n            local max_key_length = 0\n            for _, key in ipairs(object_keys) do\n               local encoded = encode_value(self, tostring(key), parents, etc, options, indent, true)\n               if options.align_keys then\n                  max_key_length = math.max(max_key_length, #encoded)\n               end\n               table.insert(KEYS, encoded)\n            end\n            local key_indent = indent .. tostring(options.indent or \"\")\n            local subtable_indent = key_indent .. string.rep(\" \", max_key_length) .. (options.align_keys and \"  \" or \"\")\n            local FORMAT = \"%s%\" .. string.format(\"%d\", max_key_length) .. \"s: %s\"\n\n            local COMBINED_PARTS = { }\n            for i, key in ipairs(object_keys) do\n               local encoded_val = encode_value(self, TT[key], parents, etc, options, subtable_indent)\n               table.insert(COMBINED_PARTS, string.format(FORMAT, key_indent, KEYS[i], encoded_val))\n            end\n            result_value = \"{\\n\" .. table.concat(COMBINED_PARTS, \",\\n\") .. \"\\n\" .. indent .. \"}\"\n\n         else\n\n            local PARTS = { }\n            for _, key in ipairs(object_keys) do\n               local encoded_val = encode_value(self, TT[key],       parents, etc, options, indent)\n               local encoded_key = encode_value(self, tostring(key), parents, etc, options, indent, true)\n               table.insert(PARTS, string.format(\"%s:%s\", encoded_key, encoded_val))\n            end\n            result_value = \"{\" .. table.concat(PARTS, \",\") .. \"}\"\n\n         end\n      else\n         --\n         -- An empty array/object... we'll treat it as an array, though it should really be an option\n         --\n         result_value = \"[]\"\n      end\n\n      parents[T] = false\n      return result_value\n   end\nend\n\nlocal function top_level_encode(self, value, etc, options)\n   local val = encode_value(self, value, {}, etc, options)\n   if val == nil then\n      --PRIVATE(\"may need to revert to the previous public verison if I can't figure out what the guy wanted\")\n      return val\n   else\n      return val\n   end\nend\n\nfunction OBJDEF:encode(value, etc, options)\n   if type(self) ~= 'table' or self.__index ~= OBJDEF then\n      OBJDEF:onEncodeError(\"JSON:encode must be called in method format\", etc)\n   end\n\n   --\n   -- If the user didn't pass in a table of decode options, make an empty one.\n   --\n   if type(options) ~= 'table' then\n      options = {}\n   end\n\n   return top_level_encode(self, value, etc, options)\nend\n\nfunction OBJDEF:encode_pretty(value, etc, options)\n   if type(self) ~= 'table' or self.__index ~= OBJDEF then\n      OBJDEF:onEncodeError(\"JSON:encode_pretty must be called in method format\", etc)\n   end\n\n   --\n   -- If the user didn't pass in a table of decode options, use the default pretty ones\n   --\n   if type(options) ~= 'table' then\n      options = default_pretty_options\n   end\n\n   return top_level_encode(self, value, etc, options)\nend\n\nfunction OBJDEF.__tostring()\n   return \"JSON encode/decode package\"\nend\n\nOBJDEF.__index = OBJDEF\n\nfunction OBJDEF:new(args)\n   local new = { }\n\n   if args then\n      for key, val in pairs(args) do\n         new[key] = val\n      end\n   end\n\n   return setmetatable(new, OBJDEF)\nend\n\nJSON = OBJDEF:new() -- Noita expects to just dofile everything :(\n--return OBJDEF:new()\n\n--\n-- Version history:\n--\n--   20170927.26   Use option.null in decoding as well. Thanks to Max Sindwani for the bump, and sorry to Oliver Hitz\n--                 whose first mention of it four years ago was completely missed by me.\n--\n--   20170823.25   Added support for JSON:unsupportedTypeEncoder().\n--                 Thanks to Chronos Phaenon Eosphoros (https://github.com/cpeosphoros) for the idea.\n--\n--   20170819.24   Added support for boolean keys in tables.\n--\n--   20170416.23   Added the \"array_newline\" formatting option suggested by yurenchen (http://www.yurenchen.com/)\n--\n--   20161128.22   Added:\n--                   JSON:isString()\n--                   JSON:isNumber()\n--                   JSON:decodeIntegerObjectificationLength\n--                   JSON:decodeDecimalObjectificationLength\n--\n--   20161109.21   Oops, had a small boo-boo in the previous update.\n--\n--   20161103.20   Used to silently ignore trailing garbage when decoding. Now fails via JSON:onTrailingGarbage()\n--                 http://seriot.ch/parsing_json.php\n--\n--                 Built-in error message about \"expected comma or ']'\" had mistakenly referred to '['\n--\n--                 Updated the built-in error reporting to refer to bytes rather than characters.\n--\n--                 The decode() method no longer assumes that error handlers abort.\n--\n--                 Made the VERSION string a string instead of a number\n--\n\n--   20160916.19   Fixed the isNumber.__index assignment (thanks to Jack Taylor)\n--   \n--   20160730.18   Added JSON:forceString() and JSON:forceNumber()\n--\n--   20160728.17   Added concatenation to the metatable for JSON:asNumber()\n--\n--   20160709.16   Could crash if not passed an options table (thanks jarno heikkinen <jarnoh@capturemonkey.com>).\n--\n--                 Made JSON:asNumber() a bit more resilient to being passed the results of itself.\n--\n--   20160526.15   Added the ability to easily encode null values in JSON, via the new \"null\" encoding option.\n--                 (Thanks to Adam B for bringing up the issue.)\n--\n--                 Added some support for very large numbers and precise floats via\n--                    JSON.decodeNumbersAsObjects\n--                    JSON.decodeIntegerStringificationLength\n--                    JSON.decodeDecimalStringificationLength\n--\n--                 Added the \"stringsAreUtf8\" encoding option. (Hat tip to http://lua-users.org/wiki/JsonModules )\n--\n--   20141223.14   The encode_pretty() routine produced fine results for small datasets, but isn't really\n--                 appropriate for anything large, so with help from Alex Aulbach I've made the encode routines\n--                 more flexible, and changed the default encode_pretty() to be more generally useful.\n--\n--                 Added a third 'options' argument to the encode() and encode_pretty() routines, to control\n--                 how the encoding takes place.\n--\n--                 Updated docs to add assert() call to the loadfile() line, just as good practice so that\n--                 if there is a problem loading JSON.lua, the appropriate error message will percolate up.\n--\n--   20140920.13   Put back (in a way that doesn't cause warnings about unused variables) the author string,\n--                 so that the source of the package, and its version number, are visible in compiled copies.\n--\n--   20140911.12   Minor lua cleanup.\n--                 Fixed internal reference to 'JSON.noKeyConversion' to reference 'self' instead of 'JSON'.\n--                 (Thanks to SmugMug's David Parry for these.)\n--\n--   20140418.11   JSON nulls embedded within an array were being ignored, such that\n--                     [\"1\",null,null,null,null,null,\"seven\"],\n--                 would return\n--                     {1,\"seven\"}\n--                 It's now fixed to properly return\n--                     {1, nil, nil, nil, nil, nil, \"seven\"}\n--                 Thanks to \"haddock\" for catching the error.\n--\n--   20140116.10   The user's JSON.assert() wasn't always being used. Thanks to \"blue\" for the heads up.\n--\n--   20131118.9    Update for Lua 5.3... it seems that tostring(2/1) produces \"2.0\" instead of \"2\",\n--                 and this caused some problems.\n--\n--   20131031.8    Unified the code for encode() and encode_pretty(); they had been stupidly separate,\n--                 and had of course diverged (encode_pretty didn't get the fixes that encode got, so\n--                 sometimes produced incorrect results; thanks to Mattie for the heads up).\n--\n--                 Handle encoding tables with non-positive numeric keys (unlikely, but possible).\n--\n--                 If a table has both numeric and string keys, or its numeric keys are inappropriate\n--                 (such as being non-positive or infinite), the numeric keys are turned into\n--                 string keys appropriate for a JSON object. So, as before,\n--                         JSON:encode({ \"one\", \"two\", \"three\" })\n--                 produces the array\n--                         [\"one\",\"two\",\"three\"]\n--                 but now something with mixed key types like\n--                         JSON:encode({ \"one\", \"two\", \"three\", SOMESTRING = \"some string\" }))\n--                 instead of throwing an error produces an object:\n--                         {\"1\":\"one\",\"2\":\"two\",\"3\":\"three\",\"SOMESTRING\":\"some string\"}\n--\n--                 To maintain the prior throw-an-error semantics, set\n--                      JSON.noKeyConversion = true\n--                 \n--   20131004.7    Release under a Creative Commons CC-BY license, which I should have done from day one, sorry.\n--\n--   20130120.6    Comment update: added a link to the specific page on my blog where this code can\n--                 be found, so that folks who come across the code outside of my blog can find updates\n--                 more easily.\n--\n--   20111207.5    Added support for the 'etc' arguments, for better error reporting.\n--\n--   20110731.4    More feedback from David Kolf on how to make the tests for Nan/Infinity system independent.\n--\n--   20110730.3    Incorporated feedback from David Kolf at http://lua-users.org/wiki/JsonModules:\n--\n--                   * When encoding lua for JSON, Sparse numeric arrays are now handled by\n--                     spitting out full arrays, such that\n--                        JSON:encode({\"one\", \"two\", [10] = \"ten\"})\n--                     returns\n--                        [\"one\",\"two\",null,null,null,null,null,null,null,\"ten\"]\n--\n--                     In 20100810.2 and earlier, only up to the first non-null value would have been retained.\n--\n--                   * When encoding lua for JSON, numeric value NaN gets spit out as null, and infinity as \"1+e9999\".\n--                     Version 20100810.2 and earlier created invalid JSON in both cases.\n--\n--                   * Unicode surrogate pairs are now detected when decoding JSON.\n--\n--   20100810.2    added some checking to ensure that an invalid Unicode character couldn't leak in to the UTF-8 encoding\n--\n--   20100731.1    initial public release\n--\n"
_TWWE_VFS["mods/cheatgui/data/hax/lib/pollnet.lua"] = "--[[ \npollnet bindings for luajit\n\nexample usage to read twitch chat:\nlocal pollnet = require(\"pollnet\")\nlocal async = require(\"async\") -- assuming you have some kind of async\nasync.run(function()\n  local url = \"wss://irc-ws.chat.twitch.tv:443\"\n  local sock = pollnet.open_ws(url)\n  sock:send(\"PASS doesntmatter\")\n  -- special nick for anon read-only access on twitch\n  local anon_user_name = \"justinfan\" .. math.random(1, 100000)\n  local target_channel = \"your_channel_name_here\"\n  sock:send(\"NICK \" .. anon_user_name)\n  sock:send(\"JOIN #\" .. target_channel)\n  \n  while sock:poll() do\n    local msg = sock:last_message()\n    if msg then\n      if msg == \"PING :tmi.twitch.tv\" then\n        sock:send(\"PONG :tmi.twitch.tv\")\n      end\n      print(msg) \n    end\n    async.await_frames(1)\n  end\n  print(\"Socket closed: \", sock:last_message())\nend)\n]]\n\nlocal ffi = require(\"ffi\")\nffi.cdef[[\nstruct pnctx* pollnet_init();\nstruct pnctx* pollnet_get_or_init_static();\nvoid pollnet_shutdown(struct pnctx* ctx);\nunsigned int pollnet_open_ws(struct pnctx* ctx, const char* url);\nvoid pollnet_close(struct pnctx* ctx, unsigned int handle);\nvoid pollnet_close_all(struct pnctx* ctx);\nvoid pollnet_send(struct pnctx* ctx, unsigned int handle, const char* msg);\nunsigned int pollnet_update(struct pnctx* ctx, unsigned int handle);\nint pollnet_get(struct pnctx* ctx, unsigned int handle, char* dest, unsigned int dest_size);\nint pollnet_get_error(struct pnctx* ctx, unsigned int handle, char* dest, unsigned int dest_size);\nunsigned int pollnet_get_connected_client_handle(struct pnctx* ctx, unsigned int handle);\nunsigned int pollnet_listen_ws(struct pnctx* ctx, const char* addr);\nunsigned int pollnet_serve_static_http(struct pnctx* ctx, const char* addr, const char* serve_dir);\nunsigned int pollnet_serve_http(struct pnctx* ctx, const char* addr);\nvoid pollnet_add_virtual_file(struct pnctx* ctx, unsigned int handle, const char* filename, const char* filedata, unsigned int filesize);\nvoid pollnet_remove_virtual_file(struct pnctx* ctx, unsigned int handle, const char* filename);\nint pollnet_get_nanoid(char* dest, unsigned int dest_size);\n]]\n\nlocal POLLNET_RESULT_CODES = {\n  [0] = \"invalid_handle\",\n  [1] = \"closed\",\n  [2] = \"opening\",\n  [3] = \"nodata\",\n  [4] = \"hasdata\",\n  [5] = \"error\",\n  [6] = \"newclient\"\n}\n\nlocal LIB_PATH = \"mods/cheatgui/bin/pollnet.dll\"\n\nlocal pollnet = nil\nlocal _ctx = nil\n\nlocal function link_pollnet(return_error)\n  if pollnet then return end\n  local happy, res = pcall(ffi.load, LIB_PATH)\n  local err_msg = \"Pollnet DLL missing or corrupt: \" .. LIB_PATH\n  if happy then\n    pollnet = res\n  elseif return_error then\n    return err_msg .. \": \" .. res\n  else\n    error(err_msg .. \": \" .. res)\n  end\nend\n\nlocal function init_ctx()\n  if _ctx then return end\n  if not pollnet then link_pollnet() end\n  _ctx = ffi.gc(pollnet.pollnet_init(), pollnet.pollnet_shutdown)\n  assert(_ctx ~= nil)\nend\n\nlocal function init_ctx_hack_static()\n  if _ctx then return end\n  _ctx = pollnet.pollnet_get_or_init_static()\n  assert(_ctx ~= nil)\n  pollnet.pollnet_close_all(_ctx)\nend\n\nlocal function shutdown_ctx()\n  if not _ctx then return end\n  pollnet.pollnet_shutdown(ffi.gc(_ctx, nil))\n  _ctx = nil\nend\n\nlocal socket_mt = {}\nlocal function Socket()\n  return setmetatable({}, {__index = socket_mt})\nend\n\nfunction socket_mt:_open(scratch_size, opener, ...)\n  init_ctx()\n  if not _ctx then return end\n  if self._socket then self:close() end\n  if not scratch_size then scratch_size = 64000 end\n  if type(opener) == \"number\" then\n    self._socket = opener\n  else\n    self._socket = opener(_ctx, ...)\n  end\n  self._scratch = ffi.new(\"int8_t[?]\", scratch_size)\n  self._scratch_size = scratch_size\n  self._status = \"unpolled\"\n  return self\nend\n\nfunction socket_mt:open_ws(url, scratch_size)\n  return self:_open(scratch_size, pollnet.pollnet_open_ws, url)\nend\n\nfunction socket_mt:serve_http(addr, dir, scratch_size)\n  self.is_http_server = true\n  if dir and dir ~= \"\" then\n    return self:_open(scratch_size, pollnet.pollnet_serve_static_http, addr, dir)\n  else\n    return self:_open(scratch_size, pollnet.pollnet_serve_http, addr)\n  end\nend\n\nfunction socket_mt:add_virtual_file(filename, filedata)\n  assert(filedata)\n  local dsize = #filedata\n  pollnet.pollnet_add_virtual_file(_ctx, self._socket, filename, filedata, dsize)\nend\n\nfunction socket_mt:remove_virtual_file(filename)\n  pollnet.pollnet_remove_virtual_file(_ctx, self._socket, filename)\nend\n\nfunction socket_mt:listen_ws(addr, scratch_size)\n  return self:_open(scratch_size, pollnet.pollnet_listen_ws, addr)\nend\n\nfunction socket_mt:on_connection(f)\n  self._on_connection = f\n  return self\nend\n\nfunction socket_mt:_get_message()\n  local msg_size = pollnet.pollnet_get(_ctx, self._socket, self._scratch, self._scratch_size)\n  if msg_size > 0 then\n    return ffi.string(self._scratch, msg_size)\n  else\n    return nil\n  end\nend\n\nfunction socket_mt:poll()\n  if not self._socket then \n    self._status = \"invalid\"\n    return false, \"invalid\"\n  end\n  local res = POLLNET_RESULT_CODES[pollnet.pollnet_update(_ctx, self._socket)] or \"error\"\n  self._status = res\n  self._last_message = nil\n  if res == \"hasdata\" then\n    self._status = \"open\"\n    self._last_message = self:_get_message()\n    return true, self._last_message\n  elseif res == \"nodata\" then\n    self._status = \"open\"\n    return true\n  elseif res == \"opening\" then\n    self._status = \"opening\"\n    return true\n  elseif res == \"error\" then\n    self._last_message = self:error_msg()\n    return false, self._last_message\n  elseif res == \"closed\" then\n    return false, \"closed\"\n  elseif res == \"newclient\" then\n    local client_addr = self:_get_message()\n    local client_handle = pollnet.pollnet_get_connected_client_handle(_ctx, self._socket)\n    assert(client_handle > 0)\n    local client_sock = Socket():_open(self._scratch_size, client_handle)\n    client_sock.parent = self\n    client_sock.remote_addr = client_addr\n    if self._on_connection then\n      self._on_connection(client_sock, client_addr)\n    else\n      print(\"No connection handler! All incoming connections will be closed!\")\n      client_sock:close()\n    end\n    return true\n  end\nend\n\nfunction socket_mt:last_message()\n  return self._last_message\nend\nfunction socket_mt:status()\n  return self._status\nend\nfunction socket_mt:send(msg)\n  assert(self._socket)\n  pollnet.pollnet_send(_ctx, self._socket, msg)\nend\nfunction socket_mt:close()\n  assert(self._socket)\n  pollnet.pollnet_close(_ctx, self._socket)\n  self._socket = nil\nend\nfunction socket_mt:error_msg()\n  if not self._socket then return \"No socket!\" end\n  local msg_size = pollnet.pollnet_get_error(_ctx, self._socket, self._scratch, self._scratch_size)\n  if msg_size > 0 then\n    local smsg = ffi.string(self._scratch, msg_size)\n    return smsg\n  else\n    return nil\n  end\nend\n\nlocal function open_ws(url, scratch_size)\n  return Socket():open_ws(url, scratch_size)\nend\n\nlocal function listen_ws(addr, scratch_size)\n  return Socket():listen_ws(addr, scratch_size)\nend\n\nlocal function serve_http(addr, dir, scratch_size)\n  return Socket():serve_http(addr, dir, scratch_size)\nend\n\nlocal function get_nanoid()\n  local _id_scratch = ffi.new(\"int8_t[?]\", 128)\n  local msg_size = pollnet.pollnet_get_nanoid(_id_scratch, 128)\n  return ffi.string(_id_scratch, msg_size)\nend\n\nlib_pollnet = {\n  init = init_ctx,\n  link = link_pollnet,\n  init_hack_static = init_ctx_hack_static,\n  shutdown = shutdown_ctx, \n  open_ws = open_ws, \n  listen_ws = listen_ws,\n  serve_http = serve_http,\n  Socket = Socket,\n  pollnet = pollnet,\n  nanoid = get_nanoid,\n}"
_TWWE_VFS["mods/cheatgui/data/hax/materials.lua"] = "materials_list = {}\n\nlocal get_name = function(mat)\n  return mat\nend\n\nif not DebugGetIsDevBuild() then\n  -- Dev build likes to complain about translations\n  get_name = function(mat)\n    local n = GameTextGet(\"$mat_\" .. mat)\n    if n and n ~= \"\" then return n else return \"[\" .. mat .. \"]\" end\n  end\nend\n\nfor _, category in ipairs{\"Liquids\", \"Solids\", \"Sands\", \"Gases\", \"Fires\"} do\n  table.insert(materials_list, {\"-- \" .. category .. \" --\", \"-- \" .. category .. \" --\"})\n  local mats = getfenv()[\"CellFactory_GetAll\" .. category]()\n  print(\"Got \" .. #mats .. \" \" .. category)\n  table.sort(mats)\n  for _, mat in ipairs(mats) do\n    table.insert(materials_list, {mat, get_name(mat)})\n  end\nend\n\n-- local getters = {\n--   {\"Fires\", CellFactory_GetAllFires, \n--   CellFactory_GetAllGases,\n--   CellFactory_GetAllSolids,\n--   CellFactory_GetAllSands,\n--   CellFactory_GetAllLiquids\n-- }"
