_TWWE_VFS["mods/cheatgui/data/hax/superhackykb.lua"] = "print(\"Loading hacky KB?\")\n\nif _hacky_keyboard_defined then\n  return\nend\n\n_hacky_keyboard_defined = true\n\nhack_type = function()\n  return \"\"\nend\n\nif not require then\n  print(\"No require? Urgh.\")\n  return\nend\n\nlocal ffi = require('ffi')\nif not ffi then\n  print(\"No FFI? Well that's a pain.\")\n  return\nend\n\n_keyboard_present = true\n\nffi.cdef([[\n  const uint8_t* SDL_GetKeyboardState(int* numkeys);\n  uint32_t SDL_GetKeyFromScancode(uint32_t scancode);\n  char* SDL_GetScancodeName(uint32_t scancode);\n  char* SDL_GetKeyName(uint32_t key);\n]])\n_SDL = ffi.load('SDL2.dll')\n\nlocal code_to_a = {}\nlocal shifts = {}\n\nfor i = 0, 284 do\n  local keycode = _SDL.SDL_GetKeyFromScancode(i)\n  if keycode > 0 then\n    local keyname = ffi.string(_SDL.SDL_GetKeyName(keycode))\n    if keyname and #keyname > 0 then\n      code_to_a[i] = keyname:lower()\n      if keyname:lower():find(\"shift\") then\n        table.insert(shifts, i)\n      end\n    end\n  end\nend\n\nlocal prev_state = {}\nfor i = 0, 284 do\n  prev_state[i] = 0\nend\n\nfunction hack_update_keys()\n  local keys = _SDL.SDL_GetKeyboardState(nil)\n  local pressed = {}\n  -- start at scancode 1 because we don't care about \"UNKNOWN\"\n  for scancode = 1, 284 do \n    if keys[scancode] > 0 and prev_state[scancode] <= 0 then\n      pressed[#pressed+1] = code_to_a[scancode]\n    end\n    prev_state[scancode] = keys[scancode]\n  end\n  local shift_held = false\n  for _, shiftcode in ipairs(shifts) do\n    if keys[shiftcode] > 0 then\n      shift_held = true\n      break\n    end\n  end\n  return pressed, shift_held\nend\n\nlocal REPLACEMENTS = {\n  space = \" \"\n}\n\nhack_type = function(current_str, no_shift)\n  local pressed, shift_held = hack_update_keys()\n  local hit_enter = false\n  for _, key in ipairs(pressed) do\n    if (no_shift or shift_held) and REPLACEMENTS[key] then\n      current_str = current_str .. REPLACEMENTS[key]\n    elseif (no_shift or shift_held) and (#key == 1) then\n      current_str = current_str .. key\n    elseif key == \"backspace\" then\n      current_str = current_str:sub(1,-2)\n    elseif key == \"enter\" or key == \"return\" then\n      hit_enter = true\n    end\n  end\n  return current_str, hit_enter\nend\n\nprint(\"Hacky KB loaded?\")"
_TWWE_VFS["mods/cheatgui/data/hax/utils.lua"] = "function get_player()\n  return EntityGetWithTag(\"player_unit\")[1]\nend\n\nfunction get_player_pos()\n  local player = get_player()\n  if not player then return 0, 0 end\n  return EntityGetTransform(player)\nend\n\nfunction enable_ai(e, enabled)\n  local ai = EntityGetFirstComponent(e, \"AnimalAIComponent\")\n  if not ai then print(\"no ai??\") end\n  --ComponentSetValue( ai, \"_enabled\", (enabled and \"1\") or \"0\" )\n  --ComponentSetValue( ai, \"enabled\", (enabled and \"1\") or \"0\" )\n  EntitySetComponentIsEnabled(e, ai, enabled)\nend\n\nfunction teleport(x, y)\n  EntitySetTransform(get_player(), x, y)\nend\n\nfunction get_health()\n  local dm = EntityGetComponent(get_player(), \"DamageModelComponent\")[1]\n  return ComponentGetValue(dm, \"hp\"), ComponentGetValue(dm, \"max_hp\")\nend\n\nfunction set_health(cur_hp, max_hp)\n  local damagemodels = EntityGetComponent(get_player(), \"DamageModelComponent\")\n  for _, damagemodel in ipairs(damagemodels or {}) do\n    ComponentSetValue(damagemodel, \"max_hp\", max_hp)\n    ComponentSetValue(damagemodel, \"hp\", cur_hp)\n  end\nend\n\nfunction quick_heal()\n  local _, max_hp = get_health()\n  set_health(max_hp, max_hp)\nend\n\nfunction set_money(amt)\n  local wallet = EntityGetFirstComponent(get_player(), \"WalletComponent\")\n  ComponentSetValue2(wallet, \"money\", amt)\nend\n\nfunction get_money()\n  local wallet = EntityGetFirstComponent(get_player(), \"WalletComponent\")\n  return ComponentGetValue2(wallet, \"money\")\nend\n\nfunction twiddle_money(delta)\n  local wallet = EntityGetFirstComponent(get_player(), \"WalletComponent\")\n  local current = ComponentGetValue2(wallet, \"money\")\n  ComponentSetValue2(wallet, \"money\", math.max(0, current+delta))\nend\n\nfunction spawn_entity(ename, offset_x, offset_y)\n  local x, y = get_player_pos()\n  x = x + (offset_x or 0)\n  y = y + (offset_y or 0)\n  return EntityLoad(ename, x, y)\nend\nspawn_item = spawn_entity\n\nfunction empty_container_of_materials(idx)\n  for _ = 1, 1000 do -- avoid infinite loop\n    local material = GetMaterialInventoryMainMaterial(idx)\n    if material <= 0 then break end\n    local matname = CellFactory_GetName(material)\n    AddMaterialInventoryMaterial(idx, matname, 0)\n  end\nend\n\nfunction spawn_potion(material, quantity, kind)\n  local x, y = get_player_pos()\n  quantity = quantity or 1000\n  local entity\n  if kind == nil or kind == \"potion\" then \n    entity = EntityLoad(\"data/entities/items/pickup/potion_empty.xml\", x, y)\n  else -- kind == \"pouch\"\n    entity = EntityLoad(\"data/entities/items/pickup/powder_stash.xml\", x, y)\n    empty_container_of_materials(entity)\n    quantity = quantity * 1.5\n  end\n  AddMaterialInventoryMaterial(entity, material, quantity)\nend\n\nfunction spawn_perk(perk_id, auto_pickup_entity)\n  local x, y = get_player_pos()\n  local perk_entity = perk_spawn(x, y - 8, perk_id)\n  if auto_pickup_entity then\n    perk_pickup(perk_entity, auto_pickup_entity, nil, true, false)\n  end\nend\n\nfunction set_tourist_mode(enabled)\n  local herd = (enabled and \"healer\") or \"player\"\n  GenomeSetHerdId(get_player(), herd)\nend\n\nfunction hello()\n  GamePrintImportant(\"Hello\", \"Hello\")\n  GamePrint(\"Hello\")\n  print(\"Hello\")\nend\n\nfunction get_closest_entity(px, py, tag)\n  if not py then\n    tag = px\n    px, py = get_player_pos()\n  end\n  return EntityGetClosestWithTag( px, py, tag)\nend\n\nfunction get_entity_mouse(tag)\n  local mx, my = DEBUG_GetMouseWorld()\n  return get_closest_entity(mx, my, tag or \"hittable\")\nend\n\nfunction print_component_info(c)\n  local frags = {\"<\" .. ComponentGetTypeName(c) .. \">\"}\n  local members = ComponentGetMembers(c)\n  if not members then return end\n  for k, v in pairs(members) do\n    table.insert(frags, k .. ': ' .. tostring(v))\n  end\n  print(table.concat(frags, '\\n'))\nend\n\nfunction get_vector_value(comp, member, kind)\n  kind = kind or \"float\"\n  local n = ComponentGetVectorSize( comp, member, kind )\n  if not n then return nil end\n  local ret = {};\n  for i = 1, n do\n    ret[i] = ComponentGetVectorValue(comp, member, kind, i-1) or \"nil\"\n  end\n  return ret\nend\n\nfunction print_vector_value(...)\n  local v = get_vector_value(...)\n  if not v then return nil end\n  return \"{\" .. table.concat(v, \", \") .. \"}\"\nend\n\nfunction print_detailed_component_info(c)\n  local members = ComponentGetMembers(c)\n  if not members then return end\n  local frags = {}\n  for k, v in pairs(members) do\n    if (not v) or #v == 0 then\n      local mems = ComponentObjectGetMembers(c, k)\n      if mems then\n        table.insert(frags, k .. \">\")\n        for k2, v2 in pairs(mems) do\n          table.insert(frags, \"  \" .. k2 .. \": \" .. tostring(v2))\n        end\n      else\n        v = print_vector_value(c, k)\n      end\n    end\n    table.insert(frags, k .. ': ' .. tostring(v))\n  end\n  print(table.concat(frags, '\\n'))\n\nend\n\nfunction print_entity_info(e)\n  local comps = EntityGetAllComponents(e)\n  if not comps then\n    print(\"Invalid entity?\")\n    return\n  end\n  for idx, comp in ipairs(comps) do\n    print(comp, \"-----------------\")\n    print_component_info(comp)\n  end\nend\n\nfunction list_components(e)\n  local comps = EntityGetAllComponents(e)\n  if not comps then\n    print(\"Invalid entity?\")\n    return\n  end\n  for idx, comp in ipairs(comps) do\n    print(comp .. \" : \" .. ComponentGetTypeName(comp))\n  end\nend\n\nfunction list_funcs(filter)\n  local ff = {}\n  for k, v in pairs(getfenv()) do\n    local first_letter = k:sub(1,1)\n    if first_letter:upper() == first_letter then\n      if (not filter) or k:lower():find(filter:lower()) then\n        table.insert(ff, k)\n      end\n    end\n  end\n  table.sort(ff)\n  print(table.concat(ff, \"\\n\"))\nend\n\nfunction get_child_info(e)\n  local children = EntityGetAllChildren(e)\n  for _, child in ipairs(children) do\n    print(child, EntityGetName(child) or \"[no name]\")\n  end\nend\n\nfunction do_here(fn)\n  local f = loadfile(fn)\n  if type(f) ~= \"function\" then\n    print(\"Loading error; check logger.txt for details.\")\n  end\n  setfenv(f, getfenv())\n  f()\nend\n\nfunction round(v)\n  local upper = math.ceil(v)\n  local lower = math.floor(v)\n  if math.abs(v - upper) < math.abs(v - lower) then\n    return upper\n  else\n    return lower\n  end\nend\n\nfunction resolve_localized_name(s, default)\n  if s:sub(1,1) ~= \"$\" then return s end\n  local rep = GameTextGet(s)\n  if rep and rep ~= \"\" then return rep else return default or s end\nend\n\nfunction localize_material(mat)\n  local n = GameTextGet(\"$mat_\" .. mat)\n  if n and n ~= \"\" then return n else return \"[\" .. mat .. \"]\" end\nend"
_TWWE_VFS["mods/cheatgui/data/hax/wand_empty.xml"] = "<Entity>\n\n    <Base file=\"data/entities/base_item.xml\">\n        <SpriteComponent \n            next_rect_animation=\"JobAbilityMachinegun\" >\n        </SpriteComponent>\n        \n        <ItemComponent\n            play_hover_animation=\"1\">\n        </ItemComponent>\n\n        <SimplePhysicsComponent\n            _enabled=\"0\">\n        </SimplePhysicsComponent>\n    </Base>\n    \n    <Base file=\"data/entities/base_wand.xml\">\n    </Base>\n\n    <AbilityComponent \n        amount_in_inventory=\"1\" \n        cooldown_frames=\"0\" \n        drop_as_item_on_death=\"1\" \n        entity_count=\"1\" \n        entity_file=\"\" \n        fast_projectile=\"0\" \n		mana_charge_speed=\"140\"\n		mana_max=\"600\"\n        max_amount_in_inventory=\"1\" \n        reload_time_frames=\"0\" \n        shooting_reduces_amount_in_inventory=\"0\" \n        sprite_file=\"data/items_gfx/machinegun.xml\" \n        swim_propel_amount=\"0\" \n        throw_as_item=\"0\" \n        ui_name=\"Rapid bolt wand\" \n        use_gun_script=\"1\" \n        >\n        <gun_config \n            actions_per_round=\"1\"\n            shuffle_deck_when_empty=\"1\"\n            reload_time=\"18\" \n            deck_capacity=\"8\" >\n        </gun_config>\n        <gunaction_config \n            fire_rate_wait=\"5\" >\n        </gunaction_config>\n    </AbilityComponent>\n\n    <HotspotComponent \n        _tags=\"shoot_pos\" \n        offset.x=\"20\" \n        offset.y=\"0\" >\n    </HotspotComponent>\n    \n    <ManaReloaderComponent\n        _tags=\"enabled_in_world,enabled_in_hand,enabled_in_inventory\" >\n    </ManaReloaderComponent>\n\n</Entity>"
_TWWE_VFS["mods/cheatgui/data/hax/wand_hax.lua"] = "dofile(\"data/scripts/gun/procedural/gun_procedural.lua\")\n\nlocal function gen_gun()\n	local entity_id = GetUpdatedEntityID()\n	local x, y = EntityGetTransform( entity_id )\n  SetRandomSeed( x, y )\n  \n  local cost, level = 0, 6\n\n	local ability_comp = EntityGetFirstComponent( entity_id, \"AbilityComponent\" )\n\n	cost = 0\n\n  local gun = { }\n  gun[\"cost\"]	= cost\n  gun[\"deck_capacity\"] = 50\n  gun[\"actions_per_round\"] = 50\n  gun[\"reload_time\"] = 60\n  gun[\"shuffle_deck_when_empty\"] = 0\n  gun[\"fire_rate_wait\"] = 60\n  gun[\"spread_degrees\"] = 0\n  gun[\"speed_multiplier\"] = 1\n  gun[\"prob_unshuffle\"] = 0.1\n  gun[\"prob_draw_many\"] = 0.15\n  gun[\"mana_charge_speed\"] = 10000\n  gun[\"mana_max\"] = 10000\n  gun[\"force_unshuffle\"] = 1\n\n\n  local name = \"HAXXXX\" --ComponentGetValue( ability_comp, \"ui_name\" )\n	\n	-- SetItemSprite( entity_id, ability_comp, \"data/items_gfx/gungen_guns/submachinegun_\", Random( 0, 7 ) )\n	ComponentSetValue( ability_comp, \"ui_name\", name )\n	ComponentObjectSetValue( ability_comp, \"gun_config\", \"actions_per_round\", gun[\"actions_per_round\"] )\n	ComponentObjectSetValue( ability_comp, \"gun_config\", \"reload_time\", gun[\"reload_time\"] )\n	ComponentObjectSetValue( ability_comp, \"gun_config\", \"deck_capacity\", gun[\"deck_capacity\"] )\n	ComponentObjectSetValue( ability_comp, \"gun_config\", \"shuffle_deck_when_empty\", gun[\"shuffle_deck_when_empty\"] )\n	ComponentObjectSetValue( ability_comp, \"gunaction_config\", \"fire_rate_wait\", gun[\"fire_rate_wait\"] )\n	ComponentObjectSetValue( ability_comp, \"gunaction_config\", \"spread_degrees\", gun[\"spread_degrees\"] )\n	ComponentObjectSetValue( ability_comp, \"gunaction_config\", \"speed_multiplier\", gun[\"speed_multiplier\"] )\n	ComponentSetValue( ability_comp, \"mana_charge_speed\", gun[\"mana_charge_speed\"])\n	ComponentSetValue( ability_comp, \"mana_max\", gun[\"mana_max\"])\n	ComponentSetValue( ability_comp, \"mana\", gun[\"mana_max\"])\n\n	ComponentSetValue( ability_comp, \"item_recoil_recovery_speed\", 15.0 ) -- TODO: implement logic for setting this\n\n	-- stuff in the gun\n	local good_cards = 5\n	if( Random(0,100) < 7 ) then good_cards = Random(20,50) end\n\n	if( is_rare == 1 ) then\n		good_cards = good_cards * 2\n	end\n\n	local orig_level = level\n	level = level - 1\n	local deck_capacity = gun[\"deck_capacity\"]\n	local actions_per_round = gun[\"actions_per_round\"]\n	local card_count = Random( 1, 3 ) \n	local bullet_card = GetRandomActionWithType( x, y, level, ACTION_TYPE_PROJECTILE, 0 )\n	local random_bullets = 0 \n	local good_card_count = 0\n\n	if( Random(0,100) < 50 and card_count < 3 ) then card_count = card_count + 1 end \n	\n	if( Random(0,100) < 10 or is_rare == 1 ) then \n		card_count = card_count + Random( 1, 2 )\n	end\n\n	good_cards = Random( 5, 45 )\n	card_count = Random( 0.51 * deck_capacity, deck_capacity )\n	card_count = clamp( card_count, 1, deck_capacity-1 )\n\n	-- card count is in between 1 and 6\n\n	if( Random(0,100) < (orig_level*10)-5 ) then\n		random_bullets = 1\n	end\n\n	if( Random( 0, 100 ) < 4 or is_rare == 1 ) then\n		local card = 0\n		local p = Random(0,100) \n		if( p < 77 ) then\n			card = GetRandomActionWithType( x, y, level+1, ACTION_TYPE_MODIFIER, 666 )\n		elseif( p < 94 ) then\n			card = GetRandomActionWithType( x, y, level+1, ACTION_TYPE_DRAW_MANY, 666 )\n			good_card_count = good_card_count + 1\n		else \n			card = GetRandomActionWithType( x, y, level+1, ACTION_TYPE_PROJECTILE, 666 )\n		end\n		AddGunActionPermanent( entity_id, card )\n	end\n\n\n	for i=1,card_count do\n		if( Random(0,100) < good_cards ) then\n			-- if actions_per_round == 1 and the first good card, then make sure it's a draw x\n			local card = 0\n			if( good_card_count == 0 and actions_per_round == 1 ) then\n				card = GetRandomActionWithType( x, y, level, ACTION_TYPE_DRAW_MANY, i )\n				good_card_count = good_card_count + 1\n			else\n				if( Random(0,100) < 83 ) then\n					card = GetRandomActionWithType( x, y, level, ACTION_TYPE_MODIFIER, i )\n				else\n					card = GetRandomActionWithType( x, y, level, ACTION_TYPE_DRAW_MANY, i )\n				end\n			end\n		\n			AddGunAction( entity_id, card )\n		else\n			AddGunAction( entity_id, bullet_card )\n			if( random_bullets == 1 ) then\n				bullet_card = GetRandomActionWithType( x, y, level, ACTION_TYPE_PROJECTILE, i )\n			end\n		end\n	end\n\n	local wand = GetWand( gun )\n\n	SetWandSprite( entity_id, ability_comp, wand.file, wand.grip_x, wand.grip_y, (wand.tip_x - wand.grip_x), (wand.tip_y - wand.grip_y) )\n	-- SetItemSprite( entity_id, ability_comp, \"data/items_gfx/wands/wand_\", Random( 0, 999 ) )\n\n	-- this way:\n	-- AddGunActionPermanent( entity_id, \"ELECTRIC_CHARGE\" )\nend\ngen_gun()"
_TWWE_VFS["mods/cheatgui/data/hax/wand_hax.xml"] = "<Entity>\n\n    <Base file=\"data/entities/base_item.xml\">\n        <SpriteComponent \n            next_rect_animation=\"JobAbilityMachinegun\" >\n        </SpriteComponent>\n        \n        <ItemComponent\n            play_hover_animation=\"1\">\n        </ItemComponent>\n\n        <SimplePhysicsComponent\n            _enabled=\"0\">\n        </SimplePhysicsComponent>\n    </Base>\n    \n    <Base file=\"data/entities/base_wand.xml\">\n    </Base>\n\n    <AbilityComponent \n        amount_in_inventory=\"1\" \n        cooldown_frames=\"0\" \n        drop_as_item_on_death=\"1\" \n        entity_count=\"1\" \n        entity_file=\"\" \n        fast_projectile=\"0\" \n		mana_charge_speed=\"140\"\n		mana_max=\"600\"\n        max_amount_in_inventory=\"1\" \n        reload_time_frames=\"0\" \n        shooting_reduces_amount_in_inventory=\"0\" \n        sprite_file=\"data/items_gfx/machinegun.xml\" \n        swim_propel_amount=\"0\" \n        throw_as_item=\"0\" \n        ui_name=\"Rapid bolt wand\" \n        use_gun_script=\"1\" \n        >\n        <gun_config \n            actions_per_round=\"1\"\n            shuffle_deck_when_empty=\"1\"\n            reload_time=\"18\" \n            deck_capacity=\"8\" >\n        </gun_config>\n        <gunaction_config \n            fire_rate_wait=\"5\" >\n        </gunaction_config>\n    </AbilityComponent>\n\n    <HotspotComponent \n        _tags=\"shoot_pos\" \n        offset.x=\"20\" \n        offset.y=\"0\" >\n    </HotspotComponent>\n    \n    <LuaComponent \n        _enabled=\"1\" \n        execute_on_added=\"1\"\n        remove_after_executed=\"1\"\n        script_source_file=\"data/hax/wand_hax.lua\" \n	>\n    </LuaComponent>\n\n    <ManaReloaderComponent\n        _tags=\"enabled_in_world,enabled_in_hand,enabled_in_inventory\" >\n    </ManaReloaderComponent>\n\n</Entity>"
_TWWE_VFS["mods/cheatgui/init.lua"] = "-- stash the environment! (mainly to keep ModTextFileGetContent around!)\ncheatgui_stash = {}\nfor k, v in pairs(_G) do\n  cheatgui_stash[k] = v\nend\n\nfunction OnWorldPostUpdate() \n  if _cheat_gui_main then _cheat_gui_main() end\nend\n\nfunction OnPlayerSpawned( player_entity )\n  print(\"OnPlayerSpawned require check:\")\n  if not require then\n    print(\"NO require.\")\n  else\n    print(\"YES require.\")\n  end\n  dofile(\"data/hax/cheatgui.lua\")\nend\n"
_TWWE_VFS["mods/cheatgui/mod.xml"] = "<Mod\n	name=\"Cheatgui\"\n	description=\"cheat/dev menu\"\n	request_no_api_restrictions=\"0\"\n>\n</Mod>"
_TWWE_VFS["mods/cheatgui/mod_id.txt"] = "cheatgui"
_TWWE_VFS["mods/component-explorer/animation_viewer/anim_parser.lua"] = "local xml_viewer = {}\n\n---@class Sprite\n---@field filename string\n---@field default_animation string\n---@field rect_animations RectAnimation[]\n---@field rect_animations_by_name {[string]: RectAnimation}\n\n---@class RectAnimation\n---@field name string\n---@field frame_count integer\n---@field frame_width integer\n---@field frame_height integer\n---@field frames_per_row integer\n---@field shrink_by_one_pixel boolean\n---@field pos_x integer\n---@field pos_y integer\n---@field frame_wait number\n\n---@param xml any\n---@return Sprite?\n---@return string[] errors\nfunction xml_viewer.parse_sprite(xml)\n    local filename = \"\"\n    local default_animation = \"\"\n    local rect_animations = {}\n    local rect_animations_by_name = {}\n    local valid = true\n\n    local errors = {}\n\n    if not xml.attr.filename then\n        errors[#errors+1] = \"Sprite is missing 'filename' field\"\n        valid = false\n    else\n        filename = xml.attr.filename\n        if not ModImageDoesExist(filename) then\n            errors[#errors+1] = \"Image file '\" .. filename .. \"' is not found\"\n            valid = false\n        end\n    end\n\n    if xml.attr.default_animation then\n        default_animation = xml.attr.default_animation\n    end\n\n    for rect_xml in xml:each_of(\"RectAnimation\") do\n        local rect_anim, rect_errors = xml_viewer.parse_rect_animation(rect_xml)\n        for _, rect_error in ipairs(rect_errors) do\n            errors[#errors+1] = rect_error\n        end\n\n        if rect_anim then\n            rect_animations[#rect_animations+1] = rect_anim\n            if rect_animations_by_name[rect_anim.name] then\n                errors[#errors+1] = \"Multiple RectAnimation with name: \" .. rect_anim.name\n            end\n            rect_animations_by_name[rect_anim.name] = rect_anim\n        end\n    end\n\n    local has_animations = false\n    for _, _ in pairs(rect_animations_by_name) do\n        has_animations = true\n        break\n    end\n\n    if not has_animations then\n        errors[#errors+1] = \"Sprite has no animations\"\n        valid = false\n    elseif not rect_animations_by_name[default_animation] then\n        errors[#errors+1] = \"Sprite has no default animation: \" .. default_animation\n    end\n\n    if not valid then\n        return nil, errors\n    end\n\n    ---@type Sprite\n    local sprite = {\n        filename = filename,\n        default_animation = default_animation,\n        rect_animations = rect_animations,\n        rect_animations_by_name = rect_animations_by_name,\n    }\n\n    return sprite, errors\nend\n\nlocal function read_int(xml, attr, errors)\n    local value = tonumber(xml.attr[attr]) or 0\n    local as_int = math.floor(value)\n    if value ~= as_int then\n        errors[#errors+1] = \"Expected '\" .. attr .. \"' to be an integer but it has a fractional part\"\n    end\n    return as_int\nend\n\nlocal function read_bool(xml, attr, errors)\n    local value = xml.attr[attr]\n    if value ~= \"0\" and value ~= \"1\" then\n        errors[#errors+1] = \"Expected '\" .. attr .. \"' to be 0 or 1\"\n    end\n    return value ~= \"0\"\nend\n\n---@param xml any\n---@return RectAnimation?\n---@return string[] errors\nfunction xml_viewer.parse_rect_animation(xml)\n    local name = \"unknown\"\n    local frame_count = 0\n    local frame_width = 0\n    local frame_height = 0\n    local frames_per_row = 9999\n    local shrink_by_one_pixel = false\n    local pos_x = 0\n    local pos_y = 0\n    local frame_wait = 0\n\n    local valid = true\n    local errors = {}\n\n    if not xml.attr.name then\n        errors[#errors+1] = \"RectAnimation is missing 'name' field\"\n    else\n        name = xml.attr.name\n    end\n\n    if not xml.attr.frame_count then\n        errors[#errors+1] = \"RectAnimation is missing 'frame_count' field\"\n        valid = false\n    else\n        frame_count = read_int(xml, \"frame_count\", errors)\n        if frame_count <= 0 then\n            errors[#errors+1] = \"Bad 'frame_count' value\"\n            valid = false\n        end\n    end\n\n    if not xml.attr.frame_width then\n        errors[#errors+1] = \"RectAnimation is missing 'frame_width' field\"\n        valid = false\n    else\n        frame_width = read_int(xml, \"frame_width\", errors)\n        if frame_width < 0 then\n            errors[#errors] = \"Invalid 'frame_width' value: \" .. xml.attr.frame_width\n            valid = false\n        end\n    end\n\n    if not xml.attr.frame_height then\n        errors[#errors+1] = \"RectAnimation is missing 'frame_height' field\"\n        valid = false\n    else\n        frame_height = read_int(xml, \"frame_height\", errors)\n        if frame_height < 0 then\n            errors[#errors] = \"Invalid 'frame_height' value: \" .. xml.attr.frame_height\n            valid = false\n        end\n    end\n\n    if xml.attr.frames_per_row then\n        frames_per_row = read_int(xml, \"frames_per_row\", errors)\n    end\n\n    if xml.attr.shrink_by_one_pixel then\n        shrink_by_one_pixel = read_bool(xml, \"shrink_by_one_pixel\", errors)\n    end\n\n    if xml.attr.pos_x then\n        pos_x = read_int(xml, \"pos_x\", errors)\n        if pos_x < 0 then\n            errors[#errors] = \"Invalid 'pos_x' value: \" .. xml.attr.pos_x\n            valid = false\n        end\n    end\n\n    if xml.attr.pos_y then\n        pos_y = read_int(xml, \"pos_y\", errors)\n        if pos_y < 0 then\n            errors[#errors] = \"Invalid 'pos_y' value: \" .. xml.attr.pos_y\n            valid = false\n        end\n    end\n\n    if not xml.attr.frame_wait then\n        errors[#errors+1] = \"RectAnimation is missing 'frame_wait' field\"\n        valid = false\n    else\n        frame_wait = tonumber(xml.attr.frame_wait) or 0\n        if frame_wait <= 0 then\n            errors[#errors+1] = \"Invalid 'frame_wait' value: \" .. xml.attr.frame_wait\n            valid = false\n        end\n    end\n\n    if not valid then\n        return nil, errors\n    end\n\n    ---@type RectAnimation\n    local rect_animation = {\n        name = name,\n        frame_count = frame_count,\n        frame_width = frame_width,\n        frame_height = frame_height,\n        frames_per_row = frames_per_row,\n        shrink_by_one_pixel = shrink_by_one_pixel,\n        pos_x = pos_x,\n        pos_y = pos_y,\n        frame_wait = frame_wait,\n    }\n\n    return rect_animation, errors\nend\n\nreturn xml_viewer\n"
_TWWE_VFS["mods/component-explorer/animation_viewer/anim_viewer.lua"] = "---@module 'component-explorer.animation_viewer.anim_parser'\nlocal anim_parser = dofile_once(\"mods/component-explorer/animation_viewer/anim_parser.lua\")\n\n---@module 'component-explorer.deps.nxml'\nlocal nxml = dofile_once(\"mods/component-explorer/deps/nxml.lua\")\n\nlocal ModTextFileGetContent = ModTextFileGetContent\n\nlocal anim_viewer = {}\nanim_viewer.open = false\n\nlocal file_path = \"\"\nlocal path_content = \"\"\n\nlocal direct_input_text = \"\"\n\n---@class AnimState\n---@field frame integer\n---@field current_animation string\n---@field time number\n---@field sprite Sprite?\n---@field play boolean\n---@field xml_error string?\n---@field sprite_errors string[]\n\n---@return AnimState\nlocal function make_state()\n    ---@type AnimState\n    local new_state = {\n        frame = 0,\n        current_animation = \"unknown\",\n        time = 0,\n        sprite = nil,\n        play = false,\n        xml_error = nil,\n        sprite_errors = {},\n    }\n    return new_state\nend\n\n---@param state AnimState\nlocal function state_reset(state)\n    state.xml_error = nil\n    state.sprite = nil\n    state.sprite_errors = {}\nend\n\nlocal direct_input_state = make_state()\nlocal path_state = make_state()\n\n---Shows image from xml file\n---@param sprite Sprite\n---@param animation string\n---@param frame integer\nlocal function show_sprite_frame(sprite, animation, frame)\n    local avail_w, avail_h = imgui.GetContentRegionAvail()\n    if avail_w <= 0 or avail_h <= 0 then\n        return\n    end\n\n    local rect_anim = sprite.rect_animations_by_name[animation]\n    local img = imgui.LoadImage(sprite.filename)\n    if img then\n        local frame_column = frame % rect_anim.frames_per_row\n        local frame_row = math.floor(frame / rect_anim.frames_per_row)\n\n        local uv0_x = (rect_anim.pos_x + frame_column * rect_anim.frame_width) / img.width\n        local uv0_y = (rect_anim.pos_y + frame_row * rect_anim.frame_height) / img.height\n\n        local pixels_w = rect_anim.frame_width\n        local pixels_h = rect_anim.frame_height\n        if rect_anim.shrink_by_one_pixel then\n            pixels_w = pixels_w - 1\n            pixels_h = pixels_h - 1\n        end\n        local uv1_x = uv0_x + pixels_w / img.width\n        local uv1_y = uv0_y + pixels_h / img.height\n\n        local display_ratio = pixels_w / pixels_h\n\n        local avail_ratio = avail_w / avail_h\n\n        local disp_w, disp_h\n        local x, y = imgui.GetCursorPos()\n        if display_ratio < avail_ratio then\n            disp_h = avail_h\n            disp_w = disp_h * display_ratio\n            x = x + (avail_w - disp_w) / 2\n        else\n            disp_w = avail_w\n            disp_h = disp_w / display_ratio\n            y = y + (avail_h - disp_h) / 2\n        end\n        imgui.SetCursorPos(x, y) -- Center\n\n        imgui.Image(img, disp_w, disp_h, uv0_x, uv0_y, uv1_x, uv1_y)\n    end\nend\n\n---@param state AnimState\n---@param xml_source string\nlocal function load_animation(state, xml_source)\n    state_reset(state)\n\n    local parse_errors = {}\n    local error_reporter = function(type, msg)\n        parse_errors[#parse_errors+1] = \"parser warning: [\" .. type .. \"] \" .. msg\n    end\n\n    local success, result = pcall(nxml.parse, xml_source, {error_reporter=error_reporter})\n    if success then\n        state.sprite, state.sprite_errors = anim_parser.parse_sprite(result)\n    else\n        parse_errors[#parse_errors+1] = result\n    end\n\n    if #parse_errors > 0 then\n        state.xml_error = table.concat(parse_errors, \"\\n\")\n    else\n        state.xml_error = nil\n    end\nend\n\n\nfunction anim_viewer.show()\n    local should_show\n    should_show, anim_viewer.open = imgui.Begin(\"Animation\", anim_viewer.open)\n    if not should_show then\n        return\n    end\n\n    ---@type AnimState\n    local state\n\n    if imgui.BeginTabBar(\"inputmethod\") then\n        if imgui.BeginTabItem(\"File Path\") then\n            state = path_state\n\n            local changed\n            imgui.SetNextItemWidth(450)\n            changed, file_path = imgui.InputText(\"Path\", file_path)\n            if changed then\n                state_reset(state)\n                path_content = \"\"\n                if file_path:sub(-4) == \".xml\" then\n                    path_content = ModTextFileGetContent(file_path) or \"\"\n                    if path_content == \"\" then\n                        state.xml_error = \"File not found\"\n                    else\n                        load_animation(state, path_content)\n                    end\n\n                end\n            end\n\n            if path_content ~= \"\" then\n                imgui.SameLine()\n                if imgui.Button(\"Edit\") then\n                    switch_direct_input = true\n                    direct_input_text = path_content\n                    direct_input_state = path_state\n\n                    path_state = make_state()\n                    file_path = \"\"\n                end\n            end\n\n            imgui.EndTabItem()\n        end\n\n        local di_tab_flags = 0\n        if switch_direct_input then\n            switch_direct_input = false\n            di_tab_flags = bit.bor(di_tab_flags, imgui.TabItemFlags.SetSelected)\n        end\n        if imgui.BeginTabItem(\"Direct Input\", nil, di_tab_flags) then\n            state = direct_input_state\n\n            local changed\n            imgui.PushItemWidth(-1)\n            changed, direct_input_text = imgui.InputTextMultiline(\"##directinput\", direct_input_text, 0, imgui.GetTextLineHeight() * 10)\n            imgui.PopItemWidth()\n            if changed then\n                load_animation(state, direct_input_text)\n            end\n            imgui.EndTabItem()\n        end\n\n        imgui.EndTabBar()\n    end\n\n    local error_count = #state.sprite_errors\n    if state.xml_error then\n        error_count = error_count + 1\n    end\n\n    if error_count > 0 and imgui.CollapsingHeader(\"Errors (\" .. error_count .. \")###sprite_errors\") then\n        if state.xml_error then\n            imgui.TextWrapped(state.xml_error)\n        end\n\n        for _, sprite_error in ipairs(state.sprite_errors) do\n            imgui.BulletText(sprite_error)\n        end\n    end\n\n    imgui.Separator()\n\n    if state.sprite then\n        if not state.current_animation then state.current_animation = state.sprite.default_animation end\n        if not state.sprite.rect_animations_by_name[state.current_animation] then\n            for _, rect_anim in ipairs(state.sprite.rect_animations) do\n                state.current_animation = rect_anim.name\n                break\n            end\n        end\n\n        imgui.SetNextItemWidth(190)\n        if imgui.BeginCombo(\"##anim\", state.current_animation) then\n            for i, rect_anim in pairs(state.sprite.rect_animations) do\n                if imgui.Selectable(rect_anim.name .. \"##\" .. i, rect_anim.name == state.current_animation) then\n                    state.current_animation = rect_anim.name\n                end\n            end\n            imgui.EndCombo()\n        end\n\n        local rect_anim = state.sprite.rect_animations_by_name[state.current_animation]\n\n        imgui.SameLine()\n        if imgui.Button(state.play and \"Pause\" or \"Play\") then\n            state.play = not state.play\n        end\n\n        if state.play then\n            state.time = state.time + 1/60\n            while state.time > rect_anim.frame_wait do\n                state.frame = (state.frame + 1) % rect_anim.frame_count\n                state.time = state.time - rect_anim.frame_wait\n            end\n        end\n\n        imgui.PushButtonRepeat(true)\n\n        imgui.SameLine()\n        if imgui.Button(\"<\") then\n            state.frame = state.frame - 1\n        end\n\n        local _\n        imgui.SameLine()\n        imgui.SetNextItemWidth(imgui.GetFontSize() * 2)\n        local frame_disp = state.frame + 1\n        _, frame_disp = imgui.InputInt(\"###cf\", frame_disp, 0)\n        state.frame = frame_disp-1\n\n        imgui.SameLine()\n        imgui.Text(\"/ \" .. rect_anim.frame_count)\n\n        imgui.SameLine()\n        if imgui.Button(\">\") then\n            state.frame = state.frame + 1\n        end\n\n        state.frame = state.frame % rect_anim.frame_count\n\n        imgui.PopButtonRepeat()\n\n        show_sprite_frame(state.sprite, state.current_animation, state.frame)\n    end\n\n    imgui.End()\nend\n\nreturn anim_viewer\n"
_TWWE_VFS["mods/component-explorer/compatibility.xml"] = "<Mod _format_version=\"0\" version_built_with=\"12\" >\n\n</Mod>\n\n"
