at(\"mVelocityY\", nil, component_id)\n        show_field_float(\"mAngle\", nil, component_id)\n        show_field_float(\"mMovementStepAccumulator\", nil, component_id)\n    end\n\nend\n\nfunction show_CutThroughWorldDoneHereComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_int(\"id_of_done_cut\", nil, component_id)\n    end\n\nend\n\nfunction show_DamageModelComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_double(\"hp\", \"hit points at the moment\", component_id)\n        show_field_double(\"max_hp\", \"the maximum hp that this can have, we'll set this when loading\", component_id)\n        show_field_double(\"max_hp_cap\", \"the maximum 'max_hp' that this can have, <= 0 means no limits. Used by perks such as GLASS_CANNON\", component_id)\n        show_field_double(\"max_hp_old\", \"used for UI rendering\", component_id)\n        show_field_float(\"critical_damage_resistance\", \"0.0 = all critical damage multiplier is applied. 1.0 = no critical damage multiplier is applied\", component_id)\n        show_field_int(\"invincibility_frames\", \"if positive, doesn't take damage\", component_id)\n        show_field_bool(\"falling_damages\", \"do we take fall damage\", component_id)\n        show_field_float(\"falling_damage_height_min\", \"how far do we need to fall to take damage, we start with this height, the peasant takes min damage from this\", component_id)\n        show_field_float(\"falling_damage_height_max\", \"after this the peasant always takes the maximum fall damage\", component_id)\n        show_field_float(\"falling_damage_damage_min\", \"when we fall over height_min we take this much, lineary ramping to damage_max\", component_id)\n        show_field_float(\"falling_damage_damage_max\", \"when we fall over height_min we take this much, lineary ramping to damage_max\", component_id)\n        show_field_bool(\"air_needed\", \"Do we breath, can we take damage from not breathing?\", component_id)\n        show_field_float(\"air_in_lungs\", \"How much air do we have in our lungs? - after the air runs out we take damage\", component_id)\n        show_field_float(\"air_in_lungs_max\", \"how much air can we have in our lungs, it's filled to this point if we're not in water\", component_id)\n        show_field_float(\"air_lack_of_damage\", \"(* dt)... damage in a second if we're in the water\", component_id)\n        show_field_float(\"minimum_knockback_force\", \"Minimum knockback force required to do the knockback\", component_id)\n        show_field_bool(\"materials_damage\", \"should materials do damage or not?\", component_id)\n        show_field_int(\"material_damage_min_cell_count\", \"if material damage is received from less than 'material_damage_min_cell_count' this frame, it is ignored\", component_id)\n        show_field_string(\"materials_that_damage\", \"list of materials that do damage, separated by ',' e.g. 'acid, fire, smoke'\", component_id)\n        show_field_string(\"materials_how_much_damage\", \"list of damage amount per material in materials_that_damage, separated by ','\", component_id)\n        show_field_bool(\"materials_damage_proportional_to_maxhp\", \"if damage from materials is proportional to max hp, instead of just damage\", component_id)\n        show_field_bool(\"physics_objects_damage\", \"if true, will take damage from physics objects that hit it\", component_id)\n        show_field_bool(\"materials_create_messages\", \"should collisions with certain materials create messages or not?\", component_id)\n        show_field_string(\"materials_that_create_messages\", \"list of materials that generate CollisionWithCell messages, separated by ',' e.g. 'acid, fire, smoke'\", component_id)\n        show_field_file_single(\"ragdoll_filenames_file\", \"the file from which to load a ragdoll on death'\", component_id)\n        show_field_string(\"ragdoll_material\", \"what material is the ragdoll made out of\", component_id)\n        show_field_float(\"ragdoll_offset_x\", \"where should the ragdoll be created relative to our entity position'\", component_id)\n        show_field_float(\"ragdoll_offset_y\", \"where should the ragdoll be created relative to our entity position'\", component_id)\n        show_field_string(\"blood_material\", \"this is the material that gets thrown as particles when this entity takes damage\", component_id)\n        show_field_string(\"blood_spray_material\", \"this is the material that gets thrown as particles when this entity sprays blood on death\", component_id)\n        show_field_bool(\"blood_spray_create_some_cosmetic\", \"if true, we force some blood spray particles to be cosmetic (can be enabled to avoid making a huge mess of blood spray)\", component_id)\n        show_field_float(\"blood_multiplier\", \"how much blood, this is the multiplier used for sprouting lots or little blood\", component_id)\n        show_field_int(\"ragdoll_blood_amount_absolute\", \"if > -1, this is the absolute amount of blood we share between particle emitters in the ragdoll\", component_id)\n        show_field_string(\"blood_sprite_directional\", \"this sprite is loaded at damage position if we take damage that creates a blood effect\", component_id)\n        show_field_string(\"blood_sprite_large\", \"this sprite is loaded at damage position if we take explosion/heavy damage\", component_id)\n        show_field_string(\"healing_particle_effect_entity\", \"if this is set, will load this entity as a child of this entity, when this entity is healed\", component_id)\n        show_field_bool(\"create_ragdoll\", \"if 0, we skip ragdoll creation on death\", component_id)\n        show_field_bool(\"ragdollify_child_entity_sprites\", \"if 1, we ragdollify child entity sprites\", component_id)\n        show_field_float(\"ragdollify_root_angular_damping\", \"If ragdoll_filenames_file= and > 0, the angular damping of the first ragdoll body is set to this value.\", component_id)\n        show_field_bool(\"ragdollify_disintegrate_nonroot\", \"If ragdoll_filenames_file= and true, all but the first sprite on the root entity will be disintegrated instead of being turned into physics bodies.\", component_id)\n        show_field_bool(\"wait_for_kill_flag_on_death\", \"if 1, we wont kill the entity along with kill fx and ragdoll until 'kill' is 1\", component_id)\n        show_field_bool(\"kill_now\", \"if 1, we wont kill the entity along with kill fx and ragdoll until 'kill_now' is 1\", component_id)\n        show_field_bool(\"drop_items_on_death\", \"drop the abilities as items on death?\", component_id)\n        show_field_bool(\"ui_report_damage\", \"If 1, damage numbers are displayed when this entity is damaged\", component_id)\n        show_field_bool(\"ui_force_report_damage\", \"If 1, damage numbers are displayed when this entity is damaged, even if the numbers are disabled in settings\", component_id)\n        show_field_int(\"in_liquid_shooting_electrify_prob\", \"when shooting underwater how likely are we to electrify the water\", component_id)\n        show_field_float(\"wet_status_effect_damage\", \"how much damage per 10 frames is done if entity has 'wet' status effect\", component_id)\n        show_field_bool(\"is_on_fire\", \"Tells us we're on fire or not\", component_id)\n        show_field_float(\"fire_probability_of_ignition\", \"what is the probability that we'll ignite, 0 means won't ever ignite\", component_id)\n        show_field_int(\"fire_how_much_fire_generates\", \"how many fire particles do we generate each frame\", component_id)\n        show_field_float(\"fire_damage_ignited_amount\", \"how much damage does being ignited do?\", component_id)\n        show_field_float(\"fire_damage_amount\", \"how much damage does fire do?, 0.2 is pretty good\", component_id)\n        show_field_int(\"mLastElectricityResistanceFrame\", \"Last frame electricity has no effect. Should not be private!\", component_id)\n        show_field_int(\"mLastFrameReportedBlock\", \"Last frame a damage block message was displayed for this entity\", component_id)\n        show_field_int(\"mLastMaxHpChangeFrame\", \"used for UI rendering\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_bool(\"mIsOnFire\", \"private variable to check when we're on fire and not\", component_id)\n        show_field_int(\"mFireProbability\", \"this gets decreased if we can't ignite anything else\", component_id)\n        show_field_int(\"mFireFramesLeft\", \"this is the remaining frames we're on fire\", component_id)\n        show_field_int(\"mFireDurationFrames\", \"this is the total duration in frames we're on fire\", component_id)\n        show_field_bool(\"mFireTriedIgniting\", \"private variable to check when we could have been ignited or not\", component_id)\n        show_field_int(\"mLastCheckX\", \"an optimization, so we don't have to check everything every frame\", component_id)\n        show_field_int(\"mLastCheckY\", \"an optimization, so we don't have to check everything every frame\", component_id)\n        show_field_int(\"mLastCheckTime\", \"an optimization, so we don't have to check everything every frame\", component_id)\n        show_field_material_id(\"mLastMaterialDamageFrame\", \"this is the last frame we took material damage\", component_id)\n        show_field_bool(\"mFallIsOnGround\", \"for fall damage, keeps a private variable about if we're on ground or not\", component_id)\n        show_field_float(\"mFallHighestY\", \"private var to keep track of how high have we flown to\", component_id)\n        show_field_int(\"mFallCount\", \"how many times have we fallen? This is used to make sure we don't take damage from the first fall\", component_id)\n        show_field_bool(\"mAirAreWeInWater\", \"a private variable to track our state in drowning\", component_id)\n        show_field_int(\"mAirFramesNotInWater\", \"how many frames have been with air to breathe\", component_id)\n        show_field_bool(\"mAirDoWeHave\", \"a private variable to track our state in drowning\", component_id)\n        show_field_int(\"mTotalCells\", \"how many cells are there total\", component_id)\n        show_field_int(\"mLiquidCount\", \"how many of the cells are liquid\", component_id)\n        show_field_material_id(\"mLiquidMaterialWeAreIn\", \"stores the liquid material we're in... may not be the most accurate\", component_id)\n        show_field_material_id_list(\"mDamageMaterials\", \"NOTE! Sorted! a list of materials that do damage (materials_that_damage)\", component_id)\n        show_field_ro_list(\"mDamageMaterialsHowMuch\", \"NOTE! Sorted! a list of materials that do damage (materials_that_damage)\", component_id)\n        show_field_material_id_list(\"mCollisionMessageMaterials\", \"NOTE! Sorted! a list of materials that create messages (materials_that_create_messages)\", component_id)\n        show_field_ro_list(\"mCollisionMessageMaterialCountsThisFrame\", \"Number of cells per collided with this frame. Order matches mCollisionMessageMaterials\", component_id)\n        show_field_ro_list(\"mMaterialDamageThisFrame\", \"A list of damage per material that damages us. In same order as materials\", component_id)\n        show_field_float(\"mFallDamageThisFrame\", \"Amount of fall damage received this frame\", component_id)\n        show_field_float(\"mElectricityDamageThisFrame\", \"Amount of electricity damage received this frame\", component_id)\n        show_field_float(\"mPhysicsDamageThisFrame\", \"max physics damage we have taken this round\", component_id)\n        show_field_vec2(\"mPhysicsDamageVecThisFrame\", \"direction of physics damage\", component_id)\n        show_field_int(\"mPhysicsDamageLastFrame\", \"frame number when we took physics damage\", component_id)\n        show_field_EntityTypeID(\"mPhysicsDamageEntity\", \"the physics entity that hit us\", component_id)\n        show_field_EntityTypeID(\"mPhysicsDamageTelekinesisCasterEntity\", \"who moved an object that hit us via telekinesis\", component_id)\n        show_field_int(\"mLastDamageFrame\", \"frame number when we took any damage\", component_id)\n        show_field_double(\"mHpBeforeLastDamage\", \"how much hp did we have a while ago?\", component_id)\n        show_field_float(\"mFireDamageBuffered\", \"used to optimized cases where lots of entities are taking fire damage\", component_id)\n        show_field_int(\"mFireDamageBufferedNextDeliveryFrame\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Objects\") then\n        local object_open = imgui.TreeNode(\"damage_multipliers ConfigDamagesByType\")\n        imgui.SameLine()\n        help.marker(\"the multipliers applied to different types of damage\")\n        if object_open then\n            show_ConfigDamagesByType_fields(\"damage_multipliers\", \"the multipliers applied to different types of damage\", component_id)\n            imgui.TreePop()\n        end\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_enum(\"ragdoll_fx_forced\", \"if set, will force this ragdoll fx to happen everytime\", component_id, ragdoll_fx)\n    end\n\nend\n\nfunction show_DamageNearbyEntitiesComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_float(\"radius\", nil, component_id)\n        show_field_float(\"damage_min\", nil, component_id)\n        show_field_float(\"damage_max\", nil, component_id)\n        show_field_float(\"target_vec_max_len\", nil, component_id)\n        show_field_float(\"knockback_multiplier\", nil, component_id)\n        show_field_int(\"time_between_damaging\", nil, component_id)\n        show_field_string(\"damage_description\", nil, component_id)\n        show_field_string(\"target_tag\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_vec2(\"mVelocity\", nil, component_id)\n        show_field_int(\"mNextDamageFrame\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_enum(\"damage_type\", \"the damage type\", component_id, damage_types)\n        show_field_enum(\"ragdoll_fx\", nil, component_id, ragdoll_fx)\n    end\n\nend\n\nfunction show_DebugFollowMouseComponent_fields(entity_id, component_id, data)end\n\nfunction show_DebugLogMessagesComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_float(\"TEMP_TEMPY\", nil, component_id)\n        show_field_float(\"TEMP_TEMP_TEMP\", nil, component_id)\n    end\n\nend\n\nfunction show_DebugSpatialVisualizerComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_float(\"min_x\", nil, component_id)\n        show_field_float(\"min_y\", nil, component_id)\n        show_field_float(\"max_x\", nil, component_id)\n        show_field_float(\"max_y\", nil, component_id)\n        show_field_abgr(\"color\", nil, component_id)\n    end\n\nend\n\nfunction show_DieIfSpeedBelowComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_float(\"min_speed\", \"The entity that owns this component is killed if its speed (via VelocityComponent) falls below this value.\", component_id)\n        show_field_float(\"mMinSpeedSquared\", nil, component_id)\n    end\n\nend\n\nfunction show_DroneLauncherComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_file_single(\"drone_entity_file\", nil, component_id)\n    end\n\nend\n\nfunction show_DrugEffectComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Objects\") then\n        local object_open = imgui.TreeNode(\"drug_fx_target ConfigDrugFx\")\n        if object_open then\n            show_ConfigDrugFx_fields(\"drug_fx_target\", nil, component_id)\n            imgui.TreePop()\n        end\n        local object_open = imgui.TreeNode(\"m_drug_fx_current ConfigDrugFx\")\n        if object_open then\n            show_ConfigDrugFx_fields(\"m_drug_fx_current\", nil, component_id)\n            imgui.TreePop()\n        end\n    end\n\nend\n\nfunction show_DrugEffectModifierComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Objects\") then\n        local object_open = imgui.TreeNode(\"fx_add ConfigDrugFx\")\n        if object_open then\n            show_ConfigDrugFx_fields(\"fx_add\", nil, component_id)\n            imgui.TreePop()\n        end\n        local object_open = imgui.TreeNode(\"fx_multiply ConfigDrugFx\")\n        if object_open then\n            show_ConfigDrugFx_fields(\"fx_multiply\", nil, component_id)\n            imgui.TreePop()\n        end\n    end\n\nend\n\nfunction show_ElectricChargeComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_int(\"charge_time_frames\", nil, component_id)\n        show_field_float(\"fx_velocity_max\", nil, component_id)\n        show_field_int(\"electricity_emission_interval_frames\", nil, component_id)\n        show_field_int(\"fx_emission_interval_min\", nil, component_id)\n        show_field_int(\"fx_emission_interval_max\", nil, component_id)\n        show_field_int(\"charge\", nil, component_id)\n    end\n\nend\n\nfunction show_ElectricityComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_int(\"energy\", nil, component_id)\n        show_field_float(\"probability_to_heat\", nil, component_id)\n        show_field_int(\"speed\", nil, component_id)\n        show_field_int(\"splittings_min\", nil, component_id)\n        show_field_int(\"splittings_max\", nil, component_id)\n        show_field_int(\"splitting_energy_min\", nil, component_id)\n        show_field_int(\"splitting_energy_max\", nil, component_id)\n        show_field_bool(\"hack_is_material_crack\", nil, component_id)\n        show_field_bool(\"hack_crack_ice\", nil, component_id)\n        show_field_bool(\"hack_is_set_fire\", \"if set will set the thing on fire where this is located at\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_int(\"mSplittingsLeft\", nil, component_id)\n        show_field_int(\"mSplittingEnergy\", nil, component_id)\n        show_field_vec2(\"mAvgDir\", nil, component_id)\n        show_field_ivec2(\"mPrevPos\", nil, component_id)\n        show_field_material_id(\"mPrevMaterial\", nil, component_id)\n        show_field_bool(\"mShouldPlaySound\", nil, component_id)\n    end\n\nend\n\nfunction show_ElectricityReceiverComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_int(\"offset_x\", nil, component_id)\n        show_field_int(\"offset_y\", nil, component_id)\n        show_field_int(\"radius\", nil, component_id)\n        show_field_int(\"active_time_frames\", nil, component_id)\n        show_field_int(\"switch_on_msg_interval_frames\", nil, component_id)\n        show_field_int(\"electrified_msg_interval_frames\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_int(\"mLastFrameElectrified\", nil, component_id)\n        show_field_int(\"mNextElectrifiedMsgFrame\", nil, component_id)\n        show_field_int(\"mNextSwitchOnMsgFrame\", nil, component_id)\n    end\n\nend\n\nfunction show_ElectricitySourceComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_int(\"radius\", nil, component_id)\n        show_field_int(\"emission_interval_frames\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_int(\"mNextFrameEmitElectricity\", nil, component_id)\n    end\n\nend\n\nfunction show_EndingMcGuffinComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_float(\"TEMP_TEMPY\", nil, component_id)\n        show_field_float(\"TEMP_TEMP_TEMP\", nil, component_id)\n    end\n\nend\n\nfunction show_EnergyShieldComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_float(\"radius\", nil, component_id)\n        show_field_float(\"damage_multiplier\", nil, component_id)\n        show_field_float(\"max_energy\", nil, component_id)\n        show_field_float(\"energy_required_to_shield\", nil, component_id)\n        show_field_float(\"recharge_speed\", nil, component_id)\n        show_field_float(\"sector_degrees\", \"if less than 180 we only provide partial cover to the current direction of the entity\", component_id)\n        show_field_float(\"energy\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_vec2(\"mPrevPosition\", nil, component_id)\n    end\n\nend\n\nfunction show_ExplodeOnDamageComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_float(\"explode_on_death_percent\", \"rolls a dice (0 - 1) if we explode on death\", component_id)\n        show_field_float(\"explode_on_damage_percent\", \"rolls a dice (0 - 1) if we explode on damage\", component_id)\n        show_field_float(\"physics_body_modified_death_probability\", \"if we get message about the physics body being modified, do we explode on what percent\", component_id)\n        show_field_float(\"physics_body_destruction_required\", \"how big of percent of our body, do we need to lose before we explode\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_bool(\"mDone\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Objects\") then\n        local object_open = imgui.TreeNode(\"config_explosion ConfigExplosion\")\n        imgui.SameLine()\n        help.marker(\"if we have explosion, it's the setup for it\")\n        if object_open then\n            show_ConfigExplosion_fields(\"config_explosion\", \"if we have explosion, it's the setup for it\", component_id)\n            imgui.TreePop()\n        end\n    end\n\nend\n\nfunction show_ExplosionComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_int(\"timeout_frames\", \"for timer\", component_id)\n        show_field_int(\"timeout_frames_random\", \"a random value between 0 and 'timout_frames_random' is added to timer\", component_id)\n        show_field_bool(\"kill_entity\", \"if 1, we kill the entity when exploding\", component_id)\n        show_field_int(\"mTimerTriggerFrame\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Objects\") then\n        local object_open = imgui.TreeNode(\"config_explosion ConfigExplosion\")\n        imgui.SameLine()\n        help.marker(\"setup for out explosion\")\n        if object_open then\n            show_ConfigExplosion_fields(\"config_explosion\", \"setup for out explosion\", component_id)\n            imgui.TreePop()\n        end\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_enum(\"trigger\", \"what triggers the explosion\", component_id, explosion_trigger_type)\n    end\n\nend\n\nfunction show_FishAIComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_int(\"direction\", nil, component_id)\n        show_field_float(\"speed\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_vec2(\"velocity\", nil, component_id)\n        show_field_int(\"stuck_counter\", nil, component_id)\n        show_field_vec2(\"mLastCheckPos\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_vec2(\"aabb_min\", nil, component_id)\n        show_field_vec2(\"aabb_max\", nil, component_id)\n    end\n\nend\n\nfunction show_FlyingComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_int(\"type\", \"type of flight, 1 = perlin noise\", component_id)\n        show_field_float(\"perlin_freq\", \"frequency of the perlin noise sampling\", component_id)\n        show_field_float(\"perlin_time_freq\", \"t *= perlin_time_freq\", component_id)\n        show_field_float(\"perlin_wind_x\", \"wind velocity that gets added to the samples\", component_id)\n        show_field_float(\"perlin_wind_y\", \"wind velocity that gets added to the samples\", component_id)\n    end\n\nend\n\nfunction show_FogOfWarRadiusComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_float(\"radius\", \"256 is the default player has\", component_id)\n    end\n\nend\n\nfunction show_FogOfWarRemoverComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_float(\"radius\", nil, component_id)\n    end\n\nend\n\nfunction show_GameAreaEffectComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_float(\"radius\", \"what's the radius (in pixels) of the area effect\", component_id)\n        show_field_string(\"collide_with_tag\", \"the tags we're looking for\", component_id)\n        show_field_int(\"frame_length\", \"if not 0 will reapply this effect after this many frames have gone by\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_vector_entityid(\"mEntitiesAppliedOutTo\", nil, component_id)\n        show_field_ro_list(\"mEntitiesAppliedFrame\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_ro_list(\"game_effect_entitities\", \"just a vector of the game_effect entities\", component_id)\n    end\n\nend\n\nfunction show_GameEffectComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_string(\"custom_effect_id\", \"if 'effect' is set to 'CUSTOM', this will define effect uniqueness.\", component_id)\n        show_field_int(\"frames\", \"how many frames does it affect -1 = forever\", component_id)\n        show_field_int(\"exclusivity_group\", \"if > 0, previous game effects with the same exclusivity group as new one will be removed when calling LoadGameEffectEntityTo\", component_id)\n        show_field_bool(\"report_block_msg\", \"to disable the block message that rises\", component_id)\n        show_field_bool(\"disable_movement\", \"if set, will disable movement\", component_id)\n        show_field_file_single(\"ragdoll_effect_custom_entity_file\", \"an entity that is loaded to each ragdoll part if 'ragdoll_effect' is set to 'CUSTOM_RAGDOLL_ENTITY'\", component_id)\n        show_field_bool(\"ragdoll_fx_custom_entity_apply_only_to_largest_body\", \"if 1, 'ragdoll_effect_custom_entity_file' is loaded only to the largest piece in the ragdoll \", component_id)\n        show_field_file_single(\"polymorph_target\", \"when doing a polymorph, this is what we convert it to\", component_id)\n        show_field_USTRING(\"mSerializedData\", \"polymorph stores the serialized entity here...\", component_id)\n        show_field_EntityID(\"mCaster\", \"Contains a handle to the caster of this GameEffect\", component_id)\n        show_field_int(\"mCasterHerdId\", \"Contains the herd if of the caster of this GameEffect\", component_id)\n        show_field_int(\"teleportation_probability\", \"How likely is it that we teleport, larger = less often\", component_id)\n        show_field_int(\"teleportation_delay_min_frames\", \"Never teleports more often that this\", component_id)\n        show_field_float(\"teleportation_radius_min\", nil, component_id)\n        show_field_float(\"teleportation_radius_max\", nil, component_id)\n        show_field_int(\"teleportations_num\", \"How many times has this GameEffectComponent teleported the owner?\", component_id)\n        show_field_double(\"no_heal_max_hp_cap\", \"If current hp is less than this, we store it here. Then we make sure the hp never exceeds this.\", component_id)\n        show_field_bool(\"caused_by_ingestion_status_effect\", \"Did this effect occur because someone ate something?\", component_id)\n        show_field_bool(\"caused_by_stains\", \"was this caused by stains\", component_id)\n        show_field_bool(\"mCharmDisabledCameraBound\", \"When charmed, will try to disable CameraBound. This keeps track if we've done it, so we can enable it back\", component_id)\n        show_field_bool(\"mCharmEnabledTeleporting\", \"When charmed, will try to enable teleporting (tag:teleportable_NOT). This keeps track if we've done it, so we can disable it again\", component_id)\n        show_field_bool(\"mInvisible\", \"Are we invisible?\", component_id)\n        show_field_int(\"mCounter\", \"Counts stuff\", component_id)\n        show_field_int(\"mCooldown\", \"Counts cooldown\", component_id)\n        show_field_bool(\"mIsExtension\", \"If 1, this is an effect extension and shouldn't create an extension when removed\", component_id)\n        show_field_bool(\"mIsSpent\", \"NOTE( Petri ): 29.4.2024 - this is used internally to make RESPAWN perk disabled in the UI\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_enum(\"effect\", \"GAME_EFFECT\", component_id, game_effect)\n        show_field_enum(\"ragdoll_effect\", \"if set, will use this for ragdoll effect\", component_id, ragdoll_fx)\n        show_field_material_id(\"ragdoll_material\", \"converts to string name of the material that ragdoll is made out of\", component_id)\n        -- show_field_StatusEffectType(\"causing_status_effect\", \"Status effect that caused this game effect, if any\", component_id)\n        show_field_unsupported(\"causing_status_effect\", \"Status effect that caused this game effect, if any\", component_id, \"StatusEffectType\")\n    end\n\nend\n\nfunction show_GameLogComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_bool(\"report_death\", \"switches on reporting things\", component_id)\n        show_field_bool(\"report_damage\", \"if set, will report when receiving damage\", component_id)\n        show_field_bool(\"report_new_biomes\", \"if false, won't report when player enters new biomes\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_int(\"mNewBiomeCheckFrame\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_VISITED_VEC(\"mVisitiedBiomes\", \"list of visited biomes\", component_id)\n    end\n\nend\n\nfunction show_GameStatsComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_string(\"name\", \"no one uses the name variable on entity, so we have to do this to make it happen\", component_id)\n        show_field_string(\"stats_filename\", \"also generated from the gunk\", component_id)\n        show_field_bool(\"is_player\", \"if true, will use the session file for loading stats\", component_id)\n        show_field_string(\"extra_death_msg\", \"set when e.g. polymorphed\", component_id)\n        show_field_bool(\"dont_do_logplayerkill\", \"if 1, StatsLogPlayerKill must be manually called from lua\", component_id)\n        show_field_int(\"player_polymorph_count\", \"skip loading of stats if this higher than 0 and decrament this by one\", component_id)\n    end\n\nend\n\nfunction show_GasBubbleComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_float(\"acceleration\", nil, component_id)\n        show_field_float(\"max_speed\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_float(\"mVelocity\", nil, component_id)\n    end\n\nend\n\nfunction show_GenomeDataComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_bool(\"is_predator\", \"Predators are considered threats by other species and hunt for food.\", component_id)\n        show_field_float(\"food_chain_rank\", \"0 means king of the hill. Greater number = more likely to get eaten by other species.\", component_id)\n        show_field_bool(\"berserk_dont_attack_friends\", \"if 1, this animal will not try to attack player who would normally be its friend\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_LensValue_bool(\"friend_thundermage\", \"if 1, thunder mage doesn't attack this\", component_id)\n        show_field_LensValue_bool(\"friend_firemage\", \"if 1, fire mage doesn't attack this\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_enum(\"herd_id\", \"This is used for example to separate people in different tribes.\", component_id, herd_id_values)\n    end\n\nend\n\nfunction show_GhostComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_float(\"speed\", \"pixels per second\", component_id)\n        show_field_int(\"new_hunt_target_check_every\", \"how often do we look for targets\", component_id)\n        show_field_float(\"hunt_box_radius\", nil, component_id)\n        show_field_float(\"aggressiveness\", \"if higher than relations then will attack\", component_id)\n        show_field_float(\"max_distance_from_home\", \"how far from home can we go?\", component_id)\n        show_field_bool(\"die_if_no_home\", \"if set to false will die, if it can't find home\", component_id)\n        show_field_string(\"target_tag\", \"if something else (like mortal), will attack the home\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_EntityID(\"mEntityHome\", \"where is our home?\", component_id)\n        show_field_int(\"mFramesWithoutHome\", nil, component_id)\n        show_field_vec2(\"mTargetPosition\", nil, component_id)\n        show_field_int(\"mTargetEntityId\", nil, component_id)\n        show_field_vec2(\"mRandomTarget\", nil, component_id)\n        show_field_int(\"mNextTargetCheckFrame\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_vec2(\"velocity\", nil, component_id)\n    end\n\nend\n\nfunction show_GodInfoComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_float(\"mana_current\", \"How much mana the player now has to use\", component_id)\n        show_field_float(\"mana_max\", \"Max size of the mana pool\", component_id)\n        show_field_float(\"gold\", \"How much gold the player has\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        -- show_field_Entity*(\"god_entity\", nil, component_id)\n        show_field_unsupported(\"god_entity\", nil, component_id, \"Entity*\")\n    end\n\nend\n\nfunction show_GunComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Privates\") then\n        -- show_field_LuaManager*(\"mLuaManager\", nil, component_id)\n        show_field_unsupported(\"mLuaManager\", nil, component_id, \"LuaManager*\")\n    end\n\nend\n\nfunction show_HealthBarComponent_fields(entity_id, component_id, data)end\n\nfunction show_HitEffectComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_int(\"value\", \"Usage depends on selected 'effect_hit'\", component_id)\n        show_field_string(\"value_string\", \"Usage depends on selected 'effect_hit'\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_enum(\"condition_effect\", \"Hit entity needs to have this 'GAME_EFFECT' for effects to apply. If both 'condition_effect' and 'condition_status' are set, they are combined with AND logic\", component_id, game_effect)\n        -- show_field_StatusEffectType(\"condition_status\", \"Hit entity needs to have this 'STATUS_EFFECT' for effects to apply\", component_id)\n        show_field_unsupported(\"condition_status\", \"Hit entity needs to have this 'STATUS_EFFECT' for effects to apply\", component_id, \"StatusEffectType\")\n        show_field_enum(\"effect_hit\", \"What kind of 'HIT_EFFECT' is applied to hit entity if condition is true\", component_id, hit_effect)\n    end\n\nend\n\nfunction show_HitboxComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_bool(\"is_player\", nil, component_id)\n        show_field_bool(\"is_enemy\", nil, component_id)\n        show_field_bool(\"is_item\", nil, component_id)\n        show_field_float(\"aabb_min_x\", nil, component_id)\n        show_field_float(\"aabb_max_x\", nil, component_id)\n        show_field_float(\"aabb_min_y\", nil, component_id)\n        show_field_float(\"aabb_max_y\", nil, component_id)\n        show_field_float(\"damage_multiplier\", \"All damage from hits to this hitbox is multiplied with this value before applying it.\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_bool(\"dead\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_vec2(\"offset\", nil, component_id)\n    end\n\nend\n\nfunction show_HomingComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_string(\"target_tag\", nil, component_id)\n        show_field_bool(\"target_who_shot\", \"If 1, targets who shot