ta)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_bool(\"is_emitting\", \"If 1, will emit all the time\", component_id)\n        show_field_int(\"emit_until_frame\", \"Can be used to activate a laser temporarily\", component_id)\n        show_field_float(\"laser_angle_add_rad\", \"Beam angle = entity angle + laser_angle_add_rad\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Objects\") then\n        local object_open = imgui.TreeNode(\"laser ConfigLaser\")\n        if object_open then\n            show_ConfigLaser_fields(\"laser\", nil, component_id)\n            imgui.TreePop()\n        end\n    end\n\nend\n\nfunction show_LevitationComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_float(\"radius\", \"the radius in which we look for entities / bodies to float\", component_id)\n        show_field_float(\"entity_force\", \"how much do we apply the mouse movements to the entitiy\", component_id)\n        show_field_float(\"box2d_force\", \"how much do we apply the mouse movements to the entitiy\", component_id)\n        show_field_int(\"effect_lifetime_frames\", nil, component_id)\n    end\n\nend\n\nfunction show_LifetimeComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_int(\"lifetime\", \"if anything else than -1 will kill this entity when this many frames have passed\", component_id)\n        show_field_bool(\"fade_sprites\", \"if 1, sprites will be faded as lifetime gets lower\", component_id)\n        show_field_bool(\"kill_parent\", \"if 1, will kill the parent entity\", component_id)\n        show_field_bool(\"kill_all_parents\", \"if 1, will kill all the parents entity\", component_id)\n        show_field_bool(\"serialize_duration\", \"if 1, will retain kill_frame and creation_frame over serialization\", component_id)\n        show_field_int(\"kill_frame_serialized\", \"frame that this is killed at\", component_id)\n        show_field_int(\"creation_frame_serialized\", \"frame that this is killed at\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_int(\"creation_frame\", \"we'll set this to GG.GetFrameNum() when this component is created\", component_id)\n        show_field_int(\"kill_frame\", \"frame that this is killed at\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_ValueRange(\"randomize_lifetime\", \"this is added to the lifetime\", component_id)\n    end\n\nend\n\nfunction show_LightComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_bool(\"update_properties\", \"turn this on if you expect this to function like the other components\", component_id)\n        show_field_float(\"radius\", \"The radius of the light in world pixels.\", component_id)\n        show_field_int(\"r\", \"Color red 0-255\", component_id)\n        show_field_int(\"g\", \"Color green 0-255\", component_id)\n        show_field_int(\"b\", \"Color blue 0-255\", component_id)\n        show_field_float(\"offset_x\", \"Offset from the center of entity.\", component_id)\n        show_field_float(\"offset_y\", \"Offset from the center of entity.\", component_id)\n        show_field_float(\"fade_out_time\", \"time in seconds, if not 0, this is how long this takes to die, when the component is destroyed\", component_id)\n        show_field_float(\"blinking_freq\", \"if less than 1, will blink randomly when rand() < blinking_freq\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_float(\"mAlpha\", nil, component_id)\n        -- show_field_as_Sprite*(\"mSprite\", nil, component_id)\n        show_field_unsupported(\"mSprite\", nil, component_id, \"as::Sprite*\")\n    end\n\nend\n\nfunction show_LightningComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_file_single(\"sprite_lightning_file\", \"particle effect, from where the file is loaded that lightning is generated from\", component_id)\n        show_field_bool(\"is_projectile\", \"if this is true, it's a projectile lightning and looks for ProjectileComponent and uses the data from there to move it\", component_id)\n        show_field_int(\"explosion_type\", \"1 = lightning trail\", component_id)\n        show_field_int(\"arc_lifetime\", \"remaining number of frames the arc exists\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_vec2(\"mExPosition\", \"stores the ex position of this entity\", component_id)\n        show_field_EntityID(\"mArcTarget\", \"if 'mArcTarget' points to an existing entity a lighting arc will be created between this entity and 'mArcTarget'\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Objects\") then\n        local object_open = imgui.TreeNode(\"config_explosion ConfigExplosion\")\n        if object_open then\n            show_ConfigExplosion_fields(\"config_explosion\", nil, component_id)\n            imgui.TreePop()\n        end\n    end\n\nend\n\nfunction show_LimbBossComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_int(\"state\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_int(\"mStatePrev\", nil, component_id)\n        show_field_float(\"mMoveToPositionX\", nil, component_id)\n        show_field_float(\"mMoveToPositionY\", nil, component_id)\n    end\n\nend\n\nfunction show_LiquidDisplacerComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_int(\"radius\", nil, component_id)\n        show_field_float(\"velocity_x\", nil, component_id)\n        show_field_float(\"velocity_y\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_int(\"mPrevX\", nil, component_id)\n        show_field_int(\"mPrevY\", nil, component_id)\n    end\n\nend\n\nfunction show_LoadEntitiesComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_file_single(\"entity_file\", \"path to the entity file we should load\", component_id)\n        show_field_bool(\"kill_entity\", \"if 1, we kill our entity when it is created\", component_id)\n        show_field_int(\"timeout_frames\", \"for timer\", component_id)\n        show_field_int(\"mTimerTriggerFrame\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_ValueRangeInt(\"count\", \"how many entities should be loaded (random range)\", component_id)\n    end\n\nend\n\nfunction show_LocationMarkerComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_int(\"id\", nil, component_id)\n    end\n\nend\n\nfunction show_LooseGroundComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_float(\"probability\", \"how often do we do this... shoots a ray in random direction and does the loosening\", component_id)\n        show_field_int(\"max_durability\", \"if material durability > max_durability, it is not loosened\", component_id)\n        show_field_float(\"max_distance\", \"how far raytraces to find things to loosen up\", component_id)\n        show_field_float(\"max_angle\", \"how much raytraces go to different directions around the up-vector. pi=full circle\", component_id)\n        show_field_int(\"min_radius\", \"the minimum radius of our loosening of pixels\", component_id)\n        show_field_int(\"max_radius\", \"the maximum radius of our loosening of pixels\", component_id)\n        show_field_float(\"chunk_probability\", \"if > 0, will drop box2d chunks of the ceiling\", component_id)\n        show_field_float(\"chunk_max_angle\", \"how much raytraces go to different directions around the up-vector. pi=full circle\", component_id)\n        show_field_int(\"chunk_count\", \"how many chunks are we allowed to do, -1 = infinite\", component_id)\n        show_field_string(\"collapse_images\", \"loads these files randomly to do the collapse shapes\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_int(\"mChunkCount\", \"how many chunks are we allowed to do, -1 = infinite\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_material_id(\"chunk_material\", \"String name of chunk material\", component_id)\n    end\n\nend\n\nfunction show_LuaComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_file_single(\"script_source_file\", nil, component_id)\n        show_field_bool(\"execute_on_added\", nil, component_id)\n        show_field_bool(\"execute_on_removed\", nil, component_id)\n        show_field_int(\"execute_every_n_frame\", \"1 = execute every frame. 2 = execute every second frame. 3 = execute every third frame and so on. -1 = execute only on add/remove/event\", component_id)\n        show_field_int(\"execute_times\", \"How many times should the script be executed? < 1 means infinite\", component_id)\n        show_field_int(\"limit_how_many_times_per_frame\", \"-1 = infinite. Use this to limit how many times this can be executed per frame. Currently only used to limit script_shot from being executed forever.\", component_id)\n        show_field_int(\"limit_to_every_n_frame\", \"-1 = no limit. Currently only used to limit script_shot from being executed every frame.\", component_id)\n        show_field_bool(\"limit_all_callbacks\", \"NOTE( Petri ): 19.8.2023 - by default limit_how_many_times_per_frame and limit_to_every_n_frame only works for script_shot. If this is set to true, will limit all callbacks. Also note that this limit is shared within this component. So if this is true and both script_shot and script_damage_received and both are called within limit_to_every_n_frame frames, only one of them will be called.\", component_id)\n        show_field_bool(\"remove_after_executed\", nil, component_id)\n        show_field_bool(\"enable_coroutines\", nil, component_id)\n        show_field_bool(\"call_init_function\", \" if 1, calls function init( entity_id:int ) after running the code in the file scope of script_source_file along with all mod appends. Does nothing if execute_on_added is 0\", component_id)\n        show_field_file_single(\"script_enabled_changed\", \"if set, calls function 'enabled_changed( entity_id:int, is_enabled:bool )' when the IsEnabled status of this LuaComponent is changed\", component_id)\n        show_field_file_single(\"script_damage_received\", \"if set, calls function 'damage_received( damage:number, message:string, entity_thats_responsible:int, is_fatal:bool, projectile_thats_responsible:int )' when we receive a message about damage (Message_DamageReceived)\", component_id)\n        show_field_file_single(\"script_damage_about_to_be_received\", \"if set, calls function 'damage_about_to_be_received( damage:number, x:number, y:number, entity_thats_responsible:int, critical_hit_chance:int )' when we receive a message (Message_DamageAboutToBeReceived) -> new_damage:number,new_critical_hit_chance:int\", component_id)\n        show_field_file_single(\"script_item_picked_up\", \"if set, calls function 'item_pickup( int entity_item, int entity_pickupper, string item_name )' when message 'Message_ItemPickUp' is called\", component_id)\n        show_field_file_single(\"script_shot\", \"if set, calls function 'shot( projectile_entity_id )' when we receive Message_Shot\", component_id)\n        show_field_file_single(\"script_collision_trigger_hit\", \"if set, calls function 'collision_trigger( colliding_entity_id )' when we receive Message_CollisionTriggerHit\", component_id)\n        show_field_file_single(\"script_collision_trigger_timer_finished\", \"if set, calls function 'collision_trigger_timer_finished()' when we receive Message_CollisionTriggerTimerFinished\", component_id)\n        show_field_file_single(\"script_physics_body_modified\", \"if set, calls function 'physics_body_modified( is_destroyed )' when physics body has been modified\", component_id)\n        show_field_file_single(\"script_pressure_plate_change\", \"if set, calls function 'pressure_plate_change( new_state )' when PressurePlateComponent decides that things have change\", component_id)\n        show_field_file_single(\"script_inhaled_material\", \"if set, calls function 'inhaled_material( material_name, count )' once per second for each inhaled material\", component_id)\n        show_field_file_single(\"script_death\", \"if set, calls function 'death( int damage_type_bit_field, string damage_message, int entity_thats_responsible, bool drop_items )' when we receive message Message_Death\", component_id)\n        show_field_file_single(\"script_throw_item\", \"if set, calls function 'throw_item( from_x, from_y, to_x, to_y )' when we receive message Message_ThrowItem\", component_id)\n        show_field_file_single(\"script_material_area_checker_failed\", \"if set, calls function 'material_area_checker_failed( pos_x, pos_y, )' when we receive message Message_MaterialAreaCheckerFailed\", component_id)\n        show_field_file_single(\"script_material_area_checker_success\", \"if set, calls function 'material_area_checker_success( pos_x, pos_y, )' when we receive message Message_MaterialAreaCheckerSuccess\", component_id)\n        show_field_file_single(\"script_electricity_receiver_switched\", \"if set, calls function 'electricity_receiver_switched( bool is_electrified )' when we receive message Message_ElectricityReceiverSwitched\", component_id)\n        show_field_file_single(\"script_electricity_receiver_electrified\", \"if set, calls function 'electricity_receiver_electrified()' when we receive message Message_ElectricityReceiverElectrified\", component_id)\n        show_field_file_single(\"script_kick\", \"if set, calls function 'kick( entity_who_kicked )' when we receive message Message_Kick\", component_id)\n        show_field_file_single(\"script_interacting\", \"if set, calls function 'interacting( entity_who_interacted, entity_interacted, interactable_name )' when we receive message Message_Interaction\", component_id)\n        show_field_file_single(\"script_audio_event_dead\", \"if set, calls function 'audio_event_dead( bank_file, event_root )' when we receive message Message_AudioEventDead\", component_id)\n        show_field_file_single(\"script_wand_fired\", \"if set, calls function 'wand_fired( gun_entity_id )' when we receive Message_WandFired\", component_id)\n        show_field_file_single(\"script_teleported\", \"if set, calls function 'teleported( from_x, from_y, to_x, to_y, bool portal_teleport )' when we receive Message_Teleported\", component_id)\n        show_field_file_single(\"script_portal_teleport_used\", \"if set, calls function 'portal_teleport_used( entity_that_was_teleported, from_x, from_y, to_x, to_y )' when we receive Message_PortalTeleportUsed\", component_id)\n        show_field_file_single(\"script_polymorphing_to\", \"if set, calls function 'polymorphing_to( string_entity_we_are_about_to_polymorph_to )' when we receive Message_PolymorphingTo\", component_id)\n        show_field_file_single(\"script_biome_entered\", \"if set, calls function 'biome_entered( string_biome_name, string_biome_old_name )' when this entity changes biomes. Requires BiomeTrackerComponent\", component_id)\n        show_field_int(\"mLastExecutionFrame\", nil, component_id)\n        show_field_int(\"mTimesExecutedThisFrame\", \"tracks how many times we've executed this frame. This will linger on and store the old value of the old frames. Used internally.\", component_id)\n        show_field_bool(\"mModAppendsDone\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_int(\"mNextExecutionTime\", nil, component_id)\n        show_field_int(\"mTimesExecuted\", nil, component_id)\n        -- show_field_LuaManager*(\"mLuaManager\", nil, component_id)\n        show_field_unsupported(\"mLuaManager\", nil, component_id, \"LuaManager*\")\n        -- show_field_ValueMap(\"mPersistentValues\", nil, component_id)\n        show_field_unsupported(\"mPersistentValues\", nil, component_id, \"ValueMap\")\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_enum(\"vm_type\", \"Do we share a single Lua virtual machine for everyone who runs 'script_source_file' ('SHARED_BY_MANY_COMPONENTS'), create one VM per one LuaComponent and reuse the VM in case the component runs the script multiple times ('ONE_PER_COMPONENT_INSTANCE'), or create a new VM every time the script is executed ('CREATE_NEW_EVERY_EXECUTION', deprecated)?\", component_id, lua_vm_type)\n    end\n\nend\n\nfunction show_MagicConvertMaterialComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_int(\"radius\", nil, component_id)\n        show_field_int(\"min_radius\", \"allows for convert to happen from x pixels from the center\", component_id)\n        show_field_bool(\"is_circle\", nil, component_id)\n        show_field_int(\"steps_per_frame\", nil, component_id)\n        show_field_string(\"from_material_tag\", \"the tag of material, e.g. [liquid]\", component_id)\n        show_field_bool(\"from_any_material\", \"if 1, converts any cells of any material to 'to_materia'\", component_id)\n        show_field_bool(\"clean_stains\", nil, component_id)\n        show_field_bool(\"extinguish_fire\", nil, component_id)\n        show_field_int(\"fan_the_flames\", \"if > 0, will call UpdateFire() fan_the_flames times\", component_id)\n        show_field_int(\"temperature_reaction_temp\", \"if != 0, will use the 'cold_freezes_to_materials' and 'warmth_melts_to_materials' in CellData to convert cells different materials\", component_id)\n        show_field_int(\"ignite_materials\", \"if > 0, will call Ignite() with ingite_materials as probability_of_fire\", component_id)\n        show_field_bool(\"loop\", nil, component_id)\n        show_field_bool(\"kill_when_finished\", nil, component_id)\n        show_field_bool(\"convert_entities\", \"if 1, kills entities with a damagemodel and converts them to 'to_material'\", component_id)\n        show_field_bool(\"stain_frozen\", \"petri hax\", component_id)\n        show_field_float(\"reaction_audio_amount\", \"if > 0, will generate chemical reaction audio at converted cells\", component_id)\n        show_field_bool(\"convert_same_material\", \"9.10.2020 - added this because at the end this caused the 'white ring' to appear, set it to false if you don't want constant whiteout\", component_id)\n        show_field_string(\"from_material_array\", nil, component_id)\n        show_field_string(\"to_material_array\", nil, component_id)\n        show_field_int(\"mRadius\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_bool(\"mUseArrays\", nil, component_id)\n        show_field_material_id_list(\"mFromMaterialArray\", nil, component_id)\n        show_field_material_id_list(\"mToMaterialArray\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_material_id(\"from_material\", nil, component_id)\n        show_field_material_id(\"to_material\", nil, component_id)\n    end\n\nend\n\nfunction show_MagicXRayComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_int(\"radius\", nil, component_id)\n        show_field_int(\"steps_per_frame\", nil, component_id)\n        show_field_int(\"mStep\", nil, component_id)\n        show_field_int(\"mRadius\", nil, component_id)\n    end\n\nend\n\nfunction show_ManaReloaderComponent_fields(entity_id, component_id, data)end\n\nfunction show_MaterialAreaCheckerComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_int(\"update_every_x_frame\", \"if something other than 0 or 1, will only update_every_x_frames \", component_id)\n        show_field_bool(\"look_for_failure\", \"if true, will send message Message_MaterialAreaCheckerFailed if the material doesn't exist. If false, will send a message Message_MaterialAreaCheckerSuccess if the aabb is full of material and material2\", component_id)\n        show_field_int(\"count_min\", \"If > 0, and look_for_failure=0, will send message if material count exceeds this number of cells\", component_id)\n        show_field_bool(\"always_check_fullness\", \"if 1, and look_for_failure=0, will always check the whole area for cells\", component_id)\n        show_field_bool(\"kill_after_message\", \"will kill this entity after sending the message\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_int(\"mPosition\", \"keeps track where we are\", component_id)\n        show_field_int(\"mLastFrameChecked\", \"keeps track of how often we've checked\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_types_aabb(\"area_aabb\", \"aabb offset, we check that this aabb contains only material\", component_id)\n        show_field_material_id(\"material\", \"String name of material that we check that the aabb contains\", component_id)\n        show_field_material_id(\"material2\", \"String name of material2 that we check that the aabb contains\", component_id)\n    end\n\nend\n\nfunction show_MaterialInventoryComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_bool(\"drop_as_item\", \"if true, drops a bag that the player can big up\", component_id)\n        show_field_bool(\"on_death_spill\", \"if true, on the death this will explode all the materials into air\", component_id)\n        show_field_bool(\"leak_gently\", \"NOTE( Petri ): 11.8.2023 - set this to false for old style leaky hidden piles situation.\", component_id)\n        show_field_float(\"leak_on_damage_percent\", \"if higher than 0 then it might leak when projectile damage happens\", component_id)\n        show_field_float(\"leak_pressure_min\", \"leak pressure coefficient\", component_id)\n        show_field_float(\"leak_pressure_max\", \"leak pressure coefficient\", component_id)\n        show_field_float(\"min_damage_to_leak\", \"the minimum damage that has to be done in order for a leak to occur\", component_id)\n        show_field_float(\"b2_force_on_leak\", \"if 0, nothing happens, elsewise will add a b2 force to the particleemitter which will push the b2body\", component_id)\n        show_field_float(\"death_throw_particle_velocity_coeff\", \"how far do we throw material particles on death?\", component_id)\n        show_field_bool(\"kill_when_empty\", \"if set, will send MessageDeath when materials are drained\", component_id)\n        show_field_bool(\"halftime_materials\", \"if true, will multiply the materials with the given halftimes\", component_id)\n        show_field_int(\"do_reactions\", \"NOTE( Petri ): 15.8.2023 - if > 0, will do CellReactions between the materials. Value is the percent chance of how often. 100 = every frame \", component_id)\n        show_field_bool(\"do_reactions_explosions\", \"requires do_reactions > 0 - are we allowed to do reaction explosions?\", component_id)\n        show_field_bool(\"do_reactions_entities\", \"requires do_reactions > 0 - are we allowed to load entities when doing reactions?\", component_id)\n        show_field_int(\"reaction_speed\", \"Note( Petri ): 17.8.2023 - how 'fast' do we let reactions happen. How many pixels of material do we convert at one time (5-10) seems like a nice speed.\", component_id)\n        show_field_bool(\"reactions_shaking_speeds_up\", \"Note( Petri ): 17.8.2023 - added the ability of shaking the bottle to cause reactions to happen quicker. \", component_id)\n        show_field_double(\"max_capacity\", \"how much materials we can store in total. < 0 = infinite\", component_id)\n        show_field_float(\"audio_collision_size_modifier_amount\", \"if > 0, 'fullness of this container' * 'audio_collision_size_modifier_amount' is added to collision audio event size\", component_id)\n        show_field_int(\"last_frame_drank\", \"last frame someone ingested from this via IngestionSystem\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_bool(\"is_death_handled\", nil, component_id)\n        show_field_vec2(\"ex_position\", \"used to figure out movement velocity\", component_id)\n        show_field_float(\"ex_angle\", \"used to figure out movement velocity\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        matinv_field.show_field_MATERIAL_VEC_DOUBLES(\"count_per_material_type\", \"Count of each material indexed by material type ID\", entity_id, component_id)\n    end\n\nend\n\nfunction show_MaterialSeaSpawnerComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_int(\"speed\", \"How many pixels to cover per one direction per one frame\", component_id)\n        show_field_float(\"sine_wavelength\", \"Parameters for sine wave that affects material spawn pattern\", component_id)\n        show_field_float(\"sine_amplitude\", \"Parameters for sine wave that affects material spawn pattern\", component_id)\n        show_field_double(\"noise_scale\", \"Parameters for noise that affects material spawn pattern\", component_id)\n        show_field_double(\"noise_threshold\", \"Parameters for noise that affects material spawn pattern\", component_id)\n        show_field_int(\"m_position\", nil, component_id)\n        show_field_int(\"frames_run\", \"to help keep the effect\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_material_id(\"material\", \"String name of material this creates\", component_id)\n        show_field_ivec2(\"size\", \"Size of the area to cover\", component_id)\n        show_field_ivec2(\"offset\", \"Offset of the center of the area to cover\", component_id)\n    end\n\nend\n\nfunction show_MaterialSuckerComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_int(\"material_type\", \"0 = liquid, 1 = sand, 2 = gas (arbitary order)\", component_id)\n        show_field_int(\"barrel_size\", \"how many pixels can we suck up\", component_id)\n        show_field_int(\"num_cells_sucked_per_frame\", \"How many cells at max can we suck per frame?\", component_id)\n        show_field_bool(\"set_projectile_to_liquid\", \"if set, will set the projectile what ever we're sucking...?\", component_id)\n        show_field_material_id(\"last_material_id\", \"hax... this is set if we use set_projectile_to_liquid\", component_id)\n        show_field_bool(\"suck_gold\", \"if set will just suck gold and update wallet\", component_id)\n        show_field_bool(\"suck_health\", \"if set will just suck healthium material and add 1 hp every sucked healthium\", component_id)\n        show_field_bool(\"suck_static_materials\", \"will suck static materials from the world\", component_id)\n        show_field_string(\"suck_tag\", \"if set, will only suck materials with this tag. NOTE, will also require the correct material_type to be set\", component_id)\n        show_field_int(\"mAmountUsed\", \"how full are we\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_int(\"mGoldAccumulator\", \"accumulates amount of gold picked during consecutive frames\", component_id)\n        show_field_int(\"mLastFramePickedGold\", \"last frame we picked gold\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_types_iaabb(\"randomized_position\", \"random offset for pos, where we look for pixels\", component_id)\n    end\n\nend\n\nfunction show_MoveToSurfaceOnCreateComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_float(\"lookup_radius\", nil, component_id)\n        show_field_float(\"offset_from_surface\", nil, component_id)\n        show_field_int(\"ray_count\", nil, component_id)\n        show_field_float(\"verlet_min_joint_distance\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_enum(\"type\", nil, component_id, movetosurface_type)\n    end\n\nend\n\nfunction show_MusicEnergyAffectorComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_float(\"energy_target\", \"the energy this makes music go towards\", component_id)\n        show_field_float(\"fade_range\", \"if > 0, fade between 0 and energy_target based on distance to this entity\", component_id)\n        show_field_bool(\"trigger_danger_music\", \"if 1, attempts to trigger danger music no matter what energy level is reached\", component_id)\n        show_field_int(\"fog_of_war_threshold\", \"if fog of war at position of this entity is greater than 'fog_of_war_threshold', this has  no effect\", component_id)\n        show_field_bool(\"is_enemy\", nil, component_id)\n        show_field_float(\"energy_lerp_up_speed_multiplier\", nil, component_id)\n    end\n\nend\n\nfunction show_NinjaRopeComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_float(\"max_length\", nil, component_id)\n        show_field_float(\"mLength\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        -- show_field_NINJA_ROPE_SEGMENT_VECTOR(\"mSegments\", nil, component_id)\n        show_field_unsupported(\"mSegments\", nil, component_id, \"NINJA_ROPE_SEGMENT_VECTOR\")\n    end\n\nend\n\nfunction show_NullDamageComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_float(\"null_chance\", \"if less than 1, then will roll the die to see if it will NULL all damage. Stick this into your projectile entity\", component_id)\n    end\n\nend\n\nfunction show_OrbComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_int(\"orb_id\", \"must be unique for every orb in the world\", component_id)\n    end\n\nend\n\nfunction show_ParticleEmitterComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_string(\"emitted_material_name\", nil, component_id)\n        show_field_bool(\"create_real_particles\", \"used to be emit_real_particles - creates these particles in the grid, if that happens velocity and lifetime are ignored\", component_id)\n        show_field_bool(\"emit_real_particles\", \"this creates particles that will behave like particles, but work outside of the screen\", component_id)\n        show_field_bool(\"emit_cosmetic_particles\", \"particle does have collisions, but no other physical interactions with the world. the particles are culled outside camera region\", component_id)\n        show_field_bool(\"cosmetic_force_create\", \"cosmetic particles are created inside grid cells\", component_id)\n        show_field_bool(\"render_back\", \"for cosmetic particles, if they are rendered on front or in the back...\", component_id)\n        show_field_bool(\"render_ultrabright\", \"if 1, particles made of a glowing material will be 3x as bright as usually\", component_id)\n        show_field_bool(\"collide_with_grid\", \"for cosmetic particles, if 1 the particles collide with grid and only exist in screen space\", component_id)\n        show_field_bool(\"collide_with_gas_and_fire\", \"does it collide with gas and fire, works with create_real_particles and raytraced images \", component_id)\n        show_field_bool(\"particle_single_width\", \"for cosmetic particles, forces them (gas,fire) to be only 1 pixel wide \", component_id)\n        show_field_bool(\"emit_only_if_there_is_space\", \"This is turned for potions after they take some damage and start leaking\", component_id)\n        show_field_int(\"emitter_lifetime_frames\", \"emitter lifetime in frames. -1 = infinite\", component_id)\n        show_field_bool(\"fire_cells_dont_ignite_damagemodel\", \"if set, and fire cells are created, this changes their default behaviour of igniting DamageModels\", component_id)\n        show_field_bool(\"color_is_based_on_pos\", \"if true, will get the particle color based on the world position (instead of randomizing it)\", component_id)\n        show_field_float(\"custom_alpha\", \"if >= 0, will use this as particle alpha\", component_id)\n        show_field_float(\"x_pos_offset_min\", nil, component_id)\n        show_field_float(\"y_pos_offset_min\", nil, component_id)\n        show_field_float(\"x_pos_offset_max\", nil, component_id)\n        show_field_float(\"y_pos_offset_max\", nil, component_id)\n        show_field_float(\"area_circle_sector_degrees\", nil, component_id)\n        show_field_float(\"x_vel_min\", nil, component_id)\n        show_field_float(\"x_vel_max\", nil, component_id)\n        show_field_float(\"y_vel_min\", nil, component_id)\n        show_field_float(\"y_vel_max\", nil, component_id)\n        show_field_float(\"direction_random_deg\", nil, component_id)\n        show_field_float(\"velocity_always_away_from_center\", \"if set, will make the velocity's rotation always away from center of randomized aabb\", component_id)\n        show_field_float(\"lifetime_min\", nil, component_id)\n        show_field_float(\"lifetime_max\", nil, component_id)\n        show_field_float(\"airflow_force\", nil, component_id)\n        show_field_float(\"airflow_time\", nil, component_id)\n        show_field_float(\"airflow_scale\", nil, component_id)\n        show_field_float(\"friction\", nil, component_id)\n        show_field_float(\"attractor_force\", \"If > 0, an attractor is created at the position of the entity that owns this component\", component_id)\n        show_field_int(\"emission_interval_min_frames\", nil, component_id)\n        show_field_int(\"emission_interval_max_frames\", nil, component_id)\n        show_field_int(\"emission_chance\", nil, component_id)\n        show_field_int(\"delay_frames\", \"if set will delay this many frames until starts\", component_id)\n        show_field_bool(\"is_emitting\", nil, component_id)\n        show_field_bool(\"use_material_inventory\", \"if set, it'll use MaterialInventoryComponent as the source of the particles emitted\", component_id)\n        show_field_bool(\"is_trail\", \"if set, will do a trail based on the previous position and current position\", component_id)\n        show_field_float(\"trail_gap\", \"if > 0, trail particles will be generated this far from each other between our old and new position, else [count_min-count_max] particles will be generated on the line\", component_id)\n        show_field_bool(\"render_on_grid\", \"if set, particle render positions will be snapped to cell grid\", component_id)\n        show_field_bool(\"fade_based_on_lifetime\", \"if set, particle's position in its lifetime will determine the rendering alpha\", component_id)\n        show_field_bool(\"draw_as_long\", \"if set, particle will rendered as a trail along it's movement vector\", component_id)\n        show_field_float(\"b2_force\", \"if 0 nothing happens, if 1 will apply a force to the physics body (if has one), also requires that we use the material inventory\", component_id)\n        show_field_bool(\"set_magic_creation\", \"if set will set the magic creation 1 in the cells and do the white glow effect\", component_id)\n        show_field_file_single(\"image_animation_file\", \"file to use for image-based animation\", component_id)\n        show_field_file_single(\"image_animation_colors_file\", \"file to use for image-based animation\", component_id)\n        show_field_float(\"image_animation_speed\", \"how long do we stay on one frame of image-based animation. 0.5 means two game frames per one animation frame. 2.0 means two animation frames per one game frame, and so on. 0 means we always emit at time 0 of the animation.\", component_id)\n        show_field_bool(\"image_animation_loop\", \"does image-based animation keep looping while this component is active?\", component_id)\n        show_field_float(\"image_animation_phase\", \"the point in time [0,1] where the image-based animation will start the first cycle\", component_id)\n        show_field_float(\"image_animation_emission_probability\", \"[0,1], probability of emitting image based particles is multiplied with this\", component_id)\n        show_field_bool(\"image_animation_raytrace_from_center\", \"enable this to disable image_animations (from the center) going through the world\", component_id)\n        show_field_bool(\"image_animation_use_entity_rotation\", \"if 1, image animation emission will be rotated based on entity rotation\", component_id)\n        show_field_bool(\"ignore_transform_updated_msg\", \"if 1, mExPosition and m_last_emit_position will not be updated when receiving Message_TransformUpdated\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_vec2(\"mExPosition\", \"is used with is_trail\", component_id)\n        show_field_int(\"mMaterialInventoryMax\", \"this is how we figure out the pressure, when using material_inventory\", component_id)\n        show_field_int(\"m_material_id\", nil, component_id)\n        show_field_int(\"m_next_emit_frame\", nil, component_id)\n        show_field_bool(\"m_has_emitted\", nil, component_id)\n        show_field_ivec2(\"m_last_emit_position\", nil, component_id)\n        -- show_field_ParticleEmitter_Animation*(\"m_cached_image_animation\", nil, component_id)\n        show_field_unsupported(\"m_cached_image_animation\", nil, component_id, \"ParticleEmitter_Animation*\")\n        show_field_float(\"m_image_based_animation_time\", nil, component_id)\n        -- show_field_float*(\"m_collision_angles\", nil, component_id)\n        show_field_unsupported(\"m_collision_angles\", nil, component_id, \"float*\")\n        show_field_int(\"m_particle_attractor_id\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_abgr(\"color\", nil, component_id)\n        show_field_vec2(\"offset\", nil, component_id)\n        show_field_ValueRange(\"area_circle_radius\", \"If > 0, the particles will be emitted inside a circular area defined by the min and max bounds of 'area_circle_radius'.\", component_id)\n        show_field_vec2(\"gravity\", nil, component_id)\n        show_field_int(\"count_min\", nil, component_id)\n        show_field_int(\"count_max\", nil, component_id)\n        show_field_enum(\"custom_style\", \"NONE or FIRE\", component_id, particle_emitter_custom_style)\n    end\n\nend\n\nfunction show_PathFindingComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_int(\"search_depth_max_no_goal\", \"TODO: Comment\", component_id)\n        show_field_int(\"iterations_max_no_goal\", \"TODO: Comment\", component_id)\n        show_field_int(\"search_depth_max_with_goal\", \"TODO: Comment\", component_id)\n        show_field_int(\"iterations_max_with_goal\", \"TODO: Comment\", component_id)\n        show_field_float(\"cost_of_flying\", \"TODO: Comment\", component_id)\n        show_field_int(\"distance_to_reach_node_x\", \"TODO: Comment\", component_id)\n        show_field_int(\"distance_to_reach_node_y\", \"TODO: Comment\", component_id)\n        show_field_int(\"frames_to_get_stuck\", \"TODO: Comment\", component_id)\n        show_field_int(\"frames_between_searches\", \"TODO: Comment\", component_id)\n        show_field_float(\"y_walking_compensation\", \"TODO: Comment\", component_id)\n        show_field_bool(\"can_fly\", \"TODO: Comment\", component_id)\n        show_field_bool(\"can_walk\", \"TODO: Comment\", component_id)\n        show_field_bool(\"can_jump\", \"TODO: Comment\", component_id)\n        show_field_bool(\"can_dive\", \"TODO: Comment\", component_id)\n        show_field_bool(\"can_swim_on_surface\", \"TODO: Comment\", component_id)\n        show_field_bool(\"never_consider_line_of_sight\", \"if 1, we require a path to have an entity at the goal, having line of sight to the entity is not enough\", component_id)\n        show_field_float(\"space_required\", \"how far (in cells) must a point on our route be from the nearest wall to consider it passable?\", component_id)\n        show_field_float(\"max_jump_distance_from_camera\", \"TODO: Comment\", component_id)\n        show_field_float(\"jump_speed\", \"TODO: Comment\", component_id)\n        show_field_float(\"initial_jump_lob\", \"TODO: Comment\", component_id)\n        show_field_float(\"initial_jump_max_distance_x\", \"TODO: Comment\", component_id)\n        show_field_float(\"initial_jump_max_distance_y\", \"TODO: Comment\", component_id)\n        show_field_int(\"read_state\", \"Read only value to get mState as an integer. Used to detect when the worst cheesers are trying to cheese our beloved squidward.\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        -- show_field_PathFindingInput(\"input\", \"TODO: Comment\", component_id)\n        show_field_unsupported(\"input\", \"TODO: Comment\", component_id, \"PathFindingInput\")\n        -- show_field_MSG_QUEUE_PATH_FINDING_RESULT(\"job_result_receiver\", \"TODO: Comment\", component_id)\n        show_field_unsupported(\"job_result_receiver\", \"TODO: Comment\", component_id, \"MSG_QUEUE_PATH_FINDING_RESULT\")\n        show_field_bool(\"waiting_for\", \"TODO: Comment\", component_id)\n        show_field_int(\"next_search_frame\", \"TODO: Comment\", component_id)\n        -- show_field_vector_pathnode(\"path\", \"TODO: Comment\", component_id)\n        show_field_unsupported(\"path\", \"TODO: Comment\", component_id, \"VECTOR_PATHNODE\")\n        -- show_field_PathFindingResultNode(\"path_next_node\", \"TODO: Comment\", component_id)\n        show_field_unsupported(\"path_next_node\", \"TODO: Comment\", component_id, \"PathFindingResultNode\")\n        show_field_vec2(\"path_next_node_vector_to\", \"TODO: Comment\", component_id)\n        show_field_float(\"path_next_node_distance_to\", \"TODO: Comment\", component_id)\n        -- show_field_PathFindingNodeHandle(\"path_previous_node\", \"TODO: Comment\", component_id)\n        show_field_unsupported(\"path_previous_node\", \"TODO: Comment\", component_id, \"PathFindingNodeHandle\")\n        show_field_int(\"path_frames_stuck\", \"TODO: Comment\", component_id)\n        show_field_bool(\"path_is_stuck\", \"TODO: Comment\", component_id)\n        show_field_int(\"path_last_frame_with_job\", \"TODO: Comment\", component_id)\n        -- show_field_PathFindingLogic*(\"mLogic\", \"this defines what is an acceptable path\", component_id)\n        show_field_unsupported(\"mLogic\", \"this defines what is an acceptable path\", component_id, \"PathFindingLogic*\")\n        -- show_field_PathFindingLogic*(\"mFallbackLogic\", \"we use this to define an acceptable path if mLogic doesn't return one\", component_id)\n        show_field_unsupported(\"mFallbackLogic\", \"we use this to define an acceptable path if mLogic doesn't return one\", component_id, \"PathFindingLogic*\")\n        -- show_field_PathFindingLogic*(\"mSelectedLogic\", \"TODO: Comment\", component_id)\n 