omponent_id, \"STACK_ANIMATIONSTATE\")\n        -- show_field_ComponentTags(\"mCachedTargetSpriteTag\", nil, component_id)\n        show_field_unsupported(\"mCachedTargetSpriteTag\", nil, component_id, \"ComponentTags\")\n        show_field_string(\"mSendOnFinishedMessageName\", nil, component_id)\n    end\n\nend\n\nfunction show_SpriteComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_file_single(\"image_file\", nil, component_id)\n        show_field_bool(\"ui_is_parent\", \"Adds this to the GG.GetUISprite() as a child, instead of the mSpriteContainer\", component_id)\n        show_field_bool(\"is_text_sprite\", \"if you want to load a text sprite, set this to true and image_file to a font file\", component_id)\n        show_field_float(\"offset_x\", nil, component_id)\n        show_field_float(\"offset_y\", nil, component_id)\n        show_field_float(\"alpha\", nil, component_id)\n        show_field_bool(\"visible\", nil, component_id)\n        show_field_bool(\"emissive\", nil, component_id)\n        show_field_bool(\"additive\", nil, component_id)\n        show_field_bool(\"fog_of_war_hole\", \"if 1, the alpha channel of this texture punctures a hole in the fog of war\", component_id)\n        show_field_bool(\"smooth_filtering\", nil, component_id)\n        show_field_string(\"rect_animation\", nil, component_id)\n        show_field_string(\"next_rect_animation\", nil, component_id)\n        show_field_string(\"text\", nil, component_id)\n        show_field_float(\"z_index\", \"0 = world grid, -1 = enemies, -1.5 = items in world, player = 0.6\", component_id)\n        show_field_bool(\"update_transform\", nil, component_id)\n        show_field_bool(\"update_transform_rotation\", nil, component_id)\n        show_field_bool(\"kill_entity_after_finished\", nil, component_id)\n        show_field_bool(\"has_special_scale\", \"if this is set, sets special_scale_x and _y to scale\", component_id)\n    