t_id)\n        show_field_float(\"mStartBodyAngle\", nil, component_id)\n        show_field_float(\"mStartBodyDistance\", nil, component_id)\n        show_field_float(\"mStartTime\", nil, component_id)\n        show_field_float(\"mMinBodyDistance\", nil, component_id)\n        show_field_bool(\"mInteract\", \"If set to true, telekinesis interaction will occur. Will automatically turn to false at the end of component update.\", component_id)\n    end\n\nend\n\nfunction show_TeleportComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_bool(\"target_x_is_absolute_position\", \"If set, target position x is in world coordinates, otherwise it's an offset\", component_id)\n        show_field_bool(\"target_y_is_absolute_position\", \"If set, target position y is in world coordinates, otherwise it's an offset\", component_id)\n        show_field_file_single(\"source_particle_fx_file\", \"This entity is loaded at the source position when teleportation occurs\", component_id)\n        show_field_file_single(\"target_particle_fx_file\", \"This entity is loaded at the target position when teleportation occurs\", component_id)\n        show_field_bool(\"load_collapse_entity\", \"if we don't want things to collapse after the teleport\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_int(\"safety_counter\", \"used to keep track that we're not stuck in waiting for a pixel scene to load, that is not going to be loaded\", component_id)\n        -- show_field_TeleportComponentState_Enum(\"state\", nil, component_id)\n        show_field_unsupported(\"state\", nil, component_id, \"TeleportComponentState::Enum\")\n        show_field_vector_entityid(\"teleported_entities\", nil, component_id)\n        show_field_types_aabb(\"source_location_camera_aabb\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_vec2(\"target