_TWWE_VFS["mods/component-explorer/components_main.lua"] = "dofile_once(\"mods/component-explorer/serialise_component.lua\")\ndofile_once(\"mods/component-explorer/component_fields.lua\")\ndofile_once(\"mods/component-explorer/configs.lua\")\nlocal matinv_field = dofile_once(\"mods/component-explorer/matinv_field.lua\")\nlocal help = dofile_once(\"mods/component-explorer/ui/help.lua\")\n\ncomponent_types = {\n    \"AIAttackComponent\",\n    \"AIComponent\",\n    \"AbilityComponent\",\n    \"AdvancedFishAIComponent\",\n    \"AltarComponent\",\n    \"AnimalAIComponent\",\n    \"ArcComponent\",\n    \"AreaDamageComponent\",\n    \"AttachToEntityComponent\",\n    \"AudioComponent\",\n    \"AudioListenerComponent\",\n    \"AudioLoopComponent\",\n    \"BiomeTrackerComponent\",\n    \"BlackHoleComponent\",\n    \"BookComponent\",\n    \"BossDragonComponent\",\n    \"BossHealthBarComponent\",\n    \"CameraBoundComponent\",\n    \"CardinalMovementComponent\",\n    \"CellEaterComponent\",\n    \"CharacterCollisionComponent\",\n    \"CharacterDataComponent\",\n    \"CharacterPlatformingComponent\",\n    \"CharacterStatsComponent\",\n    \"CollisionTriggerComponent\",\n    \"ConsumableTeleportComponent\",\n    \"ControllerGoombaAIComponent\",\n    \"ControlsComponent\",\n    \"CrawlerAnimalComponent\",\n    \"CutThroughWorldDoneHereComponent\",\n    \"DamageModelComponent\",\n    \"DamageNearbyEntitiesComponent\",\n    \"DebugFollowMouseComponent\",\n    \"DebugLogMessagesComponent\",\n    \"DebugSpatialVisualizerComponent\",\n    \"DieIfSpeedBelowComponent\",\n    \"DroneLauncherComponent\",\n    \"DrugEffectComponent\",\n    \"DrugEffectModifierComponent\",\n    \"ElectricChargeComponent\",\n    \"ElectricityComponent\",\n    \"ElectricityReceiverComponent\",\n    \"ElectricitySourceComponent\",\n    \"EndingMcGuffinComponent\",\n    \"EnergyShieldComponent\",\n    \"ExplodeOnDamageComponent\",\n    \"ExplosionComponent\",\n    \"FishAIComponent\",\n    \"FlyingComponent\",\n    \"FogOfWarRadiusComponent\",\n    \"FogOfWarRemoverComponent\",\n    \"GameAreaEffectComponent\",\n    \"GameEffectComponent\",\n    \"GameLogComponent\",\n    \"GameStatsComponent\",\n    \"GasBubbleComponent\",\n    \"GenomeDataComponent\",\n    \"GhostComponent\",\n    \"GodInfoComponent\",\n    \"GunComponent\",\n    \"HealthBarComponent\",\n    \"HitEffectComponent\",\n    \"HitboxComponent\",\n    \"HomingComponent\",\n    \"HotspotComponent\",\n    \"IKLimbAttackerComponent\",\n    \"IKLimbComponent\",\n    \"IKLimbWalkerComponent\",\n    \"IKLimbsAnimatorComponent\",\n    \"IngestionComponent\",\n    \"InheritTransformComponent\",\n    \"InteractableComponent\",\n    \"Inventory2Component\",\n    \"InventoryComponent\",\n    \"InventoryGuiComponent\",\n    \"ItemAIKnowledgeComponent\",\n    \"ItemActionComponent\",\n    \"ItemAlchemyComponent\",\n    \"ItemChestComponent\",\n    \"ItemComponent\",\n    \"ItemCostComponent\",\n    \"ItemPickUpperComponent\",\n    \"ItemRechargeNearGroundComponent\",\n    \"ItemStashComponent\",\n    \"KickComponent\",\n    \"LaserEmitterComponent\",\n    \"LevitationComponent\",\n    \"LifetimeComponent\",\n    \"LightComponent\",\n    \"LightningComponent\",\n    \"LimbBossComponent\",\n    \"LiquidDisplacerComponent\",\n    \"LoadEntitiesComponent\",\n    \"LocationMarkerComponent\",\n    \"LooseGroundComponent\",\n    \"LuaComponent\",\n    \"MagicConvertMaterialComponent\",\n    \"MagicXRayComponent\",\n    \"ManaReloaderComponent\",\n    \"MaterialAreaCheckerComponent\",\n    \"MaterialInventoryComponent\",\n    \"MaterialSeaSpawnerComponent\",\n    \"MaterialSuckerComponent\",\n    \"MoveToSurfaceOnCreateComponent\",\n    \"MusicEnergyAffectorComponent\",\n    \"NinjaRopeComponent\",\n    \"NullDamageComponent\",\n    \"OrbComponent\",\n    \"ParticleEmitterComponent\",\n    \"PathFindingComponent\",\n    \"PathFindingGridMarkerComponent\",\n    \"PhysicsAIComponent\",\n    \"PhysicsBody2Component\",\n    \"PhysicsBodyCollisionDamageComponent\",\n    \"PhysicsBodyComponent\",\n    \"PhysicsImageShapeComponent\",\n    \"PhysicsJoint2Component\",\n    \"PhysicsJoint2MutatorComponent\",\n    \"PhysicsJointComponent\",\n    \"PhysicsKeepInWorldComponent\",\n    \"PhysicsPickUpComponent\",\n    \"PhysicsRagdollComponent\",\n    \"PhysicsShapeComponent\",\n    \"PhysicsThrowableComponent\",\n    \"PixelSceneComponent\",\n    \"PixelSpriteComponent\",\n    \"PlatformShooterPlayerComponent\",\n    \"PlayerCollisionComponent\",\n    \"PlayerStatsComponent\",\n    \"PositionSeedComponent\",\n    \"PotionComponent\",\n    \"PressurePlateComponent\",\n    \"ProjectileComponent\",\n    \"RotateTowardsComponent\",\n    \"SetLightAlphaFromVelocityComponent\",\n    \"SetStartVelocityComponent\",\n    \"ShotEffectComponent\",\n    \"SimplePhysicsComponent\",\n    \"SineWaveComponent\",\n    \"SpriteAnimatorComponent\",\n    \"SpriteComponent\",\n    \"SpriteOffsetAnimatorComponent\",\n    \"SpriteParticleEmitterComponent\",\n    \"SpriteStainsComponent\",\n    \"StatusEffectDataComponent\",\n    \"StreamingKeepAliveComponent\",\n    \"TelekinesisComponent\",\n    \"TeleportComponent\",\n    \"TeleportProjectileComponent\",\n    \"TextLogComponent\",\n    \"TorchComponent\",\n    \"UIIconComponent\",\n    \"UIInfoComponent\",\n    \"VariableStorageComponent\",\n    \"VelocityComponent\",\n    \"VerletPhysicsComponent\",\n    \"VerletWeaponComponent\",\n    \"VerletWorldJointComponent\",\n    \"WalletComponent\",\n    \"WalletValuableComponent\",\n    \"WorldStateComponent\",\n    \"WormAIComponent\",\n    \"WormAttractorComponent\",\n    \"WormComponent\",\n    \"WormPlayerComponent\",\n}\n\n\n\n\nfunction show_AIAttackComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_int(\"use_probability\", \"The probability for using this attack if it's otherwise possible\", component_id)\n        show_field_float(\"min_distance\", \"The minimum distance from enemy at which we can perform this attack.\", component_id)\n        show_field_float(\"max_distance\", \"The maximum distance from enemy at which we can perform this attack.\", component_id)\n        show_field_float(\"angular_range_deg\", \"When looking for threats/prey this is our field of view around the X axis. 90 means we scan the whole 180 degrees around the X axis, to the left and right.\", component_id)\n        show_field_int(\"state_duration_frames\", \"How long do we stay in the attack state, before other states are allowed?\", component_id)\n        show_field_int(\"frames_between\", \"The minimum number of frames we wait between these attacks\", component_id)\n        show_field_int(\"frames_between_global\", \"The minimum number of frames we wait after this attack before doing any other ranged attack\", component_id)\n        show_field_string(\"animation_name\", \"The animation to play when performing this attack\", component_id)\n        show_field_bool(\"attack_landing_ranged_enabled\", \"If 1, we try to land before doing the attack, if there's ground near nearby under us\", component_id)\n        show_field_int(\"attack_ranged_action_frame\", \"The frame of the 'attack_ranged' animation during which the ranged attack actually occurs\", component_id)\n        show_field_float(\"attack_ranged_offset_x\", \"'attack_ranged_entity_file' is created here when performing a ranged attack\", component_id)\n        show_field_float(\"attack_ranged_offset_y\", \"'attack_ranged_entity_file' is created here when performing a ranged attack\", component_id)\n        show_field_float(\"attack_ranged_root_offset_x\", nil, component_id)\n        show_field_float(\"attack_ranged_root_offset_y\", nil, component_id)\n        show_field_bool(\"attack_ranged_use_message\", \"If 1, we do ranged attacks by sending a Message_UseItem\", component_id)\n        show_field_bool(\"attack_ranged_predict\", \"If 1, we attempt to predict target movement and shoot accordingly\", component_id)\n        show_field_file_single(\"attack_ranged_entity_file\", \"File to projectile entity that is created when performing a ranged attack\", component_id)\n        show_field_int(\"attack_ranged_entity_count_min\", \"Minimum number of projectiles shot when performing a ranged attack\", component_id)\n        show_field_int(\"attack_ranged_entity_count_max\", \"Maximum number of projectiles shot when performing a ranged attack\", component_id)\n        show_field_bool(\"attack_ranged_use_laser_sight\", \"If 1, we draw a laser sight to our target. Requires entity to have a sprite with tag 'laser_sight'\", component_id)\n        show_field_bool(\"attack_ranged_aim_rotation_enabled\", \"If 1, we use a laser sight\", component_id)\n        show_field_float(\"attack_ranged_aim_rotation_speed\", \"How fast can we rotate our aim to track targets\", component_id)\n        show_field_float(\"attack_ranged_aim_rotation_shooting_ok_angle_deg\", \"If our aim is closer than this to the target we shoot\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_float(\"mRangedAttackCurrentAimAngle\", \"which direction does our gun currently point at, physically saying?\", component_id)\n        show_field_int(\"mNextFrameUsable\", nil, component_id)\n    end\n\nend\n\nfunction show_AIComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_float(\"TEMP_TEMP_TEMP\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        -- show_field_AIData*(\"data\", nil, component_id)\n        show_field_unsupported(\"data\", nil, component_id, \"AIData*\")\n    end\n\nend\n\nfunction show_AbilityComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_int(\"cooldown_frames\", nil, component_id)\n        show_field_file_single(\"entity_file\", \"the projectile entity file\", component_id)\n        show_field_file_single(\"sprite_file\", nil, component_id)\n        show_field_int(\"entity_count\", nil, component_id)\n        show_field_bool(\"never_reload\", nil, component_id)\n        show_field_int(\"reload_time_frames\", nil, component_id)\n        show_field_float(\"mana\", nil, component_id)\n        show_field_float(\"mana_max\", nil, component_id)\n        show_field_float(\"mana_charge_speed\", nil, component_id)\n        show_field_bool(\"rotate_in_hand\", nil, component_id)\n        show_field_float(\"rotate_in_hand_amount\", \"[0-1], how much does the item rotate related to the actual aiming angle\", component_id)\n        show_field_float(\"rotate_hand_amount\", \"[0-1], how much does hand sprite rotate related to the actual aiming angle\", component_id)\n        show_field_bool(\"fast_projectile\", \"if 1, then the velocity of the bullet is increased quite a bit. Lightning requires this\", component_id)\n        show_field_float(\"swim_propel_amount\", nil, component_id)\n        show_field_int(\"max_charged_actions\", nil, component_id)\n        show_field_int(\"charge_wait_frames\", nil, component_id)\n        show_field_float(\"item_recoil_recovery_speed\", \"How quickly does the item return to resting state after getting recoil\", component_id)\n        show_field_float(\"item_recoil_max\", \"Maximum distance moved by recoil\", component_id)\n        show_field_float(\"item_recoil_offset_coeff\", \"Item distance moved by recoil = mItemRecoil * item_recoil_offset_coeff\", component_id)\n        show_field_float(\"item_recoil_rotation_coeff\", \"Item rotation by recoil = mItemRecoil * item_recoil_rotation_coeff\", component_id)\n        show_field_file_single(\"base_item_file\", \"when dropping / throwing the item, this is the base_item that we add the ability component to\", component_id)\n        show_field_bool(\"use_entity_file_as_projectile_info_proxy\", nil, component_id)\n        show_field_bool(\"click_to_use\", nil, component_id)\n        show_field_int(\"stat_times_player_has_shot\", \"used to track how many times player has shot this 'ability'\", component_id)\n        show_field_int(\"stat_times_player_has_edited\", \"used to track how many times this has been edited\", component_id)\n        show_field_bool(\"shooting_reduces_amount_in_inventory\", nil, component_id)\n        show_field_bool(\"throw_as_item\", nil, component_id)\n        show_field_bool(\"simulate_throw_as_item\", \"If 1, the item will be work as normal ability, but throwing animation is played by the user\", component_id)\n        show_field_int(\"max_amount_in_inventory\", nil, component_id)\n        show_field_int(\"amount_in_inventory\", nil, component_id)\n        show_field_bool(\"drop_as_item_on_death\", nil, component_id)\n        show_field_string(\"ui_name\", \"way to name the weapons\", component_id)\n        show_field_bool(\"use_gun_script\", \"If 1, the default ability behaviour is replaced with one that uses the lua gun system.\", component_id)\n        show_field_bool(\"is_petris_gun\", \"if 1, TODO( PETRI)\", component_id)\n        show_field_int(\"gun_level\", \"the level of the wand, set in gun_procedural.lua\", component_id)\n        show_field_string(\"add_these_child_actions\", \"e.g. 'bullet,bullet,damage' ... actions are parsed into a string. These are added as actual entities when the item is initialized\", component_id)\n        show_field_int(\"current_slot_durability\", \"After this many slots the last slot of the gun is removed. -1 means not initialized/infinite.\", component_id)\n        show_field_string(\"slot_consumption_function\", \"Name of the lua function in 'gun.lua' that is called to calculate durability of the last slot in the gun\", component_id)\n        show_field_int(\"mNextFrameUsable\", \"hax, don't touch!\", component_id)\n        show_field_int(\"mCastDelayStartFrame\", \"hax, don't touch!\", component_id)\n        show_field_int(\"mReloadFramesLeft\", \"hax, don't touch!\", component_id)\n        show_field_int(\"mReloadNextFrameUsable\", \"hax, don't touch!\", component_id)\n        show_field_int(\"mChargeCount\", \"hax, don't touch!\", component_id)\n        show_field_bool(\"mIsInitialized\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_int(\"mAmmoLeft\", nil, component_id)\n        show_field_int(\"mNextChargeFrame\", nil, component_id)\n        show_field_float(\"mItemRecoil\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Objects\") then\n        local object_open = imgui.TreeNode(\"gun_config ConfigGun\")\n        imgui.SameLine()\n        help.marker(\"Constants for gun script\")\n        if object_open then\n            show_ConfigGun_fields(\"gun_config\", \"Constants for gun script\", component_id)\n            imgui.TreePop()\n        end\n        local object_open = imgui.TreeNode(\"gunaction_config ConfigGunActionInfo\")\n        imgui.SameLine()\n        help.marker(\"Constants for gun script\")\n        if object_open then\n            show_ConfigGunActionInfo_fields(\"gunaction_config\", \"Constants for gun script\", component_id)\n            imgui.TreePop()\n        end\n    end\n\nend\n\nfunction show_AdvancedFishAIComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_float(\"move_check_range_min\", nil, component_id)\n        show_field_float(\"move_check_range_max\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_bool(\"flock\", nil, component_id)\n        show_field_bool(\"avoid_predators\", nil, component_id)\n        show_field_bool(\"mHasTargetDirection\", nil, component_id)\n        show_field_vec2(\"mTargetPos\", nil, component_id)\n        show_field_vec2(\"mTargetVec\", nil, component_id)\n        show_field_vec2(\"mLastFramesMovementAreaMin\", nil, component_id)\n        show_field_vec2(\"mLastFramesMovementAreaMax\", nil, component_id)\n        show_field_int(\"mNumFailedTargetSearches\", nil, component_id)\n        show_field_int(\"mNextFrameCheckAreWeStuck\", nil, component_id)\n        show_field_int(\"mNextFrameCheckFlockWants\", nil, component_id)\n        show_field_int(\"mNextFramePredatorAvoidance\", nil, component_id)\n        show_field_float(\"mScared\", nil, component_id)\n        show_field_bool(\"mWantsToBeInFlock\", nil, component_id)\n    end\n\nend\n\nfunction show_AltarComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_string(\"recognized_entity_tags\", nil, component_id)\n        show_field_int(\"uses_remaining\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        -- show_field_EntityTags(\"m_recognized_entity_tags\", nil, component_id)\n        show_field_unsupported(\"m_recognized_entity_tags\", nil, component_id, \"EntityTags\")\n        show_field_int(\"m_recognized_entity_tags_count\", nil, component_id)\n        -- show_field_EntityTags(\"m_current_entity_tags\", nil, component_id)\n        show_field_unsupported(\"m_current_entity_tags\", nil, component_id, \"EntityTags\")\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_material_id(\"good_fx_material\", \"String name of material for particles emitted on successful sacrifice\", component_id)\n        show_field_material_id(\"neutral_fx_material\", \"String name of material for particles emitted on successful sacrifice\", component_id)\n        show_field_material_id(\"evil_fx_material\", \"String name of material for particles emitted on successful sacrifice\", component_id)\n    end\n\nend\n\nfunction show_AnimalAIComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_int(\"ai_state\", \"Current state of ai, defines what the animal is doing\", component_id)\n        show_field_int(\"ai_state_timer\", \"If not 0, then we wait till this frame to pop current state from our state stack\", component_id)\n        show_field_bool(\"keep_state_alive_when_enabled\", \"if 1, will ensure state timer keeps current state alive for a while when Component is Enabled\", component_id)\n        show_field_string(\"preferred_job\", \"We always do this job, unless interrupted (i.e. by taking fire damage)\", component_id)\n        show_field_int(\"escape_if_damaged_probability\", \"the chance of escaping if someone damages us. only works if 'can_fly = 0 '\", component_id)\n        show_field_int(\"attack_if_damaged_probability\", \"the chance of counter-attacking if someone damages us, and we didn't escape\", component_id)\n        show_field_int(\"eye_offset_x\", \"We cast rays from our position + eye_offset to check if we can see something\", component_id)\n        show_field_int(\"eye_offset_y\", \"We cast rays from our position + eye_offset to check if we can see something\", component_id)\n        show_field_bool(\"attack_only_if_attacked\", \"If 1, we never attack anyone unless attacked before by someone\", component_id)\n        show_field_bool(\"dont_counter_attack_own_herd\", \"If 1, we don't attack members of our herd even if they accidentally attack us\", component_id)\n        show_field_float(\"creature_detection_range_x\", \"When looking for threats/prey this is the max distance from us on the X axis we scan\", component_id)\n        show_field_float(\"creature_detection_range_y\", \"When looking for threats/prey this is the max distance from us on the Y axis we scan\", component_id)\n        show_field_float(\"creature_detection_angular_range_deg\", \"When looking for threats/prey this is our field of view around the X axis. 90 means we scan the whole 180 degrees around the X axis, to the left and right\", component_id)\n        show_field_int(\"creature_detection_check_every_x_frames\", \"Checks for threats/prey take place at least this many frames apart from each other\", component_id)\n        show_field_float(\"max_distance_to_cam_to_start_hunting\", \"JobDefault idles before we've been once at least this close to the camera\", component_id)\n        show_field_int(\"pathfinding_max_depth_no_target\", \"The maximum depth (in nodes) path search use when we have not found prey yet\", component_id)\n        show_field_int(\"pathfinding_max_depth_has_target\", \"The maximum depth (in nodes) path search use when we have found prey\", component_id)\n        show_field_float(\"aggressiveness_min\", \"what's the initial random aggressiveness of this creature\", component_id)\n        show_field_float(\"aggressiveness_max\", \"what's the initial random aggressiveness of this creature\", component_id)\n        show_field_bool(\"tries_to_ranged_attack_friends\", \"if 1, the AI tries to attack whoever it considers a friend based on herd_ids, CHARMED and BERSERK status etc. useful e.g. for healers.\", component_id)\n        show_field_bool(\"attack_melee_enabled\", \"If 1, and melee attack has been configured, we can perform melee attacks\", component_id)\n        show_field_bool(\"attack_dash_enabled\", \"If 1, and dash attack has been configured, we can perform dash attacks (a long-distance melee attack where we dash towards the enemy)\", component_id)\n        show_field_bool(\"attack_landing_ranged_enabled\", \"If 1, and ranged attack has been configured, we can perform ranged attacks\", component_id)\n        show_field_bool(\"attack_ranged_enabled\", \"If 1, and ranged attack has been configured, we can perform ranged attacks\", component_id)\n        show_field_float(\"attack_knockback_multiplier\", \"If not 0, melee and dash attacks cause knockback to target\", component_id)\n        show_field_bool(\"is_static_turret\", \"If 1, we can only attack in one fixed direction\", component_id)\n        show_field_int(\"attack_melee_max_distance\", \"Maximum distance at which we can perform a melee attack\", component_id)\n        show_field_int(\"attack_melee_action_frame\", \"The animation frame during which the melee attack damage is inflicted and visual effects are created\", component_id)\n        show_field_int(\"attack_melee_frames_between\", \"The minimum number of frames we wait between melee attacks\", component_id)\n        show_field_float(\"attack_melee_damage_min\", \"Melee attack damage inclusive minimum amount. The damage is randomized between melee attack_damage_min and attack_melee_damage_max\", component_id)\n        show_field_float(\"attack_melee_damage_max\", \"Melee attack damage inclusive maximum amount. The damage is randomized between melee attack_damage_min and attack_melee_damage_max\", component_id)\n        show_field_float(\"attack_melee_impulse_vector_x\", \"The x component of the impulse that is applied to damaged entities\", component_id)\n        show_field_float(\"attack_melee_impulse_vector_y\", \"The y component of the impulse that is applied to damaged entities\", component_id)\n        show_field_float(\"attack_melee_impulse_multiplier\", \"A multiplier applied to attack_melee_impulse\", component_id)\n        show_field_float(\"attack_melee_offset_x\", \"Melee attack particle effects are created here\", component_id)\n        show_field_float(\"attack_melee_offset_y\", \"Melee attack particle effects are created here\", component_id)\n        show_field_bool(\"attack_melee_finish_enabled\", \"If 1, we perform a finishing move when our attack would kill the target using the 'attack_finish' animation\", component_id)\n        show_field_int(\"attack_melee_finish_action_frame\", \"The animation frame during which the melee attack finishing move damage is inflicted and visual effects are created\", component_id)\n        show_field_float(\"attack_dash_distance\", \"The maximum distance from enemy at which we can perform a dash attack. If a normal melee attack is possible we always do that instead\", component_id)\n        show_field_int(\"attack_dash_frames_between\", \"The minimum number of frames we wait between dash attacks\", component_id)\n        show_field_float(\"attack_dash_damage\", \"The amount of damage inflicted by the dash attack\", component_id)\n        show_field_float(\"attack_dash_speed\", \"The speed at which we dash\", component_id)\n        show_field_float(\"attack_dash_lob\", \"The smaller this value is the more curved our dash attack trajectory is\", component_id)\n        show_field_float(\"attack_ranged_min_distance\", \"The minimum distance from enemy at which we can perform a ranged attack.\", component_id)\n        show_field_float(\"attack_ranged_max_distance\", \"The maximum distance from enemy at which we can perform a ranged attack.\", component_id)\n        show_field_int(\"attack_ranged_action_frame\", \"The frame of the 'attack_ranged' animation during which the ranged attack actually occurs\", component_id)\n        show_field_float(\"attack_ranged_offset_x\", \"'attack_ranged_entity_file' is created here when performing a ranged attack\", component_id)\n        show_field_float(\"attack_ranged_offset_y\", \"'attack_ranged_entity_file' is created here when performing a ranged attack\", component_id)\n        show_field_bool(\"attack_ranged_use_message\", \"If 1, we do ranged attacks by sending a Message_UseItem\", component_id)\n        show_field_bool(\"attack_ranged_predict\", \"If 1, we attempt to predict target movement and shoot accordingly\", component_id)\n        show_field_file_single(\"attack_ranged_entity_file\", \"File to projectile entity that is created when performing a ranged attack\", component_id)\n        show_field_int(\"attack_ranged_entity_count_min\", \"Minimum number of projectiles shot when performing a ranged attack\", component_id)\n        show_field_int(\"attack_ranged_entity_count_max\", \"Maximum number of projectiles shot when performing a ranged attack\", component_id)\n        show_field_bool(\"attack_ranged_use_laser_sight\", \"If 1, we draw a laser sight to our target. Requires entity to have a sprite with tag 'laser_sight'\", component_id)\n        show_field_bool(\"attack_ranged_laser_sight_beam_kind\", \"0 = red, 1 = blue \", component_id)\n        show_field_bool(\"attack_ranged_aim_rotation_enabled\", nil, component_id)\n        show_field_float(\"attack_ranged_aim_rotation_speed\", nil, component_id)\n        show_field_float(\"attack_ranged_aim_rotation_shooting_ok_angle_deg\", nil, component_id)\n        show_field_int(\"attack_ranged_state_duration_frames\", \"How long do we stay in the attack state, before other states are allowed?\", component_id)\n        show_field_bool(\"hide_from_prey\", \"If 1, we attempt to hide from our target after a succesful attack\", component_id)\n        show_field_float(\"hide_from_prey_target_distance\", \"The minimum distance from our target where we should move when hiding\", component_id)\n        show_field_int(\"hide_from_prey_time\", \"The number of frames we spend hiding and staying hiding\", component_id)\n        show_field_bool(\"food_eating_create_particles\", \"If 1, we replace eaten cells with particles made of this material\", component_id)\n        show_field_int(\"eating_area_radius_x\", \"1/2 width of the area from which we eat food\", component_id)\n        show_field_int(\"eating_area_radius_y\", \"1/2 height of the area from which we eat food\", component_id)\n        show_field_int(\"mouth_offset_x\", \"The center of the area from which we eat food\", component_id)\n        show_field_int(\"mouth_offset_y\", \"The center of the area from which we eat food\", component_id)\n        show_field_bool(\"defecates_and_pees\", \"If 1, we occasionally take a leak or a dump\", component_id)\n        show_field_int(\"butt_offset_x\", \"Bodily wastes are created here\", component_id)\n        show_field_int(\"butt_offset_y\", \"Bodily wastes are created here\", component_id)\n        show_field_float(\"pee_velocity_x\", \"The velocity at which our piss gets shot\", component_id)\n        show_field_float(\"pee_velocity_y\", \"The velocity at which our piss gets shot\", component_id)\n        show_field_bool(\"needs_food\", \"If 1, we stop to eat if we encounter 'food_material' cells\", component_id)\n        show_field_bool(\"sense_creatures\", \"If 1, we occasionally search our surroundings for prey and threats\", component_id)\n        show_field_bool(\"sense_creatures_through_walls\", \"If 1, will see creatures even if the wall raycast fails\", component_id)\n        show_field_bool(\"can_fly\", \"If 1, we can fly. Please set 'PathFindingComponent.can_fly' to 1 as well if this is 1\", component_id)\n        show_field_bool(\"can_walk\", \"If 1, we can walk. Please set 'PathFindingComponent.can_walk' to 1 as well if this is 1\", component_id)\n        show_field_int(\"path_distance_to_target_node_to_turn_around\", \"If we're further than this from target path finding node on the X-axis we turn to face it\", component_id)\n        show_field_float(\"path_cleanup_explosion_radius\", \"If we get stuck on ground we create an explosion this big to clear our surroundings a bit\", component_id)\n        show_field_float(\"max_distance_to_move_from_home\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        -- show_field_AI_STATE_STACK(\"mAiStateStack\", \"a stack of actions and times they take, we can push new actions to the front and pop them from there\", component_id)\n        show_field_unsupported(\"mAiStateStack\", \"a stack of actions and times they take, we can push new actions to the front and pop them from there\", component_id, \"AI_STATE_STACK\")\n        show_field_int(\"mAiStateLastSwitchFrame\", \"when was the last time we switched a state\", component_id)\n        show_field_int(\"mAiStatePrev\", \"previous AI state\", component_id)\n        show_field_int(\"mCreatureDetectionNextCheck\", \"threat/prey check, next time we check for threat/prey\", component_id)\n        show_field_EntityID(\"mGreatestThreat\", \"the entity we consider to be our greatest threat\", component_id)\n        show_field_EntityID(\"mGreatestPrey\", \"the entity we consider to be our most important prey\", component_id)\n        show_field_int(\"mSelectedMultiAttack\", \"which AIAttackComponent attack are we using?\", component_id)\n        show_field_bool(\"mHasFoundPrey\", \"1, if we have ever found prey\", component_id)\n        show_field_bool(\"mHasBeenAttackedByPlayer\", \"1, if we have been ever attacked\", component_id)\n        show_field_bool(\"mHasStartedAttacking\", \"1, if we have ever started attacking anyone\", component_id)\n        show_field_int(\"mNearbyFoodCount\", \"amount of 'food_material' near us\", component_id)\n        show_field_int(\"mEatNextFrame\", \"next frame we can eat\", component_id)\n        show_field_int(\"mEatTime\", \"time we've been constantly eating\", component_id)\n        show_field_int(\"mFrameNextGiveUp\", \"next frame we consider ourselves to be stuck\", component_id)\n        show_field_vec2(\"mLastFramesMovementAreaMin\", \"AABB min of the area where we've been since the last time we got stuck\", component_id)\n        show_field_vec2(\"mLastFramesMovementAreaMax\", \"AABB max of the area where we've been since the last time we got stuck\", component_id)\n        show_field_material_id(\"mFoodMaterialId\", \"cached id of 'food_material'\", component_id)\n        show_field_material_id(\"mFoodParticleEffectMaterialId\", \"cached id of 'food_particle_effect_material'\", component_id)\n        show_field_float(\"mNextJumpLob\", \"we use this for next jump\", component_id)\n        show_field_vec2(\"mNextJumpTarget\", \"we use this for next jump\", component_id)\n        show_field_bool(\"mNextJumpHasVelocity\", \"we use this for next jump\", component_id)\n        show_field_int(\"mLastFrameJumped\", \"previous frame we launched into a jump\", component_id)\n        show_field_int(\"mFramesWithoutTarget\", nil, component_id)\n        show_field_int(\"mLastFrameCanDamageOwnHerd\", nil, component_id)\n        show_field_vec2(\"mHomePosition\", \"where our home is located\", component_id)\n        show_field_int(\"mLastFrameAttackWasDone\", \"when was the last time we did an attack (not necessarily did damage to anyone though)\", component_id)\n        show_field_int(\"mNextFrameCanCallFriend\", nil, component_id)\n        show_field_int(\"mNextFrameRespondFriend\", nil, component_id)\n        show_field_bool(\"mHasNoticedPlayer\", \"if 1, we have noticed player or player projectile\", component_id)\n        show_field_float(\"mRangedAttackCurrentAimAngle\", \"which direction does our gun currently point at, physically saying?\", component_id)\n        show_field_int(\"mRangedAttackNextFrame\", \"next frame we can perform a ranged attack\", component_id)\n        show_field_int(\"mMeleeAttackNextFrame\", \"next frame we can perform a melee attack\", component_id)\n        show_field_float(\"mNextMeleeAttackDamage\", \"the amount of damage our next melee attack will cause. used by finishing move logic\", component_id)\n        show_field_bool(\"mMeleeAttacking\", \"1, if we're doing a melee attack\", component_id)\n        show_field_int(\"mMeleeAttackDashNextFrame\", \"the next frame we can perform a melee attack\", component_id)\n        -- show_field_RtsUnitGoal(\"mCurrentJob\", \"info about our current job. sorta legacy and could be simplified because the RTS logic is not used anywhere but doesn't have much overhead either.\", component_id)\n        show_field_unsupported(\"mCurrentJob\", \"info about our current job. sorta legacy and could be simplified because the RTS logic is not used anywhere but doesn't have much overhead either.\", component_id, \"RtsUnitGoal\")\n    end\n\n\n    if imgui.CollapsingHeader(\"Objects\") then\n        local object_open = imgui.TreeNode(\"attack_melee_finish_config_explosion ConfigExplosion\")\n        imgui.SameLine()\n        help.marker(\"If we have explosion, it's the setup for it\")\n        if object_open then\n            show_ConfigExplosion_fields(\"attack_melee_finish_config_explosion\", \"If we have explosion, it's the setup for it\", component_id)\n            imgui.TreePop()\n        end\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_int(\"attack_ranged_frames_between\", \"The minimum number of frames we wait between ranged attacks\", component_id)\n        show_field_material_id(\"food_material\", \"The cell material we eat if encountering said material and 'needs_food' is 1\", component_id)\n        show_field_material_id(\"food_particle_effect_material\", \"We create particles made of this material when eating if 'food_eating_create_particles' is 1\", component_id)\n        show_field_float(\"mAggression\", \"the greater this value the more likely we're to attack creatures from other herds\", component_id)\n    end\n\nend\n\nfunction show_ArcComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_int(\"lifetime\", \"remaining number of frames the arc exists\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_EntityID(\"mArcTarget\", \"if 'mArcTarget' points to an existing entity a lighting arc will be created between this entity and 'mArcTarget'\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_enum(\"type\", \"which implementation the arc should use\", component_id, arc_type)\n        show_field_material_id(\"material\", \"string name for the material the arc is made of\", component_id)\n    end\n\nend\n\nfunction show_AreaDamageComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_float(\"circle_radius\", \"if > 0, will only damage entities inside the aabb rectangle which are closer than 'circle_radius' to the aabb center.\", component_id)\n        show_field_float(\"damage_per_frame\", nil, component_id)\n        show_field_int(\"update_every_n_frame\", nil, component_id)\n        show_field_EntityID(\"entity_responsible\", \"if NULL, will try to figure out who to blame\", component_id)\n        show_field_string(\"death_cause\", nil, component_id)\n        show_field_string(\"entities_with_tag\", \"damage entities with this tag\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_vec2(\"aabb_min\", nil, component_id)\n        show_field_vec2(\"aabb_max\", nil, component_id)\n        show_field_enum(\"damage_type\", \"the damage type\", component_id, damage_types)\n    end\n\nend\n\nfunction show_AttachToEntityComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_bool(\"only_position\", \"if 1, we only inherit position. it is calculated as follows: target_position + target_offset * target_scale\", component_id)\n        show_field_string(\"target_hotspot_tag\", \"if set, we apply the offset of target HotSpot with this tag\", component_id)\n        show_field_int(\"target_sprite_id\", \"if >= 0, the Nth sprite transform in target entity is inherited\", component_id)\n        show_field_bool(\"rotate_based_on_x_scale\", \"if 1, the rotation is set to 0 deg if scale >= 0 else to 180 deg\", component_id)\n        show_field_bool(\"destroy_component_when_target_is_gone\", \"should probably be on by default\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_EntityID(\"target\", \"EntityID of the entity we're attached to. This will fail after save/load, unfortunately\", component_id)\n        show_field_int(\"mUpdateFrame\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_types_xform(\"Transform\", nil, component_id)\n    end\n\nend\n\nfunction show_AudioComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_string(\"file\", nil, component_id)\n        show_field_string(\"event_root\", nil, component_id)\n        show_field_string(\"audio_physics_material\", nil, component_id)\n        show_field_bool(\"set_latest_event_position\", nil, component_id)\n        show_field_bool(\"remove_latest_event_on_destroyed\", nil, component_id)\n        show_field_bool(\"send_message_on_event_dead\", nil, component_id)\n        show_field_bool(\"play_only_if_visible\", \"plays sounds only if entity position is on screen and not covered by fog of war\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_material_id(\"m_audio_physics_material\", nil, component_id)\n        show_field_AudioSourceHandle(\"m_latest_source\", nil, component_id)\n    end\n\nend\n\nfunction show_AudioListenerComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_float(\"z\", nil, component_id)\n    end\n\nend\n\nfunction show_AudioLoopComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_string(\"file\", nil, component_id)\n        show_field_string(\"event_name\", nil, component_id)\n        show_field_bool(\"auto_play\", nil, component_id)\n        show_field_bool(\"auto_play_if_enabled\", nil, component_id)\n        show_field_bool(\"play_on_component_enable\", nil, component_id)\n        show_field_bool(\"calculate_material_lowpass\", nil, component_id)\n        show_field_bool(\"set_speed_parameter\", nil, component_id)\n        show_field_bool(\"set_speed_parameter_only_based_on_x_movement\", nil, component_id)\n        show_field_bool(\"set_speed_parameter_only_based_on_y_movement\", nil, component_id)\n        show_field_float(\"volume_autofade_speed\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_float(\"m_volume\", nil, component_id)\n        show_field_float(\"m_intensity\", nil, component_id)\n        show_field_float(\"m_intensity2\", nil, component_id)\n        show_field_AudioSourceHandle(\"m_source\", nil, component_id)\n        show_field_int(\"m_frame_created\", nil, component_id)\n    end\n\nend\n\nfunction show_BiomeTrackerComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_int(\"limit_to_every_n_frame\", \"if > 1, we will only check the biome every n frames\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        -- show_field_Biome*(\"unsafe_current_biome\", \"DO NOT ACCESS, since this can be in valid\", component_id)\n        show_field_unsupported(\"unsafe_current_biome\", \"DO NOT ACCESS, since this can be in valid\", component_id, \"Biome*\")\n        show_field_string(\"current_biome_name\", \"used to track in which biome we are at\", component_id)\n    end\n\nend\n\nfunction show_BlackHoleComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_float(\"radius\", nil, component_id)\n        show_field_float(\"particle_attractor_force\", nil, component_id)\n        show_field_float(\"damage_probability\", nil, component_id)\n        show_field_float(\"damage_amount\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_int(\"m_particle_attractor_id\", nil, component_id)\n    end\n\nend\n\nfunction show_BookComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_float(\"TEMP_TEMPY\", nil, component_id)\n        show_field_float(\"TEMP_TEMP_TEMP\", nil, component_id)\n    end\n\nend\n\nfunction show_BossDragonComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_float(\"speed\", nil, component_id)\n        show_field_float(\"speed_hunt\", nil, component_id)\n        show_field_float(\"acceleration\", nil, component_id)\n        show_field_float(\"direction_adjust_speed\", nil, component_id)\n        show_field_float(\"direction_adjust_speed_hunt\", nil, component_id)\n        show_field_float(\"gravity\", nil, component_id)\n        show_field_float(\"tail_gravity\", nil, component_id)\n        show_field_float(\"part_distance\", nil, component_id)\n        show_field_int(\"ground_check_offset\", nil, component_id)\n        show_field_float(\"eat_ground_radius\", nil, component_id)\n        show_field_bool(\"eat_ground\", \"does the worm destroy the ground it moves through or not?\", component_id)\n        show_field_float(\"hitbox_radius\", nil, component_id)\n        show_field_float(\"bite_damage\", \"how much damage does this do when it hits an entity\", component_id)\n        show_field_float(\"target_kill_radius\", nil, component_id)\n        show_field_float(\"target_kill_ragdoll_force\", nil, component_id)\n        show_field_float(\"hunt_box_radius\", nil, component_id)\n        show_field_float(\"random_target_box_radius\", nil, component_id)\n        show_field_int(\"new_hunt_target_check_every\", nil, component_id)\n        show_field_int(\"new_random_target_check_every\", nil, component_id)\n        show_field_float(\"jump_cam_shake\", nil, component_id)\n        show_field_float(\"jump_cam_shake_distance\", nil, component_id)\n        show_field_float(\"eat_anim_wait_mult\", nil, component_id)\n        show_field_string(\"projectile_1\", nil, component_id)\n        show_field_int(\"projectile_1_count\", nil, component_id)\n        show_field_string(\"projectile_2\", nil, component_id)\n        show_field_int(\"projectile_2_count\", nil, component_id)\n        show_field_file_single(\"ragdoll_filename\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_int(\"mTargetEntityId\", nil, component_id)\n        show_field_vec2(\"mTargetVec\", nil, component_id)\n        show_field_float(\"mGravVelocity\", nil, component_id)\n        show_field_float(\"mSpeed\", nil, component_id)\n        show_field_vec2(\"mRandomTarget\", nil, component_id)\n        show_field_vec2(\"mLastLivingTargetPos\", nil, component_id)\n        show_field_int(\"mNextTargetCheckFrame\", nil, component_id)\n        show_field_int(\"mNextHuntTargetCheckFrame\", nil, component_id)\n        show_field_bool(\"mOnGroundPrev\", nil, component_id)\n        show_field_int(\"mMaterialIdPrev\", nil, component_id)\n        show_field_int(\"mPhase\", nil, component_id)\n        show_field_int(\"mNextPhaseSwitchTime\", nil, component_id)\n        show_field_float(\"mPartDistance\", nil, component_id)\n        show_field_bool(\"mIsInitialized\", nil, component_id)\n    end\n\nend\n\nfunction show_BossHealthBarComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_bool(\"gui\", nil, component_id)\n        show_field_bool(\"gui_special_final_boss\", nil, component_id)\n        show_field_bool(\"in_world\", nil, component_id)\n        show_field_float(\"gui_max_distance_visible\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_bool(\"mOldSpritesDestroyed\", nil, component_id)\n    end\n\nend\n\nfunction show_CameraBoundComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_bool(\"enabled\", \"If enabled, kills this component if it's outside the camera distance\", component_id)\n        show_field_float(\"distance\", \"Distance in pixels from the center of camera, if outside this distance the entity is destroyed\", component_id)\n        show_field_float(\"distance_border\", \"Offset towards camera in pixels from 'distance' where the entity is respawned if it was frozen\", component_id)\n        show_field_int(\"max_count\", \"If more than 'max_count' entities of this type exist the one furthest from camera is destroyed\", component_id)\n        show_field_bool(\"freeze_on_distance_kill\", \"If true and the entity went too far - this entity will be stored so we can later respawn it where it was destroyed because it got too far from the camera?\", component_id)\n        show_field_bool(\"freeze_on_max_count_kill\", \"If true and the entity was one too many of its kind - this entity will be stored so we can later respawn it where it was destroyed because it got too far from the camera?\", component_id)\n    end\n\nend\n\nfunction show_CardinalMovementComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_bool(\"horizontal_movement\", \"allow horizontal movement\", component_id)\n        show_field_bool(\"vertical_movement\", \"allow vertical movement\", component_id)\n        show_field_bool(\"intercardinal_movement\", \"allow intercardinal movement\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_vec2(\"mPrevPos\", nil, component_id)\n    end\n\nend\n\nfunction show_CellEaterComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_float(\"radius\", nil, component_id)\n        show_field_int(\"eat_probability\", nil, component_id)\n        show_field_bool(\"only_stain\", nil, component_id)\n        show_field_bool(\"eat_dynamic_physics_bodies\", nil, component_id)\n        show_field_bool(\"limited_materials\", \"if true, will only eat the materials defined in material_list\", component_id)\n        show_field_string(\"ignored_material_tag\", \"if set, will not eat any materials with this tag. please note that this lowers the performance of cell eating by some amount.\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_material_id(\"ignored_material\", \"String name of a material that shouldn't be eaten by the component\", component_id)\n        show_field_material_id_list(\"materials\", \"is a list of accepted materials sorted\", component_id)\n    end\n\nend\n\nfunction show_CharacterCollisionComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_int(\"getting_crushed_threshold\", nil, component_id)\n        show_field_int(\"moving_up_before_getting_crushed_threshold\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_int(\"getting_crushed_counter\", \"1.12.2018 - Is this still used?\", component_id)\n        show_field_int(\"stuck_in_ground_counter\", \"used this mostly for player to figure out if it's stuck in ground\", component_id)\n        show_field_bool(\"mCollidedHorizontally\", nil, component_id)\n    end\n\nend\n\nfunction show_CharacterDataComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_int(\"platforming_type\", \"0 = oldest, 1 = newer, 2 = safest\", component_id)\n        show_field_float(\"mass\", \"1.0 = approx. mass of player\", component_id)\n        show_field_int(\"buoyancy_check_offset_y\", nil, component_id)\n        show_field_float(\"liquid_velocity_coeff\", \"how much do liquids move this character. e.g. when standing in a flowing river\", component_id)\n        show_field_float(\"gravity\", nil, component_id)\n        show_field_float(\"fly_recharge_spd\", nil, component_id)\n        show_field_float(\"fly_recharge_spd_ground\", nil, component_id)\n        show_field_bool(\"flying_needs_recharge\", \"const variable... player has this as true\", component_id)\n        show_field_int(\"flying_in_air_wait_frames\", \"to fix the tap tap tap flying cheese, we wait this many frames before recharging in air\", component_id)\n        show_field_int(\"flying_recharge_removal_frames\", \"another fix to the tap tap - this is how many frames from pressing down up we'll remove fly charge\", component_id)\n        show_field_int(\"climb_over_y\", nil, component_id)\n        show_field_int(\"check_collision_max_size_x\", nil, component_id)\n        show_field_int(\"check_collision_max_size_y\", nil, component_id)\n        show_field_bool(\"is_on_ground\", nil, component_id)\n        show_field_bool(\"is_on_slippery_ground\", nil, component_id)\n        show_field_float(\"ground_stickyness\", nil, component_id)\n        show_field_bool(\"effect_hit_ground\", nil, component_id)\n        show_field_int(\"eff_hg_damage_min\", \"if we want to damage ground when hitting it... this is the place\", component_id)\n        show_field_int(\"eff_hg_damage_max\", \"if we want to damage ground when hitting it... this is the place\", component_id)\n        show_field_float(\"eff_hg_position_x\", nil, component_id)\n        show_field_float(\"eff_hg_position_y\", nil, component_id)\n        show_field_float(\"eff_hg_size_x\", nil, component_id)\n        show_field_float(\"eff_hg_size_y\", nil, component_id)\n        show_field_float(\"eff_hg_velocity_min_x\", nil, component_id)\n        show_field_float(\"eff_hg_velocity_max_x\", nil, component_id)\n        show_field_float(\"eff_hg_velocity_min_y\", nil, component_id)\n        show_field_float(\"eff_hg_velocity_max_y\", nil, component_id)\n        show_field_float(\"eff_hg_offset_y\", nil, component_id)\n        show_field_bool(\"eff_hg_update_box2d\", \"if true, will move physics bodies that it hits\", component_id)\n        show_field_float(\"eff_hg_b2force_multiplier\", \"multiplies the velocity with this...\", component_id)\n        show_field_float(\"destroy_ground\", \"how much damage do we do the ground when land on it\", component_id)\n        show_field_bool(\"send_transform_update_message\", \"if 1, will send Message_TransformUpdated to updated entities and their children when the component is processed by PlayerCollisionSystem or CharacterCollisionSystem\", component_id)\n        show_field_bool(\"dont_update_velocity_and_xform\", \"might be useful if you want to use CharacterCollisionSystem to only update on_ground status\", component_id)\n        show_field_float(\"mFlyingTimeLeft\", \"How much flying energy do we have left? - NOTE( Petri ): 1.3.2023 - This used to be a private variable. It was changed to fix the save/load infinite flying bug.\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_int(\"mFramesOnGround\", nil, component_id)\n        show_field_int(\"mLastFrameOnGround\", nil, component_id)\n        show_field_vec2(\"mVelocity\", nil, component_id)\n        show_field_bool(\"mCollidedHorizontally\", \"moved this here from CharacterCollisionComponent - since that is multithreaded and we needed a non multithreaded version\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_spread_aabb(\"collision_aabb\", nil, component_id)\n        show_field_float(\"fly_time_max\", \"how much flying energy + \", component_id)\n    end\n\nend\n\nfunction show_CharacterPlatformingComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_float(\"jump_velocity_x\", nil, component_id)\n        show_field_float(\"jump_velocity_y\", nil, component_id)\n        show_field_int(\"jump_keydown_buffer\", nil, component_id)\n        show_field_float(\"fly_speed_mult\", \"AI stuff\", component_id)\n        show_field_float(\"fly_speed_change_spd\", \"player\", component_id)\n        show_field_bool(\"fly_model_player\", \"if true, uses player fly model\", component_id)\n        show_field_bool(\"fly_smooth_y\", \"if true, smooths out the AI fly model\", component_id)\n        show_field_float(\"accel_x\", nil, component_id)\n        show_field_float(\"accel_x_air\", nil, component_id)\n        show_field_float(\"pixel_gravity\", nil, component_id)\n        show_field_float(\"swim_idle_buoyancy_coeff\", nil, component_id)\n        show_field_float(\"swim_down_buoyancy_coeff\", nil, component_id)\n        show_field_float(\"swim_up_buoyancy_coeff\", nil, component_id)\n        show_field_float(\"swim_drag\", \"when in water velocity *= swim_drag\", component_id)\n        show_field_float(\"swim_extra_horizontal_drag\", \"when in water velocity.x *= swim_extra_horizontal_drag\", component_id)\n        show_field_bool(\"mouse_look\", nil, component_id)\n        show_field_float(\"mouse_look_buffer\", nil, component_id)\n        show_field_bool(\"keyboard_look\", \"if true, turns based on if left or right has been pressed down\", component_id)\n        show_field_float(\"turning_buffer\", nil, component_id)\n        show_field_string(\"animation_to_play\", nil, component_id)\n        show_field_string(\"animation_to_play_next\", nil, component_id)\n        show_field_float(\"run_animation_velocity_switching_threshold\", nil, component_id)\n        show_field_bool(\"run_animation_velocity_switching_enabled\", nil, component_id)\n        show_field_int(\"turn_animation_frames_between\", nil, component_id)\n        show_field_int(\"precision_jumping_max_duration_frames\", \"maximum duration of precision jump or knockback. -1 = infinite\", component_id)\n        show_field_float(\"audio_liquid_splash_intensity\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_vec2(\"mExAnimationPos\", nil, component_id)\n        show_field_int(\"mFramesInAirCounter\", nil, component_id)\n        show_field_bool(\"mIsPrecisionJumping\", nil, component_id)\n        show_field_int(\"mPrecisionJumpingTime\", nil, component_id)\n        show_field_float(\"mPrecisionJumpingSpeedX\", nil, component_id)\n        show_field_int(\"mPrecisionJumpingTimeLeft\", nil, component_id)\n        show_field_float(\"mFlyThrottle\", nil, component_id)\n        show_field_float(\"mSmoothedFlyingTargetY\", nil, component_id)\n        show_field_int(\"mJetpackEmitting\", \"-1 = undefined, 0 = not emitting, 1 = emitting\", component_id)\n        show_field_int(\"mNextTurnAnimationFrame\", nil, component_id)\n        show_field_int(\"mFramesNotSwimming\", \"0 = currently swimming\", component_id)\n        show_field_int(\"mFramesSwimming\", \"0 = not currently swimming\", component_id)\n        show_field_bool(\"mShouldCrouch\", nil, component_id)\n        show_field_bool(\"mShouldCrouchPrev\", nil, component_id)\n        show_field_int(\"mLastPostureSwitchFrame\", nil, component_id)\n        show_field_int(\"mLookOverrideLastFrame\", nil, component_id)\n        show_field_int(\"mLookOverrideDirection\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_spread_aabb(\"velocity\", nil, component_id)\n        show_field_float(\"run_velocity\", nil, component_id)\n        show_field_float(\"fly_velocity_x\", nil, component_id)\n        show_field_float(\"fly_speed_max_up\", nil, component_id)\n        show_field_float(\"fly_speed_max_down\", nil, component_id)\n    end\n\nend\n\nfunction show_CharacterStatsComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Privates\") then\n        -- show_field_CharacterStatsModifier(\"stats\", nil, component_id)\n        show_field_unsupported(\"stats\", nil, component_id, \"CharacterStatsModifier\")\n    end\n\nend\n\nfunction show_CollisionTriggerComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_float(\"width\", nil, component_id)\n        show_field_float(\"height\", nil, component_id)\n        show_field_float(\"radius\", nil, component_id)\n        show_field_string(\"required_tag\", nil, component_id)\n        show_field_bool(\"remove_component_when_triggered\", nil, component_id)\n        show_field_bool(\"destroy_this_entity_when_triggered\", 