rivates\") then\n        show_field_float(\"rotation_speed\", nil, component_id)\n        show_field_float(\"mStartingMass\", nil, component_id)\n        show_field_bool(\"mMainBodyFound\", nil, component_id)\n        show_field_int(\"mNextFrameActive\", nil, component_id)\n        show_field_float(\"mRotationTarget\", nil, component_id)\n        show_field_vec2(\"mLastPositionWhenHadPath\", nil, component_id)\n        show_field_bool(\"mHasLastPosition\", nil, component_id)\n    end\n\nend\n\nfunction show_PhysicsBody2Component_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        -- show_field_b2ObjectID(\"mBodyId\", \"this is mBody->GetBodyId() - not to be confused with uid, has to be tracked separately, since the mBody pointer is not unique\", component_id)\n        show_field_unsupported(\"mBodyId\", \"this is mBody->GetBodyId() - not to be confused with uid, has to be tracked separately, since the mBody pointer is not unique\", component_id, \"b2ObjectID\")\n        show_field_float(\"linear_damping\", nil, component_id)\n        show_field_float(\"angular_damping\", nil, component_id)\n        show_field_bool(\"allow_sleep\", nil, component_id)\n        show_field_bool(\"fixed_rotation\", nil, component_id)\n        show_field_bool(\"is_bullet\", nil, component_id)\n        show_field_bool(\"is_static\", nil, component_id)\n        show_field_float(\"buoyancy\", nil, component_id)\n        show_field_bool(\"hax_fix_going_through_ground\", \"if 1, will lift the body upwards if it is inside ground\", component_id)\n        show_field_bool(\"hax_fix_going_through_sand\", \"hax_fix_going_through_ground has to be set, if set will lift the body upwards if it is inside sand\", component_id)\n        show_field_bool(\"hax_wait_till_pixel_scenes_loaded\", nil, component_id)\n        show_field_bool(\"go_through_sand\", \"if 1, will go through sand PhysicsBridge::mGoThroughSand = 1\", component_id)\n        show_field_bool(\"auto_clean\", \"if 1, the simulation might destroy this body if it's hidden under sand. Problematic if you have a small piece with joint attached to something like the wheels of minecart. Set to 0 in cases like that\", component_id)\n        show_field_bool(\"force_add_update_areas\", \"if 1, we will mark our predicted aabb as a box2d update area.\", component_id)\n        show_field_bool(\"update_entity_transform\", nil, component_id)\n        show_field_bool(\"kill_entity_if_body_destroyed\", \"if 1, will kill the entity when physics body is destroyed\", component_id)\n        show_field_bool(\"kill_entity_after_initialized\", \"if 1, will destroy the entity after initialization has been done based the entity's PhysicsBodyComponents and JointComponents\", component_id)\n        show_field_bool(\"manual_init\", \"if 1, initialization occurs only when done via for example lua component and Physic2InitFromComponents()\", component_id)\n        show_field_bool(\"destroy_body_if_entity_destroyed\", \"if 1, root body is destroyed if the entity is destroyed\", component_id)\n        show_field_float(\"root_offset_x\", \"TODO\", component_id)\n        show_field_float(\"root_offset_y\", \"TODO\", component_id)\n        show_field_float(\"init_offset_x\", \"TODO\", component_id)\n        show_field_float(\"init_offset_y\", \"TODO\", component_id)\n        show_field_bool(\"mActiveState\", \"private variable, please don't mess around with this\", component_id)\n        show_field_int(\"mPixelCountOrig\", \"the number of pixels the body had when it was originally created\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        -- show_field_b2Body*(\"mBody\", nil, component_id)\n        show_field_unsupported(\"mBody\", nil, component_id, \"b2Body*\")\n        show_field_bool(\"mInitialized\", \"private variable, please don't mess around with this\", component_id)\n        show_field_int(\"mPixelCount\", \"if set, tracks the number of csolidcells the body has\", component_id)\n        show_field_bool(\"mRefreshed\", \"this is sure the bodies are only parsed once\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_vec2(\"mLocalPosition\", \"private variable, please don't mess around with this\", component_id)\n    end\n\nend\n\nfunction show_PhysicsBodyCollisionDamageComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_float(\"speed_threshold\", nil, component_id)\n        show_field_float(\"damage_multiplier\", nil, component_id)\n    end\n\nend\n\nfunction show_PhysicsBodyComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_bool(\"is_external\", \"if mBody is set from outside, will ignore all the things\", component_id)\n        show_field_bool(\"hax_fix_going_through_ground\", \"if set will lift the body upwards if it is inside ground\", component_id)\n        show_field_bool(\"hax_fix_going_through_sand\", \"hax_fix_going_through_ground has to be set, if set will lift the body upwards if it is inside sand\", component_id)\n        show_field_bool(\"hax_wait_till_pixel_scenes_loaded\", nil, component_id)\n        show_field_int(\"uid\", \"if the entity has multiple physics bodies and has specific shapes for those and possible joints, you should use this. 0 is default for shapes\", component_id)\n        show_field_bool(\"is_enabled\", \"Use this to kill the physics body of. if is_enabled is set to false, will destroy the physics body\", component_id)\n        show_field_float(\"linear_damping\", nil, component_id)\n        show_field_float(\"angular_damping\", nil, component_id)\n        show_field_bool(\"allow_sleep\", nil, component_id)\n        show_field_bool(\"fixed_rotation\", nil, component_id)\n        show_field_float(\"buoyancy\", nil, component_id)\n        show_field_float(\"gravity_scale_if_has_no_image_shapes\", nil, component_id)\n        show_field_bool(\"is_bullet\", nil, component_id)\n        show_field_bool(\"is_static\", nil, component_id)\n        show_field_bool(\"is_kinematic\", nil, component_id)\n        show_field_bool(\"is_character\", \"if it is a character, then we need to few interesting things from time to time\", component_id)\n        show_field_bool(\"go_through_sand\", \"if set, will go through sand PhysicsBridge::mGoThroughSand = 1\", component_id)\n        show_field_bool(\"gridworld_box2d\", \"default is 1. You should only change this if you know the body isn't going to touch gridworld\", component_id)\n        show_field_bool(\"auto_clean\", \"if set, the simulation might destroy this body if it's hidden under sand. Problematic if you have a small piece with joint attached to something like the wheels of minecart. Set to 0 in cases like that\", component_id)\n        show_field_bool(\"on_death_leave_physics_body\", \"if set, will leave the b2body into the world, even if the entity is killed\", component_id)\n        show_field_bool(\"on_death_really_leave_body\", \"camera bound... god damn... we need something special when we want to leave the body\", component_id)\n        show_field_bool(\"update_entity_transform\", \"WARNING! Don't touch this unless you know what you're doing. If false, doesn't update the entitys transform to match the physics body. This is used with multi body entities, to use the correct body to update the entity, e.g. minecart\", component_id)\n        show_field_bool(\"force_add_update_areas\", \"if 1, we will mark our predicted aabb as a box2d update area.\", component_id)\n        show_field_bool(\"kills_entity\", \"if set, will kill the entity when physics body is destroyed\", component_id)\n        show_field_bool(\"projectiles_rotate_toward_velocity\", \"for physics projectiles, if true will initially rotate the body based on the velocity\", component_id)\n        show_field_bool(\"randomize_init_velocity\", \"randomizes the init velocity\", component_id)\n        show_field_bool(\"mActiveState\", \"private variable, please don't mess around with this\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        -- show_field_b2Body*(\"mBody\", nil, component_id)\n        show_field_unsupported(\"mBody\", nil, component_id, \"b2Body*\")\n        -- show_field_b2ObjectID(\"mBodyId\", \"this is mBody->GetBodyId() - not to be confused with uid shit, has to be tracked separately, since the mBody pointer is not unique\", component_id)\n        show_field_unsupported(\"mBodyId\", \"this is mBody->GetBodyId() - not to be confused with uid shit, has to be tracked separately, since the mBody pointer is not unique\", component_id, \"b2ObjectID\")\n        show_field_int(\"mPixelCount\", \"if set, tracks the number of csolidcells the body has\", component_id)\n        -- show_field_b2Vec2(\"mLocalPosition\", nil, component_id)\n        show_field_unsupported(\"mLocalPosition\", nil, component_id, \"b2Vec2\")\n        show_field_bool(\"mRefreshed\", \"this is sure the bodies are only parsed once\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_vec2(\"initial_velocity\", \"if you want a velocity at the start, set it here\", component_id)\n    end\n\nend\n\nfunction show_PhysicsImageShapeComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_bool(\"is_root\", \"if 1, PhysicsBody2Component will use this to figure out where the entity is located\", component_id)\n        show_field_int(\"body_id\", \"used to figure out which bodies are attached to each other when creating joints\", component_id)\n        show_field_bool(\"use_sprite\", \"will try to find the SpriteComponent and use that\", component_id)\n        show_field_bool(\"is_circle\", \"tries to fit this into a circle, looks at bounding box of the pixels and sets the circle to the center of that with radius being the line from there to a straight edge\", component_id)\n        show_field_bool(\"centered\", \"if this is true, moves offset to be in the center of the image, overwrites the offset_x, offset_y\", component_id)\n        show_field_float(\"offset_x\", \"offset x in pixels\", component_id)\n        show_field_float(\"offset_y\", \"offset y in pixels\", component_id)\n        show_field_float(\"z\", \"offset in the z direction\", component_id)\n        show_field_file_single(\"image_file\", \"the png file from which the body is created from\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        -- show_field_b2Body*(\"mBody\", \"used in joint creation phase\", component_id)\n        show_field_unsupported(\"mBody\", \"used in joint creation phase\", component_id, \"b2Body*\")\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_material_id(\"material\", \"the material from which the body is created\", component_id)\n    end\n\nend\n\nfunction show_PhysicsJoint2Component_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_int(\"joint_id\", \"Use this to create a relation between PhysicsJointMutator and a joint. The PhysicsJointMutator must exist when the physics objects are initialized for the first time. This id should be unique inside one entity. Defaults to 0\", component_id)\n        show_field_float(\"break_force\", \"if > 0, will break if theres a force too strong.\", component_id)\n        show_field_float(\"break_distance\", \"if > 0, will break if the anchors on the bodies get further than this.\", component_id)\n        show_field_bool(\"break_on_body_modified\", \"if > 1, will break if an attached body is modified\", component_id)\n        show_field_float(\"break_on_shear_angle_deg\", \"if > 0, will break if the angle between the linked bodies becomes greater than this\", component_id)\n        show_field_int(\"body1_id\", nil, component_id)\n        show_field_int(\"body2_id\", nil, component_id)\n        show_field_float(\"offset_x\", nil, component_id)\n        show_field_float(\"offset_y\", nil, component_id)\n        show_field_float(\"ray_x\", nil, component_id)\n        show_field_float(\"ray_y\", nil, component_id)\n        show_field_float(\"surface_attachment_offset_x\", nil, component_id)\n        show_field_float(\"surface_attachment_offset_y\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_enum(\"type\", \"Enum - REVOLUTE_JOINT, WELD_JOINT, REVOLUTE_JOINT_ATTACH_TO_NEARBY_SURFACE or WELD_JOINT_ATTACH_TO_NEARBY_SURFACE\", component_id, joint_type)\n    end\n\nend\n\nfunction show_PhysicsJoint2MutatorComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_int(\"joint_id\", \"Use this to create a relation between PhysicsJointMutator and a joint created by PhysicsJoint2Component. The PhysicsJoint2Mutator must exist when the physics objects are initialized for the first time.\", component_id)\n        show_field_bool(\"destroy\", \"if 1, the joint will break and this component will be destroyed.\", component_id)\n        show_field_float(\"motor_speed\", \"if != 0 and this is linked to a revolute joint, the joint motor will be enabled at this speed\", component_id)\n        show_field_float(\"motor_max_torque\", \"max torque for motor\", component_id)\n        show_field_uint64(\"mBox2DJointId\", \"Private, don't touch this! Stores the joint's id in the physics engine.\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_float(\"mPreviousMotorSpeed\", nil, component_id)\n        show_field_float(\"mPreviousMotorMaxTorque\", nil, component_id)\n    end\n\nend\n\nfunction show_PhysicsJointComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n      