d)\n    end\n\nend\n\nfunction show_PlayerCollisionComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_int(\"getting_crushed_threshold\", nil, component_id)\n        show_field_int(\"moving_up_before_getting_crushed_threshold\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_int(\"getting_crushed_counter\", \"1.12.2018 - Is this still used?\", component_id)\n        show_field_int(\"stuck_in_ground_counter\", \"used this mostly for player to figure out if it's stuck in ground\", component_id)\n        show_field_int(\"DEBUG_stuck_in_static_ground\", \"used to report error + also to free the player in case something horrible has gone wrong\", component_id)\n        show_field_bool(\"mCollidedHorizontally\", nil, component_id)\n        -- show_field_b2Body*(\"mPhysicsCollisionHax\", \"hax\", component_id)\n        show_field_unsupported(\"mPhysicsCollisionHax\", \"hax\", component_id, \"b2Body*\")\n    end\n\nend\n\nfunction show_PlayerStatsComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_int(\"lives\", nil, component_id)\n        show_field_float(\"max_hp\", nil, component_id)\n        show_field_float(\"speed\", nil, component_id)\n    end\n\nend\n\nfunction show_PositionSeedComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_float(\"pos_x\", nil, component_id)\n        show_field_float(\"pos_y\", nil, component_id)\n    end\n\nend\n\nfunction show_PotionComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_float(\"spray_velocity_coeff\", nil, component_id)\n        show_field_float(\"spray_velocity_normalized_min\", nil, component_id)\n        show_field_bool(\"body_colored\", nil, component_id)\n        show_field_bool(\"throw_bunch\", nil, component_id)\n        show_field_int(\"throw_how_many\", nil, component_id)\n        show_field_bool(\"dont_spray_static_materials\", \"NOTE( Petri ): 15.8.2023 - if this is set to true, will only spray dynamic materials, that dont cause bugs (i.e. will not spray hard rock, box2d materials)\", component_id)\n        show_field_bool(\"dont_spray_just_leak_gas_materials\", \"NOTE( Petri ): 15.8.2023 - if this is set to true, will only leak gas materials instead of 'spraying' them.\", component_id)\n        show_field_bool(\"never_color\", \"Petri: body_colored didn't seem to work, so I added never_color. It can be set to true if you never want the potion to be colored\", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_material_id(\"custom_color_material\", \"if set, will always use the color from this material\", component_id)\n    end\n\nend\n\nfunction show_PressurePlateComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_int(\"check_every_x_frames\", \"how often do we check the world\", component_id)\n        show_field_int(\"state\", \"0 is up, 1 is down\", component_id)\n        show_field_float(\"material_percent\", \"how much material should there be in the aabbs that we go down \", component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_int(\"mNextFrame\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_vec2(\"aabb_min\", nil, component_id)\n        show_field_vec2(\"aabb_max\", nil, component_id)\n    end\n\nend\n\nfunction show_ProjectileComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_int(\"lifetime\", \"lifetime, -1 means it's endless, otherwise it's the frame count\", component_id)\n        show_field_int(\"lifetime_randomness\", \"final lifetime will be lifetime + random(-lifetime_randomness,lifetime_randomness)\", component_id)\n        show_field_bool(\"on_lifetime_out_explode\", \"when lifetime runs out, should we explode?\", component_id)\n        show_field_bool(\"collide_with_world\", \"true by default. Some projectiles you don't want to collide with the world, e.g. blackholes\", component_id)\n        show_field_float(\"speed_min\", nil, component_id)\n        show_field_float(\"speed_max\", nil, component_id)\n        show_field_float(\"friction\", nil, component_id)\n        show_field_float(\"direction_random_rad\", \"when fired, randomizes the velocity -this, this\", component_id)\n        show_field_float(\"direction_nonrandom_rad\", \"when fired, multiplies this with projectile_i and adds it to direction\", component_id)\n        show_field_float(\"lob_min\", nil, component_id)\n        show_field_float(\"lob_max\", nil, component_id)\n        show_field_float(\"camera_shake_when_shot\", nil, component_id)\n        show_field_float(\"shoot_light_flash_radius\", nil, component_id)\n        show_field_int(\"shoot_light_flash_r\", nil, component_id)\n        show_field_int(\"shoot_light_flash_g\", nil, component_id)\n        show_field_int(\"shoot_light_flash_b\", nil, component_id)\n        show_field_bool(\"create_shell_casing\", \"should we create shell casings?\", component_id)\n        show_field_string(\"shell_casing_material\", \"material of the shell casing\", component_id)\n        show_field_file_single(\"muzzle_flash_file\", \"this entity is created along with the projectile, oriented along the projectile's path\", component_id)\n        show_field_int(\"bounces_left\", nil, component_id)\n        show_field_float(\"bounce_energy\", \"when bouncing, velocity is multiplied by this\", component_id)\n        show_field_bool(\"bounce_always\", \"if true, will do a fake bounce if can't do the proper bounce, but will always try to bounce\", component_id)\n        show_field_bool(\"bounce_at_any_angle\", \"if true, will bounce at any reflection angle\", component_id)\n        show_field_bool(\"attach_to_parent_trigger\", \"if true, will attach to the projectile entity that created this projectile via a trigger\", component_id)\n        show_field_file_single(\"bounce_fx_file\", \"this entity is created at the bounce position. it gets the bounce angle as rotation.\", component_id)\n        show_field_float(\"angular_velocity\", \"this is only applied if velocity_sets_rotation == false\", component_id)\n        show_field_bool(\"velocity_sets_rotation\", \"whether we set the rotation based on velocity, as in spear or if we update the rotation with angular_velocity\", component_id)\n        show_field_bool(\"velocity_sets_scale\", \"if true, the sprite width is made equal to the distance traveled since last frame\", component_id)\n        show_field_float(\"velocity_sets_scale_coeff\", \"Larger value means velocity affects the scale more\", component_id)\n        show_field_bool(\"velocity_sets_y_flip\", \"if true, the sprite is flipped based on which side the projectile is currently traveling\", component_id)\n        show_field_float(\"velocity_updates_animation\", \"updates the animation based on far the sprite moved\", component_id)\n        show_field_float(\"ground_penetration_coeff\", \"if > 0, this, along with VelocityComponent.mass affects how far we penetrate in materials\", component_id)\n        show_field_int(\"ground_penetration_max_durability_to_destroy\", \"if 0, will not penetrate into materials with durability greater than this\", component_id)\n        show_field_string(\"go_through_this_material\", \"if set, we never collide with this material\", component_id)\n        show_field_bool(\"do_moveto_update\", \"this should probably be true, to get normal projectile behaviour, but you might want to disable this for some physics-based projectiles, like bombs\", component_id)\n        show_field_int(\"on_death_duplicate_remaining\", \"if greater than 0, the projectile creates two clones of itself on death. 'on_death_duplicate_remaining' on the clones is reduced by one\", component_id)\n        show_field_bool(\"on_death_gfx_leave_sprite\", \"if true, finds all the sprites and leaves as sand cells into the grid\", component_id)\n        show_field_bool(\"on_death_explode\", \"if true, does explosion with config_explosion\", component_id)\n        show_field_bool(\"on_death_emit_particle\", \"if true, emits on_death_emit_particle_type on death\", component_id)\n        show_field_int(\"on_death_emit_particle_count\", \"how many particles should we emit\", component_id)\n        show_field_bool(\"die_on_liquid_collision\", \"if true, dies on collision with liquids\", component_id)\n        show_field_bool(\"die_on_low_velocity\", \"if true, dies when speed goes below die_on_low_velocity_limit\", component_id)\n        show_field_float(\"die_on_low_velocity_limit\", \"please see die_on_low_velocity\", component_id)\n        show_field_string(\"on_death_emit_particle_type\", nil, component_id)\n        show_field_bool(\"on_death_particle_check_concrete\", \"if you want it to stick as concrete, you should enable this\", component_id)\n        show_field_bool(\"ground_collision_fx\", \"if 1, spurt some particles when colliding with mortals\", component_id)\n        show_field_bool(\"explosion_dont_damage_shooter\", \"if true, explosion doesn't damage the entity who shot this\", component_id)\n        show_field_float(\"on_death_item_pickable_radius\", \"if > 0, makes items closer than this radius pickable on death\", component_id)\n        show_field_bool(\"penetrate_world\", \"if true, the projectile doesn't collide with ground, liquids, physical objects etc\", component_id)\n        show_field_float(\"penetrate_world_velocity_coeff\", \"if 'penetrate_world' is true, the projectile moves with a velocity multiplied by this value when inside world\", component_id)\n        show_field_bool(\"penetrate_entities\", \"if true, the projectile doesn't stop when it collides with entities. damages each entity only once\", component_id)\n        show_field_bool(\"on_collision_die\", \"if true, this is killed as soon as it hits the ground\", component_id)\n        show_field_bool(\"on_collision_remove_projectile\", \"if true, ProjectileComponent is removed from the entitiy\", component_id)\n        show_field_bool(\"on_collision_spawn_entity\", \"if true, spawns the spawn_entity\", component_id)\n        show_field_string(\"spawn_entity\", \"this is spawned if hit something an on_collision_spawn_entity = 1\", component_id)\n        show_field_bool(\"spawn_entity_is_projectile\", \"if true, will use ShootProjectile instead of LoadEntity()\", component_id)\n        show_field_float(\"physics_impulse_coeff\", \"projectile applies an impulse to physics bodies it hits. Impulse = physics_impulse_coeff * velocity\", component_id)\n        show_field_int(\"damage_every_x_frames\", \"if set != -1, will only do damage every x frames, used for fields and such, which would otherwise do damage every frame\", component_id)\n        show_field_bool(\"damage_scaled_by_speed\", \"if 1, damage is multiplied by (projectile speed / original projectile speed) ratio\", component_id)\n        show_field_float(\"damage_scale_max_speed\", \"if > 0 and damage_scaled_by_speed = 1, will use this instead of mInitialSpeed when calculating the damage\", component_id)\n        show_field_bool(\"collide_with_entities\", \"if 1, looks for entities with tag, collide_with_tag and collides with them, giving them damage\", component_id)\n        show_field_string(\"collide_with_tag\", \"default: mortal, if you needed can be changed to something more specific\", component_id)\n        show_field_string(\"dont_collide_with_tag\", \"if set will ignore entities with this tag\", component_id)\n        show_field_int(\"collide_with_shooter_frames\", \"remember friendly_fire 1, if -1 won't collide with shooter at all, otherwise uses the value as frame count and while it's running won't damage the shooter \", component_id)\n        show_field_bool(\"friendly_fire\", \"if true, will damage same herd id\", component_id)\n        show_field_float(\"damage\", \"how much Projectile damage does this do when it hits something\", component_id)\n        show_field_float(\"knockback_force\", \"How far do entities get thrown if a knockback occurs. final_knockback = ProjectileComponent.knockback_force * VelocityComponent.mVelocity * VelocityComponent.mass / who_we_hit.mass\", component_id)\n        show_field_float(\"ragdoll_force_multiplier\", \"velocity * ragdoll_force_multiplier is applied to any ragdolls that are created by entities killed by this\", component_id)\n        show_field_float(\"hit_particle_force_multiplier\", \"hit particle velocity = projectile_velocity * hit_particle_force_multiplier * some randomness\", component_id)\n        show_field_float(\"blood_count_multiplier\", \"how much blood does this projectile cause\", component_id)\n        show_field_string(\"damage_game_effect_entities\", \"a list of game_effects entities separated with ','. e.g. 'data/entities/misc/effect_electrocution.xml,data/entities/misc/effect_on_fire.xml' \", component_id)\n        show_field_bool(\"never_hit_player\", \"If 1, does not hit player no matter what herds this and player belong to\", component_id)\n        show_field_bool(\"collect_materials_to_shooter\", \"if 1, looks up the 'who_shot' entity and its MaterialInventoryComponent on destruction and updates it based on the cells destroyed on our explosion.\", component_id)\n        show_field_bool(\"play_damage_sounds\", nil, component_id)\n        show_field_int(\"mLastFrameDamaged\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_EntityID(\"mWhoShot\", \"entity (creature) that shot this\", component_id)\n        show_field_EntityTypeID(\"mWhoShotEntityTypeID\", \"used for stats\", component_id)\n        show_field_int(\"mShooterHerdId\", \"the herdid of mWhoShot, unless friendly fire\", component_id)\n        show_field_int(\"mStartingLifetime\", nil, component_id)\n        show_field_EntityID(\"mEntityThatShot\", \"for triggers, if shot from a trigger this should point to the projectile entity that shot this. Otherwise this should be the same as mWhoShot. NOTE! Not really tested properly so might break.\", component_id)\n        -- show_field_ProjectileTriggers(\"mTriggers\", nil, component_id)\n        show_field_unsupported(\"mTriggers\", nil, component_id, \"ProjectileTriggers\")\n        show_field_vector_entityid(\"mDamagedEntities\", nil, component_id)\n        show_field_float(\"mInitialSpeed\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Objects\") then\n        local object_open = imgui.TreeNode(\"config ConfigGunActionInfo\")\n        if object_open then\n            show_ConfigGunActionInfo_fields(\"config\", nil, component_id)\n            imgui.TreePop()\n        end\n        local object_open = imgui.TreeNode(\"config_explosion ConfigExplosion\")\n        imgui.SameLine()\n        help.marker(\"if we have explosion, it's the setup for it\")\n        if object_open then\n            show_ConfigExplosion_fields(\"config_explosion\", \"if we have explosion, it's the setup for it\", component_id)\n            imgui.TreePop()\n        end\n        local object_open = imgui.TreeNode(\"damage_by_type ConfigDamagesByType\")\n        imgui.SameLine()\n        help.marker(\"the amounts of different types of damage this does\")\n        if object_open then\n            show_ConfigDamagesByType_fields(\"damage_by_type\", \"the amounts of different types of damage this does\", component_id)\n            imgui.TreePop()\n        end\n        local object_open = imgui.TreeNode(\"damage_critical ConfigDamageCritical\")\n        imgui.SameLine()\n        help.marker(\"config for critical hit\")\n        if object_open then\n            show_ConfigDamageCritical_fields(\"damage_critical\", \"config for critical hit\", component_id)\n            imgui.TreePop()\n        end\n    end\n\n\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_enum(\"projectile_type\", nil, component_id, projectile_type)\n        show_field_vec2(\"shell_casing_offset\", \"where the shell casing will be created relative to projectile, y is flipped if projectile direction is to the left.\", component_id)\n        show_field_enum(\"ragdoll_fx_on_collision\", \"if not NORMAL, do a special ragdoll\", component_id, ragdoll_fx)\n    end\n\nend\n\nfunction show_RotateTowardsComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_string(\"entity_with_tag\", \"will rotate this entity towards the closest entity with tag\", component_id)\n    end\n\nend\n\nfunction show_SetLightAlphaFromVelocityComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_float(\"max_velocity\", nil, component_id)\n    end\n\n\n    if imgui.CollapsingHeader(\"Privates\") then\n        show_field_vec2(\"mPrevPosition\", nil, component_id)\n    end\n\nend\n\nfunction show_SetStartVelocityComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Custom data types\") then\n        show_field_vec2(\"velocity\", \"This is added together with random velocity\", component_id)\n        show_field_ValueRange(\"randomize_angle\", \"Random angle min max range in radians, clockwise. 0.0 points directly rightward.\", component_id)\n        show_field_ValueRange(\"randomize_speed\", \"Random speed min max range\", component_id)\n    end\n\nend\n\nfunction show_ShotEffectComponent_fields(entity_id, component_id, data)\n    if imgui.CollapsingHeader(\"Members\") then\n        show_field_string(\"extra_modifier\", \"name of modifier function executed per projectile from 'gun_extra_modifiers.lua'\", component_id)\n    end\n\n\n    if