ates\") then\n        show_field_vec2(\"mPrevPosition\", nil, component_id)\n        show_field_vec2(\"mDirection\", \"if mDirection == 0,0 nothings works\", component_id)\n    end\n\nend\n\n\ncomponent_type_functions = {\n    AIAttackComponent = {\n        show_fields = show_AIAttackComponent_fields,\n    },\n    AIComponent = {\n        show_fields = show_AIComponent_fields,\n    },\n    AbilityComponent = {\n        show_fields = show_AbilityComponent_fields,\n    },\n    AdvancedFishAIComponent = {\n        show_fields = show_AdvancedFishAIComponent_fields,\n    },\n    AltarComponent = {\n        show_fields = show_AltarComponent_fields,\n    },\n    AnimalAIComponent = {\n        show_fields = show_AnimalAIComponent_fields,\n    },\n    ArcComponent = {\n        show_fields = show_ArcComponent_fields,\n    },\n    AreaDamageComponent = {\n        show_fields = show_AreaDamageComponent_fields,\n    },\n    AttachToEntityComponent = {\n        show_fields = show_AttachToEntityComponent_fields,\n    },\n    AudioComponent = {\n        show_fields = show_AudioComponent_fields,\n    },\n    AudioListenerComponent = {\n        show_fields = show_AudioListenerComponent_fields,\n    },\n    AudioLoopComponent = {\n        show_fields = show_AudioLoopComponent_fields,\n    },\n    BiomeTrackerComponent = {\n        show_fields = show_BiomeTrackerComponent_fields,\n    },\n    BlackHoleComponent = {\n        show_fields = show_BlackHoleComponent_fields,\n    },\n    BookComponent = {\n        show_fields = show_BookComponent_fields,\n    },\n    BossDragonComponent = {\n        show_fields = show_BossDragonComponent_fields,\n    },\n    BossHealthBarComponent = {\n        show_fields = show_BossHealthBarComponent_fields,\n    },\n    CameraBoundComponent = {\n        show_fields = show_CameraBoundComponent_fields,\n    },\n    CardinalMovementComponent = {\n        show_fields = show_CardinalMovementComponent_fields,\n    },\n    CellEaterComponent = {\n        show_fie