_TWWE_VFS["mods/component-explorer/configs.lua"] = "local beta_version = dofile(\"mods/component-explorer/utils/beta_version.lua\")\n\nif beta_version.is_beta then\n    return dofile(\"mods/component-explorer/configs_beta.lua\")\nelse\n    return dofile(\"mods/component-explorer/configs_main.lua\")\nend\n\n"
_TWWE_VFS["mods/component-explorer/configs_beta.lua"] = "dofile_once(\"mods/component-explorer/component_fields.lua\")\n\nfunction show_ConfigDamageCritical_fields(field_name, description, component_id)\n    local function get(component_id, name)\n        return ComponentObjectGetValue2(component_id, field_name, name)\n    end\n\n    local function set(component_id, name, ...)\n        return ComponentObjectSetValue2(component_id, field_name, name, ...)\n    end\n    if imgui.TreeNode(\"Members\") then\n\n        show_field_int(\"chance\", \"the chance of a critical hit. ]0-100[ - can be higher than 100% - then will multiply the multiplier by the extra\", component_id, get, set)\n        show_field_float(\"damage_multiplier\", \"multiplier that is applied to all damage types on a critical hit\", component_id, get, set)\n\n        imgui.TreePop()\n    end\n\n\n    if imgui.TreeNode(\"Privates\") then\n\n        show_field_bool(\"mSucceeded\", nil, component_id, get, set)\n\n        imgui.TreePop()\n    end\n\nend\n\nfunction show_ConfigDamagesByType_fields(field_name, description, component_id)\n    local function get(component_id, name)\n        return ComponentObjectGetValue2(component_id, field_name, name)\n    end\n\n    local function set(component_id, name, ...)\n        return ComponentObjectSetValue2(component_id, field_name, name, ...)\n    end\n\n        show_field_float(\"melee\", nil, component_id, get, set)\n        show_field_float(\"projectile\", nil, component_id, get, set)\n        show_field_float(\"explosion\", nil, component_id, get, set)\n        show_field_float(\"electricity\", \"electricity stun effect is rand[0-1] < electricity\", component_id, get, set)\n        show_field_float(\"fire\", nil, component_id, get, set)\n        show_field_float(\"drill\", nil, component_id, get, set)\n        show_field_float(\"slice\", nil, component_id, get, set)\n        show_field_float(\"ice\", \"freezing stun effect is rand[0-1] < ice\", component_id, get, set)\n        show_field_float(\"healing\", \"healing aka negative damage. this should be given as a negative value.\", component_id, get, set)\n        show_field_float(\"physics_hit\", \"damage from being hit with a physics object\", component_id, get, set)\n        show_field_float(\"radioactive\", nil, component_id, get, set)\n        show_field_float(\"poison\", nil, component_id, get, set)\n        show_field_float(\"overeating\", nil, component_id, get, set)\n        show_field_float(\"curse\", nil, component_id, get, set)\n        show_field_float(\"holy\", \"NOTE( Petri ): Added 18.7.2023. Just an extra type of damage\", component_id, get, set)\n\n\nend\n\nfunction show_ConfigDrugFx_fields(field_name, description, component_id)\n    local function get(component_id, name)\n        return ComponentObjectGetValue2(component_id, field_name, name)\n    end\n\n    local function set(component_id, name, ...)\n        return ComponentObjectSetValue2(component_id, field_name, name, ...)\n    end\n\n        show_field_float(\"distortion_amount\", nil, component_id, get, set)\n        show_field_float(\"color_amount\", nil, component_id, get, set)\n        show_field_float(\"fractals_amount\", nil, component_id, get, set)\n        show_field_float(\"fractals_size\", nil, component_id, get, set)\n        show_field_float(\"nightvision_amount\", nil, component_id, get, set)\n        show_field_float(\"doublevision_amount\", nil, component_id, get, set)\n\n\nend\n\nfunction show_ConfigExplosion_fields(field_name, description, component_id)\n    local function get(component_id, name)\n        return ComponentObjectGetValue2(component_id, field_name, name)\n    end\n\n    local function set(component_id, name, ...)\n        return ComponentObjectSetValue2(component_id, field_name, name, ...)\n    end\n    if imgui.TreeNode(\"Members\") then\n\n        show_field_bool(\"never_cache\", \"if set, won't ever cache and the explosion happens that frame. Used for projectiles\", component_id, get, set)\n        show_field_float(\"explosion_radius\", \"Explosion radius, used to find the peasants and physics bodies that are thrown into the air\", component_id, get, set)\n        show_field_string(\"explosion_sprite\", \"sprite animation of the explosion that we play\", component_id, get, set)\n        show_field_bool(\"explosion_sprite_emissive\", \"if 1, sprite is emissive\", component_id, get, set)\n        show_field_bool(\"explosion_sprite_additive\", \"if 1, sprite is additive\", component_id, get, set)\n        show_field_bool(\"explosion_sprite_random_rotation\", \"if true, rotates the sprite to random 90 degrees\", component_id, get, set)\n        show_field_float(\"explosion_sprite_lifetime\", \"if 0, finds the lifetime based on the rect animation currently playing. If not 0 it is seconds how long does the explosion sprite stay in the world\", component_id, get, set)\n        show_field_float(\"damage\", \"how much damage does this do to living entities\", component_id, get, set)\n        show_field_float(\"camera_shake\", \"camera shake - how much we shake the camera\", component_id, get, set)\n        show_field_bool(\"particle_effect\", \"Should we use the ParticleEffect::DoExplosion()\", component_id, get, set)\n        show_field_string(\"load_this_entity\", \"if set, this entity is loaded when the explosion is queued\", component_id, get, set)\n        show_field_bool(\"light_enabled\", \"Should the explosion emit light to its surroundings?\", component_id, get, set)\n        show_field_float(\"light_fade_time\", \"The time it takes for the light flash to fade out\", component_id, get, set)\n        show_field_int(\"light_r\", \"Color red 0-255\", component_id, get, set)\n        show_field_int(\"light_g\", \"Color green 0-255\", component_id, get, set)\n        show_field_int(\"light_b\", \"Color blue 0-255\", component_id, get, set)\n        show_field_float(\"light_radius_coeff\", \"The radius of the light will be explosion_radius * light_radius_coeff\", component_id, get, set)\n        show_field_bool(\"hole_enabled\", \"Do we remove ground, creata a crater\", component_id, get, set)\n        show_field_bool(\"destroy_non_platform_solid_enabled\", \"Do we remove solid cells that aren't platforms?\", component_id, get, set)\n        show_field_int(\"electricity_count\", \"How many electricity entitities should we create?\", component_id, get, set)\n        show_field_int(\"min_radius_for_cracks\", \"Cracks are created if explosion_radius is larger than this\", component_id, get, set)\n        show_field_int(\"crack_count\", \"How many crack entitities should we create?\", component_id, get, set)\n        show_field_float(\"knockback_force\", \"How far do entities get thrown if a knockback occurs? final_knocback = explosion_radius * knockback_force * target.inv_normalized_distance_from_explosion / target.mass\", component_id, get, set)\n        show_field_bool(\"hole_destroy_liquid\", \"Do we destroy the liquid cells we ran into, or do we just throw them into to the air?\", component_id, get, set)\n        show_field_bool(\"hole_destroy_physics_dynamic\", \"Do we destroy the dynamic physics cells we encountered?\", component_id, get, set)\n        show_field_string(\"create_cell_material\", \"The material destroyed cells might turn into.\", component_id, get, set)\n        show_field_int(\"create_cell_probability\", \"The probability a destroyed cell is turned into 'create_cell_material'\", component_id, get, set)\n        show_field_int(\"background_lightning_count\", \"Parallax background lightning count is set to this on explosion\", component_id, get, set)\n        show_field_string(\"spark_material\", \"spark material, TODO moved these to use a special Serializer\", component_id, get, set)\n        show_field_int(\"material_sparks_min_hp\", \"How many sparks are we creating (rand max)\", component_id, get, set)\n        show_field_int(\"material_sparks_probability\", \"How many sparks are we creating (rand max)\", component_id, get, set)\n        show_field_int(\"material_sparks_count_min\", \"How many sparks are we creating (rand min)\", component_id, get, set)\n        show_field_int(\"material_sparks_count_max\", \"How many sparks are we creating (rand max)\", component_id, get, set)\n        show_field_bool(\"material_sparks_enabled\", \"Should we create few fire particles around the explosion\", component_id, get, set)\n        show_field_bool(\"material_sparks_real\", \"if the spark particles created are real or fake\", component_id, get, set)\n        show_field_bool(\"material_sparks_scale_with_hp\", \"if true, will create more sparks the harder the material\", component_id, get, set)\n        show_field_bool(\"sparks_enabled\", \"Should we create few fire particles around the explosion\", component_id, get, set)\n        show_field_int(\"sparks_count_min\", \"How many sparks are we creating (rand min)\", component_id, get, set)\n        show_field_int(\"sparks_count_max\", \"How many sparks are we creating (rand max)\", component_id, get, set)\n        show_field_float(\"sparks_inner_radius_coeff\", \"If 'sparks_enabled', Sparks are created in the area between circles defined by 'explosion_radius'*'sparks_inner_radius_coeff' and 'explosion_radius'\", component_id, get, set)\n        show_field_bool(\"stains_enabled\", \"Should we stain the ground and other particles\", component_id, get, set)\n        show_field_float(\"stains_radius\", \"The distance from the edge of the hole to the edge of the stained area, 0.0f for default which is 0.3 * explosion_radius\", component_id, get, set)\n        show_field_int(\"ray_energy\", \"This is the energy we have per ray. Could be called 'penetration power' or something like that. If cells have a hp of 20 rays with 100 energy can penetrate 5 cells\", component_id, get, set)\n        show_field_int(\"max_durability_to_destroy\", \"When destroying cells only cells with a durability <= max_durability_to_destroy will be affected\", component_id, get, set)\n        show_field_int(\"gore_particle_count\", \"How many particles to create in case we do gore stuff?\", component_id, get, set)\n        show_field_bool(\"shake_vegetation\", \"Should we shake vegetation around the explosion (uses the area of stain_image to find vegetation)\", component_id, get, set)\n        show_field_bool(\"damage_mortals\", \"Look for peasants and throw them into the air? Remember to enabled physics_throw as well if you want them to actually fly\", component_id, get, set)\n        show_field_bool(\"physics_throw_enabled\", \"Should we throw physics objects into the air, also peasants\", component_id, get, set)\n        show_field_float(\"physics_multiplier_ragdoll_force\", \"treat the ragdolls a bit differently from other physics objects, to get them to fly nicely\", component_id, get, set)\n        show_field_float(\"cell_explosion_power\", \"used when a solid cell explodes as the multiplier to how big the radius is going to be\", component_id, get, set)\n        show_field_float(\"cell_explosion_radius_min\", \"when cell explodes, this is the minimum radius that explosion is made of\", component_id, get, set)\n        show_field_float(\"cell_explosion_radius_max\", \"when cell explodes, this is the minimum radius that explosion is made of\", component_id, get, set)\n        show_field_float(\"cell_explosion_velocity_min\", \"cell explodes only when body velocity is greater than this\", component_id, get, set)\n        show_field_float(\"cell_explosion_damage_required\", \"how much fire damage is required before this explodes\", component_id, get, set)\n        show_field_float(\"cell_explosion_probability\", \"this is used when there's a tiny contact that doesn't cause an explosion, in those cases this is used as a random to check if we should explode or not\", component_id, get, set)\n        show_field_float(\"cell_explosion_power_ragdoll_coeff\", \"ragdoll cells destruction power is multiplied with this\", component_id, get, set)\n        show_field_bool(\"pixel_sprites_enabled\", \"if enabled will carve out the pixel sprites\", component_id, get, set)\n        show_field_bool(\"is_digger\", \"if 1, we apply some special digger logic to this explosion\", component_id, get, set)\n        show_field_bool(\"audio_enabled\", \"Do we play an explosion sound?\", component_id, get, set)\n        show_field_string(\"audio_event_name\", \"Name of audio event in 'explosion' audio bank. If not set, will default to 'explosion' or 'explosion_small' based on explosion radius.\", component_id, get, set)\n        show_field_float(\"audio_liquid_amount_normalized\", \"value of the 'liquid_amount' parameter passed to the explosion's audio event\", component_id, get, set)\n        show_field_int(\"explosion_delay_id\", \"for delayed barrel explosions... this has to be set and has to be the same for the explosions for there to be a delay\", component_id, get, set)\n\n        imgui.TreePop()\n    end\n\n\n    if imgui.TreeNode(\"Privates\") then\n\n        show_field_EntityID(\"who_is_responsible\", \"the entity that caused the explosion\", component_id, get, set)\n        show_field_bool(\"null_damage\", \"if set, will not call DamageModelSystem::TakeDamage()\", component_id, get, set)\n        show_field_EntityID(\"dont_damage_this\", \"if set, this entity doesn't receive damage from the explosion\", component_id, get, set)\n        show_field_EntityID(\"impl_send_message_to_this\", nil, component_id, get, set)\n        show_field_types_vector2(\"impl_position\", nil, component_id, get, set)\n        show_field_int(\"impl_delay_frame\", nil, component_id, get, set)\n\n        imgui.TreePop()\n    end\n\n\n    if imgui.TreeNode(\"Custom data types\") then\n\n        show_field_ValueRange(\"physics_explosion_power\", \"how hard do we throw physics objects\", component_id, get, set)\n        show_field_ValueRangeInt(\"delay\", \"if > 0, the explosion occurs with a delay chosen randomly from this range and is never buffered\", component_id, get, set)\n\n        imgui.TreePop()\n    end\n\nend\n\nfunction show_ConfigGunActionInfo_fields(field_name, description, component_id)\n    local function get(component_id, name)\n        return ComponentObjectGetValue2(component_id, field_name, name)\n    end\n\n    local function set(component_id, name, ...)\n        return ComponentObjectSetValue2(component_id, field_name, name, ...)\n    end\n\n        show_field_string(\"action_id\", nil, component_id, get, set)\n        show_field_string(\"action_name\", nil, component_id, get, set)\n        show_field_string(\"action_description\", nil, component_id, get, set)\n        show_field_string(\"action_sprite_filename\", nil, component_id, get, set)\n        show_field_string(\"action_unidentified_sprite_filename\", nil, component_id, get, set)\n        show_field_int(\"action_type\", nil, component_id, get, set)\n        show_field_string(\"action_spawn_level\", \"comma separated values should match probabilities\", component_id, get, set)\n        show_field_string(\"action_spawn_probability\", \"comma separated values should match levels\", component_id, get, set)\n        show_field_string(\"action_spawn_requires_flag\", \"if set, requires that this persistent flag is set for spawn probablities to be something else than 0\", component_id, get, set)\n        show_field_bool(\"action_spawn_manual_unlock\", \"if true, will not automatically call AddFlagPersistent( action_spawn_requires_flag ) when this action is spawned. You must do it yourself! \", component_id, get, set)\n        show_field_int(\"action_max_uses\", \"-1 = infinite otherwise it's the amount specified\", component_id, get, set)\n        show_field_string(\"custom_xml_file\", \"if set, this will be used instead of 'action.xml'\", component_id, get, set)\n        show_field_float(\"action_mana_drain\", \"how much mana does this action drain?\", component_id, get, set)\n        show_field_bool(\"action_is_dangerous_blast\", \"TODO - is this used anywhere?\", component_id, get, set)\n        show_field_int(\"action_draw_many_count\", nil, component_id, get, set)\n        show_field_bool(\"action_ai_never_uses\", nil, component_id, get, set)\n        show_field_bool(\"action_never_unlimited\", nil, component_id, get, set)\n        show_field_bool(\"state_shuffled\", nil, component_id, get, set)\n        show_field_int(\"state_cards_drawn\", nil, component_id, get, set)\n        show_field_bool(\"state_discarded_action\", nil, component_id, get, set)\n        show_field_bool(\"state_destroyed_action\", nil, component_id, get, set)\n        show_field_int(\"fire_rate_wait\", nil, component_id, get, set)\n        show_field_float(\"speed_multiplier\", nil, component_id, get, set)\n        show_field_float(\"child_speed_multiplier\", nil, component_id, get, set)\n        show_field_float(\"dampening\", nil, component_id, get, set)\n        show_field_float(\"explosion_radius\", nil, component_id, get, set)\n        show_field_float(\"spread_degrees\", \"in 360 degrees, randomizes the direction of the bullet -spread_degrees to +spread_degrees\", component_id, get, set)\n        show_field_float(\"pattern_degrees\", \"in 360 degrees, if != 0, distributes the bullets to an even pattern from -pattern_degrees to +pattern_degrees\", component_id, get, set)\n        show_field_float(\"screenshake\", nil, component_id, get, set)\n        show_field_float(\"recoil\", nil, component_id, get, set)\n        show_field_float(\"damage_melee_add\", \"TODO - is this used anywhere?\", component_id, get, set)\n        show_field_float(\"damage_projectile_add\", \"if change to mul - take into account that default is 0\", component_id, get, set)\n        show_field_float(\"damage_electricity_add\", nil, component_id, get, set)\n        show_field_float(\"damage_fire_add\", \"TODO - is this used anywhere?\", component_id, get, set)\n        show_field_floa