, component_id, get, set)\n        show_field_float(\"explosion_radius\", \"Explosion radius, used to find the peasants and physics bodies that are thrown into the air\", component_id, get, set)\n        show_field_string(\"explosion_sprite\", \"sprite animation of the explosion that we play\", component_id, get, set)\n        show_field_bool(\"explosion_sprite_emissive\", \"if 1, sprite is emissive\", component_id, get, set)\n        show_field_bool(\"explosion_sprite_additive\", \"if 1, sprite is additive\", component_id, get, set)\n        show_field_bool(\"explosion_sprite_random_rotation\", \"if true, rotates the sprite to random 90 degrees\", component_id, get, set)\n        show_field_float(\"explosion_sprite_lifetime\", \"if 0, finds the lifetime based on the rect animation currently playing. If not 0 it is seconds how long does the explosion sprite stay in the world\", component_id, get, set)\n        show_field_float(\"damage\", \"how much damage does this do to living entities\", component_id, get, set)\n        show_field_float(\"camera_shake\", \"camera shake - how much we shake the camera\", component_id, get, set)\n        show_field_bool(\"particle_effect\", \"Should we use the ParticleEffect::DoExplosion()\", component_id, get, set)\n        show_field_string(\"load_this_entity\", \"if set, this entity is loaded when the explosion is queued\", component_id, get, set)\n        show_field_bool(\"light_enabled\", \"Should the explosion emit light to its surroundings?\", component_id, get, set)\n        show_field_float(\"light_fade_time\", \"The time it takes for the light flash to fade out\", component_id, get, set)\n        show_field_int(\"light_r\", \"Color red 0-255\", component_id, get, set)\n        show_field_int(\"light_g\", \"Color green 0-255\", component_id, get, set)\n        show_field_int(\"light_b\", \"Color blue 0-255\", component_id, get, set)\n        show_field_float(\"light_radius_coeff\", \"The radius of the light will be explosion_radius * light_radius_coeff\", component_id, get, set)\n        show_field_bool(\"hole_enabled\", \"Do we remove ground, creata a crater\", component_id, get, set)\n        show_field_bool(\"destroy_non_platform_solid_enabled\", \"Do we remove solid cells that aren't platforms?\", component_id, get, set)\n        show_field_int(\"electricity_count\", \"How many electricity entitities should we create?\", component_id, get, set)\n        show_field_int(\"min_radius_for_cracks\", \"Cracks are created if explosion_radius is larger than this\", component_id, get, set)\n        show_field_int(\"crack_count\", \"How many crack entitities should we create?\", component_id, get, set)\n        show_field_float(\"knockback_force\", \"How far do entities get thrown if a knockback occurs? final_knocback = explosion_radius * knockback_force * target.inv_normalized_distance_from_explosion / target.mass\", component_id, get, set)\n        show_field_bool(\"hole_destroy_liquid\", \"Do we destroy the liquid cells we ran into, or do we just throw them into to the air?\", component_id, get, set)\n        show_field_bool(\"hole_destroy_physics_dynamic\", \"Do we destroy the dynamic physics cells we encountered?\", component_id, get, set)\n        show_field_string(\"create_cell_material\", \"The material destroyed cells might turn into.\", component_id, get, set)\n        show_field_int(\"create_cell_probability\", \"The probability a destroyed cell is turned into 'create_cell_material'\", component_id, get, set)\n        show_field_int(\"background_lightning_count\", \"Parallax background lightning count is set to this on explosion\", component_id, get, set)\n        show_field_string(\"spark_material\", \"spark material, TODO moved these to use a special Serializer\", component_id, get, set)\n        show_field_int(\"material_sparks_min_hp\", \"How many sparks are we creating (rand max)\", component_id, get, set)\n        show_field_int(\"material_sparks_probability\", \"How many s