include_privates)\n    end\n    if type_name == \"VerletWeaponComponent\" then\n        return add_VerletWeaponComponent_fields(component_id, component, include_privates)\n    end\n    if type_name == \"VerletWorldJointComponent\" then\n        return add_VerletWorldJointComponent_fields(component_id, component, include_privates)\n    end\n    if type_name == \"WalletComponent\" then\n        return add_WalletComponent_fields(component_id, component, include_privates)\n    end\n    if type_name == \"WalletValuableComponent\" then\n        return add_WalletValuableComponent_fields(component_id, component, include_privates)\n    end\n    if type_name == \"WorldStateComponent\" then\n        return add_WorldStateComponent_fields(component_id, component, include_privates)\n    end\n    if type_name == \"WormAIComponent\" then\n        return add_WormAIComponent_fields(component_id, component, include_privates)\n    end\n    if type_name == \"WormAttractorComponent\" then\n        return add_WormAttractorComponent_fields(component_id, component, include_privates)\n    end\n    if type_name == \"WormComponent\" then\n        return add_WormComponent_fields(component_id, component, include_privates)\n    end\n    if type_name == \"WormPlayerComponent\" then\n        return add_WormPlayerComponent_fields(component_id, component, include_privates)\n    end\nend\n\nfunction serialise_component(component_id, include_privates)\n    local type_name = ComponentGetTypeName(component_id)\n    local component = nxml.new_element(type_name)\n\n    local enabled = ComponentGetIsEnabled(component_id)\n    if not enabled then\n        component.attr._enabled = enabled\n    end\n\n    add_component_fields(component_id, type_name, component, include_privates)\n\n    local tags = ComponentGetTags(component_id)\n    if tags and tags ~= \"\" then\n        component.attr._tags = tags\n    end\n\n    return component\nend\n"
_TWWE_VFS["mods/component-explorer/serialise_entity.lua"] = "dofile_once(\"mods/component-explorer/serialise_component.lua\")\nlocal nxml = dofile_once(\"mods/component-explorer/deps/nxml.lua\")\n\nfunction serialise_entity(entity_id, include_privates)\n    local entity = nxml.new_element(\"Entity\")\n\n    local name = EntityGetName(entity_id)\n    if name ~= \"unknown\" and name ~= \"\" then\n        entity.attr.name = name\n    end\n\n    local tags = EntityGetTags(entity_id)\n    if tags ~= \"\" then\n        entity.attr.tags = tags\n    end\n\n    local transform = entity_transform(entity_id)\n    if transform then\n        entity:add_child(transform)\n    end\n\n    local component_ids = EntityGetAllComponents(entity_id)\n    for _, component_id in ipairs(component_ids) do\n        entity:add_child(serialise_component(component_id, include_privates))\n    end\n\n    local child_entity_ids = EntityGetAllChildren(entity_id) or {}\n    for _, child_entity_id in ipairs(child_entity_ids) do\n        entity:add_child(serialise_entity(child_entity_id))\n    end\n\n    return entity\nend\n\nfunction entity_transform(entity_id)\n    local transform = nxml.new_element(\"_Transform\")\n    local x, y, rotation, scale_x, scale_y = EntityGetTransform(entity_id)\n\n    if x ~= 0 or y ~= 0 then\n        transform.attr[\"position.x\"] = x\n        transform.attr[\"position.y\"] = y\n    end\n\n    if rotation ~= 0 then\n        transform.attr[\"rotation\"] = rotation\n    end\n\n    if scale_x ~= 0 or scale_y ~= 0 then\n        transform.attr[\"scale.x\"] = scale_x\n        transform.attr[\"scale.y\"] = scale_y\n    end\n\n    if #transform.attr ~= 0 then\n        return transform\n    end\n\n    return nil\nend\n\n"
_TWWE_VFS["mods/component-explorer/settings.lua"] = "dofile(\"data/scripts/lib/mod_settings.lua\")\n\nlocal mod_id = \"component-explorer\"\nmod_settings_version = 2\nmod_settings = {\n    {\n        category_id = \"main_window\",\n        ui_name = \"Main window\",\n        ui_description = \"Where to put the main window?\",\n        settings = {\n            {\n                id = \"main_window_side\",\n                ui_name = \"Main window side\",\n                ui_description = \"What side of the screen should the window be?\",\n                value_default = \"top\",\n                values = {{\"top\", \"Top\"}, {\"bottom\", \"Bottom\"}, {\"left\", \"Left\"}, {\"right\", \"Right\"}},\n                scope = MOD_SETTING_SCOPE_RUNTIME,\n            },\n            {\n                id = \"main_window_side_offset\",\n                ui_name = \"Main window offset\",\n                ui_description = \"How far along the selected side should the window be?\",\n                value_default = 95,\n                value_min = 0,\n                value_max = 100,\n                value_display_formatting = \" $0 %\",\n                scope = MOD_SETTING_SCOPE_RUNTIME,\n            }\n        },\n    },\n    {\n        category_id = \"default_windows\",\n        ui_name = \"Default windows\",\n        ui_description = \"What windows should be opened by default\",\n        settings = {\n            {\n                id = \"window_open_entity_list\",\n                ui_name = \"Entity list\",\n                ui_description = \"Window that displays all entities\",\n                value_default = false,\n                scope = MOD_SETTING_SCOPE_RUNTIME,\n            },\n        },\n    },\n    {\n        category_id = \"xml\",\n        ui_name = \"XML Defaults\",\n        ui_description = \"What XML settings are selected by default\",\n        settings = {\n            {\n                id = \"xml_indent_char\",\n                ui_name = \"Indentation Character\",\n                ui_description = \"What character to use for indentation in the XML exports\",\n                value_default = \"space\",\n                values = {{\"space\", \"Spaces\"}, {\"tab\", \"Tabs\"}},\n                scope = MOD_SETTING_SCOPE_RUNTIME,\n            },\n            {\n                id = \"xml_space_count\",\n                ui_name = \"Spaces indentation: count\",\n                ui_description = \"When using spaces for indentations, how many to use per indentation level\",\n                value_default = 4,\n                value_min = 1,\n                value_max = 8,\n                scope = MOD_SETTING_SCOPE_RUNTIME,\n            },\n            {\n                id = \"xml_include_privates\",\n                ui_name = \"Private fields\",\n                ui_description = \"Include fields that are markes as 'Private' in the component_documentation.txt file\",\n                value_default = false,\n                scope = MOD_SETTING_SCOPE_RUNTIME,\n            },\n        },\n    },\n    {\n        category_id = \"pause\",\n        ui_name = \"Pause settings\",\n        ui_description = \"What should the mod do when the game is paused?\",\n        settings = {\n            {\n                id = \"pause_wands\",\n                ui_name = \"Run in wands menu\",\n                ui_description = \"Should the windows be shown in the wand pickup menu?\",\n                value_default = true,\n                scope = MOD_SETTING_SCOPE_RUNTIME,\n            },\n            {\n                id = \"pause_escape\",\n                ui_name = \"Run in escape menu\",\n                ui_description = \"Should component explorer windows be shown in the escape menu?\",\n                value_default = true,\n                scope = MOD_SETTING_SCOPE_RUNTIME,\n            },\n        },\n    },\n    {\n        category_id = \"keyboard\",\n        ui_name = \"Keyboard shortcuts\",\n        ui_description = \"Customize how Component Explorer uses keyboard shortcuts.\",\n        settings = {\n            {\n                id = \"keyboard_shortcuts\",\n                ui_name = \"Enable Shortcuts\",\n                ui_description = \"Enable/disable all keyboard shortcuts\",\n                value_default = true,\n                scope = MOD_SETTING_SCOPE_RUNTIME,\n            },\n            {\n                id = \"magic_key\",\n                ui_name = \"Magic Key\",\n                ui_description = \"Keys that must be held to use keyboard shortcuts\",\n                value_default = \"ctrl+shift\",\n                values = {\n                    {\"ctrl+shift\", \"CTRL+SHIFT\"},\n                    {\"ctrl\", \"CTRL\"},\n                    {\"super\", \"SUPER\"},\n                    {\"alt\", \"ALT\"},\n                },\n                scope = MOD_SETTING_SCOPE_RUNTIME,\n            },\n        }\n    },\n    {\n        category_id = \"data_display\",\n        ui_name = \"Data Display\",\n        ui_description = \"How should Component Explorer display data to you?\",\n        settings = {\n            {\n                id = \"preferred_decimal_format\",\n                ui_name = \"Preferred decimal format\",\n                value_default = \"magnitude\",\n                values = {\n                    {\"decimal\", \"Decimal\"},\n                    {\"all_scientific\", \"Scientific (all)\"},\n                    {\"double_scientific\", \"Scientific (only doubles)\"},\n                    {\"magnitude\", \"Switch on magnitude\"},\n                },\n                scope = MOD_SETTING_SCOPE_RUNTIME,\n            }\n        }\n    },\n    {\n        category_id = \"cursor\",\n        ui_name = \"Cursor settings\",\n        ui_description = \"Default settings for the cursor at launch.\",\n        settings = {\n            {\n                id = \"keep_visible\",\n                ui_name = \"Visible outside config\",\n                ui_description = \"Keep the cursor visible even when the cursor config is closed.\",\n                value_default = false,\n                scope = MOD_SETTING_SCOPE_RUNTIME,\n            },\n            {\n                id = \"parent\",\n                ui_name = \"Cursor parent\",\n                ui_description = \"Relative to what should the cursor be positioned?\",\n                value_default = \"player\",\n                values = {\n                    {\"camera\", \"Camera\"},\n                    {\"world\", \"World\"},\n                    {\"player\", \"Player\"},\n                },\n                scope = MOD_SETTING_SCOPE_RUNTIME,\n            }\n        },\n    },\n    {\n        category_id = \"file_viewer\",\n        ui_name = \"File viewer settings\",\n        ui_description = \"Settings that affects the file viewer window.\",\n        settings = {\n            {\n                id = \"line_numbers\",\n                ui_name = \"Show line numbers in file viewer\",\n                value_default = true,\n                scope = MOD_SETTING_SCOPE_RUNTIME,\n            }\n        }\n    },\n    {\n        category_id = \"unsafe\",\n        ui_name = \"Unsafe Explorer\",\n        ui_description = \"These settings require unsafe explorer to take effect\",\n        settings = {\n            {\n                id = \"window_open_logs\",\n                ui_name = \"Open Logs window by default\",\n                ui_description = \"logger.txt monitor window\",\n                value_default = false,\n                scope = MOD_SETTING_SCOPE_RUNTIME,\n            },\n            {\n                id = \"overlay_open_logs\",\n                ui_name = \"Open Logs Overlay by default\",\n                ui_description = \"Overlay displaying the logger.txt file\",\n                value_default = false,\n                scope = MOD_SETTING_SCOPE_RUNTIME,\n            },\n            {\n                id = \"logger_txt\",\n                ui_name = \"Enable logger.txt output\",\n                ui_description = \"Need this if you want to use the logger window or overlay.\",\n                value_default = true,\n                scope = MOD_SETTING_SCOPE_RUNTIME,\n            }\n        },\n    },\n}\n\nfunction ModSettingsUpdate(init_scope)\n    local old_version = mod_settings_get_version(mod_id)\n    mod_settings_update(mod_id, mod_settings, init_scope)\nend\n\nfunction ModSettingsGuiCount()\n    return mod_settings_gui_count(mod_id, mod_settings)\nend\n\nfunction ModSettingsGui(gui, in_main_menu)\n    mod_settings_gui(mod_id, mod_settings, gui, in_main_menu)\nend\n"
_TWWE_VFS["mods/component-explorer/settings_value.lua"] = "local settings_value = {}\n\n---@alias SettingsType \"string\" | \"number\" | \"boolean\" | \"nil\"\n\n---@type SettingsType[]\nlocal SettingsTypes = {\n    \"string\", \"number\", \"boolean\", \"nil\"\n}\n\n---@class SettingsValue\n---@field type SettingsType\n---@field string_value string\n---@field number_value number\n---@field boolean_value boolean\nlocal SettingsValue = {}\nSettingsValue.__index = SettingsValue\n\n---@return SettingsValue\n---@nodiscard\nfunction SettingsValue.new()\n    return setmetatable({\n        type=\"string\",\n        string_value=\"\",\n        number_value=0,\n        boolean_value=false,\n    }, SettingsValue)\nend\n\n---@param value string|number|boolean|nil\n---@return SettingsValue\n---@nodiscard\nfunction SettingsValue.from_lua_value(value)\n    local vt = type(value)\n    local setting = setmetatable({\n        type=vt,\n        string_value=\"\",\n        number_value=0,\n        boolean_value=false,\n    }, SettingsValue)\n\n    if vt == \"string\" then\n        setting.string_value = value\n    elseif vt == \"number\" then\n        setting.number_value = value\n    elseif vt == \"boolean\" then\n        setting.boolean_value = value\n    else\n        setting.type = \"nil\"\n    end\n\n    return setting\nend\n\n---@return string|number|boolean|nil\n---@nodiscard\nfunction SettingsValue:to_lua_value()\n    if self.type == \"string\" then\n        return self.string_value\n    elseif self.type == \"number\" then\n        return self.number_value\n    elseif self.type == \"boolean\" then\n        return self.boolean_value\n    end\n\n    return nil\nend\n\n---Shows the setting allowing the user to change type or stored value.\n---Setting is modified in-place.\n---@return boolean changed True if the value changed\nfunction SettingsValue:show(name)\n    imgui.Text(name .. \": \")\n    imgui.SameLine()\n\n    imgui.PushID(name)\n    imgui.BeginGroup()\n\n    if imgui.BeginCombo(\"Type\", self.type) then\n        for _, settings_type in ipairs(SettingsTypes) do\n            local is_selected = settings_type == self.type\n            if imgui.Selectable(settings_type, is_selected) then\n                self.type = settings_type\n            end\n        end\n        imgui.EndCombo()\n    end\n\n    local changed = false\n    if self.type == \"string\" then\n        local line_height = imgui.GetTextLineHeight()\n        changed, self.string_value = imgui.InputTextMultiline(\"Value\", self.string_value, 0, 4 * line_height)\n    elseif self.type == \"number\" then\n        changed, self.number_value = imgui.InputDouble(\"Value\", self.number_value)\n    elseif self.type == \"boolean\" then\n        changed, self.boolean_value = imgui.Checkbox(\"Value\", self.boolean_value)\n    else\n        imgui.Text(\"nil\")\n    end\n\n    imgui.EndGroup()\n    imgui.PopID()\n\n    return changed\nend\n\nsettings_value.SettingsValue = SettingsValue\n\nreturn settings_value\n"
_TWWE_VFS["mods/component-explorer/spawn_data/actions.lua"] = "---@module 'component-explorer.utils.file_util'\nlocal file_util = dofile_once(\"mods/component-explorer/utils/file_util.lua\")\n\ndofile_once(\"data/scripts/gun/gun_enums.lua\")\n\nlocal function register_origins(origin)\n    if not actions then\n        return\n    end\n    for _, action in ipairs(actions) do\n        if action.origin == nil then\n            action.origin = origin\n        end\n    end\nend\n\nlocal original_do_mod_appends = do_mod_appends\ndo_mod_appends = function(appends_for)\n    if appends_for == \"data/scripts/gun/gun_actions.lua\" then\n        register_origins(\"Vanilla\")\n    else\n        local mod_id = string.match(appends_for, \"mods/([^/]*)\")\n        register_origins(mod_id or \"Unknown\")\n    end\n\n    original_do_mod_appends(appends_for)\nend\ndofile(\"data/scripts/gun/gun_actions.lua\")\ndo_mod_appends = original_do_mod_appends\n\nlocal actions = actions\n\nfor _, action in ipairs(actions) do\n    action.display_name = GameTextGetTranslatedOrNot(action.name)\n    action.display_description = GameTextGetTranslatedOrNot(action.description)\nend\n\nlocal action_types = {}\n\nlocal gun_enums_source = file_util.ModTextFileGetContent(\"data/scripts/gun/gun_enums.lua\")\nfor k, v in string.gmatch(gun_enums_source, \"ACTION_TYPE_([%w_]+)%s*=%s*(%d+)\") do\n    action_types[tonumber(v)] = k\nend\n\nlocal unique_action_types = {}\nfor i=0,#action_types do\n    table.insert(unique_action_types, action_types[i])\nend\n\n---@param act integer\n---@return string\nlocal function action_type_to_name(act)\n    return action_types[act]\nend\n\nreturn {\n    actions=actions,\n    unique_action_types=unique_action_types,\n    action_type_to_name=action_type_to_name,\n}\n"
