_TWWE_VFS["mods/component-explorer/spawn_stuff.lua"] = "local spawn_stuff = {}\n\nspawn_stuff.open = false\n\nfunction spawn_stuff.show()\n    -- Loaded with a delay because these files need to use the translations\n\n    imgui.SetNextWindowSize(480, 200, imgui.Cond.FirstUseEver)\n\n    local show\n    show, spawn_stuff.open = imgui.Begin(\"Spawn Stuff\", spawn_stuff.open)\n\n    if not show then\n        return\n    end\n\n    if imgui.BeginTabBar(\"spawn_stuff\") then\n        if imgui.BeginTabItem(\"Creatures\") then\n            ---@module 'component-explorer.spawn_stuff.creatures'\n            local creature_content = dofile_once(\"mods/component-explorer/spawn_stuff/creatures.lua\")\n\n            if imgui.BeginChild(\"#creatures_child\") then\n                creature_content()\n                imgui.EndChild()\n            end\n            imgui.EndTabItem()\n        end\n\n        if imgui.BeginTabItem(\"Items\") then\n            ---@module 'component-explorer.spawn_stuff.items'\n            local item_content = dofile_once(\"mods/component-explorer/spawn_stuff/items.lua\")\n\n            if imgui.BeginChild(\"#items_child\") then\n                item_content()\n                imgui.EndChild()\n            end\n            imgui.EndTabItem()\n        end\n\n        if imgui.BeginTabItem(\"Perks\") then\n            ---@module 'component-explorer.spawn_stuff.perks'\n            local perk_content = dofile_once(\"mods/component-explorer/spawn_stuff/perks.lua\")\n\n            if imgui.BeginChild(\"#perks_child\") then\n                perk_content()\n                imgui.EndChild()\n            end\n            imgui.EndTabItem()\n        end\n\n        if imgui.BeginTabItem(\"Spells\") then\n            if imgui.BeginChild(\"#spells_child\") then\n                ---@module 'component-explorer.spawn_stuff.spells'\n                local spell_content = dofile_once(\"mods/component-explorer/spawn_stuff/spells.lua\")\n\n                spell_content()\n                imgui.EndChild()\n            end\n            imgui.EndTabItem()\n        end\n\n        if imgui.BeginTabItem(\"Materials\") then\n            if imgui.BeginChild(\"#materials_child\") then\n                ---@module 'component-explorer.spawn_stuff.materials'\n                local material_content = dofile_once(\"mods/component-explorer/spawn_stuff/materials.lua\")\n\n                material_content()\n                imgui.EndChild()\n            end\n            imgui.EndTabItem()\n        end\n\n        if imgui.BeginTabItem(\"Props\") then\n            ---@module 'component-explorer.spawn_stuff.props'\n            local props_content = dofile_once(\"mods/component-explorer/spawn_stuff/props.lua\")\n\n            if imgui.BeginChild(\"#props_child\") then\n                props_content()\n                imgui.EndChild()\n            end\n            imgui.EndTabItem()\n        end\n\n        imgui.EndTabBar()\n    end\n\n    imgui.End()\nend\n\nreturn spawn_stuff\n"
_TWWE_VFS["mods/component-explorer/spawn_stuff/creatures.lua"] = "---@module 'component-explorer.spawn_data.creatures'\nlocal creatures_ = dofile_once(\"mods/component-explorer/spawn_data/creatures.lua\")\n\n---@module 'component-explorer.utils.copy'\nlocal copy = dofile_once(\"mods/component-explorer/utils/copy.lua\")\n\n---@module 'component-explorer.utils.strings'\nlocal string_util = dofile_once(\"mods/component-explorer/utils/strings.lua\")\n\n---@module 'component-explorer.cursor'\nlocal cursor = dofile_once(\"mods/component-explorer/cursor.lua\")\n\n---@module 'component-explorer.ui.combo'\nlocal combo = dofile_once(\"mods/component-explorer/ui/combo.lua\")\n\n---@module 'component-explorer.utils.file_util'\nlocal file_util = dofile_once(\"mods/component-explorer/utils/file_util.lua\")\n\n---@module 'component-explorer.entity'\nlocal entity = dofile_once(\"mods/component-explorer/entity.lua\")\n\nlocal function get_enhanced_creatures()\n    local ret = {}\n    for _, c_ in ipairs(creatures_) do\n        local c = copy.shallow_copy(c_)\n\n        if not file_util.file_exists(c.file) then\n            goto continue\n        end\n\n        -- Add display_name attribute\n        if c.name then\n            c.display_name = GameTextGetTranslatedOrNot(c.name)\n        elseif c.statsname then\n            c.display_name = c.statsname\n        else\n            c.display_name = string.match(c.file, \"[^/]*$\")\n        end\n\n        -- See if there's an animal_icon we can use if no img_path is set yet\n        if imgui.LoadImage and c.img_path == nil then\n            local file_name = string.match(c.file, \"([^/]*)%.xml$\")\n            local potential_img_path = \"data/ui_gfx/animal_icons/\" .. file_name .. \".png\"\n            if imgui.LoadImage(potential_img_path) then\n                c.img_path = potential_img_path\n            end\n        end\n\n        table.insert(ret, c)\n        ::continue::\n    end\n\n    table.sort(ret, function(a, b) return a.display_name < b.display_name end)\n    return ret\nend\n\nlocal creatures = get_enhanced_creatures()\n\nlocal function get_unique_attrs(attr)\n    local set = {}\n    for _, c in ipairs(creatures) do\n        set[c[attr]] = true\n    end\n\n    local ret = {}\n    for item, _ in pairs(set) do\n        table.insert(ret, item)\n    end\n\n    table.sort(ret)\n    return ret\nend\n\nlocal function popup_contents(c)\n    if imgui.MenuItem(\"Copy file path\") then\n        imgui.SetClipboardText(c.file)\n    end\n\n    if imgui.MenuItem(\"Copy name\") then\n        imgui.SetClipboardText(c.display_name)\n    end\nend\n\nlocal unique_herds = get_unique_attrs(\"herd\")\nlocal unique_origins = get_unique_attrs(\"origin\")\n\nlocal filter_search = \"\"\n---@type string?\nlocal filter_herd = nil\n---@type string?\nlocal filter_origin = nil\n\nreturn function()\n    local _\n\n    imgui.SetNextItemWidth(200)\n    _, filter_search = imgui.InputText(\"Search\", filter_search)\n\n    imgui.SameLine()\n    imgui.SetNextItemWidth(150)\n    _, filter_herd = combo.optional(\"Herd\", unique_herds, filter_herd)\n\n    if #unique_origins > 1 then\n        imgui.SameLine()\n        imgui.SetNextItemWidth(150)\n        _, filter_origin = combo.optional(\"Origin\", unique_origins, filter_origin)\n    end\n\n    local filtered_creatures\n\n    if filter_search == \"\" and filter_herd == nil and filter_origin == nil then\n        filtered_creatures = creatures\n    else\n        filtered_creatures = {}\n        for _, c in ipairs(creatures) do\n            if\n                (filter_search == \"\" or (\n                    string_util.ifind(c.display_name, filter_search, 1, true) or\n                    (c.name and string_util.ifind(c.name, filter_search, 1, true)) or\n                    (c.statsname and string_util.ifind(c.statsname, filter_search, 1, true)) or\n                    string_util.ifind(c.tags, filter_search, 1, true) or\n                    string_util.ifind(c.file, filter_search, 1, true)\n                ))\n                and (filter_herd == nil or c.herd == filter_herd)\n                and (filter_origin == nil or c.origin == filter_origin)\n            then\n                table.insert(filtered_creatures, c)\n            end\n        end\n    end\n\n    if not imgui.BeginChild(\"table\") then\n        return\n    end\n\n    local column_count = 6\n\n    local has_image_support = imgui.LoadImage ~= nil\n    if has_image_support then\n        column_count = column_count + 1\n    end\n\n    local flags = bit.bor(\n        imgui.TableFlags.Resizable,\n        imgui.TableFlags.Hideable,\n        imgui.TableFlags.RowBg\n    )\n    if imgui.BeginTable(\"creatures\", column_count, flags) then\n        if has_image_support then\n            imgui.TableSetupColumn(\"img\",  imgui.TableColumnFlags.WidthFixed)\n        end\n        imgui.TableSetupColumn(\"Name\")\n        imgui.TableSetupColumn(\"File\")\n        imgui.TableSetupColumn(\"Tags\", imgui.TableColumnFlags.DefaultHide)\n        imgui.TableSetupColumn(\"Herd\", imgui.TableColumnFlags.WidthFixed)\n        imgui.TableSetupColumn(\"Origin\", bit.bor(imgui.TableColumnFlags.DefaultHide, imgui.TableColumnFlags.WidthFixed))\n        imgui.TableSetupColumn(\"Spawn\", imgui.TableColumnFlags.WidthFixed)\n        imgui.TableHeadersRow()\n\n        -- Keep all images loaded, not just the visible ones\n        if has_image_support then\n            local image_paths = {}\n            for _, c in ipairs(creatures) do\n                if c.img_path then\n                    table.insert(image_paths, c.img_path)\n                end\n            end\n            -- Files are placed alphabetically in the data.wak, loading them in\n            -- that order is much faster.\n            table.sort(image_paths)\n            for _, path in ipairs(image_paths) do\n                imgui.LoadImage(path)\n            end\n        end\n\n        local clipper = imgui.ListClipper.new()\n        clipper:Begin(#filtered_creatures)\n        while clipper:Step() do\n            for i=clipper.DisplayStart,clipper.DisplayEnd - 1 do\n                local c = filtered_creatures[i + 1]\n                imgui.PushID(c.file)\n\n                if has_image_support then\n                    imgui.TableNextColumn()\n                    if c.img_path then\n                        local img = imgui.LoadImage(c.img_path)\n                        if img then\n                            local style = imgui.GetStyle()\n                            local image_size = imgui.GetTextLineHeight() + style.CellPadding_y * 2\n                            imgui.Image(img, image_size, image_size)\n                        end\n                    end\n                end\n\n                imgui.TableNextColumn()\n                imgui.Text(c.display_name)\n\n                imgui.TableNextColumn()\n                imgui.Text(c.file)\n\n                imgui.TableNextColumn()\n                imgui.Text(c.tags)\n\n                imgui.TableNextColumn()\n                imgui.Text(c.herd)\n                if imgui.IsItemHovered() and imgui.IsMouseReleased(imgui.MouseButton.Right) then\n                    filter_herd = c.herd\n                end\n\n                imgui.TableNextColumn()\n                imgui.Text(c.origin)\n                if #unique_origins > 1 and imgui.IsItemHovered() and imgui.IsMouseReleased(imgui.MouseButton.Right) then\n                    filter_origin = c.origin\n                end\n\n                imgui.TableNextColumn()\n                if imgui.SmallButton(\"Spawn\") then\n                    local spawned_entity = EntityLoad(c.file, cursor.pos())\n\n                    if imgui.IsKeyDown(imgui.Key.LeftShift) then\n                        entity.watch_entity(spawned_entity)\n                    end\n                end\n\n                if imgui.BeginPopupContextItem() then\n                    popup_contents(c)\n                    imgui.EndPopup()\n                end\n\n                imgui.PopID()\n            end\n        end\n\n        imgui.EndTable()\n    end\n\n    imgui.EndChild()\nend\n"
_TWWE_VFS["mods/component-explorer/spawn_stuff/items.lua"] = "---@module 'component-explorer.spawn_data.items'\nlocal items_ = dofile_once(\"mods/component-explorer/spawn_data/items.lua\")\n\n---@module 'component-explorer.utils.copy'\nlocal copy = dofile_once(\"mods/component-explorer/utils/copy.lua\")\n\n---@module 'component-explorer.utils.strings'\nlocal string_util = dofile_once(\"mods/component-explorer/utils/strings.lua\")\n\n---@module 'component-explorer.cursor'\nlocal cursor = dofile_once(\"mods/component-explorer/cursor.lua\")\n\n---@module 'component-explorer.ui.combo'\nlocal combo = dofile_once(\"mods/component-explorer/ui/combo.lua\")\n\n---@module 'component-explorer.utils.file_util'\nlocal file_util = dofile_once(\"mods/component-explorer/utils/file_util.lua\")\n\nlocal function get_enhanced_items()\n    local ret = {}\n    for _, c_ in ipairs(items_) do\n        local c = copy.shallow_copy(c_)\n\n        if not file_util.file_exists(c.file) then\n            goto continue\n        end\n\n        local preferred_name = c.item_name or c.ui_name\n        if preferred_name then\n            c.display_name = GameTextGetTranslatedOrNot(preferred_name)\n        else\n            c.display_name = string.match(c.file, \"[^/]*$\")\n        end\n\n        table.insert(ret, c)\n        ::continue::\n    end\n\n    table.sort(ret, function(a, b) return a.display_name < b.display_name end)\n    return ret\nend\n\nlocal items = get_enhanced_items()\n\nlocal function get_unique_attrs(attr)\n    local set = {}\n    for _, c in ipairs(items) do\n        set[c[attr]] = true\n    end\n\n    local ret = {}\n    for item, _ in pairs(set) do\n        table.insert(ret, item)\n    end\n\n    table.sort(ret)\n\n    return ret\nend\n\nlocal unique_origins = get_unique_attrs(\"origin\")\n\nlocal function popup_contents(item)\n    if imgui.MenuItem(\"Copy file path\") then\n        imgui.SetClipboardText(item.file)\n    end\n\n    if imgui.MenuItem(\"Copy name\") then\n        imgui.SetClipboardText(item.display_name)\n    end\nend\n\nlocal filter_search = \"\"\n---@type string?\nlocal filter_origin = nil\n\nreturn function()\n    local _\n\n    imgui.SetNextItemWidth(200)\n    _, filter_search = imgui.InputText(\"Search\", filter_search)\n\n    if #unique_origins > 1 then\n        imgui.SameLine()\n        imgui.SetNextItemWidth(150)\n        _, filter_origin = combo.optional(\"Origin\", unique_origins, filter_origin)\n    end\n\n    local filtered_items\n\n    if filter_search == \"\" and filter_origin == nil then\n        filtered_items = items\n    else\n        filtered_items = {}\n        for _, c in ipairs(items) do\n            if\n                (filter_search == \"\" or (\n                    string_util.ifind(c.display_name, filter_search, 1, true) or\n                    (c.ui_name and string_util.ifind(c.ui_name, filter_search, 1, true)) or\n                    string_util.ifind(c.tags, filter_search, 1, true) or\n                    string_util.ifind(c.file, filter_search, 1, true)\n                ))\n                and (filter_origin == nil or c.origin == filter_origin)\n            then\n                table.insert(filtered_items, c)\n            end\n        end\n    end\n\n    if not imgui.BeginChild(\"table\") then\n        return\n    end\n\n    local flags = bit.bor(\n        imgui.TableFlags.Resizable,\n        imgui.TableFlags.Hideable,\n        imgui.TableFlags.RowBg\n    )\n    if imgui.BeginTable(\"items\", 5, flags) then\n        imgui.TableSetupColumn(\"Name\")\n        imgui.TableSetupColumn(\"File\")\n        imgui.TableSetupColumn(\"Tags\", imgui.TableColumnFlags.DefaultHide)\n        imgui.TableSetupColumn(\"Origin\", bit.bor(imgui.TableColumnFlags.DefaultHide, imgui.TableColumnFlags.WidthFixed))\n        imgui.TableSetupColumn(\"Spawn\", imgui.TableColumnFlags.WidthFixed)\n        imgui.TableHeadersRow()\n\n        local clipper = imgui.ListClipper.new()\n        clipper:Begin(#filtered_items)\n\n        while clipper:Step() do\n            for i=clipper.DisplayStart,clipper.DisplayEnd - 1 do\n                local c = filtered_items[i + 1]\n\n                imgui.PushID(c.file)\n\n                imgui.TableNextColumn()\n                imgui.Text(c.display_name)\n\n                imgui.TableNextColumn()\n                imgui.Text(c.file)\n\n                imgui.TableNextColumn()\n                imgui.Text(c.tags)\n\n                imgui.TableNextColumn()\n                imgui.Text(c.origin)\n                if #unique_origins > 1 and imgui.IsItemHovered() and imgui.IsMouseReleased(imgui.MouseButton.Right) then\n                    filter_origin = c.origin\n                end\n\n                imgui.TableNextColumn()\n                if imgui.SmallButton(\"Spawn\") then\n                    EntityLoad(c.file, cursor.pos())\n                end\n\n                if imgui.BeginPopupContextItem() then\n                    popup_contents(c)\n                    imgui.EndPopup()\n                end\n\n                imgui.PopID()\n            end\n        end\n\n        imgui.EndTable()\n    end\n\n    imgui.EndChild()\nend\n"
_TWWE_VFS["mods/component-explorer/spawn_stuff/materials.lua"] = "---@module 'component-explorer.utils.strings'\nlocal string_util = dofile_once(\"mods/component-explorer/utils/strings.lua\")\n\n---@module 'component-explorer.ui.combo'\nlocal combo = dofile_once(\"mods/component-explorer/ui/combo.lua\")\n\n---@module 'component-explorer.utils.player_util'\nlocal player_util = dofile_once(\"mods/component-explorer/utils/player_util.lua\")\n\n---@module 'component-explorer.spawn_data.materials'\nlocal materials = dofile_once(\"mods/component-explorer/spawn_data/materials.lua\")\n\nlocal function get_unique_attrs(attr)\n    local set = {}\n    for _, mat in ipairs(materials) do\n        set[mat[attr]] = true\n    end\n\n    local ret = {}\n    for item, _ in pairs(set) do\n        table.insert(ret, item)\n    end\n\n    table.sort(ret)\n    return ret\nend\nlocal unique_origins = get_unique_attrs(\"origin\")\nlocal unique_material_types = get_unique_attrs(\"material_type\")\n\nlocal function make_empty_stash(x, y)\n    local stash = EntityLoad(\"data/entities/items/pickup/powder_stash.xml\", x, y)\n    while true do\n        local mat_id = GetMaterialInventoryMainMaterial(stash)\n        if mat_id == 0 then\n            return stash\n        end\n        AddMaterialInventoryMaterial(stash, CellFactory_GetName(mat_id), 0)\n    end\nend\n\n---@param entity integer\n---@return integer\nlocal function container_matinv_size(entity)\n    local sucker_comp = EntityGetFirstComponentIncludingDisabled(entity, \"MaterialSuckerComponent\")\n    if sucker_comp then\n        return ComponentGetValue2(sucker_comp, \"barrel_size\")\n    end\n\n    -- Fallback default\n    return 1000\nend\n\nlocal function popup_contents(mat)\n    if imgui.MenuItem(\"Copy name\") then\n        imgui.SetClipboardText(mat.name)\n    end\n\n    if imgui.MenuItem(\"Copy display name\") then\n        imgui.SetClipboardText(mat.display_name)\n    end\nend\n\nlocal filter_search = \"\"\n---@type string?\nlocal filter_origin = nil\n---@type string?\nlocal filter_material_type = nil\n\nlocal container_options = {\"Flask\", \"Pouch\"}\nlocal container_choice = nil\n\nlocal function mat_container_choice(mat)\n    if container_choice then return container_choice end\n\n    if mat.material_type == \"Powder\" or mat.material_type == \"Static\" then\n        return \"Pouch\"\n    else\n        return \"Flask\"\n    end\nend\n\nreturn function()\n    local _\n\n    imgui.SetNextItemWidth(200)\n    _, filter_search = imgui.InputText(\"Search\", filter_search)\n\n    imgui.SameLine()\n    imgui.SetNextItemWidth(150)\n    _, filter_material_type = combo.optional(\"Material Type\", unique_material_types, filter_material_type)\n\n    if #unique_origins > 1 then\n        imgui.SameLine()\n        imgui.SetNextItemWidth(150)\n        _, filter_origin = combo.optional(\"Origin\", unique_origins, filter_origin)\n    end\n\n    imgui.Separator()\n\n    imgui.SetNextItemWidth(150)\n    _, container_choice = combo.optional(\"Spawn Container\", container_options, container_choice, \"--Depends--\")\n    if not imgui.BeginChild(\"table\") then\n        return\n    end\n\n    local filtered_materials\n    if filter_search == \"\" and filter_material_type == nil and filter_origin == nil then\n        filtered_materials = materials\n    else\n        filtered_materials = {}\n        for _, mat in ipairs(materials) do\n            if\n                (filter_search == \"\" or (\n                    string_util.ifind(mat.display_name, filter_search, 1, true) or\n                    string_util.ifind(mat.name, filter_search, 1, true) or\n                    string_util.ifind(mat.tags, filter_search, 1, true)\n                ))\n                and (filter_material_type == nil or mat.material_type == filter_material_type)\n                and (filter_origin == nil or mat.origin == filter_origin)\n            then\n                table.insert(filtered_materials, mat)\n            end\n        end\n    end\n\n    local flags = bit.bor(\n        imgui.TableFlags.Resizable,\n        imgui.TableFlags.Hideable,\n        imgui.TableFlags.RowBg\n    )\n\n    if imgui.BeginTable(\"mats\", 7, flags) then\n        imgui.TableSetupColumn(\"#\", imgui.TableColumnFlags.WidthFixed)\n        imgui.TableSetupColumn(\"Display\")\n        imgui.TableSetupColumn(\"Name\", imgui.TableColumnFlags.DefaultHide)\n        imgui.TableSetupColumn(\"Tags\", imgui.TableColumnFlags.DefaultHide)\n        imgui.TableSetupColumn(\"Type\", imgui.TableColumnFlags.WidthFixed)\n        imgui.TableSetupColumn(\"Origin\", imgui.TableColumnFlags.WidthFixed)\n        imgui.TableSetupColumn(\"Spawn\", imgui.TableColumnFlags.WidthFixed)\n        imgui.TableHeadersRow()\n\n        local clipper = imgui.ListClipper.new()\n        clipper:Begin(#filtered_materials)\n\n        while clipper:Step() do\n            for i=clipper.DisplayStart,clipper.DisplayEnd - 1 do\n                local mat = filtered_materials[i + 1]\n                imgui.PushID(mat.name)\n\n                imgui.TableNextColumn()\n                imgui.Text(tostring(mat.id))\n\n                imgui.TableNextColumn()\n                imgui.Text(mat.display_name)\n\n                imgui.TableNextColumn()\n                imgui.Text(mat.name)\n\n                imgui.TableNextColumn()\n                imgui.Text(mat.tags)\n\n                imgui.TableNextColumn()\n                imgui.Text(mat.material_type)\n                if imgui.IsItemHovered() and imgui.IsMouseReleased(imgui.MouseButton.Right) then\n                    filter_material_type = mat.material_type\n                end\n\n                imgui.TableNextColumn()\n                imgui.Text(mat.origin)\n                if #unique_origins > 1 and imgui.IsItemHovered() and imgui.IsMouseReleased(imgui.MouseButton.Right) then\n                    filter_origin = mat.origin\n                end\n\n                imgui.TableNextColumn()\n                local mat_container = mat_container_choice(mat)\n                if imgui.SmallButton(mat_container) then\n                    local player = player_util.get_player()\n                    if player then\n                        local x, y = EntityGetTransform(player)\n                        local container\n                        if mat_container == \"Pouch\" then\n                            container = make_empty_stash(x, y)\n                        else\n                            container = EntityLoad(\"data/entities/items/pickup/potion_empty.xml\", x, y)\n                        end\n                        AddMaterialInventoryMaterial(container, mat.name, container_matinv_size(container))\n                    end\n                end\n\n                if imgui.BeginPopupContextItem() then\n                    popup_contents(mat)\n                    imgui.EndPopup()\n                end\n\n                imgui.PopID()\n            end\n        end\n\n        imgui.EndTable()\n    end\n\n    imgui.EndChild()\nend\n"
_TWWE_VFS["mods/component-explorer/spawn_stuff/perks.lua"] = "---@module 'component-explorer.utils.strings'\nlocal string_util = dofile_once(\"mods/component-explorer/utils/strings.lua\")\n\n---@module 'component-explorer.ui.combo'\nlocal combo = dofile_once(\"mods/component-explorer/ui/combo.lua\")\n\n---@module 'component-explorer.utils.player_util'\nlocal player_util = dofile_once(\"mods/component-explorer/utils/player_util.lua\")\n\n---@module 'component-explorer.spawn_data.perks'\nlocal perk_list = dofile_once(\"mods/component-explorer/spawn_data/perks.lua\")\n\n---@module 'component-explorer.cursor'\nlocal cursor = dofile_once(\"mods/component-explorer/cursor.lua\")\n\nlocal function get_unique_attrs(attr)\n    local set = {}\n    for _, perk in ipairs(perk_list) do\n        set[perk[attr]] = true\n    end\n\n    local ret = {}\n    for item, _ in pairs(set) do\n        table.insert(ret, item)\n    end\n\n    table.sort(ret)\n    return ret\nend\nlocal unique_origins = get_unique_attrs(\"origin\")\n\nlocal function spawn_perk_at_cursor(perk)\n    local x, y = cursor.pos()\n    perk_spawn(x, y, perk.id)\nend\n\nlocal function player_equip_perk(perk)\n    local player = player_util.get_player()\n    if player then\n        local success, result = pcall(function()\n            local x, y = EntityGetTransform(player)\n            local perk_entity = perk_spawn(x, y - 8, perk.id)\n            perk_pickup(perk_entity, player, nil, true, false)\n        end)\n\n        if not success then\n            print_error(\"CE give perk error: \" .. tostring(result))\n        end\n    end\nend\n\nlocal function popup_contents(p)\n    if imgui.MenuItem(\"Copy perk.id\") then\n        imgui.SetClipboardText(p.id)\n    end\n\n    if imgui.MenuItem(\"Copy name\") then\n        imgui.SetClipboardText(p.display_name)\n    end\nend\n\n\nlocal filter_search = \"\"\n---@type string?\nlocal filter_origin = nil\n\nreturn function()\n    local _\n\n    imgui.SetNextItemWidth(200)\n    _, filter_search = imgui.InputText(\"Search\", filter_search)\n\n    if #unique_origins > 1 then\n        imgui.SameLine()\n        imgui.SetNextItemWidth(150)\n        _, filter_origin = combo.optional(\"Origin\", unique_origins, filter_origin)\n    end\n\n    local filtered_perks\n    if filter_search == \"\" and filter_origin == nil then\n        filtered_perks = perk_list\n    else\n        filtered_perks = {}\n        for _, perk in ipairs(perk_list) do\n            if\n                (filter_search == \"\" or (\n                    string_util.ifind(perk.id, filter_search, 1, true) or\n                    string_util.ifind(perk.display_name, filter_search, 1, true) or\n                    string_util.ifind(perk.display_description, filter_search, 1, true)\n                ))\n                and (filter_origin == nil or perk.origin == filter_origin)\n            then\n                table.insert(filtered_perks, perk)\n            end\n        end\n    end\n\n    if not imgui.BeginChild(\"table\") then return end\n\n    local column_count = 4\n\n    local has_image_support = imgui.LoadImage ~= nil\n    if has_image_support then\n        column_count = column_count + 1\n    end\n\n    local flags = bit.bor(\n        imgui.TableFlags.Resizable,\n        imgui.TableFlags.Hideable,\n        imgui.TableFlags.RowBg\n    )\n\n    if imgui.BeginTable(\"perks\", column_count, flags) then\n        if has_image_support then\n            imgui.TableSetupColumn(\"img\", imgui.TableColumnFlags.WidthFixed)\n        end\n        imgui.TableSetupColumn(\"Name\")\n        imgui.TableSetupColumn(\"ID\")\n        imgui.TableSetupColumn(\"Origin\", imgui.TableColumnFlags.WidthFixed)\n        imgui.TableSetupColumn(\"Spawn\", imgui.TableColumnFlags.WidthFixed)\n        imgui.TableHeadersRow()\n\n        if has_image_support then\n            local image_paths = {}\n            for _, p in ipairs(perk_list) do\n                if p.perk_icon then\n                    table.insert(image_paths, p.perk_icon)\n                end\n            end\n            -- Files are placed alphabetically in the data.wak, loading them in\n            -- that order is much faster.\n            table.sort(image_paths)\n            for _, path in ipairs(image_paths) do\n                imgui.LoadImage(path)\n            end\n        end\n\n        local spawn_at_cursor = imgui.IsKeyDown(imgui.Key.LeftShift)\n\n        local clipper = imgui.ListClipper.new()\n        clipper:Begin(#filtered_perks)\n\n        while clipper:Step() do\n            for i=clipper.DisplayStart,clipper.DisplayEnd - 1 do\n                local perk = filtered_perks[i + 1]\n                imgui.PushID(perk.id)\n\n                if has_image_support then\n                    imgui.TableNextColumn()\n                    if perk.perk_icon then\n                        local img = imgui.LoadImage(perk.perk_icon)\n                        if img then\n                            local style = imgui.GetStyle()\n                            local image_size = imgui.GetTextLineHeight() + style.CellPadding_y * 2\n                            imgui.Image(img, image_size, image_size)\n                        end\n                    end\n                end\n\n                imgui.TableNextColumn()\n                imgui.Text(perk.display_name)\n\n                imgui.TableNextColumn()\n                imgui.Text(perk.id)\n\n                imgui.TableNextColumn()\n                imgui.Text(perk.origin)\n                if #unique_origins > 1 and imgui.IsItemHovered() and imgui.IsMouseReleased(imgui.MouseButton.Right) then\n                    filter_origin = perk.origin\n                end\n\n                imgui.TableNextColumn()\n\n                if spawn_at_cursor then\n                    if imgui.SmallButton(\"Spawn\") then spawn_perk_at_cursor(perk) end\n                else\n                    if imgui.SmallButton(\"Equip\") then player_equip_perk(perk) end\n                end\n\n                if imgui.BeginPopupContextItem() then\n                    popup_contents(perk)\n                    imgui.EndPopup()\n                end\n\n                imgui.PopID()\n            end\n        end\n\n        imgui.EndTable()\n    end\n\n    imgui.EndChild()\nend\n"
_TWWE_VFS["mods/component-explorer/spawn_stuff/props.lua"] = "---@module 'component-explorer.spawn_data.props'\nlocal props = dofile_once(\"mods/component-explorer/spawn_data/props.lua\")\n\n---@module 'component-explorer.utils.strings'\nlocal string_util = dofile_once(\"mods/component-explorer/utils/strings.lua\")\n\n---@module 'component-explorer.cursor'\nlocal cursor = dofile_once(\"mods/component-explorer/cursor.lua\")\n\n---@module 'component-explorer.ui.combo'\nlocal combo = dofile_once(\"mods/component-explorer/ui/combo.lua\")\n\n---@module 'component-explorer.entity'\nlocal entity = dofile_once(\"mods/component-explorer/entity.lua\")\n\nfor _, prop in ipairs(props) do\n    prop.material = prop.material or \"\"\nend\n\nlocal function get_unique_attrs(attr)\n    local set = {}\n    for _, c in ipairs(props) do\n        set[c[attr]] = true\n    end\n\n    local ret = {}\n    for item, _ in pairs(set) do\n        table.insert(ret, item)\n    end\n\n    table.sort(ret)\n    return ret\nend\n\nlocal function popup_contents(c)\n    if imgui.MenuItem(\"Copy file path\") then\n        imgui.SetClipboardText(c.file)\n    end\n\n    if imgui.MenuItem(\"Copy name\") then\n        imgui.SetClipboardText(c.name)\n    end\n\n    if c.material ~= \"\" and imgui.MenuItem(\"Copy material\") then\n        imgui.SetClipboardText(c.material)\n    end\nend\n\nlocal unique_origins = get_unique_attrs(\"origin\")\n\nlocal filter_search = \"\"\n---@type string?\nlocal filter_origin = nil\n\nreturn function()\n    local _\n\n    imgui.SetNextItemWidth(200)\n    _, filter_search = imgui.InputText(\"Search\", filter_search)\n\n    if #unique_origins > 1 then\n        imgui.SameLine()\n        imgui.SetNextItemWidth(150)\n        _, filter_origin = combo.optional(\"Origin\", unique_origins, filter_origin)\n    end\n\n    local filtered_props\n\n    if filter_search == \"\" and filter_origin == nil then\n        filtered_props = props\n    else\n        filtered_props = {}\n        for _, c in ipairs(props) do\n            if\n                (filter_search == \"\" or (\n                    (c.name and string_util.ifind(c.name, filter_search, 1, true)) or\n                    string_util.ifind(c.tags, filter_search, 1, true) or\n                    string_util.ifind(c.material, filter_search, 1, true) or\n                    string_util.ifind(c.file, filter_search, 1, true)\n                ))\n                and (filter_origin == nil or c.origin == filter_origin)\n            then\n                table.insert(filtered_props, c)\n            end\n        end\n    end\n\n    if not imgui.BeginChild(\"table\") then\n        return\n    end\n\n    local column_count = 6\n\n    local has_image_support = imgui.LoadImage ~= nil\n    if has_image_support then\n        column_count = column_count + 1\n    end\n\n    local flags = bit.bor(\n        imgui.TableFlags.Resizable,\n        imgui.TableFlags.Hideable,\n        imgui.TableFlags.RowBg\n    )\n    if imgui.BeginTable(\"props\", column_count, flags) then\n        if has_image_support then\n            imgui.TableSetupColumn(\"img\",  imgui.TableColumnFlags.WidthFixed)\n        end\n        imgui.TableSetupColumn(\"Name\")\n        imgui.TableSetupColumn(\"File\")\n        imgui.TableSetupColumn(\"Material\", imgui.TableColumnFlags.DefaultHide)\n        imgui.TableSetupColumn(\"Tags\", imgui.TableColumnFlags.DefaultHide)\n        imgui.TableSetupColumn(\"Origin\", bit.bor(imgui.TableColumnFlags.DefaultHide, imgui.TableColumnFlags.WidthFixed))\n        imgui.TableSetupColumn(\"Spawn\", imgui.TableColumnFlags.WidthFixed)\n        imgui.TableHeadersRow()\n\n        -- Keep all images loaded, not just the visible ones\n        if has_image_support then\n            local image_paths = {}\n            for _, c in ipairs(props) do\n                if c.image then\n                    table.insert(image_paths, c.image)\n                end\n            end\n            -- Files are placed alphabetically in the data.wak, loading them in\n            -- that order is much faster.\n            table.sort(image_paths)\n            for _, path in ipairs(image_paths) do\n                imgui.LoadImage(path)\n            end\n        end\n\n        local clipper = imgui.ListClipper.new()\n        clipper:Begin(#filtered_props)\n        while clipper:Step() do\n            for i=clipper.DisplayStart,clipper.DisplayEnd - 1 do\n                local c = filtered_props[i + 1]\n                imgui.PushID(c.file)\n\n                if has_image_support then\n                    imgui.TableNextColumn()\n                    if c.image then\n                        local img = imgui.LoadImage(c.image)\n                        if img then\n                            local image_height = imgui.GetTextLineHeight()\n                            local image_width = image_height / img.height * img.width\n                            imgui.Image(img, image_width, image_height)\n                        end\n                    end\n                end\n\n                imgui.TableNextColumn()\n                imgui.Text(c.name)\n\n                imgui.TableNextColumn()\n                imgui.Text(c.file)\n\n                imgui.TableNextColumn()\n                imgui.Text(c.material)\n\n                imgui.TableNextColumn()\n                imgui.Text(c.tags)\n\n                imgui.TableNextColumn()\n                imgui.Text(c.origin)\n                if #unique_origins > 1 and imgui.IsItemHovered() and imgui.IsMouseReleased(imgui.MouseButton.Right) then\n                    filter_origin = c.origin\n                end\n\n                imgui.TableNextColumn()\n                local do_spawn = imgui.SmallButton(\"Spawn\")\n                if imgui.BeginPopupContextItem() then\n                    popup_contents(c)\n                    imgui.EndPopup()\n                end\n\n                if do_spawn then\n                    local spawned_prop = EntityLoad(c.file, cursor.pos())\n\n                    if imgui.IsKeyDown(imgui.Key.LeftShift) then\n                        entity.watch_entity(spawned_prop)\n                    end\n                end\n\n                imgui.PopID()\n            end\n        end\n\n        imgui.EndTable()\n    end\n\n    imgui.EndChild()\nend\n"
_TWWE_VFS["mods/component-explorer/spawn_stuff/spells.lua"] = "---@module 'component-explorer.utils.strings'\nlocal string_util = dofile_once(\"mods/component-explorer/utils/strings.lua\")\n\n---@module 'component-explorer.ui.combo'\nlocal combo = dofile_once(\"mods/component-explorer/ui/combo.lua\")\n\n---@module 'component-explorer.utils.player_util'\nlocal player_util = dofile_once(\"mods/component-explorer/utils/player_util.lua\")\n\n---@module 'component-explorer.spawn_data.actions'\nlocal actions_data = dofile_once(\"mods/component-explorer/spawn_data/actions.lua\")\n\n---@module 'component-explorer.cursor'\nlocal cursor = dofile_once(\"mods/component-explorer/cursor.lua\")\n\nlocal actions = actions_data.actions\nlocal unique_action_types = actions_data.unique_action_types\nlocal action_type_to_name = actions_data.action_type_to_name\n\nlocal function get_unique_attrs(attr)\n    local set = {}\n    for _, action in ipairs(actions) do\n        set[action[attr]] = true\n    end\n\n    local ret = {}\n    for item, _ in pairs(set) do\n        table.insert(ret, item)\n    end\n\n    table.sort(ret)\n    return ret\nend\nlocal unique_origins = get_unique_attrs(\"origin\")\n\nlocal function popup_contents(action)\n    if imgui.MenuItem(\"Copy action.id\") then\n        imgui.SetClipboardText(action.id)\n    end\n\n    if imgui.MenuItem(\"Copy name\") then\n        imgui.SetClipboardText(action.display_name)\n    end\nend\n\nlocal filter_search = \"\"\n---@type string?\nlocal filter_origin = nil\n---@type string?\nlocal filter_action_type = nil\n\nreturn function()\n    local _\n\n    imgui.SetNextItemWidth(200)\n    _, filter_search = imgui.InputText(\"Search\", filter_search)\n\n    imgui.SameLine()\n    imgui.SetNextItemWidth(150)\n    _, filter_action_type = combo.optional(\"Type\", unique_action_types, filter_action_type)\n\n    if #unique_origins > 1 then\n        imgui.SameLine()\n        imgui.SetNextItemWidth(150)\n        _, filter_origin = combo.optional(\"Origin\", unique_origins, filter_origin)\n    end\n\n    local filtered_actions\n    if filter_search == \"\" and filter_origin == nil and filter_action_type == nil then\n        filtered_actions = actions\n    else\n        filtered_actions = {}\n        for _, action in ipairs(actions) do\n            if\n                (filter_search == \"\" or (\n                    string_util.ifind(action.id, filter_search, 1, true) or\n                    string_util.ifind(action.display_name, filter_search, 1, true) or\n                    string_util.ifind(action.display_description, filter_search, 1, true)\n                ))\n                and (filter_origin == nil or action.origin == filter_origin)\n                and (filter_action_type == nil or action_type_to_name(action.type) == filter_action_type)\n            then\n                table.insert(filtered_actions, action)\n            end\n        end\n    end\n\n    if not imgui.BeginChild(\"table\") then return end\n\n    local column_count = 5\n\n    local has_image_support = imgui.LoadImage ~= nil\n    if has_image_support then\n        column_count = column_count + 1\n    end\n\n    local flags = bit.bor(\n        imgui.TableFlags.Resizable,\n        imgui.TableFlags.Hideable,\n        imgui.TableFlags.RowBg\n    )\n\n    if imgui.BeginTable(\"spells\", column_count, flags) then\n        if has_image_support then\n            imgui.TableSetupColumn(\"img\", imgui.TableColumnFlags.WidthFixed)\n        end\n        imgui.TableSetupColumn(\"Name\")\n        imgui.TableSetupColumn(\"ID\")\n        imgui.TableSetupColumn(\"Type\", imgui.TableColumnFlags.WidthFixed)\n        imgui.TableSetupColumn(\"Origin\", imgui.TableColumnFlags.WidthFixed)\n        imgui.TableSetupColumn(\"Spawn\", imgui.TableColumnFlags.WidthFixed)\n        imgui.TableHeadersRow()\n\n        if has_image_support then\n            local image_paths = {}\n            for _, p in ipairs(actions) do\n                if p.sprite then\n                    table.insert(image_paths, p.sprite)\n                end\n            end\n            -- Files are placed alphabetically in the data.wak, loading them in\n            -- that order is much faster.\n            table.sort(image_paths)\n            for _, path in ipairs(image_paths) do\n                imgui.LoadImage(path)\n            end\n        end\n\n        local spawn_at_cursor = imgui.IsKeyDown(imgui.Key.LeftShift)\n\n        local clipper = imgui.ListClipper.new()\n        clipper:Begin(#filtered_actions)\n\n        while clipper:Step() do\n            for i=clipper.DisplayStart,clipper.DisplayEnd - 1 do\n                local action = filtered_actions[i + 1]\n                imgui.PushID(action.id)\n\n                if has_image_support then\n                    imgui.TableNextColumn()\n                    if action.sprite then\n                        local img = imgui.LoadImage(action.sprite)\n                        if img then\n                            local style = imgui.GetStyle()\n                            local image_size = imgui.GetTextLineHeight() + style.CellPadding_y * 2\n                            imgui.Image(img, image_size, image_size)\n                        end\n                    end\n                end\n\n                imgui.TableNextColumn()\n                imgui.Text(action.display_name)\n\n                imgui.TableNextColumn()\n                imgui.Text(action.id)\n\n                imgui.TableNextColumn()\n                imgui.Text(action_type_to_name(action.type))\n                if imgui.IsItemHovered() and imgui.IsMouseReleased(imgui.MouseButton.Right) then\n                    filter_action_type = action_type_to_name(action.type)\n                end\n\n                imgui.TableNextColumn()\n                imgui.Text(action.origin)\n                if #unique_origins > 1 and imgui.IsItemHovered() and imgui.IsMouseReleased(imgui.MouseButton.Right) then\n                    filter_origin = action.origin\n                end\n\n                imgui.TableNextColumn()\n                if imgui.SmallButton(\"Spawn\") then\n                    local x, y = cursor.pos()\n                    if not spawn_at_cursor then\n                        local player = player_util.get_player()\n                        if player then\n                            x, y = EntityGetTransform(player)\n                        end\n                    end\n\n                    CreateItemActionEntity(action.id, x, y)\n                end\n\n                if imgui.BeginPopupContextItem() then\n                    popup_contents(action)\n                    imgui.EndPopup()\n                end\n\n                imgui.PopID()\n            end\n        end\n\n        imgui.EndTable()\n    end\n\n    imgui.EndChild()\nend\n"
_TWWE_VFS["mods/component-explorer/style.lua"] = "local style = {}\n\nstyle.colour_fail = {1, 0.4, 0.4, 1}\nstyle.colour_danger = style.colour_fail\nstyle.colour_warn = {0.96, 0.94, 0, 1}\n\nlocal function danger_button_ex(text, buttonfn)\n    imgui.PushStyleColor(imgui.Col.Button, 1, 0.4, 0.4)\n    imgui.PushStyleColor(imgui.Col.ButtonHovered, 1, 0.6, 0.6)\n    imgui.PushStyleColor(imgui.Col.ButtonActive, 0.8, 0.4, 0.4)\n    local ret = buttonfn(text)\n    imgui.PopStyleColor(3)\n\n    return ret\nend\n\nfunction style.danger_button(text)\n    return danger_button_ex(text , imgui.Button)\nend\n\nfunction style.danger_small_button(text)\n    return danger_button_ex(text , imgui.SmallButton)\nend\n\nreturn style\n"
_TWWE_VFS["mods/component-explorer/tags_gui.lua"] = "local tags_gui = {}\n\nfunction tags_gui.show(data, tags, add, remove, common_tags)\n    common_tags = common_tags or {}\n\n    data.new_tag_input = data.new_tag_input or \"\"\n\n    imgui.SetNextItemWidth(200)\n    local submit\n    submit, data.new_tag_input = imgui.InputText(\n        \"Add tag\", data.new_tag_input,\n        imgui.InputTextFlags.EnterReturnsTrue\n    )\n    if submit then\n        add(data.new_tag_input)\n        data.new_tag_input = \"\"\n    end\n\n    local tag_set = {}\n    for _, tag in ipairs(tags) do\n        tag_set[tag] = true\n    end\n\n    if #common_tags > 0 then\n        imgui.SameLine()\n        if imgui.Button(\"Common..\") then\n            imgui.OpenPopup(\"common_tags_popup\")\n        end\n\n        if imgui.BeginPopup(\"common_tags_popup\") then\n            for _, tag in ipairs(common_tags) do\n                if imgui.MenuItem(tag, \"\", tag_set[tag] ~= nil) then\n                    if tag_set[tag] then\n                        remove(tag)\n                    else\n                        add(tag)\n                    end\n                end\n            end\n            imgui.EndPopup()\n        end\n    end\n\n    local table_flags = imgui.TableFlags.Resizable\n    if imgui.BeginTable(\"tags\", 2, table_flags) then\n\n        imgui.TableSetupColumn(\"Tag\")\n        imgui.TableSetupColumn(\"Remove\", imgui.TableColumnFlags.WidthFixed)\n        imgui.TableHeadersRow()\n\n        for _, tag in ipairs(tags) do\n            imgui.PushID(tag)\n\n            imgui.TableNextColumn()\n            imgui.Text(tag)\n\n            imgui.TableNextColumn()\n            if imgui.SmallButton(\"-\") then\n                remove(tag)\n            end\n\n            imgui.PopID()\n        end\n\n        imgui.EndTable()\n    end\nend\n\nreturn tags_gui\n"
_TWWE_VFS["mods/component-explorer/translations.lua"] = "---@module 'component-explorer.utils.tcsv'\nlocal tcsv = dofile_once(\"mods/component-explorer/utils/tcsv.lua\")\n\n---@module 'component-explorer.file_viewer'\nlocal file_viewer = dofile_once(\"mods/component-explorer/file_viewer.lua\")\n\n---@module 'component-explorer.style'\nlocal style = dofile_once(\"mods/component-explorer/style.lua\")\n\n---@module 'component-explorer.utils.strings'\nlocal string_util = dofile_once(\"mods/component-explorer/utils/strings.lua\")\n\nlocal ModTextFileGetContent = ModTextFileGetContent\n\nlocal translations = {}\ntranslations.open = false\n\nlocal function csv_report_table(csv, state)\n    if #csv.warnings > 0 then\n        imgui.PushStyleColor(imgui.Col.Text, unpack(style.colour_warn))\n        local show_warns = imgui.TreeNode(\"Warnings (\" .. #csv.warnings .. \")###csv_warnings\")\n        imgui.PopStyleColor()\n\n        if show_warns then\n            for _, warning in ipairs(csv.warnings) do\n                imgui.BulletText(warning)\n            end\n            imgui.TreePop()\n        end\n        imgui.Separator()\n    end\n\n    if imgui.TreeNode(\"Usage help\") then\n        imgui.TextWrapped(table.concat({\n            \"If you're viewing a file with many languages (i.e. common.csv),\" ..\n            \" you'll probably want to resize this window to be really large.\",\n            \"Right click the table to hide and unhide languages.\"\n        }, \"\\n\"))\n        imgui.TreePop()\n    end\n\n    state.search = state.search or \"\"\n    local search_changed\n    search_changed, state.search = imgui.InputText(\"Search\", state.search)\n\n    if search_changed then\n        state.refresh_filter = true\n    end\n\n    local flags = bit.bor(\n        imgui.TableFlags.Resizable,\n        imgui.TableFlags.Hideable,\n        imgui.TableFlags.Borders,\n        imgui.TableFlags.ContextMenuInBody,\n        imgui.TableFlags.RowBg\n    )\n\n    if imgui.BeginTable(\"##direct_input_csv\", #csv.langs + 1, flags) then\n        -- Header row\n        imgui.TableSetupColumn(\"Key\", imgui.TableColumnFlags.NoHide)\n        for _, lang in ipairs(csv.langs) do\n            imgui.TableSetupColumn(lang)\n        end\n        imgui.TableHeadersRow()\n\n        -- Search\n        local enabled_columns = {1}\n        local enabled_columns_str_arr = {}\n        for lang_idx=1,#csv.langs do\n            local column_flags = imgui.TableGetColumnFlags(lang_idx)\n            if bit.band(column_flags, imgui.TableColumnFlags.IsEnabled) ~= 0 then\n                enabled_columns[#enabled_columns+1] = lang_idx + 1\n                enabled_columns_str_arr[#enabled_columns_str_arr+1] = \"\" .. lang_idx\n            end\n        end\n\n        local enabled_columns_cache_key = table.concat(enabled_columns_str_arr, \"|\")\n        if state.enabled_columns_cache_key ~= enabled_columns_cache_key then\n            state.enabled_columns_cache_key = enabled_columns_cache_key\n            state.refresh_filter = true\n        end\n\n        if state.refresh_filter == true or state.refresh_filter == nil then\n            state.refresh_filter = false\n\n            local filtered_rows\n            if state.search == \"\" then\n                filtered_rows = csv.rows\n            else\n                filtered_rows = {}\n                for _, row in ipairs(csv.rows) do\n                    for _, col in ipairs(enabled_columns) do\n                        if string_util.ifind(row[col], state.search, 1, true) then\n                            table.insert(filtered_rows, row)\n                            goto next_row\n                        end\n                    end\n\n                    ::next_row::\n                end\n            end\n\n            state.filtered_rows = filtered_rows\n        end\n\n        -- Table body\n        local clipper = imgui.ListClipper.new()\n        clipper:Begin(#state.filtered_rows)\n        while clipper:Step() do\n            for i=clipper.DisplayStart,clipper.DisplayEnd - 1 do\n                row = state.filtered_rows[i + 1]\n                for _, val in ipairs(row) do\n                    imgui.TableNextColumn()\n\n                    -- Replace newlines because ListClipper only works if all\n                    -- lines are the same height.\n                    imgui.Text(val:gsub(\"\\n\", \"\\\\n\"))\n\n                    if imgui.IsItemHovered() then\n                        if imgui.BeginTooltip() ~= false then\n                            imgui.Text(val)\n                            imgui.EndTooltip()\n                        end\n                    end\n                end\n            end\n        end\n\n        imgui.EndTable()\n    end\nend\n\nlocal common_csv = nil\nlocal common_csv_state = {}\n\nlocal function show_common_csv()\n    local path = \"data/translations/common.csv\"\n\n    imgui.Text(\"File viewer: \" .. path)\n    imgui.SameLine()\n    file_viewer.small_open_button(path)\n\n    if common_csv == nil then\n        common_csv = tcsv.parse(ModTextFileGetContent(path), path, false)\n    end\n    csv_report_table(common_csv, common_csv_state)\nend\n\nlocal di_state = {}\nlocal di_text = \"\"\nlocal di_csv = nil\nlocal di_trans_mod = false\n\nlocal function show_direct_input()\n    local input_changed\n    input_changed, di_text = imgui.InputTextMultiline(\"Input\", di_text, 0, imgui.GetTextLineHeight() * 6)\n\n    local trans_mod_changed\n    trans_mod_changed, di_trans_mod = imgui.Checkbox(\"Parse as translation mod\", di_trans_mod)\n\n    if input_changed or trans_mod_changed then\n        di_state.refresh_filter = true\n    end\n\n    if di_csv == nil or input_changed or trans_mod_changed then\n        di_csv = tcsv.parse(di_text, \"direct_input.xml\", di_trans_mod)\n    end\n\n    imgui.Separator()\n    csv_report_table(di_csv, di_state)\nend\n\nlocal fi_state = {}\nlocal fi_path = \"\"\nlocal fi_csv = nil\nlocal fi_trans_mod = false\n\nlocal function show_file_input()\n    local path_changed\n    path_changed, fi_path = imgui.InputText(\"Path\", fi_path)\n\n    imgui.SameLine()\n    local refresh = imgui.Button(\"Refresh\")\n\n    local trans_mod_changed\n    trans_mod_changed, fi_trans_mod = imgui.Checkbox(\"Parse as translation mod\", fi_trans_mod)\n\n    local valid_path = string_util.ifind(fi_path, \".csv$\")\n\n    if not valid_path then\n        fi_csv = nil\n    end\n\n    if valid_path and (path_changed or trans_mod_changed or refresh) then\n        fi_csv = nil\n        fi_state.refresh_filter = true\n\n        local content = ModTextFileGetContent(fi_path)\n        if content then\n            fi_csv = tcsv.parse(content, \"direct_input.xml\", fi_trans_mod)\n        end\n    end\n\n    imgui.Separator()\n    imgui.Text(\"File viewer: \" .. fi_path)\n    imgui.SameLine()\n    file_viewer.small_open_button(fi_path)\n\n    imgui.Separator()\n    if fi_csv then\n        csv_report_table(fi_csv, fi_state)\n    end\nend\n\nfunction translations.show()\n    imgui.SetNextWindowSize(480, 200, imgui.Cond.FirstUseEver)\n\n    local should_show\n    should_show, translations.open = imgui.Begin(\"Translations\", translations.open)\n\n    if not should_show then\n        return\n    end\n\n    if imgui.BeginTabBar(\"##translationtabs\") then\n        if imgui.BeginTabItem(\"common.csv\") then\n            if imgui.BeginChild(\"##common_csv\") then\n                show_common_csv()\n                imgui.EndChild()\n            end\n            imgui.EndTabItem()\n        end\n\n        if imgui.BeginTabItem(\"File path\") then\n            if imgui.BeginChild(\"##file_path\") then\n                show_file_input()\n                imgui.EndChild()\n            end\n            imgui.EndTabItem()\n        end\n\n        if imgui.BeginTabItem(\"Direct input\") then\n            if imgui.BeginChild(\"##direct_input\") then\n                show_direct_input()\n\n                imgui.EndChild()\n            end\n\n            imgui.EndTabItem()\n        end\n\n        imgui.EndTabBar()\n    end\n\n    imgui.End()\nend\n\nreturn translations\n"
_TWWE_VFS["mods/component-explorer/ui/combo.lua"] = "local ui_combo = {}\n\n---Combo list with an --All-- option that corresponds to nil.\n---@param label string\n---@param list string[]\n---@param value string?\n---@param default_name string?\n---@return boolean\n---@return string?\nfunction ui_combo.optional(label, list, value, default_name)\n    default_name = default_name or \"--All--\"\n    local changed = false\n    if imgui.BeginCombo(label, value or default_name) then\n        if imgui.Selectable(default_name, value == nil) then\n            changed = true\n            value = nil\n        end\n\n        for _, item in ipairs(list) do\n            if imgui.Selectable(item, value == item) then\n                changed = true\n                value = item\n            end\n        end\n        imgui.EndCombo()\n    end\n\n    return changed, value\nend\n\nreturn ui_combo\n"
_TWWE_VFS["mods/component-explorer/ui/help.lua"] = "local help = {}\n\n---@param desc string\nfunction help.tooltip(desc)\n    if imgui.IsItemHovered() then\n        if imgui.BeginTooltip() ~= false then\n            imgui.PushTextWrapPos(400)\n            imgui.Text(desc)\n            imgui.PopTextWrapPos()\n            imgui.EndTooltip()\n        end\n    end\nend\n\n---@param desc string\nfunction help.exclam_marker(desc)\n    imgui.TextDisabled(\"(!)\")\n    help.tooltip(desc)\nend\n\n---@param desc string\nfunction help.marker(desc)\n    imgui.TextDisabled(\"(?)\")\n    help.tooltip(desc)\nend\n\nreturn help\n"
_TWWE_VFS["mods/component-explorer/ui/helpers.lua"] = "local helpers = {}\n\nfunction helpers.window_appear_center()\n    local w, h = imgui.GetMainViewportSize()\n    imgui.SetNextWindowPos(w / 2, h / 2, imgui.Cond.Appearing, 0.5, 0.5)\nend\n\nreturn helpers\n"
_TWWE_VFS["mods/component-explorer/ui/im.lua"] = "local im = {}\n\n---@type Window?\nlocal _curr_window\n\n---@return Window?\nfunction im.CurrentWindow()\n    return _curr_window\nend\n\n---@class OpenData\n---@field pos number[]?\n---@field size number[]?\n---@field dock_id integer?\n\n---@class Window\n---@field id string\n---@field open boolean\n---@field flags WindowFlags\n---@field open_data OpenData?\n\n---@param id string\n---@param open boolean\n---@param flags WindowFlags?\n---@param open_data OpenData?\n---@return Window\nfunction im.Window(id, open, flags, open_data)\n    return {\n        id=id,\n        open=open or false,\n        flags=flags or 0,\n        open_data=open_data,\n    }\nend\n\n---@param window Window\n---@param name string?\n---@param flags WindowFlags?\n---@return boolean should_show\nfunction im.Begin(window, name, flags)\n    if window.open == false then\n        return false\n    end\n\n    local od = window.open_data\n    if od then\n        window.open_data = nil\n        if od.pos then imgui.SetNextWindowPos(unpack(od.pos)) end\n        if od.size then imgui.SetNextWindowSize(unpack(od.size)) end\n        if od.dock_id then imgui.SetNextWindowDockID(od.dock_id) end\n    else\n        imgui.SetNextWindowSize(600, 400, imgui.Cond.FirstUseEver)\n    end\n\n    flags = bit.bor(flags or 0, window.flags)\n    name = (name or \"\") .. window.id\n\n    local should_show\n    should_show, window.open = imgui.Begin(name, window.open, flags)\n\n    if should_show then\n        _curr_window = window\n    end\n\n    return should_show\nend\n\n---@param window Window\nfunction im.End(window)\n    if _curr_window == window then\n        _curr_window = nil\n    end\n\n    imgui.End()\nend\n\n---@return OpenData\nfunction im.GetOpenData()\n    local open_data = {}\n\n    local curr_window = im.CurrentWindow()\n\n    if imgui.IsKeyDown(imgui.Key.LeftCtrl) then\n        if curr_window then\n            curr_window.open = false\n            if imgui.GetWindowDockID then\n                local dock_id = imgui.GetWindowDockID()\n                if dock_id ~= 0 then\n                    open_data.dock_id = dock_id\n                end\n            end\n        end\n\n        if not open_data.dock_id then\n            open_data.pos = {imgui.GetWindowPos()}\n            open_data.size = {imgui.GetWindowSize()}\n        end\n    elseif imgui.IsKeyDown(imgui.Key.LeftShift) then\n        local dock_id = 0\n        if imgui.GetWindowDockID then\n            dock_id = imgui.GetWindowDockID()\n            if dock_id == 0 and curr_window and imgui.DockBuilderAddNode then\n                dock_id = imgui.DockBuilderAddNode()\n                imgui.DockBuilderSetNodePos(dock_id, imgui.GetWindowPos())\n                imgui.DockBuilderSetNodeSize(dock_id, imgui.GetWindowSize())\n                imgui.DockBuilderDockWindow(curr_window.id, dock_id)\n                imgui.DockBuilderFinish(dock_id)\n            end\n        end\n\n        if dock_id ~= 0 then\n            open_data.dock_id = dock_id\n        else\n            open_data.pos = {imgui.GetWindowPos()}\n            open_data.size = {imgui.GetWindowSize()}\n        end\n    end\n\n    return open_data\nend\n\nreturn im\n"
_TWWE_VFS["mods/component-explorer/ui/link.lua"] = "local link = {}\n\nlink.open_link = nil\n\nfunction link.button(label, url)\n    imgui.Text(label .. \": \" .. url)\n    imgui.SameLine()\n    if imgui.SmallButton(\"Copy\") then\n        imgui.SetClipboardText(url)\n    end\n\n    if link.open_link then\n        imgui.SameLine()\n        if imgui.SmallButton(\"Open\") then\n            link.open_link(url)\n        end\n    end\nend\n\nfunction link.text_link(fallback_label, url, link_label)\n    if imgui.TextLinkOpenURL then\n        if link_label then\n            imgui.TextLinkOpenURL(link_label, url)\n        else\n            imgui.TextLinkOpenURL(url)\n        end\n    else\n        link.button(fallback_label, url)\n    end\nend\n\nfunction link.menu_item(label, extra, url)\n    if imgui.MenuItem(label, extra) then\n        if link.open_link then\n            link.open_link(url)\n        else\n            imgui.SetClipboardText(url)\n        end\n    end\nend\n\nreturn link\n"
_TWWE_VFS["mods/component-explorer/unique_wand_sprites.lua"] = "-- Global so mods can append to this if they want to.\nunique_wand_sprites = {\n    {\n        tip_x = 10,\n        tip_y = -0.5,\n        offset_x = 1,\n        offset_y = 3.5,\n        sprite_file = \"data/items_gfx/flute.xml\",\n        image_file = \"data/items_gfx/flute.png\",\n        wiki_file = \"Huilu (Wand).png\",\n    },\n    {\n        tip_x = 10,\n        tip_y = -0.5,\n        offset_x = 1,\n        offset_y = 3.5,\n        sprite_file = \"data/items_gfx/kantele.xml\",\n        image_file = \"data/items_gfx/kantele.png\",\n        wiki_file = \"Wand kantele.png\",\n    },\n    {\n        tip_x = 6,\n        tip_y = -0.5,\n        offset_x = 0,\n        offset_y = 0,\n        sprite_file = \"data/items_gfx/bomb_wand.xml\",\n        image_file = \"data/items_gfx/bomb_wand.png\",\n        wiki_file = \"Wand bomb wand.png\",\n    },\n    {\n        tip_x = 8,\n        tip_y = 0.5,\n        offset_x = 0,\n        offset_y = 0,\n        sprite_file = \"data/items_gfx/handgun.xml\",\n        image_file = \"data/items_gfx/handgun.png\",\n        wiki_file = \"Wand handgun.png\",\n    },\n    {\n        tip_x = 17,\n        tip_y = -0.5,\n        offset_x = 0,\n        offset_y = 0,\n        sprite_file = \"data/items_gfx/wands/custom/scepter_01.xml\",\n        image_file = \"data/items_gfx/wands/custom/scepter_01.png\",\n        wiki_file = \"Wand scepter 01.png\",\n    },\n    {\n        tip_x = 9,\n        tip_y = -0.5,\n        offset_x = 0,\n        offset_y = 0,\n        sprite_file = \"data/entities/items/wands/experimental/experimental_wand_1_sprite.xml\",\n        image_file = \"data/entities/items/wands/experimental/experimental_wand_1.png\",\n        wiki_file = \"Wand experimental wand 1.png\",\n    },\n    {\n        tip_x = 12,\n        tip_y = -0.5,\n        offset_x = 0,\n        offset_y = 0,\n        sprite_file = \"data/entities/items/wands/experimental/experimental_wand_2_sprite.xml\",\n        image_file = \"data/entities/items/wands/experimental/experimental_wand_2.png\",\n        wiki_file = \"Wand experimental wand 2.png\",\n    },\n    {\n        tip_x = 15,\n        tip_y = 1,\n        offset_x = 0,\n        offset_y = 0,\n        sprite_file = \"data/items_gfx/wands/custom/actual_wand.xml\",\n        image_file = \"data/items_gfx/wands/custom/actual_wand_honest.png\",\n        wiki_file = \"Actual wand honest.png\",\n    },\n    {\n        tip_x = 15,\n        tip_y = -0.5,\n        offset_x = 0,\n        offset_y = 0,\n        sprite_file = \"data/items_gfx/wands/custom/good_01.xml\",\n        image_file = \"data/items_gfx/wands/custom/good_01.png\",\n        wiki_file = \"Wand wand good 1.png\",\n    },\n    {\n        tip_x = 15,\n        tip_y = -0.5,\n        offset_x = 0,\n        offset_y = 0,\n        sprite_file = \"data/items_gfx/wands/custom/good_02.xml\",\n        image_file = \"data/items_gfx/wands/custom/good_02.png\",\n        wiki_file = \"Wand wand good 2.png\",\n    },\n    {\n        tip_x = 15,\n        tip_y = -0.5,\n        offset_x = 0,\n        offset_y = 0,\n        sprite_file = \"data/items_gfx/wands/custom/good_03.xml\",\n        image_file = \"data/items_gfx/wands/custom/good_03.png\",\n        wiki_file = \"Wand wand good 3.png\",\n    },\n    {\n        tip_x = 21,\n        tip_y = 0,\n        offset_x = 3,\n        offset_y = 5,\n        image_file = \"data/items_gfx/wands/custom/skull_01.png\",\n        wiki_file = \"Wand skull 01.png\",\n    },\n    {\n        tip_x = 14,\n        tip_y = 0,\n        offset_x = 3,\n        offset_y = 3,\n        image_file = \"data/items_gfx/wands/custom/wood_01.png\",\n        wiki_file = \"Wand wood 01.png\",\n    },\n    {\n        tip_x = 16,\n        tip_y = 0,\n        offset_x = 3,\n        offset_y = 5,\n        image_file = \"data/items_gfx/wands/custom/plant_01.png\",\n        wiki_file = \"Wand plant 01.png\",\n    },\n    {\n        tip_x = 22,\n        tip_y = 0,\n        offset_x = 3,\n        offset_y = 5,\n        image_file = \"data/items_gfx/wands/custom/plant_02.png\",\n        wiki_file = \"Wand plant 02.png\",\n    },\n    {\n        tip_x = 18,\n        tip_y = 0,\n        offset_x = 3,\n        offset_y = 6.5,\n        image_file = \"data/items_gfx/wands/custom/vasta.png\",\n        wiki_file = \"Wand vasta.png\",\n    },\n    {\n        tip_x = 17,\n        tip_y = 0,\n        offset_x = 3,\n        offset_y = 6.5,\n        image_file = \"data/items_gfx/wands/custom/vihta.png\",\n        wiki_file = \"Wand vihta.png\",\n    },\n}\n"
_TWWE_VFS["mods/component-explorer/unsafe/appends/globals.lua"] = "local ffi = require(\"ffi\")\n\n---@module 'component-explorer.unsafe.stl'\nlocal stl = dofile_once(\"mods/component-explorer/unsafe/stl.lua\")\n\n---@module 'component-explorer.unsafe.o_world_state'\nlocal ws = dofile_once(\"mods/component-explorer/unsafe/o_world_state.lua\")\n\n---@module 'component-explorer.style'\nlocal style = dofile_once(\"mods/component-explorer/style.lua\")\n\n---@module 'component-explorer.globals'\nlocal globals = dofile_once(\"mods/component-explorer/globals.lua\")\n\nif not ws.world_state or not ws.world_state_lua_globals then\n    return\nend\n\n\nlocal orig_extra = globals.extra\nglobals.extra = function(...)\n    orig_extra(...)\n\n    if style.danger_button(\"Scan existing\") then\n        local all_globals = stl.map_string_keys(\n            ffi.cast(\"std_map*\", ws.world_state[0] + ws.world_state_lua_globals)\n        )\n\n        for _, global in ipairs(all_globals) do\n            if not globals.is_watching(global) then\n                globals.watch(global)\n            end\n        end\n    end\nend\n"
_TWWE_VFS["mods/component-explorer/unsafe/appends/link.lua"] = "---@module 'component-explorer.ui.link'\nlocal link = dofile_once(\"mods/component-explorer/ui/link.lua\")\n\n---@module 'component-explorer.unsafe.win32'\nlocal win32 = dofile_once(\"mods/component-explorer/unsafe/win32.lua\")\n\nlink.open_link = function(url)\n    win32.open(url)\nend\n"
_TWWE_VFS["mods/component-explorer/unsafe/appends/lua_console.lua"] = "---@module 'component-explorer.lua_console'\nlocal lua_console = dofile_once(\"mods/component-explorer/lua_console.lua\")\n\n---@module 'component-explorer.user_scripts'\nlocal us = dofile_once(\"mods/component-explorer/user_scripts.lua\")\n\n---@module 'component-explorer.utils.ce_settings'\nlocal ce_settings = dofile_once(\"mods/component-explorer/utils/ce_settings.lua\")\n\n---@module 'component-explorer.unsafe.win32'\nlocal win32 = dofile_once(\"mods/component-explorer/unsafe/win32.lua\")\n\nlocal _menu_bar = lua_console.Console.draw_menu_bar_items\nfunction lua_console.Console:draw_menu_bar_items()\n    _menu_bar(self)\n\n    local user_scripts_open = ce_settings.get(\"window_open_user_scripts\") --[[@as boolean]]\n\n    if imgui.BeginMenu(\"User Scripts\") then\n        if imgui.MenuItem(\"Show\", \"\", user_scripts_open) then\n            user_scripts_open = not user_scripts_open\n            ce_settings.set(\"window_open_user_scripts\", user_scripts_open)\n        end\n\n        if imgui.MenuItem(\"Open script folder\") then\n            win32.explore(us.directory_path)\n        end\n\n        imgui.EndMenu()\n    end\nend\n"
_TWWE_VFS["mods/component-explorer/unsafe/appends/main.lua"] = "---@module 'component-explorer.utils.ce_settings'\nlocal ce_settings = dofile_once(\"mods/component-explorer/utils/ce_settings.lua\")\n\n---@module 'component-explorer.unsafe.logger'\nlocal logger = dofile_once(\"mods/component-explorer/unsafe/logger.lua\")\n\ndofile_once(\"mods/component-explorer/unsafe/noita_version.lua\")\n\n---@module 'component-explorer.unsafe.user_scripts_window'\nlocal uswindow = dofile_once(\"mods/component-explorer/unsafe/user_scripts_window.lua\")\n\n---@module 'component-explorer.user_scripts'\nlocal us = dofile_once(\"mods/component-explorer/user_scripts.lua\")\n\n\nlocal magic_numbers = nil\nlocal debug = nil\n\nif is_steam_version() then\n    ---@module 'component-explorer.unsafe.magic_numbers'\n    magic_numbers = dofile_once(\"mods/component-explorer/unsafe/magic_numbers.lua\")\n\n    ---@module 'component-explorer.unsafe.debug'\n    debug = dofile_once(\"mods/component-explorer/unsafe/debug.lua\")\nend\n\n\nlocal _show_view_menu_items = show_view_menu_items\nfunction show_view_menu_items()\n    _show_view_menu_items()\n\n    imgui.Separator()\n\n    local _\n    _, logger.window_open  = imgui.MenuItem(\"Logs Window\", sct(\"U\"), logger.window_open)\n    _, logger.overlay_open = imgui.MenuItem(\"Logs Overlay\", sct(\"O\"), logger.overlay_open)\n\n    if is_steam_version() then\n        imgui.Separator()\n\n        if magic_numbers then\n            _, magic_numbers.open = imgui.MenuItem(\"Magic Numbers\", sct(\"M\"), magic_numbers.open)\n        end\n\n        if debug then\n            _, debug.open = imgui.MenuItem(\"Debug\", sct(\"D\"), debug.open)\n        end\n    end\nend\n\nlocal _keyboard_shortcut_items = keyboard_shortcut_items\nfunction keyboard_shortcut_items()\n    _keyboard_shortcut_items()\n\n    if imgui.IsKeyPressed(imgui.Key.U, false) then\n        logger.window_open = not logger.window_open\n    end\n\n    if imgui.IsKeyPressed(imgui.Key.O, false) then\n        logger.overlay_open = not logger.overlay_open\n    end\n\n    if magic_numbers then\n        if imgui.IsKeyPressed(imgui.Key.M, false) then\n            magic_numbers.open = not magic_numbers.open\n        end\n    end\n\n    if debug then\n        if imgui.IsKeyPressed(imgui.Key.D, false) then\n            debug.open = not debug.open\n        end\n    end\nend\n\nlocal _update_ui = update_ui\nfunction update_ui(paused, current_frame_run)\n    _update_ui(paused, current_frame_run)\n\n    if logger.window_open then\n        logger.show_window()\n    end\n\n    if logger.overlay_open then\n        logger.show_overlay()\n    end\n\n    if console.open and ce_settings.get(\"window_open_user_scripts\") then\n        uswindow.draw_user_scripts_window(console)\n    end\n\n    if magic_numbers and magic_numbers.open then\n        magic_numbers.show()\n    end\n\n    if debug and debug.open then\n        debug.show()\n    end\nend\n"
_TWWE_VFS["mods/component-explorer/unsafe/appends/user_scripts.lua"] = "local us = dofile_once(\"mods/component-explorer/user_scripts.lua\")\n\nlocal function read_all(file)\n    local f = assert(io.open(file, \"rb\"))\n    local content = f:read(\"*all\")\n    f:close()\n    return content\nend\n\nfunction us.user_script(script_name)\n    local path = us.make_path(script_name)\n    local f, err = loadstring(read_all(path), path)\n    if not f then\n        error(err, 0)\n    end\n\n    return f()\nend\n\nfunction us.exists(script_name)\n    local path = us.make_path(script_name)\n    local handle = io.open(path, \"rb\")\n    if not handle then\n        return false\n    end\n\n    handle:close()\n    return true\nend\n"
_TWWE_VFS["mods/component-explorer/unsafe/debug.lua"] = "dofile_once(\"mods/component-explorer/unsafe/memory_type.lua\")\n\n---@module 'component-explorer.unsafe.memory_display'\nlocal memory_display = dofile_once(\"mods/component-explorer/unsafe/memory_display.lua\")\n\n---@module 'component-explorer.utils.strings'\nlocal string_util = dofile_once(\"mods/component-explorer/utils/strings.lua\")\n\nlocal debug = {}\n\nlocal debug_base = 0x00e07e20\nlocal petri_base = 0x00e077a0\nlocal olli_base = 0x00e07814\n\nlocal debug_categories = {\n    {\n        name = \"Debug\",\n        items = {\n            {\n                name = \"mDrawPathFindingGrid\",\n                type = CE_MemoryType.bool_,\n                addr = debug_base + 4,\n            },\n            {\n                name = \"DEBUG_RAGDOLL_EXTRA_FORCE\",\n                type = CE_MemoryType.float_,\n                addr = debug_base + 8,\n            },\n            {\n                name = \"mRenderPathFinding\",\n                type = CE_MemoryType.bool_,\n                addr = debug_base + 0xc,\n            },\n            {\n                name = \"mPauseSimulation\",\n                type = CE_MemoryType.bool_,\n                addr = debug_base + 0xd,\n            },\n            {\n                name = \"mPauseSomeSimulation\",\n                type = CE_MemoryType.bool_,\n                addr = debug_base + 0xe,\n            },\n            {\n                name = \"mCameraFreeIsSmoothed\",\n                type = CE_MemoryType.bool_,\n                addr = debug_base + 0xf,\n            },\n            {\n                name = \"mCameraIsLockedInGameplay\",\n                type = CE_MemoryType.bool_,\n                addr = debug_base + 0x10,\n            },\n            {\n                name = \"camera_light\",\n                type = CE_MemoryType.bool_,\n                addr = debug_base + 0x11,\n            },\n            {\n                name = \"mAllowCameraMoveWhenLocked\",\n                type = CE_MemoryType.bool_,\n                addr = debug_base + 0x12,\n            },\n            {\n                name = \"mCameraDisableCameraShake\",\n                type = CE_MemoryType.bool_,\n                addr = debug_base + 0x13,\n            },\n            {\n                name = \"mCameraTargetOffsetY\",\n                type = CE_MemoryType.float_,\n                addr = debug_base + 0x14,\n            },\n            {\n                name = \"mCameraTargetOffsetX\",\n                type = CE_MemoryType.float_,\n                addr = debug_base + 0x18,\n            },\n            {\n                name = \"mPostFxDisabled\",\n                type = CE_MemoryType.bool_,\n                addr = debug_base + 0x1c,\n            },\n            {\n                name = \"mGuiDisabled\",\n                type = CE_MemoryType.bool_,\n                addr = debug_base + 0x1d,\n            },\n            {\n                name = \"mGuiHalfSize\",\n                type = CE_MemoryType.bool_,\n                addr = debug_base + 0x1e,\n            },\n            {\n                name = \"mFogOfWarOpenEverywhere\",\n                type = CE_MemoryType.bool_,\n                addr = debug_base + 0x1f,\n            },\n            {\n                name = \"mTrailerMode\",\n                type = CE_MemoryType.bool_,\n                addr = debug_base + 0x20,\n            },\n            {\n                name = \"mDayTimeRotationPaused\",\n                type = CE_MemoryType.bool_,\n                addr = debug_base + 0x21,\n            },\n            {\n                name = \"mPlayerNeverDies\",\n                type = CE_MemoryType.bool_,\n                addr = debug_base + 0x22,\n            },\n            {\n                name = \"mFreezeAI\",\n                type = CE_MemoryType.bool_,\n                addr = debug_base + 0x23,\n            },\n            {\n                name = \"mGameAudioVisualizatio