_TWWE_VFS["mods/component-explorer/unsafe/magic_numbers.lua"] = "---@module 'component-explorer.utils.strings'\nlocal string_util = dofile_once(\"mods/component-explorer/utils/strings.lua\")\n\n---@module 'component-explorer.unsafe.memory_display'\nlocal memory_display = dofile_once(\"mods/component-explorer/unsafe/memory_display.lua\")\n\ndofile_once(\"mods/component-explorer/unsafe/memory_type.lua\")\ndofile_once(\"mods/component-explorer/unsafe/magic_number_items.lua\")\n\nmagic_numbers = {}\n\nlocal search = \"\"\n\nlocal function show_magic_items()\n    for _, item in ipairs(developer_items) do\n        if string_util.ifind(item.name, search, 1, true) then\n            memory_display.show_item(item)\n        end\n    end\nend\n\nmagic_numbers.open = false\n\nfunction magic_numbers.show()\n    local should_show\n    should_show, magic_numbers.open = imgui.Begin(\"Magic Numbers\", magic_numbers.open)\n\n    if should_show then\n        local _\n        _, search = imgui.InputText(\"Search\", search)\n        imgui.Separator()\n\n        if imgui.BeginChild(\"magicinputs\") then\n            show_magic_items()\n            imgui.EndChild()\n        end\n        imgui.End()\n    end\nend\n\nreturn magic_numbers\n"
_TWWE_VFS["mods/component-explorer/unsafe/memory_display.lua"] = "local ffi = require(\"ffi\")\n\n---@module 'component-explorer.unsafe.win32'\nlocal win32 = dofile_once(\"mods/component-explorer/unsafe/win32.lua\")\n\nlocal base = win32.get_base_address()\n\nlocal memory_display = {}\n\nfunction memory_display.show_item(item)\n    if item.addr == nil then\n        print(\"item.addr must not be nil.\")\n        return\n    end\n\n    local address = base + item.addr\n\n    local location = nil\n\n    if item.type == CE_MemoryType.bool_ then\n        location = ffi.cast(\"bool*\", address)\n    elseif item.type == CE_MemoryType.uint32_t then\n        location = ffi.cast(\"uint32_t*\", address)\n    elseif item.type == CE_MemoryType.uint8_t then\n        location = ffi.cast(\"uint8_t*\", address)\n    elseif item.type == CE_MemoryType.int8_t then\n        location = ffi.cast(\"int8_t*\", address)\n    elseif item.type == CE_MemoryType.int_ then\n        location = ffi.cast(\"int*\", address)\n    elseif item.type == CE_MemoryType.float_ then\n        location = ffi.cast(\"float*\", address)\n    elseif item.type == CE_MemoryType.double_ then\n        location = ffi.cast(\"double*\", address)\n    end\n\n    if location == nil then\n        -- Unsuported type\n        return\n    end\n\n    local value = location[0]\n    local changed\n\n    if item.type == CE_MemoryType.bool_ then\n        imgui.SetNextItemWidth(180)\n        changed, value = imgui.Checkbox(item.name, value)\n    elseif\n        item.type == CE_MemoryType.int_ or\n        item.type == CE_MemoryType.uint32_t or\n        item.type == CE_MemoryType.uint8_t or\n        item.type == CE_MemoryType.int8_t\n    then\n        imgui.SetNextItemWidth(180)\n        changed, value = imgui.InputInt(item.name, value)\n    elseif item.type == CE_MemoryType.float_ then\n        imgui.SetNextItemWidth(180)\n        changed, value = imgui.InputFloat(item.name, value)\n    elseif item.type == CE_MemoryType.double_ then\n        imgui.SetNextItemWidth(180)\n        changed, value = imgui.InputFloat(item.name, value)\n    end\n\n    if changed then\n        location[0] = value\n    end\n\nend\n\nreturn memory_display\n"
_TWWE_VFS["mods/component-explorer/unsafe/memory_type.lua"] = "local ffi = require(\"ffi\")\n\nffi.cdef([[\n\nstruct CE_MemoryType {\n    static const int bool_ = 1;\n    static const int int_ = 2;\n    static const int uint32_t = 3;\n    static const int float_ = 4;\n    static const int double_ = 5;\n    static const int std_string = 6;\n    static const int int8_t = 7;\n    static const int uint8_t = 8;\n};\n\n]])\n\nCE_MemoryType = ffi.new(\"struct CE_MemoryType\")\n"
_TWWE_VFS["mods/component-explorer/unsafe/noita_version.lua"] = "local win32 = dofile_once(\"mods/component-explorer/unsafe/win32.lua\")\n\n-- These are offsets in the exe, not the addresses as they are loaded in memory.\n-- Sometimes multiple versions of the game are compatible but have different\n-- version strings.\nlocal steam_identifier_sets = {\n    {\n        {\n            location = 0x00be7498,\n            string = \"Noita-Build-Jan 25 2025-12:40:28\",\n        },\n        {\n            location = 0x00d50d2a,\n            string = \"steam_api.dll\",\n        },\n    },\n    {\n        {\n            location = 0x00be7498,\n            string = \"Noita-Build-Jan 25 2025-15:55:41\",\n        },\n        {\n            location = 0x00d50d2a,\n            string = \"steam_api.dll\",\n        },\n    },\n}\n\nfunction check_identifiers(fh, identifiers)\n    local success, result = pcall(function()\n        for _, identifier in ipairs(identifiers) do\n            fh:seek(\"set\", identifier.location)\n            if fh:read(#identifier.string) ~= identifier.string then\n                return false\n            end\n        end\n        return true\n    end)\n\n    if success then\n        return result\n    else\n        print(\"Error checking version: \" .. result)\n        return false\n    end\nend\n\nlocal steam_version = nil\nfunction is_steam_version()\n    if steam_version == nil then\n        -- Changed to true if checks succeed\n        steam_version = false\n\n        local nf = io.open(win32.get_exe_path(), \"rb\")\n        if not nf then\n            return false\n        end\n\n        for _, identifiers in ipairs(steam_identifier_sets) do\n            steam_version = check_identifiers(nf, identifiers)\n            if steam_version then break end\n        end\n        nf:close()\n    end\n\n    return steam_version\nend\n"
_TWWE_VFS["mods/component-explorer/unsafe/o_world_state.lua"] = "local ffi = require(\"ffi\")\nlocal ouroborous = dofile_once(\"mods/component-explorer/unsafe/ouroboros.lua\")\n\nlocal get_global_addr = ouroborous.func_c_address(GlobalsGetValue)\n\nlocal iter = ffi.cast(\"uint8_t*\", get_global_addr)\nfor _=1,1500 do\n    if  iter[0x0] == 0x8d and iter[0x1] == 0x4c and iter[0x2] == 0x24\n    and iter[0x4] == 0xe8\n    and iter[0x9] == 0x8b and iter[0xa] == 0x35\n    then\n        local rela_call = ffi.cast(\"int32_t*\", iter + 5)[0]\n        local next_instruction = iter + 0x9\n        iter = next_instruction + rela_call\n        goto stage2\n    end\n\n    iter = iter + 1\nend\n\nprint(\"Couldn't find next 'GlobalsGetValue' stage\")\ndo return {} end\n\n::stage2::\n\nlocal world_state\n\nfor _=1, 300 do\n    if  iter[0x0] == 0x8b and iter[0x1] == 0x1d\n    and iter[0x6] == 0x85 and iter[0x7] == 0xdb\n    and iter[0x8] == 0x74\n    then\n        world_state = ffi.cast(\"uint8_t***\", iter + 2)[0]\n        goto stage3\n    end\n\n    iter = iter + 1\nend\n\nprint(\"Couldn't find WorldStateComponent\")\ndo return {} end\n\n::stage3::\n\nlocal world_state_lua_globals\n\nfor _=1, 200 do\n    if  iter[0x0] == 0x8b and iter[0x1] == 0xf0\n    and iter[0x2] == 0x3b and iter[0x3] == 0xb3\n    and iter[0x8] == 0x74\n    then\n        world_state_lua_globals = ffi.cast(\"int32_t*\", iter + 4)[0]\n        goto stage4\n    end\n\n    iter = iter + 1\n\nend\n\nprint(\"Couldn't find WorldStateComponent.lua_globals offset\")\ndo return {} end\n\n::stage4::\n\nreturn {\n    world_state = world_state,\n    world_state_lua_globals = world_state_lua_globals,\n}\n"
_TWWE_VFS["mods/component-explorer/unsafe/ouroboros.lua"] = "local ffi = require(\"ffi\")\n\nlocal ouroborous = {}\n\nffi.cdef([[\n\nstruct lua_State;\ntypedef struct lua_State lua_State;\n\ntypedef int(*lua_CFunction)(lua_State*L);\n\ntypedef uint32_t GCRef;\ntypedef uint32_t MRef;\n\n#pragma pack(push,1)\n\nstruct GCHeader {\n    GCRef nextgc;\n    uint8_t marked;\n    uint8_t gct;\n};\n\nstruct GCfuncCommon {\n    uint8_t ffid;\n    uint8_t nupvalues;\n\n    GCRef env;\n    GCRef gclist;\n    MRef pc;\n};\n\ntypedef struct GCfuncC {\n    struct GCHeader header;\n    struct GCfuncCommon common;\n    lua_CFunction f;\n    // TValue upvalue[1];\n} GCfuncC;\n\ntypedef struct GCfuncL {\n    struct GCHeader header;\n    struct GCfuncCommon common;\n    GCRef uvptr[1];\n} GCfuncL;\n\ntypedef union GCfunc {\n    GCfuncC c;\n    GCfuncL l;\n} GCfunc;\n\n#pragma pack(pop)\n\n]])\n\nlocal FF = {\n    LUA = 0,\n    C = 1,\n}\n\n---@param obj any\n---@return integer\nlocal function get_pointer(obj)\n    return tonumber((\"%p\"):format(obj), 16)\nend\n\nfunction ouroborous.func_c_address(func)\n    local gcfunc = ffi.cast(\"GCfunc*\", get_pointer(func))\n    if gcfunc.c.common.ffid ~= FF.C then\n        return nil\n    end\n\n    return gcfunc.c.f\nend\n\nreturn ouroborous\n"
_TWWE_VFS["mods/component-explorer/unsafe/stl.lua"] = "local ffi = require(\"ffi\")\n\nlocal stl = {}\n\nffi.cdef([[\nstruct node_payload { void* align; };\n\ntypedef struct std_node {\n    struct std_node* left;\n    struct std_node* parent;\n    struct std_node* right;\n    uint8_t color;\n    uint8_t isnil;\n    struct node_payload payload;\n} std_node;\n\ntypedef struct std_map {\n    std_node* header;\n    size_t size;\n} std_map;\n\ntypedef struct ce_std_string {\n    union {\n        char* ptr;\n        char buf[16];\n    };\n    size_t size;\n    size_t capacity;\n} ce_std_string;\n]])\n\nlocal string_meta = {}\n\nfunction string_meta:__tostring()\n    if self.capacity > 0xf then\n        return ffi.string(self.ptr, self.size)\n    end\n    return ffi.string(ffi.cast(\"char*\", self), self.size)\nend\n\nstl.String = ffi.metatype(\"ce_std_string\", string_meta)\n\nlocal function get_nodes_string_keys(node, nil_node, result)\n    if node == nil_node then\n        return\n    end\n\n    local keyvalue = ffi.cast(\"ce_std_string*\", node.payload)\n    result[#result + 1] = tostring(keyvalue)\n\n    get_nodes_string_keys(node.left, nil_node, result)\n    get_nodes_string_keys(node.right, nil_node, result)\nend\n\n---Given a std::map<std::string, Any>, return all std::strings\n---@param map any\n---@return string[]\nfunction stl.map_string_keys(map)\n    local result = {}\n    get_nodes_string_keys(map.header.parent, map.header, result)\n    return result\nend\n\nreturn stl\n"
_TWWE_VFS["mods/component-explorer/unsafe/user_scripts.lua"] = "local win32 = dofile_once(\"mods/component-explorer/unsafe/win32.lua\")\nlocal us = dofile_once(\"mods/component-explorer/user_scripts.lua\")\n\nlocal us_unsafe = {}\n\nwin32.create_directory(us.directory_path)\n\nlocal SCRIPTS_TREE_FETCH_EVERY = 60 * 3\n\nlocal cached_scripts_tree = {}\nlocal scripts_tree_last_time_fetched = nil\n\nlocal function fetch_scripts_tree()\n    return win32.list_dir_contents(us.directory_path .. \"\\\\*.lua\")\nend\n\nfunction us_unsafe.get_scripts_tree()\n    local frame_num = GameGetFrameNum()\n    if\n        scripts_tree_last_time_fetched and\n        frame_num - scripts_tree_last_time_fetched < SCRIPTS_TREE_FETCH_EVERY\n    then\n        return cached_scripts_tree\n    end\n\n    scripts_tree_last_time_fetched = frame_num\n    cached_scripts_tree = fetch_scripts_tree()\n\n    return cached_scripts_tree\nend\n\nreturn us_unsafe\n"
_TWWE_VFS["mods/component-explorer/unsafe/user_scripts_window.lua"] = "---@module 'component-explorer.user_scripts'\nlocal us = dofile_once(\"mods/component-explorer/user_scripts.lua\")\n---@module 'component-explorer.unsafe.user_scripts'\nlocal us_unsafe = dofile_once(\"mods/component-explorer/unsafe/user_scripts.lua\")\n\n---@module 'component-explorer.utils.strings'\nlocal string_util = dofile_once(\"mods/component-explorer/utils/strings.lua\")\n\n---@module 'component-explorer.utils.ce_settings'\nlocal ce_settings = dofile_once(\"mods/component-explorer/utils/ce_settings.lua\")\n\n---@module 'component-explorer.repeat_scripts'\nlocal repeat_scripts = dofile_once(\"mods/component-explorer/repeat_scripts.lua\")\n\n\nlocal uswindow = {}\n\nlocal search = \"\"\n\n---@param console Console\nfunction uswindow.draw_user_scripts_window(console)\n    local should_show\n    local open = ce_settings.get(\"window_open_user_scripts\")\n    should_show, open = imgui.Begin(\"User Scripts\", open)\n    ce_settings.set(\"window_open_user_scripts\", open)\n\n    if not should_show then\n        return\n    end\n\n    local _\n    _, search = imgui.InputText(\"Search\", search)\n\n    local ret = nil\n\n    local files = us_unsafe.get_scripts_tree()\n    for _, file in ipairs(files) do\n        if\n            not us.is_hidden(file) and\n            string_util.ifind(file, search, 1, true)\n        then\n            if imgui.Button(file) then\n                console:run_command_text(us.user_script_call_string(file))\n                console:scroll_to_bottom()\n            end\n\n            if imgui.BeginPopupContextItem() then\n                local run_every = repeat_scripts.show_run_options()\n                if run_every then\n                    console:add_repeat_script(us.user_script_call_string(file), run_every)\n                end\n                imgui.EndPopup()\n            end\n        end\n    end\n\n    imgui.End()\n\n    return ret\nend\n\nreturn uswindow\n"
