redAccess,\n  /* in */           DWORD                 dwShareMode,\n  /* in, optional */ LPSECURITY_ATTRIBUTES lpSecurityAttributes,\n  /* in */           DWORD                 dwCreationDisposition,\n  /* in */           DWORD                 dwFlagsAndAttributes,\n  /* in, optional */ HANDLE                hTemplateFile\n);\n\nstruct DESIRED_ACCESS {\n    static const DWORD GENERIC_READ    = 0x80000000;\n    static const DWORD GENERIC_WRITE   = 0x40000000;\n    static const DWORD GENERIC_EXECUTE = 0x20000000;\n    static const DWORD GENERIC_ALL     = 0x10000000;\n};\n\nstruct SHARE_MODE {\n    static const DWORD FILE_SHARE_READ   = 0x00000001;\n    static const DWORD FILE_SHARE_WRITE  = 0x00000002;\n    static const DWORD FILE_SHARE_DELETE = 0x00000004;\n};\n\nstruct CREATION_DISPOSITION {\n    static const DWORD CREATE_NEW        = 1;\n    static const DWORD CREATE_ALWAYS     = 2;\n    static const DWORD OPEN_EXISTING     = 3;\n    static const DWORD OPEN_ALWAYS       = 4;\n    static const DWORD TRUNCATE_EXISTING = 5;\n};\n\nstruct FILE_ATTRIBUTE {\n    static const DWORD FILE_ATTRIBUTE_ARCHIVE   = 32;\n    static const DWORD FILE_ATTRIBUTE_ENCRYPTED = 16384;\n    static const DWORD FILE_ATTRIBUTE_HIDDEN    = 2;\n    static const DWORD FILE_ATTRIBUTE_NORMAL    = 128;\n    static const DWORD FILE_ATTRIBUTE_OFFLINE   = 4096;\n    static const DWORD FILE_ATTRIBUTE_READONLY  = 1;\n    static const DWORD FILE_ATTRIBUTE_SYSTEM    = 4;\n    static const DWORD FILE_ATTRIBUTE_TEMPORARY = 256;\n\n    static const DWORD FILE_FLAG_BACKUP_SEMANTICS   = 0x02000000;\n    static const DWORD FILE_FLAG_DELETE_ON_CLOSE    = 0x04000000;\n    static const DWORD FILE_FLAG_NO_BUFFERING       = 0x20000000;\n    static const DWORD FILE_FLAG_OPEN_NO_RECALL     = 0x00100000;\n    static const DWORD FILE_FLAG_OPEN_REPARSE_POINT = 0x00200000;\n    static const DWORD FILE_FLAG_OVERLAPPED         = 0x40000000;\n    static const DWORD FILE_FLAG_POSIX_SEMANTICS    = 0x01000000;\n    static const DWORD FILE_FLAG_RANDOM_ACCESS      = 0x10000000;\n    static const DWORD FILE_FLAG_SESSION_AWARE      = 0x00800000;\n    static const DWORD FILE_FLAG_SEQUENTIAL_SCAN    = 0x08000000;\n    static const DWORD FILE_FLAG_WRITE_THROUGH      = 0x80000000;\n};\n\nstruct WAIT_RESULT {\n    static const DWORD WAIT_ABANDONED = 0x00000080;\n    static const DWORD WAIT_OBJECT_0  = 0x00000000;\n    static const DWORD WAIT_TIMEOUT   = 0x00000102;\n    static const DWORD WAIT_FAILED    = 0xFFFFFFFF;\n};\n\nstruct WIN_ERROR {\n    static const DWORD NO_ERROR                             = 0;\n    static const DWORD ERROR_INVALID_FUNCTION               = 1;\n    static const DWORD ERROR_FILE_NOT_FOUND                 = 2;\n    static const DWORD ERROR_NOT_ENOUGH_MEMORY              = 8;\n    static const DWORD ERROR_NO_MORE_FILES                  = 18;\n    static const DWORD ERROR_HANDLE_EOF                     = 38;\n    static const DWORD ERROR_DEV_NOT_EXIST                  = 55;\n    static const DWORD ERROR_INVALID_PARAMETER              = 87;\n    static const DWORD ERROR_INSUFFICIENT_BUFFER            = 122;\n    static const DWORD ERROR_INVALID_NAME                   = 123;\n    static const DWORD ERROR_BUSY                           = 170;\n    static const DWORD ERROR_ALREADY_EXISTS                 = 183;\n    static const DWORD ERROR_MORE_DATA                      = 234;\n    static const DWORD WAIT_TIMEOUT                         = 258;\n    static const DWORD ERROR_IO_PENDING                     = 997;\n    static const DWORD ERROR_DEVICE_REINITIALIZATION_NEEDED = 1164;\n    static const DWORD ERROR_CONTINUE                       = 1246;\n    static const DWORD ERROR_NO_MORE_DEVICES                = 1248;\n};\n\nstruct SW {\n    static const DWORD HIDE = 0;\n    static const DWORD SHOWNORMAL = 1;\n    static const DWORD NORMAL = 1;\n    static const DWORD SHOWMINIMIZED = 2;\n    static const DWORD SHOWMAXIMIZED = 3;\n    static const DWORD MAXIMIZE = 3;\n    static const DWORD SHOWNOACTIVATE = 4;\n    static const DWORD SHOW = 5;\n    static const DWORD MINIMIZE = 6;\n    static const DWORD SHOWMINNOACTIVE = 7;\n    static const DWORD SHOWNA = 8;\n    static const DWORD RESTORE = 9;\n    static const DWORD SHOWDEFAULT = 10;\n    static const DWORD FORCEMINIMIZE = 11;\n};\n\nHLOCAL LocalFree(\n  /* in */ HLOCAL hMem\n);\n\nDWORD FormatMessageA(\n  /* in */           DWORD   dwFlags,\n  /* in, optional */ LPCVOID lpSource,\n  /* in */           DWORD   dwMessageId,\n  /* in */           DWORD   dwLanguageId,\n  /* out */          LPCSTR  lpBuffer,\n  /* in */           DWORD   nSize,\n  /* in, optional */ va_list *Arguments\n);\n\nBOOL ReadFile(\n  /* in */                HANDLE       hFile,\n  /* out */               LPVOID       lpBuffer,\n  /* in */                DWORD        nNumberOfBytesToRead,\n  /* out, optional */     LPDWORD      lpNumberOfBytesRead,\n  /* in, out, optional */ LPOVERLAPPED lpOverlapped\n);\n\nBOOL GetOverlappedResult(\n  /* in */  HANDLE       hFile,\n  /* in */  LPOVERLAPPED lpOverlapped,\n  /* out */ LPDWORD      lpNumberOfBytesTransferred,\n  /* in */  BOOL         bWait\n);\n\nLPVOID VirtualAlloc(\n  /* in, optional */ LPVOID lpAddress,\n  /* in */           SIZE_T dwSize,\n  /* in */           DWORD  flAllocationType,\n  /* in */           DWORD  flProtect\n);\n\nDWORD GetModuleFileNameA(\n  /* in, optional */  HMODULE hModule,\n  /* out */           LPSTR   lpFilename,\n  /* in */            DWORD   nSize\n);\n\nBOOL CreateDirectoryA(\n  /* in */           LPCSTR                lpPathName,\n  /* in, optional */ LPSECURITY_ATTRIBUTES lpSecurityAttributes\n);\n\ntypedef struct _FILETIME {\n  DWORD dwLowDateTime;\n  DWORD dwHighDateTime;\n} FILETIME, *PFILETIME, *LPFILETIME;\n\ntypedef struct _WIN32_FIND_DATAA {\n  DWORD dwFileAttributes;\n  FILETIME ftCreationTime;\n  FILETIME ftLastAccessTime;\n  FILETIME ftLastWriteTime;\n  DWORD nFileSizeHigh;\n  DWORD nFileSizeLow;\n  DWORD dwReserved0;\n  DWORD dwReserved1;\n  CHAR cFileName[260];\n  CHAR cAlternateFileName[14];\n  DWORD dwFileType;\n  DWORD dwCreatorType;\n  WORD  wFinderFlags;\n} WIN32_FIND_DATAA, *PWIN32_FIND_DATAA, *LPWIN32_FIND_DATAA;\n\nHANDLE FindFirstFileA(\n  /* in */  LPCSTR             lpFileName,\n  /* out */ LPWIN32_FIND_DATAA lpFindFileData\n);\n\nBOOL FindNextFileA(\n  /* in */  HANDLE             hFindFile,\n  /* out */ LPWIN32_FIND_DATAA lpFindFileData\n);\n\nBOOL FindClose(\n  /* in, out */ HANDLE hFindFile\n);\n\nHINSTANCE ShellExecuteA(\n  /* in, optional */ HWND   hwnd,\n  /* in, optional */ LPCSTR lpOperation,\n  /* in */           LPCSTR lpFile,\n  /* in, optional */ LPCSTR lpParameters,\n  /* in, optional */ LPCSTR lpDirectory,\n  /* in */           INT    nShowCmd\n);\n\n]])\n\nwin32.DesiredAccess = ffi.new(\"struct DESIRED_ACCESS\")\nwin32.ShareMode = ffi.new(\"struct SHARE_MODE\")\nwin32.CreationDisposition = ffi.new(\"struct CREATION_DISPOSITION\")\nwin32.FileAttribute = ffi.new(\"struct FILE_ATTRIBUTE\")\nwin32.WinError = ffi.new(\"struct WIN_ERROR\")\nwin32.SW = ffi.new(\"struct SW\")\n\nlocal shell32 = ffi.load(\"Shell32.dll\")\n\nwin32.INVALID_HANDLE_VALUE = ffi.cast(\"HANDLE\", -1)\n\nfunction win32.format_message(error_code)\n    local flags =\n        0x100  + -- FORMAT_MESSAGE_ALLOCATE_BUFFER\n        0x1000 + -- FORMAT_MESSAGE_FROM_SYSTEM\n        0x200  + -- FORMAT_MESSAGE_IGNORE_INSERTS\n        0xff     -- FORMAT_MESSAGE_MAX_WIDTH_MASK\n\n    local message_arr = ffi.new('char*[1]')\n    -- When using FORMAT_MESSAGE_ALLOCATE_BUFFER:\n    -- Instead of passing a char* we pass a pointer to a char*, the function\n    -- allocates the memory it needs and places the pointer to that memory into\n    -- the location we pass. Since this function normally takes a char* instead\n    -- a char** we need to do this scary cast. We then need to free the memory\n    -- with LocalFree.\n    local message_ptr = ffi.cast('char*', message_arr)\n\n    C.FormatMessageA(flags, nil, error_code, 0, message_ptr, 0, nil)\n    local message = message_arr[0]\n\n    if message == nil then\n        -- Well, We couldn't get the error message for some reason. We can\n        -- retrieve the error, and then get the error text with FormatMessageA!\n        -- Oh wait..\n        local err = C.GetLastError()\n        error(\"Couldn't format error code, everything is f'ed: \" .. tostring(err))\n    end\n\n    local message_string = ffi.string(message)\n\n    C.LocalFree(message)\n\n    return message_string .. \" ( \" .. tostring(error_code) .. \")\"\nend\n\nlocal exe_path = nil\nfunction win32.get_exe_path()\n    if exe_path == nil then\n        local buffer = ffi.new(\"char[1000]\")\n        local result = C.GetModuleFileNameA(nil, buffer, ffi.sizeof(buffer))\n        if result == 0 then\n            error(\"Couldn't get exe path: \" ..\n                win32.format_message(C.GetLastError()))\n        end\n\n        exe_path = ffi.string(buffer, result)\n    end\n\n    return exe_path\nend\n\nffi.cdef([[\n\nstruct HandleLifetime {\n    HANDLE handle;\n};\n\n]])\n\nlocal hlmt = {\n    __gc = function(self)\n        if self.handle ~= nil then\n            C.CloseHandle(self.handle)\n        end\n    end\n}\n\nwin32.HandleLifetime = ffi.metatype(\"struct HandleLifetime\", hlmt)\n\nfunction win32.create_directory(name)\n    local success = C.CreateDirectoryA(name, nil)\n    if success then\n        return \"success\"\n    end\n\n    local err = C.GetLastError()\n    if err == win32.WinError.ERROR_ALREADY_EXISTS then\n        return \"already-exists\"\n    end\n\n    error(\"CreateDirectoryA \" .. win32.format_message(err))\nend\n\nfunction win32.list_dir_contents(name)\n    local find_data = ffi.new(\"WIN32_FIND_DATAA\")\n    local handle = C.FindFirstFileA(name, find_data)\n\n    local file_list = {}\n    local succ, err = pcall(function()\n        local success = handle ~= win32.INVALID_HANDLE_VALUE\n        while success do\n            table.insert(file_list, ffi.string(find_data.cFileName))\n            success = C.FindNextFileA(handle, find_data) ~= 0\n        end\n    end)\n\n    local last_find_result = C.GetLastError()\n\n    if handle ~= win32.INVALID_HANDLE_VALUE then\n        C.FindClose(handle)\n    end\n\n    if not succ then\n        error(err)\n    end\n\n    if\n        last_find_result ~= win32.WinError.ERROR_FILE_NOT_FOUND and\n        last_find_result ~= win32.WinError.ERROR_NO_MORE_FILES\n    then\n        error(\"Find*FileA: \" .. win32.format_message(last_find_result))\n    end\n\n    return file_list\nend\n\nfunction win32.open(path)\n    shell32.ShellExecuteA(nil, \"open\", path, nil, nil, win32.SW.SHOWNORMAL)\nend\n\nfunction win32.explore(path)\n    shell32.ShellExecuteA(nil, \"explore\", path, nil, nil, win32.SW.SHOWNORMAL)\nend\n\nfunction win32.get_base_address()\n    return ffi.cast(\"char*\", ffi.C.GetModuleHandleA(nil))\nend\n\nreturn win32\n"
_TWWE_VFS["mods/component-explorer/user_scripts.lua"] = "local us = {}\n\nus.directory_path = \"user-scripts\"\n\nfunction us.make_path(script_name)\n    return us.directory_path .. \"/\" .. script_name:lower()\nend\n\n---@param script_name string\n---@return any\nfunction us.user_script(script_name)\n    -- Overwritten by unsafe appends\n    print(\"Get unsafe-explorer to make user scripts work\")\nend\n\n---@param script_name string\n---@return boolean\nfunction us.exists(script_name)\n    -- Overwritten by unsafe appends\n    return false\nend\n\n---@param script_name string\n---@return string\nfunction us.user_script_call_string(script_name)\n    return 'return user_script(\"' .. script_name .. '\")'\nend\n\n---@param script_name string\n---@return boolean\nfunction us.is_hidden(script_name)\n    return script_name:sub(1, 1) == \"_\"\nend\n\nreturn us\n"
_TWWE_VFS["mods/component-explorer/utils/beta_version.lua"] = "local beta_version = {}\n\n-- Table just indicates compatibility with certain betas.\n-- Used to gate certain features/options that only work on later versions of Noita.\n\nbeta_version.is_beta = not not CellFactory_HasTag\n\nreturn beta_version\n"
_TWWE_VFS["mods/component-explorer/utils/ce_settings.lua"] = "local ce_settings = {}\n\nlocal mod_id = \"component-explorer\"\nlocal settings = {}\nlocal computed = {}\n\nlocal IS_NIL = {}\n\nlocal function load_setting_value(key)\n    local full_key = mod_id .. \".\" .. key\n    local value = ModSettingGet(full_key)\n\n    -- Seems like 'value_default=false' gets turned into nil by Noita\n    if value == nil then\n        return false\n    end\n\n    return value\nend\n\nfunction ce_settings.load()\n    settings = {}\n    computed = {}\nend\n\nfunction ce_settings.get(key)\n    if settings[key] == nil then\n        settings[key] = load_setting_value(key)\n    end\n\n    return settings[key]\nend\n\nfunction ce_settings.set(key, value)\n    if ce_settings.get(key) ~= value then\n        ModSettingSet(mod_id .. \".\" .. key, value)\n        settings[key] = value\n    end\nend\n\nlocal magic_key_labels = {\n    [\"ctrl+shift\"] = \"CTRL+SHIFT\",\n    [\"ctrl\"] = \"CTRL\",\n    [\"super\"] = \"SUPER\",\n    [\"alt\"] = \"ALT\",\n}\n\n---@generic T\n---@param name string\n---@param func T\n---@return T\nlocal function computed_func(name, func)\n    return function()\n        local cached = computed[name]\n        if cached then\n            if cached == IS_NIL then return nil end\n            return cached\n        end\n\n        local result = func()\n        if result == nil then computed[name] = IS_NIL\n                         else computed[name] = result end\n\n        return result\n    end\nend\n\n---@generic T\n---@param name string\n---@param func T\n---@return T\nlocal function computed_func_1(name, func)\n    return function(value)\n        local cache = computed[name]\n        if not cache then\n            cache = {}\n            computed[name] = cache\n        end\n\n        local cached = cache[value]\n        if cached then\n            if cached == IS_NIL then return nil end\n            return cached\n        end\n\n        local result = func(value)\n        if result == nil then cache[value] = IS_NIL\n                         else cache[value] = result end\n\n        return result\n    end\nend\n\nce_settings.magic_key_label = computed_func(\"magic_key_label\", function()\n    if not ce_settings.get(\"keyboard_shortcuts\") then\n        return nil\n    end\n\n    return magic_key_labels[ce_settings.get(\"magic_key\")]\nend)\n\nfunction ce_settings.magic_keys_down()\n    if not ce_settings.get(\"keyboard_shortcuts\") then\n        return false\n    end\n\n    local kd = imgui.IsKeyDown\n    local keys = imgui.Key\n\n    local magic_key = ce_settings.get(\"magic_key\")\n\n    if magic_key == \"ctrl+shift\" then\n        return (kd(keys.LeftCtrl) or kd(keys.RightCtrl))\n           and (kd(keys.LeftShift) or kd(keys.RightShift))\n    elseif magic_key == \"ctrl\" then\n        return kd(keys.LeftCtrl) or kd(keys.RightCtrl)\n    elseif magic_key == \"super\" then\n        return kd(keys.LeftSuper) or kd(keys.RightSuper)\n    elseif magic_key == \"alt\" then\n        return kd(keys.LeftAlt) or kd(keys.RightAlt)\n    else\n        print(\"Error unknown magic_key: \" .. magic_key)\n    end\nend\n\nreturn ce_settings\n"
_TWWE_VFS["mods/component-explorer/utils/component_tags.lua"] = "local comp_tag_util = {}\n\n-- From https://noita.wiki.gg/wiki/Modding:_Special_tags#Component_tags\ncomp_tag_util.special_tags = {\n    \"enabled_in_hand\",\n    \"enabled_in_world\",\n    \"enabled_in_inventory\",\n    \"shop_cost\",\n    \"fire\",\n}\n\nreturn comp_tag_util\n"
_TWWE_VFS["mods/component-explorer/utils/copy.lua"] = "local copy = {}\n\nfunction copy.shallow_copy(tbl)\n    local ret = {}\n    for k, v in pairs(tbl) do\n        ret[k] = v\n    end\n    return ret\nend\n\nreturn copy\n"
_TWWE_VFS["mods/component-explorer/utils/eval.lua"] = "local CE_PARSE_ERROR = \"Couldn't parse expression, check logger.txt\"\n\nlocal eval = {}\n\nlocal set_content = ModTextFileSetContent\n\n--- loadstring but returns nil if there's a syntax error\n---@param str string\n---@return function?\n---@return string?\nfunction eval.loadstring_ish(str)\n    local filename = \"mods/component-explorer/user_command.lua\"\n    set_content(filename, str)\n    local f, err = loadfile(filename)\n\n    if not f then\n        return nil, err or CE_PARSE_ERROR\n    end\n\n    return f\nend\n\n---@param str string String to evaluate\n---@return boolean succes\n---@return any result\nfunction eval.eval(str)\n    local f, err = eval.loadstring_ish(str)\n    if not f then\n        return false, err\n    end\n\n    return pcall(f)\nend\n\nreturn eval\n"
_TWWE_VFS["mods/component-explorer/utils/file_util.lua"] = "local file_util = {}\n\nlocal ModDoesFileExist = ModDoesFileExist\nlocal ModTextFileGetContent = ModTextFileGetContent\n\nlocal exists_cache = {}\n\n---@param path string\n---@return boolean\nfunction file_util.file_exists(path)\n    local cached = exists_cache[path]\n    if cached ~= nil then\n        return cached\n    end\n\n    local exists\n\n    if path:sub(-4) == \".png\" then\n        exists = ModImageDoesExist(path)\n    else\n        exists = ModDoesFileExist(path)\n    end\n\n    exists_cache[path] = exists\n    return exists\nend\n\nfile_util.ModTextFileGetContent = ModTextFileGetContent\n\nreturn file_util\n"
_TWWE_VFS["mods/component-explorer/utils/lua_appends.lua"] = "local lua_appends = {}\n\n---@param path string Path to the script you want to get appends of\n---@return string[]\nlocal function impl_get(path)\n    local result = {}\n\n    dofile = function(appended)\n        table.insert(result, appended)\n    end\n\n    do_mod_appends(path)\n\n    return result\nend\n\n---Returns the Lua files that were appended to the given script\n---@param path string Path to the script you want to get appends of\n---@return string[]\nfunction lua_appends.get(path)\n    local dofile_restore = dofile\n    local status, ret = pcall(impl_get, path)\n    dofile = dofile_restore\n\n    if not status then\n        error(ret)\n    end\n\n    return ret\nend\n\n---@alias recursive_appends {path: string, appends: recursive_appends[]}\n\n---@param path string\n---@param maxdepth integer\n---@return recursive_appends[]\nlocal function impl_get_recursive(path, maxdepth)\n    if maxdepth == 0 then\n        return {}\n    end\n\n    ---@type recursive_appends[]\n    local result = {}\n\n    local dofile_restore = dofile\n\n    dofile = function(appended)\n        table.insert(result,\n            {\n                path = appended,\n                appends = impl_get_recursive(appended, maxdepth - 1),\n            }\n        )\n    end\n\n    do_mod_appends(path)\n\n    dofile = dofile_restore\n\n    return result\nend\n\n---@param path string Path to the script you want to get appends of\n---@param maxdepth integer? Maximum depth it will try to resolve the appends to. Defaults to 10\n---@return recursive_appends[] appends Nested list of appended scripts\nfunction lua_appends.get_recursive(path, maxdepth)\n    maxdepth = maxdepth or 10\n\n    local dofile_restore = dofile\n    local status, ret = pcall(impl_get_recursive, path, maxdepth)\n    dofile = dofile_restore\n\n    if not status then\n        error(ret)\n    end\n\n    return ret\nend\n\n\nreturn lua_appends\n"
_TWWE_VFS["mods/component-explorer/utils/math_util.lua"] = "local math_util = {}\n\n---@param a string\n---@return string\nfunction math_util.int64_clamp(a)\n    local an = tonumber(a)\n    if an == nil then return \"0\" end\n    if an >= 2^63 then return \"9223372036854775807\" end\n    if an < -2^63 then return \"-9223372036854775808\" end\n    return a\nend\n\n---@param a string\n---@return string\nfunction math_util.uint64_clamp(a)\n    local an = tonumber(a)\n    if an == nil then return \"0\" end\n    if an >= 2^64 then return \"18446744073709551615\" end\n    if an < 0 then return \"0\" end\n    return a\nend\n\n---@param a number\n---@param min number\n---@param max number\nfunction math_util.clamp(a, min, max)\n    if a < min then return min end\n    if a > max then return max end\n    return a\nend\n\nreturn math_util\n"
_TWWE_VFS["mods/component-explorer/utils/matutil.lua"] = "local matutil = {}\n\nlocal _all_materials = nil\nfunction matutil.get_all_material_names()\n    if _all_materials == nil then\n        _all_materials = {}\n        local i = 0\n        while true do\n            local material_name = CellFactory_GetName(i)\n            if material_name == \"unknown\" then\n                break\n            end\n\n            table.insert(_all_materials, material_name)\n            i = i + 1\n        end\n    end\n    return _all_materials\nend\n\nfunction matutil.material_name(matid)\n    return matutil.get_all_material_names()[matid + 1]\nend\n\nreturn matutil\n"
_TWWE_VFS["mods/component-explorer/utils/player_util.lua"] = "local player_util = {}\n\n---@return integer?\nfunction player_util.get_player()\n    local p = EntityGetWithTag(\"player_unit\")[1]\n    if p then\n        return p\n    end\n\n    return EntityGetWithTag(\"polymorphed_player\")[1]\nend\n\nreturn player_util\n"
_TWWE_VFS["mods/component-explorer/utils/strings.lua"] = "local string_util = {}\n\nfunction string_util.normalise(s)\n    s = string.lower(s)\n    s = s:gsub(\"ä\", \"a\") s = s:gsub(\"Ä\", \"a\")\n    s = s:gsub(\"ö\", \"o\") s = s:gsub(\"Ö\", \"o\")\n    return s\nend\n\nlocal nm = string_util.normalise\n\nfunction string_util.ifind(s, pattern, init, plain)\n    return string.find(nm(s), nm(pattern), init, plain)\nend\n\nfunction string_util.split_iter(str, sep, plain)\n    local start = 1\n\n    return function()\n        local sep_start, sep_end = string.find(str, sep, start, plain)\n        sep_start = sep_start or #str + 1\n        sep_end = sep_end or #str + 1\n\n        if start <= sep_start then\n            local value = string.sub(str, start, sep_start - 1)\n            start = sep_end + 1\n            return value\n        end\n    end\nend\n\nfunction string_util.split(str, sep, plain)\n    local result = {}\n    for value in string_util.split_iter(str, sep, plain) do\n        table.insert(result, value)\n    end\n    return result\nend\n\nfunction string_util.trim(s)\n   return s:gsub(\"^%s*(.-)%s*$\", \"%1\")\nend\n\nfunction string_util.starts_with(s, start)\n    if #s < #start then return false end\n    local part = s:sub(1, #start)\n    return part == start\nend\n\nfunction string_util.ends_with(s, ending)\n    if #s < #ending then return false end\n    local part = s:sub(#s - #ending + 1)\n    return part == ending\nend\n\nfunction string_util.remove_prefix(s, start)\n    if not string_util.starts_with(s, start) then\n        return s\n    end\n    return s:sub(#start + 1)\nend\n\nfunction string_util.remove_suffix(s, ending)\n    if not string_util.ends_with(s, ending) then\n        return s\n    end\n    return s:sub(1, #s - #ending)\nend\n\n---@param s string\n---@return string\nfunction string_util.strip(s)\n    return s:match(\"^%s*(.-)%s*$\")\nend\n\nreturn string_util\n"
_TWWE_VFS["mods/component-explorer/utils/tcsv.lua"] = "-- Noita Translations CSV Reader\n\nlocal tcsv = {}\n\n---@class LineReader\n---@field content string\n---@field char_index integer\nlocal LineReader = {}\nLineReader.__index = LineReader\n\nfunction LineReader.new(content)\n    return setmetatable({\n        content = content,\n        char_index = 1,\n    }, LineReader)\nend\n\n---@return string?\n---@nodiscard\nfunction LineReader:next()\n    local idx = self.char_index\n\n    if idx > #self.content then\n        -- Reached EOF\n        return nil\n    end\n\n    local start = idx\n\n    while true do\n        local chr = self.content:sub(idx, idx)\n        if chr == \"\\n\" then\n            -- Put char_index after the newline\n            self.char_index = idx + 1\n            idx = idx - 1\n            break\n        end\n\n        if idx == #self.content then\n            self.char_index = idx + 1\n            break\n        end\n\n        idx = idx + 1\n    end\n\n    local line = self.content:sub(start, idx)\n    line = line:gsub(\"\\r\", \"\")\n\n    return line\nend\n\n---@param line string\n---@param filename string\n---@param line_nr integer\n---@return string[] fields\n---@return string[] warnings\n---@nodiscard\nlocal function parse_csv_line(line, filename, line_nr)\n    local ret = {}\n    local warnings = {}\n    local idx = 1\n    local field_start = 1\n\n    local in_quote = false\n\n    while idx <= #line do\n        local chr = line:sub(idx, idx)\n        if chr == '\"' then\n            if idx < #line and line:sub(idx + 1, idx + 1) == '\"' then\n                idx = idx + 1\n                goto continue\n            end\n\n            in_quote = not in_quote\n            if in_quote then\n                idx = idx + 1\n                field_start = idx\n            else\n                table.insert(ret, line:sub(field_start, idx - 1))\n\n                if idx < #line and line:sub(idx + 1, idx + 1) ~= \",\" then\n                    table.insert(warnings, table.concat({\n                        \"Text -\", filename, \"on line\", line_nr,\n                        \"expected a ',' at around\", idx + 1}, \" \"))\n                end\n\n                field_start = idx + 2\n                idx = idx + 1\n            end\n        elseif not in_quote and chr == \",\" then\n            table.insert(ret, line:sub(field_start, idx - 1))\n            field_start = idx + 1\n        end\n\n        ::continue::\n        idx = idx + 1\n    end\n\n    return ret, warnings\nend\n\n---@class CSV\n---@field warnings string[]\n---@field langs string[]\n---@field rows string[][]\n\n---@param content string\n---@param filename string\n---@param is_mod_translation boolean\n---@return CSV\n---@nodiscard\nfunction tcsv.parse(content, filename, is_mod_translation)\n    local line_reader = LineReader.new(content)\n    local line = line_reader:next()\n    local line_nr = 1\n\n    local num_langs\n    local first_row_columns\n\n    local langs = {}\n    local warnings = {}\n    local rows = {}\n\n    while line ~= nil and line ~= \"\" do\n        local values, line_warns = parse_csv_line(line, filename, line_nr)\n        for _, lw in ipairs(line_warns) do\n            table.insert(warnings, lw)\n        end\n\n        if line_nr == 1 then\n            first_row_columns = #values\n\n            if is_mod_translation then\n                num_langs = 1\n            else\n                for i=2,#values do\n                    if values[i] == \"\" then\n                        num_langs = i - 2\n                        break\n                    end\n                end\n                if num_langs == nil then\n                    table.insert(warnings, table.concat({\n                        \"There should be an empty value on the header\",\n                        \"row after the last language\"}, \" \"))\n\n                    num_langs = math.max(1, #values - 1)\n                end\n            end\n\n            for i=2,num_langs+1 do\n                if i <= #values then\n                    table.insert(langs, values[i])\n                else\n                    table.insert(langs, \"#lang\" .. i - 1)\n                end\n            end\n        else\n            if #values == 0 then\n                table.insert(warnings, table.concat({\n                    \"Incomplete CSV row on line\", line_nr,\n                    \"(missing comma?)\"}, \" \"))\n                goto continue\n            end\n\n            if #values < num_langs + 1 then\n                table.insert(warnings, table.concat({\n                    \"Missing values on line\", line_nr,\n                    \"expected\", num_langs + 1, \"values but got\", #values}, \" \"))\n            elseif #values >= 2 * (num_langs + 1) and #values > first_row_columns then\n                table.insert(warnings, table.concat({\n                    \"Found two or more times the expected values on line\", line_nr .. \".\",\n                    \"Number of values:\", #values,\n                    \"(missing newline?)\"}, \" \"))\n            end\n\n            for i=2, math.min(num_langs + 1, #values) do\n                values[i] = values[i]:gsub(\"\\\\n\", \"\\n\")\n            end\n\n            local row = {}\n            for i=1,num_langs + 1 do\n                table.insert(row, values[i] or \"\")\n            end\n            table.insert(rows, row)\n        end\n\n        ::continue::\n        line_nr = line_nr + 1\n        line = line_reader:next()\n    end\n\n    while line == \"\" do\n        local stopped_nr = line_nr\n\n        line = line_reader:next()\n        line_nr = line_nr + 1\n\n        if line ~= nil and line ~= \"\" then\n            table.insert(warnings, table.concat({\n                \"CSV reader stopped on line\", stopped_nr,\n                \"because there was an empty line, but\",\n                \"there's more content on line\", line_nr}, \" \"))\n            break\n        end\n    end\n\n    return {\n        warnings = warnings,\n        langs = langs,\n        rows = rows,\n    }\nend\n\nreturn tcsv\n"
_TWWE_VFS["mods/component-explorer/utils/wiki.lua"] = "local string_util = dofile_once(\"mods/component-explorer/utils/strings.lua\")\n\nlocal wiki = {}\n\nlocal function parse_state(text)\n    return {\n        text = text,\n        index = 1,\n    }\nend\n\nlocal function parse_error(state, text)\n    error({\n        state=state,\n        error=text\n    })\nend\n\nlocal function spaces(state)\n    local i = state.index\n    while i <= #state.text do\n        local chr = state.text:sub(i, i)\n        if chr ~= \" \" and chr ~= \"\\t\" and chr ~= \"\\r\" and chr ~= \"\\n\" then\n            break\n        end\n        i = i + 1\n    end\n\n    state.index = i\nend\n\nlocal function expect(state, expected)\n    local actual = state.text:sub(state.index, state.index + #expected - 1)\n    if actual ~= expected then\n        parse_error(state, \"Expected '\" .. expected .. \"' but got '\" .. actual .. \"'\")\n    end\n    state.index = state.index + #expected\nend\n\nlocal function readuntil(state, one_of)\n    local i=state.index\n    while i <= #state.text do\n        for _, v in ipairs(one_of) do\n            local real = state.text:sub(i, i + #v - 1)\n            if real == v then\n                local part = state.text:sub(state.index, i - 1)\n                state.index = i\n                return part\n            end\n        end\n\n        i = i + 1\n    end\n\n    parse_error(state,\n        \"Expected one of \" .. table.concat(one_of, \", \") .. \" but reached end of text instead.\")\nend\n\nlocal function peek(state, count)\n    return state.text:sub(state.index, state.index + count - 1)\nend\n\nfunction wiki.format_template(template_name, values, alignment)\n    local param_strings = {\"\"}\n    for _, item in ipairs(values) do\n        local key, value = unpack(item)\n        local to_align = math.max(0, alignment - string.len(key))\n        table.insert(param_strings, key .. string.rep(\" \", to_align) .. \" = \" .. tostring(value))\n    end\n\n    local param_string = table.concat(param_strings, \"\\n| \")\n    return \"{{\" .. template_name .. param_string .. \"\\n}}\"\nend\n\nfunction wiki.parse_template(template_text)\n    local state = parse_state(template_text)\n    spaces(state)\n    expect(state, \"{{\")\n    spaces(state)\n    local template_name = string_util.trim(readuntil(state, {\"}}\", \"|\"}))\n\n    local values = {}\n    while peek(state, 2) ~= \"}}\" do\n        expect(state, \"|\")\n\n        local key = string_util.trim(readuntil(state, {\"=\"}))\n\n        spaces(state)\n        expect(state, \"=\")\n        spaces(state)\n\n        local value = string_util.trim(readuntil(state, {\"|\", \"}}\"}))\n        table.insert(values, {key, value})\n    end\n\n    expect(state, \"}}\")\n\n    return {\n        template_name = template_name,\n        values = values\n    }\nend\n\nfunction wiki.normalise_page_name(name)\n    -- Capitalise\n    name = name:sub(1, 1):upper() .. name:sub(2)\n    -- Use spaces\n    name = name:gsub(\"_\", \" \")\n    -- Collapse spaces\n    name = name:gsub(\"  +\", \" \")\n\n    return name\nend\n\nfunction wiki.normalise_spell_name(name)\n    -- General\n    name = wiki.normalise_page_name(name)\n    -- Capitalise words\n    name = name:gsub(\"[- ].\", string.upper)\n\n    return name\nend\n\nreturn wiki\n"
_TWWE_VFS["mods/component-explorer/utils/wiki_spell_names.lua"] = "dofile_once(\"data/scripts/gun/gun_actions.lua\")\n\n---@module 'component-explorer.utils.wiki'\nlocal wiki = dofile_once(\"mods/component-explorer/utils/wiki.lua\")\n\n---@module 'component-explorer.utils.tcsv'\nlocal tcsv = dofile_once(\"mods/component-explorer/utils/tcsv.lua\")\n\nlocal wiki_spell_names = {}\n\n---action_long_distance_cast -> Long-distance cast\n---@type {[string]: string}\nlocal english_lookup = {}\n\n---@param csv_file string\nlocal function register_en_translations(csv_file)\n    local csv = tcsv.parse(ModTextFileGetContent(csv_file), csv_file, false)\n    for i=2,#csv.rows do\n        local row = csv.rows[i]\n        english_lookup[row[1]] = row[2]\n    end\nend\n\nregister_en_translations(\"data/translations/common_dev.csv\")\nregister_en_translations(\"data/translations/common.csv\")\n\nwiki_spell_names.by_action_id = {}\nfor _, action in ipairs(actions) do\n    local name = action.name\n\n    -- Modded spells might not be using translations\n    if name:sub(1, 1) == \"$\" then\n        local without_dollar = name:sub(2)\n        local english_name = english_lookup[without_dollar]\n        if english_name then\n            name = wiki.normalise_spell_name(english_name)\n        else\n            -- Probably not correct, just a last ditch effort\n            name = without_dollar\n        end\n    end\n\n    wiki_spell_names.by_action_id[action.id] = name\nend\n\nlocal to_action_id = {}\nfor action_id, name in pairs(wiki_spell_names.by_action_id) do\n    to_action_id[name:lower()] = action_id\nend\n\nfunction wiki_spell_names.to_action_id(name)\n    if name == nil then return nil end\n    local id = to_action_id[name:lower()]\n    if id then\n        return id\n    end\n\n    -- If the name is already an action_id, return it\n    if wiki_spell_names.by_action_id[name:upper()] then\n        return name:upper()\n    end\n\n    return name\nend\n\nreturn wiki_spell_names\n"
_TWWE_VFS["mods/component-explorer/utils/wiki_wand.lua"] = "---@module 'component-explorer.wand_sprites'\nlocal wand_sprites = dofile_once(\"mods/component-explorer/wand_sprites.lua\")\n\n---@module 'component-explorer.utils.wiki_spell_names'\nlocal wiki_spell_names = dofile_once(\"mods/component-explorer/utils/wiki_spell_names.lua\")\n\n---@module 'component-explorer.utils.wiki'\nlocal wiki = dofile_once(\"mods/component-explorer/utils/wiki.lua\")\n\n---@module 'component-explorer.utils.strings'\nlocal string_util = dofile_once(\"mods/component-explorer/utils/strings.lua\")\n\nlocal wiki_wand = {}\n\n---Turn an EZWand object into a list of values used in Wand/Wand Card templates\n---@param ezwand table\n---@param to_wand_card boolean\n---@param is_wand2 boolean\n---@return table\nfunction wiki_wand.get_wand_values(ezwand, to_wand_card, is_wand2)\n    local values = {}\n\n    if is_wand2 and to_wand_card then\n        table.insert(values, {\"wandCard\", \"Yes\"})\n    end\n\n    if to_wand_card then\n        local item_name = nil\n\n        local item_comp = EntityGetFirstComponentIncludingDisabled(ezwand.entity_id, \"ItemComponent\")\n        if item_comp then\n            if ComponentGetValue2(item_comp, \"always_use_item_name_in_ui\") then\n                item_name = ComponentGetValue2(item_comp, \"item_name\")\n            end\n        end\n\n        if item_name then\n            table.insert(values, {\"wandName\", GameTextGetTranslatedOrNot(item_name)})\n        end\n    end\n\n    local wiki_file_name = wand_sprites.wiki_sprite_filename(ezwand)\n    if wiki_file_name then\n        table.insert(values, {\"wandPic\", wiki_file_name})\n    end\n\n    if ezwand.shuffle then\n        table.insert(values, {\"shuffle\", \"Yes\"})\n    end\n\n    if ezwand.spellsPerCast ~= 1 then\n        table.insert(values, {\"spellsCast\", ezwand.spellsPerCast})\n    end\n\n    if to_wand_card then\n        table.insert(values, {\"castDelay\", (\"%.2f\"):format(ezwand.castDelay / 60)})\n        table.insert(values, {\"rechargeTime\", (\"%.2f\"):format(ezwand.rechargeTime / 60)})\n        table.insert(values, {\"manaMax\", (\"%.2f\"):format(ezwand.manaMax)})\n        table.insert(values, {\"manaCharge\", (\"%.2f\"):format(ezwand.manaChargeSpeed)})\n    end\n\n    local spells, attached_spells = ezwand:GetSpells()\n\n    if is_wand2 or to_wand_card then\n        table.insert(values, {\"capacity\", ezwand.capacity})\n    else\n        table.insert(values, {\"capacity\", #spells})\n    end\n\n    if to_wand_card then\n        table.insert(values, {\"spread\", ezwand.spread})\n        table.insert(values, {\"speed\", (\"%.2f\"):format(ezwand.speedMultiplier)})\n    end\n\n    if is_wand2 then\n        if #attached_spells > 0 then\n            local ac_actions = {}\n            for _, ac in ipairs(attached_spells) do\n                ac_actions[#ac_actions+1] = ac.action_id\n            end\n            table.insert(values, {\"alwaysCasts\", table.concat(ac_actions, \",\")})\n        end\n\n        local previous_inv_x = -1\n\n        local spell_actions = {}\n        for _, spell in ipairs(spells) do\n            local prepend = \"\"\n            if previous_inv_x + 1 ~= spell.inventory_x then\n                for _=previous_inv_x+1,spell.inventory_x-1 do\n                    spell_actions[#spell_actions+1] = \"\"\n                end\n                prepend = \"\\n\" .. string.rep(\" \", 17)\n            end\n            spell_actions[#spell_actions+1] = prepend .. spell.action_id\n            previous_inv_x = spell.inventory_x\n        end\n\n        if #spell_actions > 0 then\n            table.insert(values, {\"spells\", table.concat(spell_actions, \",\")})\n        end\n    else\n        for _, spell in ipairs(attached_spells) do\n            local wiki_name = wiki_spell_names.by_action_id[spell.action_id]\n            table.insert(values, {\"alwaysCasts\", wiki_name})\n        end\n\n        local spell_nr = 1\n        for _, spell in ipairs(spells) do\n            local wiki_name = wiki_spell_names.by_action_id[spell.action_id]\n            table.insert(values, {\"spell\" .. spell_nr, wiki_name})\n            spell_nr = spell_nr + 1\n        end\n    end\n\n    return values\nend\n\n---Turn an EZWand object into wiki wand text\n---@param ezwand table\n---@param to_wand_card boolean\n---@return string\nfunction wiki_wand.wand_to_wiki_text(ezwand, to_wand_card, is_wand2)\n    local wand_values = wiki_wand.get_wand_values(ezwand, to_wand_card, is_wand2)\n\n    if is_wand2 then\n        return wiki.format_template(\"Wand2\", wand_values, 12)\n    end\n\n    if to_wand_card then\n        return wiki.format_template(\"Wand Card\", wand_values, 12)\n    end\n\n    return wiki.format_template(\"Wand\", wand_values, 11)\nend\n\n---Turn range text like \"3, 8.5\" into values 3, 8.5. If the given string is a\n---single value then it returns it as a range with the same start and end. The\n---function also parses old-style \"(3 - 8.5)\" ranges.\n---@param range string|number\n---@return number\n---@return number\nfunction wiki_wand.field_range_value(range)\n    if type(range) == \"number\" then\n        return range, range\n    end\n\n    range = string_util.strip(range)\n    range = string_util.remove_prefix(range, \"x\") -- speed = x 1.25\n    range = string_util.strip(range)\n\n    local min, max\n\n    local comma = range:find(\",\", 1, true)\n    if comma then\n        min = tonumber(range:sub(1, comma - 1))\n        max = tonumber(range:sub(comma + 1))\n    elseif range:sub(1, 1) == \"(\" and range:sub(-1, -1) == \")\" then\n        local dash_pos = range:find(\"-\", 3, true)\n        if dash_pos then\n            min = tonumber(range:sub(2, dash_pos - 1))\n            max = tonumber(range:sub(dash_pos + 1, #range - 1))\n        end\n    else\n        min = tonumber(range)\n        max = min\n    end\n\n    if min == nil or max == nil then\n        error(\"Couldn't parse range/value\")\n    end\n\n    if min > max then\n        min, max = max, min\n    end\n\n    return min, max\nend\n\nwiki_wand.FIELD_RANGES = {\n    {\"i\", \"spellsCast\"},\n    {\"f\", \"castDelay\"},\n    {\"f\", \"rechargeTime\"},\n    {\"i\", \"manaMax\"},\n    {\"i\", \"manaCharge\"},\n    {\"i\", \"capacity\"},\n    {\"f\", \"spread\"},\n    {\"f\", \"speed\"},\n}\n\nwiki_wand.SUPPORTS_FIELD_RANGE = {}\nfor _, field_range in ipairs(wiki_wand.FIELD_RANGES) do\n    local field_name = field_range[2]\n    wiki_wand.SUPPORTS_FIELD_RANGE[field_name] = true\nend\n\nlocal function set_sprite_by_filename(ezwand, filename)\n    local data = wand_sprites.from_wiki_name(filename)\n    if data == nil then return false end\n\n    ezwand:SetSprite(\n        data.sprite_file or data.image_file,\n        data.offset_x, data.offset_y,\n        data.tip_x, data.tip_y)\n\n    return true\nend\n\n---@param spell_list string\n---@param keep_gaps boolean?\n---@return string[]\nlocal function split_spell_list(spell_list, keep_gaps)\n    local actions = string_util.split(spell_list, \",\", true)\n    local ret = {}\n    for _, action in ipairs(actions) do\n        action = string_util.trim(action)\n        if action ~= \"\" then\n            ret[#ret+1] = wiki_spell_names.to_action_id(action)\n        elseif keep_gaps then\n            ret[#ret+1] = \"\"\n        end\n    end\n\n    return ret\nend\n\nfunction wiki_wand.load_data_to_wand(wand, template_data)\n    map = {}\n    for _, v in ipairs(template_data.values) do\n        if wiki_wand.SUPPORTS_FIELD_RANGE[v[1]] then\n            map[v[1]] = wiki_wand.field_range_value(v[2])\n        else\n            map[v[1]] = v[2]\n        end\n    end\n\n    if map.wandPic then\n        set_sprite_by_filename(wand, map.wandPic)\n    end\n\n    if map.wandName then\n        local item_comp = EntityGetFirstComponentIncludingDisabled(wand.entity_id, \"ItemComponent\")\n        ComponentSetValue2(item_comp, \"always_use_item_name_in_ui\", true)\n        ComponentSetValue2(item_comp, \"item_name\", map.wandName)\n    end\n\n    wand.shuffle = map.shuffle == \"true\"\n    wand.spellsPerCast = tonumber(map.spellsCast) or 1\n\n    map.castDelay = tonumber(map.castDelay)\n    map.rechargeTime = tonumber(map.rechargeTime)\n    map.manaMax = tonumber(map.manaMax)\n    map.manaCharge = tonumber(map.manaCharge)\n    map.capacity = tonumber(map.capacity)\n    map.spread = tonumber(map.spread)\n    map.speed = tonumber(map.speed)\n\n    if map.castDelay then\n        wand.castDelay = map.castDelay * 60\n    end\n\n    if map.rechargeTime then\n        wand.rechargeTime = map.rechargeTime * 60\n    end\n\n    if map.manaMax then\n        wand.manaMax = map.manaMax\n    end\n\n    if map.manaCharge then\n        wand.manaChargeSpeed = map.manaCharge\n    end\n\n    wand.capacity = map.capacity\n\n    if map.spread then\n        wand.spread = map.spread\n    end\n\n    if map.speed then\n        wand.speedMultiplier = map.speed\n    end\n\n    wand:DetachSpells()\n    wand:RemoveSpells()\n\n    if template_data.template_name == \"Wand2\" then\n        if map.alwaysCasts then\n            wand:AttachSpells(split_spell_list(map.alwaysCasts))\n        end\n        if map.spells then\n            wand:AddSpells(split_spell_list(map.spells, true))\n            wand:RemoveSpells(\"\", -1)\n        end\n    else\n        for _, item in ipairs(template_data.values) do\n            if item[1] == \"alwaysCasts\" then\n                local action_id = wiki_spell_names.to_action_id(item[2])\n                wand:AttachSpells(action_id)\n            end\n        end\n\n        for spell_nr=1, map.capacity do\n            local spell_name = map[\"spell\" .. spell_nr]\n            if spell_name ~= nil then\n                local action_id = wiki_spell_names.to_action_id(spell_name)\n                wand:AddSpells(action_id)\n            end\n        end\n    end\nend\n\nreturn wiki_wand\n"
_TWWE_VFS["mods/component-explorer/version.lua"] = "return {\n    version = \"1.60.4\",\n    homepage = \"https://github.com/dextercd/Noita-Component-Explorer\",\n    wiki = \"https://noita.wiki.gg/wiki/Mod:Component_Explorer\",\n}"
_TWWE_VFS["mods/component-explorer/wand_sprites.lua"] = "dofile(\"mods/component-explorer/unique_wand_sprites.lua\")\nlocal wiki = dofile_once(\"mods/component-explorer/utils/wiki.lua\")\nlocal string_util = dofile_once(\"mods/component-explorer/utils/strings.lua\")\n\nlocal wand_sprites = {}\n\ndofile_once(\"data/scripts/gun/procedural/wands.lua\")\n\nlocal procedural_wands = {}\nfor _, wand in ipairs(wands) do\n    local sprite_path = string_util.split(wand.file, \"/\", true)\n    local sprite_filename = sprite_path[#sprite_path]\n    local wiki_name = wiki.normalise_page_name(sprite_filename)\n    procedural_wands[wiki_name] = {\n        offset_x = wand.grip_x,\n        offset_y = wand.grip_y,\n        tip_x = (wand.tip_x - wand.grip_x),\n        tip_y = (wand.tip_y - wand.grip_y),\n        image_file = wand.file,\n        wiki_file = wiki_name,\n    }\nend\n\nfunction wand_sprites.from_wiki_name(name)\n    name = wiki.normalise_page_name(name)\n\n    local procedural = procedural_wands[name]\n    if procedural then return procedural end\n\n    for _, v in ipairs(unique_wand_sprites) do\n        if v.wiki_file == name then\n            return v\n        end\n    end\n\n    return nil\nend\n\nfunction wand_sprites.wiki_sprite_filename(wand)\n    local sprite1\n    local sprite2\n\n    if wand.ability_component then\n        sprite1 = ComponentGetValue2(wand.ability_component, \"sprite_file\")\n    end\n\n    local sprite_comp = EntityGetFirstComponentIncludingDisabled(wand.entity_id, \"SpriteComponent\", \"item\")\n    if sprite_comp then\n        sprite2 = ComponentGetValue2(sprite_comp, \"image_file\")\n    end\n\n    -- Some wand scripts like data/scripts/gun/procedural/wand_vihta.lua replace\n    -- the sprite on the sprite/item component but not the ability component.\n\n    for _, v in ipairs(unique_wand_sprites) do\n        if (sprite2 and sprite2 == v.image_file) or sprite1 == v.sprite_file then\n            -- For some reason the offsets that were extracted aren't accurate.\n            -- Replacing with 4 seems more accurate overall but not perfect.\n            v.offset_x = 4\n            v.offset_y = 4\n            return v.wiki_file\n        end\n    end\n\n    if string_util.ends_with(sprite1, \".png\") then\n        local path = string_util.split(sprite1, \"/\", true)\n        local filename = path[#path]\n        return wiki.normalise_page_name(filename)\n    end\n\n    return nil\nend\n\nreturn wand_sprites\n"
_TWWE_VFS["mods/component-explorer/wiki_wands.lua"] = "---@module 'component-explorer.style'\nlocal style = dofile_once(\"mods/component-explorer/style.lua\")\n\n---@module 'component-explorer.ui.link'\nlocal link = dofile_once(\"mods/component-explorer/ui/link.lua\")\n\n---@module 'component-explorer.deps.EZWand'\nlocal EZWand = dofile_once(\"mods/component-explorer/deps/EZWand.lua\")\n\n---@module 'component-explorer.utils.strings'\nlocal string_util = dofile_once(\"mods/component-explorer/utils/strings.lua\")\n\n---@module 'component-explorer.utils.wiki'\nlocal wiki = dofile_once(\"mods/component-explorer/utils/wiki.lua\")\n\n---@module 'component-explorer.utils.player_util'\nlocal player_util = dofile_once(\"mods/component-explorer/utils/player_util.lua\")\n\n---@module 'component-explorer.utils.copy'\nlocal copy = dofile_once(\"mods/component-explorer/utils/copy.lua\")\n\n---@module 'component-explorer.preset_wands'\nlocal preset_wands = dofile_once(\"mods/component-explorer/preset_wands.lua\")\n\n---@module 'component-explorer.cursor'\nlocal cursor = dofile_once(\"mods/component-explorer/cursor.lua\")\n\n---@module 'component-explorer.utils.wiki_wand'\nlocal wiki_wand_util = dofile_once(\"mods/component-explorer/utils/wiki_wand.lua\")\n\ndofile_once(\"data/scripts/gun/procedural/wands.lua\")\n\nlocal wiki_wands = {}\nwiki_wands.open = false\n\nlocal _g_parsed_template = nil\n\nlocal function error_text(str)\n    imgui.PushStyleColor(imgui.Col.Text, unpack(style.colour_fail))\n    imgui.Text(str)\n    imgui.PopStyleColor()\nend\n\nlocal function show_range(type, field_name, template_values, range_values)\n    local item\n    for _, v in ipairs(template_values) do\n        if v[1] == field_name then\n            item = v\n            break\n        end\n    end\n    if item == nil then return end\n\n    local text_value = item[2]\n    local min, max = wiki_wand_util.field_range_value(text_value)\n\n    if min == max then\n        return\n    end\n\n    local value = range_values[field_name] or min\n\n    local _\n    imgui.SetNextItemWidth(200)\n    if type == \"f\" then\n        _, value = imgui.SliderFloat(field_name, value, min, max)\n    elseif type == \"i\" then\n        _, value = imgui.SliderInt(field_name, value, min, max)\n    end\n\n    range_values[field_name] = value\nend\n\nlocal range_values = {}\nlocal last_wand_card_template = nil\n\nlocal function confirm_wand_card_import(template_data)\n    if last_wand_card_template ~= template_data then\n        last_wand_card_template = template_data\n        range_values = {}\n    end\n\n    for _, field in ipairs(wiki_wand_util.FIELD_RANGES) do\n        local type, name = unpack(field)\n        show_range(type, name, template_data.values, range_values)\n    end\n\n    local create_in_inv = false\n    local create_at_pos = false\n    local x, y = 0, 0\n\n    local player = player_util.get_player()\n\n    if not player then imgui.BeginDisabled() end\n\n    if imgui.Button(\"Create at player\") then\n        assert(player)\n        create_at_pos = true\n        x, y = EntityGetTransform(player)\n    end\n\n    imgui.SameLine()\n    if imgui.Button(\"Put in inventory\") then\n        create_in_inv = true\n    end\n\n    if not player then imgui.EndDisabled() end\n\n    imgui.SameLine()\n    if imgui.Button(\"Create at cursor\") then\n        create_at_pos = true\n        x, y = cursor.pos()\n    end\n\n    if not create_in_inv and not create_at_pos then\n        return false\n    end\n\n    local ammended_data = copy.shallow_copy(template_data)\n    ammended_data.values = {}\n\n    -- Apply ranges and other fixups\n    for _, item_ in ipairs(template_data.values) do\n        local item = copy.shallow_copy(item_)\n        local name = item[1]\n\n        if wiki_wand_util.SUPPORTS_FIELD_RANGE[name] then\n            if range_values[name] then\n                item[2] = range_values[name]\n            elseif name == \"speed\" then\n                item[2] = wiki_wand_util.field_range_value(item[2])\n            end\n        end\n\n        table.insert(ammended_data.values, item)\n    end\n\n    local wand\n\n    if create_in_inv or create_at_pos then\n        wand = EZWand()\n        wand:UpdateSprite()\n        wiki_wand_util.load_data_to_wand(wand, ammended_data)\n    end\n\n    if create_in_inv then\n        local success = pcall(function()\n            wand:PutInPlayersInventory()\n        end)\n\n        if success then\n            return true\n        end\n\n        -- Couldn't put in inventory.. maybe the inventory is full or the player\n        -- is polymorphed.. Fall back to placing it at the player's position.\n        assert(player)\n        create_at_pos = true\n        x, y = EntityGetTransform(player)\n    end\n\n    if create_at_pos then\n        wand:PlaceAt(x, y)\n        return true\n    end\nend\n\nlocal function confirm_wand_import(template_data)\n    local wand\n\n    local currently_held = EZWand.GetHeldWand()\n    if not currently_held then imgui.BeginDisabled() end\n    if imgui.Button(\"Place in current wand\") then\n        wand = currently_held\n    end\n    if not currently_held then imgui.EndDisabled() end\n\n    for _, preset in ipairs(preset_wands) do\n        imgui.SameLine()\n        if imgui.Button(\"New \" .. preset.name) then\n            local px, py = 0, 0\n            local player = player_util.get_player()\n            if player then\n                px, py = EntityGetTransform(player)\n            end\n            wand = EZWand(preset.data)\n            wand:UpdateSprite()\n            wand:PlaceAt(px, py)\n        end\n    end\n\n    if wand then\n        wiki_wand_util.load_data_to_wand(wand, template_data)\n        return true\n    end\nend\n\nlocal import_text = \"\"\nlocal import_last_error = \"\"\n\nlocal function import_menu()\n    if imgui.Button(\"Clear\") then\n        import_text = \"\"\n    end\n\n    local template_changed\n    template_changed, import_text = imgui.InputTextMultiline(\"##Import\", import_text, -1, 0)\n\n    if string_util.trim(import_text) == \"\" then\n        return\n    end\n\n    if template_changed then\n        _g_parsed_template = nil\n        parse_success, parse_result = pcall(wiki.parse_template, import_text)\n        if not parse_success then\n            import_last_error = parse_result\n            return\n        end\n\n        import_last_error = \"\"\n        _g_parsed_template = parse_result\n    end\n\n    if _g_parsed_template then\n        local success, result = pcall(function()\n            local confirm_function\n            if _g_parsed_template.template_name == \"Wand Card\" then\n                confirm_function = confirm_wand_card_import\n            elseif _g_parsed_template.template_name == \"Wand\" then\n                confirm_function = confirm_wand_import\n            elseif _g_parsed_template.template_name == \"Wand2\" then\n                confirm_function = confirm_wand_card_import\n            else\n                error_text(\"Unknown template: '\" .. _g_parsed_template.template_name .. \"'\")\n                return\n            end\n\n            if confirm_function(_g_parsed_template) then\n                import_last_error = \"\"\n                import_text = \"\"\n            end\n        end)\n\n        if not success then\n            import_last_error = result\n        end\n    end\n\n    if import_last_error ~= \"\" then\n        if type(import_last_error) == \"table\" and import_last_error.error then\n            error_text(import_last_error.error)\n        else\n            error_text(tostring(import_last_error))\n        end\n    end\nend\n\n\nlocal function needs_wand()\n    imgui.PushStyleColor(imgui.Col.Text, unpack(style.colour_warn))\n    imgui.Text(\"No wand currently held\")\n    imgui.PopStyleColor()\nend\n\nlocal function legacy_template()\n    imgui.PushStyleColor(imgui.Col.Text, unpack(style.colour_warn))\n    imgui.Text(\"Consider using the Wand2 template instead of this legacy template.\")\n    imgui.PopStyleColor()\nend\n\nlocal wand2_wand_card = false\n\nlocal function wiki_wands_contents()\n    local wand = EZWand.GetHeldWand()\n\n    if not imgui.BeginTabBar(\"wiki_wand_tabs\") then\n        return\n    end\n\n    if imgui.BeginTabItem(\"Wand2\") then\n        if not wand then\n            needs_wand()\n        else\n            local _\n            _, wand2_wand_card = imgui.Checkbox(\"Wand Card\", wand2_wand_card)\n            local wand_text = wiki_wand_util.wand_to_wiki_text(wand, wand2_wand_card, true)\n            if imgui.Button(\"Copy\") then\n                imgui.SetClipboardText(wand_text)\n            end\n\n            imgui.Text(wand_text)\n        end\n        imgui.EndTabItem()\n    end\n\n    if imgui.BeginTabItem(\"Wand (old)\") then\n        legacy_template()\n        if not wand then\n            needs_wand()\n        else\n            local wand_text = wiki_wand_util.wand_to_wiki_text(wand, false)\n            if imgui.Button(\"Copy\") then\n                imgui.SetClipboardText(wand_text)\n            end\n\n            imgui.Text(wand_text)\n        end\n        imgui.EndTabItem()\n    end\n\n    if imgui.BeginTabItem(\"Wand Card (old)\") then\n        legacy_template()\n        if not wand then\n            needs_wand()\n        else\n            local wand_text = wiki_wand_util.wand_to_wiki_text(wand, true)\n            if imgui.Button(\"Copy\") then\n                imgui.SetClipboardText(wand_text)\n            end\n\n            imgui.Text(wand_text)\n        end\n        imgui.EndTabItem()\n    end\n\n    if imgui.BeginTabItem(\"Import\") then\n        import_menu()\n        imgui.EndTabItem()\n    end\n\n    if imgui.BeginTabItem(\"About\") then\n        imgui.TextWrapped(table.concat({\n            \"The Noita wiki (noita.wiki.gg) could use more inspiring wand builds and demo GIF's!\\n\",\n            \"Noita includes a built-in GIF recorder and this mod should make it easier to use the wand templates on the wiki.\",\n            \"\\n\\n\",\n            \"If you need help editing the wiki, you can visit the #noita-wiki channel in the Noita Discord server.\",\n            \"\\n\\n\",\n            \"To easily copy wands off of the Noita wiki, you can add the following line to your personal common.js file:\",\n        }))\n\n        local cjs_line = \"importScript('User:DexterCD/wandCopy.js');\"\n        imgui.BeginDisabled()\n        imgui.InputText(\"##cjs\", cjs_line)\n        imgui.EndDisabled()\n        imgui.SameLine()\n        if imgui.Button(\"Copy\") then\n            imgui.SetClipboardText(cjs_line)\n        end\n        link.text_link(\"Common.js\", \"https://noita.wiki.gg/wiki/Special:MyPage/common.js\")\n\n        imgui.EndTabItem()\n    end\n\n    imgui.EndTabBar()\nend\n\nfunction wiki_wands.show()\n    local should_show\n    should_show, wiki_wands.open = imgui.Begin(\"Wiki Wands\", wiki_wands.open)\n\n    if not should_show then\n        return\n    end\n\n    wiki_wands_contents()\n\n    imgui.End()\nend\n\nreturn wiki_wands\n"
_TWWE_VFS["mods/component-explorer/xml_fields.lua"] = "local xml_fields = {}\n\nfunction xml_fields.simple(name, value)\n    return {{name, value}}\nend\n\nfunction xml_fields.vec2(name, x, y)\n    return {\n        {name .. \".x\", x},\n        {name .. \".y\", y},\n    }\nend\n\nfunction xml_fields.aabb(name, min_x, max_x, min_y, max_y)\n    return {\n        {name .. \".min_x\", min_x},\n        {name .. \".max_x\", max_x},\n        {name .. \".min_y\", min_y},\n        {name .. \".max_y\", max_y},\n    }\nend\n\n-- Idea:\n-- Function to turn component into a big tree, e.g.\n-- {\n--   {\"hp\", 12},\n--   {\"swim_propel_amount\", 4},\n--   {\"evil_fx_material\", \"lava\"},\n-- }\n--\n-- We just run this on the default components and then have a function that\n-- compares the default and provided\n\nreturn xml_fields\n"
_TWWE_VFS["mods/component-explorer/xml_serialise.lua"] = "local nxml = dofile_once(\"mods/component-explorer/deps/nxml.lua\")\n\n---@module 'component-explorer.utils.ce_settings'\nlocal ce_settings = dofile_once(\"mods/component-explorer/utils/ce_settings.lua\")\n\nlocal xml_serialise = {}\n\nxml_serialise.use_tabs = ce_settings.get(\"xml_indent_char\") == \"tab\"\nxml_serialise.space_count = ce_settings.get(\"xml_space_count\")\nxml_serialise.include_privates = ce_settings.get(\"xml_include_privates\")\n\nfunction xml_serialise.button()\n    _, xml_serialise.use_tabs = imgui.Checkbox(\"Use tabs\", xml_serialise.use_tabs)\n    if not xml_serialise.use_tabs then\n        imgui.SameLine()\n        _, xml_serialise.space_count = imgui.SliderInt(\"Space Count\", xml_serialise.space_count, 1, 8)\n    end\n\n    _, xml_serialise.include_privates = imgui.Checkbox(\"Include privates\", xml_serialise.include_privates)\n\n    return imgui.Button(\"Copy XML (Beta)\")\nend\n\nfunction xml_serialise.indentation()\n    if xml_serialise.use_tabs then\n        return \"\\t\"\n    end\n\n    return string.rep(\" \", xml_serialise.space_count)\nend\n\nfunction xml_serialise.tostring(element)\n    return nxml.tostring(element, false, xml_serialise.indentation())\nend\n\nreturn xml_serialise\n"
