_TWWE_VFS["mods/death_cam/init.lua"] = "function OnPlayerDied(player_entity)\n	GameSetCameraFree(true)\n	ComponentSetValue2(EntityGetComponent(GameGetWorldStateEntity(), \"WorldStateComponent\")[1],\n		\"open_fog_of_war_everywhere\", true)\nend\n"
_TWWE_VFS["mods/death_cam/mod.xml"] = "\n<Mod\n	name=\"Death Cam\"\n	description=\"Gain freecam on death to look around!\"\n	request_no_api_restrictions=\"0\"	\n	is_game_mode=\"0\"\n	is_translation=\"0\"\n	ui_newgame_name=\"\"\n	ui_newgame_description=\"\"\n	ui_newgame_gfx_banner_bg=\"\"\n	ui_newgame_gfx_banner_fg=\"\"\n	translation_xml_path=\"\"\n	translation_csv_path=\"\"\n>\n</Mod>\n	"
