_TWWE_VFS["mods/nobys_things/mod_data/entities/buildings/debug_turret.xml"] = "<Entity tags=\"mortal,hittable,glue_NOT\" >	\n	<DamageModelComponent \n		hp=\"4000\"\n		ragdoll_material=\"steel\"\n		ragdoll_filenames_file=\"\" \n		blood_material=\"\"\n		fire_probability_of_ignition=\"0\" \n		air_needed=\"0\" >\n		<damage_multipliers\n			melee=\"0\"\n			projectile=\"0\"\n			explosion=\"0\"\n			electricity=\"0\"\n			fire=\"0\"\n			drill=\"0\"\n			slice=\"0\"\n			ice=\"0\"\n			healing=\"0\"\n			physics_hit=\"0\"\n			radioactive=\"0\"\n			poison=\"0\"\n			overeating=\"0\"\n			curse=\"0\"\n			>\n		</damage_multipliers>\n	</DamageModelComponent>\n\n	<SpriteComponent \n		image_file=\"mods/nobys_things/mod_data/images/entities_gfx/debug_turret.xml\" \n		special_scale_x=\"1\"\n		has_special_scale=\"1\"\n		offset_x=\"0\"\n		offset_y=\"0\" >\n	</SpriteComponent>\n\n	<SpriteAnimatorComponent>\n	</SpriteAnimatorComponent>\n	\n	<HitboxComponent \n		_enabled=\"1\" \n		aabb_min_x=\"-5\"\n		aabb_max_x=\"4\" \n		aabb_min_y=\"-5\"\n		aabb_max_y=\"5\" \n		>\n	</HitboxComponent>\n\n	<CameraBoundComponent\n		max_count=\"10\"\n		distance=\"160000\" >\n	</CameraBoundComponent>\n\n	<LuaComponent\n		script_source_file=\"mods/nobys_things/mod_data/scripts/buildings/debug_turret.lua\"\n		execute_every_n_frame=\"60\"\n		>\n	</LuaComponent>\n	\n	<VariableStorageComponent\n		name=\"projectile_file\"\n		value_string=\"data/entities/projectiles/deck/light_bullet.xml\"\n		>\n	</VariableStorageComponent>\n\n	<VariableStorageComponent\n		name=\"vel_x\"\n		value_int=\"0\"\n		>\n	</VariableStorageComponent>\n\n	<VariableStorageComponent\n		name=\"vel_y\"\n		value_int=\"600\"\n		>\n	</VariableStorageComponent>\n\n</Entity>"
_TWWE_VFS["mods/nobys_things/mod_data/entities/misc/cursor_follow.xml"] = "<Entity>\n    <InheritTransformComponent>\n    </InheritTransformComponent>\n\n    <LuaComponent\n		script_source_file=\"mods/nobys_things/mod_data/scripts/projectiles/cursor_follow.lua\"\n		execute_every_n_frame=\"1\"\n		>\n	</LuaComponent>\n\n	<ParticleEmitterComponent \n		_tags=\"autoaim_fx\"\n		_enabled=\"0\"\n		emitted_material_name=\"spark_white\"\n		offset.x=\"0\"\n		offset.y=\"0\"\n		gravity.y=\"50\"\n		x_vel_min=\"-8\"\n		x_vel_max=\"8\"\n		y_vel_min=\"-8\"\n		y_vel_max=\"8\"\n		count_min=\"10\"\n		count_max=\"15\"\n		lifetime_min=\"0.2\"\n		lifetime_max=\"0.8\"\n		emitter_lifetime_frames=\"4\"\n		create_real_particles=\"0\"\n		emit_cosmetic_particles=\"1\"\n		emission_interval_min_frames=\"1\"\n		emission_interval_max_frames=\"1\"\n		is_emitting=\"1\" >\n	</ParticleEmitterComponent>\n</Entity>\n"
