_TWWE_VFS["mods/nobys_things/mod_data/images/entities_gfx/debug_turret.xml"] = "<Sprite\n filename=\"mods/nobys_things/mod_data/images/entities_gfx/debug_turret.png\"\n offset_x=\"5.5\"\n offset_y=\"6.5\"\n default_animation=\"stand\" >\n\n <!-- animation -->\n <RectAnimation\n  name=\"stand\"\n  pos_x=\"0\"\n  pos_y=\"0\"\n  frame_count=\"8\"\n  frame_width=\"12\"\n  frame_height=\"12\"\n  frame_wait=\"0.1\"\n  frames_per_row=\"8\"\n  loop=\"1\"   >\n </RectAnimation>\n</Sprite>"
_TWWE_VFS["mods/nobys_things/mod_data/scripts/buildings/debug_turret.lua"] = "dofile_once(\"data/scripts/lib/utilities.lua\")\n\nlocal entity_id = GetUpdatedEntityID()\nx, y = EntityGetTransform( entity_id )\n\nlocal projectile_file\nlocal vel_x = 0\nlocal vel_y = 600\n\nlocal variablestorages = EntityGetComponent( entity_id, \"VariableStorageComponent\" )\n\nif ( variablestorages ~= nil ) then\n	for j,storage_id in ipairs(variablestorages) do\n		local var_name = ComponentGetValue2( storage_id, \"name\" )\n\n		if ( var_name == \"projectile_file\" ) then\n			projectile_file = ComponentGetValue2( storage_id, \"value_string\" )\n			if #projectile_file == 0 then\n				return\n			end\n		end\n\n		if ( var_name == \"vel_x\" ) then\n			vel_x = ComponentGetValue2( storage_id, \"value_int\" )\n		end\n\n		if ( var_name == \"vel_y\" ) then\n			vel_y = ComponentGetValue2( storage_id, \"value_int\" )\n		end\n	end\nend\n\nshoot_projectile( entity_id, projectile_file, x, y + 4, vel_x, vel_y )"
_TWWE_VFS["mods/nobys_things/mod_data/scripts/debug/aabb_visualizer.lua"] = "\n\nfunction visualize_entity(entity_id)\n	--* Rect Component types:\n	--* 	\"HitboxComponent\",\n	--* 	\"AreaDamageComponent\",\n	--* 	\"CharacterDataComponent\",\n	--* 	\"CollisionTriggerComponent\",\n	--* 	\"MaterialAreaCheckerComponent\",\n	local color = {}\n	color.rect = \"blue\"\n	--* Colors:\n	--*		\"red\"\n	--*		\"green\"\n	--*		\"blue\"\n	--*		\"yellow\"\n	--*		\"purple\"\n	--*		\"cyan\"\n	\n	local comps = EntityGetAllComponents(entity_id)\n	local comp_type\n	\n	if ( comps ~= nil ) then\n		for i,comp in ipairs( comps ) do\n			comp_type = ComponentGetTypeName(comp)\n			local aabb = {}\n			local skip_visualizer = false\n			local alpha = ComponentGetIsEnabled(comp) and 0.6 or 0.2\n			\n			--* SQUARES\n			\n			if comp_type == \"HitboxComponent\" then\n				color.rect= \"green\"\n				aabb.min_x = ComponentGetValue2(comp, \"aabb_min_x\")\n				aabb.min_y = ComponentGetValue2(comp, \"aabb_min_y\")\n				aabb.max_x = ComponentGetValue2(comp, \"aabb_max_x\") - 1\n				aabb.max_y = ComponentGetValue2(comp, \"aabb_max_y\") - 1\n			elseif comp_type == \"AreaDamageComponent\" then\n				color.rect= \"red\"\n				aabb.min_x, aabb.min_y = ComponentGetValue2(comp, \"aabb_min\")\n				aabb.max_x, aabb.max_y = ComponentGetValue2(comp, \"aabb_max\")\n				--? AreaDamageComponent scale is weird aff, not accurate at all\n				--? 	aabb.min_x = aabb.min_x / 3\n				--? 	aabb.min_y = aabb.min_y / 3\n				--? 	aabb.max_x = aabb.max_x / 3\n				--? 	aabb.max_y = aabb.max_y / 3\n			elseif comp_type == \"MaterialAreaCheckerComponent\" then\n				color.rect= \"cyan\"\n				aabb.min_x, aabb.min_y, aabb.max_x, aabb.max_y = ComponentGetValue2(comp, \"area_aabb\")\n			elseif comp_type == \"CharacterDataComponent\" then\n				color.rect= \"purple\"\n				aabb.min_x = ComponentGetValue2(comp, \"collision_aabb_min_x\")\n				aabb.min_y = ComponentGetValue2(comp, \"collision_aabb_min_y\")\n				aabb.max_x = ComponentGetValue2(comp, \"collision_aabb_max_x\")\n				aabb.max_y = ComponentGetValue2(comp, \"collision_aabb_max_y\")\n			elseif comp_type == \"CollisionTriggerComponent\" then\n				color.rect= \"yellow\"\n				local width = ComponentGetValue2(comp, \"width\")\n				local height = ComponentGetValue2(comp, \"height\")\n				aabb.min_x, aabb.min_y = -width / 2, -height / 2\n				aabb.max_x, aabb.max_y = width / 2, height / 2\n			else\n				skip_visualizer = true\n			end\n\n			if not skip_visualizer then\n				create_visualizer(entity_id, comp_type)\n				visualize_rectangle(visualizer_entity, aabb, color, alpha)\n				goto next_comp\n			end\n			\n			--* CIRCLES\n			\n			skip_visualizer = false\n\n			if comp_type == \"AreaDamageComponent\" then\n				aabb.radius = ComponentGetValue2(comp, \"circle_radius\")\n			else\n				skip_visualizer = true\n			end\n\n			local circles = {\n				\"CellEaterComponent\",\n				\"WormAttractorComponent\",\n				\"BlackHoleComponent\",\n				\"DamageNearbyEntitiesComponent\",\n				\"GameAreaEffectComponent\",\n				\"InteractableComponent\",\n				\"LightComponent\",\n				\"LiquidDisplacerComponent\",\n				\"MagicConvertMaterialComponent\",\n				\"MagicXRayComponent\",\n				\"CollisionTriggerComponent\",\n				\"ElectricityReceiverComponent\",\n				\"ElectricitySourceComponent\",\n				\"TelekinesisComponent\",\n			}\n			for i,circle in ipairs(circles) do\n				if comp_type == circle then\n					aabb.radius = ComponentGetValue2(comp, \"radius\")\n					skip_visualizer = false\n				end\n			end\n			\n			if not skip_visualizer then\n				color.R = 255\n				color.G = 0\n				color.B = 108\n				create_visualizer(entity_id, comp_type)\n				visualize_circle(visualizer_entity, aabb.radius, color, alpha)	\n			end\n\n			::next_comp::\n		end\n	end\nend\n\n\nfunction create_visualizer(entity_id, comp_type)\n	visualizer_entity = EntityCreateNew(\"aabb_visualizer: \" .. comp_type)\n	-- local x, y, rot = EntityGetTransform(entity_id)\n	-- EntitySetTransform(visualizer_entity, x, y, rot)\n	EntityAddTag(visualizer_entity, \"aabb_visualizer\")\n	EntityAddComponent2(visualizer_entity, \"InheritTransformComponent\", {\n		rotate_based_on_x_scale = false\n	})\n	EntityAddChild(entity_id, visualizer_entity)\nend\n\nfunction visualize_rectangle(visualizer_entity, aabb, color, alpha)\n	local width = aabb.max_x - aabb.min_x - 1\n	local height = aabb.max_y - aabb.min_y + 1\n\n	local image_path = \"mods/nobys_things/mod_data/images/debug_gfx/\" .. color.rect.. \".png\"\n\n	-- * HORIZONTAL LINE TOP\n	EntityAddComponent2(visualizer_entity, \"SpriteComponent\", {\n		image_file = image_path,\n		special_scale_x = width,\n		special_scale_y = 1,\n		offset_x = -(aabb.min_x + 1) / width,\n		offset_y = -aabb.min_y,\n		has_special_scale = true,\n		alpha = alpha,\n		z_index = -99,\n		smooth_filtering = true,\n	})\n\n	-- * HORIZONTAL LINE BOTTOM\n	EntityAddComponent2(visualizer_entity, \"SpriteComponent\", {\n		image_file = image_path,\n		special_scale_x = width,\n		special_scale_y = 1,\n		offset_x = -(aabb.min_x + 1) / width,\n		offset_y = -aabb.max_y,\n		has_special_scale = true,\n		alpha = alpha,\n		z_index = -99,\n		smooth_filtering = true,\n	})\n\n	-- * VERTICAL LINE LEFT\n	EntityAddComponent2(visualizer_entity, \"SpriteComponent\", {\n		image_file = image_path,\n		special_scale_x = 1,\n		special_scale_y = height,\n		offset_x = -aabb.min_x,\n		offset_y = -aabb.min_y / height,\n		has_special_scale = true,\n		alpha = alpha,\n		z_index = -99,\n		smooth_filtering = true,\n	})\n\n	-- * VERTICAL LINE RIGHT\n	EntityAddComponent2(visualizer_entity, \"SpriteComponent\", {\n		image_file = image_path,\n		special_scale_x = 1,\n		special_scale_y = height,\n		offset_x = -aabb.max_x,\n		offset_y = -aabb.min_y / height,\n		has_special_scale = true,\n		alpha = alpha,\n		z_index = -99,\n		smooth_filtering = true,\n	})\nend	\n	\nfunction visualize_circle(visualizer_entity, radius, color, alpha)\n	local colorInt = color.R + color.G*256 + color.B*256^2 + 255*256^3\n\n	local comp = EntityAddComponent2(visualizer_entity, \"ParticleEmitterComponent\", {\n		is_emitting = true,\n		emitted_material_name = \"spark\",\n		emit_cosmetic_particles = true,\n		collide_with_grid = false,\n		collide_with_gas_and_fire = false,\n		cosmetic_force_create = true,\n		custom_alpha = alpha,\n		color = colorInt,\n		lifetime_min = 0.001,\n		lifetime_max = 0.001,\n		x_vel_min = 0,\n		x_vel_max = 0,\n		y_vel_min = 0,\n		y_vel_max = 0,\n		count_min = math.min( math.ceil(40 * radius), 20000),\n		count_max = math.min( math.ceil(40 * radius), 20000),\n		emission_interval_min_frames = 1,\n		emission_interval_max_frames = 1,\n	})\n	ComponentSetValue2(comp, \"area_circle_radius\", radius, radius)\n	ComponentSetValue2(comp, \"gravity\", 0, 0)\nend"
_TWWE_VFS["mods/nobys_things/mod_data/scripts/gun/new_actions.lua"] = "local function table_insert_all (new_actions)\n	for i,v in ipairs(new_actions) do\n		table.insert (actions, v)\n	end\nend\n\nlocal new_actions = {\n	\n	--* MODIFIERS \n	\n	{\n		id          = \"FOLLOW_CURSOR\",\n		name 		= \"Cursor following\",\n		description = \"Makes a projectile follow your crosshair\",\n		sprite 		= \"mods/nobys_things/mod_data/images/ui_gfx/cursor_follow.png\",\n		sprite_unidentified = \"data/ui_gfx/gun_actions/sinewave_unidentified.png\",\n		related_extra_entities = \"mods/nobys_things/mod_data/entities/misc/cursor_follow.xml\",\n		type 		= ACTION_TYPE_MODIFIER,\n		spawn_level                       = \"1,2,3,4,5,6\", -- HOMING\n		spawn_probability                 = \"0.1,0.4,0.4,0.4,0.4,0.4\", -- HOMING\n		price = 220,\n		mana = 40,\n		action 		= function()\n			c.extra_entities = c.extra_entities .. \"mods/nobys_things/mod_data/entities/misc/cursor_follow.xml,\"\n			draw_actions( 1, true )\n		end,\n	},\n	{\n		id          = \"HOMING_CURSOR_REAL\",\n		name 		= \"Cursor homing\",\n		description = \"Makes a projectile accelerate towards your crosshair\",\n		sprite 		= \"mods/nobys_things/mod_data/images/ui_gfx/cursor_homing.png\",\n		sprite_unidentified = \"data/ui_gfx/gun_actions/sinewave_unidentified.png\",\n		related_extra_entities = \"mods/nobys_things/mod_data/entities/misc/cursor_homing.xml\",\n		type 		= ACTION_TYPE_MODIFIER,\n		spawn_level                       = \"1,2,3,4,5,6\", -- HOMING\n		spawn_probability                 = \"0.1,0.4,0.4,0.4,0.4,0.4\", -- HOMING\n		price = 220,\n		mana = 60,\n		action 		= function()\n			c.extra_entities = c.extra_entities .. \"mods/nobys_things/mod_data/entities/misc/cursor_homing.xml,\"\n			draw_actions( 1, true )\n		end,\n	},\n	{\n		id          = \"GRAVITY_DISABLE\",\n		name 		= \"Disable gravity\",\n		description = \"Makes projectile unaffected by gravity\",\n		sprite 		= \"mods/nobys_things/mod_data/images/ui_gfx/gravity_disable.png\",\n		sprite_unidentified = \"data/ui_gfx/gun_actions/i_shape_unidentified.png\",\n		type 		= ACTION_TYPE_MODIFIER,\n		spawn_level                       = \"2,3,4,5,6,10\", -- GRAVITY_ANTI\n		spawn_probability                 = \"0.5,0.4,0.4,0.3,0.3,0.3\", -- GRAVITY_ANTI\n		price = 30,\n		mana = 10,\n		--max_uses = 100,\n		action = function()\n			c.gravity = 0\n			c.extra_entities = c.extra_entities .. \"mods/nobys_things/mod_data/entities/misc/gravity_disable.xml,\"\n			draw_actions( 1, true )\n		end,\n	},\n	{\n		id          = \"PENETRATING_SHOT\",\n		name 		= \"Penetrating shot\",\n		description = \"Makes the projectile not die when colliding with enemies, but it can only hit each enemy once\",\n		sprite 		= \"mods/nobys_things/mod_data/images/ui_gfx/penetrating_shot.png\",\n		sprite_unidentified = \"data/ui_gfx/gun_actions/homing_unidentified.png\",\n		type 		= ACTION_TYPE_MODIFIER,\n		spawn_level                       = \"2,3,4,5,6\", -- PIERCING_SHOT\n		spawn_probability                 = \"0.4,0.5,0.6,0.6,0.4\", -- PIERCING_SHOT\n		price = 190,\n		mana = 80,\n		--max_uses = 100,\n		action 		= function()\n			c.extra_entities = c.extra_entities .. \"mods/nobys_things/mod_data/entities/misc/penetrating_shot.xml,\"\n			draw_actions( 1, true )\n		end,\n	},\n	{\n		id          = \"INFINITE_LIFETIME\",\n		name 		= \"Infinite lifetime\",\n		description = \"Makes projectile last forever\",\n		sprite 		= \"mods/nobys_things/mod_data/images/ui_gfx/infinite_lifetime.png\",\n		sprite_unidentified = \"data/ui_gfx/gun_actions/spread_reduce_unidentified.png\",\n		type 		= ACTION_TYPE_MODIFIER,\n		spawn_level                       = \"6,10\", -- LIFETIME\n		spawn_probability                 = \"0.1,0.1\", -- LIFETIME\n		price = 350,\n		mana = 120,\n		max_uses = 3,\n		custom_xml_file = \"data/entities/misc/custom_cards/lifetime_infinite.xml\",\n		action 		= function()\n			c.extra_entities = c.extra_entities .. \"mods/nobys_things/mod_data/entities/misc/infinite_lifetime.xml,data/entities/particles/tinyspark_yellow.xml,\"\n			c.fire_rate_wait = c.fire_rate_wait + 13\n			draw_actions( 1, true )\n		end,\n	},\n	\n	--* LOGIC SPELLS \n\n	{\n		id          = \"DRAW_EAT\",\n		name 		= \"Eat 1 draw\",\n		description = \"Takes 1 place in a multicast but self-discards\",\n		sprite 		= \"mods/nobys_things/mod_data/images/ui_gfx/eat_draw.png\",\n		sprite_unidentified = \"data/ui_gfx/gun_actions/i_shape_unidentified.png\",\n		type 		= ACTION_TYPE_OTHER,\n		spawn_level                       = \"10\",\n		spawn_probability                 = \"0.3\",\n		price = 30,\n		mana = 0,\n		--max_uses = 100,\n		action = function()\n			local data = hand[#hand]\n			if ( #hand > 0 ) and ( data ~= nil ) and ( data.id == \"DRAW_EAT\" ) then\n				table.insert( discarded, data )\n				table.remove( hand, #hand )\n			end\n		end,\n	},\n\n	{\n		id          = \"STOP_PROJECTILES\",\n		name 		= \"Stop projectiles\",\n		description = \"Prevents any projectiles after it from spawning\",\n		sprite 		= \"mods/nobys_things/mod_data/images/ui_gfx/stop_projectiles.png\",\n		sprite_unidentified = \"data/ui_gfx/gun_actions/i_shape_unidentified.png\",\n		type 		= ACTION_TYPE_OTHER,\n		spawn_level                       = \"10\",\n		spawn_probability                 = \"0.3\",\n		price = 0,\n		mana = 0,\n		--max_uses = 100,\n		action = function()\n			add_projectile(\"\")\n		end,\n	},\n}\n\ntable_insert_all(new_actions)"
_TWWE_VFS["mods/nobys_things/mod_data/scripts/projectiles/cursor_follow.lua"] = "dofile_once(\"data/scripts/lib/utilities.lua\")\n\nlocal range = 200\nlocal steering_strength = 0.2 -- how much to lerp towards target (0...1)\nlocal scatter = 0.1 -- how much the velocity direction is randomized. radians\n\nlocal entity_id = GetUpdatedEntityID()\nlocal pos_x, pos_y = EntityGetFirstHitboxCenter( entity_id )\n\n-- get shooter\nlocal comp = EntityGetFirstComponent( entity_id, \"ProjectileComponent\" )\nif comp == nil then return end\nlocal who_shot = ComponentGetValue2( comp, \"mWhoShot\")\n\n\nlocal cursor_x, cursor_y = DEBUG_GetMouseWorld()\n\n-- check los\n--if RaytraceSurfacesAndLiquiform(pos_x, pos_y, cursor_x, cursor_y) then return end\n\n-- direction\nlocal dir_x, dir_y = vec_sub(cursor_x, cursor_y, pos_x, pos_y)\ndir_x,dir_y = vec_normalize(dir_x, dir_y)\n\n-- get velocity and rotate it to align with ray\nlocal vel_x,vel_y = GameGetVelocityCompVelocity(entity_id)\nif vel_x == nil then return end\nlocal speed = get_magnitude(vel_x, vel_y)\n\n-- lerp direction and restore speed\nvel_x,vel_y = vec_normalize(vel_x, vel_y)\nvel_x = lerp(dir_x, vel_x, steering_strength)\nvel_y = lerp(dir_y, vel_y, steering_strength)\nvel_x,vel_y = vec_normalize(vel_x, vel_y)\nvel_x = vel_x * speed\nvel_y = vel_y * speed\n\n-- scatter\nSetRandomSeed(pos_x + GameGetFrameNum(), pos_y)\nvel_x,vel_y = vec_rotate(vel_x,vel_y, rand(-scatter, scatter))\n\n-- set velocity\ncomp = EntityGetFirstComponent( entity_id, \"VelocityComponent\" )\nComponentSetValueVector2( comp, \"mVelocity\", vel_x, vel_y)\n\n-- FX\nEntitySetComponentsWithTagEnabled( entity_id, \"autoaim_fx\", true )\n"
_TWWE_VFS["mods/nobys_things/mod_data/scripts/projectiles/cursor_homing.lua"] = "dofile_once(\"data/scripts/lib/utilities.lua\")\n\nlocal range = 200\nlocal steering_strength = 0.5 -- how much to lerp towards target (0...1)\n-- local scatter = 0.1 -- how much the velocity direction is randomized. radians\n\nlocal entity_id = GetUpdatedEntityID()\nlocal pos_x, pos_y = EntityGetFirstHitboxCenter( entity_id )\n\n-- get shooter\nlocal comp = EntityGetFirstComponent( entity_id, \"ProjectileComponent\" )\nif comp == nil then return end\nlocal who_shot = ComponentGetValue2( comp, \"mWhoShot\")\n\n\nlocal cursor_x, cursor_y = DEBUG_GetMouseWorld()\n\n-- check los\n--if RaytraceSurfacesAndLiquiform(pos_x, pos_y, cursor_x, cursor_y) then return end\n\n-- direction\nlocal dir_x, dir_y = vec_sub(cursor_x, cursor_y, pos_x, pos_y)\ndir_x,dir_y = vec_normalize(dir_x, dir_y)\n\n-- get velocity and rotate it to align with ray\nlocal vel_x,vel_y = GameGetVelocityCompVelocity(entity_id)\nif vel_x == nil then return end\nlocal speed = get_magnitude(vel_x, vel_y)\nspeed = speed + 7\n\n-- lerp direction and restore speed\nvel_x,vel_y = vec_normalize(vel_x, vel_y)\nvel_x = lerp(dir_x, vel_x, steering_strength)\nvel_y = lerp(dir_y, vel_y, steering_strength)\nvel_x,vel_y = vec_normalize(vel_x, vel_y)\nvel_x = vel_x * speed\nvel_y = vel_y * speed\n\n\n-- -- scatter\n-- SetRandomSeed(pos_x + GameGetFrameNum(), pos_y)\n-- vel_x,vel_y = vec_rotate(vel_x,vel_y, rand(-scatter, scatter))\n\n-- set velocity\ncomp = EntityGetFirstComponent( entity_id, \"VelocityComponent\" )\nComponentSetValueVector2( comp, \"mVelocity\", vel_x, vel_y)\n\n-- FX\nEntitySetComponentsWithTagEnabled( entity_id, \"autoaim_fx\", true )\n"
_TWWE_VFS["mods/nobys_things/mod_data/scripts/projectiles/gravity_disable.lua"] = "dofile_once(\"data/scripts/lib/utilities.lua\")\n\nlocal entity_id = GetUpdatedEntityID()  \n\nlocal comp = EntityGetFirstComponent( entity_id, \"VelocityComponent\" )\nif comp == nil then return end\n\nComponentSetValue2( comp, \"gravity_x\", 0)\nComponentSetValue2( comp, \"gravity_y\", 0)\n\n-- ComponentSetValue2( comp, \"mGravity\", gravity_x, gravity_y)\n\n"
_TWWE_VFS["mods/nobys_things/mod_data/scripts/projectiles/infinite_lifetime.lua"] = "dofile_once(\"data/scripts/lib/utilities.lua\")\n\nlocal entity_id = GetUpdatedEntityID()\nlocal x, y = EntityGetTransform( entity_id )\n\nentity_id = EntityGetRootEntity( entity_id )\n\n\nif ( entity_id ~= NULL_ENTITY ) then\n	edit_component( entity_id, \"ProjectileComponent\", function(comp,vars)\n		ComponentSetValue2( comp, \"lifetime\", -1 )\n	end)\n	\n	edit_component( entity_id, \"LifetimeComponent\", function(comp,vars)\n		ComponentSetValue2( comp, \"lifetime\", -1 )\n	end)\nend\n"
_TWWE_VFS["mods/nobys_things/mod_data/scripts/projectiles/penetrating_shot.lua"] = "dofile_once(\"data/scripts/lib/utilities.lua\")\n\nlocal entity_id    = GetUpdatedEntityID()\nlocal x, y = EntityGetTransform( entity_id )\n\nlocal parent_id = EntityGetParent( entity_id )\n\nlocal target_id = 0\n\nif ( parent_id ~= NULL_ENTITY ) then\n	target_id = parent_id\nelse\n	target_id = entity_id\nend\n\nif ( target_id ~= NULL_ENTITY ) then\n	local projectile_components = EntityGetComponent( target_id, \"ProjectileComponent\" )\n	\n	if( projectile_components == nil ) then return end\n	\n	if ( #projectile_components > 0 ) then\n		edit_component( target_id, \"ProjectileComponent\", function(comp,vars)\n			vars.penetrate_entities = 1\n		end)\n	end\nend\n"
_TWWE_VFS["mods/removable_perks/changelog.txt"] = "v0.5.16:\n- Add setting to add gravity to dropped perks\n\nv0.5.15:\n- FIX: Perks with 2 game effects (basically just Vampirism and Exploding Corpses) didn't have their second effect removed\n\nv0.5.14:\n- FIX: Minor bug with removing Leggy Mutation\n\nv0.5.13:\n- FIX: Updated \"Freeze Field\" perk removal function\n\nv0.5.12:\n- FIX: Updated \"No Wand Editing\" perk removal function\n\nv0.5.11:\n- FIX: Mod incompatibility with Apotheosis, Nightmare mode and Daily practice\n\nv0.5.10:\n- Empty game effect entities should now get removed, instead of just the components\n- FIX: Icons were not removed on the beta branch\n\nv0.5.9:\n- Disable GUI interactivity while gamepad is connected\n\nv0.5.8:\n- Add a mod setting to only show the button for opening the menu while the inventory is open.\n\nv0.5.7:\n- FIX: Extra health (One-off) infinite heal should no longer work\n \nv0.5.6:\n- FIX: Enemy spawn rates were severely reduced in nightmare mode for some stupid reason.\n- FIX: Berserk particle effect should get removed properly now.\n\nv0.5.5:\n- FIX: Removing Slime Blood or Oil Blood while also having Gas Blood would reduce gravity, as if picking up another Gas Blood.\n\nv0.5.4:\n- Don't drop \"Gamble\" or \"Summon Sädekivi (Mega Beam Stone)\" perks, to prevent abuse.\n\nv0.5.3:\n- Won't show tooltip of the open/close window button if a gamepad is active.\n\nv0.5.2:\n- Extra Mana and Extra Slots are irreversible, but the perk icon should still be removable (for perfectionists like me),\n  so now at least the perk doesn't drop anymore for abusing infinite mana/slot boosts.\n\nv0.5.1:\n- FIX: The following perks were not removed properly: Freeze Field, Gas Fire, Fungal Colony, Spontaneous Generation.\n\nv0.5.0:\n- Made the newest perks removable\n- Fixed a bunch of bugs\n- Mod no longer requires to be enabled from the start of the run\n\nv0.4.2:\n- FIX: Electricity perk was not being removed correctly.\n\nv0.4.1:\n- Make this mod compatible with the \"A lesson in every nugget\" mod.\n- FIX: Kill still existing homunculus when removing the homunculus perk.\n\nv0.4.0:\n- Upated for december 1st update\n- Changed the way perks are removed to a GUI which can be opened with a button right of the perk list\n- Removed the perk removal station\n\nv0.3.2:\n- Added perks from oct 29 update\n\nv0.3.1:\n- Compatibility update for Noita 1.0.\n\nv0.3.0:\n- \"Bleed Oil\" and \"Bleed Slime\" are now removable, removing one will apply the bleed effect which was picked last.\n  This means ALL vanilla perks are now removable!\n- Made mod compatible with mods that add custom UI icons like gokis champions mode\n- Reduced particle effect on removal\n- Perks on the remover station are now shown in order and display their index above them\n- FIX: The perk UI icons got shuffled after removing one, fixed that by rebuilding the entire list after every removal\n- FIX: Better tanksys_stacking_perk_icons mod compatibility\n\nv0.2.0:\n- Made the mod compatible with the tanksys_stacking_perk_icons mod\n- Interactions now play sounds\n- A particle effect now plays on perk removal\n- FIX: Berserk runes are now properly removed when removing critical plus\n- FIX: When removing a perk the display should now switch to the next perk correctly\n- FIX: Unremovable perks should no longer be switched to accidentally after removing a perk\n\nv0.1.0:\n- First release\n"
