_TWWE_VFS["mods/removable_perks/files/entity_definitions/dissolve_powders.lua"] = "local mats = {\"mud\",\"sand\",\"bone\",\"soil\",\"sandstone\",\"fungisoil\",\"snow\",\"snow_sticky\",\"sand_herb\",\"wax\",\"coal\",\"sulphur\",\"salt\",\"gunpowder\",\"gunpowder_explosive\",\"gunpowder_tnt\",\"gunpowder_unstable\",\"poo\",\"glass_broken\"}\n-- converts mats to material ids\nfor i, v in ipairs(mats) do\n  mats[i] = CellFactory_GetType(v)\nend\nreturn {\n  {\n    name = \"CellEaterComponent\",\n    values = {\n		  limited_materials=true,\n		  materials=mats\n    }\n  },\n}\n"
