_TWWE_VFS["mods/removable_perks/files/entity_definitions/pe_projectile_repulsion_field.lua"] = "return {\n  {\n    name = \"ParticleEmitterComponent\",\n    values = {\n      emitted_material_name=\"spark_purple\",\n      lifetime_min=0.06,\n      lifetime_max=0.12,\n      count_min=15,\n      count_max=25,\n      render_on_grid=true,\n      fade_based_on_lifetime=true,\n      area_circle_radius = { min = 50, max = 50 },\n      cosmetic_force_create=false,\n      airflow_force=0.3,\n      airflow_time=0.01,\n      airflow_scale=0.05,\n      emission_interval_min_frames=0,\n      emission_interval_max_frames=0,\n      emit_cosmetic_particles=true,\n    }\n  },\n  {\n    name = \"ParticleEmitterComponent\",\n    values = {\n      emitted_material_name=\"spark_purple\",\n      lifetime_min=0.4,\n      lifetime_max=0.7,\n      count_min=5,\n      count_max=10,\n      render_on_grid=true,\n      fade_based_on_lifetime=true,\n      cosmetic_force_create=false,\n      airflow_force=1.5,\n      airflow_time=1.9,\n      airflow_scale=0.15,\n      emission_interval_min_frames=1,\n      emission_interval_max_frames=1,\n      emit_cosmetic_particles=true,\n      draw_as_long=true,\n      x_vel_min=-1,\n      x_vel_max=1,\n      y_vel_min=-1,\n      y_vel_max=1,\n      is_emitting=true,\n      velocity_always_away_from_center=100,\n    }\n  },\n}\n"
