_TWWE_VFS["mods/removable_perks/files/get_perks.lua"] = "dofile_once(\"data/scripts/lib/utilities.lua\")\ndofile_once(\"data/scripts/perks/perk_list.lua\")\ndofile_once(\"mods/removable_perks/files/utils.lua\")\nlocal perk_id_lookup\n\nfunction build_unremovable_perks_table()\n  if not unremovable_perks then\n    unremovable_perks = {}\n    for i, action in ipairs(perk_list) do\n      if action.func and not action._remove then\n        -- print(tostring(action.id ) .. \" is unremovable!\" .. (\"!\"):rep(10))\n        unremovable_perks[action.id] = true\n      end\n    end\n  end\nend\n\n-- Returns a table of custom perk entries ordered by pickup order\nfunction get_active_perks()\n  build_unremovable_perks_table()\n  if not perk_id_lookup then\n    perk_id_lookup = dofile_once(\"mods/removable_perks/_virtual/perk_id_lookup.lua\")\n  end\n  local perks = {}\n  local players = EntityGetWithTag(\"player_unit\")\n  if #players > 0 then\n    for i, child in ipairs(EntityGetAllChildren(players[1]) or {}) do\n      -- Check whether it's a perk or something else (like gokis hero mode etc)\n      local ui_icon_component = EntityGetFirstComponentIncludingDisabled(child, \"UIIconComponent\")\n      if ui_icon_component then\n        local ui_description = ComponentGetValue2(ui_icon_component, \"description\")\n        local ui_name = ComponentGetValue2(ui_icon_component, \"name\")\n        local icon_sprite_file = ComponentGetValue2(ui_icon_component, \"icon_sprite_file\")\n        local perk_id = perk_id_lookup[ui_name]\n        local essence_id = ({\n          [\"$item_essence_fire\"] = \"fire\",\n          [\"$item_essence_air\"] = \"air\",\n          [\"$item_essence_water\"] = \"water\",\n          [\"$item_essence_laser\"] = \"laser\",\n          [\"$item_essence_alcohol\"] = \"alcohol\",\n        })[ui_name]\n        if (perk_id and not unremovable_perks[perk_id]) or essence_id then\n          table.insert(perks, {\n            id = perk_id or essence_id,\n            ui_name = GameTextGetTranslatedOrNot(ui_name),\n            ui_description = ui_description,\n            ui_icon = icon_sprite_file,\n            perk_entity = child,\n            is_perk = not essence_id\n          })\n        end\n      end\n    end\n  end\n\n  return perks\nend\n"
_TWWE_VFS["mods/removable_perks/files/gui.lua"] = "dofile_once(\"data/scripts/lib/utilities.lua\")\nlocal utils = dofile_once(\"mods/removable_perks/files/utils.lua\")\ndofile_once(\"mods/removable_perks/files/get_perks.lua\")\n\nif not gui then\n  is_open = false\n  gui = GuiCreate()\nend\n\nfunction rebuild_perk_table()\n  perks = get_active_perks()\n  -- local already_encountered = {}\n  -- for i, perk in ipairs(perks) do\n  --   if already_encountered[perk.id] then\n  --     already_encountered[perk.id].count = (already_encountered[perk.id].count or 0) + 1\n  --   else\n  --     already_encountered[perk.id] = perk\n  --   end\n  -- end\nend\n\nlocal button_width = 16\nlocal button_height = 16\nlocal screen_w, screen_h = GuiGetScreenDimensions(gui)\nGuiStartFrame(gui)\nGuiOptionsAdd(gui, GUI_OPTION.NoPositionTween)\nif GameGetIsGamepadConnected() then\n  GuiOptionsAdd(gui, GUI_OPTION.NonInteractive)\nend\nlocal show_button_in_inventory_only = ModSettingGet(\"removable_perks.show_button_in_inventory_only\")\nlocal inventory_gui_comp\nlocal inventory_is_open\nif show_button_in_inventory_only then\n  local player = EntityGetWithTag(\"player_unit\")[1]\n  if player then\n    inventory_gui_comp = EntityGetFirstComponentIncludingDisabled(player, \"InventoryGuiComponent\")\n    inventory_is_open = ComponentGetValue2(inventory_gui_comp, \"mActive\")\n    if inventory_is_open and is_open then\n      is_open = false\n    end\n  end\nend\nif ((show_button_in_inventory_only and (inventory_is_open or is_open)) or not show_button_in_inventory_only) and GuiImageButton(gui, 2, screen_w - 28, 73, \"\", \"mods/removable_perks/files/open_menu_icon.png\") then\n  is_open = not is_open\n  if is_open then\n    rebuild_perk_table()\n    if show_button_in_inventory_only and inventory_gui_comp then\n      ComponentSetValue2(inventory_gui_comp, \"mActive\", false)\n    end\n  end\nend\nif not is_gamepad_active() then\n  GuiTooltip(gui, \"Remove perks\", \"Click to open/close a menu that lets you remove perks you have picked up.\")\nend\n\nlocal width = 180\nlocal window_x_percent = 50\nlocal window_y_percent = 30\n\nif is_open then\n  local animation_speed = 0.1\n  if tooltip and tooltip.title then\n    -- Perk description shown on hover\n    GuiAnimateBegin(gui)\n    GuiLayoutBeginVertical(gui, window_x_percent, window_y_percent)\n    GuiBeginAutoBox(gui)\n    GuiAnimateAlphaFadeIn(gui, 99998, animation_speed, 0.01, false)\n    GuiText(gui, -(width/2), -88, tooltip.title)\n    GuiColorSetForNextWidget(gui, 1, 1, 1, 0.6)\n    GuiText(gui, -(width/2), 0, tooltip.description)\n    GuiZSetForNextWidget(gui, 1)\n    GuiAnimateScaleIn(gui, 99999, animation_speed, false)\n    GuiEndAutoBoxNinePiece(gui, 5)\n    GuiLayoutEnd(gui)\n    GuiAnimateEnd(gui)\n  end\n  -- Perk picker window\n  GuiAnimateBegin(gui)\n  GuiAnimateAlphaFadeIn(gui, 99997, animation_speed, 0.01, false)\n  GuiAnimateScaleIn(gui, 99996, animation_speed, false)\n  GuiLayoutBeginVertical(gui, window_x_percent, window_y_percent)\n  tooltip = tooltip or {}\n  GuiBeginAutoBox(gui)\n  GuiZSetForNextWidget(gui, -2)\n  GuiText(gui, -(width/2), -50, \"Removable perks (click to remove):\")\n  local h = 0\n  if was_perk_removed then\n    rebuild_perk_table()\n  end\n  if #perks == 0 then\n    GuiZSetForNextWidget(gui, -2)\n    local no_perks_found_text = \"< No removable perks found >\"\n    GuiText(gui, -(width/2), 0, no_perks_found_text)\n    _, h = GuiGetTextDimensions(gui, no_perks_found_text)\n  end\n  GuiZSetForNextWidget(gui, -100)\n  GuiBeginScrollContainer(gui, 999, -(width/2), 2, width, 105 - h, true, -2, 0)\n  was_perk_removed = false\n  local something_hovered = false\n  for i=1,#perks do\n    local x = (i-1) % 10\n    local y = math.floor((i-1) / 10)\n    GuiZSetForNextWidget(gui, -101)\n    local clicked, right_clicked = GuiImageButton(gui, 600+i, x*18, y*18, \"\", perks[i].ui_icon)\n    local _, _, hovered = GuiGetPreviousWidgetInfo(gui)\n    something_hovered = something_hovered or hovered\n    local drop_perk = not (perks[i].id == \"EXTRA_MANA\" or perks[i].id == \"EXTRA_SLOTS\" or perks[i].id == \"GAMBLE\" or perks[i].id == \"MEGA_BEAM_STONE\")\n    if hovered and last_hovered ~= i then\n      last_hovered = i\n      -- TODO: Do some line wrapping for long descriptions?\n      local title = perks[i].ui_name\n      if not drop_perk then\n        title = title .. \" (Unremovable, REMOVE ICON ONLY)\"\n      end\n      tooltip = { title = title, description = perks[i].ui_description }\n    end\n    if clicked then\n      if perks[i].is_perk then\n        utils.remove_perk(perks[i], false, drop_perk)\n      else\n        utils.remove_essence(perks[i], false, true)\n      end\n      was_perk_removed = true\n      break\n    end\n  end\n  if not something_hovered or was_perk_removed then\n    tooltip = {}\n    last_hovered = nil\n  end\n  GuiEndScrollContainer(gui)\n\n  GuiEndAutoBoxNinePiece(gui, 5)\n  GuiLayoutEnd(gui)\n  GuiAnimateEnd(gui)\nend\n"
_TWWE_VFS["mods/removable_perks/files/perk_list_append.lua"] = "dofile_once(\"data/scripts/lib/utilities.lua\")\ndofile_once(\"mods/removable_perks/files/utils.lua\")\ndofile_once(\"mods/removable_perks/files/get_perks.lua\")\nlocal EZWand = dofile_once(\"mods/removable_perks/lib/EZWand.lua\")\n\nlocal perk_removal_functions = {\n  GOLD_IS_FOREVER = function(entity_id)\n    edit_component2(GameGetWorldStateEntity(), \"WorldStateComponent\", function(comp, vars)\n      vars.perk_gold_is_forever = false\n    end)\n  end,\n  TRICK_BLOOD_MONEY = function(entity_id)\n    edit_component2(GameGetWorldStateEntity(), \"WorldStateComponent\", function(comp, vars)\n      vars.perk_trick_kills_blood_money = false\n    end)\n  end,\n  EXPLODING_GOLD = function(entity_id)\n    GameRemoveFlagRun(\"exploding_gold\")\n  end,\n  FASTER_LEVITATION = function(entity_id)\n    edit_component2(entity_id, \"CharacterPlatformingComponent\", function(comp, vars)\n      vars.pixel_gravity = ComponentGetValue2(comp, \"pixel_gravity\") / 1.4\n    end)\n  end,\n  LOW_GRAVITY = function(entity_id)\n    edit_component2(entity_id, \"CharacterPlatformingComponent\", function(comp, vars)\n      vars.pixel_gravity = ComponentGetValue2(comp, \"pixel_gravity\") / 0.6\n    end)\n    local count = get_perk_active_count(entity_id, \"$perk_low_gravity\")\n    -- Remove script and tag if this is the last instance of the perk\n    if count == 1 then\n      EntityRemoveTag(entity_id, \"low_gravity\")\n      remove_component(entity_id, \"LuaComponent\", { script_source_file = \"data/scripts/perks/low_gravity.lua\" })\n    end\n  end,\n  HIGH_GRAVITY = function(entity_id)\n    edit_component2(entity_id, \"CharacterPlatformingComponent\", function(comp, vars)\n      vars.pixel_gravity = ComponentGetValue2(comp, \"pixel_gravity\") / 1.4\n    end)\n    local count = get_perk_active_count(entity_id, \"$perk_high_gravity\")\n    -- Remove script and tag if this is the last instance of the perk\n    if count == 1 then\n      EntityRemoveTag(entity_id, \"high_gravity\")\n      remove_component(entity_id, \"LuaComponent\", { script_source_file = \"data/scripts/perks/high_gravity.lua\" })\n    end\n  end,\n  BREATH_UNDERWATER = function(entity_id)\n    edit_component2(entity_id, \"CharacterPlatformingComponent\", function(comp, vars)\n      local swim_idle_buoyancy_coeff = {1.2, 0.72, 0.432, 0.2592, 0.15552, 0.093312, 0.0559872, 0.03359232, 0.02015538}\n      local swim_up_buoyancy_coeff = {0.9, 0.18, 0.036,0.0072,0.00144,0.000288,5.76e-005,1.152e-005,2.304e-006}\n      local swim_down_buoyancy_coeff = {0.7, 0.14, 0.028,0.0056,0.00112,0.000224,4.48e-005,8.96e-006,1.792e-006}\n      local swim_drag = {0.95, 1.01,1.01,1.01,1.01,1.01,1.01,1.01,1.01}\n      local swim_extra_horizontal_drag = {0.9, 1.01,1.01,1.01,1.01,1.01,1.01,1.01,1.01}\n      local count = get_perk_active_count(entity_id, \"$perk_breath_underwater\")\n      count = math.min(9, count)\n      vars.swim_idle_buoyancy_coeff = swim_idle_buoyancy_coeff[count]\n      vars.swim_up_buoyancy_coeff = swim_up_buoyancy_coeff[count]\n      vars.swim_down_buoyancy_coeff = swim_down_buoyancy_coeff[count]\n      vars.swim_drag = swim_drag[count]\n      vars.swim_extra_horizontal_drag = swim_extra_horizontal_drag[count]\n    end)\n  end,\n  STRONG_KICK = function(entity_id)\n    edit_component2(entity_id, \"KickComponent\", function(comp, vars)\n      vars.max_force = ComponentGetValue2(comp, \"max_force\") / 1.7\n      vars.player_kickforce = ComponentGetValue2(comp, \"player_kickforce\") / 1.7\n      vars.kick_damage = ComponentGetValue2(comp, \"kick_damage\") - 2.4\n      vars.kick_knockback = ComponentGetValue2(comp, \"kick_knockback\") - 250\n      vars.telekinesis_throw_speed = ComponentGetValue2(comp, \"telekinesis_throw_speed\") - 25\n      local str = ComponentGetValue2(comp, \"kick_entities\")\n      -- Make a new string up until the last \",\"\n      vars.kick_entities = str:sub(0, str:len() - (str:reverse():find(\",\") or 0))\n    end)\n    edit_component2(entity_id, \"TelekinesisComponent\", function(comp, vars)\n      vars.throw_speed = ComponentGetValue2(comp, \"throw_speed\") - 25\n    end)\n  end,\n  TELEKINESIS = function(entity_id)\n    EntityRemoveComponent(entity_id, EntityGetFirstComponentIncludingDisabled(entity_id, \"TelekinesisComponent\"))\n    EntityRemoveComponent(entity_id, EntityGetFirstComponentIncludingDisabled(entity_id, \"AudioLoopComponent\", \"sound_telekinesis_move\"))\n    EntityRemoveComponent(entity_id, EntityGetFirstComponentIncludingDisabled(entity_id, \"AudioLoopComponent\", \"sound_telekinesis_hold\"))\n    component_write(EntityGetFirstComponentIncludingDisabled(entity_id, \"KickComponent\" ), { can_kick = true })\n  end,\n  EXPLODING_CORPSES = function(entity_id)\n    add_halo_level(entity_id, 1)\n  end,\n  SAVING_GRACE = function(entity_id)\n    add_halo_level(entity_id, -1)\n  end,\n  INVISIBILITY = function(entity_id)\n    -- Use default removal function?\n    -- Set all player sprites back to alpha 1.0\n    local sprite_components = EntityGetComponent(entity_id, \"SpriteComponent\")\n    for i, comp in ipairs(sprite_components or {}) do\n      ComponentSetValue2(comp, \"alpha\", 1.0)\n      EntityRefreshSprite(entity_id, comp)\n    end\n  end,\n  GLOBAL_GORE = function(entity_id)\n    add_halo_level(entity_id, 1)\n  end,\n  LEVITATION_TRAIL = function(entity_id)\n    remove_component(entity_id, \"LuaComponent\", { script_source_file = \"data/scripts/perks/levitation_trail.lua\" })\n  end,\n  VAMPIRISM = function(entity_id)\n    edit_component2(entity_id, \"DamageModelComponent\", function(comp, vars)\n      local max_hp = ComponentGetValue2(comp, \"max_hp\") / 0.75\n      vars.max_hp = math.floor(max_hp * 25) / 25\n    end)\n    add_halo_level(entity_id, 1)\n  end,\n  EXTRA_HP = function(entity_id)\n    edit_component2(entity_id, \"DamageModelComponent\", function(comp, vars)\n      local old_max_hp = ComponentGetValue2(comp, \"max_hp\")\n      local current_hp = ComponentGetValue2(comp, \"hp\")\n      vars.max_hp = old_max_hp / 1.5\n      current_hp = math.max(current_hp - math.abs(vars.max_hp - old_max_hp), 1 / 25)\n      vars.hp = math.min(current_hp, vars.max_hp)\n    end)\n  end,\n  HEARTS_MORE_EXTRA_HP = function(entity_id)\n    local var_store = get_variable_storage_component(entity_id, \"hearts_more_extra_hp\")\n    if var_store then\n      EntityRemoveComponent(entity_id, var_store)\n    end\n  end,\n  GLASS_CANNON = function(entity_id)\n    edit_component2(entity_id, \"DamageModelComponent\", function(comp, vars)\n      vars.hp = 100 / 25\n      vars.max_hp = 100 / 25\n      vars.max_hp_cap = 0\n    end)\n  end,\n  RESPAWN = function(entity_id)\n    add_halo_level(entity_id, -1)\n  end,\n  FOOD_CLOCK = function(entity_id)\n    remove_component(entity_id, \"LuaComponent\", { script_source_file = \"data/scripts/perks/food_clock.lua\" })\n    remove_component(entity_id, \"ShotEffectComponent\", { extra_modifier = \"food_clock\" })\n    local comp = EntityGetFirstComponentIncludingDisabled(entity_id, \"IngestionComponent\")\n    if comp then\n      local ingestion_cooldown_delay_frames = {600,400}\n      local ingestion_reduce_every_n_frame = {5,3}\n      local ingestion_satiation_material_tag = {\"\", \"[food]\"}\n      local count = get_perk_active_count(entity_id, \"$perk_food_clock\")\n      count = math.min(2, count)\n      ComponentSetValue2(comp, \"ingestion_cooldown_delay_frames\", ingestion_cooldown_delay_frames[count])\n      ComponentSetValue2(comp, \"ingestion_reduce_every_n_frame\", ingestion_reduce_every_n_frame[count])\n      ComponentSetValue2(comp, \"ingestion_satiation_material_tag\", ingestion_satiation_material_tag[count])\n    end\n  end,\n  RADAR_ENEMY = function(entity_id)\n    remove_component(entity_id, \"LuaComponent\", { script_source_file = \"data/scripts/perks/radar.lua\" })\n  end,\n  WAND_RADAR = function(entity_id)\n    remove_component(entity_id, \"LuaComponent\", { script_source_file = \"data/scripts/perks/radar_wand.lua\" })\n  end,\n  ITEM_RADAR = function(entity_id)\n    remove_component(entity_id, \"LuaComponent\", { script_source_file = \"data/scripts/perks/radar_item.lua\" })\n  end,\n  MOON_RADAR = function(entity_id)\n    remove_component(entity_id, \"LuaComponent\", { script_source_file = \"data/scripts/perks/radar_moon.lua\" })\n  end,\n  MAP = function(entity_id)\n    kill_child_by_filename(entity_id, \"data/entities/misc/perks/map.xml\")\n  end,\n  TELEPORTITIS_DODGE = function(entity_id)\n    for i, child in ipairs(EntityGetAllChildren(entity_id)) do\n      if EntityHasTag(child, \"teleportitis_dodge\") then\n        EntityKill(child)\n        break\n      end\n    end\n  end,\n  NO_WAND_EDITING = function(entity_id)\n    edit_component2(GameGetWorldStateEntity(), \"WorldStateComponent\", function(comp, vars)\n      vars.perk_hp_drop_chance = ComponentGetValue2(comp, \"perk_hp_drop_chance\") - 20\n    end)\n  end,\n  WAND_EXPERIMENTER = function(entity_id)\n    remove_component(entity_id, \"LuaComponent\", { script_wand_fired = \"data/scripts/perks/wand_experimenter.lua\" })\n  end,\n  ADVENTURER = function(entity_id)\n    remove_component(entity_id, \"LuaComponent\", { script_source_file = \"data/scripts/perks/adventurer.lua\" })\n  end,\n  PROJECTILE_HOMING_SHOOTER = function(entity_id)\n    remove_component(entity_id, \"ShotEffectComponent\", { extra_modifier = \"projectile_homing_shooter\" })\n    remove_component(entity_id, \"ShotEffectComponent\", { extra_modifier = \"powerful_shot\" })\n  end,\n  UNLIMITED_SPELLS = function(entity_id)\n    edit_component2(GameGetWorldStateEntity(), \"WorldStateComponent\", function(comp, vars)\n      vars.perk_infinite_spells = false\n    end)\n  end,\n  FREEZE_FIELD = function(entity_id)\n    kill_child_by_filename(entity_id, \"data/entities/misc/perks/freeze_field.xml\")\n  end,\n  FIRE_GAS = function(entity_id)\n    kill_child_by_filename(entity_id, \"data/entities/misc/perks/fire_gas.xml\")\n  end,\n  DISSOLVE_POWDERS = function(entity_id)\n    kill_child_by_filename(entity_id, \"data/entities/misc/perks/dissolve_powders.xml\")\n  end,\n  BLEED_SLIME = function(entity_id, perk_entity)\n    apply_last_bleed_effect(entity_id, perk_entity)\n    edit_component2(entity_id, \"DamageModelComponent\", function(comp, vars)\n      local projectile_resistance = tonumber(ComponentObjectGetValue(comp, \"damage_multipliers\", \"projectile\"))\n      projectile_resistance = projectile_resistance / 0.75\n      ComponentObjectSetValue2(comp, \"damage_multipliers\", \"projectile\", projectile_resistance)\n    end)\n  end,\n  BLEED_OIL = function(entity_id, perk_entity)\n    apply_last_bleed_effect(entity_id, perk_entity)\n    edit_component2(entity_id, \"DamageModelComponent\", function(comp, vars)\n      local explosion_resistance = tonumber(ComponentObjectGetValue(comp, \"damage_multipliers\", \"explosion\"))\n      explosion_resistance = explosion_resistance / 0.6\n      ComponentObjectSetValue2(comp, \"damage_multipliers\", \"explosion\", explosion_resistance)\n    end)\n  end,\n  BLEED_GAS = function(entity_id, perk_entity)\n    apply_last_bleed_effect(entity_id, perk_entity)\n    edit_component2(entity_id, \"CharacterPlatformingComponent\", function(comp, vars)\n      vars.pixel_gravity = ComponentGetValue2(comp, \"pixel_gravity\") / 0.75\n    end)\n  end,\n  SHIELD = function(entity_id)\n    local shield_num = tonumber(GlobalsGetValue(\"PERK_SHIELD_COUNT\", \"0\"))\n    GlobalsSetValue(\"PERK_SHIELD_COUNT\", tostring(shield_num - 1))\n    local last_shield_id\n    -- Find the energy shield that was added last and remove it\n    for i, child in ipairs(EntityGetAllChildren(entity_id)) do\n      if EntityHasTag(child, \"energy_shield\") then\n        last_shield_id = child\n      end\n    end\n    if last_shield_id then\n      EntityKill(last_shield_id)\n    end\n  end,\n  REVENGE_EXPLOSION = function(entity_id)\n    remove_component(entity_id, \"LuaComponent\", { script_damage_received = \"data/scripts/perks/revenge_explosion.lua\" })\n    edit_all_components2(entity_id, \"DamageModelComponent\", function(comp, vars)\n      local explosion_resistance = tonumber(ComponentObjectGetValue(comp, \"damage_multipliers\", \"explosion\"))\n      explosion_resistance = explosion_resistance / 0.75\n      ComponentObjectSetValue2(comp, \"damage_multipliers\", \"explosion\", explosion_resistance)\n    end)\n  end,\n  REVENGE_TENTACLE = function(entity_id)\n    remove_component(entity_id, \"LuaComponent\", { script_damage_received = \"data/scripts/perks/revenge_tentacle.lua\" })\n  end,\n  REVENGE_RATS = function(entity_id)\n    remove_component(entity_id, \"LuaComponent\", { script_damage_received = \"data/scripts/perks/revenge_rats.lua\" })\n    local new_rattiness subtract_rattiness_level(entity_id)\n    if new_rattiness == 2 then\n      kill_child_by_name(entity_id, \"belt\")\n      edit_component2(entity_id, \"CharacterPlatformingComponent\", function(comp, vars)\n				local vel_x = math.abs(ComponentGetValue2(comp, \"velocity_max_x\")) / 1.15\n				vars.run_velocity = ComponentGetValue2(comp, \"run_velocity\") / 1.15\n				vars.velocity_min_x = -vel_x\n				vars.velocity_max_x = vel_x\n      end)\n    end\n    undo_perk_pickup_event(\"RAT\")\n  end,\n  REVENGE_BULLET = function(entity_id)\n    remove_component(entity_id, \"LuaComponent\", { script_damage_received = \"data/scripts/perks/revenge_bullet.lua\" })\n    edit_component2(entity_id, \"DamageModelComponent\", function(comp, vars)\n      local explosion_resistance = tonumber(ComponentObjectGetValue(comp, \"damage_multipliers\", \"explosion\"))\n      local projectile_resistance = tonumber(ComponentObjectGetValue(comp, \"damage_multipliers\", \"projectile\"))\n      explosion_resistance = explosion_resistance / 0.8\n      projectile_resistance = projectile_resistance / 0.8\n      ComponentObjectSetValue2(comp, \"damage_multipliers\", \"explosion\", explosion_resistance)\n      ComponentObjectSetValue2(comp, \"damage_multipliers\", \"projectile\", projectile_resistance)\n    end)\n  end,\n  ATTACK_FOOT = function(entity_id)\n    -- If this was the last perk = remove 4 walkers, remove climber, remove flag run ATTACK_FOOT_CLIMBER\n    -- If more than 1 remaining = remove 2 walkers, reduce limb length\n    -- If it's the last or second to last one remaining, remove lukkiness level\n    -- Always remove 1 attacker\n    local children_to_kill = {\n      { name = \"data/entities/misc/perks/attack_foot/limb_attacker.xml\", amount = 1 },\n    }\n    local remaining_count = get_perk_active_count(entity_id, \"$perk_attack_foot\")\n    if remaining_count == 1 then\n      table.insert(children_to_kill, { name = \"data/entities/misc/perks/attack_foot/limb_walker.xml\", amount = 4 })\n      table.insert(children_to_kill, { name = \"data/entities/misc/perks/attack_foot/limb_climb.xml\", amount = 1 })\n      GameRemoveFlagRun(\"ATTACK_FOOT_CLIMBER\")\n    else\n      table.insert(children_to_kill, { name = \"data/entities/misc/perks/attack_foot/limb_walker.xml\", amount = 2 })\n      -- Reduce limb length\n      for _, child in ipairs(EntityGetAllChildren(entity_id) or {}) do\n        if EntityHasTag(child, \"attack_foot_walker\") then\n          component_readwrite(EntityGetFirstComponent(child, \"IKLimbComponent\"), { length = 50 }, function(comp)\n            comp.length = comp.length / 1.5\n          end)\n        end\n      end\n    end\n    if remaining_count < 3 then\n      subtract_lukkiness_level(entity_id)\n    end\n    kill_children_by_filename(entity_id, children_to_kill)\n    edit_component2(entity_id, \"CharacterPlatformingComponent\", function(comp, vars)\n      local run_speed = ComponentGetValue2(comp, \"run_velocity\") / 1.25\n      local vel_x = math.abs(ComponentGetValue2(comp, \"velocity_max_x\")) / 1.25\n      ComponentSetValue2(comp, \"run_velocity\", run_speed)\n      ComponentSetValue2(comp, \"velocity_min_x\", -vel_x)\n      ComponentSetValue2(comp, \"velocity_max_x\", vel_x)\n      if remaining_count == 1 then\n        ComponentSetValue2(comp, \"pixel_gravity\", 350) -- TODO: Remove this once the IKLimbWalkerComponent bug is fixed (hopefully)\n      end\n    end)\n    undo_perk_pickup_event(\"LUKKI\")\n  end,\n  LEGGY_FEET = function(entity_id)\n    local children_to_kill = {\n      { name = \"data/entities/misc/perks/attack_leggy/leggy_limb_attacker.xml\", amount = 1 },\n    }\n    local remaining_count = get_perk_active_count(entity_id, \"$perk_leggy_feet\")\n    if remaining_count == 1 then\n      table.insert(children_to_kill, { name = \"data/entities/misc/perks/attack_leggy/leggy_limb_left.xml\", amount = 2 })\n      table.insert(children_to_kill, { name = \"data/entities/misc/perks/attack_leggy/leggy_limb_right.xml\", amount = 2 })\n      table.insert(children_to_kill, { name = \"data/entities/misc/perks/attack_foot/limb_climb.xml\", amount = 1 })\n      GameRemoveFlagRun(\"ATTACK_FOOT_CLIMBER\")\n    else\n      table.insert(children_to_kill, { name = \"data/entities/misc/perks/attack_leggy/leggy_limb_left.xml\", amount = 1 })\n      table.insert(children_to_kill, { name = \"data/entities/misc/perks/attack_leggy/leggy_limb_right.xml\", amount = 1 })\n      -- Reduce limb length\n      for _, child in ipairs(EntityGetAllChildren(entity_id) or {}) do\n        if EntityHasTag(child, \"leggy_foot_walker\") then\n          component_readwrite(EntityGetFirstComponent(child, \"IKLimbComponent\"), { length = 50 }, function(comp)\n            comp.length = comp.length / 1.5\n          end)\n        end\n      end\n    end\n    if remaining_count < 3 then\n      subtract_lukkiness_level(entity_id)\n    end\n    kill_children_by_filename(entity_id, children_to_kill)\n    edit_component2(entity_id, \"CharacterPlatformingComponent\", function(comp, vars)\n      local run_speed = ComponentGetValue2(comp, \"run_velocity\") / 1.25\n      local vel_x = math.abs(ComponentGetValue2(comp, \"velocity_max_x\")) / 1.25\n      ComponentSetValue2(comp, \"run_velocity\", run_speed)\n      ComponentSetValue2(comp, \"velocity_min_x\", -vel_x)\n      ComponentSetValue2(comp, \"velocity_max_x\", vel_x)\n      if remaining_count == 1 then\n        ComponentSetValue2(comp, \"pixel_gravity\", 350) -- TODO: Remove this once the IKLimbWalkerComponent bug is fixed (hopefully)\n      end\n    end)\n    undo_perk_pickup_event(\"LUKKI\")\n  end,\n  PLAGUE_RATS = function(entity_id)\n    remove_component(entity_id, \"LuaComponent\", { script_source_file = \"data/scripts/perks/plague_rats.lua\" })\n    subtract_rattiness_level(entity_id)\n    undo_perk_pickup_event(\"RAT\")\n  end,\n  VOMIT_RATS = function(entity_id)\n    kill_child_by_filename(entity_id, \"data/entities/misc/perks/vomit_rats.xml\")\n    subtract_rattiness_level(entity_id)\n    undo_perk_pickup_event(\"RAT\")\n  end,\n  CORDYCEPS = function(entity_id)\n    remove_component(entity_id, \"LuaComponent\", { script_source_file = \"data/scripts/perks/cordyceps.lua\" })\n    GameRemoveFlagRun(\"player_status_cordyceps\")\n    subtract_funginess_level(entity_id)\n    undo_perk_pickup_event(\"FUNGI\")\n  end,\n  MOLD = function(entity_id)\n    kill_child_by_filename(entity_id, \"data/entities/misc/perks/slime_fungus.xml\")\n    GameRemoveFlagRun(\"player_status_mold\")\n    subtract_funginess_level(entity_id)\n    undo_perk_pickup_event(\"FUNGI\")\n  end,\n  WORM_SMALLER_HOLES = function(entity_id)\n    remove_component(entity_id, \"LuaComponent\", { script_source_file = \"data/scripts/perks/worm_smaller_holes.lua\" })\n  end,\n  PROJECTILE_REPULSION = function(entity_id)\n    kill_child_by_filename(entity_id, \"data/entities/misc/perks/projectile_repulsion_field.xml\")\n    edit_component2(entity_id, \"DamageModelComponent\", function(comp, vars)\n      local projectile_resistance = ComponentObjectGetValue2(comp, \"damage_multipliers\", \"projectile\")\n      ComponentObjectSetValue2(comp, \"damage_multipliers\", \"projectile\", projectile_resistance / 1.26)\n    end)\n  end,\n  RISKY_CRITICAL = function(entity_id)\n    kill_child_by_filename(entity_id, \"data/entities/misc/perks/risky_critical.xml\")\n  end,\n  FUNGAL_DISEASE = function(entity_id)\n    kill_child_by_filename(entity_id, \"data/entities/misc/perks/fungal_disease.xml\")\n    GameRemoveFlagRun(\"player_status_fungal_disease\")\n    subtract_funginess_level(entity_id)\n    undo_perk_pickup_event(\"FUNGI\")\n  end,\n  PROJECTILE_SLOW_FIELD = function(entity_id)\n    kill_child_by_filename(entity_id, \"data/entities/misc/perks/projectile_slow_field.xml\")\n  end,\n  PROJECTILE_REPULSION_SECTOR = function(entity_id)\n    kill_child_by_filename(entity_id, \"data/entities/misc/perks/projectile_repulsion_sector.xml\")\n  end,\n  PROJECTILE_EATER_SECTOR = function(entity_id)\n    kill_child_by_filename(entity_id, \"data/entities/misc/perks/projectile_eater_sector.xml\")\n  end,\n  LOW_RECOIL = function(entity_id)\n    remove_component(entity_id, \"ShotEffectComponent\", { extra_modifier = \"low_recoil\" })\n  end,\n  ORBIT = function(entity_id)\n    remove_component(entity_id, \"LuaComponent\", { script_source_file = \"data/scripts/perks/orbit.lua\" })\n    edit_component2(entity_id, \"DamageModelComponent\", function(comp, vars)\n      local explosion_resistance = tonumber(ComponentObjectGetValue(comp, \"damage_multipliers\", \"explosion\"))\n      local projectile_resistance = tonumber(ComponentObjectGetValue(comp, \"damage_multipliers\", \"projectile\"))\n      explosion_resistance = explosion_resistance / 1.33\n      projectile_resistance = projectile_resistance / 1.33\n      ComponentObjectSetValue2(comp, \"damage_multipliers\", \"explosion\", explosion_resistance)\n      ComponentObjectSetValue2(comp, \"damage_multipliers\", \"projectile\", projectile_resistance)\n    end)\n  end,\n  ANGRY_GHOST = function(entity_id)\n    kill_child_by_filename(entity_id, \"data/entities/misc/perks/angry_ghost.xml\")\n    remove_component(entity_id, \"LuaComponent\", { script_wand_fired = \"data/scripts/perks/angry_ghost_shoot.lua\" })\n    local remaining_count = get_perk_active_count(entity_id, \"$perk_angry_ghost\")\n    if remaining_count == 1 then\n      GameRemoveFlagRun(\"player_status_angry_ghost\")\n      subtract_ghostness_level(entity_id)\n    end\n    undo_perk_pickup_event(\"GHOST\")\n  end,\n  HUNGRY_GHOST = function(entity_id)\n    kill_child_by_filename(entity_id, \"data/entities/misc/perks/hungry_ghost.xml\")\n    local remaining_count = get_perk_active_count(entity_id, \"$perk_hungry_ghost\")\n    if remaining_count == 1 then\n      GameRemoveFlagRun(\"player_status_hungry_ghost\")\n      subtract_ghostness_level(entity_id)\n    end\n    undo_perk_pickup_event(\"GHOST\")\n  end,\n  DEATH_GHOST = function(entity_id)\n    remove_component(entity_id, \"LuaComponent\", { script_source_file = \"data/scripts/perks/death_ghost.lua\" })\n    local remaining_count = get_perk_active_count(entity_id, \"$perk_death_ghost\")\n    if remaining_count == 1 then\n      GameRemoveFlagRun(\"player_status_death_ghost\")\n      subtract_ghostness_level(entity_id)\n    end\n    undo_perk_pickup_event(\"GHOST\")\n  end,\n  HOMUNCULUS = function(entity_id)\n    kill_child_by_filename(entity_id, \"data/entities/misc/perks/homunculus_spawner.xml\")\n    local homunculus = EntityGetWithName(\"$animal_homunculus\")\n    if homunculus > 0 then\n      EntityKill(homunculus)\n    end\n  end,\n  LUKKI_MINION = function(entity_id)\n    local x, y = EntityGetTransform(entity_id)\n    local lukkis = EntityGetInRadiusWithTag(x, y, 200, \"lukki\")\n    for i, lukki in ipairs(lukkis) do\n      if EntityGetName(lukki) == \"$perk_lukki_minion\" then\n        EntityKill(lukki)\n      end\n    end\n    remove_component(entity_id, \"VariableStorageComponent\", { name = \"owner_id\" })\n    local remaining_count = get_perk_active_count(entity_id, \"$perk_lukki_minion\")\n    if remaining_count == 1 then\n      GameRemoveFlagRun(\"player_status_lukki_minion\")\n      subtract_lukkiness_level(entity_id)\n    end\n    undo_perk_pickup_event(\"LUKKI\")\n  end,\n  ELECTRICITY = function(entity_id)\n    kill_child_by_filename(entity_id, \"data/entities/misc/perks/electricity.xml\")\n  end,\n  ATTRACT_ITEMS = function(entity_id)\n    remove_component(entity_id, \"LuaComponent\", { script_source_file = \"data/scripts/perks/attract_items.lua\" })\n    local distance_full = tonumber(GlobalsGetValue(\"PERK_ATTRACT_ITEMS_RANGE\", \"0\"))\n    distance_full = distance_full - 24\n    if distance_full >= 72 then\n      GlobalsSetValue(\"PERK_ATTRACT_ITEMS_RANGE\", tostring(distance_full))\n    else\n      GlobalsSetValue(\"PERK_ATTRACT_ITEMS_RANGE\", \"0\")\n    end\n  end,\n  EXTRA_KNOCKBACK = function(entity_id)\n    remove_component(entity_id, \"ShotEffectComponent\", { extra_modifier = \"extra_knockback\" })\n  end,\n  LOWER_SPREAD = function(entity_id)\n    remove_component(entity_id, \"ShotEffectComponent\", { extra_modifier = \"lower_spread\" })\n  end,\n  BOUNCE = function(entity_id)\n    remove_component(entity_id, \"ShotEffectComponent\", { extra_modifier = \"bounce\" })\n  end,\n  FAST_PROJECTILES = function(entity_id)\n    remove_component(entity_id, \"ShotEffectComponent\", { extra_modifier = \"fast_projectiles\" })\n  end,\n  ALWAYS_CAST = function(entity_id)\n    -- In case the currently active item is not a wand, just don't do anything\n    pcall(function()\n      local wand = EZWand(tonumber(find_the_wand_held(entity_id)))\n      local spells, attached_spells = wand:GetSpells()\n      wand:DetachSpells()\n      for i=1, #attached_spells-1 do\n        wand:AttachSpells(attached_spells[i].action_id)\n      end\n    end)\n  end,\n  EXTRA_MANA = function(entity_id) end,\n  NO_MORE_SHUFFLE = function(entity_id)\n    GlobalsSetValue(\"PERK_NO_MORE_SHUFFLE_WANDS\", \"0\")\n  end,\n  DUPLICATE_PROJECTILE = function(entity_id)\n    remove_component(entity_id, \"ShotEffectComponent\", { extra_modifier = \"duplicate_projectile\" })\n    edit_component2(entity_id, \"DamageModelComponent\", function(comp, vars)\n      local projectile_resistance = tonumber(ComponentObjectGetValue(comp, \"damage_multipliers\", \"projectile\"))\n      projectile_resistance = projectile_resistance / 1.25\n      ComponentObjectSetValue2(comp, \"damage_multipliers\", \"projectile\", projectile_resistance)\n    end)\n  end,\n  FASTER_WANDS = function(entity_id)\n    local x, y = EntityGetTransform(entity_id)\n    local wands = EntityGetInRadiusWithTag(x, y, 24, \"wand\")\n    for i,wand_id in ipairs(wands) do\n      local root_entity = EntityGetRootEntity(wand_id)\n      if root_entity == entity_id then\n        local wand = EZWand(wand_id)\n        wand.rechargeTime = (wand.rechargeTime + 5) / 0.8\n        wand.castDelay = (wand.castDelay + 5) / 0.8\n        wand.manaChargeSpeed = math.max(10, wand.manaChargeSpeed - 30)\n      end\n    end\n  end,\n  EXTRA_SLOTS = function(entity_id)\n    local x, y = EntityGetTransform(entity_id)\n    local wands = EntityGetInRadiusWithTag(x, y, 24, \"wand\")\n    for i,wand_id in ipairs(wands) do\n      local root_entity = EntityGetRootEntity(wand_id)\n      if root_entity == entity_id then\n        local wand = EZWand(wand_id)\n        local old_values = entity_retrieve_table(wand.entity_id, \"extra_slots_old_values\")\n        if old_values then\n          wand.capacity = tonumber(old_values.capacity)\n        end\n      end\n    end\n  end,\n  CONTACT_DAMAGE = function(entity_id)\n    kill_child_by_filename(entity_id, \"data/entities/misc/perks/contact_damage.xml\")\n  end,\n  EXTRA_PERK = function(entity_id)\n    local perk_count = tonumber(GlobalsGetValue( \"TEMPLE_PERK_COUNT\", \"3\"))\n    perk_count = perk_count - 1\n    GlobalsSetValue(\"TEMPLE_PERK_COUNT\", tostring(perk_count))\n  end,\n  PERKS_LOTTERY = function(entity_id)\n    local perk_destroy_chance = tonumber(GlobalsGetValue( \"TEMPLE_PERK_DESTROY_CHANCE\", \"100\"))\n    perk_destroy_chance = perk_destroy_chance * 2\n    GlobalsSetValue(\"TEMPLE_PERK_DESTROY_CHANCE\", to_string(perk_destroy_chance))\n  end,\n  GAMBLE = function(entity_id) end,\n  EXTRA_SHOP_ITEM = function(entity_id)\n    local shop_item_count = tonumber(GlobalsGetValue(\"TEMPLE_SHOP_ITEM_COUNT\", \"5\"))\n    shop_item_count = math.max(shop_item_count - 1, 5)\n    GlobalsSetValue(\"TEMPLE_SHOP_ITEM_COUNT\", tostring(shop_item_count))\n  end,\n  GENOME_MORE_HATRED = function(entity_id)\n    edit_component2(GameGetWorldStateEntity(), \"WorldStateComponent\", function(comp, vars)\n      vars.global_genome_relations_modifier = ComponentGetValue2(comp, \"global_genome_relations_modifier\") + 25\n    end)\n    add_halo_level(entity_id, 1)\n  end,\n  GENOME_MORE_LOVE = function(entity_id)\n    edit_component2(GameGetWorldStateEntity(), \"WorldStateComponent\", function(comp, vars)\n      vars.global_genome_relations_modifier = ComponentGetValue2(comp, \"global_genome_relations_modifier\") - 25\n    end)\n    add_halo_level(entity_id, -1)\n  end,\n  PEACE_WITH_GODS = function(entity_id)\n    GlobalsSetValue(\"TEMPLE_PEACE_WITH_GODS\", \"0\")\n    local steves = EntityGetWithTag(\"necromancer_shop\")\n    for i,steve in ipairs(steves) do\n      local game_effect_component = GameGetGameEffect(steve, \"CHARM\")\n      EntityRemoveComponent(steve, game_effect_component)\n    end\n    add_halo_level(entity_id, -1)\n  end,\n  MANA_FROM_KILLS = function(entity_id)\n    remove_component(entity_id, \"LuaComponent\", { script_source_file = \"data/scripts/perks/mana_from_kills.lua\" })\n  end,\n  ANGRY_LEVITATION = function(entity_id)\n    remove_component(entity_id, \"LuaComponent\", { script_source_file = \"data/scripts/perks/angry_levitation.lua\" })\n  end,\n  LASER_AIM = function(entity_id)\n    kill_child_by_filename(entity_id, \"data/entities/misc/perks/laser_aim.xml\")\n    remove_component(entity_id, \"ShotEffectComponent\", { extra_modifier = \"laser_aim\" })\n  end,\n  PERSONAL_LASER = function(entity_id)\n    kill_child_by_filename(entity_id, \"data/entities/misc/perks/personal_laser.xml\")\n    remove_component(entity_id, \"ShotEffectComponent\", { extra_modifier = \"slow_firing\" })\n  end,\n  MEGA_BEAM_STONE = function(entity_id) end,\n}\n\n-- Add the removal functions to the perks table\nfor i, perk in ipairs(perk_list) do\n  if perk_removal_functions[perk.id] then\n    perk._remove = perk_removal_functions[perk.id]\n  end\nend\n\nfunction remove_component(entity_id, component_name, check_for_vars)\n  for i, comp in ipairs(EntityGetComponentIncludingDisabled(entity_id, component_name) or {}) do\n    for var, value in pairs(check_for_vars) do\n      if ComponentGetValue2(comp, var) == value then\n        EntityRemoveComponent(entity_id, comp)\n        return\n      end\n    end\n  end\nend\n\nfunction get_perk_active_count(owner_entity, perk_name)\n  local count = 0\n  for i, child in ipairs(EntityGetAllChildren(owner_entity) or {}) do\n    local ui_icon_component = EntityGetFirstComponentIncludingDisabled(child, \"UIIconComponent\")\n    if ui_icon_component and (ComponentGetValue2(ui_icon_component, \"name\") == perk_name) then\n      count = count + 1\n    end\n  end\n  return count\nend\n\nfunction subtract_lukkiness_level(entity_id)\n	local lukkiness = tonumber(GlobalsGetValue(\"PLAYER_LUKKINESS_LEVEL\", \"0\"))\n	lukkiness = lukkiness - 1\n	GlobalsSetValue(\"PLAYER_LUKKINESS_LEVEL\", tostring(lukkiness))\n\n	if lukkiness == 2 then\n		EntitySetComponentsWithTagEnabled(entity_id, \"lukki_enable\", false)\n\n		local comp = EntityGetFirstComponentIncludingDisabled(entity_id, \"SpriteComponent\", \"lukki_disable\")\n		if comp then\n			ComponentSetValue2(comp, \"alpha\", 1.0)\n		end\n\n		local platformingcomponent = EntityGetFirstComponentIncludingDisabled(entity_id, \"CharacterPlatformingComponent\")\n    if platformingcomponent then\n      local run_speed = ComponentGetValue2(platformingcomponent, \"run_velocity\") / 1.1\n      local vel_x = math.abs(ComponentGetValue2(platformingcomponent, \"velocity_max_x\" )) / 1.1\n\n      local vel_x_min = 0 - vel_x\n      local vel_x_max = vel_x\n\n      ComponentSetValue2(platformingcomponent, \"run_velocity\", run_speed)\n      ComponentSetValue2(platformingcomponent, \"velocity_min_x\", vel_x_min)\n      ComponentSetValue2(platformingcomponent, \"velocity_max_x\", vel_x_max)\n    end\n	end\nend\n\nfunction subtract_rattiness_level(entity_id)\n  local rattiness = tonumber(GlobalsGetValue(\"PLAYER_RATTINESS_LEVEL\", \"0\"))\n  rattiness = rattiness - 1\n  GlobalsSetValue(\"PLAYER_RATTINESS_LEVEL\", tostring(rattiness))\n  if rattiness == 2 then\n    kill_child_by_name(entity_id, \"belt\")\n    edit_component2(entity_id, \"CharacterPlatformingComponent\", function(comp, vars)\n      local vel_x = math.abs(ComponentGetValue2(comp, \"velocity_max_x\")) / 1.15\n      vars.run_velocity = ComponentGetValue2(comp, \"run_velocity\") / 1.15\n      vars.velocity_min_x = -vel_x\n      vars.velocity_max_x = vel_x\n    end)\n  elseif get_rat_perk_count() == 0 then\n    local world_entity_id = GameGetWorldStateEntity()\n    if world_entity_id then\n      component_write(EntityGetFirstComponent(world_entity_id, \"WorldStateComponent\"), { perk_rats_player_friendly = false })\n    end\n  end\n  return rattiness\nend\n\nfunction subtract_funginess_level(entity_id)\n  local funginess = tonumber(GlobalsGetValue(\"PLAYER_FUNGAL_LEVEL\", \"0\"))\n  funginess = funginess - 1\n  GlobalsSetValue(\"PLAYER_FUNGAL_LEVEL\", tostring(funginess))\n  if funginess == 2 then\n		EntitySetComponentsWithTagEnabled(entity_id, \"player_hat\", false)\n		EntitySetComponentsWithTagEnabled(entity_id, \"player_hat2_shadow\", true)\n    edit_component2(entity_id, \"DamageModelComponent\", function(comp, vars)\n      local explosion_resistance = ComponentObjectGetValue2(comp, \"damage_multipliers\", \"explosion\")\n      ComponentObjectSetValue2(comp, \"damage_multipliers\", \"explosion\", explosion_resistance * 0.9)\n    end)\n  end\n  return funginess\nend\n\nfunction subtract_ghostness_level(entity_id)\n  local ghostness = tonumber(GlobalsGetValue(\"PLAYER_GHOSTNESS_LEVEL\", \"0\"))\n  ghostness = ghostness - 1\n  GlobalsSetValue(\"PLAYER_GHOSTNESS_LEVEL\", tostring(ghostness))\n  if ghostness == 2 then\n		kill_children_by_filename(entity_id, {\n      { name = \"data/entities/misc/perks/ghostly_ghost.xml\", amount = 1 },\n      { name = \"data/entities/misc/perks/tiny_ghost_extra.xml\", amount = 1 },\n    })\n    local character_data_component = EntityGetFirstComponentIncludingDisabled(entity_id, \"CharacterDataComponent\")\n    local fly_time = ComponentGetValue2(character_data_component, \"fly_recharge_spd\") / 1.15\n    ComponentSetValue2(character_data_component, \"fly_recharge_spd\", fly_time)\n  end\n  return ghostness\nend\n\nfunction get_rat_perk_count(entity_id)\n  -- local flag_name = get_perk_picked_flag_name(\"PLAGUE_RATS\")\n  -- local pickup_count = tonumber(GlobalsGetValue(flag_name .. \"_PICKUP_COUNT\", \"0\"))\n  -- local flag_name2 = get_perk_picked_flag_name(\"REVENGE_RATS\")\n  -- local pickup_count2 = tonumber(GlobalsGetValue(flag_name2 .. \"_PICKUP_COUNT\", \"0\"))\n  -- return pickup_count + pickup_count2\n\n  -- TODO: Use the commented out version instead?\n  return get_perk_active_count(entity_id, \"$perk_plague_rats\") + get_perk_active_count(entity_id, \"$perk_revenge_rats\")\nend\n\nfunction undo_perk_pickup_event(style)\n	local flag_name = string.upper(style) .. \"_PERK_TOTAL_COUNT\"\n	local count = tonumber(GlobalsGetValue(flag_name, \"0\"))\n	count = count - 1\n	GlobalsSetValue(flag_name, tostring(count))\nend\n\nfunction apply_last_bleed_effect(entity_id, this_perk_entity)\n  local active_perks = get_active_perks()\n  local bleed_perk_found = false\n  -- Iterate backwards to find the last item\n  for i=#active_perks,1,-1 do\n    local active_perk = active_perks[i]\n    if (active_perk.id == \"BLEED_OIL\" or active_perk.id == \"BLEED_SLIME\" or active_perk.id == \"BLEED_GAS\") and active_perk.perk_entity ~= this_perk_entity then\n      local perk = get_perk_with_id(perk_list, active_perk.id)\n      -- Disable these functions for the duration of the function call\n      local _ComponentObjectSetValue = ComponentObjectSetValue\n      local _ComponentSetValue2 = ComponentSetValue2\n      ComponentObjectSetValue = function() end\n      ComponentSetValue2 = function() end\n      perk.func(nil, entity_id)\n      ComponentObjectSetValue = _ComponentObjectSetValue\n      ComponentSetValue2 = _ComponentSetValue2\n      bleed_perk_found = true\n      break\n    end\n  end\n  -- If no more blood perks are active, return to normal blood\n  if not bleed_perk_found then\n    local damagemodels = EntityGetComponent(entity_id, \"DamageModelComponent\")\n    if damagemodels then\n      for i, damagemodel in ipairs(damagemodels) do\n        ComponentSetValue(damagemodel, \"blood_material\", \"blood_fading\")\n        ComponentSetValue(damagemodel, \"blood_spray_material\", \"blood\")\n        ComponentSetValue(damagemodel, \"blood_multiplier\", \"1.0\")\n        ComponentSetValue(damagemodel, \"blood_sprite_directional\", \"\")\n        ComponentSetValue(damagemodel, \"blood_sprite_large\", \"\")\n      end\n    end\n  end\nend\n"
_TWWE_VFS["mods/removable_perks/files/test_removal_functions.lua"] = "local new_entity = EntityCreateNew()\nEntityAddComponent2(new_entity, \"LuaComponent\", {\n  script_source_file=\"mods/removable_perks/files/test_removal_functions2.lua\",\n  vm_type=\"ONE_PER_COMPONENT_INSTANCE\",\n  enable_coroutines=true,\n  execute_on_added=true,\n  execute_every_n_frame=-1,\n  execute_times=1,\n})\n"
_TWWE_VFS["mods/removable_perks/files/test_removal_functions2.lua"] = "dofile_once(\"data/scripts/lib/coroutines.lua\")\ndofile_once(\"data/scripts/perks/perk.lua\")\ndofile_once(\"data/scripts/perks/perk_list.lua\")\ndofile_once(\"mods/removable_perks/files/get_perks.lua\")\nlocal utils = dofile_once(\"mods/removable_perks/files/utils.lua\")\n\nasync(function()\n  local players = EntityGetWithTag(\"player_unit\")\n  wait(60)\n  if #players > 0 then\n    local player = players[1]\n    for i, perk in ipairs(perk_list) do\n      perk_pickup(nil, player, perk.id, false, false, true)\n      -- wait(0)\n      -- perk_pickup(nil, player, perk.id, false, false, true)\n      -- wait(0)\n      -- perk_pickup(nil, player, perk.id, false, false, true)\n    end\n  end\n  wait(5)\n  local perks = get_active_perks()\n  for i, perk_ in ipairs(perks) do\n    wait(1)\n    local success, err = pcall(function()\n      -- print(\"Trying to remove perk: \" .. tostring(perk_.id))\n      utils.remove_perk(perk_, true)\n      -- print(\"Removed perk: \" .. tostring(perk_.id))\n    end)\n    if not success then\n      print(\"ERROOOOOR: \" .. err)\n    end\n  end\nend)\n"
_TWWE_VFS["mods/removable_perks/files/utils.lua"] = "dofile_once(\"data/scripts/perks/perk.lua\")\n\nfunction string_split(inputstr, sep)\n  sep = sep or \"%s\"\n  local t = {}\n  for str in string.gmatch(inputstr, \"([^\"..sep..\"]+)\") do\n    table.insert(t, str)\n  end\n  return t\nend\n\nfunction entity_store_table(entity_id, var_name, values)\n  local var_name = \"removable_perks_\" .. var_name\n  local var_store = get_variable_storage_component(entity_id, var_name)\n  local value_string = \"\"\n  for k, v in pairs(values) do\n    value_string = value_string .. k .. \";\" .. tostring(v) .. \";\"\n  end\n  -- Remove the last semicolon\n  value_string = value_string:sub(1, -2)\n  if var_store then\n    local old_value = ComponentGetValue2(var_store, \"value_string\")\n    ComponentSetValue2(var_store, \"value_string\", old_value .. \";\" .. value_string)\n  else\n    EntityAddComponent2(entity_id, \"VariableStorageComponent\", {\n      _tags = \"enabled_in_hand\",\n      name = var_name,\n      value_string = value_string\n    })\n  end\nend\n\nfunction entity_retrieve_table(entity_id, var_name, dont_remove_entries)\n  local var_name = \"removable_perks_\" .. var_name\n  local var_store = get_variable_storage_component(entity_id, var_name)\n  if var_store then\n    local out = {}\n    local values = string_split(ComponentGetValue2(var_store, \"value_string\"), \";\")\n    if #values == 0 then return end\n    local num_values = 0\n    for i=#values,1,-2 do\n      if out[values[i-1]] then\n        break\n      else\n        num_values = num_values + 1\n        out[values[i-1]] = values[i]\n      end\n    end\n\n    if not dont_remove_entries then\n      -- Rebuild the string with the last values chopped off\n      local new_value_string = \"\"\n      for i=1,#values-num_values*2 do\n        new_value_string = new_value_string .. values[i] .. \";\"\n      end\n      -- Remove the last semicolon\n      new_value_string = new_value_string:sub(1, -2)\n      if new_value_string == \"\" then\n        EntityRemoveComponent(entity_id, var_store)\n      else\n        ComponentSetValue2(var_store, \"value_string\", new_value_string)\n      end\n    end\n    return out\n  end\nend\n\nfunction kill_child_by_name(entity_id, name)\n  for i, child in ipairs(EntityGetAllChildren(entity_id)) do\n    if EntityGetName(child) == name then\n      EntityKill(child)\n      break\n    end\n  end\nend\n\nfunction is_table_content_equal(t1, t2)\n  return table.concat(t1, \",\") == table.concat(t2, \",\")\nend\n\nfunction is_value_equal(a, b)\n  if type(a) ~= type(b) then\n    return false\n  elseif type(a) == \"string\" or type(a) == \"boolean\" then\n    return a == b\n  end\n  return math.abs(a - b) < 0.00001\nend\n\nfunction is_component_value_equal(comp_id, prop, expected_value)\n  local prop_val1, prop_val2 = ComponentGetValue2(comp_id, prop)\n  if type(expected_value) == \"table\" then\n    if expected_value.min and expected_value.max then\n      if not is_value_equal(prop_val1, expected_value.min) or not is_value_equal(prop_val2, expected_value.max) then\n        return false\n      end\n    elseif not is_table_content_equal(prop_val1, expected_value) then\n      return false\n    end\n  elseif not is_value_equal(prop_val1, expected_value) then\n    return false\n  end\n  return true\nend\n\nfunction entity_has_components_with_values(entity, expected_components)\n  for _, expected_component in ipairs(expected_components) do\n    local comps = EntityGetComponentIncludingDisabled(entity, expected_component.name) or {}\n    if #comps == 0 then\n      return false\n    end\n    local found_component = false\n    for _, comp_id in ipairs(comps) do\n      local match = true\n      for prop, expected_value in pairs(expected_component.values or {}) do\n        match = match and is_component_value_equal(comp_id, prop, expected_value)\n      end\n      if match then\n        found_component = true\n        break\n      end\n    end\n    if not found_component then\n      return false\n    end\n  end\n  return true\nend\n\n-- BULLSHIT fucking workaround because EntityGetFilename stops working on child entities after a game restart\nfunction entity_is_filename(entity, filename)\n  -- If only it was this easy........\n  -- do return EntityGetFilename(entity) == filename end\n  local lookup = {\n    [\"data/entities/misc/perks/map.xml\"] = \"map.lua\",\n    [\"data/entities/particles/perks/projectile_repulsion_field.xml\"] = \"pe_projectile_repulsion_field.lua\",\n    [\"data/entities/particles/perks/critical_hit_boost.xml\"] = \"pe_critical_hit_boost.lua\",\n    [\"data/entities/misc/perks/projectile_repulsion_field.xml\"] = \"projectile_repulsion_field.lua\",\n    [\"data/entities/misc/perks/attack_foot/limb_attacker.xml\"] = \"attack_foot_limb_attacker.lua\",\n    [\"data/entities/misc/perks/attack_foot/limb_walker.xml\"] = \"attack_foot_limb_walker.lua\",\n    [\"data/entities/misc/perks/attack_foot/limb_climb.xml\"] = \"attack_foot_limb_climb.lua\",\n    [\"data/entities/misc/perks/attack_leggy/leggy_limb_attacker.xml\"] = \"attack_leggy_limb_attacker.lua\",\n    [\"data/entities/misc/perks/attack_leggy/leggy_limb_left.xml\"] = \"attack_leggy_limb_left.lua\",\n    [\"data/entities/misc/perks/attack_leggy/leggy_limb_right.xml\"] = \"attack_leggy_limb_right.lua\",\n    [\"data/entities/misc/perks/freeze_field.xml\"] = \"freeze_field.lua\",\n    [\"data/entities/misc/perks/fire_gas.xml\"] = \"fire_gas.lua\",\n    [\"data/entities/misc/perks/dissolve_powders.xml\"] = \"dissolve_powders.lua\",\n    [\"data/entities/misc/perks/vomit_rats.xml\"] = \"vomit_rats.lua\",\n    [\"data/entities/misc/perks/slime_fungus.xml\"] = \"slime_fungus.lua\",\n    [\"data/entities/misc/perks/risky_critical.xml\"] = \"risky_critical.lua\",\n    [\"data/entities/misc/perks/fungal_disease.xml\"] = \"fungal_disease.lua\",\n    [\"data/entities/misc/perks/projectile_slow_field.xml\"] = \"projectile_slow_field.lua\",\n    [\"data/entities/particles/perks/projectile_slow_field.xml\"] = \"pe_projectile_slow_field.lua\",\n    [\"data/entities/misc/perks/projectile_repulsion_sector.xml\"] = \"projectile_repulsion_sector.lua\",\n    [\"data/entities/misc/perks/projectile_eater_sector.xml\"] = \"projectile_eater_sector.lua\",\n    [\"data/entities/misc/perks/angry_ghost.xml\"] = \"angry_ghost.lua\",\n    [\"data/entities/misc/perks/hungry_ghost.xml\"] = \"hungry_ghost.lua\",\n    [\"data/entities/misc/perks/homunculus_spawner.xml\"] = \"homunculus_spawner.lua\",\n    [\"data/entities/misc/perks/electricity.xml\"] = \"electricity.lua\",\n    [\"data/entities/misc/perks/contact_damage.xml\"] = \"contact_damage.lua\",\n    [\"data/entities/misc/perks/laser_aim.xml\"] = \"laser_aim.lua\",\n    [\"data/entities/misc/perks/personal_laser.xml\"] = \"personal_laser.lua\",\n    [\"data/entities/misc/perks/ghostly_ghost.xml\"] = \"ghostly_ghost.lua\",\n    [\"data/entities/misc/perks/tiny_ghost_extra.xml\"] = \"tiny_ghost_extra.lua\",\n    [\"data/entities/misc/essences/air.xml\"] = \"essence_air.lua\",\n    [\"data/entities/misc/essences/fire.xml\"] = \"essence_fire.lua\",\n    [\"data/entities/misc/essences/alcohol.xml\"] = \"essence_alcohol.lua\",\n    [\"data/entities/misc/essences/water.xml\"] = \"essence_water.lua\",\n    [\"data/entities/misc/essences/laser.xml\"] = \"essence_laser.lua\",\n  }\n  if not lookup[filename] then\n    print(\"<Removable perks> - Missing entity definition for: \" .. tostring(filename))\n    return false\n  end\n  return entity_has_components_with_values(entity, dofile_once(\"mods/removable_perks/files/entity_definitions/\" .. lookup[filename]))\nend\n\nfunction kill_child_by_filename(entity_id, filename)\n  for i, child in ipairs(EntityGetAllChildren(entity_id)) do\n    if entity_is_filename(child, filename) then\n      EntityKill(child)\n      break\n    end\n  end\nend\n\nfunction kill_children_by_filename(entity_id, names)\n  local already_killed = {}\n  for _, child in ipairs(EntityGetAllChildren(entity_id) or {}) do\n    for _, name_amount in ipairs(names) do\n      if not already_killed[child] and name_amount.amount > 0 and entity_is_filename(child, name_amount.name) then\n				name_amount.amount = name_amount.amount - 1\n        -- print(\"Killing \" .. tostring(name_amount.name) .. \" with id \" .. tostring(child))\n        already_killed[child] = true\n        EntityKill(child)\n      end\n    end\n  end\nend\n\nlocal function remove_perk(perk_, silent, drop_perk)\n  local player = EntityGetWithTag(\"player_unit\")[1]\n  if not player then\n    return\n  end\n  local perk = get_perk_with_id(perk_list, perk_.id)\n  local flag_name = get_perk_picked_flag_name(perk_.id)\n	local pickup_count = tonumber(GlobalsGetValue(flag_name .. \"_PICKUP_COUNT\", \"0\"))\n  pickup_count = pickup_count - 1\n	GlobalsSetValue(flag_name .. \"_PICKUP_COUNT\", tostring(pickup_count))\n\n  -- Remove run flags if this is the last perk instance\n  if pickup_count == 0 then\n    GameRemoveFlagRun(flag_name)\n    for i,other_perk_id in ipairs(perk.remove_other_perks or {}) do\n      GameRemoveFlagRun(get_perk_picked_flag_name(other_perk_id))\n    end\n  end\n\n  local function kill_child_entity_with_game_effect(game_effect)\n    if game_effect then\n      local game_effect_component = GameGetGameEffect(player, game_effect)\n      if game_effect_component then\n        for i, child in ipairs(EntityGetAllChildren(player) or {}) do\n          for i2, component in ipairs(EntityGetComponentIncludingDisabled(child, \"GameEffectComponent\") or {}) do\n            if component == game_effect_component then\n              EntityKill(child)\n              return\n            end\n          end\n        end\n      end\n    end\n  end\n  kill_child_entity_with_game_effect(perk.game_effect)\n  kill_child_entity_with_game_effect(perk.game_effect2)\n  if perk.particle_effect then\n		kill_child_by_filename(player, (\"data/entities/particles/perks/%s.xml\"):format(perk.particle_effect))\n	end\n  if perk._remove then\n    perk._remove(player, perk_.perk_entity)\n  end\n  -- Workaround for a bug, entities without component cannot be EntityKilled\n  -- and apparently UIIconComponent doesn't really count as a component\n  EntityAddComponent2(perk_.perk_entity, \"LifetimeComponent\", { lifetime = 1 })\n  if not silent then\n    GamePrint(\"Removed perk: \" .. GameTextGetTranslatedOrNot(perk.ui_name))\n    local x, y = EntityGetTransform(player)\n    GamePlaySound(\"data/audio/Desktop/event_cues.snd\", \"event_cues/chest/create\", x, y)\n  end\n  if drop_perk then\n    local x, y = EntityGetTransform(player)\n    local perk_entity = perk_spawn(x, y - 5, perk_.id)\n    EntityAddComponent2(perk_entity, \"VariableStorageComponent\", {\n      name = \"perk_dont_remove_others\",\n      value_bool = true\n    })\n    if ModSettingGet(\"removable_perks.add_gravity\") then\n      EntityAddComponent2(perk_entity, \"SimplePhysicsComponent\", {\n        _tags=\"enabled_in_world\"\n      })\n      EntityAddComponent2(perk_entity, \"VelocityComponent\", {\n        _tags=\"enabled_in_world\"\n      })\n    end\n  end\nend\n\nlocal function remove_essence(essence, silent, drop_essence)\n  local player = EntityGetWithTag(\"player_unit\")[1]\n  if not player then\n    return\n  end\n  if essence.id == \"fire\" then\n    local damage_model_component = EntityGetFirstComponentIncludingDisabled(player, \"DamageModelComponent\")\n    local projectile_resistance = ComponentObjectGetValue2(damage_model_component, \"damage_multipliers\", \"projectile\")\n    local explosion_resistance = ComponentObjectGetValue2(damage_model_component, \"damage_multipliers\", \"explosion\")\n    ComponentObjectSetValue2(damage_model_component, \"damage_multipliers\", \"projectile\", projectile_resistance / 1.3)\n    ComponentObjectSetValue2(damage_model_component, \"damage_multipliers\", \"explosion\", explosion_resistance / 1.3)\n  end\n\n  kill_child_by_filename(player, \"data/entities/misc/essences/\" .. essence.id .. \".xml\")\n\n  GameRemoveFlagRun(\"essence_\" .. essence.id)\n	local globalskey = \"ESSENCE_\" .. string.upper(essence.id) .. \"_PICKUP_COUNT\"\n	local pickups = tonumber(GlobalsGetValue(globalskey, \"0\"))\n	pickups = pickups - 1\n	GlobalsSetValue(globalskey, tostring(pickups))\n\n  EntityKill(essence.perk_entity)\n  if not silent then\n    GamePrint(\"Removed essence: \" .. GameTextGetTranslatedOrNot(essence.ui_name))\n    local x, y = EntityGetTransform(player)\n    GamePlaySound(\"data/audio/Desktop/event_cues.snd\", \"event_cues/chest/create\", x, y)\n  end\n  if drop_essence then\n    local x, y = EntityGetTransform(player)\n    EntityLoad(\"data/entities/items/pickup/essence_\" .. essence.id .. \".xml\", x, y - 5)\n  end\nend\n\nfunction is_gamepad_active()\n	local players = EntityGetWithTag(\"player_unit\")\n	for i, player in ipairs(players) do\n		local platform_shooter_player = EntityGetFirstComponentIncludingDisabled(player, \"PlatformShooterPlayerComponent\")\n		if platform_shooter_player then\n			local is_gamepad = ComponentGetValue2(platform_shooter_player, \"mHasGamepadControlsPrev\")\n			if is_gamepad then\n        return true\n			end\n		end\n	end\nend\n\nreturn {\n  remove_perk = remove_perk,\n  remove_essence = remove_essence,\n}\n"
