_TWWE_VFS["mods/spell_lab_shugged/files/entities/flight_overwritten_values.xml"] = "<Entity name=\"spell_lab_shugged_flight_overwritten_values\" >\n	<InheritTransformComponent/>\n	<CharacterPlatformingComponent _enabled=\"0\" />\n</Entity>"
_TWWE_VFS["mods/spell_lab_shugged/files/entities/hp_fixer.lua"] = "dofile_once( \"data/scripts/lib/utilities.lua\" )\nlocal entity_id = GetUpdatedEntityID()\nlocal player_id = EntityGetParent( entity_id )\nlocal damage_model = EntityGetFirstComponentIncludingDisabled( player_id, \"DamageModelComponent\" )\nif not damage_model then return end\nlocal hp_comp = get_variable_storage_component( entity_id, \"hp\" )\nlocal max_hp_comp = get_variable_storage_component( entity_id, \"max_hp\" )\nif not hp_comp or not max_hp_comp then\n	hp = ComponentGetValue2( damage_model, \"hp\" )\n	max_hp = ComponentGetValue2( damage_model, \"max_hp\" )\n	EntityAddComponent2( entity_id, \"VariableStorageComponent\", { name = \"hp\", value_float = hp } )\n	EntityAddComponent2( entity_id, \"VariableStorageComponent\", { name = \"max_hp\", value_float = max_hp } )\n	local wait_for_kill_flag_on_death = ComponentGetValue2( damage_model, \"wait_for_kill_flag_on_death\" )\n	EntityAddComponent2( entity_id, \"VariableStorageComponent\",\n		{ name = \"wait_for_kill_flag_on_death\", value_bool = wait_for_kill_flag_on_death } )\n	ComponentSetValue2( damage_model, \"wait_for_kill_flag_on_death\", true )\n	return\nend\nlocal hp = ComponentGetValue2( hp_comp, \"value_float\" )\nlocal max_hp = ComponentGetValue2( max_hp_comp, \"value_float\" )\nComponentSetValue2( damage_model, \"hp\", hp )\nComponentSetValue2( damage_model, \"max_hp\", max_hp )"
_TWWE_VFS["mods/spell_lab_shugged/files/entities/hp_fixer.xml"] = "<Entity name=\"spell_lab_shugged_hp_fixer\" >\n	<LuaComponent\n		script_source_file=\"mods/spell_lab_shugged/files/entities/hp_fixer.lua\"\n		execute_every_n_frame=\"1\">\n	</LuaComponent>\n	<LuaComponent\n		script_source_file=\"mods/spell_lab_shugged/files/entities/hp_fixer_removed.lua\"\n		execute_on_removed=\"1\"\n		execute_every_n_frame=\"-1\">\n	</LuaComponent>\n</Entity>"
_TWWE_VFS["mods/spell_lab_shugged/files/entities/hp_fixer_removed.lua"] = "dofile_once( \"data/scripts/lib/utilities.lua\" )\nlocal entity_id = GetUpdatedEntityID()\nlocal player_id = EntityGetParent( entity_id )\nlocal comp = get_variable_storage_component( entity_id, \"wait_for_kill_flag_on_death\" )\nif not comp then return end\nlocal damage_model = EntityGetFirstComponentIncludingDisabled( player_id, \"DamageModelComponent\" )\nif not damage_model then return end\nlocal wait_for_kill_flag_on_death = ComponentGetValue2( comp, \"value_bool\" )\nComponentSetValue2( damage_model, \"wait_for_kill_flag_on_death\", wait_for_kill_flag_on_death )"
_TWWE_VFS["mods/spell_lab_shugged/files/entities/low_hp_triggerer.lua"] = "local root_id = EntityGetRootEntity( GetUpdatedEntityID() )\nif not EntityHasTag( root_id, \"player_unit\" ) then return end\nlocal damage_model = EntityGetFirstComponentIncludingDisabled( root_id, \"DamageModelComponent\" )\nif not damage_model then return end\nlocal max_hp = ComponentGetValue2( damage_model, \"max_hp\" )\nComponentSetValue2( damage_model, \"hp\", max_hp * 0.2 )"
_TWWE_VFS["mods/spell_lab_shugged/files/entities/low_hp_triggerer.xml"] = "<Entity>\n	<InheritTransformComponent/>\n	<LuaComponent\n		script_source_file=\"mods/spell_lab_shugged/files/entities/low_hp_triggerer.lua\"\n		execute_every_n_frame=\"1\"\n		remove_after_executed=\"1\">\n	</LuaComponent>\n</Entity>"
