_TWWE_VFS["mods/spell_lab_shugged/files/gui/action_metadata.lua"] = "dofile_once( \"mods/spell_lab_shugged/files/lib/entity_xml_parser.lua\" )\nTYPE_ADJUSTMENT = {\n	Add = 1,\n	Set = 2,\n}\nfunction get_action_metadata( this_action_data )\n	if not this_action_data then return end\n	local metadata = {\n		c = {},\n		projectiles = nil,\n		shot_effects = {},\n	}\n\n	reflecting = true\n	local last_projectile_timer_time = nil\n	local add_projectile_trigger_timer_injected = function( entity_filename, delay_frames, action_draw_count )\n		last_projectile_timer_time = delay_frames\n		Reflection_RegisterProjectile( entity_filename )\n	end\n	Reflection_RegisterProjectile = function( filepath )\n		metadata.projectiles = metadata.projectiles or {}\n		if metadata.projectiles[filepath] then\n			metadata.projectiles[filepath].projectiles = metadata.projectiles[filepath].projectiles + 1\n			return\n		end\n		local xml_content = parse_entity_xml( filepath )\n		if not xml_content then\n			print( \"Spell \" .. tostring( this_action_data.action_id ) .. \" has a wrong argument in its Reflection_RegisterProjectile(). You might want to blame the author of that spell if you see this\" )\n			return\n		end\n		local properties\n\n		local proj_comp = xml_content:first_of( \"ProjectileComponent\" )\n		if proj_comp then\n			properties = proj_comp.attr\n			local damage_by_type = proj_comp:first_of( \"damage_by_type\" )\n			if damage_by_type then\n				for type, value in pairs( damage_by_type.attr ) do\n					properties[ \"damage_\" .. type ] = ( properties[ \"damage_\" .. type ] or 0 ) + tonumber( value )\n				end\n			end\n			local config_explosion = proj_comp:first_of( \"config_explosion\" )\n			if config_explosion then\n				properties.explosion_damage = config_explosion.attr.damage or 5\n				properties.explosion_radius = config_explosion.attr.explosion_radius or 20\n			else\n				properties.explosion_damage = 5\n				properties.explosion_radius = 20\n			end\n		end\n		properties = properties or {}\n		properties.projectiles = 1\n\n		properties.lifetime_cap = nil\n		properties.lifetime_cap2 = nil\n		for lifetime_comp in xml_content:each_of( \"LifetimeComponent\" ) do\n			local lifetime = tonumber( lifetime_comp.attr.lifetime )\n			if lifetime and lifetime >= 0 then\n				local randomize_min = tonumber( lifetime_comp.attr[\"randomize_lifetime.min\"] ) or 0\n				local randomize_max = tonumber( lifetime_comp.attr[\"randomize_lifetime.max\"] ) or 0\n				local lifetime2 = lifetime + randomize_max\n				lifetime = lifetime + randomize_min\n				if not properties.lifetime_cap or lifetime < properties.lifetime_cap then\n					properties.lifetime_cap = lifetime\n				end\n				if not properties.lifetime_cap2 or lifetime2 < properties.lifetime_cap2 then\n					properties.lifetime_cap2 = lifetime2\n				end\n			end\n		end\n		for xray_comp in xml_content:each_of( \"MagicXRayComponent\" ) do\n			local steps_per_frame = tonumber( xray_comp.attr.steps_per_frame )\n			local radius = tonumber( xray_comp.attr.radius )\n			if steps_per_frame and steps_per_frame >= 0 and radius and radius >= 0 then\n				local lifetime = radius / steps_per_frame\n				if not properties.lifetime_cap or lifetime < properties.lifetime_cap then\n					properties.lifetime_cap = lifetime\n				end\n				if not properties.lifetime_cap2 or lifetime < properties.lifetime_cap2 then\n					properties.lifetime_cap2 = lifetime\n				end\n			end\n		end\n		local vel_comp = xml_content:first_of( \"VelocityComponent\" )\n		if vel_comp then\n			properties.gravity = vel_comp.attr.gravity_y or 400\n			properties.air_friction = vel_comp.attr.air_friction or 0.55\n		end\n\n		if last_projectile_timer_time then\n			properties.timer_time = last_projectile_timer_time\n			last_projectile_timer_time = nil\n		end\n\n		metadata.projectiles[filepath] = properties\n	end\n	local _shot_effects = shot_effects\n	local _c = c\n		c = {}\n		shot_effects = {}\n		current_reload_time = 0\n\n		local draws = 0\n		local _draw_actions = draw_actions\n		draw_actions = function( how_many ) draws = draws + how_many end\n\n		local _EntityLoad = EntityLoad\n		EntityLoad = function() end\n\n		reset_modifiers( c )\n		ConfigGunShotEffects_Init( shot_effects )\n\n		c.friendly_fire = nil\n\n		shot_effects.spell_lab_shugged_recoil_knockback = shot_effects.recoil_knockback\n		shot_effects.recoil_knockback = nil\n		shot_effects.spell_lab_shugged_count_recoil_get = 0\n		shot_effects.spell_lab_shugged_count_recoil_set = 0\n		setmetatable( shot_effects,\n			{\n				__index = function( t, key )\n					if key == \"recoil_knockback\" then\n						rawset( t, \"spell_lab_shugged_count_recoil_get\", rawget( t, \"spell_lab_shugged_count_recoil_get\" ) + 1 )\n						return rawget( t, \"spell_lab_shugged_recoil_knockback\" )\n					end\n					return rawget( t, key )\n				end,\n				__newindex = function( t, key, value )\n					if key == \"recoil_knockback\" then\n						rawset( t, \"spell_lab_shugged_count_recoil_set\", rawget( t, \"spell_lab_shugged_count_recoil_set\" ) + 1 )\n						rawset( t, \"spell_lab_shugged_recoil_knockback\", value )\n					end\n					rawset( t, key, value )\n				end,\n			}\n		)\n\n		local action_action = this_action_data.action\n		local action_env = getfenv( action_action )\n		action_env.add_projectile_trigger_timer = add_projectile_trigger_timer_injected\n		setfenv( action_action, action_env )\n\n		pcall( action_action )\n\n		draw_actions = _draw_actions\n		c.draw_actions = draws\n		c.reload_time = current_reload_time\n		c.mana = this_action_data.mana\n		if rawget( shot_effects, \"spell_lab_shugged_count_recoil_set\" ) == 1 then\n			if rawget( shot_effects, \"spell_lab_shugged_count_recoil_get\" ) == 1 then\n				c.spell_lab_shugged_recoil = { value = shot_effects.spell_lab_shugged_recoil_knockback, type = TYPE_ADJUSTMENT.Add }\n			elseif rawget( shot_effects, \"spell_lab_shugged_count_recoil_get\" ) == 0 then\n				c.spell_lab_shugged_recoil = { value = shot_effects.spell_lab_shugged_recoil_knockback, type = TYPE_ADJUSTMENT.Set }\n			end\n		end\n		c.lifetime_cap = { nil, nil }\n		if #c.extra_entities > 0 then\n			string.gsub( c.extra_entities, \"[^,]+\", function( extra_entity )\n				local extra_entity_content = parse_entity_xml( extra_entity )\n				if extra_entity_content == nil then return end\n				for lifetime_comp in extra_entity_content:each_of( \"LifetimeComponent\" ) do\n					local lifetime = tonumber( lifetime_comp.attr.lifetime )\n					if lifetime and lifetime >= 0 then\n						local randomize_min = tonumber( lifetime_comp.attr[\"randomize_lifetime.min\"] ) or 0\n						local randomize_max = tonumber( lifetime_comp.attr[\"randomize_lifetime.max\"] ) or 0\n						local lifetime2 = lifetime + randomize_max\n						lifetime = lifetime + randomize_min\n						if not c.lifetime_cap[1] or lifetime < c.lifetime_cap[1] then\n							c.lifetime_cap[1] = lifetime\n						end\n						if not c.lifetime_cap[2] or lifetime2 < c.lifetime_cap[2] then\n							c.lifetime_cap[2] = lifetime2\n						end\n					end\n				end\n			end )\n		end\n		metadata.c = c\n\n		EntityLoad = _EntityLoad\n	c = _c\n	shot_effects = _shot_effects\n	reflecting = false\n	if metadata.projectiles then\n		local temp = metadata.projectiles\n		metadata.projectiles = {}\n		for _, d in pairs( temp ) do\n			table.insert( metadata.projectiles, d )\n		end\n	end\n	return metadata\nend\n\nif player then EntityRemoveTag( player, \"player_unit\" ) end\n\nlocal action_metadata = {}\nfor _, action in pairs( actions ) do\n	action_metadata[ action.id ] = get_action_metadata( action )\nend\n\ndofile_once( \"mods/spell_lab_shugged/files/gui/extra_modifiers_supported.lua\" )\nlocal extra_modifier_metadata = {}\nfor _, id in pairs( extra_modifiers_supported ) do\n	do\n		local fake_action = {\n			id = \"FAKE_ACTION_\" .. string.upper( id ),\n			mana = 0,\n			action = extra_modifiers[ id ],\n		}\n		local metadata = get_action_metadata( fake_action ).c\n		for k, v in pairs( metadata ) do\n			if k == \"mana\" and v == 0 then\n				metadata[ k ] = nil\n				break\n			end\n		end\n		extra_modifier_metadata[ id ] = metadata\n\n	end\n	::continue::\nend\n\nif player then EntityAddTag( player, \"player_unit\" ) end\n\nlocal metadata_to_show = {\n	c = {\n		{ \"draw_actions\"            , wrap_key( \"draws\" ), 0, function(value) return format_value( value, 0 ) end },\n		{ \"max_uses\"                , wrap_key( \"max_uses\" ), nil, function(value) return format_value( value, 0 ) end },\n		{ \"mana\"                    , \"$inventory_manadrain\", nil, function(value) return format_value( value, 0 ) end },\n		{ \"fire_rate_wait\"          , \"$inventory_castdelay\", 0, function(value) return format_time( value, 3 ) end },\n		{ \"speed_multiplier\"        , \"$inventory_mod_speed\", 1, function(value) return \"x \" .. format_value( value, 2 ) end },\n		{ \"lifetime_add\"            , wrap_key( \"lifetime_add\" ), 0, function(value) return format_value( value, 0, true ) end },\n		{ \"lifetime_cap\"            , wrap_key( \"lifetime_cap\" ), nil, function(value) return format_range( value[1], value[2] ) end },\n		{ \"reload_time\"             , \"$inventory_rechargetime\", 0, function(value) return format_time( value, 3 ) end },\n		{ \"spread_degrees\"          , \"$inventory_spread\", 0, function(value) return GameTextGet( wrap_key( \"degrees\" ), format_value( value, 3, true, FORMAT.Round ) ) end },\n		{ \"damage_critical_chance\"  , \"$inventory_mod_critchance\", 0, function(value) return format_value( value, 0, true ) .. \"%\" end },\n		{ \"explosion_radius\"        , \"$inventory_explosion_radius\", 0, function(value) return format_value( value, 0, true, FORMAT.Ceiling ) end },\n		{ \"damage_projectile_add\"   , \"$inventory_mod_damage\", 0, function(value) return format_value( value * 25, 2, true, FORMAT.Ceiling ) end },\n		{ \"damage_ice_add\"          , \"$inventory_mod_damage_ice\", 0, function(value) return format_value( value * 25, 2, true, FORMAT.Ceiling ) end },\n		{ \"damage_explosion_add\"    , \"$inventory_mod_damage_explosion\", 0, function(value) return format_value( value * 25, 2, true, FORMAT.Ceiling ) end },\n		{ \"damage_melee_add\"        , \"$inventory_mod_damage_melee\", 0, function(value) return format_value( value * 25, 2, true, FORMAT.Ceiling ) end },\n		{ \"damage_electricity_add\"  , \"$inventory_mod_damage_electric\", 0, function(value) return format_value( value * 25, 2, true, FORMAT.Ceiling ) end },\n		{ \"damage_fire_add\"         , \"$inventory_mod_damage_fire\", 0, function(value) return format_value( value * 25, 2, true, FORMAT.Ceiling ) end },\n		{ \"friendly_fire\"           , wrap_key( \"friendly_fire\" ), nil, function(value) return wrap_key( value and \"enable2\" or \"disable2\" ) end },\n		{ \"gravity\"                 , wrap_key( \"gravity\" ), 0, function(value) return format_value( value, 0, true ) end },\n		{ \"bounces\"                 , \"$inventory_mod_bounces\", 0, function(value) return format_value( value, 0, true ) end },\n		{ \"spell_lab_shugged_recoil\", wrap_key( \"recoil\" ), nil, function(value)\n			if value.type == TYPE_ADJUSTMENT.Set then\n				return GameTextGet( wrap_key( \"value_set_to\" ), format_value( value.value, 0 ) )\n			else\n				if value.value ~= 0 then\n					return format_value( value.value, 0, true )\n				else\n					return nil\n				end\n			end\n		end },\n	},\n	projectiles = {\n		{ wrap_key( \"projectile_num_projectiles\" ), function( data ) if data.projectiles ~= nil and tonumber( data.projectiles ) ~= 1 then return format_value( data.projectiles, 0 ) end end },\n		{ wrap_key( \"projectile_damage_projectile\" ), function( data ) if data.damage ~= nil and tonumber( data.damage ) ~= 0 then return format_value( data.damage * 25, 3, false, FORMAT.Round ) end end },\n		{ wrap_key( \"projectile_damage_curse\" ), function( data ) if data.damage_curse ~= nil and tonumber( data.damage_curse ) ~= 0 then return format_value( data.damage_curse * 25, 3, false, FORMAT.Round ) end end },\n		{ wrap_key( \"projectile_damage_slice\" ), function( data ) if data.damage_slice ~= nil and tonumber( data.damage_slice ) ~= 0 then return format_value( data.damage_slice * 25, 3, false, FORMAT.Round ) end end },\n		{ wrap_key( \"projectile_damage_melee\" ), function( data ) if data.damage_melee ~= nil and tonumber( data.damage_melee ) ~= 0 then return format_value( data.damage_melee * 25, 3, false, FORMAT.Round ) end end },\n		{ wrap_key( \"projectile_damage_electricity\" ), function( data ) if data.damage_electricity ~= nil and tonumber( data.damage_electricity ) ~= 0 then return format_value( data.damage_electricity * 25, 3, false, FORMAT.Round ) end end },\n		{ wrap_key( \"projectile_damage_explosion\" ), function( data ) if data.damage_explosion ~= nil and tonumber( data.damage_explosion ) ~= 0 then return format_value( data.damage_explosion * 25, 3, false, FORMAT.Round ) end end },\n		{ wrap_key( \"projectile_damage_fire\" ), function( data ) if data.damage_fire ~= nil and tonumber( data.damage_fire ) ~= 0 then return format_value( data.damage_fire * 25, 3, false, FORMAT.Round ) end end },\n		{ wrap_key( \"projectile_damage_ice\" ), function( data ) if data.damage_ice ~= nil and tonumber( data.damage_ice ) ~= 0 then return format_value( data.damage_ice * 25, 3, false, FORMAT.Round ) end end },\n		{ wrap_key( \"projectile_damage_drill\" ), function( data ) if data.damage_drill ~= nil and tonumber( data.damage_drill ) ~= 0 then return format_value( data.damage_drill * 25, 3, false, FORMAT.Round ) end end },\n		{ wrap_key( \"projectile_damage_poison\" ), function( data ) if data.damage_poison ~= nil and tonumber( data.damage_poison ) ~= 0 then return format_value( data.damage_poison * 25, 3, false, FORMAT.Round ) end end },\n		{ wrap_key( \"projectile_damage_healing\" ), function( data ) if data.damage_healing ~= nil and tonumber( data.damage_healing ) ~= 0 then return format_value( data.damage_healing * 25, 3, false, FORMAT.Round ) end end },\n		{ wrap_key( \"projectile_damage_radioactive\" ), function( data ) if data.damage_radioactive ~= nil and tonumber( data.damage_radioactive ) ~= 0 then return format_value( data.damage_radioactive * 25, 3, false, FORMAT.Round ) end end },\n		{ wrap_key( \"projectile_speed\" ), function( data ) return format_range( data.speed_min, data.speed_max ) end },\n		{ wrap_key( \"projectile_air_friction\" ), function( data ) return data.air_friction end },\n		{ wrap_key( \"projectile_innate_spread\" ), function( data ) if data.direction_random_rad ~= nil and tonumber(data.direction_random_rad) ~= 0 then return GameTextGet( wrap_key( \"degrees\" ), format_value( data.direction_random_rad * 180 / math.pi, 1, false, FORMAT.Round ) ) end end },\n		{ wrap_key( \"projectile_gravity\" ), function( data ) if data.gravity ~= nil and tonumber(data.gravity) ~= 0 then return data.gravity end end },\n		{ wrap_key( \"projectile_lifetime\" ), function( data )\n			if not data.lifetime then return end\n			local result\n			if not data.lifetime_randomness or data.lifetime_randomness == \"0\" then\n				result = tostring( data.lifetime )\n			else\n				result = format_range( data.lifetime - data.lifetime_randomness, data.lifetime + data.lifetime_randomness )\n			end\n			return GameTextGet( wrap_key( \"frames\" ), result )\n		end },\n		{ wrap_key( \"projectile_lifetime_cap\" ), function( data )\n			local result = format_range( data.lifetime_cap, data.lifetime_cap2 )\n			if result then\n				return GameTextGet( wrap_key( \"frames\" ), result )\n			end\n		end },\n		{ wrap_key( \"projectile_friendly_fire\" ), function( data ) if data.friendly_fire == \"1\" then return \"$menu_yes\" end end },\n		{ wrap_key( \"projectile_shooter_collision_protection\" ), function( data )\n			if data.collide_with_shooter_frames and data.collide_with_shooter_frames ~= \"-1\" then\n				return GameTextGet( wrap_key( \"frames\" ), data.collide_with_shooter_frames )\n			end\n		end },\n		{ wrap_key( \"projectile_explosion_enabled\" ), function( data ) return \"$menu_\" .. ( ( data.on_death_explode == \"1\" or data.on_lifetime_out_explode == \"1\" ) and \"yes\" or \"no\" ) end },\n		{ wrap_key( \"projectile_explosion_radius\" ), function( data ) if data.explosion_radius ~= nil then return format_value( data.explosion_radius, 0 ) end end },\n		{ wrap_key( \"projectile_explosion_damage\" ), function( data ) if data.explosion_damage ~= nil then return format_value( data.explosion_damage * 25, 2, false, FORMAT.Round ) end end },\n		{ wrap_key( \"projectile_explosion_dont_damage_shooter\" ), function( data ) if data.explosion_dont_damage_shooter and data.explosion_dont_damage_shooter ~= \"0\" then return \"$menu_yes\" end end },\n		{ wrap_key( \"projectile_timer_time\" ), function( data ) if data.timer_time ~= nil then return GameTextGet( wrap_key( \"frames\" ), format_value( data.timer_time, 0 ) ) end end },\n		{ wrap_key( \"projectile_die_on_low_velocity\" ), function( data ) if data.die_on_low_velocity == \"1\" then return data.die_on_low_velocity_limit or \"50\" end end },\n		{ \"$inventory_mod_bounces\", function( data ) if data.bounces_left ~= \"0\" then return data.bounces_left end end },\n	}\n}\n\nfunction c_metadata_to_lines( this_c_metadata )\n	local c_lines = {}\n	for _, d in ipairs( metadata_to_show.c ) do\n		local value = this_c_metadata[d[1]]\n		if value ~= nil and value ~= d[3] then\n			local text = tostring( d[4]( value ) )\n			if text ~= \"nil\" then\n				table.insert( c_lines, { d[2], text } )\n			end\n		end\n	end\n	return c_lines\nend\n\nfunction proj_metadata_to_lines( this_projectiles_metadata )\n	local num_lines = 0\n	local projectiles_lines = {}\n	for proj_index, data in ipairs( this_projectiles_metadata or {} ) do\n		local proj_lines = {}\n		for _, d in ipairs( metadata_to_show.projectiles ) do\n			local value = d[2]( data )\n			if value then\n				table.insert( proj_lines, { d[1], value } )\n			end\n		end\n		projectiles_lines[ proj_index ] = proj_lines\n		num_lines = num_lines + #proj_lines\n	end\n	num_lines = num_lines + #projectiles_lines\n	return projectiles_lines, num_lines\nend\n\nreturn { action_metadata, extra_modifier_metadata, metadata_to_show }"
_TWWE_VFS["mods/spell_lab_shugged/files/gui/damage_info.lua"] = "GuiLayoutAddVerticalSpacing( gui, 360 * 0.05 )\nlocal x_pos = ( screen_width + 4 * ( 20 + 2 ) ) * 0.5\nlocal highest_dps = GlobalsGetValue( \"spell_lab_shugged_recent_highest_dps\", \"\" )\nif #highest_dps > 0 then\n	GuiTextCentered( gui, x_pos, 0, text_get_translated( \"damage_info_dps\" ) .. highest_dps )\nend\n\nlocal total_damage = GlobalsGetValue( \"spell_lab_shugged_recent_total_damage\", \"\" )\nif #total_damage > 0 then\n	GuiTextCentered( gui, x_pos, 0, text_get_translated( \"damage_info_total_damage\" ) .. total_damage )\nend\n\nlocal player_projectiles = EntityGetWithTag( \"spell_lab_shugged_player_projectile\" ) or {}\nlocal total_projectile_damage = 0\nlocal total_projectiles = #player_projectiles\nfor _, v in pairs( player_projectiles ) do\n	local projectile = EntityGetFirstComponent( v, \"ProjectileComponent\" )\n	if projectile then\n		local damage = ComponentGetValue2( projectile, \"damage\" )\n		total_projectile_damage = total_projectile_damage + math.max( damage, 0 )\n	end\nend\nGuiTextCentered( gui, x_pos, 0, text_get_translated( \"damage_info_total_projectile_damage\" ) .. separator( math.floor( total_projectile_damage * 25 + 0.5 ) ) )\nGuiTextCentered( gui, x_pos, 0, text_get_translated( \"damage_info_total_projectiles_num\" ) .. separator( math.floor( total_projectiles ) ) )"
_TWWE_VFS["mods/spell_lab_shugged/files/gui/edit_panel_api.lua"] = "local edit_panel_access_cache = {}\nfunction access_edit_panel_state( wand_id, dont_cache )\n	local cache = edit_panel_access_cache[ wand_id ]\n	if cache then\n		return cache\n	end\n	local result = access_edit_panel_state_impl( wand_id )\n	if not dont_cache then\n		edit_panel_access_cache[ wand_id ] = result\n	end\n	return result\nend\n\nfunction read_state_table_from_wand( wand_id )\n	local actions, permanent_actions = WANDS.wand_get_actions_absolute( wand_id )\n	local _actions = {}\n	for i = 0, maxn( actions ) do\n		local _a = { false }\n\n		local a = actions[ i ]\n		do\n			if not a then goto skip end\n			local this_action_data = action_data[ a.action_id ]\n			if not this_action_data then goto skip end\n			\n			_a[2] = a.action_id\n			\n			if this_action_data.max_uses and this_action_data.max_uses ~= -1  then -- don't give it a -1 plz\n				if world_state_unlimited_spells and not this_action_data.never_unlimited then -- Should be unlimited, but being limited\n					_a[3] = nil\n				elseif a.uses_remaining == -1 then -- Should be limited, but being unlimited\n					_a[3] = this_action_data.max_uses\n				else -- just normal case\n					_a[3] = a.uses_remaining\n				end\n			else\n				_a[3] = nil\n			end\n		end\n		::skip::\n\n		_actions[ i + 1 ] = _a\n	end\n	local _permanent_actions = {}\n	for i, a in ipairs( permanent_actions ) do\n		table.insert( _permanent_actions, a.action_id )\n	end\n	return _actions, _permanent_actions\nend\n\nfunction read_state_from_wand( wand_id )\n	local a, pa = read_state_table_from_wand( wand_id )\n	return table_to_state_str( a ), permanent_table_to_state_str( pa )\nend\n\nfunction access_edit_panel_state_impl( wand_id )\n	local row_offset_comp = get_variable_storage_component( wand_id, \"spell_lab_shugged_edit_panel_row_offset\" ) or\n		EntityAddComponent2( wand_id, \"VariableStorageComponent\", {\n			_tags = \"enabled_in_world,enabled_in_hand,enabled_in_inventory\",\n			name = \"spell_lab_shugged_edit_panel_row_offset\",\n			value_int = 0,\n		} )\n	local history_max_index_comp = get_variable_storage_component( wand_id, \"spell_lab_shugged_edit_panel_history_max_index\" ) or\n		EntityAddComponent2( wand_id, \"VariableStorageComponent\", {\n			_tags = \"enabled_in_world,enabled_in_hand,enabled_in_inventory\",\n			name = \"spell_lab_shugged_edit_panel_history_max_index\",\n			value_int = 0,\n		} )\n	local current_history_index_comp = get_variable_storage_component( wand_id, \"spell_lab_shugged_edit_panel_current_history_index\" ) or\n		EntityAddComponent2( wand_id, \"VariableStorageComponent\", {\n			_tags = \"enabled_in_world,enabled_in_hand,enabled_in_inventory\",\n			name = \"spell_lab_shugged_edit_panel_current_history_index\",\n			value_int = 0,\n		} )\n	local function get_all_history_comps()\n		return EntityGetComponentIncludingDisabled( wand_id, \"VariableStorageComponent\", \"spell_lab_shugged_edit_panel_history\" ) or {}\n	end\n	local function new_state_history( new_state, new_permanent_state, operation_name )\n		local history_limit = math.max( mod_setting_get( \"wand_edit_panel_history_limit\" ), 1 )\n		local history_max_index = ComponentGetValue2( history_max_index_comp, \"value_int\" )\n		local current_history_index = ComponentGetValue2( current_history_index_comp, \"value_int\" )\n		if current_history_index ~= history_max_index then\n			for _, history_comp in ipairs( get_all_history_comps() ) do\n				if ComponentGetValue2( history_comp, \"value_int\" ) > current_history_index then\n					EntityRemoveComponent( wand_id, history_comp )\n				end\n			end\n			history_max_index = current_history_index\n		end\n		local new_history_index = history_max_index + 1\n		local offset = new_history_index - history_limit\n		if offset > 0 then\n			for _, history_comp in ipairs( get_all_history_comps() ) do\n				local index = ComponentGetValue2( history_comp, \"value_int\" )\n				if index > offset then\n					ComponentSetValue2( history_comp, \"value_int\", index - offset )\n				else\n					EntityRemoveComponent( wand_id, history_comp )\n				end\n			end\n			new_history_index = history_limit\n		end\n		local include_permanent = new_permanent_state and new_permanent_state ~= \"\"\n		if include_permanent then\n			new_state = string.format( \"%s|%s\", new_state, new_permanent_state )\n		end\n		EntityAddComponent2( wand_id, \"VariableStorageComponent\", {\n			_tags = \"spell_lab_shugged_edit_panel_history\",\n			name = operation_name,\n			value_int = new_history_index,\n			value_string = new_state,\n			value_bool = include_permanent,\n		} )\n		ComponentSetValue2( history_max_index_comp, \"value_int\", new_history_index )\n		ComponentSetValue2( current_history_index_comp, \"value_int\", new_history_index )\n	end\n	local data_comp = get_variable_storage_component( wand_id, \"spell_lab_shugged_edit_panel\" )\n	local permanent_data_comp = get_variable_storage_component( wand_id, \"spell_lab_shugged_edit_panel_permanent\" )\n	if not data_comp or not permanent_data_comp then\n		local state_str, permanent_state_str = read_state_from_wand( wand_id )\n		data_comp = EntityAddComponent2( wand_id, \"VariableStorageComponent\", {\n			_tags = \"enabled_in_world,enabled_in_hand,enabled_in_inventory\",\n			name = \"spell_lab_shugged_edit_panel\",\n			value_string = state_str,\n		} )\n		permanent_data_comp = EntityAddComponent2( wand_id, \"VariableStorageComponent\", {\n			_tags = \"enabled_in_world,enabled_in_hand,enabled_in_inventory\",\n			name = \"spell_lab_shugged_edit_panel_permanent\",\n			value_string = permanent_state_str,\n		} )\n\n		new_state_history( state_str, permanent_state_str, wrap_key( \"operation_read_from_wand\" ) )\n	end\n	local autocap_comp = get_variable_storage_component( wand_id, \"spell_lab_shugged_edit_panel_autocap_enabled\" ) or\n		EntityAddComponent2( wand_id, \"VariableStorageComponent\", {\n			_tags = \"enabled_in_world,enabled_in_hand,enabled_in_inventory\",\n			name = \"spell_lab_shugged_edit_panel_autocap_enabled\",\n			value_bool = false,\n		} )\n	local force_compact_comp = get_variable_storage_component( wand_id, \"spell_lab_shugged_edit_panel_force_compact_enabled\" ) or\n		EntityAddComponent2( wand_id, \"VariableStorageComponent\", {\n			_tags = \"enabled_in_world,enabled_in_hand,enabled_in_inventory\",\n			name = \"spell_lab_shugged_edit_panel_force_compact_enabled\",\n			value_bool = false,\n		} )\n	local sync_flag_comp = get_variable_storage_component( wand_id, \"spell_lab_shugged_edit_panel_sync_flag\" ) or\n		EntityAddComponent2( wand_id, \"VariableStorageComponent\", {\n			_tags = \"enabled_in_world,enabled_in_hand,enabled_in_inventory\",\n			name = \"spell_lab_shugged_edit_panel_sync_flag\",\n			value_bool = false,\n		} )\n	local function get_saved_state_history( index )\n		for _, history_comp in ipairs( get_all_history_comps() ) do\n			if ComponentGetValue2( history_comp, \"value_int\" ) == index then\n				return ComponentGetValue2( history_comp, \"value_bool\" ), ComponentGetValue2( history_comp, \"value_string\" ), ComponentGetValue2( history_comp, \"name\" )\n			end\n		end\n	end\n	local function use_history_state( include_permanent, history_state )\n		local history_permanent_state = nil\n		if include_permanent then\n			history_state, history_permanent_state = string.match( history_state, \"([^|]*)|([^|]*)\" )\n		end\n		-- who cares about uses of permanent actions\n		ComponentSetValue2( permanent_data_comp, \"value_string\", history_permanent_state or \"\" )\n		local history_actions = {}\n		for s, a, u in state_str_iter_actions( history_state ) do\n			local this_action_data = action_data[ a ]\n			if not this_action_data then\n				u = nil\n			elseif this_action_data.max_uses then\n				if world_state_unlimited_spells and not this_action_data.never_unlimited then\n					u = nil\n				elseif not u or u == \"\" then\n					u = this_action_data.max_uses\n				end\n			end\n			table.insert( history_actions, { s, a, u } )\n		end\n		ComponentSetValue2( data_comp, \"value_string\", table_to_state_str( history_actions ) )\n		ComponentSetValue2( sync_flag_comp, \"value_bool\", true )\n	end\n	return {\n		get = function()\n			return ComponentGetValue2( data_comp, \"value_string\" )\n		end,\n		set = function( new_state, operation_name )\n			while string.sub( new_state, -3, -1 ) == \",:,\" do\n				new_state = string.sub( new_state, 1, -3 )\n			end\n			ComponentSetValue2( data_comp, \"value_string\", new_state )\n			ComponentSetValue2( sync_flag_comp, \"value_bool\", true )\n\n			new_state_history( new_state, nil, operation_name )\n		end,\n		get_permanent = function()\n			return ComponentGetValue2( permanent_data_comp, \"value_string\" )\n		end,\n		set_both = function( new_state, new_permanent_state, operation_name )\n			while string.sub( new_state, -3, -1 ) == \",:,\" do\n				new_state = string.sub( new_state, 1, -3 )\n			end\n			while string.sub( new_permanent_state, -2, -1 ) == \",,\" do\n				new_permanent_state = string.sub( new_permanent_state, 1, -2 )\n			end\n			ComponentSetValue2( data_comp, \"value_string\", new_state )\n			ComponentSetValue2( permanent_data_comp, \"value_string\", new_permanent_state )\n			ComponentSetValue2( sync_flag_comp, \"value_bool\", true )\n\n			new_state_history( new_state, new_permanent_state, operation_name )\n		end,\n		need_sync = function()\n			return ComponentGetValue2( sync_flag_comp, \"value_bool\" )\n		end,\n		force_sync = function()\n			ComponentSetValue2( sync_flag_comp, \"value_bool\", true )\n		end,\n		done_sync = function()\n			ComponentSetValue2( sync_flag_comp, \"value_bool\", false )\n		end,\n		undo = function()\n			local current_history_index = ComponentGetValue2( current_history_index_comp, \"value_int\" )\n			if current_history_index == 1 then return end\n			current_history_index = current_history_index - 1\n			ComponentSetValue2( current_history_index_comp, \"value_int\", current_history_index )\n\n			local include_permanent, history_state = get_saved_state_history( current_history_index )\n			use_history_state( include_permanent, history_state )\n		end,\n		redo = function()\n			local current_history_index = ComponentGetValue2( current_history_index_comp, \"value_int\" )\n			if current_history_index == ComponentGetValue2( history_max_index_comp, \"value_int\" ) then return end\n			current_history_index = current_history_index + 1\n			ComponentSetValue2( current_history_index_comp, \"value_int\", current_history_index )\n\n			local include_permanent, history_state = get_saved_state_history( current_history_index )\n			use_history_state( include_permanent, history_state )\n		end,\n		peek_undo = function()\n			local current_history_index = ComponentGetValue2( current_history_index_comp, \"value_int\" )\n			if current_history_index == 1 then return nil end\n			local _, _, operation_name = get_saved_state_history( current_history_index )\n			return operation_name\n		end,\n		peek_redo = function()\n			local current_history_index = ComponentGetValue2( current_history_index_comp, \"value_int\" )\n			if current_history_index == ComponentGetValue2( history_max_index_comp, \"value_int\" ) then return nil end\n			local _, _, operation_name = get_saved_state_history( current_history_index + 1 )\n			return operation_name\n		end,\n		get_current_history_index = function()\n			local current_history_index = ComponentGetValue2( current_history_index_comp, \"value_int\" )\n			local history_max_index     = ComponentGetValue2( history_max_index_comp, \"value_int\" )\n			return current_history_index, history_max_index\n		end,\n		get_offset = function()\n			return ComponentGetValue2( row_offset_comp, \"value_int\" )\n		end,\n		set_offset = function( row_offset )\n			ComponentSetValue2( row_offset_comp, \"value_int\", row_offset )\n		end,\n		get_autocap_enabled = function()\n			return ComponentGetValue2( autocap_comp, \"value_bool\" )\n		end,\n		set_autocap_enabled = function( enabled )\n			ComponentSetValue2( autocap_comp, \"value_bool\", enabled )\n		end,\n		get_force_compact_enabled = function()\n			return ComponentGetValue2( force_compact_comp, \"value_bool\" )\n		end,\n		set_force_compact_enabled = function( enabled )\n			ComponentSetValue2( force_compact_comp, \"value_bool\", enabled )\n		end,\n	}\nend\nfunction table_to_state_str( t )\n	local maxnt = maxn( t )\n	if maxnt == -1 then return \"\" end\n	for i = 1, maxnt do\n		if t[ i ] then\n			t[ i ] = format_action_str( t[ i ][1], t[ i ][2], t[ i ][3] )\n		else\n			t[ i ] = \":,\"\n		end\n	end\n	return table.concat( t )\nend\nfunction permanent_table_to_state_str( t )\n	if #t == 0 then return \"\" end\n	return table.concat( t, \",\" ) .. \",\"\nend\nfunction state_str_iter_actions( state_str )\n	local f = string.gmatch( state_str, \"(@?)([^,%:]*)%:(-?%d*),\" )\n	return function()\n		local s, a, u = f()\n		if u == -1 then\n			u = nil\n		end\n		return s and s ~= \"\", a, u\n	end\nend\nfunction state_str_iter_permanent_actions( state_str )\n	return string.gmatch( state_str, \"([^,]*),\" )\nend\nfunction format_action_str( selected, action_id, uses_remaining )\n	if uses_remaining == nil or uses_remaining == -1 then\n		uses_remaining = \"\"\n	end\n	return string.format( \"%s%s:%s,\", ( selected and selected ~= \"\" ) and \"@\" or \"\", action_id or \"\", tostring( uses_remaining or \"\" ) )\nend\nfunction reload_state_for_wand( wand_id )\n	edit_panel_access_cache[ wand_id ] = nil\n	EntityRemoveComponent( wand_id, get_variable_storage_component( wand_id, \"spell_lab_shugged_edit_panel\" ) )\n	EntityRemoveComponent( wand_id, get_variable_storage_component( wand_id, \"spell_lab_shugged_edit_panel_permanent\" ) )\nend"
_TWWE_VFS["mods/spell_lab_shugged/files/gui/edit_panel_shown.lua"] = "if not held_wand then return end\n\nlocal actions_per_row = math.floor( screen_width / ( 20 + 2 ) - 3 )\ndo\n	local actions_per_row_limit = tonumber( mod_setting_get( \"wand_edit_panel_max_actions_per_row\" ) )\n	if actions_per_row_limit and actions_per_row_limit ~= 0 then\n		actions_per_row = math.min( actions_per_row, actions_per_row_limit )\n	end\nend\nlocal edit_panel_state = access_edit_panel_state( held_wand )\n\nlocal common_actions = {}\nlocal permanent_actions = {}\nfor s, a, u in state_str_iter_actions( edit_panel_state.get() ) do\n	table.insert( common_actions, { s, a, u } )\nend\nfor a in state_str_iter_permanent_actions( edit_panel_state.get_permanent() ) do\n	table.insert( permanent_actions, a )\nend\nlocal capacity = EntityGetWandCapacity( held_wand )\nlocal panel_row_offset = edit_panel_state.get_offset()\nlocal rows_num\nlocal not_showing_all\nlocal offset_reached_end\nlocal max_rows_to_show = tonumber( mod_setting_get( \"wand_edit_panel_max_rows\" ) ) or 5\nif edit_panel_state.get_autocap_enabled() then\n	rows_num = max_rows_to_show\n	not_showing_all = true\n	offset_reached_end = false\nelse\n	rows_num = math.ceil( capacity / actions_per_row )\n	if max_rows_to_show + panel_row_offset == rows_num then\n		offset_reached_end = true\n	elseif max_rows_to_show + panel_row_offset > rows_num then\n		panel_row_offset = math.max( rows_num - max_rows_to_show, 0 )\n		edit_panel_state.set_offset( panel_row_offset )\n		offset_reached_end = true\n	else\n		offset_reached_end = false\n	end\n	if rows_num > max_rows_to_show then\n		rows_num = max_rows_to_show\n		not_showing_all = true\n	else\n		not_showing_all = false\n		offset_reached_end = true\n	end\nend\n\nlocal create_real_sprite = mod_setting_get( \"gif_mode\" )\n\nlocal function do_permanent_shortcuts( edit_panel_state, left_click, right_click, j, permanent_action, capacity )\n	if shortcut_check.check( shortcuts.always_cast, left_click, right_click ) then\n		local max_uses = nil\n		do\n			local this_action_data = action_data[ permanent_action ]\n			if this_action_data.max_uses ~= nil then\n				if not world_state_unlimited_spells or this_action_data.never_unlimited then\n					max_uses = this_action_data.max_uses\n				end\n			end\n		end\n\n		local current_actions = { { true, permanent_action, max_uses } }\n		local is_first = true\n		for s, a, u in state_str_iter_actions( edit_panel_state.get() ) do\n			if is_first then\n				if not a or a == \"\" then\n					-- just leave that slot to the demoted action\n				else\n					table.insert( current_actions, { s, a, u } )\n				end\n				is_first = false\n			else\n				table.insert( current_actions, { s, a, u } )\n			end\n		end\n		if not edit_panel_state.get_autocap_enabled() and not fit_into_capacity( current_actions, 1, capacity ) then\n			GamePrint( text_get_translated( \"demotion_no_space\" ) )\n			return\n		end\n		local current_permanent_actions = {}\n		for pa in state_str_iter_permanent_actions( edit_panel_state.get_permanent() ) do\n			table.insert( current_permanent_actions, pa )\n		end\n		table.remove( current_permanent_actions, j )\n		edit_panel_state.set_both( table_to_state_str( current_actions ), permanent_table_to_state_str( current_permanent_actions ), wrap_key( \"operation_demote_permanent_action\" ) )\n	end\nend\nlocal function do_shortcuts( edit_panel_state, left_click, right_click, i, action_id, capacity )\n	if shortcut_check.check( shortcuts.always_cast, left_click, right_click ) then\n		if action_id and action_id ~= \"\" then\n			local current_actions = {}\n			for s, a, u in state_str_iter_actions( edit_panel_state.get() ) do\n				table.insert( current_actions, { s, a, u } )\n			end\n			if current_actions[ i ] then\n				current_actions[ i ] = { false }\n				edit_panel_state.set_both( table_to_state_str( current_actions ), edit_panel_state.get_permanent() .. action_id .. \",\", wrap_key( \"operation_promote_permanent_action\" ) )\n			end\n		end\n	elseif shortcut_check.check( shortcuts.expand_selection_left, left_click, right_click ) then\n		local current_actions = {}\n		local index = 1\n		local last_selected_index = 1\n		for s, a, u in state_str_iter_actions( edit_panel_state.get() ) do\n			if s and index < i then\n				last_selected_index = index\n			end\n			index = index + 1\n			table.insert( current_actions, { s, a, u } )\n		end\n		for j = last_selected_index, i, 1 do\n			if current_actions[ j ] then\n				current_actions[ j ][1] = true\n			else\n				current_actions[ j ] = { true }\n			end\n		end\n		edit_panel_state.set( table_to_state_str( current_actions ), wrap_key( \"operation_select\" ) )\n	elseif shortcut_check.check( shortcuts.expand_selection_right, left_click, right_click ) then	\n		local current_actions = {}\n		local index = 1\n		local next_selected_index = -1\n		for s, a, u in state_str_iter_actions( edit_panel_state.get() ) do\n			if s and index > i and next_selected_index == -1 then\n				next_selected_index = index\n			end\n			index = index + 1\n			table.insert( current_actions, { s, a, u } )\n		end\n		if next_selected_index ~= -1 then\n			for j = i, next_selected_index, 1 do\n				if current_actions[ j ] then\n					current_actions[ j ][1] = true\n				else\n					current_actions[ j ] = { true }\n				end\n			end\n		elseif not edit_panel_state.get_autocap_enabled() then\n			for j = i, capacity do\n				if current_actions[ j ] then\n					current_actions[ j ][1] = true\n				else\n					current_actions[ j ] = { true }\n				end\n			end\n		end\n		edit_panel_state.set( table_to_state_str( current_actions ), wrap_key( \"operation_select\" ) )\n	elseif shortcut_check.check( shortcuts.duplicate, left_click, right_click ) then\n		local current_actions = {}\n		local selected_indexes = {}\n		local index = 1\n		for s, a, u in state_str_iter_actions( edit_panel_state.get() ) do\n			table.insert( current_actions, { false, a, u } )\n			if s then\n				table.insert( selected_indexes, index )\n			end\n			index = index + 1\n		end\n		if current_actions[ i ] and current_actions[ i ][1] then\n			return\n		end\n		local first = selected_indexes[1]\n		if not first then return end\n		local offset = i - first\n		if not edit_panel_state.get_autocap_enabled() then\n			for j, index in ipairs( selected_indexes ) do\n				local the_other = index + offset\n				if the_other > capacity then\n					return\n				end\n			end\n		end\n		local selected_actions = {}\n		for j, index in ipairs( selected_indexes ) do\n			selected_actions[ j ] = { true, current_actions[ index ][2], current_actions[ index ][3] }\n		end\n		for j, index in ipairs( selected_indexes ) do\n			current_actions[ index + offset ] = selected_actions[ j ]\n		end\n		edit_panel_state.set( table_to_state_str( current_actions ), wrap_key( \"operation_duplicate_action\" ) )\n	elseif shortcut_check.check( shortcuts.multi_select, left_click, right_click ) then\n		local current_actions = {}\n		for s, a, u in state_str_iter_actions( edit_panel_state.get() ) do\n			table.insert( current_actions, { s, a, u } )\n		end\n		if current_actions[ i ] then\n			current_actions[ i ][1] = not current_actions[ i ][1]\n		else\n			current_actions[ i ] = { true }\n		end\n		edit_panel_state.set( table_to_state_str( current_actions ), wrap_key( \"operation_select\" ) )\n	elseif shortcut_check.check( shortcuts.delete_action, left_click, right_click ) then\n		local current_actions = {}\n		for s, a, u in state_str_iter_actions( edit_panel_state.get() ) do\n			table.insert( current_actions, { s, a, u } )\n		end\n		if current_actions[ i ] then\n			local a = current_actions[ i ][2]\n			if a and a ~= \"\" then\n				new_action_history_entry( a )\n			end\n		end\n		current_actions[ i ] = { true }\n		edit_panel_state.set( table_to_state_str( current_actions ), wrap_key( \"operation_clear_action_slot\" ) )\n	elseif shortcut_check.check( shortcuts.delete_slot, left_click, right_click ) then\n		local current_actions = {}\n		for s, a, u in state_str_iter_actions( edit_panel_state.get() ) do\n			table.insert( current_actions, { s, a, u } )\n		end\n		if current_actions[ i ] then\n			local a = current_actions[ i ][2]\n			if a and a ~= \"\" then\n				new_action_history_entry( a )\n			end\n		end\n		table.remove( current_actions, i )\n		edit_panel_state.set( table_to_state_str( current_actions ), wrap_key( \"operation_delete_action_slot\" ) )\n	elseif shortcut_check.check( shortcuts.swap, left_click, right_click ) then\n		local current_actions = {}\n		local indexes_to_swap = {}\n		local index = 1\n		for s, a, u in state_str_iter_actions( edit_panel_state.get() ) do\n			table.insert( current_actions, { s, a, u } )\n			if s then\n				table.insert( indexes_to_swap, index )\n			end\n			index = index + 1\n		end\n		local first = indexes_to_swap[1]\n		if not first then return end\n		local offset = i - first\n		if selected then\n			local temp = {}\n			for j, index in ipairs( indexes_to_swap ) do\n				temp[ j ] = current_actions[ index ]\n			end\n			local size = #indexes_to_swap\n			for j = 1, size - offset do\n				current_actions[ indexes_to_swap[ j + offset ] ] = temp[ j ]\n			end\n			for j = 1, offset do\n				current_actions[ indexes_to_swap[ j ] ] = temp[ size - offset + j ]\n			end\n		else\n			if not edit_panel_state.get_autocap_enabled() then\n				for j, index in ipairs( indexes_to_swap ) do\n					local the_other = index + offset\n					if the_other > capacity then\n						return\n					end\n				end\n			end\n			for j, index in ipairs( indexes_to_swap ) do\n				local the_other = index + offset\n				local temp = current_actions[ the_other ]\n				current_actions[ the_other ] = current_actions[ index ]\n				current_actions[ index ] = temp\n			end\n		end\n		edit_panel_state.set( table_to_state_str( current_actions ), wrap_key( \"operation_swap_actions\" ) )\n	elseif shortcut_check.check( shortcuts.override, left_click, right_click ) then\n		local current_actions = {}\n		local indexes_to_swap = {}\n		local index = 1\n		for s, a, u in state_str_iter_actions( edit_panel_state.get() ) do\n			table.insert( current_actions, { s, a, u } )\n			if s then\n				table.insert( indexes_to_swap, index )\n			end\n			index = index + 1\n		end\n		local first = indexes_to_swap[1]\n		if not first then return end\n		local offset = i - first\n		if not edit_panel_state.get_autocap_enabled() then\n			for j, index in ipairs( indexes_to_swap ) do\n				local the_other = index + offset\n				if the_other > capacity then\n					return\n				end\n			end\n		end\n		local selected_actions = {}\n		for j, index in ipairs( indexes_to_swap ) do\n			selected_actions[ j ] = current_actions[ index ]\n		end\n		for j, index in ipairs( indexes_to_swap ) do\n			current_actions[ index + offset ] = selected_actions[ j ]\n			current_actions[ index ] = { false }\n		end\n		edit_panel_state.set( table_to_state_str( current_actions ), wrap_key( \"operation_override_actions\" ) )\n	elseif shortcut_check.check( shortcuts.select, left_click, right_click ) then\n		local current_actions = {}\n		for s, a, u in state_str_iter_actions( edit_panel_state.get() ) do\n			table.insert( current_actions, { false, a, u } )\n		end\n		if current_actions[ i ] then\n			current_actions[ i ][1] = true\n		else\n			current_actions[ i ] = { true }\n		end\n		edit_panel_state.set( table_to_state_str( current_actions ), wrap_key( \"operation_select\" ) )\n	elseif shortcut_check.check( shortcuts.deselect, left_click, right_click ) then\n		local current_actions = {}\n		for s, a, u in state_str_iter_actions( edit_panel_state.get() ) do\n			table.insert( current_actions, { s, a, u } )\n		end\n		if current_actions[ i ] then\n			current_actions[ i ][1] = false\n		else\n			current_actions[ i ] = { false }\n		end\n		edit_panel_state.set( table_to_state_str( current_actions ), wrap_key( \"operation_deselect\" ) )\n	end\nend\n\nlocal permanent_rows_num = math.ceil( #permanent_actions / actions_per_row )\nif not_showing_all and panel_row_offset > 0 then\n	if GuiImageButton( gui, next_id(), horizontal_centered_x(1), screen_height * 0.96 - ( rows_num + permanent_rows_num + 1 ) * ( 20 + 2 ) + 2, \"\", \"mods/spell_lab_shugged/files/gui/buttons/pageup.png\" ) then\n		edit_panel_state.set_offset( panel_row_offset - 1 )\n	end\nend\nGuiLayoutBeginVertical( gui, 0, screen_height * 0.96 - ( rows_num + permanent_rows_num ) * ( 20 + 2 ) + 2, true )\n	local permanent_note = text_get( \"spell_box_permanent_tips\", shortcut_texts.always_cast )\n	for j, permanent_action in ipairs( permanent_actions ) do\n		if j % actions_per_row == 1 % actions_per_row then\n			if #permanent_actions - j + 1 >= actions_per_row then\n				GuiLayoutBeginHorizontal( gui, horizontal_centered_x( actions_per_row ), 0, true )\n			else\n				GuiLayoutBeginHorizontal( gui, horizontal_centered_x( #permanent_actions % actions_per_row ), 0, true )\n			end\n		end\n		if not create_real_sprite then\n			local left_click, right_click = do_action_button( permanent_action, 0, 0, false, do_least_tooltip, nil, permanent_note, show_permanent_icon )\n			if left_click or right_click then\n				do_permanent_shortcuts( edit_panel_state, left_click, right_click, j, permanent_action, capacity )\n			end\n		else\n			GuiOptionsAddForNextWidget( gui, GUI_OPTION.NonInteractive )\n			GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/transparent_20x20.png\" )\n			local _,_,_,x,y = previous_data( gui )\n			local this_action_data = action_data[ permanent_action ]\n			if this_action_data then\n				local world_x, world_y = get_world_position( x, y )\n				GameCreateSpriteForXFrames( this_action_data.sprite, world_x, world_y, false, 0, 0, 2, true )\n				GameCreateSpriteForXFrames( \"data/ui_gfx/inventory/icon_gun_permanent_actions.png\", world_x - 2, world_y - 2, false, 0, 0, 2, true )\n			end\n		end\n		if j % actions_per_row == 0 or j == #permanent_actions then\n			GuiLayoutEnd( gui )\n		end\n	end\nGuiLayoutEnd( gui )\nGuiLayoutBeginVertical( gui, 0, screen_height * 0.96 - rows_num * ( 20 + 2 ) + 2, true )\n	local note_not_selected = text_get( \"spell_box_commmon_tips\", shortcut_texts.select )\n	local note_selected = text_get( \"spell_box_commmon_tips_selected\", shortcut_texts.deselect )\n\n	local total_count = rows_num * actions_per_row\n	local panel_offset = panel_row_offset * actions_per_row\n	for i = 1 + panel_offset, total_count + panel_offset do\n		if i % actions_per_row == 1 % actions_per_row then\n			if edit_panel_state.get_autocap_enabled() or capacity - i + 1 >= actions_per_row then\n				GuiLayoutBeginHorizontal( gui, horizontal_centered_x( actions_per_row ), 0, true )\n			else\n				GuiLayoutBeginHorizontal( gui, horizontal_centered_x( capacity % actions_per_row ), 0, true )\n			end\n		end\n		local selected, action_id, uses_remaining\n		if common_actions[ i ] then\n			selected, action_id, uses_remaining = unpack( common_actions[ i ] )\n		end\n		if uses_remaining == \"\" then uses_remaining = nil end\n		local note = selected and note_selected or note_not_selected\n		if not create_real_sprite then\n			local left_click, right_click = do_action_button( action_id, 0, 0, selected, do_least_tooltip, uses_remaining, note, show_uses_remaining )\n			if left_click or right_click then\n				do_shortcuts( edit_panel_state, left_click, right_click, i, action_id, capacity )\n			end\n		else\n			GuiOptionsAddForNextWidget( gui, GUI_OPTION.NonInteractive )\n			GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/transparent_20x20.png\" )\n			local _,_,_,x,y = previous_data( gui )\n			local this_action_data = action_data[ action_id ]\n			if this_action_data then\n				local world_x, world_y = get_world_position( x, y )\n				GameCreateSpriteForXFrames( this_action_data.sprite, world_x, world_y, false, 0, 0, 2, true )\n			end\n		end\n		if i == capacity and not edit_panel_state.get_autocap_enabled() then\n			GuiLayoutEnd( gui )\n			break\n		end\n\n		if i % actions_per_row == 0 or i == total_count then\n			GuiLayoutEnd( gui )\n		end\n	end\nGuiLayoutEnd( gui )\n\nif not_showing_all and not offset_reached_end then\n	if GuiImageButton( gui, next_id(), horizontal_centered_x(1), screen_height * 0.96 + 2, \"\", \"mods/spell_lab_shugged/files/gui/buttons/pagedown.png\" ) then\n		edit_panel_state.set_offset( panel_row_offset + 1 )\n	end\nend\n\nif edit_panel_state.need_sync() then\n	local ability = EntityGetFirstComponentIncludingDisabled( held_wand, \"AbilityComponent\" )\n	if not ability then return end\n	local old_capacity = capacity\n	local old_deck_capacity = WANDS.wand_get_stat( held_wand, \"deck_capacity\" )\n	WANDS.wand_clear_actions( held_wand )\n	local pa_num = 0\n	for a in state_str_iter_permanent_actions( edit_panel_state.get_permanent() ) do\n		if a ~= \"\" then\n			pa_num = pa_num + 1\n			local action_entity = CreateItemActionEntity( a, x, y )\n			EntityAddChild( held_wand, action_entity )\n			local item_comp = EntityGetFirstComponentIncludingDisabled( action_entity, \"ItemComponent\" )\n			ComponentSetValue2( item_comp, \"permanently_attached\", true )\n			ComponentSetValue2( item_comp, \"inventory_slot\", 0, 0 )\n			EntitySetComponentsWithTagEnabled( action_entity, \"enabled_in_world\", false )\n		end\n	end\n	local i = 0\n	local i_trimmed_end_space = 0\n	for _, a, u in state_str_iter_actions( edit_panel_state.get() ) do\n		-- if held_wand_actions[ index ] then\n		-- 	EntityRemoveFromParent( held_wand_actions[ index ].entity )\n		-- 	EntityKill( held_wand_actions[ index ].entity )\n		-- end\n		if a and a ~= \"\" then\n			local action_entity = CreateItemActionEntity( a, x, y )\n			EntityAddChild( held_wand, action_entity )\n			local item_comp = EntityGetFirstComponentIncludingDisabled( action_entity, \"ItemComponent\" )\n			local _, item_y = ComponentGetValue2( item_comp, \"inventory_slot\" )\n			ComponentSetValue2( item_comp, \"inventory_slot\", i, item_y )\n			local this_action_data = action_data[ a ]\n			local never_unlimited = this_action_data.never_unlimited\n			if this_action_data.max_uses then\n				if world_state_unlimited_spells and not never_unlimited then\n					-- CreateItemActionEntity has already done it\n				elseif not u or u == \"\" then\n					-- CreateItemActionEntity has already done it\n				else\n					ComponentSetValue2( item_comp, \"uses_remaining\", tonumber( u ) )\n				end\n			end\n			i = i + 1\n			i_trimmed_end_space = i\n			EntitySetComponentsWithTagEnabled( action_entity, \"enabled_in_world\", false )\n		elseif not edit_panel_state.get_force_compact_enabled() then\n			i = i + 1\n		end\n	end\n	local deck_capacity_taken = i_trimmed_end_space + pa_num\n	if edit_panel_state.get_autocap_enabled() or old_deck_capacity < deck_capacity_taken then\n		WANDS.wand_set_stat( held_wand, \"deck_capacity\", deck_capacity_taken )\n	else\n		WANDS.wand_set_stat( held_wand, \"deck_capacity\", old_capacity + pa_num )\n	end\n\n	force_refresh_held_wands()\n	edit_panel_state.done_sync()\nend"
_TWWE_VFS["mods/spell_lab_shugged/files/gui/edit_panel_utils.lua"] = "function fit_into_capacity( current_actions, times_inserting, max_capacity )\n	local empty_slots_taken = 0\n	for i = max_capacity + times_inserting, 1, -1 do\n		if empty_slots_taken == times_inserting then return true end\n		local a = current_actions[ i ]\n		if not a or a[2] == \"\" then\n			empty_slots_taken = empty_slots_taken + 1\n			table.remove( current_actions, i )\n		end\n	end\n	return empty_slots_taken == times_inserting\nend\n\nfunction set_action( edit_panel_state, action_id, uses_remaining, do_replace, max_capacity, left_insert )\n	if edit_panel_state.get_autocap_enabled() then\n		max_capacity = nil\n	end\n	local current_actions = {}\n	local set = false\n	local times_inserting = 0\n	for s, a, u in state_str_iter_actions( edit_panel_state.get() ) do\n		if s then\n			if left_insert then\n				table.insert( current_actions, { true, action_id, uses_remaining } )\n			end\n			if not do_replace and a ~= \"\" then\n				table.insert( current_actions, { false, a, u } )\n				times_inserting = times_inserting + 1\n			end\n			if not left_insert then\n				table.insert( current_actions, { true, action_id, uses_remaining } )\n			end\n			set = true\n		else\n			table.insert( current_actions, { s, a, u } )\n		end\n	end\n	if not set then\n		times_inserting = times_inserting + 1\n		if not left_insert then\n			table.insert( current_actions, { false, action_id, uses_remaining } )\n		else\n			table.insert( current_actions, 1, { false, action_id, uses_remaining } )\n		end\n	end\n	if not do_replace and max_capacity then\n		if not fit_into_capacity( current_actions, times_inserting, max_capacity ) then\n			GamePrint( text_get_translated( \"no_enough_space\" ) )\n			return\n		end\n	end\n	edit_panel_state.set( table_to_state_str( current_actions ), wrap_key( \"operation_set_action\" ) )\nend\nfunction set_action_group( edit_panel_state, action_group, do_replace, max_capacity, left_insert )\n	if edit_panel_state.get_autocap_enabled() then\n		max_capacity = nil\n	end\n	local current_actions = {}\n	local i = 1\n	local last_insert_index = 1\n	local set = false\n	local times_inserting = 0\n	for s, a, u in state_str_iter_actions( edit_panel_state.get() ) do\n		local action_to_set = action_group[ i ]\n		if action_to_set and s then\n			if left_insert then\n				table.insert( current_actions, { true, action_to_set[1], action_to_set[2] } )\n			end\n			if not do_replace and a ~= \"\" then\n				table.insert( current_actions, { false, a, u } )\n				times_inserting = times_inserting + 1\n			end\n			if not left_insert then\n				table.insert( current_actions, { true, action_to_set[1], action_to_set[2] } )\n			end\n			i = i + 1\n			last_insert_index = #current_actions\n			set = true\n		else\n			table.insert( current_actions, { s, a, u } )\n		end\n	end\n	if i <= #action_group then\n		if not set then\n			last_insert_index = 0\n		end\n		if not left_insert then\n			for j = i, #action_group do\n				table.insert( current_actions, { true, action_group[ j ][1], action_group[ j ][2] } )\n				times_inserting = times_inserting + 1\n			end\n		else\n			for j = #action_group, i, -1 do\n				table.insert( current_actions, last_insert_index + 1, { true, action_group[ j ][1], action_group[ j ][2] } )\n				times_inserting = times_inserting + 1\n			end\n		end\n	end\n	if not do_replace and max_capacity then\n		if not fit_into_capacity( current_actions, times_inserting, max_capacity ) then\n			GamePrint( text_get_translated( \"no_enough_space\" ) )\n			return\n		end\n	end\n	edit_panel_state.set( table_to_state_str( current_actions ), wrap_key( \"operation_set_action_group\" ) )\nend"
_TWWE_VFS["mods/spell_lab_shugged/files/gui/editable_text.lua"] = "local editable_text = {}\neditable_text.text = \"\"\neditable_text.input_anchor = 1\n\nfunction editable_text:try_on_changed()\n	if self.on_changed then\n		self.on_changed()\n	end\nend\n\nlocal function insert_character( str, char, index )\n	return string.sub( str, 1, index - 1 ) .. char .. string.sub( str, index, -1 )\nend\n\nfunction editable_text:insert_character( char )\n	self.text = insert_character( self.text, char, self.input_anchor )\n	self.input_anchor = self.input_anchor + 1\n	self:try_on_changed()\nend\n\nfunction editable_text:input_anchor_move_left()\n	if self.input_anchor > 1 then\n		self.input_anchor = self.input_anchor - 1\n	end\nend\n\nfunction editable_text:input_anchor_move_right()\n	if self.input_anchor <= #self.text then\n		self.input_anchor = self.input_anchor + 1\n	end\nend\n\nfunction editable_text:input_anchor_move_to_last_word()\n	local str_left = string.sub( self.text, 1, self.input_anchor - 1 )\n	local last_word_idx, _, _ = string.find( str_left, \"[^ ]* *$\" )\n	if last_word_idx then\n		self.input_anchor = last_word_idx\n	end\nend\n\nfunction editable_text:input_anchor_move_to_next_word()\n	local str_right = string.sub( self.text, self.input_anchor, -1 )\n	local _, next_word_idx, _ = string.find( str_right, \"^ *[^ ]*\" )\n	if next_word_idx then\n		self.input_anchor = self.input_anchor + next_word_idx\n	end\nend\n\nfunction editable_text:left_delete()\n	if self.input_anchor >= 2 then\n		self.text =\n			string.sub( self.text, 1, self.input_anchor - 2 )\n			.. string.sub( self.text, self.input_anchor, -1 )\n		self.input_anchor = self.input_anchor - 1\n		self:try_on_changed()\n	end\nend\n\nfunction editable_text:right_delete()\n	if self.input_anchor <= #self.text then\n		self.text =\n			string.sub( self.text, 1, self.input_anchor - 1 )\n			.. string.sub( self.text, self.input_anchor + 1, -1 )\n		self:try_on_changed()\n	end\nend\n\nfunction editable_text:input_anchor_move_to_beginning()\n	self.input_anchor = 1\nend\n\nfunction editable_text:input_anchor_move_to_end()\n	self.input_anchor = #self.text + 1\nend\n\nfunction editable_text:clear()\n	self.text = \"\"\n	self.input_anchor = 1\n	self:try_on_changed()\nend\n\nreturn editable_text"
_TWWE_VFS["mods/spell_lab_shugged/files/gui/extra_modifiers_supported.lua"] = "extra_modifiers_supported = {\n	\"critical_hit_boost\",\n	\"critical_plus_small\",\n	\"powerful_shot\",\n	\"projectile_homing_shooter\",\n	\"food_clock\",\n	\"damage_plus_small\",\n	\"extra_knockback\",\n	\"lower_spread\",\n	\"laser_aim\",\n	\"low_recoil\",\n	\"bounce\",\n	\"projectile_homing_shooter_wizard\",\n	\"projectile_alcohol_trail\",\n	\"duplicate_projectile\",\n	\"fast_projectiles\",\n	\"slow_firing\",\n}"
_TWWE_VFS["mods/spell_lab_shugged/files/gui/get_player.lua"] = "function get_player()\n	return EntityGetWithTag( \"player_unit\" )[1]\nend"
_TWWE_VFS["mods/spell_lab_shugged/files/gui/gui_elements.lua"] = "SCROLL_TABLE_WIDTH = 174\nfunction do_scroll_table( scroll_id, width, height, height_autofit, hover_callback, cell_list, cell_gui_func, row_size )\n	row_size = row_size or 8\n	width = width or SCROLL_TABLE_WIDTH\n	if height_autofit then\n		local num_rows = math.max( 1, math.ceil( #cell_list / row_size ) )\n		height = math.min( num_rows * 20, height or 160 )\n	end\n	height = math.max( height, 20 )\n	local _x, _y\n\n	GuiBeginScrollContainer( gui, scroll_id, 0, 0, width, height )\n		do\n			local _,_,_,x,y,width,height,_,_,_,_ = previous_data( gui )\n			_x, _y = x, y\n			local mx, my = get_mouse_pos_on_screen()\n			-- extra 2 pixels for the margins\n			local hovered = -2 <= mx - x and mx - x <= width + 2 and -2 <= my - y and my - y <= height + 2\n			if hover_callback then\n				hover_callback( hovered )\n			end\n			scroll_box_no_wand_switching( hovered )\n		end\n		GuiLayoutBeginVertical( gui, 0, 0 )\n			local index = 1\n			local cell = cell_list[ index ]\n			while cell do\n				GuiLayoutBeginHorizontal( gui, 0, 0 )\n					local cells_in_row = 0\n					while cell and cells_in_row < row_size do\n						cell_gui_func( cell, index )\n						cells_in_row = cells_in_row + 1\n						index = index + 1\n						cell = cell_list[ index ]\n					end\n				GuiLayoutEnd( gui )\n				GuiLayoutAddVerticalSpacing( gui, -2 )\n			end\n			if index == 1 then -- no cell to show\n				GuiText( gui, 0, 0, wrap_key( \"scroll_table_nothing\" ) )\n			end\n		GuiLayoutEnd( gui )\n	GuiEndScrollContainer( gui )\n	return _x, _y, width, height\nend\n\nfunction do_flag_toggle_image_button( filepath, flag, option_text, click_callback, description )\n	local mod_settings_key = wrap_setting_key( flag )\n	if not ModSettingGet( mod_settings_key ) then\n		GuiOptionsAddForNextWidget( gui, GUI_OPTION.DrawSemiTransparent )\n	end\n	local left_click, right_click = GuiImageButton( gui, next_id(), 0, 0, \"\", filepath )\n	if left_click then\n		sound_button_clicked()\n		local new = not ModSettingGet( mod_settings_key )\n		ModSettingSet( mod_settings_key, new )\n		if click_callback then\n			click_callback( new )\n		end\n	end\n	option_text = option_text or flag\n	option_text = text_get_translated( option_text )\n	if ModSettingGet( mod_settings_key ) then\n		GuiTooltip( gui, text_get_translated( \"disable\" ) .. option_text, description or \"\" )\n	else\n		GuiTooltip( gui, text_get_translated( \"enable\" ) .. option_text, description or \"\" )\n	end\n	return left_click, right_click\nend\n\nfunction do_action_image( id, action_id, x, y, alpha, scale_x, scale_y, rotation )\n	x = x or 0\n	y = y or 0\n	alpha = alpha or 1.0\n	scale_x = scale_x or 1.0\n	scale_y = scale_y or 1.0\n	rotation = rotation or 0.0\n\n	local image_sprite = \"mods/spell_lab_shugged/files/gui/buttons/empty_spell.png\"\n	local this_action_data = action_data[action_id]\n	local spell_box_suffix = \"\"\n	if this_action_data then spell_box_suffix = spell_box_suffix .. \"_\" .. this_action_data.type end\n	if this_action_data then\n		image_sprite = this_action_data.sprite\n	end\n	GuiImage( gui, id, x, y, image_sprite, alpha, scale_x, scale_y, rotation )\n	GuiZSetForNextWidget( gui, 1 )\n	GuiImage( gui, next_id(), -20, 0, \"mods/spell_lab_shugged/files/gui/buttons/spell_box\"..spell_box_suffix..\".png\", 1.0, 1.0, 0 )\nend\n\nfunction do_action_button( action_id, x, y, selected, tooltip_func, uses_remaining, note, extra_gui, empty_slot_show_tooltip, no_title )\n	if x == nil then x = 0 end\n	if y == nil then y = 0 end\n	local image_sprite = \"mods/spell_lab_shugged/files/gui/buttons/empty_spell.png\"\n	local this_action_data =  action_data[action_id]\n	local left_click,right_click,hover\n	local spell_box_suffix = \"\"\n\n	GuiLayoutBeginHorizontal( gui, 0, 0 )\n	\n	if this_action_data then spell_box_suffix = spell_box_suffix .. \"_\" .. this_action_data.type end\n	if this_action_data then\n		image_sprite = this_action_data.sprite\n	end\n	local this_action_metadata = action_metadata[ action_id ]\n\n	GuiImageButton( gui, next_id(), 2, 2, \"\", image_sprite )\n	local left_click,right_click,hover = previous_data( gui )\n\n	if selected then\n		spell_box_suffix = spell_box_suffix .. \"_active\"\n	elseif hover then\n		spell_box_suffix = spell_box_suffix .. \"_hover\"\n	end\n\n	--if tooltip_string ~= nil then GuiTooltip( gui, tooltip_string, \"\" ) end\n	--if this_action_data then GuiTooltip( gui, GameTextGetTranslatedOrNot( this_action_data.name ) .. \" (\" .. this_action_data.id .. \")\", \"\" ) end\n	if this_action_data or empty_slot_show_tooltip then\n		do_custom_tooltip( function()\n			GuiLayoutBeginVertical( gui, 0, 0 )\n				if this_action_data and not no_title then\n					local title = GameTextGetTranslatedOrNot( this_action_data.name )\n					if uses_remaining then\n						title = title .. \"(\" .. tostring( uses_remaining ) .. \")\"\n					end\n					GuiText( gui, 0, 0, title )\n				end\n				if tooltip_func then\n					tooltip_func( this_action_data, this_action_metadata )\n				end\n				if note then\n					GuiDimText( gui, 0, 0, note )\n				end\n			GuiLayoutEnd( gui )\n		end, 2, -2 ) -- make it looks as if it belongs to the spell box\n	end\n\n	GuiZSetForNextWidget( gui, 1 )\n	GuiImage( gui, next_id(), -20, 0, \"mods/spell_lab_shugged/files/gui/buttons/spell_box\"..spell_box_suffix..\".png\", 1.0, 1.0, 0 )\n	if extra_gui then\n		local _,_,_,x,y,_,_,_,_,_,_ = previous_data( gui )\n		extra_gui( x, y, this_action_data, uses_remaining )\n	end\n\n	GuiLayoutEnd( gui )\n\n	if left_click or right_click then\n		sound_action_button_clicked()\n	end\n	return left_click, right_click\nend\n\nfunction do_fake_action_button( action_type, action_sprite, name, id, desc, type, semi_transparent, uses_remaining, properties )\n	GuiLayoutBeginHorizontal( gui, 0, 0 )\n\n	GuiImageButton( gui, next_id(), 2, 2, \"\", \"mods/spell_lab_shugged/files/gui/buttons/transparent_16x16.png\" )\n	\n	local left_click, right_click,hover,x1,y1 = previous_data( gui )\n	do_custom_tooltip( function()\n		GuiLayoutBeginVertical( gui, 0, 0, true )\n			GuiText( gui, 0, 0, name )\n			if id then\n				GuiDimText( gui, 0, 0, id )\n			end\n			if type then\n				GuiColoredText( gui, 0.5, 0.5, 1.0, 1.0, 0, 0, type )\n			end\n			GuiText( gui, 0, 0, desc )\n			if properties and #properties > 0 then\n				GuiLayoutAddVerticalSpacing( gui, 5 )\n				do_property_list( properties )\n			end\n		GuiLayoutEnd( gui )\n	end, 2, -2 )\n	\n	local sprite_width, sprite_height = GuiGetImageDimensions( gui, action_sprite )\n	GuiOptionsAddForNextWidget( gui, GUI_OPTION.Layout_NoLayouting )\n	GuiOptionsAddForNextWidget( gui, GUI_OPTION.NonInteractive )\n	if semi_transparent then\n		GuiOptionsAddForNextWidget( gui, GUI_OPTION.DrawSemiTransparent )\n	end\n	GuiImageButton( gui, next_id(), x1 - 2 + ( 20 - sprite_width ) / 2, y1 - 2 + ( 20 - sprite_height ) / 2, \"\", action_sprite, 1 )\n\n	GuiZSetForNextWidget( gui, 1 )\n	if semi_transparent then\n		GuiOptionsAddForNextWidget( gui, GUI_OPTION.DrawSemiTransparent )\n	end\n	local spell_box_suffix = tostring( action_type or ACTION_TYPE_PROJECTILE )\n	if hover then\n		spell_box_suffix = spell_box_suffix .. \"_hover\"\n	end\n	GuiImage( gui, next_id(), --[[-( 2 + sprite_width / 2 + 10 )]]-20, 0, \"mods/spell_lab_shugged/files/gui/buttons/spell_box_\"..spell_box_suffix..\".png\", 1.0, 1.0, 0 )\n	if uses_remaining then\n		show_uses_remaining( x1, y1, nil, uses_remaining )\n	end\n\n	GuiLayoutEnd( gui )\n\n	return left_click, right_click\nend\n\nfunction show_permanent_icon( x, y )\n	GuiZSetForNextWidget( gui, -1 )\n	GuiOptionsAddForNextWidget( gui, GUI_OPTION.Layout_NoLayouting )\n	GuiImage( gui, next_id(), x-2, y-2, \"data/ui_gfx/inventory/icon_gun_permanent_actions.png\", 1.0, 1.0, 0 )\nend\n\nfunction show_locked_state( x, y, this_action_data )\n	if not this_action_data or not this_action_data.spawn_requires_flag then return end\n	if HasFlagPersistent( this_action_data.spawn_requires_flag ) then\n		if mod_setting_get( \"show_icon_unlocked\" ) then\n			GuiZSetForNextWidget( gui, -1 )\n			GuiOptionsAddForNextWidget( gui, GUI_OPTION.Layout_NoLayouting )\n			GuiImage( gui, next_id(), x+14, y-2, \"mods/spell_lab_shugged/files/gui/unlocked.png\", 0.3, 1.0, 0 )\n		end\n	else\n		GuiZSetForNextWidget( gui, -1 )\n		GuiOptionsAddForNextWidget( gui, GUI_OPTION.Layout_NoLayouting )\n		GuiImage( gui, next_id(), x+14, y-2, \"mods/spell_lab_shugged/files/gui/locked.png\", 1.0, 1.0, 0 )\n	end\nend\n\nfunction show_uses_remaining( x, y, _, uses_remaining, scale )\n	if not uses_remaining or tonumber( uses_remaining ) < 0 then return end\n	scale = scale or 1\n	local offset = -2 * scale\n	x, y = x + offset, y + offset\n	GuiZSetForNextWidget( gui, -1 )\n	GuiOptionsAddForNextWidget( gui, GUI_OPTION.Layout_NoLayouting )\n	GuiText( gui, x, y, tostring( uses_remaining ), scale, \"data/fonts/font_pixel_noshadow.xml\", true )\nend\n\nfunction do_property_list( lines )\n	for _, p in ipairs( lines ) do\n		local name = p[1]\n		local value = p[2]\n		GuiLayoutBeginHorizontal( gui, 0, 0 )\n			GuiColoredText( gui, 0.811, 0.811, 0.811, 1.0, 0, 0, name )\n			local _,_,_,_,_,width,_,_,_,_,_ = previous_data( gui )\n			GuiColoredText( gui, 1.0, 0.75, 0.5, 1.0, 72 - width, 0, tostring( value ) )\n		GuiLayoutEnd( gui )\n		GuiLayoutAddVerticalSpacing( gui, -2 )\n	end\nend\n\nfunction do_least_tooltip( this_action_data, this_action_metadata )\n	GuiDimText( gui, 0, 0, this_action_data.id )\n	GuiColoredText( gui, 0.5, 0.5, 1.0, 1.0, 0, 0, GameTextGetTranslatedOrNot( type_text[ this_action_data.type ] ) )\nend\n\nfunction do_verbose_tooltip( this_action_data, this_action_metadata )\n	local c_lines = c_metadata_to_lines( this_action_metadata.c )\n	local projectiles_lines, num_proj_lines = proj_metadata_to_lines( this_action_metadata.projectiles )\n	\n	local title = GameTextGetTranslatedOrNot( this_action_data.name )\n	if this_action_data.max_uses then\n		title = title .. ( \"(\" .. tostring( this_action_data.max_uses ) .. \")\" )\n	end\n	GuiText( gui, 0, 0, title )\n	\n	GuiDimText( gui, 0, 0, this_action_data.id )\n	GuiColoredText( gui, 0.5, 0.5, 1.0, 1.0, 0, 0, GameTextGetTranslatedOrNot( type_text[ this_action_data.type ] ) )\n	GuiText( gui, 0, 0, word_wrap( GameTextGetTranslatedOrNot( this_action_data.description ) ) )\n	if not this_action_metadata then return end\n	GuiLayoutAddVerticalSpacing( gui, 5 )\n	if this_action_metadata.projectiles then\n		GuiText( gui, 0, 0, wrap_key( \"spell_data\" ) )\n	end\n	\n	do_property_list( c_lines )\n	\n	local only_one_proj = #projectiles_lines == 1\n	for proj_index, proj_lines in ipairs( projectiles_lines ) do\n		if only_one_proj then\n			GuiText( gui, 0, 0, wrap_key( \"projectile_data\" ) )\n		else\n			GuiText( gui, 0, 0, GameTextGet( wrap_key( \"projectile_nth_data\" ), tostring( proj_index ) ) )\n		end\n		do_property_list( proj_lines )\n	end\nend\n\nfunction show_tooltip( content_fn, x, y )\n	GuiLayoutBeginLayer( gui )\n		GuiLayoutBeginVertical( gui, x, y, true )\n			GuiBeginAutoBox( gui )\n				content_fn()\n				GuiZSetForNextWidget( gui, 1 )\n			GuiEndAutoBoxNinePiece( gui )\n		GuiLayoutEnd( gui )\n	GuiLayoutEndLayer( gui )\nend\n\nfunction GuiTooltip( gui, ... )\n	local texts = { ... }\n	do_custom_tooltip( function()\n		GuiLayoutBeginVertical( gui, 0, 0 )\n			local is_first = true\n			for i, text in ipairs( texts ) do\n				text = GameTextGetTranslatedOrNot( text )\n				for t in string.gmatch( text or \"\", \"[^\\n]+\" ) do\n					if is_first then\n						is_first = false\n					else\n						GuiLayoutAddVerticalSpacing( gui, 2 )\n					end\n					GuiText( gui, 0, 0, t )\n				end\n			end\n		GuiLayoutEnd( gui )\n	end, 2, 0, true )\nend\n\nlocal function autobox_size( content_fn )\n	local id_offset = 0\n	local function next_id()\n		id_offset = id_offset + 1\n		return id_offset\n	end\n\n	GuiIdPushString( gui, \"INVISIBLE_TOOLTIP\" )\n\n	GuiAnimateBegin( gui )\n	GuiAnimateAlphaFadeIn( gui, next_id(), 0, 0, false )\n\n	show_tooltip( content_fn, 0, 0 )\n\n	GuiAnimateEnd( gui )\n\n	GuiIdPop( gui )\n\n	local _,_,_,_,_,width,height,draw_x,draw_y,draw_width,draw_height = previous_data( gui )\n	return width, height\nend\n\nfunction do_custom_tooltip( callback, x_offset, y_offset, animated )\n	if not callback then return end\n	x_offset = x_offset or 0\n	y_offset = y_offset or 0\n\n	local left_click,right_click,hover,x,y,width,height,draw_x,draw_y,draw_width,draw_height = previous_data( gui )\n	if not hover then return end\n\n	local tooltip_width, tooltip_height = autobox_size( callback )\n\n	GuiIdPushString( gui, \"TOOLTIP\" )\n\n	if animated then\n		GuiAnimateBegin( gui )\n		GuiAnimateAlphaFadeIn( gui, 2 * peek_next_id(), 0.08, 0.1, false )\n		GuiAnimateScaleIn( gui, 2 * peek_next_id() + 1, 0.08, false )\n	end\n\n	GuiZSet( gui, -1024 )\n\n	local align_left = x + width / 2 > screen_width / 2 \n	if align_left then\n		GuiOptionsAdd( gui, GUI_OPTION.Align_Left )\n	end\n\n	x_offset = x_offset + 5 + 2\n	if align_left then\n		x_offset = -x_offset\n	else\n		x_offset = x_offset + width\n	end\n\n	if y + y_offset + tooltip_height > screen_height then\n		y_offset = y_offset - ( y + y_offset + tooltip_height - screen_height )\n	end\n\n	show_tooltip( callback, x + x_offset, y + y_offset )\n\n	if align_left then\n		GuiOptionsRemove( gui, GUI_OPTION.Align_Left )\n	end\n\n	GuiZSet( gui, 1024 )\n\n	if animated then\n		GuiAnimateEnd( gui )\n	end\n\n	GuiIdPop( gui )\nend\n\nlocal function show_simple_action_image( action_id, uses_remaining )\n	if action_id and action_id ~= \"\" then\n		local this_action_data = action_data[ action_id ]\n		local sprite = ( this_action_data and this_action_data.sprite ) and this_action_data.sprite or \"data/ui_gfx/gun_actions/_unidentified.png\"\n		GuiZSetForNextWidget( gui, -1 )\n		GuiImage( gui, next_id(), 0, 0, sprite, 1.0, 0.5, 0 )\n		GuiImage( gui, next_id(), -11, -1, \"mods/spell_lab_shugged/files/gui/buttons/spell_box.png\", 1.0, 0.5, 0 )\n	else\n		GuiImage( gui, next_id(), -1, -1, \"mods/spell_lab_shugged/files/gui/buttons/spell_box.png\", 1.0, 0.5, 0 )\n	end\n	GuiZSet( gui, -1 )\n	local _,_,_,x,y = previous_data( gui )\n	show_uses_remaining( x, y, nil, uses_remaining, 0.5 )\n	GuiZSet( gui, 1 )\nend\n\nfunction do_simple_action_list( all_actions )\n	local common_actions = {}\n	local permanent_actions = {}\n	local max_x = 0\n	for _, a in ipairs( all_actions ) do\n		if a.permanent then\n			table.insert( permanent_actions, a.action_id )\n		else\n			if a.x ~= 0 then\n				common_actions[ a.x + 1 ] = { a.action_id, a.uses_remaining }\n				max_x = math.max( max_x, a.x + 1 )\n			else\n				common_actions[ max_x + 1 ] = { a.action_id, a.uses_remaining }\n				max_x = max_x + 1\n			end\n		end\n	end\n	do_simple_permanent_action_list( permanent_actions )\n	do_simple_common_action_list( common_actions, max_x )\nend\n\nfunction do_simple_permanent_action_list( permanent_actions )\n	if #permanent_actions == 0 then return end\n	GuiLayoutBeginHorizontal( gui, 0, 0 )\n	for _,permanent_action in pairs( permanent_actions ) do\n		show_simple_action_image( permanent_action )\n	end\n	GuiLayoutEnd( gui )\n	GuiLayoutAddVerticalSpacing( gui, 1 )\nend\n\nfunction do_simple_common_action_list( common_actions, max_x )\n	if max_x <= 0 then return end\n	local actions_per_row = 26\n	for i = 1, max_x do\n		if i % actions_per_row == 1 then\n			GuiLayoutBeginHorizontal( gui, 0, 0 )\n		end\n		show_simple_action_image( unpack( common_actions[ i ] or {} ) )\n		if i % actions_per_row == 0 or i == max_x then\n			GuiLayoutEnd( gui )\n		end\n	end\nend\n\nfunction do_flat_action_list( actions )\n	for _,action_id in ipairs( actions ) do\n		local this_action_data = action_data[action_id]\n		if this_action_data then GuiImage( gui, next_id(), 0, 0, this_action_data.sprite, 1.0, 0.5, 0 ) end\n	end\nend\n\nfunction do_wand_stats( gui, stats )\n	for _, v in ipairs( wand_stats ) do\n		if stats[ v.stat ] then\n			GuiLayoutBeginHorizontal( gui, 0, 0 )\n				GuiText( gui, 0, 0, v.label )\n				local left_click,right_click,hover,x,y,width,height,draw_x,draw_y,draw_width,draw_height = previous_data( gui )\n				GuiColoredText( gui, 1.0, 0.75, 0.5, 1.0, 72 - width, 0, v.text_callback( stats[ v.stat ] ) )\n			GuiLayoutEnd( gui )\n			GuiLayoutAddVerticalSpacing( gui, -4 )\n		end\n	end\nend"
_TWWE_VFS["mods/spell_lab_shugged/files/gui/gui_utils.lua"] = "local gui_z = 0\ndo\n	local old_GuiZSet = GuiZSet\n	function GuiZSet( gui, z )\n		gui_z = gui_z + z\n		old_GuiZSet( gui, gui_z )\n	end\n\n	local old_GuiZSetForNextWidget = GuiZSetForNextWidget\n	function GuiZSetForNextWidget( gui, z )\n		old_GuiZSetForNextWidget( gui, gui_z + z )\n	end\nend\nfunction reset_z()\n	gui_z = 0\nend\n\nfunction GuiColoredText( gui, red, green, blue, alpha, ... )\n	GuiColorSetForNextWidget( gui, red, green, blue, alpha )\n	GuiText( gui, ... )\nend\nfunction GuiSoftText( gui, ... )\n	GuiColorSetForNextWidget( gui, color(207,207,207,255) )\n	GuiText( gui, ... )\nend\nfunction GuiDimText( gui, ... )\n	GuiColorSetForNextWidget( gui, 0.5, 0.5, 0.5, 1.0 )\n	GuiText( gui, ... )\nend\n\nlocal cache_frame\nlocal cached_mouse_x, cached_mouse_y\nfunction get_mouse_pos_on_screen()\n	if now ~= cache_frame or not cached_mouse_x or not cached_mouse_y then\n		cached_mouse_x, cached_mouse_y = get_screen_position( DEBUG_GetMouseWorld() )\n		cache_frame = now\n	end\n	return cached_mouse_x, cached_mouse_y\nend\n\nfunction percent_to_ui_scale_y( y )\n	return y * screen_height / 100\nend\n\nfunction horizontal_centered_x( buttons_num, offset )\n	offset = offset or 0\n	return screen_width / 2 - ( ( buttons_num - offset ) * 22 + 2 ) / 2\nend\n\nfunction get_screen_position( x, y )\n	local camera_x, camera_y = GameGetCameraPos()\n	local res_width = MagicNumbersGetValue( \"VIRTUAL_RESOLUTION_X\" )\n	local res_height = MagicNumbersGetValue( \"VIRTUAL_RESOLUTION_Y\" )\n	local ax = (x - camera_x) / res_width * screen_width\n	local ay = (y - camera_y) / res_height * screen_height\n	return ax + screen_width * 0.5, ay + screen_height * 0.5\nend\n\nfunction get_world_position( x, y )\n	local camera_x, camera_y = GameGetCameraPos()\n	local res_width = MagicNumbersGetValue( \"VIRTUAL_RESOLUTION_X\" )\n	local res_height = MagicNumbersGetValue( \"VIRTUAL_RESOLUTION_Y\" )\n	local ax, ay = x - screen_width * 0.5, y - screen_height * 0.5\n	local wx = ax * res_width / screen_width + camera_x\n	local wy = ay * res_height / screen_height + camera_y\n	return wx, wy\nend\n\nfunction previous_data( gui )\n	local left_click,right_click,hover,x,y,width,height,draw_x,draw_y,draw_width,draw_height = GuiGetPreviousWidgetInfo( gui )\n	if left_click == 1 then left_click = true elseif left_click == 0 then left_click = false end\n	if right_click == 1 then right_click = true elseif right_click == 0 then right_click = false end\n	if hover == 1 then hover = true elseif hover == 0 then hover = false end\n	return left_click,right_click,hover,x,y,width,height,draw_x,draw_y,draw_width,draw_height\nend\n\nfunction sound_button_clicked()\n	if mod_setting_get( \"button_click_sound\" ) then\n		GamePlaySound( \"data/audio/Desktop/ui.bank\", \"ui/button_click\", GameGetCameraPos() )\n	end\nend\n\nfunction sound_action_button_clicked()\n	if mod_setting_get( \"action_button_click_sound\" ) then\n		GamePlaySound( \"data/audio/Desktop/ui.bank\", \"ui/button_click\", GameGetCameraPos() )\n	end\nend\n\nfunction previous_hovered( margin )\n	margin = margin or 0\n	local mx, my = get_mouse_pos_on_screen()\n	local _,_,_,x,y,width,height,_,_,_,_ = previous_data( gui )\n	return -margin + x < mx and mx < x + width + margin and -margin + y < my and my < y + height + margin\nend\n\nfunction scroll_box_no_wand_switching( hovered )\n	if hovered then\n		local mx, my = get_mouse_pos_on_screen()\n		GuiIdPushString( gui, \"NO_MORE_WAND_SWITCHING\" )\n		GuiAnimateBegin( gui )\n		GuiAnimateAlphaFadeIn( gui, 1, 0, 0, true )\n		GuiOptionsAddForNextWidget( gui, GUI_OPTION.Layout_NoLayouting )\n		GuiOptionsAddForNextWidget( gui, GUI_OPTION.AlwaysClickable )\n		GuiBeginScrollContainer( gui, 2, mx - 25, my - 25, 50, 50, false, 0, 0 )\n		GuiEndScrollContainer( gui )\n		GuiAnimateEnd( gui )\n		GuiIdPop( gui )\n		ModTextFileSetContent_Saved( \"mods/spell_lab_shugged/scroll_box_hovered.txt\", \"true\" )\n	else\n		ModTextFileSetContent_Saved( \"mods/spell_lab_shugged/scroll_box_hovered.txt\", \"false\" )\n	end\nend\n\nlocal ID_GAP = 64\nlocal id_remainder_table = {}\nlocal next_id_remainder = 1\n\n-- to avoid any id confliction\nfunction do_content_wrapped( content_fn, push_this_string )\n	local id_offset = id_remainder_table[ push_this_string ]\n	if not id_offset then\n		id_offset = next_id_remainder\n		id_remainder_table[ push_this_string ] = next_id_remainder\n		next_id_remainder = next_id_remainder + 1\n	end\n	local peek_next_id = function()\n		return id_offset\n	end\n	local next_id = function()\n		id_offset = id_offset + ID_GAP\n		return id_offset\n	end\n\n	local e = getfenv( content_fn )\n	e.id_offset = id_offset\n	e.peek_next_id = peek_next_id\n	e.next_id = next_id\n	setfenv( content_fn, e )\n\n	GuiIdPushString( gui, push_this_string )\n	content_fn()\n	GuiIdPop( gui )\nend"
_TWWE_VFS["mods/spell_lab_shugged/files/gui/keyboard_focus.lua"] = "dofile_once( \"mods/spell_lab_shugged/files/lib/controls_freezing_utils.lua\" )\nFocus_PlayerControls = {\n	id = \"player_controls\",\n	on_focused = function()\n		unfreeze_controls()\n	end,\n	on_unfocused = function()\n		freeze_controls()\n	end,\n	on_input = function( keyboard_input )\n		if not held_wand or not mod_setting_get( \"show_wand_edit_panel\" ) then return end\n		local edit_panel_state = access_edit_panel_state( held_wand )\n		if shortcut_check.check_input( keyboard_input, shortcuts.left_delete ) then\n			local current_actions = {}\n			local did = false\n			for s, a, u in state_str_iter_actions( edit_panel_state.get() ) do\n				if s then\n					did = true\n					if a == \"\" then\n						current_actions[ #current_actions ] = { true }\n					end\n					table.insert( current_actions, { false } )\n				else\n					table.insert( current_actions, { s, a, u } )\n				end\n			end\n			if did then\n				edit_panel_state.set( table_to_state_str( current_actions ), wrap_key( \"operation_delete_action\" ) )\n			end\n		end\n		if shortcut_check.check_input( keyboard_input, shortcuts.right_delete ) then\n			local current_actions = {}\n			local delete_next_action\n			local did = false\n			for s, a, u in state_str_iter_actions( edit_panel_state.get() ) do\n				if s then\n					did = true\n					if a == \"\" then\n						delete_next_action = true\n					end\n					table.insert( current_actions, { false } )\n				else\n					if not delete_next_action then\n						table.insert( current_actions, { s, a, u } )\n					else\n						table.insert( current_actions, { true } )\n						delete_next_action = false\n					end\n				end\n			end\n			if did then\n				edit_panel_state.set( table_to_state_str( current_actions ), wrap_key( \"operation_delete_action\" ) )\n			end\n		end\n		if shortcut_check.check_input( keyboard_input, shortcuts.undo ) then\n			edit_panel_state.undo()\n		end\n		if shortcut_check.check_input( keyboard_input, shortcuts.redo ) then\n			edit_panel_state.redo()\n		end\n		if shortcut_check.check_input( keyboard_input, shortcuts.transform_mortal_into_dummy ) then\n			if selecting_mortal_to_transform then\n				dofile( \"mods/spell_lab_shugged/files/scripts/transform_mortal_into_dummy.lua\" )\n				selecting_mortal_to_transform = false\n			end\n		end\n	end,\n}\n\nlocal current_focus = Focus_PlayerControls\nfunction change_keyboard_focus( focus )\n	if current_focus.id == focus.id then return false end\n	if current_focus.on_unfocused then\n		current_focus.on_unfocused()\n	end\n	if focus.on_focused then\n		focus.on_focused()\n	end\n	current_focus = focus\n	return true\nend\n\nfunction is_keyboard_focus( focus )\n	return current_focus.id == focus.id\nend\n\nfunction update_keyboard_input( keyboard_input )\n	if current_focus.on_input then\n		current_focus.on_input( keyboard_input )\n	end\nend"
_TWWE_VFS["mods/spell_lab_shugged/files/gui/keyboard_listener.lua"] = "local listened_keys = {}\ndo\n	KEYCODES_RAW, KEYCODES_BY_TYPE = unpack( dofile_once( \"mods/spell_lab_shugged/files/lib/keycodes_wrapped.lua\" ) )\n\n	local is_joystick_key_down = function( ... ) return InputIsJoystickButtonDown( 0, ... ) end\n	local is_joystick_key_just_down = function( ... ) return InputIsJoystickButtonJustDown( 0, ... ) end\n\n	for k, v in pairs( KEYCODES_BY_TYPE.Keyboard ) do\n		listened_keys[ k ] = { v, InputIsKeyDown, InputIsKeyJustDown }\n	end\n	for k, v in pairs( KEYCODES_BY_TYPE.Joystick ) do\n		listened_keys[ k ] = { v, is_joystick_key_down, is_joystick_key_just_down }\n	end\n\n	listened_keys.Key_LCTRL = nil\n	listened_keys.Key_RCTRL = nil\n	listened_keys.Key_LSHIFT = nil\n	listened_keys.Key_RSHIFT = nil\n	listened_keys.Key_LALT = nil\n	listened_keys.Key_RALT = nil\n\n	listened_keys.Key_CTRL = { nil,\n		function() return InputIsKeyDown( KEYCODES_RAW.Key_LCTRL ) or InputIsKeyDown( KEYCODES_RAW.Key_RCTRL ) end,\n		function() return InputIsKeyJustDown( KEYCODES_RAW.Key_LCTRL ) or InputIsKeyJustDown( KEYCODES_RAW.Key_RCTRL ) end,\n	}\n	listened_keys.Key_SHIFT = { nil,\n		function() return InputIsKeyDown( KEYCODES_RAW.Key_LSHIFT ) or InputIsKeyDown( KEYCODES_RAW.Key_RSHIFT ) end,\n		function() return InputIsKeyJustDown( KEYCODES_RAW.Key_LSHIFT ) or InputIsKeyJustDown( KEYCODES_RAW.Key_RSHIFT ) end,\n	}\n	listened_keys.Key_ALT = { nil,\n		function() return InputIsKeyDown( KEYCODES_RAW.Key_LALT ) or InputIsKeyDown( KEYCODES_RAW.Key_RALT ) end,\n		function() return InputIsKeyJustDown( KEYCODES_RAW.Key_LALT ) or InputIsKeyJustDown( KEYCODES_RAW.Key_RALT ) end,\n	}\n\nend\n\nlocal frames_keys_held = {}\nfor keyname, _ in pairs( listened_keys ) do\n	frames_keys_held[ keyname ] = 0\nend\n\nlocal listen_result_just_down = {}\nfunction listen_keyboard_just_down()\n	for name, tri in pairs( listened_keys ) do\n		local code = tri[1]\n\n		local current_frames_held = frames_keys_held[ name ]\n		listen_result_just_down[ name ] = tri[3]( code ) or current_frames_held > 30\n		if tri[2]( code ) then\n			frames_keys_held[ name ] = current_frames_held + 1\n		else\n			frames_keys_held[ name ] = 0\n		end\n	end\n	return listen_result_just_down\nend\n\nlocal listen_result_down = {}\nfunction listen_keyboard_down()\n	for name, tri in pairs( listened_keys ) do\n		listen_result_down[ name ] = tri[2]( tri[1] )\n	end\n	return listen_result_down\nend"
_TWWE_VFS["mods/spell_lab_shugged/files/gui/pickers.lua"] = "PICKERS = {\n	None = \"\",\n	SpellPicker = \"spell_picker\",\n	WandPicker = \"wand_picker\",\n	WandBox = \"wand_box\",\n	SpellGroupBox = \"spell_group_box\",\n	ShotEffects = \"shot_effects\",\n}\n\nlocal pickers_data = {}\n\npickers_data[\"\"] = {\n	buttons = function() end,\n	menu = function() end,\n	name = \"None\",\n}\n\nfor name, filename in pairs( PICKERS ) do\n	if #filename > 0 then\n		local data = dofile_once( \"mods/spell_lab_shugged/files/gui/pickers/\" .. filename .. \".lua\" )\n		data.name = name\n		pickers_data[ filename ] = data\n	end\nend\n\nlocal active_picker = \"\"\nlocal active_picker_data = pickers_data[\"\"]\n\nfunction is_picker_active( picker )\n	return picker == active_picker\nend\n\nfunction change_picker( picker )\n	local result = picker == active_picker\n	if result then picker = \"\" end\n	active_picker = picker\n	active_picker_data = pickers_data[ picker ]\n	return result\nend\n\nfunction do_active_picker_menu()\n	do_content_wrapped( active_picker_data.menu, active_picker_data.name .. \"_menu\" )\nend\n\nfunction do_active_picker_buttons()\n	do_content_wrapped( active_picker_data.buttons, active_picker_data.name .. \"_buttons\" )\nend\n\nfunction do_picker_button( filepath, picker, option_text, click_callback )\n	if picker ~= active_picker then\n		GuiOptionsAddForNextWidget( gui, GUI_OPTION.DrawSemiTransparent )\n	end\n	local result\n	if GuiImageButton( gui, next_id(), 0, 0, \"\", filepath ) then\n		sound_button_clicked()\n		result = change_picker( picker )\n		if click_callback then\n			click_callback( result )\n		end\n	end\n	option_text = text_get_translated( option_text )\n	if picker == active_picker then\n		GuiTooltip( gui, text_get_translated( \"disable\" ) .. option_text, \"\" )\n	else\n		GuiTooltip( gui, text_get_translated( \"enable\" ) .. option_text, \"\" )\n	end\nend"
_TWWE_VFS["mods/spell_lab_shugged/files/gui/pickers/shot_effects.lua"] = "dofile_once( \"mods/spell_lab_shugged/files/gui/shot_effect_entries.lua\" )\n\ndofile_once( \"data/scripts/perks/perk_list.lua\" )\nlocal perk_id_to_idx = {}\nfor idx, perk in ipairs( perk_list ) do\n	perk_id_to_idx[ perk.id ] = idx\nend\n\ndofile_once( \"data/scripts/status_effects/status_list.lua\" )\nlocal status_id_to_idx = {}\nfor idx, status in ipairs( status_effects ) do\n	status_id_to_idx[ status.id ] = idx\nend\n\ndofile_once( \"mods/spell_lab_shugged/files/lib/entity_xml_parser.lua\" )\n\nlocal SHOT_EFFECT_TYPE = {\n	extra_modifier = wrap_key( \"shot_effect_type_extra_modifier\" ),\n	shot_script    = wrap_key( \"shot_effect_type_shot_script\" ),\n	game_effect    = wrap_key( \"shot_effect_type_game_effect\" ),\n}\nlocal SHOT_EFFECT_SOURCE_TYPE = {\n	Perk         = wrap_key( \"shot_effect_source_type_perk\" ),\n	Status       = wrap_key( \"shot_effect_source_type_status\" ),\n	CustomEffect = wrap_key( \"shot_effect_source_type_custom_effect\" ),\n}\n\nlocal shot_effect_data = {}\nfor _, shot_effect in ipairs( shot_effect_entries ) do\n	local data = {}\n\n	data.id = shot_effect.id\n	data.name = shot_effect.name\n	data.desc = shot_effect.desc\n	data.icon = shot_effect.icon\n	data.source_type = shot_effect.source_type\n	data.max_count = shot_effect.max_count\n\n	local related_status = shot_effect.related_status\n	if related_status then\n		related_status = status_effects[ status_id_to_idx[ related_status ] ]\n		if related_status then\n			data.id = data.id or ( \"STATUS_\" .. related_status.id )\n			data.name = data.name or related_status.ui_name\n			data.desc = data.desc or related_status.ui_description\n			data.icon = data.icon or related_status.ui_icon\n			data.source_type = data.source_type or SHOT_EFFECT_SOURCE_TYPE.Status\n			data.max_count = data.max_count or 1\n		end\n	end\n\n	do\n		local related_custom_effect = shot_effect.related_custom_effect\n		if not related_custom_effect then goto related_custom_effect_skip end\n		local effect_xml_content = parse_entity_xml( related_custom_effect )\n		if not effect_xml_content then goto related_custom_effect_skip end\n		local icon_comp = effect_xml_content:first_of( \"UIIconComponent\" )\n		if not icon_comp then goto related_custom_effect_skip end\n		data.id = data.id or string.upper( related_custom_effect:match( \"([^/]+)%.xml$\" ) )\n		data.name = data.name or icon_comp.attr.name\n		data.desc = data.desc or icon_comp.attr.description\n		data.icon = data.icon or icon_comp.attr.icon_sprite_file\n		data.source_type = data.source_type or SHOT_EFFECT_SOURCE_TYPE.CustomEffect\n	end\n	::related_custom_effect_skip::\n\n	local related_perk = shot_effect.related_perk\n	if related_perk then\n		related_perk = perk_list[ perk_id_to_idx[ related_perk ] ]\n		if related_perk then\n			data.id = data.id or ( \"PERK_\" .. related_perk.id )\n			data.name = data.name or related_perk.ui_name\n			data.desc = data.desc or related_perk.ui_description\n			data.icon = data.icon or related_perk.perk_icon\n			data.source_type = data.source_type or SHOT_EFFECT_SOURCE_TYPE.Perk\n			if related_perk.stackable == STACKABLE_YES then\n				if related_perk.stackable_maximum then\n					data.max_count = data.max_count or related_perk.stackable_maximum\n				else\n					data.max_count = data.max_count or -1\n				end\n			else\n				data.max_count = data.max_count or 1\n			end\n		end\n	end\n\n	if not data.id or not data.icon or not data.name or not data.desc then\n		goto continue\n	end\n\n	local keys = { \"extra_modifier\", \"shot_script\", \"game_effect\", \"custom_child_entity\" }\n	for _, key in ipairs( keys ) do\n		local value = shot_effect[ key ]\n		if value ~= nil then\n			if type( value ) ~= \"table\" then\n				data[ key ] = { value }\n			else\n				data[ key ] = value\n			end\n			if SHOT_EFFECT_TYPE[ key ] then\n				data.type = data.type or SHOT_EFFECT_TYPE[ key ]\n			end\n		end\n	end\n\n	data.properties = shot_effect.properties or {}\n	if data.extra_modifier and #data.extra_modifier > 0 and not shot_effect.dont_use_fetched_metadata then\n		local metadata = extra_modifier_metadata[ data.extra_modifier[1] ]\n		if not metadata then\n			print( \"Invalid extra modifier id:\", tostring( data.extra_modifier[1] ) )\n		else\n			for _, v in ipairs( c_metadata_to_lines( metadata ) ) do\n				data.properties[ #data.properties + 1 ] = v\n			end\n		end\n	end\n	if data.max_count and data.max_count ~= -1 then\n		data.properties[ #data.properties + 1 ] = { wrap_key( \"shot_effect_max_count\" ), data.max_count }\n	else\n		data.properties[ #data.properties + 1 ] = { wrap_key( \"shot_effect_max_count\" ), wrap_key( \"shot_effect_max_count_infinite\" ) }\n	end\n\n	data.equivalent_action_type = shot_effect.equivalent_action_type or ACTION_TYPE_MODIFIER\n	data.no_unsafe = shot_effect.no_unsafe\n\n	shot_effect_data[ #shot_effect_data + 1 ] = data\n\n	::continue::\nend\n\nlocal function add_shot_effect( shot_effect )\n	local entity_id = EntityCreateNew()\n	EntityAddChild( player, entity_id )\n	EntityAddComponent2( entity_id, \"InheritTransformComponent\" )\n	EntityAddTag( entity_id, \"spell_lab_shugged_shot_effect\" )\n\n	EntityAddComponent2( entity_id, \"VariableStorageComponent\", { value_string = shot_effect.id } )\n\n	for _, extra_modifier in ipairs( shot_effect.extra_modifier or {} ) do\n		EntityAddComponent2( entity_id, \"ShotEffectComponent\", { extra_modifier = extra_modifier } )\n	end\n	for _, shot_script in ipairs( shot_effect.shot_script or {} ) do\n		EntityAddComponent2( entity_id, \"LuaComponent\", { script_shot = shot_script } )\n	end\n	for _, game_effect in ipairs( shot_effect.game_effect or {} ) do\n		EntityAddComponent2( entity_id, \"GameEffectComponent\", { effect = game_effect } )\n	end\n	for _, custom_child_entity in ipairs( shot_effect.custom_child_entity or {} ) do\n		local child_id = EntityLoad( custom_child_entity )\n		EntityAddChild( entity_id, child_id )\n	end\nend\n\nlocal function remove_shot_effect( shot_effect )\n	local id = shot_effect.id\n	for _, shot_effect_entity in ipairs( EntityGetAllChildren( player, \"spell_lab_shugged_shot_effect\" ) or {} ) do\n		local id_comp = EntityGetFirstComponent( shot_effect_entity, \"VariableStorageComponent\" )\n		if id == ComponentGetValue2( id_comp, \"value_string\" ) then\n			EntityRemoveFromParent( shot_effect_entity )\n			EntityKill( shot_effect_entity )\n			break\n		end\n	end\nend\n\nlocal picker = {}\npicker.menu = function()\n	local count_table = {}\n	for _, shot_effect_entity in ipairs( EntityGetAllChildren( player, \"spell_lab_shugged_shot_effect\" ) or {} ) do\n		local id_comp = EntityGetFirstComponent( shot_effect_entity, \"VariableStorageComponent\" )\n		local id = ComponentGetValue2( id_comp, \"value_string\" )\n		count_table[ id ] = ( count_table[ id ] or 0 ) + 1\n	end\n	GuiLayoutBeginVertical( gui, 640 * 0.05, 360 * 0.16, true )\n		do_scroll_table( next_id(), nil, nil, true, nil, shot_effect_data, function( shot_effect )\n			local count = count_table[ shot_effect.id ] or 0\n			local max_count = shot_effect.max_count\n			local unsafe_count_allowed = mod_setting_get( \"shot_effect_unsafe_count_allowed\" ) and not shot_effect.no_unsafe\n			local max_count_valid = max_count and max_count ~= -1\n			local count_shown\n			if count == 0 then\n				count_shown = nil\n			elseif not unsafe_count_allowed and max_count == 1 and count <= 1 then\n				count_shown = nil\n			else\n				count_shown = count\n			end\n			local source_type_shown = nil\n			if shot_effect.source_type then\n				source_type_shown = GameTextGet( wrap_key( \"shot_effect_source_type\" ), GameTextGetTranslatedOrNot( shot_effect.source_type ) )\n			end\n\n			local left_click, right_click = do_fake_action_button(\n				shot_effect.equivalent_action_type, shot_effect.icon, shot_effect.name, source_type_shown, shot_effect.desc,\n				shot_effect.type, count == 0, count_shown, shot_effect.properties )\n			if left_click then\n				if not max_count_valid or count < max_count or unsafe_count_allowed then\n					sound_button_clicked()\n					add_shot_effect( shot_effect )\n				elseif max_count == 1 and count == 1 then\n					sound_button_clicked()\n					remove_shot_effect( shot_effect )\n				end\n			elseif right_click then\n				if count > 0 then\n					sound_button_clicked()\n					remove_shot_effect( shot_effect )\n				end\n			end\n		end )\n	GuiLayoutEnd( gui )\nend\n\npicker.buttons = function()\n	GuiLayoutBeginHorizontal( gui, horizontal_centered_x(1,4), percent_to_ui_scale_y(2), true )\n		do_flag_toggle_image_button( \"mods/spell_lab_shugged/files/gui/buttons/unsafe_values.png\", \"shot_effect_unsafe_count_allowed\" )\n	GuiLayoutEnd( gui )\nend\n\nreturn picker"
_TWWE_VFS["mods/spell_lab_shugged/files/gui/pickers/spell_group_box.lua"] = "local saved_spell_groups = {}\nlocal saved_spell_group_data = mod_setting_get( \"saved_spell_groups\" )\nif saved_spell_group_data ~= nil then\n	local loaded_spell_groups = smallfolk.loads( saved_spell_group_data )\n	for k,v in pairs( loaded_spell_groups ) do\n		if #v > 0 then\n			table.insert( saved_spell_groups, v )\n		end\n	end\nend\n\nlocal function serialize_saved_spell_groups()\n	if saved_spell_groups ~= nil then\n		mod_setting_set( \"saved_spell_groups\", smallfolk.dumps( saved_spell_groups ) )\n	end\nend\n\nlocal picker = {}\nlocal selected_spell_group_index = 0\npicker.menu = function()\n	GuiLayoutBeginVertical( gui, 640 * 0.05, 360 * 0.16, true )\n		do_scroll_table( next_id(), nil, nil, true, nil, saved_spell_groups, function( saved_spell_group, index )\n			GuiImageButton( gui, next_id(), 2, 2, \"\", \"mods/spell_lab_shugged/files/gui/buttons/transparent_16x16.png\" )\n			local left_click,right_click,_,x,y,_,_,_,_,_,_ = previous_data( gui )\n			if shortcut_check.check( shortcuts.select, left_click, right_click ) then\n				if selected_spell_group_index ~= index then\n					selected_spell_group_index = index\n				else\n					selected_spell_group_index = 0\n				end\n			elseif shortcut_check.check( shortcuts.deselect, left_click, right_click ) then\n				if selected_spell_group_index == index then\n					selected_spell_group_index = 0\n				end\n			elseif shortcut_check.check( shortcuts.swap, left_click, right_click ) then\n				if selected_spell_group_index ~= index then\n					saved_spell_groups[ selected_spell_group_index ], saved_spell_groups[ index ] =\n						saved_spell_groups[ index ], saved_spell_groups[ selected_spell_group_index ]\n					selected_spell_group_index = index\n				end\n			end\n			do_custom_tooltip( function()\n				do_simple_common_action_list( saved_spell_group, #saved_spell_group )\n				GuiDimText( gui, 0, 0, text_get_translated( \"spell_group_select\" ) )\n			end, 3, -0.5 )\n\n			local spell_box\n			if selected_spell_group_index == index then\n				spell_box = \"mods/spell_lab_shugged/files/gui/buttons/spell_box_active.png\"\n			else\n				spell_box = \"mods/spell_lab_shugged/files/gui/buttons/transparent_20x20.png\"\n			end\n			GuiImage( gui, next_id(), -20, 0, spell_box, 1, 1, 0 )\n\n			local i = 1\n			while i <= 4 and i <= #saved_spell_group do\n				local action_id = saved_spell_group[ i ][1]\n\n				local this_action_data = action_data[ action_id ]\n				local action_sprite = ( this_action_data and this_action_data.sprite )\n					and this_action_data.sprite or \"data/ui_gfx/gun_actions/_unidentified.png\"\n\n				local spell_box = { \"mods/spell_lab_shugged/files/gui/buttons/spell_box\", \"\", \".png\" }\n				if this_action_data then spell_box[2] = \"_\" .. this_action_data.type or \"\" end\n\n				local x_offset, y_offset\n				if i == 1 then x_offset, y_offset = 1, 1\n				elseif i == 2 then x_offset, y_offset = 10, 1\n				elseif i == 3 then x_offset, y_offset = 1, 10\n				elseif i == 4 then x_offset, y_offset = 10, 10\n					if i < #saved_spell_group then\n						action_sprite = \"mods/spell_lab_shugged/files/gui/buttons/more_spells.png\"\n						spell_box[2] = \"\"\n					end\n				end\n				x_offset, y_offset = x_offset - 1.5, y_offset - 1.5\n\n				if this_action_data then\n					GuiOptionsAddForNextWidget( gui, GUI_OPTION.Layout_NoLayouting )\n					GuiZSetForNextWidget( gui, -2 )\n					GuiImage( gui, next_id(), x + x_offset, y + y_offset, action_sprite, 1.0, 0.5, 0 )\n				end\n				GuiOptionsAddForNextWidget( gui, GUI_OPTION.Layout_NoLayouting )\n				GuiZSetForNextWidget( gui, -1 )\n				GuiImage( gui, next_id(), x + x_offset - 1, y + y_offset - 1, table.concat( spell_box ), 1.0, 0.5, 0 )\n\n				i = i + 1\n			end\n		end, 8 )\n	GuiLayoutEnd( gui )\nend\n\npicker.buttons = function()\n	local buttons_num = 1\n	if held_wand and mod_setting_get( \"show_wand_edit_panel\" ) then\n		buttons_num = buttons_num + 3\n	end\n	GuiLayoutBeginHorizontal( gui, horizontal_centered_x(buttons_num,4), percent_to_ui_scale_y(2), true )\n		if held_wand and mod_setting_get( \"show_wand_edit_panel\" ) then\n			if GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/save_wand.png\" ) then\n				if not held_wand then return end\n				sound_button_clicked()\n				local edit_panel_state = access_edit_panel_state( held_wand )\n				local actions_to_save = {}\n				for s, a, u in state_str_iter_actions( edit_panel_state.get() ) do\n					if s then\n						if u == \"\" then u = nil end\n						table.insert( actions_to_save, { a, u } )\n					end\n				end\n				if #actions_to_save > 0 then\n					table.insert( saved_spell_groups, 1, actions_to_save )\n					serialize_saved_spell_groups()\n				end\n			end\n			GuiTooltip( gui, wrap_key( \"spell_group_box_save\" ), \"\" )\n		end\n\n		if GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/delete_wand.png\" ) then\n			if selected_spell_group_index ~= 0 then\n				sound_button_clicked()\n				table.remove( saved_spell_groups, selected_spell_group_index )\n				serialize_saved_spell_groups()\n			end\n		end\n		GuiTooltip( gui, wrap_key( \"spell_group_box_delete\" ), \"\" )\n\n		if held_wand and mod_setting_get( \"show_wand_edit_panel\" ) then\n			local left_click, right_click = GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/load_into_wand.png\" )\n			if left_click or right_click then\n				local saved_spell_group = saved_spell_groups[ selected_spell_group_index ]\n				local do_replace = mod_setting_get( \"replace_mode\" )\n				if shortcut_check.check( shortcuts.replace_switch_temp ) then do_replace = not do_replace end\n				if saved_spell_group and held_wand then\n					sound_button_clicked()\n					set_action_group( access_edit_panel_state( held_wand ), saved_spell_group, do_replace, EntityGetWandCapacity( held_wand ), right_click )\n				end\n			end\n			GuiTooltip( gui, wrap_key( \"spell_group_box_load\" ), \"\" )\n			do_flag_toggle_image_button( \"mods/spell_lab_shugged/files/gui/buttons/spell_replacement.png\",\n				\"replace_mode\", \"spell_replacement\", nil,\n				text_get( \"spell_replacement_tips\", shortcut_texts.replace_switch_temp )\n			)\n		end\n	GuiLayoutEnd( gui )\nend\n\nreturn picker"
_TWWE_VFS["mods/spell_lab_shugged/files/gui/pickers/spell_picker.lua"] = "local FILTER_TYPE_SEARCH = 8\nlocal FILTER_TYPE_RECENT = 9\nlocal FILTER_TYPE_IN_INV = 10\nlocal filter_type = filter_type or ACTION_TYPE_PROJECTILE\n\nlocal action_history = smallfolk.loads( mod_setting_get( \"action_history\" ) or \"{}\" )\nfunction new_action_history_entry( action_id )\n	local size = #action_history\n	if action_history[ size ] == action_id then return end\n\n	action_history[ size + 1 ] = action_id\n\n	action_history_limit = math.max( 1, tonumber( mod_setting_get( \"action_history_limit\" ) ) or 96 )\n	if size > action_history_limit then\n		local action_history_limited = {}\n		for i = 1, action_history_limit do\n			action_history_limited[ i ] = action_history[ size - action_history_limit + i ]\n		end\n		action_history = action_history_limited\n	end\n	mod_setting_set( \"action_history\", smallfolk.dumps( action_history ) )\nend\n\nlocal function clear_action_history()\n	action_history = {}\n	mod_setting_set( \"action_history\", smallfolk.dumps( action_history ) )\nend\n\nlocal CHARACTERS_ACTION_ID = \"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_\"\n\nlocal fzy = dofile_once( \"mods/spell_lab_shugged/files/lib/fzy_lua.lua\" )\n\nlocal current_action_search_needle = dofile( \"mods/spell_lab_shugged/files/gui/editable_text.lua\" )\nlocal current_action_search_result = {}\nlocal action_search_haystacks = {}\nfor i, a in pairs( actions ) do\n	action_search_haystacks[ i ] = a.id\nend\nlocal last_action_search_needle = \"\"\ncurrent_action_search_needle.on_changed = function()\n	local search_needle_text = current_action_search_needle.text\n	if search_needle_text == last_action_search_needle then return end\n	last_action_search_needle = search_needle_text\n\n	if search_needle_text == \"\" then\n		current_action_search_result = {}\n		return\n	end\n\n	-- TODO: replace for-loop with stream api\n	local all_needles_search_result = {}\n	for needle in string.gmatch( search_needle_text, \"[^ ]+\" ) do\n		all_needles_search_result[ #all_needles_search_result + 1 ] = fzy.filter( needle, action_search_haystacks, false )\n	end\n\n	current_action_search_result = {}\n	for _, search_result in ipairs( all_needles_search_result ) do\n		for _, search_result_entry in ipairs( search_result ) do\n			current_action_search_result[ #current_action_search_result + 1 ] = search_result_entry\n		end\n	end\n	table.sort( current_action_search_result, function( a, b ) return a[3] > b[3] end )\n	for i, search_result_entry in ipairs( current_action_search_result ) do\n		current_action_search_result[ i ] = action_search_haystacks[ search_result_entry[1] ]\n	end\nend\n\nlocal function show_keyboard_key( character, x, y, key_width, clicked_func )\n	key_width = key_width - 1 -- gap between keys\n	x = x + 0.5\n	clicked_func = clicked_func or function()\n		current_action_search_needle:insert_character( character )\n	end\n\n	GuiOptionsAddForNextWidget( gui, GUI_OPTION.Layout_NoLayouting )\n	local button_text = \"\"\n	local text_width,_ = GuiGetTextDimensions( gui, button_text )\n	while text_width < key_width do\n		button_text = button_text .. \"l\"\n		text_width,_ = GuiGetTextDimensions( gui, button_text )\n	end\n	button_text = string.sub( button_text, 1, -1 )\n	text_width,_ = GuiGetTextDimensions( gui, button_text )\n	local bracket_width,_ = GuiGetTextDimensions( gui, \"[\" )\n	GuiAnimateBegin( gui )\n		GuiAnimateAlphaFadeIn( gui, 1, 0, 0, true )\n		GuiButton( gui, next_id(), x + key_width / 2 - text_width / 2, y, button_text )\n		local left_click,right_click = previous_data( gui )\n		if left_click or right_click then\n			clicked_func( left_click, right_click )\n		end\n	GuiAnimateEnd( gui )\n	local _,_,hover,_,_,_,_,_,_,_,_ = previous_data( gui )\n	local character_width,_ = GuiGetTextDimensions( gui, character )\n	GuiOptionsAddForNextWidget( gui, GUI_OPTION.Layout_NoLayouting )\n	if hover then\n		GuiColoredText( gui, 1, 1, 0.5, 1, x - bracket_width / 3, y, \"[\" )\n	else\n		GuiColoredText( gui, 1, 1, 1, 0.3, x - bracket_width / 3, y, \"[\" )\n	end\n	GuiOptionsAddForNextWidget( gui, GUI_OPTION.Layout_NoLayouting )\n	if hover then\n		GuiColoredText( gui, 1, 1, 0.5, 1, x + key_width - bracket_width * 2 / 3, y, \"]\" )\n	else\n		GuiColoredText( gui, 1, 1, 1, 0.3, x + key_width - bracket_width * 2 / 3, y, \"]\" )\n	end\n	GuiOptionsAddForNextWidget( gui, GUI_OPTION.Layout_NoLayouting )\n	if hover then\n		GuiColorSetForNextWidget( gui, 1, 1, 0.5, 1 )\n	end\n	GuiButton( gui, next_id(), x + key_width / 2 - character_width / 2, y, character )\nend\n\nlocal spell_search_focused = false\n\nlocal character_keys = {\n	{ \"Key_a\", \"A\" },\n	{ \"Key_b\", \"B\" },\n	{ \"Key_c\", \"C\" },\n	{ \"Key_d\", \"D\" },\n	{ \"Key_e\", \"E\" },\n	{ \"Key_f\", \"F\" },\n	{ \"Key_g\", \"G\" },\n	{ \"Key_h\", \"H\" },\n	{ \"Key_i\", \"I\" },\n	{ \"Key_j\", \"J\" },\n	{ \"Key_k\", \"K\" },\n	{ \"Key_l\", \"L\" },\n	{ \"Key_m\", \"M\" },\n	{ \"Key_n\", \"N\" },\n	{ \"Key_o\", \"O\" },\n	{ \"Key_p\", \"P\" },\n	{ \"Key_q\", \"Q\" },\n	{ \"Key_r\", \"R\" },\n	{ \"Key_s\", \"S\" },\n	{ \"Key_t\", \"T\" },\n	{ \"Key_u\", \"U\" },\n	{ \"Key_v\", \"V\" },\n	{ \"Key_w\", \"W\" },\n	{ \"Key_x\", \"X\" },\n	{ \"Key_y\", \"Y\" },\n	{ \"Key_z\", \"Z\" },\n	{ \"Key_1\", \"1\" },\n	{ \"Key_2\", \"2\" },\n	{ \"Key_3\", \"3\" },\n	{ \"Key_4\", \"4\" },\n	{ \"Key_5\", \"5\" },\n	{ \"Key_6\", \"6\" },\n	{ \"Key_7\", \"7\" },\n	{ \"Key_8\", \"8\" },\n	{ \"Key_9\", \"9\" },\n	{ \"Key_0\", \"0\" },\n	{ \"Key_SPACE\", \" \" },\n	{ \"Key_MINUS\", \"_\" },\n}\n\nlocal Focus_SpellSearch = {\n	id = \"spell_search\",\n	on_focused = function() spell_search_focused = true end,\n	on_unfocused = function() spell_search_focused = false end,\n	on_input = function( keyboard_input )\n		if keyboard_input.Key_BACKSPACE then\n			current_action_search_needle:left_delete()\n		end\n		if keyboard_input.Key_DELETE then\n			current_action_search_needle:right_delete()\n		end\n		if keyboard_input.Key_HOME then\n			current_action_search_needle:input_anchor_move_to_beginning()\n		end\n		if keyboard_input.Key_END then\n			current_action_search_needle:input_anchor_move_to_end()\n		end\n		if keyboard_input.Key_LEFT then\n			if not keyboard_input.Key_ALT then\n				current_action_search_needle:input_anchor_move_left()\n			else\n				current_action_search_needle:input_anchor_move_to_last_word()\n			end\n		end\n		if keyboard_input.Key_RIGHT then\n			if not keyboard_input.Key_ALT then\n				current_action_search_needle:input_anchor_move_right()\n			else\n				current_action_search_needle:input_anchor_move_to_next_word()\n			end\n		end\n		for _, p in ipairs( character_keys ) do\n			if keyboard_input[ p[1] ] then\n				current_action_search_needle:insert_character( p[2] )\n			end\n		end\n	end,\n}\n\nlocal picker = {}\n\nlocal keyboard = {\n	{ \"Q\", \"W\", \"E\", \"R\", \"T\", \"Y\", \"U\", \"I\", \"O\", \"P\" },\n	{ \"A\", \"S\", \"D\", \"F\", \"G\", \"H\", \"J\", \"K\", \"L\" },\n	{ \"Z\", \"X\", \"C\", \"V\", \"B\", \"N\", \"M\", \"_\" },\n}\n\npicker.menu = function()\n	local show_locked_spells = mod_setting_get( \"show_locked_spells\" )\n	local actions_data_to_show\n\n	if filter_type <= 7 then\n		actions_data_to_show_ = sorted_actions[filter_type]\n		actions_data_to_show = {}\n		for _, action_data in ipairs( actions_data_to_show_ ) do\n			if action_data.hide_from_conjurer then\n				goto continue\n			end\n			if not show_locked_spells and not is_action_unlocked( action_data ) then\n				goto continue\n			end\n			actions_data_to_show[ #actions_data_to_show + 1 ] = action_data\n			::continue::\n		end\n	else\n		local action_ids_to_show\n		if filter_type == FILTER_TYPE_SEARCH then\n			action_ids_to_show = current_action_search_result\n		elseif filter_type == FILTER_TYPE_RECENT then\n			action_ids_to_show = action_history\n		elseif filter_type == FILTER_TYPE_IN_INV then\n			local unsorted = {}\n			-- looks ugly, but that's for the compatiblity with a mod called \"Noita Inventory\"\n			for _, child_id in ipairs( EntityGetAllChildren( player ) or {} ) do\n				if EntityGetName( child_id ) == \"inventory_full\" or EntityGetName( child_id ) == \"inventory_quick\" then\n					for _, child_2_id in ipairs( EntityGetAllChildren( child_id ) or {} ) do\n						local item_comp = EntityGetFirstComponentIncludingDisabled( child_2_id, \"ItemComponent\" )\n						local item_action_comp = EntityGetFirstComponentIncludingDisabled( child_2_id, \"ItemActionComponent\" )\n						if item_comp and item_action_comp and EntityHasTag( child_2_id, \"card_action\" ) then\n							unsorted[ ComponentGetValue2( item_action_comp, \"action_id\" ) or \"\" ] = true\n						elseif EntityHasTag( child_2_id, \"wand\" ) and not mod_setting_get( \"include_spells_in_non_inv_wand\" ) then\n							for _, child_3_id in ipairs( EntityGetAllChildren( child_2_id, \"card_action\" ) or {} ) do\n								local item_comp = EntityGetFirstComponentIncludingDisabled( child_3_id, \"ItemComponent\" )\n								local item_action_comp = EntityGetFirstComponentIncludingDisabled( child_3_id, \"ItemActionComponent\" )\n								if item_comp and item_action_comp then\n									unsorted[ ComponentGetValue2( item_action_comp, \"action_id\" ) or \"\" ] = true\n								end\n							end\n						end\n					end\n				end\n			end\n\n			local px, py = get_player_or_camera_position()\n			for _, card_id in ipairs( EntityGetInRadiusWithTag( px, py, 180, \"card_action\" ) ) do\n				-- exclude those in non-inv wands, because of an issue which nolla is responsible for\n				if not mod_setting_get( \"include_spells_in_non_inv_wand\" ) and EntityGetParent( card_id ) ~= 0 then goto continue end\n\n				local item_comp = EntityGetFirstComponentIncludingDisabled( card_id, \"ItemComponent\" )\n				local item_action_comp = EntityGetFirstComponentIncludingDisabled( card_id, \"ItemActionComponent\" )\n				if not item_comp or not item_action_comp then goto continue end\n\n				unsorted[ ComponentGetValue2( item_action_comp, \"action_id\" ) or \"\" ] = true\n				::continue::\n			end\n			if mod_setting_get( \"include_spells_in_non_inv_wand\" ) then\n				for _, wand_id in ipairs( EntityGetInRadiusWithTag( px, py, 180, \"wand\" ) ) do\n					for _, card_id in ipairs( EntityGetAllChildren( wand_id, \"card_action\" ) or {} ) do\n						local item_comp = EntityGetFirstComponentIncludingDisabled( card_id, \"ItemComponent\" )\n						local item_action_comp = EntityGetFirstComponentIncludingDisabled( card_id, \"ItemActionComponent\" )\n						if not item_comp or not item_action_comp then goto continue end\n\n						unsorted[ ComponentGetValue2( item_action_comp, \"action_id\" ) or \"\" ] = true\n						::continue::\n					end\n				end\n			end\n\n			unsorted[\"\"] = nil\n			action_ids_to_show = {}\n			for k, _ in pairs( unsorted ) do\n				if action_id_to_idx[ k ] then\n					action_ids_to_show[ #action_ids_to_show + 1 ] = k\n				end\n			end\n\n			table.sort( action_ids_to_show, function( a, b ) return action_id_to_idx[ a ] < action_id_to_idx[ b ] end )\n		end\n		actions_data_to_show = {}\n		for i, a in ipairs( action_ids_to_show ) do\n			if action_data.hide_from_conjurer then\n				goto continue\n			end\n			if not show_locked_spells and not is_action_unlocked( action_data ) then\n				goto continue\n			end\n\n			-- actions in FILTER_TYPE_RECENT should be ordered inversely\n			if filter_type ~= FILTER_TYPE_RECENT then\n				actions_data_to_show[ i ] = action_data[ a ]\n			else\n				actions_data_to_show[ #action_ids_to_show - i + 1 ] = action_data[ a ]\n			end\n			::continue::\n		end\n	end\n\n	local function show_filter( i, tooltip_text )\n		if filter_type ~= i then GuiOptionsAddForNextWidget( gui, GUI_OPTION.DrawSemiTransparent ) end\n		GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/type_filter_\"..i..\".png\" )\n		local left_click,right_click,hover,_,_,_ = previous_data( gui )\n		GuiTooltip( gui, tooltip_text, \"\" )\n		if filter_type ~= i then\n			if hover and mod_setting_get( \"filter_buttons_trigger\" ) == \"HOVER\" then\n				filter_type = i\n			end\n			if left_click and mod_setting_get( \"filter_buttons_trigger\" ) == \"CLICK\" then\n				filter_type = i\n				sound_button_clicked()\n			end\n		end\n	end\n\n	if filter_type <= 7 then\n		GuiLayoutBeginHorizontal( gui, 0, 360 * 0.16, true, 0, 0 )\n			GuiLayoutBeginVertical( gui, 640 * 0.01, 0, true )\n			for i = 0, 7 do\n				show_filter( i, type_text[i] )\n			end\n			GuiLayoutEnd( gui )\n		GuiLayoutEnd( gui )\n	end\n	\n	local interacting = false\n\n	do\n		local x, y = 640 * 0.05 + 2, 360 * 0.16 - 16\n		local tab_width, tab_height = GuiGetImageDimensions( gui, \"mods/spell_lab_shugged/files/gui/buttons/tab.png\" )\n		for i, tab in ipairs( { \"types\", \"search\", \"recent\", \"in_inv\" } ) do\n			if GuiImageButton( gui, next_id(), x, y, \"\", \"mods/spell_lab_shugged/files/gui/buttons/tab_transparent.png\" ) then\n				if i == 1 then filter_type = 0 else filter_type = i + 6 end\n				sound_button_clicked()\n			end\n			local left_click,right_click,hover = previous_data( gui )\n\n			if i == 3 then\n				GuiTooltip( gui, text_get( \"spell_picker_tab_recent_tips\", shortcut_texts.clear_action_history ) )\n				if shortcut_check.check( shortcuts.clear_action_history, left_click, right_click ) then\n					clear_action_history()\n					sound_button_clicked()\n				end\n			end\n\n			local selected = i + 6 == filter_type or ( i == 1 and filter_type <= 7 )\n			if selected then\n				GuiZSetForNextWidget( gui, -3 )\n				GuiImage( gui, next_id(), x, y - 1, \"mods/spell_lab_shugged/files/gui/buttons/tab_selected.png\", 1, 1, 0 )\n			elseif hover then\n				GuiZSetForNextWidget( gui, -2.5 )\n				GuiImage( gui, next_id(), x, y, \"mods/spell_lab_shugged/files/gui/buttons/tab_hovered.png\", 1, 1, 0 )\n			else\n				GuiZSetForNextWidget( gui, -2 )\n				GuiImage( gui, next_id(), x, y, \"mods/spell_lab_shugged/files/gui/buttons/tab.png\", 1, 1, 0 )\n			end\n\n			local y_offset = 1.5\n			if not selected then\n				y_offset = 2\n			end\n			GuiZSetForNextWidget( gui, -4 )\n			local scale = 1\n			local width, height = GuiGetTextDimensions( gui, text_get_translated( \"spell_picker_tab_\" .. tab ) )\n			local max_width = tab_width - 4\n			if width > max_width then\n				scale = max_width / width\n				width = max_width\n			end\n			local args = { x + tab_width / 2 - width / 2, y + y_offset + tab_height / 2 - height / 2, wrap_key( \"spell_picker_tab_\" .. tab ), scale, \"data/fonts/font_pixel.xml\", true }\n			if zh_cn_languages[ text_get_translated( \"$current_language\" ) ] then\n				args[5] = \"\"\n			end\n			if selected then\n				GuiSoftText( gui, unpack( args ) )\n			else\n				GuiColoredText( gui, 0.42, 0.42, 0.42, 1.0, unpack( args ) )\n			end\n			x = x + tab_width - 1\n		end\n	end\n\n	GuiLayoutBeginVertical( gui, 640 * 0.05, 360 * 0.16, true )\n		local scroll_ids = {}\n		for i = 0, 10 do\n			scroll_ids[ i ] = next_id()\n		end\n\n		local height = nil\n		local height_autofit = true\n		if filter_type == FILTER_TYPE_SEARCH then\n			if mod_setting_get( \"show_screen_keyboard\" ) then\n				height = 98\n			else\n				height = 138\n			end\n			height_autofit = false\n		end\n\n		local scroll_table = { do_scroll_table( scroll_ids[ filter_type ], nil,\n			height, height_autofit, function( hovered ) interacting = interacting or hovered end,\n			actions_data_to_show, function( action )\n			local left_click, right_click = do_action_button( action.id, 0, 0, false, do_verbose_tooltip, action.max_uses, nil, show_locked_state, false, true )\n			if left_click or right_click then\n				local is_unlocked_action = action.spawn_requires_flag and HasFlagPersistent( action.spawn_requires_flag ) \n				if shortcut_check.check( shortcuts.relock, left_click, right_click ) then\n					if is_unlocked_action then\n						RemoveFlagPersistent( action.spawn_requires_flag )\n					end\n					return\n				end\n\n				if not mod_setting_get( \"quick_spell_picker\" )\n					or not mod_setting_get( \"show_wand_edit_panel\" ) or not held_wand then\n					if not player then return end\n					local x, y = EntityGetTransform( player )\n					local action_entity = CreateItemActionEntity( action.id, x, y )\n					local inventory_full\n					local player_child_entities = EntityGetAllChildren( player )\n					if not player_child_entities then return end\n					for i,child_entity in ipairs( player_child_entities ) do\n						if EntityGetName( child_entity ) == \"inventory_full\" then\n							inventory_full = child_entity\n							break\n						end\n					end\n					-- set inventory contents\n					if inventory_full then\n						EntitySetComponentsWithTagEnabled( action_entity, \"enabled_in_world\", false )\n						EntityAddChild( inventory_full, action_entity )\n						GamePrint( GameTextGet( wrap_key( \"action_added_to_inventory\" ), GameTextGetTranslatedOrNot( action.name ) ) )\n						if filter_type ~= FILTER_TYPE_RECENT then\n							new_action_history_entry( action.id )\n						end\n					end\n					return\n				end\n				if not held_wand then return end\n				local do_replace = mod_setting_get( \"replace_mode\" )\n				if shift then do_replace = not do_replace end\n				local uses_remaining = nil\n				if action.max_uses then\n					if not world_state_unlimited_spells or action.never_unlimited then\n						if not mod_setting_get( \"zero_uses\" ) then\n							uses_remaining = action.max_uses\n						else\n							uses_remaining = 0\n						end\n					end\n				end\n				set_action( access_edit_panel_state( held_wand ), action.id, uses_remaining, do_replace, EntityGetWandCapacity( held_wand ), right_click )\n				if filter_type ~= FILTER_TYPE_RECENT then\n					new_action_history_entry( action.id )\n				end\n			end\n		end ) }\n\n		if filter_type == FILTER_TYPE_SEARCH then\n			GuiOptionsAddForNextWidget( gui, GUI_OPTION.NonInteractive )\n			GuiZSetForNextWidget( gui, 1 )\n			GuiTextInput( gui, next_id(), 3, 10, \"\", input_bar_width, -1, CHARACTERS_ACTION_ID )\n			local _,_,_,_,_,_,text_input_height,_,_,_,_ = previous_data( gui )\n			GuiLayoutAddVerticalSpacing( gui, -( text_input_height + 10 ) )\n\n			local keyboard_height = text_input_height\n			if mod_setting_get( \"show_screen_keyboard\" ) then\n				keyboard_height = 10 --[[ incorrectly assumed height of text input ]]+ 40\n			end\n\n			GuiBeginScrollContainer( gui, next_id(), 0, 8, SCROLL_TABLE_WIDTH, keyboard_height )\n				if InputIsMouseButtonJustDown( Mouse_left ) then\n					local _,_,_,x,y,width,height,_,_,_,_ = previous_data( gui )\n					local mx, my = get_mouse_pos_on_screen()\n					if -2 <= mx - x and mx - x <= width + 2 and -2 <= my - y and my - y <= height + 2 then\n						interacting = true\n					end\n				end\n				local row_height = 13\n				local key_width = 13\n				local big_key_width = 1.5 * key_width\n				local med_key_width = 0.75 * key_width\n				local input_bar_width\n				if mod_setting_get( \"show_screen_keyboard\" ) then\n					input_bar_width = 174 - 2 * big_key_width - 2 * med_key_width - 2.5\n				else\n					input_bar_width = 174 - key_width - 2.5\n				end\n				if not spell_search_focused then\n					GuiOptionsAddForNextWidget( gui, GUI_OPTION.DrawSemiTransparent )\n				end\n				GuiOptionsAddForNextWidget( gui, GUI_OPTION.NonInteractive )\n				if spell_search_focused or current_action_search_needle.text ~= \"\" then\n					GuiTextInput( gui, next_id(), 0, 0, current_action_search_needle.text, input_bar_width, -1, CHARACTERS_ACTION_ID )\n				else\n					GuiZSetForNextWidget( gui, -1 )\n					GuiTextInput( gui, next_id(), 0, 0, text_get_translated( \"spell_picker_searchbox\" ), input_bar_width, -1, CHARACTERS_ACTION_ID )\n					GuiTextInput( gui, next_id(), 0, 0, \"\", input_bar_width, -1, CHARACTERS_ACTION_ID )\n				end\n				local _,_,_,x,y,width,height,_,_,_,_ = previous_data( gui )\n				if spell_search_focused or current_action_search_needle.text ~= \"\" then\n					local left_text = current_action_search_needle.text:sub( 1, current_action_search_needle.input_anchor - 1 )\n					local input_anchor_offset = GuiGetTextDimensions( gui, left_text )\n					GuiLayoutBeginLayer( gui )\n					GuiZSetForNextWidget( gui, -1 )\n					local image_height = 10\n					local scale = text_input_height / image_height\n					GuiImage( gui, next_id(), x + 1 + input_anchor_offset, y + 2 * ( text_input_height - 2 ) / ( image_height - 2 ), \"mods/spell_lab_shugged/files/gui/input_anchor.png\", 1, scale, 0 )\n					GuiLayoutEndLayer( gui )\n				end\n				if InputIsMouseButtonJustDown( Mouse_left ) then\n					local mx, my = get_mouse_pos_on_screen()\n					if -2 <= mx - x and mx - x <= width + 2 and -2 <= my - y and my - y <= height + 2 then\n						change_keyboard_focus( Focus_SpellSearch )\n						local width_mouse_pos = mx - x\n						local last_substring, substring\n						for i = 0, #current_action_search_needle.text do\n							substring = string.sub( current_action_search_needle.text, 1, i )\n							if GuiGetTextDimensions( gui, substring ) >= width_mouse_pos then\n								break\n							end\n							last_substring = substring\n							substring = nil\n						end\n						if last_substring and not substring then\n							current_action_search_needle.input_anchor = #last_substring + 1\n						elseif not last_substring and substring then\n							current_action_search_needle.input_anchor = #substring + 1\n						elseif last_substring and substring then\n							if width_mouse_pos - GuiGetTextDimensions( gui, last_substring ) <= GuiGetTextDimensions( gui, substring ) - width_mouse_pos then\n								current_action_search_needle.input_anchor = #last_substring + 1\n							else\n								current_action_search_needle.input_anchor = #substring + 1\n							end\n						end\n					end\n				end\n				if mod_setting_get( \"show_screen_keyboard\" ) then\n					show_keyboard_key( \" \", x + width, y, big_key_width )\n					show_keyboard_key( \"<\", x + width + big_key_width, y, med_key_width, function( left_click, right_click )\n						if left_click then\n							current_action_search_needle:input_anchor_move_left()\n						elseif right_click then\n							current_action_search_needle:input_anchor_move_to_last_word()\n						end\n					end )\n					show_keyboard_key( \">\", x + width + med_key_width + big_key_width, y, med_key_width, function( left_click, right_click )\n						if left_click then\n							current_action_search_needle:input_anchor_move_right()\n						elseif right_click then\n							current_action_search_needle:input_anchor_move_to_next_word()\n						end\n					end )\n					show_keyboard_key( \"<-\", x + width + 2 * med_key_width + big_key_width, y, big_key_width, function( left_click, right_click )\n						if left_click then\n							current_action_search_needle:left_delete()\n						elseif right_click then\n							current_action_search_needle:clear()\n						end\n					end )\n\n					local ordinal_y = y + row_height\n					for i, c in ipairs( keyboard[1] ) do\n						show_keyboard_key( c, x + i * key_width - key_width, ordinal_y, key_width )\n					end\n					for i, c in ipairs( keyboard[2] ) do\n						show_keyboard_key( c, x + i * key_width - key_width / 2, ordinal_y + row_height, key_width )\n					end\n					for i, c in ipairs( keyboard[3] ) do\n						show_keyboard_key( c, x + i * key_width, ordinal_y + 2 * row_height, key_width )\n					end\n					for i = 1, 3 do\n						local first_j = 1\n						if i == 1 then\n							first_j = 0\n						end\n						for j = first_j, 3 do\n							show_keyboard_key( tostring( i * 3 - 3 + j ), x + #keyboard[1] * key_width + j * key_width - key_width / 2, ordinal_y + 2 * row_height - i * row_height + row_height, key_width )\n						end\n					end\n				else\n					show_keyboard_key( \"X\", x + width, y, key_width, function( left_click, right_click )\n						current_action_search_needle:clear()\n					end )\n				end\n			GuiEndScrollContainer( gui )\n		end\n	GuiLayoutEnd( gui )\n\n	if spell_search_focused and filter_type ~= FILTER_TYPE_SEARCH then\n		change_keyboard_focus( Focus_PlayerControls )\n	elseif InputIsMouseButtonJustDown( Mouse_left ) then\n		if not interacting then\n			if change_keyboard_focus( Focus_PlayerControls ) then\n				block_upcoming_wand_shooting()\n			end\n		end\n	end\nend\n\npicker.buttons = function()\n	local buttons_num = 2\n	if held_wand and mod_setting_get( \"show_wand_edit_panel\" ) then\n		buttons_num = buttons_num + 2\n	end\n	GuiLayoutBeginHorizontal( gui, horizontal_centered_x(buttons_num,4), percent_to_ui_scale_y(2), true )\n		if held_wand and mod_setting_get( \"show_wand_edit_panel\" ) then\n			do_flag_toggle_image_button( \"mods/spell_lab_shugged/files/gui/buttons/quick_spell_picker.png\", \"quick_spell_picker\" )\n		end\n		do_flag_toggle_image_button( \"mods/spell_lab_shugged/files/gui/buttons/show_locked_spells.png\", \"show_locked_spells\", nil, nil, text_get( \"relock_tips\", shortcut_texts.relock ) )\n		do_flag_toggle_image_button( \"mods/spell_lab_shugged/files/gui/buttons/zero_uses.png\", \"zero_uses\" )\n		if held_wand and mod_setting_get( \"show_wand_edit_panel\" ) then\n			do_flag_toggle_image_button( \"mods/spell_lab_shugged/files/gui/buttons/spell_replacement.png\", \"replace_mode\", \"spell_replacement\", nil, text_get( \"spell_replacement_tips\", shortcut_texts.replace_switch_temp ) )\n		end\n	GuiLayoutEnd( gui )\nend\n\nreturn picker"
_TWWE_VFS["mods/spell_lab_shugged/files/gui/pickers/wand_box.lua"] = "local wand_box_current_page_index = 1\nlocal wand_box_selected_indexes = {}\n\nlocal function wand_box_get_page_data( index )\n	return mod_setting_get( \"wand_box_page_\" .. tostring( index ) )\nend\n\nlocal function wand_box_set_page_data( index, data )\n	if not data then\n		ModSettingRemove( \"spell_lab_shugged.wand_box_page_\" .. tostring( index ) )\n		return\n	end\n	mod_setting_set( \"wand_box_page_\" .. tostring( index ), data )\nend\nif not mod_setting_get( \"wand_box_page_max_index\" ) then\n	mod_setting_set( \"wand_box_page_max_index\", 1 )\n	wand_box_set_page_data( 1, smallfolk.dumps( {} ) )\nend\n\nlocal function serialize_wand_box_page( page_index )\n	if saved_wands and saved_wands[ page_index ] then\n		mod_setting_set( \"wand_box_page_\" .. tostring( page_index ), smallfolk.dumps( saved_wands[ page_index ] ) )\n	end\nend\n\nlocal function wand_box_new_page( index, content )\n	table.insert( saved_wands, index, content )\n	content = smallfolk.dumps( content )\n	local max_index = mod_setting_get( \"wand_box_page_max_index\" )\n	for i = index, max_index do\n		local data_to_move = wand_box_get_page_data( i )\n		wand_box_set_page_data( i + 1, data_to_move )\n	end\n	mod_setting_set( \"wand_box_page_max_index\", max_index + 1 )\n\n	wand_box_set_page_data( index, content )\nend\n\nlocal function wand_box_remove_page( index )\n	table.remove( saved_wands, index )\n	local max_index = mod_setting_get( \"wand_box_page_max_index\" )\n	mod_setting_set( \"wand_box_page_max_index\", max_index - 1 )\n	for i = index + 1, max_index do\n		local data_to_move = wand_box_get_page_data( i )\n		wand_box_set_page_data( i - 1, data_to_move )\n	end\n	wand_box_set_page_data( max_index, nil )\nend\n\nsaved_wands = {}\nfor i = 1, mod_setting_get( \"wand_box_page_max_index\" ) do\n	local page_data = wand_box_get_page_data( i )\n	if page_data then\n		page_wands = smallfolk.loads( page_data )\n		for _, wand in ipairs( page_wands ) do\n			local capacity = wand.stats.capacity\n			local deck_capacity = wand.stats.deck_capacity\n\n			if not capacity and deck_capacity then\n				capacity = deck_capacity\n				for _, a in ipairs( wand.all_actions ) do\n					if a.permanent then\n						capacity = capacity - 1\n					end\n				end\n				wand.stats.capacity = capacity\n			end\n\n			if not deck_capacity and capacity then\n				deck_capacity = capacity\n				for _, a in ipairs( wand.all_actions ) do\n					if a.permanent then\n						deck_capacity = deck_capacity + 1\n					end\n				end\n				wand.stats.deck_capacity = deck_capacity\n			end\n		end\n		table.insert( saved_wands, page_wands )\n	end\nend\n\nlocal old_version_data = ModSettingGet( \"spell_lab_shugged_saved_wands\" )\nif old_version_data then\n	local old_version_wands = smallfolk.loads( old_version_data )\n	for i = 1, math.ceil( #old_version_wands / 100 ) do\n		local page = {}\n		for j = 1 + ( i - 1 ) * 100, i * 100 do\n			local wand = old_version_wands[ j ]\n			if not wand then break end\n			table.insert( page, wand )\n		end\n		wand_box_new_page( i, page )\n	end\n	ModSettingRemove( \"spell_lab_shugged_saved_wands\" )\n	print( \"[spell lab shugged] Upgraded your wand box data to the format used in new version.\" )\nend\nlocal t = { [\"spell_lab\"] = \"spell_lab_saved_wands\", [\"EcsGui\"] = \"WandsConn_saved_wands\" }\nfor name, key in pairs( t ) do\n	local flag = \"spell_lab_shugged.migrated_wand_box_data_from_\" .. string.lower( name )\n	do -- for old version stuff\n		if HasFlagPersistent( flag ) then\n			RemoveFlagPersistent( flag )\n			ModSettingSet( flag, true )\n		end\n		local old_setting_key = \"spell_lab_shugged_migrated_wand_box_data_from_\" .. string.lower( name )\n		if ModSettingGet( old_setting_key ) then\n			ModSettingRemove( old_setting_key )\n			ModSettingSet( flag, true )\n		end\n	end\n	if ModSettingGet( flag ) then goto continue end\n	local spell_lab_wands_data = ModSettingGet( key )\n	if not spell_lab_wands_data then goto continue end\n	local spell_lab_wands = smallfolk.loads( spell_lab_wands_data )\n	for i, wand in ipairs( spell_lab_wands ) do\n		local all_actions = {}\n		local absolute_actions = wand.absolute_actions\n		local permanent_actions = wand.permanent_actions\n		for _, pa in ipairs( permanent_actions or {} ) do\n			pa.entity = nil\n			pa.item = nil\n			pa.x = 0\n			table.insert( all_actions, pa )\n		end\n		for _, a in pairs( absolute_actions or {} ) do\n			a.entity = nil\n			a.item = nil\n			table.insert( all_actions, a )\n		end\n		wand.absolute_actions = nil\n		wand.permanent_actions = nil\n		wand.all_actions = all_actions\n	end\n	for i = 1, math.ceil( #spell_lab_wands / 100 ) do\n		local page = {}\n		for j = 1 + ( i - 1 ) * 100, i * 100 do\n			local wand = spell_lab_wands[ j ]\n			if not wand then break end\n			table.insert( page, wand )\n		end\n		wand_box_new_page( i, page )\n	end\n	print( \"[spell lab shugged] Migrated wand box data from \" .. name )\n	ModSettingSet( flag, true )\n	::continue::\nend\n\nlocal picker = {}\npicker.menu = function()\n	local current_page = saved_wands[ wand_box_current_page_index ]\n	GuiLayoutBeginVertical( gui, 2, 16 )\n		local wand_index = 1\n		for y_index = 1, 10 do\n			GuiLayoutBeginHorizontal( gui, 0, 0 )\n				for x_index = 1, 10 do\n					local saved_wand = current_page[ wand_index ]\n					if wand_index > #current_page or saved_wand == nil then break end\n					do\n						local spell_box\n						if wand_box_selected_indexes[ wand_index ] then\n							spell_box = \"mods/spell_lab_shugged/files/gui/buttons/spell_box_active.png\"\n						else\n							spell_box = \"mods/spell_lab_shugged/files/gui/buttons/spell_box.png\"\n						end\n						GuiImageButton( gui, next_id(), 0, 0, \"\", spell_box )\n					end\n					local left_click,right_click,_,x,y,_,_,_,_ = previous_data( gui )\n					if left_click or right_click then\n						wand_box_delete_wand_confirming = false\n						if shortcut_check.check( shortcuts.expand_selection_left, left_click, right_click ) then\n							local to = 1\n							for i = wand_index, 1, -1 do\n								if wand_box_selected_indexes[ i ] then\n									to = i\n									break\n								end\n							end\n							for i = to, wand_index do\n								wand_box_selected_indexes[ i ] = true\n							end\n						elseif shortcut_check.check( shortcuts.expand_selection_right, left_click, right_click ) then\n							local to = #current_page\n							for i = wand_index, #current_page do\n								if wand_box_selected_indexes[ i ] then\n									to = i\n									break\n								end\n							end\n							for i = wand_index, to do\n								wand_box_selected_indexes[ i ] = true\n							end\n						elseif shortcut_check.check( shortcuts.multi_select, left_click, right_click ) then\n							wand_box_selected_indexes[ wand_index ] = not wand_box_selected_indexes[ wand_index ]\n						elseif shortcut_check.check( shortcuts.swap, left_click, right_click ) then\n							local indexes_to_swap = {}\n							for i = 1, #current_page do\n								if wand_box_selected_indexes[ i ] then\n									table.insert( indexes_to_swap, i )\n								end\n							end\n							local first = indexes_to_swap[1]\n							if not first then goto skip end\n							local idx = 10 * ( y_index - 1 ) + x_index\n							local offset = idx - first\n							if wand_box_selected_indexes[ idx ] then\n								local temp = {}\n								for i, index in ipairs( indexes_to_swap ) do\n									temp[ i ] = current_page[ index ]\n								end\n								local size = #indexes_to_swap\n								for i = 1, size - offset do\n									current_page[ indexes_to_swap[ i + offset ] ] = temp[ i ]\n								end\n								for i = 1, offset do\n									current_page[ indexes_to_swap[ i ] ] = temp[ size - offset + i ]\n								end\n							else\n								for _, index in ipairs( indexes_to_swap ) do\n									local the_other = index + offset\n									if the_other > #current_page then\n										goto skip\n									end\n								end\n								for _, index in ipairs( indexes_to_swap ) do\n									local the_other = index + offset\n									local temp = current_page[ the_other ]\n									current_page[ the_other ] = current_page[ index ]\n									current_page[ index ] = temp\n								end\n							end\n						elseif shortcut_check.check( shortcuts.select, left_click, right_click ) then\n							wand_box_selected_indexes = { [ wand_index ] = true }\n						elseif shortcut_check.check( shortcuts.deselect, left_click, right_click ) then\n							wand_box_selected_indexes[ wand_index ] = false\n						end\n					end\n					::skip::\n					do_custom_tooltip( function()\n						if not shortcut_check.check( shortcuts.show_wand_stats, left_click, right_click ) then\n							do_simple_action_list( saved_wand.all_actions )\n							GuiLayoutBeginHorizontal( gui, 0, 0 )\n								GuiDimText( gui, 0, 0, GameTextGet(\n									wrap_key( \"wand_box_hold_something_to_show_wand_stats\" ),\n									shortcut_texts.show_wand_stats\n								) )\n							GuiLayoutEnd( gui )\n						else\n							do_wand_stats( gui, saved_wand.stats )\n						end\n					end )\n					if saved_wand then\n						local dynamic_wand_data = WANDS.wand_get_dynamic_wand_data_from_stats( saved_wand.stats )\n						if dynamic_wand_data then\n							local image_width, image_height = GuiGetImageDimensions( gui, dynamic_wand_data.file )\n							\n							GuiZSetForNextWidget( gui, -1 )\n							GuiOptionsAddForNextWidget( gui, GUI_OPTION.Layout_NoLayouting )\n							GuiImage( gui, next_id(), x + ( 20 - image_height ) / 2.5, y + 10, dynamic_wand_data.file, 1.0, 1.0, 1.0, -60 / 180 * math.pi )\n						end\n					end\n					wand_index = wand_index + 1\n				end\n			GuiLayoutEnd( gui )\n			GuiLayoutAddVerticalSpacing( gui, -2 )\n		end\n	GuiLayoutEnd( gui )\nend\n\npicker.buttons = function()\n	local buttons_num = 7\n	if held_wand then\n		buttons_num = buttons_num + 1\n	end\n	GuiLayoutBeginHorizontal( gui, horizontal_centered_x(buttons_num,4), percent_to_ui_scale_y(2), true )\n		local current_page = saved_wands[ wand_box_current_page_index ]\n		if #current_page < 100 then\n			if GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/save_wand.png\" ) then\n				if held_wand then\n					sound_button_clicked()\n					local data = WANDS.wand_get_data( held_wand )\n					table.insert( current_page, data )\n					serialize_wand_box_page( wand_box_current_page_index )\n				end\n			end\n			GuiTooltip( gui, wrap_key( \"wand_box_save\" ), \"\" )\n		else\n			GuiOptionsAddForNextWidget( gui, GUI_OPTION.DrawSemiTransparent )\n			GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/save_wand.png\" )\n			GuiTooltip( gui, wrap_key( \"wand_box_save_reached_page_limit\" ), \"\" )\n		end\n		local selected_indexes = {}\n		for k = 1, #current_page do\n			if wand_box_selected_indexes[ k ] then\n				table.insert( selected_indexes, k )\n			end\n		end\n		if #selected_indexes > 0 then\n			if GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/delete_wand.png\" ) then\n				sound_button_clicked()\n				if not wand_box_delete_wand_confirming then\n					wand_box_delete_wand_confirming = true\n				else\n					if shortcut_check.check( shortcuts.confirm ) then\n						for i = #current_page, 1, -1 do\n							if wand_box_selected_indexes[ i ] then\n								table.remove( current_page, i )\n							end\n						end\n						serialize_wand_box_page( wand_box_current_page_index )\n						wand_box_selected_indexes = {}\n					end\n					wand_box_delete_wand_confirming = false\n				end\n			end\n			if not wand_box_delete_wand_confirming then\n				GuiTooltip( gui, wrap_key( \"wand_box_delete\" ), \"\" )\n			else\n				GuiTooltip( gui, wrap_key( \"wand_box_delete\" ), text_get( \"deletion_confirm_button\", shortcut_texts.confirm ) )\n			end\n		else\n			GuiOptionsAddForNextWidget( gui, GUI_OPTION.DrawSemiTransparent )\n			GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/delete_wand.png\" )\n			GuiTooltip( gui, wrap_key( \"wand_box_no_wand_selected\" ), \"\" )\n		end\n\n		if held_wand then\n			if #selected_indexes > 0 then\n				if GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/load_into_wand.png\" ) then\n					for i = 1, #current_page do\n						if wand_box_selected_indexes[ i ] then\n							sound_button_clicked()\n							local saved_wand = current_page[ i ]\n							WANDS.initialize_wand( held_wand, saved_wand )\n							force_refresh_held_wands()\n							reload_state_for_wand( held_wand ) -- for force compact\n							wand_box_selected_indexes[ i ] = false\n							break\n						end\n					end\n				end\n				GuiTooltip( gui, wrap_key( \"wand_box_load_to_hand\" ), \"\" )\n			else\n				GuiOptionsAddForNextWidget( gui, GUI_OPTION.DrawSemiTransparent )\n				GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/load_into_wand.png\" )\n				GuiTooltip( gui, wrap_key( \"wand_box_no_wand_selected\" ), \"\" )\n			end\n		end\n\n		if GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/load_into_world.png\" ) then\n			local wands_to_load = {}\n			for i = 1, #current_page do\n				local saved_wand = current_page[ i ]\n				if wand_box_selected_indexes[ i ] then\n					table.insert( wands_to_load, saved_wand )\n				end\n			end\n			for i, wand in ipairs( wands_to_load ) do\n				local x, y = get_player_or_camera_position()\n				local offset_x = ( i - 1 - ( #wands_to_load - 1 ) / 2 ) * 12\n				local wand_ = EntityLoad( \"data/entities/items/wand_level_03.xml\", x + offset_x, y )\n				if wand_ then\n					WANDS.initialize_wand( wand_, wand )\n				end\n			end\n			if #wands_to_load > 0 then\n				sound_button_clicked()\n			end\n		end\n		GuiTooltip( gui, wrap_key( \"wand_box_load_to_world\" ), \"\" )\n\n		if wand_box_current_page_index > 1 then\n			if GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/pagelast.png\" ) then\n				sound_button_clicked()\n				wand_box_current_page_index = wand_box_current_page_index - 1\n				wand_box_remove_page_confirming = false\n				wand_box_selected_indexes = {}\n			end\n			GuiTooltip( gui, wrap_key( \"wand_box_last_page\" ), GameTextGet( wrap_key( \"wand_box_current_page\" ), wand_box_current_page_index, mod_setting_get( \"wand_box_page_max_index\" ) ) )\n		else\n			GuiOptionsAddForNextWidget( gui, GUI_OPTION.DrawSemiTransparent )\n			GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/pagelast.png\" )\n			GuiTooltip( gui, wrap_key( \"wand_box_no_last_page\" ), \"\" )\n		end\n		if wand_box_current_page_index < mod_setting_get( \"wand_box_page_max_index\" ) then\n			if GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/pagenext.png\" ) then\n				sound_button_clicked()\n				wand_box_current_page_index = wand_box_current_page_index + 1\n				wand_box_remove_page_confirming = false\n				wand_box_selected_indexes = {}\n			end\n			GuiTooltip( gui, wrap_key( \"wand_box_next_page\" ), GameTextGet( wrap_key( \"wand_box_current_page\" ), wand_box_current_page_index, mod_setting_get( \"wand_box_page_max_index\" ) ) )\n		else\n			GuiOptionsAddForNextWidget( gui, GUI_OPTION.DrawSemiTransparent )\n			GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/pagenext.png\" )\n			GuiTooltip( gui, wrap_key( \"wand_box_no_next_page\" ), \"\" )\n		end\n\n		if GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/pagenew.png\" ) then\n			sound_button_clicked()\n			wand_box_remove_page_confirming = false\n			wand_box_new_page( wand_box_current_page_index, {} )\n			wand_box_selected_indexes = {}\n		end\n		GuiTooltip( gui, wrap_key( \"wand_box_new_page\" ), \"\" )\n		if GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/pagedelete.png\" ) then\n			sound_button_clicked()\n			if not wand_box_remove_page_confirming then\n				wand_box_remove_page_confirming = true\n			else\n				if shortcut_check.check( shortcuts.confirm ) then\n					if mod_setting_get( \"wand_box_page_max_index\" ) ~= 1 then\n						if wand_box_current_page_index == mod_setting_get( \"wand_box_page_max_index\" ) then\n							wand_box_current_page_index =  wand_box_current_page_index - 1\n						end\n						wand_box_remove_page( wand_box_current_page_index )\n					else\n						wand_box_set_page_data( wand_box_current_page_index, smallfolk.dumps( {} ) )\n						saved_wands[ wand_box_current_page_index ] = {}\n					end\n					wand_box_selected_indexes = {}\n				end\n				wand_box_remove_page_confirming = false\n			end\n		end\n		if not wand_box_remove_page_confirming then\n			GuiTooltip( gui, GameTextGet( wrap_key( \"wand_box_delete_page\" ), wand_box_current_page_index ), \"\" )\n		else\n			GuiTooltip( gui, GameTextGet( wrap_key( \"wand_box_delete_page\" ), wand_box_current_page_index ), text_get( \"deletion_confirm_button\", shortcut_texts.confirm ) )\n		end\n	GuiLayoutEnd( gui )\nend\n\nreturn picker"
_TWWE_VFS["mods/spell_lab_shugged/files/gui/pickers/wand_picker.lua"] = "local picker = {}\npicker.menu = function()\n	GuiBeginAutoBox( gui )\n		GuiLayoutBeginVertical( gui, 640 * 0.05, 360 * 0.24, true )\n			GuiLayoutBeginHorizontal( gui, 0, 0 )\n				GuiLayoutBeginVertical( gui, 0, 0 )\n					local precise_mode = mod_setting_get( \"wand_picker_precise_mode\" )\n					for _, stat in ipairs( wand_stats ) do\n						GuiLayoutBeginHorizontal( gui, 0, 0 )\n							local width = GuiGetTextDimensions( gui, stat.label )\n							GuiText( gui, 60 - width, 0, stat.label )\n							local _, _, _, x, y, width = previous_data( gui )\n							GuiOptionsAddForNextWidget( gui, GUI_OPTION.Layout_NoLayouting )\n							GuiColoredText( gui, 1.0, 0.75, 0.5, 1.0, x + width + 10, y, stat.text_callback( stat.current ) )\n							if not precise_mode then\n								stat.current = stat.value_callback( GuiSlider( gui, next_id(), 70, 0, \" \", stat.current, stat.min, stat.max, stat.default, 1.0, stat.formatter, 140 ) )\n							else\n								local first_button = true\n								for _, button in ipairs( stat.buttons_precise_mode or {} ) do\n									local _x = 0\n									if first_button then\n										_x = 70\n										first_button = false\n									end\n									local text = button.text\n									if type( text ) == \"function\" then\n										text = text()\n									end\n									GuiOptionsAddForNextWidget( gui, GUI_OPTION.NoSound )\n									GuiButton( gui, _x, 0, text, next_id() )\n									local left_click, right_click = previous_data( gui )\n									if type( stat.current ) == \"boolean\" then\n										stat.current = stat.current and 1 or 0\n									end\n									if left_click then\n										stat.current = stat.current + button.value\n										GamePlaySound( \"data/audio/Desktop/ui.bank\", \"ui/button_click\", GameGetCameraPos() )\n									elseif right_click then\n										stat.current = stat.current - button.value\n										GamePlaySound( \"data/audio/Desktop/ui.bank\", \"ui/button_click\", GameGetCameraPos() )\n									end\n								end\n								if stat.name == \"shuffle_deck_when_empty\" then\n									stat.current = math.min( stat.max, math.max( stat.min, stat.current ) )\n								end\n							end\n						GuiLayoutEnd( gui )\n					end\n					GuiLayoutBeginHorizontal( gui, 0, 360 * 0.02, true )\n					if GuiButton( gui, 0, 0, wrap_key( \"wand_picker_spawn_wand\" ), next_id() ) then\n						if player then\n							local x, y = EntityGetTransform( player )\n							local wand = EntityLoad( \"data/entities/items/wand_level_01.xml\", x, y )\n							local wand_data = {\n								stats = {}\n							}\n							for _,stat_data in ipairs( wand_stats ) do\n								wand_data.stats[stat_data.stat] = stat_data.current\n							end\n							wand_data.stats[\"shuffle_deck_when_empty\"] = wand_data.stats[\"shuffle_deck_when_empty\"] == 1\n							WANDS.initialize_wand( wand, wand_data )\n						end\n					end\n					if held_wand then\n						if GuiButton( gui, 8, 0, wrap_key( \"wand_picker_copy_held_wand\" ), next_id() ) then\n							if not held_wand then goto skip end\n							local stats = WANDS.wand_get_stats( held_wand )\n							if not stats then goto skip end\n							for k,v in pairs( stats ) do\n								for _,stat_data in ipairs( wand_stats ) do\n									if stat_data.stat == k then\n										stat_data.current = v\n										break\n									end\n								end\n							end\n							::skip::\n						end\n						if GuiButton( gui, 8, 0, wrap_key( \"wand_picker_update_held_wand\" ), next_id() ) then\n							if player and held_wand then\n								local x, y = EntityGetTransform( player )\n								local wand_data = {\n									stats = {}\n								}\n								for _,stat_data in ipairs( wand_stats ) do\n									wand_data.stats[stat_data.stat] = stat_data.current\n								end\n								local do_update = true\n								local deck_capacity = wand_data.stats.capacity + WANDS.wand_get_num_actions_permanent( wand )\n								if not WANDS.wand_check_actions_out_of_bound( held_wand, deck_capacity ) then\n									if not shift then\n										GamePrint( text_get( \"wand_picker_exploding_actions\", shortcut_texts.confirm ) )\n										do_update = false\n									end\n								end\n								if do_update then\n									wand_data.stats.shuffle_deck_when_empty = wand_data.stats.shuffle_deck_when_empty == 1\n									WANDS.initialize_wand( held_wand, wand_data, false )\n									WANDS.wand_explode_actions_out_of_bound( held_wand )\n									force_refresh_held_wands()\n								end\n							end\n						end\n					end\n					if GuiButton( gui, 8, 0, text_get( \"wand_picker_precise_mode\", text_get_translated( precise_mode and \"disable\" or \"enable\" ) ), next_id() ) then\n						mod_setting_set( \"wand_picker_precise_mode\", not precise_mode )\n					end\n					if precise_mode then\n						GuiTooltip( gui, wrap_key( \"wand_picker_precise_mode_tips\" ), \"\" )\n					end\n					GuiLayoutEnd( gui )\n				GuiLayoutEnd( gui )\n			GuiLayoutEnd( gui )\n		GuiLayoutEnd( gui )\n		GuiZSetForNextWidget( gui, 1 )\n	GuiEndAutoBoxNinePiece( gui )\nend\n\npicker.buttons = function() end\n\nreturn picker"
_TWWE_VFS["mods/spell_lab_shugged/files/gui/shot_effect_entries.lua"] = "shot_effect_entries = {\n	{\n		related_status = \"BLOODY\",\n		extra_modifier = \"critical_hit_boost\",\n		desc = wrap_key( \"shot_effect_desc_bloody\" ),\n	},\n	{\n		related_perk = \"RISKY_CRITICAL\",\n		extra_modifier = \"critical_plus_small\",\n		desc = wrap_key( \"shot_effect_desc_risky_critical\" ),\n	},\n	{\n		related_perk = \"PROJECTILE_HOMING\",\n		game_effect = \"PROJECTILE_HOMING\",\n	},\n	{\n		related_perk = \"PROJECTILE_HOMING_SHOOTER\",\n		extra_modifier = { \"powerful_shot\", \"projectile_homing_shooter\" },\n	},\n	{\n		related_perk = \"FOOD_CLOCK\",\n		extra_modifier = \"food_clock\",\n		desc = wrap_key( \"shot_effect_desc_food_clock\" ),\n	},\n	{\n		related_custom_effect = \"data/entities/misc/effect_damage_plus_small.xml\",\n		icon = \"data/items_gfx/perks/hungry_ghost.png\",\n		extra_modifier = \"damage_plus_small\",\n		dont_use_fetched_metadata = true,\n		properties = {\n			{ \"$inventory_mod_damage\", \"+7.5\" },\n			{ \"$inventory_mod_damage\", \"x 1.25\" },\n		},\n	},\n	{\n		related_perk = \"EXTRA_KNOCKBACK\",\n		extra_modifier = \"extra_knockback\",\n	},\n	{\n		related_perk = \"LOWER_SPREAD\",\n		extra_modifier = \"lower_spread\",\n	},\n	{\n		related_perk = \"LASER_AIM\",\n		extra_modifier = \"laser_aim\",\n		desc = wrap_key( \"shot_effect_desc_laser_aim\" ),\n	},\n	{\n		related_perk = \"LOW_RECOIL\",\n		extra_modifier = \"low_recoil\",\n		metadata = {\n			{ \"speed_multiplier\", 0.8 },\n			{ wrap_key( \"recoil\" ), { TYPE_ADJUSTMENT.Add, -16 } },\n		},\n		properties = {\n			{ wrap_key( \"recoil\" ), \"x 0.5\" },\n		},\n	},\n	{\n		related_perk = \"BOUNCE\",\n		extra_modifier = \"bounce\",\n	},\n	{\n		related_custom_effect = \"data/entities/misc/effect_homing_shooter.xml\",\n		extra_modifier = \"projectile_homing_shooter_wizard\",\n		desc = wrap_key( \"shot_effect_desc_homing_shooter_wizard\" ),\n	},\n	{\n		id = \"essence_alcohol\",\n		icon = \"data/items_gfx/essences/essence_alcohol.png\",\n		name = \"$item_essence_alcohol\",\n		desc = \"$itemdesc_essence_alcohol\",\n		source_type = \"$item_essence_alcohol\",\n		extra_modifier = \"projectile_alcohol_trail\",\n	},\n	{\n		related_perk = \"DUPLICATE_PROJECTILE\",\n		extra_modifier = \"duplicate_projectile\",\n		equivalent_action_type = ACTION_TYPE_UTILITY,\n		desc = wrap_key( \"shot_effect_desc_duplicate_projectile\" ),\n	},\n	{\n		related_perk = \"FAST_PROJECTILES\",\n		extra_modifier = \"fast_projectiles\",\n	},\n	{\n		related_perk = \"PERSONAL_LASER\",\n		extra_modifier = \"slow_firing\",\n		desc = wrap_key( \"shot_effect_desc_personal_laser\" ),\n	},\n	{\n		related_perk = \"GLASS_CANNON\",\n		game_effect = \"DAMAGE_MULTIPLIER\",\n		max_count = 2,\n		desc = wrap_key( \"shot_effect_desc_glass_cannon\" ),\n	},\n	{\n		related_perk = \"LOW_HP_DAMAGE_BOOST\",\n		game_effect = \"LOW_HP_DAMAGE_BOOST\",\n		custom_child_entity = \"mods/spell_lab_shugged/files/entities/low_hp_triggerer.xml\",\n		max_count = 1,\n	},\n	{\n		related_status = \"BERSERK\",\n		game_effect = \"BERSERK\",\n		max_count = 1,\n	},\n	{\n		related_custom_effect = \"data/entities/misc/effect_twitchy.xml\",\n		shot_script = \"data/scripts/status_effects/twitchy_shot.lua\",\n		max_count = 1,\n		metadata = {\n			{ \"friendly_fire\", true },\n		},\n		desc = wrap_key( \"shot_effect_desc_twitchy\" ),\n	},\n	{\n		related_custom_effect = \"data/entities/misc/neutralized.xml\",\n		shot_script = \"data/scripts/projectiles/neutralized.lua\",\n		max_count = 1,\n	},\n}"
_TWWE_VFS["mods/spell_lab_shugged/files/gui/update.lua"] = "if do_gui then\n	do_content_wrapped( do_gui, \"main\" )\n	return\nend\n\nprint( \"[spell lab] setting up GUI\" )\n\ndofile_once( \"data/scripts/gun/gun.lua\" )\ndofile_once( \"data/scripts/lib/utilities.lua\" )\ndofile_once( \"mods/spell_lab_shugged/files/lib/helper.lua\")\ndofile_once( \"mods/spell_lab_shugged/files/gui/gui_utils.lua\")\ndofile_once( \"mods/spell_lab_shugged/files/gui/gui_elements.lua\")\ndofile_once( \"mods/spell_lab_shugged/files/gui/get_player.lua\" )\nWANDS = dofile_once( \"mods/spell_lab_shugged/files/lib/wands.lua\")\ndofile_once( \"data/scripts/debug/keycodes.lua\" )\nKEYCODES_RAW, KEYCODES_BY_TYPE = unpack( dofile_once( \"mods/spell_lab_shugged/files/lib/keycodes_wrapped.lua\" ) )\nsmallfolk = dofile_once( \"mods/spell_lab_shugged/files/lib/smallfolk.lua\" )\nshortcut_check = dofile_once( \"mods/spell_lab_shugged/files/lib/shortcut_check.lua\" )\n\ngui = gui or GuiCreate()\nGuiStartFrame( gui )\nscreen_width, screen_height = GuiGetScreenDimensions( gui )\n\nlocal version = \"Shugged v1.8.11\"\n\ntype_text = {\n	[ACTION_TYPE_MODIFIER]          = \"$inventory_actiontype_modifier\",\n	[ACTION_TYPE_PROJECTILE]        = \"$inventory_actiontype_projectile\",\n	[ACTION_TYPE_STATIC_PROJECTILE] = \"$inventory_actiontype_staticprojectile\",\n	[ACTION_TYPE_OTHER]             = \"$inventory_actiontype_other\",\n	[ACTION_TYPE_MATERIAL]          = \"$inventory_actiontype_material\",\n	[ACTION_TYPE_DRAW_MANY]         = \"$inventory_actiontype_drawmany\",\n	[ACTION_TYPE_UTILITY]           = \"$inventory_actiontype_utility\",\n	[ACTION_TYPE_PASSIVE]           = \"$inventory_actiontype_passive\",\n}\n\nsorted_actions = {}\naction_data = {}\nfor k, _ in pairs( type_text ) do\n	sorted_actions[ k ] = {}\nend\nfor _, action in pairs( actions ) do\n	sorted_actions[action.type][ #sorted_actions[action.type] + 1 ] = action\n	action_data[action.id] = action\nend\naction_metadata, extra_modifier_metadata, metadata_to_show =\n	unpack( dofile( \"mods/spell_lab_shugged/files/gui/action_metadata.lua\" ) )\n\nlocal is_panel_open = false\n\ndofile_once( \"mods/spell_lab_shugged/files/gui/edit_panel_utils.lua\" )\ndofile_once( \"mods/spell_lab_shugged/files/gui/pickers.lua\" )\n\naction_id_to_idx = {}\n\nfor i, a in ipairs( actions ) do\n	if a.id and a.id ~= \"\" then\n		action_id_to_idx[ a.id ] = i\n	end\n	if a.max_uses ~= nil then\n		local hell_no = type( a.max_uses )\n		if hell_no == \"string\" then\n			a.max_uses = tonumber( a.max_uses ) or 0\n		elseif hell_no ~= \"number\" then\n			a.max_uses = 0\n		end\n		if a.max_uses < 0 then\n			a.max_uses = nil\n		end\n	end\nend\n\nwand_stats = dofile( \"mods/spell_lab_shugged/files/gui/wand_stats.lua\" )\n\ndofile_once( \"mods/spell_lab_shugged/files/gui/edit_panel_api.lua\" )\n\ndofile_once( \"mods/spell_lab_shugged/files/gui/keyboard_listener.lua\" )\ndofile_once( \"mods/spell_lab_shugged/files/gui/keyboard_focus.lua\" )\n\nfunction show_edit_panel_toggle_options()\n	GuiLayoutBeginHorizontal( gui, 0, 0, true )\n		local edit_panel_state = access_edit_panel_state( held_wand )\n		local force_compact_enabled = edit_panel_state.get_force_compact_enabled()\n		if not force_compact_enabled then\n			GuiOptionsAddForNextWidget( gui, GUI_OPTION.DrawSemiTransparent )\n		end\n		if GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/force_compact.png\" ) then\n			sound_button_clicked()\n			edit_panel_state.set_force_compact_enabled( not force_compact_enabled )\n			edit_panel_state.force_sync()\n		end\n		GuiTooltip( gui, text_get_translated( force_compact_enabled and \"disable\" or \"enable\" ) .. text_get_translated( \"wand_force_compact\" ), text_get_translated( \"wand_force_compact_description\" ) .. \"\\n\" .. text_get_translated( \"inventory_get_ignored\" )  )\n		local autocap_enabled = edit_panel_state.get_autocap_enabled()\n		if not autocap_enabled then\n			GuiOptionsAddForNextWidget( gui, GUI_OPTION.DrawSemiTransparent )\n		end\n		if GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/automatic_capacity.png\" ) then\n			sound_button_clicked()\n			edit_panel_state.set_autocap_enabled( not autocap_enabled )\n			if autocap_enabled and edit_panel_state.get_force_compact_enabled() then\n				local new_capacity = 0\n				for _ in state_str_iter_permanent_actions( edit_panel_state.get_permanent() ) do\n					new_capacity = new_capacity + 1\n				end\n				local temp = 0\n				for _, a, _ in state_str_iter_actions( edit_panel_state.get() ) do\n					temp = temp + 1\n					if a and a ~= \"\" then\n						new_capacity = new_capacity + temp\n						temp = 0\n					end\n				end\n				WANDS.wand_set_stat( held_wand, \"deck_capacity\", new_capacity )\n			end\n		end\n		GuiTooltip( gui, text_get_translated( autocap_enabled and \"disable\" or \"enable\" ) .. text_get_translated( \"automatic_capacity\" ), wrap_key( \"automatic_capacity_description\" ) )\n	GuiLayoutEnd( gui )\n\n	GuiLayoutBeginHorizontal( gui, 0, 0, true )\n		local function cant_undo()\n			GuiOptionsAddForNextWidget( gui, GUI_OPTION.DrawSemiTransparent )\n			GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/undo.png\" )\n			GuiTooltip( gui, text_get_translated( \"cant_undo\" ), \"\" )\n		end\n		local function cant_redo()\n			GuiOptionsAddForNextWidget( gui, GUI_OPTION.DrawSemiTransparent )\n			GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/redo.png\" )\n			GuiTooltip( gui, text_get_translated( \"cant_redo\" ), \"\" )\n		end\n		local operation_to_undo = edit_panel_state.peek_undo()\n		local operation_to_redo = edit_panel_state.peek_redo()\n		if operation_to_undo then\n			if GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/undo.png\" ) then\n				sound_button_clicked()\n				edit_panel_state.undo()\n			end\n			GuiTooltip( gui, text_get_translated( \"undo\" ) .. \" \" .. GameTextGetTranslatedOrNot( operation_to_undo ),\n				GameTextGet( wrap_key( \"current_history\" ), edit_panel_state.get_current_history_index() ) )\n		else cant_undo() end\n		if operation_to_redo then\n			if GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/redo.png\" ) then\n				sound_button_clicked()\n				edit_panel_state.redo()\n			end\n			GuiTooltip( gui, text_get_translated( \"redo\" ) .. \" \" .. GameTextGetTranslatedOrNot( operation_to_redo ),\n				GameTextGet( wrap_key( \"current_history\" ), edit_panel_state.get_current_history_index() ) )\n		else cant_redo() end\n	GuiLayoutEnd( gui )\nend\n\nshortcuts = {\n	select = { \"Mouse_left\" },\n	deselect = { \"Mouse_right\" },\n	multi_select = { \"Key_CTRL\", \"Mouse_left\" },\n	expand_selection_left = { \"Key_CTRL\", \"Key_ALT\", \"Mouse_left\" },\n	expand_selection_right = { \"Key_CTRL\", \"Key_ALT\", \"Mouse_right\" },\n	swap = { \"Key_ALT\", \"Mouse_left\" },\n	override = { \"Key_ALT\", \"Mouse_right\" },\n	duplicate = { \"Key_ALT\", \"Key_SHIFT\", \"Mouse_left\" },\n	delete_action = { \"Key_SHIFT\", \"Mouse_left\" },\n	delete_slot = { \"Key_SHIFT\", \"Mouse_right\" },\n	always_cast = { \"Key_CTRL\", \"Key_SHIFT\", \"Mouse_left\" },\n	left_delete = { \"Key_BACKSPACE\" },\n	right_delete = { \"Key_DELETE\" },\n	undo = { \"Key_CTRL\", \"Key_z\" },\n	redo = { \"Key_CTRL\", \"Key_y\" },\n	relock = { \"Key_CTRL\", \"Key_SHIFT\", \"Mouse_left\" },\n	show_wand_stats = { \"Key_CTRL\" },\n	replace_switch_temp = { \"Key_SHIFT\" },\n	replace_switch = {},\n	confirm = { \"Key_SHIFT\" },\n	clear_action_history = { \"Key_SHIFT\", \"Mouse_right\" },\n	transform_mortal_into_dummy = { \"Key_SHIFT\" },\n}\n\ndofile_once( \"mods/spell_lab_shugged/files/lib/shortcut_tostring.lua\" )\n\nshortcut_texts = {}\n\nshortcut_used_keys = nil\n\nlocal edit_panel_shortcut_tips\n\nfunction reload_shortcuts()\n	for name, _ in pairs( shortcuts ) do\n		local value = mod_setting_get( \"shortcut_\" .. name )\n		if value ~= nil then value = smallfolk.loads( value ) end\n		if value ~= nil then shortcuts[ name ] = value end\n	end\n\n	if not mod_setting_get( \"shortcut_strict\" ) then\n		shortcut_used_keys = {}\n		for _, shortcut in pairs( shortcuts ) do\n			for _, key in ipairs( shortcut ) do\n				shortcut_used_keys[ key ] = true\n			end\n		end\n	else\n		shortcut_used_keys = nil\n	end\n\n	reload_shortcut_texts()\nend\n\nlocal last_cur_lang = GameTextGet( \"$current_language\" )\n\nfunction reload_shortcut_texts()\n	for name, v in pairs( shortcuts ) do\n		shortcut_texts[ name ] = shortcut_tostring( v, last_cur_lang )\n	end\n\n	edit_panel_shortcut_tips = text_get_translated( \"shortcut_tips\" )\n	for name, v in pairs( shortcuts ) do\n		edit_panel_shortcut_tips = edit_panel_shortcut_tips:gsub( \"{\" .. name .. \"}\", shortcut_texts[ name ] )\n	end\nend\n\nreload_shortcuts()\n\nfunction do_gui()\n	shift = InputIsKeyDown( Key_LSHIFT ) or InputIsKeyDown( Key_RSHIFT )\n	alt = InputIsKeyDown( Key_LALT ) or InputIsKeyDown( Key_RALT )\n\n	cached_mouse_x, cached_mouse_y = nil, nil\n\n	now = GameGetFrameNum()\n	reset_z()\n\n	GuiStartFrame( gui )\n\n	screen_width, screen_height = GuiGetScreenDimensions( gui )\n\n	GuiOptionsAdd( gui, GUI_OPTION.NoPositionTween )\n	GuiOptionsAdd( gui, GUI_OPTION.HandleDoubleClickAsClick )\n	GuiOptionsAdd( gui, GUI_OPTION.ClickCancelsDoubleClick )\n\n	world_state = GameGetWorldStateEntity()\n	if EntityGetIsAlive( world_state ) then\n		local comp_worldstate = EntityGetFirstComponentIncludingDisabled( world_state, \"WorldStateComponent\" )\n		world_state_unlimited_spells = ComponentGetValue2( comp_worldstate, \"perk_infinite_spells\" )\n	end\n\n	player = get_player()\n	held_wand = get_held_wand()\n\n	keyboard_input_holding = listen_keyboard_down()\n\n	dofile( \"mods/spell_lab_shugged/files/gui/wand_listener.lua\" )\n\n	update_keyboard_input( listen_keyboard_just_down() )\n\n	if GameGetFrameNum() % 60 == 0 then\n		if mod_setting_get( \"shortcut_changed\" ) then\n			mod_setting_set( \"shortcut_changed\", false )\n			reload_shortcuts()\n		end\n\n		local cur_lang = GameTextGet( \"$current_language\" )\n		if cur_lang ~= last_cur_lang then\n			last_cur_lang = cur_lang\n			reload_shortcut_texts()\n		end\n	end\n\n	local mod_button_reservation = tonumber( GlobalsGetValue( \"spell_lab_shugged_mod_button_reservation\", \"0\" ) )\n	local current_button_reservation = tonumber( GlobalsGetValue( \"mod_button_tr_current\", \"0\" ) )\n	if current_button_reservation > mod_button_reservation then\n		current_button_reservation = mod_button_reservation\n	elseif current_button_reservation < mod_button_reservation then\n		current_button_reservation = math.max( 0, mod_button_reservation + ( current_button_reservation - mod_button_reservation ) )\n	else\n		current_button_reservation = mod_button_reservation\n	end\n	GlobalsSetValue( \"mod_button_tr_current\", tostring( current_button_reservation + 15 ) )\n	\n	GuiOptionsAddForNextWidget( gui, GUI_OPTION.NonInteractive )\n	GuiOptionsAddForNextWidget( gui, GUI_OPTION.AlwaysClickable )\n	if GuiImageButton( gui, next_id(), screen_width - 14 - current_button_reservation, 2, \"\", \"mods/spell_lab_shugged/files/gui/wrench.png\" ) then\n		sound_button_clicked()\n		is_panel_open = not is_panel_open\n	end\n	\n	local animation_id = next_id()\n	next_id()\n	if previous_hovered() then\n		local _,_,_,x,y = previous_data( gui )\n		local text = wrap_key( ( is_panel_open and \"hide\" or \"show\" ) .. \"_spell_lab\" )\n		local text_width = GuiGetTextDimensions( gui, text )\n		GuiAnimateBegin( gui )\n		GuiAnimateAlphaFadeIn( gui, animation_id, 0.08, 0.1, false )\n		GuiAnimateScaleIn( gui, animation_id + 1, 0.08, false )\n		GuiOptionsAdd( gui, GUI_OPTION.Align_Left )\n		GuiZSet( gui, -100 )\n		show_tooltip( function()\n			GuiZSetForNextWidget( gui, -100 )\n			GuiText( gui, 0, 0, text )\n			GuiZSetForNextWidget( gui, -100 )\n			GuiDimText( gui, 0, 0, version )\n		end, x - 5 - 2 - 3, y + 10 )\n		GuiZSet( gui, 100 )\n		GuiOptionsRemove( gui, GUI_OPTION.Align_Left )\n		GuiAnimateEnd( gui )\n	end\n\n	if is_panel_open and not GameIsInventoryOpen() and player and not GameHasFlagRun( \"gkbrkn_config_menu_open\" ) then\n		GuiLayoutBeginVertical( gui, 0, 360 * 0.02, true )\n			GuiLayoutBeginHorizontal( gui, horizontal_centered_x(9,4), percent_to_ui_scale_y(2), true )\n				if GlobalsGetValue( \"spell_lab_shugged_checkpoint_x\", \"0\" ) == \"0\" then\n					GuiOptionsAddForNextWidget( gui, GUI_OPTION.DrawSemiTransparent )\n				end\n				GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/spell_lab.png\" )\n				do\n					local left_click, right_click = previous_data( gui )\n					if left_click then\n						sound_button_clicked()\n						if GlobalsGetValue( \"spell_lab_shugged_checkpoint_x\", \"0\" ) == \"0\" then\n							local px, py = EntityGetTransform( player )\n							GlobalsSetValue( \"spell_lab_shugged_checkpoint_x\", math.floor( px ) )\n							GlobalsSetValue( \"spell_lab_shugged_checkpoint_y\", math.floor( py ) )\n							EntityApplyTransform( player, 14600, -6050 )\n							GameSetCameraPos( 14600, -6050 )\n						else\n							if not shift then\n								local cx = tonumber( GlobalsGetValue( \"spell_lab_shugged_checkpoint_x\", \"0\" ) )\n								local cy = tonumber( GlobalsGetValue( \"spell_lab_shugged_checkpoint_y\", \"0\" ) ) - 10\n								EntityApplyTransform( player, cx, cy )\n								GameSetCameraPos( cx, cy )\n							else\n								EntityApplyTransform( player, 250, -100 )\n								GameSetCameraPos( 250, -100 )\n							end\n							GlobalsSetValue( \"spell_lab_shugged_checkpoint_x\", \"0\" )\n							GlobalsSetValue( \"spell_lab_shugged_checkpoint_y\", \"0\" )\n						end\n					elseif right_click then\n						if GlobalsGetValue( \"spell_lab_shugged_checkpoint_x\", \"0\" ) ~= \"0\" then\n							sound_button_clicked()\n							EntityLoad( \"mods/spell_lab_shugged/files/biome_impl/wand_lab/wand_lab.xml\", 14600, -6000 )\n						end\n					end\n				end\n				if GlobalsGetValue( \"spell_lab_shugged_checkpoint_x\", \"0\" ) == \"0\" then\n					GuiTooltip( gui, wrap_key( \"enter_spell_lab\" ), \"\" )\n				else\n					GuiTooltip( gui, wrap_key( \"leave_spell_lab\" ), wrap_key( \"reload_spell_lab\" ) )\n				end\n\n				do_picker_button( \"mods/spell_lab_shugged/files/gui/buttons/edit_wands.png\", PICKERS.SpellPicker, \"spell_picker\", function( showing )\n					if showing and held_wand and mod_setting_get( \"quick_spell_picker\" ) then\n						mod_setting_set( \"show_wand_edit_panel\", true )\n					end\n				end )\n				do_picker_button( \"mods/spell_lab_shugged/files/gui/buttons/wand_spawner.png\", PICKERS.WandPicker, \"wand_spawner\" )\n				do_picker_button( \"mods/spell_lab_shugged/files/gui/buttons/wand_list.png\", PICKERS.WandBox, \"wand_box\" )\n				do_picker_button( \"mods/spell_lab_shugged/files/gui/buttons/spell_groups.png\", PICKERS.SpellGroupBox, \"spell_group_box\", function( showing )\n					if showing and held_wand then\n						mod_setting_set( \"show_wand_edit_panel\", true )\n					end\n				end )\n				do_picker_button( \"mods/spell_lab_shugged/files/gui/buttons/shot_effects.png\", PICKERS.ShotEffects, \"shot_effects\" )\n				do_flag_toggle_image_button( \"mods/spell_lab_shugged/files/gui/buttons/show_toggles.png\", \"show_toggle_options\", \"toggle_options\" )\n				do_flag_toggle_image_button( \"mods/spell_lab_shugged/files/gui/buttons/damage_info.png\", \"damage_info\" )\n				do\n					local gif_mode = mod_setting_get( \"gif_mode\" )\n					local description = wrap_key( gif_mode and \"gif_mode_disable\" or \"gif_mode_enable\" )\n					local left_click, right_click = do_flag_toggle_image_button( \"mods/spell_lab_shugged/files/gui/buttons/show_wand_edit_panel.png\", \"show_wand_edit_panel\", \"wand_edit_panel\", nil, description )\n					if right_click then\n						sound_button_clicked()\n						mod_setting_set( \"gif_mode\", not gif_mode )\n					end\n				end\n			GuiLayoutEnd( gui )\n\n			if mod_setting_get( \"show_wand_edit_panel\" ) and held_wand then\n				GuiLayoutBeginLayer( gui )\n					local x, y = horizontal_centered_x(-9,4) + 5, 360 * 0.02 + percent_to_ui_scale_y(2)\n					GuiLayoutBeginVertical( gui, x, y, true )\n						show_edit_panel_toggle_options()\n					GuiLayoutEnd( gui )\n				GuiLayoutEndLayer( gui )\n			end\n\n			GuiLayoutBeginHorizontal( gui, horizontal_centered_x(9,4), percent_to_ui_scale_y(2), true )\n				GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/shortcut_tips.png\" )\n\n				GuiTooltip( gui, wrap_key( \"shortcut_tips_title\" ), edit_panel_shortcut_tips )\n\n				if GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/clear_projectiles.png\" ) then\n					sound_button_clicked()\n\n					local function silent_kill( proj_id )\n						for _, proj_comp in ipairs( EntityGetComponentIncludingDisabled( proj_id, \"ProjectileComponent\" ) or {} ) do\n							ComponentSetValue2( proj_comp, \"on_death_explode\", false )\n							ComponentSetValue2( proj_comp, \"on_lifetime_out_explode\", false )\n						end\n						for _, expl_comp in ipairs( EntityGetComponentIncludingDisabled( proj_id, \"ExplosionComponent\" ) or {} ) do\n							ComponentSetValue2( expl_comp, \"trigger\", \"ON_CREATE\" )\n						end\n						for _, litn_comp in ipairs( EntityGetComponentIncludingDisabled( proj_id, \"LightningComponent\" ) or {} ) do\n							EntitySetComponentIsEnabled( proj_id, litn_comp, false )\n						end\n						EntityKill( proj_id )\n					end\n\n					for _, proj_id in ipairs( EntityGetWithTag( \"projectile\" ) or {} ) do\n						silent_kill( proj_id )\n					end\n					for _, proj_id in ipairs( EntityGetWithTag( \"player_projectile\" ) or {} ) do\n						silent_kill( proj_id )\n					end\n				end\n				GuiTooltip( gui, wrap_key( \"clear_projectiles\" ), \"\" )\n\n				do\n					local raw_value_key = \"spell_lab_shugged.wand_cast_delay_fixed_to_raw_value\"\n					local cast_delay_key = \"spell_lab_shugged.wand_cast_delay_fixed_to\"\n					local reload_time_key = \"spell_lab_shugged.wand_reload_time_fixed_to\"\n\n					local fixed_to_raw_value = GlobalsGetValue( raw_value_key, \"0\" ) == \"1\"\n					local cast_delay_fixed_to = tonumber( GlobalsGetValue( cast_delay_key, \"\" ) )\n					local reload_time_fixed_to = tonumber( GlobalsGetValue( reload_time_key, \"\" ) )\n\n					if fixed_to_raw_value or ( cast_delay_fixed_to and reload_time_fixed_to ) then\n						local left_click, right_click = GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/clear_wait.png\" )\n						if left_click then\n							if clear_held_wand_wait() then sound_button_clicked() end\n						elseif right_click then\n							if fixed_to_raw_value then\n								GlobalsSetValue( raw_value_key, \"\" )\n								sound_button_clicked()\n							elseif cast_delay_fixed_to and reload_time_fixed_to then\n								GlobalsSetValue( cast_delay_key, \"\" )\n								GlobalsSetValue( reload_time_key, \"\" )\n								sound_button_clicked()\n							end\n						end\n						local _,_,_,x,y = previous_data( gui )\n						if fixed_to_raw_value then\n							local raw_value_text = GameTextGetTranslatedOrNot( wrap_key( \"wand_raw_value\" ) )\n							GuiTooltip( gui, wrap_key( \"wand_ready\" ), GameTextGet( wrap_key( \"wand_cast_delay_fixed_to\" ), raw_value_text, raw_value_text ) )\n						elseif cast_delay_fixed_to and reload_time_fixed_to then\n							GuiTooltip( gui, wrap_key( \"wand_ready\" ), GameTextGet( wrap_key( \"wand_cast_delay_fixed_to\" ),\n							format_time( cast_delay_fixed_to ), format_time( reload_time_fixed_to ) ) )\n						end\n						GuiZSetForNextWidget( gui, -1 )\n						GuiOptionsAddForNextWidget( gui, GUI_OPTION.Layout_NoLayouting )\n						GuiImage( gui, next_id(), x - 2, y - 2, \"mods/spell_lab_shugged/files/gui/locked.png\", 1.0, 1.0, 0 )\n					else\n						local left_click, right_click = GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/clear_wait.png\" )\n						if shift and left_click then\n							if held_wand then\n								local ab_comp = EntityGetFirstComponentIncludingDisabled( held_wand, \"AbilityComponent\" )\n								if ab_comp then\n									local cast_delay = WANDS.ability_component_get_stat( ab_comp, \"fire_rate_wait\" )\n									local reload_time = WANDS.ability_component_get_stat( ab_comp, \"reload_time\" )\n									GlobalsSetValue( cast_delay_key, tostring( cast_delay ) )\n									GlobalsSetValue( reload_time_key, tostring( reload_time ) )\n									sound_button_clicked()\n								end\n							end\n						elseif shift and right_click then\n							GlobalsSetValue( cast_delay_key, \"0\" )\n							GlobalsSetValue( reload_time_key, \"0\" )\n							sound_button_clicked()\n						elseif alt and ( left_click or right_click ) then\n							GlobalsSetValue( raw_value_key, \"1\" )\n							sound_button_clicked()\n						elseif left_click then\n							if clear_held_wand_wait() then sound_button_clicked() end\n						end\n					end\n					GuiTooltip( gui, wrap_key( \"wand_ready\" ), wrap_key( \"wand_ready_description\" ) )\n				end\n\n				if GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/clear_wand.png\" ) then\n					if held_wand then\n						sound_button_clicked()\n						WANDS.wand_clear_actions( held_wand )\n					end\n				end\n				GuiTooltip( gui, wrap_key( \"clear_held_wand\" ), \"\" )\n\n				local num_effects_positive = GameGetGameEffectCount( player, \"EDIT_WANDS_EVERYWHERE\" )\n				local num_effects_negative = GameGetGameEffectCount( player, \"NO_WAND_EDITING\" )\n				local wand_editing_level = num_effects_positive - num_effects_negative\n				if wand_editing_level > 0 then\n					GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/edit_wands_everywhere.png\" )\n				elseif wand_editing_level < 0 then\n					GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/edit_wands_everywhere.png\" )\n				else\n					GuiOptionsAddForNextWidget( gui, GUI_OPTION.DrawSemiTransparent )\n					GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/edit_wands_everywhere.png\" )\n				end\n				do\n					local a = #EntityGetWithTag( \"spell_lab_shugged_effect_edit_wands_everywhere\" )\n					local b = #EntityGetWithTag( \"spell_lab_shugged_effect_no_wand_editing\" )\n					local c = GameGetGameEffectCount( player, \"EDIT_WANDS_EVERYWHERE\" ) - a\n					local d = GameGetGameEffectCount( player, \"NO_WAND_EDITING\" ) - b\n					local level = a + c - b - d\n					local tooltip = {}\n\n					if num_effects_positive > 0 then\n						tooltip[ #tooltip + 1 ] = GameTextGet( wrap_key( \"edit_wands_num\" ), text_get( \"edit_wands_perk_positive\" ), a, c )\n					end\n					if num_effects_negative > 0 then\n						tooltip[ #tooltip + 1 ] = GameTextGet( wrap_key( \"edit_wands_num\" ), text_get( \"edit_wands_perk_negative\" ), b, d )\n					end\n\n					local expr = {}\n					local function add_num_to_expr( num )\n						if #expr > 0 then\n							expr[ #expr + 1 ] = \" + \"\n						end\n						if num > 0 then\n							expr[ #expr + 1 ] = tostring( num )\n						elseif num == 0 then\n							expr[ #expr + 1 ] = \"0\"\n						elseif num < 0 then\n							expr[ #expr + 1 ] = \"(\"\n							expr[ #expr + 1 ] = tostring( num )\n							expr[ #expr + 1 ] = \")\"\n						end\n					end\n\n					if a ~= 0 or c ~= 0 then\n						add_num_to_expr( a )\n						add_num_to_expr( c )\n					end\n					if b ~= 0 or d ~= 0 then\n						add_num_to_expr( -b )\n						add_num_to_expr( -d )\n					end\n\n					if #expr > 0 then\n						expr[ #expr + 1 ] = \" = \"\n					end\n					expr[ #expr + 1 ] = tostring( level )\n\n					if level > 0 then\n						expr[ #expr + 1 ] = \" > 0\"\n					elseif level < 0 then\n						expr[ #expr + 1 ] = \" < 0\"\n					end\n\n					table.insert( tooltip, GameTextGet( wrap_key( \"edit_wands_level\" ), table.concat( expr ) ) )\n\n					if level > 0 then\n						table.insert( tooltip, wrap_key( \"edit_wands_everywhere\" ) )\n					elseif level == 0 then\n						table.insert( tooltip, wrap_key( \"edit_wands_workshop\" ) )\n					else\n						table.insert( tooltip, wrap_key( \"edit_wands_unable\" ) )\n					end\n\n					local title = {\n						GameTextGet( wrap_key( \"edit_wands_gain\" ), text_get( \"edit_wands_perk_positive\" ) ),\n						GameTextGet( wrap_key( \"edit_wands_lose\" ), text_get( \"edit_wands_perk_positive\" ) ),\n					}\n\n					local left_click,right_click = previous_data( gui )\n\n					if left_click then\n						sound_button_clicked()\n						local effect_to_remove = EntityGetWithTag( \"spell_lab_shugged_effect_no_wand_editing\" )[1]\n						if effect_to_remove then\n							EntityRemoveTag( effect_to_remove, \"spell_lab_shugged_effect_no_wand_editing\" )\n							EntityRemoveFromParent( effect_to_remove )\n							EntityKill( effect_to_remove )\n						else\n							local effect_id = EntityCreateNew()\n							EntityAddChild( player, effect_id )\n							EntityAddComponent2( effect_id, \"GameEffectComponent\", {\n								effect = \"EDIT_WANDS_EVERYWHERE\",\n								frames = -1,\n							} )\n							EntityAddTag( effect_id, \"spell_lab_shugged_effect_edit_wands_everywhere\" )\n						end\n					elseif right_click then\n						sound_button_clicked()\n						local effect_to_remove = EntityGetWithTag( \"spell_lab_shugged_effect_edit_wands_everywhere\" )[1]\n						if effect_to_remove then\n							EntityRemoveTag( effect_to_remove, \"spell_lab_shugged_effect_edit_wands_everywhere\" )\n							EntityRemoveFromParent( effect_to_remove )\n							EntityKill( effect_to_remove )\n						else\n							local effect_id = EntityCreateNew()\n							EntityAddChild( player, effect_id )\n							EntityAddComponent2( effect_id, \"GameEffectComponent\", {\n								effect = \"NO_WAND_EDITING\",\n								frames = -1,\n							} )\n							EntityAddTag( effect_id, \"spell_lab_shugged_effect_no_wand_editing\" )\n						end\n					end\n					\n					GuiTooltip( gui, table.concat( title, \"\\n\" ), table.concat( tooltip, \"\\n\" ) )\n				end\n				local hp_fixer = EntityGetWithName( \"spell_lab_shugged_hp_fixer\" )\n				if hp_fixer ~= 0 then\n					local hp_comp = get_variable_storage_component( hp_fixer, \"hp\" )\n					local max_hp_comp = get_variable_storage_component( hp_fixer, \"max_hp\" )\n					local hp_fixed_to = ComponentGetValue2( hp_comp, \"value_float\" )\n					local max_hp_fixed_to = ComponentGetValue2( max_hp_comp, \"value_float\" )\n					local _,right_click = GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/heart.png\" )\n					if right_click then\n						sound_button_clicked()\n						EntityKill( hp_fixer )\n					end\n					local _,_,_,x,y = previous_data( gui )\n					GuiTooltip( gui, GameTextGet( wrap_key( \"hp_fixed_to\" ),\n						format_damage( hp_fixed_to ), format_damage( max_hp_fixed_to ) ), \"\" )\n					GuiZSetForNextWidget( gui, -1 )\n					GuiOptionsAddForNextWidget( gui, GUI_OPTION.Layout_NoLayouting )\n					GuiImage( gui, next_id(), x - 2, y - 2, \"mods/spell_lab_shugged/files/gui/locked.png\", 1.0, 1.0, 0 )\n				else\n					if GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/heart.png\" ) then\n						sound_button_clicked()\n						if shift then\n							EntityAddChild( player, EntityLoad( \"mods/spell_lab_shugged/files/entities/hp_fixer.xml\" ) )\n						else\n							local damage_model = EntityGetFirstComponentIncludingDisabled( player, \"DamageModelComponent\" )\n							if damage_model then\n								local max_hp = ComponentGetValue2( damage_model, \"max_hp\" )\n								ComponentSetValue2( damage_model, \"hp\", max_hp )\n							end\n						end\n					end\n					GuiTooltip( gui, wrap_key( \"full_hp\" ), \"\" )\n				end\n\n\n				GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/spawn_target_dummy.png\" )\n				do\n					local snap_gird_size = 10\n					local left_click,right_click,hover = previous_data( gui )\n					if alt and hover then\n						local x, y = get_player_or_camera_position()\n						x = math.floor( x / snap_gird_size + 0.5 ) * snap_gird_size\n						y = math.floor( y / snap_gird_size + 0.5 ) * snap_gird_size\n\n						-- nolla why do you have to do this\n						GameCreateSpriteForXFrames( \"mods/spell_lab_shugged/files/entities/dummy_target/dummy_target.png\", x, y, false, 14, 10.5, 2, true )\n					end\n					if left_click or right_click then\n						local x, y = get_player_or_camera_position()\n						if alt then\n							x = math.floor( x / snap_gird_size + 0.5 ) * snap_gird_size\n							y = math.floor( y / snap_gird_size + 0.5 ) * snap_gird_size\n						end\n						if left_click then\n							EntityLoad( \"mods/spell_lab_shugged/files/entities/dummy_target/dummy_target.xml\", x, y )\n						elseif right_click then\n							EntityLoad( \"mods/spell_lab_shugged/files/entities/dummy_target/dummy_target_final.xml\", x, y )\n						end\n						sound_button_clicked()\n					end\n				end\n				-- GuiTooltip( gui, wrap_key( \"spawn_target_dummy\" ), wrap_key( \"spawn_target_dummy_description\" ) )\n				do_custom_tooltip( function()\n					GuiText( gui, 0, 0, wrap_key( \"spawn_target_dummy\" ) )\n					GuiText( gui, 0, 0, wrap_key( \"spawn_target_dummy_description\" ) )\n					GuiLayoutAddVerticalSpacing( gui, 6 )\n					GuiText( gui, 0, 0, wrap_key( \"target_dummy_numbers_are\" ) )\n					GuiColorSetForNextWidget( gui, color(0,207,40,255) )\n					GuiText( gui, 0, 0, wrap_key( \"target_dummy_last_frame_damage\" ) )\n					GuiColorSetForNextWidget( gui, color(208,208,248,255) )\n					GuiText( gui, 0, 0, wrap_key( \"target_dummy_average_dps\" ) )\n					GuiColorSetForNextWidget( gui, color(255,85,0,255) )\n					GuiText( gui, 0, 0, wrap_key( \"target_dummy_total_damage\" ) )\n					GuiColorSetForNextWidget( gui, color(208,208,248,255) )\n					GuiText( gui, 0, 0, wrap_key( \"target_dummy_dps\" ) )\n					GuiColorSetForNextWidget( gui, color(126,126,126,255) )\n					GuiText( gui, 0, 0, wrap_key( \"target_dummy_highest_dps\" ) )\n				end, 3, 0, true )\n\n				if not selecting_mortal_to_transform then\n					GuiOptionsAddForNextWidget( gui, GUI_OPTION.DrawSemiTransparent )\n				end\n				if GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/transform_into_target_dummy.png\" ) then\n					sound_button_clicked()\n					selecting_mortal_to_transform = not selecting_mortal_to_transform\n				end\n				GuiTooltip( gui, wrap_key( \"transform_mortal_into_target_dummy\" ),\n					text_get( \"transform_mortal_into_target_dummy_description\", shortcut_texts.transform_mortal_into_dummy )\n				)\n\n				GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/spawn_convenient_wand.png\" )\n				do\n					local left_click,right_click = previous_data( gui )\n					local wand_data = {\n						stats = {\n							shuffle_deck_when_empty = false,\n							actions_per_round = 1,\n							fire_rate_wait = 10,\n							reload_time = 20,\n							mana_max = 100000,\n							mana_charge_speed = 100000,\n							capacity = 26,\n							spread_degrees = 0,\n							speed_multiplier = 1,\n						},\n						sprite = {\n							file = \"data/items_gfx/wands/wand_0821.png\",\n							hotspot = {\n								x = 18.0,\n								y = 0.0,\n							},\n							x = 4,\n							y = 3,\n						},\n					}\n					if left_click then\n						sound_button_clicked()\n						local x, y = get_player_or_camera_position()\n						local wand = EntityLoad( \"data/entities/items/wand_level_01.xml\", x, y )\n						WANDS.initialize_wand( wand, wand_data )\n					elseif right_click and held_wand then\n						sound_button_clicked()\n						WANDS.initialize_wand( held_wand, wand_data, false )\n					end\n				end\n				GuiTooltip( gui, wrap_key( \"spawn_best_wand\" ), wrap_key( \"spawn_best_wand_description\" ) )\n			GuiLayoutEnd( gui )\n\n			if mod_setting_get( \"show_toggle_options\" ) then\n				GuiLayoutBeginHorizontal( gui, horizontal_centered_x(8,4), percent_to_ui_scale_y(2), true )\n					do_flag_toggle_image_button( \"mods/spell_lab_shugged/files/gui/buttons/disable_projectiles.png\", \"disable_casting\" )\n					do_flag_toggle_image_button( \"mods/spell_lab_shugged/files/gui/buttons/disable_toxic_statuses.png\", \"disable_toxic_statuses\", nil, nil, wrap_key( \"disable_toxic_statuses_description\" ) )\n					do_flag_toggle_image_button( \"mods/spell_lab_shugged/files/gui/buttons/invincible.png\", \"invincible\", \"$status_protection_all\" )\n					do_flag_toggle_image_button( \"mods/spell_lab_shugged/files/gui/buttons/disable_polymorphing.png\", \"no_polymorphing\", \"$status_protection_polymorph\" )\n					do_flag_toggle_image_button( \"mods/spell_lab_shugged/files/gui/buttons/no_recoil.png\", \"no_recoil\" )\n\n					if not world_state_unlimited_spells then\n						GuiOptionsAddForNextWidget( gui, GUI_OPTION.DrawSemiTransparent )\n					end\n					if GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/spell_lab_shugged/files/gui/buttons/unlimited_spells.png\" ) then\n						sound_button_clicked()\n						if EntityGetIsAlive( world_state ) then\n							local comp_worldstate = EntityGetFirstComponent( world_state, \"WorldStateComponent\" )\n							ComponentSetValue2( comp_worldstate, \"perk_infinite_spells\", not world_state_unlimited_spells )\n						end\n						if not world_state_unlimited_spells then\n							if not mod_setting_get( \"zero_uses\" ) then\n								GameRegenItemActionsInPlayer( player )\n							end\n							local inventory2 = EntityGetFirstComponent( player, \"Inventory2Component\" )\n							if inventory2 ~= nil then\n								ComponentSetValue2( inventory2, \"mForceRefresh\", true )\n								ComponentSetValue2( inventory2, \"mActualActiveItem\", 0 )\n							end\n						end\n					end\n					GuiTooltip( gui, text_get_translated( world_state_unlimited_spells and \"disable\" or \"enable\" ) .. text_get_translated( \"$perk_unlimited_spells\" ), \"\" )\n\n					local desc = wrap_key( \"creative_mode_flight_description\" )\n					if DebugGetIsDevBuild() then\n						desc = GameTextGetTranslatedOrNot( desc ) .. \"\\n\" .. text_get_translated( \"creative_mode_flight_note_dev_exe\" )\n					end\n					do_flag_toggle_image_button( \"mods/spell_lab_shugged/files/gui/buttons/creative_mode_flight.png\", \"creative_mode_flight\", nil, nil, desc )\n					do_flag_toggle_image_button( \"mods/spell_lab_shugged/files/gui/buttons/better_all_seeing_eye.png\", \"better_all_seeing_eye\", \"$perk_remove_fog_of_war\" )\n				GuiLayoutEnd( gui )\n			end\n\n			do_active_picker_buttons()\n\n			if mod_setting_get( \"damage_info\" ) then\n				dofile( \"mods/spell_lab_shugged/files/gui/damage_info.lua\" )\n			end\n		GuiLayoutEnd( gui )\n\n		do_active_picker_menu()\n\n		if mod_setting_get( \"show_wand_edit_panel\" ) then\n			do_content_wrapped(	function() dofile( \"mods/spell_lab_shugged/files/gui/edit_panel_shown.lua\" ) end, \"edit_panel\" )\n		end\n	else\n		change_keyboard_focus( Focus_PlayerControls )\n	end\nend\n\nprint(\"[spell lab] done setting up GUI\")"
_TWWE_VFS["mods/spell_lab_shugged/files/gui/wand_listener.lua"] = "local function get_all_wands_in_inventory()\n	if not player then return end\n	local children = EntityGetAllChildren( player )\n	if not children then return end\n	for _, child in pairs( children ) do\n		if EntityGetName( child ) == \"inventory_quick\" then\n			return EntityGetAllChildren( child, \"wand\" )\n		end\n	end\nend\n\nlocal wands_to_listen\nlocal wand_listener_type = mod_setting_get( \"wand_listener_type\" )\nif wand_listener_type == \"INV\" then\n	wands_to_listen = get_all_wands_in_inventory()\nelseif wand_listener_type == \"HAND\" then\n	wands_to_listen = { held_wand }\nelseif wand_listener_type == \"PANEL\" then\n	if mod_setting_get( \"show_wand_edit_panel\" ) then\n		wands_to_listen = { held_wand }\n	end\nelse\n	GamePrint( \"Something is very wrong!\" )\n	GamePrintImportant( \"Something is very wrong!\" )\n	print( \"Something is very wrong!\" )\nend\n\nfor _, wand_id in ipairs( wands_to_listen or {} ) do\n	local edit_panel_state = access_edit_panel_state( wand_id )\n	if edit_panel_state.get_force_compact_enabled() then goto continue end\n	local current_state = edit_panel_state.get()\n	local current_permanent_state = edit_panel_state.get_permanent()\n	local new_state_table, new_permanent_table = read_state_table_from_wand( wand_id )\n	local diff = false\n\n	local i = 1\n	local permanent_state_iter_func = state_str_iter_permanent_actions( current_permanent_state )\n	local new_permanent = new_permanent_table[ i ]\n	local pa = permanent_state_iter_func()\n	while new_permanent ~= nil or pa ~= nil do\n		if new_permanent ~= pa then\n			diff = true\n			break\n		end\n		i = i + 1\n		new_permanent = new_permanent_table[ i ]\n		pa = permanent_state_iter_func()\n	end\n\n	if not diff then\n		local j = 1\n		local state_iter_func = state_str_iter_actions( current_state )\n		local new = new_state_table[ j ]\n		local s, a, u = state_iter_func()\n		while new ~= nil or s ~= nil do\n			if new then\n				-- both are just sth like !(a == null ? b == null : a.equals(b))\n				-- or more apparently, if a ~= null then return a ~= b else return b ~= null end\n				if new[2] ~= nil then\n					if new[2] ~= a then\n						diff = true\n						break\n					end\n				elseif a and a ~= \"\" then\n					diff = true\n					break\n				end\n				if new[3] ~= nil then\n					if new[3] ~= tonumber( u ) then\n						diff = true\n						break\n					end\n				else\n					if u and u ~= \"\" then\n						diff = true\n						break\n					end\n				end\n			else\n				if a and a ~= \"\" then\n					diff = true\n					break\n				end\n			end\n			j = j + 1\n			new = new_state_table[ j ]\n			s, a, u = state_iter_func()\n		end\n	end\n\n	if diff then\n		edit_panel_state.set_both( table_to_state_str( new_state_table ), permanent_table_to_state_str( new_permanent_table ), wrap_key( \"operation_read_from_wand\" ) )\n		edit_panel_state.done_sync()\n	end\n\n	::continue::\nend"
_TWWE_VFS["mods/spell_lab_shugged/files/gui/wand_stats.lua"] = "return {\n	{\n		stat = \"shuffle_deck_when_empty\",\n		label = \"$inventory_shuffle\",\n		default = 0, current = 0,\n		min = 0, max = 1,\n		formatter = \" \",\n		value_callback = function( value )\n			if type( value ) == \"boolean\" then\n				if value then\n					value = 1\n				else\n					value = 0\n				end\n			end\n			return math.floor( value + 0.5 )\n		end,\n		text_callback = function( value )\n			return GameTextGetTranslatedOrNot( \"$menu_\" .. ( value == 0 and \"no\" or \"yes\" ) ) end,\n		buttons_precise_mode = {\n			{\n				text = function( value )\n					return \"[\" .. GameTextGetTranslatedOrNot( \"$menu_yes\" ) .. \"]\"\n				end,\n				value = 1,\n			},\n			{\n				text = function( value )\n					return \"[\" .. GameTextGetTranslatedOrNot( \"$menu_no\" ) .. \"]\"\n				end,\n				value = -1,\n			},\n		},\n	},\n	{\n		stat = \"actions_per_round\",\n		label = \"$inventory_actionspercast\",\n		default = 1, current = 1,\n		min = 1, max = 26,\n		formatter = \" \",\n		value_callback = function( value ) return math.floor( value + 0.5 ) end,\n		text_callback = function( value ) return tostring( value ) end,\n		buttons_precise_mode = {\n			{\n				text = \"[1]\",\n				value = 1,\n			},\n			{\n				text = \"[5]\",\n				value = 5,\n			},\n			{\n				text = \"[25]\",\n				value = 25,\n			},\n		},\n	},   \n	{\n		stat = \"fire_rate_wait\",\n		label = \"$inventory_castdelay\",\n		default = 10, current = 10,\n		min = -21, max = 240,\n		formatter = \" \",\n		value_callback = function( value ) return math.floor( value + 0.5 ) end,\n		text_callback = format_time,\n		buttons_precise_mode = {\n			{\n				text = \"[1f]\",\n				value = 1,\n			},\n			{\n				text = \"[5f]\",\n				value = 5,\n			},\n			{\n				text = \"[30f]\",\n				value = 30,\n			},\n		},\n	},\n	{\n		stat = \"reload_time\",\n		label = \"$inventory_rechargetime\",\n		default = 20, current = 20,\n		min = -21, max = 240,\n		formatter = \" \",\n		value_callback = function( value ) return math.floor( value + 0.5 ) end,\n		text_callback = format_time,\n		buttons_precise_mode = {\n			{\n				text = \"[1f]\",\n				value = 1,\n			},\n			{\n				text = \"[5f]\",\n				value = 5,\n			},\n			{\n				text = \"[30f]\",\n				value = 30,\n			},\n		},\n	},\n	{\n		stat = \"mana_max\",\n		label = \"$inventory_manamax\",\n		default = 100, current = 100,\n		min = 0, max = 5000,\n		formatter = \" \",\n		value_callback = function( value ) return math.floor( value + 0.5 ) end,\n		text_callback = function( value ) return tostring( value ) end,\n		buttons_precise_mode = {\n			{\n				text = \"[1]\",\n				value = 1,\n			},\n			{\n				text = \"[10]\",\n				value = 10,\n			},\n			{\n				text = \"[100]\",\n				value = 100,\n			},\n			{\n				text = \"[1000]\",\n				value = 1000,\n			},\n		},\n	},\n	{\n		stat = \"mana_charge_speed\",\n		label = \"$inventory_manachargespeed\",\n		default = 30, current = 30,\n		min = 0, max = 5000,\n		formatter = \" \",\n		value_callback = function( value ) return math.floor( value + 0.5 ) end,\n		text_callback = function( value ) return tostring( value ) end,\n		buttons_precise_mode = {\n			{\n				text = \"[1]\",\n				value = 1,\n			},\n			{\n				text = \"[10]\",\n				value = 10,\n			},\n			{\n				text = \"[100]\",\n				value = 100,\n			},\n			{\n				text = \"[1000]\",\n				value = 1000,\n			},\n		},\n	},\n	{\n		stat = \"capacity\",\n		label = \"$inventory_capacity\",\n		default = 3, current = 3,\n		min = 1, max = 26,\n		formatter = \" \",\n		value_callback = function( value ) return math.floor( value + 0.5 ) end,\n		text_callback = function( value ) return tostring( value ) end,\n		buttons_precise_mode = {\n			{\n				text = \"[1]\",\n				value = 1,\n			},\n			{\n				text = \"[5]\",\n				value = 5,\n			},\n			{\n				text = \"[25]\",\n				value = 25,\n			},\n		},\n	},\n	{\n		stat = \"spread_degrees\",\n		label = \"$inventory_spread\",\n		default = 0, current = 0,\n		min = -30, max = 30,\n		formatter = \" \",\n		value_callback = function( value ) return math.floor( value + 0.5 ) end,\n		text_callback = function( value ) return GameTextGet( \"$inventory_degrees\", math.floor( value * 10 ) / 10 ) end,\n		buttons_precise_mode = {\n			{\n				text = function() return \"[\" .. GameTextGet( \"$inventory_degrees\", 1 ) .. \"]\" end,\n				value = 1,\n			},\n			{\n				text = function() return \"[\" .. GameTextGet( \"$inventory_degrees\", 5 ) .. \"]\" end,\n				value = 5,\n			},\n			{\n				text = function() return \"[\" .. GameTextGet( \"$inventory_degrees\", 30 ) .. \"]\" end,\n				value = 30,\n			},\n		},\n	},\n	{\n		stat = \"speed_multiplier\",\n		label = \"$spell_lab_shugged_speed_multiplier\",\n		default = 1.0, current = 1.0,\n		min = 0.0, max = 2.0,\n		formatter = \" \",\n		value_callback = function( value ) return math.floor( value * 1000 ) / 1000 end,\n		text_callback = function( value ) return ( math.floor( value * 1000 ) / 1000 .. \" x\" ) end,\n		buttons_precise_mode = {\n			{\n				text = \"[0.001 x]\",\n				value = 0.001,\n			},\n			{\n				text = \"[0.01 x]\",\n				value = 0.01,\n			},\n			{\n				text = \"[0.1 x]\",\n				value = 0.1,\n			},\n		},\n	}\n}"
_TWWE_VFS["mods/spell_lab_shugged/files/lib/controls_freezing_utils.lua"] = "function freeze_controls()\n	for _, player in ipairs( EntityGetWithTag( \"player_unit\" ) or {} ) do\n		local controls_disabler = EntityCreateNew()\n		EntityAddTag( controls_disabler, \"spell_lab_shugged_controls_disabler\" )\n		EntityAddTag( controls_disabler, \"spell_lab_shugged_non_toxic_status\" )\n		EntityAddChild( player, controls_disabler )\n		EntityAddComponent2( controls_disabler, \"InheritTransformComponent\" )\n		EntityAddComponent2( controls_disabler, \"GameEffectComponent\", {\n			frames = -1,\n			disable_movement = true,\n			effect = \"FROZEN\",\n		} )\n	end\nend\nfunction unfreeze_controls()\n	for _, controls_disabler in ipairs( EntityGetWithTag( \"spell_lab_shugged_controls_disabler\" ) ) do\n		local effect_comp = EntityGetFirstComponentIncludingDisabled( controls_disabler, \"GameEffectComponent\" )\n		ComponentSetValue2( effect_comp, \"frames\", 1 )\n	end\nend"
_TWWE_VFS["mods/spell_lab_shugged/files/lib/entity_xml_parser.lua"] = "nxml = dofile_once( \"mods/spell_lab_shugged/files/lib/nxml.lua\" )\nfunction parse_entity_xml( filepath )\n	if not filepath or not ModDoesFileExist( filepath ) then return nil end\n	local xml_content = nxml.parse( ModTextFileGetContent( filepath ) )\n	local children_to_add = {}\n	for basefile in xml_content:each_child() do\n		if basefile.name ~= \"Base\" then goto continue end\n		local include_children = basefile.attr.include_children\n		local basefile_content = parse_entity_xml( basefile.attr.file )\n		if not basefile_content then goto continue end\n\n		for child in basefile:each_child() do\n			local child_to_edit\n			for c in basefile_content:each_of( child.name ) do\n				if not c.attr.edited then\n					child_to_edit = c\n					break\n				end\n			end\n			if child_to_edit == nil then\n				print_error( \"base file used incorrectly in file: \" .. basefile.attr.file .. \" name: \" .. child.name .. \" path: \" .. filepath )\n				break\n			end\n\n			for k, v in pairs( child.attr ) do\n				if k == \"_remove_from_base\" and v == \"1\" then\n					child_to_edit.attr.removed = \"1\"\n					goto skip\n				end\n				child_to_edit.attr[k] = v\n			end\n			for object in child:each_child() do\n				local object_to_edit = child_to_edit:first_of( object.name )\n				if object_to_edit then\n					for k, v in pairs( object.attr ) do\n						object_to_edit[k] = v\n					end\n				else\n					table.insert( child_to_edit.children, object )\n				end\n			end\n			::skip::\n			child_to_edit.attr.edited = true\n		end\n		for child in basefile_content:each_child() do\n			if not child.attr.removed and ( child.name ~= \"Entity\" or include_children == \"1\" ) then\n				child.attr.edited = nil\n				table.insert( children_to_add, child )\n			end\n		end\n		::continue::\n	end\n	for _, child in ipairs( children_to_add ) do\n		xml_content:add_child( child )\n	end\n	return xml_content\nend"
_TWWE_VFS["mods/spell_lab_shugged/files/lib/fzy_lua.lua"] = "-- The MIT License (MIT)\n\n-- Copyright (c) 2020 Seth Warn\n\n-- Permission is hereby granted, free of charge, to any person obtaining a copy\n-- of this software and associated documentation files (the \"Software\"), to deal\n-- in the Software without restriction, including without limitation the rights\n-- to use, copy, modify, merge, publish, distribute, sublicense, and/or sell\n-- copies of the Software, and to permit persons to whom the Software is\n-- furnished to do so, subject to the following conditions:\n\n-- The above copyright notice and this permission notice shall be included in\n-- all copies or substantial portions of the Software.\n\n-- THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR\n-- IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,\n-- FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE\n-- AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER\n-- LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,\n-- OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN\n-- THE SOFTWARE.\n\n-- The lua implementation of the fzy string matching algorithm\n\nlocal SCORE_GAP_LEADING = -0.005\nlocal SCORE_GAP_TRAILING = -0.005\nlocal SCORE_GAP_INNER = -0.01\nlocal SCORE_MATCH_CONSECUTIVE = 1.0\nlocal SCORE_MATCH_SLASH = 0.9\nlocal SCORE_MATCH_WORD = 0.8\nlocal SCORE_MATCH_CAPITAL = 0.7\nlocal SCORE_MATCH_DOT = 0.6\nlocal SCORE_MAX = math.huge\nlocal SCORE_MIN = -math.huge\nlocal MATCH_MAX_LENGTH = 1024\n\nlocal fzy = {}\n\n-- Check if `needle` is a subsequence of the `haystack`.\n--\n-- Usually called before `score` or `positions`.\n--\n-- Args:\n--   needle (string)\n--   haystack (string)\n--   case_sensitive (bool, optional): defaults to false\n--\n-- Returns:\n--   bool\nfunction fzy.has_match(needle, haystack, case_sensitive)\n  if not case_sensitive then\n    needle = string.lower(needle)\n    haystack = string.lower(haystack)\n  end\n\n  local j = 1\n  for i = 1, string.len(needle) do\n    j = string.find(haystack, needle:sub(i, i), j, true)\n    if not j then\n      return false\n    else\n      j = j + 1\n    end\n  end\n\n  return true\nend\n\nlocal function is_lower(c)\n  return c:match(\"%l\")\nend\n\nlocal function is_upper(c)\n  return c:match(\"%u\")\nend\n\nlocal function precompute_bonus(haystack)\n  local match_bonus = {}\n\n  local last_char = \"/\"\n  for i = 1, string.len(haystack) do\n    local this_char = haystack:sub(i, i)\n    if last_char == \"/\" or last_char == \"\\\\\" then\n      match_bonus[i] = SCORE_MATCH_SLASH\n    elseif last_char == \"-\" or last_char == \"_\" or last_char == \" \" then\n      match_bonus[i] = SCORE_MATCH_WORD\n    elseif last_char == \".\" then\n      match_bonus[i] = SCORE_MATCH_DOT\n    elseif is_lower(last_char) and is_upper(this_char) then\n      match_bonus[i] = SCORE_MATCH_CAPITAL\n    else\n      match_bonus[i] = 0\n    end\n\n    last_char = this_char\n  end\n\n  return match_bonus\nend\n\nlocal function compute(needle, haystack, D, M, case_sensitive)\n  -- Note that the match bonuses must be computed before the arguments are\n  -- converted to lowercase, since there are bonuses for camelCase.\n  local match_bonus = precompute_bonus(haystack)\n  local n = string.len(needle)\n  local m = string.len(haystack)\n\n  if not case_sensitive then\n    needle = string.lower(needle)\n    haystack = string.lower(haystack)\n  end\n\n  -- Because lua only grants access to chars through substring extraction,\n  -- get all the characters from the haystack once now, to reuse below.\n  local haystack_chars = {}\n  for i = 1, m do\n    haystack_chars[i] = haystack:sub(i, i)\n  end\n\n  for i = 1, n do\n    D[i] = {}\n    M[i] = {}\n\n    local prev_score = SCORE_MIN\n    local gap_score = i == n and SCORE_GAP_TRAILING or SCORE_GAP_INNER\n    local needle_char = needle:sub(i, i)\n\n    for j = 1, m do\n      if needle_char == haystack_chars[j] then\n        local score = SCORE_MIN\n        if i == 1 then\n          score = ((j - 1) * SCORE_GAP_LEADING) + match_bonus[j]\n        elseif j > 1 then\n          local a = M[i - 1][j - 1] + match_bonus[j]\n          local b = D[i - 1][j - 1] + SCORE_MATCH_CONSECUTIVE\n          score = math.max(a, b)\n        end\n        D[i][j] = score\n        prev_score = math.max(score, prev_score + gap_score)\n        M[i][j] = prev_score\n      else\n        D[i][j] = SCORE_MIN\n        prev_score = prev_score + gap_score\n        M[i][j] = prev_score\n      end\n    end\n  end\nend\n\n-- Compute a matching score.\n--\n-- Args:\n--   needle (string): must be a subequence of `haystack`, or the result is\n--     undefined.\n--   haystack (string)\n--   case_sensitive (bool, optional): defaults to false\n--\n-- Returns:\n--   number: higher scores indicate better matches. See also `get_score_min`\n--     and `get_score_max`.\nfunction fzy.score(needle, haystack, case_sensitive)\n  local n = string.len(needle)\n  local m = string.len(haystack)\n\n  if n == 0 or m == 0 or m > MATCH_MAX_LENGTH or n > m then\n    return SCORE_MIN\n  elseif n == m then\n    return SCORE_MAX\n  else\n    local D = {}\n    local M = {}\n    compute(needle, haystack, D, M, case_sensitive)\n    return M[n][m]\n  end\nend\n\n-- Compute the locations where fzy matches a string.\n--\n-- Determine where each character of the `needle` is matched to the `haystack`\n-- in the optimal match.\n--\n-- Args:\n--   needle (string): must be a subequence of `haystack`, or the result is\n--     undefined.\n--   haystack (string)\n--   case_sensitive (bool, optional): defaults to false\n--\n-- Returns:\n--   {int,...}: indices, where `indices[n]` is the location of the `n`th\n--     character of `needle` in `haystack`.\n--   number: the same matching score returned by `score`\nfunction fzy.positions(needle, haystack, case_sensitive)\n  local n = string.len(needle)\n  local m = string.len(haystack)\n\n  if n == 0 or m == 0 or m > MATCH_MAX_LENGTH or n > m then\n    return {}, SCORE_MIN\n  elseif n == m then\n    local consecutive = {}\n    for i = 1, n do\n      consecutive[i] = i\n    end\n    return consecutive, SCORE_MAX\n  end\n\n  local D = {}\n  local M = {}\n  compute(needle, haystack, D, M, case_sensitive)\n\n  local positions = {}\n  local match_required = false\n  local j = m\n  for i = n, 1, -1 do\n    while j >= 1 do\n      if D[i][j] ~= SCORE_MIN and (match_required or D[i][j] == M[i][j]) then\n        match_required = (i ~= 1) and (j ~= 1) and (\n        M[i][j] == D[i - 1][j - 1] + SCORE_MATCH_CONSECUTIVE)\n        positions[i] = j\n        j = j - 1\n        break\n      else\n        j = j - 1\n      end\n    end\n  end\n\n  return positions, M[n][m]\nend\n\n-- Apply `has_match` and `positions` to an array of haystacks.\n--\n-- Args:\n--   needle (string)\n--   haystack ({string, ...})\n--   case_sensitive (bool, optional): defaults to false\n--\n-- Returns:\n--   {{idx, positions, score}, ...}: an array with one entry per matching line\n--     in `haystacks`, each entry giving the index of the line in `haystacks`\n--     as well as the equivalent to the return value of `positions` for that\n--     line.\nfunction fzy.filter(needle, haystacks, case_sensitive)\n  local result = {}\n\n  for i, line in ipairs(haystacks) do\n    if fzy.has_match(needle, line, case_sensitive) then\n      local p, s = fzy.positions(needle, line, case_sensitive)\n      table.insert(result, {i, p, s})\n    end\n  end\n\n  return result\nend\n\n-- The lowest value returned by `score`.\n--\n-- In two special cases:\n--  - an empty `needle`, or\n--  - a `needle` or `haystack` larger than than `get_max_length`,\n-- the `score` function will return this exact value, which can be used as a\n-- sentinel. This is the lowest possible score.\nfunction fzy.get_score_min()\n  return SCORE_MIN\nend\n\n-- The score returned for exact matches. This is the highest possible score.\nfunction fzy.get_score_max()\n  return SCORE_MAX\nend\n\n-- The maximum size for which `fzy` will evaluate scores.\nfunction fzy.get_max_length()\n  return MATCH_MAX_LENGTH\nend\n\n-- The minimum score returned for normal matches.\n--\n-- For matches that don't return `get_score_min`, their score will be greater\n-- than than this value.\nfunction fzy.get_score_floor()\n  return MATCH_MAX_LENGTH * SCORE_GAP_INNER\nend\n\n-- The maximum score for non-exact matches.\n--\n-- For matches that don't return `get_score_max`, their score will be less than\n-- this value.\nfunction fzy.get_score_ceiling()\n  return MATCH_MAX_LENGTH * SCORE_MATCH_CONSECUTIVE\nend\n\n-- The name of the currently-running implmenetation, \"lua\" or \"native\".\nfunction fzy.get_implementation_name()\n  return \"lua\"\nend\n\nreturn fzy\n"
_TWWE_VFS["mods/spell_lab_shugged/files/lib/helper.lua"] = "local mod_settings_prefix = \"spell_lab_shugged.\"\n\nfunction mod_setting_get( key )\n	return ModSettingGet( mod_settings_prefix .. key )\nend\nfunction mod_setting_set( key, value )\n	return ModSettingSet( mod_settings_prefix .. key, value )\nend\nfunction wrap_setting_key( key )\n	return mod_settings_prefix .. key\nend\n\nlocal transl_key_prefix = \"$spell_lab_shugged_\"\n\nfunction wrap_key( key )\n	if string.sub( key, 1, 1 ) == \"$\" then\n		return key\n	end\n	return transl_key_prefix .. key\nend\nfunction text_get_translated( key )\n	return GameTextGetTranslatedOrNot( wrap_key( key ) )\nend\nfunction text_get( key, ... )\n	return GameTextGet( wrap_key( key ), ... )\nend\n\ndo\n	local function c( h )\n		return ( h + 1 ) / 256\n	end\n	function color( r, g, b, a )\n		return c( r ), c( g ), c( b ), c( a )\n	end\nend\n\nfunction maxn( t )\n	local result = table.maxn( t )\n	if result == 0 and not t[0] then return -1 end\n	return result\nend\n\nlocal function thousands_separator( value_text )\n	local formatted = value_text\n	local num_separators = 0\n	while true do\n		formatted, k = string.gsub(formatted, \"^(-?%d+)(%d%d%d)\", '%1,%2')\n		if k == 0 then\n			break\n		end\n	end\n	return formatted\nend\n\nlocal function ten_thousands_separator( value_text )\n	local formatted = value_text\n	local num_separators = 0\n	while true do\n		formatted, k = string.gsub(formatted, \"^(-?%d+)(%d%d%d%d)\", '%1,%2')\n		if k == 0 then\n			break\n		end\n	end\n	return formatted\nend\n\nfunction word_wrap( str, wrap_size )\n	if GameTextGetTranslatedOrNot( \"$current_language\" ) ~= \"English\" then\n		return str\n	end\n	if wrap_size == nil then wrap_size = 60 end\n	local last_space_index = 1\n	local last_wrap_index = 0\n	for i=1,#str do\n		if str:sub(i,i) == \" \" then\n			last_space_index = i\n		end\n		if str:sub(i,i) == \"\\n\" then\n			last_space_index = i\n			last_wrap_index = i\n		end\n		if i - last_wrap_index > wrap_size then\n			str = str:sub(1,last_space_index-1) .. \"\\n\" .. str:sub(last_space_index + 1)\n			last_wrap_index = i\n		end\n	end\n	return str\nend\n\nlocal not_a_gui = GuiCreate()\nfunction center_text( text )\n	return GuiGetTextDimensions( not_a_gui, text, 1, 0, \"mods/spell_lab_shugged/files/font/font_small_numbers.xml\", true ) / 2\nend\n\nzh_cn_languages = {\n	[\"简体中文\"] = true,\n	[\"喵体中文\"] = true,\n	[\"汪体中文\"] = true,\n	[\"完全汉化\"] = true,\n}\n\nfunction separator( text )\n	return ( zh_cn_languages[ GameTextGetTranslatedOrNot( \"$current_language\" ) ]\n	and ten_thousands_separator or thousands_separator )( text )\nend\n\nFORMAT = {\n	Floor = 0,\n	Round = 1,\n	Ceiling = 2\n}\n\nlocal inf = 1 / 0\nlocal threshold = 10 ^ 10\nfunction format_damage( damage, never_use_scientific_notation, result_inf )\n	if damage == inf then\n		return result_inf or \"∞\"\n	end\n	damage = damage * 25\n	if not never_use_scientific_notation and ( damage > threshold or -damage > threshold ) then\n		return string.format( \"%.10e\", damage )\n	end\n	return separator( string.format( \"%.2f\", damage ) )\nend\n\nfunction format_value( value, decimals, show_sign, format )\n	local text = \"\"\n	if value ~= nil then\n		if show_sign and value > 0 then\n			text = \"+\"\n		end\n		local rounder = math.floor\n		local value_offset = 0\n		if format == FORMAT.Ceiling then\n			rounder = math.ceil\n		elseif format == FORMAT.Round then\n			value_offset = 0.5\n		end\n		local power = math.pow( 10, decimals )\n		text = text .. tostring( rounder( value * power + value_offset ) / power )\n	else\n		return \"missing\"\n	end\n	return text\nend\n\nfunction format_time( time, digits )\n	digits = digits or 2\n	return format_value( time / 60, digits, true, FORMAT.Round ) .. \" s (\" .. GameTextGet( wrap_key( \"frames\" ), format_value( time, 0 ) ) .. \")\"\nend\n\nfunction format_range( min, max )\n	if not min or not max then return nil end\n	if min ~= max then\n		return min .. \" - \" .. max\n	else\n		return tostring( min )\n	end\nend\n\nfunction get_player_or_camera_position()\n	if player then\n		x, y = EntityGetTransform( player )\n		return x, y\n	end\n	return GameGetCameraPos()\nend\n\nfunction get_held_wand()\n	if not player then return end\n	local wands\n	for _, child_id in ipairs( EntityGetAllChildren( player ) or {} ) do\n		if EntityGetName( child_id ) == \"inventory_quick\" then\n			wands = EntityGetAllChildren( child_id, \"wand\" )\n			break\n		end\n	end\n	if not wands or #wands == 0 then return end\n	local inv2 = EntityGetFirstComponent( player, \"Inventory2Component\" )\n	local active_item = ComponentGetValue2( inv2, \"mActiveItem\" )\n	for _, wand_id in pairs( wands ) do\n		if wand_id == active_item then\n			return wand_id\n		end\n	end\nend\n\nfunction force_refresh_held_wands()\n	if not player then return end\n	local inv2_comp = EntityGetFirstComponent( player, \"Inventory2Component\" )\n	if not inv2_comp then return end\n	ComponentSetValue2( inv2_comp, \"mForceRefresh\", true )\n	ComponentSetValue2( inv2_comp, \"mActualActiveItem\", 0 )\n	ComponentSetValue2( inv2_comp, \"mDontLogNextItemEquip\", true )\nend\nfunction clear_held_wand_wait()\n	if not held_wand then return false end\n	local ab_comp = EntityGetFirstComponentIncludingDisabled( held_wand, \"AbilityComponent\" )\n	if not ab_comp then return false end\n	ComponentSetValue2( ab_comp, \"mReloadFramesLeft\", 0 )\n	ComponentSetValue2( ab_comp, \"mNextFrameUsable\", now )\n	ComponentSetValue2( ab_comp, \"mReloadNextFrameUsable\", now )\n	return true\nend\nfunction block_upcoming_wand_shooting()\n	if not held_wand then return end\n	local ab_comp = EntityGetFirstComponentIncludingDisabled( held_wand, \"AbilityComponent\" )\n	if not ab_comp then return end\n	ComponentSetValue2( ab_comp, \"mReloadFramesLeft\", math.max( 10, ComponentGetValue2( ab_comp, \"mReloadFramesLeft\" ) ) )\n	ComponentSetValue2( ab_comp, \"mNextFrameUsable\", math.max( now + 10, ComponentGetValue2( ab_comp, \"mNextFrameUsable\" ) ) )\n	ComponentSetValue2( ab_comp, \"mReloadNextFrameUsable\", math.max( now + 10, ComponentGetValue2( ab_comp, \"mReloadNextFrameUsable\" ) ) )\nend\n\nfunction is_action_unlocked( action )\n	if action then\n		return not action.spawn_requires_flag or HasFlagPersistent( action.spawn_requires_flag )\n	end\n	return false\nend"
_TWWE_VFS["mods/spell_lab_shugged/files/lib/keycodes_wrapped.lua"] = "local f = loadfile( \"data/scripts/debug/keycodes.lua\" )\nlocal raw = {}\nsetfenv( f, raw )()\n\nlocal by_type = { Mouse = {}, Keyboard = {}, Joystick = {} }\nfor k, v in pairs( raw ) do\n	if k:find \"^Mouse_\" then\n		by_type.Mouse[ k ] = v\n	elseif k:find \"^Key_\" then\n		by_type.Keyboard[ k ] = v\n	elseif k:find \"^JOY_BUTTON_\" then\n		by_type.Joystick[ k ] = v\n	end\nend\n\nreturn { raw, by_type }"
_TWWE_VFS["mods/spell_lab_shugged/files/lib/nxml.lua"] = "---@alias int integer\n---@alias bool boolean\n---@alias str string\n---@alias token_type \"string\" | \"<\" | \">\" | \"/\" | \"=\"\n---@alias error_type \"missing_attribute_value\" | \"missing_element_close\" | \"missing_equals_sign\" | \"missing_element_name\" | \"missing_tag_open\" | \"mismatched_closing_tag\" | \"missing_token\" | \"missing_element\"\n---@alias error_fn fun(type: error_type, msg: str)\n\n---@class (exact) token\n---@field value string?\n---@field type token_type\n\n---@class (exact) error\n---@field type error_type\n---@field msg str\n---@field row int\n---@field col int\n\n---@class (exact) tokenizer\n---@field data str\n---@field cur_idx int\n---@field cur_row int\n---@field cur_col int\n---@field prev_row int\n---@field prev_col int\n---@field len int\n\n---@class (exact) parser\n---@field tok tokenizer_blob\n---@field errors error[]\n---@field error_reporter error_fn\n\n---@alias parser_blob parser_funcs | parser\n---@alias tokenizer_blob tokenizer_funcs | tokenizer\n---@alias element_blob element_funcs | element\n\n---@class (exact) element\n---@field content str[]?\n---@field children element_blob[]\n---@field attr table<string, string>\n---@field name str\n---@field errors error[]\n\nlocal ffi = nil\nif require then\n	pcall(function()\n		ffi = require(\"ffi\")\n	end)\nend\n\n---@param str str\n---@param start_idx int\n---@param len int\n---@return str\nlocal function str_sub(str, start_idx, len)\n	return str:sub(start_idx + 1, start_idx + len)\nend\n\n---@param str str\n---@param idx int\n---@return integer\nlocal function str_index(str, idx)\n	return string.byte(str:sub(idx + 1, idx + 1))\nend\n\n--[[\n * The following is a Lua port of the NXML parser:\n * https://github.com/xwitchproject/nxml\n *\n * The NXML Parser is heavily based on code from poro\n * https://github.com/gummikana/poro\n *\n * The poro project is licensed under the Zlib license:\n *\n * --------------------------------------------------------------------------\n * Copyright (c) 2010-2019 Petri Purho, Dennis Belfrage\n * Contributors: Martin Jonasson, Olli Harjola\n * This software is provided 'as-is', without any express or implied\n * warranty.  In no event will the authors be held liable for any damages\n * arising from the use of this software.\n * Permission is granted to anyone to use this software for any purpose,\n * including commercial applications, and to alter it and redistribute it\n * freely, subject to the following restrictions:\n * 1. The origin of this software must not be misrepresented; you must not\n *    claim that you wrote the original software. If you use this software\n *    in a product, an acknowledgment in the product documentation would be\n *    appreciated but is not required.\n * 2. Altered source versions must be plainly marked as such, and must not be\n *    misrepresented as being the original software.\n * 3. This notice may not be removed or altered from any source distribution.\n * --------------------------------------------------------------------------\n]]\n\n---@class nxml\nlocal nxml = {}\n\n---@class tokenizer_funcs\nlocal TOKENIZER_FUNCS = {}\nlocal TOKENIZER_MT = {\n	__index = TOKENIZER_FUNCS,\n	__tostring = function(self) return \"natif.nxml.tokenizer\" end\n}\n\n---@param cstring str\n---@param len int\n---@return tokenizer_blob\nlocal function new_tokenizer(cstring, len)\n	---@type tokenizer\n	local tokenizer = {\n		data = cstring,\n		cur_idx = 0,\n		cur_row = 1,\n		cur_col = 1,\n		prev_row = 1,\n		prev_col = 1,\n		len = len\n	}\n	return setmetatable(tokenizer, TOKENIZER_MT)\nend\n\n---@type table<int, bool>\nlocal ws = {\n	[string.byte(\" \")] = true,\n	[string.byte(\"\\t\")] = true,\n	[string.byte(\"\\n\")] = true,\n	[string.byte(\"\\r\")] = true\n}\n\n---@param char int\n---@return bool\nfunction TOKENIZER_FUNCS:is_whitespace(char)\n	local n = tonumber(char)\n	return ws[n] or false\nend\n\n---@type table<int, bool>\nlocal punct = {\n	[string.byte(\"<\")] = true,\n	[string.byte(\">\")] = true,\n	[string.byte(\"=\")] = true,\n	[string.byte(\"/\")] = true,\n}\n\n---@param char int\n---@return bool\nfunction TOKENIZER_FUNCS:is_whitespace_or_punctuation(char)\n	local n = tonumber(char)\n	--- We can disable here because is_whitespace(!int) -> false\n	---@diagnostic disable-next-line: param-type-mismatch\n	return self:is_whitespace(n) or punct[n] or false\nend\n\n---@param n int? 1\nfunction TOKENIZER_FUNCS:move(n)\n	---@cast self tokenizer_blob\n	n = n or 1\n	local prev_idx = self.cur_idx\n	self.cur_idx = self.cur_idx + n\n	if self.cur_idx >= self.len then\n		self.cur_idx = self.len\n		return\n	end\n	for i = prev_idx, self.cur_idx - 1 do\n		if str_index(self.data, i) == string.byte(\"\\n\") then\n			self.cur_row = self.cur_row + 1\n			self.cur_col = 1\n		else\n			self.cur_col = self.cur_col + 1\n		end\n	end\nend\n\n---@param n int? 1\n---@return int\nfunction TOKENIZER_FUNCS:peek(n)\n	---@cast self tokenizer_blob\n	n = n or 1\n	local idx = self.cur_idx + n\n	if idx >= self.len then return 0 end\n\n	return str_index(self.data, idx)\nend\n\n---@param str str\n---@return boolean\nfunction TOKENIZER_FUNCS:match_string(str)\n	local len = #str\n\n	for i = 0, len - 1 do\n		if self:peek(i) ~= str_index(str, i) then return false end\n	end\n	return true\nend\n\n---@return bool\nfunction TOKENIZER_FUNCS:eof()\n	---@cast self tokenizer_blob\n	return self.cur_idx >= self.len\nend\n\n---@return int\nfunction TOKENIZER_FUNCS:cur_char()\n	---@cast self tokenizer_blob\n	if self:eof() then return 0 end\n	return str_index(self.data, self.cur_idx)\nend\n\nfunction TOKENIZER_FUNCS:skip_whitespace()\n	while not self:eof() do\n		if self:is_whitespace(self:cur_char()) then\n			self:move()\n		elseif self:match_string(\"<!--\") then\n			self:move(4)\n			while not self:eof() and not self:match_string(\"-->\") do\n				self:move()\n			end\n\n			if self:match_string(\"-->\") then\n				self:move(3)\n			end\n		elseif self:cur_char() == string.byte(\"<\") and self:peek(1) == string.byte(\"!\") then\n			self:move(2)\n			while not self:eof() and self:cur_char() ~= string.byte(\">\") do\n				self:move()\n			end\n			if self:cur_char() == string.byte(\">\") then\n				self:move()\n			end\n		elseif self:match_string(\"<?\") then\n			self:move(2)\n			while not self:eof() and not self:match_string(\"?>\") do\n				self:move()\n			end\n			if self:match_string(\"?>\") then\n				self:move(2)\n			end\n		else\n			break\n		end\n	end\nend\n\n---@return str\nfunction TOKENIZER_FUNCS:read_quoted_string()\n	---@cast self tokenizer_blob\n	local start_idx = self.cur_idx\n	local len = 0\n\n	while not self:eof() and self:cur_char() ~= string.byte(\"\\\"\") do\n		len = len + 1\n		self:move()\n	end\n\n	self:move() -- skip \"\n	return str_sub(self.data, start_idx, len)\nend\n\n---@return str\nfunction TOKENIZER_FUNCS:read_unquoted_string()\n	---@cast self tokenizer_blob\n	local start_idx = self.cur_idx - 1 -- first char is move()d\n	local len = 1\n\n	while not self:eof() and not self:is_whitespace_or_punctuation(self:cur_char()) do\n		len = len + 1\n		self:move()\n	end\n\n	return str_sub(self.data, start_idx, len)\nend\n\nlocal C_NULL = 0\nlocal C_LT = string.byte(\"<\")\nlocal C_GT = string.byte(\">\")\nlocal C_SLASH = string.byte(\"/\")\nlocal C_EQ = string.byte(\"=\")\nlocal C_QUOTE = string.byte(\"\\\"\")\n\n---@return token?\nfunction TOKENIZER_FUNCS:next_token()\n	self:skip_whitespace()\n\n	self.prev_row = self.cur_row\n	self.prev_col = self.cur_col\n\n	if self:eof() then return nil end\n\n	local c = self:cur_char()\n	self:move()\n\n	if c == C_NULL then\n		return nil\n	elseif c == C_LT then\n		---@type token\n		local v = { type = \"<\" }\n		return v\n	elseif c == C_GT then\n		---@type token\n		local v = { type = \">\" }\n		return v\n	elseif c == C_SLASH then\n		---@type token\n		local v = { type = \"/\" }\n		return v\n	elseif c == C_EQ then\n		---@type token\n		local v = { type = \"=\" }\n		return v\n	elseif c == C_QUOTE then\n		---@type token\n		local v = { type = \"string\", value = self:read_quoted_string() }\n		return v\n	else\n		---@type token\n		local v = { type = \"string\", value = self:read_unquoted_string() }\n		return v\n	end\nend\n\n---@class parser_funcs\nlocal PARSER_FUNCS = {}\nlocal PARSER_MT = {\n	__index = PARSER_FUNCS,\n	__tostring = function(self) return \"natif.nxml.parser\" end\n}\n\n---@param tokenizer tokenizer_blob\n---@param error_reporter fun(type, msg)?\n---@return parser | parser_funcs parser\nlocal function new_parser(tokenizer, error_reporter)\n	---@type parser\n	local parser = {\n		tok = tokenizer,\n		errors = {},\n		error_reporter = error_reporter or function(type, msg) print(\"parser error: [\" .. type .. \"] \" .. msg) end\n	}\n	return setmetatable(parser, PARSER_MT)\nend\n\n---@class element_funcs\nlocal XML_ELEMENT_FUNCS = {}\nlocal XML_ELEMENT_MT = {\n	__index = XML_ELEMENT_FUNCS,\n	__tostring = function(self)\n		return nxml.tostring(self, false)\n	end,\n}\n\n---@param type error_type\n---@param msg str\nfunction PARSER_FUNCS:report_error(type, msg)\n	---@cast self parser_blob\n	self.error_reporter(type, msg)\n	---@type error\n	local error = { type = type, msg = msg, row = self.tok.prev_row, col = self.tok.prev_col }\n	table.insert(self.errors, error)\nend\n\n---@param attr_table table<str, str>\n---@param name str\nfunction PARSER_FUNCS:parse_attr(attr_table, name)\n	---@cast self parser_blob\n	local tok = self.tok:next_token()\n	if not tok then\n		self:report_error(\"missing_token\", string.format(\"parsing attribute '%s' - did not find a token\", name))\n		return\n	end\n	if tok.type == \"=\" then\n		tok = self.tok:next_token()\n\n		if not tok then\n			self:report_error(\"missing_token\", string.format(\"parsing attribute '%s' - did not find a token\", name))\n			return\n		end\n\n		if tok.type == \"string\" then\n			attr_table[name] = tok.value\n		else\n			self:report_error(\"missing_attribute_value\",\n				string.format(\"parsing attribute '%s' - expected a string after =, but did not find one\", name))\n		end\n	else\n		self:report_error(\"missing_equals_sign\",\n			string.format(\"parsing attribute '%s' - did not find equals sign after attribute name\", name))\n	end\nend\n\n---@param skip_opening_tag bool\n---@return element_blob?\nfunction PARSER_FUNCS:parse_element(skip_opening_tag)\n	---@cast self parser_blob\n	local tok\n	if not skip_opening_tag then\n		tok = self.tok:next_token()\n		if not tok then\n			self:report_error(\"missing_token\", \"parsing element - did not find a token\")\n			return\n		end\n		if tok.type ~= \"<\" then\n			self:report_error(\"missing_tag_open\", \"couldn't find a '<' to start parsing with\")\n		end\n	end\n\n	tok = self.tok:next_token()\n	if not tok then\n		self:report_error(\"missing_token\", \"parsing element - did not find a token\")\n		return\n	end\n	if tok.type ~= \"string\" then\n		self:report_error(\"missing_element_name\", \"expected an element name after '<'\")\n	end\n\n	local elem_name = tok.value\n	if not elem_name then\n		self:report_error(\"missing_attribute_value\", \"parse element element missing name\")\n		return\n	end\n	local elem = nxml.new_element(elem_name)\n	local content_idx = 0\n\n	local self_closing = false\n\n	while true do\n		tok = self.tok:next_token()\n\n		if tok == nil then\n			return elem\n		elseif tok.type == \"/\" then\n			if self.tok:cur_char() == C_GT then\n				self.tok:move()\n				self_closing = true\n			end\n			break\n		elseif tok.type == \">\" then\n			break\n		elseif tok.type == \"string\" then\n			self:parse_attr(elem.attr, tok.value)\n		end\n	end\n\n	if self_closing then return elem end\n\n	while true do\n		tok = self.tok:next_token()\n\n		if tok == nil then\n			return elem\n		elseif tok.type == \"<\" then\n			if self.tok:cur_char() == C_SLASH then\n				self.tok:move()\n\n				local end_name = self.tok:next_token()\n				if not end_name then\n					self:report_error(\"missing_token\",\n						string.format(\"parsing element '%s' - did not find a token\", elem_name))\n					return\n				end\n				if end_name.type == \"string\" and end_name.value == elem_name then\n					local close_greater = self.tok:next_token()\n					if not close_greater then\n						self:report_error(\"missing_token\",\n							string.format(\"parsing element '%s' - did not find a token\", elem_name))\n						return\n					end\n\n					if close_greater.type == \">\" then\n						return elem\n					else\n						self:report_error(\"missing_element_close\",\n							string.format(\"no closing '>' found for element '%s'\", elem_name))\n					end\n				else\n					self:report_error(\"mismatched_closing_tag\",\n						string.format(\"closing element is in wrong order - expected '</%s>', but instead got '%s'\",\n							elem_name, tostring(end_name.value)))\n				end\n				return elem\n			else\n				local child = self:parse_element(true)\n				table.insert(elem.children, child)\n			end\n		else\n			if not elem.content then\n				elem.content = {}\n			end\n\n			content_idx = content_idx + 1\n			elem.content[content_idx] = tok.value or tok.type\n		end\n	end\nend\n\n---@return element_blob[]\nfunction PARSER_FUNCS:parse_elements()\n	---@cast self parser_blob\n	local tok = self.tok:next_token()\n	---@type element_blob[]\n	local elems = {}\n	local elems_i = 1\n\n	while tok and tok.type == \"<\" do\n		local next_element = self:parse_element(true)\n		if not next_element then\n			self.error_reporter(\"missing_element\", \"parse_element returned nil while parsing elements\")\n			return elems\n		end\n		elems[elems_i] = next_element\n		elems_i = elems_i + 1\n\n		tok = self.tok:next_token()\n	end\n\n	return elems\nend\n\n---@param str str\n---@return bool\nlocal function is_punctuation(str)\n	return str == \"/\" or str == \"<\" or str == \">\" or str == \"=\"\nend\n\n---@return str\nfunction XML_ELEMENT_FUNCS:text()\n	---@cast self element_blob\n	if self.content == nil then return \"\" end\n	local content_count = #self.content\n	if content_count == 0 then return \"\" end\n\n	local text = self.content[1]\n	for i = 2, content_count do\n		local elem = self.content[i]\n		local prev = self.content[i - 1]\n\n		if is_punctuation(elem) or is_punctuation(prev) then\n			text = text .. elem\n		else\n			text = text .. \" \" .. elem\n		end\n	end\n\n	return text\nend\n\n---@param child element_blob\nfunction XML_ELEMENT_FUNCS:add_child(child)\n	self.children[#self.children + 1] = child\nend\n\n---@param children element_blob[]\nfunction XML_ELEMENT_FUNCS:add_children(children)\n	local children_i = #self.children + 1\n	for i = 1, #children do\n		self.children[children_i] = children[i]\n		children_i = children_i + 1\n	end\nend\n\n---@param child element_blob\nfunction XML_ELEMENT_FUNCS:remove_child(child)\n	for i = 1, #self.children do\n		if self.children[i] == child then\n			table.remove(self.children, i)\n			break\n		end\n	end\nend\n\n---@param index int\nfunction XML_ELEMENT_FUNCS:remove_child_at(index)\n	table.remove(self.children, index)\nend\n\nfunction XML_ELEMENT_FUNCS:clear_children()\n	---@cast self element_blob\n	self.children = {}\nend\n\nfunction XML_ELEMENT_FUNCS:clear_attrs()\n	self.attr = {}\nend\n\n---@param element_name str\n---@return element_blob?\nfunction XML_ELEMENT_FUNCS:first_of(element_name)\n	local i = 0\n	local n = #self.children\n\n	while i < n do\n		i = i + 1\n		local c = self.children[i]\n\n		if c.name == element_name then return c end\n	end\n\n	return nil\nend\n\n---@param element_name str\n---@return fun(): element_blob?\nfunction XML_ELEMENT_FUNCS:each_of(element_name)\n	local i = 1\n	local n = #self.children\n\n	return function()\n		while i <= n do\n			local child = self.children[i]\n			i = i + 1\n			if child.name == element_name then\n				return child\n			end\n		end\n	end\nend\n\n---@param element_name str\n---@return element_blob[]\nfunction XML_ELEMENT_FUNCS:all_of(element_name)\n	local table = {}\n	local i = 1\n	for elem in self:each_of(element_name) do\n		table[i] = elem\n		i = i + 1\n	end\n	return table\nend\n\n---@return fun(): element_blob\nfunction XML_ELEMENT_FUNCS:each_child()\n	local i = 0\n	local n = #self.children\n\n	return function()\n		while i < n do\n			i = i + 1\n			return self.children[i]\n		end\n	end\nend\n\n---@param data str\n---@return element_blob\nfunction nxml.parse(data)\n	local data_len = #data\n	local tok = new_tokenizer(data, data_len)\n	local parser = new_parser(tok)\n\n	local elem = parser:parse_element(false)\n\n	if not elem or (elem.errors and #elem.errors > 0) then\n		error(\"parser encountered errors\")\n	end\n\n	return elem\nend\n\n---@param data str\n---@return element_blob[]\nfunction nxml.parse_many(data)\n	local data_len = #data\n	local tok = new_tokenizer(data, data_len)\n	local parser = new_parser(tok)\n\n	local elems = parser:parse_elements()\n\n	for i = 1, #elems do\n		local elem = elems[i]\n\n		if elem.errors and #elem.errors > 0 then\n			error(\"parser encountered errors\")\n		end\n	end\n\n	return elems\nend\n\n---@param name str\n---@param attrs table<str, str>? {}\n---@return element_blob\nfunction nxml.new_element(name, attrs)\n	---@type element\n	local element = {\n		name = name,\n		attr = attrs or {},\n		children = {},\n		errors = {},\n		content = nil\n	}\n	return setmetatable(element, XML_ELEMENT_MT)\nend\n\n---@param value str | bool\n---@return str\nlocal function attr_value_to_str(value)\n	local t = type(value)\n	if t == \"string\" then return value end\n	if t == \"boolean\" then return value and \"1\" or \"0\" end\n\n	return tostring(value)\nend\n\n---@param elem element_blob\n---@param packed bool\n---@param indent_char str? \\t\n---@param cur_indent str? \"\"\n---@return str\nfunction nxml.tostring(elem, packed, indent_char, cur_indent)\n	indent_char = indent_char or \"\\t\"\n	cur_indent = cur_indent or \"\"\n	local s = \"<\" .. elem.name\n	local self_closing = #elem.children == 0 and (not elem.content or #elem.content == 0)\n\n	for k, v in pairs(elem.attr) do\n		s = s .. \" \" .. k .. \"=\\\"\" .. attr_value_to_str(v) .. \"\\\"\"\n	end\n\n	if self_closing then\n		s = s .. \" />\"\n		return s\n	end\n\n	s = s .. \">\"\n\n	local deeper_indent = cur_indent .. indent_char\n\n	if elem.content and #elem.content ~= 0 then\n		if not packed then s = s .. \"\\n\" .. deeper_indent end\n		s = s .. elem:text()\n	end\n\n	if not packed then s = s .. \"\\n\" end\n\n	for i, v in ipairs(elem.children) do\n		if not packed then s = s .. deeper_indent end\n		s = s .. nxml.tostring(v, packed, indent_char, deeper_indent)\n		if not packed then s = s .. \"\\n\" end\n	end\n\n	s = s .. cur_indent .. \"</\" .. elem.name .. \">\"\n\n	return s\nend\n\nreturn nxml\n"
_TWWE_VFS["mods/spell_lab_shugged/files/lib/shortcut_check.lua"] = "local shortcut_check = {}\n\nlocal cache = {}\n\nlocal xor = function( a, b ) return ( a and not b ) or ( not a and b ) end\n\nfunction shortcut_check.check_input( keyboard_input, shortcut, left_click, right_click, dont_cache )\n	if #shortcut == 0 then return false end\n	local inverted_shortcut = cache[ shortcut ]\n	if inverted_shortcut == nil then\n		inverted_shortcut = {}\n		for _, keyname in ipairs( shortcut ) do\n			inverted_shortcut[ keyname ] = true\n		end\n		if not dont_cache then\n			cache[ shortcut ] = inverted_shortcut\n		end\n	end\n\n	for keyname, status in pairs( keyboard_input ) do\n		if shortcut_used_keys == nil or shortcut_used_keys[ keyname ] then\n			if xor( status, inverted_shortcut[ keyname ] ) then return false end\n		end\n	end\n	if left_click ~= nil or right_click ~= nil then\n		if xor( left_click, inverted_shortcut.Mouse_left ) then return false end\n		if xor( right_click, inverted_shortcut.Mouse_right ) then return false end\n	end\n	return true\nend\n\nfunction shortcut_check.check( ... )\n	return shortcut_check.check_input( keyboard_input_holding, ... )\nend\n\nreturn shortcut_check"
_TWWE_VFS["mods/spell_lab_shugged/files/lib/shortcut_setting.lua"] = "local smallfolk = dofile_once( \"mods/spell_lab_shugged/files/lib/smallfolk.lua\" )\ndofile_once( \"mods/spell_lab_shugged/files/lib/shortcut_tostring.lua\" )\ndofile_once( \"mods/spell_lab_shugged/files/gui/keyboard_listener.lua\" )\nlocal KEYCODES_RAW = dofile_once( \"mods/spell_lab_shugged/files/lib/keycodes_wrapped.lua\" )[1]\n\nlocal current_key_detector\nfunction mod_setting_shortcut( mod_id, gui, in_main_menu, im_id, setting )\n    GuiLayoutBeginHorizontal( gui, 0, 0, true, 2, 2 )\n    GuiText( gui, mod_setting_group_x_offset, 0, setting.ui_name )\n\n    local changed = false\n	if current_key_detector == setting.id then\n		local shortcut = {}\n		for k, v in pairs( listen_keyboard_down() ) do\n			if v then\n				shortcut[ #shortcut + 1 ] = k\n			end\n		end\n\n		local str\n		if #shortcut > 0 then\n			str = shortcut_tostring( shortcut, GameTextGet( \"$current_language\" ) )\n			str = str .. ( setting.click_required and text.shortcut_click_here or text.shortcut_click_to_save )\n		else\n			str = \"$menuoptions_configurecontrols_pressakey\"\n		end\n\n		GuiColorSetForNextWidget( gui, 1, 1, 0.5, 1 )\n		local left_click, right_click =\n			GuiButton( gui, im_id, mod_setting_group_x_offset - GuiGetTextDimensions( gui, setting.ui_name ) + 120, 0, str )\n\n		if InputIsMouseButtonJustUp( KEYCODES_RAW.Mouse_left ) or InputIsMouseButtonJustDown( KEYCODES_RAW.Mouse_right ) then\n			current_key_detector = nil\n			if not setting.click_required then\n				ModSettingSetNextValue( mod_setting_get_id( mod_id, setting ), smallfolk.dumps( shortcut ), false )\n				changed = true\n			else\n				local click_given = false\n				if left_click then\n					shortcut[ #shortcut + 1 ] = \"Mouse_left\"\n					click_given = true\n				end\n				if right_click then\n					shortcut[ #shortcut + 1 ] = \"Mouse_right\"\n					click_given = true\n				end\n				if click_given then\n					ModSettingSetNextValue( mod_setting_get_id( mod_id, setting ), smallfolk.dumps( shortcut ), false )\n					changed = true\n				end\n			end\n		end\n	else\n		local str\n		do\n			local value = ModSettingGetNextValue( mod_setting_get_id( mod_id, setting ) )\n			if type( value ) ~= \"string\" then value = setting.value_default or \"{}\" end\n			local shortcut\n			do\n				local status, _ = pcall( function()\n					shortcut = smallfolk.loads( value )\n				end )\n				if not status then\n					shortcut = {}\n				end\n			end\n\n			if #shortcut == 0 then\n				str = \"$menuoptions_configurecontrols_action_unbound\"\n			else\n				str = shortcut_tostring( shortcut, GameTextGet( \"$current_language\" ) )\n			end\n		end\n\n		local left_click, right_click =\n			GuiButton( gui, im_id, mod_setting_group_x_offset - GuiGetTextDimensions( gui, setting.ui_name ) + 120, 0, str )\n\n		if left_click and not right_click then\n			current_key_detector = setting.id\n			ModSettingSetNextValue( mod_setting_get_id( mod_id, setting ), \"{}\", false )\n			changed = true\n		elseif not left_click and right_click then\n			ModSettingSetNextValue( mod_setting_get_id( mod_id, setting ), \"{}\", false )\n			changed = true\n		end\n	end\n\n	if changed then ModSettingSet( mod_id .. \".shortcut_changed\", true, false ) end\n\n	mod_setting_tooltip( mod_id, gui, in_main_menu, setting )\n\n    GuiLayoutEnd( gui )\nend"
_TWWE_VFS["mods/spell_lab_shugged/files/lib/shortcut_tostring.lua"] = "local special_chars = {\n	MINUS = \"-\",\n	EQUALS = \"=\",\n	LEFTBRACKET = \"[\",\n	RIGHTBRACKET = \"]\",\n	BACKSLASH = \"\\\\\",\n	NONUSHASH = \"#\",\n	SEMICOLON = \";\",\n	APOSTROPHE = \"'\",\n	GRAVE = \"`\",\n	COMMA = \",\",\n	PERIOD = \".\",\n	SLASH = \"/\",\n	NUMLOCKCLEAR = \"NUMLOCK\",\n	KP_DIVIDE = \"/\",\n	KP_MULTIPLY = \"*\",\n	KP_MINUS = \"-\",\n	KP_PLUS = \"+\",\n	KP_PERIOD = \".\",\n	NONUSBACKSLASH = \"\\\\\",\n	APPLICATION = \"MENU\",\n	POWER = \"SHUTDOWN\",\n	KP_EQUALS = \"=\",\n	KP_COMMA = \",\",\n	KP_EQUALSAS400 = \"=\",\n	KP_LEFTPAREN = \"(\",\n	KP_RIGHTPAREN = \")\",\n	KP_LEFTBRACE = \"{\",\n	KP_RIGHTBRACE = \"}\",\n	KP_XOR = \"^\",\n	KP_POWER = \"SHUTDOWN\",\n	KP_PERCENT = \"%\",\n	KP_LESS = \"<\",\n	KP_GREATER = \">\",\n	KP_AMPERSAND = \"&\",\n	KP_DBLAMPERSAND = \"&&\",\n	KP_VERTICALBAR = \"|\",\n	KP_DBLVERTICALBAR = \"||\",\n	KP_COLON = \":\",\n	KP_HASH = \"#\",\n	KP_AT = \"@\",\n	KP_EXCLAM = \"!\",\n	KP_PLUSMINUS = \"+-\",\n	LGUI = \"LEFT WINDOWS\",\n	RGUI = \"RIGHT WINDOWS\",\n}\n\nlocal named_keys = {\n	Key_CTRL = \"Ctrl\",\n	Key_SHIFT = \"Shift\",\n	Key_ALT = \"Alt\",\n	JOY_BUTTON_0 = \"$input_xboxbutton_a\",\n	JOY_BUTTON_1 = \"$input_xboxbutton_b\",\n	JOY_BUTTON_2 = \"$input_xboxbutton_x\",\n	JOY_BUTTON_3 = \"$input_xboxbutton_y\",\n}\n\nlocal custom_keys_i18n = {\n	[\"简体中文\"] = {\n		Mouse_left = \"左键\",\n		Mouse_right = \"右键\",\n	},\n	DEFAULT = {\n		Mouse_left = \"Left-click\",\n		Mouse_right = \"Right-click\",\n	},\n}\n\ndo\n	local other_zh_cn_languages = { \"喵体中文\", \"汪体中文\", \"完全汉化\" }\n	for _, v in ipairs( other_zh_cn_languages ) do\n		custom_keys_i18n[ v ] = custom_keys_i18n[\"简体中文\"]\n	end\nend\n\nlocal function keyname_to_text( keyname, lang )\n	local result = named_keys[ keyname ]\n	if result then return result end\n\n	local i18n = custom_keys_i18n[ lang ] or custom_keys_i18n.DEFAULT\n	result = i18n[ keyname ]\n	if result then return result end\n\n	if keyname:find \"^Mouse_\" then\n		return GameTextGet( \"$input_\" .. keyname:gsub( \"_\", \"\" ):lower() ):upper()\n	elseif keyname:find \"^Key_\"  then\n		local name = keyname:sub(5):upper()\n\n		result = special_chars[ name ]\n		if result then return result end\n\n		local did = 0\n		result, did = name:gsub( \"^KP_\", \"KEYPAD \" )\n		if did > 0 then return result end\n		result, did = name:gsub( \"^AC_\", \"AC \" )\n		if did > 0 then return result end\n\n		return name\n	elseif keyname:find \"^JOY_BUTTON_\" then\n		local result = GameTextGet( \"$input_xboxbutton_\" .. keyname:sub(12):lower() )\n		if keyname:find \"%d%d_DOWN$\" then\n			result = result .. \" DOWN\"\n		elseif keyname:find \"%d%d_MOVED$\" then\n			result = result .. \" MOVED\"\n		end\n	end\n	return GameTextGet( \"$menuoptions_configurecontrols_keyname_unknown\" )\nend\n\nlocal order = {\n	Key_CTRL = -100,\n	Key_ALT = -99,\n	Key_SHIFT = -98,\n	DEFAULT = 0,\n	Mouse_left = 99,\n	Mouse_right = 100,\n}\nlocal function shortcut_sort( shortcut )\n	table.sort( shortcut, function( a, b )\n		local order_a = order[ a ] or order.DEFAULT\n		local order_b = order[ b ] or order.DEFAULT\n		if order_a ~= order_b then return order_a < order_b end\n\n		local len_a = #a\n		local len_b = #b\n		if len_a ~= len_b then return len_a > len_b end\n\n		return a < b\n	end )\nend\n\nfunction shortcut_tostring( shortcut, lang )\n	local copy = {}\n	for k, v in pairs( shortcut ) do\n		copy[ k ] = v\n	end\n	shortcut_sort( copy )\n\n	local strs_to_concat = {}\n	for _, key in ipairs( copy ) do\n		strs_to_concat[ #strs_to_concat + 1 ] = keyname_to_text( key, lang )\n	end\n	return table.concat( strs_to_concat, \" + \" )\nend"
_TWWE_VFS["mods/spell_lab_shugged/files/lib/smallfolk.lua"] = "--[[\n\nCopyright (c) 2014 Robin Wellner\n\nPermission is hereby granted, free of charge, to any person obtaining a copy of this software and associated \ndocumentation files (the \"Software\"), to deal in the Software without restriction, including without limitation \nthe rights to use, copy, modify, merge, publish, distribute, sublicense, and/or sell copies of the Software, and \nto permit persons to whom the Software is furnished to do so, subject to the following conditions:\n\nThe above copyright notice and this permission notice shall be included in all copies or substantial portions of the Software.\n\nTHE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED \nTO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL \nTHE AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION OF \nCONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER \nDEALINGS IN THE SOFTWARE.\n\n]]\n\nlocal M = {}\nlocal expect_object, dump_object\nlocal error, tostring, pairs, type, floor, huge, concat = error, tostring, pairs, type, math.floor, math.huge, table.concat\n\nlocal dump_type = {}\n\nfunction dump_type:string(nmemo, memo, acc)\n	local nacc = #acc\n	acc[nacc + 1] = '\"'\n	acc[nacc + 2] = self:gsub('\"', '\"\"')\n	acc[nacc + 3] = '\"'\n	return nmemo\nend\n\nfunction dump_type:number(nmemo, memo, acc)\n	acc[#acc + 1] = (\"%.17g\"):format(self)\n	return nmemo\nend\n\nfunction dump_type:table(nmemo, memo, acc)\n	if memo[self] then\n		acc[#acc + 1] = '@'\n		acc[#acc + 1] = tostring(memo[self])\n		return nmemo\n	end\n	nmemo = nmemo + 1\n	memo[self] = nmemo\n	acc[#acc + 1] = '{'\n	local nself = #self\n	for i = 1, nself do -- don't use ipairs here, we need the gaps\n		nmemo = dump_object(self[i], nmemo, memo, acc)\n		acc[#acc + 1] = ','\n	end\n	for k, v in pairs(self) do\n		if type(k) ~= 'number' or floor(k) ~= k or k < 1 or k > nself then\n			nmemo = dump_object(k, nmemo, memo, acc)\n			acc[#acc + 1] = ':'\n			nmemo = dump_object(v, nmemo, memo, acc)\n			acc[#acc + 1] = ','\n		end\n	end\n	acc[#acc] = acc[#acc] == '{' and '{}' or '}'\n	return nmemo\nend\n\nfunction dump_object(object, nmemo, memo, acc)\n	if object == true then\n		acc[#acc + 1] = 't'\n	elseif object == false then\n		acc[#acc + 1] = 'f'\n	elseif object == nil then\n		acc[#acc + 1] = 'n'\n	elseif object ~= object then\n		if (''..object):sub(1,1) == '-' then\n			acc[#acc + 1] = 'N'\n		else\n			acc[#acc + 1] = 'Q'\n		end\n	elseif object == huge then\n		acc[#acc + 1] = 'I'\n	elseif object == -huge then\n		acc[#acc + 1] = 'i'\n	else\n		local t = type(object)\n		if not dump_type[t] then\n			error('cannot dump type ' .. t)\n		end\n		return dump_type[t](object, nmemo, memo, acc)\n	end\n	return nmemo\nend\n\nfunction M.dumps(object)\n	local nmemo = 0\n	local memo = {}\n	local acc = {}\n	dump_object(object, nmemo, memo, acc)\n	return concat(acc)\nend\n\nlocal function invalid(i)\n	error('invalid input at position ' .. i)\nend\n\nlocal nonzero_digit = {['1'] = true, ['2'] = true, ['3'] = true, ['4'] = true, ['5'] = true, ['6'] = true, ['7'] = true, ['8'] = true, ['9'] = true}\nlocal is_digit = {['0'] = true, ['1'] = true, ['2'] = true, ['3'] = true, ['4'] = true, ['5'] = true, ['6'] = true, ['7'] = true, ['8'] = true, ['9'] = true}\nlocal function expect_number(string, start)\n	local i = start\n	local head = string:sub(i, i)\n	if head == '-' then\n		i = i + 1\n		head = string:sub(i, i)\n	end\n	if nonzero_digit[head] then\n		repeat\n			i = i + 1\n			head = string:sub(i, i)\n		until not is_digit[head]\n	elseif head == '0' then\n		i = i + 1\n		head = string:sub(i, i)\n	else\n		invalid(i)\n	end\n	if head == '.' then\n		local oldi = i\n		repeat\n			i = i + 1\n			head = string:sub(i, i)\n		until not is_digit[head]\n		if i == oldi + 1 then\n			invalid(i)\n		end\n	end\n	if head == 'e' or head == 'E' then\n		i = i + 1\n		head = string:sub(i, i)\n		if head == '+' or head == '-' then\n			i = i + 1\n			head = string:sub(i, i)\n		end\n		if not is_digit[head] then\n			invalid(i)\n		end\n		repeat\n			i = i + 1\n			head = string:sub(i, i)\n		until not is_digit[head]\n	end\n	return tonumber(string:sub(start, i - 1)), i\nend\n\nlocal expect_object_head = {\n	t = function(string, i) return true, i end,\n	f = function(string, i) return false, i end,\n	n = function(string, i) return nil, i end,\n	Q = function(string, i) return -(0/0), i end,\n	N = function(string, i) return 0/0, i end,\n	I = function(string, i) return 1/0, i end,\n	i = function(string, i) return -1/0, i end,\n	['\"'] = function(string, i)\n		local nexti = i - 1\n		repeat\n			nexti = string:find('\"', nexti + 1, true) + 1\n		until string:sub(nexti, nexti) ~= '\"'\n		return string:sub(i, nexti - 2):gsub('\"\"', '\"'), nexti\n	end,\n	['0'] = function(string, i)\n		return expect_number(string, i - 1)\n	end,\n	['{'] = function(string, i, tables)\n		local nt, k, v = {}\n		local j = 1\n		tables[#tables + 1] = nt\n		if string:sub(i, i) == '}' then\n			return nt, i + 1\n		end\n		while true do\n			k, i = expect_object(string, i, tables)\n			if string:sub(i, i) == ':' then\n				v, i = expect_object(string, i + 1, tables)\n				nt[k] = v\n			else\n				nt[j] = k\n				j = j + 1\n			end\n			local head = string:sub(i, i)\n			if head == ',' then\n				i = i + 1\n			elseif head == '}' then\n				return nt, i + 1\n			else\n				invalid(i)\n			end\n		end\n	end,\n	['@'] = function(string, i, tables)\n		local match = string:match('^%d+', i)\n		local ref = tonumber(match)\n		if tables[ref] then\n			return tables[ref], i + #match\n		end\n		invalid(i)\n	end,\n}\nexpect_object_head['1'] = expect_object_head['0']\nexpect_object_head['2'] = expect_object_head['0']\nexpect_object_head['3'] = expect_object_head['0']\nexpect_object_head['4'] = expect_object_head['0']\nexpect_object_head['5'] = expect_object_head['0']\nexpect_object_head['6'] = expect_object_head['0']\nexpect_object_head['7'] = expect_object_head['0']\nexpect_object_head['8'] = expect_object_head['0']\nexpect_object_head['9'] = expect_object_head['0']\nexpect_object_head['-'] = expect_object_head['0']\nexpect_object_head['.'] = expect_object_head['0']\n\nexpect_object = function(string, i, tables)\n	local head = string:sub(i, i)\n	if expect_object_head[head] then\n		return expect_object_head[head](string, i + 1, tables)\n	end\n	invalid(i)\nend\n\nfunction M.loads(string, maxsize)\n	return (expect_object(string, 1, {}))\nend\n\nreturn M"
_TWWE_VFS["mods/spell_lab_shugged/files/lib/variables.lua"] = "function EntityClearVariable( entity, variable_tag, value )\n    local variable = EntityGetFirstComponent( entity, \"VariableStorageComponent\", variable_tag );\n    if variable ~= nil then\n        EntityRemoveComponent( entity, variable );\n    end\nend\n\nfunction EntityGetVariableString( entity, variable_tag, default )\n    local variable = EntityGetFirstComponent( entity, \"VariableStorageComponent\", variable_tag );\n    if variable ~= nil then\n        return ComponentGetValue2( variable, \"value_string\" );\n    end\n    return default;\nend\n\nfunction EntitySetVariableString( entity, variable_tag, value )\n    local current_variable = EntityGetFirstComponent( entity, \"VariableStorageComponent\", variable_tag );\n    if current_variable == nil then\n        EntityAddComponent( entity, \"VariableStorageComponent\", {\n            _tags=variable_tag..\",enabled_in_world,enabled_in_hand,enabled_in_inventory\",\n            value_string=tostring(value)\n        } );\n    else\n        ComponentSetValue2( current_variable, \"value_string\", value );\n    end\nend\n\nfunction EntityHasNamedVariable( entity, name )\n    for k,component in pairs( EntityGetComponent( entity, \"VariableStorageComponent\" ) or {} ) do\n        if ComponentGetValue2( component, \"name\") == name then\n            return true;\n        end\n    end\n    return false;\nend\n\nfunction EntityGetVariableNumber( entity, variable_tag, default )\n    return tonumber( EntityGetVariableString( entity, variable_tag, default ) );\nend\n\nfunction EntitySetVariableNumber( entity, variable_tag, value )\n    return EntitySetVariableString( entity, variable_tag, value );\nend\n\nfunction EntityAdjustVariableNumber( entity, variable_tag, default, callback )\n    local new_value = callback( EntityGetVariableNumber( entity, variable_tag, default ) );\n    EntitySetVariableNumber( entity, variable_tag, tostring( new_value ) );\n    return new_value;\nend\n\nfunction ComponentAdjustValue( component, member, callback )\n    local new_value = callback( ComponentGetValue2( component, member ) );\n    ComponentSetValue2( component, member, new_value );\n    return new_value;\nend\n\nfunction ComponentSetValues( component, member_value_table )\n    for member,new_value in pairs(member_value_table) do\n        ComponentSetValue2( component, member, new_value );\n    end\nend\n\nfunction ComponentAdjustValues( component, member_callback_table )\n    for member,callback in pairs( member_callback_table ) do\n        ComponentSetValue2( component, member, callback( ComponentGetValue2( component, member ) ) );\n    end\nend\n\nfunction ComponentObjectSetValues( component, object, member_value_table )\n    for member,new_value in pairs(member_value_table) do\n        ComponentObjectSetValue2( component, object, member, new_value );\n    end\nend\n\nfunction ComponentObjectAdjustValues( component, object, member_callback_table )\n    for member,callback in pairs(member_callback_table) do\n        ComponentObjectSetValue2( component, object, member, callback( ComponentObjectGetValue2( component, object, member ) ) );\n    end\nend\n\nfunction ComponentSetValues( component, member_value_table )\n    for member,new_value in pairs(member_value_table) do\n        ComponentSetValue2( component, member, new_value );\n    end\nend\n\nfunction ComponentAdjustMetaCustoms( component, member_callback_table )\n    for member,callback in pairs(member_callback_table) do\n        local current_value = ComponentGetValue2( component, member );\n        local new_value = callback( current_value );\n        ComponentSetValue2( component, member, new_value );\n    end\nend"
_TWWE_VFS["mods/spell_lab_shugged/files/lib/wands.lua"] = "dofile_once( \"data/scripts/gun/procedural/gun_procedural.lua\" )\ndofile_once( \"mods/spell_lab_shugged/files/lib/variables.lua\" )\n\n-- override the one from gun_procedural.lua\n-- which uses EntityGetFirstComponent instead of EntityGetFirstComponentIncludingDisabled,\n-- causing issues\nfunction SetWandSprite( entity_id, ability_comp, item_file, offset_x, offset_y, tip_x, tip_y )\n\n	if( ability_comp ~= nil ) then\n		ComponentSetValue( ability_comp, \"sprite_file\", item_file)\n	end\n\n	local sprite_comp = EntityGetFirstComponentIncludingDisabled( entity_id, \"SpriteComponent\", \"item\" )\n	if( sprite_comp ~= nil ) then\n		ComponentSetValue( sprite_comp, \"image_file\", item_file)\n		ComponentSetValue( sprite_comp, \"offset_x\", offset_x )\n		ComponentSetValue( sprite_comp, \"offset_y\", offset_y )\n	end\n\n	local hotspot_comp = EntityGetFirstComponentIncludingDisabled( entity_id, \"HotspotComponent\", \"shoot_pos\" )\n	if( hotspot_comp ~= nil ) then\n		ComponentSetValueVector2( hotspot_comp, \"offset\", tip_x, tip_y )\n	end \nend\n\nlocal WAND_STAT_SETTER = {\n	Direct = 1,\n	Gun = 2,\n	GunAction = 3\n}\n\nlocal WAND_STAT_SETTERS = {\n	shuffle_deck_when_empty = WAND_STAT_SETTER.Gun,\n	actions_per_round = WAND_STAT_SETTER.Gun,\n	speed_multiplier = WAND_STAT_SETTER.GunAction,\n	-- deck_capacity = WAND_STAT_SETTER.Gun,\n	reload_time = WAND_STAT_SETTER.Gun,\n	fire_rate_wait = WAND_STAT_SETTER.GunAction,\n	spread_degrees = WAND_STAT_SETTER.GunAction,\n	mana_charge_speed = WAND_STAT_SETTER.Direct,\n	mana_max = WAND_STAT_SETTER.Direct,\n	mana = WAND_STAT_SETTER.Direct,\n}\n\nlocal WANDS = {}\n\nfunction WANDS.wand_clear_actions( wand )\n	local actions = {}\n	local children = EntityGetAllChildren( wand, \"card_action\" ) or {}\n	for i,v in ipairs( children ) do\n		local item = EntityGetFirstComponentIncludingDisabled( v, \"ItemComponent\" )\n		local item_action = EntityGetFirstComponentIncludingDisabled( v, \"ItemActionComponent\" )\n		if item and item_action then\n			EntityRemoveFromParent( v )\n			EntityKill( v )\n		end\n	end\n	return actions\nend\n\nfunction WANDS.wand_get_actions( wand )\n	local actions = {}\n	local children = EntityGetAllChildren( wand, \"card_action\" ) or {}\n	for i,v in ipairs( children ) do\n		local item = EntityGetFirstComponentIncludingDisabled( v, \"ItemComponent\" )\n		local item_action = EntityGetFirstComponentIncludingDisabled( v, \"ItemActionComponent\" )\n		if item and item_action then\n			local action_id = ComponentGetValue2( item_action, \"action_id\" )\n			local permanent = ComponentGetValue2( item, \"permanently_attached\" )\n			local locked = ComponentGetValue2( item, \"is_frozen\" )\n			local x, y = ComponentGetValue2( item, \"inventory_slot\" )\n			if action_id ~= nil then\n				table.insert( actions, { action_id = action_id, permanent = permanent, locked = locked, x = x, y = y, entity = v, item = item } )\n			end\n		end\n	end\n	return actions\nend\n\n-- TODO : Deduplicate\nfunction WANDS.wand_get_actions_absolute( wand )\n	local actions = {}\n	local permanent_actions = {}\n	local children = EntityGetAllChildren( wand, \"card_action\" ) or {}\n	local slot_0_taken = false\n	local offset = 0\n	for i,v in ipairs( children ) do\n		local item = EntityGetFirstComponentIncludingDisabled( v, \"ItemComponent\" )\n		local item_action = EntityGetFirstComponentIncludingDisabled( v, \"ItemActionComponent\" )\n		if item and item_action then\n			local action_id = ComponentGetValue2( item_action, \"action_id\" )\n			local permanent = ComponentGetValue2( item, \"permanently_attached\" )\n			local uses_remaining = ComponentGetValue2( item, \"uses_remaining\" )\n			local locked = ComponentGetValue2( item, \"is_frozen\" )\n			local x, y = ComponentGetValue2( item, \"inventory_slot\" )\n			if action_id then\n				if not permanent then\n					local index = x\n					if x == 0 then\n						if slot_0_taken then\n							x = i - 1 - #permanent_actions\n						else\n							slot_0_taken = true\n						end\n					end\n\n					actions[ x - offset ] = { action_id = action_id, permanent = permanent, locked = locked, x = x, y = y, entity = v, item = item, uses_remaining = uses_remaining }\n				else\n					if x ~= 0 then\n						offset = offset + 1\n					end\n					permanent_actions[ #permanent_actions + 1 ] = { action_id = action_id, permanent = permanent, locked = locked, x = x, y = y, entity = v, item = item, uses_remaining = uses_remaining }\n				end\n			end\n		end\n	end\n	return actions, permanent_actions\nend\n\nfunction WANDS.wand_get_actions_all( wand )\n	local actions = {}\n	for i, a in ipairs( EntityGetAllChildren( wand, \"card_action\" ) or {} ) do\n		local item_comp = EntityGetFirstComponentIncludingDisabled( a, \"ItemComponent\" )\n		local ia_comp   = EntityGetFirstComponentIncludingDisabled( a, \"ItemActionComponent\" )\n		if not item_comp or not ia_comp then goto continue end\n		local action_id      = ComponentGetValue2( ia_comp, \"action_id\" )\n		local permanent      = ComponentGetValue2( item_comp, \"permanently_attached\" )\n		local uses_remaining = ComponentGetValue2( item_comp, \"uses_remaining\" )\n		local locked         = ComponentGetValue2( item_comp, \"is_frozen\" )\n		local x, y           = ComponentGetValue2( item_comp, \"inventory_slot\" )\n		if not action_id then goto continue end\n		table.insert( actions, {\n			action_id      = action_id,\n			permanent      = permanent,\n			locked         = locked,\n			x              = x,\n			y              = y,\n			uses_remaining = uses_remaining,\n		} )\n		::continue::\n	end\n	return actions\nend\n\nfunction WANDS.wand_get_actions_permanent( wand )\n	local permanent_actions = {}\n	for i,v in ipairs( EntityGetAllChildren( wand, \"card_action\" ) or {} ) do\n		local item        = EntityGetFirstComponentIncludingDisabled( v, \"ItemComponent\" )\n		local item_action = EntityGetFirstComponentIncludingDisabled( v, \"ItemActionComponent\" )\n		if not item or not item_action then goto continue end\n		local action_id = ComponentGetValue2( item_action, \"action_id\" )\n		local permanent = ComponentGetValue2( item, \"permanently_attached\" )\n		if not action_id or not permanent then goto continue end\n		local uses_remaining = ComponentGetValue2( item, \"uses_remaining\" )\n		local locked         = ComponentGetValue2( item, \"is_frozen\" )\n		local x, y           = ComponentGetValue2( item, \"inventory_slot\" )\n		table.insert( permanent_actions, {\n			action_id      = action_id,\n			locked         = locked,\n			x              = x,\n			y              = y,\n			entity         = v,\n			item           = item,\n			uses_remaining = uses_remaining\n		} )\n		::continue::\n	end\n	return permanent_actions\nend\n\nfunction WANDS.wand_get_num_actions_permanent( wand )\n	local num_permanent_actions = 0\n	for i, v in ipairs( EntityGetAllChildren( wand, \"card_action\" ) or {} ) do\n		local item        = EntityGetFirstComponentIncludingDisabled( v, \"ItemComponent\" )\n		local item_action = EntityGetFirstComponentIncludingDisabled( v, \"ItemActionComponent\" )\n		if not item or not item_action then goto continue end\n		local action_id = ComponentGetValue2( item_action, \"action_id\" )\n		local permanent = ComponentGetValue2( item, \"permanently_attached\" )\n		if not action_id or not permanent then goto continue end\n		num_permanent_actions = num_permanent_actions + 1\n		::continue::\n	end\n	return num_permanent_actions\nend\n\nfunction WANDS.actions_get_num_permanent( actions )\n	local num_permanent_actions = 0\n	for _, a in pairs( actions ) do\n		if a.permanent then\n			num_permanent_actions = num_permanent_actions + 1\n		end\n	end\n	return num_permanent_actions\nend\n\nfunction WANDS.wand_set_actions( wand, actions_table )\n	for _,action_id in pairs(actions_table) do\n		AddGunAction( wand, action_id )\n	end\nend\n\nfunction WANDS.wand_shuffle_actions( wand )\n	local actions = {}\n	local actions_data = {}\n	local children = EntityGetAllChildren( wand, \"card_action\" ) or {}\n	for i,v in ipairs( children ) do\n		local item = EntityGetFirstComponentIncludingDisabled( v, \"ItemComponent\" )\n		local item_action = EntityGetFirstComponentIncludingDisabled( v, \"ItemActionComponent\" )\n		if item and item_action then\n			local action_id = ComponentGetValue2( item_action, \"action_id\" )\n			local permanent = ComponentGetValue2( item, \"permanently_attached\" )\n			local locked = ComponentGetValue2( item, \"is_frozen\" )\n			local x, y = ComponentGetValue2( item, \"inventory_slot\" )\n			if action_id ~= nil and permanent ~= true and locked ~= true then\n				table.insert( actions, { action_entity = v, item = item } )\n				table.insert( actions_data, { x = x, y = y } )\n			end\n		end\n	end\n	local wx, wy = EntityGetTransform( wand )\n	SetRandomSeed( GameGetFrameNum(), wx + wy )\n	local actions_data_shuffled = {}\n	for i, v in ipairs(actions_data) do\n		local pos = Random( 1, #actions_data_shuffled + 1 )\n		table.insert( actions_data_shuffled, pos, v )\n	end\n	for i=1,#actions do\n		local action = actions[i]\n		local action_data = actions_data_shuffled[i]\n		ComponentSetValue2( action.item, \"inventory_slot\", action_data.x, action_data.y )\n	end\nend\n\nfunction WANDS.wand_copy_actions( base_wand, copy_wand )\n	local actions = WANDS.wand_get_actions( base_wand )\n	for index,action_data in pairs( actions ) do\n		local action_entity = CreateItemActionEntity( action_data.action_id )\n		local item = EntityGetFirstComponentIncludingDisabled( action_entity, \"ItemComponent\" )\n		if action_data.permanent then\n			ComponentSetValue2( item, \"permanently_attached\", true )\n		end\n		if ComponentSetValue2 and action_data.x ~= nil and action_data.y ~= nil then\n			ComponentSetValue2( item, \"inventory_slot\", action_data.x, action_data.y )\n		end\n		EntitySetComponentsWithTagEnabled( action_entity, \"enabled_in_world\", false )\n		EntityAddChild( copy_wand, action_entity )\n	end\nend\n\nfunction WANDS.wand_copy_stats( base_wand, copy_wand )\n	local base_ability = EntityGetFirstComponentIncludingDisabled( base_wand, \"AbilityComponent\" )\n	local target_ability = EntityGetFirstComponentIncludingDisabled( copy_wand, \"AbilityComponent\" )\n	if base_ability and target_ability then\n		for stat,stat_type in pairs( WAND_STAT_SETTERS ) do\n			WANDS.ability_component_set_stat( target_ability, stat, WANDS.ability_component_get_stat( base_ability, stat ) )\n		end\n	end\nend\n\nfunction WANDS.wand_copy( base_wand, copy_wand, copy_sprite, copy_actions )\n	WANDS.wand_copy_stats( base_wand, copy_wand )\n	if copy_sprite ~= false then\n		local base_ability = EntityGetFirstComponentIncludingDisabled( base_wand, \"AbilityComponent\" )\n		local target_ability = EntityGetFirstComponentIncludingDisabled( copy_wand, \"AbilityComponent\" )\n		ComponentSetValue2( target_ability, \"sprite_file\", ComponentGetValue2( base_ability, \"sprite_file\" ) )\n		local base_sprite = EntityGetFirstComponentIncludingDisabled( base_wand, \"SpriteComponent\" )\n		local copy_sprite = EntityGetFirstComponentIncludingDisabled( copy_wand, \"SpriteComponent\" )\n		CopyListedComponentMembers( base_sprite, copy_sprite, \"image_file\",\"offset_x\",\"offset_y\")\n		local base_hotspot = EntityGetFirstComponentIncludingDisabled( base_wand, \"HotspotComponent\", \"shoot_pos\" )\n		local copy_hotspot = EntityGetFirstComponentIncludingDisabled( copy_wand, \"HotspotComponent\", \"shoot_pos\" )\n		CopyComponentMembers( base_hotspot, copy_hotspot )\n		local base_hotspot_x, base_hotspot_y = ComponentGetValue2( base_hotspot, \"offset\" )\n		ComponentSetValue2( copy_hotspot, \"offset\", base_hotspot_x, base_hotspot_y )\n	end\n	if copy_actions ~= false then\n		WANDS.wand_copy_actions( base_wand, copy_wand )\n	end\nend\n\nfunction WANDS.ability_component_get_stat( ability, stat )\n	local setter = WAND_STAT_SETTERS[stat]\n	if setter ~= nil then\n		if setter == WAND_STAT_SETTER.Direct then\n			return ComponentGetValue2( ability, stat )\n		elseif setter == WAND_STAT_SETTER.Gun then\n			return ComponentObjectGetValue2( ability, \"gun_config\", stat )\n		elseif setter == WAND_STAT_SETTER.GunAction then\n			return ComponentObjectGetValue2( ability, \"gunaction_config\", stat )\n		end\n	end\nend\n\nfunction WANDS.ability_component_set_stat( ability, stat, value )\n	local setter = WAND_STAT_SETTERS[stat]\n	if setter ~= nil then\n		if setter == WAND_STAT_SETTER.Direct then\n			ComponentSetValue2( ability, stat, value )\n		elseif setter == WAND_STAT_SETTER.Gun then\n			ComponentObjectSetValue2( ability, \"gun_config\", stat, value )\n		elseif setter == WAND_STAT_SETTER.GunAction then\n			ComponentObjectSetValue2( ability, \"gunaction_config\", stat, value )\n		end\n	end\nend\n\nfunction WANDS.ability_component_adjust_stat( ability, stat, callback )\n	local setter = WAND_STAT_SETTERS[stat]\n	if setter ~= nil then\n		local current_value = nil\n		if setter == WAND_STAT_SETTER.Direct then\n			current_value = ComponentGetValue2( ability, stat )\n		elseif setter == WAND_STAT_SETTER.Gun then\n			current_value = ComponentObjectGetValue2( ability, \"gun_config\", stat )\n		elseif setter == WAND_STAT_SETTER.GunAction then\n			current_value = ComponentObjectGetValue2( ability, \"gunaction_config\", stat )\n		end\n		local new_value = callback( current_value )\n		if setter == WAND_STAT_SETTER.Direct then\n			ComponentSetValue2( ability, stat, new_value )\n		elseif setter == WAND_STAT_SETTER.Gun then\n			ComponentObjectSetValue2( ability, \"gun_config\", stat, new_value )\n		elseif setter == WAND_STAT_SETTER.GunAction then\n			ComponentObjectSetValue2( ability, \"gunaction_config\", stat, new_value )\n		end\n	end\nend\n\nfunction WANDS.ability_component_get_stats( ability, stat )\n	local stats = {}\n	for k,v in pairs( WAND_STAT_SETTERS ) do\n		stats[k] = WANDS.ability_component_get_stat( ability, k )\n	end\n	return stats\nend\n\nfunction WANDS.ability_component_set_stats( ability, stat_value_table )\n	for stat,value in pairs(stat_value_table) do\n		WANDS.ability_component_set_stat( ability, stat, value )\n	end\nend\n\nfunction WANDS.ability_component_adjust_stats( ability, stat_callback_table )\n	for stat,callback in pairs(stat_callback_table) do\n		WANDS.ability_component_adjust_stat( ability, stat, callback )\n	end\nend\n\nfunction WANDS.wand_get_stat( wand, stat )\n	local ability = EntityGetFirstComponentIncludingDisabled( wand, \"AbilityComponent\" )\n	if ability then\n		if stat == \"deck_capacity\" then\n			return ComponentObjectGetValue2( ability, \"gun_config\", \"deck_capacity\" )\n		elseif stat == \"capacity\" then\n			return EntityGetWandCapacity( wand )\n		else\n			return WANDS.ability_component_get_stat( ability, stat )\n		end\n	end\nend\n\nfunction WANDS.wand_set_stat( wand, stat, value )\n	local ability = EntityGetFirstComponentIncludingDisabled( wand, \"AbilityComponent\" )\n	if ability then\n		if stat == \"deck_capacity\" then\n			ComponentObjectSetValue2( ability, \"gun_config\", \"deck_capacity\", value )\n		elseif stat == \"capacity\" then\n			ComponentObjectSetValue2( ability, \"gun_config\", \"deck_capacity\", value + WANDS.wand_get_num_actions_permanent( wand ) )\n		else\n			WANDS.ability_component_set_stat( ability, stat, value )\n		end\n	end\nend\n\nfunction WANDS.wand_adjust_stat( wand, stat, callback )\n	local ability = EntityGetFirstComponentIncludingDisabled( wand, \"AbilityComponent\" )\n	if ability then\n		if stat == \"deck_capacity\" then\n			local value = ComponentObjectGetValue2( ability, \"gun_config\", \"deck_capacity\" )\n			ComponentObjectSetValue2( ability, \"gun_config\", \"deck_capacity\", callback( value ) )\n		elseif stat == \"capacity\" then\n			local value = ComponentObjectGetValue2( ability, \"gun_config\", \"deck_capacity\" )\n			ComponentObjectSetValue2( ability, \"gun_config\", \"deck_capacity\", callback( value ) )\n		else\n			WANDS.ability_component_adjust_stat( ability, stat, callback )\n		end\n	end\nend\n\nfunction WANDS.wand_get_stats( wand, stat )\n	local ability = EntityGetFirstComponentIncludingDisabled( wand, \"AbilityComponent\" )\n	if ability then\n		local result = WANDS.ability_component_get_stats( ability, stat )\n		result.capacity = EntityGetWandCapacity( wand )\n		result.deck_capacity = ComponentObjectGetValue2( ability, \"gun_config\", \"deck_capacity\" )\n		return result\n	end\nend\n\nfunction WANDS.wand_set_stats( wand, stat_value_table )\n	local ability = EntityGetFirstComponentIncludingDisabled( wand, \"AbilityComponent\" )\n	if ability then return WANDS.ability_component_set_stats( ability, stat_value_table ) end\nend\n\nfunction WANDS.wand_adjust_stats( wand, stat_callback_table )\n	local ability = EntityGetFirstComponentIncludingDisabled( wand, \"AbilityComponent\" )\n	if ability then return WANDS.ability_component_adjust_stats( ability, stat_callback_table ) end\nend\n\nfunction WANDS.wand_get_dynamic_wand_data_from_stats( stats )\n	local gun = {\n		deck_capacity           = stats.deck_capacity,\n		actions_per_round       = stats.actions_per_round,\n		reload_time             = stats.reload_time,\n		shuffle_deck_when_empty = stats.shuffle_deck_when_empty and 1 or 0,\n		fire_rate_wait          = stats.fire_rate_wait,\n		spread_degrees          = stats.spread_degrees,\n		speed_multiplier        = stats.speed_multiplier,\n		mana_charge_speed       = stats.mana_charge_speed,\n		mana_max                = stats.mana_max,\n	}\n	return GetWand( gun )\nend\n\nfunction WANDS.wand_get_dynamic_wand_data( wand )\n	local stats = WANDS.wand_get_stats( wand )\n	stats.deck_capacity = stats.capacity + WANDS.wand_get_num_actions_permanent()\n	return WANDS.wand_get_dynamic_wand_data_from_stats( stats )\nend\n\nfunction WANDS.wand_get_data( wand )\n	return {\n		stats       = WANDS.wand_get_stats( wand ),\n		all_actions = WANDS.wand_get_actions_all( wand ),\n	}\nend\n\nfunction WANDS.initialize_wand( wand, wand_data, do_clear_actions )\n	do_clear_actions = do_clear_actions ~= false\n	if do_clear_actions then WANDS.wand_clear_actions( wand ) end\n	local ability = EntityGetFirstComponentIncludingDisabled( wand, \"AbilityComponent\" )\n	local item = EntityGetFirstComponent( wand, \"ItemComponent\" )\n	if wand_data.name then\n		ComponentSetValue2( ability, \"ui_name\", wand_data.name )\n		if item then\n			ComponentSetValue2( item, \"item_name\", wand_data.name )\n			ComponentSetValue2( item, \"always_use_item_name_in_ui\", true )\n		end\n	end\n\n	for stat,value in pairs( wand_data.stats or {} ) do\n		WANDS.ability_component_set_stat( ability, stat, value )\n	end\n\n	if wand_data.stats.capacity then\n		local deck_capacity = wand_data.stats.capacity\n		if do_clear_actions then\n			deck_capacity = deck_capacity + WANDS.actions_get_num_permanent( wand_data.all_actions or {} )\n		else\n			deck_capacity = deck_capacity + WANDS.wand_get_num_actions_permanent( wand )\n		end\n		ComponentObjectSetValue2( ability, \"gun_config\", \"deck_capacity\", deck_capacity )\n	end\n\n	for stat,range in pairs( wand_data.stat_ranges or {} ) do\n		WANDS.ability_component_set_stat( ability, stat, Random( range[1], range[2] ) )\n	end\n\n	WANDS.ability_component_set_stat( ability, \"mana\", WANDS.ability_component_get_stat( ability, \"mana_max\" ) )\n\n	for _, action in pairs( wand_data.permanent_actions or {} ) do\n		AddGunActionPermanent( wand, action.id )\n	end\n\n	if wand_data.absolute_actions then\n		for x,action in pairs( wand_data.absolute_actions ) do\n			local action_entity = CreateItemActionEntity( action.action_id )\n			if action_entity then\n				local item = EntityGetFirstComponentIncludingDisabled( action_entity, \"ItemComponent\" )\n				if action.locked then\n					ComponentSetValue2( item, \"is_frozen\", true )\n				end\n				if action.uses_remaining then\n					ComponentSetValue2( item, \"uses_remaining\", action.uses_remaining )\n				end\n				ComponentSetValue2( item, \"inventory_slot\", action.x or x, 0 )\n				EntitySetComponentsWithTagEnabled( action_entity, \"enabled_in_world\", false )\n				EntityAddChild( wand, action_entity )\n			end\n		end\n	end\n\n	for _, a in ipairs( wand_data.permanent_actions or {} ) do\n		local action_entity = CreateItemActionEntity( a.action_id )\n		if action_entity then\n			local item = EntityGetFirstComponentIncludingDisabled( action_entity, \"ItemComponent\" )\n			if a.locked then\n				ComponentSetValue2( item, \"is_frozen\", true )\n			end\n			if a.uses_remaining then\n				ComponentSetValue2( item, \"uses_remaining\", a.uses_remaining )\n			end\n			ComponentSetValue2( item, \"inventory_slot\", 0, 0 )\n			ComponentSetValue2( item, \"permanently_attached\", true )\n			EntitySetComponentsWithTagEnabled( action_entity, \"enabled_in_world\", false )\n			EntityAddChild( wand, action_entity )\n		end\n	end\n\n	for _, a in ipairs( wand_data.all_actions or {} ) do\n		local action_entity = CreateItemActionEntity( a.action_id )\n		if action_entity then\n			local item = EntityGetFirstComponentIncludingDisabled( action_entity, \"ItemComponent\" )\n			if a.locked then\n				ComponentSetValue2( item, \"is_frozen\", true )\n			end\n			if a.uses_remaining then\n				ComponentSetValue2( item, \"uses_remaining\", a.uses_remaining )\n			end\n			ComponentSetValue2( item, \"inventory_slot\", a.x, a.y )\n			ComponentSetValue2( item, \"permanently_attached\", a.permanent )\n			EntitySetComponentsWithTagEnabled( action_entity, \"enabled_in_world\", false )\n			EntityAddChild( wand, action_entity )\n		end\n	end\n\n	if wand_data.sprite ~= nil then\n		SetWandSprite( wand, ability, wand_data.sprite.file, wand_data.sprite.x, wand_data.sprite.y, wand_data.sprite.hotspot.x, wand_data.sprite.hotspot.y )\n		EntityRefreshSprite( wand, EntityGetFirstComponent( wand, \"SpriteComponent\", \"item\" ) )\n	else\n		local sprite = EntityGetFirstComponent( wand, \"SpriteComponent\", \"item\" )\n		local is_special_wand = false\n		if sprite then\n			local image_file = ComponentGetValue2( sprite, \"image_file\" )\n			if not string.sub( image_file, -13, -1 ):match( \"wand_%d%d%d%d%.png\" ) then\n				is_special_wand = true\n			end\n		end\n		if not is_special_wand then\n			local dynamic_wand = WANDS.wand_get_dynamic_wand_data( wand )\n			SetWandSprite( wand, ability, dynamic_wand.file, dynamic_wand.grip_x, dynamic_wand.grip_y, ( dynamic_wand.tip_x - dynamic_wand.grip_x ), ( dynamic_wand.tip_y - dynamic_wand.grip_y ) )\n			EntityRefreshSprite( wand, EntityGetFirstComponent( wand, \"SpriteComponent\", \"item\" ) )\n		end\n	end\nend\n\nfunction WANDS.wand_explode_action( wand, x, include_permanent_actions, include_frozen_actions, ox, oy )\n	local actions = WANDS.wand_get_actions_absolute( wand )\n	if actions then\n		local action = actions[x]\n		if action then\n			local action_to_remove = action.entity\n			EntityRemoveFromParent( action_to_remove )\n			EntityApplyTransform( action_to_remove, EntityGetTransform( wand ) )\n			EntitySetComponentsWithTagEnabled( action_to_remove, \"enabled_in_hand\", false )\n			EntitySetComponentsWithTagEnabled( action_to_remove, \"enabled_in_inventory\", false )\n			EntitySetComponentsWithTagEnabled( action_to_remove, \"enabled_in_world\", true )\n			ComponentSetValue2( EntityGetFirstComponent( action_to_remove, \"VelocityComponent\" ), \"mVelocity\", Random( -150, 150 ), Random( -250, -100 ) )\n			return action_to_remove\n		end\n	end\nend\n\nlocal function wand_explode_action_impl( wand, action_to_remove, vx, vy )\n	EntityRemoveFromParent( action_to_remove )\n	EntityApplyTransform( action_to_remove, EntityGetTransform( wand ) )\n	EntitySetComponentsWithTagEnabled( action_to_remove, \"enabled_in_hand\", false )\n	EntitySetComponentsWithTagEnabled( action_to_remove, \"enabled_in_inventory\", false )\n	EntitySetComponentsWithTagEnabled( action_to_remove, \"enabled_in_world\", true )\n	ComponentSetValue2( EntityGetFirstComponent( action_to_remove, \"VelocityComponent\" ), \"mVelocity\", vx, vy )\nend\n\nfunction WANDS.wand_explode_actions_out_of_bound( wand )\n	local deck_capacity = WANDS.wand_get_stat( wand, \"deck_capacity\" )\n	local vx = 0\n	for _, a in ipairs( EntityGetAllChildren( wand, \"card_action\" ) or {} ) do\n		local item        = EntityGetFirstComponentIncludingDisabled( a, \"ItemComponent\" )\n		local item_action = EntityGetFirstComponentIncludingDisabled( a, \"ItemActionComponent\" )\n		if item and item_action then\n			local x, _      = ComponentGetValue2( item, \"inventory_slot\" )\n			local permanent = ComponentGetValue2( item, \"permanently_attached\" )\n			if x >= deck_capacity and not permanent then\n				wand_explode_action_impl( wand, a, vx, -100 )\n				vx = vx + 30\n			end\n		end\n	end\nend\n\nfunction WANDS.wand_check_actions_out_of_bound( wand, deck_capacity )\n	for _, a in ipairs( EntityGetAllChildren( wand, \"card_action\" ) or {} ) do\n		local item        = EntityGetFirstComponentIncludingDisabled( a, \"ItemComponent\" )\n		local item_action = EntityGetFirstComponentIncludingDisabled( a, \"ItemActionComponent\" )\n		if item and item_action then\n			local x, _      = ComponentGetValue2( item, \"inventory_slot\" )\n			local permanent = ComponentGetValue2( item, \"permanently_attached\" )\n			if x >= deck_capacity and not permanent then\n				return false\n			end\n		end\n	end\n	return true\nend\n\nfunction WANDS.wand_explode_random_action( wand, include_permanent_actions, include_frozen_actions, ox, oy )\n	local x, y = EntityGetTransform( wand )\n	local actions = {}\n	local children = EntityGetAllChildren( wand, \"card_action\" ) or {}\n	for i,action in ipairs( children ) do\n		local item_action = EntityGetFirstComponentIncludingDisabled( action, \"ItemActionComponent\" )\n		if item_action ~= nil then\n			local item = EntityGetFirstComponentIncludingDisabled( action, \"ItemComponent\" )\n			if item ~= nil then\n				local action_id = ComponentGetValue2( item_action, \"action_id\" )\n				if action_id ~= nil then\n					if include_permanent_actions == true or ComponentGetValue2( item, \"permanently_attached\" ) == false then\n						if include_frozen_actions == true or ComponentGetValue2( item, \"is_frozen\" ) == false then\n							table.insert( actions, { action_id=action_id, permanent=permanent, entity=action } )\n						end\n					end\n				end\n			end\n		end\n	end\n	if #actions > 0 then\n		local r = math.ceil( math.random() * #actions )\n		local action_to_remove = actions[ r ]\n		local card = CreateItemActionEntity( action_to_remove.action_id, ox or x, oy or y )\n		ComponentSetValue2( EntityGetFirstComponent( card, \"VelocityComponent\" ), \"mVelocity\", Random( -150, 150 ), Random( -250, -100 ) )\n		EntityRemoveFromParent( action_to_remove.entity )\n		return action_to_remove\n	end\nend\n\nfunction WANDS.wand_remove_first_action( wand, include_permanent_actions, include_frozen_actions )\n	local x, y = EntityGetTransform( wand )\n	local actions = {}\n	local children = EntityGetAllChildren( wand, \"card_action\" ) or {}\n	for _,action in pairs( children ) do\n		local item_action = EntityGetFirstComponentIncludingDisabled( action, \"ItemActionComponent\" )\n		if item_action ~= nil then\n			local item = EntityGetFirstComponentIncludingDisabled( action, \"ItemComponent\" )\n			if item ~= nil then\n				if include_permanent_actions == true or ComponentGetValue2( item, \"permanently_attached\" ) == false then\n					if include_frozen_actions == true or ComponentGetValue2( item, \"is_frozen\" ) == false then\n						EntityRemoveFromParent( action )\n						EntitySetComponentsWithTagEnabled( action,  \"enabled_in_world\", true )\n						EntitySetComponentsWithTagEnabled( action,  \"enabled_in_hand\", false )\n						EntitySetComponentsWithTagEnabled( action,  \"enabled_in_inventory\", false )\n						EntitySetComponentsWithTagEnabled( action,  \"item_unidentified\", false )\n						EntitySetTransform( action, x, y )\n						return action\n					end\n				end\n			end\n		end\n	end\nend\n\nfunction WANDS.wand_lock( wand, lock_spells, lock_wand )\n	if lock_spells == nil then lock_spells = true end\n	if lock_wand == nil then lock_wand = true end\n	if lock_spells then\n		local children = EntityGetAllChildren( wand, \"card_action\" ) or {}\n		for i,action in ipairs( children ) do\n			local item = EntityGetFirstComponentIncludingDisabled( action, \"ItemComponent\" )\n			if item ~= nil then\n				ComponentSetValue2( item, \"is_frozen\", true )\n			end\n		end\n	end\n	if lock_wand then\n		local item = EntityGetFirstComponentIncludingDisabled( wand, \"ItemComponent\" )\n		if item ~= nil then\n			ComponentSetValue2( item, \"is_frozen\", true )\n		end\n	end\nend\n\nfunction WANDS.wand_attach_action( wand, action, permanent, locked )\n	EntityAddChild( wand, action )\n	local item_action = EntityGetFirstComponentIncludingDisabled( action, \"ItemActionComponent\" )\n	if item_action ~= nil then\n		EntitySetComponentsWithTagEnabled( action,  \"enabled_in_world\", false )\n		EntitySetComponentsWithTagEnabled( action,  \"enabled_in_hand\", false )\n		EntitySetComponentsWithTagEnabled( action,  \"enabled_in_inventory\", false )\n	end\nend\n\nfunction WANDS.wand_is_always_cast_valid( wand )\n	local children = EntityGetAllChildren( wand, \"card_action\" ) or {}\n	for i,v in ipairs( children ) do\n		local items = EntityGetComponentIncludingDisabled( v, \"ItemComponent\" )\n		local has_a_valid_spell = false\n		for _,item in pairs( items or {}) do\n			if ComponentGetValue2( item, \"permanently_attached\" ) == false then\n				has_a_valid_spell = true\n				break\n			end\n		end\n		if has_a_valid_spell then\n			return true\n		end\n	end\n	return false\nend\n\nfunction WANDS.force_always_cast( wand, amount )\n	if amount == nil then amount = 1 end\n	local children = EntityGetAllChildren( wand, \"card_action\" ) or {}\n	local always_cast_count = 0\n	for _,child in pairs( children ) do\n		local item_component = EntityGetFirstComponentIncludingDisabled( child, \"ItemComponent\" )\n		if item_component then\n			if ComponentGetValue2( item_component, \"permanently_attached\" ) == true then\n				always_cast_count = always_cast_count + 1\n				break\n			end\n		end\n	end\n	while always_cast_count < amount do\n		local random_child = children[ Random( 1,#children ) ]\n		local item_component = EntityGetFirstComponentIncludingDisabled( random_child, \"ItemComponent\" )\n		if item_component and ComponentGetValue2( item_component, \"permanently_attached\" ) ~= true then\n			ComponentSetValue2( item_component, \"permanently_attached\", true )\n			always_cast_count = always_cast_count + 1\n		end\n	end\nend\n	\nreturn WANDS"
_TWWE_VFS["mods/spell_lab_shugged/files/scripts/creative_mode_flight.lua"] = "dofile_once(\"data/scripts/lib/utilities.lua\")\ndofile_once(\"data/scripts/debug/keycodes.lua\")\n\nlocal entity_id = GetUpdatedEntityID()\n\nlocal lerp_speed = 0.60\n\nlocal cp_comp = EntityGetFirstComponent( entity_id, \"CharacterPlatformingComponent\" )\nlocal cd_comp = EntityGetFirstComponent( entity_id, \"CharacterDataComponent\" )\n\nlocal speed = tonumber( ModSettingGet( \"spell_lab_shugged.creative_mode_flight_speed_normal\" ) ) or 200\n\nlocal ctrl = InputIsKeyDown( Key_LCTRL ) or InputIsKeyDown( Key_RCTRL )\nlocal shift = InputIsKeyDown( Key_LSHIFT ) or InputIsKeyDown( Key_RSHIFT )\nif ctrl then\n	speed = tonumber( ModSettingGet( \"spell_lab_shugged.creative_mode_flight_speed_faster\" ) ) or 450\nend\nif shift then\n	local dist = ( tonumber( ModSettingGet( \"spell_lab_shugged.creative_mode_flight_speed_no_clip\" ) ) or 300 ) / 60\n	component_read( EntityGetFirstComponent( entity_id, \"ControlsComponent\" ),\n		{ mButtonDownDown = false, mButtonDownUp = false, mButtonDownLeft = false, mButtonDownRight = false }, function( controls_comp )\n		local x, y = EntityGetTransform( entity_id )\n		if controls_comp.mButtonDownDown and controls_comp.mButtonDownUp then\n			ComponentSetValue2( cd_comp, \"is_on_ground\", true )\n		elseif controls_comp.mButtonDownDown then\n			y = y + dist\n		elseif controls_comp.mButtonDownUp then\n			y = y - dist\n		end\n		if controls_comp.mButtonDownLeft and controls_comp.mButtonDownRight then\n		elseif controls_comp.mButtonDownLeft then\n			x = x - dist\n		elseif controls_comp.mButtonDownRight then\n			x = x + dist\n		end\n		EntityApplyTransform( entity_id, x, y )\n	end )\n	speed = 0\nelse\n	component_read( EntityGetFirstComponent( entity_id, \"ControlsComponent\" ),\n		{ mButtonDownDown = false, mButtonDownUp = false }, function( controls_comp )\n		if not cd_comp then return end\n		local vx, vy = ComponentGetValue2( cd_comp, \"mVelocity\" )\n		local desired_vy = 0\n		if controls_comp.mButtonDownUp and controls_comp.mButtonDownDown then\n			ComponentSetValue2( cd_comp, \"is_on_ground\", true )\n		elseif controls_comp.mButtonDownDown then\n			desired_vy = desired_vy + speed\n		elseif controls_comp.mButtonDownUp then\n			desired_vy = desired_vy - speed\n		end\n		ComponentSetValue2( cd_comp, \"mVelocity\", vx, lerp( vy, desired_vy, lerp_speed ) )\n	end )\nend\nif cd_comp then\n	ComponentSetValue2( cd_comp, \"mFlyingTimeLeft\", ComponentGetValue2( cd_comp, \"fly_time_max\" ) )\nend\nif cp_comp then\n	ComponentSetValue2( cp_comp, \"pixel_gravity\", 0 )\n	ComponentSetValue2( cp_comp, \"velocity_max_x\", speed )\n	ComponentSetValue2( cp_comp, \"velocity_max_y\", speed )\n	ComponentSetValue2( cp_comp, \"velocity_min_x\", -speed )\n	ComponentSetValue2( cp_comp, \"velocity_min_y\", -speed )\n	ComponentSetValue2( cp_comp, \"run_velocity\", speed )\n	ComponentSetValue2( cp_comp, \"fly_velocity_x\", speed )\n	ComponentSetValue2( cp_comp, \"fly_speed_max_up\", speed )\n	ComponentSetValue2( cp_comp, \"fly_speed_max_down\", speed )\nend\nlocal dm_comp = EntityGetFirstComponent( entity_id, \"DamageModelComponent\" )\nif dm_comp then\n	local air_in_lungs_max = ComponentGetValue2( dm_comp, \"air_in_lungs_max\" )\n	ComponentSetValue2( dm_comp, \"air_in_lungs\", air_in_lungs_max )\nend"
_TWWE_VFS["mods/spell_lab_shugged/files/scripts/player_shot.lua"] = "function shot( proj_id )\n	EntityAddTag( proj_id, \"spell_lab_shugged_player_projectile\" )\nend"
_TWWE_VFS["mods/spell_lab_shugged/files/scripts/player_update.lua"] = "local entity_id = GetUpdatedEntityID()\n\nlocal mod_setting_prefix = \"spell_lab_shugged.\"\n\nsettings = settings or {}\nif GlobalsGetValue( \"spell_lab_shugged.refresh_player_state\", \"0\" ) == \"1\" then\n	settings = {}\n	GlobalsSetValue( \"spell_lab_shugged.refresh_player_state\", \"0\" )\nend\n\non_setting_turning_on = on_setting_turning_on or function( setting_name )\n	local result = not settings[ setting_name ] and ModSettingGet( mod_setting_prefix .. setting_name )\n	if result then\n		settings[ setting_name ] = true\n	end\n	return result\nend\non_setting_turning_off = on_setting_turning_off or function( setting_name )\n	local result = settings[ setting_name ] and not ModSettingGet( mod_setting_prefix .. setting_name )\n	if result then\n		settings[ setting_name ] = false\n	end\n	return result\nend\n\nif settings[ \"no_polymorphing\" ] == nil then\n	settings[ \"no_polymorphing\" ] = EntityGetWithName( \"spell_lab_shugged_no_polymorphing\" ) ~= 0\nend\n\nif on_setting_turning_on( \"no_polymorphing\" ) then\n	local effect_entity = EntityCreateNew( \"spell_lab_shugged_no_polymorphing\" )\n	EntityAddChild( entity_id, effect_entity )\n	EntityAddComponent2( effect_entity, \"InheritTransformComponent\" )\n	EntityAddComponent2( effect_entity, \"GameEffectComponent\", {\n		effect = \"PROTECTION_POLYMORPH\",\n		frames = -1,\n	} )\nelseif on_setting_turning_off( \"no_polymorphing\" ) then\n	EntityKill( EntityGetWithName( \"spell_lab_shugged_no_polymorphing\" ) )\nend\n\nif settings[ \"invincible\" ] == nil then\n	settings[ \"invincible\" ] = EntityGetWithName( \"spell_lab_shugged_invincible\" ) ~= 0\nend\n\nif on_setting_turning_on( \"invincible\" ) then\n	local effect_entity = EntityCreateNew( \"spell_lab_shugged_invincible\" )\n	EntityAddChild( entity_id, effect_entity )\n	EntityAddComponent2( effect_entity, \"InheritTransformComponent\" )\n	EntityAddComponent2( effect_entity, \"GameEffectComponent\", {\n		effect = \"PROTECTION_ALL\",\n		frames = -1,\n	} )\nelseif on_setting_turning_off( \"invincible\" ) then\n	EntityKill( EntityGetWithName( \"spell_lab_shugged_invincible\" ) )\nend\n\nif settings[ \"disable_toxic_statuses\" ] == nil then\n	settings[ \"disable_toxic_statuses\" ] = EntityHasTag( entity_id, \"glue_NOT\" )\nend\n\nif on_setting_turning_on( \"disable_toxic_statuses\" ) then\n	EntityAddTag( entity_id, \"glue_NOT\" )\nelseif on_setting_turning_off( \"disable_toxic_statuses\" ) then\n	EntityRemoveTag( entity_id, \"glue_NOT\" )\nend\n\n-- broad-spectrum protection\nif ModSettingGet( mod_setting_prefix .. \"disable_toxic_statuses\" ) then\n	local toxic_game_effects = {\n		TELEPORTATION          = true,\n		UNSTABLE_TELEPORTATION = true,\n		BLINDNESS              = true,\n		CONFUSION              = true,\n		MOVEMENT_SLOWER        = true,\n		FROZEN                 = true,\n		ELECTROCUTION          = true,\n	}\n	local frozen = nil\n	for _, child_id in ipairs( EntityGetAllChildren( entity_id ) or {} ) do\n		if EntityHasTag( child_id, \"spell_lab_shugged_non_toxic_status\" ) then goto continue end\n\n		local effect_comp = EntityGetFirstComponentIncludingDisabled( child_id, \"GameEffectComponent\" )\n		if not effect_comp then goto continue end\n\n		local game_effect_id = ComponentGetValue2( effect_comp, \"effect\" )\n		if not toxic_game_effects[ game_effect_id ] then goto continue end\n\n		ComponentSetValue2( effect_comp, \"disable_movement\", false )\n		if ComponentGetValue2( effect_comp, \"frames\" ) > 1 then\n			ComponentSetValue2( effect_comp, \"frames\", 1 )\n		end\n		::continue::\n	end\nend\n\nif settings[ \"creative_mode_flight\" ] == nil then\n	settings[ \"creative_mode_flight\" ] = EntityGetWithName( \"spell_lab_shugged_flight_overwritten_values\" ) ~= 0\nend\n\nflight_overwritten_fields = flight_overwritten_fields or {\n	\"run_velocity\",\n	\"fly_velocity_x\",\n	\"fly_speed_max_up\",\n	\"fly_speed_max_down\",\n	\"velocity_max_x\",\n	\"velocity_max_y\",\n}\nflight_overwritten_fields2 = flight_overwritten_fields2 or {\n	velocity_min_x = -200,\n	velocity_min_y = -200,\n	pixel_gravity = 0,\n	swim_idle_buoyancy_coeff = 0,\n	swim_down_buoyancy_coeff = 0,\n	swim_up_buoyancy_coeff = 0,\n	fly_speed_change_spd = 0,\n	swim_drag = 1,\n	swim_extra_horizontal_drag = 1,\n}\n\nlocal flight_comp = EntityGetFirstComponentIncludingDisabled( entity_id, \"LuaComponent\", \"spell_lab_shugged_creative_mode_flight\" )\n	or EntityAddComponent2( entity_id, \"LuaComponent\", {\n		_tags = \"spell_lab_shugged_creative_mode_flight\",\n		_enabled = false,\n		script_source_file = \"mods/spell_lab_shugged/files/scripts/creative_mode_flight.lua\",\n		execute_every_n_frame = 1,\n	} )\n\nif on_setting_turning_on( \"creative_mode_flight\" ) then\n	local cp_comp = EntityGetFirstComponentIncludingDisabled( entity_id, \"CharacterPlatformingComponent\" )\n	if cp_comp then\n		local values_entity = EntityLoad( \"mods/spell_lab_shugged/files/entities/flight_overwritten_values.xml\" )\n		EntityAddChild( entity_id, values_entity )\n		local values_comp = EntityGetFirstComponentIncludingDisabled( values_entity, \"CharacterPlatformingComponent\" )\n		for _, field_name in ipairs( flight_overwritten_fields ) do\n			ComponentSetValue2( values_comp, field_name, ComponentGetValue2( cp_comp, field_name ) )\n			ComponentSetValue2( cp_comp, field_name, 200 )\n		end\n		for field_name, value in pairs( flight_overwritten_fields2 ) do\n			ComponentSetValue2( values_comp, field_name, ComponentGetValue2( cp_comp, field_name ) )\n			ComponentSetValue2( cp_comp, field_name, value )\n		end\n	end\n	EntitySetComponentIsEnabled( entity_id, flight_comp, true )\nelseif on_setting_turning_off( \"creative_mode_flight\" ) then\n	local cp_comp = EntityGetFirstComponentIncludingDisabled( entity_id, \"CharacterPlatformingComponent\" )\n	if cp_comp then\n		local values_entity = EntityGetWithName( \"spell_lab_shugged_flight_overwritten_values\" )\n		if values_entity ~= 0 then\n			local values_comp = EntityGetFirstComponentIncludingDisabled( values_entity, \"CharacterPlatformingComponent\" )\n			for _, field_name in ipairs( flight_overwritten_fields ) do\n				ComponentSetValue2( cp_comp, field_name, ComponentGetValue2( values_comp, field_name ) )\n			end\n			for field_name, _ in pairs( flight_overwritten_fields2 ) do\n				ComponentSetValue2( cp_comp, field_name, ComponentGetValue2( values_comp, field_name ) )\n			end\n			EntityKill( values_entity )\n		end\n	end\n	EntitySetComponentIsEnabled( entity_id, flight_comp, false )\nend\n\nif settings[ \"better_all_seeing_eye\" ] == nil then\n	settings[ \"better_all_seeing_eye\" ] = EntityGetWithName( \"spell_lab_shugged_better_all_seeing_eye\" ) ~= 0\nend\n\nif on_setting_turning_on( \"better_all_seeing_eye\" ) then\n	EntityAddChild( entity_id, EntityLoad( \"mods/spell_lab_shugged/files/entities/better_all_seeing_eye.xml\" ) )\nelseif on_setting_turning_off( \"better_all_seeing_eye\" ) then\n	EntityKill( EntityGetWithName( \"spell_lab_shugged_better_all_seeing_eye\" ) )\nend"
_TWWE_VFS["mods/spell_lab_shugged/files/scripts/remove_toxic_effect.lua"] = "if not ModSettingGet( \"spell_lab_shugged.disable_toxic_statuses\" ) then return end\n\nlocal tag = \"spell_lab_shugged.about_to_remove_toxic_status\"\n\nlocal entity_id = GetUpdatedEntityID()\n\nif not EntityHasTag( entity_id, tag ) then\n	ComponentSetValue2( GetUpdatedComponentID(), \"mNextExecutionTime\", GameGetFrameNum() )\n	EntityAddTag( entity_id, tag )\n	return\nend\n\nif not EntityHasTag( EntityGetParent( entity_id ), \"player_unit\" ) then return end\n\nEntityRemoveFromParent( entity_id )\nEntitySetTransform( entity_id, 14600, -8000 )\nEntityApplyTransform( entity_id, 14600, -8000 )\nEntityKill( entity_id )\n\nEntityRemoveComponent( entity_id, GetUpdatedComponentID() )\n"
_TWWE_VFS["mods/spell_lab_shugged/files/scripts/toxic_effect_entities.lua"] = "-- specific protection\ntoxic_effect_entities = {\n	\"data/entities/misc/effect_confusion.xml\",\n	\"data/entities/misc/effect_drunk.xml\",\n	\"data/entities/misc/effect_drunk_01.xml\",\n	\"data/entities/misc/effect_teleportation_enemy.xml\",\n	\"data/entities/misc/effect_teleportation.xml\",\n	\"data/entities/misc/effect_unstable_teleportation.xml\",\n}"
_TWWE_VFS["mods/spell_lab_shugged/files/scripts/transform_mortal_into_dummy.lua"] = "local error_msg = nil\nlocal mx, my = DEBUG_GetMouseWorld()\nlocal mortal_id = EntityGetClosestWithTag( mx, my, \"mortal\" )\nlocal mortal_x, mortal_y = EntityGetTransform( mortal_id )\nif not is_valid_entity( mortal_id ) or ( mx - mortal_x ) ^ 2 + ( my - mortal_y ) ^ 2 > 1600 then\n	mortal_id = EntityGetClosestWithTag( mx, my, \"enemy\" )\n	mortal_x, mortal_y = EntityGetTransform( mortal_id )\n	if not is_valid_entity( mortal_id ) or ( mx - mortal_x ) ^ 2 + ( my - mortal_y ) ^ 2 > 1600 then\n		error_msg = text_get_translated( \"transform_mortal_failed_no_mortal_found\" )\n	end\nend\nif EntityHasTag( mortal_id, \"player_unit\" ) or EntityHasTag( mortal_id, \"polymorphed_player\" ) then\n	error_msg = text_get_translated( \"transform_mortal_failed_cant_transform_player\" )\nend\nif EntityHasTag( mortal_id, \"spell_lab_shugged_target_dummy\" ) then\n	error_msg = text_get_translated(  \"transform_mortal_failed_already_transformed\" )\nend\nif not error_msg then\n	-- GameDropAllItems( mortal_id )\n	local comp_names_to_disable = {\n		\"AnimalAIComponent\",\n		\"PhysicsAIComponent\",\n		\"FishAIComponent\",\n		\"AdvancedFishAIComponent\",\n		\"BossDragonComponent\",\n		\"WormComponent\",\n		\"WormAIComponent\",\n		\"BossHealthBarComponent\",\n		\"CameraBoundComponent\",\n	}\n	for _, comp_name in ipairs( comp_names_to_disable ) do\n		for _, c in ipairs( EntityGetComponent( mortal_id, comp_name ) or {} ) do\n			EntitySetComponentIsEnabled( mortal_id, c, false )\n		end\n	end\n	for _, ctrl_comp in ipairs( EntityGetComponentIncludingDisabled( mortal_id, \"ControlsComponent\" ) or {} ) do\n		ComponentSetValue2( ctrl_comp, \"enabled\", false )\n	end\n	local cp_comp = EntityGetFirstComponentIncludingDisabled( mortal_id, \"CharacterPlatformingComponent\" )\n	if cp_comp then\n		for _, field_name in ipairs( {\n			\"velocity_min_x\",\n			\"velocity_min_y\",\n			\"velocity_max_x\",\n			\"velocity_max_y\",\n			\"pixel_gravity\",\n			\"run_velocity\",\n			\"fly_velocity_x\",\n			\"fly_speed_up\",\n			\"fly_speed_down\",\n		} ) do\n			ComponentSetValue2( cp_comp, field_name, 0 )\n		end\n	end\n	local cd_comp = EntityGetFirstComponentIncludingDisabled( mortal_id, \"CharacterDataComponent\" )\n	if cd_comp then\n		ComponentSetValue2( cd_comp, \"mVelocity\", 0, 0 )\n	end\n	for _, pbody_id in ipairs( PhysicsBodyIDGetFromEntity( mortal_id ) ) do\n		PhysicsBodyIDSetGravityScale( pbody_id, 0 )\n		local x, y, a = PhysicsBodyIDGetTransform( pbody_id )\n		PhysicsBodyIDSetTransform( pbody_id, x, y, a, 0, 0 )\n	end\n	local dm_comp = EntityGetFirstComponentIncludingDisabled( mortal_id, \"DamageModelComponent\" )\n	if dm_comp then\n		ComponentSetValue2( dm_comp, \"wait_for_kill_flag_on_death\", true )\n	end\n	dm_comp = EntityGetFirstComponent( mortal_id, \"DamageModelComponent\" )\n	if dm_comp then\n		ComponentSetValue2( dm_comp, \"wait_for_kill_flag_on_death\", true )\n	end\n	EntityAddComponent2( mortal_id, \"LuaComponent\", {\n		_tags=\"enabled_in_world\",\n		script_source_file = \"mods/spell_lab_shugged/files/scripts/transformed_mortal_update.lua\",\n		execute_every_n_frame = 1,\n	} )\n	EntityLoadToEntity( \"mods/spell_lab_shugged/files/entities/dummy_target/base_dummy_target.xml\", mortal_id )\n	EntityAddTag( mortal_id, \"spell_lab_shugged_target_dummy\" )\n	GamePrint( GameTextGet( wrap_key( \"transform_mortal_succeeded\" ), GameTextGetTranslatedOrNot( EntityGetName( mortal_id ) ) ) )\nelse\n	GamePrint( error_msg )\nend"
_TWWE_VFS["mods/spell_lab_shugged/files/scripts/transformed_mortal_update.lua"] = "for _, pbody_id in ipairs( PhysicsBodyIDGetFromEntity( GetUpdatedEntityID() ) ) do\n	local x, y, a = PhysicsBodyIDGetTransform( pbody_id )\n	PhysicsBodyIDSetTransform( pbody_id, x, y, a, 0, 0 )\nend"
_TWWE_VFS["mods/spell_lab_shugged/files/translations.csv"] = ",en,ru,pt-br,es-es,de,fr-fr,it,pl,zh-cn,jp,ko,,NOTES ¡§C use \\n for newline,max length\nspell_lab_shugged_enable,Enable ,,,,,,,,开 ,,,,,\nspell_lab_shugged_disable,Disable ,,,,,,,,关 ,,,,,\nspell_lab_shugged_enable2,Enable,,,,,,,,启用,,,,,\nspell_lab_shugged_disable2,Disable,,,,,,,,禁用,,,,,\nspell_lab_shugged_show_spell_lab,Show Spell Lab,,,,,,,,显示法术实验室,,,,,\nspell_lab_shugged_hide_spell_lab,Hide Spell Lab,,,,,,,,隐藏法术实验室,,,,,\nspell_lab_shugged_speed_multiplier,Proj. Speed,,,,,,,,投射物速度倍数,,,,,\nspell_lab_shugged_dummy_target_interact,Press [E] to remove this dummy target,,,,,,,,按 [E] 删除假人,,,,,\nspell_lab_shugged_enter_spell_lab,Enter the Spell Lab,,,,,,,,进入法术实验室,,,,,\nspell_lab_shugged_leave_spell_lab,Leave the Spell Lab\\nShift + Left-click to return to the mines intrance,,,,,,,,离开法术实验室\\nShift + 左键返回矿井入口,,,,,\nspell_lab_shugged_reload_spell_lab,Right-click to fix spell lab,,,,,,,,右键修复法术实验室,,,,,\nspell_lab_shugged_spell_picker,Spell Picker,,,,,,,,选取法术,,,,,\nspell_lab_shugged_wand_spawner,Wand Picker,,,,,,,,法杖生成器,,,,,\nspell_lab_shugged_wand_box,Wand Box,,,,,,,,法杖仓库,,,,,\nspell_lab_shugged_spell_group_box,Spell Group Box,,,,,,,,法术组合仓库,,,,,\nspell_lab_shugged_shot_effects,Shot Effects,,,,,,,,射击效果,,,,,\nspell_lab_shugged_toggle_options,Toggle Options,,,,,,,,开关类选项,,,,,\nspell_lab_shugged_wand_force_compact,Force Compact,,,,,,,,强制紧凑,,,,,\nspell_lab_shugged_wand_force_compact_description,\"When enabled, in inventory spells are guaranteed compactly aligned,\\nno matter how they are laid out in the wand edit panel\",,,,,,,,开启后，无论法杖编辑面板中如何排列，法杖中法术总是排列紧凑,,,,,\nspell_lab_shugged_inventory_get_ignored,Note: Enabling this will make edit panel ignore changes made in vanilla inventory.,,,,,,,,注意：启用此功能将使编辑面板无视原版背包中的更改,,,,,\nspell_lab_shugged_no_enough_space,Spell Insertion Failed: No enough space in wand,,,,,,,,插入法术失败：法杖中没有足够的空间,,,,,\nspell_lab_shugged_spell_replacement,Spell Replacement Mode,,,,,,,,法术替换模式,,,,,\nspell_lab_shugged_spell_replacement_tips,\"Works with Quick Spell Picker option and Spell Group Box.\\nWhen enabled, spells will be put into wand by replacing\\nWhen disabled, spells will be put into wand by inserting.\\nHold $0 to apply the other way to put spells temporarily.\\nTips: When inserting,\\n    left-click to insert to the right\\n    right-click to insert to the left\",,,,,,,,该选项影响快速装填和法术组合仓库。\\n开启时，放置法术操作以替换原有法术方式执行。\\n关闭时，放置法术操作以插入原有法术之间方式执行。\\n按住 $0 可暂时使用另一种执行方式。\\n提示：插入法术时，左键插入选中格的右边，右键插入选中格的左边。,,,,,\nspell_lab_shugged_zero_uses,0 Uses,,,,,,,,初始使用次数归零,,,,,\nspell_lab_shugged_automatic_capacity,Automatic Capacity,,,,,,,,自动调整容量,,,,,\nspell_lab_shugged_automatic_capacity_description,\"When enabled, the number of slots in the wand edit panel\\nis not limited by the actual capacity of the wand\\nNote: If there are no spells in the wand, the wand's capacity will be adjusted to 0,\\nmaking the wand not shown in the vanilla inventory.\\nThis is normal, just continue to edit the wand with automatic capacity enabled.\",,,,,,,,开启时，法杖编辑面板按最大行数显示，同时法杖的实际容量自动调整至恰好容下其中法术\\n注意：如果法杖中没有法术，法杖的容量会被调整为0，使之无法在原版背包中显示\\n此为正常现象，继续使用自动调整容量编辑法杖即可,,,,,\nspell_lab_shugged_wand_edit_panel,Wand Edit Panel,,,,,,,,法杖编辑面板,,,,,\nspell_lab_shugged_clear_projectiles,Clear Projectile,,,,,,,,清除投射物,,,,,\nspell_lab_shugged_wand_ready,Clear Cast Delay / Recharge Time,,,,,,,,清除当前施放延迟/充能时间,,,,,\nspell_lab_shugged_wand_ready_description,Shift + Left-click to fix cast delay & recharge time to the values of held wand\\nShift + Right-click to fix cast delay & recharge time to 0\\nAlt + click to fix cast delay & recharge time of all wands to their raw values,,,,,,,,Shift + 左键锁定施放延迟/充能时间为当前法杖数值\\nShift + 右键锁定施放延迟/充能时间为 0\\nAlt + 点击锁定所有法杖施放延迟/充能时间为其面板原始值,,,,,\nspell_lab_shugged_wand_cast_delay_fixed_to,The cast delays of your wands are fixed to $0\\nThe reload times of your wands are fixed to $1\\nRight-click to unfix them,,,,,,,,施放延迟已锁定为 $0\\n充能时间已锁定为 $1\\n右击取消锁定,,,,,\nspell_lab_shugged_wand_raw_value,Raw value of wand,,,,,,,,法杖原始值,,,,,\nspell_lab_shugged_hp_fixed_to,Your HP is fixed to $0 / $1\\nRight-click to unfix it,,,,,,,,你的生命值已锁定为 $0 / $1\\n右键取消锁定,,,,,\nspell_lab_shugged_full_hp,Completely heal\\nShift + Click to fix your hp,,,,,,,,完全回复生命值\\nShift + 点击锁定生命值,,,,,\nspell_lab_shugged_clear_held_wand,Clear Held Wand,,,,,,,,清空当前法杖,,,,,\nspell_lab_shugged_edit_wands_perk_positive,TEWE,,,,,,,,随时编辑魔杖,,,,,\nspell_lab_shugged_edit_wands_perk_negative,NWT,,,,,,,,无法编辑魔杖,,,,,\nspell_lab_shugged_edit_wands_gain,Gain one $0 effect,,,,,,,,获得一层$0效果,,,,,\nspell_lab_shugged_edit_wands_lose,Right-click to lose one $0 effect,,,,,,,,右键失去一层$0效果,,,,,\nspell_lab_shugged_edit_wands_num,You have $1(from this mod) + $2(external) $0 effect(s),,,,,,,,当前你拥有 $1(来自此功能) + $2(其他来源) 层$0效果,,,,,\nspell_lab_shugged_edit_wands_level,Your current wand editing level is $0,,,,,,,,你当前的法杖编辑等级为 $0,,,,,\nspell_lab_shugged_edit_wands_everywhere,You can edit wands everywhere,,,,,,,,你可以随时编辑魔杖,,,,,\nspell_lab_shugged_edit_wands_workshop,You can only edit wands in workshops(i.e. holy mountains),,,,,,,,你可以在圣山中编辑魔杖,,,,,\nspell_lab_shugged_edit_wands_unable,You can't edit wands,,,,,,,,你无法编辑魔杖,,,,,\nspell_lab_shugged_target_dummy_numbers_are,Those numbers are: ,,,,,,,,所显示数字的含义分别为：,,,,,\nspell_lab_shugged_target_dummy_last_frame_damage,Most Recent Damage,,,,,,,,最近一次伤害,,,,,\nspell_lab_shugged_target_dummy_average_dps,Average DPS,,,,,,,,平均 DPS,,,,,\nspell_lab_shugged_target_dummy_total_damage,Total Damage,,,,,,,,总伤害,,,,,\nspell_lab_shugged_target_dummy_dps,DPS,,,,,,,,DPS,,,,,\nspell_lab_shugged_target_dummy_highest_dps,Highest DPS,,,,,,,,最高 DPS,,,,,\nspell_lab_shugged_spawn_target_dummy,Spawn Target Dummy,,,,,,,,生成伤害测试假人,,,,,\nspell_lab_shugged_spawn_target_dummy_description,Right-click to spawn boss target dummy,,,,,,,,右键生成 Boss 级伤害测试假人,,,,,\nspell_lab_shugged_transform_mortal_into_target_dummy,Creature to Target Dummy,,,,,,,,转化生物为伤害测试假人,,,,,\nspell_lab_shugged_transform_mortal_into_target_dummy_description,Click this button and then press $0 to transform the creature closest to your mouse position,,,,,,,,点击此按钮后，按 $0 转化离鼠标指针最近的生物,,,,,\nspell_lab_shugged_transform_mortal_succeeded,Transformed $0 into a target dummy,,,,,,,,已将 $0 转化为伤害测试假人,,,,,\nspell_lab_shugged_transform_mortal_failed_no_mortal_found,Error: No creature found near your mouse position,,,,,,,,错误：鼠标指针附近没有合适的生物,,,,,\nspell_lab_shugged_transform_mortal_failed_cant_transform_player,Error: Unable to transform yourself into a target dummy,,,,,,,,错误：无法将玩家转化为伤害测试假人,,,,,\nspell_lab_shugged_transform_mortal_failed_already_transformed,Error: Unable to transform a target dummy into a target dummy,,,,,,,,错误：无法将伤害测试假人转化为伤害测试假人,,,,,\nspell_lab_shugged_spawn_best_wand,Spawn Convenient Wand,,,,,,,,一键生成神杖,,,,,\nspell_lab_shugged_spawn_best_wand_description,Right-click to replace held wand with convenient wand,,,,,,,,右键替换手中法杖为神杖,,,,,\nspell_lab_shugged_disable_casting,No Shooting,,,,,,,,禁止法杖射击,,,,,\nspell_lab_shugged_disable_toxic_statuses,No Toxic Statuses,,,,,,,,免疫部分负面效果,,,,,\nspell_lab_shugged_disable_toxic_statuses_description,\"Immunity from (unstable) teleportisis, blindness, confusion, slower movement,\\nfrozen, electrocution, drunk and glued\",,,,,,,,免疫（不稳）传送、致盲、混乱、更慢移动、冻结、电击、醉酒、胶粘,,,,,\nspell_lab_shugged_force_2gcedge,Force 2GC + Edge,,,,,,,,双玻璃大炮 + 刀尖舔血,,,,,\nspell_lab_shugged_no_recoil,No recoil,,,,,,,,无后坐力,,,,,\nspell_lab_shugged_damage_info,Damage Info,,,,,,,,伤害数值显示,,,,,\nspell_lab_shugged_creative_mode_flight,Superflight,,,,,,,,超级飞行,,,,,\nspell_lab_shugged_creative_mode_flight_description,\"Hold Ctrl to fly faster. Hold Shift to fly through walls.\\nUnfortunately, holding Ctrl and Shift at the same time does not make you fly through walls faster,\\nbecause Ctrl + Shift + S and Ctrl + Shift + W has been taken by Component Explorer mod\",,,,,,,,按住 Ctrl 以更快的速度飞行，按住 Shift 可以穿墙飞行\\n遗憾的是，同时按住 Ctrl 和 Shift 并不能让你以更快的速度穿墙飞行，\\n因为组件浏览器模组已经占用了 Ctrl + Shift + S 和 Ctrl + Shift + W。,,,,,\nspell_lab_shugged_creative_mode_flight_note_dev_exe,\"Also note that in Debug mode holding Ctrl doesn't do anything\",,,,,,,,此外请注意，如果开启游戏的 Debug 模式，按住 Ctrl 只会使你停下。,,,,,\nspell_lab_shugged_wand_box_save,Save Held Wand,,,,,,,,保存手持法杖,,,,,\nspell_lab_shugged_wand_box_save_reached_page_limit,The number of wands on this page has reached the maximum of 100,,,,,,,,本页法杖数量已达上限,,,,,\nspell_lab_shugged_wand_box_delete,Delete Selected Wand,,,,,,,,删除所选法杖,,,,,\nspell_lab_shugged_wand_box_no_wand_selected,No Wand Selected,,,,,,,,当前没有选中法杖,,,,,\nspell_lab_shugged_wand_box_load_to_hand,Load Selected Wand Into Held Wand,,,,,,,,加载所选法杖至手持法杖,,,,,\nspell_lab_shugged_wand_box_load_to_world,Load Selected Wand Into World,,,,,,,,生成所选法杖,,,,,\nspell_lab_shugged_wand_box_hold_something_to_show_wand_stats,Hold $0 to show wand stats,,,,,,,,按住 $0 显示法杖属性,,,,,\nspell_lab_shugged_wand_box_last_page,Last Page,,,,,,,,上一页,,,,,\nspell_lab_shugged_wand_box_next_page,Next Page,,,,,,,,下一页,,,,,\nspell_lab_shugged_wand_box_no_last_page,No Last Page,,,,,,,,已在第一页,,,,,\nspell_lab_shugged_wand_box_no_next_page,No Next Page,,,,,,,,已在最后一页,,,,,\nspell_lab_shugged_wand_box_new_page,Create New Page,,,,,,,,新建仓库页,,,,,\nspell_lab_shugged_wand_box_delete_page,Delete Page $0,,,,,,,,删除第 $0 页,,,,,\nspell_lab_shugged_wand_box_current_page,Current: $0 / $1,,,,,,,,当前： $0 / $1,,,,,\nspell_lab_shugged_wand_picker_spawn_wand,[Spawn],,,,,,,,[生成法杖],,,,,\nspell_lab_shugged_wand_picker_copy_held_wand,[Copy Held Wand],,,,,,,,[复制手持法杖],,,,,\nspell_lab_shugged_wand_picker_update_held_wand,[Update Held Wand],,,,,,,,[更新手持法杖],,,,,\nspell_lab_shugged_wand_picker_precise_mode,[$0Precise Mode],,,,,,,,[$0精确调整],,,,,\nspell_lab_shugged_wand_picker_precise_mode_tips,\"Tips: Left/right clicking on a value increases/decreases the stat by the value\",,,,,,,,提示：左键/右键点击数值可以使相应的属性增加/减少这个数值,,,,,\nspell_lab_shugged_wand_picker_exploding_actions,The capacity you are setting for your wand is not enough for holding the spells in it. Hold $0 and click again to confirm.,,,,,,,,当前设置的法杖容量不足以容纳法杖中法术，若仍要继续，请按住 $0 并再次点击,,,,,\nspell_lab_shugged_quick_spell_picker,Quick Spell Picker,,,,,,,,快速装填,,,,,\nspell_lab_shugged_show_locked_spells,Show Locked Spells,,,,,,,,显示未解锁法术,,,,,\nspell_lab_shugged_spell_group_box_save,Save Selected Spells As A Group,,,,,,,,保存所选法术为组合,,,,,\nspell_lab_shugged_spell_group_box_delete,Delete Selected Spell Group,,,,,,,,删除所选法术组合,,,,,\nspell_lab_shugged_spell_group_box_load,Load Selected Spell Group Into Held Wand,,,,,,,,加载所选法术组合至法杖,,,,,\nspell_lab_shugged_spell_group_select,Left-click to select this spell group,,,,,,,,左键选择该法术组合,,,,,\nspell_lab_shugged_damage_info_dps,Damage Per Second: ,,,,,,,,每秒伤害：,,,,,\nspell_lab_shugged_damage_info_total_damage,Total Damage: ,,,,,,,,总伤害：,,,,,\nspell_lab_shugged_damage_info_total_projectile_damage,Total Projectile Damage: ,,,,,,,,总投射物伤害：,,,,,\nspell_lab_shugged_damage_info_total_projectiles_num,Total Projectiles: ,,,,,,,,总投射物数量：,,,,,\nspell_lab_shugged_action_added_to_inventory,$0 added to your inventory,,,,,,,,法术 $0 已放入你的物品栏,,,,,\nspell_lab_shugged_spell_box_commmon_tips,$0 to select this slot,,,,,,,,$0选择该法术槽,,,,,\nspell_lab_shugged_spell_box_commmon_tips_selected,$0 to deselect this slot,,,,,,,,$0取消选择该法术槽,,,,,\nspell_lab_shugged_spell_box_permanent_tips,$0 to demote this spell,,,,,,,,$0以取消始终施放,,,,,\nspell_lab_shugged_demotion_no_space,Spell Demotion Failed: No space for the demoted spell in wand,,,,,,,,取消始终施放失败：法杖中没有空间放置法术,,,,,\nspell_lab_shugged_current_row,Current: $0 / $1,,,,,,,,当前：第 $0 / $1 行,,,,,\nspell_lab_shugged_current_row_autocap,Current: $0,,,,,,,,当前：第 $0 行,,,,,\nspell_lab_shugged_relock_tips,Tips: $0 to relock an unlocked spell,,,,,,,,提示：$0可重新锁定已解锁的法术,,,,,\nspell_lab_shugged_operation_select,Select,,,,,,,,选择,,,,,\nspell_lab_shugged_operation_deselect,Deselect,,,,,,,,取消选择,,,,,\nspell_lab_shugged_operation_set_action,Put Spell(s),,,,,,,,放置法术,,,,,\nspell_lab_shugged_operation_set_action_group,Put Spell Group,,,,,,,,放置法术组合,,,,,\nspell_lab_shugged_operation_read_from_wand,External Wand Operation,,,,,,,,外部法杖操作,,,,,\nspell_lab_shugged_operation_delete_action,Delete Spell(s),,,,,,,,删除法术,,,,,\nspell_lab_shugged_operation_delete_action_slot,Delete Slot(s),,,,,,,,删除法术槽,,,,,\nspell_lab_shugged_operation_demote_permanent_action,Promote Always-cast Spell,,,,,,,,取消始终施放,,,,,\nspell_lab_shugged_operation_promote_permanent_action,Demote Always-cast Spell,,,,,,,,设置始终施放,,,,,\nspell_lab_shugged_operation_swap_actions,Swap Spell(s),,,,,,,,交换法术,,,,,\nspell_lab_shugged_operation_override_actions,Move Spell(s),,,,,,,,移动法术,,,,,\nspell_lab_shugged_operation_duplicate_action,Duplicate Spell(s),,,,,,,,复制法术,,,,,\nspell_lab_shugged_undo,Undo,,,,,,,,撤销,,,,,\nspell_lab_shugged_redo,Redo,,,,,,,,恢复,,,,,\nspell_lab_shugged_cant_undo,Nothing To Undo,,,,,,,,无操作可供撤销,,,,,\nspell_lab_shugged_cant_redo,Nothing To Redo,,,,,,,,无操作可供恢复,,,,,\nspell_lab_shugged_current_history,Current: $0 / $1,,,,,,,,当前：$0 / $1,,,,,\nspell_lab_shugged_gif_mode_enable,Right-click to enable Replay Mode,,,,,,,,右键开启回放模式,,,,,\nspell_lab_shugged_gif_mode_disable,Right-click to disable Replay Mode,,,,,,,,右键关闭回放模式,,,,,\nspell_lab_shugged_shortcut_tips_title,Wand Edit Panel Shortcuts,,,,,,,,法杖编辑面板快捷键,,,,,\nspell_lab_shugged_shortcut_tips,\"{select}: Select\\n{deselect}: Deselect\\n{swap}: \\n    If clicked slot is not selected: swap selected spell(s) to clicked slot\\n    If clicked slot is selected: cycle selected spells\\nThe above shortcuts also work in the wand box and spell group box\\n{multi_select}: Multiple selection\\n{expand_selection_left}: Expand selection on the left side\\n{expand_selection_right}: Expand selection on the right side\\nThe above shortcuts also work in the wand box\\n{override}: move selected spell(s) to clicked slot\\n{duplicate}: Duplicate Spell(s)\\n{delete_action}: Delete spell\\n{delete_slot}: Delete spell and shift following spells left\\n{always_cast}: Promote/Demote always-cast spell\\n{left_delete}: Delete a spell to the left\\n{right_delete}: Delete a spell to the right\\n{undo}: Undo\\n{redo}: Redo\",,,,,,,,{select}：选中\\n{deselect}：取消选中\\n{swap}：\\n    若点击槽位未选中：将已选择法术交换至此处\\n    若点击槽位已选中：轮换已选择法术\\n以上快捷键也可在法杖仓库与法术组合仓库页面使用\\n{multi_select}：选中多个\\n{expand_selection_left}：扩展左边的选区至此处\\n{expand_selection_right}：扩展右边的选区至此处\\n以上快捷键也可在法杖仓库页面使用\\n{override}：将已选择法术移动至此处\\n{duplicate}：复制法术\\n{delete_action}：删除法术\\n{delete_slot}：删除法术并将右侧法术左移\\n{always_cast}：设置/取消始终施放\\n{left_delete}：向左删除法术\\n{right_delete}：向右删除法术\\n{undo}：撤销操作\\n{redo}：恢复操作,,,,,\nspell_lab_shugged_value_set_to,Set to $0,,,,,,,,设置为 $0,,,,,\nspell_lab_shugged_max_uses,Max Uses,,,,,,,,最大使用次数,,,,,\nspell_lab_shugged_draws,Draws,,,,,,,,抽取法术,,,,,\nspell_lab_shugged_degrees,$0 DEG,,,,,,,,$0 度,,,,,\nspell_lab_shugged_frames,$0 f,,,,,,,,$0 帧,,,,,\nspell_lab_shugged_recoil,Recoil,,,,,,,,后座力,,,,,\nspell_lab_shugged_friendly_fire,Friendly Fire,,,,,,,,友方伤害,,,,,\nspell_lab_shugged_gravity,Proj. Gravity,,,,,,,,投射物重力,,,,,\nspell_lab_shugged_lifetime_add,Lifetime Add,,,,,,,,存在时间修正,,,,,\nspell_lab_shugged_lifetime_cap,Lifetime Limit,,,,,,,,存在时间限制,,,,,\nspell_lab_shugged_projectile_nth_data,Projectile #$0,,,,,,,,投射物 #$0,,,,,\nspell_lab_shugged_projectile_num_projectiles,Projectiles,,,,,,,,投射物数量,,,,,\nspell_lab_shugged_projectile_damage_projectile,Dmg. (Projectile),,,,,,,,投射物伤害,,,,,\nspell_lab_shugged_projectile_damage_curse,Dmg. (Curse),,,,,,,,诅咒伤害,,,,,\nspell_lab_shugged_projectile_damage_slice,Dmg. (Slice),,,,,,,,切割伤害,,,,,\nspell_lab_shugged_projectile_damage_melee,Dmg. (Melee),,,,,,,,近战伤害,,,,,\nspell_lab_shugged_projectile_damage_electricity,Dmg. (Electric),,,,,,,,电击伤害,,,,,\nspell_lab_shugged_projectile_damage_explosion,Dmg. (Explosion),,,,,,,,爆炸伤害,,,,,\nspell_lab_shugged_projectile_damage_fire,Dmg. (Fire),,,,,,,,火焰伤害,,,,,\nspell_lab_shugged_projectile_damage_ice,Dmg. (Ice),,,,,,,,冰冻伤害,,,,,\nspell_lab_shugged_projectile_damage_drill,Dmg. (Drill),,,,,,,,穿凿伤害,,,,,\nspell_lab_shugged_projectile_damage_poison,Dmg. (Poison),,,,,,,,紫毒伤害,,,,,\nspell_lab_shugged_projectile_damage_healing,Dmg. (Healing),,,,,,,,治疗伤害,,,,,\nspell_lab_shugged_projectile_damage_radioactive,Dmg. (Radioactive),,,,,,,,绿毒伤害,,,,,\nspell_lab_shugged_projectile_speed,Speed,,,,,,,,速度,,,,,\nspell_lab_shugged_projectile_innate_spread,Spread (Innate),,,,,,,,固有散射,,,,,\nspell_lab_shugged_projectile_explosion_enabled,Expl. Enabled,,,,,,,,启用爆炸,,,,,\nspell_lab_shugged_projectile_explosion_radius,Expl. Radius,,,,,,,,爆炸半径,,,,,\nspell_lab_shugged_projectile_explosion_damage,Expl. Damage,,,,,,,,爆炸伤害,,,,,\nspell_lab_shugged_projectile_gravity,Gravity,,,,,,,,重力,,,,,\nspell_lab_shugged_projectile_air_friction,Friction Coeff,,,,,,,,阻力系数,,,,,\nspell_lab_shugged_projectile_lifetime,Lifetime,,,,,,,,存在时间,,,,,\nspell_lab_shugged_projectile_lifetime_cap,Lifetime Limit,,,,,,,,存在时间限制,,,,,\nspell_lab_shugged_projectile_friendly_fire,Friendly Fire,,,,,,,,友方伤害,,,,,\nspell_lab_shugged_projectile_shooter_collision_protection,Shooter Coll. Prot.,,,,,,,,自伤保护,,,,,\nspell_lab_shugged_projectile_explosion_dont_damage_shooter,Expl. Shooter Prot.,,,,,,,,爆炸无自伤,,,,,\nspell_lab_shugged_projectile_timer_time,Timer Time,,,,,,,,定时时间,,,,,\nspell_lab_shugged_projectile_die_on_low_velocity,Low Speed Limit,,,,,,,,速度底限,,,,,\nspell_lab_shugged_projectile_data,Projectile,,,,,,,,投射物,,,,,\nspell_lab_shugged_spell_data,Spell Data,,,,,,,,法术数据,,,,,\nspell_lab_shugged_spell_picker_tab_types,Spells By Type,,,,,,,,所有法术,,,,,\nspell_lab_shugged_spell_picker_tab_search,Search Spells,,,,,,,,搜索法术,,,,,\nspell_lab_shugged_spell_picker_tab_recent,Recently Used,,,,,,,,最近使用,,,,,\nspell_lab_shugged_spell_picker_tab_recent_tips,Tips: $0 to clear,,,,,,,,提示: $0清空,,,,,\nspell_lab_shugged_spell_picker_tab_in_inv,Inv & Nearby,,,,,,,,背包&附近,,,,,\nspell_lab_shugged_scroll_table_nothing,(nothing here),,,,,,,,（空）,,,,,\nspell_lab_shugged_spell_picker_searchbox,Search Spells by ID..,,,,,,,,搜索法术 ID..,,,,,\nspell_lab_shugged_spell_lab_reloader_interact,Press [E] to fix spell lab,,,,,,,,按 [E] 修复法术实验室,,,,,\nspell_lab_shugged_deletion_confirm_button,$0 + Left-click to confirm deletion\\nLeft-click again to