,,,,,,,使用法杖前请先关闭禁止法杖射击选项,,,,,\n"
_TWWE_VFS["mods/spell_lab_shugged/init.lua"] = "ModLuaFileAppend( \"data/scripts/gun/gun.lua\", \"mods/spell_lab_shugged/files/append/gun/no_recoil.lua\" )\nModLuaFileAppend( \"data/scripts/gun/gun.lua\", \"mods/spell_lab_shugged/files/append/gun/cast_delay_fixer.lua\" )\nModLuaFileAppend( \"data/scripts/gun/gun.lua\", \"mods/spell_lab_shugged/files/append/gun/disable_casting.lua\" )\n\nlocal translations = ModTextFileGetContent( \"mods/spell_lab_shugged/files/translations.csv\" )\nlocal main = \"data/translations/common.csv\"\nlocal main_content = ModTextFileGetContent( main )\nif main_content:sub( #main_content, #main_content ) ~= \"\\n\" then\n	main_content = main_content .. \"\\n\"\nend\nModTextFileSetContent( main, main_content .. translations:gsub( \"^[^\\n]*\\n\", \"\", 1 ) )\n\nlocal injected_lua_folder = \"mods/spell_lab_shugged/files/scripts/saved/\"\n\nlocal twitchy_effect_path = \"data/entities/misc/effect_twitchy.xml\"\nlocal twitchy_effect = ModTextFileGetContent( twitchy_effect_path )\nif ModDoesFileExist( twitchy_effect_path ) and twitchy_effect then\n	local twitchy_lua_path = \"data/scripts/status_effects/twitchy.lua\"\n	if ModDoesFileExist( twitchy_lua_path ) then\n		local twitchy_lua = ModTextFileGetContent( twitchy_lua_path )\n		ModTextFileSetContent( injected_lua_folder .. \"twitchy.lua\",\n			[[if EntityHasTag( EntityGetRootEntity( GetUpdatedEntityID() ), \"player_unit\" ) and ModSettingGet( \"spell_lab_shugged.disable_toxic_statuses\" ) then\n				if EntityGetParent( GetUpdatedEntityID() ) ~= 0 then\n					EntityKill( GetUpdatedEntityID() )\n				else\n					EntityRemoveComponent( GetUpdatedEntityID(), GetUpdatedComponentID() )\n				end\n				return\n			end\n			]] .. twitchy_lua )\n		twitchy_effect = twitchy_effect:gsub( twitchy_lua_path:gsub( \"%.\", \"%.\" ), injected_lua_folder .. \"twitchy.lua\" )\n	end\n\n	local twitchy_lua2_path = \"data/scripts/status_effects/twitchy_shot.lua\"\n	if ModDoesFileExist( twitchy_lua2_path ) then\n		local twitchy_lua2 = ModTextFileGetContent( twitchy_lua2_path )\n		ModTextFileSetContent( injected_lua_folder .. \"twitchy_shot.lua\",\n			twitchy_lua2 .. [[\n			local old_shot = shot\n			function shot( projectile_id )\n				if EntityHasTag( EntityGetRootEntity( GetUpdatedEntityID() ), \"player_unit\" ) and ModSettingGet( \"spell_lab_shugged.disable_toxic_statuses\" ) then\n					if EntityGetParent( GetUpdatedEntityID() ) ~= 0 then\n						EntityKill( GetUpdatedEntityID() )\n					else\n						EntityRemoveComponent( GetUpdatedEntityID(), GetUpdatedComponentID() )\n					end\n					return\n				end\n				old_shot( projectile_id )\n			end]] )\n		twitchy_effect = twitchy_effect:gsub( twitchy_lua_path:gsub( \"%.\", \"%.\" ), injected_lua_folder .. \"twitchy_shot.lua\" )\n	end\n\n	ModTextFileSetContent( twitchy_effect_path, twitchy_effect )\nend\n\nlocal neutralized_effect_path = \"data/entities/misc/neutralized.xml\"\nlocal neutralized_effect = ModTextFileGetContent( neutralized_effect_path )\nif ModDoesFileExist( neutralized_effect_path ) and neutralized_effect then\n	local neutralized_lua_path = \"data/scripts/projectiles/neutralized.lua\"\n	if ModDoesFileExist( neutralized_lua_path ) then\n		local neutralized_lua = ModTextFileGetContent( neutralized_lua_path )\n		ModTextFileSetContent( injected_lua_folder .. \"neutralized.lua\",\n			neutralized_lua .. [[\n			local old_shot = shot\n			function shot( projectile_id )\n				if EntityHasTag( EntityGetRootEntity( GetUpdatedEntityID() ), \"player_unit\" ) and ModSettingGet( \"spell_lab_shugged.disable_toxic_statuses\" ) then\n					EntityKill( GetUpdatedEntityID() )\n					return\n				end\n				old_shot( projectile_id )\n			end]] )\n		neutralized_effect = neutralized_effect:gsub( neutralized_lua_path:gsub( \"%.\", \"%.\" ), injected_lua_folder .. \"neutralized.lua\" )\n	end\n\n	ModTextFileSetContent( neutralized_effect_path, neutralized_effect )\nend\n\nlocal glue_lua_path = \"data/scripts/projectiles/glue_init.lua\"\nlocal glue_lua = ModTextFileGetContent( glue_lua_path )\nif ModDoesFileExist( glue_lua_path ) and glue_lua then\n	ModTextFileSetContent( glue_lua_path, glue_lua:gsub( \"if target2 ~= target then\",\n		[[if EntityHasTag( target2, \"player_unit\" ) and ModSettingGet( \"spell_lab_shugged.disable_toxic_statuses\" ) then return end\n		if target2 ~= target then]] ) )\nend\n\nfunction OnModPostInit()\n	local nxml = dofile_once( \"mods/spell_lab_shugged/files/lib/nxml.lua\" )\n	dofile_once( \"mods/spell_lab_shugged/files/scripts/toxic_effect_entities.lua\" )\n	for _, effect_path in ipairs( toxic_effect_entities ) do\n		local effect = ModTextFileGetContent( effect_path )\n		if ModDoesFileExist( effect_path ) and effect then\n			local parsed = nxml.parse( effect )\n			table.insert( parsed.children, 1, nxml.new_element( \"LuaComponent\", {\n				script_source_file = \"mods/spell_lab_shugged/files/scripts/remove_toxic_effect.lua\",\n				execute_on_added = true,\n				execute_every_n_frame = 1,\n			} ) )\n			ModTextFileSetContent( effect_path, tostring( parsed ) )\n		end\n	end\nend\n\nlocal mod_setting_prefix = \"spell_lab_shugged.\"\n\nlocal default_settings = {\n	[\"quick_spell_picker\"] = true,\n	[\"spell_replacement\"] = true,\n	[\"show_toggle_options\"] = true,\n	[\"show_locked_spells\"] = true,\n}\n\nif ModSettingGet( mod_setting_prefix .. \"no_weather\" ) then\n	local init_lua_path = \"data/scripts/init.lua\"\n	ModLuaFileAppend( init_lua_path, \"mods/spell_lab_shugged/files/append/init.lua\" )\n	ModTextFileSetContent( init_lua_path, ModTextFileGetContent( init_lua_path ) ) -- refresh it\nend\n\nModTextFileSetContent_Saved = ModTextFileSetContent\n\nfor key, value in pairs( default_settings ) do\n	if ModSettingGet( mod_setting_prefix .. key ) == nil then\n		ModSettingSet( mod_setting_prefix .. key, value )\n	end\nend\n\ndofile_once( \"mods/spell_lab_shugged/files/lib/controls_freezing_utils.lua\" )\nfunction OnPlayerSpawned( player_id )\n	unfreeze_controls()\n	GlobalsSetValue( \"mod_button_tr_width\", \"0\" )\n	if not GameHasFlagRun( \"spell_lab_shugged_init\" ) then\n		EntityLoad( \"mods/spell_lab_shugged/files/biome_impl/wand_lab/wand_lab.xml\", 14600, -6000 )\n		GameAddFlagRun( \"spell_lab_shugged_init\" )\n	end\n	local not_inited = true\n	for _, lua_comp in ipairs( EntityGetComponentIncludingDisabled( player_id, \"LuaComponent\" ) or {} ) do\n		if ComponentGetValue2( lua_comp, \"script_source_file\" ) == \"mods/spell_lab_shugged/files/scripts/player_update.lua\" then\n			not_inited = false\n			break\n		end\n	end\n	if not_inited then\n		GlobalsSetValue( \"spell_lab_shugged.refresh_player_state\", \"1\" )\n		EntityAddComponent2( player_id, \"LuaComponent\", {\n			script_source_file = \"mods/spell_lab_shugged/files/scripts/player_update.lua\",\n			execute_on_added = true,\n			execute_every_n_frame = 1,\n		} )\n		EntityAddComponent2( player_id, \"LuaComponent\", { script_shot = \"mods/spell_lab_shugged/files/scripts/player_shot.lua\" })\n	end\nend\n\nfunction OnWorldInitialized()\n	local mod_button_reservation = tonumber( GlobalsGetValue( \"mod_button_tr_width\", \"0\" ) )\n	GlobalsSetValue( \"spell_lab_shugged_mod_button_reservation\", tostring( mod_button_reservation ) )\n	GlobalsSetValue( \"mod_button_tr_width\", tostring( mod_button_reservation + 15 ) )\nend\n\nfunction OnWorldPreUpdate()\n	dofile( \"mods/spell_lab_shugged/files/gui/update.lua\" )\nend\n\nfunction OnWorldPostUpdate()\n	GlobalsSetValue( \"mod_button_tr_current\", \"0\" )\nend"
_TWWE_VFS["mods/spell_lab_shugged/mod.xml"] = "<Mod\n	name=\"Spell Lab Shugged 法术实验室\"\n    description=\"Devoted to providing modernized, convenient, and hopefully comprehensive assistance for making wand setups.\\n致力于提供现代化、便捷、功能全面的编杖体验。\">\n</Mod>\n"
_TWWE_VFS["mods/spell_lab_shugged/mod_id.txt"] = "spell_lab_shugged"
_TWWE_VFS["mods/spell_lab_shugged/settings.lua"] = "dofile_once( \"data/scripts/lib/utilities.lua\" )\ndofile_once( \"data/scripts/lib/mod_settings.lua\" )\ndofile_once( \"mods/spell_lab_shugged/files/lib/shortcut_setting.lua\" )\n\nlocal mod_id = \"spell_lab_shugged\"\n\nmod_settings_version = 1\nlocal function load_mod_settings( cur_lang )\n	if cur_lang == \"简体中文\" or cur_lang == \"喵体中文\" or cur_lang == \"汪体中文\" or cur_lang == \"完全汉化\" then\n		text = {\n			wand_edit_panel = \"法杖编辑面板\",\n			wand_edit_panel_max_num_rows = \"最大行数\",\n			wand_edit_panel_max_num_rows_description = \"法杖编辑面板最多可以同时显示的行数，默认为 5\",\n			wand_edit_panel_max_actions_per_row = \"单行格数限制\",\n			wand_edit_panel_max_actions_per_row_description =\n				\"限制法杖编辑面板单行最多可以显示的格数\\n单行最多能容纳的格数自动由虚拟分辨率计算得出，然后应用此限制\\n0 = 不进行限制\",\n			wand_edit_panel_history_limit = \"历史记录最大条数\",\n			wand_edit_panel_history_limit_description = \"法杖编辑面板保留最近操作的数量，默认为 30\",\n			wand_listener_type = \"法杖监听\",\n			wand_listener_type_description = \"法杖编辑面板应该从哪些法杖监听外部操作？\\n该设置不影响编辑，但会影响历史记录的产生数量\",\n			wand_listener_type_values = {\n				{ \"INV\", \"背包中所有法杖\" },\n				{ \"HAND\", \"手持法杖\" },\n				{ \"PANEL\", \"手持法杖（仅法杖编辑面板显示时）\" },\n			},\n			spell_picker = \"法术选取菜单\",\n			filter_buttons_trigger = \"法术类别切换方式\",\n			filter_buttons_trigger_description = \"法术类别按钮应该如何触发？\",\n			filter_buttons_trigger_values = {\n				{ \"HOVER\", \"悬浮\" },\n				{ \"CLICK\", \"点击\" },\n			},\n			action_history_limit = \"法术使用记录最大条数\",\n			action_history_limit_description = \"法术选取菜单保留的法术使用记录条数，默认为 96\",\n			show_icon_unlocked = \"标记已解锁法术\",\n			show_icon_unlocked_description = \"开启时，将在已解锁法术右上角显示图标，以便重新锁定它们\",\n			include_spells_in_non_inv_wand = \"背包/附近页面显示附近法杖中法术\",\n			include_spells_in_non_inv_wand_description = \"开启时，法术选取菜单的背包/附近页面将显示附近法杖中法术\",\n			show_screen_keyboard = \"法术搜索页面显示软键盘\",\n			creative_mode_flight_speed = \"超级飞行速度\",\n			creative_mode_flight_speed_normal = \"正常\",\n			creative_mode_flight_speed_normal_description = \"默认：200\",\n			creative_mode_flight_speed_faster = \"加速\",\n			creative_mode_flight_speed_faster_description = \"默认：450\",\n			creative_mode_flight_speed_no_clip = \"穿墙\",\n			creative_mode_flight_speed_no_clip_description = \"默认：300\",\n			all_seeing_eye = \"全视之眼效果\",\n			all_seeing_eye_lighting = \"照明\",\n			all_seeing_eye_fog_of_war_removing = \"移除战争迷雾\",\n			shortcut = \"快捷键设置\",\n			shortcut_strict = \"严格检测\",\n			shortcut_strict_description = \"没有包含在任何快捷键中的键是否应该影响快捷键检测？\",\n			shortcut_click_to_save = \"（点击以保存）\",\n			shortcut_click_here = \" +（请点击）\",\n			shortcut_general = \"法杖编辑面板、法杖仓库 & 法术组合仓库\",\n			shortcut_multi_selectable = \"法杖编辑面板 & 法杖仓库\",\n			shortcut_select = \"选择\",\n			shortcut_deselect = \"取消选择\",\n			shortcut_multi_select = \"选择多个\",\n			shortcut_expand_selection_left = \"扩展左边选区\",\n			shortcut_expand_selection_right = \"扩展右边选区\",\n			shortcut_swap = \"交换/轮换\",\n			shortcut_override = \"移动\",\n			shortcut_wand_edit_panel = \"法杖编辑面板\",\n			shortcut_duplicate = \"复制选中法术至此处\",\n			shortcut_delete_action = \"删除法术\",\n			shortcut_delete_slot = \"删除法术及其槽位\",\n			shortcut_always_cast = \"设置/取消始终施放\",\n			shortcut_undo = \"撤销\",\n			shortcut_redo = \"恢复\",\n			shortcut_left_delete = \"向左删除\",\n			shortcut_right_delete = \"向右删除\",\n			shortcut_spell_picker = \"法术选取菜单\",\n			shortcut_relock = \"重新锁定已解锁法术\",\n			shortcut_replace_switch_temp = \"临时开启/关闭法术替换模式\",\n			shortcut_clear_action_history = \"清除法术历史\",\n			shortcut_wand_box = \"法杖仓库\",\n			shortcut_show_wand_stats = \"显示法杖信息\",\n			shortcut_confirm = \"确认（删除等）\",\n			shortcut_transform_mortal_into_dummy = \"转化生物为伤害测试假人\",\n			no_weather = \"禁用天气\",\n			no_weather_description = \"开启时，天气将锁定为晴朗状态\",\n			dummy_target_show_full_damage_number = \"伤害测试假人显示完整伤害数字\",\n			dummy_target_show_full_damage_number_description = \"开启时，将以完整形式而不是科学计数法显示伤害数字\",\n			button_click_sound = \"按钮点击音效\",\n			action_button_click_sound = \"法术按钮点击音效\",\n		}\n	else\n		text = {\n			wand_edit_panel = \"Wand Edit Panel\",\n			wand_edit_panel_max_num_rows = \"Max Rows\",\n			wand_edit_panel_max_num_rows_description = \"How many rows should the wand edit panel show at most at the same time?\\n5 by default\",\n			wand_edit_panel_max_actions_per_row = \"Max Slots In One Row Limit\",\n			wand_edit_panel_max_actions_per_row_description =\n				\"How many slots should one row of the wand edit panel contain at most?\\nNote: That is calculated with your virtual resolution magic numbers\\n0 = No extra limit to it\",\n			wand_edit_panel_history_limit = \"Max Histories\",\n			wand_edit_panel_history_limit_description = \"How many recent operations should the wand edit panel remember?\\n30 by default\",\n			wand_listener_type = \"Wand Listening\",\n			wand_listener_type_description = \"From which wand(s) should be listened to track any external options?\\nValue doesn't change the way you edit wand, but changes how many histories will be created\",\n			wand_listener_type_values = {\n				{ \"INV\", \"All Wands in Inventory\" },\n				{ \"HAND\", \"Held Wand\" },\n				{ \"PANEL\", \"Held Wand(Only when the wand edit panel is shown)\" },\n			},\n			spell_picker = \"Spell Picker\",\n			filter_buttons_trigger = \"Switch between types\",\n			filter_buttons_trigger_description = \"How to trigger the spell type buttons?\",\n			filter_buttons_trigger_values = {\n				{ \"HOVER\", \"Hover\" },\n				{ \"CLICK\", \"Click\" },\n			},\n			action_history_limit = \"Recently Used Spells Limit\",\n			action_history_limit_description = \"How many recently used spells should the spell picker menu remember?\\n96 by default\",\n			show_icon_unlocked = \"Mark Out Unlocked Spells\",\n			show_icon_unlocked_description = \"Should we mark out unlocked spells with a small icon in the top right corner?\",\n			include_spells_in_non_inv_wand = \"Include Spells In Nearby Wands\",\n			include_spells_in_non_inv_wand_description = \"Should spells in nearby wands be shown in Inv/Nearby page of the spell picker?\",\n			show_screen_keyboard = \"Show Screen Keyboard In Spell Search Page\",\n			creative_mode_flight_speed = \"Superflight Speed\",\n			creative_mode_flight_speed_normal = \"Normal\",\n			creative_mode_flight_speed_normal_description = \"200 by default\",\n			creative_mode_flight_speed_faster = \"Faster\",\n			creative_mode_flight_speed_faster_description = \"450 by default\",\n			creative_mode_flight_speed_no_clip = \"No Clip\",\n			creative_mode_flight_speed_no_clip_description = \"300 by default\",\n			all_seeing_eye = \"Effect of All-seeing Eye\",\n			all_seeing_eye_lighting = \"Lighting\",\n			all_seeing_eye_fog_of_war_removing = \"Fog of War Removing\",\n			shortcut = \"Shortcuts Setting\",\n			shortcut_strict = \"Strict Detection\",\n			shortcut_strict_description = \"Should keys that not used in any shortcut be considered in shortcut detection?\",\n			shortcut_click_to_save = \" (click to save)\",\n			shortcut_click_here = \" + (click here)\",\n			shortcut_general = \"Wand Edit Panel, Wand Box & Spell Group Box\",\n			shortcut_multi_selectable = \"Wand Edit Panel & Wand Box\",\n			shortcut_select = \"Select\",\n			shortcut_deselect = \"Deselect\",\n			shortcut_multi_select = \"Multiple selection\",\n			shortcut_expand_selection_left = \"Expand selection on the left side\",\n			shortcut_expand_selection_right = \"Expand selection on the right side\",\n			shortcut_swap = \"Swap/Cycle\",\n			shortcut_override = \"Move\",\n			shortcut_wand_edit_panel = \"Wand Edit Panel\",\n			shortcut_duplicate = \"Duplicate spell(s)\",\n			shortcut_delete_action = \"Delete spell\",\n			shortcut_delete_slot = \"Delete slot\",\n			shortcut_always_cast = \"Promote/Demote always-cast\",\n			shortcut_undo = \"Undo\",\n			shortcut_redo = \"Redo\",\n			shortcut_left_delete = \"Delete to the left\",\n			shortcut_right_delete = \"Delete to the right\",\n			shortcut_spell_picker = \"Spell Picker\",\n			shortcut_relock = \"Relock unlocked spell\",\n			shortcut_replace_switch_temp = \"Invert replace mode\",\n			shortcut_clear_action_history = \"Clear spell history\",\n			shortcut_wand_box = \"Wand Box\",\n			shortcut_show_wand_stats = \"Show wand stats\",\n			shortcut_confirm = \"Confirm (deletions, etc.)\",\n			shortcut_transform_mortal_into_dummy = \"Target dummy transformation\",\n			no_weather = \"Disable Weather\",\n			no_weather_description = \"Should we disable all kinds of rain or snow?\",\n			dummy_target_show_full_damage_number = \"Show Full Damage Number For Dummy Targets\",\n			dummy_target_show_full_damage_number_description = \"Should dummy targets always has full-length damage numbers shown?\",\n			button_click_sound = \"Button Click Sound\",\n			action_button_click_sound = \"Spell Button Click sound\",\n		}\n	end\n	mod_settings = {\n		{\n			category_id = \"wand_edit_panel\",\n			ui_name = text.wand_edit_panel,\n			foldable = true,\n			_folded = true,\n			settings = {\n				{\n					id                 = \"wand_edit_panel_max_rows\",\n					ui_name            = text.wand_edit_panel_max_num_rows,\n					ui_description     = text.wand_edit_panel_max_num_rows_description,\n					allowed_characters = \"0123456789\",\n					text_max_length    = 3,\n					value_default      = \"5\",\n					scope              = MOD_SETTING_SCOPE_RUNTIME,\n				},\n				{\n					id                 = \"wand_edit_panel_max_actions_per_row\",\n					ui_name            = text.wand_edit_panel_max_actions_per_row,\n					ui_description     = text.wand_edit_panel_max_actions_per_row_description,\n					allowed_characters = \"0123456789\",\n					text_max_length    = 3,\n					value_default      = \"0\",\n					scope              = MOD_SETTING_SCOPE_RUNTIME,\n				},\n				{\n					id                 = \"wand_edit_panel_history_limit\",\n					ui_name            = text.wand_edit_panel_history_limit,\n					ui_description     = text.wand_edit_panel_history_limit_description,\n					allowed_characters = \"0123456789\",\n					text_max_length    = 3,\n					value_default      = \"30\",\n					scope              = MOD_SETTING_SCOPE_RUNTIME,\n				},\n				{\n					id                 = \"wand_listener_type\",\n					ui_name            = text.wand_listener_type,\n					ui_description     = text.wand_listener_type_description,\n					value_default      = text.wand_listener_type_values[1][1],\n					values             = text.wand_listener_type_values,\n					scope              = MOD_SETTING_SCOPE_RUNTIME,\n				},\n			},\n		},\n		{\n			category_id = \"spell_picker\",\n			ui_name = text.spell_picker,\n			foldable = true,\n			_folded = true,\n			settings = {\n				{\n					id                 = \"filter_buttons_trigger\",\n					ui_name            = text.filter_buttons_trigger,\n					ui_description     = text.filter_buttons_trigger_description,\n					value_default      = text.filter_buttons_trigger_values[1][1],\n					values             = text.filter_buttons_trigger_values,\n					scope              = MOD_SETTING_SCOPE_RUNTIME,\n				},\n				{\n					id                 = \"show_icon_unlocked\",\n					ui_name            = text.show_icon_unlocked,\n					ui_description     = text.show_icon_unlocked_description,\n					value_default      = false,\n					scope              = MOD_SETTING_SCOPE_RUNTIME,\n				},\n				{\n					id                 = \"action_history_limit\",\n					ui_name            = text.action_history_limit,\n					ui_description     = text.action_history_limit_description,\n					allowed_characters = \"0123456789\",\n					text_max_length    = 3,\n					value_default      = \"96\",\n					scope              = MOD_SETTING_SCOPE_RUNTIME,\n				},\n				{\n					id                 = \"include_spells_in_non_inv_wand\",\n					ui_name            = text.include_spells_in_non_inv_wand,\n					ui_description     = text.include_spells_in_non_inv_wand_description,\n					value_default      = false,\n					scope              = MOD_SETTING_SCOPE_RUNTIME,\n				},\n				{\n					id                 = \"show_screen_keyboard\",\n					ui_name            = text.show_screen_keyboard,\n					value_default      = false,\n					scope              = MOD_SETTING_SCOPE_RUNTIME,\n				},\n			},\n		},\n		{\n			category_id = \"creative_mode_flight_speed\",\n			ui_name = text.creative_mode_flight_speed,\n			foldable = true,\n			_folded = true,\n			settings = {\n				{\n					id                 = \"creative_mode_flight_speed_normal\",\n					ui_name            = text.creative_mode_flight_speed_normal,\n					ui_description     = text.creative_mode_flight_speed_normal_description,\n					allowed_characters = \"0123456789\",\n					text_max_length    = 6,\n					value_default      = \"200\",\n					scope              = MOD_SETTING_SCOPE_RUNTIME,\n				},\n				{\n					id                 = \"creative_mode_flight_speed_faster\",\n					ui_name            = text.creative_mode_flight_speed_faster,\n					ui_description     = text.creative_mode_flight_speed_faster_description,\n					allowed_characters = \"0123456789\",\n					text_max_length    = 6,\n					value_default      = \"450\",\n					scope              = MOD_SETTING_SCOPE_RUNTIME,\n				},\n				{\n					id                 = \"creative_mode_flight_speed_no_clip\",\n					ui_name            = text.creative_mode_flight_speed_no_clip,\n					ui_description     = text.creative_mode_flight_speed_no_clip_description,\n					allowed_characters = \"0123456789\",\n					text_max_length    = 6,\n					value_default      = \"300\",\n					scope              = MOD_SETTING_SCOPE_RUNTIME,\n				},\n			},\n		},\n		{\n			category_id = \"all_seeing_eye\",\n			ui_name = text.all_seeing_eye,\n			foldable = true,\n			_folded = true,\n			settings = {\n				{\n					id                       = \"all_seeing_eye_lighting\",\n					ui_name                  = text.all_seeing_eye_lighting,\n					value_default            = 0,\n					value_min                = 0,\n					value_max                = 1,\n					value_display_multiplier = 100,\n					value_display_formatting = \" $0%\",\n					scope                    = MOD_SETTING_SCOPE_RUNTIME,\n				},\n				{\n					id                       = \"all_seeing_eye_fog_of_war_removing\",\n					ui_name                  = text.all_seeing_eye_fog_of_war_removing,\n					value_default            = 1,\n					value_min                = 0,\n					value_max                = 1,\n					value_display_multiplier = 100,\n					value_display_formatting = \" $0%\",\n					scope                    = MOD_SETTING_SCOPE_RUNTIME,\n				},\n			},\n		},\n		{\n			category_id = \"shortcut\",\n			ui_name = text.shortcut,\n			foldable = true,\n			_folded = true,\n			settings = {\n				{\n					id             = \"shortcut_strict\",\n					ui_name        = text.shortcut_strict,\n					ui_description = text.shortcut_strict_description,\n					value_default  = false,\n					scope          = MOD_SETTING_SCOPE_RUNTIME,\n					change_fn      = function( mod_id, gui, in_main_menu, setting, old_value, new_value )\n						ModSettingSet( mod_id .. \".shortcut_changed\", true, false )\n					end,\n				},\n				{\n					category_id = \"shortcut_general\",\n					ui_name = text.shortcut_general,\n					foldable = true,\n					_folded = true,\n					settings = {\n						{\n							id             = \"shortcut_select\",\n							ui_name        = text.shortcut_select,\n							value_default  = '{\"Mouse_left\"}',\n							scope          = MOD_SETTING_SCOPE_RUNTIME,\n							ui_fn          = mod_setting_shortcut,\n							click_required = true,\n						},\n						{\n							id             = \"shortcut_deselect\",\n							ui_name        = text.shortcut_deselect,\n							value_default  = '{\"Mouse_right\"}',\n							scope          = MOD_SETTING_SCOPE_RUNTIME,\n							ui_fn          = mod_setting_shortcut,\n							click_required = true,\n						},\n						{\n							id             = \"shortcut_swap\",\n							ui_name        = text.shortcut_swap,\n							value_default  = '{\"Key_ALT\",\"Mouse_left\"}',\n							scope          = MOD_SETTING_SCOPE_RUNTIME,\n							ui_fn          = mod_setting_shortcut,\n							click_required = true,\n						},\n					}\n				},\n				{\n					category_id = \"shortcut_multi_selectable\",\n					ui_name = text.shortcut_multi_selectable,\n					foldable = true,\n					_folded = true,\n					settings = {\n						{\n							id             = \"shortcut_multi_select\",\n							ui_name        = text.shortcut_multi_select,\n							value_default  = '{\"Key_CTRL\",\"Mouse_left\"}',\n							scope          = MOD_SETTING_SCOPE_RUNTIME,\n							ui_fn          = mod_setting_shortcut,\n							click_required = true,\n						},\n						{\n							id             = \"shortcut_expand_selection_left\",\n							ui_name        = text.shortcut_expand_selection_left,\n							value_default  = '{\"Key_CTRL\",\"Key_ALT\",\"Mouse_left\"}',\n							scope          = MOD_SETTING_SCOPE_RUNTIME,\n							ui_fn          = mod_setting_shortcut,\n							click_required = true,\n						},\n						{\n							id             = \"shortcut_expand_selection_right\",\n							ui_name        = text.shortcut_expand_selection_right,\n							value_default  = '{\"Key_CTRL\",\"Key_ALT\",\"Mouse_right\"}',\n							scope          = MOD_SETTING_SCOPE_RUNTIME,\n							ui_fn          = mod_setting_shortcut,\n							click_required = true,\n						},\n					},\n				},\n				{\n					category_id = \"shortcut_wand_edit_panel\",\n					ui_name = text.shortcut_wand_edit_panel,\n					foldable = true,\n					_folded = true,\n					settings = {\n						{\n							id             = \"shortcut_override\",\n							ui_name        = text.shortcut_override,\n							value_default  = '{\"Key_ALT\",\"Mouse_right\"}',\n							scope          = MOD_SETTING_SCOPE_RUNTIME,\n							ui_fn          = mod_setting_shortcut,\n							click_required = true,\n						},\n						{\n							id             = \"shortcut_duplicate\",\n							ui_name        = text.shortcut_duplicate,\n							value_default  = '{\"Key_ALT\",\"Key_SHIFT\",\"Mouse_left\"}',\n							scope          = MOD_SETTING_SCOPE_RUNTIME,\n							ui_fn          = mod_setting_shortcut,\n							click_required = true,\n						},\n						{\n							id             = \"shortcut_delete_action\",\n							ui_name        = text.shortcut_delete_action,\n							value_default  = '{\"Key_SHIFT\",\"Mouse_left\"}',\n							scope          = MOD_SETTING_SCOPE_RUNTIME,\n							ui_fn          = mod_setting_shortcut,\n							click_required = true,\n						},\n						{\n							id             = \"shortcut_delete_slot\",\n							ui_name        = text.shortcut_delete_slot,\n							value_default  = '{\"Key_SHIFT\",\"Mouse_right\"}',\n							scope          = MOD_SETTING_SCOPE_RUNTIME,\n							ui_fn          = mod_setting_shortcut,\n							click_required = true,\n						},\n						{\n							id             = \"shortcut_always_cast\",\n							ui_name        = text.shortcut_always_cast,\n							value_default  = '{\"Key_CTRL\",\"Key_SHIFT\",\"Mouse_left\"}',\n							scope          = MOD_SETTING_SCOPE_RUNTIME,\n							ui_fn          = mod_setting_shortcut,\n							click_required = true,\n						},\n						{\n							id            = \"shortcut_left_delete\",\n							ui_name       = text.shortcut_left_delete,\n							value_default = '{\"Key_BACKSPACE\"}',\n							scope         = MOD_SETTING_SCOPE_RUNTIME,\n							ui_fn         = mod_setting_shortcut,\n						},\n						{\n							id            = \"shortcut_right_delete\",\n							ui_name       = text.shortcut_right_delete,\n							value_default = '{\"Key_DELETE\"}',\n							scope         = MOD_SETTING_SCOPE_RUNTIME,\n							ui_fn         = mod_setting_shortcut,\n						},\n						{\n							id            = \"shortcut_undo\",\n							ui_name       = text.shortcut_undo,\n							value_default = '{\"Key_CTRL\",\"Key_z\"}',\n							scope         = MOD_SETTING_SCOPE_RUNTIME,\n							ui_fn         = mod_setting_shortcut,\n						},\n						{\n							id            = \"shortcut_redo\",\n							ui_name       = text.shortcut_redo,\n							value_default = '{\"Key_CTRL\",\"Key_y\"}',\n							scope         = MOD_SETTING_SCOPE_RUNTIME,\n							ui_fn         = mod_setting_shortcut,\n						},\n					},\n				},\n				{\n					category_id = \"shortcut_spell_picker\",\n					ui_name = text.shortcut_spell_picker,\n					foldable = true,\n					_folded = true,\n					settings = {\n						{\n							id             = \"shortcut_relock\",\n							ui_name        = text.shortcut_relock,\n							value_default  = '{\"Key_CTRL\",\"Key_SHIFT\",\"Mouse_left\"}',\n							scope          = MOD_SETTING_SCOPE_RUNTIME,\n							ui_fn          = mod_setting_shortcut,\n							click_required = true,\n						},\n						{\n							id             = \"shortcut_replace_switch_temp\",\n							ui_name        = text.shortcut_replace_switch_temp,\n							value_default  = '{\"Key_SHIFT\"}',\n							scope          = MOD_SETTING_SCOPE_RUNTIME,\n							ui_fn          = mod_setting_shortcut,\n						},\n						{\n							id             = \"shortcut_clear_action_history\",\n							ui_name        = text.shortcut_clear_action_history,\n							value_default  = '{\"Key_SHIFT\",\"Mouse_right\"}',\n							scope          = MOD_SETTING_SCOPE_RUNTIME,\n							ui_fn          = mod_setting_shortcut,\n							click_required = true,\n						},\n					},\n				},\n				{\n					category_id = \"shortcut_wand_box\",\n					ui_name = text.shortcut_wand_box,\n					foldable = true,\n					_folded = true,\n					settings = {\n						{\n							id             = \"shortcut_show_wand_stats\",\n							ui_name        = text.shortcut_show_wand_stats,\n							value_default  = '{\"Key_CTRL\"}',\n							scope          = MOD_SETTING_SCOPE_RUNTIME,\n							ui_fn          = mod_setting_shortcut,\n						},\n					},\n				},\n				{\n					id             = \"shortcut_confirm\",\n					ui_name        = text.shortcut_confirm,\n					value_default  = '{\"Key_SHIFT\"}',\n					scope          = MOD_SETTING_SCOPE_RUNTIME,\n					ui_fn          = mod_setting_shortcut,\n				},\n				{\n					id             = \"shortcut_transform_mortal_into_dummy\",\n					ui_name        = text.shortcut_transform_mortal_into_dummy,\n					value_default  = '{\"Key_SHIFT\"}',\n					scope          = MOD_SETTING_SCOPE_RUNTIME,\n					ui_fn          = mod_setting_shortcut,\n				},\n			},\n		},\n		{\n			id                 = \"no_weather\",\n			ui_name            = text.no_weather,\n			ui_description     = text.no_weather_description,\n			value_default      = false,\n			scope              = MOD_SETTING_SCOPE_RUNTIME_RESTART,\n		},\n		{\n			id                 = \"dummy_target_show_full_damage_number\",\n			ui_name            = text.dummy_target_show_full_damage_number,\n			ui_description     = text.dummy_target_show_full_damage_number_description,\n			value_default      = false,\n			scope              = MOD_SETTING_SCOPE_RUNTIME,\n		},\n		{\n			id                 = \"button_click_sound\",\n			ui_name            = text.button_click_sound,\n			value_default      = false,\n			scope              = MOD_SETTING_SCOPE_RUNTIME,\n		},\n		{\n			id                 = \"action_button_click_sound\",\n			ui_name            = text.action_button_click_sound,\n			value_default      = false,\n			scope              = MOD_SETTING_SCOPE_RUNTIME,\n		},\n	}\nend\nload_mod_settings()\n\nfunction ModSettingsUpdate( init_scope )\n	local old_version = mod_settings_get_version( mod_id ) -- This can be used to migrate some settings between mod versions.\n	mod_settings_update( mod_id, mod_settings, init_scope )\nend\n\nfunction ModSettingsGuiCount()\n	return mod_settings_gui_count( mod_id, mod_settings )\nend\n\nlocal last_cur_lang\nfunction ModSettingsGui( gui, in_main_menu )\n	local cur_lang = GameTextGet( \"$current_language\" )\n	if cur_lang ~= last_cur_lang then\n		load_mod_settings( cur_lang )\n		last_cur_lang = cur_lang\n	end\n    mod_settings_gui( mod_id, mod_settings, gui, in_main_menu )\nend"
_TWWE_VFS["mods/ui_timer_hits/compatibility.xml"] = "<Mod _format_version=\"0\" version_built_with=\"6\" >\n\n</Mod>\n\n"
_TWWE_VFS["mods/ui_timer_hits/files/gui/_update.lua"] = "-- don't edit these\nprint(\"[ui_timer] setting up GUI\");\ndofile_once( \"data/scripts/lib/coroutines.lua\" );\ndofile_once( \"mods/ui_timer_hits/files/lib/variables.lua\" );\ndofile_once( \"mods/ui_timer_hits/files/lib/helper.lua\" );\ndofile_once( \"data/scripts/lib/utilities.lua\" );\n\nlocal mod_settings_parsed = false;\nlocal mod_settings_id = \"ui_timer_hits\";\nlocal gui = gui or GuiCreate();\nlocal screen_width, screen_height;\nlocal full_screen_width, screen_height = GuiGetScreenDimensions( gui );\nlocal gui_id = 12788;\nlocal id_offset = 0;\nlocal function truncate_long_string( str )\n    if #str > 31 then\n        str = str:sub( 0, 14 )..\"...\"..str:sub( -14 );\n    end\n    return str;\nend\n\nlocal function word_wrap( str, wrap_size )\n    if str then\n        if wrap_size == nil then wrap_size = 60; end\n        local last_space_index = 1;\n        local last_wrap_index = 0;\n        for i=1,#str do\n            if str:sub(i,i) == \" \" then\n                last_space_index = i;\n            end\n            if str:sub(i,i) == \"\\n\" then\n                last_space_index = i;\n                last_wrap_index = i;\n            end\n            if i - last_wrap_index > wrap_size then\n                str = str:sub(1,last_space_index-1) .. \"\\n\" .. str:sub(last_space_index + 1);\n                last_wrap_index = i;\n            end\n        end\n        return str;\n    end\n    return \"\";\nend\n\nlocal function next_id()\n    id_offset = id_offset + 1;\n    return gui_id + id_offset;\nend\n\nlocal function pattern_validation( value )\n    local status,result = pcall( function() local s = string.format( value, 0,0,0,0,0,0,0,0 ); end );\n    if status == false then\n        return result;\n    end \n    return true;\nend\n\nlocal is_panel_open = false;\nlocal mod_settings = {};\nlocal function parse_mod_settings()\n    mod_settings = {\n        { key=\"show_position\", label = \"Show Position\", default = true, type = \"boolean\" },\n        { key=\"show_depth\", label = \"Show Depth\", default = true, type = \"boolean\" },\n        { key=\"show_time\", label = \"Show Time\", default = true, type = \"boolean\" },\n        { key=\"show_hits\", label = \"Show Hits\", default = true, type = \"boolean\" },\n        { key=\"show_hit_message\", label = \"Log Hits\", default = false, type = \"boolean\" },\n        { key=\"include_environmental_hits\", label = \"Include Environmental Damage Hits\", default = true, type = \"boolean\" },\n        { key=\"include_negative_damage\", label = \"Include Negative Damage Hits\", default = false, type = \"boolean\" },\n        { key=\"include_self_damage_hits\", label = \"Include Self Damage Hits\", default = true, type = \"boolean\" },\n        { key=\"include_polymorphed_hits\", label = \"Include Polymorph Damage Hits\", default = true, type = \"boolean\" },\n        { key=\"show_while_in_inventory\", label = \"Show In Inventory\", default = true, type = \"boolean\" },\n\n        { key=\"play_sound_on_hit\", label = \"Play Sound on Hit\", default = true, type = \"boolean\" },\n        { key=\"sound_volume\", label = \"Sound Volume\", default = 10, type = \"range\", type_data = { min = 0, max = 20, value_callback = function( value ) return math.floor( value + 0.5 ); end } },\n        { key=\"time_between_sounds\", label = \"Time Between Sounds\", default = 15, type = \"range\", type_data = { min = 1, max = 120, value_callback = function( value ) return math.floor( value + 0.5 ); end } },\n\n        { key=\"visibility\", label = \"Visibility\", default = 1.0, type = \"range\", type_data = { min = 0.01, max = 1.0, text_callback = function( value ) return math.floor( value * 100 )..\"%\"; end } },\n        { key=\"gui_x\", label = \"X\", default = 24, type = \"range\", type_data = { min = 0, max = screen_width, value_callback = function( value ) return math.floor( value + 0.5 ); end } },\n        { key=\"gui_y\", label = \"Y\", default = 39, type = \"range\", type_data = { min = 0, max = screen_height, value_callback = function( value ) return math.floor( value + 0.5 ); end } },\n        { key=\"inventory_gui_x\", label = \"Inventory X\", default = 24, type = \"range\", type_data = { min = 0, max = screen_width, value_callback = function( value ) return math.floor( value + 0.5 ); end } },\n        { key=\"inventory_gui_y\", label = \"Inventory Y\", default = 350, type = \"range\", type_data = { min = 0, max = screen_width, value_callback = function( value ) return math.floor( value + 0.5 ); end } },\n        { key=\"position_string\", label = \"Position String\", default = \"X %1d\", type = \"input\", validation_callback = pattern_validation },\n        { key=\"depth_string\", label = \"Depth String\", default = \"Y %1d\", type = \"input\", validation_callback = pattern_validation },\n        { key=\"time_string\", label = \"Time String\", default = \"%s\", type = \"input\", validation_callback = pattern_validation },\n        { key=\"hits_string\", label = \"Hits String\", default = \"%1d Hits\", type = \"input\", validation_callback = pattern_validation },\n        { key=\"hit_string\", label = \"Hit String\", default = \"%1d Hit\", type = \"input\", validation_callback = pattern_validation },\n        { key=\"polymorph_hits_string\", label = \"Polymorph Hits String\", default = \"%1d Hits (+%1d)\", type = \"input\", validation_callback = pattern_validation },\n        { key=\"polymorph_hit_string\", label = \"Polymorph Hit String\", default = \"%1d Hit (+%1d)\", type = \"input\", validation_callback = pattern_validation },\n        { key=\"separator\", label = \"Separator\", default = \" - \", type = \"input\", validation_callback = pattern_validation },\n        { key=\"hit_message_string\", label = \"Hit Message String\", default = \"You were hit for %.3f damage!\", type = \"input\", validation_callback = pattern_validation },\n    };\n\n    for _,setting in ipairs( mod_settings ) do\n        if ModSettingGet( mod_settings_id..\".\"..setting.key ) == nil then\n            ModSettingSet( mod_settings_id..\".\"..setting.key, setting.default );\n        end\n        setting.current = ModSettingGet( mod_settings_id..\".\"..setting.key );\n    end\nend\n\nlocal gui_functions = {\n    boolean = function( setting )\n        if GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/ui_timer_hits/files/gui/checkbox\" .. (setting.current == true and \"_fill\" or \"\") .. \".png\" ) then\n            setting.current = not setting.current;\n            ModSettingSet( mod_settings_id..\".\"..setting.key, setting.current );\n            GuiLayoutAddVerticalSpacing( gui, 1 );\n        end\n    end,\n    range = function( setting )\n        local new_value = GuiSlider( gui, next_id(), -2, 0, \"\", setting.current, setting.type_data.min, setting.type_data.max, setting.default, 1.0, \" \", 100 );\n        if setting.type_data.value_callback ~= nil then\n            new_value = setting.type_data.value_callback( new_value );\n        end\n        if setting.current ~= new_value then\n            setting.current = new_value;\n            ModSettingSet( mod_settings_id..\".\"..setting.key, setting.current );\n        end\n    end,\n    input = function( setting )\n        local new_value = GuiTextInput( gui, next_id(), 0, 0, setting.current, 200, 100 );\n        if setting.current ~= new_value then\n            setting.current = new_value;\n            ModSettingSet( mod_settings_id..\".\"..setting.key, setting.current );\n        end\n    end,\n}\n\nlocal function safe_string_format( format, ... )\n    local s = \"\";\n    local status,result = pcall( function(...)\n        s = string.format( format, ... );\n    end, ... );\n    if status == false then return \"err\"; end \n    return s;\nend\n\nfunction do_gui()\n    id_offset = 1;\n    GuiStartFrame( gui );\n    screen_width, screen_height = GuiGetScreenDimensions( gui );\n    if not mod_settings_parsed then parse_mod_settings(); mod_settings_parsed = true; end\n    if not GameIsInventoryOpen() then\n        GuiOptionsAdd( gui, GUI_OPTION.NoPositionTween );\n        GuiLayoutBeginVertical( gui, 5, 15 );\n        if is_panel_open then\n            GuiBeginScrollContainer( gui, next_id(), 0, 0, 400, 200, false );\n                GuiLayoutBeginVertical( gui, 0, 0 );\n                    GuiColorSetForNextWidget( gui, 0.5, 0.5, 0.5, 1.0 );\n                    GuiOptionsAddForNextWidget( gui, GUI_OPTION.TextRichRendering );\n                    GuiText( gui, 0, 0, \"UI Timer / Hits Options\" );\n                    GuiLayoutBeginHorizontal( gui, 0, 0 );\n                        GuiLayoutBeginVertical( gui, 0, 0 );\n                            for _,setting in ipairs( mod_settings ) do\n                                GuiText( gui, 0, 0, setting.label );\n                                if setting.tooltip then GuiTooltip( gui, setting.tooltip, \"\"); end\n                            end   \n                        GuiLayoutEnd( gui );\n                        \n                        GuiLayoutAddHorizontalSpacing( gui, 1 );\n                        GuiLayoutAddHorizontalSpacing( gui, 1 );\n                        GuiLayoutAddHorizontalSpacing( gui, 1 );\n                        GuiLayoutAddHorizontalSpacing( gui, 1 );\n\n                        GuiLayoutBeginVertical( gui, 0, 0 );\n                            for _,setting in ipairs( mod_settings ) do\n                                GuiLayoutBeginHorizontal( gui, 0, 0 );\n                                    if gui_functions[setting.type] then\n                                        gui_functions[setting.type]( setting );\n                                        if setting.validation_callback then\n                                            local result = setting.validation_callback( setting.current );\n                                            if result ~= true then\n                                                GuiTooltip( gui, word_wrap( result ), \"\" );\n                                            end\n                                        end\n                                    end\n                                    if setting.type == \"range\" then\n                                        if setting.type_data.text_callback then\n                                            GuiText( gui, 0, 0, setting.type_data.text_callback( setting.current ) );\n                                        else\n                                            GuiText( gui, 0, 0, tostring( setting.current ) );\n                                        end\n                                    end\n                                GuiLayoutEnd( gui );\n                                if setting.type == \"range\" then\n                                    GuiLayoutAddVerticalSpacing( gui, -2 );\n                                elseif setting.type == \"input\" then\n                                    GuiLayoutAddVerticalSpacing( gui, -2 );\n                                end\n                            end   \n                        GuiLayoutEnd( gui );\n                    GuiLayoutEnd( gui );\n                GuiLayoutEnd( gui );\n            GuiEndScrollContainer( gui );\n        end\n        GuiLayoutEnd( gui );\n        GuiOptionsRemove( gui, GUI_OPTION.NoPositionTween );\n    end\n\n    local gx = ModSettingGet(\"ui_timer_hits.gui_x\" );\n    local gy = ModSettingGet(\"ui_timer_hits.gui_y\" );\n    local text = \"\";\n    local player = ( EntityGetWithTag( \"player_unit\" ) or {} )[1];\n    if player == nil then\n        player = ( find_polymorphed_players() or {} )[1];\n    end\n    if player ~= nil then\n        local x, y = EntityGetTransform( player );\n        id_offset = 0;\n\n        local is_inventory_open = false;\n        if GameHasFlagRun( \"gkbrkn_config_menu_open\" ) or GameIsInventoryOpen() then\n            is_inventory_open = true;\n        end\n        if is_inventory_open then\n            gx = ModSettingGet(\"ui_timer_hits.inventory_gui_x\" );\n            gy = ModSettingGet(\"ui_timer_hits.inventory_gui_y\" );\n        end\n\n        if ModSettingGet( \"ui_timer_hits.show_while_in_inventory\" ) == true or not is_inventory_open then\n            local entries = {};\n\n            if ModSettingGet( \"ui_timer_hits.show_time\" ) then\n                --if USE_GAME_FRAMES_FOR_TIMER then\n                --    text = \"Time: \"..math.floor( GameGetFrameNum() / 60 ) .. \" \";\n                --end\n                table.insert( entries, safe_string_format( ModSettingGet( \"ui_timer_hits.time_string\"), StatsGetValue( \"playtime_str\" ) ) );\n            end\n            if ModSettingGet( \"ui_timer_hits.show_hits\" ) then\n                --local hit_count = EntityGetVariableNumber( player, \"ui_timer_hits_total_hits\", 0 );\n                local hit_count = tonumber( GlobalsGetValue( \"ui_timer_hits_player_hits\", \"0\" ) );\n                local poly_hit_count = tonumber( GlobalsGetValue( \"ui_timer_hits_poly_player_hits\", \"0\" ) );\n                if ModSettingGet( \"ui_timer_hits.include_polymorphed_hits\" ) then\n                    if hit_count == 1 then\n                        table.insert( entries, safe_string_format( ModSettingGet( \"ui_timer_hits.polymorph_hit_string\" ), hit_count, poly_hit_count ) );\n                    else\n                        table.insert( entries, safe_string_format( ModSettingGet( \"ui_timer_hits.polymorph_hits_string\" ), hit_count, poly_hit_count ) );\n                    end\n                else\n                    if hit_count == 1 then\n                        table.insert( entries, safe_string_format( ModSettingGet( \"ui_timer_hits.hit_string\" ), hit_count, poly_hit_count ) );\n                    else\n                        table.insert( entries, safe_string_format( ModSettingGet( \"ui_timer_hits.hits_string\" ), hit_count, poly_hit_count ) );\n                    end\n                end\n            end\n            if ModSettingGet( \"ui_timer_hits.show_position\" ) then\n                table.insert( entries, safe_string_format( ModSettingGet( \"ui_timer_hits.position_string\" ), math.floor( x ) ) );\n            end\n            if ModSettingGet( \"ui_timer_hits.show_depth\" ) then\n                table.insert( entries, safe_string_format( ModSettingGet( \"ui_timer_hits.depth_string\" ), math.floor( y / 10 ) ) );\n            end\n\n            for index,entry in ipairs( entries ) do\n                text = text .. entry;\n                if index ~= #entries then\n                    text = text .. ModSettingGet( \"ui_timer_hits.separator\" );\n                end\n            end\n        end\n    end\n    GuiLayoutBeginVertical( gui, 0, 0 );\n    GuiColorSetForNextWidget( gui, 1.0, 1.0, 1.0, ModSettingGet( \"ui_timer_hits.visibility\" ) );\n    if GuiButton( gui, next_id(), gx, gy, text ) then\n        is_panel_open = not is_panel_open;\n    end\n    GuiLayoutEnd( gui );\nend\n\nif gui then\n    async_loop(function()\n        if gui then\n            local status, err = pcall( do_gui );\n            if err then\n                GamePrint(\"Goki Says: PLEASE LET ME KNOW ABOUT THIS\");\n                GamePrint(err);\n                print(\"Goki Says: PLEASE LET ME KNOW ABOUT THIS\");\n                print(err);\n                print_error(\"Goki Says: PLEASE LET ME KNOW ABOUT THIS\");\n                print_error(err);\n            end\n        end\n        wait( 0 );\n    end);\nend\n"
_TWWE_VFS["mods/ui_timer_hits/files/gui/container.xml"] = "<Entity tags=\"ui_depth_gui\">\n  <LuaComponent\n    script_source_file=\"mods/ui_timer_hits/files/gui/update.lua\"\n    vm_type=\"ONE_PER_COMPONENT_INSTANCE\"\n    enable_coroutines=\"1\"\n    execute_on_added=\"1\"\n    execute_times=\"1\"\n    execute_every_n_frame=\"-1\"\n    >\n  </LuaComponent>\n</Entity>\n"
_TWWE_VFS["mods/ui_timer_hits/files/gui/update.lua"] = "print(\"[ui_timer] setting up GUI\")\ndofile_once(\"data/scripts/lib/coroutines.lua\")\ndofile_once(\"mods/ui_timer_hits/files/lib/variables.lua\")\ndofile_once(\"mods/ui_timer_hits/files/lib/helper.lua\")\ndofile_once(\"data/scripts/lib/utilities.lua\")\n\nlocal function truncate_long_string(str)\n    if #str > 31 then\n        str = str:sub(0, 14) .. \"...\" .. str:sub(-14)\n    end\n    return str\nend\n\nlocal function pattern_validation(value)\n    local status, result = pcall(function()\n        local s = string.format(value, 0, 0, 0, 0, 0, 0, 0, 0)\n    end)\n    if status == false then\n        return result\n    end\n    return true\nend\n\nlocal function safe_string_format(format, ...)\n    local s = \"\"\n    local status, result = pcall(function(...)\n        s = string.format(format, ...)\n    end, ...)\n    if status == false then\n        return \"err\"\n    end\n    return s\nend\n\nlocal gui = gui or GuiCreate()\nlocal full_screen_width, full_screen_height = GuiGetScreenDimensions(gui)\nGuiStartFrame(gui)\nlocal screen_width, screen_height = GuiGetScreenDimensions(gui)\n\nlocal gokiui = dofile_once(\"mods/ui_timer_hits/files/mod_settings.lua\")(gui, 2, \"ui_timer_hits\", {\n    { key = \"show_position\", label = \"Show Position\", default = true, type = \"boolean\" },\n    { key = \"show_depth\", label = \"Show Depth\", default = true, type = \"boolean\" },\n    { key = \"show_time\", label = \"Show Time\", default = true, type = \"boolean\" },\n    { key = \"show_hits\", label = \"Show Hits\", default = true, type = \"boolean\" },\n    { key = \"show_hit_message\", label = \"Log Hits\", default = false, type = \"boolean\" },\n    { key = \"include_environmental_hits\", label = \"Include Environmental Damage Hits\", default = true, type = \"boolean\" },\n    { key = \"include_negative_damage\", label = \"Include Negative Damage Hits\", default = false, type = \"boolean\" },\n    { key = \"include_self_damage_hits\", label = \"Include Self Damage Hits\", default = true, type = \"boolean\" },\n    { key = \"include_polymorphed_hits\", label = \"Include Polymorph Damage Hits\", default = true, type = \"boolean\" },\n    { key = \"show_while_in_inventory\", label = \"Show In Inventory\", default = true, type = \"boolean\" },\n    { key = \"play_sound_on_hit\", label = \"Play Sound on Hit\", default = true, type = \"boolean\" },\n    { key = \"sound_volume\", label = \"Sound Volume\", default = 10, type = \"range\", type_data = { min = 0, max = 20, value_callback = function(value) return math.floor(value + 0.5) end } },\n    { key = \"time_between_sounds\", label = \"Time Between Sounds\", default = 15, type = \"range\", type_data = { min = 1, max = 120, value_callback = function(value) return math.floor(value + 0.5) end } },\n    { key = \"visibility\", label = \"Visibility\", default = 1.0, type = \"range\", type_data = { min = 0.01, max = 1.0, text_callback = function(value) return math.floor(value * 100) .. \"%\" end } },\n    { key = \"gui_x\", label = \"X\", default = 24, type = \"range\", type_data = { min = 0, max = screen_width, value_callback = function(value) return math.floor(value + 0.5) end } },\n    { key = \"gui_y\", label = \"Y\", default = 39, type = \"range\", type_data = { min = 0, max = screen_height, value_callback = function(value) return math.floor(value + 0.5) end } },\n    { key = \"inventory_gui_x\", label = \"Inventory X\", default = 24, type = \"range\", type_data = { min = 0, max = screen_width, value_callback = function(value) return math.floor(value + 0.5) end } },\n    { key = \"inventory_gui_y\", label = \"Inventory Y\", default = 350, type = \"range\", type_data = { min = 0, max = screen_width, value_callback = function(value) return math.floor(value + 0.5) end } },\n    { key = \"position_string\", label = \"Position String\", default = \"X %.2f\", type = \"input\", validation_callback = pattern_validation },\n    { key = \"depth_string\", label = \"Depth String\", default = \"Y %.2f\", type = \"input\", validation_callback = pattern_validation },\n    { key = \"time_string\", label = \"Time String\", default = \"%s\", type = \"input\", validation_callback = pattern_validation },\n    { key = \"hits_string\", label = \"Hits String\", default = \"%1d Hits\", type = \"input\", validation_callback = pattern_validation },\n    { key = \"hit_string\", label = \"Hit String\", default = \"%1d Hit\", type = \"input\", validation_callback = pattern_validation },\n    { key = \"polymorph_hits_string\", label = \"Polymorph Hits String\", default = \"%1d Hits (+%1d)\", type = \"input\", validation_callback = pattern_validation },\n    { key = \"polymorph_hit_string\", label = \"Polymorph Hit String\", default = \"%1d Hit (+%1d)\", type = \"input\", validation_callback = pattern_validation },\n    { key = \"separator\", label = \"Separator\", default = \" - \", type = \"input\", validation_callback = pattern_validation },\n    { key = \"hit_message_string\", label = \"Hit Message String\", default = \"You were hit for %.3f damage!\", type = \"input\", validation_callback = pattern_validation },\n})\n\nlocal next_id = gokiui.next_id\nlocal reset_id = gokiui.reset_id\n\nfunction do_gui()\n    reset_id()\n    GuiStartFrame(gui)\n    screen_width, screen_height = GuiGetScreenDimensions(gui)\n    gokiui.parse_mod_settings()\n    if not GameIsInventoryOpen() then\n        GuiOptionsAdd(gui, GUI_OPTION.NoPositionTween)\n        GuiLayoutBeginVertical(gui, 5, 15)\n        if is_panel_open then\n            GuiBeginScrollContainer(gui, next_id(), 0, 0, 400, 200, false)\n            GuiLayoutBeginVertical(gui, 0, 0)\n            GuiColorSetForNextWidget(gui, 0.5, 0.5, 0.5, 1.0)\n            GuiOptionsAddForNextWidget(gui, GUI_OPTION.TextRichRendering)\n            GuiText(gui, 0, 0, \"UI Timer / Hits Options\")\n            GuiLayoutBeginHorizontal(gui, 0, 0)\n\n            gokiui.do_gui()\n\n            GuiLayoutEnd(gui)\n            GuiLayoutEnd(gui)\n            GuiEndScrollContainer(gui)\n        end\n        GuiLayoutEnd(gui)\n        GuiOptionsRemove(gui, GUI_OPTION.NoPositionTween)\n    end\n\n    local gx = ModSettingGet(\"ui_timer_hits.gui_x\")\n    local gy = ModSettingGet(\"ui_timer_hits.gui_y\")\n    local text = \"\"\n    local player = (EntityGetWithTag(\"player_unit\") or {})[1]\n    if player == nil then\n        player = (find_polymorphed_players() or {})[1]\n    end\n    if player ~= nil then\n        local x, y = EntityGetTransform(player)\n        id_offset = 0\n\n        local is_inventory_open = false\n        if GameHasFlagRun(\"gkbrkn_config_menu_open\") or GameIsInventoryOpen() then\n            is_inventory_open = true\n        end\n        if is_inventory_open then\n            gx = ModSettingGet(\"ui_timer_hits.inventory_gui_x\")\n            gy = ModSettingGet(\"ui_timer_hits.inventory_gui_y\")\n        end\n\n        if ModSettingGet(\"ui_timer_hits.show_while_in_inventory\") == true or not is_inventory_open then\n            local entries = {}\n\n            if ModSettingGet(\"ui_timer_hits.show_time\") then\n                table.insert(entries, safe_string_format(ModSettingGet(\"ui_timer_hits.time_string\"), StatsGetValue(\"playtime_str\")))\n            end\n            if ModSettingGet(\"ui_timer_hits.show_hits\") then\n                local hit_count = tonumber(GlobalsGetValue(\"ui_timer_hits_player_hits\", \"0\"))\n                local poly_hit_count = tonumber(GlobalsGetValue(\"ui_timer_hits_poly_player_hits\", \"0\"))\n                if ModSettingGet(\"ui_timer_hits.include_polymorphed_hits\") then\n                    if hit_count == 1 then\n                        table.insert(entries, safe_string_format(ModSettingGet(\"ui_timer_hits.polymorph_hit_string\"), hit_count, poly_hit_count))\n                    else\n                        table.insert(entries, safe_string_format(ModSettingGet(\"ui_timer_hits.polymorph_hits_string\"), hit_count, poly_hit_count))\n                    end\n                else\n                    if hit_count == 1 then\n                        table.insert(entries, safe_string_format(ModSettingGet(\"ui_timer_hits.hit_string\"), hit_count, poly_hit_count))\n                    else\n                        table.insert(entries, safe_string_format(ModSettingGet(\"ui_timer_hits.hits_string\"), hit_count, poly_hit_count))\n                    end\n                end\n            end\n            if ModSettingGet(\"ui_timer_hits.show_position\") then\n                table.insert(entries, safe_string_format(ModSettingGet(\"ui_timer_hits.position_string\"), x))\n            end\n            if ModSettingGet(\"ui_timer_hits.show_depth\") then\n                table.insert(entries, safe_string_format(ModSettingGet(\"ui_timer_hits.depth_string\"), y))\n            end\n\n            for index, entry in ipairs(entries) do\n                text = text .. entry\n                if index ~= #entries then\n                    text = text .. ModSettingGet(\"ui_timer_hits.separator\")\n                end\n            end\n        end\n    end\n    GuiLayoutBeginVertical(gui, 0, 0)\n    GuiColorSetForNextWidget(gui, 1.0, 1.0, 1.0, ModSettingGet(\"ui_timer_hits.visibility\"))\n    if GuiButton(gui, next_id(), gx, gy, text) then\n        is_panel_open = not is_panel_open\n    end\n    GuiLayoutEnd(gui)\nend\n\nif gui then\n    async_loop(function()\n        if gui then\n            local status, err = pcall(do_gui)\n            if err then\n                GamePrint(\"Goki Says: PLEASE LET ME KNOW ABOUT THIS\")\n                GamePrint(err)\n                print(\"Goki Says: PLEASE LET ME KNOW ABOUT THIS\")\n                print(err)\n                print_error(\"Goki Says: PLEASE LET ME KNOW ABOUT THIS\")\n                print_error(err)\n            end\n        end\n        wait(0)\n    end)\nend\n"
_TWWE_VFS["mods/ui_timer_hits/files/lib/helper.lua"] = "function find_polymorphed_players()\n    local nearby_polymorph = EntityGetWithTag( \"polymorphed\" ) or {};\n    local polymorphed_players = {};\n    for _,entity in pairs( nearby_polymorph ) do\n        local game_stats = EntityGetFirstComponent( entity, \"GameStatsComponent\" );\n        if game_stats ~= nil then\n            if ComponentGetValue( game_stats, \"is_player\" ) == \"1\" then\n                table.insert( polymorphed_players, entity );\n            end\n        end\n    end\n    return polymorphed_players;\nend"
_TWWE_VFS["mods/ui_timer_hits/files/lib/variables.lua"] = "function EntityGetVariableString( entity, variable_tag, default )\n    local variable = EntityGetFirstComponent( entity, \"VariableStorageComponent\", variable_tag );\n    if variable ~= nil then\n        return ComponentGetValue( variable, \"value_string\" );\n    end\n    return default;\nend\n\nfunction EntitySetVariableString( entity, variable_tag, value )\n    local current_variable = EntityGetFirstComponent( entity, \"VariableStorageComponent\", variable_tag );\n    if current_variable == nil then\n        EntityAddComponent( entity, \"VariableStorageComponent\", {\n            _tags=variable_tag..\",enabled_in_world,enabled_in_hand,enabled_in_inventory\",\n            value_string=tostring(value)\n        } );\n    else\n        ComponentSetValue( current_variable, \"value_string\", tostring( value ) );\n    end\nend\n\nfunction EntityGetVariableNumber( entity, variable_tag, default )\n    return tonumber( EntityGetVariableString( entity, variable_tag, default ) );\nend\n\nfunction EntitySetVariableNumber( entity, variable_tag, value )\n    return EntitySetVariableString( entity, variable_tag, value );\nend\n\nfunction EntityAdjustVariableNumber( entity, variable_tag, default, callback )\n    EntitySetVariableNumber( entity, variable_tag, callback( EntityGetVariableNumber( entity, variable_tag, default ) ) );\nend\n"
_TWWE_VFS["mods/ui_timer_hits/files/mod_settings.lua"] = "return function( gui, gui_id, mod_settings_id, mod_settings )\n    local id_offset = 0;\n\n    local function word_wrap( str, wrap_size )\n        if str then\n            if wrap_size == nil then wrap_size = 60; end\n            local last_space_index = 1;\n            local last_wrap_index = 0;\n            for i=1,#str do\n                if str:sub(i,i) == \" \" then\n                    last_space_index = i;\n                end\n                if str:sub(i,i) == \"\\n\" then\n                    last_space_index = i;\n                    last_wrap_index = i;\n                end\n                if i - last_wrap_index > wrap_size then\n                    str = str:sub(1,last_space_index-1) .. \"\\n\" .. str:sub(last_space_index + 1);\n                    last_wrap_index = i;\n                end\n            end\n            return str;\n        end\n        return \"\";\n    end\n\n    local function reset_id()\n        id_offset = 1;\n    end\n\n    local function next_id()\n        id_offset = id_offset + 1;\n        return gui_id + id_offset;\n    end\n\n    local is_panel_open = false;\n    local has_been_parsed = false;\n    local function parse_mod_settings()\n        if not has_been_parsed then\n            has_been_parsed = true;\n            for _,setting in ipairs( mod_settings ) do\n                if ModSettingGet( mod_settings_id..\".\"..setting.key ) == nil then\n                    ModSettingSet( mod_settings_id..\".\"..setting.key, setting.default );\n                end\n                setting.current = ModSettingGet( mod_settings_id..\".\"..setting.key );\n            end\n        end\n    end\n\n    local gui_functions = {\n        boolean = function( setting )\n            if GuiImageButton( gui, next_id(), 0, 0, \"\", \"mods/ui_timer_hits/files/gui/checkbox\" .. (setting.current == true and \"_fill\" or \"\") .. \".png\" ) then\n                setting.current = not setting.current;\n                ModSettingSet( mod_settings_id..\".\"..setting.key, setting.current );\n                GuiLayoutAddVerticalSpacing( gui, 1 );\n            end\n        end,\n        range = function( setting )\n            local new_value = GuiSlider( gui, next_id(), -2, 0, \"\", setting.current, setting.type_data.min, setting.type_data.max, setting.default, 1.0, \" \", 100 );\n            if setting.type_data.value_callback ~= nil then\n                new_value = setting.type_data.value_callback( new_value );\n            end\n            if setting.current ~= new_value then\n                setting.current = new_value;\n                ModSettingSet( mod_settings_id..\".\"..setting.key, setting.current );\n            end\n        end,\n        input = function( setting )\n            local new_value = GuiTextInput( gui, next_id(), 0, 0, setting.current, 200, 100 );\n            if setting.current ~= new_value then\n                setting.current = new_value;\n                ModSettingSet( mod_settings_id..\".\"..setting.key, setting.current );\n            end\n        end,\n    }\n\n    local function do_gui()\n        GuiLayoutBeginVertical( gui, 0, 0 );\n            for _,setting in ipairs( mod_settings ) do\n                GuiText( gui, 0, 0, setting.label );\n                if setting.tooltip then GuiTooltip( gui, setting.tooltip, \"\"); end\n            end   \n        GuiLayoutEnd( gui );\n        \n        GuiLayoutAddHorizontalSpacing( gui, 1 );\n        GuiLayoutAddHorizontalSpacing( gui, 1 );\n        GuiLayoutAddHorizontalSpacing( gui, 1 );\n        GuiLayoutAddHorizontalSpacing( gui, 1 );\n\n        GuiLayoutBeginVertical( gui, 0, 0 );\n            for _,setting in ipairs( mod_settings ) do\n                GuiLayoutBeginHorizontal( gui, 0, 0 );\n                    if gui_functions[setting.type] then\n                        gui_functions[setting.type]( setting );\n                        if setting.validation_callback then\n                            local result = setting.validation_callback( setting.current );\n                            if result ~= true then\n                                GuiTooltip( gui, word_wrap( result ), \"\" );\n                            end\n                        end\n                    end\n                    if setting.type == \"range\" then\n                        if setting.type_data.text_callback then\n                            GuiText( gui, 0, 0, setting.type_data.text_callback( setting.current ) );\n                        else\n                            GuiText( gui, 0, 0, tostring( setting.current ) );\n                        end\n                    elseif setting.type == \"input\" then\n                        if GuiButton( gui, next_id(), 0, 0, \"[Reset]\" ) then\n                            ModSettingSet( mod_settings_id..\".\"..setting.key, setting.default );\n                            setting.current = setting.default;\n                        end\n                    end\n                GuiLayoutEnd( gui );\n                if setting.type == \"range\" then\n                    GuiLayoutAddVerticalSpacing( gui, -2 );\n                elseif setting.type == \"input\" then\n                    GuiLayoutAddVerticalSpacing( gui, -2 );\n                end\n            end   \n        GuiLayoutEnd( gui );\n    end\n\n    return {\n        reset_id = reset_id,\n        next_id = next_id,\n        parse_mod_settings = parse_mod_settings,\n        do_gui = do_gui\n    }\nend"
_TWWE_VFS["mods/ui_timer_hits/files/scripts/player_damage_received.lua"] = "dofile_once( \"mods/ui_timer_hits/files/lib/variables.lua\" );\n\nlast_sound_played = 0;\n\nfunction damage_received( damage, message, entity_thats_responsible, is_fatal  )\n    local entity = tonumber( GetUpdatedEntityID() );\n    local counted_hit = false;\n    if tonumber( entity_thats_responsible ) == 0 then\n        if ModSettingGet( \"ui_timer_hits.include_environmental_hits\" ) then counted_hit = true; end\n    elseif tonumber( entity_thats_responsible ) == entity then\n        if ModSettingGet( \"ui_timer_hits.include_self_damage_hits\" ) then counted_hit = true; end\n    else\n        counted_hit = true;\n    end\n    -- If damage would be negative and counted, but we don't include negative damage, reset counted to false\n    if counted_hit and damage < 0 and ModSettingGet( \"ui_timer_hits.include_negative_damage\" ) ~= true then counted_hit = false; end\n    if counted_hit then\n        local current_hits = tonumber( GlobalsGetValue( \"ui_timer_hits_player_hits\", \"0\" ) );\n        GlobalsSetValue( \"ui_timer_hits_player_hits\", tostring( current_hits + 1 ) );\n        --EntityAdjustVariableNumber( entity, \"ui_timer_hits_player_hits\", 0, function( value ) return tonumber( value ) + 1 end );\n        if ModSettingGet( \"ui_timer_hits.play_sound_on_hit\" ) then\n            local now = GameGetFrameNum();\n            if now - last_sound_played >= ModSettingGet( \"ui_timer_hits.time_between_sounds\" ) then\n                last_sound_played = now;\n                local x, y = EntityGetTransform( entity );\n                for i=1,math.min( ModSettingGet( \"ui_timer_hits.sound_volume\" ), 10 ) do\n                    GamePlaySound( \"data/audio/Desktop/animals.snd\", \"animals/mine/beep\", x, y );\n                end\n            end\n        end\n        if ModSettingGet( \"ui_timer_hits.show_hit_message\" ) then\n            GamePrint( string.format( ModSettingGet( \"ui_timer_hits.hit_message_string\" ), damage * 25, GameTextGetTranslatedOrNot( message ) ) );\n        end\n    end\nend\n"
_TWWE_VFS["mods/ui_timer_hits/files/scripts/poly_player_damage_received.lua"] = "dofile_once( \"mods/ui_timer_hits/files/lib/variables.lua\" );\n\nlast_sound_played = 0;\n\nfunction damage_received( damage, message, entity_thats_responsible, is_fatal  )\n    local entity = tonumber( GetUpdatedEntityID() );\n    local counted_hit = false;\n    if tonumber( entity_thats_responsible ) == 0 then\n        if ModSettingGet( \"ui_timer_hits.include_environmental_hits\" ) then counted_hit = true; end\n    elseif tonumber( entity_thats_responsible ) == entity then\n        if ModSettingGet( \"ui_timer_hits.include_self_damage_hits\" ) then counted_hit = true; end\n    else\n        counted_hit = true;\n    end\n    -- If damage would be negative and counted, but we don't include negative damage, reset counted to false\n    if counted_hit and damage < 0 and ModSettingGet( \"ui_timer_hits.include_negative_damage\" ) ~= true then counted_hit = false; end\n    if counted_hit then\n        local current_hits = tonumber( GlobalsGetValue( \"ui_timer_hits_poly_player_hits\", \"0\" ) );\n        GlobalsSetValue( \"ui_timer_hits_poly_player_hits\", tostring( current_hits + 1 ) );\n        --EntityAdjustVariableNumber( entity, \"ui_timer_hits_player_hits\", 0, function( value ) return tonumber( value ) + 1 end );\n        if ModSettingGet( \"ui_timer_hits.play_sound_on_hit\" ) then\n            local now = GameGetFrameNum();\n            if now - last_sound_played >= ModSettingGet( \"ui_timer_hits.time_between_sounds\" ) then\n                last_sound_played = now;\n                local x, y = EntityGetTransform( entity );\n                for i=1,math.min( ModSettingGet( \"ui_timer_hits.sound_volume\" ), 10 ) do\n                    GamePlaySound( \"data/audio/Desktop/animals.snd\", \"animals/mine/beep\", x, y );\n                end\n            end\n        end\n        if ModSettingGet( \"ui_timer_hits.show_hit_message\" ) then\n            GamePrint( string.format( ModSettingGet( \"ui_timer_hits.hit_message_string\" ), damage * 25, GameTextGetTranslatedOrNot( message ) ) );\n        end\n    end\nend\n"
_TWWE_VFS["mods/ui_timer_hits/init.lua"] = "dofile_once( \"mods/ui_timer_hits/files/lib/helper.lua\");\ndofile_once( \"mods/ui_timer_hits/files/lib/variables.lua\");\n\nfunction OnWorldPreUpdate()\n    if INCLUDE_POLYMORPHED_HITS then\n        for _,player in pairs( find_polymorphed_players() or {} ) do\n            if EntityGetVariableNumber( player, \"ui_timer_poly_player\", 0 ) == 0 then\n                EntitySetVariableNumber( player, \"ui_timer_poly_player\", 1 );\n                EntityAddComponent( player, \"LuaComponent\", {\n                    script_damage_received=\"mods/ui_timer_hits/files/scripts/poly_player_damage_received.lua\"\n                });\n            end\n        end\n    end\nend\n\nfunction OnPlayerSpawned( player_entity )\n    EntityLoad('mods/ui_timer_hits/files/gui/container.xml');\n    local init_check_flag = \"ui_timer_hits_init\";\n    if GameHasFlagRun( init_check_flag ) == false then\n        GameAddFlagRun( init_check_flag );\n        EntityAddComponent( player_entity, \"LuaComponent\", {\n            script_damage_received=\"mods/ui_timer_hits/files/scripts/player_damage_received.lua\"\n        });\n    end\nend\n"
_TWWE_VFS["mods/ui_timer_hits/mod.xml"] = "<Mod\n    name=\"UI: Timer, Hits, Depth\"\n    description=\"Options to shows the timer, hits, and depth on the screen at all times.\"\n    request_no_api_restrictions=\"0\"\n> \n</Mod>\n\n<!-- \n    If a mod requires access to the full lua api e.g. os.* io.* it has to request access via 'request_no_api_restrictions=\"1\"'.\n    It is recommended that other options are explored first, as we may completely disable those APIs in the future.\n    By default mods have access to the table, string, math and bit libraries and to the APIs exposed by the game.\n -->\n"
_TWWE_VFS["mods/ui_timer_hits/mod_id.txt"] = "ui_timer_hits"
