ion(c) return c.friendly_fire end, default = false},\n    {name = \"physics_impulse_coeff\", get = function(c) return c.physics_impulse_coeff end, default = 0},\n    {name = \"lifetime_add\", get = function(c) return c.lifetime_add end, default = 0},\n    {name = \"sprite\", get = function(c) return c.sprite end, default = \"\"},\n    {name = \"extra_entities\", get = function(c) return c.extra_entities end, default = {}, format=format_cast_state_list},\n    {name = \"game_effect_entities\", get = function(c) return c.game_effect_entities end, default = \"\", format=format_comma_list},\n    {name = \"sound_loop_tag\", get = function(c) return c.sound_loop_tag end, default = \"\"},\n    {name = \"projectile_file\", get = function(c) return c.projectile_file end, default = \"\"},\n    -- {name = \"projectiles\", get = function(c) return c.projectiles end, default = \"\",\n    --  format=make_format_comma_list_with_images(\n    --      function(entity_filename)\n    --          local action = projectile_table[entity_filename]\n    --          if(action == nil) then\n    --              return \"data/ui_gfx/gun_actions/unidentified.png\"\n    --          end\n    --          if(action.normal ~= nil) then\n    --              return action.normal.sprite\n    --          elseif(action.timer ~= nil) then\n    --              return action.timer.sprite\n    --          elseif(action.trigger ~= nil) then\n    --              return action.trigger.sprite\n    --          elseif(action.death_trigger ~= nil) then\n    --              return action.death_trigger.sprite\n    --          end\n    --          return \"data/ui_gfx/gun_actions/unidentified.png\"\n    --      end\n    -- )},\n}\n"
_TWWE_VFS["mods/wand_dbg/files/debug_card.xml"] = "<Entity name=\"debug_card\">\n  <InheritTransformComponent>\n    <Transform position.x=\"0\" position.y=\"0\"></Transform>\n  </InheritTransformComponent>\n\n  <VelocityComponent _tags=\"enabled_in_world\" >\n  </VelocityComponent>\n\n  <VariableStorageComponent\n      name=\"x_target\"\n      value_float=\"0\" >\n  </VariableStorageComponent>\n\n  <VariableStorageComponent\n      name=\"y_target\"\n      value_float=\"0\" >\n  </VariableStorageComponent>\n\n  <VariableStorageComponent\n      name=\"omega\"\n      value_float=\"0\" >\n  </VariableStorageComponent>\n\n  <LuaComponent\n      script_source_file=\"mods/wand_dbg/files/move_card.lua\"\n      execute_every_n_frame=\"1\"\n      >\n  </LuaComponent>\n</Entity>\n"
_TWWE_VFS["mods/wand_dbg/files/debugger.lua"] = "init_debugger = function()\n    debugging = true\n    dofile( \"data/scripts/gun/gun.lua\" );\n\n    --Undo the modifications from Spell Lab\n    function register_action( state )\n        state.reload_time = current_reload_time\n        ConfigGunActionInfo_PassToGame( state )\n    end\n\n    local cast_history = {}\n\n    local action_trees = {}\n    local current_node = nil\n    local current_explanation = \"\"\n    local shot_type = \"root\"\n    local timeout_frames = 0\n\n    local removed_actions = {}\n    local inserted_actions = {}\n\n    local uses_table = {}\n\n    local table_insert = table.insert\n    local table_remove = table.remove\n\n    local original_order_deck = order_deck\n    function order_deck()\n        for i, a in ipairs(deck) do\n            a.temp_index = i\n        end\n        original_order_deck()\n        local order = {}\n        for i, a in ipairs(deck) do\n            order[i] = a.temp_index\n            a.temp_index = nil\n        end\n        make_snapshot(\"order_deck\", {order=order})\n    end\n\n    function move_discarded_to_deck()\n        for i,action in ipairs(discarded) do\n            table.insert(deck, action)\n        end\n        discarded = copy_table(discarded)\n        while #discarded > 0 do\n            table.remove(discarded, 1)\n        end\n    end\n\n    function move_hand_to_discarded()\n        for i,action in ipairs(hand) do\n\n            local identify = false\n\n            if got_projectiles or (action.type == ACTION_TYPE_OTHER) or (action.type == ACTION_TYPE_UTILITY) then -- ACTION_TYPE_MATERIAL, ACTION_TYPE_PROJECTILE are handled via got_projectiles\n                if action.uses_remaining > 0 then\n                    if action.custom_uses_logic then\n                        -- do nothing\n                    elseif action.is_identified then\n                        -- consume consumable actions\n                        action.uses_remaining = action.uses_remaining - 1\n                        local reduce_uses = ActionUsesRemainingChanged( action.inventoryitem_id, action.uses_remaining )\n                        if not reduce_uses then\n                            action.uses_remaining = action.uses_remaining + 1 -- cancel the reduction\n                        end\n                    end\n                end\n\n                identify = true\n            end\n\n            if identify then\n                ActionUsed( action.inventoryitem_id )\n                action.is_identified = true\n            end\n\n            if use_game_log then\n                if action.is_identified then\n                    LogAction( action.name )\n                else\n                    LogAction( \"?\" )\n                end\n            end\n\n            if action.uses_remaining ~= 0 or action.custom_uses_logic then\n                if action.permanently_attached == nil then\n                    table.insert( discarded, action )\n                end\n            end\n        end\n        hand = copy_table(hand)\n        while #hand > 0 do\n            if hand[1].permanently_attached == nil then\n                table.remove(hand, 1)\n            else\n                make_snapshot(\"delete_ac_card\", {source = \"hand\", index = 1, unique_ac_id = hand[1].unique_ac_id})\n                table_remove(hand, 1)\n            end\n        end\n    end\n\n    function action_reset()\n        current_reload_time = current_reload_time - 25\n\n        for i,v in ipairs( hand ) do\n            -- print( \"removed \" .. v.id .. \" from hand\" )\n            table.insert( discarded, v )\n        end\n\n        for i,v in ipairs( deck ) do\n            -- print( \"removed \" .. v.id .. \" from deck\" )\n            table.insert( discarded, v )\n        end\n\n        hand = copy_table(hand)\n        deck = copy_table(deck)\n\n        while #hand > 0 do\n            table.remove(hand, 1)\n        end\n        while #deck > 0 do\n            table.remove(deck, 1)\n        end\n\n        if ( force_stop_draws == false ) then\n            force_stop_draws = true\n            move_discarded_to_deck()\n            order_deck()\n        end\n    end\n\n    cast_state_list_metatable = {\n        __concat = function(list,b)\n            local action_id = \"\"\n            if(current_node == nil) then\n                action_id = \"from_wand\"\n            else\n                action_id = current_node.action.id\n            end\n\n            local identifier = action_id..\"{\"..b..\"}\"\n            list[identifier] = (list[identifier] or 0)+1\n\n            return list\n        end,\n    }\n    function new_cast_state_list()\n        local list = {}\n        setmetatable(list, cast_state_list_metatable)\n        return list\n    end\n\n    local cast_state_maybe_changed = false\n    function make_snapshot(event_type, info, copy_c)\n        local event = {\n            type = event_type,\n            info = info,\n            node = current_node,\n            c_final = c,\n        }\n        if(c.last_copy == nil or copy_c or cast_state_maybe_changed) then\n            event.c = {}\n            ConfigGunActionInfo_Copy(c, event.c)\n            c.last_copy = event.c\n            cast_state_maybe_changed = false\n        else\n            event.c = c.last_copy\n        end\n        table.insert(cast_history, event)\n    end\n\n    ConfigGunActionInfo_PassToGame = function()\n    end\n\n    ConfigGunShotEffects_PassToGame = function()\n    end\n\n    OnNotEnoughManaForAction = function()\n        --GamePrint(\"not enough mana\")\n    end\n\n    BeginProjectile = function(entity_filename)\n        current_projectile = entity_filename\n        projectile_list_add(c.projectiles, entity_filename)\n\n        local action = projectile_table[entity_filename]\n        if(action\n           and (action.normal==nil or action.normal.id ~= current_node.action.id)\n           and (action.timer==nil or action.timer.id ~= current_node.action.id)\n           and (action.trigger==nil or action.trigger.id ~= current_node.action.id)\n           and (action.death_trigger==nil or action.death_trigger.id ~= current_node.action.id)) then\n            current_node.flavor = current_node.flavor or {}\n            projectile_list_add(current_node.flavor, entity_filename)\n        end\n    end\n    EndProjectile = function()\n        current_projectile = \"\"\n    end\n    BeginTriggerTimer = function(frames)\n        shot_type = \"timer\"\n        timeout_frames = frames\n    end\n    BeginTriggerHitWorld = function()\n        shot_type = \"trigger\"\n    end\n    BeginTriggerDeath = function()\n        shot_type = \"death_trigger\"\n    end\n    EndTrigger = function()\n    end\n    SetProjectileConfigs = function()\n    end\n\n    local reloaded = false\n    StartReload = function()\n        reloaded = true\n        --GamePrint(\"not enough mana\")\n    end\n\n    ActionUsed = function(inventoryitem_id) end\n\n    OnActionPlayed = function(action_id)\n        if(action_id == nil) then action_id = \"nil\" end\n        --GamePrint(\"action \" .. action_id .. \" played\")\n    end\n\n    ActionUsesRemainingChanged = function(inventoryitem_id, uses_remaining)\n        if(uses_remaining < 0) then\n            return false\n        end\n        uses_table[inventoryitem_id] = uses_remaining\n        return true\n    end\n\n    draw_shot = function( shot, instant_reload_if_empty )\n        local c_old = c\n\n        c = shot.state\n\n        c.shot_type = shot_type\n        if(shot_type == \"timer\") then\n            c.timer = timeout_frames\n        end\n        c.parent_projectile = current_projectile\n        c.root_node = current_node\n\n        if(c_old ~= c) then\n            c_old_copy = {}\n            ConfigGunActionInfo_Copy(c_old, c_old_copy)\n            make_snapshot(\"new_cast_state\", {c_old=c_old_copy, c_old_final=c_old}, true)\n        end\n\n        shot_structure = {}\n        draw_actions( shot.num_of_cards_to_draw, instant_reload_if_empty )\n        register_action( shot.state )\n        SetProjectileConfigs()\n\n        make_snapshot(\"register_action\", {}, true)\n\n        c = c_old\n    end\n\n\n    local draw_total = 0\n    local draw_step = 0\n    local original_draw_actions = draw_actions\n    draw_actions = function(how_many, instant_reload_if_empty)\n        draw_total = how_many\n        draw_step = 0\n        if(current_node ~= nil) then\n            current_node.draw_how_many = how_many\n            if(dont_draw_actions) then\n                current_node.dont_draw_actions = true\n            end\n            if(playing_permanent_card) then\n                current_node.playing_permanent_card = true\n            end\n        end\n        original_draw_actions(how_many, instant_reload_if_empty)\n    end\n\n    local original_draw_action = draw_action\n    draw_action = function(instant_reload_if_empty)\n        local old_explanation = current_explanation\n        current_explanation = \"draw\"\n        draw_step = draw_step+1\n        local out = original_draw_action(instant_reload_if_empty)\n        if(not out) then\n            draw_step = draw_step-1\n        end\n        current_explanation = old_explanation\n        return out\n    end\n\n    local original_check_recursion = check_recursion\n    check_recursion = function(data, rec_)\n        local rec = original_check_recursion(data, rec_)\n        if(rec == -1) then\n            local node = {parent = current_node, children = {}, action = data, rec = recursion_level, iter = iteration, explanation=current_explanation, recursion_limited=true, event_index = #cast_history, end_event_index = #cast_history}\n            table.insert(current_node.children, node)\n        end\n        return rec\n    end\n\n    local adding_always_cast = false\n\n    local ac_play_actions = function(action)\n        OnActionPlayed( action.id )\n\n        table_insert(hand, action)\n        adding_always_cast = true\n\n        set_current_action( action )\n        action.action()\n\n        local is_projectile = false\n\n        if action.type == ACTION_TYPE_PROJECTILE then\n            is_projectile = true\n            got_projectiles = true\n        end\n\n        if  action.type == ACTION_TYPE_STATIC_PROJECTILE then\n            is_projectile = true\n            got_projectiles = true\n        end\n\n        if action.type == ACTION_TYPE_MATERIAL then\n            is_projectile = true\n            got_projectiles = true\n        end\n\n        if is_projectile then\n            for i,modifier in ipairs(active_extra_modifiers) do\n                extra_modifiers[modifier]()\n            end\n        end\n\n        current_reload_time = current_reload_time + ACTION_DRAW_RELOAD_TIME_INCREASE\n    end\n\n    function modify_action(action, is_always_cast)\n        local original_action = action.action\n        if(action.id == \"RESET\") then\n            original_action = action_reset\n        end\n        action.original_action = action.original_action or original_action\n        action.action = function( recursion_level, iteration, ...)\n            local node = {parent = current_node, children = {}, action = action, rec = recursion_level, iter = iteration, explanation=current_explanation}\n            if(current_explanation == \"draw\") then\n                node.draw_step = draw_step\n                node.draw_total = draw_total\n            end\n            table.insert(current_node.children, node)\n            current_node = node\n            if(is_always_cast and adding_always_cast) then\n                make_snapshot(\"add_ac_card\", {dest = \"hand\"})\n                adding_always_cast = false\n            end\n            current_explanation = action.id\n            make_snapshot(\"action\", {recursion_level=recursion_level, iteration=iteration})\n            cast_state_maybe_changed = true\n            node.event_index = #cast_history\n            local ret = action.original_action(recursion_level, iteration, unpack(arg or {}))\n            make_snapshot(\"action_end\", {recursion_level=recursion_level, iteration=iteration}, true)\n            node.end_event_index = #cast_history\n            current_node = node.parent\n            current_explanation = node.explanation\n            return ret\n        end\n    end\n\n    for i, action in ipairs(actions) do\n        modify_action(action, false)\n    end\n\n    function debug_wand(wand_deck, wand_stats)\n        dbglog_y = 0\n        mana = wand_stats.mana\n\n        cast_history = {}\n        action_trees = {}\n\n        removed_actions = {}\n        inserted_actions = {}\n\n        _clear_deck( false )\n        local start_deck = {}\n        local always_casts = {}\n        uses_table = {}\n\n        if(wand_deck ~= nil) then\n\n            -- GamePrint(\"maximize_uses = \"..tostring(wand_stats.maximize_uses) .. \", unlimited_spells = \"..tostring(wand_stats.unlimited_spells))\n            for i, card in ipairs(wand_deck) do\n                local inventoryitem_id = i\n                local is_identified = true\n\n                for j, action in ipairs(actions) do\n                    if action.id == card.id then\n                        action_clone = {}\n                        clone_action( action, action_clone )\n                        action_clone.original_action = action.original_action\n\n                        if(card.is_always_cast) then\n                            action_clone.permanently_attached = true\n                            action_clone.uses_remaining = -1\n                            action_clone.sprite = action.sprite\n                            action_clone.deck_index = nil\n                            table.insert(always_casts, action_clone)\n                        else\n                            action_clone.inventoryitem_id = inventoryitem_id\n                            action_clone.uses_remaining   = card.uses_remaining or -1\n                            action_clone.deck_index       = #deck\n                            action_clone.is_identified    = is_identified\n                            action_clone.sprite = action.sprite\n                            if(action.max_uses ~= nil and action.max_uses ~= -1 and wand_stats.maximize_uses ~= nil) then\n                                action_clone.uses_remaining = wand_stats.maximize_uses and action.max_uses or 0\n                            end\n                            if(wand_stats.unlimited_spells and not action.never_unlimited) then\n                                action_clone.uses_remaining = -1\n                            end\n                            -- GamePrint(action.id..\" uses = \"..action_clone.uses_remaining)\n                            uses_table[action_clone.inventoryitem_id] = action_clone.uses_remaining\n                            table.insert(deck, action_clone)\n                        end\n                        break\n                    end\n                end\n            end\n\n            for j, action in ipairs(deck) do\n                table.insert(start_deck, action)\n            end\n        end\n\n        -- for i, action in ipairs(deck) do\n        --     modify_action(action, false)\n        -- end\n\n        table.insert = function(t, i)\n            local table_name\n            if(t == discarded) then table_name = \"discarded\" end\n            if(t == hand)      then table_name = \"hand\" end\n            if(t == deck)      then table_name = \"deck\" end\n            if(table_name ~= nil) then\n                local found_matching_action = false\n                for j, r in ipairs(removed_actions) do\n                    if (r.action == i) then\n                        -- GuiText(gui, dbglog_x, dbglog_y, i.id .. \" \" .. table_name .. \" <- \" .. r.table_name)\n                        -- dbglog_y = dbglog_y+10\n                        make_snapshot(\"card_move\", {source = r.table_name, dest = table_name, index = r.index})\n                        table_remove(removed_actions, j)\n                        found_matching_action = true\n                        break\n                    end\n                end\n                if(not found_matching_action) then\n                    table_insert(inserted_actions, {table_name = table_name, action = i})\n                end\n            end\n\n            return table_insert(t, i)\n        end\n\n        table.remove = function(t, index)\n            local table_name\n            if(t == discarded) then table_name = \"discarded\" end\n            if(t == hand)      then table_name = \"hand\" end\n            if(t == deck)      then table_name = \"deck\" end\n            if(table_name ~= nil) then\n                local i = t[index]\n                local found_matching_action = false\n                for j, r in ipairs(inserted_actions) do\n                    if (r.action == i) then\n                        -- GuiText(gui, dbglog_x, dbglog_y, i.id .. \" \" .. r.table_name .. \" <- \" .. table_name)\n                        -- dbglog_y = dbglog_y+10\n                        make_snapshot(\"card_move\", {source = table_name, dest = r.table_name, index = index})\n                        table_remove(inserted_actions, j)\n                        found_matching_action = true\n                        break\n                    end\n                end\n                if(not found_matching_action) then\n                    table_insert(removed_actions, {table_name = table_name, action = i, index = index})\n                end\n            end\n\n            return table_remove(t, index)\n        end\n\n        local original_ConfigGunActionInfo_Init = ConfigGunActionInfo_Init\n        local original_ConfigGunActionInfo_Copy = ConfigGunActionInfo_Copy\n\n        ConfigGunActionInfo_Init = function (value)\n            value.projectiles = {}\n            original_ConfigGunActionInfo_Init( value )\n            value.extra_entities = new_cast_state_list()\n        end\n\n        ConfigGunActionInfo_Copy = function(source, dest)\n            dest.projectiles = copy_table(source.projectiles)\n            original_ConfigGunActionInfo_Copy(source, dest)\n            dest.extra_entities = copy_table(source.extra_entities)\n            setmetatable(dest.extra_entities, cast_state_list_metatable)\n        end\n\n        local original_GameGetFrameNum                          = GameGetFrameNum\n        local original_EntityGetWithTag                         = EntityGetWithTag\n        local original_EntityGetInRadiusWithTag                 = EntityGetInRadiusWithTag\n        local original_GetUpdatedEntityID                       = GetUpdatedEntityID\n        local original_EntityGetComponent                       = EntityGetComponent\n        local original_EntityGetFirstComponent                  = EntityGetFirstComponent\n        local original_EntityInflictDamage                      = EntityInflictDamage\n        local original_EntityGetTransform                       = EntityGetTransform\n        local original_EntityLoad                               = EntityLoad\n        local original_EntityGetAllChildren                     = EntityGetAllChildren\n        local original_EntityGetName                            = EntityGetName\n        local original_EntityHasTag                             = EntityHasTag\n        local original_EntityGetFirstComponentIncludingDisabled = EntityGetFirstComponentIncludingDisabled\n        local original_ComponentGetValue2                       = ComponentGetValue2\n        local original_ComponentSetValue2                       = ComponentSetValue2\n\n        local original_ComponentGetValue                        = ComponentGetValue\n        local original_ComponentSetValue                        = ComponentSetValue\n        local original_ComponentGetIsEnabled                    = ComponentGetIsEnabled\n        local original_EntityGetAllChildren                     = EntityGetAllChildren\n        local original_EntityAddChild                           = EntityAddChild\n        local original_EntitySetComponentsWithTagEnabled        = EntitySetComponentsWithTagEnabled\n        local original_GetGameEffectLoadTo                      = GetGameEffectLoadTo\n\n        local zeta_list = {}\n\n        for i, s in ipairs(wand_stats.zeta_options) do\n            table.insert(zeta_list, { name=\"\", tags=\"\",\n                                      components = {{type_name = \"ItemActionComponent\", tags=\"\", action_id=s}},\n                                      children = {}})\n        end\n\n        local player = {\n            name = \"player\", tags=\"player_unit\",\n            components = {\n                {\n                    type_name = \"DamageModelComponent\", tags=\"\",\n                    hp = wand_stats.hp, max_hp = wand_stats.max_hp,\n                    damage_multipliers = wand_stats.damage_multipliers,\n                    n_stainless = wand_stats.n_stainless,\n                    ambrosia = wand_stats.ambrosia,\n                },\n                {type_name = \"WalletComponent\", tags=\"\",\n                 mHasReachedInf = 0, mMoneyPrevFrame = wand_stats.money, money = wand_stats.money, money_spent = 0},\n                {type_name = \"Inventory2Component\", tags=\"\", mActiveItem = {}},\n            },\n            children = {\n                { -- inventory_quick\n                  name = \"inventory_quick\", tags=\"\",\n                  components = {},\n                  children = {\n                      { -- wand with all zeta options\n                        name=\"wand\", tags=\"wand,\",\n                        components = {},\n                        children = zeta_list\n                      }\n                  },\n                }\n            }\n        }\n\n        local entities = {player}\n\n        n_entities_with_tag = {\n            homing_target = wand_stats.n_enemies,\n            projectile = wand_stats.n_projectiles,\n            black_hole_giga = wand_stats.n_omega_black_holes,\n        }\n\n        if(wand_stats.frame_number) then\n            GameGetFrameNum                      = function()\n                return wand_stats.frame_number\n            end\n        end\n        EntityGetWithTag                         = function(tag)\n            local matches = {}\n            for i,e in ipairs(entities) do\n                if(string.find(\",\"..e.tags, \",\"..tag..\",\")) then\n                    table.insert(matches, e)\n                end\n            end\n\n            n_matches = n_entities_with_tag[tag] or 0\n            for i=#matches,n_matches do\n                matches[i] = 0\n            end\n            return matches\n        end\n        EntityGetInRadiusWithTag                 = function(x, y, r, tag)\n            return EntityGetWithTag(tag)\n        end\n        GetUpdatedEntityID                       = function() return player end\n        EntityGetComponent                       = function(entity_id, component_type_name, tag)\n            components = {}\n            for i, c in ipairs(player.components) do\n                if(c.type_name == component_type_name and (tag==nil or string.find(\",\"..c.tags, \",\"..tag..\",\"))) then\n                    table.insert(components, c)\n                end\n            end\n            return components\n        end\n        EntityGetFirstComponent                  = function(entity_id, component_type_name, tag)\n            if(entity_id and entity_id ~= 0) then\n                for i, c in ipairs(entity_id.components) do\n                    if(c.type_name == component_type_name and (tag==nil or string.find(\",\"..c.tags, \",\"..tag..\",\"))) then\n                        return c\n                    end\n                end\n            end\n            return nil\n        end\n        EntityGetFirstComponentIncludingDisabled = EntityGetFirstComponent\n        EntityInflictDamage = function(entity, amount, damage_type, description, ragdoll_fx, impulse_x, impulse_y, entity_who_is_responsible, world_pos_x, world_pos_y, knockback_force)\n            local comp = EntityGetFirstComponent(entity, \"DamageModelComponent\")\n            if(comp ~= nil and not comp.ambrosia) then\n                local type = string.lower(string.sub(damage_type, 8)) -- a bit hacky, but I think this works\n                comp.hp = comp.hp-amount*comp.damage_multipliers[type]*math.pow(0.5, comp.n_stainless)\n            end\n        end\n        EntityGetTransform                       = function(entity_id) return 0,0,0,1,1 end\n        EntityLoad                               = function(entity_id) end\n        EntityGetAllChildren                     = function(entity_id) if(entity_id) then return entity_id.children end end\n        EntityGetName                            = function(entity_id) if(entity_id) then return entity_id.name end end\n        EntityHasTag                             = function(entity_id, tag) if(entity_id) then return string.find(\",\"..(entity_id.tags or \"\"), \",\"..tag..\",\") end end\n        ComponentGetValue2                       = function(component_id, variable_name) if(component_id) then return component_id[variable_name] end end\n        ComponentSetValue2                       = function(component_id, variable_name, value) if(component_id) then component_id[variable_name] = value end end\n\n        ComponentGetValue                        = function(component_id, variable_name) end\n        ComponentSetValue                        = function(component_id, variable_name, value) end\n        ComponentGetIsEnabled                    = function(component_id) end\n        EntityAddChild                           = function(entity_id, child_id) end\n        EntitySetComponentsWithTagEnabled        = function(entity_id, tag, enabled) end\n        GetGameEffectLoadTo                      = function(entity_id, game_effect_name, always_load_new) end\n\n        local every_other_state = tonumber(GlobalsGetValue( \"GUN_ACTION_IF_HALF_STATUS\", \"0\"))\n        if(wand_stats.every_other_state~=nil) then\n            GlobalsSetValue( \"GUN_ACTION_IF_HALF_STATUS\", wand_stats.every_other_state and \"1\" or \"0\")\n        end\n\n        gun = wand_stats.gun_config\n        state_from_game = {}\n        ConfigGunActionInfo_Init(state_from_game)\n        for m, v in pairs(wand_stats.gunaction_config) do\n            if(m == \"extra_entities\") then\n                if(v ~= nil and v ~= \"\") then\n                    state_from_game.extra_entities = state_from_game.extra_entities..v\n                end\n            else\n                state_from_game[m] = v\n            end\n        end\n        -- if gun.shuffle_deck_when_empty then\n        --     GamePrint(\"Shuffle Deck When Empty: yes\")\n        -- else\n        --     GamePrint(\"Shuffle Deck When Empty: no\")\n        -- end\n\n        -- GuiText(gui, dbglog_x, dbglog_y,'starting shot')\n        -- dbglog_y = dbglog_y+10\n\n        --GamePrint(\"cards in deck: \" .. #deck)\n        first_shot   = true\n        reloading    = false\n        start_reload = false\n        got_projectiles = false\n\n        local cast_limit = 26\n\n        reloaded = false\n\n        local cast_number = 1\n        while(not reloaded or #deck > #start_deck) do\n            _start_shot(wand_stats.mana)\n\n            current_node = {parent = nil, children = {}, cast_number = cast_number, c = c}\n            table.insert(action_trees, current_node)\n            cast_number = cast_number+1\n\n            local old_table_insert = table.insert --TODO: check if this does anything?\n            playing_permanent_card = true\n            current_explanation = \"always_cast\"\n            for ac, action in ipairs(always_casts) do\n                action_clone = {}\n                clone_action(action, action_clone)\n                action_clone.original_action = action.original_action\n                action_clone.permanently_attached = true\n                action_clone.uses_remaining   = -1\n                action_clone.sprite = action.sprite\n\n                modify_action(action_clone, true)\n\n                handle_mana_addition(action_clone)\n                ac_play_actions(action_clone)\n            end\n            playing_permanent_card = false\n            table.insert = old_table_insert\n\n            shot_type = \"root\"\n            _draw_actions_for_shot(false)\n            _handle_reload()\n            -- draw_shot(root_shot, false)\n            -- move_hand_to_discarded()\n            make_snapshot(\"cast_done\", {}, true)\n            cast_limit = cast_limit - 1\n            if(cast_limit == 0) then\n                break\n            end\n        end\n\n        table.insert = table_insert\n        table.remove = table_remove\n\n        ConfigGunActionInfo_Init = original_ConfigGunActionInfo_Init\n        ConfigGunActionInfo_Copy = original_ConfigGunActionInfo_Copy\n\n        GameGetFrameNum                          = original_GameGetFrameNum\n        EntityGetWithTag                         = original_EntityGetWithTag\n        EntityGetInRadiusWithTag                 = original_EntityGetInRadiusWithTag\n        GetUpdatedEntityID                       = original_GetUpdatedEntityID\n        EntityGetComponent                       = original_EntityGetComponent\n        EntityGetFirstComponent                  = original_EntityGetFirstComponent\n        EntityInflictDamage                      = original_EntityInflictDamage\n        EntityGetTransform                       = original_EntityGetTransform\n        EntityLoad                               = original_EntityLoad\n        EntityGetAllChildren                     = original_EntityGetAllChildren\n        EntityGetName                            = original_EntityGetName\n        EntityHasTag                             = original_EntityHasTag\n        EntityGetFirstComponentIncludingDisabled = original_EntityGetFirstComponentIncludingDisabled\n        ComponentGetValue2                       = original_ComponentGetValue2\n        ComponentSetValue2                       = original_ComponentSetValue2\n\n        ComponentGetValue                        = original_ComponentGetValue\n        ComponentSetValue                        = original_ComponentSetValue\n        ComponentGetIsEnabled                    = original_ComponentGetIsEnabled\n        EntityGetAllChildren                     = original_EntityGetAllChildren\n        EntityAddChild                           = original_EntityAddChild\n        EntitySetComponentsWithTagEnabled        = original_EntitySetComponentsWithTagEnabled\n        GetGameEffectLoadTo                      = original_GetGameEffectLoadTo\n\n        -- GuiText(gui, dbglog_x, dbglog_y,'ending shot')\n        -- dbglog_y = dbglog_y+10\n\n        GlobalsSetValue(\"GUN_ACTION_IF_HALF_STATUS\", tostring(every_other_state))\n\n        return cast_history, action_trees, start_deck, always_casts\n    end\n\n    return debug_wand\nend\n"
_TWWE_VFS["mods/wand_dbg/files/move_card.lua"] = "dofile_once(\"data/scripts/lib/utilities.lua\")\n\nlocal entity_id = GetUpdatedEntityID()\nlocal x, y, theta = EntityGetTransform( entity_id )\n\nlocal x_targe, y_target, omega\n\nlocal variable_comps = EntityGetComponent(player, \"VariableStorageComponent\")\nif(comps ~= nil) then\n    for i, v in ipairs(variable_comps) do\n        local n = ComponentGetValue2(v, name)\n        if(n == \"x_target\") then\n            x_target = ComponentGetValue2( v, \"value_float\" )\n        end\n        if(n == \"y_target\") then\n            y_target = ComponentGetValue2( v, \"value_float\" )\n        end\n        if(n == \"angular_vel\") then\n            omega = ComponentGetValue2( v, \"value_float\" )\n        end\n    end\nend\n\nedit_component(entity_id, \"VelocityComponent\", function(comp,vars)\n    vel_x, vel_y = ComponentGetValueVector2( comp, \"mVelocity\")\n\n    local rx = x_target-x\n    local ry = y_target-y\n\n    local k = 1\n    local c = 0.1\n\n    vel_x = (1-c)*vel_x + k*rx\n    vel_y = (1-c)*vel_y + k*ry\n    omega = omega + vel_x\n    ComponentSetValueVector2( comp, \"mVelocity\", vel_x, vel_y)\nend)\n\n\nlocal k = 1\nlocal c = 0.1\n\nomega = (1-c)*omega-k*theta\ntheta = theta + omega\n\nEntitySetTransform(entity_id, x, y, theta)\n"
_TWWE_VFS["mods/wand_dbg/files/spell_info.lua"] = "SPELL_INFO = {}\nfunction SPELL_INFO.get_spell_info()\n    --we don't personally need these, but Goki's things does some jank\n    local original_BeginProjectile               = BeginProjectile\n    local original_OnActionPlayed                = OnActionPlayed\n    local original_Reflection_RegisterProjectile = Reflection_RegisterProjectile\n\n    BeginProjectile               = BeginProjectile               or (function() end)\n    OnActionPlayed                = OnActionPlayed                or (function() end)\n    Reflection_RegisterProjectile = Reflection_RegisterProjectile or (function() end)\n\n    dofile( \"data/scripts/gun/gun.lua\" );\n    reflecting = true\n\n    local action_table = {}\n    local projectile_table = {}\n    local projectile_list = {\"ERROR\"}\n    local extra_entity_table = {}\n\n    local original_GlobalsGetValue = GlobalsGetValue\n    local original_GlobalsSetValue = GlobalsSetValue\n\n    GlobalsGetValue = function() return nil end\n    GlobalsSetValue = function() end\n\n    EntityLoad = function() end\n\n    local original_add_projectile                   = add_projectile\n    local original_add_projectile_trigger_timer     = add_projectile_trigger_timer\n    local original_add_projectile_trigger_hit_world = add_projectile_trigger_hit_world\n    local original_add_projectile_trigger_death     = add_projectile_trigger_death\n    local original_draw_actions                     = draw_actions\n    local original_check_recursion                  = check_recursion\n\n    function is_related(action, entity_filename)\n        if(not action.related_projectiles) then return false end\n        for j,e in ipairs(action.related_projectiles) do\n            if(j%2 == 1) then\n                if(entity_filename == e) then\n                    return true\n                end\n            end\n        end\n        return false\n    end\n\n    add_projectile = function(entity_filename)\n        if(current_action ~= nil) then\n            if(projectile_table[entity_filename] == nil) then\n                table.insert(projectile_list, entity_filename)\n                projectile_table[entity_filename] = {i = #projectile_list}\n            end\n            if(projectile_table[entity_filename].normal == nil or is_related(current_action, entity_filename)) then\n                projectile_table[entity_filename].normal = current_action\n            end\n        end\n    end\n\n    add_projectile_trigger_timer = function(entity_filename)\n        if(current_action ~= nil) then\n            if(projectile_table[entity_filename] == nil) then\n                table.insert(projectile_list, entity_filename)\n                projectile_table[entity_filename] = {i = #projectile_list}\n            end\n            if(projectile_table[entity_filename].timer == nil or is_related(current_action, entity_filename)) then\n                projectile_table[entity_filename].timer = current_action\n            end\n        end\n    end\n\n    add_projectile_trigger_hit_world = function(entity_filename)\n        if(current_action ~= nil) then\n            if(projectile_table[entity_filename] == nil) then\n                table.insert(projectile_list, entity_filename)\n                projectile_table[entity_filename] = {i = #projectile_list}\n            end\n            if(projectile_table[entity_filename].trigger == nil or is_related(current_action, entity_filename)) then\n                projectile_table[entity_filename].trigger = current_action\n            end\n        end\n    end\n\n    add_projectile_trigger_death = function(entity_filename)\n        if(current_action ~= nil) then\n            if(projectile_table[entity_filename] == nil) then\n                table.insert(projectile_list, entity_filename)\n                projectile_table[entity_filename] = {i = #projectile_list}\n            end\n            if(projectile_table[entity_filename].death_trigger == nil) then\n                projectile_table[entity_filename].death_trigger = current_action\n            end\n        end\n    end\n\n    check_recursion = function(data, recursion_level) return -1 end\n\n    draw_actions = function( how_many, instant_reload_if_empty )\n        c.draw_many_count = how_many\n    end\n\n\n    for i, action in ipairs(actions) do\n        if(action.related_projectiles) then\n            for j,entity_filename in ipairs(action.related_projectiles) do\n                if(j%2 == 1) then\n                    if(projectile_table[entity_filename] == nil) then\n                        table.insert(projectile_list, entity_filename)\n                        projectile_table[entity_filename] = {i = #projectile_list}\n                    end\n                    if(projectile_table[entity_filename].normal == nil) then\n                        projectile_table[entity_filename].normal = action\n                    end\n                end\n            end\n        end\n    end\n\n    for i, action in ipairs(actions) do\n        ConfigGunActionInfo_Init(c)\n        ConfigGunShotEffects_Init(shot_effects)\n        current_action = action\n        action.action()\n\n        action.c = {}\n        ConfigGunActionInfo_Copy(c, action.c)\n\n        for entity_filename in string.gmatch(c.extra_entities, \"[^ ,]+\") do\n            extra_entity_table[entity_filename] = action\n        end\n\n        action_table[action.id] = action\n    end\n\n    add_projectile                   = original_add_projectile\n    add_projectile_trigger_timer     = original_add_projectile_trigger_timer\n    add_projectile_trigger_hit_world = original_add_projectile_trigger_hit_world\n    add_projectile_trigger_death     = original_add_projectile_trigger_death\n    draw_actions                     = original_draw_actions\n    check_recursion                  = original_check_recursion\n\n    GlobalsGetValue = original_GlobalsGetValue\n    GlobalsSetValue = original_GlobalsSetValue\n\n    BeginProjectile               = original_BeginProjectile\n    -- OnActionPlayed                = original_OnActionPlayed\n    Reflection_RegisterProjectile = original_Reflection_RegisterProjectile\n\n    return action_table, projectile_table, projectile_list, extra_entity_table\nend\n"
_TWWE_VFS["mods/wand_dbg/files/ui.lua"] = "mx = 0\nmy = 0\ngx = 0\ngy = 0\n\nbound_x_min = 0\nbound_y_min = 0\nbound_x_max = 0\nbound_y_max = 0\n\nlocal drag_mx = 0\nlocal drag_my = 0\n\nlocal max_x\nlocal max_y\nwindow_active = false\nother_window_blocking = false\ninner_window_hovered = false\n\n--Constant settings windows\nlocal drag_bar_height = 9\nlocal window_min_width = 10\nlocal window_min_height = 10\n\ngui_selected = nil\nnew_gui_selected = nil\n\nlocal named_gui_id = 100000\ngui_id = 0\nlocal gui_ids = {}\nfunction get_id(name, n_ids)\n    n_ids = n_ids or 1\n    if(name ~= nil) then\n        if(gui_ids[name] ~= nil) then\n            prev_gui_id = gui_ids[name]\n            return gui_ids[name]\n        end\n        named_gui_id = named_gui_id+n_ids\n        gui_ids[name] = named_gui_id\n        prev_gui_id = named_gui_id\n        return named_gui_id\n    end\n    gui_id = gui_id+1\n    prev_gui_id = gui_id\n    return gui_id\nend\n\nfunction start_gui(gui)\n    -- GuiStartFrame(gui)\n    -- GuiOptionsAdd(gui, GUI_OPTION.NoPositionTween);\n    gui_id = 0\nend\n\nz_global = 0\nfunction z_set_global(gui, z)\n    z_global = z\n    GuiZSet(gui, z)\nend\n\nfunction z_set_next_relative(gui, z)\n    GuiZSetForNextWidget(gui, z_global+z)\nend\n\nfunction z_set_relative(gui, z)\n    GuiZSetForNextWidget(gui, z_global+z)\nend\n\ninteractive = true\nglobal_interactive = true\nfunction set_interactive(gui, new_interactive)\n    interactive = new_interactive\n    if(interactive and global_interactive) then\n        GuiOptionsRemove(gui, GUI_OPTION.NonInteractive)\n    else\n        GuiOptionsAdd(gui, GUI_OPTION.NonInteractive)\n    end\nend\n\nlocal last_widget_hidden = false\nlocal last_widget_x = 0\nlocal last_widget_y = 0\nlocal last_widget_width = 0\nlocal last_widget_height = 0\n\nfunction get_previous_widget_info_bounded(gui)\n    if(last_widget_hidden) then\n        return false, false, false, last_widget_x, last_widget_y, last_widget_width, last_widget_height\n    end\n    local clicked, right_clicked, hovered, x, y, width, height = GuiGetPreviousWidgetInfo(gui)\n    if(inner_window_hovered and not other_window_blocking and (clicked or right_clicked)) then\n        window_active = true\n    elseif(not inner_window_hovered or not interactive or other_window_blocking) then\n        clicked = false\n        right_clicked = false\n        hovered = false\n    end\n    return clicked, right_clicked, hovered, x, y, width, height\nend\n\nfunction get_previous_widget_info(gui)\n    local clicked, right_clicked, hovered, x, y, width, height = GuiGetPreviousWidgetInfo(gui)\n    if(inner_window_hovered and not other_window_blocking and (clicked or right_clicked)) then\n        window_active = true\n    elseif(not inner_window_hovered or not interactive or other_window_blocking) then\n        clicked = false\n        right_clicked = false\n        hovered = false\n    end\n    return clicked, right_clicked, hovered, x, y, width, height\nend\n\nfunction gui_image_bounded(gui, id, x, y, sprite_filename, alpha, scale, scale_y, rotation, rect_animation_playback_type, rect_animation_name)\n    -- default values\n    alpha = alpha or 1\n    scale = scale or 1\n    scale_y = scale_y or 0\n    rotation = rotation or 0\n    rect_animation_playback_type = rect_animation_playback_type or GUI_RECT_ANIMATION_PLAYBACK.PlayToEndAndHide\n    rect_animation_name = rect_animation_name or \"\"\n\n    local y_scale = scale_y == 0 and scale or scale_y\n\n    bound_x_min = bound_x_min or 0\n    bound_y_min = bound_y_min or 0\n    bound_x_max = bound_x_max or gw\n    bound_y_max = bound_y_max or gh\n\n    local c = math.cos(rotation)\n    local s = math.sin(rotation)\n    local w, h = GuiGetImageDimensions(gui, sprite_filename)\n    w = w*scale\n    h = h*y_scale\n    local x_min = x + math.min(w*c, 0) + math.min(-h*s, 0)\n    local y_min = y + math.min(h*c, 0) + math.min(w*s, 0)\n    local x_max = x + math.max(w*c, 0) + math.max(-h*s, 0)\n    local y_max = y + math.max(h*c, 0) + math.max(w*s, 0)\n\n    if(bound_x_min <= x_max and x_min <= bound_x_max\n       and bound_y_min <= y_max and y_min <= bound_y_max) then\n        GuiImage(gui, id, x, y, sprite_filename, alpha, scale, scale_y, rotation, rect_animation_playback_type, rect_animation_name)\n        last_widget_hidden = false\n    else\n        last_widget_hidden = true\n        last_widget_x = x\n        last_widget_y = y\n        last_widget_width = w\n        last_widget_height = h\n    end\nend\n\nfunction draw_line(gui, x1, y1, x2, y2, thickness, color, alpha, end_spacing, arrow_size, arrow_pos)\n    thickness = thickness or 1\n    end_spacing = end_spacing or 0\n    arrow_pos = arrow_pos or 0.5\n    color = color or \"white\"\n    alpha = alpha or 1\n    local sprite = base_dir .. \"files/ui_gfx/line_dot_\"..color..\".png\"\n    local dx = (x2-x1)\n    local dy = (y2-y1)\n    local length = math.sqrt(dx*dx+dy*dy)\n    dx = dx/length\n    dy = dy/length\n    local rotation = math.atan2(-dx, dy)\n    local x_off, y_off = complexx(-0.5*thickness, 0.5*thickness, dx, dy)\n    gui_image_bounded(gui, get_id(), x1+dx*end_spacing+x_off, y1+dy*end_spacing+y_off, sprite,\n                      alpha, thickness, length+0.5*thickness-2*end_spacing, rotation)\n\n    if(arrow_size) then\n        local x0 = lerp(x1, x2, arrow_pos)+dx*arrow_size/2\n        local y0 = lerp(y1, y2, arrow_pos)+dy*arrow_size/2\n        local xt, yt = complexx(-arrow_size, arrow_size/2, dx,dy)\n        draw_line(gui, x0, y0, x0+xt, y0+yt, thickness, color, alpha)\n        xt, yt = complexx(-arrow_size, -arrow_size/2, dx,dy)\n        draw_line(gui, x0, y0, x0+xt, y0+yt, thickness, color, alpha)\n    end\nend\n\nfunction draw_box(gui, x, y, width, height, thickness, color, alpha)\n    draw_line(gui, x, y, x+width, y, thickness, color, alpha)\n    draw_line(gui, x+width, y, x+width, y+height, thickness, color, alpha)\n    draw_line(gui, x+width, y+height, x, y+height, thickness, color, alpha)\n    draw_line(gui, x, y+height, x, y, thickness, color, alpha)\nend\n\nfunction draw_spline(gui, x0, y0, x1, y1, x2, y2, x3, y3, thickness, color, alpha, end_spacing, arrow_size, arrow_pos, segment_spacing)\n    segment_spacing = segment_spacing or 0.05\n    arrow_pos = arrow_pos or 0.5\n    local x = x0\n    local y = y0\n    local drew_arrow = false\n    for t = segment_spacing,1+0.5*segment_spacing,segment_spacing do\n        local new_x = bezier(x0, x1, x2, x3, t)\n        local new_y = bezier(y0, y1, y2, y3, t)\n\n        if(not drew_arrow and t >= 1-1.5*segment_spacing) then\n            draw_line(gui, x, y, new_x, new_y, thickness, color, alpha, end_spacing, arrow_size, arrow_pos)\n            drew_arrow = true\n        else\n            draw_line(gui, x, y, new_x, new_y, thickness, color, alpha, end_spacing)\n        end\n        x = new_x\n        y = new_y\n    end\nend\n\nfunction test_drag(gui, id)\n    if(other_window_blocking) then return false end\n    GuiOptionsAddForNextWidget(gui, GUI_OPTION.IsDraggable)\n    GuiOptionsAddForNextWidget(gui, GUI_OPTION.NoPositionTween)\n    local test_x = mx-8\n    local test_y = my-8\n\n    local old_interactive = interactive\n    set_interactive(gui, true)\n    GuiButton(gui, get_id(\"drag_test\"), test_x, test_y, \"     \")\n    set_interactive(gui, old_interactive)\n    local clicked, right_clicked, hovered, text_x, text_y, width, height = GuiGetPreviousWidgetInfo(gui)\n    window_active = window_active or clicked\n    if(math.abs(text_x-test_x) > 4 or math.abs(text_y-test_y) > 4) then\n        -- window.x = window.x+text_x-test_x-11\n        -- window.y = window.y+text_y-test_y-9\n        return true\n    else\n        return false\n    end\nend\n\nlocal windows = {}\nlocal grabbed = nil\n\nfunction make_window(base_id, base_x, base_y, width, height, show, title)\n    show = show or true\n    local window = {id = base_id,\n                    title = title,\n                    default_x = base_x,\n                    default_y = base_y,\n                    default_width = width,\n                    default_height = height,\n                    x = ModSettingGet(mod_name..\".\"..base_id..\"_x\") or base_x,\n                    y = ModSettingGet(mod_name..\".\"..base_id..\"_y\") or base_y,\n                    width = ModSettingGet(mod_name..\".\"..base_id..\"_width\") or width,\n                    height = ModSettingGet(mod_name..\".\"..base_id..\"_height\") or height,\n                    -- x = base_x,\n                    -- y = base_y,\n                    -- width = width,\n                    -- height = height,\n                    show = ModSettingGet(mod_name..\".\"..base_id..\"_show\"),\n                    hovered_frames=0,\n                    x_scroll = 0,\n                    x_scroll_target = 0,\n                    y_scroll = 0}\n    if(window.show == nil) then\n        window.show = show\n    end\n    table.insert(windows, window)\n    return window\nend\n\nfunction start_window(gui, window, order)\n    if(not window.show) then\n        ModSettingSet(mod_name..\".\"..window.id..\"_show\", window.show)\n        return false\n    end\n\n    z_set_global(gui, -100*(#windows-order))\n\n    if(grabbed == window.id..-1) then\n        if(not window.dragging) then\n            drag_mx = mx-window.x\n            drag_my = my-window.y\n        end\n        window.x = mx-drag_mx\n        window.y = my-drag_my\n        window.dragging = true\n    end\n\n    local sx = 0\n    local sy = 0\n    for i=0,3 do\n        if(grabbed == window.id..i) then\n            sx = (i+1)%4>=2 and 1 or -1\n            sy =       i>=2 and 1 or -1\n        end\n    end\n    for i=0,3 do\n        if(grabbed == window.id..i+4) then\n            if(i%2 == 0) then\n                sx = (i+1)%4>=2 and 1 or -1\n            else\n                sy =       i>=2 and 1 or -1\n            end\n        end\n    end\n\n    if(grabbed ~= nil) then\n        local grabbed_number = tonumber(string.match(grabbed, \"[-0-9]+$\"))\n        if(grabbed_number ~= nil and grabbed == window.id..grabbed_number and 0 <= grabbed_number and grabbed_number < 8) then\n            if(not window.dragging) then\n                drag_mx = mx-sx*window.width\n                drag_my = my-sy*window.height\n                window.scale_mx = mx-window.x\n                window.scale_my = my-window.y\n            end\n\n            if(sx ~= 0) then\n                window.width = math.max(sx*(mx-drag_mx), window_min_width)\n                if(sx == -1) then\n                    window.x = math.min(mx-window.scale_mx, drag_mx-window.scale_mx-window_min_width)\n                end\n            end\n\n            if(sy ~= 0) then\n                window.height = math.max(sy*(my-drag_my), window_min_height)\n                if(sy == -1) then\n                    window.y = math.min(my-window.scale_my, drag_my-window.scale_my-window_min_height)\n                end\n            end\n            window.dragging = true\n        end\n    end\n\n    if(grabbed==nil) then\n        window.dragging = false\n    -- else\n        window.x = clamp(window.x, 0, gw)\n        window.y = clamp(window.y, 0, gh)\n        ModSettingSet(mod_name..\".\"..window.id..\"_x\", window.x)\n        ModSettingSet(mod_name..\".\"..window.id..\"_y\", window.y)\n        ModSettingSet(mod_name..\".\"..window.id..\"_width\", window.width)\n        ModSettingSet(mod_name..\".\"..window.id..\"_height\", window.height)\n        ModSettingSet(mod_name..\".\"..window.id..\"_show\", window.show)\n    end\n\n    local width = window.width\n    local height = window.height-drag_bar_height\n    if(window.x_scroll_active) then\n        height = height-8\n    end\n\n    -- local box_x0 = window.x+4 +20-2\n    -- local box_y0 = window.y+20+drag_bar_height-2+4\n    -- local box_x1 = window.x+4 +width-8-2 - 20\n    -- local box_y1 = box_y0+height-40\n    -- draw_line(gui, box_x0, box_y0, box_x1, box_y0, 0.5)\n    -- draw_line(gui, box_x1, box_y1, box_x1, box_y0, 0.5)\n    -- draw_line(gui, box_x1, box_y1, box_x0, box_y1, 0.5)\n    -- draw_line(gui, box_x0, box_y0, box_x0, box_y1, 0.5)\n\n    GuiOptionsAdd(gui, GUI_OPTION.Layout_NoLayouting)\n    GuiBeginScrollContainer(gui, get_id(window.id), window.x, window.y, width, window.height, false)\n    z_set_next_relative(gui, -1.0)\n    GuiText(gui, window.x, window.y-2, window.title)\n    GuiOptionsRemove(gui, GUI_OPTION.Layout_NoLayouting)\n    z_set_next_relative(gui, 0.5)\n    set_interactive(gui, grabbed == nil)\n    GuiBeginScrollContainer(gui, get_id(window.id..\"inner\"), 0, drag_bar_height-2, width-8-2, height, true)\n    max_x = 0\n    max_y = 0\n\n    local lx = window.x-1\n    local ly = window.y+drag_bar_height-2-1\n    local ux = window.x+window.width+6\n    local uy = window.y+drag_bar_height+height+6\n    inner_window_hovered = (lx <= mx and mx < ux and ly <= my and my < uy)\n\n    set_interactive(gui, not other_window_blocking)\n\n    local clicked, right_clicked, hovered, sx, sy, swidth, sheight = GuiGetPreviousWidgetInfo(gui)\n    if(not other_window_blocking and (clicked or right_clicked)) then\n        window_active = true\n    end\n\n    local dot_sprite = base_dir .. \"files/ui_gfx/line_dot_white.png\"\n    GuiImage(gui, get_id(), 0, 0, dot_sprite, 0, 1, 0, 0)\n    local _, __, ___, x0, y0, w0, h0 = GuiGetPreviousWidgetInfo(gui)\n    scroll_y = (window.y+drag_bar_height-2)-y0+4\n\n    local margin_x = 3\n    local margin_y = 3\n    -- local margin_x = -20\n    -- local margin_y = -20\n    bound_x_min = -margin_x-2\n    bound_y_min = scroll_y - margin_y\n    bound_x_max = width-8-2 + margin_x\n    bound_y_max = scroll_y + height + margin_y\n\n    window.y_scroll = scroll_y\n\n    return true\nend\n\nfunction extend_max_bound(x, y)\n    max_x = math.max(x, max_x)\n    max_y = math.max(y, max_y)\nend\n\nfunction end_window(gui, window, order)\n    bound_x_min = 0\n    bound_y_min = 0\n    bound_x_max = gw\n    bound_y_max = gh\n    set_interactive(gui, true)\n\n    if(not window.show) then return end\n    GuiLayoutEnd(gui, 0, 0, true, 0, 0)\n    GuiEndScrollContainer(gui)\n    GuiEndScrollContainer(gui)\n\n    if(max_x > window.width) then\n        local x_scroll_max = max_x-window.width\n        window.x_scroll = math.min(window.x_scroll, x_scroll_max)\n        window.x_scroll_target = math.min(window.x_scroll_target, x_scroll_max)\n        GuiColorSetForNextWidget(gui,1,1,1,0)\n        local new_x_scroll = GuiSlider(gui, get_id(window.id..\"_horizontal_scrollbar\"), window.x-2.25, window.y+window.height-4, \"\",\n                                              window.x_scroll, 0, x_scroll_max, 0, 0, \" \", window.width-4)\n        if(math.abs(new_x_scroll-window.x_scroll) > 1) then\n            window.x_scroll_target = new_x_scroll\n        end\n        window.x_scroll = lerp(window.x_scroll, window.x_scroll_target, 0.3)\n        local clicked, right_clicked, hovered, x, y, width, height = GuiGetPreviousWidgetInfo(gui)\n        if(not other_window_blocking and (clicked or right_clicked)) then\n            window_active = true\n        end\n        window.x_scroll_active = true\n    else\n        window.x_scroll = 0\n        window.x_scroll_active = false\n    end\n\n    GuiImageNinePiece(gui, get_id(window.id..\"_move_bar\"),\n                      window.x, window.y, window.width+4, drag_bar_height-2)\n\n    if(window.hovered_frames <= 0) then\n        window.hovered = nil\n    end\n    window.hovered_frames = window.hovered_frames-1\n\n    local lx = window.x-1\n    local ly = window.y-1\n    local cy = window.y+drag_bar_height\n    local ux = window.x+window.width+6\n    local uy = window.y+window.height+6\n    local resize_tolerance = 2\n    local edge_hovered = {}\n    edge_hovered[0] = (math.abs(mx-lx) < resize_tolerance\n                           and ly-resize_tolerance < my and my < uy+resize_tolerance)\n    edge_hovered[1] = (math.abs(my-ly) < resize_tolerance\n                           and lx-resize_tolerance < mx and mx < ux+resize_tolerance)\n    edge_hovered[2] = (math.abs(mx-ux) < resize_tolerance\n                           and ly-resize_tolerance < my and my < uy+resize_tolerance)\n    edge_hovered[3] = (math.abs(my-uy) < resize_tolerance\n                           and lx-resize_tolerance < mx and mx < ux+resize_tolerance)\n\n    local window_hovered = (lx <= mx and mx < ux and ly <= my and my < uy)\n\n    -- Debug lines for checking alignment\n    -- GuiZSet(gui, -1.0)\n    -- draw_line(gui, lx,ly,ux,ly, 1.0, \"white\", 1.0, 0)\n    -- draw_line(gui, ux,ly,ux,uy, 1.0, \"white\", 1.0, 0)\n    -- draw_line(gui, ux,uy,lx,uy, 1.0, \"white\", 1.0, 0)\n    -- draw_line(gui, lx,uy,lx,ly, 1.0, \"white\", 1.0, 0)\n\n    -- draw_line(gui, lx,cy,ux,cy, 1.0, \"white\", 1.0, 0)\n\n    -- draw_line(gui, ux-9,ly,ux-9,cy, 1.0, \"white\", 1.0, 0)\n\n    -- draw_line(gui, lx,my,ux,my, 1.0, \"white\", 1.0, 0)\n    -- draw_line(gui, mx,ly,mx,uy, 1.0, \"white\", 1.0, 0)\n    -- GuiZSet(gui, 0.0)\n\n    local corner_hovered = false\n    for i=0,3 do\n        if(edge_hovered[i] and edge_hovered[(i+1)%4]) then\n            if(window.hovered==nil or window.hovered==i) then\n                window.hovered = i\n                window.hovered_frames = 2\n            end\n            corner_hovered = true\n        end\n    end\n    if(not corner_hovered) then\n        for i=0,3 do\n            if(edge_hovered[i]) then\n                if(window.hovered==nil or window.hovered==i+4) then\n                    window.hovered = i+4\n                    window.hovered_frames = 2\n                end\n                corner_hovered = true\n            end\n        end\n    end\n\n    for i=0,3 do\n        if(grabbed == window.id..i or (window.hovered==i and grabbed==nil)) then\n            -- draw_line(gui, mx, my, mx+4, my+4,1,\"white\",1,0,5,1)\n            -- draw_line(gui, mx, my, mx-4, my-4,1,\"white\",1,0,5,1)\n\n            z_set_next_relative(gui, -1.0)\n            local resize_sprite = base_dir..\"files/ui_gfx/resize.png\"\n            local im_w, im_h = GuiGetImageDimensions(gui, resize_sprite)\n            local ix = mx+(i%2==1 and 2.5 or -5.5)-0.25\n            local iy = my+(i%2==1 and -5.5 or -2.5)-0.25\n            local angle = i%2==1 and math.pi/4 or -math.pi/4\n            GuiImage(gui, get_id(window.id..\"_resize_icon\"), ix, iy, resize_sprite, 1, 1, 0, angle)\n\n            if(test_drag(gui, window.id..\"_corner_\"..i)) then\n                grabbed = window.id..i\n            else\n                grabbed = nil\n            end\n        end\n    end\n    for i=0,3 do\n        if(grabbed == window.id..i+4 or (window.hovered==i+4 and grabbed==nil)) then\n            z_set_next_relative(gui, -1.0)\n            local resize_sprite = base_dir..\"files/ui_gfx/resize.png\"\n            local ix = mx+(i%2==1 and -2.25 or 5.5)\n            local iy = my+(i%2==1 and -6 or -2.5)\n            local angle = i%2==1 and 0 or math.pi/2\n            GuiImage(gui, get_id(window.id..\"_resize_icon\"), ix, iy, resize_sprite, 1, 1, 0, angle)\n\n            if(test_drag(gui, window.id..\"_edge_\"..i)) then\n                grabbed = window.id..i+4\n            else\n                grabbed = nil\n            end\n        end\n    end\n\n    if(not corner_hovered\n           and (window.hovered == nil or window.hovered == -1)\n           and (lx <= mx and mx < ux-9 and ly <= my and my < cy))\n    then\n        window.hovered = -1\n        window.hovered_frames = 2\n    end\n\n    if(grabbed == window.id..-1 or (window.hovered==-1 and grabbed==nil)) then\n        if(test_drag(gui, window.id..\"_drag\")) then\n            grabbed = window.id..-1\n        else\n            grabbed = nil\n        end\n    end\n\n    z_set_next_relative(gui, -1.0)\n    local close_window_sprite = base_dir..\"files/ui_gfx/close.png\"\n    local im_w, im_h = GuiGetImageDimensions(gui, close_window_sprite)\n    local close_pressed = GuiImageButton(gui, get_id(window.id..\"_close_button\"),\n                                         window.x+window.width-math.floor(im_w/2), window.y, \"\", close_window_sprite)\n    GuiTooltip(gui, \"close\", \"\")\n    if(close_pressed) then\n        window.show = false\n    end\n\n    if(not other_window_blocking and window_hovered) then\n        other_window_blocking = true\n    end\nend\n\ntop_window = -1\n\nfunction draw_windows(gui)\n    other_window_blocking = false\n    for i,window in ipairs(windows) do\n        window_active = false\n        if(start_window(gui, window, i) and window.func ~= nil) then\n            window.func(window)\n        end\n        end_window(gui, window)\n        window.index = i\n        --technically not right, since one window's id can be a substring of another's but good enough\n        if(window_active or grabbed ~= nil and string.sub(grabbed,1,#window.id) == window.id) then\n            gui_selected = new_gui_selected\n            new_gui_selected = nil\n            top_window = i\n            other_window_blocking = true\n        end\n    end\n\n    if(top_window ~= -1 and top_window ~= 1) then\n        table.insert(windows, 1, table.remove(windows, top_window))\n        top_window = -1\n    end\n    set_interactive(gui, true)\nend\n\nfunction reset_windows()\n    for i,window in ipairs(windows) do\n        window.x = window.default_x\n        window.y = window.default_y\n        window.width = window.default_width\n        window.height = window.default_height\n    end\nend\n\n\nfunction do_window_show_hide_button(gui, window, x, y, icon)\n    local pressed = GuiImageButton(gui, get_id((window.id)..\"show_hide_button\"), x, y, \"\", icon)\n    local tooltip = \"Show \"..window.title\n    if(window.show) then\n        tooltip = \"Hide \"..window.title\n    end\n    GuiTooltip(gui, tooltip, \"\")\n    if(pressed) then\n        window.show = not window.show\n        top_window = window.index\n    end\nend\n"
_TWWE_VFS["mods/wand_dbg/files/utils.lua"] = "function clamp(x, a, b)\n    return math.max(a, math.min(b, x))\nend\n\nfunction soft_clamp(x, a, b)\n    return math.tanh((x-0.5*(a+b))/(b-a))*(b-a)+0.5*(a+b)\nend\n\nfunction sign(x)\n    if(x >= 0) then\n        return 1\n    end\n    return -1\nend\n\nfunction lerp(a, b, t)\n    return a*(1-t)+b*t\nend\n\nfunction cubic_bezier(a,b,c,t)\n    return lerp(lerp(a,b,t), lerp(b,c,t), t)\nend\n\nfunction bezier(a,b,c,d,t)\n    return lerp(cubic_bezier(a,b,c,t), cubic_bezier(b,c,d,t), t)\nend\n\nfunction complexx(ar, ai, br, bi)\n    return ar*br-ai*bi, ar*bi+ai*br\nend\n\nfunction copy_table(t)\n    local out = {}\n    for i, a in pairs(t) do\n        -- table.insert(out, a)\n        out[i] = a\n    end\n    return out\nend\n\nfunction projectile_list_add(list, element)\n    local entry = projectile_table[element]\n    local i = entry and entry.i or 1\n    for j = 1,#list,2 do\n        if(list[j] == i) then\n            list[j+1] = list[j+1]+1\n            return\n        end\n    end\n    table.insert(list, i)\n    table.insert(list, 1)\nend\n\n-- function comma_multiplicity_list_add(list, new_element)\n--     --NOTE: this can fail if elements can contain a * character, or if they can be substrings of each other\n--     -- but this is fine since it's only used for filenames\n--     local i, j = string.find(list, new_element)\n--     if(i ~= nil) then\n--         local  pre = string.sub(list, 1, j)\n--         local post = string.sub(list, j+1)\n--         local n = 1\n--         local i, j = string.find(post, \"%*%d+\")\n--         if(i==1) then\n--             n = tonumber(string.sub(post,2,j))\n--             post = string.sub(post,j+1)\n--         end\n--         list = pre..\"*\"..(n+1)..post\n--         return list\n--     end\n--     list = list..new_element..\";\"\n--     return list\n-- end\n\n-- function comma_multiplicity_list_iter(list)\n--     return function()\n--         local mult_i, mult_j = string.find(list, \"%*%d+\")\n--         local comma_i, comma_j = string.find(list, \";\")\n--         if(not comma_i) then\n--             return\n--         end\n--         local n = 1\n--         local item_end = comma_i\n--         if(mult_i~=nil and mult_i < comma_i) then\n--             n = tonumber(string.sub(list, mult_i+1, mult_j))\n--             item_end = mult_i\n--         end\n--         local item = string.sub(list, 1, item_end-1)\n--         list = string.sub(list, comma_j+1)\n--         -- GamePrint(item..\" x \"..n)\n--         return item, n\n--     end\n-- end\n\n-- function format_comma_list(text)\n--     local counts = {}\n--     for item in string.gmatch(text, \"[^ ,]+\") do\n--         counts[item] = (counts[item] or 0)+1\n--     end\n--     local formatted = \"\"\n--     for i, n in pairs(counts) do\n--         formatted = formatted..i\n--         if(n ~= 1) then\n--             formatted = formatted..\" (x\"..n..\")\"\n--         end\n--         formatted = formatted..\", \"\n--     end\n--     return formatted\n-- end\n\n-- function make_format_comma_list_with_images(get_image)\n--     return function(text)\n--         local counts = {}\n--         for item in string.gmatch(text, \"[^ ,]+\") do\n--             counts[item] = (counts[item] or 0)+1\n--         end\n--         local formatted = {}\n--         for i, n in pairs(counts) do\n--             table.insert(formatted, {get_image(i), i})\n--             if(n ~= 1) then\n--                 table.insert(formatted, \"x\"..n..\" \")\n--             else\n--                 table.insert(formatted, \" \")\n--             end\n--         end\n--         return formatted\n--     end\n-- end\n\nfunction get_projectile_action(entity_filename)\n    local action = projectile_table[entity_filename]\n    if(action == nil) then\n        return nil\n    end\n    if(action.normal ~= nil) then\n        return action.normal\n    elseif(action.timer ~= nil) then\n        return action.timer\n    elseif(action.trigger ~= nil) then\n        return action.trigger\n    elseif(action.death_trigger ~= nil) then\n        return action.death_trigger\n    end\n    return nil\nend\n\nfunction get_projectile_icon(entity_filename)\n    local action = projectile_table[entity_filename]\n    if(action == nil) then\n        return \"data/ui_gfx/gun_actions/unidentified.png\"\n    end\n    if(action.normal ~= nil) then\n        return action.normal.sprite\n    elseif(action.timer ~= nil) then\n        return action.timer.sprite\n    elseif(action.trigger ~= nil) then\n        return action.trigger.sprite\n    elseif(action.death_trigger ~= nil) then\n        return action.death_trigger.sprite\n    end\n    return \"data/ui_gfx/gun_actions/unidentified.png\"\nend\n\nfunction format_projectiles(list)\n    local formatted = {}\n    for j = 1,#list,2 do\n        local e = list[j]\n        local n = list[j+1]\n        local item = projectile_list[e]\n        table.insert(formatted, {get_projectile_icon(item), item})\n        if(n ~= 1) then\n            table.insert(formatted, \"x\"..n..\" \")\n        elseif(last_e) then\n            table.insert(formatted, \" \")\n        end\n    end\n    return formatted\nend\n\nfunction format_cast_state_list(list)\n    local formatted = {}\n    for identifier, n in pairs(list) do\n        -- local action_id = string.match(identifier, \"[^:]*\")\n        local action_id = string.match(identifier, \"[^{]*\")\n        local items = string.sub(identifier, #action_id+2,-2)\n        local action_sprite\n        local action = action_table[action_id]\n        if(action ~= nil) then\n            action_sprite = action.sprite\n        else\n            action_sprite = \"data/ui_gfx/gun_actions/unidentified.png\"\n        end\n        table.insert(formatted, {action_sprite, items})\n        if(n ~= 1) then\n            table.insert(formatted, \"x\"..n..\" \")\n        else\n            table.insert(formatted, \" \")\n        end\n    end\n    return formatted\nend\n"
_TWWE_VFS["mods/wand_dbg/init.lua"] = "base_dir = \"mods/wand_dbg/\"\nmod_name = \"wand_dbg\"\ndofile_once(\"data/scripts/lib/utilities.lua\");\ndofile_once(base_dir .. \"files/debugger.lua\");\ndofile_once(base_dir .. \"files/spell_info.lua\");\ndofile_once(base_dir .. \"files/utils.lua\");\ndofile_once(base_dir .. \"files/ui.lua\");\n\nlocal gui = GuiCreate()\n\ndebug_wand = nil\naction_table, projectile_table, projectile_list, extra_entity_table = nil\n-- actions_list, projectile_table, extra_entity_table = {}, {}, {}\ndofile_once(base_dir .. \"files/cast_state_properties.lua\");\n\nlocal show_wand_dbg = ModSettingGet(mod_name..\".show\")\nlocal show_animation = ModSettingGet(mod_name..\".show_animation\")\nlocal need_to_remake_cards = false\n\n--                                                     id    x    y    w    h   show           title\nlocal config_window     = make_window(    \"config_window\", 390, 150, 230, 180, false, \"Wand Options\")\nlocal tree_window       = make_window(      \"tree_window\",  10,  54, 300, 170, false,    \"Flowchart\")\nlocal cast_state_window = make_window(\"cast_state_window\", 320,  54, 300, 170, false,  \"Shot States\")\n\nlocal current_cast_states = {}\nlocal final_cast_states = {}\nlocal cast_states = final_cast_states\nlocal cast_state_collapsed = {}\nlocal use_final_cast_state = ModSettingGet(mod_name..\".use_final_cast_state\") or true\n\nlocal current_i = 0\nlocal current_i_target = nil\nlocal playing = true\nlocal playback_timer = 20\nlocal looping = true\n\nlocal last_wand_deck\nlocal last_wand_stats\nlocal wand_changed = false\nlocal cast_history, action_trees, start_deck, always_casts, always_cast_cards\n\nlocal options = {\n    {id=\"maximize_uses\", name=\"Spell Uses\", type=\"boolean\", value=false, true_text=\"Max\", false_text=\"0\"},\n    {id=\"unlimited_spells\", name=\"Unlimited Spells\", type=\"boolean\", value=false},\n    {id=\"mana\", name=\"Mana\", type=\"number\", value=0, min=0, max=100},\n    {id=\"every_other_state\", name=\"Every Other State\", type=\"boolean\", value=false, true_text=\"Skip\", false_text=\"Don't skip\"},\n    {id=\"n_enemies\", name=\"Nearby enemies\", type=\"number\", value=0, min=0, max=100, integer=true},\n    {id=\"n_projectiles\", name=\"Nearby Projectiles\", type=\"number\", value=0, min=0, max=100, integer=true},\n    {id=\"n_omega_black_holes\", name=\"Nearby Omega Black Holes\", type=\"number\", value=0, min=0, max=100, integer=true},\n    {id=\"money\", name=\"Gold\", type=\"number\", value=0, min=0, max=2147483648, inf_value=2147483648, log_scale=true},\n    {id=\"hp\", name=\"HP\", type=\"number\", type = \"number\", value=4, min=0, max=400000000000, display_multiplier=25, log_scale=true},\n    {id=\"max_hp\", name=\"Max HP\", type=\"number\", type=\"number\", value=4, min=0, max=400000000000, display_multiplier=25, log_scale=true},\n    {id=\"n_stainless\", name=\"Number of Stainless\", type=\"number\", value=0, min=0, max=100, integer=true},\n    {id=\"ambrosia\", name=\"Ambrosia Stain\", type=\"boolean\", value=false},\n    -- {id=\"damage_multipliers\", name=\"Damage Multipliers\", type=\"custom\", value={ curse       = 1,\n    --                                                                             drill       = 1,\n    --                                                                             electricity = 1,\n    --                                                                             explosion   = 0.35,\n    --                                                                             fire        = 1,\n    --                                                                             healing     = 1,\n    --                                                                             ice         = 1,\n    --                                                                             melee       = 1,\n    --                                                                             overeating  = 1,\n    --                                                                             physics_hit = 1,\n    --                                                                             poison      = 1,\n    --                                                                             projectile  = 1,\n    --                                                                             radioactive = 1,\n    --                                                                             slice       = 1 }},\n    -- {id=\"zeta_options\", name=\"Zeta Options\", type=\"custom\", value = {}},\n    {id=\"frame_number\", name=\"Frame Number\", type=\"text_number\", value = 0, integer=true},\n    {id=\"show_with_inventory\", name=\"Show Windows when Inventory is Open\", type=\"boolean\", value = false, always_override = true},\n}\n\nlocal config = {}\n\nfor i, option in ipairs(options) do\n    option.default = option.value\n    option.override = ModSettingGet(mod_name..\".\"..option.id..\"_override\") or nil\n    option.value    = ModSettingGet(mod_name..\".\"..option.id..\"_value\") or option.value\n    option.value = option.value or false\n    config[option.id] = option.override and option.value\nend\n\nlocal discarded = {}\nlocal hand = {}\nlocal deck = {}\n\n-- debug_wand = dofile_once( \"mods/wand_dbg/files/debugger.lua\" );\n\nfunction OnWorldInitialized()\nend\n\nlocal _ModTextFileGetContent = ModTextFileGetContent;\nfunction OnWorldPreUpdate()\n    -- dofile( \"mods/spell_lab/files/gui/update.lua\" );\nend\n\nfunction get_bg_sprite(type)\n    local bg_sprite = \"data/ui_gfx/inventory/item_bg_\"\n    if(type == ACTION_TYPE_PROJECTILE) then\n        bg_sprite = bg_sprite .. \"projectile\"\n    elseif(type == ACTION_TYPE_STATIC_PROJECTILE) then\n        bg_sprite = bg_sprite .. \"static_projectile\"\n    elseif(type == ACTION_TYPE_MODIFIER) then\n        bg_sprite = bg_sprite .. \"modifier\"\n    elseif(type == ACTION_TYPE_DRAW_MANY) then\n        bg_sprite = bg_sprite .. \"draw_many\"\n    elseif(type == ACTION_TYPE_MATERIAL) then\n        bg_sprite = bg_sprite .. \"material\"\n    elseif(type == ACTION_TYPE_OTHER) then\n        bg_sprite = bg_sprite .. \"other\"\n    elseif(type == ACTION_TYPE_UTILITY) then\n        bg_sprite = bg_sprite .. \"utility\"\n    elseif(type == ACTION_TYPE_PASSIVE) then\n        bg_sprite = bg_sprite .. \"passive\"\n    end\n    bg_sprite = bg_sprite .. \".png\"\n    return bg_sprite\nend\n\nlocal player\n\nlocal action_sprites = {}\nlocal dying_action_sprites = {}\n\nfunction make_debug_card(action)\n    card = {action = action, x = 0, y = 0, theta = 0, scale = 1.0, dx = 0, dy = 0, dtheta = 0, dscale = 0.0, x_target = 0, y_target = 0}\n    action.debug_card = card\n    return card\nend\n\nfunction clear_card_sprites(always_casts_only)\n    local children = EntityGetAllChildren(player)\n    if children ~= nil then\n        for i, c in ipairs(children) do\n            if(not always_casts_only) then\n                if(EntityHasTag(c, \"dbg_card\")) then\n                    EntityKill(c)\n                end\n            else\n                if(EntityHasTag(c, \"ac_dbg_card\")) then\n                    EntityKill(c)\n                end\n            end\n        end\n    end\nend\n\nfunction add_sprite(card, is_always_cast)\n    local bg_sprite = get_bg_sprite(card.action.type)\n    local card_sprite = EntityCreateNew(\"debug_card\")\n    EntityAddChild(player, card_sprite)\n    if(is_always_cast) then\n        EntityAddTag(card_sprite, \"ac_dbg_card\")\n    end\n    EntityAddTag(card_sprite, \"dbg_card\")\n    -- EntityAddComponent(card_sprite, \"VariableStorageComponent\",\n    --                    {value_int = i})\n    EntityAddComponent(card_sprite, \"SpriteComponent\",\n                        {_tags = \"enabled_in_world,ui,no_hitbox,\",\n                        image_file = bg_sprite,\n                        emissive=\"1\",\n                        offset_x=\"10\",\n                        offset_y=\"19\",\n                        -- has_special_scale=\"1\",\n                        -- special_scale_x=\"1.0\",\n                        -- special_scale_y=\"1.0\",\n                        z_index=\"-1.5\"})\n    EntityAddComponent(card_sprite, \"SpriteComponent\",\n                        {_tags = \"enabled_in_world,ui,no_hitbox,\",\n                        image_file = card.action.sprite,\n                        emissive=\"1\",\n                        offset_x=\"8\",\n                        offset_y=\"17\",\n                        -- has_special_scale=\"1\",\n                        -- special_scale_x=\"1.0\",\n                        -- special_scale_y=\"1.0\",\n                        z_index=\"-1.51\"})\n    return card_sprite\nend\n\nfunction clear_action_sprites()\n    local children = EntityGetAllChildren(player)\n    if(children ~= nil) then\n        for i, c in ipairs(children) do\n            if(EntityHasTag(c, \"dbg_action\")) then\n                EntityKill(c)\n            end\n        end\n    end\n    action_sprites = {}\n    dying_action_sprites = {}\nend\n\nfunction add_action_sprite(action)\n    local bg_sprite = get_bg_sprite(action.type)\n    local card_sprite = EntityCreateNew(\"debug_action\")\n    EntityAddChild(player, card_sprite)\n    EntityAddTag(card_sprite, \"dbg_action\")\n    -- EntityAddComponent(card_sprite, \"VariableStorageComponent\",\n    --                    {value_int = i})\n    -- EntityAddComponent(card_sprite, \"SpriteComponent\",\n    --                     {_tags = \"enabled_in_world,ui,no_hitbox,\",\n    --                     image_file = bg_sprite,\n    --                     emissive=\"1\",\n    --                     offset_x=\"10\",\n    --                     offset_y=\"19\",\n    --                     -- has_special_scale=\"1\",\n    --                     -- special_scale_x=\"1.0\",\n    --                     -- special_scale_y=\"1.0\",\n    --                     z_index=\"-1.5\"})\n    EntityAddComponent(card_sprite, \"SpriteComponent\",\n                        {_tags = \"enabled_in_world,ui,no_hitbox,\",\n                         image_file = action_table[action.id].sprite,\n                         emissive=\"1\",\n                         offset_x=\"8\",\n                         offset_y=\"17\",\n                         -- has_special_scale=\"1\",\n                         -- special_scale_x=\"1.0\",\n                         -- special_scale_y=\"1.0\",\n                         z_index=\"-1.51\"})\n    EntityAddComponent(card_sprite, \"SpriteComponent\",\n                       {_tags = \"enabled_in_world,ui,no_hitbox,line1,\",\n                        image_file = \"data/fonts/font_pixel_white.xml\",\n                        is_text_sprite=\"1\",\n                        emissive=\"1\",\n                        offset_x=\"15\",\n                        offset_y=\"4\",\n                        text=\"\",\n                        has_special_scale=\"1\",\n                        special_scale_x=\"0.6\",\n                        special_scale_y=\"0.6\",\n                        z_index=\"-1.51\"})\n    EntityAddComponent(card_sprite, \"SpriteComponent\",\n                       {_tags = \"enabled_in_world,ui,no_hitbox,line2,\",\n                        image_file = \"data/fonts/font_pixel_white.xml\",\n                        is_text_sprite=\"1\",\n                        emissive=\"1\",\n                        offset_x=\"15\",\n                        offset_y=\"-4\",\n                        text=\"\",\n                        has_special_scale=\"1\",\n                        special_scale_x=\"0.6\",\n                        special_scale_y=\"0.6\",\n                        z_index=\"-1.51\"})\n    return card_sprite\nend\n\nfunction push_action(node)\n    local action = node.action\n    local new_action_sprite = {node = node, sprite=add_action_sprite(action), x = (action.debug_card and action.debug_card.x) or 0, y = (action.debug_card and action.debug_card.y) or 0, theta = 0, scale = 1.0, dx = 0, dy = 0, dtheta = 0, dscale = 0.0, x_target = 0, y_target = 0, line1 = \"\", line2 = \"\"}\n    table.insert(action_sprites, new_action_sprite)\n    return new_action_sprite\nend\n\nfunction pop_action(fadetime)\n    local action_sprite = action_sprites[#action_sprites]\n    action_sprite.dy = action_sprite.dy+2\n    action_sprite.dscale = action_sprite.dscale+1\n    action_sprite.lifetime = fadetime\n    action_sprite.max_lifetime = fadetime\n    table.remove(action_sprites, #action_sprites)\n    table.insert(dying_action_sprites, action_sprite)\nend\n\nlocal playback_wait = 20\n\nfunction animate_card(card, sprite_entity, cx, cy, gui_to_world_scale)\n    local rx = 0\n    local ry = 0\n    if(card.x_target ~= nil and card.y_target ~= nil) then\n        rx = card.x_target - card.x\n        ry = card.y_target - card.y\n    end\n\n    local k = 0.1\n    local c = 0.5\n\n    local ddx = -c*card.dx + k*rx\n    card.dx = card.dx + ddx\n    card.dy = (1.0-c)*card.dy + k*ry\n\n    local k_theta = 0.1\n    local c_theta = 0.5\n    card.dtheta = (1.0-c)*card.dtheta - k_theta*card.theta\n    card.dtheta = card.dtheta - 0.01*ddx\n\n    local k_scale = 0.2\n    local c_scale = 0.5\n    card.dscale = (1.0-c_scale)*card.dscale + k_scale*(1.0-card.scale)\n\n    card.x = card.x + card.dx\n    card.y = card.y + card.dy\n    card.theta = card.theta + card.dtheta\n    card.scale = card.scale + card.dscale\n    if(card.scale < 0.1) then card.scale = 0.1 end\n\n    EntitySetTransform(sprite_entity,\n                       cx+gui_to_world_scale*card.x, cy+gui_to_world_scale*card.y, card.theta, card.scale, card.scale)\n\n    local line1 = EntityGetFirstComponent(sprite_entity, \"SpriteComponent\", \"line1\")\n    local line2 = EntityGetFirstComponent(sprite_entity, \"SpriteComponent\", \"line2\")\n    if(line1 ~= nil) then\n        local old_text = ComponentGetValue2(line1, \"text\")\n        if(card.line1 ~= old_text) then\n            ComponentSetValue2(line1, \"text\", card.line1)\n            EntityRefreshSprite(sprite_entity, line1)\n        end\n    end\n    if(line2 ~= nil) then\n        local old_text = ComponentGetValue2(line2, \"text\")\n        if(card.line2 ~= old_text) then\n            ComponentSetValue2(line2, \"text\", card.line2)\n            EntityRefreshSprite(sprite_entity, line2)\n        end\n    end\nend\n\nfunction animate_dying_card(card, sprite_entity, cx, cy, gui_to_world_scale)\n    local c = 0.1\n\n    local ddx = -c*card.dx\n    card.dx = card.dx + ddx\n    card.dy = (1.0-c)*card.dy\n\n    local k_theta = 0.1\n    local c_theta = 0.5\n    card.dtheta = (1.0-c)*card.dtheta - k_theta*card.theta\n    card.dtheta = card.dtheta - 0.01*ddx\n\n    local c_scale = 0.1\n    card.dscale = (1.0-c_scale)*card.dscale\n\n    card.x = card.x + card.dx\n    card.y = card.y + card.dy\n    card.theta = card.theta + card.dtheta\n    card.scale = card.scale + card.dscale\n    if(card.scale < 0.1) then card.scale = 0.1 end\n\n    local alpha = 1\n    card.lifetime = card.lifetime-1\n    alpha = card.lifetime/card.max_lifetime\n    if(card.lifetime <= 0) then\n        EntityKill(card.sprite)\n        return false\n    end\n\n    EntitySetTransform(sprite_entity,\n                       cx+gui_to_world_scale*card.x, cy+gui_to_world_scale*card.y, card.theta, card.scale, card.scale)\n    local sprites = EntityGetComponent(sprite_entity, \"SpriteComponent\")\n    if(sprites ~= inl) then\n        for i, s in ipairs(sprites) do\n            ComponentSetValue2(s, \"alpha\", alpha)\n        end\n    end\n    local line1 = EntityGetFirstComponent(sprite_entity, \"SpriteComponent\", \"line1\")\n    local line2 = EntityGetFirstComponent(sprite_entity, \"SpriteComponent\", \"line2\")\n    if(line1 ~= nil) then\n        local old_text = ComponentGetValue2(line1, \"text\")\n        if(card.line1 ~= old_text) then\n            ComponentSetValue2(line1, \"text\", card.line1)\n            EntityRefreshSprite(sprite_entity, line1)\n        end\n    end\n    if(line2 ~= nil) then\n        local old_text = ComponentGetValue2(line2, \"text\")\n        if(card.line2 ~= old_text) then\n            ComponentSetValue2(line2, \"text\", card.line2)\n            EntityRefreshSprite(sprite_entity, line2)\n        end\n    end\n\n    return true\nend\n\nfunction draw_deck(base_x, base_y, cx, cy, gui_to_world_scale, deck, focus)\n    -- if(focus_on_end == nil) then focus_on_end = true end\n    focus = focus or \"middle\"\n    for i, card in ipairs(deck) do\n        -- local sprite = card.action.sprite\n        -- local bg_sprite = get_bg_sprite(card.action.type)\n\n        -- local im_w, im_h = GuiGetImageDimensions(gui, bg_sprite, scale)\n\n        -- local x_rel = 16*i\n        -- local y_rel = 0\n\n        -- GuiImage(gui, get_id(), base_x+x_rel-im_w/2, base_y+y_rel-im_h/2, bg_sprite,\n        --          1.0, scale, 0, 0)\n\n        -- im_w, im_h = GuiGetImageDimensions(gui, sprite, scale)\n        -- GuiImage(gui, get_id(), base_x+x_rel-im_w/2, base_y+y_rel-im_h/2, sprite,\n        --          1.0, scale, 0, 0)\n\n        local spacing = 24\n        local max_spacings = 6\n        if(#deck > max_spacings) then\n            local a2 = math.min((#deck-1)/max_spacings-1, 1)\n            local a1 = 1-a2\n            if(focus==\"right\") then\n                local z = (i-1)/(#deck-1)\n                card.x_target = base_x + spacing*max_spacings*(a1*z+a2*z*z)\n            elseif(focus==\"left\") then\n                local z = (#deck-i)/(#deck-1)\n                card.x_target = base_x + spacing*max_spacings*(1-a1*z-a2*z*z)\n            elseif(focus==\"middle\") then\n                card.x_target = base_x + spacing*max_spacings*(i-1)/(#deck-1)\n            end\n        else\n            card.x_target = base_x + spacing*(i-1)\n        end\n\n        card.y_target = base_y + 0.0\n\n        animate_card(card, card.sprite, cx, cy, gui_to_world_scale)\n    end\nend\n\nfunction draw_playback(base_x, base_y, width, mx, my)\n    local button_width = 8\n    local button_spacing = 4\n    local bar_width = width - (4*button_width+4*button_spacing)\n\n    if(cast_history == nil) then return current_i_target end\n\n    local play_pause = base_dir..\"files/ui_gfx/play.png\"\n    local play_pause_text = \"play\"\n    if(playing) then\n        play_pause = base_dir..\"files/ui_gfx/pause.png\"\n        play_pause_text = \"pause\"\n    end\n    local loop_text = \"loop\"\n    if(looping) then\n        loop_text = \"don't loop\"\n    end\n\n    local x = base_x+bar_width\n    x = x+button_spacing\n    local prev_pressed = GuiImageButton(gui, get_id(\"playback_previous\"), x, base_y-3.5, \"\", base_dir..\"files/ui_gfx/prev.png\")\n    get_previous_widget_info()\n    GuiTooltip(gui, \"previous\", \"\")\n    x = x+button_spacing+button_width\n    local play_pause_pressed = GuiImageButton(gui, get_id(\"playback_play\"), x, base_y-3.5, \"\", play_pause)\n    get_previous_widget_info()\n    GuiTooltip(gui, play_pause_text, \"\")\n    x = x+button_spacing+button_width\n    local next_pressed = GuiImageButton(gui, get_id(\"playback_next\"), x, base_y-3.5, \"\", base_dir..\"files/ui_gfx/next.png\")\n    get_previous_widget_info()\n    GuiTooltip(gui, \"next\", \"\")\n    x = x+button_spacing+button_width\n    if(not looping) then GuiColorSetForNextWidget( gui, 0.5, 0.5, 0.5, 0.5) end\n    local loop_pressed = GuiImageButton(gui, get_id(\"playback_loop\"), x, base_y-3.5, \"\", base_dir..\"files/ui_gfx/loop.png\")\n    get_previous_widget_info()\n    GuiTooltip(gui, loop_text, \"\")\n\n    if(play_pause_pressed) then\n        playing = not playing\n    end\n    if(loop_pressed) then\n        looping = not looping\n    end\n    if(next_pressed) then\n        current_i_target = current_i+1\n    end\n    if(prev_pressed) then\n        current_i_target = current_i-1\n    end\n\n    local last_x_rel = 0\n    local last_y_rel = 0\n    local last_indent_offset = 0\n\n    local base_scale = 0.5\n    local scale = base_scale\n\n    local first_action = true\n\n    local j = 0\n    local x_rel = 0\n    local y_rel = 0\n\n    local mouse_t = clamp((mx-base_x)/bar_width*#cast_history, 0.001, #cast_history)\n\n    local ui_hover = (math.abs(mx-(base_x+bar_width/2)) <= bar_width/2+button_width/2 and math.abs(my-(base_y)) <= button_width)\n\n    --invisible line to block clicks from casting spells\n    draw_line(gui, base_x, base_y,\n              base_x+bar_width, base_y,\n              2*button_width, \"white\", 0.0, 0)\n\n    draw_line(gui, base_x, base_y,\n              base_x+bar_width, base_y,\n              1.0, \"white\", 1.0, 0)\n    GuiImage(gui, get_id(\"playback_indicator\"), base_x+bar_width*(current_i-1)/#cast_history-3.5, base_y-3.5, base_dir..\"files/ui_gfx/big_dot.png\",\n             1, 1)\n    if(ui_hover and not other_window_blocking) then\n        local clicked = GuiImageButton(gui, get_id(\"playback_click_blocker\"), base_x+bar_width*mouse_t/#cast_history-50.5, base_y-50.5, \"\", base_dir..\"files/ui_gfx/invisible_button.png\")\n        get_previous_widget_info()\n        GuiText(gui, base_x+bar_width*mouse_t/#cast_history, base_y, math.ceil(mouse_t)..\"/\"..#cast_history)\n        GuiImage(gui, get_id(\"playback_hover_indicator\"), base_x+bar_width*mouse_t/#cast_history-3.5, base_y-3.5, base_dir..\"files/ui_gfx/big_dot.png\", 0.5, 1)\n       if(clicked) then\n           current_i_target = math.ceil(mouse_t)\n       end\n    end\n    if #cast_history < bar_width then\n        for i, e in ipairs(cast_history) do\n            if(e.type == \"action\") then\n                GuiImage(gui, get_id(), base_x+bar_width*i/#cast_history-1.5, base_y-1.5, base_dir..\"files/ui_gfx/small_dot.png\",\n                         1, 1)\n            end\n        end\n    end\n\n    return current_i_target\nend\n\nfunction process_node(tree)\n    local name = tree.action and tree.action.id or \"shot_\"..tree.cast_number\n    tree.str = \"(\" .. name\n    local previous_child_string = nil\n    for i, c in ipairs(tree.children) do\n        if(c.str == nil) then\n            process_node(c)\n        end\n        if(i ~= 0) then\n            tree.str = tree.str .. \" \"\n        end\n        tree.str = tree.str .. c.str\n        c.identical_to_previous = (c.str == previous_child_string)\n        previous_child_string = c.str\n    end\n    tree.str = tree.str..\")\"\nend\n\nfunction draw_ellipses(number_identical, width, x_spacing, y_spacing, scale, x, y, parent_x, parent_y)\n    -- if(parent_x ~= nil and parent_y ~= nil) then\n    --     local x_start = parent_x+8*scale\n    --     local y_start = parent_y\n    --     local x_end = x-8*scale\n    --     local y_end = y\n    --     draw_spline(gui, x_start, y_start, x_start+0.5*x_spacing, y_start,\n    --                 x_end-0.5*x_spacing, y_end, x_end, y_end,\n    --                 0.5, \"white\", 1.0, 0, 4, 1)\n    -- end\n\n    x = x-8*scale\n    y = y-10*scale\n    draw_spline(gui, x, y, x, y+4,\n                x+0.5*width, y, x+0.5*width, y+4,\n                0.5, \"white\", 1.0, 0)\n    draw_spline(gui, x+width, y, x+width, y+4,\n                x+0.5*width, y, x+0.5*width, y+4,\n                0.5, \"white\", 1.0, 0)\n    GuiOptionsAddForNextWidget(gui, GUI_OPTION.Align_HorizontalCenter)\n    GuiText(gui, x+0.5*width, y+2.5,\"x\" .. number_identical)\n    height = 11\n    return width, height\nend\n\nfunction draw_node(tree, x_spacing, y_spacing, scale, x, y, parent_x, parent_y)\n    local spline_offset = 0\n    local node_height = 0\n    if(tree.action ~= nil) then\n        local sprite = tree.action.sprite\n        local bg_sprite = get_bg_sprite(tree.action.type)\n        local im_w, im_h = GuiGetImageDimensions(gui, bg_sprite, scale)\n        z_set_next_relative(gui, 0.5)\n        gui_image_bounded(gui, get_id(\"node_background\"..tostring(tree)), x-im_w/2, y-im_h/2, bg_sprite,\n                                                      1.0, scale, 0, 0)\n        local clicked, right_clicked, hovered, text_x, text_y, bwidth, bheight = get_previous_widget_info_bounded(gui)\n\n        local foreground_scale = scale\n        if(hovered) then\n            foreground_scale = 1.5*foreground_scale\n        end\n        im_w, im_h = GuiGetImageDimensions(gui, sprite, foreground_scale)\n        z_set_next_relative(gui, 0.25)\n        gui_image_bounded(gui, get_id(\"node_foreground\"..tostring(tree)), x-im_w/2, y-im_h/2, sprite,\n                 1.0, foreground_scale, 0, 0)\n        if(clicked) then\n            current_i_target = tree.event_index\n        end\n\n        if(tree.flavor) then\n            local fscale = 0.75\n            local fx = x-im_w*(0.5+0.5*fscale)\n            local fy = y+im_h*(0.5-0.5*fscale)\n            draw_text_image_list(format_projectiles(tree.flavor), fx, fy, fscale*scale, -im_h*(1.0-fscale)*0.5)\n            node_height = node_height+im_h*(0.5)\n        end\n\n        if(tree.recursion_limited) then\n            local cross_half = 0.6*y_spacing\n            draw_line(gui, x-cross_half, y-cross_half, x+cross_half, y+cross_half, 1.0, \"red\", 0.8)\n            draw_line(gui, x-cross_half, y+cross_half, x+cross_half, y-cross_half, 1.0, \"red\", 0.8)\n        end\n    else\n        -- GuiOptionsAddForNextWidget(gui, GUI_OPTION.Align_Left)\n        GuiOptionsAddForNextWidget(gui, GUI_OPTION.Align_HorizontalCenter)\n        GuiText(gui, x, y-5, tree.cast_number)\n        local clicked, right_clicked, hovered, text_x, text_y, twidth, theight = get_previous_widget_info(gui)\n        spline_offset = twidth/2-3\n    end\n\n    if(parent_x ~= nil and parent_y ~= nil) then\n        local x_start = parent_x+8*scale\n        local y_start = parent_y\n        local x_end = x-8*scale\n        local y_end = y\n\n        local color\n        if(tree.explanation == \"draw\") then\n            color = \"white\"\n        elseif(tree.explanation == \"always_cast\") then\n            color = \"light_blue\"\n        else\n            color = \"gold\"\n        end\n        draw_spline(gui, x_start, y_start, x_start+0.5*x_spacing, y_start,\n                    x_end-0.5*x_spacing, y_end, x_end, y_end,\n                    0.5, color, 1.0, 0, 4, 1)\n    end\n\n    if(tree.width and tree.height and (x+tree.width < bound_x_min or x > bound_x_max or y+tree.height < bound_y_min or y > bound_y_max)) then\n        return tree.width, tree.height\n    end\n\n    local height = 0\n    local width = x_spacing\n    local max_child_width = 0\n    local previous_width = 0\n    local number_identical = 1\n    for i, c in ipairs(tree.children) do\n        local child_x = x+x_spacing\n        local child_y = y+height\n        if(c.identical_to_previous) then\n            number_identical = number_identical + 1\n        else\n            if(number_identical > 1) then\n                local ellipses_width, ellipses_height = draw_ellipses(number_identical, previous_width, x_spacing, y_spacing, scale, child_x, child_y, x, y)\n                height = height + ellipses_height\n                child_y = y+height\n            end\n            number_identical = 1\n            local child_width, child_height = draw_node(c, x_spacing, y_spacing, scale, child_x, child_y, x+spline_offset, y)\n            if(child_width > max_child_width) then\n                max_child_width = child_width\n            end\n            previous_width = child_width\n            height = height+child_height\n        end\n    end\n\n    if(number_identical > 1) then\n        local child_x = x+x_spacing\n        local child_y = y+height\n        local ellipses_width, ellipses_height = draw_ellipses(number_identical, previous_width, x_spacing, y_spacing, scale, child_x, child_y, x, y)\n        height = height + ellipses_height\n    end\n\n    if(tree.draw_how_many ~= nil and tree.dont_draw_actions\n       or (tree.draw_how_many == 1 and tree.playing_permanent_card)) then\n        local x_start = x+8*scale\n        local y_start = y\n        local x_text = x+x_spacing\n        if(#tree.children == 0) then\n            x_text = x+0.7*x_spacing\n        end\n        local x_end = x_text-4*scale\n        local y_end = y+height\n        height = height+y_spacing\n        draw_spline(gui, x_start, y_start, x_start+0.5*x_spacing, y_start,\n                    x_end-0.5*x_spacing, y_end, x_end, y_end,\n                    0.5, \"red\", 1.0, 0, 4, 1)\n        local text = tree.draw_how_many\n        local text_width, text_height = GuiGetTextDimensions(gui, text, 1, 0)\n        GuiColorSetForNextWidget(gui,1.0,0,0,1)\n        GuiOptionsAddForNextWidget(gui, GUI_OPTION.Align_HorizontalCenter)\n        GuiText(gui, x_text+0.5, y_end-0.5*text_height+0.5, text)\n        local cross_half = 0.3*y_spacing\n        draw_line(gui, x_text-cross_half+0.5, y_end-cross_half+0.5, x_text+cross_half, y_end+cross_half, 1.0, \"red\", 0.8)\n        draw_line(gui, x_text-cross_half+0.5, y_end+cross_half-0.5, x_text+cross_half, y_end-cross_half, 1.0, \"red\", 0.8)\n        max_child_width = math.max(max_child_width, x_text-x_start+cross_half)\n    end\n\n    width = width+max_child_width\n    if(#tree.children == 0) then\n        width = 8+max_child_width\n        height = y_spacing\n    end\n    height = math.max(y_spacing+node_height, height)\n    tree.width = width\n    tree.height = height\n    return width, height\nend\n\nfunction draw_trees(base_x, base_y, min_height)\n    base_x = base_x or 0\n    base_y = base_y or 0\n\n    local x_spacing = 20\n    local y_spacing = 10\n\n    local scale = 0.5\n\n    local x = base_x+8\n    local y = base_y+8\n\n    for i, t in ipairs(action_trees) do\n        local width, height = draw_node(t, x_spacing, y_spacing, scale, x, y)\n        y = y + height\n        extend_max_bound(width+8+0.5*x_spacing, y-base_y)\n    end\n\n    --invisible dot for bottom margin\n    local dot_sprite = base_dir .. \"files/ui_gfx/line_dot_white.png\"\n    GuiImage(gui, get_id(), x, y, dot_sprite, 0.0, 1, 0, 0)\n\n    return y-base_y\nend\n\nfunction draw_text_image_list(value, x, y, scale, text_offset)\n    scale = scale or 0.5\n    text_offset = text_offset or 0\n    local width = 0\n    if(type(value) == \"string\") then\n        width = GuiGetTextDimensions(gui, value)\n        GuiText(gui, x, y+text_offset, value)\n    elseif(type(value) == \"table\") then\n        for i,t in ipairs(value) do\n            local item_width = 0\n            local item_height = 0\n            if(type(t) == \"string\") then\n                item_width = GuiGetTextDimensions(gui, t)\n                GuiText(gui, x, y+text_offset, t)\n            else\n                item_width, item_height = GuiGetImageDimensions(gui, t[1], scale)\n                gui_image_bounded(gui, get_id, x, y+1, t[1], 1, scale)\n                GuiTooltip(gui, t[2], \"\")\n                item_width = item_width+1\n            end\n            width = width+item_width\n            x = x+item_width\n        end\n        width = width-4\n    end\n    return width\nend\n\nfunction draw_cast_state(state, x, y)\n    local base_x = x\n    local base_y = y\n    local width = 0\n    local height = 0\n\n    if(state.width and state.height and (x+state.width < bound_x_min or x > bound_x_max or y+state.height < bound_y_min or y > bound_y_max)) then\n        return state.width, state.height\n    end\n\n    local c = state.current\n\n    if(c.projectiles ~= nil and #c.projectiles > 0)  then\n        width = draw_text_image_list(format_projectiles(c.projectiles), x+6, y)+10\n    else\n        text = cast_state_collapsed[state.c] and \"no proj.\" or \"no projectiles\"\n        width = draw_text_image_list(text, x+6, y)+10\n    end\n    y = y+8\n    height = height+8\n    if(not cast_state_collapsed[state.c]) then\n        for i, p in ipairs(cast_state_properties) do\n            local raw_value = p.get(c)\n            if(raw_value ~= nil and raw_value ~= p.default) then\n                local value\n                if(p.format ~= nil) then\n                    value = p.format(raw_value)\n                else\n                    value = to_string(raw_value)\n                end\n                local text = p.name..\": \"\n                local name_width = GuiGetTextDimensions(gui, text)\n                GuiText(gui, x+4, y, text)\n                local value_width = draw_text_image_list(value, x+4+name_width, y)\n                width = math.max(width, name_width+value_width+8)\n                y = y+8\n                height = height+8\n            end\n        end\n    -- else\n    --     width = 10\n    --     height = 8\n    end\n    height = height+4\n\n    -- draw_box(gui, x, base_y, width, height, 1, 1)\n    --invisible image to get offsets\n    GuiImage(gui, get_id(\"cast_state_offset_\"..tostring(state)), 0, 0, base_dir .. \"files/ui_gfx/line_dot_white.png\", 0.0)\n    local clicked, right_clicked, hovered, x0, y0, widget_width, widget_height = get_previous_widget_info(gui)\n\n    local widg_x = x0+math.max(x, bound_x_min)\n    local widg_y = y0+math.max(base_y, bound_y_min)\n    local widg_w = x0+math.min(width+x, bound_x_max)-widg_x\n    local widg_h = y0+math.min(height+base_y, bound_y_max)-widg_y\n    if(widg_w > 0 and widg_h > 0) then\n\n        GuiOptionsAddForNextWidget(gui, GUI_OPTION.ForceFocusable)\n        z_set_next_relative(gui, 1.0)\n\n        local nine_piece = base_dir..\"files/ui_gfx/9piece_outline.png\"\n        local highlight_nine_piece = base_dir..\"files/ui_gfx/9piece_outline_highlight.png\"\n        if(other_window_blocking or not inner_window_hovered) then\n            highlight_nine_piece = nine_piece\n        end\n        GuiImageNinePiece(gui, get_id(\"cast_state_collapse_button_\"..tostring(state)), widg_x, widg_y, widg_w, widg_h, 1,\n                          nine_piece, highlight_nine_piece)\n        local clicked, right_clicked, hovered, widget_x, widget_y, widget_width, widget_height = get_previous_widget_info(gui)\n        if(hovered) then\n            -- GuiOptionsAddForNextWidget(gui, GUI_OPTION.Layout_NoLayouting)\n            -- GuiImage(gui, get_id(), mx, my, base_dir .. \"files/ui_gfx/line_dot_white.png\", 1, 10, 10)\n            GuiOptionsAddForNextWidget(gui, GUI_OPTION.Layout_NoLayouting)\n            -- GuiText(gui, mx, my, \"width = \"..width..\", height = \"..height..\"; widget_width = \"..widget_width..\", widget_height = \"..widget_height)\n            local tooltip_text = cast_state_collapsed[state.c] and \"expand\" or \"collapse\"\n            GuiText(gui, mx, my, tooltip_text)\n        end\n        if(clicked) then\n            cast_state_collapsed[state.c] = not cast_state_collapsed[state.c]\n        end\n        local image = base_dir..\"files/ui_gfx/black_circle.png\"\n        local im_w, im_h = GuiGetImageDimensions(gui, image, 1)\n        GuiImage(gui, get_id(), base_x-0.5*im_w, base_y-0.5*im_h, image, 1, 1)\n        z_set_next_relative(gui, -0.5)\n        if(state.c.shot_type == \"root\") then\n            local cast_number = state.c.root_node.cast_number or \"error\"\n            local im_w, im_h = GuiGetTextDimensions(gui, cast_number)\n            GuiText(gui, base_x-0.5*im_w+0.5, base_y-0.5*im_h, cast_number)\n        else\n            local image = get_projectile_icon(state.c.parent_projectile)\n            local im_w, im_h = GuiGetImageDimensions(gui, image, 0.5)\n            gui_image_bounded(gui, get_id(), base_x-0.5*im_w, base_y-0.5*im_h, image, 1, 0.5)\n\n            local description = \"\"\n            local trigger_name = \"\"\n            if(state.c.shot_type == \"timer\") then\n                trigger_name = \"a \"..state.c.timer..\" frame timer\"\n            elseif(state.c.shot_type == \"trigger\") then\n                trigger_name = \"a trigger\"\n            elseif(state.c.shot_type == \"death_trigger\") then\n                trigger_name = \"an expiration trigger\"\n            else\n                trigger_name = \"an unknown trigger type\"\n            end\n            GuiTooltip(gui, state.c.parent_projectile..\" with \"..trigger_name, description)\n\n            z_set_next_relative(gui, -1.0)\n            local image = base_dir..\"files/ui_gfx/\"..state.c.shot_type..\".png\"\n            local im_w, im_h = GuiGetImageDimensions(gui, image, 0.5)\n            GuiImage(gui, get_id(), base_x-0.5*im_w-3, base_y-0.5*im_h-3, image, 1, 0.5)\n        end\n    end\n    state.width = width\n    state.height = height\n    return width, height\nend\n\nfunction draw_cast_states(states, x, y, parent_x, parent_y)\n    local width = 0\n    local height = 0\n\n    local x_spacing = 24\n\n    local base_x = x\n    local base_y = y\n\n    for i, c in ipairs(states) do\n        if(cast_states[c] == nil) then\n            break\n        end\n\n        if(parent_x ~= nil) then\n            local x_start = parent_x\n            local y_start = math.min(parent_y, y)\n            local x_end = x-4\n            local y_end = y\n            z_set_relative(gui, -1.5)\n            draw_spline(gui, x_start, y_start, x_start+0.5*x_spacing, y_start,\n                        x_end-0.5*x_spacing, y_end, x_end, y_end,\n                        0.5, \"white\", 1.0, 0, 4, 1)\n            z_set_relative(gui, 0)\n        end\n\n        local state_width, state_height = draw_cast_state(cast_states[c], x+4, y)\n        state_width = state_width+8\n\n        local child_x = x+state_width+x_spacing\n        local child_y = y\n\n        local children_width, children_height = draw_cast_states(cast_states[c].children, child_x, child_y,\n                                                                 x+state_width, y+state_height)\n        children_width = children_width+x_spacing+8\n        state_height = math.max(state_height+8, children_height)\n        y = y+state_height\n        width = math.max(width, state_width+children_width)\n        height = height+state_height\n        extend_max_bound(4+width, y)\n    end\n\n    --invisible dot for bottom margin\n    local dot_sprite = base_dir .. \"files/ui_gfx/line_dot_white.png\"\n    GuiImage(gui, get_id(), x, y, dot_sprite, 0.0, 1, 0, 0)\n\n    return width, height\nend\n\nfunction draw_config(x, y, window_x, window_y)\n    for i, option in ipairs(options) do\n        local option_changed = false\n        if(option.always_override) then\n            option.override = option.always_override\n        end\n\n        local button_text = option.name..\": \"\n        if(not option.override) then\n            button_text = button_text..\"Use game value\"\n        elseif(option.type == \"boolean\") then\n            button_text = button_text..\"\"..(option.value and (option.true_text or \"Yes\") or (option.false_text or \"No\"))\n        elseif(option.type == \"number\") then\n            if(option.inf_value and option.value >= option.inf_value) then\n                button_text = button_text..\"∞\"\n            else\n                button_text = button_text..string.format(\"%.0f\", option.value*(option.display_multiplier or 1))\n            end\n        end\n        local clicked, right_clicked = GuiButton(gui, get_id(\"config_button_\"..option.id), x, y, button_text)\n        local _, __, hovered, button_x, button_y, button_width, button_height = get_previous_widget_info(gui)\n\n        local option_width = button_width\n        local option_height = button_height\n        if(option.override) then\n            if(option.type == \"number\") then\n                local old_value = option.value\n                GuiColorSetForNextWidget(gui,1,1,1,0)\n\n                local slider_width = 200\n                local slider_height = 12\n\n                local slider_value   = option.log_scale and math.log(option.value+1)   or option.value\n                local slider_min     = option.log_scale and math.log(option.min+1)     or option.min\n                local slider_max     = option.log_scale and math.log(option.max*1.01+1)     or option.max\n                local slider_default = option.log_scale and math.log(option.default+1) or option.default\n                option.value = GuiSlider(gui, get_id(\"config_slider_\"..option.id), x+12, y+button_height, \"\",\n                                         slider_value, slider_min, slider_max, slider_default, option.display_multiplier or 1,\n                                         \" \", slider_width)\n                get_previous_widget_info(gui)\n                if(option.log_scale) then\n                    option.value = math.exp(option.value)-1\n                end\n                if(option.integer) then\n                    option.value = math.floor(option.value)\n                end\n\n                if(option.value ~= old_value) then\n                    option_changed = true\n                end\n\n                option_width = math.max(option_width, slider_width)\n                option_height = option_height+slider_height\n            elseif(option.type == \"text_number\") then\n                local old_value = option.value\n                local textbox_id = get_id(\"config_text_number_box_\"..option.id)\n                if(gui_selected == textbox_id) then\n                    -- GamePrint(\"text box \"..textbox_id..\" is selected\")\n                    textbox_id = \"\"\n                end\n                option.value = tonumber(GuiTextInput(gui, textbox_id, x+button_width, y,\n                                                     string.format(\"%d\", option.value), 60, 9, \"0123456789\")) or 0\n                local clicked, right_clicked, hovered, textbox_x, textbox_y, textbox_width, textbox_height = get_previous_widget_info(gui)\n                if(clicked) then\n                    -- GamePrint(\"text box \"..textbox_id..\" is clicked\")\n                    gui_selected = textbox_id\n                    new_gui_selected = textbox_id\n                end\n\n                if(option.integer) then\n                    option.value = math.floor(option.value)\n                end\n\n                if(option.value ~= old_value) then\n                    option_changed = true\n                end\n\n                option_width = option_width+textbox_width\n                option_height = math.max(option_height, textbox_height)\n            end\n        end\n        y = y+option_height\n        extend_max_bound(option_width, y)\n\n        if(clicked) then\n            if(option.type==\"boolean\") then\n                if(option.override) then\n                    if(option.value) then\n                        option.override = nil\n                        option.value = false\n                    else\n                        option.value = true\n                    end\n                else\n                    option.override = true\n                    option.value = false\n                end\n            else\n                option.override = not option.override\n            end\n            option_changed = true\n        end\n\n        if(option_changed) then\n            wand_changed = true\n            option.needs_saving = true\n        end\n\n        if(option.needs_saving and GameGetFrameNum()%60==0) then\n            ModSettingSet(mod_name..\".\"..option.id..\"_override\", option.override==true)\n            ModSettingSet(mod_name..\".\"..option.id..\"_value\", option.value)\n            option.needs_saving = false\n        end\n\n        config[option.id] = option.override and option.value\n    end\nend\n\nfunction get_deck(deck_name)\n    if(deck_name == \"discarded\") then\n        return discarded\n    elseif(deck_name == \"hand\") then\n        return hand\n    elseif(deck_name == \"deck\") then\n        return deck\n    end\nend\n\nfunction get_action_stack(node)\n    local action_stack = {}\n    while(node ~= nil and node.action ~= nil) do\n        table.insert(action_stack, 1, node)\n        node = node.parent\n    end\n    return action_stack\nend\n\nfunction set_history(current_i_target)\n    if(current_i_target == current_i+1) then\n        step_history()\n        return\n    end\n\n    reset_cast_except_action_sprites()\n\n    if(current_i_target <= 1) then\n        for i = 1, #action_sprites do\n            pop_action(10)\n        end\n        return\n    end\n\n    e = cast_history[current_i_target-1]\n\n    local node = e.node\n    local action_stack = get_action_stack(node)\n\n    local deletion_start = 1\n    --TODO: this is slightly incorrect if an action is poped, and pushed back between\n    --      the current state and the new target one, but not a huge deal for now\n    for i, a in ipairs(action_sprites) do\n        if(i <= #action_stack and action_stack[i].action == a.node.action) then\n            deletion_start = i+1 --this way it can reach beyond #action_sprites\n        else\n            break\n        end\n    end\n\n    for i = deletion_start, #action_sprites do\n        pop_action(10)\n    end\n\n    for i=deletion_start, #action_stack do\n        local action_sprite = push_action(action_stack[i])\n    end\n\n    clear_card_sprites(true)\n    step_history(current_i_target-current_i, true, true)\nend\n\nfunction step_history(steps, no_instant_step, skip_actions)\n    if(steps == nil) then steps = 1 end\n    local start_i = current_i\n    while current_i < start_i+steps do\n        if(current_i > #cast_history or current_i <= 0) then break end\n        local e = cast_history[current_i]\n        -- GamePrint(\"event: \"..e.type)\n        if(not skip_actions and e.type == \"action\") then\n            local card = e.node.action.debug_card\n            if(card ~= nil) then\n                card.dscale = card.dscale+0.5\n                card.dy = card.dy-10.0\n            end\n\n            local action_sprite = push_action(e.node)\n\n            -- Speed up playback for divide by's\n            local iteration = e.info.iteration or 0\n            playback_wait = math.ceil(20*math.pow(2, -0.5*iteration))\n            -- playback_wait = math.ceil(15*math.pow(2, -0.5*iteration))\n            -- if(iteration >= 2) then\n            --     playback_wait = 1\n            -- end\n        elseif(not skip_actions and e.type == \"action_end\") then\n            pop_action(10)\n            playback_wait = 10\n        elseif(e.type == \"new_cast_state\") then\n            if(current_cast_states[e.info.c_old_final] == nil) then\n                current_cast_states[e.info.c_old_final] = {c = e.info.c_old_final, current = e.info.c_old, children = {}}\n            else\n                current_cast_states[e.info.c_old_final].current = e.info.c_old\n            end\n            table.insert(current_cast_states[e.info.c_old_final].children, e.c_final)\n            if(not no_instant_step) then steps = steps+1 end\n        elseif(e.type == \"card_move\") then\n            local source = get_deck(e.info.source)\n            local dest = get_deck(e.info.dest)\n            local item = source[e.info.index]\n            table.remove(source, e.info.index)\n            table.insert(dest, item)\n            playback_wait = 5\n        elseif(e.type == \"add_ac_card\") then\n            local dest = get_deck(e.info.dest)\n            local action = e.node.action\n            local card = make_debug_card(action)\n            card.sprite = add_sprite(card, true)\n            table.insert(dest, card)\n            playback_wait = 5\n        elseif(e.type == \"delete_ac_card\") then\n            local source = get_deck(e.info.source)\n            local sprite = source[e.info.index]\n            if(sprite) then\n                sprite = sprite.sprite\n                table.remove(source, e.info.index)\n                --TODO: fade this out\n                EntityKill(sprite)\n            end\n            playback_wait = 5\n        elseif(e.type == \"order_deck\") then\n            local sorted_deck = {}\n            for i, j in ipairs(e.info.order) do\n                sorted_deck[i] = deck[j]\n            end\n            deck = sorted_deck\n            playback_wait = 5\n        -- elseif(e.type == \"register_action\") then\n        -- elseif(e.type == \"cast_done\") then\n        --     update_reload_times(e.c)\n        --     -- -- table.sort(deck, function(a,b) return e.info.order[a.deck_index] < e.info.order[b.deck_index] end)\n        --     -- playing = false\n        else\n            if(not no_instant_step) then steps = steps+1 end\n        end\n        if(current_cast_states[e.c_final] == nil) then\n            current_cast_states[e.c_final] = {c=e.c_final, children = {}}\n        end\n        current_cast_states[e.c_final].current = e.c\n        current_i = current_i + 1\n    end\nend\n\nfunction reset_cast()\n    clear_action_sprites()\n    clear_card_sprites(true)\n    reset_cast_except_action_sprites()\nend\n\nfunction reset_cast_except_action_sprites()\n    current_i = 1\n\n    discarded = {}\n    hand = {}\n    deck = {}\n\n    current_cast_states = {}\n\n    if(start_deck ~= nil) then\n        for i, card in ipairs(start_deck) do\n            table.insert(deck, card)\n        end\n    end\nend\n\nfunction OnWorldPostUpdate()\n    -- GamePrint(\"memory: \"..gcinfo())\n\n    -- we wait to initialize these for compatibility with mods (*cough* Goki's things *cough*)\n    -- that wait until OnModPostInit to append some stuff to gun_actions.lua\n    if(not debug_wand) then\n        action_table, projectile_table, projectile_list, extra_entity_table = SPELL_INFO.get_spell_info()\n        debug_wand = init_debugger()\n    end\n\n    player = EntityGetWithTag( \"player_unit\" )[1];\n    local held_wand\n    local m1\n    local px, py\n    local player_hp = 4\n    local player_max_hp = 4\n    local player_damage_multipliers = { curse       = 1,\n                                        drill       = 1,\n                                        electricity = 1,\n                                        explosion   = 0.35,\n                                        fire        = 1,\n                                        healing     = 1,\n                                        ice         = 1,\n                                        melee       = 1,\n                                        overeating  = 1,\n                                        physics_hit = 1,\n                                        poison      = 1,\n                                        projectile  = 1,\n                                        radioactive = 1,\n                                        slice       = 1 }\n    local player_n_stainless = 0\n    local player_has_ambrosia = false\n    local player_has_unlimited_spells = false\n    if(player ~= nil) then\n        local inventory = EntityGetFirstComponent(player, \"Inventory2Component\")\n        local active_item = ComponentGetValue2( inventory, \"mActiveItem\" )\n\n        if(active_item ~= nil) and EntityHasTag(active_item, \"wand\") then\n            held_wand = active_item\n        end\n\n        px, py = EntityGetTransform(player)\n\n        local comp = EntityGetFirstComponent(player, \"DamageModelComponent\")\n        if(comp ~= nil) then\n            player_hp = ComponentGetValue2(comp, \"hp\")\n            player_max_hp = ComponentGetValue2(comp, \"max_hp\")\n            local damage_multipliers_object = ComponentObjectGetMembers(comp, \"damage_multipliers\")\n            for type, multiplier in pairs(damage_multipliers_object) do\n                player_damage_multipliers[type] = tonumber(multiplier)\n            end\n        end\n\n        local player_children = EntityGetAllChildren(player)\n        for c, child in ipairs(player_children) do\n            local game_effects = EntityGetComponent(child, \"GameEffectComponent\")\n            if(game_effects ~= nil) then\n                for i, e in ipairs(game_effects) do\n                    if(ComponentGetValue2(e, \"effect\") == \"STAINLESS_ARMOUR\") then\n                        player_n_stainless = player_n_stainless + 1\n                    end\n\n                    if(ComponentGetValue2(e, \"effect\") == \"PROTECTION_ALL\") then\n                        player_has_ambrosia = true\n                    end\n                end\n            end\n        end\n\n        local world_entity_id = GameGetWorldStateEntity()\n        if( world_entity_id ~= nil ) then\n            local comp_worldstate = EntityGetFirstComponent( world_entity_id, \"WorldStateComponent\" )\n            if( comp_worldstate ~= nil ) then\n                player_has_unlimited_spells = ComponentGetValue2(comp_worldstate, \"perk_infinite_spells\")\n            end\n        end\n        -- local controls_component = EntityGetFirstComponent(player, \"ControlsComponent\")\n        -- m1 = ComponentGetValue2(controls_component, \"mButtonDownLeftClick\") or false\n    end\n\n    GuiStartFrame(gui)\n    GuiOptionsAdd(gui, GUI_OPTION.NoPositionTween);\n    global_interactive = not GameGetIsGamepadConnected()\n    set_interactive(gui, true)\n    start_gui(gui)\n\n    mx, my = DEBUG_GetMouseWorld()\n\n    local cx, cy, cw, ch = GameGetCameraBounds()\n    cx, cy = GameGetCameraPos()\n    cw = cw - 4\n    -- ch = ch - 2\n    local cx = cx-cw/2\n    local cy = cy-ch/2\n\n    gw, gh = GuiGetScreenDimensions(gui)\n    bound_x_min = 0\n    bound_y_min = 0\n    bound_x_max = gw\n    bound_y_max = gh\n    -- GamePrint(\"screen dimensions: (\"..gw..\", \"..gh..\")\")\n    -- GamePrint(\"camera dimensions: (\"..cw..\", \"..ch..\")\")\n\n    mx = (mx-cx)*gw/cw+1.0\n    my = (my-cy)*gw/cw-1.5\n\n    -- local dot_sprite = base_dir .. \"files/ui_gfx/line_dot_white.png\"\n    -- GuiImage(gui, get_id(), mx, my, dot_sprite,\n    --          1.0, 1, 0, 0)\n\n    local open_pressed = GuiImageButton(gui, get_id(\"icon\"), gw-16, gh-16, \"\", base_dir..\"files/ui_gfx/icon.png\")\n    local open_tooltip = \"Show Wand DBG\"\n    if(show_wand_dbg) then\n        open_tooltip = \"Hide Wand DBG\"\n    end\n    GuiTooltip(gui, open_tooltip, \"\")\n    if(open_pressed) then\n        show_wand_dbg = not show_wand_dbg\n        ModSettingSet(mod_name..\".show\", show_wand_dbg)\n        wand_changed = true\n    end\n    if(not show_wand_dbg) then\n        clear_card_sprites()\n        reset_cast()\n        return\n    end\n\n    local open_animation_pressed = GuiImageButton(gui, get_id(\"animation_show_hide_button\"), gw-16-32, gh-16, \"\", base_dir..\"files/ui_gfx/animation_icon.png\")\n    local open_animation_tooltip = \"Show Deck Animation\"\n    if(show_animation) then\n        open_animation_tooltip = \"Hide Deck Animation\"\n    end\n    GuiTooltip(gui, open_animation_tooltip, \"\")\n    if(open_animation_pressed) then\n        show_animation = not show_animation\n        ModSettingSet(mod_name..\".show_animation\", show_animation)\n    end\n\n    -- local open_tree_pressed = GuiImageButton(gui, get_id(\"tree_icon\"), gw-16-32, gh-16, \"\", base_dir..\"files/ui_gfx/tree_icon.png\")\n    -- local open_tree_tooltip = \"Show Flowchart\"\n    -- if(tree_window.show) then\n    --     open_tree_tooltip = \"Hide Flowchart\"\n    -- end\n    -- GuiTooltip(gui, open_tree_tooltip, \"\")\n    -- if(open_tree_pressed) then\n    --     tree_window.show = not tree_window.show\n    --     top_window = tree_window.index\n    -- end\n\n    do_window_show_hide_button(gui, tree_window, gw-16-64, gh-16, base_dir..\"files/ui_gfx/tree_icon.png\")\n    do_window_show_hide_button(gui, cast_state_window, gw-16-48, gh-16, base_dir..\"files/ui_gfx/cast_state_icon.png\")\n    do_window_show_hide_button(gui, config_window, gw-16-16, gh-16, base_dir..\"files/ui_gfx/config_icon.png\")\n\n    local reset_windows_pressed = GuiImageButton(gui, get_id(\"reset_windows_button\"), gw-16-80, gh-16, \"\", base_dir..\"files/ui_gfx/reset_windows_icon.png\")\n    GuiTooltip(gui, \"Reset Window Layout\", \"\")\n    if(reset_windows_pressed) then\n        reset_windows()\n    end\n\n    local wand_deck = {}\n    local n_always_casts = 0\n    if(player == nil or held_wand == nil) then\n        need_to_remake_cards = true\n        reset_cast()\n        clear_card_sprites()\n    else\n        local spells = EntityGetAllChildren(held_wand) or {}\n        local ability_component = EntityGetFirstComponentIncludingDisabled(held_wand, \"AbilityComponent\")\n        local deck_capacity = ComponentObjectGetValue(ability_component, \"gun_config\", \"deck_capacity\")\n        local deck_capacity2 = EntityGetWandCapacity(held_wand)\n        n_always_casts = deck_capacity - deck_capacity2\n\n        local wand_stats = {gun_config = {}, gunaction_config = {}, n_always_casts = n_always_casts}\n\n        wand_stats.mana_max = ComponentGetValue2(ability_component, \"mana_max\")\n        for i,option in ipairs(options) do\n            if(option.id == \"mana\") then\n                option.max = wand_stats.mana_max\n                option.default = wand_stats.mana_max\n            elseif(option.id == \"hp\") then\n                option.max = config.max_hp or player_max_hp\n                option.value = math.min(option.value, option.max)\n                break\n            end\n        end\n\n        if(last_wand_stats == nil or wand_stats.mana_max ~= last_wand_stats.mana_max) then\n            wand_changed = true\n        end\n\n        ConfigGun_Init(wand_stats.gun_config)\n        local gun_config_members = ComponentObjectGetMembers(ability_component, \"gun_config\")\n        -- GamePrint(\"gun_config:\")\n        for member, value in pairs(gun_config_members) do\n            -- GamePrint(member..\" = \"..value)\n            if(type(wand_stats.gun_config[member]) == \"string\") then\n                wand_stats.gun_config[member] = value\n            elseif(type(wand_stats.gun_config[member]) == \"number\") then\n                wand_stats.gun_config[member] = tonumber(value)\n            elseif(type(wand_stats.gun_config[member]) == \"boolean\") then\n                wand_stats.gun_config[member] = (value==\"1\")\n            end\n\n            if(last_wand_stats == nil or wand_stats.gun_config[member] ~= last_wand_stats.gun_config[member]) then\n                wand_changed = true\n            end\n        end\n\n        ConfigGunActionInfo_Init(wand_stats.gunaction_config)\n        local gunaction_config_members = ComponentObjectGetMembers(ability_component, \"gunaction_config\")\n        for member, value in pairs(gunaction_config_members) do\n            if(type(wand_stats.gunaction_config[member]) == \"string\") then\n                wand_stats.gunaction_config[member] = value\n            elseif(type(wand_stats.gunaction_config[member]) == \"number\") then\n                wand_stats.gunaction_config[member] = tonumber(value)\n            elseif(type(wand_stats.gunaction_config[member]) == \"boolean\") then\n                wand_stats.gunaction_config[member] = (value==\"1\")\n            end\n\n            if(last_wand_stats == nil or wand_stats.gunaction_config[member] ~= last_wand_stats.gunaction_config[member]) then\n                wand_changed = true\n            end\n        end\n\n        for i,s in ipairs(spells) do\n            local comp = EntityGetFirstComponentIncludingDisabled(s, \"ItemActionComponent\")\n            local item_comp = EntityGetFirstComponentIncludingDisabled(s, \"ItemComponent\")\n            if (comp ~= nil and item_comp ~= nil) then\n                local action_id = ComponentGetValue2( comp, \"action_id\" )\n                local is_always_cast = ComponentGetValue2(item_comp, \"permanently_attached\")\n                local uses_remaining = ComponentGetValue2(item_comp, \"uses_remaining\")\n\n                table.insert(wand_deck, {id = action_id, is_always_cast = is_always_cast, uses_remaining = uses_remaining})\n            end\n        end\n        if(last_wand_deck == nil or #wand_deck ~= #last_wand_deck) then\n            wand_changed = true\n        else\n            for i,a in ipairs(wand_deck) do\n                local b = last_wand_deck[i]\n                if(a.id ~= b.id or a.is_always_cast ~= b.is_always_cast or a.uses_remaining ~= b.uses_remaining) then\n                    wand_changed = true\n                    break\n                end\n            end\n        end\n        last_wand_deck = wand_deck\n        last_wand_stats = wand_stats\n        if(wand_changed) then\n            need_to_remake_cards = true\n            wand_changed = false\n            -- GamePrint(\"wand changed\")\n\n            wand_stats.mana = config.mana or ComponentGetValue2(ability_component, \"mana\")\n            wand_stats.maximize_uses = config.maximize_uses\n            wand_stats.unlimited_spells = config.unlimited_spells==nil and player_has_unlimited_spells or config.unlimited_spells\n            wand_stats.n_enemies = config.n_enemies or #(EntityGetInRadiusWithTag(px, py, 240, \"homing_target\"))\n            wand_stats.n_projectiles = config.n_projectiles or #(EntityGetInRadiusWithTag(px, py, 160, \"projectile\"))\n            wand_stats.n_omega_black_holes = config.n_omega_black_holes or #(EntityGetWithTag(px, py, 160, \"black_hole_giga\"))\n            wand_stats.hp = config.hp or player_hp\n            wand_stats.max_hp = config.max_hp or player_max_hp\n            wand_stats.every_other_state = config.every_other_state\n            wand_stats.money = config.money or 0\n            wand_stats.damage_multipliers = config.damage_multipliers or player_damage_multipliers\n            wand_stats.n_stainless = config.n_stainless and config.n_stainless or player_n_stainless\n            wand_stats.ambrosia = config.ambrosia==nil and player_has_ambrosia or config.ambrosia\n            -- wand_stats.zeta_options = string.gmatch(config.zeta_options, \"[^,]\")\n            wand_stats.zeta_options = nil\n            wand_stats.frame_number = config.frame_number\n\n            if(not wand_stats.zeta_options) then\n                wand_stats.zeta_options = {}\n                local children = EntityGetAllChildren( player)\n                local inventory = EntityGetFirstComponent( player, \"Inventory2Component\" )\n\n                if ( children ~= nil ) and ( inventory ~= nil ) then\n                    local active_wand = ComponentGetValue2( inventory, \"mActiveItem\" )\n\n                    for i,child_id in ipairs( children ) do\n                        if ( EntityGetName( child_id ) == \"inventory_quick\" ) then\n                            local wands = EntityGetAllChildren( child_id )\n\n                            if ( wands ~= nil ) then\n                                for k,wand_id in ipairs( wands ) do\n                                    if ( wand_id ~= active_wand ) and EntityHasTag( wand_id, \"wand\" ) then\n                                        local spells = EntityGetAllChildren( wand_id )\n\n                                        if ( spells ~= nil ) then\n                                            for j,spell_id in ipairs( spells ) do\n                                                local comp = EntityGetFirstComponentIncludingDisabled( spell_id, \"ItemActionComponent\" )\n\n                                                if ( comp ~= nil ) then\n                                                    local action_id = ComponentGetValue2( comp, \"action_id\" )\n                                                    table.insert( wand_stats.zeta_options, action_id )\n                                                end\n                                            end\n                                        end\n                                    end\n                                end\n                            end\n                        end\n                    end\n                end\n            end\n\n            local start_deck_actions\n            cast_history, action_trees, start_deck_actions, always_casts = debug_wand(wand_deck, wand_stats)\n            for i, t in ipairs(action_trees) do\n                process_node(t)\n            end\n\n            final_cast_states = {}\n            for i, e in ipairs(cast_history) do\n                if(e.type == \"new_cast_state\") then\n                    if(final_cast_states[e.info.c_old_final] == nil) then\n                        final_cast_states[e.info.c_old_final] = {c = e.info.c_old_final, current = e.info.c_old_final, children = {}}\n                    end\n                    table.insert(final_cast_states[e.info.c_old_final].children, e.c_final)\n                end\n                if(final_cast_states[e.c_final] == nil) then\n                    final_cast_states[e.c_final] = {c=e.c_final, current=e.c_final, children = {}}\n                end\n            end\n\n            always_cast_cards = {}\n            start_deck = {}\n            cast_state_collapsed = {}\n            -- if(cast_history ~= nil) then GamePrint(\"#cast_history = \" .. #cast_history) end\n            for i, action in ipairs(start_deck_actions) do\n                table.insert(start_deck, make_debug_card(action))\n            end\n\n            reset_cast()\n            current_i_target = nil\n        end\n        if(cast_history ~= nil and start_deck ~= nil) then\n            if(show_animation) then\n                if(need_to_remake_cards) then\n                    current_i_target = current_i\n                    reset_cast()\n                    clear_card_sprites()\n                    for i, card in ipairs(start_deck) do\n                        card.sprite = add_sprite(card)\n                    end\n                end\n            end\n\n            if(show_animation or cast_state_window.show) then\n                if(current_i_target == nil) then\n                    current_i_target = current_i\n                end\n                if(current_i_target ~= current_i) then\n                    set_history(current_i_target)\n                end\n                if(current_i > #cast_history) then\n                    reset_cast()\n                end\n\n                current_i_target = nil\n            end\n\n            if(show_animation) then\n                if(cast_history ~= nil) then\n                    if(current_i > #cast_history or current_i < 1) then current_i = 1 end\n                    -- discarded = cast_history[current_i].discarded\n                    -- hand = cast_history[current_i].hand\n                    -- deck = cast_history[current_i].deck\n\n                    local base_x = 32\n                    local base_y = gh*0.9\n                    local label_y = gh*0.78\n\n                    GameCreateSpriteForXFrames(base_dir..\"files/ui_gfx/discarded.png\", cx+cw/gw*base_x, cy+cw/gw*label_y,\n                                               false, 0, 0, 1, true)\n                    -- GuiText(gui, base_x, base_y-40,'discarded:')\n                    draw_deck(base_x, base_y, cx, cy, cw/gw, discarded, \"right\")\n                    base_x = base_x+16*13\n\n                    GameCreateSpriteForXFrames(base_dir..\"files/ui_gfx/hand.png\", cx+cw/gw*base_x, cy+cw/gw*label_y,\n                                               false, 0, 0, 1, true)\n                    -- GuiText(gui, base_x, base_y-40,'hand:')\n                    draw_deck(base_x, base_y, cx, cy, cw/gw, hand, \"middle\")\n                    base_x = base_x+16*13\n\n                    GameCreateSpriteForXFrames(base_dir..\"files/ui_gfx/deck.png\", cx+cw/gw*base_x, cy+cw/gw*label_y,\n                                               false, 0, 0, 1, true)\n                    -- GuiText(gui, base_x, base_y-40,'deck:')\n                    draw_deck(base_x, base_y, cx, cy, cw/gw, deck, \"left\")\n                end\n\n                if(action_sprites ~= nil) then\n                    for i = #action_sprites,1,-1 do\n                        a = action_sprites[i]\n                        a.x_target = 10+32*i\n                        a.y_target = gh*0.73\n\n                        local node = a.node\n                        if(node.draw_how_many == nil) then\n                            a.line1 = \"\"\n                            a.line2 = \"\"\n                        elseif(node.dont_draw_actions == -1) then\n                            a.line1 = \"can't draw\"\n                            a.line2 = \"\"\n                        elseif(node.playing_permanent_card and node.draw_how_many <= 1) then\n                            a.line1 = \"can't draw 1\"\n                            a.line2 = \"in always cast\"\n                        elseif(node.draw_how_many >= 1) then\n                            a.line1 = \"draw\"\n                            if(a.line2 == \"\") then\n                                a.line2 = \"0/\"..node.draw_how_many\n                            end\n                        end\n\n                        if(node.draw_step ~= nil and i > 1) then\n                            --technically draw_total and draw_how_many are slightly redundent,\n                            --but could theoretically support wierd spells later on more easily\n                            action_sprites[i-1].line2 = node.draw_step..\"/\"..node.draw_total\n                        end\n\n                        animate_card(a, a.sprite, cx, cy, cw/gw)\n                    end\n                end\n\n                for i=#dying_action_sprites,1,-1 do\n                    local alive = animate_dying_card(dying_action_sprites[i], dying_action_sprites[i].sprite, cx, cy, cw/gw)\n                    if(not alive) then\n                        table.remove(dying_action_sprites, i)\n                    end\n                end\n\n                if(not looping and current_i == #cast_history) then\n                    playing = false\n                end\n                if(playing) then\n                    playback_timer = playback_timer-1\n                else\n                    playback_timer = 1\n                end\n                if(playback_timer <= 0) then\n                    step_history(1)\n                    playback_timer = playback_wait\n                end\n\n                need_to_remake_cards = false\n            else\n                if(not need_to_remake_cards) then\n                    clear_card_sprites()\n                    clear_action_sprites()\n                    need_to_remake_cards = true\n                end\n            end\n\n            tree_window.func = function(window)\n                draw_trees(-window.x_scroll, 0)\n            end\n\n            cast_state_window.func = function(window)\n                root_cast_states = {}\n                for i, t in ipairs(action_trees) do\n                    table.insert(root_cast_states, t.c)\n                end\n\n                local x = -window.x_scroll\n                local y = 0\n\n                if(use_final_cast_state) then\n                    cast_states = final_cast_states\n                else\n                    cast_states = current_cast_states\n                end\n\n                local text = use_final_cast_state and \"Showing final shot state (click to toggle)\" or \"Showing current shot state (click to toggle)\"\n                local clicked, righ_clicked = GuiButton(gui, get_id(\"final_cast_state_button\"), x, y, text)\n                local _, __, hovered, text_x, text_y, text_width, text_height = get_previous_widget_info(gui)\n                y = y+text_height+4\n                if(clicked) then\n                    use_final_cast_state = not use_final_cast_state\n                    ModSettingSet(mod_name..\".use_final_cast_state\", use_final_cast_state)\n                end\n\n                draw_cast_states(root_cast_states, -window.x_scroll, y)\n            end\n\n            config_window.func = function(window)\n                draw_config(-window.x_scroll, 0, window.x, window.y)\n            end\n\n            if(config.show_with_inventory or not GameIsInventoryOpen()) then\n                draw_windows(gui)\n            end\n\n            if(show_animation) then\n                current_i_target = draw_playback(10, gh*0.9+5, gw-20, mx, my)\n                if(window_active) then\n                    gui_selected = new_gui_selected\n                    new_gui_selected = nil\n                end\n            end\n        end\n    end\nend\n"
