_TWWE_VFS["mods/wand_editor/compatibility.xml"] = "<Mod _format_version=\"0\" version_built_with=\"12\" >\n\n</Mod>\n\n"
_TWWE_VFS["mods/wand_editor/files/append/gun.lua"] = "local __wand_editor_register_action = register_action\n\nfunction register_action( state )--无后坐力实现\n    if not reflecting then\n        if ModSettingGet(\"wand_editor\"..\"NoRecoil\") then shot_effects.recoil_knockback = 0; end\n    end\n    __wand_editor_register_action( state )\n    return state\nend\n\nlocal __wand_editor_draw_shot = draw_shot\n\nfunction draw_shot(...)--禁用施法\n    if ModSettingGet(\"wand_editor\" .. \"DisableProj\") then\n        return\n    end\n	return __wand_editor_draw_shot(...)\nend\n\nlocal __wand_editor__play_permanent_card = _play_permanent_card\n\nfunction _play_permanent_card(...)--禁用施法\n    if ModSettingGet(\"wand_editor\" .. \"DisableProj\") then\n		gun.reload_time = 0\n        return\n    end\n	return __wand_editor__play_permanent_card(...)\nend\n\nlocal __wand_editor_StartReload= StartReload\n\nfunction StartReload(...)\n    if ModSettingGet(\"wand_editor\" .. \"DisableProj\") then\n        return\n    end\n	return __wand_editor_StartReload(...)\nend\n\n\nlocal __wand_editor_draw_action = draw_action\n\nfunction draw_action(...)\n	local __wand_editor_Enable = ModSettingGet(\"wand_editor\" .. \"SpellInfMana\")\n	local __wand_editor_LastMana\n    if __wand_editor_Enable then\n        if #deck > 0 then\n            deck[1].mana = 0\n        end\n		__wand_editor_LastMana = mana\n    end\n    local result = {__wand_editor_draw_action(...)}\n	if Enable then\n		mana = LastMana\n	end\n	return unpack(result)\nend\n"
_TWWE_VFS["mods/wand_editor/files/append/gun_actions.lua"] = "for _,v in pairs(actions or {})do\n	v.max_uses = nil\nend\n"
_TWWE_VFS["mods/wand_editor/files/biome_impl/wand_lab/overwrite.lua"] = "local entity = GetUpdatedEntityID();\nlocal x, y = EntityGetTransform( entity );\nEntityLoad( \"mods/wand_editor/files/entity/dummy_target.xml\", x - 100, y );\nEntityLoad( \"mods/wand_editor/files/entity/dummy_target.xml\", x + 100, y );\nif EntityGetWithName(\"WandEditorSpellLabVisualizer\") == 0 then\n	local id = EntityLoad(\"data/entities/buildings/workshop_spell_visualizer.xml\", x - 78, y - 50);\n	EntitySetName(id,\"WandEditorSpellLabVisualizer\")\nend\n"
