_TWWE_VFS["mods/wand_editor/files/gui/GetSpellData.lua"] = "dofile_once(\"mods/wand_editor/files/libs/fn.lua\")\ndofile_once(\"mods/wand_editor/files/libs/unsafe.lua\")\ndofile_once(\"data/scripts/gun/gun.lua\")\n\n---输入类型枚举量获得其对应的字符串\n---@param type integer\n---@return string\nfunction SpellTypeEnumToStr(type)\n	local TypeTable = {\n		[ACTION_TYPE_PROJECTILE] = GameTextGetTranslatedOrNot(\"$inventory_actiontype_projectile\"),\n		[ACTION_TYPE_STATIC_PROJECTILE] = GameTextGetTranslatedOrNot(\"$inventory_actiontype_staticprojectile\"),\n		[ACTION_TYPE_MODIFIER] = GameTextGetTranslatedOrNot(\"$inventory_actiontype_modifier\"),\n		[ACTION_TYPE_DRAW_MANY] = GameTextGetTranslatedOrNot(\"$inventory_actiontype_drawmany\"),\n		[ACTION_TYPE_MATERIAL] = GameTextGetTranslatedOrNot(\"$inventory_actiontype_material\"),\n		[ACTION_TYPE_OTHER] = GameTextGetTranslatedOrNot(\"$inventory_actiontype_other\"),\n		[ACTION_TYPE_UTILITY] = GameTextGetTranslatedOrNot(\"$inventory_actiontype_utility\"),\n		[ACTION_TYPE_PASSIVE] = GameTextGetTranslatedOrNot(\"$inventory_actiontype_passive\")\n	}\n    local result = TypeTable[type]\n	if result ~= nil then\n		return result\n	end\n	return \"unknown\"\nend\n\n---返回模组加载情况\n---@return table<string, boolean>\nlocal function GetModEnableList()\n	local temp = ModGetActiveModIDs()\n	local ModIdToEnable = {}\n    for _, v in pairs(temp) do\n		ModIdToEnable[v] = true\n    end\n	return ModIdToEnable\nend\nlocal mustReload = false\nlocal LastRealUnlimitedSpells = ModSettingGet(ModID .. \"Last_real_unlimited_spells\") or false\nlocal RealUnlimitedSpells = ModSettingGet(\"wand_editor.real_unlimited_spells\") or false\nlocal RefreshRealUnlimitedSpells = false\nif LastRealUnlimitedSpells ~= RealUnlimitedSpells then\n    ModSettingSet(ModID .. \"Last_real_unlimited_spells\", RealUnlimitedSpells)\n    mustReload = true\n	RefreshRealUnlimitedSpells = true\nend\nif not ModSettingGet(\"wand_editor.cache_spell_data\") then\n    mustReload = true\nend\nif not mustReload then\n	if ModSettingGet(ModID..\"VerHash\") == nil then--如果为空就尝试进行初始化\n		local hashPath = Cpp.CurrentPath()..\"/_version_hash.txt\"\n		if Cpp.PathExists(hashPath) then\n			ModSettingSet(ModID .. \"VerHash\", ReadFileAll(hashPath))\n		end\n	else\n		local hashPath = Cpp.CurrentPath()..\"/_version_hash.txt\"\n		if Cpp.PathExists(hashPath) then--如果发现有的话就读取\n			local newHash = ReadFileAll(hashPath)\n			if newHash ~= ModSettingGet(ModID..\"VerHash\") then--不一致就设置新的\n				ModSettingSet(ModID .. \"VerHash\", ReadFileAll(hashPath))\n				mustReload = true --并且要刷新\n			end\n		end\n	end\nend \n\nif ModSettingGet(ModID..\"ReloadSpellData\") then\n    mustReload = true\n	ModSettingSet(ModID..\"ReloadSpellData\", false)\nend\n\n--判断是否有缓存文件\nlocal cachePath = Cpp.CurrentPath() .. \"/mods/wand_editor/cache/\"\nlocal HasCahce = Cpp.PathExists(cachePath..\"SpellsData.lua\") and Cpp.PathExists(cachePath..\"ModEnable.lua\") and Cpp.PathExists(cachePath..\"TypeToSpellList.lua\")\n\n--检查是否需要更新缓存\nlocal ModIdToEnable = GetModEnableList()\nif HasCahce and (not mustReload) then\n    local UpModEnable = dofile_once(\"mods/wand_editor/cache/ModEnable.lua\")\n	local Change = false\n    for k, v in pairs(UpModEnable) do\n        if ModIdToEnable[k] == nil then --代表有变动\n            Change = true\n            break\n        end\n    end\n	if not Change then\n		for k, v in pairs(ModIdToEnable) do\n			if UpModEnable[k] == nil then --代表有变动\n				Change = true\n				break\n			end\n		end\n	end\n	if not Change then--可以直接读取缓存！\n		--print(\"Cache Get\")\n		local result1 = dofile_once(\"mods/wand_editor/cache/SpellsData.lua\")\n        local result2 = dofile_once(\"mods/wand_editor/cache/TypeToSpellList.lua\")\n		return {result1,result2}\n	end\nend\n--print(\"Init Spell Data\")\n--需要重新加载\n\nlocal function GetModId(str)\n	local pos = string.find(str, \"/\")\n    local pos2 = string.find(str, \"/\", pos+1)\n	return string.sub(str,pos+1,pos2-1)\nend\n\nlocal result = {}\nlocal oriLua = Cpp.GetOriginalGunActionsLua()\n\nlocal mod_config_text = ReadFileAll(SavePath .. \"save00/mod_config.xml\")\nlocal __Nxml = dofile_once(\"mods/wand_editor/files/libs/nxml.lua\")\nlocal ModConfig = __Nxml.parse(mod_config_text)\nlocal ModIDToSteamID = {}\nfor _, v in pairs(ModConfig.children) do\n    if v.name == \"Mod\" then\n        ModIDToSteamID[v.attr.name] = v.attr.workshop_item_id\n    end\nend\n\nlocal Appends = ModLuaFileGetAppends(\"data/scripts/gun/gun_actions.lua\")\nlocal AppendsModToFile = {}\nlocal ModIDToName = {}\nlocal SteamPath = Cpp.RegLMGetValue(\"SOFTWARE\\\\WOW6432Node\\\\Valve\\\\Steam\\\\NSIS\", \"Path\")\n\nfor _, v in pairs(Appends or {}) do\n	local modid = GetModId(v)\n	if AppendsModToFile[modid] == nil then\n		AppendsModToFile[modid] = {}\n	end\n    AppendsModToFile[modid][#AppendsModToFile[modid] + 1] = ModTextFileGetContent(v)\n	local ModXml\n	if ModIDToSteamID[modid] == \"0\" then--本地模组\n        ModXml = __Nxml.parse(ReadFileAll(\"mods/\" .. modid .. \"/mod.xml\"))\n    elseif SteamPath then--创意工坊模组\n		ModXml = __Nxml.parse(ReadFileAll(SteamPath ..\"/steamapps/workshop/content/881100/\"..ModIDToSteamID[modid]..\"/mod.xml\"))\n	end\n	if ModXml then\n		ModIDToName[modid] = ModXml.attr.name\n    else\n		ModIDToName[modid] = modid--假设获取失败(SteamPath为空)\n	end\nend\n\nlocal CurrentID = nil\nlocal hasProj = {}\ndraw_actions = function(draw)           --设置抽取数，当被调用时\n	result[CurrentID].draw_actions = draw\nend\nlocal isReaction = false\n\n--监听的数据\ncurrent_reload_time = 0 --充能时间\n\nc = {}\nreset_modifiers(c)                      --初始化\nshot_effects = {}\nConfigGunShotEffects_Init(shot_effects) --初始化\nshot_effects.recoil_knockback = QuietNaN\nlocal isAssign = true\nlocal function ShotListener(key, value)\n	if isReaction then\n		return\n	end\n	if key == \"recoil_knockback\" then\n		if IsNaN(value) then\n            isAssign = false\n			return 0\n		else\n			if isAssign then\n                result[CurrentID].true_recoil = Cpp.ConcatStr(\"=\", tostring(value))\n            else\n				result[CurrentID].true_recoil = NumToWithSignStr(value)\n			end\n		end\n	end\nend\n\n--以下函数只会在程序从C++层面调用gun.lua的时候加载，其他情况下为nil，需要赋值函数来避免空报错\nRegisterGunAction = function()\n\nend\n\nRegisterGunShotEffects = function ()\n	\nend\n\nBeginTriggerTimer = function (timer)\n	result[CurrentID].timerLifeTime = timer\nend\n\nBeginTriggerHitWorld = function ()\n	\nend\n\nBeginTriggerDeath = function ()\n	\nend\n\nEndTrigger = function ()\n	\nend\n\nBeginProjectile = function ()\n	\nend\n\nEndProjectile = function ()\n	\nend\n\nSetProjectileConfigs = function ()\n	\nend\n\nStartReload = function ()\n	\nend\n\nActionUsesRemainingChanged = function ()\n	return true\nend\n\nActionUsed = function ()\n	\nend\n\nLogAction = function ()\n	\nend\n\nOnActionPlayed = function ()\n	\nend\n\nOnNotEnoughManaForAction = function ()\n	\nend\n\nBaabInstruction = function ()\n	\nend\n\nTableListener(shot_effects, ShotListener)\nlocal posX = 14600\nlocal posY = -45804\n\nreflecting = true\nReflection_RegisterProjectile = function(filepath)\n	if not isAssign or filepath == nil or isReaction then\n		return\n	end\n	--获取投射物数据，判断是否有缓存\n    if hasProj[filepath] == nil then\n		local projXML = ParseXmlAndBase(filepath)\n		if projXML == nil then\n			return\n		end\n        local proj = EntityCreateNew()\n        EntitySetTransform(proj, posX, posY)\n        EntityLoadToEntity(filepath, proj)\n		hasProj[filepath] = {}\n		local projComp = EntityGetFirstComponent(proj, \"ProjectileComponent\")\n        if projComp then\n            for _, v in pairs(projXML.children) do\n                if v.name == \"ProjectileComponent\" then\n                    result[CurrentID].lifetime = v.attr.lifetime\n                    hasProj[filepath].lifetime = result[CurrentID].lifetime\n                elseif v.name == \"LifetimeComponent\" then --待完成\n                    local lifetimeLimit = tonumber(v.attr.lifetime)\n                    if result[CurrentID].lifetimeLimit == nil or (result[CurrentID].lifetimeLimit ~= nil and lifetimeLimit <= result[CurrentID].lifetimeLimit) then\n                        result[CurrentID].lifetimeLimit = tonumber(v.attr.lifetime)\n                        hasProj[filepath].lifetimeLimit = result[CurrentID].lifetimeLimit\n                        if v.attr[\"randomize_lifetime.min\"] ~= nil then\n                            result[CurrentID].lifetimeLimitMin = tonumber(v.attr[\"randomize_lifetime.min\"])\n                            hasProj[filepath].lifetimeLimitMin = result[CurrentID].lifetimeLimitMin\n                        end\n                        if v.attr[\"randomize_lifetime.max\"] ~= nil then\n                            result[CurrentID].lifetimeLimitMax = tonumber(v.attr[\"randomize_lifetime.max\"])\n                            hasProj[filepath].lifetimeLimitMax = result[CurrentID].lifetimeLimitMax\n                        end\n                    end\n                elseif v.name == \"MagicXRayComponent\" then --特殊情况\n                    local radius = tonumber(v.attr.radius)\n                    local steps_per_frame = tonumber(v.attr.steps_per_frame)\n                    local lifetimeLimit = math.ceil(radius / steps_per_frame)\n                    if result[CurrentID].lifetimeLimit ~= nil then               --判断是否有数据\n                        if lifetimeLimit <= result[CurrentID].lifetimeLimit then --如果有的话就要判断谁小\n                            result[CurrentID].lifetimeLimit = lifetimeLimit\n                            hasProj[filepath].lifetimeLimit = result[CurrentID].lifetimeLimit\n                            result[CurrentID].lifetimeLimitMin = nil\n                            hasProj[filepath].lifetimeLimitMin = nil\n                            result[CurrentID].lifetimeLimitMax = nil\n                            hasProj[filepath].lifetimeLimitMax = nil\n                        else\n                            result[CurrentID].lifetimeLimit = lifetimeLimit\n                            hasProj[filepath].lifetimeLimit = result[CurrentID].lifetimeLimit\n                        end\n                    else\n                        result[CurrentID].lifetimeLimit = lifetimeLimit\n                        hasProj[filepath].lifetimeLimit = result[CurrentID].lifetimeLimit\n                    end\n                end\n            end\n            result[CurrentID].projComp = {}\n            for k, v in pairs(ComponentGetMembers(projComp)) do --批量加载数据\n                result[CurrentID].projComp[k] = v\n            end\n            hasProj[filepath].projComp = result[CurrentID].projComp\n\n            ComponentSetValue2(projComp, \"on_death_explode\", false)\n            ComponentSetValue2(projComp, \"on_lifetime_out_explode\", false)\n            ComponentSetValue2(projComp, \"collide_with_entities\", false)\n            ComponentSetValue2(projComp, \"collide_with_world\", false)\n\n            --接下来要从object中手动获得值\n            local damage_by_type = ComponentObjectGetMembers(projComp, \"damage_by_type\")\n            if damage_by_type ~= nil then\n                result[CurrentID].projDmg = {}\n                for k, v in pairs(damage_by_type) do\n                    result[CurrentID].projDmg[k] = tonumber(v)\n                end\n\n                hasProj[filepath].projDmg = result[CurrentID].projDmg\n            end\n            local config_explosion = ComponentObjectGetMembers(projComp, \"config_explosion\")\n            if config_explosion ~= nil then\n                result[CurrentID].projExplosion = tonumber(ComponentObjectGetValue2(projComp, \"config_explosion\",\n                    \"damage\"))\n                hasProj[filepath].projExplosion = result[CurrentID].projExplosion\n                result[CurrentID].projExplosionRadius = tonumber(ComponentObjectGetValue2(projComp, \"config_explosion\",\n                    \"explosion_radius\"))\n                hasProj[filepath].projExplosionRadius = result[CurrentID].projExplosionRadius\n            end\n        end\n        for _, v in pairs(EntityGetAllComponents(proj)) do\n            EntityRemoveComponent(proj, v)\n        end\n		EntityAddComponent2(proj, \"LifetimeComponent\", { lifetime = 0 })\n		--杀死实体\n		EntityKill(proj)\n	else\n		--读取缓存\n		for k, v in pairs(hasProj[filepath]) do\n			result[CurrentID][k] = v\n		end\n	end\nend\n\nlocal player = GetPlayer()\nEntityRemoveTag(player, \"player_unit\")\nlocal TypeToSpellListCount = {}\n\nlocal TypeToSpellList = {}\nTypeToSpellList.AllSpells = {}\n\nlocal old_GlobalsSetValue = GlobalsSetValue\nGlobalsSetValue = function ()\n	\nend\n\nfor k, v in pairs(actions or {}) do\n    isReaction = false\n	reflecting = true\n	result[v.id] = {}\n	CurrentID = v.id\n    result[v.id].type = v.type\n    if TypeToSpellList[v.type] == nil then\n        TypeToSpellList[v.type] = {}\n    end\n    if TypeToSpellListCount[v.type] == nil then\n        TypeToSpellListCount[v.type] = 1\n    end--性能优化策略\n    TypeToSpellList[v.type][TypeToSpellListCount[v.type]] = v.id\n	TypeToSpellListCount[v.type] = TypeToSpellListCount[v.type] + 1\n	TypeToSpellList.AllSpells[k] = v.id\n	result[v.id].name = v.name\n	result[v.id].description = v.description\n	result[v.id].sprite = v.sprite\n	result[v.id].mana = v.mana or ACTION_MANA_DRAIN_DEFAULT\n    result[v.id].max_uses = v.max_uses\n    result[v.id].spawn_probability = v.spawn_probability\n    result[v.id].spawn_level = v.spawn_level\n    result[v.id].never_unlimited = v.never_unlimited\n	result[v.id].custom_xml_file = v.custom_xml_file\n	pcall(v.action) --执行\n	result[v.id].reload_time = current_reload_time\n	if result[v.id].c == nil then\n		result[v.id].c = {}\n	end\n	for ckey, cv in pairs(c or {}) do\n		result[v.id].c[ckey] = cv\n	end\n	if result[v.id].shot == nil then\n		result[v.id].shot = {}\n	end\n    if not isAssign then\n        reflecting = false\n        pcall(v.action)\n    else\n        isReaction = true\n        reflecting = false\n        pcall(v.action)\n    end\n    if shot_effects then\n        local flag, t = pcall(shot_effects)\n		if flag then\n			for shotkey, shotv in pairs(t) do\n				result[v.id].shot[shotkey] = shotv\n			end\n        else\n			for shotkey, shotv in pairs(shot_effects) do\n				result[v.id].shot[shotkey] = shotv\n			end\n		end\n	end\n    isAssign = true\n	if c.extra_entities and c.extra_entities ~= \"\" then\n        local extra_entities = split(c.extra_entities, \",\")\n		for _,ExtraEntityPath in pairs(extra_entities) do\n            local ExtraEntity = ParseXmlAndBase(ExtraEntityPath)\n			if ExtraEntity then\n				for _,EEv in pairs(ExtraEntity.children)do\n					if EEv.name == \"LifetimeComponent\" then\n						result[v.id].lifetimeLimit = tonumber(EEv.attr.lifetime)\n						if EEv.attr[\"randomize_lifetime.min\"] ~= nil then\n							result[v.id].lifetimeLimitMin = tonumber(EEv.attr[\"randomize_lifetime.min\"])\n						end\n						if EEv.attr[\"randomize_lifetime.max\"] ~= nil then\n							result[v.id].lifetimeLimitMax = tonumber(EEv.attr[\"randomize_lifetime.max\"])\n						end\n					end\n				end\n			end\n		end\n	end\n	c = {}\n	shot_effects = {}\n	reset_modifiers(c)\n    ConfigGunShotEffects_Init(shot_effects)\n    shot_effects.recoil_knockback = QuietNaN\n	TableListener(shot_effects, ShotListener)\n\n	current_reload_time = 0\nend\nGlobalsSetValue = old_GlobalsSetValue\nlocal function AppendsToString(str, appends)\n	return str..\"\\n\"..appends\nend\n\nloadstring(oriLua)()\n\nfor _,v in pairs(actions)do\n	if result[v.id] then\n        result[v.id].wand_editor_from = \"Noita\"\n		result[v.id].wand_editor_from_id = \"Noita\"\n	end\nend\n\nfor k,v in pairs(AppendsModToFile)do\n    local dpOriLua = oriLua\n    for _, lua in pairs(v) do\n        dpOriLua = AppendsToString(dpOriLua, lua)\n    end\n	loadstring(dpOriLua)()\n	for _,v2 in pairs(actions)do\n		if result[v2.id] and result[v2.id].wand_editor_from == nil then\n            result[v2.id].wand_editor_from = ModIDToName[k]\n			result[v2.id].wand_editor_from_id = k\n		end\n	end\nend\n\nlocal function SaveFile(effil, _ModIdToEnable, _result, _TypeToSpellList)\n	local Cpp = require(\"WandEditorDll\")\n	fastConcatStr = Cpp.ConcatStr\n    local function SerializeTable(_tbl, indent)\n        local tbl = effil.dump(_tbl)\n        indent = indent or \"\"\n        local parts = {}\n        local partsKey = 1\n        local L_SerializeTable = SerializeTable\n\n        local _tostr = tostring\n        local _type = type\n        local is_array = #tbl > 0 or tbl[0] ~= nil\n        for k, v in pairs(tbl) do\n            local key\n            if is_array and _type(k) == \"number\" then\n                key = fastConcatStr(\"[\", _tostr(k), \"] = \")\n            else\n                key = fastConcatStr(\"[\\\"\", _tostr(k), \"\\\"] = \")\n            end\n\n            if _type(v) == \"table\" then\n                parts[partsKey] = fastConcatStr(indent, key, \"{\\n\")\n                parts[partsKey + 1] = L_SerializeTable(v, indent .. \"    \")\n                parts[partsKey + 2] = fastConcatStr(indent, \"},\\n\")\n                partsKey = partsKey + 3\n            elseif _type(v) == \"boolean\" or _type(v) == \"number\" then\n                parts[partsKey] = fastConcatStr(indent, key, _tostr(v), \",\\n\")\n                partsKey = partsKey + 1\n            else\n                parts[partsKey] = string.format(\"%s%s%q,\\n\", indent, key, v)\n                partsKey = partsKey + 1\n            end\n        end\n        return table.concat(parts)\n    end\n	\n	local file = io.open(\"mods/wand_editor/cache/ModEnable.lua\", \"w\") --将模组启动情况写入文件\n	file:write(\"return {\\n\" .. SerializeTable(_ModIdToEnable, \"\") .. \"}\")\n	file:close()\n	\n	file = io.open(\"mods/wand_editor/cache/SpellsData.lua\", \"w\") --法术缓存写入文件\n	file:write(\"return {\\n\" .. SerializeTable(_result, \"\") .. \"}\")\n	file:close()\n	\n	file = io.open(\"mods/wand_editor/cache/TypeToSpellList.lua\", \"w\") --法术列表缓存写入文件\n	file:write(\"return {\\n\" .. SerializeTable(_TypeToSpellList, \"\") .. \"}\")\n	file:close()\nend\nlocal function DeepCopy(original)\n    local copy\n    if type(original) == 'table' then\n        copy = effil.table({})\n        for orig_key, orig_value in pairs(original) do\n            copy[DeepCopy(orig_key)] = DeepCopy(orig_value)\n        end\n    else -- 非表类型直接复制\n        copy = original\n    end\n    return copy\nend\nif ModSettingGet(\"wand_editor.cache_spell_data\") then\n	local runner = effil.thread(SaveFile)\n	runner(effil,ModIdToEnable,DeepCopy(result),TypeToSpellList)\nend\n\nreflecting = nil--删除变量\ncurrent_reload_time = nil\nReflection_RegisterProjectile = nil\nEntityAddTag(player, \"player_unit\") --恢复状态\ndraw_actions = nil\n\nRegisterGunAction = nil\nRegisterGunShotEffects = nil\nBeginTriggerTimer = nil\nBeginTriggerHitWorld = nil\nBeginTriggerDeath = nil\nEndTrigger = nil\nBeginProjectile = nil\nEndProjectile = nil\nSetProjectileConfigs = nil\nStartReload = nil\nActionUsesRemainingChanged = nil\nActionUsed = nil\nLogAction = nil\nOnActionPlayed = nil\nOnNotEnoughManaForAction = nil\nBaabInstruction = nil\n\nreturn {result, TypeToSpellList, RefreshRealUnlimitedSpells}\n"
_TWWE_VFS["mods/wand_editor/files/gui/SpellsScroll.lua"] = "dofile_once(\"mods/wand_editor/files/libs/fn.lua\")\ndofile_once(\"data/scripts/gun/gun_enums.lua\")\nlocal GetPlayerXY = Compose(EntityGetTransform, GetPlayer)\nlocal fastConcatStr = Cpp.ConcatStr\n\nlocal LastSearch = \"\"--上一次的搜索记录，用于确认是否改变了搜索内容\nlocal LastList--上一次的列表，缓存的数据\nlocal LastType        --上一次的类型，用于判断是否需要重新搜索\nlocal LastFn          --上一次调用的匹配函数，用于判断设置是否更改\nlocal LastRatioMinScore --上一次的匹配分数，用于判断设置是否更改\nlocal LastIDSearchMode  --上一次的是否启用id搜索模式，用于判断设置是否更改\nlocal LastListMax\n\nlocal IsFavorite = false\nlocal FavoriteTable\nlocal HasFavorite\nif ModSettingGet(\"wand_editor_FavoriteTable\") == nil then\n    ModSettingSet(\"wand_editor_FavoriteTable\", \"return {}\")\nend\nif ModSettingGet(\"wand_editor_HasFavorite\") == nil then\n    ModSettingSet(\"wand_editor_HasFavorite\", \"return {}\")\nend\n\n---安全性检查，防止其他模组篡改\n---@param str string\n---@return table\nlocal function SafeLoad(str)\n    local luaStr = tostring(ModSettingGet(str))\n	if HasEnds(luaStr) then\n        ModSettingSet(\"wand_editor_FavoriteTable\", \"return {}\")\n        ModSettingSet(\"wand_editor_HasFavorite\", \"return {}\")\n        return {}\n	end\n    local CheckFn = loadstring(tostring(luaStr))\n    if type(CheckFn) ~= \"function\" then\n        ModSettingSet(\"wand_editor_FavoriteTable\", \"return {}\")\n        ModSettingSet(\"wand_editor_HasFavorite\", \"return {}\")\n        return {}\n    end\n	local fn = setfenv(CheckFn, {})\n	local flag, result = pcall(fn)\n	if not flag then--数据恢复为空表，有代码或其他行为试图篡改为非法数据\n        ModSettingSet(\"wand_editor_FavoriteTable\", \"return {}\")\n        ModSettingSet(\"wand_editor_HasFavorite\", \"return {}\")\n		return {}\n	end\n	return result\nend\n\nFavoriteTable = SafeLoad(\"wand_editor_FavoriteTable\")\nHasFavorite = SafeLoad(\"wand_editor_HasFavorite\")\n\nlocal UesSearchRatio = Cpp.AbsPartialPinyinRatio\nif ModSettingGet(\"wand_editor_RatioMinScore\") == nil then\n	ModSettingSet(\"wand_editor_RatioMinScore\", 60)\nend\nlocal RatioMinScore = ModSettingGet(\"wand_editor_RatioMinScore\")\nlocal IDSearchMode = false\nlocal SearchHistoryList = {}\nlocal SearchKey\n\nfunction SearchSpell(this, spellData, TypeToSpellList, SpellDrawType)\n    local SearchSettingFn = function(_, _, posX, posY, SettingEnable)\n        if SettingEnable then\n            this.ScrollContainer(\"SearchSettingSrcoll\", posX - 20, posY + 20, 180, 30, nil, 0)--绘制一个框\n            this.AddAnywhereItem(\"SearchSettingSrcoll\", function()\n                this.checkbox(\"SearchMode\", 0, 2, GameTextGetTranslatedOrNot(\"$wand_editor_search_fuzzy_setting\"), nil,--一个checkbox，用于设置方面的选项\n                    nil, function()\n                    this.tooltips(function()\n                        GuiText(this.gui, 0, 0, GameTextGetTranslatedOrNot(\"$wand_editor_search_fuzzy_setting_info\"))\n                    end,this.GetZDeep()-114514)\n                end)\n            end)\n            this.AddAnywhereItem(\"SearchSettingSrcoll\", function()\n                this.checkbox(\"IdMode\", 85, 2, GameTextGetTranslatedOrNot(\"$wand_editor_search_id_setting\"), nil,--一个checkbox，用于设置方面的选项\n                    nil, function()\n                    this.tooltips(function()\n                        GuiText(this.gui, 0, 0, GameTextGetTranslatedOrNot(\"$wand_editor_search_id_setting_info\"))\n                    end,this.GetZDeep()-114514)\n                end)\n            end)\n            this.AddAnywhereItem(\"SearchSettingSrcoll\", function()\n				GuiZSetForNextWidget(this.gui, this.GetZDeep()-3)--不要再覆盖啦！\n                ModSettingSet(\"wand_editor_RatioMinScore\",--参数二即为要设置的值\n                    GuiSlider(this.gui, this.NewID(\"FuzzySlider\"), 0, 15,\n                        GameTextGetTranslatedOrNot(\"$wand_editor_search_fuzzy_score_min_info\"),\n                        ModSettingGet(\"wand_editor_RatioMinScore\"), 0, 99, 60, 1, \"\", 80))\n				GuiTooltip(this.gui,GameTextGetTranslatedOrNot(\"$menuoptions_reset_keyboard\"),\"\")\n            end)\n\n            this.DrawScrollContainer(\"SearchSettingSrcoll\", false)\n        end\n    end\n    if this.GetCheckboxEnable(\"SearchMode\") then --如果处于启用状态那么设置搜索函数\n        UesSearchRatio = Cpp.PinyinRatio\n        RatioMinScore = ModSettingGet(\"wand_editor_RatioMinScore\")\n    else --因为另一种搜索规则如果大于0那么就是绝对相关的，因此就RatioMinScore设为0就行\n        UesSearchRatio = Cpp.AbsPartialPinyinRatio\n        RatioMinScore = 0\n    end\n	if this.GetCheckboxEnable(\"IdMode\") then--如果处于启用状态那么设置ID搜索模式\n		IDSearchMode = true\n    else\n		IDSearchMode = false\n	end\n	this.MoveImagePicker(\"SearchSetting\", 50, 249, 5, 0, GameTextGetTranslatedOrNot(\"$wand_editor_search_setting\"), \"mods/wand_editor/files/gui/images/button_fold_open.png\", nil, SearchSettingFn, \"mods/wand_editor/files/gui/images/button_fold_close.png\", nil, nil, true)\n\n	GuiZSetForNextWidget(this.gui, this.GetZDeep()+1000)--不要再覆盖啦！\n    local Search = this.TextInput(\"input\", 63, 249, 123, -1)\n	local _,_, hover = GuiGetPreviousWidgetInfo(this.gui)\n    if hover and InputIsMouseButtonJustDown(Mouse_right) then\n        this.TextInputRestore(\"input\")\n        GamePlaySound(\"data/audio/Desktop/ui.bank\", \"ui/button_click\", GameGetCameraPos())\n    end\n    if hover then\n        UI.UserData[\"SavedSearchHistory\"] = false\n		if SearchKey == nil and Search ~= \"\" and InputIsKeyJustDown(Key_DOWN) then\n			if Search ~= SearchHistoryList[#SearchHistoryList] then--需要判断是否是刚才保存过的，避免重复\n				PushValueOnList(SearchHistoryList, Search)\n				if #SearchHistoryList > 20 then --移除过多内容\n					table.remove(SearchHistoryList, 1)\n				end\n			end\n			this.SetInputText(\"input\", \"\")\n		elseif #SearchHistoryList > 0 then--当列表有可选内容时会进行的操作\n            if InputIsKeyJustDown(Key_UP) then\n                if Search ~= \"\" and SearchKey == nil then\n					if Search ~= SearchHistoryList[#SearchHistoryList] then--需要判断是否是刚才保存过的，避免重复\n						PushValueOnList(SearchHistoryList, Search)\n						if #SearchHistoryList > 20 then --移除过多内容\n							table.remove(SearchHistoryList, 1)\n						end\n					end\n                    SearchKey = math.max(1, #SearchHistoryList - 1)\n                elseif SearchKey == nil then\n                    SearchKey = #SearchHistoryList\n                else\n                    SearchKey = math.max(1, SearchKey - 1)\n                end\n                this.SetInputText(\"input\", SearchHistoryList[SearchKey])\n            elseif InputIsKeyJustDown(Key_DOWN) and SearchKey then\n                SearchKey = SearchKey + 1\n                if SearchKey <= #SearchHistoryList then\n                    this.SetInputText(\"input\", SearchHistoryList[SearchKey])\n                else\n                    SearchKey = nil\n                    this.SetInputText(\"input\", \"\")\n                end\n            end\n		end\n    end\n    if not hover and not UI.UserData[\"SavedSearchHistory\"] then --历史搜索数据存储\n        if (#SearchHistoryList > 0 and SearchHistoryList[#SearchHistoryList] ~= Search) or #SearchHistoryList == 0 then\n            if Search ~= \"\" and SearchKey == nil then\n                PushValueOnList(SearchHistoryList, Search)\n                if #SearchHistoryList > 20 then --移除过多内容\n                    table.remove(SearchHistoryList, 1)\n                end\n            end\n            if SearchHistoryList[SearchKey] ~= Search then --文本不相同时再清除搜索key用于记录新的搜索文本\n                SearchKey = nil\n            end\n        end\n        UI.UserData[\"SavedSearchHistory\"] = true\n    end\n	--TablePrint(SearchHistoryList)\n	\n	this.tooltips(function ()\n		GuiText(this.gui,0,0,GameTextGetTranslatedOrNot(\"$wand_editor_search_info\"))\n    end, nil, 8, 16)\n	local DrawSpellList\n    if SpellDrawType ~= \"favorite\" then\n        DrawSpellList = TypeToSpellList[SpellDrawType]\n        IsFavorite = false\n    else --特判\n        DrawSpellList = FavoriteTable\n        IsFavorite = true\n    end\n	local SearchList\n	if ModSettingGet(ModID .. \".split_search_text\") then\n		SearchList = split(string.lower(Search), \" \")\n	else\n		SearchList = { string.lower(Search) }\n	end\n	--当搜索内容不为空且上一次搜索内容不等于现在的输入内容，或类型变化时搜索，或匹配分数变化时搜索，或搜索方式函数变化时搜索，或id搜索模式变化时搜索\n    if (Search ~= \"\" and LastSearch ~= Search) or LastType ~= SpellDrawType or LastFn ~= UesSearchRatio or LastRatioMinScore ~= RatioMinScore or LastIDSearchMode ~= IDSearchMode or #SearchList ~= LastListMax then\n		if Search == \"\" then\n			return DrawSpellList,SpellDrawType\n		end\n		LastSearch = Search\n        LastType = SpellDrawType\n		SpellDrawType = \"HasSearch\"\n        local ScoreToSpellID = {}\n		local ScoreToSpellIDCount = {}--带有Count的(计数器)的变量代码均为性能优化，用于取代table.insert\n        local ScoreList = {}\n		local ScoreListCount = 1\n        local HasScore = {}\n		for _, v in pairs(DrawSpellList) do --循环计算匹配程度\n            if spellData[v] == nil then\n                goto continue\n            end\n            local score = 0\n			for _,lowerSearch in pairs(SearchList)do\n                local TempScore = UesSearchRatio(string.lower(GameTextGetTranslatedOrNot(spellData[v].name)), lowerSearch) --大小写不敏感\n                if TempScore > score then\n                    score = TempScore\n                end\n                if string.byte(lowerSearch, 1, 1) == string.byte(\"@\") then\n					local ModIdSearch = string.sub(lowerSearch,2)\n					local ModIdScore = UesSearchRatio(string.lower(GameTextGetTranslatedOrNot(spellData[v].wand_editor_from or \"?\")), ModIdSearch)\n                    if ModIdScore > score then\n                        score = ModIdScore\n                    end\n					ModIdScore = UesSearchRatio(string.lower(GameTextGetTranslatedOrNot(spellData[v].wand_editor_from_id or \"?\")), ModIdSearch)\n					if ModIdScore > score then\n                        score = ModIdScore\n                    end\n				end\n				local IDScore = 0\n				if IDSearchMode then\n					IDScore = UesSearchRatio(string.lower(v), lowerSearch)\n				end\n				local key = string.sub(spellData[v].name, 2)\n				local EnStr = CSV.get(key, \"en\")\n				local EnScore = 0\n				if EnStr ~= nil then\n					EnScore = UesSearchRatio(string.lower(EnStr), lowerSearch)\n				end\n				if IDScore > score then\n					score = IDScore\n				end\n				if EnScore > score then\n					score = EnScore\n				end\n			end\n            if ScoreToSpellID[score] == nil then\n                ScoreToSpellID[score] = {}\n                ScoreToSpellIDCount[score] = 1\n            end\n            ScoreToSpellID[score][ScoreToSpellIDCount[score]] = v\n            ScoreToSpellIDCount[score] = ScoreToSpellIDCount[score] + 1\n            if HasScore[score] == nil then\n                ScoreList[ScoreListCount] = score\n                ScoreListCount = ScoreListCount + 1\n                HasScore[score] = true\n            end\n            ::continue::\n        end\n		--接下来进行排序\n        table.sort(ScoreList)\n        DrawSpellList = {}\n		local DrawSpellListCount = 1\n        for i = #ScoreList, 1, -1 do\n            if ScoreList[i] > RatioMinScore then\n                for _, v in pairs(ScoreToSpellID[ScoreList[i]]) do\n					DrawSpellList[DrawSpellListCount] = v\n					DrawSpellListCount = DrawSpellListCount + 1\n                end\n            else--如果有不符合条件的，这意味着之后的也都不符合，所以直接退出循环\n                break\n            end\n        end\n        LastList = DrawSpellList\n        LastFn = UesSearchRatio\n        LastRatioMinScore = RatioMinScore\n        LastIDSearchMode = IDSearchMode\n		LastListMax = #SearchList\n    elseif LastSearch == Search and LastType == SpellDrawType and Search ~= \"\" then\n        DrawSpellList = LastList\n    end\n	return DrawSpellList,SpellDrawType\nend\nlocal data = dofile_once(\"mods/wand_editor/files/gui/GetSpellData.lua\") --读取法术数据\nlocal spellData = data[1]\n\nlocal TypeToSpellList = data[2]\nlocal SpellDrawType = \"AllSpells\"\nlocal TypeList = {\n	\"AllSpells\",\n	ACTION_TYPE_PROJECTILE,\n	ACTION_TYPE_STATIC_PROJECTILE,\n	ACTION_TYPE_MODIFIER,\n	ACTION_TYPE_DRAW_MANY,\n	ACTION_TYPE_MATERIAL,\n	ACTION_TYPE_OTHER,\n	ACTION_TYPE_UTILITY,\n	ACTION_TYPE_PASSIVE,\n	\"favorite\"\n}\nlocal SpellList = {\n	AllSpells = \"AllSpells\",\n	[ACTION_TYPE_PROJECTILE] = \"projectile\",\n	[ACTION_TYPE_STATIC_PROJECTILE] = \"static_projectile\",\n	[ACTION_TYPE_MODIFIER] = \"modifier\",\n	[ACTION_TYPE_DRAW_MANY] = \"draw_many\",\n	[ACTION_TYPE_MATERIAL] = \"material\",\n	[ACTION_TYPE_OTHER] = \"other\",\n	[ACTION_TYPE_UTILITY] = \"utility\",\n	[ACTION_TYPE_PASSIVE] = \"passive\",\n}\n\nlocal GetPlayerWandID = Compose(GetEntityHeldWand, GetPlayer)\n\nfunction SpellDepotClickCB(_, right_click, _, _, depot_enable)\n	if right_click then\n		local status = ModSettingGet(fastConcatStr(ModID,\"SpellDepotCloseSpellOnGround\"))\n        if status == nil then\n            ModSettingSet(fastConcatStr(ModID , \"SpellDepotCloseSpellOnGround\"), true)\n        else\n            ModSettingSet(fastConcatStr(ModID , \"SpellDepotCloseSpellOnGround\"), not status)\n        end\n		GamePlaySound(\"data/audio/Desktop/ui.bank\", \"ui/button_click\", GameGetCameraPos())\n	end\n	if not depot_enable then\n		return\n	end\n	local function HelpHover()\n		UI.tooltips(function()\n			GuiText(UI.gui, 0, 0, GameTextGetTranslatedOrNot(\"$wand_editor_search_help\"))\n		end, UI.GetZDeep()-114514, 5)\n	end\n	UI.MoveImageButton(\"SpellDepotHelp\", 200, 249,\n		\"mods/wand_editor/files/gui/images/help.png\", nil, HelpHover, nil, nil, true)\n\n	local function WandContainerClickCB(_, _, _, _, WandContainer_enable)\n		if WandContainer_enable then\n			DrawWandContainer(GetPlayerWandID(), spellData)\n		end\n	end\n    local wandEditBoxText = GameTextGet(\"$wand_editor_wand_edit_box\")\n	local y_offest = 20\n	if UI.GetPickerStatus(\"WandContainerBTN\") then\n        wandEditBoxText = wandEditBoxText .. GameTextGet(\"$wand_editor_wand_edit_box_help\")\n		y_offest = 0\n	end\n	UI.MoveImagePicker(\"WandContainerBTN\", 28, 247, 8, y_offest,\n		wandEditBoxText,\"mods/wand_editor/files/gui/images/wand_container.png\", nil, WandContainerClickCB,\n		nil, true, true, true)\n\n	local DrawSpellList, InputType = SearchSpell(UI, spellData, TypeToSpellList, SpellDrawType)\n	--绘制容器\n	DrawSpellContainer(UI, spellData, DrawSpellList, InputType)\n	for i, v in pairs(TypeList) do     --绘制左边选择类型按钮\n		local sprite\n		if v == \"AllSpells\" then\n			sprite = fastConcatStr(ModDir , \"files/gui/images/all_spells.png\")\n		elseif v == \"favorite\" then\n			sprite = fastConcatStr(ModDir , \"files/gui/images/favorite_icon.png\")\n		else\n			sprite = fastConcatStr(ModDir , \"files/gui/images/\" , SpellList[v] , \"_icon.png\")\n		end\n\n		local Hover = function()\n			local _, _, hover = GuiGetPreviousWidgetInfo(UI.gui)\n			if hover then\n				SpellDrawType = v\n				local HoverText\n				if v == \"AllSpells\" then\n					HoverText = GameTextGetTranslatedOrNot(\"$wand_editor_All_spells\")\n				elseif v == \"favorite\" then\n					HoverText = GameTextGetTranslatedOrNot(\"$wand_editor_favorite\")\n				else\n					HoverText = SpellTypeEnumToStr(v)\n				end\n				UI.tooltips(function()\n					GuiText(UI.gui, 0, 0, HoverText)\n				end, nil, nil, nil, true)\n			end\n		end\n        if SpellDrawType ~= v then\n            GuiOptionsAddForNextWidget(UI.gui, GUI_OPTION.DrawSemiTransparent)\n        end\n		GuiZSetForNextWidget(UI.gui, UI.GetZDeep())\n		UI.MoveImageButton(\"Switch\" .. v, 7, 44 + i * 20, sprite, nil, Hover, nil, nil, true)\n	end\nend\n\nlocal SkipDrawMoreText = {\n    [\"RANDOM_SPELL\"] = true,\n    [\"RANDOM_PROJECTILE\"] = true,\n    [\"RANDOM_STATIC_PROJECTILE\"] = true,\n    [\"RANDOM_MODIFIER\"] = true,\n    [\"RANDOM_EXPLOSION\"] = true,\n	[\"DAMAGE_RANDOM\"] = true,\n}\n\nlocal DrawLastText = function (LastText, cb)\n	GuiLayoutAddVerticalSpacing(UI.gui, 5)\n	local spaceX = GuiGetTextDimensions(UI.gui, LastText)\n	GuiText(UI.gui, spaceX, 0, \" \")\n	local _, _, _, x, y = GuiGetPreviousWidgetInfo(UI.gui)\n    GuiOptionsAddForNextWidget(UI.gui, GUI_OPTION.Layout_NoLayouting)\n	if cb then\n		cb()\n	end\n	GuiText(UI.gui, x - spaceX, y, LastText)\nend\n\n---用于绘制法术文本\n---@param this table\n---@param id string\n---@param idata table\nfunction HoverDarwSpellText(this, id, idata, Uses, LastText)\n    local world_entity_id = GameGetWorldStateEntity()\n    local comp_worldstate = EntityGetFirstComponent(world_entity_id, \"WorldStateComponent\")\n    local inf_spells_enable = ComponentGetValue2(comp_worldstate, \"perk_infinite_spells\")\n	\n	local rightMargin = 72\n	local function NewLine(str1, str2)\n		local text = GameTextGetTranslatedOrNot(str1)\n		local w = GuiGetTextDimensions(this.gui,text)\n        GuiLayoutBeginHorizontal(this.gui, 0, 0, true, 2, -1)\n        GuiText(this.gui, 0, 0, text)\n        GuiRGBAColorSetForNextWidget(this.gui, 255, 222, 173, 255)\n		if w + 8 > rightMargin then\n			GuiText(this.gui, w + 8 - w, 0, str2)\n        else\n			GuiText(this.gui, rightMargin - w, 0, str2)\n		end\n		GuiLayoutEnd(this.gui)\n	end\n    local name = GameTextGetTranslatedOrNot(idata.name)\n	if Uses and Uses ~= -1 then\n		name = name..\" (\"..tostring(Uses)..\")\"\n	end\n	GuiText(this.gui, 0, 0, string.upper(name))\n	GuiColorSetForNextWidget(this.gui, 0.5, 0.5, 0.5, 1.0)\n	GuiText(this.gui, 0, 0, id)\n	GuiText(this.gui, 0, 0, GameTextGetTranslatedOrNot(idata.description))\n	GuiColorSetForNextWidget(this.gui, 0.5, 0.5, 1.0, 1.0)\n	GuiText(this.gui, 0, 0, SpellTypeEnumToStr(idata.type))\n	\n	GuiLayoutAddVerticalSpacing(UI.gui,7)\n	--GuiLayoutBeginVertical(this.gui, 0, 7, true) --垂直布局\n    if idata.max_uses and idata.max_uses ~= -1 then\n		if (inf_spells_enable and idata.never_unlimited) or not inf_spells_enable then\n			NewLine(\"$wand_editor_max_uses\", tostring(idata.max_uses)) --使用次数\n		end\n    end\n	\n	NewLine(\"$inventory_manadrain\", tostring(idata.mana))--耗蓝\n    local DrawIDText\n	local DrawIDSetting = ModSettingGet(ModID..\".spell_mod_id_or_name\")\n	if DrawIDSetting == \"name\" then\n        DrawIDText = idata.wand_editor_from\n    elseif DrawIDSetting == \"id\" then\n        DrawIDText = idata.wand_editor_from_id\n    elseif DrawIDSetting == \"all\" and idata.wand_editor_from and idata.wand_editor_from_id then\n		DrawIDText = \"ID:\"..idata.wand_editor_from_id..\" \"..GameTextGetTranslatedOrNot(\"$wand_editor_spell_name\")..\":\"..idata.wand_editor_from\n	end\n	DrawIDText = DrawIDText or \"?\"\n    if SkipDrawMoreText[id] then\n		DrawLastText(DrawIDText,function ()\n			GuiRGBAColorSetForNextWidget(this.gui, 72, 209, 204, 255)\n		end)\n		if LastText then\n			DrawLastText(LastText)\n		end\n		return\n    end\n	\n	if idata.draw_actions and idata.draw_actions ~= 0 then\n		NewLine(\"$wand_editor_draw_many\", tostring(idata.draw_actions))\n	end\n\n	if idata.timerLifeTime then\n		NewLine(\"$wand_editor_timer_life_time\", tostring(idata.timerLifeTime)..\"f\")\n	end\n\n	if idata.projComp and idata.projComp.damage ~= \"0\" then --如果有投射物伤害\n		NewLine(\"$inventory_damage\", tostring(tonumber(idata.projComp.damage) * 25))\n	end\n	\n	if idata.projExplosion and idata.projExplosion ~= 0 then --如果有爆炸伤害\n		NewLine(\"$inventory_dmg_explosion\", tostring(math.floor(idata.projExplosion * 25)))\n	end\n	if idata.projExplosionRadius and idata.projExplosionRadius ~= 0 then --如果有爆炸半径\n		NewLine(\"$inventory_explosion_radius\", tostring(idata.projExplosionRadius))\n	end\n	\n	if idata.true_recoil then --如果有后坐力\n		NewLine(\"$wand_editor_recoil_knockback\", idata.true_recoil)\n	end\n\n    if idata.projComp then\n        for k, v in pairs(idata.projDmg) do --伤害参数\n            if v ~= 0 then\n                if k == \"electricity\" then\n                    NewLine(\"$inventory_mod_damage_electric\", tostring(v * 25))\n                else\n                    NewLine(\"$inventory_dmg_\" .. k, tostring(v * 25))\n                end\n            end\n        end\n        --散射\n        if idata.projComp.direction_random_rad ~= \"0\" then\n            local rad = tonumber(idata.projComp.direction_random_rad)\n			local formatted = string.format(\"%.2f\",math.deg(rad)) .. GameTextGetTranslatedOrNot(\"$wand_editor_deg\")\n			NewLine(\"$inventory_spread\", formatted)\n		end\n        --速度\n        local speed_min = tonumber(idata.projComp.speed_min)\n        local speed_max = tonumber(idata.projComp.speed_max)\n        if (speed_min == speed_max) and speed_min ~= 0 and speed_max ~= 0 then\n            NewLine(\"$inventory_speed\", tostring(speed_max))\n        elseif speed_min ~= 0 and speed_max ~= 0 then\n            NewLine(\"$inventory_speed\",\n                tostring(speed_min) .. GameTextGetTranslatedOrNot(\"$wand_editor_to\") .. tostring(speed_max))\n        end\n        if idata.lifetime then\n            local randomness = tonumber(idata.projComp.lifetime_randomness)\n            if randomness ~= 0 then\n                NewLine(\"$wand_editor_lifetime\",\n                    tostring(idata.lifetime - randomness) ..\n                    \"f\" .. GameTextGetTranslatedOrNot(\"$wand_editor_to\") .. tostring(idata.lifetime + randomness) .. \"f\")\n            else\n                NewLine(\"$wand_editor_lifetime\", idata.lifetime .. \"f\")\n            end\n        end\n    end\n	\n	if idata.lifetimeLimit then\n		if idata.lifetimeLimitMin and idata.lifetimeLimitMax then\n			NewLine(\"$wand_editor_lifetime_limit\",\n				tostring(idata.lifetimeLimit + idata.lifetimeLimitMin) ..\n				\"f\" .. GameTextGetTranslatedOrNot(\"$wand_editor_to\") .. tostring(idata.lifetimeLimit + idata.lifetimeLimitMax) .. \"f\")\n		else\n			NewLine(\"$wand_editor_lifetime_limit\", tostring(idata.lifetimeLimit) .. \"f\")\n		end\n	end\n	\n	local SecondWithSign = Compose(NumToWithSignStr, tonumber, FrToSecondStr)\n	if idata.c.fire_rate_wait ~= 0 then--施放延迟\n		NewLine(\"$inventory_castdelay\", SecondWithSign(idata.c.fire_rate_wait)  .. \"s(\"..idata.c.fire_rate_wait..\"f)\" )\n	end\n	if idata.reload_time ~= 0 then --充能延迟\n		NewLine(\"$inventory_rechargetime\", SecondWithSign(idata.reload_time) .. \"s(\"..idata.reload_time..\"f)\" )\n	end\n	\n	if idata.c.lifetime_add ~= 0 then	--存在时间修正\n		NewLine(\"$wand_editor_lifetime\", NumToWithSignStr(idata.c.lifetime_add) .. \"f\" )\n	end\n\n	if idata.c.damage_critical_chance ~= 0 then --暴击几率\n		NewLine(\"$inventory_mod_critchance\", NumToWithSignStr(idata.c.damage_critical_chance) .. \"%\" )\n	end\n\n	if idata.c.spread_degrees ~= 0 then--散射修正\n		NewLine(\"$inventory_spread\", NumToWithSignStr(idata.c.spread_degrees) .. GameTextGetTranslatedOrNot(\"$wand_editor_deg\") )\n	end\n\n	if idata.c.speed_multiplier ~= 1 then--投射物速度修正\n		NewLine(\"$inventory_mod_speed\", \"x \"..tostring(idata.c.speed_multiplier))\n	end\n\n	if idata.c.bounces ~= 0 then --弹跳次数\n		NewLine(\"$inventory_mod_bounces\", NumToWithSignStr(idata.c.bounces))\n	end\n\n	if idata.c.damage_projectile_add ~= 0 then--投射物伤害修正\n		NewLine(\"$inventory_mod_damage\", NumToWithSignStr(idata.c.damage_projectile_add * 25))\n	end\n\n	if idata.c.damage_healing_add ~= 0 then--治疗伤害修正\n		NewLine(\"$inventory_mod_damage_healing\", NumToWithSignStr(idata.c.damage_healing_add * 25))\n	end\n\n	if idata.c.damage_curse_add ~= 0 then--诅咒伤害修正\n		NewLine(\"$inventory_mod_damage_curse\", NumToWithSignStr(idata.c.damage_curse_add * 25))\n	end\n\n	if idata.c.damage_explosion_add ~= 0 then--爆炸伤害修正\n		NewLine(\"$inventory_mod_damage_explosion\", NumToWithSignStr(idata.c.damage_explosion_add * 25))\n	end\n\n	if idata.c.damage_slice_add ~= 0 then--切割伤害修正\n		NewLine(\"$inventory_mod_damage_slice\", NumToWithSignStr(idata.c.damage_slice_add * 25))\n	end\n\n	if idata.c.damage_ice_add ~= 0 then--冰冻伤害修正\n		NewLine(\"$inventory_mod_damage_ice\", NumToWithSignStr(idata.c.damage_ice_add * 25))\n	end\n\n	if idata.c.damage_melee_add ~= 0 then--近战伤害修正\n		NewLine(\"$inventory_mod_damage_melee\", NumToWithSignStr(idata.c.damage_melee_add * 25))\n	end\n\n	if idata.c.damage_drill_add ~= 0 then--穿凿伤害修正\n		NewLine(\"$inventory_mod_damage_drill\", NumToWithSignStr(idata.c.damage_drill_add * 25))\n	end\n\n	if idata.c.damage_fire_add ~= 0 then--火焰伤害修正\n		NewLine(\"$inventory_mod_damage_fire\", NumToWithSignStr(idata.c.damage_fire_add * 25))\n	end\n\n    if idata.c.damage_electricity_add ~= 0 then --雷电伤害修正\n        NewLine(\"$inventory_mod_damage_electric\", NumToWithSignStr(idata.c.damage_electricity_add * 25))\n    end\n	DrawLastText(DrawIDText,function ()\n		GuiRGBAColorSetForNextWidget(this.gui, 72, 209, 204, 255)\n	end)\n    if LastText then\n		DrawLastText(LastText)\n    end\nend\n\nlocal LastHistoryTable = {}\nlocal HistoryTableMap = {}\n\nlocal NewUseHistory = function (id)\n	if HistoryTableMap[id] == nil then\n		table.insert(LastHistoryTable, 1, id)\n		HistoryTableMap[id] = true\n	elseif HistoryTableMap[id] then\n		local KeyPos\n		for key, Value in pairs(LastHistoryTable) do\n			if Value == id then\n				KeyPos = key\n				break\n			end\n		end\n		table.remove(LastHistoryTable, KeyPos)\n		table.insert(LastHistoryTable, 1, id)\n	end\n	if #LastHistoryTable > 18 then\n		HistoryTableMap[LastHistoryTable[19]] = false\n		table.remove(LastHistoryTable,19)\n	end\n	ModSettingSet(ModID .. \"SpellDepotHistoryData\", fastConcatStr(\"return {\",SerializeTable(LastHistoryTable),\"}\"))\nend\n---用于绘制法术容器\n---@param this table\n---@param spellData table 法术数据\n---@param spellTable table 法术列表\n---@param type integer|string\nfunction DrawSpellContainer(this, spellData, spellTable, type)\n    local ZDeepest = this.GetZDeep()\n    local ContainerName = fastConcatStr(\"SpellsScroll\", tostring(type))\n	if UI.GetPickerStatus(\"SpellDepotHistoryMode\") then\n        this.ScrollContainer(ContainerName, 30, 64, 178, 130, nil, 0, 1.35)\n        this.ScrollContainer(\"HistorySpells\", 30, 200, 178, 45, nil, 0, 1.35)\n\n        local RemoveCB = function(left_click)\n            if left_click then\n                GamePlaySound(\"data/audio/Desktop/ui.bank\", \"ui/button_click\", GameGetCameraPos())\n                if UI.UserData[\"RemoveSpellDepotHistoryBtn_IKnowWhatImDoing\"] == nil then\n                    UI.UserData[\"RemoveSpellDepotHistoryBtn_IKnowWhatImDoing\"] = true\n                    return\n                end\n                HistoryTableMap = {}\n                LastHistoryTable = {}\n                ModSettingSet(ModID .. \"SpellDepotHistoryData\", \"return {}\")\n                UI.UserData[\"RemoveSpellDepotHistoryBtn_IKnowWhatImDoing\"] = nil\n            end\n        end\n		GuiZSetForNextWidget(UI.gui,UI.GetZDeep())\n		UI.MoveImageButton(\"RemoveSpellDepotHistoryBtn\", 215, 200,\n            \"mods/wand_editor/files/gui/images/remove_spell_depot_history.png\", nil, function()\n			local _,_,hover = GuiGetPreviousWidgetInfo(UI.gui)\n			if UI.UserData[\"RemoveSpellDepotHistoryBtn_IKnowWhatImDoing\"] then\n				GuiTooltip(UI.gui, GameTextGet(\"$wand_editor_remove_spell_depot_history_IKnowWhatImDoing\"), \"\")\n            else\n				GuiTooltip(UI.gui, GameTextGet(\"$wand_editor_remove_spell_depot_history\"), \"\")\n			end\n			if not hover and UI.UserData[\"RemoveSpellDepotHistoryBtn_IKnowWhatImDoing\"] then\n				UI.UserData[\"RemoveSpellDepotHistoryBtn_IKnowWhatImDoing\"] = nil\n			end\n		end, RemoveCB, false, true)\n    else\n		this.ScrollContainer(ContainerName, 30, 64, 178, 180, nil, 0, 1.3)\n	end\n	local SpellSlotDraw = function (pos,id,Container,GuiID)\n		this.SetZDeep(this.GetZDeep() + 3)--设置深度，确保行为正确\n		local sprite = spellData[id].sprite\n\n        local SpellHover = function()                 --绘制法术悬浮窗用函数\n            local _, _, hover = GuiGetPreviousWidgetInfo(UI.gui)\n			this.UserData[\"WandContainerHasHover\"] = this.UserData[\"WandContainerHasHover\"] or hover\n            if not this.UserData[\"HasSpellMove\"] then --法术悬浮窗绘制\n                UI.BetterTooltips(function()\n					local world_entity_id = GameGetWorldStateEntity()\n					local comp_worldstate = EntityGetFirstComponent(world_entity_id, \"WorldStateComponent\")\n                    local inf_spells_enable = ComponentGetValue2(comp_worldstate, \"perk_infinite_spells\")\n					\n                    local max\n					if (inf_spells_enable and spellData[id].never_unlimited) or not inf_spells_enable then\n						max = spellData[id].max_uses\n					end\n                    HoverDarwSpellText(this, id, spellData[id],max)\n                end, this.GetZDeep() - 114514,8,24)\n            end\n        end\n		\n		local SpellCilck = function(left_click, right_click, x, y) --法术点击效果\n            local CTRL = InputIsKeyDown(Key_LCTRL) or InputIsKeyDown(Key_RCTRL)\n            local ALT = InputIsKeyDown(Key_LALT) or InputIsKeyDown(Key_RALT)\n            local SHIFT = InputIsKeyDown(Key_LSHIFT) or InputIsKeyDown(Key_RSHIFT)\n            if left_click and SHIFT then                                                                                                                --快捷添加法术\n                local CurrentWand\n                if this.UserData[\"FixedWand\"] and this.UserData[\"HasShiftClick\"] and this.UserData[\"HasShiftClick\"][this.UserData[\"FixedWand\"][2]] then --固定的法杖必须是有选框才能判定\n                    CurrentWand = this.UserData[\"FixedWand\"][2]\n                else                                                                                                                                    --否则就判断手持\n                    local HeldWand = Compose(GetEntityHeldWand, GetPlayer)()\n                    if HeldWand then\n                        CurrentWand = HeldWand\n                    end\n                end\n                if CurrentWand and this.UserData[\"HasShiftClick\"] and this.UserData[\"HasShiftClick\"][CurrentWand] then --如果是有选框的\n                    local wandData = GetWandData(CurrentWand)\n                    local HasShiftClick = this.UserData[\"HasShiftClick\"][CurrentWand]\n                    local min = HasShiftClick[2]\n                    local max = HasShiftClick[3] or min\n                    min = math.min(min, max)\n                    max = math.max(HasShiftClick[2], max)\n                    if min == max then --如果是单个选框的\n                        SetTableSpells(wandData, id, min)\n                        InitWand(wandData, CurrentWand)\n                        HasShiftClick[2] = HasShiftClick[2] + 1\n                    else --反之就是多个\n                        for i = min, max do\n                            SetTableSpells(wandData, id, i)\n                        end\n                        InitWand(wandData, CurrentWand)\n                        this.UserData[\"HasShiftClick\"][CurrentWand] = nil\n                    end\n                    this.OnceCallOnExecute(function()\n                        RefreshHeldWands()\n                    end)\n					NewUseHistory(id)\n                elseif CurrentWand then --没有选框\n                    local wandData = GetWandData(CurrentWand)\n                    for k, v in pairs(wandData.spells.spells) do\n                        if v == \"nil\" then\n                            SetTableSpells(wandData, id, k)\n                            InitWand(wandData, CurrentWand)\n                            break\n                        end\n                    end\n                    this.OnceCallOnExecute(function()\n                        RefreshHeldWands()\n                    end)\n					NewUseHistory(id)\n                end\n			elseif right_click and SHIFT then\n                local CurrentWand\n                if this.UserData[\"FixedWand\"] and this.UserData[\"HasShiftClick\"] and this.UserData[\"HasShiftClick\"][this.UserData[\"FixedWand\"][2]] then --固定的法杖必须是有选框才能判定\n                    CurrentWand = this.UserData[\"FixedWand\"][2]\n                else                                                                                                                                    --否则就判断手持\n                    local HeldWand = Compose(GetEntityHeldWand, GetPlayer)()\n                    if HeldWand then\n                        CurrentWand = HeldWand\n                    end\n                end\n				if CurrentWand and this.UserData[\"HasShiftClick\"] and this.UserData[\"HasShiftClick\"][CurrentWand] then --必须是有选框的\n					NewUseHistory(id)\n					local HasShiftClick = this.UserData[\"HasShiftClick\"][CurrentWand]\n                    local min = HasShiftClick[2]\n                    local max = HasShiftClick[3] or min\n					if min == max then--必须是单选一格的情况下\n						local wandData = GetWandData(CurrentWand)\n                        local flag = InsertTableSpells(wandData, InputIsKeyDown(Key_z), id, min)\n                        if flag then\n							InitWand(wandData, CurrentWand)\n							this.OnceCallOnExecute(function()\n								RefreshHeldWands()\n							end)\n                        else\n							GamePrint(GameTextGet(\"$wand_editor_spell_insert_error\"))\n						end\n					end\n				end\n            elseif left_click and CTRL then --CTRL+左键\n                local inventory_full = EntityGetChildWithName(GetPlayer(), \"inventory_full\")\n                if inventory_full then\n					NewUseHistory(id)\n                    local px, py = GetPlayerXY()\n                    local spell = CreateItemActionEntity(id, px, py)\n                    EntitySetComponentsWithTagEnabled(spell, \"enabled_in_world\", false)\n                    EntityAddChild(inventory_full, spell)\n                    GamePrint(GameTextGetTranslatedOrNot(spellData[id].name),\n                        GameTextGetTranslatedOrNot(\"$wand_editor_added_spell\"))\n                end\n            elseif left_click and ALT then --ALT+左键收藏/删除法术\n                if IsFavorite and Container ~= \"HistorySpells\" then\n                    HasFavorite[id] = nil\n                    table.remove(FavoriteTable, pos)\n                    GamePrint(GameTextGetTranslatedOrNot(spellData[id].name),\n                        GameTextGetTranslatedOrNot(\"$wand_editor_remove_favorite\"))\n                    ModSettingSet(\"wand_editor_FavoriteTable\", \"return {\" .. SerializeTable(FavoriteTable) .. \"}\")\n                    ModSettingSet(\"wand_editor_HasFavorite\", \"return {\" .. SerializeTable(HasFavorite) .. \"}\")\n                else\n                    if HasFavorite[id] == nil then\n                        table.insert(FavoriteTable, 1, id)\n                        HasFavorite[id] = true\n                        GamePrint(GameTextGetTranslatedOrNot(spellData[id].name),\n                            GameTextGetTranslatedOrNot(\"$wand_editor_added_favorite_spell\"))\n                        ModSettingSet(\"wand_editor_FavoriteTable\", \"return {\" .. SerializeTable(FavoriteTable) .. \"}\")\n                        ModSettingSet(\"wand_editor_HasFavorite\", \"return {\" .. SerializeTable(HasFavorite) .. \"}\")\n                    else\n                        GamePrint(GameTextGetTranslatedOrNot(spellData[id].name),\n                            GameTextGetTranslatedOrNot(\"$wand_editor_added_favorite_Already\"))\n                    end\n                end\n            elseif left_click and not UI.UserData[\"HasSpellMove\"]and not this.GetNoMoveBool() then --纯左键\n                this.UserData[\"SpellHoverEnable\"] = false\n                DrawFloatSpell(x, y, sprite, id)\n				NewUseHistory(id)\n            elseif left_click and UI.UserData[\"HasSpellMove\"] then\n                UI.UserData[\"HasSpellMove\"] = false\n                UI.UserData[\"FloatSpellID\"] = nil\n                UI.UserData[\"UpSpellIndex\"] = nil\n				this.UserData[\"SpellHoverEnable\"] = true\n            end\n		end\n\n		this.AddScrollImageItem(Container, sprite, function()--添加图片项目的回调绘制\n			GuiZSetForNextWidget(this.gui, this.GetZDeep() + 2)\n			GuiImage(this.gui, this.NewID(fastConcatStr(\"__SPELL_\" , id , \"_BG\", GuiID)), -2, 0, \"data/ui_gfx/inventory/full_inventory_box.png\", 1, 1)\n            local _, _, _, x, y, w, h = GuiGetPreviousWidgetInfo(this.gui)\n            GuiZSetForNextWidget(this.gui, this.GetZDeep())\n            GuiOptionsAddForNextWidget(this.gui, GUI_OPTION.Layout_NoLayouting)\n            if not UI.GetPickerStatus(\"DisableSpellWobble\") then\n                GuiOptionsAddForNextWidget(this.gui, GUI_OPTION.DrawWobble) --让法术摇摆\n            end\n            local sw,sh = GuiGetImageDimensions(this.gui, sprite, 1)\n			UI.MoveImageButton(fastConcatStr(\"__SPELL_\", id, GuiID), x + (w-sw)/2, y + (h-sh)/2, sprite, nil, SpellHover, SpellCilck, true, true)--最后两个参数是不始终调用点击回调和禁止移动\n			--绘制法术背景，深度要控制好\n\n            GuiZSetForNextWidget(this.gui, this.GetZDeep() + 1)\n			GuiOptionsAddForNextWidget(this.gui,GUI_OPTION.Layout_NoLayouting)\n			GuiImage(this.gui, this.NewID(fastConcatStr(\"__SPELL_\" , id , \"_SPELLBG\", GuiID)), x, y, SpellTypeBG[spellData[id].type], 1, 1)\n        end)\n		this.SetZDeep(ZDeepest)\n	end\n    for pos, id in pairs(spellTable) do\n        if spellData[id] == nil then\n            goto continue\n        end\n        SpellSlotDraw(pos, id, ContainerName, \"spellTable\")\n        ::continue::\n    end\n	if UI.GetPickerStatus(\"SpellDepotHistoryMode\") then\n		local TableStr = ModSettingGet(ModID .. \"SpellDepotHistoryData\")\n		if TableStr == nil then\n			ModSettingSet(ModID .. \"SpellDepotHistoryData\", \"return {}\")\n			LastHistoryTable = {}\n        else\n            LastHistoryTable = loadstring(TableStr)()\n			for k,v in pairs(LastHistoryTable)do\n				HistoryTableMap[v] = true\n			end\n		end\n        for pos, id in pairs(LastHistoryTable) do\n            if spellData[id] == nil then\n                HistoryTableMap[id] = nil\n				LastHistoryTable[pos] = nil\n                goto continue\n            end\n            SpellSlotDraw(pos, id, \"HistorySpells\", \"History\")\n            ::continue::\n        end\n		this.DrawScrollContainer(\"HistorySpells\", false)\n	end\n    GuiZSetForNextWidget(this.gui, this.GetZDeep() + 1) --设置深度，确保行为正确\n    this.DrawScrollContainer(ContainerName, true)\nend\n"
_TWWE_VFS["mods/wand_editor/files/gui/TargetDummyGUI.lua"] = "dofile_once(\"mods/wand_editor/files/libs/fn.lua\")\n\nlocal function NumInput(id, x, y, w, l, str)\n    UI.TextInput(id, x, y, w, l, str, \"1234567890.-\")\n    local _,right_click, hover = GuiGetPreviousWidgetInfo(UI.gui)\n    if not hover then --文本检查\n        local srcText = UI.GetInputText(id)\n        local text = tonumber(srcText)\n        if text == nil then\n            UI.TextInputRestore(id)\n        elseif text ~= nil then\n            local Format = tostring(text)\n            if Format ~= srcText then\n                UI.SetInputText(id, Format)\n            end\n        end\n    end\n    GuiTooltip(UI.gui, GameTextGetTranslatedOrNot(\"$menuoptions_reset_keyboard\"), \"\")\n	if right_click then\n        UI.TextInputRestore(id)\n		GamePlaySound(\"data/audio/Desktop/ui.bank\", \"ui/button_click\", GameGetCameraPos())\n	end\nend\n\nlocal leftMargin = 65\nlocal ColTwoMargin = 87\n\nlocal function NewDamageSettingLine(str, id)\n    str = GameTextGetTranslatedOrNot(str)\n	\n	GuiLayoutBeginHorizontal(UI.gui, 0, 0, true, 0, 2)\n    local w = GuiGetTextDimensions(UI.gui, str)\n	GuiZSetForNextWidget(UI.gui, UI.GetZDeep())\n    GuiText(UI.gui, leftMargin - w, 0, str)\n    local ShowText = UI.GetInputText(id)\n	\n    if ShowText == \"\" or ShowText == nil then\n        ShowText = \" \"\n    else\n        ShowText = \"x\" .. ShowText\n    end\n	\n	local ShowW = GuiGetTextDimensions(UI.gui, ShowText)\n	ShowW = GuiGetTextDimensions(UI.gui, ShowText)\n    GuiRGBAColorSetForNextWidget(UI.gui, 255, 222, 173, 255)\n	\n	GuiZSetForNextWidget(UI.gui, UI.GetZDeep())\n	GuiText(UI.gui, 5, 0, ShowText)\n	\n    GuiZSetForNextWidget(UI.gui, UI.GetZDeep())\n    NumInput(id, ColTwoMargin - ShowW, 0, 90, -1, \"1\")\n	\n	GuiLayoutEnd(UI.gui)\nend\n\nlocal function GetDmgNum(id)\n	return tonumber(UI.GetInputText(id) or \"1\") or 1\nend\n\nlocal OnPlayerPosSpwan = function ()\n	local player = GetPlayer()\n	local px,py = EntityGetTransform(player)\n	local dummy = EntityLoad(\"mods/wand_editor/files/entity/dummy_target.xml\", px, py)\n	local shift = InputIsKeyDown(Key_LSHIFT) or InputIsKeyDown(Key_RSHIFT)\n	if not shift then\n		local dmgModel = EntityGetFirstComponentIncludingDisabled(dummy, \"DamageModelComponent\")\n		local SetDmgMult = Curry(ComponentObjectSetValue2, 4)(dmgModel, \"damage_multipliers\")\n		SetDmgMult(\"projectile\", GetDmgNum(\"DummyDmgProj\"))\n		SetDmgMult(\"explosion\", GetDmgNum(\"DummyDmgExpl\"))\n		SetDmgMult(\"electricity\", GetDmgNum(\"DummyDmgElectric\"))\n		SetDmgMult(\"slice\", GetDmgNum(\"DummyDmgSlice\"))\n		SetDmgMult(\"drill\", GetDmgNum(\"DummyDmgDrill\"))\n		SetDmgMult(\"fire\", GetDmgNum(\"DummyDmgFire\"))\n		SetDmgMult(\"ice\", GetDmgNum(\"DummyDmgIce\"))\n		SetDmgMult(\"melee\", GetDmgNum(\"DummyDmgMelee\"))\n		SetDmgMult(\"holy\", GetDmgNum(\"DummyDmgHoly\"))\n		SetDmgMult(\"healing\", GetDmgNum(\"DummyDmgHeal\"))\n		SetDmgMult(\"physics_hit\", GetDmgNum(\"DummyDmgPhysicsHit\"))\n		SetDmgMult(\"curse\", GetDmgNum(\"DummyDmgCurse\"))\n		SetDmgMult(\"radioactive\", GetDmgNum(\"DummyDmgToxic\"))\n		SetDmgMult(\"poison\", GetDmgNum(\"DummyDmgPoison\"))\n		GamePrint(GameTextGet(\"$wand_editor_options_spwan_dummy_done_tips\"))\n	else\n		GamePrint(GameTextGet(\"$wand_editor_options_spwan_dummy_done_tips_default\"))\n	end\nend\n\nfunction SpwanDummyCB(_, right_click, _, _, this_enable)\n	if right_click then\n        OnPlayerPosSpwan()\n		GamePlaySound(\"data/audio/Desktop/ui.bank\", \"ui/button_click\", GameGetCameraPos())\n	end\n    if not this_enable then\n        return\n    end\n    UI.ScrollContainer(\"SpwanDummyOptions\", 20, 64, 268, 210, 2, 2)\n    UI.AddAnywhereItem(\"SpwanDummyOptions\", function()\n        GuiLayoutBeginVertical(UI.gui, 0, 0, true)\n        NewDamageSettingLine(\"$wand_editor_dmg_proj\", \"DummyDmgProj\")\n        NewDamageSettingLine(\"$wand_editor_dmg_expl\", \"DummyDmgExpl\")\n        NewDamageSettingLine(\"$wand_editor_dmg_electric\", \"DummyDmgElectric\")\n        NewDamageSettingLine(\"$wand_editor_dmg_slice\", \"DummyDmgSlice\")\n		NewDamageSettingLine(\"$wand_editor_dmg_drill\", \"DummyDmgDrill\")\n		NewDamageSettingLine(\"$wand_editor_dmg_fire\", \"DummyDmgFire\")\n		NewDamageSettingLine(\"$wand_editor_dmg_ice\", \"DummyDmgIce\")\n        NewDamageSettingLine(\"$wand_editor_dmg_melee\", \"DummyDmgMelee\")\n        NewDamageSettingLine(\"$wand_editor_dmg_holy\", \"DummyDmgHoly\")\n        NewDamageSettingLine(\"$wand_editor_dmg_heal\", \"DummyDmgHeal\")\n        NewDamageSettingLine(\"$wand_editor_dmg_physics_hit\", \"DummyDmgPhysicsHit\")\n        NewDamageSettingLine(\"$wand_editor_dmg_curse\", \"DummyDmgCurse\")\n        NewDamageSettingLine(\"$wand_editor_dmg_toxic\", \"DummyDmgToxic\")\n        NewDamageSettingLine(\"$wand_editor_dmg_poison\", \"DummyDmgPoison\")\n		\n		GuiLayoutAddVerticalSpacing(UI.gui, 18)\n        GuiLayoutBeginHorizontal(UI.gui, 0, 0, true, 4, 2)\n\n		GuiZSetForNextWidget(UI.gui, UI.GetZDeep())\n		local spwan_left_click, spwan_right_click = GuiButton(UI.gui,UI.NewID(\"SettingDummySpwan\"),3,0,GameTextGet(\"$wand_editor_options_spwan_dummy\"))\n        GuiTooltip(UI.gui, GameTextGet(\"$wand_editor_options_spwan_dummy_tips\"), \"\")\n\n		if spwan_left_click then\n            UI.MiscEventFn[\"MoveDummyFn\"] = function()\n                local ALTLockCamera = InputIsKeyDown(Key_LALT) or InputIsKeyDown(Key_RALT)\n				local player = GetPlayer()\n				if ALTLockCamera and player then\n                    local PSPComp = EntityGetFirstComponentIncludingDisabled(player, \"PlatformShooterPlayerComponent\")\n                    if PSPComp then\n                        local center_camera_on_this_entity = ComponentGetValue2(PSPComp, \"center_camera_on_this_entity\")\n                        if center_camera_on_this_entity then\n                            ComponentSetValue2(PSPComp, \"center_camera_on_this_entity\", false)\n							GlobalsSetValue(ModID..\"CameraLocked\", \"1\")\n                        end\n                    end\n                elseif not ALTLockCamera and player then\n					local PSPComp = EntityGetFirstComponentIncludingDisabled(player, \"PlatformShooterPlayerComponent\")\n                    if PSPComp then\n                        local center_camera_on_this_entity = ComponentGetValue2(PSPComp, \"center_camera_on_this_entity\")\n                        if not center_camera_on_this_entity then\n                            ComponentSetValue2(PSPComp, \"center_camera_on_this_entity\", true)\n							GlobalsSetValue(ModID..\"CameraLocked\", \"0\")\n                        end\n                    end\n				end\n                local click = InputIsMouseButtonDown(Mouse_right)\n                if click or GameIsInventoryOpen() then --右键取消，或打开物品栏取消\n                    UI.MiscEventFn[\"MoveDummyFn\"] = nil\n                    UI.OnMoveImage(\"MoveDummy\", 0, 0, \"mods/wand_editor/files/entity/dummy/dummy_target.png\", true, 1.5)\n                    return\n                end\n                UI.OnMoveImage(\"MoveDummy\", 0, 0, \"mods/wand_editor/files/entity/dummy/dummy_target.png\", false, 1.5,UI.GetZDeep() - 114514)\n                local LeftClick = InputIsMouseButtonDown(Mouse_left)\n                if LeftClick then\n					if player then\n						local PSPComp = EntityGetFirstComponentIncludingDisabled(player, \"PlatformShooterPlayerComponent\")\n						if PSPComp then\n							local center_camera_on_this_entity = ComponentGetValue2(PSPComp, \"center_camera_on_this_entity\")\n							if not center_camera_on_this_entity then\n                                ComponentSetValue2(PSPComp, \"center_camera_on_this_entity\", true)\n								GlobalsSetValue(ModID..\"CameraLocked\", \"0\")\n							end\n						end\n					end\n					local px, py = DEBUG_GetMouseWorld()\n                    local dummy = EntityLoad(\"mods/wand_editor/files/entity/dummy_target.xml\", px, py)\n					local shift = InputIsKeyDown(Key_LSHIFT) or InputIsKeyDown(Key_RSHIFT)\n                    if not shift then\n                        local dmgModel = EntityGetFirstComponentIncludingDisabled(dummy, \"DamageModelComponent\")\n                        local SetDmgMult = Curry(ComponentObjectSetValue2, 4)(dmgModel, \"damage_multipliers\")\n                        SetDmgMult(\"projectile\", GetDmgNum(\"DummyDmgProj\"))\n                        SetDmgMult(\"explosion\", GetDmgNum(\"DummyDmgExpl\"))\n                        SetDmgMult(\"electricity\", GetDmgNum(\"DummyDmgElectric\"))\n                        SetDmgMult(\"slice\", GetDmgNum(\"DummyDmgSlice\"))\n                        SetDmgMult(\"drill\", GetDmgNum(\"DummyDmgDrill\"))\n                        SetDmgMult(\"fire\", GetDmgNum(\"DummyDmgFire\"))\n                        SetDmgMult(\"ice\", GetDmgNum(\"DummyDmgIce\"))\n                        SetDmgMult(\"melee\", GetDmgNum(\"DummyDmgMelee\"))\n                        SetDmgMult(\"holy\", GetDmgNum(\"DummyDmgHoly\"))\n                        SetDmgMult(\"healing\", GetDmgNum(\"DummyDmgHeal\"))\n                        SetDmgMult(\"physics_hit\", GetDmgNum(\"DummyDmgPhysicsHit\"))\n                        SetDmgMult(\"curse\", GetDmgNum(\"DummyDmgCurse\"))\n                        SetDmgMult(\"radioactive\", GetDmgNum(\"DummyDmgToxic\"))\n                        SetDmgMult(\"poison\", GetDmgNum(\"DummyDmgPoison\"))\n                        GamePrint(GameTextGet(\"$wand_editor_options_spwan_dummy_done_tips\"))\n                    else\n						GamePrint(GameTextGet(\"$wand_editor_options_spwan_dummy_done_tips_default\"))\n                    end\n                    UI.OnMoveImage(\"MoveDummy\", 0, 0, \"mods/wand_editor/files/entity/dummy/dummy_target.png\", true, 1.5)\n					UI.MiscEventFn[\"MoveDummyFn\"] = nil\n					return\n                end\n            end\n		end\n        if spwan_right_click then\n            OnPlayerPosSpwan()\n			GamePlaySound(\"data/audio/Desktop/ui.bank\", \"ui/button_click\", GameGetCameraPos())\n		end\n		GuiZSetForNextWidget(UI.gui, UI.GetZDeep())\n		local del_left_click = GuiButton(UI.gui,UI.NewID(\"SettingDummyDel\"),3,0,GameTextGet(\"$wand_editor_options_del_dummy\"))\n		if del_left_click then\n            local t = EntityGetWithTag(\"polymorphable_NOT\")\n			for _,v in pairs(t)do\n				if EntityGetName(v) == \"wand_editor_dummy_target\" then\n					EntityKill(v)\n				end\n			end\n		end\n        GuiTooltip(UI.gui, GameTextGet(\"$wand_editor_options_del_dummy_tips\"), \"\")\n\n		GuiZSetForNextWidget(UI.gui, UI.GetZDeep())\n		local reset_left_click = GuiButton(UI.gui,UI.NewID(\"SettingDummyReset\"),3,0,GameTextGet(\"$wand_editor_options_reset_options\"))\n		if reset_left_click then\n			UI.TextInputRestore(\"DummyDmgProj\")\n			UI.TextInputRestore(\"DummyDmgExpl\")\n			UI.TextInputRestore(\"DummyDmgElectric\")\n			UI.TextInputRestore(\"DummyDmgSlice\")\n			UI.TextInputRestore(\"DummyDmgDrill\")\n			UI.TextInputRestore(\"DummyDmgFire\")\n			UI.TextInputRestore(\"DummyDmgIce\")\n			UI.TextInputRestore(\"DummyDmgMelee\")\n			UI.TextInputRestore(\"DummyDmgHoly\")\n			UI.TextInputRestore(\"DummyDmgHeal\")\n			UI.TextInputRestore(\"DummyDmgPhysicsHit\")\n			UI.TextInputRestore(\"DummyDmgCurse\")\n			UI.TextInputRestore(\"DummyDmgToxic\")\n			UI.TextInputRestore(\"DummyDmgPoison\")\n		end\n        GuiLayoutEnd(UI.gui)\n        GuiLayoutEnd(UI.gui)\n    end)\n	if not UI.MiscEventFn[\"MoveDummyFn\"] then\n		UI.DrawScrollContainer(\"SpwanDummyOptions\", false, true)\n	end\nend\n"
_TWWE_VFS["mods/wand_editor/files/gui/ToggleOptions.lua"] = "dofile_once(\"mods/wand_editor/files/misc/bygoki/lib/helper.lua\")\nlocal Nxml = dofile_once(\"mods/wand_editor/files/libs/nxml.lua\")\nlocal fastConcatStr = Cpp.ConcatStr\nlocal old_thousands_separator = thousands_separator\nlocal thousands_separator = function(num)\n	if num > 1e15 then\n		return string.lower(tostring(num))\n	else\n		return old_thousands_separator(string.format(\"%.2f\", num))\n	end\nend\n\nlocal function get_screen_position(x, y)\n	local screen_width, screen_height = GuiGetScreenDimensions(UI.gui)\n	local camera_x, camera_y = GameGetCameraPos()\n	local res_width = MagicNumbersGetValue(\"VIRTUAL_RESOLUTION_X\")\n	local res_height = MagicNumbersGetValue(\"VIRTUAL_RESOLUTION_Y\")\n	local ax = (x - camera_x) / res_width * screen_width\n	local ay = (y - camera_y) / res_height * screen_height\n	return ax + screen_width * 0.5, ay + screen_height * 0.5\nend\n\nfunction DrawDamageInfo()\n    local function InfoCallBack(s_x, s_y)\n        GuiLayoutBeginLayer(UI.gui)\n        GuiLayoutBeginVertical(UI.gui, s_x, s_y + 5, true)\n        GuiLayoutAddVerticalSpacing(UI.gui, 5)\n\n        local player_projectiles = EntityGetWithTag(\"projectile_player\") or {}\n        local highest_projectile_damage = 0\n        local highest_damage_projectile = nil\n        local total_projectile_damage = 0\n        local total_projectiles = #player_projectiles\n        for k, v in pairs(player_projectiles) do\n            local projectile = EntityGetFirstComponent(v, \"ProjectileComponent\")\n            if projectile then\n                local damage = ComponentGetValue2(projectile, \"damage\") * 25\n                if damage > highest_projectile_damage then\n                    highest_damage_projectile = v\n                    highest_projectile_damage = damage\n                end\n                total_projectile_damage = total_projectile_damage + damage\n            end\n        end\n        GuiOptionsAddForNextWidget(UI.gui, GUI_OPTION.Align_HorizontalCenter)\n		GuiZSetForNextWidget(UI.gui,UI.GetZDeep())\n        GuiText(UI.gui, 0, 0, GameTextGet(\"$wand_editor_total_proj_dmg\") .. thousands_separator(total_projectile_damage))\n\n        GuiOptionsAddForNextWidget(UI.gui, GUI_OPTION.Align_HorizontalCenter)\n		GuiZSetForNextWidget(UI.gui,UI.GetZDeep())\n        GuiText(UI.gui, 0, 0, GameTextGet(\"$wand_editor_total_proj\") .. tostring(total_projectiles))\n\n        local highest_dps = GlobalsGetValue(ModID .. \"highest_dps\", \"\") --渲染dps数据，伤害来自假人\n        if #highest_dps > 0 then\n            GuiOptionsAddForNextWidget(UI.gui, GUI_OPTION.Align_HorizontalCenter)\n			GuiZSetForNextWidget(UI.gui,UI.GetZDeep())\n            GuiText(UI.gui, 0, 0, GameTextGet(\"$wand_editor_dps\") .. highest_dps)\n        end\n\n        local total_damage = GlobalsGetValue(ModID .. \"total_damage\", \"\") --渲染总伤数据，伤害来自假人\n        if #total_damage > 0 then\n            GuiOptionsAddForNextWidget(UI.gui, GUI_OPTION.Align_HorizontalCenter)\n			GuiZSetForNextWidget(UI.gui,UI.GetZDeep())\n            GuiText(UI.gui, 0, 0, GameTextGet(\"$wand_editor_total_damage\") .. total_damage)\n        end\n\n        GuiLayoutEnd(UI.gui)\n        GuiLayoutEndLayer(UI.gui)\n        if highest_damage_projectile ~= nil then\n            local esx, esy = get_screen_position(EntityGetTransform(highest_damage_projectile))\n			GuiZSetForNextWidget(UI.gui,UI.GetZDeep())\n            GuiText(UI.gui, esx, esy, thousands_separator(highest_projectile_damage))\n        end\n    end\n	GuiZSetForNextWidget(UI.gui,UI.GetZDeep())\n	UI.MoveImageButton(\"DamageInfoMoveBTN\",UI.ScreenWidth * 0.5,2,\"mods/wand_editor/files/gui/images/move.png\",InfoCallBack,function ()\n		GuiTooltip(UI.gui,GameTextGet(\"$wand_editor_picker_desc\"),\"\")\n	end)\nend\n\nlocal function PickerGap(gap)\n	return 19 + gap * 22\nend\n\nlocal AutoUpdateNoPrint = function (str)\n	if not ModSettingGet(ModID..\".auto_update\") then\n		GamePrint(str)\n	end\nend\n\nlocal WriteUpdateFilePath = \"mods/wand_editor_new_ver.zip\"\n\nlocal UpdateFn = function(_click, isBtn)\n    local function ClickSoundUpdate()\n        if not ModSettingGet(ModID .. \".auto_update\") then\n            GamePlaySound(\"data/audio/Desktop/ui.bank\", \"ui/button_click\", GameGetCameraPos())\n        end\n    end\n    local click = _click\n    if not isBtn then\n        click = click or ModSettingGet(ModID .. \".auto_update\")\n    end\n    local RequestRestart\n    if not ModSettingGet(ModID .. \".auto_update\") then\n        RequestRestart = click\n    elseif ModSettingGet(ModID .. \".auto_update\") and UI.UserData[\"LastUpdateErrorTime\"] then --自动重置\n        local _, _, _, hour = GameGetDateAndTimeLocal()\n        if hour - UI.UserData[\"LastUpdateErrorTime\"] > 0 then                              --请求失败就隔一个小时自动重新请求/下载一次\n            RequestRestart = true\n        end\n    end\n    if ModSettingGet(ModID .. \".auto_update\") and isBtn then\n        RequestRestart = _click\n    end\n    if UI.UserData[\"UpdateCheck\"] == \"new\" then --如果确认有新版本\n        if click and UI.UserData[\"DownloadThreadHandle\"] == nil and UI.UserData[\"DownloadStatus\"] == nil or (RequestRestart and UI.UserData[\"DownloadStatus\"] == \"error\") then\n            local function DownloadNewVer(verStr, intptr, GithubFlag)\n                local link = \"/KagiamamaHIna/Wand-Editor/releases/download/v\" ..\n                    verStr .. \"/wand_editor_v\" .. verStr .. \".zip\"\n                local https = require(\"ssl.https\")\n                local ltn12 = require(\"ltn12\")\n                require(\"github_mirror\")\n                local Cpp = require(\"WandEditorDll\")\n                local code = 0\n                local Returns\n                -- 准备sink，用于收集响应体数据\n                local response_chunks = {}\n                local response_sink = ltn12.sink.table(response_chunks)\n                local function sinkfn(chunk, err) --闭包函数和指针实现数据共享和下载的数据量读取\n                    if chunk then\n                        Cpp.SetIntPtrV(intptr, Cpp.GetIntPtrV(intptr) + #chunk)\n                    end\n                    return response_sink(chunk, err)\n                end\n                local function RequestGithub()\n                    Returns = { https.request {\n                        url = GitHub_Link(link),\n                        sink = sinkfn,\n                    } }\n                end\n                local function RequestMirror()\n                    Returns = { https.request {\n                        url = CurrentMirror(link),\n                        sink = sinkfn,\n                    } }\n                end\n                if GithubFlag then --根据谁先获得，来进行数据获取执行\n                    RequestGithub()\n                else\n                    RequestMirror()\n                end\n                code = Returns[2]\n                if code ~= 200 then --请求另外一个\n                    Cpp.SetIntPtrV(intptr, 0) --上一个请求失败了，这里我觉得要重置一下计数器\n                    if GithubFlag then --反过来\n                        RequestMirror()\n                    else\n                        RequestGithub()\n                    end\n                    code = Returns[2]\n                end\n                return response_chunks, code\n            end\n\n            UI.UserData[\"SizeIntPtr\"] = Cpp.NewIntPtr(0)\n            local runner = effil.thread(DownloadNewVer)\n			--因为我发行的版本号都是有规则的，所以可以这么干 UI.UserData[\"UpdateDataVer\"]\n            UI.UserData[\"DownloadThreadHandle\"] = runner(UI.UserData[\"UpdateDataVer\"], UI.UserData[\"SizeIntPtr\"], UI.UserData[\"GetForGithub\"])\n            UI.UserData[\"DownloadStatus\"] = \"download\"\n            ClickSoundUpdate()\n\n            UI.MiscEventFn[\"UpdateFn\"] = function()\n                if UI.UserData[\"DownloadThreadHandle\"] and UI.UserData[\"DownloadStatus\"] == \"download\" then\n                    local handle = UI.UserData[\"DownloadThreadHandle\"]\n                    local status = handle:status()\n                    if status ~= \"completed\" then --判断线程是否执行完毕\n                        return\n                    end\n                    local response_chunks, code = handle:get()\n                    if code == 200 then                     --执行完毕的时候，并且页面请求正常\n                        local file = io.open(WriteUpdateFilePath, \"wb\")\n                        for _, chunk in pairs(effil.dump(response_chunks)) do --将二进制数据写入文件\n                            file:write(chunk)\n                        end\n                        file:close()\n                        UI.UserData[\"DownloadStatus\"] = \"done\"\n                        AutoUpdateNoPrint(GameTextGet(\"$wand_editor_new_ver_done_tip\"))\n                        UI.UserData[\"LastUpdateErrorTime\"] = nil\n                    else\n                        UI.UserData[\"DownloadStatus\"] = \"error\"\n                        AutoUpdateNoPrint(GameTextGet(\"$wand_editor_new_ver_failed_tip\"))\n                        if ModSettingGet(ModID .. \".auto_update\") then\n                            local _, _, _, hour = GameGetDateAndTimeLocal()\n                            UI.UserData[\"LastUpdateErrorTime\"] = hour\n                        else\n                            UI.UserData[\"LastUpdateErrorTime\"] = nil\n                        end\n                    end\n                    UI.UserData[\"DownloadThreadHandle\"] = nil --已经完成了，可以移除\n                    UI.MiscEventFn[\"UpdateFn\"] = nil\n                end\n            end\n        end\n    end\n    local function RequestDefine(GithubFlag)\n        local address = \"/KagiamamaHIna/Wand-Editor/refs/heads/main/files/libs/define.lua\" --合并主分支的时候记得改\n        local https = require(\"ssl.https\")\n        require(\"github_mirror\")\n        local result\n        if GithubFlag then\n            result = { https.request(GitHub_Link(address, true)) }\n        else\n            result = { https.request(CurrentMirror(address, true)) }\n        end\n        return unpack(result)\n    end\n    if (click and UI.UserData[\"UpdateCheck\"] == nil) or (RequestRestart and UI.UserData[\"UpdateCheck\"] == \"error\") then\n        local runner = effil.thread(RequestDefine)\n        local runner2 = effil.thread(RequestDefine)\n        UI.UserData[\"UpdateThreadHandles\"] = { runner(false), runner2(true) }\n        UI.UserData[\"UpdateCheck\"] = \"testing\"\n        ClickSoundUpdate()\n        UI.MiscEventFn[\"UpdateCheckFn\"] = function() --分离方便检测\n            if UI.UserData[\"UpdateThreadHandles\"] and UI.UserData[\"UpdateCheck\"] == \"testing\" then\n                local handles = UI.UserData[\"UpdateThreadHandles\"]\n                local status = handles[1]:status() or handles[2]:status()\n                if status ~= \"completed\" then\n                    return\n                end\n                local handle1 = handles[1]\n                local handle2 = handles[2]\n                local handle\n                local _, code1 = handle1:get()\n                local _, code2 = handle2:get()\n\n                if handle1:status() == \"completed\" then\n                    if code1 == 200 then\n                        handle = handle1\n                        UI.UserData[\"GetForGithub\"] = false\n                    end\n                else\n                    if code2 == 200 then\n                        handle = handle2\n                        UI.UserData[\"GetForGithub\"] = true\n                    end\n                end\n                local text, code\n                if handle == nil or (code1 ~= 200 and code2 ~= 200) then --完全失败\n                    code = false\n                else\n                    text, code = handle:get()\n                end\n\n                if code == 200 then --200代表请求正确\n                    local fn = loadstring(text)\n                    local env = {}\n                    setfenv(fn, env)() --设置环境执行以获得版本信息\n                    local numList = split(env.ModVersion or \"\", \".\")\n                    local LocalNumList = split(ModVersion, \".\")\n                    local newFlag = true\n                    if env.ModVersion == ModVersion then --检查两个字符串是否相等\n                        newFlag = false\n                    end\n                    if newFlag then --不相等的情况下进一步检查\n                        local Size = #numList\n                        if Size < #LocalNumList then --取大的\n                            Size = #LocalNumList\n                        end\n                        for i = Size, 1, -1 do\n                            local LocalNum = tonumber(LocalNumList[i]) or 0\n                            local num = tonumber(numList[i]) or 0\n                            if LocalNum > num then --大到小检查，只要我们有一个大于对面的则认为是最新版\n                                newFlag = false\n                                break\n                            end\n                        end\n                    end\n					if env.NoRewriteList ~= nil then--如果是空就用本地的\n						NoRewriteList = env.NoRewriteList\n					end\n                    if newFlag then\n                        UI.UserData[\"UpdateCheck\"] = \"new\"\n                        UI.UserData[\"UpdateDataVer\"] = env.ModVersion\n                    else --如果一致，则认为是最新版\n                        UI.UserData[\"UpdateCheck\"] = \"latest\"\n                    end\n                    AutoUpdateNoPrint(GameTextGet(\"$wand_editor_check_done_tip\"))\n                else\n                    UI.UserData[\"UpdateCheck\"] = \"error\"\n                    AutoUpdateNoPrint(GameTextGet(\"$wand_editor_check_failed_tip\"))\n                    if ModSettingGet(ModID .. \".auto_update\") then\n                        local _, _, _, hour = GameGetDateAndTimeLocal()\n                        UI.UserData[\"LastUpdateErrorTime\"] = hour\n                    else\n                        UI.UserData[\"LastUpdateErrorTime\"] = nil\n                    end\n                end\n                UI.MiscEventFn[\"UpdateCheckFn\"] = nil\n                UI.UserData[\"UpdateThreadHandles\"] = nil --垃圾回收\n            end\n        end\n    end\nend\n\nlocal UpdateClick = function(click)\n    UpdateFn(click, true)\nend\n\nlocal ThreadUnZip = function(effil, _WriteUpdateFilePath, _NoRewriteList)\n    local Cpp = require(\"WandEditorDll\")\n	local fastConcatStr = Cpp.ConcatStr\n    local function RemoveExclude(t, ExcludeList) --深拷贝并移除不要移除的路径与文件\n        local result = {}\n        for k, v in pairs(t) do\n            result[k] = {}\n            for _, v2 in pairs(v) do\n                local flag\n                for _, ExcludeStr in pairs(ExcludeList) do\n                    flag = string.find(v2, ExcludeStr, 1, true)\n                    if flag then\n                        break\n                    end\n                end\n                if flag == nil then\n                    result[k][#result[k] + 1] = v2\n                end\n            end\n        end\n        return result\n    end\n\n    local function IncludePathRemove(t, newVerT) --生成一个需要删除的文件的表\n        local result = {}\n        local MorePath = {}\n        for _, v in pairs(t.Path) do --构造多出来的路径表\n            local flag = false\n            for _, p in pairs(newVerT.Path) do\n                p = p:gsub(\"wand_editor/cache/\", \"\")\n                if v == p then --如果遍历到有，则代表存在，不需要删除\n                    flag = true\n                    break\n                end\n            end\n            if not flag then\n                MorePath[#MorePath + 1] = v\n            end\n        end\n        local tempList = {}\n        for _, v in pairs(t.File) do --移除多余路径下的多余文件\n            local flag\n            for _, p in pairs(MorePath) do\n                flag = string.find(v, p, 1, true)\n                if flag then\n                    break\n                end\n            end\n            if flag == nil then\n                tempList[#tempList + 1] = v\n            end\n        end\n        for _, v in pairs(tempList) do --移除多余文件\n            local flag\n            for _, p in pairs(newVerT.File) do\n                p = p:gsub(\"wand_editor/cache/\", \"\")\n                if v == p then --如果遍历到有，则代表存在，不需要删除\n                    flag = true\n                    break\n                end\n            end\n            if not flag then\n                result[#result + 1] = v\n            end\n        end\n        for _, v in pairs(MorePath) do --深拷贝合并\n            result[#result + 1] = v\n        end\n        return result\n    end\n	local function AddOriginalPath(t)\n		local newTable = {}\n		\n		for k,t1 in pairs(t) do\n			local key = \"O_\"..k\n			newTable[key] = {}\n			for k2,v in pairs(t1) do\n				newTable[key][k2] = v:gsub(\"wand_editor/cache/\", \"\")\n			end\n		end\n		for k,v in pairs(newTable) do\n			t[k] = v\n		end\n		return t\n	end\n    local function ForThreadSerializeTable(tbl, indent)\n        indent = indent or \"\"\n        local parts = {}\n        local partsKey = 1\n\n        local _tostr = tostring\n        local _type = type\n        local is_array = #tbl > 0 or tbl[0] ~= nil\n        for k, v in pairs(tbl) do\n            local key\n            if is_array and _type(k) == \"number\" then\n                key = fastConcatStr(\"[\", _tostr(k), \"] = \")\n            else\n                key = fastConcatStr(\"[\\\"\", _tostr(k), \"\\\"] = \")\n            end\n\n            if _type(v) == \"table\" then\n                parts[partsKey] = fastConcatStr(indent, key, \"{\\n\")\n                parts[partsKey + 1] = ForThreadSerializeTable(v, indent .. \"    \")\n                parts[partsKey + 2] = fastConcatStr(indent, \"},\\n\")\n                partsKey = partsKey + 3\n            elseif _type(v) == \"boolean\" or _type(v) == \"number\" then\n                parts[partsKey] = fastConcatStr(indent, key, _tostr(v), \",\\n\")\n                partsKey = partsKey + 1\n            else\n                parts[partsKey] = string.format(\"%s%s%q,\\n\", indent, key, v)\n                partsKey = partsKey + 1\n            end\n        end\n        return table.concat(parts)\n    end\n	--代码逻辑开始\n	Cpp.RemoveAll(\"mods/wand_editor/cache/wand_editor/\")\n	Cpp.Remove(\"mods/wand_editor/cache/CurrentPath.lua\")\n	Cpp.Remove(\"mods/wand_editor/cache/NewPaths.lua\")\n	local NoRewriteList = effil.dump(_NoRewriteList)\n    local PreDeletePaths = RemoveExclude(Cpp.GetDirectoryPathAll(\"mods/wand_editor/\"), NoRewriteList)\n	Cpp.Uncompress(_WriteUpdateFilePath, \"mods/wand_editor/cache/\")\n	Cpp.Remove(WriteUpdateFilePath)     --移除压缩文件\n	local newPaths = AddOriginalPath(Cpp.GetDirectoryPathAll(\"mods/wand_editor/cache/wand_editor/\"))\n	PreDeletePaths = IncludePathRemove(PreDeletePaths, newPaths)\n	local file = io.open(\"mods/wand_editor/cache/PreDeletePaths.lua\", \"w\") --将需要删除的数据写入文件\n	file:write(\"return {\\n\" .. ForThreadSerializeTable(PreDeletePaths, \"\") .. \"}\")\n	file:close()\n\n	for _,v in pairs(newPaths.O_Path) do--提前创建文件夹\n		Cpp.CreateDirs(v)\n	end\n\n	file = io.open(\"mods/wand_editor/cache/NewPaths.lua\", \"w\") --将新路径写入文件\n	file:write(\"return {\\n\" .. ForThreadSerializeTable(newPaths, \"\") .. \"}\")\n    file:close()\nend\n\n--检查下载完成与解压完成\nlocal UncompressNewZipFn = function()\n	if UI.UserData[\"DownloadStatus\"] == \"done\" and ModSettingGet(ModID .. \".auto_update\") then\n        if Cpp.PathExists(WriteUpdateFilePath) and UI.UserData[\"UncompressUpdateZip\"] == nil and UI.UserData[\"UncompressUpdateHandle\"] == nil then\n            local runner = effil.thread(ThreadUnZip)\n			UI.UserData[\"UncompressUpdateHandle\"] = runner(effil, WriteUpdateFilePath, NoRewriteList)--多线程执行防止主线程阻塞\n        elseif UI.UserData[\"UncompressUpdateHandle\"] then\n            local handle = UI.UserData[\"UncompressUpdateHandle\"]\n			if handle:status() == \"completed\" then\n				UI.UserData[\"UncompressUpdateZip\"] = true\n                UI.UserData[\"UncompressUpdateHandle\"] = nil\n				--三个需要提前覆写的\n                RewriteBinFile(\"mods/wand_editor/init.lua\", \"mods/wand_editor/cache/wand_editor/init.lua\")\n                RewriteBinFile(\"mods/wand_editor/settings.lua\", \"mods/wand_editor/cache/wand_editor/settings.lua\")\n				RewriteBinFile(\"mods/wand_editor/unsafeFn.lua\", \"mods/wand_editor/cache/wand_editor/unsafeFn.lua\")\n				local file = io.open(\"mods/wand_editor/cache/UpdateFlag\", \"w\") --新建标记文件\n				file:close()\n			end\n		end\n	end\nend\n\nUI.MiscEventFn[\"ListenerAutoUpdate\"] = function()\n    if UI.UserData[\"UpdateCheck\"] == \"latest\" or (UI.UserData[\"DownloadStatus\"] == \"done\" and UI.UserData[\"UncompressUpdateZip\"]) then\n        --如果检查完成且是最新版/下载完成且预处理完成，移除这两个检查用的，停止检查\n        UI.MiscEventFn[\"AutoUpdate\"] = nil\n        UI.MiscEventFn[\"ListenerAutoUpdate\"] = nil\n    end\n\n    if GetPlayer() and UI.UserData[\"LinstenerUpdateStart\"] == nil then\n        UI.UserData[\"LinstenerUpdateStart\"] = true\n    end\n\n    --UI.UserData[\"DownloadStatus\"] = \"done\"--调试用\n    --未知原因，疑似太早执行会造成主线程堵塞，然后卡至请求结束，缓一段时间到玩家生成就没有此现象\n    if not GetPlayer() and UI.UserData[\"LinstenerUpdateStart\"] == nil and not ModSettingGet(ModID .. \".auto_update\") then\n        if UI.MiscEventFn[\"AutoUpdate\"] then\n            UI.MiscEventFn[\"AutoUpdate\"] = nil\n        end\n        return\n    end\n    if UI.MiscEventFn[\"AutoUpdate\"] == nil and ModSettingGet(ModID .. \".auto_update\") then\n        UI.MiscEventFn[\"AutoUpdate\"] = function() --增加检测更新的函数\n            UpdateFn(true, false)\n            --自动检测是否下载完成和是否需要解压\n            UncompressNewZipFn()\n        end\n    elseif UI.MiscEventFn[\"AutoUpdate\"] and not ModSettingGet(ModID .. \".auto_update\") then\n        UI.MiscEventFn[\"AutoUpdate\"] = nil\n    end\nend\n\nfunction ToggleOptionsCB(_, _, _, iy, this_enable)\n    if not this_enable then\n        return\n    end\n	UI.MoveImagePicker(\"ProtectionBlindness\", PickerGap(0), iy + 20, 8, 0, GameTextGet(\"$wand_editor_protection_blindness\"),\n        \"mods/wand_editor/files/gui/images/protection_blindness.png\", nil, nil, nil, true, true, true)\n	\n	UI.MoveImagePicker(\"ProtectionAll\", PickerGap(1), iy + 20, 8, 0, GameTextGet(\"$wand_editor_protection_all\"),\n		\"mods/wand_editor/files/gui/images/protection_all.png\", nil, nil, nil, true, true, true)\n\n	UI.MoveImagePicker(\"ProtectionPoly\", PickerGap(2), iy + 20, 8, 0, GameTextGet(\"$wand_editor_protection_poly\"),\n        \"mods/wand_editor/files/gui/images/protection_poly.png\", nil, nil, nil, true, true, true)\n	\n	local LockHPCB = function (_, LockHP_right_click)--右键使血量恢复至满血的实现\n			local player = GetPlayer()\n			if LockHP_right_click and player then\n            local damage_model = EntityGetFirstComponent(player, \"DamageModelComponent\")\n			local MaxHP\n            if damage_model then\n                MaxHP = ComponentGetValue2(damage_model, \"max_hp\")\n				if UI.UserData[\"LockHPValue\"] ~= nil then\n					UI.UserData[\"LockHPValue\"] = MaxHP\n				end\n				ComponentSetValue2(damage_model, \"hp\", MaxHP)\n			end\n		end\n	end\n	UI.MoveImagePicker(\"LockHP\", PickerGap(3), iy + 20, 8, 0, GameTextGet(\"$wand_editor_lock_hp\"),\n		\"mods/wand_editor/files/gui/images/lock_hp.png\", nil, LockHPCB, nil, true, true, true)\n\n	UI.MoveImagePicker(\"DamageInfo\", PickerGap(4), iy + 20, 8, 0, GameTextGet(\"$wand_editor_damage_info\"),\n		\"mods/wand_editor/files/gui/images/damage_info.png\", nil, nil, nil, true, true, true)\n\n	UI.MoveImagePicker(\"NoRecoil\", PickerGap(5), iy + 20, 8, 0, GameTextGet(\"$wand_editor_no_recoil\"),\n		\"mods/wand_editor/files/gui/images/no_recoil.png\", nil, nil, nil, true, true, true)\n\n	UI.MoveImagePicker(\"DisableParticles\", PickerGap(6), iy + 20, 8, 0, GameTextGet(\"$wand_editor_no_particles\"),\n		\"mods/wand_editor/files/gui/images/disable_particles.png\", nil, nil, nil, true, true, true)\n\n	UI.MoveImagePicker(\"DisableProj\", PickerGap(7), iy + 20, 8, 0, GameTextGet(\"$wand_editor_no_proj\"),\n		\"mods/wand_editor/files/gui/images/disable_projectiles.png\", nil, nil, nil, true, true, true)\n\n	UI.MoveImagePicker(\"DisablePlayerGravity\", PickerGap(8), iy + 20, 8, 0, GameTextGet(\"$wand_editor_disable_player_gravity\"),\n        \"mods/wand_editor/files/gui/images/disable_player_gravity.png\", nil, nil, nil, true, true, true)\n\n	UI.MoveImagePicker(\"UnlimitedSpells\", PickerGap(0), iy + 40, 8, 0, GameTextGet(\"$wand_editor_unlimited_spells\"),\n		\"mods/wand_editor/files/gui/images/unlimited_spells.png\", nil, nil, nil, true, true, true)\n\n	UI.MoveImagePicker(\"InfFly\", PickerGap(1), iy + 40, 8, 0, GameTextGet(\"$wand_editor_inf_fly\"),\n        \"mods/wand_editor/files/gui/images/inf_fly.png\", nil, nil, nil, true, true, true)\n\n	UI.MoveImagePicker(\"QuickTP\", PickerGap(2), iy + 40, 8, 0, GameTextGet(\"$wand_editor_tp\"),\n        \"mods/wand_editor/files/gui/images/tp.png\", nil, nil, nil, true, true, true)\n		\n	UI.MoveImagePicker(\"EditWandsEverywhere\", PickerGap(3), iy + 40, 8, 0,\n		GameTextGet(\"$wand_editor_edit_wands_everywhere\"),\n		\"mods/wand_editor/files/gui/images/edit_wands_everywhere.png\", nil, nil, nil, true, true, true)\n\n	UI.MoveImagePicker(\"AlwaysDrawWandEditBox\", PickerGap(4), iy + 40, 8, 0,\n		GameTextGet(\"$wand_editor_always_draw_wand_edit_box\"),\n		\"mods/wand_editor/files/gui/images/always_draw_wand_edit_box.png\", nil, nil, nil, true, true, true)\n--[[\n	UI.MoveImagePicker(\"KeyBoardInput\", PickerGap(5) + 1, iy + 40, 8, 0, GameTextGet(\"$wand_editor_keyboard_input\"),\n		\"mods/wand_editor/files/gui/images/keyboard_input.png\", nil, nil, nil, true, true, true)]]\n\n	UI.MoveImagePicker(\"DisableSpellWobble\", PickerGap(5), iy + 40, 8, 0,\n		GameTextGet(\"$wand_editor_disable_spell_wobble\"),\n        \"mods/wand_editor/files/gui/images/disable_spell_wobble.png\", nil, nil, nil, true, true, true)\n\n	UI.MoveImagePicker(\"DisableWandHistory\", PickerGap(6), iy + 40, 8, 0,\n		GameTextGet(\"$wand_editor_disable_wand_history\"),\n        \"mods/wand_editor/files/gui/images/disable_wand_history.png\", nil, nil, nil, true, true, true)\n	\n	UI.MoveImagePicker(\"DisableSpellHover\", PickerGap(7), iy + 40, 8, 0,\n		GameTextGet(\"$wand_editor_disable_spell_hover\"),\n        \"mods/wand_editor/files/gui/images/disable_spell_hover.png\", nil, nil, nil, true, true, true)\n\n	UI.MoveImagePicker(\".remove_lighting\", PickerGap(8), iy + 40, 8, 0,\n		GameTextGet(\"$wand_editor_remove_lighting\"),\n        \"mods/wand_editor/files/gui/images/remove_lighting.png\", nil, nil, nil, true, true, true)\n\n    local LabSettingKey = fastConcatStr(ModID , \"SpellLab\")\n    local SrcPlayerXKey = fastConcatStr(ModID , \"SpellLab_player_x\")\n	local SrcPlayerYKey = fastConcatStr(ModID , \"SpellLab_player_y\")\n    local LabStatus = ModSettingGet(LabSettingKey)\n	local HoverSpellLab = function ()\n        local tips\n        if LabStatus then\n            tips = GameTextGet(\"$wand_editor_spell_lab_button_leave\")\n        else\n            tips = GameTextGet(\"$wand_editor_spell_lab_button_enter\")\n        end\n		UI.tooltips(function ()\n			GuiText(UI.gui,0,0,tips)\n		end,nil,8)\n	end\n    local ClickSpellLab = function(left_click, right_click)\n        if left_click then\n            local player = GetPlayer()\n            if not LabStatus and player then --未开启的时候\n                local x, y = EntityGetTransform(player)\n                ModSettingSet(SrcPlayerXKey, x)\n                ModSettingSet(SrcPlayerYKey, y)\n                GameSetCameraPos(12200, -5900)\n                EntitySetTransform(player, 12200, -5900)\n            else --开启的时候\n                local x = ModSettingGet(SrcPlayerXKey) or 0\n                local y = ModSettingGet(SrcPlayerYKey) or 0\n                GameSetCameraPos(x, y)\n                EntitySetTransform(player, x, y)\n            end\n            LabStatus = not LabStatus\n            ModSettingSet(LabSettingKey, LabStatus)\n        end\n        if right_click and LabStatus then --用一种奇怪的方法规避内部检查\n            local list = EntityGetInRadiusWithTag(12200, -5900, 750, \"player_unit\")\n            if #list == 0 then\n				GamePrint(GameTextGet(\"$wand_editor_spell_lab_button_reset_error\"))\n				return\n			end\n            local GetResetCount = function()\n                local t = Cpp.GetDirectoryPath(\"mods/wand_editor/files/biome_impl/wand_lab/reset\")\n                return Cpp.PathGetFileName(t.File[1])\n            end\n            local AddResetCount = function()\n                local k = GetResetCount()\n				k = tonumber(k) + 1\n                local t = Cpp.GetDirectoryPath(\"mods/wand_editor/files/biome_impl/wand_lab/reset\")\n                Cpp.Rename(t.File[1], \"mods/wand_editor/files/biome_impl/wand_lab/reset/\" .. tostring(k))\n				Cpp.Rename(\"mods/wand_editor/files/biome_impl/wand_lab/reset_xml/\"..tostring(k-1),\"mods/wand_editor/files/biome_impl/wand_lab/reset_xml/\"..tostring(k))\n            end\n			local XmlSrcPath = \"mods/wand_editor/files/biome_impl/wand_lab/reset/\"\n            local ResetXml = UI.UserData[\"ResetXmlBuffer\"]\n            if ResetXml == nil then\n                ResetXml = Nxml.parse(ReadFileAll(\"mods/wand_editor/files/biome_impl/wand_lab/overwrite.xml\"))\n                for _, v in pairs(ResetXml.children) do\n                    if v.name == \"PixelSceneComponent\" then\n                        UI.UserData[\"ResetXmlPathBuffer\"] = v\n                        break\n                    end\n                end\n                UI.UserData[\"ResetXmlBuffer\"] = ResetXml\n            end\n			AddResetCount()\n			local count = GetResetCount()\n            UI.UserData[\"ResetXmlPathBuffer\"].attr.pixel_scene = XmlSrcPath..count\n			local file = io.open(\"mods/wand_editor/files/biome_impl/wand_lab/reset_xml/\"..tostring(count), \"w\") --将新内容写进文件中\n			file:write(tostring(ResetXml))\n			file:close()\n            local list = EntityGetInRadiusWithTag(12200, -5900, 530,\"polymorphable_NOT\")\n            for _, v in pairs(list) do\n                if EntityGetName(v) == \"wand_editor_dummy_target\" then\n                    EntityKill(v)\n                end\n            end\n            EntityLoad(\"mods/wand_editor/files/biome_impl/wand_lab/reset_xml/\" .. tostring(count), 12200, -5900)\n			GamePrint(GameTextGet(\"$wand_editor_spell_lab_button_reset_done\"))\n		end\n    end\n    if not LabStatus then\n        GuiOptionsAddForNextWidget(UI.gui, GUI_OPTION.DrawSemiTransparent)\n    end\n	GuiZSetForNextWidget(UI.gui, UI.GetZDeep())\n	UI.MoveImageButton(\"EnterSpellLab\", PickerGap(0), iy + 60, \"mods/wand_editor/files/gui/images/wand_lab_icon.png\",nil,HoverSpellLab,ClickSpellLab,nil,true)\n		\n    local UpdateHover = function()\n        local _, _, hover = GuiGetPreviousWidgetInfo(UI.gui)\n		UI.tooltips(function() --根据状态改变悬浮提示\n			GuiText(UI.gui, 0, 0, GameTextGet(\"$wand_editor_check_update\"))\n			if UI.UserData[\"UpdateCheck\"] == nil then\n				GuiText(UI.gui, 0, 0, GameTextGet(\"$wand_editor_no_checking\"))\n			elseif UI.UserData[\"UpdateCheck\"] == \"testing\" then\n				GuiText(UI.gui, 0, 0, GameTextGet(\"$wand_editor_checking\"))\n			elseif UI.UserData[\"UpdateCheck\"] == \"error\" then\n				GuiText(UI.gui, 0, 0, GameTextGet(\"$wand_editor_connect_failed\"))\n			elseif UI.UserData[\"UpdateCheck\"] == \"latest\" then\n				GuiText(UI.gui, 0, 0, GameTextGet(\"$wand_editor_latest_ver\"))\n			elseif UI.UserData[\"UpdateCheck\"] == \"new\" then\n				if UI.UserData[\"DownloadStatus\"] == nil then\n					GuiText(UI.gui, 0, 0, GameTextGet(\"$wand_editor_new_ver\", UI.UserData[\"UpdateDataVer\"], ModVersion))\n                elseif UI.UserData[\"DownloadStatus\"] == \"download\" then\n					local SizeString = \"? nullptr error\"\n					if UI.UserData[\"SizeIntPtr\"] then\n						SizeString = Compose(ToBytesString, Cpp.GetIntPtrV)(UI.UserData[\"SizeIntPtr\"])\n					end\n					GuiText(UI.gui, 0, 0, GameTextGet(\"$wand_editor_new_ver_downloading\", SizeString))\n				elseif UI.UserData[\"DownloadStatus\"] == \"error\" then\n                    GuiText(UI.gui, 0, 0, GameTextGet(\"$wand_editor_new_ver_failed\"))\n					if UI.UserData[\"SizeIntPtr\"] then\n						Cpp.Free(UI.UserData[\"SizeIntPtr\"])\n						UI.UserData[\"SizeIntPtr\"] = nil\n					end\n				elseif UI.UserData[\"DownloadStatus\"] == \"done\" then\n                    GuiText(UI.gui, 0, 0, GameTextGet(\"$wand_editor_download_complete\"))\n					if UI.UserData[\"SizeIntPtr\"] then\n						Cpp.Free(UI.UserData[\"SizeIntPtr\"])\n						UI.UserData[\"SizeIntPtr\"] = nil\n					end\n				end\n			end\n		end, nil, 8)\n        if hover then\n            if UI.UserData[\"DownloadStatus\"] == \"done\" and InputIsKeyDown(Key_c) then\n                Cpp.SetClipboard(Cpp.CurrentPath() .. \"/mods\")\n            end\n        end\n    end\n	UI.MoveImagePicker(\"SpellDepotHistoryMode\", PickerGap(1), iy + 60, 8, 0,\n		GameTextGet(\"$wand_editor_spell_depot_history\"),\n        \"mods/wand_editor/files/gui/images/spell_depot_history.png\", nil, nil, nil, true, true, true)\n\n	UI.MoveImagePicker(\"SpellInfMana\", PickerGap(2), iy + 60, 8, 0,\n		GameTextGet(\"$wand_editor_spell_inf_mana\"),\n        \"mods/wand_editor/files/gui/images/inf_mana.png\", nil, nil, nil, true, true, true)\n	\n	GuiZSetForNextWidget(UI.gui, UI.GetZDeep())\n	UI.MoveImageButton(\"UpdateMod\", PickerGap(3), iy + 60, \"mods/wand_editor/files/gui/images/update_mod.png\", nil, UpdateHover, UpdateClick, nil, true)\n    local reloadText = GameTextGet(\"$wand_editor_reload_spell_data\")\n	if UI.GetPickerStatus(\"ReloadSpellData\") then\n		reloadText = reloadText ..\"\\n\".. GameTextGet(\"$menu_mods_help_paused\")\n	end\n    local ModAboutCB = function()\n        local _, _, hover = GuiGetPreviousWidgetInfo(UI.gui)\n        UI.tooltips(function()\n            GuiText(UI.gui, 0, 0, ModVersion)\n            GuiText(UI.gui, 0, 0, ModLink)\n            GuiText(UI.gui, 0, 0, GameTextGet(\"$wand_editor_about_copy_link_tips\"))\n            if Cpp.PathExists(\"mods/wand_editor/cache/avatar.png\") then\n                GuiImage(UI.gui, UI.NewID(\"AuthorAvatar\"), 0, 0, \"mods/wand_editor/cache/avatar.png\", 1,\n                    0.5 / UI.GetScale())\n            end\n            if ModSettingGet(ModID .. \"YukimiAvailable\") and ModSettingGet(ModID .. \"YukimiAvailableShow\") then\n                GuiText(UI.gui, 0, 0, GameTextGet(\"$wand_editor_yukimi_close\"))\n            elseif ModSettingGet(ModID .. \"YukimiAvailable\") and not ModSettingGet(ModID .. \"YukimiAvailableShow\") then\n                GuiText(UI.gui, 0, 0, GameTextGet(\"$wand_editor_yukimi_open\"))\n            end\n            if ModSettingGet(ModID .. \"YukimiAvailable\") and ModSettingGet(ModID .. \"YukimiAlways\") then\n                GuiText(UI.gui, 0, 0, GameTextGet(\"$wand_editor_always_yukimi_close\"))\n            elseif ModSettingGet(ModID .. \"YukimiAvailable\") and not ModSettingGet(ModID .. \"YukimiAlways\") then\n                GuiText(UI.gui, 0, 0, GameTextGet(\"$wand_editor_always_yukimi_open\"))\n            end\n        end, nil, 8)\n        if hover then\n            if InputIsKeyDown(Key_c) then\n                Cpp.SetClipboard(ModLink)\n            end\n        elseif not hover and UI.UserData[\"ModAboutConut\"] then\n            UI.UserData[\"ModAboutConut\"] = nil\n        end\n    end\n	local ModAboutClickCB = function (left_click, right_click)\n        if left_click and ModSettingGet(ModID .. \"YukimiAvailable\") == nil then\n            if UI.UserData[\"ModAboutConut\"] == nil then\n                UI.UserData[\"ModAboutConut\"] = 1\n            elseif UI.UserData[\"ModAboutConut\"] < 2 then\n                UI.UserData[\"ModAboutConut\"] = UI.UserData[\"ModAboutConut\"] + 1\n            else\n                ModSettingSet(ModID .. \"YukimiAvailable\", true)\n                ModSettingSet(ModID .. \"YukimiAvailableShow\", true)\n                ModSettingSet(ModID .. \"YukimiAlways\", false)\n                UI.UserData[\"ModAboutConut\"] = nil\n            end\n        end\n		if ModSettingGet(ModID .. \"YukimiAvailable\") and left_click and (InputIsKeyDown(Key_LSHIFT) or InputIsKeyDown(Key_RSHIFT)) then\n			ModSettingSet(ModID..\"YukimiAlways\",not ModSettingGet(ModID..\"YukimiAlways\"))		\n		end\n		if ModSettingGet(ModID..\"YukimiAvailable\") and right_click then\n			ModSettingSet(ModID..\"YukimiAvailableShow\",not ModSettingGet(ModID..\"YukimiAvailableShow\"))\n		end\n	end\n	if ModSettingGet(\"wand_editor.cache_spell_data\") then\n		UI.MoveImagePicker(\"ReloadSpellData\", PickerGap(4), iy + 60, 8, 0, reloadText,\n        \"mods/wand_editor/files/gui/images/reload_spell_data.png\", nil, nil, nil, true, true, true)\n\n		GuiZSetForNextWidget(UI.gui, UI.GetZDeep())\n		UI.MoveImageButton(\"ModAbout\", PickerGap(5), iy + 60, \"mods/wand_editor/files/gui/images/about.png\", nil, ModAboutCB, ModAboutClickCB, nil, true)\n	else\n		GuiZSetForNextWidget(UI.gui, UI.GetZDeep())\n		UI.MoveImageButton(\"ModAbout\", PickerGap(4), iy + 60, \"mods/wand_editor/files/gui/images/about.png\", nil, ModAboutCB, ModAboutClickCB, nil, true)\n	end\n\nend\n"
_TWWE_VFS["mods/wand_editor/files/gui/WandBuilder.lua"] = "dofile_once(\"data/scripts/gun/procedural/gun_procedural.lua\")\nlocal this = UI\nlocal sliderModeKey = ModID .. \"sliderMode\"\nlocal sliderMode = ModSettingGet(sliderModeKey)\nif sliderMode == nil then\n    ModSettingSet(sliderModeKey, false)\n	sliderMode = false\nend\nlocal function GetValue(id, isDecimal)\n    local num\n	if sliderMode then\n		num = UI.GetSliderValue(id..\"WBSlider\")\n    else\n		num = tonumber(UI.GetInputText(id))\n	end\n    if num == nil then\n        return \"\"\n    end\n    if isDecimal then\n        return num\n    end\n    return math.floor(num)\nend\n\nlocal function GetValueSToF(id, isDecimal)\n    local num\n	if sliderMode then\n		num = UI.GetSliderValue(id..\"WBSlider\")\n    else\n		num = tonumber(UI.GetInputText(id) or \"\")\n	end\n    if num == nil then\n        return \"\"\n    end\n	if not sliderMode then\n		num = math.floor(num*60 + 0.5)\n	end\n    if isDecimal then\n        return num\n    end\n    return math.floor(num)\nend\n\n---通过设置参数获得一根新法杖\n---@return Wand\nlocal function GetWand()\n	local shuffleBool = UI.GetCheckboxEnable(\"shuffle_builder\")\n	local IsShuffle\n    if shuffleBool then\n        IsShuffle = 1\n    else\n        IsShuffle = 0\n    end\n    local GetDeckCapacity = Compose(tonumber, UI.GetInputText)\n	if sliderMode then\n		GetDeckCapacity = function (str)\n			return math.floor(UI.GetSliderValue(str..\"WBSlider\"))\n		end\n	end\n	local NewWand = {\n		item_name = nil,\n		mana_charge_speed = GetValue(\"manachargespeed_builder\"),      					--回蓝速度\n		mana_max = GetValue(\"manamax_builder\"),               							--蓝上限\n		fire_rate_wait = GetValueSToF(\"castdelay_builder\"),         					--施放延迟\n		reload_time = GetValueSToF(\"rechargetime_builder\"),            					--充能延迟\n		deck_capacity = GetDeckCapacity(\"capacity_builder\"),          					--容量\n		spread_degrees = GetValue(\"spread_builder\",true),         						--散射\n		shuffle_deck_when_empty = IsShuffle, 											--是否乱序\n		speed_multiplier = GetValue(\"speed_multiplier_builder\", true),       			--初速度加成\n		mana = GetValue(\"manamax_builder\"),                   							--蓝\n		actions_per_round = GetValue(\"cast_builder\"),      								--施放数\n		shoot_pos = { x = 0, y = 0 }, 													--发射位置\n		sprite_file = nil,            													--贴图\n		sprite_pos = { x = 0, y = 0 } 													--精灵图偏移\n    }\n    SetRandomSeed(Compose(EntityGetTransform, GetPlayer)())\n	--这里是改的原版生成贴图的代码\n	local gun_in_wand_space = {}\n	gun_in_wand_space.fire_rate_wait = clamp(((NewWand[\"fire_rate_wait\"] + 5) / 7)-1, 0, 4)\n	gun_in_wand_space.actions_per_round = clamp(NewWand[\"actions_per_round\"]-1,0,2)\n	gun_in_wand_space.shuffle_deck_when_empty = clamp(NewWand[\"shuffle_deck_when_empty\"], 0, 1)\n	gun_in_wand_space.deck_capacity = clamp( (NewWand[\"deck_capacity\"]-3)/3, 0, 7 ) -- TODO\n	gun_in_wand_space.spread_degrees = clamp( ((NewWand[\"spread_degrees\"] + 5 ) / 5 ) - 1, 0, 2 )\n	gun_in_wand_space.reload_time = clamp(((NewWand[\"reload_time\"] + 5) / 25) - 1, 0, 2)\n	\n	local best_wand = nil\n	local best_score = 1000\n	for k, wand in pairs(wands) do\n		local score = WandDiff(gun_in_wand_space, wand)\n		if (score <= best_score) then\n			best_wand = wand\n			best_score = score\n			-- just randomly return one of them...\n			if (score == 0 and Random(0, 100) < 33) then\n				best_wand = wand\n				break\n			end\n		end\n	end\n	NewWand.shuffle_deck_when_empty = shuffleBool\n	NewWand.sprite_pos.x = best_wand.grip_x\n	NewWand.sprite_pos.y = best_wand.grip_y\n	NewWand.shoot_pos.x = best_wand.tip_x - best_wand.grip_x\n	NewWand.shoot_pos.y = best_wand.tip_y - best_wand.grip_y\n    NewWand.sprite_file = best_wand.file\n	return NewWand\nend\n\nlocal function NewSlider(id,x,y,text,value_min, value_max, value_default, value_display_multiplier, value_formatting, width)\n	id = id..\"WBSlider\"\n    UI.Slider(id, x, y, text, value_min, value_max, value_default, value_display_multiplier, value_formatting, width)\n    local _, _, hover= GuiGetPreviousWidgetInfo(UI.gui)\n	local XOffset = UI.UserData[\"WandBuilderXOffset\"] or 0\n	GuiTooltip(this.gui,GameTextGet(\"$menuoptions_reset_keyboard\")..\"\\n\"..GameTextGet(\"$wand_editor_wand_builder_slider_tips\"),\"\",XOffset+2)\n\n    local function MoveSlider()\n        local left = InputIsKeyDown(Key_KP_MINUS) or InputIsKeyDown(Key_LEFT) or InputIsKeyDown(Key_MINUS)\n        local right = InputIsKeyDown(Key_KP_PLUS) or InputIsKeyDown(Key_RIGHT) or InputIsKeyDown(Key_EQUALS)\n        local num = 1\n        if InputIsKeyDown(Key_LSHIFT) or InputIsKeyDown(Key_RSHIFT) then --按下shift一次移动更多\n            num = num * 10\n        end\n        if left then\n            UI.SetSliderValue(id, UI.GetSliderValue(id) - num)\n        elseif right then\n            UI.SetSliderValue(id, UI.GetSliderValue(id) + num)\n        end\n    end\n    if hover then\n        local hasPush = InputIsKeyDown(Key_KP_PLUS) or InputIsKeyDown(Key_KP_MINUS) or InputIsKeyDown(Key_LEFT) or\n            InputIsKeyDown(Key_RIGHT) or InputIsKeyDown(Key_MINUS) or InputIsKeyDown(Key_EQUALS)\n        if UI.UserData[\"PushFrBuilderID\" .. id] == nil then --如果在悬浮，就分配一个帧检测时间\n            UI.UserData[\"PushFrBuilderID\" .. id] = 30\n        else\n            if hasPush then                                        --如果按了\n                if UI.UserData[\"PushFrBuilderID\" .. id] == 30 then --按的第一下\n                    MoveSlider()\n                end\n                if UI.UserData[\"PushFrBuilderID\" .. id] ~= 0 then\n                    UI.UserData[\"PushFrBuilderID\" .. id] = UI.UserData[\"PushFrBuilderID\" .. id] - 1\n                else --如果到了0\n                    MoveSlider()\n                end\n            else\n                UI.UserData[\"PushFrBuilderID\" .. id] = 30 --如果不按就重置时间\n            end\n        end\n    elseif UI.UserData[\"PushFrBuilderID\" .. id] then --如果未悬浮就设为空\n        UI.UserData[\"PushFrBuilderID\" .. id] = nil\n    end\n	return width,hover\nend\n\nlocal function NumInput(id, x, y, w, l, str, allow)\n	l = -1--不管显示会不会超出了，直接自动分配可输入字符\n	allow = Default(allow, \"1234567890.-\")\n    UI.TextInput(id, x, y, w, l, str, allow)\n    local _,right_click, hover,_,_,width = GuiGetPreviousWidgetInfo(UI.gui)\n    if not hover then --文本检查\n        local srcText = UI.GetInputText(id)\n        local text = tonumber(srcText)\n        if text == nil then\n            UI.TextInputRestore(id)\n        elseif text ~= nil then\n            local Format = tostring(text)\n            if Format ~= srcText then\n                UI.SetInputText(id, Format)\n            end\n        end\n    end\n    GuiTooltip(UI.gui, GameTextGetTranslatedOrNot(\"$menuoptions_reset_keyboard\"), \"\",UI.UserData[\"WandBuilderXOffset\"])\n    if right_click then\n        UI.TextInputRestore(id)\n        GamePlaySound(\"data/audio/Desktop/ui.bank\", \"ui/button_click\", GameGetCameraPos())\n    end\n	return width,hover\nend\n\nfunction WandBuilderCB(_, _, _, _, this_enable)\n    if not this_enable then\n        return\n    end\n	UI.ScrollContainer(\"WandBuilder\", 20, 64, 268, 160, 2, 2)\n	UI.AddAnywhereItem(\"WandBuilder\", function()\n        local function GetValueStr(id, format)\n            local num\n			if sliderMode then\n				num = UI.GetSliderValue(id..\"WBSlider\")\n			else\n				num = UI.GetInputText(id)\n			end\n            if num == nil or tonumber(num) == nil or num == \"\" then\n                return \"\"\n            end\n            if format then\n                return string.format(format, tonumber(num))\n            end\n            return Compose(tostring, math.floor)(num)\n        end\n        local function GetValueStrSToF(id, format)\n            local num\n			if sliderMode then\n				num = tonumber(UI.GetSliderValue(id..\"WBSlider\") or \"\")\n			else\n                num = tonumber(UI.GetInputText(id) or \"\")\n			end\n            if num == nil then\n                return \"\"\n            end\n			if not sliderMode then\n				num = math.floor(num*60 + 0.5)\n			end\n			if format then\n                return string.format(format, num)\n			end\n			return Compose(tostring, math.floor)(num)\n		end\n		local leftMargin = 65\n        local ColTwoMargin = 73\n		if sliderMode then\n			ColTwoMargin = 103\n		end\n		local function NewLine(str, ShowText, fn, ShowFrTran)\n			str = GameTextGetTranslatedOrNot(str)\n			GuiLayoutBeginHorizontal(this.gui, 0, 0, true, 0, 2)\n			local w = GuiGetTextDimensions(this.gui, str)\n			GuiZSetForNextWidget(this.gui, this.GetZDeep() - 1)\n            GuiText(this.gui, leftMargin - w, 0, str)\n			if ShowText == \"\" or ShowText == nil then\n                ShowText = \" \"\n			elseif ShowFrTran then\n				local num = tonumber(ShowText)\n				local SecondWithSign = Compose(NumToWithSignStr, tonumber, FrToSecondStr)\n				if num then\n					ShowText = SecondWithSign(num) .. \"s(\" .. ShowText .. \"f)\"\n				end\n			end\n\n			GuiZSetForNextWidget(this.gui, this.GetZDeep() - 1)\n            local wdith,hover = fn(3)\n			GuiZSetForNextWidget(this.gui, this.GetZDeep() - 1)\n            GuiRGBAColorSetForNextWidget(this.gui, 255, 222, 173, 255)\n			if hover then\n				local textW = GuiGetTextDimensions(this.gui,ShowText)\n				UI.UserData[\"WandBuilderXOffset\"] = textW\n			end\n			GuiText(this.gui, ColTwoMargin-wdith, 0, ShowText)\n			GuiLayoutEnd(this.gui)\n		end\n        GuiLayoutBeginVertical(this.gui, 0, 0, true)\n		local shuffle\n		if UI.GetCheckboxEnable(\"shuffle_builder\") then\n			shuffle = GameTextGet(\"$menu_yes\")\n		else\n			shuffle = GameTextGet(\"$menu_no\")\n		end\n		NewLine(\"$inventory_shuffle\", shuffle, function(ShowW)\n            UI.checkbox(\"shuffle_builder\", ShowW + 2, 1, \"\", nil, nil, nil, nil)\n			if sliderMode then\n				return 25,false\n            else\n				return 24.5,false\n			end\n		end)\n		NewLine(\"$inventory_actionspercast\", GetValueStr(\"cast_builder\"), function(ShowW)\n			if sliderMode then\n            	return NewSlider(\"cast_builder\", ShowW, 1, \"\", 1, 50, 1, 1, \" \", 100)\n            else\n				return NumInput(\"cast_builder\", ShowW + 2, 1, 70, 9, \"1\", \"1234567890\")\n			end\n		end)\n        NewLine(\"$inventory_castdelay\", GetValueStrSToF(\"castdelay_builder\"), function(ShowW)\n			if sliderMode then\n            	return NewSlider(\"castdelay_builder\", ShowW, 1, \"\", -21, 240, 10, 1, \" \", 100)\n			else\n				return NumInput(\"castdelay_builder\", ShowW + 2, 1, 70, 7, \"0.17\", \"1234567890.-\")\n			end\n		end, true)\n        NewLine(\"$inventory_rechargetime\", GetValueStrSToF(\"rechargetime_builder\"), function(ShowW)\n			if sliderMode then\n            	return NewSlider(\"rechargetime_builder\", ShowW, 1, \"\", -21, 240, 20, 1, \" \", 100)\n			else\n	            return NumInput(\"rechargetime_builder\", ShowW + 2, 1, 70, 7, \"0.33\", \"1234567890.-\")\n			end\n		end, true)\n        NewLine(\"$inventory_manamax\", GetValueStr(\"manamax_builder\"), function(ShowW)\n			if sliderMode then\n            	return NewSlider(\"manamax_builder\", ShowW, 1, \"\", 0, 20000, 2000, 1, \" \", 100)\n			else\n				return NumInput(\"manamax_builder\",ShowW + 2, 1, 70,9,\"2000\",\"1234567890\")\n			end\n		end)\n        NewLine(\"$inventory_manachargespeed\", GetValueStr(\"manachargespeed_builder\"), function(ShowW)\n			if sliderMode then\n            	return NewSlider(\"manachargespeed_builder\", ShowW, 1, \"\", 0, 20000, 500, 1, \" \", 100)\n			else\n				return NumInput(\"manachargespeed_builder\",ShowW + 2, 1, 70,9,\"500\",\"1234567890\")\n			end\n		end)\n        NewLine(\"$inventory_capacity\", GetValueStr(\"capacity_builder\"), function(ShowW)\n			if sliderMode then\n				return NewSlider(\"capacity_builder\", ShowW, 1, \"\", 1, 50, 26, 1, \" \", 100)\n			else\n				return NumInput(\"capacity_builder\", ShowW + 2, 0, 70, 9, \"26\", \"1234567890\")\n			end\n		end)\n        NewLine(\"$inventory_spread\", GetValueStr(\"spread_builder\") .. GameTextGet(\"$wand_editor_deg\"), function(ShowW)\n			if sliderMode then\n				return NewSlider(\"spread_builder\", ShowW, 1, \"\", -30, 30, 0, 1,\" \",100)\n			else\n				return NumInput(\"spread_builder\", ShowW + 2, 0, 70, 9, \"0\", \"1234567890.-\")\n			end\n        end)\n        NewLine(\"$wand_editor_speed_multiplier\", \"x\" .. GetValueStr(\"speed_multiplier_builder\", \"%.8f\"), function(ShowW)\n			if sliderMode then\n			    return NewSlider(\"speed_multiplier_builder\", ShowW, 1, \"\", 0, 2, 1, 0.0001, \" \", 100)\n			else\n				return NumInput(\"speed_multiplier_builder\", ShowW + 2, 0, 70, 10, \"1\", \"1234567890.-\")\n			end\n			--GuiTooltip(this.gui,GameTextGetTranslatedOrNot(\"$menuoptions_reset_keyboard\"),\"\")\n        end)\n		local UpdateImage\n		if UI.GetCheckboxEnable(\"update_image_builder\") then\n			UpdateImage = GameTextGet(\"$menu_yes\")\n		else\n			UpdateImage = GameTextGet(\"$menu_no\")\n		end\n		NewLine(\"$wand_editor_update_wand_image\", UpdateImage, function(ShowW)\n            UI.checkbox(\"update_image_builder\", ShowW + 2, 1, \"\", nil, nil, nil, nil)\n			if sliderMode then\n				return 25,false\n            else\n				return 24.5,false\n			end\n		end)\n		\n		GuiLayoutAddVerticalSpacing(this.gui, 18)\n        GuiLayoutBeginHorizontal(this.gui, 0, 0, true, 4, 2)\n        GuiZSetForNextWidget(this.gui, this.GetZDeep()-1)\n        if GuiButton(this.gui, this.NewID(\"wand_builder_botton\"), 4, 0, GameTextGet(\"$wand_editor_wand_builder_botton\")) then\n			InitWand(GetWand(),nil,Compose(EntityGetTransform, GetPlayer)())\n		end\n		GuiZSetForNextWidget(this.gui, this.GetZDeep()-1)\n		local click = GuiButton(this.gui, this.NewID(\"wand_builder_held_botton\"), 4, 0, GameTextGet(\"$wand_editor_wand_builder_held_botton\"))\n		GuiTooltip(this.gui,GameTextGet(\"$wand_editor_wand_builder_held_botton_tip\"),\"\")\n        if click then\n            local wand = Compose(GetEntityHeldWand, GetPlayer)()\n			if wand ~= nil then\n                local wandData = GetWandData(wand)\n				if InputIsKeyDown(Key_LSHIFT) or InputIsKeyDown(Key_RSHIFT) then\n                    this.SetCheckboxEnable(\"shuffle_builder\", wandData.shuffle_deck_when_empty)\n					if sliderMode then\n						local SetSlider = function (id, v)\n							this.SetSliderValue(id..\"WBSlider\", v)\n						end\n						SetSlider(\"cast_builder\", wandData.actions_per_round)\n						SetSlider(\"castdelay_builder\", wandData.fire_rate_wait)\n						SetSlider(\"rechargetime_builder\", wandData.reload_time)\n						SetSlider(\"manamax_builder\", wandData.mana_max)\n						SetSlider(\"manachargespeed_builder\", wandData.mana_charge_speed)\n						SetSlider(\"capacity_builder\", wandData.deck_capacity)\n						SetSlider(\"spread_builder\", wandData.spread_degrees)\n						SetSlider(\"speed_multiplier_builder\", wandData.speed_multiplier)\n                    else\n						this.SetInputText(\"cast_builder\", wandData.actions_per_round)\n						this.SetInputText(\"castdelay_builder\", FrToSecondStr(wandData.fire_rate_wait))\n						this.SetInputText(\"rechargetime_builder\", FrToSecondStr(wandData.reload_time))\n						this.SetInputText(\"manamax_builder\", wandData.mana_max)\n						this.SetInputText(\"manachargespeed_builder\", wandData.mana_charge_speed)\n						this.SetInputText(\"capacity_builder\", tostring(wandData.deck_capacity))\n						this.SetInputText(\"spread_builder\", wandData.spread_degrees)\n						this.SetInputText(\"speed_multiplier_builder\", wandData.speed_multiplier)\n					end\n                else\n					InitWand(wandData,nil,Compose(EntityGetTransform, GetPlayer)())\n				end\n			end\n		end\n		GuiZSetForNextWidget(this.gui, this.GetZDeep()-1)\n        if GuiButton(this.gui, this.NewID(\"wand_builder_update_botton\"), 4, 0, GameTextGet(\"$wand_editor_wand_builder_update_botton\")) then\n            local wand = Compose(GetEntityHeldWand, GetPlayer)()\n            if wand ~= nil then\n                local wandData = GetWandData(wand)\n                local new = GetWand()\n                for i = new.deck_capacity + 1, #wandData.spells.spells do --删除越界法术\n                    wandData.spells.spells[i] = nil\n                end\n                new.spells = wandData.spells --更新法杖的时候不要更新法术啥的\n                if this.GetCheckboxEnable(\"update_image_builder\") then\n                    InitWand(new, wand)\n                else\n                    new.sprite_file = wandData.sprite_file\n                    new.shoot_pos = wandData.shoot_pos\n                    new.sprite_pos = wandData.sprite_pos\n                    new.spells = wandData.spells\n                    InitWand(new, wand)\n                end\n                this.OnceCallOnExecute(function()\n                    RefreshHeldWands()\n                end)\n            end\n        end\n        GuiZSetForNextWidget(this.gui, this.GetZDeep() - 1)\n        local modeStr\n		local modeTipsStr\n		if sliderMode then\n            modeStr = GameTextGet(\"$wand_editor_wand_builder_slider_mode\")\n            modeTipsStr = GameTextGet(\"$wand_editor_wand_builder_slider_mode_tips\")\n        else\n            modeStr = GameTextGet(\"$wand_editor_wand_builder_input_box_mode\")\n			modeTipsStr = GameTextGet(\"$wand_editor_wand_builder_input_box_mode_tips\")\n		end\n        local modeSwtich = GuiButton(this.gui, this.NewID(\"wand_builder_update_switch\"), 4, 0, modeStr)\n        GuiTooltip(this.gui, modeTipsStr)\n		if modeSwtich then\n            sliderMode = not sliderMode\n			ModSettingSet(sliderModeKey, sliderMode)\n		end\n        GuiLayoutEnd(this.gui)\n        GuiLayoutEnd(this.gui)\n	end)\n    UI.DrawScrollContainer(\"WandBuilder\", false, true)\n	\n    local flag, wand = pcall(GetWand)\n    if flag then\n		GuiZSetForNextWidget(UI.gui,UI.GetZDeep())\n		GuiImage(UI.gui,UI.NewID(\"wand_build_preview_images\"),20,UI.GetScrollHeight(\"WandBuilder\") + UI.GetScrollY(\"WandBuilder\") + 5,wand.sprite_file,1,3,0)\n	end\nend\n"
_TWWE_VFS["mods/wand_editor/files/gui/WandContainer.lua"] = "dofile_once(\"mods/wand_editor/files/libs/fn.lua\")\ndofile_once(\"data/scripts/gun/gun_enums.lua\")\nlocal fastConcatStr = Cpp.ConcatStr\n---@class Gui\nlocal this = UI\nlocal L_tostring = tostring\nlocal L_GuiZSetForNextWidget = GuiZSetForNextWidget\nlocal L_GuiImage = GuiImage\nlocal L_GuiGetPreviousWidgetInfo = GuiGetPreviousWidgetInfo\nlocal L_GuiOptionsAddForNextWidget = GuiOptionsAddForNextWidget\nlocal L_GuiLayoutBeginHorizontal = GuiLayoutBeginHorizontal\nlocal L_GuiText = GuiText\nlocal L_GuiImageButton = GuiImageButton\nlocal L_GuiLayoutEnd = GuiLayoutEnd\nlocal L_SpellTypeBG = SpellTypeBG\n\nlocal CopiedData = false\n\nlocal CheckSpells = function(str)\n    if HasEnds(str) then\n        return false\n    end\n    local CheckFn = loadstring(str)\n    if type(CheckFn) ~= \"function\" then\n        return false\n    end\n    local fn = setfenv(CheckFn, {}) --设置环境 防止注入攻击\n    local flag, result = pcall(fn)\n    if not flag then\n        return false\n    end\n    if type(result) ~= \"table\" then\n        return false\n    end\n	return true,result\nend\n\nlocal function SpellPicker(ScrollID, id, wandEntity, wandData, spellData, k, v, isAlways)\n	local BaseName = \"Spell\"\n	if isAlways then\n		BaseName = fastConcatStr(BaseName, \"_isAlways\")\n	end\n	local srcDeep = this.GetZDeep()\n    local BGAlpha = 1\n	if not isAlways then\n		local BGAlphaKey = fastConcatStr(id , \"LastWandContHoverAlpha\" , L_tostring(k))\n		local BGAlphaMaxKey = fastConcatStr(id , \"LastWandContHoverMax\" , L_tostring(k))\n		if this.UserData[fastConcatStr(id , \"LastWandContHover\" , L_tostring(k))] and v == \"nil\" and (not isAlways) then --法术为空的时候才渐变\n			if this.UserData[BGAlphaKey] == nil then                                   --格子渐变实现\n				this.UserData[BGAlphaKey] = 1\n				this.UserData[BGAlphaMaxKey] = 0.6\n			elseif this.UserData[BGAlphaKey] > this.UserData[BGAlphaMaxKey] then\n				this.UserData[BGAlphaKey] = this.UserData[BGAlphaKey] - 0.015\n				this.UserData[BGAlphaMaxKey] = 0.6\n			else\n				this.UserData[BGAlphaKey] = this.UserData[BGAlphaKey] + 0.015\n				this.UserData[BGAlphaMaxKey] = 1\n			end\n			BGAlpha = this.UserData[BGAlphaKey]\n		else\n			this.UserData[BGAlphaKey] = nil\n			this.UserData[BGAlphaMaxKey] = nil\n		end\n	end\n\n	L_GuiZSetForNextWidget(this.gui, this.GetZDeep())\n    this.SetZDeep(this.GetZDeep() - 1)\n	\n	L_GuiImage(this.gui, this.NewID(fastConcatStr(id , BaseName, \"full_BG\" , L_tostring(k))), 0, 0,\n        \"data/ui_gfx/inventory/full_inventory_box.png\", BGAlpha, 1)\n	local click, _, hover, x, y,FullBoxW,FullBoxH = L_GuiGetPreviousWidgetInfo(this.gui)\n	local CacheKey = fastConcatStr(id, \"HoverCache\")\n	if this.UserData[CacheKey] == nil then\n		local scale = this.GetScale()\n		local _, my = InputGetMousePosOnScreen()\n		my = my / scale\n		local ScrollY = this.GetScrollY(ScrollID)\n		local ScrollH = this.GetScrollHeight(ScrollID)\n		local ScrollMarginY = this.GetScrollMY(ScrollID)\n        if ScrollY and ScrollMarginY and (my < ScrollY - ScrollMarginY or my > ScrollY + ScrollH + ScrollMarginY) then\n            this.UserData[CacheKey] = true\n        else\n			this.UserData[CacheKey] = this.UserData[CacheKey] or false\n        end\n		this.OnceCallOnExecute(function ()\n			this.UserData[CacheKey] = nil\n		end)\n	end\n	if this.UserData[CacheKey] then\n		click = false\n		hover = false\n	end\n\n	local highlight = false\n    if this.UserData[\"HasShiftClick\"][wandEntity] and this.UserData[\"HasShiftClick\"][wandEntity][1] == id and (not isAlways) then --判断是否要高亮\n        local HasShiftClick = this.UserData[\"HasShiftClick\"][wandEntity]\n        local min = HasShiftClick[2]\n        local max = HasShiftClick[3] or min\n        if max < min then --计算是否要高亮\n            if k >= max and k <= min then\n                highlight = true\n            end\n        else\n            if k >= min and k <= max then\n                highlight = true\n            end\n        end\n        if highlight then\n            L_GuiZSetForNextWidget(this.gui, this.GetZDeep())\n            this.SetZDeep(this.GetZDeep() - 1)\n            L_GuiImage(this.gui, this.NewID(fastConcatStr(id, \"hgBG\", L_tostring(k))), -22, 0,\n                \"mods/wand_editor/files/gui/images/highlight.png\", BGAlpha, 1)\n        end\n    end\n	if hover then\n		if isAlways then\n			if v ~= \"nil\" and not this.GetPickerStatus(\"DisableSpellHover\") then\n				this.BetterTooltips(function()\n					HoverDarwSpellText(this, v.id, spellData[v.id],nil, GameTextGet(\"$wand_editor_always\") .. L_tostring(k))\n				end, this.GetZDeep()-114514, 8, 26)\n			else\n				OldGuiTooltip(this.gui, GameTextGet(\"$wand_editor_always\") .. L_tostring(k), \"\")\n			end\n		else\n			if v ~= \"nil\" and not this.GetPickerStatus(\"DisableSpellHover\") then\n				this.BetterTooltips(function()\n					local text\n					if v.uses_remaining ~= -1 then\n						text = GameTextGet(\"$wand_editor_slot\",L_tostring(k))..\" (\"..GameTextGet(\"$inventory_usesremaining\")..\" : \"..v.uses_remaining..\")\"\n					else\n						text = GameTextGet(\"$wand_editor_slot\",L_tostring(k))\n					end\n					HoverDarwSpellText(this, v.id, spellData[v.id],v.uses_remaining, text)\n				end,this.GetZDeep()-114514,8,26)\n			else\n                OldGuiTooltip(this.gui, GameTextGet(\"$wand_editor_slot\", L_tostring(k)), \"\")\n			end\n		end\n	end\n\n    if v ~= \"nil\" and spellData[v.id] ~= nil then --绘制法术与背景\n        L_GuiZSetForNextWidget(this.gui, this.GetZDeep())\n        this.SetZDeep(this.GetZDeep() - 1)\n		GuiOptionsAddForNextWidget(this.gui, GUI_OPTION.Layout_NoLayouting)\n        L_GuiImage(this.gui, this.NewID(fastConcatStr(id, BaseName, \"BG\", v.id, L_tostring(k))), x, y,\n			L_SpellTypeBG[spellData[v.id].type],\n            1, 1)\n		local _,_,_,thisImgX = GuiGetPreviousWidgetInfo(this.gui)\n        L_GuiZSetForNextWidget(this.gui, this.GetZDeep())\n        this.SetZDeep(this.GetZDeep() - 1)\n        if not this.GetPickerStatus(\"DisableSpellWobble\") then\n            L_GuiOptionsAddForNextWidget(this.gui, GUI_OPTION.DrawWobble)\n        end\n        L_GuiOptionsAddForNextWidget(this.gui, GUI_OPTION.AlwaysClickable)\n        GuiOptionsAddForNextWidget(this.gui, GUI_OPTION.Layout_NoLayouting)\n		local sw,sh = GuiGetImageDimensions(this.gui, spellData[v.id].sprite, 1)\n		\n        L_GuiImageButton(this.gui, this.NewID(fastConcatStr(id, BaseName, v.id, L_tostring(k))), x + (FullBoxW-sw)/2, y + (FullBoxH-sh)/2, \"\",\n            spellData[v.id].sprite)\n        if isAlways then\n            L_GuiZSetForNextWidget(this.gui, this.GetZDeep())\n            this.SetZDeep(this.GetZDeep() - 1)\n			GuiOptionsAddForNextWidget(this.gui, GUI_OPTION.Layout_NoLayouting)\n            L_GuiImage(this.gui, this.NewID(fastConcatStr(id, BaseName, \"Always\", v.id, L_tostring(k))), x+1, y,\n                \"mods/wand_editor/files/gui/images/always_icon.png\",\n                1, 1)\n        end\n        if not isAlways and v ~= \"nil\" and v.uses_remaining ~= -1 then\n            L_GuiZSetForNextWidget(this.gui, this.GetZDeep())\n            this.SetZDeep(this.GetZDeep() - 1)\n			GuiOptionsAddForNextWidget(this.gui, GUI_OPTION.Layout_NoLayouting)\n            L_GuiText(this.gui, x+2, y+2, L_tostring(v.uses_remaining), 1, \"data/fonts/font_small_numbers.xml\")\n        end\n		GuiAnimateBegin(this.gui)\n		GuiAnimateAlphaFadeIn(this.gui, UI.NewID(fastConcatStr(id , BaseName, \"SpellBGInvisibility\", L_tostring(k))), 0, 0, false)\n		L_GuiOptionsAddForNextWidget(this.gui,GUI_OPTION.Layout_NoLayouting)\n		L_GuiImage(this.gui, this.NewID(fastConcatStr(id , BaseName, \"full_BG_invisibility\" , L_tostring(k))), thisImgX, 0,\"data/ui_gfx/inventory/full_inventory_box.png\", BGAlpha, 1)\n		GuiAnimateEnd(this.gui)\n    end\n	if not isAlways then\n		this.UserData[fastConcatStr(id , \"LastWandContHover\" , L_tostring(k))] = hover\n        this.UserData[\"WandContainerHasHover\"] = this.UserData[\"WandContainerHasHover\"] or hover\n	end\n    if not hover then\n        this.SetZDeep(srcDeep) --恢复深度以解决奇怪深度问题\n        return\n    end\n	\n    if not isAlways then\n        local CurrentWand\n        if this.UserData[\"FixedWand\"] and this.UserData[\"HasShiftClick\"][this.UserData[\"FixedWand\"][2]] then --固定的法杖必须是有选框才能判定\n            CurrentWand = this.UserData[\"FixedWand\"][2]\n        else                                                                                           --否则就判断手持\n            local HeldWand = Compose(GetEntityHeldWand, GetPlayer)()\n            if HeldWand then\n                CurrentWand = HeldWand\n            end\n        end\n        if (InputIsKeyDown(Key_LALT) or InputIsKeyDown(Key_RALT)) and click and this.UserData[\"HasShiftClick\"][CurrentWand] then --批量添加始终\n            local CurrentData = GetWandData(CurrentWand)\n            local HasShiftClick = this.UserData[\"HasShiftClick\"][CurrentWand]\n            local min = HasShiftClick[2]\n            local max = HasShiftClick[3] or min\n            min = math.min(min, max)\n            max = math.max(HasShiftClick[2], max)\n            if min == max then --如果是单个选框的\n                local spell = GetSpellID(CurrentData, min)\n                if spell ~= \"nil\" then\n                    PushAlwaysSpell(CurrentData, spell.id)\n                    RemoveTableSpells(CurrentData, min)\n                    InitWand(CurrentData, CurrentWand)\n                end\n            else --反之就是多个\n                for i = min, max do\n                    local spell = GetSpellID(CurrentData, i)\n                    if spell ~= \"nil\" then\n                        PushAlwaysSpell(CurrentData, spell.id)\n                        RemoveTableSpells(CurrentData, i)\n                    end\n                end\n                InitWand(CurrentData, CurrentWand)\n            end\n            this.UserData[\"HasShiftClick\"][CurrentWand] = nil\n            this.OnceCallOnExecute(function()\n                RefreshHeldWands()\n            end)\n        elseif (InputIsKeyDown(Key_LALT) or InputIsKeyDown(Key_RALT)) and click and v ~= \"nil\" then --添加始终\n            PushAlwaysSpell(wandData, v.id)\n            RemoveTableSpells(wandData, k)\n            InitWand(wandData, wandEntity)\n            this.OnceCallOnExecute(function()\n                RefreshHeldWands()\n            end)\n        elseif (InputIsKeyDown(Key_LSHIFT) or InputIsKeyDown(Key_RSHIFT)) and click then --框选法术\n            local FixedWand\n            if this.UserData[\"FixedWand\"] then\n                FixedWand = this.UserData[\"FixedWand\"][2]\n            end\n            if this.UserData[\"HasShiftClick\"][wandEntity] == nil then\n                this.UserData[\"HasShiftClick\"][wandEntity] = { id, k, nil }\n                if FixedWand and this.UserData[\"HasShiftClick\"][FixedWand] and FixedWand ~= wandEntity then\n                    if this.UserData[\"HasShiftClick\"][FixedWand][1] == \"WandSpellViewer\" then --判断id是为了看看需不需要设置\n                        this.UserData[\"HasShiftClick\"][FixedWand] = nil\n                    end\n                elseif FixedWand == wandEntity then                          --固定的法杖，等于传入的法杖实体的时候\n                    local HeldWand = Compose(GetEntityHeldWand, GetPlayer)() --获取手持法杖\n                    if HeldWand and HeldWand ~= wandEntity then\n                        this.UserData[\"HasShiftClick\"][HeldWand] = nil\n                    end\n                end\n            elseif this.UserData[\"HasShiftClick\"][wandEntity][2] == k or this.UserData[\"HasShiftClick\"][wandEntity][1] ~= id or this.UserData[\"HasShiftClick\"][wandEntity][3] == k then\n                if this.UserData[\"HasShiftClick\"][wandEntity][1] ~= id then --如果是id不相同，那么就要重新设置\n                    this.UserData[\"HasShiftClick\"][wandEntity][1] = id\n                    this.UserData[\"HasShiftClick\"][wandEntity][2] = k\n                    this.UserData[\"HasShiftClick\"][wandEntity][3] = nil\n                    if FixedWand and FixedWand ~= wandEntity then --如果你看不懂没关系，你叫我来可能也要反应半天\n                        this.UserData[\"HasShiftClick\"][FixedWand] = nil\n                    end\n                else --如果是id相同且索引一致，那么就清空数据，代表取消\n                    this.UserData[\"HasShiftClick\"][wandEntity] = nil\n                end\n            else\n                this.UserData[\"HasShiftClick\"][wandEntity][3] = k\n            end\n            --多选跨法杖交换，恶心！\n        elseif click and this.UserData[\"FloatSpellID\"] == nil and (InputIsKeyDown(Key_LCTRL) or InputIsKeyDown(Key_RCTRL)) and next(this.UserData[\"HasShiftClick\"]) then\n            if this.UserData[\"HasShiftClick\"][wandEntity] then --如果你手持的和点击的法杖实体是同一个\n                local HasShiftClick = this.UserData[\"HasShiftClick\"][wandEntity]\n                local min = HasShiftClick[2]\n                local max = HasShiftClick[3] or min\n                min = math.min(min, max)\n                max = math.max(HasShiftClick[2], max)\n                local ThisK = k\n				local DeepCopyT\n                if InputIsKeyDown(Key_v) then\n                    DeepCopyT = DeepCopy(wandData.spells.spells)\n                end\n				if InputIsKeyDown(Key_v) or k <= min then\n					for i = min, max do\n						if ThisK > wandData.deck_capacity then\n							break\n						end\n						if InputIsKeyDown(Key_v) then\n							if DeepCopyT[i] ~= \"nil\" then\n								SetTableSpells(wandData,DeepCopyT[i].id,ThisK,DeepCopyT[i].uses_remaining)\n							else\n								wandData.spells.spells[ThisK] = \"nil\"\n							end\n						else\n							SwapSpellPos(wandData, i, ThisK)\n						end\n						ThisK = ThisK + 1\n					end\n                else\n					ThisK = ThisK + (max-min)\n                    for i = max, min, -1 do\n                        if ThisK > wandData.deck_capacity then\n                            break\n                        end\n						SwapSpellPos(wandData, i, ThisK)\n						ThisK = ThisK - 1\n					end\n				end\n                InitWand(wandData, wandEntity)\n                this.UserData[\"HasShiftClick\"][wandEntity] = nil\n                this.OnceCallOnExecute(function()\n                    RefreshHeldWands()\n                end)\n            elseif this.UserData[\"FixedWand\"] then              --反之不同，需要判空\n                local HeldWand = Compose(GetEntityHeldWand, GetPlayer)()\n                local FixedWand = this.UserData[\"FixedWand\"][2] --如果是跨法杖编辑，那么代表这个是必然存在的\n                local HasShiftClick = this.UserData[\"HasShiftClick\"][HeldWand] or\n                this.UserData[\"HasShiftClick\"][FixedWand]\n                if HasShiftClick ~= nil then\n                    local IsFixed = false\n                    local OtherWand\n                    if FixedWand == wandEntity then --如果点击法杖等于固定法杖，那么其他数据就是手持法杖\n                        OtherWand = GetWandData(HeldWand)\n                        IsFixed = true\n                    else --否则是固定法杖\n                        OtherWand = GetWandData(FixedWand)\n                    end\n                    --如果没有问题(Bug)，那么应该只有一个是真（即有数据\n                    local min = HasShiftClick[2]\n                    local max = HasShiftClick[3] or min\n                    min = math.min(min, max)\n                    max = math.max(HasShiftClick[2], max)\n                    local ThisK = k\n                    local DeepCopyT\n                    if InputIsKeyDown(Key_v) then\n                        DeepCopyT = DeepCopy(OtherWand.spells.spells)\n                    end\n					if InputIsKeyDown(Key_v) or k <= min then\n                    	for i = min, max do                                     --i是原始位置，k是目标位置\n                            if i > OtherWand.deck_capacity or ThisK > wandData.deck_capacity then --超出容量就什么都不做\n            	                break\n        	                end\n    	                    if InputIsKeyDown(Key_v) then\n								if DeepCopyT[i] ~= \"nil\" then\n									SetTableSpells(wandData, DeepCopyT[i].id,ThisK,DeepCopyT[i].uses_remaining)							\n                            	else\n									wandData.spells.spells[ThisK] = \"nil\"\n								end\n							else\n								Swap2InputSpellPos(wandData, OtherWand, ThisK, i)\n							end\n                        	ThisK = ThisK + 1\n                    	end\n					else\n                        ThisK = ThisK + (max - min)\n						for i = max, min, -1 do\n							if ThisK > wandData.deck_capacity then\n								break\n							end\n							Swap2InputSpellPos(OtherWand, wandData, i, ThisK)\n							ThisK = ThisK - 1\n						end\n					end\n                    if IsFixed then\n                        InitWand(wandData, wandEntity)\n                        InitWand(OtherWand, HeldWand)\n                    else\n                        InitWand(wandData, wandEntity)\n                        InitWand(OtherWand, FixedWand)\n                    end\n                    this.UserData[\"HasShiftClick\"][HeldWand] = nil\n                    this.UserData[\"HasShiftClick\"][FixedWand] = nil\n                    this.OnceCallOnExecute(function()\n                        RefreshHeldWands()\n                    end)\n                end\n            end\n        elseif click and this.UserData[\"FloatSpellID\"] ~= nil then\n            if this.UserData[\"UpSpellIndex\"] ~= nil and v ~= \"nil\" then --如果存在键，则代表这是一次交换操作\n                local i = this.UserData[\"UpSpellIndex\"][1]\n                local OtherWand = this.UserData[\"UpSpellIndex\"][3]\n                if OtherWand == wandEntity then --如果是同一实体\n                    SetTableSpells(wandData, v.id, i, v.uses_remaining, false)\n                else                --刷新另一根法杖\n                    local OtherWandData = this.UserData[\"UpSpellIndex\"][2]\n                    SetTableSpells(OtherWandData, v.id, i, v.uses_remaining, false)\n                    InitWand(OtherWandData, this.UserData[\"UpSpellIndex\"][3])\n                end --刷新手持法杖 这一步相当于交换\n                SetTableSpells(wandData, this.UserData[\"FloatSpellID\"], k, this.UserData[\"UpSpellIndex\"][4], false)\n                InitWand(wandData, wandEntity)\n            else                          --当前法杖的\n                local uses_remaining\n                if this.UserData[\"UpSpellIndex\"] then --如果有记录的话就赋值使用次数\n                    uses_remaining = this.UserData[\"UpSpellIndex\"][4]\n                end\n                SetTableSpells(wandData, this.UserData[\"FloatSpellID\"], k, uses_remaining, false)\n                InitWand(wandData, wandEntity)\n            end\n            this.UserData[\"UpSpellIndex\"] = nil\n            this.UserData[\"FloatSpellID\"] = nil\n            this.OnceCallOnExecute(function()\n                RefreshHeldWands()\n            end)\n            this.UserData[\"SpellHoverEnable\"] = true\n        elseif v ~= \"nil\" and click then --移动法术\n            if not this.GetNoMoveBool() then\n                this.UserData[\"SpellHoverEnable\"] = false\n                DrawFloatSpell(x, y, spellData[v.id].sprite, v.id)\n                if this.UserData[\"UpSpellIndex\"] == nil then --记录上次的键等数据\n                    this.UserData[\"UpSpellIndex\"] = { k, wandData, wandEntity, v.uses_remaining }\n                end\n                RemoveTableSpells(wandData, k)\n                InitWand(wandData, wandEntity)\n                this.OnceCallOnExecute(function()\n                    RefreshHeldWands()\n                end)\n            end\n        elseif (InputIsKeyDown(Key_LCTRL) or InputIsKeyDown(Key_RCTRL)) and (InputIsKeyDown(Key_c) or InputIsKeyDown(Key_x)) and this.UserData[\"HasShiftClick\"][CurrentWand] then\n            if not CopiedData then\n                local CurrentData = GetWandData(CurrentWand)\n                local HasShiftClick = this.UserData[\"HasShiftClick\"][CurrentWand]\n                local min = HasShiftClick[2]\n                local max = HasShiftClick[3] or min\n                min = math.min(min, max)\n                max = math.max(HasShiftClick[2], max)\n                local DownX = InputIsKeyDown(Key_x)\n                local T = {}\n                for i = min, max do\n                    T[#T + 1] = GetSpellID(CurrentData, i)\n                    if DownX then\n                        RemoveTableSpells(CurrentData, i)\n                    end\n                end\n                if DownX then\n                    InitWand(CurrentData, CurrentWand)\n					this.OnceCallOnExecute(function()\n						RefreshHeldWands()\n					end)\n                end\n                Cpp.SetClipboard(Cpp.ConcatStr(\"return {\\n\", SerializeTable(T), \"}\"))\n                CopiedData = true\n				this.UserData[\"HasShiftClick\"][CurrentWand] = nil\n            end\n		elseif (InputIsKeyDown(Key_LCTRL) or InputIsKeyDown(Key_RCTRL)) and InputIsKeyJustDown(Key_v) and hover then\n            local ClipboardData = Cpp.GetClipboard()\n            local flag, t = CheckSpells(ClipboardData)\n            if flag then\n                for i = #t, 1, -1 do\n                    if t[i] ~= 'nil' then\n                        InsertTableSpells(wandData, false, t[i].id, k, t[i].uses_remaining)\n                    end\n                end\n                InitWand(wandData, wandEntity)\n                this.OnceCallOnExecute(function()\n                    RefreshHeldWands()\n                end)\n            end\n		elseif (InputIsKeyDown(Key_LCTRL) or InputIsKeyDown(Key_RCTRL)) and InputIsKeyJustDown(Key_b) and hover then\n            local ClipboardData = Cpp.GetClipboard()\n            local flag, t = CheckSpells(ClipboardData)\n            if flag then\n                for i = #t, 1, -1 do\n                    InsertTableSpells(wandData, false, \"wand_editor_temp_spell_id\", k) --伪造\n                end\n				local count = 1\n                for i = #t, 1, -1 do\n                    if t[count] == \"nil\" then\n                        wandData.spells.spells[k + #t - i] = \"nil\"\n                    else\n                        wandData.spells.spells[k + #t - i] = { id = t[count].id, is_frozen = false, isAlways = false, uses_remaining = t[count].uses_remaining }\n                    end\n					count = count + 1\n				end\n                InitWand(wandData, wandEntity)\n				this.OnceCallOnExecute(function()\n					RefreshHeldWands()\n				end)\n            end\n        else\n			CopiedData = false\n        end\n    else --是始终施放法术的操作\n        if hover and InputIsKeyDown(Key_BACKSPACE) then\n            if this.UserData[\"AlwaysClickFr\"] == nil then\n                this.UserData[\"AlwaysClickFr\"] = 45\n            elseif this.UserData[\"AlwaysClickFr\"] > 0 then\n                this.UserData[\"AlwaysClickFr\"] = this.UserData[\"AlwaysClickFr\"] - 1\n            end\n            if this.UserData[\"AlwaysClickFr\"] == 45 or this.UserData[\"AlwaysClickFr\"] == 0 then\n                RemoveTableAlwaysSpells(wandData, k)\n                InitWand(wandData, wandEntity)\n                this.OnceCallOnExecute(function()\n                    RefreshHeldWands()\n                end)\n            end\n        elseif click and this.UserData[\"FloatSpellID\"] == nil then\n            if not this.GetNoMoveBool() then\n                this.UserData[\"SpellHoverEnable\"] = false\n                DrawFloatSpell(x, y, spellData[v.id].sprite, v.id)\n                --不记录上次数据\n                RemoveTableAlwaysSpells(wandData, k)\n                InitWand(wandData, wandEntity)\n                this.OnceCallOnExecute(function()\n                    RefreshHeldWands()\n                end)\n            end\n        elseif not InputIsKeyDown(Key_BACKSPACE) then\n            this.UserData[\"AlwaysClickFr\"] = nil\n        end\n    end\n	if not isAlways then\n        if hover and InputIsKeyJustDown(Key_BACKSPACE) and highlight then --按下退格键多选删除法术\n			local HasShiftClick = this.UserData[\"HasShiftClick\"][wandEntity]\n			local min = HasShiftClick[2]\n			local max = HasShiftClick[3] or min\n			min = math.min(min, max)\n            max = math.max(HasShiftClick[2], max)\n			for i = min, max do\n				RemoveTableSpells(wandData, i)\n			end\n			InitWand(wandData, wandEntity)\n			this.UserData[\"HasShiftClick\"][wandEntity] = nil\n			this.OnceCallOnExecute(function()\n				RefreshHeldWands()\n			end)\n		elseif hover and InputIsKeyJustDown(Key_BACKSPACE) and v ~= \"nil\" then --按下退格键删除法术\n			RemoveTableSpells(wandData, k)\n			InitWand(wandData, wandEntity)\n			this.OnceCallOnExecute(function()\n				RefreshHeldWands()\n			end)\n		end\n	end\n    this.SetZDeep(srcDeep) --恢复深度以解决奇怪深度问题\nend\n\nlocal LastWand\nlocal LastCapacity = 0\nfunction DrawWandContainer(wandEntity, spellData)\n    local srcZDeep = this.GetZDeep()\n	this.SetZDeep(srcZDeep + 1000)\n	if this.UserData[\"HasShiftClick\"] == nil then\n		this.UserData[\"HasShiftClick\"] = {}\n	else\n		for entity, _ in pairs(this.UserData[\"HasShiftClick\"]) do\n			if not EntityGetIsAlive(entity) then --垃圾回收\n				this.UserData[\"HasShiftClick\"][entity] = nil\n			end\n		end\n	end\n	local Skip = false --是否跳过\n	if wandEntity == nil then\n		Skip = true\n	end\n    local wandData = GetWandData(wandEntity)\n	\n	local HeldWand = Compose(GetEntityHeldWand, GetPlayer)()\n	local FixedWand\n	if this.UserData[\"FixedWand\"] then\n		FixedWand = this.UserData[\"FixedWand\"][2]\n	end\n	if HeldWand and HeldWand ~= FixedWand then --阻止同时出现多个多选框\n		if this.UserData[\"HasShiftClick\"][HeldWand] and this.UserData[\"HasShiftClick\"][FixedWand] and this.UserData[\"HasShiftClick\"][FixedWand][1] == \"WandSpellViewer\" then\n			this.UserData[\"HasShiftClick\"][HeldWand] = nil\n		end\n	end\n	if wandData == nil then\n		Skip = true\n	end\n	local TrueWidth = this.ScreenWidth - 20\n	local HScrollX = 10\n	local HScrollY = this.ScreenHeight - 38.5\n    local HScrollWidth = this.GetHScrollWidth(\"WandContainer\")\n	\n	if not Skip then\n        if HScrollWidth == nil or LastWand ~= wandEntity or this.UserData[\"NextResetHScroll\"] then --自动居中\n            HScrollX = this.ScreenWidth * 2\n            HScrollY = this.ScreenHeight * 2\n            this.UserData[\"NextResetHScroll\"] = false\n        elseif HScrollWidth < TrueWidth and HScrollWidth ~= 0 then\n            HScrollX = this.ScreenWidth * 0.5 - HScrollWidth / 2\n        end\n        local Ability = EntityGetFirstComponentIncludingDisabled(wandEntity, \"AbilityComponent\")\n		local thisDecks = ComponentObjectGetValue2(Ability, \"gun_config\", \"deck_capacity\")\n        if LastCapacity ~= thisDecks then --如果不一致就刷新数据\n            this.UserData[\"NextResetHScroll\"] = true\n            this.OnceCallOnExecute(function()\n                this.ResetHScrollSlider(\"WandContainer\")\n            end)\n        end\n		if wandData then--执行顺序问题，先放这里防止始终数量更改\n			LastCapacity = thisDecks\n		end\n	end\n\n	this.HorizontalScroll(\"WandContainer\", HScrollX, HScrollY, TrueWidth, 20, false, 0, 0)\n    local SecondWithSign = Compose(NumToWithSignStr, tonumber, FrToSecondStr)\n	\n	local ViewerHover = function()\n		local _, _, hover = L_GuiGetPreviousWidgetInfo(this.gui)\n		local tip = GameTextGet(\"$wand_editor_wand_spell_viewer_tip_close\")\n        if this.UserData[\"FixedWand\"] then\n            tip = GameTextGet(\"$wand_editor_wand_spell_viewer_tip_open\")\n        end\n        UI.BetterTooltipsNoCenter(function()\n			local rightMargin = 70\n            local function NewLine(str1, str2)\n                local text = GameTextGetTranslatedOrNot(str1)\n                local w = GuiGetTextDimensions(UI.gui, text)\n                GuiLayoutBeginHorizontal(UI.gui, 0, 0, true, 2, -1)\n                GuiText(UI.gui, 0, 0, text)\n                GuiRGBAColorSetForNextWidget(UI.gui, 255, 222, 173, 255)\n                GuiText(UI.gui, rightMargin - w, 0, str2)\n                GuiLayoutEnd(UI.gui)\n            end\n            if InputIsKeyDown(Key_LCTRL) or InputIsKeyDown(Key_RCTRL) then\n				local wand = wandData\n				if wand.always_use_item_name_in_ui then\n                    GuiText(UI.gui, 0, 0, GameTextGetTranslatedOrNot(wand.item_name))\n                else\n					GuiText(UI.gui, 0, 0, GameTextGetTranslatedOrNot(\"$item_wand\"))\n				end\n				GuiLayoutAddVerticalSpacing(UI.gui, 1)\n                \n                local shuffle\n                if wand.shuffle_deck_when_empty then\n                    shuffle = GameTextGet(\"$menu_yes\")\n                else\n                    shuffle = GameTextGet(\"$menu_no\")\n                end\n                NewLine(\"$inventory_shuffle\", shuffle)\n                NewLine(\"$inventory_actionspercast\", wand.actions_per_round)\n                NewLine(\"$inventory_castdelay\", SecondWithSign(wand.fire_rate_wait) .. \"s(\" .. wand.fire_rate_wait .. \"f)\")\n                NewLine(\"$inventory_rechargetime\", SecondWithSign(wand.reload_time) .. \"s(\" .. wand.reload_time .. \"f)\")\n                NewLine(\"$inventory_manamax\", math.floor(wand.mana_max))\n                NewLine(\"$inventory_manachargespeed\", math.floor(wand.mana_charge_speed))\n                NewLine(\"$inventory_capacity\", wand.deck_capacity)\n                NewLine(\"$inventory_spread\", wand.spread_degrees .. GameTextGet(\"$wand_editor_deg\"))\n                NewLine(\"$wand_editor_speed_multiplier\", \"x\" .. string.format(\"%.8f\", wand.speed_multiplier))				\n            else\n				GuiText(this.gui,0,0,tip)\n			end\n		end,-3000,10)\n		if hover or this.UserData[\"FixedWand\"] then\n			local ViewerWandData = wandData\n			local ViewerWandEntity = wandEntity\n			if this.UserData[\"FixedWand\"] then\n				ViewerWandData = this.UserData[\"FixedWand\"][1]\n				ViewerWandEntity = this.UserData[\"FixedWand\"][2]\n			end\n			if ViewerWandData == nil then --使用遁入虚空会导致法杖id刷新，所以此时无法获得法杖最新数据，因此需要判空\n				return\n			end\n			this.ScrollContainer(\"WandSpellViewerContainer\", 250, 64, this.ScreenWidth - 250 - 40,\n				this.ScreenHeight - 60 - 70, nil, 0, 1.14)\n\n			for k, v in pairs(ViewerWandData.spells.always) do\n				this.AddScrollImageItem(\"WandSpellViewerContainer\", \"data/ui_gfx/inventory/full_inventory_box.png\",\n					function()\n						SpellPicker(\"WandSpellViewerContainer\", \"WandSpellViewer\", ViewerWandEntity, ViewerWandData, spellData, k, v, true)\n					end)\n			end\n			for k, v in pairs(ViewerWandData.spells.spells) do\n				this.AddScrollImageItem(\"WandSpellViewerContainer\", \"data/ui_gfx/inventory/full_inventory_box.png\",\n					function()\n						SpellPicker(\"WandSpellViewerContainer\", \"WandSpellViewer\", ViewerWandEntity, ViewerWandData, spellData, k, v)\n					end)\n			end\n			if this.UserData[\"FixedWand\"] then\n                this.UserData[\"FixedWand\"][1] = GetWandData(ViewerWandEntity)\n			end\n			L_GuiZSetForNextWidget(this.gui, this.GetZDeep() + 1)\n			this.DrawScrollContainer(\"WandSpellViewerContainer\", true)\n		end\n	end\n	local ViewerClick = function(left_click)\n        if left_click or (InputIsKeyDown(Key_GRAVE) and this.UserData[\"ViewerCKeyDown\"] == nil) then --点击左键就存储数据\n			this.UserData[\"ViewerCKeyDown\"] = true\n            if this.UserData[\"FixedWand\"] == nil then\n                this.UserData[\"FixedWand\"] = { wandData, wandEntity }\n            else\n                this.UserData[\"FixedWand\"] = nil\n            end\n        elseif not InputIsKeyDown(Key_GRAVE) and this.UserData[\"ViewerCKeyDown\"] then\n			RestoreInput()\n			this.UserData[\"ViewerCKeyDown\"] = nil\n        end\n		if left_click then\n			GamePlaySound(\"data/audio/Desktop/ui.bank\", \"ui/button_click\", GameGetCameraPos())\n		end\n	end\n	--为了实现，满足条件下即使玩家也不拿着法杖，也会绘制这些控件\n	if not Skip then\n		L_GuiZSetForNextWidget(this.gui, this.GetZDeep() + 1)\n		this.MoveImageButton(\"WandSpellViewerBTN\", HScrollX + 3, this.ScreenHeight - 53.5,\n			\"mods/wand_editor/files/gui/images/wand_spell_viewer.png\", nil, ViewerHover, ViewerClick, nil, true)\n	elseif this.UserData[\"FixedWand\"] then\n		L_GuiZSetForNextWidget(this.gui, this.GetZDeep() + 1)\n		this.MoveImageButton(\"WandSpellViewerBTN\", 235, 64, \"mods/wand_editor/files/gui/images/wand_spell_viewer.png\", nil,\n			ViewerHover, ViewerClick, nil, true)\n	end\n    if not Skip then --绘制法术编辑栏\n        for k, v in pairs(wandData.spells.always) do\n            this.AddHScrollItem(\"WandContainer\", function()\n                SpellPicker(\"WandContainer\", \"WandContainer\", wandEntity, wandData, spellData, k, v, true)\n            end)\n        end\n        for k, v in pairs(wandData.spells.spells) do\n            this.AddHScrollItem(\"WandContainer\", function()\n                SpellPicker(\"WandContainer\", \"WandContainer\", wandEntity, wandData, spellData, k, v)\n            end)\n        end\n\n        this.DarwHorizontalScroll(\"WandContainer\")\n        LastWand = wandEntity\n    end\n	this.SetZDeep(srcZDeep)\nend\n"
_TWWE_VFS["mods/wand_editor/files/gui/WandDepot.lua"] = "local GetHeldWand = Compose(GetEntityHeldWand, GetPlayer)\nlocal data = dofile_once(\"mods/wand_editor/files/gui/GetSpellData.lua\") --读取法术数据\nlocal spellData = data[1]\nlocal TypeToSpellList = data[2]\nlocal deg57_5 = math.rad(-57.5)\nlocal CurrentPin\nlocal fastConcatStr = Cpp.ConcatStr\nlocal function ClickSound()\n	GamePlaySound(\"data/audio/Desktop/ui.bank\", \"ui/button_click\", GameGetCameraPos())\nend\n---返回法杖仓库大小\n---@return integer\nlocal function GetWandDepotSize()\n	return ModSettingGet(ModID .. \"WandDepotSize\")\nend\n\n--设置法杖仓库大小(不影响实际，单纯的设置)\nlocal function SetWandDepotSize(num)\n	ModSettingSet(ModID .. \"WandDepotSize\", num)\nend\n\n---获得法杖仓库表原始文本\n---@param index integer\n---@return string\nlocal function GetWandDepotStr(index)\n    local size = GetWandDepotSize()\n    if index <= size then\n        local result = ModSettingGet(ModID .. \"WandDepot\" .. tostring(index))\n        if result == nil then\n            return \"\"\n        end\n        return result\n    end\n    error(\"wand depot index out of bounds:\" .. tostring(index))\n    return \"\"\nend\nlocal cache\nlocal cacheTable--缓存机制，只有在获取和上个字符串不同的时候才进行读取并检查安全性\n---获得法杖仓库表\n---@param index integer\n---@return table\nlocal function GetWandDepot(index)\n	local size = GetWandDepotSize()\n    if index <= size then\n        local CheckFnStr = tostring(ModSettingGet(ModID .. \"WandDepot\" .. tostring(index)))\n        if cache == nil then--数据缓存\n            cache = CheckFnStr\n        elseif cache == CheckFnStr and cacheTable then\n            return cacheTable\n		elseif cache ~= CheckFnStr then\n			cache = CheckFnStr\n		end\n        if HasEnds(CheckFnStr) then\n            ModSettingSet(ModID .. \"WandDepot\" .. tostring(index), \"return {}\")\n            return {}\n        end\n		local CheckFn = loadstring(CheckFnStr)\n		if type(CheckFn) ~= \"function\" then--数据恢复为空表，有代码或其他行为试图篡改为非法数据\n			ModSettingSet(ModID .. \"WandDepot\" .. tostring(index),\"return {}\")\n			return {}\n		end\n        local fn = setfenv(CheckFn, {})\n        local flag, result = pcall(fn)\n        if not flag then --数据恢复为空表，有代码或其他行为试图篡改为非法数据\n            ModSettingSet(ModID .. \"WandDepot\" .. tostring(index), \"return {}\")\n            return {}\n        end\n		cacheTable = result\n		return result\n	end\n	error(\"wand depot index out of bounds:\" .. tostring(index))\n	return {}\nend\n\n---设置法杖仓库表\n---@param t table\n---@param index integer\nlocal function SetWandDepotLua(t, index)\n	local size = GetWandDepotSize()\n	if index <= size then\n		ModSettingSet(ModID .. \"WandDepot\" .. tostring(index), \"return {\\n\" .. SerializeTable(t) .. \"}\")\n	else\n		error(\"wand depot index out of bounds\" .. tostring(index))\n	end\nend\n\n---检查数据是否合法\n---@param str string\n---@return boolean\nlocal function CheckWandDepotData(str)\n	if HasEnds(str) then\n		return false\n	end\n    local CheckFn = loadstring(str)\n    if type(CheckFn) ~= \"function\" then\n		return false\n    end\n	local fn = setfenv(CheckFn, {}) --设置环境 防止注入攻击\n    local flag, result = pcall(fn)\n	if not flag then\n		return false\n	end\n    if type(result) ~= \"table\" then\n        return false\n	end\n	local baseWand = {\n		spells = true, --法术表\n		mana_charge_speed = true,      --回蓝速度\n		mana_max = true,               --蓝上限\n		fire_rate_wait = true,         --施放延迟\n		reload_time = true,            --充能延迟\n		deck_capacity = true,          --容量\n		spread_degrees = true,         --散射\n		shuffle_deck_when_empty = true, --是否乱序\n		speed_multiplier = true,       --初速度加成\n		mana = true,                   --蓝\n		actions_per_round = true,      --施放数\n		shoot_pos = true, --发射位置\n		sprite_file = true,            --贴图\n		sprite_pos = true, 	--精灵图偏移\n		rect_animation = true\n    }\n	\n	for _,wand in pairs(result)do--判断格式是否正确\n		for k,_ in pairs(baseWand)do\n            if wand[k] == nil then\n				return false\n			end\n		end\n	end\n	return true,result\nend\n\n---为法杖仓库新建一个页面\n---@param t table?\n---@return table\nlocal function NewWandDepot(t)\n	local index = GetWandDepotSize()\n	if index >= 99999 then\n		GamePrint(GameTextGet(\"$wand_editor_wand_depot_wandlist_limit\"))\n		return {}\n	end\n	SetWandDepotSize(index + 1)\n    index = index + 1\n	if t == nil then\n		ModSettingSet(ModID .. \"WandDepot\" .. tostring(index), \"return {}\")\n        return {}\n    else\n		ModSettingSet(ModID .. \"WandDepot\" .. tostring(index), \"return {\\n\" .. SerializeTable(t) .. \"}\")\n		return t\n	end\nend\n\n---删除法杖仓库指定索引页面\n---@param index integer\nlocal function RemoveWandDepot(index)\n	local max = GetWandDepotSize()\n	local key = ModID .. \"WandDepot\"\n    for i = index, max - 1 do\n		local newkey = key .. tostring(i + 1)\n        local str = ModSettingGet(newkey)\n        ModSettingSet(key .. tostring(i), str)\n	end\n	ModSettingRemove(ModID .. \"WandDepot\" .. tostring(max))\n	SetWandDepotSize(max - 1)\nend\n\nlocal PinList = {\n	\"white\",\n	\"black\",\n	\"red\",\n	\"lime\",\n	\"blue\",\n	\"yellow\",\n	\"cyan\",\n	\"fuchsia\",\n	\"sliver\",\n	\"grey\",\n	\"maroon\",\n	\"olive\",\n	\"green\",\n	\"purple\",\n	\"teal\",\n	\"navy\",\n}\n\nlocal PinImageMap = {\n	white = \"mods/wand_editor/files/gui/images/pin/white.png\",\n	black = \"mods/wand_editor/files/gui/images/pin/black.png\",\n	red = \"mods/wand_editor/files/gui/images/pin/red.png\",\n	lime = \"mods/wand_editor/files/gui/images/pin/lime.png\",\n	blue = \"mods/wand_editor/files/gui/images/pin/blue.png\",\n	yellow = \"mods/wand_editor/files/gui/images/pin/yellow.png\",\n	cyan = \"mods/wand_editor/files/gui/images/pin/cyan.png\",\n	fuchsia = \"mods/wand_editor/files/gui/images/pin/fuchsia.png\",\n	sliver = \"mods/wand_editor/files/gui/images/pin/sliver.png\",\n	grey = \"mods/wand_editor/files/gui/images/pin/grey.png\",\n	maroon = \"mods/wand_editor/files/gui/images/pin/maroon.png\",\n	olive = \"mods/wand_editor/files/gui/images/pin/olive.png\",\n	green = \"mods/wand_editor/files/gui/images/pin/green.png\",\n	purple = \"mods/wand_editor/files/gui/images/pin/purple.png\",\n	teal = \"mods/wand_editor/files/gui/images/pin/teal.png\",\n	navy = \"mods/wand_editor/files/gui/images/pin/navy.png\",\n}\n\nlocal RegList = {}\nfor _,v in pairs(PinList)do\n	RegList[#RegList + 1] = \"WandDepotPinList\" .. v\nend\n\nUI.PickerEnableList(unpack(RegList))\nRegList = nil\n\nlocal RowMax = 12\nlocal ColMax = 8\nlocal TableMax = RowMax * ColMax\nlocal RowGap = 23\nlocal ColGap = 23\nlocal SlotBG = \"data/ui_gfx/inventory/full_inventory_box.png\"\nlocal HLSlotBG = \"data/ui_gfx/inventory/full_inventory_box_highlight.png\"\n---绘制法杖格\n---@param id string\n---@param k integer\n---@param wand Wand\nlocal function DrawWandSlot(id, k, wand)\n    local world_entity_id = GameGetWorldStateEntity()\n    local comp_worldstate = EntityGetFirstComponent(world_entity_id, \"WorldStateComponent\")\n    local inf_spells_enable = ComponentGetValue2(comp_worldstate, \"perk_infinite_spells\")\n    local HistoryMode = UI.UserData[\"WandDepotHistoryEnable\"]\n	\n    local sprite\n    local s = strip(wand.sprite_file)\n    if string.sub(s, #s - 3) == \".xml\" then --特殊文件需要处理\n        local SpriteXml = ParseXmlAndBase(wand.sprite_file)\n        sprite = SpriteXml.attr.filename\n    else\n        sprite = wand.sprite_file\n    end\n    k = k - 1\n    local thisSlot\n    if UI.UserData[\"WandDepotKHighlight\"] == k then\n        thisSlot = HLSlotBG\n    else\n        thisSlot = SlotBG\n    end\n    local column = math.floor(k % (RowMax))\n    local row = math.floor(k / (RowMax))\n    local x = ColGap * column\n    local y = row * RowGap\n	if wand.__DepotPin and PinImageMap[wand.__DepotPin] then\n		GuiZSetForNextWidget(UI.gui, UI.GetZDeep() - 4)\n		GuiImage(UI.gui,UI.NewID(fastConcatStr(id,tostring(k),wand.__DepotPin)),x,11 + y,PinImageMap[wand.__DepotPin],1,1)\n	end\n    GuiZSetForNextWidget(UI.gui, UI.GetZDeep() - 1)\n    local left_click, right_click = GuiImageButton(UI.gui, UI.NewID(fastConcatStr(id , tostring(k) , \"BG\")), 0 + x, 12 + y, \"\", thisSlot)\n    local _, _, hover = GuiGetPreviousWidgetInfo(UI.gui)\n    if hover then\n        local rightMargin = 70\n        local function NewLine(str1, str2)\n            local text = GameTextGetTranslatedOrNot(str1)\n            local w = GuiGetTextDimensions(UI.gui, text)\n            GuiLayoutBeginHorizontal(UI.gui, 0, 0, true, 2, -1)\n            GuiText(UI.gui, 0, 0, text)\n            GuiRGBAColorSetForNextWidget(UI.gui, 255, 222, 173, 255)\n            GuiText(UI.gui, rightMargin - w, 0, str2)\n            GuiLayoutEnd(UI.gui)\n        end\n        local SecondWithSign = Compose(NumToWithSignStr, tonumber, FrToSecondStr)\n        UI.BetterTooltipsNoCenter(function()\n            GuiLayoutBeginVertical(UI.gui, 0, 0, true)\n            if InputIsKeyDown(Key_LCTRL) or InputIsKeyDown(Key_RCTRL) then\n				if wand.always_use_item_name_in_ui then\n                    GuiText(UI.gui, 0, 0, GameTextGetTranslatedOrNot(wand.item_name))\n                else\n					GuiText(UI.gui, 0, 0, GameTextGetTranslatedOrNot(\"$item_wand\"))\n				end\n				GuiLayoutAddVerticalSpacing(UI.gui, 1)\n                \n                local shuffle\n                if wand.shuffle_deck_when_empty then\n                    shuffle = GameTextGet(\"$menu_yes\")\n                else\n                    shuffle = GameTextGet(\"$menu_no\")\n                end\n                NewLine(\"$inventory_shuffle\", shuffle)\n                NewLine(\"$inventory_actionspercast\", wand.actions_per_round)\n                NewLine(\"$inventory_castdelay\", SecondWithSign(wand.fire_rate_wait) .. \"s(\" .. wand.fire_rate_wait ..\n                    \"f)\")\n                NewLine(\"$inventory_rechargetime\", SecondWithSign(wand.reload_time) .. \"s(\" .. wand.reload_time .. \"f)\")\n                NewLine(\"$inventory_manamax\", math.floor(wand.mana_max))\n                NewLine(\"$inventory_manachargespeed\", math.floor(wand.mana_charge_speed))\n                NewLine(\"$inventory_capacity\", wand.deck_capacity)\n                NewLine(\"$inventory_spread\", wand.spread_degrees .. GameTextGet(\"$wand_editor_deg\"))\n                NewLine(\"$wand_editor_speed_multiplier\", \"x\" .. string.format(\"%.8f\", wand.speed_multiplier))\n            else\n                GuiLayoutBeginHorizontal(UI.gui, 0, 0, true)\n                for i = 1, #wand.spells.always do\n                    local v = wand.spells.always[i]\n                    GuiZSetForNextWidget(UI.gui, UI.GetZDeep() - 101)\n                    GuiImage(UI.gui, UI.NewID(id .. \"always_full_BG\" .. tostring(i)), 0, 0,\n                        \"data/ui_gfx/inventory/full_inventory_box.png\", 1, 0.5)\n                    local _, _, _, weigthX, weigthY, weigthW, weigthH = GuiGetPreviousWidgetInfo(UI.gui)\n                    if spellData[v.id] ~= nil then --判空，防止法术数据异常\n                        GuiZSetForNextWidget(UI.gui, UI.GetZDeep() - 102)\n						GuiOptionsAddForNextWidget(UI.gui, GUI_OPTION.Layout_NoLayouting)\n                        GuiImage(UI.gui, UI.NewID(id .. v.id .. \"always\" .. tostring(i)), weigthX, weigthY,\n                            SpellTypeBG[spellData[v.id].type],\n                            1, 0.5)\n						local sw,sh = GuiGetImageDimensions(UI.gui, spellData[v.id].sprite, 0.5)\n                        GuiZSetForNextWidget(UI.gui, UI.GetZDeep() - 103)\n						GuiOptionsAddForNextWidget(UI.gui, GUI_OPTION.Layout_NoLayouting)\n                        GuiImage(UI.gui, UI.NewID(id .. v.id .. \"always_spell\" .. tostring(i) .. \"BG\"), weigthX + (weigthW-sw)/2, weigthY + (weigthH-sh)/2,\n                            spellData[v.id].sprite, 1, 0.5)\n\n                        GuiZSetForNextWidget(UI.gui, UI.GetZDeep() - 104)\n						GuiOptionsAddForNextWidget(UI.gui, GUI_OPTION.Layout_NoLayouting)\n                        GuiImage(UI.gui, UI.NewID(id .. v.id .. \"Always_icon\" .. tostring(k)), weigthX, weigthY,\n                            \"mods/wand_editor/files/gui/images/always_icon.png\",\n                            1, 0.5)\n                    end\n                    if weigthX + weigthW >= UI.ScreenWidth - 80 then\n                        GuiLayoutEnd(UI.gui)\n                        GuiLayoutBeginHorizontal(UI.gui, 0, 0, true)\n                    end\n                end\n                for i = 1, #wand.spells.spells do\n                    local v = wand.spells.spells[i]\n                    GuiZSetForNextWidget(UI.gui, UI.GetZDeep() - 101)\n                    GuiImage(UI.gui, UI.NewID(id .. \"full_BG\" .. tostring(i)), 0, 0,\n                        \"data/ui_gfx/inventory/full_inventory_box.png\", 1, 0.5)\n                    local _, _, _, weigthX, weigthY, weigthW, weigthH = GuiGetPreviousWidgetInfo(UI.gui)\n                    if v and v ~= \"nil\" and spellData[v.id] ~= nil then --判空，防止法术数据异常\n                        GuiZSetForNextWidget(UI.gui, UI.GetZDeep() - 102)\n						GuiOptionsAddForNextWidget(UI.gui, GUI_OPTION.Layout_NoLayouting)\n                        GuiImage(UI.gui, UI.NewID(id .. v.id .. tostring(i) .. \"BG\"), weigthX, weigthY,\n                            SpellTypeBG[spellData[v.id].type],\n                            1, 0.5)\n						local sw,sh = GuiGetImageDimensions(UI.gui, spellData[v.id].sprite, 0.5)\n                        GuiZSetForNextWidget(UI.gui, UI.GetZDeep() - 103)\n						GuiOptionsAddForNextWidget(UI.gui, GUI_OPTION.Layout_NoLayouting)\n                        GuiImage(UI.gui, UI.NewID(id .. v.id .. \"spell\" .. tostring(i)), weigthX + (weigthW-sw)/2, weigthY + (weigthH-sh)/2, spellData[v.id].sprite, 1,\n                            0.5)\n                        local DrawUses = function(thisUses)\n                            GuiZSetForNextWidget(UI.gui, UI.GetZDeep() - 104)\n							GuiOptionsAddForNextWidget(UI.gui, GUI_OPTION.Layout_NoLayouting)\n                            if thisUses then\n                                GuiText(UI.gui, weigthX, weigthY, tostring(thisUses), 0.5, \"data/fonts/font_small_numbers.xml\")\n                            else\n                                GuiText(UI.gui, weigthX, weigthY, tostring(v.uses_remaining), 0.5,\n                                    \"data/fonts/font_small_numbers.xml\")\n                            end\n                        end\n                        if v.uses_remaining ~= -1 and inf_spells_enable and spellData[v.id].never_unlimited then --开启无限法术了，还不为空，那么就直接作为结果\n                            DrawUses()\n                            --没开启无限法术，使用次数为无限，但是查询其有使用次数为有限的那么就拿查询的作为结果\n                        elseif not inf_spells_enable and (v.uses_remaining == -1 or v.uses_remaining == nil) and (spellData[v.id].max_uses and spellData[v.id].max_uses ~= -1) then\n                            DrawUses(spellData[v.id].max_uses)\n                        elseif v.uses_remaining ~= -1 and not inf_spells_enable then\n                            DrawUses()\n                        end\n                    end\n                    if weigthX + weigthW >= UI.ScreenWidth - 80 then\n                        GuiLayoutEnd(UI.gui)\n                        GuiLayoutBeginHorizontal(UI.gui, 0, 0, true)\n                    end\n                end\n                GuiLayoutEnd(UI.gui)\n                GuiColorSetForNextWidget(UI.gui, 0.5, 0.5, 0.5, 1.0)\n                GuiText(UI.gui, 0, 0, GameTextGet(\"$wand_editor_wand_depot_wand_desc\"))\n                if not HistoryMode and wand.__DepotPin and PinImageMap[wand.__DepotPin] then\n                    GuiColorSetForNextWidget(UI.gui, 0.5, 0.5, 0.5, 1.0)\n					GuiText(UI.gui, 0, 0, GameTextGet(\"$wand_editor_pin_del_tip\",string.lower(GameTextGet(\"$wand_editor_pin_\" .. wand.__DepotPin))))\n				elseif CurrentPin and not HistoryMode then\n					GuiColorSetForNextWidget(UI.gui, 0.5, 0.5, 0.5, 1.0)\n					GuiText(UI.gui, 0, 0, GameTextGet(\"$wand_editor_pin_add_tip\", string.lower(GameTextGet(\"$wand_editor_pin_\" .. CurrentPin))))\n				end\n            end\n            GuiLayoutEnd(UI.gui)\n        end, UI.GetZDeep() - 100, 10)\n    end\n    local CTRL = InputIsKeyDown(Key_LCTRL) or InputIsKeyDown(Key_RCTRL)\n    if left_click and (not CTRL) then\n        if UI.UserData[\"WandDepotKHighlight\"] == k then\n            UI.UserData[\"WandDepotKHighlight\"] = nil\n        else\n            UI.UserData[\"WandDepotKHighlight\"] = k\n        end\n    elseif left_click and CTRL and UI.UserData[\"WandDepotKHighlight\"] then --交换法杖操作\n        if k ~= UI.UserData[\"WandDepotKHighlight\"] and not HistoryMode then\n            local CurrentIndex = UI.UserData[\"WandDepotCurrentIndex\"]\n            local CurrentTable = GetWandDepot(CurrentIndex)\n            if CurrentTable[UI.UserData[\"WandDepotKHighlight\"] + 1] ~= nil and CurrentTable[k + 1] ~= nil then\n                local oldTable = CurrentTable[UI.UserData[\"WandDepotKHighlight\"] + 1]\n                CurrentTable[UI.UserData[\"WandDepotKHighlight\"] + 1] = wand\n                CurrentTable[k + 1] = oldTable\n                --TablePrint(CurrentTable)\n                --print(\"k:\",k,\"|HG:\",UI.UserData[\"WandDepotKHighlight\"])\n                SetWandDepotLua(CurrentTable, CurrentIndex)\n                UI.UserData[\"WandDepotKHighlight\"] = nil\n            end\n        end\n    end\n    if not HistoryMode and right_click then\n        if wand.__DepotPin then\n            wand.__DepotPin = nil\n		elseif CurrentPin then\n            wand.__DepotPin = CurrentPin\n        end\n		local CurrentIndex = UI.UserData[\"WandDepotCurrentIndex\"]\n        local CurrentTable = GetWandDepot(CurrentIndex)\n		SetWandDepotLua(CurrentTable, CurrentIndex)\n	end\n    GuiZSetForNextWidget(UI.gui, UI.GetZDeep() - 2)\n    GuiImage(UI.gui, UI.NewID(id .. tostring(k)), 5 + x, 22 + y, sprite, 1, 1, 0, deg57_5)\nend\n\nlocal HistoryCache\nlocal HistoryCacheTable\nlocal HistorySetKey = ModID..\"WandEditHistoryData\"\nlocal function GetHistoryData()\n    local str = ModSettingGet(HistorySetKey)\n	if str == nil then\n        ModSettingSet(HistorySetKey, \"return {}\")\n		str = \"return {}\"\n	end\n    local CheckFnStr = tostring(str)\n	CheckFnStr = CheckFnStr\n    if HistoryCache == nil then --数据缓存\n        HistoryCache = CheckFnStr\n    elseif HistoryCache == CheckFnStr and HistoryCacheTable then\n        return HistoryCacheTable\n    elseif HistoryCache ~= CheckFnStr then\n        HistoryCache = CheckFnStr\n    end\n	if HasEnds(CheckFnStr) then\n		ModSettingSet(HistorySetKey, \"return {}\")\n		return {}\n	end\n	local CheckFn = loadstring(CheckFnStr)\n	if type(CheckFn) ~= \"function\" then--数据恢复为空表，有代码或其他行为试图篡改为非法数据\n		ModSettingSet(HistorySetKey,\"return {}\")\n		return {}\n	end\n	local fn = setfenv(CheckFn, {})\n	local flag, result = pcall(fn)\n	if not flag then --数据恢复为空表，有代码或其他行为试图篡改为非法数据\n		ModSettingSet(HistorySetKey, \"return {}\")\n		return {}\n	end\n	HistoryCacheTable = result\n	return result\nend\n\nlocal function SetHisroryData(t)\n	ModSettingSet(HistorySetKey, \"return {\\n\" .. SerializeTable(t) .. \"}\")\nend\n\nfunction WandDepotCB(_, _right, _, _, this_enable)\n    if _right then\n		ClickSound()\n		UI.UserData[\"WandDepotHistoryEnable\"] = not UI.UserData[\"WandDepotHistoryEnable\"]\n	end\n    if not this_enable then\n        return\n    end\n	local HistoryMode = UI.UserData[\"WandDepotHistoryEnable\"]\n	if UI.UserData[\"WandDepotCurrentIndex\"] == nil then\n		UI.UserData[\"WandDepotCurrentIndex\"] = 1\n	end\n	local CurrentIndex = UI.UserData[\"WandDepotCurrentIndex\"]\n    if GetWandDepotSize() == 0 then\n        NewWandDepot()\n        UI.UserData[\"WandDepotCurrentIndex\"] = 1\n    end\n    local CurrentTable\n    if HistoryMode then\n        CurrentTable = GetHistoryData()\n    else\n		CurrentTable = GetWandDepot(CurrentIndex)\n	end\n	local WandDepotH = 210\n	local WandDepotW = 278\n	UI.ScrollContainer(\"WandDepot\", 20, 64, WandDepotW, WandDepotH, 2, 2)\n	UI.AddAnywhereItem(\"WandDepot\", function()\n		for k, v in pairs(CurrentTable) do --绘制法杖格\n			DrawWandSlot(\"WandDepotSlot\", k, v)\n		end\n	end)\n    if #CurrentTable == 0 then --如果是空的绘制一段文本\n        UI.AddAnywhereItem(\"WandDepot\", function()\n            GuiZSetForNextWidget(UI.gui, UI.GetZDeep() - 1)\n            GuiText(UI.gui, 5, 5, GameTextGet(\"$wand_editor_wand_depot_isempty\"))\n        end)\n    end\n\n    UI.AddAnywhereItem(\"WandDepot\", function()\n        if HistoryMode then\n            GuiLayoutBeginHorizontal(UI.gui, 2, WandDepotH - 10, true)\n			local deleteTextKey = \"$wand_editor_wand_depot_history_clear\"\n            if UI.UserData[\"wand_editor_wand_depot_history_clear\"] then\n                deleteTextKey = \"$wand_editor_wand_depot_history_clear_IKnowWhatImDoing\"\n            end\n\n            GuiZSetForNextWidget(UI.gui, UI.GetZDeep() - 1)\n            local del_click = GuiButton(UI.gui, UI.NewID(\"WandDepotHistoryDel\"), 0, 0, \"[x]\")\n			local _, _, del_hover = GuiGetPreviousWidgetInfo(UI.gui)\n            GuiTooltip(UI.gui, GameTextGet(deleteTextKey), \"\")\n			if not del_hover and UI.UserData[\"wand_editor_wand_depot_history_clear\"] then\n				UI.UserData[\"wand_editor_wand_depot_history_clear\"] = nil\n			end\n			if del_click and UI.UserData[\"wand_editor_wand_depot_history_clear\"] == nil then\n                UI.UserData[\"wand_editor_wand_depot_history_clear\"] = true\n            elseif del_click and UI.UserData[\"wand_editor_wand_depot_history_clear\"] then\n                ModSettingSet(HistorySetKey, \"return {}\")\n				UI.UserData[\"wand_editor_wand_depot_history_clear\"] = nil\n			end\n			\n			GuiZSetForNextWidget(UI.gui, UI.GetZDeep() - 1)\n            local CopyDepot_click = GuiButton(UI.gui, UI.NewID(\"WandDepotHistoryCopyDepot\"), 12, 0, \"[c]\")\n			GuiTooltip(UI.gui, GameTextGet(\"$wand_editor_wand_depot_history_copy\"), \"\")\n			if CopyDepot_click then\n				Cpp.SetClipboard(ModSettingGet(HistorySetKey))\n			end\n			GuiLayoutEnd(UI.gui)\n			return\n		end\n		GuiLayoutBeginHorizontal(UI.gui, 2, WandDepotH - 10, true)\n		GuiZSetForNextWidget(UI.gui, UI.GetZDeep() - 1)\n		local add_click = GuiButton(UI.gui, UI.NewID(\"WandDepotAddTable\"), 0, 0, \"[+]\") --新增页面按钮\n        GuiTooltip(UI.gui, GameTextGet(\"$wand_editor_wand_depot_newpage\"), \"\")\n		local CTRL = InputIsKeyDown(Key_LCTRL) or InputIsKeyDown(Key_RCTRL)\n        if add_click and CTRL then\n            local ClipboardData = Cpp.GetClipboard()\n			local flag,newPage = CheckWandDepotData(ClipboardData)\n            if flag then\n                local ALT = InputIsKeyDown(Key_LALT) or InputIsKeyDown(Key_RALT)\n                if ALT then\n					SetWandDepotLua(newPage,CurrentIndex)\n                else					\n                	NewWandDepot(newPage)\n				end\n				GamePrint(GameTextGet(\"$wand_editor_wand_depot_copy_correctly\"))\n            else\n				GamePrint(GameTextGet(\"$wand_editor_wand_depot_copy_error\"))\n			end\n        elseif add_click then\n            local ALT = InputIsKeyDown(Key_LALT) or InputIsKeyDown(Key_RALT)\n			if ALT then\n				SetWandDepotLua({},CurrentIndex)\n            else\n				NewWandDepot()\n			end\n		end\n\n		GuiZSetForNextWidget(UI.gui, UI.GetZDeep() - 1)\n		local delete_click = GuiButton(UI.gui, UI.NewID(\"WandDepotDeleteTable\"), 11, 0, \"[x]\") --删除页面按钮\n		local deleteTextKey = \"$wand_editor_wand_depot_deletepage\"\n        if UI.UserData[\"wand_depot_IKnowWhatImDoing\"] then\n            deleteTextKey = \"$wand_editor_wand_depot_deletepage_IKnowWhatImDoing\"\n        end\n		local _, _, delete_hover = GuiGetPreviousWidgetInfo(UI.gui)\n		GuiTooltip(UI.gui, GameTextGet(deleteTextKey), \"\")\n        if UI.UserData[\"wand_depot_IKnowWhatImDoing\"] and delete_hover and delete_click then\n            UI.UserData[\"wand_depot_IKnowWhatImDoing\"] = false\n            if CurrentIndex > GetWandDepotSize() - 1 and CurrentIndex - 1 ~= 0 then --防止越界\n                UI.UserData[\"WandDepotCurrentIndex\"] = CurrentIndex - 1\n            end\n            RemoveWandDepot(CurrentIndex)\n        elseif UI.UserData[\"wand_depot_IKnowWhatImDoing\"] and (not delete_hover) then\n            UI.UserData[\"wand_depot_IKnowWhatImDoing\"] = false\n        elseif delete_click and delete_hover then\n            UI.UserData[\"wand_depot_IKnowWhatImDoing\"] = true\n        end\n		\n		GuiZSetForNextWidget(UI.gui, UI.GetZDeep() - 1)\n        local CopyDepot_click = GuiButton(UI.gui, UI.NewID(\"WandDepotCopyDepot\"), 12, 0, \"[c]\")\n		GuiTooltip(UI.gui, GameTextGet(\"$wand_editor_wand_depot_copy\"), \"\")\n        if CopyDepot_click then\n			Cpp.SetClipboard(GetWandDepotStr(CurrentIndex))\n		end\n		GuiLayoutEnd(UI.gui)\n\n		GuiLayoutBeginHorizontal(UI.gui, WandDepotW / 2 - 47, WandDepotH - 10, true)\n		GuiZSetForNextWidget(UI.gui, UI.GetZDeep() - 1)\n		local topmast_click = GuiButton(UI.gui, UI.NewID(\"WandDepotTopmost\"), 0, 0, \"<<\")\n		if topmast_click then\n			UI.UserData[\"WandDepotCurrentIndex\"] = 1\n		end\n		GuiZSetForNextWidget(UI.gui, UI.GetZDeep() - 1)\n		local up_click = GuiButton(UI.gui, UI.NewID(\"WandDepotUp\"), 5, 0, \"<\")\n		if up_click and CurrentIndex > 1 then\n			UI.UserData[\"WandDepotCurrentIndex\"] = UI.UserData[\"WandDepotCurrentIndex\"] - 1\n		end\n		GuiLayoutEnd(UI.gui)\n\n		GuiLayoutBeginHorizontal(UI.gui, WandDepotW / 2, WandDepotH - 10, true)\n\n		GuiOptionsAddForNextWidget(UI.gui, GUI_OPTION.Align_HorizontalCenter)\n		GuiZSetForNextWidget(UI.gui, UI.GetZDeep() - 1)\n		local text = UI.TextInput(\"WandDepotPage\", 0, 0, 35, 5, \"1\", \"1234567890\")\n		local _, _, hover = GuiGetPreviousWidgetInfo(UI.gui)\n		local page = tonumber(text)\n		if not hover and text == \"\" then\n			UI.TextInputRestore(\"WandDepotPage\")\n		elseif page and page ~= CurrentIndex and hover then\n			if page > GetWandDepotSize() then\n				local max = GetWandDepotSize()\n				UI.UserData[\"WandDepotCurrentIndex\"] = max\n                UI.SetInputText(\"WandDepotPage\", tostring(max))\n            elseif page <= 0 then\n                page = 1\n				UI.UserData[\"WandDepotCurrentIndex\"] = page\n				UI.SetInputText(\"WandDepotPage\", tostring(page))\n			else --及时同步\n                UI.UserData[\"WandDepotCurrentIndex\"] = page\n				UI.SetInputText(\"WandDepotPage\", tostring(page))\n			end\n		elseif page and page ~= CurrentIndex then\n			UI.SetInputText(\"WandDepotPage\", tostring(CurrentIndex))\n		end\n		GuiZSetForNextWidget(UI.gui, UI.GetZDeep() - 1)\n		GuiText(UI.gui, -4, 0, \"/\" .. tostring(math.max(GetWandDepotSize(), 1)))\n\n		GuiZSetForNextWidget(UI.gui, UI.GetZDeep() - 1)\n		local next_click = GuiButton(UI.gui, UI.NewID(\"WandDepotNext\"), 2, 0, \">\")\n		if next_click and CurrentIndex < GetWandDepotSize() then\n			UI.UserData[\"WandDepotCurrentIndex\"] = CurrentIndex + 1\n		end\n		GuiZSetForNextWidget(UI.gui, UI.GetZDeep() - 1)\n		local bottom_click = GuiButton(UI.gui, UI.NewID(\"WandDepotBottom\"), 7, 0, \">>\")\n		if bottom_click then\n			UI.UserData[\"WandDepotCurrentIndex\"] = GetWandDepotSize()\n		end\n		GuiLayoutEnd(UI.gui)\n	end)\n	UI.DrawScrollContainer(\"WandDepot\", false) --绘制框内控件和框\n	\n	if not HistoryMode then\n		local DepotSaveCB = function(left_click)\n			if left_click then\n				ClickSound()\n				local held = GetHeldWand()\n				if held == nil then\n					return\n				end\n				if #CurrentTable >= TableMax then\n					GamePrint(GameTextGet(\"$wand_editor_wand_depot_limit\"))\n					return\n				end\n				local wand = GetWandData(held)\n				wand.wandEntity = nil\n				CurrentTable[#CurrentTable + 1] = wand\n				SetWandDepotLua(CurrentTable, CurrentIndex)\n			end\n		end\n		GuiZSetForNextWidget(UI.gui, UI.GetZDeep())\n		UI.MoveImageButton(\"WandDepotSave\", 20, 64 + WandDepotH + 7,\n			\"mods/wand_editor/files/gui/images/wand_depot_save.png\", nil, function()\n				GuiTooltip(UI.gui, GameTextGet(\"$wand_editor_wand_depot_save\"), \"\")\n			end, DepotSaveCB, false, true)\n	end\n	\n    local DepotDeleteCB = function(left_click)\n        if left_click then\n            ClickSound()\n            if UI.UserData[\"WandDepotKHighlight\"] == nil then\n                return\n            end\n			if UI.UserData[\"WandDepotKHighlight\"] > #CurrentTable then\n				return\n			end\n			if UI.UserData[\"wand_depot_deleteWand_IKnowWhatImDoing\"] == nil then\n				UI.UserData[\"wand_depot_deleteWand_IKnowWhatImDoing\"] = true\n				return\n			end\n			local hgK = UI.UserData[\"WandDepotKHighlight\"] + 1\n			local wand = CurrentTable[hgK]\n			if not (wand.__DepotPin and PinImageMap[wand.__DepotPin]) then\n				UI.UserData[\"wand_depot_deleteWand_IKnowWhatImDoing\"] = nil\n				local k = UI.UserData[\"WandDepotKHighlight\"] + 1\n				table.remove(CurrentTable, k)\n				if HistoryMode then\n					SetHisroryData(CurrentTable)\n				else\n					SetWandDepotLua(CurrentTable, CurrentIndex)\n				end\n				if k > #CurrentTable then--删除后检查\n					UI.UserData[\"WandDepotKHighlight\"] = nil\n				end\n			end\n\n        end\n    end\n    local deleteTextKey = \"$wand_editor_wand_depot_delete\"\n    if UI.UserData[\"wand_depot_deleteWand_IKnowWhatImDoing\"] then\n		local hgK = UI.UserData[\"WandDepotKHighlight\"] + 1\n		local wand = CurrentTable[hgK]\n		if not HistoryMode and wand.__DepotPin and PinImageMap[wand.__DepotPin] then\n			deleteTextKey = \"$wand_editor_wand_depot_delete_pin\"\n        else\n			deleteTextKey = \"$wand_editor_wand_depot_delete_IKnowWhatImDoing\"\n		end\n	end\n	GuiZSetForNextWidget(UI.gui, UI.GetZDeep())\n	UI.MoveImageButton(\"WandDepotDelete\", 45, 64 + WandDepotH + 7,\n        \"mods/wand_editor/files/gui/images/wand_depot_delete.png\", nil, function()\n            local _, _, hover = GuiGetPreviousWidgetInfo(UI.gui)\n			if not hover then\n				UI.UserData[\"wand_depot_deleteWand_IKnowWhatImDoing\"] = nil\n			end\n			GuiTooltip(UI.gui, GameTextGet(deleteTextKey), \"\")\n		end, DepotDeleteCB, false, true)\n\n	local RewriteWandCB = function(left_click)\n		if left_click then\n            ClickSound()\n            if UI.UserData[\"WandDepotKHighlight\"] == nil then\n                return\n            end\n			local k = UI.UserData[\"WandDepotKHighlight\"] + 1\n			local held = GetHeldWand()\n			if held == nil then\n				return\n			end\n			if k <= #CurrentTable then\n				local wand = CurrentTable[k]\n				InitWand(wand, held)\n			end\n			UI.OnceCallOnExecute(function()\n				RefreshHeldWands()\n			end)\n		end\n	end\n	GuiZSetForNextWidget(UI.gui, UI.GetZDeep())\n	UI.MoveImageButton(\"WandDepotRewriteWand\", 70, 64 + WandDepotH + 7,\n		\"mods/wand_editor/files/gui/images/wand_depot_rewritewand.png\", nil, function()\n			GuiTooltip(UI.gui, GameTextGet(\"$wand_editor_wand_depot_rewritewand\"), \"\")\n		end, RewriteWandCB, false, true)\n\n	local LoadWandCB = function(left_click)\n		if left_click then\n			ClickSound()\n            if UI.UserData[\"WandDepotKHighlight\"] == nil then\n                return\n            end\n\n			local k = UI.UserData[\"WandDepotKHighlight\"] + 1\n			if k <= #CurrentTable then\n				local wand = CurrentTable[k]\n				InitWand(wand, nil, Compose(EntityGetTransform, GetPlayer)())\n			end\n		end\n	end\n	GuiZSetForNextWidget(UI.gui, UI.GetZDeep())\n	UI.MoveImageButton(\"WandDepotLoadWand\", 95, 64 + WandDepotH + 7,\n		\"mods/wand_editor/files/gui/images/wand_depot_loadwand.png\", nil, function()\n			GuiTooltip(UI.gui, GameTextGet(\"$wand_editor_wand_depot_loadwand\"), \"\")\n        end, LoadWandCB, false, true)\n		\n    local function HelpHover()\n        UI.tooltips(function()\n            GuiText(UI.gui, 0, 0, GameTextGetTranslatedOrNot(\"$wand_editor_wand_depot_help\"))\n        end, nil, 5)\n    end\n	GuiZSetForNextWidget(UI.gui, UI.GetZDeep())\n	UI.MoveImageButton(\"WandDepotHelp\", 130,64 + WandDepotH + 11,\n        \"mods/wand_editor/files/gui/images/help.png\", nil, HelpHover, nil, nil, true)\n	if not HistoryMode then\n		local PinSelectText = {GameTextGet(\"$wand_editor_pin_deselect\"),GameTextGet(\"$wand_editor_pin_select\")}\n		for k, v in pairs(PinList) do\n			local function PinCB(pin_click, _, _, _, pin_enable)\n				if not pin_enable then\n					if CurrentPin == v then\n						CurrentPin = nil\n					end\n					return\n				end\n				CurrentPin = v\n			end\n			GuiZSetForNextWidget(UI.gui, UI.GetZDeep() - 3)\n			UI.MoveImagePicker(\"WandDepotPinList\" .. v, 6, 64 + (k - 1) * 13, 8, 4,\n				GameTextGet(\"$wand_editor_pin_\" .. v) .. GameTextGet(\"$wand_editor_pin\"), PinImageMap[v], PinSelectText, PinCB,\n				nil, true, nil, true, true)\n			\n		end\n	end\nend\n\nUI.MiscEventFn[\"LoadWandBox\"] = function ()\n	if ModSettingGet(ModID .. \"LoadSpellLab\") then\n		local flag = ModDoesFileExist(\"mods/spell_lab/files/lib/wands.lua\")\n		flag = flag or ModDoesFileExist(\"mods/spell_lab/files/lib/smallfolk.lua\")\n		if not flag then\n			GamePrint(GameTextGet(\"$wand_editor_spell_lab_load_import_wand_box_error\"))\n			GamePrint(GameTextGet(\"$wand_editor_load_spell_lab_wand_box_error\"))\n		else\n			local posX = 14600\n			local posY = -45804\n			local smallfolk = dofile(\"mods/spell_lab/files/lib/smallfolk.lua\")\n			local WANDS = dofile_once(\"mods/spell_lab/files/lib/wands.lua\")\n			local saved_wand_data = ModSettingGet(\"spell_lab_saved_wands\")\n			if saved_wand_data ~= nil then\n                local loaded_wands = smallfolk.loads(saved_wand_data)\n                local AllTable = {}\n				local Current = {}\n                for k, v in pairs(loaded_wands) do\n                    local wand = EntityLoad(\"data/entities/items/wand_level_03.xml\", posX, posY)\n                    WANDS.initialize_wand(wand, v)\n                    local t = GetWandData(wand)\n                    if #Current >= TableMax then\n                        AllTable[#AllTable + 1] = Current\n                        Current = {}\n                    end\n                    Current[#Current + 1] = t\n                    EntityKill(wand)\n                end\n				AllTable[#AllTable + 1] = Current\n				for _,v in pairs(AllTable)do\n					if #v ~= 0 then\n						NewWandDepot(v)\n					end\n				end\n			end\n			\n			GamePrint(GameTextGet(\"$wand_editor_load_import_wand_box_done\"))\n		end\n		ModSettingSet(ModID .. \"LoadSpellLab\", false)\n	end\n	if ModSettingGet(ModID .. \"LoadECSSpellLab\") then\n		local flag = ModDoesFileExist(\"mods/_EcsGui/files/lib/wands.lua\")\n		flag = flag or ModDoesFileExist(\"mods/_EcsGui/files/lib/smallfolk.lua\")\n		if not flag then\n			GamePrint(GameTextGet(\"$wand_editor_wands_conn_load_import_wand_box_error\"))\n			GamePrint(GameTextGet(\"$wand_editor_load_wands_conn_wand_box_error\"))\n		else\n			local posX = 14600\n			local posY = -45804\n			local smallfolk = dofile(\"mods/_EcsGui/files/lib/smallfolk.lua\")\n			local WANDS = dofile_once(\"mods/_EcsGui/files/lib/wands.lua\")\n			local saved_wand_data = ModSettingGet(\"WandsConn_saved_wands\")\n			if saved_wand_data ~= nil then\n                local loaded_wands = smallfolk.loads(saved_wand_data)\n                local AllTable = {}\n				local Current = {}\n                for k, v in pairs(loaded_wands) do\n                    local wand = EntityLoad(\"data/entities/items/wand_level_03.xml\", posX, posY)\n                    WANDS.initialize_wand(wand, v)\n                    local t = GetWandData(wand)\n                    if #Current >= TableMax then\n                        AllTable[#AllTable + 1] = Current\n                        Current = {}\n                    end\n                    Current[#Current + 1] = t\n                    EntityKill(wand)\n                end\n				AllTable[#AllTable + 1] = Current\n				for _,v in pairs(AllTable)do\n					if #v ~= 0 then\n						NewWandDepot(v)\n					end\n				end\n			end\n			GamePrint(GameTextGet(\"$wand_editor_load_import_wand_box_done\"))\n		end\n		ModSettingSet(ModID .. \"LoadECSSpellLab\", false)\n	end\n	if ModSettingGet(ModID .. \"LoadSpellLabShug\") then\n		local flag = ModDoesFileExist(\"mods/spell_lab_shugged/files/lib/wands.lua\")\n		flag = flag or ModDoesFileExist(\"mods/spell_lab_shugged/files/lib/smallfolk.lua\")\n		if not flag then\n			GamePrint(GameTextGet(\"$wand_editor_spell_lab_shugged_load_import_wand_box_error\"))\n			GamePrint(GameTextGet(\"$wand_editor_load_spell_lab_shug_wand_box_error\"))\n		else\n            local MaxIndex = ModSettingGet(\"spell_lab_shugged.wand_box_page_max_index\")\n			if MaxIndex ~= nil or MaxIndex ~= 0 then\n				local smallfolk = dofile(\"mods/spell_lab_shugged/files/lib/smallfolk.lua\")\n                local WANDS = dofile_once(\"mods/spell_lab_shugged/files/lib/wands.lua\")\n				local AllTable = {}\n                local Current = {}\n				local posX = 14600\n				local posY = -45804\n                for i = 1, MaxIndex do\n                    local saved_wand_data = ModSettingGet(\"spell_lab_shugged.wand_box_page_\" .. tostring(i))\n                    if saved_wand_data ~= nil then\n                        local loaded_wands = smallfolk.loads(saved_wand_data)\n                        for k, v in pairs(loaded_wands) do\n                            local wand = EntityLoad(\"data/entities/items/wand_level_03.xml\", posX, posY)\n                            WANDS.initialize_wand(wand, v)\n                            local t = GetWandData(wand)\n                            if #Current >= TableMax then\n                                AllTable[#AllTable + 1] = Current\n                                Current = {}\n                            end\n                            Current[#Current + 1] = t\n							EntityKill(wand)\n                        end\n						AllTable[#AllTable + 1] = Current\n						Current = {}\n                    end\n                end\n				AllTable[#AllTable + 1] = Current\n                for _, v in pairs(AllTable) do\n					if #v ~= 0 then\n						NewWandDepot(v)\n					end\n				end\n			end\n			GamePrint(GameTextGet(\"$wand_editor_load_import_wand_box_done\"))\n		end\n		ModSettingSet(ModID .. \"LoadSpellLabShug\", false)\n	end\nend\n"
_TWWE_VFS["mods/wand_editor/files/gui/update.lua"] = "function GUIUpdate()\n    local fastConcatStr = Cpp.ConcatStr\n	\n	local function AddNullEntityToPlayer(name)\n        local id = EntityLoadChild(GetPlayer(), \"mods/wand_editor/files/entity/NullEntity.xml\")\n        EntitySetName(id, name)\n		return id\n	end\n\n	local function RemoveNullEntityWithName(name)\n		EntityKill(EntityGetWithName(name))\n	end\n	local MainBtnEnable = false\n	if UI == nil then\n		--初始化\n		---@class Gui\n        UI = dofile_once(\"mods/wand_editor/files/libs/gui.lua\")\n		\n		dofile_once(\"data/scripts/lib/utilities.lua\")\n		dofile_once(\"mods/wand_editor/files/gui/SpellsScroll.lua\")\n        dofile_once(\"mods/wand_editor/files/gui/WandContainer.lua\")\n        dofile_once(\"mods/wand_editor/files/gui/WandBuilder.lua\")\n        dofile_once(\"mods/wand_editor/files/gui/WandDepot.lua\")\n		dofile_once(\"mods/wand_editor/files/gui/TargetDummyGUI.lua\")\n		dofile_once(\"mods/wand_editor/files/gui/ToggleOptions.lua\")\n		UI.UserData[\"HasSpellMove\"] = false\n		local data = dofile_once(\"mods/wand_editor/files/gui/GetSpellData.lua\") --读取法术数据\n		local spellData = data[1]\n        local TypeToSpellList = data[2]\n        local RefreshRealUnlimitedSpells = data[3]\n		_ToFnSpellData = spellData\n		dofile(\"mods/wand_editor/files/libs/fn.lua\")\n		local ZDeepest = UI.GetZDeep()\n		---绘制一个悬浮法术\n		---@param x number\n		---@param y number\n		---@param sprite string\n		---@param id string\n		function DrawFloatSpell(x, y, sprite, id)\n			local hasMove = UI.UserData[\"HasSpellMove\"]\n			if not hasMove and not UI.GetNoMoveBool() then\n				UI.UserData[\"FloatSpellID\"] = id\n				UI.UserData[\"HasSpellMove\"] = true\n                UI.TickEventFn[\"MoveSpellFn\"] = function() --分离出一个事件，用于表示法术点击后的效果\n                    UI.OnceCallOnExecute(function()\n                        if UI.UserData[\"WandContainerHasHover\"] == nil or UI.UserData[\"WandContainerHasHover\"] then\n							UI.UserData[\"WandContainerHasHover\"] = false\n						end\n					end)\n					local click = InputIsMouseButtonDown(Mouse_right)\n					if click or GameIsInventoryOpen() then          --右键取消，或打开物品栏取消\n						if GameIsInventoryOpen() and UI.UserData[\"UpSpellIndex\"] then --如果是点击之前的法术并且打开了物品栏，恢复法术\n							SetTableSpells(UI.UserData[\"UpSpellIndex\"][2], UI.UserData[\"FloatSpellID\"],\n								UI.UserData[\"UpSpellIndex\"][1], UI.UserData[\"UpSpellIndex\"][4], false)\n							InitWand(UI.UserData[\"UpSpellIndex\"][2], UI.UserData[\"UpSpellIndex\"][3])\n						end\n						UI.OnMoveImage(\"MoveSpell\", x, y, sprite, true)\n						UI.TickEventFn[\"MoveSpellFn\"] = nil\n						UI.UserData[\"HasSpellMove\"] = false\n						UI.UserData[\"FloatSpellID\"] = nil\n						UI.UserData[\"UpSpellIndex\"] = nil\n						return\n					end\n					--绘制悬浮图标\n					local status = UI.OnMoveImage(\"MoveSpell\", x, y, sprite, nil, nil, ZDeepest - 114514,\n						UI.UserData[\"SpellHoverEnable\"],\n                        function(movex, movey)\n                            local sw, sh = GuiGetImageDimensions(UI.gui, spellData[id].sprite, 1)\n                            local w, h = GuiGetImageDimensions(UI.gui, \"data/ui_gfx/inventory/full_inventory_box.png\", 1)\n							GuiZSetForNextWidget(UI.gui, ZDeepest - 114513)\n							GuiImage(UI.gui, UI.NewID(\"MoveSpell_BG\"), movex - (w-sw)/2, movey - (h-sh)/2,\n								SpellTypeBG[spellData[id].type], 1, 1)                                         --绘制背景\n						end)\n					local LeftClick = (InputIsMouseButtonDown(Mouse_left) and not ModSettingGet(fastConcatStr(ModID, \"SpellDepotCloseSpellOnGround\")))\n					if not UI.UserData[\"WandContainerHasHover\"] and LeftClick then\n                        UI.UserData[\"SpellHoverEnable\"] = true\n					end\n					if not status then\n						UI.TickEventFn[\"MoveSpellFn\"] = nil\n                        if (not UI.UserData[\"WandContainerHasHover\"]) then\n							local worldx, worldy = DEBUG_GetMouseWorld()\n							local spell = CreateItemActionEntity(id, worldx, worldy + 5)\n							if UI.UserData[\"UpSpellIndex\"] and UI.UserData[\"UpSpellIndex\"][4] ~= nil then\n								local uses_remaining = UI.UserData[\"UpSpellIndex\"][4]\n								local item = EntityGetFirstComponentIncludingDisabled(spell, \"ItemComponent\")\n								ComponentSetValue2(item, \"uses_remaining\", uses_remaining)\n							end\n							UI.UserData[\"FloatSpellID\"] = nil\n                            UI.UserData[\"UpSpellIndex\"] = nil\n						end\n						UI.UserData[\"HasSpellMove\"] = false\n						UI.OnMoveImage(\"MoveSpell\", x, y, sprite, true)\n					end\n				end\n			end\n		end\n        local function PickerGap(gap)\n            return 19 + gap * 22\n        end\n        local function ClickSound()\n            GamePlaySound(\"data/audio/Desktop/ui.bank\", \"ui/button_click\", GameGetCameraPos())\n        end\n		UI.UserData[\"WandDepotHistoryEnable\"] = false\n		UI.PickerEnableList(\"WandBuilderBTN\", \"SpellDepotBTN\", \"WandDepotBTN\", \"ToggleOptionsBTN\", \"SpwanDummyBTN\")\n        UI.SetCheckboxEnable(\"shuffle_builder\", false)\n		UI.SetCheckboxEnable(\"update_image_builder\", false)\n        local MainCB = function(left_click, right_click, x, _, enable)\n			MainBtnEnable = enable\n            if not enable then\n                return\n            end\n			local y = 12\n            --开启状态\n            local spellDepotText = GameTextGet(\"$wand_editor_spell_depot\")\n			if ModSettingGet(fastConcatStr(ModID,\"SpellDepotCloseSpellOnGround\")) then\n                spellDepotText = fastConcatStr(spellDepotText ,\"\\n\", GameTextGet(\"$wand_editor_spell_depot_close_tips\"))\n            else\n				spellDepotText = fastConcatStr(spellDepotText ,\"\\n\", GameTextGet(\"$wand_editor_spell_depot_open_tips\"))\n			end\n			UI.MoveImagePicker(\"SpellDepotBTN\", PickerGap(0), y + 30, 8, 0, spellDepotText,\n				\"mods/wand_editor/files/gui/images/spell_depot.png\", nil, SpellDepotClickCB, nil, true, nil,\n				true)\n			if not UI.GetPickerStatus(\"SpellDepotBTN\") and not ModSettingGet(ModID .. \"hasButtonMove\") and UI.GetPickerStatus(\"AlwaysDrawWandEditBox\") and UI.GetPickerStatus(\"WandContainerBTN\") then\n				DrawWandContainer(Compose(GetEntityHeldWand, GetPlayer)(), spellData)\n			end\n			UI.MoveImagePicker(\"WandBuilderBTN\", PickerGap(1), y + 30, 8, 0, GameTextGet(\"$wand_editor_wand_spawner\"),\n				\"mods/wand_editor/files/gui/images/wand_builder.png\", nil, WandBuilderCB, nil, true, nil,\n				true)\n			local WandDepotTips\n			if UI.UserData[\"WandDepotHistoryEnable\"] then\n				WandDepotTips = GameTextGet(\"$wand_editor_wand_depot_history\")\n            else\n				WandDepotTips = GameTextGet(\"$wand_editor_wand_depot\")\n			end\n			UI.MoveImagePicker(\"WandDepotBTN\", PickerGap(2), y + 30, 8, 0, WandDepotTips,\n				\"mods/wand_editor/files/gui/images/wand_depot.png\", nil, WandDepotCB, nil, true, nil,\n				true)\n\n			UI.MoveImagePicker(\"SpwanDummyBTN\", PickerGap(3), y + 30, 8, 0, GameTextGet(\"$wand_editor_spawn_dummy\"),\n				\"mods/wand_editor/files/gui/images/spawn_target_dummy.png\", nil, SpwanDummyCB, nil, true, nil,\n                true)\n\n			UI.MoveImagePicker(\"ToggleOptionsBTN\", PickerGap(4), y + 30, 8, 0, GameTextGet(\"$wand_editor_toggle_options\"),\n				\"mods/wand_editor/files/gui/images/toggle_options_icon.png\", nil, ToggleOptionsCB, nil, true, nil,\n                true)\n				--[[\n			GuiZSetForNextWidget(UI.gui, UI.GetZDeep())--生成假人于自身\n			UI.MoveImageButton(\"SpwanDummy\", PickerGap(4), y + 30,\n				\"mods/wand_editor/files/gui/images/spawn_target_dummy.png\", nil, function()\n					GuiTooltip(UI.gui, GameTextGet(\"$wand_editor_spawn_dummy\"), \"\")\n                end,\n				function (click)\n                    if not click then\n                        return\n                    end\n					ClickSound()\n					local px,py = Compose(EntityGetTransform, GetPlayer)()\n                    EntityLoad(\"mods/wand_editor/files/entity/dummy_target.xml\", px, py)\n                end, false, true)]]\n\n			GuiZSetForNextWidget(UI.gui, UI.GetZDeep())--清除投射物\n			UI.MoveImageButton(\"ClearProj\", PickerGap(5), y + 30,\n				\"mods/wand_editor/files/gui/images/clear_projectiles.png\", nil, function()\n					GuiTooltip(UI.gui, GameTextGet(\"$wand_editor_clear_proj\"), \"\")\n                end,\n				function (click)\n                    if not click then\n                        return\n                    end\n                    ClickSound()\n                    local t\n					local CTRL = InputIsKeyDown(Key_LCTRL) or InputIsKeyDown(Key_RCTRL)\n					if CTRL then\n                        t = EntityGetWithTag(\"projectile\") or {}\n                    else\n						t = EntityGetWithTag(\"projectile_player\") or {}\n					end\n					for _,v in pairs(t) do\n						local projectile = EntityGetFirstComponent( v, \"ProjectileComponent\" )\n						if projectile ~= nil then\n							ComponentSetValue2( projectile, \"on_death_explode\", false )\n							ComponentSetValue2( projectile, \"on_lifetime_out_explode\", false )\n						end\n						EntityKill(v)\n					end\n                end, false, true)\n				\n			GuiZSetForNextWidget(UI.gui, UI.GetZDeep())--清除延迟\n			UI.MoveImageButton(\"ClearWait\", PickerGap(6), y + 30,\n				\"mods/wand_editor/files/gui/images/clear_wait.png\", nil, function()\n					GuiTooltip(UI.gui, GameTextGet(\"$wand_editor_clear_wait\"), \"\")\n                end,\n				function (click)\n                    if not click then\n                        return\n                    end\n					ClickSound()\n					local now = GameGetFrameNum()\n                    local player = GetPlayer()\n					for _,v in pairs( EntityGetWithTag(\"wand\") ) do\n						if EntityGetRootEntity( v ) == player then\n							local ability = EntityGetFirstComponentIncludingDisabled( v, \"AbilityComponent\" )\n							if ability then\n								ComponentSetValue2( ability, \"mReloadFramesLeft\", 0 )\n								ComponentSetValue2( ability, \"mNextFrameUsable\", now )\n								ComponentSetValue2( ability, \"mReloadNextFrameUsable\", now )\n							end\n						end\n					end\n                end, false, true)\n				\n			GuiZSetForNextWidget(UI.gui, UI.GetZDeep())--刷新法术使用次数\n			UI.MoveImageButton(\"RefreshUses\", PickerGap(7), y + 30,\n				\"mods/wand_editor/files/gui/images/refresh_uses.png\", nil, function()\n					GuiTooltip(UI.gui, GameTextGet(\"$wand_editor_refresh_uses\"), \"\")\n                end,\n				function (click)\n                    if not click then\n                        return\n                    end\n					ClickSound()\n					GameRegenItemActionsInPlayer(GetPlayer())\n                end, false, true)\n		end\n		---@param this Gui\n        UI.MainTickFn[\"Main\"] = function(this) --我认为的主事件循环）\n            if CSV == nil then\n                CSV = dofile_once(\"mods/wand_editor/files/libs/csv.lua\")(ModTextFileGetContent(\"data/translations/common.csv\"))\n            end\n            if ModSettingGet(\"wand_editor.reset_all_btn\") then\n                UI.ResetAllCanMove()\n                ModSettingSet(\"wand_editor.reset_all_btn\", false)\n            end\n            if GetPlayer() == nil then\n                return\n            end --分离一下停止逻辑\n			if RefreshRealUnlimitedSpells then--刷新法术使用次数\n                GameRegenItemActionsInPlayer(GetPlayer())\n				RefreshRealUnlimitedSpells = false\n			end\n			if UI.UserData[\"LastSpellInfManaEnable\"] == nil then\n				UI.UserData[\"LastSpellInfManaEnable\"] = UI.GetPickerHover(\"SpellInfMana\")\n            elseif UI.UserData[\"LastSpellInfManaEnable\"] ~= UI.GetPickerHover(\"SpellInfMana\") then\n                UI.UserData[\"LastSpellInfManaEnable\"] = UI.GetPickerHover(\"SpellInfMana\")\n				UI.OnceCallOnExecute(function ()--需要刷新法杖的数据来让法术可以正常耗蓝\n					RefreshHeldWands()\n				end)\n			end\n            if GameIsInventoryOpen() then\n                return\n            end\n            if EntityGetWithName(\"WandEditorRestoreEntity\") == 0 then--如果没有人外部手贱删除这个实体，那么应该是玩家重生之类的导致消失了\n				local player = GetPlayer()\n				EntityLoadChild(player, \"mods/wand_editor/files/entity/Restore.xml\")\n				EntityAddComponent2(player, \"LuaComponent\", { script_shot = \"mods/wand_editor/files/misc/self/player_shot.lua\" })\n			end\n            if InputIsKeyDown(Key_BACKSPACE) then\n                local worldx, worldy = DEBUG_GetMouseWorld()\n                local entitys = EntityGetInRadiusWithTag(worldx, worldy, 12, \"polymorphable_NOT\")\n                for _, v in pairs(entitys) do\n                    if EntityGetName(v) == \"wand_editor_dummy_target\" then\n                        EntityKill(v)\n                        GamePrint(GameTextGet(\"$wand_editor_kill_dummy_tip\"))\n                    end\n                end\n            end\n            local MenuPng = \"mods/wand_editor/files/gui/images/menu.png\"\n			if Cpp.PathExists(\"mods/wand_editor/cache/UpdateFlag\") then\n				MenuPng = \"mods/wand_editor/files/gui/images/menu_update.png\"\n			end\n			GuiZSetForNextWidget(this.gui, UI.GetZDeep()) --设置深度，确保行为正确\n			UI.MoveImagePicker(\"MainButton\", 185, 12, 8, 0, GameTextGet(\"$wand_editor_main_button\"),\n				MenuPng, nil, MainCB, nil, false, nil, false)\n        end\n		\n        UI.MiscEventFn[\"RequestAvatar\"] = function()\n			if Cpp.PathExists(\"mods/wand_editor/cache/avatar.png\") then--请求头像\n                UI.MiscEventFn[\"RequestAvatar\"] = nil\n				return\n			end\n            if UI.UserData[\"RequestAvatarMode\"] == nil then\n                local Request = function()\n                    local https = require(\"ssl.https\")\n					local ltn12 = require(\"ltn12\")\n                    local code = 0\n                    local Returns\n					-- 准备sink，用于收集响应体数据\n					local response_chunks = {}\n                    local response_sink = ltn12.sink.table(response_chunks)\n                    local count = 0\n                    while code ~= 200 and count <= 12 do--失败太多次就不请求了\n                        Returns = { https.request {\n							url = \"https://avatars.githubusercontent.com/u/128758465\",\n							sink = response_sink,\n						} }\n                        code = Returns[2]\n						count = count + 1\n                    end\n                    return response_chunks,code\n                end\n                local runner = effil.thread(Request)\n				UI.UserData[\"RequestAvatarhandle\"] = runner()\n                UI.UserData[\"RequestAvatarMode\"] = true\n            elseif UI.UserData[\"RequestAvatarMode\"] then\n				local handle = UI.UserData[\"RequestAvatarhandle\"]\n                local status = handle:status()\n                if status == \"completed\" then\n                    local response_chunks, code = handle:get()\n					if code == 200 then--如果正确请求了，那么就写入文件\n						local file = io.open(\"mods/wand_editor/cache/avatar.png\", \"wb\")\n						for _, chunk in pairs(effil.dump(response_chunks)) do\n							file:write(chunk)\n						end\n						file:close()\n					end\n                    UI.MiscEventFn[\"RequestAvatar\"] = nil\n                    UI.UserData[\"RequestAvatarhandle\"] = nil\n				end\n			end\n		end\n\n        UI.MiscEventFn[\"RequestYukimi\"] = function()\n            local flag1 = Cpp.PathExists(\"mods/wand_editor/cache/yukimi/1.png\") or UI.UserData[\"YKThisRunError1\"]\n            local flag2 = Cpp.PathExists(\"mods/wand_editor/cache/yukimi/2.png\") or UI.UserData[\"YKThisRunError2\"]\n			local flag3 = Cpp.PathExists(\"mods/wand_editor/cache/yukimi/3.png\") or UI.UserData[\"YKThisRunError3\"]\n			local flag4 = Cpp.PathExists(\"mods/wand_editor/cache/yukimi/4.png\") or UI.UserData[\"YKThisRunError4\"]\n            if flag1 and flag2 and flag3 and flag4 then\n				UI.MiscEventFn[\"RequestYukimi\"] = nil\n                return\n            end\n			--没有图片\n            local function RequestDownload(id, link, path)\n                local ModeKey = \"RequestDMode\" .. id\n                local HandleKey = \"RequestDHandle\" .. id\n				\n                if UI.UserData[ModeKey] == nil then\n					local Request = function()\n						local https = require(\"ssl.https\")\n						local ltn12 = require(\"ltn12\")\n						local code = 0\n						local Returns\n						-- 准备sink，用于收集响应体数据\n						local response_chunks = {}\n						local response_sink = ltn12.sink.table(response_chunks)\n						local count = 0\n						while code ~= 200 and count <= 10 do--失败太多次就不请求了\n							Returns = { https.request {\n								url = link,\n								sink = response_sink,\n							} }\n							code = Returns[2]\n							count = count + 1\n						end\n						return response_chunks,code\n					end\n					local runner = effil.thread(Request)\n					UI.UserData[HandleKey] = runner()\n					UI.UserData[ModeKey] = true\n				elseif UI.UserData[ModeKey] then\n					local handle = UI.UserData[HandleKey]\n					local status = handle:status()\n					if status == \"completed\" then\n						local response_chunks, code = handle:get()\n						if code == 200 then--如果正确请求了，那么就写入文件\n							local file = io.open(path, \"wb\")\n							for _, chunk in pairs(effil.dump(response_chunks)) do\n								file:write(chunk)\n							end\n                            file:close()\n                        else\n							UI.UserData[\"YKThisRunError\"..id] = true\n						end\n                        UI.UserData[HandleKey] = nil\n					end\n                end\n            end\n			if not flag1 then\n				RequestDownload(\"1\",\n				\"https://wiki.biligame.com/imascg/index.php?title=Special:Redirect/file/CGSS-Yukimi-Petit-9-1.png\",\n					\"mods/wand_editor/cache/yukimi/1.png\")\n			end\n\n            if not flag2 then\n				RequestDownload(\"2\",\n				\"https://wiki.biligame.com/imascg/index.php?title=Special:Redirect/file/CGSS-Yukimi-Petit-9-2.png\",\n					\"mods/wand_editor/cache/yukimi/2.png\")\n            end\n			\n            if not flag3 then\n				RequestDownload(\"3\",\n				\"https://wiki.biligame.com/imascg/index.php?title=Special:Redirect/file/CGSS-Yukimi-Petit-9-3.png\",\n					\"mods/wand_editor/cache/yukimi/3.png\")\n            end\n			\n			if not flag4 then\n				RequestDownload(\"4\",\n				\"https://wiki.biligame.com/imascg/index.php?title=Special:Redirect/file/CGSS-Yukimi-Petit-9-4.png\",\n					\"mods/wand_editor/cache/yukimi/4.png\")\n			end\n		end\n\n        UI.MiscEventFn[\"Yukimi\"] = function()\n            if ModSettingGet(ModID .. \"YukimiAvailable\") and ModSettingGet(ModID .. \"YukimiAvailableShow\") then\n				if not ModSettingGet(ModID .. \"YukimiAlways\") and not MainBtnEnable then\n					return\n				end\n				local flag = Cpp.PathExists(\"mods/wand_editor/cache/yukimi/1.png\")\n				flag = flag and Cpp.PathExists(\"mods/wand_editor/cache/yukimi/2.png\")\n				flag = flag and Cpp.PathExists(\"mods/wand_editor/cache/yukimi/3.png\")\n				flag = flag and Cpp.PathExists(\"mods/wand_editor/cache/yukimi/4.png\")\n                if flag then\n					if UI.UserData[\"YukimiTimeCount\"] == nil then\n                        UI.UserData[\"YukimiTimeCount\"] = 0\n                    elseif UI.UserData[\"YukimiTimeCount\"] < 2147483647 then\n                        UI.UserData[\"YukimiTimeCount\"] = UI.UserData[\"YukimiTimeCount\"] + 1\n                    else--强制重置逻辑帧计时\n						UI.UserData[\"YukimiTimeCount\"] = 0\n					end\n					local flag2 = Cpp.PathExists(\"mods/wand_editor/cache/yukimi/1_flip.png\")\n					flag2 = flag2 and Cpp.PathExists(\"mods/wand_editor/cache/yukimi/2_flip.png\")\n					flag2 = flag2 and Cpp.PathExists(\"mods/wand_editor/cache/yukimi/3_flip.png\")\n					flag2 = flag2 and Cpp.PathExists(\"mods/wand_editor/cache/yukimi/4_flip.png\")\n                    if not flag2 then\n                        Cpp.FlipImageLoadAndWrite(\"mods/wand_editor/cache/yukimi/1.png\",\n                            \"mods/wand_editor/cache/yukimi/1_flip.png\")\n                        Cpp.FlipImageLoadAndWrite(\"mods/wand_editor/cache/yukimi/2.png\",\n                            \"mods/wand_editor/cache/yukimi/2_flip.png\")\n                        Cpp.FlipImageLoadAndWrite(\"mods/wand_editor/cache/yukimi/3.png\",\n                            \"mods/wand_editor/cache/yukimi/3_flip.png\")\n                        Cpp.FlipImageLoadAndWrite(\"mods/wand_editor/cache/yukimi/4.png\",\n                            \"mods/wand_editor/cache/yukimi/4_flip.png\")\n                    end\n                    local ImgList = {\n						\"mods/wand_editor/cache/yukimi/1_flip.png\",\n                        \"mods/wand_editor/cache/yukimi/2_flip.png\",\n                        \"mods/wand_editor/cache/yukimi/3_flip.png\",\n						\"mods/wand_editor/cache/yukimi/4_flip.png\",\n					}\n                    local YukimiPosX = UI.ScreenWidth-10\n					local YukimiPosY = UI.ScreenHeight-25\n                    if UI.UserData[\"YukimiDEG\"] == nil then\n                        UI.UserData[\"YukimiDEG\"] = -173\n                        UI.UserData[\"YukimiDEGMax\"] = -183\n                    elseif UI.UserData[\"YukimiDEG\"] > UI.UserData[\"YukimiDEGMax\"] then\n                        UI.UserData[\"YukimiDEG\"] = UI.UserData[\"YukimiDEG\"] - 0.18\n                        UI.UserData[\"YukimiDEGMax\"] = -183\n                    else\n                        UI.UserData[\"YukimiDEG\"] = UI.UserData[\"YukimiDEG\"] + 0.18\n                        UI.UserData[\"YukimiDEGMax\"] = -173\n                    end\n                    if UI.UserData[\"YukimiCurrentImg\"] == nil then\n                        SetRandomSeed(GameGetRealWorldTimeSinceStarted(), 1919810)\n                        UI.UserData[\"YukimiCurrentImg\"] = ImgList[Random(1, #ImgList)]\n                    end\n					GuiZSetForNextWidget(UI.gui,UI.GetZDeep())\n					GuiImage(UI.gui, UI.NewID(\"Yukimi\"), YukimiPosX, YukimiPosY, UI.UserData[\"YukimiCurrentImg\"], 1,\n						0.5 / UI.GetScale(), 0, math.rad(UI.UserData[\"YukimiDEG\"]))\n					GuiAnimateBegin(UI.gui)\n                    GuiAnimateAlphaFadeIn(UI.gui, UI.NewID(\"SajoYukimiNoDraw\"), 0, 0, false)\n					GuiZSetForNextWidget(UI.gui,UI.GetZDeep()-1)\n					GuiImage(UI.gui, UI.NewID(\"YukimiTrue\"), YukimiPosX-65, YukimiPosY-55, UI.UserData[\"YukimiCurrentImg\"], 1,\n						0.5 / UI.GetScale(), 0)\n                    GuiAnimateEnd(UI.gui)\n					local YukimiLeftClick = GuiGetPreviousWidgetInfo(UI.gui)\n                    local t = dofile_once(\"mods/wand_editor/files/misc/self/yukimi.lua\")\n                    local RefreshAll = false\n					if UI.UserData[\"YukimiRefreshMax\"] == nil then\n                        SetRandomSeed(GameGetRealWorldTimeSinceStarted(), 114514 + 1919810)\n                        UI.UserData[\"YukimiRefreshMax\"] = 60 * (30 + Random(-10, 5))\n					end\n					if UI.UserData[\"YukimiTimeCount\"] > UI.UserData[\"YukimiRefreshMax\"] then\n                        RefreshAll = true\n						UI.UserData[\"YukimiTimeCount\"] = 0\n						SetRandomSeed(GameGetRealWorldTimeSinceStarted(), 114514 + 1919810)\n                        UI.UserData[\"YukimiRefreshMax\"] = 60 * (30 + Random(-10, 5))\n					end\n                    if UI.UserData[\"YukimiCurrentText\"] == nil or YukimiLeftClick or RefreshAll then\n                        local count = UI.UserData[\"YukimiClickCount\"] or 0\n                        local key = UI.UserData[\"LastYukimiImgKey\"]\n						if UI.UserData[\"LastYukimiImgKey\"] == nil then\n                            UI.UserData[\"LastYukimiImgKey\"] = 1\n							key = 1\n						end\n						local NewCount = 0\n                        while UI.UserData[\"LastYukimiImgKey\"] == key do\n                            SetRandomSeed(GameGetRealWorldTimeSinceStarted(), 114514 + count + NewCount)\n                            key = Random(1, #t)\n                            NewCount = NewCount + 1\n                        end\n						UI.UserData[\"LastYukimiImgKey\"] = key\n                        UI.UserData[\"YukimiCurrentText\"] = t[key]\n                    end\n                    if YukimiLeftClick or RefreshAll then\n						UI.UserData[\"YukimiTimeCount\"] = 0\n                        local count = UI.UserData[\"YukimiClickCount\"] or 0\n                        local key = UI.UserData[\"LastYukimiTextKey\"]\n						if UI.UserData[\"LastYukimiTextKey\"] == nil then\n                            UI.UserData[\"LastYukimiTextKey\"] = 1\n							key = 1\n						end\n                        local NewCount = 0\n                        while UI.UserData[\"LastYukimiTextKey\"] == key do\n                            SetRandomSeed(GameGetRealWorldTimeSinceStarted(), 1919810 + count + NewCount)\n                            key = Random(1, #ImgList)\n                            NewCount = NewCount + 1\n                        end\n						UI.UserData[\"LastYukimiTextKey\"] = key\n                        UI.UserData[\"YukimiCurrentImg\"] = ImgList[key]\n						if UI.UserData[\"YukimiClickCount\"] == nil then\n                            UI.UserData[\"YukimiClickCount\"] = 1\n                        elseif UI.UserData[\"YukimiClickCount\"] < 16384 then\n							UI.UserData[\"YukimiClickCount\"] = UI.UserData[\"YukimiClickCount\"] + 1\n                        else\n							UI.UserData[\"YukimiClickCount\"] = 1\n						end\n					end\n					UI.BetterTooltipsNoCenter(function ()\n                        GuiText(UI.gui, 0, 0, UI.UserData[\"YukimiCurrentText\"],0.23,\"data/fonts/generated/notosans_jp_48.bin\")\n					end,nil)\n				end\n			end\n		end\n\n        UI.MiscEventFn[\"ToggleOptions\"] = function()\n			if ModSettingGet(ModID .. \".remove_lighting\") and not UI.UserData[\"RemoveLighting\"] then\n                GameSetPostFxParameter(\"WandEditor_ENABLE_LIGHTING\", 2.0, 0.0, 0.0, 0.0)\n                UI.UserData[\"RemoveLighting\"] = true\n            elseif not ModSettingGet(ModID .. \".remove_lighting\") and UI.UserData[\"RemoveLighting\"] then\n				GameSetPostFxParameter(\"WandEditor_ENABLE_LIGHTING\", 0.0, 0.0, 0.0, 0.0)\n                UI.UserData[\"RemoveLighting\"] = false\n			end\n            if GetPlayer() == nil then --找不到玩家时禁止执行下一步\n                return\n            end\n			local SkipDisableThrow = false\n            if not UI.GetPickerStatus(\"QuickTP\") or InputIsKeyDown(Key_LSHIFT) or InputIsKeyDown(Key_RSHIFT) then\n				SkipDisableThrow = true\n                local Active = GetActiveItem()\n				if Active ~= nil then\n                    local ItemAbility = EntityGetFirstComponentIncludingDisabled(Active, \"AbilityComponent\")\n                    local HasData, comp = GetStorageComp(Active, \"wand_editor_get_throw\")\n                    if ItemAbility ~= nil and comp ~= nil then\n						local throw = ComponentGetValue2(ItemAbility, \"throw_as_item\")\n                        if HasData == 1 then\n                            ComponentSetValue2(ItemAbility, \"throw_as_item\", true)\n                        elseif HasData == 0 and not throw then\n                            ComponentSetValue2(ItemAbility, \"throw_as_item\", false)\n                        end\n                        EntityRemoveComponent(Active, comp)--只恢复这一次\n					end\n				end\n			end\n			if UI.GetPickerStatus(\"ProtectionBlindness\") then\n                local player = GetPlayer()\n                local childs = EntityGetAllChildren(player)\n				for _,v in pairs(childs or {})do\n                    local GameEffects = EntityGetComponent(v, \"GameEffectComponent\")\n					for _,effect in pairs(GameEffects or {})do\n                        local effectName = ComponentGetValue2(effect, \"effect\")\n						if effectName == \"BLINDNESS\" then\n                            EntityKill(v)\n							break\n						end\n					end\n				end\n			end\n            if UI.GetPickerStatus(\"ProtectionAll\") and EntityGetWithName(\"WandEditorProtectionAllEntity\") == 0 then--无敌给予\n                local player = GetPlayer()\n                LoadGameEffectEntityTo(player, \"mods/wand_editor/files/entity/protection_all.xml\")\n            elseif (not UI.GetPickerStatus(\"ProtectionAll\")) and EntityGetWithName(\"WandEditorProtectionAllEntity\") ~= 0 then\n                EntityKill(EntityGetWithName(\"WandEditorProtectionAllEntity\"))\n            end\n\n            if UI.GetPickerStatus(\"ProtectionPoly\") and EntityGetWithName(\"WandEditorProtectionPolyEntity\") == 0 then--变形免疫给予\n                local player = GetPlayer()\n                LoadGameEffectEntityTo(player, \"mods/wand_editor/files/entity/protection_poly.xml\")\n            elseif (not UI.GetPickerStatus(\"ProtectionPoly\")) and EntityGetWithName(\"WandEditorProtectionPolyEntity\") ~= 0 then\n                EntityKill(EntityGetWithName(\"WandEditorProtectionPolyEntity\"))\n            end\n			\n            if UI.GetPickerStatus(\"EditWandsEverywhere\") and EntityGetWithName(\"WandEditorEditWandsEverywhereEntity\") == 0 then --随编给予\n                local player = GetPlayer()\n                EntityLoadChild(player, \"mods/wand_editor/files/entity/edit_wands_everywhere.xml\")\n            elseif (not UI.GetPickerStatus(\"EditWandsEverywhere\")) and EntityGetWithName(\"WandEditorEditWandsEverywhereEntity\") ~= 0 then\n                EntityKill(EntityGetWithName(\"WandEditorEditWandsEverywhereEntity\"))\n            end\n			local t = GetStorageComp(nil,nil,true)\n            local _, m, d = GameGetDateAndTimeLocal()\n			if t and t[m] and t[m][d] ~= nil and (not ModSettingGet(fastConcatStr(ModID,\"Mama\"))) then\n				GamePrint(\"Happy Birthday! \", t[m][d])\n				ModSettingSet(fastConcatStr(ModID,\"Mama\"), true)\n            elseif t and t[m] and t[m][d] == nil and ModSettingGet(fastConcatStr(ModID,\"Mama\")) then\n				ModSettingSet(fastConcatStr(ModID,\"Mama\"), false)\n			end\n			if UI.GetPickerStatus(\"UnlimitedSpells\") and EntityGetWithName(\"WandEditorUnlimitedSpells\") == 0 then--无限法术切换\n                local player = GetPlayer()\n                local world_entity_id = GameGetWorldStateEntity()\n                if world_entity_id ~= nil then\n                    local comp_worldstate = EntityGetFirstComponent(world_entity_id, \"WorldStateComponent\")\n                    if comp_worldstate ~= nil then\n                        ComponentSetValue2(comp_worldstate, \"perk_infinite_spells\", true)\n                    end\n                end\n                GameRegenItemActionsInPlayer(player)\n                UI.OnceCallOnExecute(function()\n                    RefreshHeldWands()\n                end)\n                AddNullEntityToPlayer(\"WandEditorUnlimitedSpells\")\n            elseif not UI.GetPickerStatus(\"UnlimitedSpells\") and EntityGetWithName(\"WandEditorUnlimitedSpells\") ~= 0 then\n				local world_entity_id = GameGetWorldStateEntity()\n                if world_entity_id ~= nil then\n                    local comp_worldstate = EntityGetFirstComponent(world_entity_id, \"WorldStateComponent\")\n                    if comp_worldstate ~= nil then\n                        ComponentSetValue2(comp_worldstate, \"perk_infinite_spells\", false)\n                    end\n                end\n				UI.OnceCallOnExecute(function()\n                    RefreshHeldWands()\n                end)\n				RemoveNullEntityWithName(\"WandEditorUnlimitedSpells\")\n			end\n			if UI.GetPickerStatus(\"InfFly\") and EntityGetWithName(\"WandEditorInfFly\") == 0 then\n                local player = GetPlayer()\n                local CharacterComp = EntityGetFirstComponent(player, \"CharacterDataComponent\")\n				if CharacterComp then\n                    ComponentSetValue2(CharacterComp, \"flying_needs_recharge\", false)\n					AddNullEntityToPlayer(\"WandEditorInfFly\")\n				end\n            elseif not UI.GetPickerStatus(\"InfFly\") and EntityGetWithName(\"WandEditorInfFly\") ~= 0 then\n				local player = GetPlayer()\n                local CharacterComp = EntityGetFirstComponent(player, \"CharacterDataComponent\")\n				if CharacterComp then\n                    ComponentSetValue2(CharacterComp, \"flying_needs_recharge\", true)\n					RemoveNullEntityWithName(\"WandEditorInfFly\")\n				end\n			end\n            if UI.GetPickerStatus(\"LockHP\") then --血量锁定实现\n                local player = GetPlayer()\n                local damage_model = EntityGetFirstComponent(player, \"DamageModelComponent\")\n                if UI.UserData[\"LockHPValue\"] == nil and damage_model then\n                    local hp = ComponentGetValue2(damage_model, \"hp\")\n                    UI.UserData[\"LockHPValue\"] = hp\n                elseif UI.UserData[\"LockHPValue\"] and damage_model then\n                    ComponentSetValue2(damage_model, \"hp\", UI.UserData[\"LockHPValue\"])\n                end\n            else\n                UI.UserData[\"LockHPValue\"] = nil\n            end\n            if UI.GetPickerStatus(\"LockHP\") and EntityGetWithName(\"WandEditorSavingGrace\") == 0 then --死里逃生给予\n                local player = GetPlayer()\n                LoadGameEffectEntityTo(player, \"mods/wand_editor/files/entity/saving_grace.xml\")\n            elseif (not UI.GetPickerStatus(\"LockHP\")) and EntityGetWithName(\"WandEditorSavingGrace\") ~= 0 then\n                EntityKill(EntityGetWithName(\"WandEditorSavingGrace\"))\n            end\n			\n			if GameIsInventoryOpen() then--开启物品栏时禁止执行下一步\n				return\n			end\n			\n            if UI.GetPickerStatus(\"QuickTP\") and EntityGetWithName(\"advanced_map\") == 0 and not SkipDisableThrow then\n                local player = GetPlayer()\n                local Active = GetActiveItem()\n                if Active ~= nil then\n                    local ItemAbility = EntityGetFirstComponentIncludingDisabled(Active, \"AbilityComponent\")\n                    if ItemAbility ~= nil then\n                        local HasData, comp = GetStorageComp(Active, \"wand_editor_get_throw\")\n                        if comp == nil then\n                            local throw = ComponentGetValue2(ItemAbility, \"throw_as_item\")\n                            local throwInt\n                            if throw then\n                                throwInt = 1\n                            else\n                                throwInt = 0\n                            end\n                            AddSetStorageComp(Active, \"wand_editor_get_throw\", throwInt)\n                            ComponentSetValue2(ItemAbility, \"throw_as_item\", false)\n                        end\n                    end\n                end\n\n                local Controls = EntityGetFirstComponent(player, \"ControlsComponent\")\n                local right = ComponentGetValue2(Controls, \"mButtonDownThrow\")\n                if right and (UI.UserData[\"QuickTPFr\"] == nil or UI.UserData[\"QuickTPFr\"] == 0) then\n                    local x, y = DEBUG_GetMouseWorld()\n                    EntitySetTransform(player, x, y)\n                    if UI.UserData[\"QuickTPFr\"] ~= 0 then\n                        UI.UserData[\"QuickTPFr\"] = 20\n                    end\n                elseif right and UI.UserData[\"QuickTPFr\"] and UI.UserData[\"QuickTPFr\"] ~= 0 then\n                    UI.UserData[\"QuickTPFr\"] = UI.UserData[\"QuickTPFr\"] - 1\n                elseif not right and UI.UserData[\"QuickTPFr\"] then\n                    UI.UserData[\"QuickTPFr\"] = nil\n                end\n            end\n			if UI.GetPickerStatus(\"DisablePlayerGravity\") and EntityGetWithName(\"wand_editor_disable_player_gravity\") == 0 then\n                local player = GetPlayer()\n                local comp = EntityGetFirstComponentIncludingDisabled(player, \"CharacterPlatformingComponent\")\n                if comp ~= nil then\n                    local x_min = ComponentGetValue2(comp, \"velocity_min_x\")\n                    local x_max = ComponentGetValue2(comp, \"velocity_max_x\")\n                    local y_min = ComponentGetValue2(comp, \"velocity_min_y\")\n					local y_max = ComponentGetValue2(comp, \"velocity_max_y\")\n                    ModSettingSet(ModID .. \"player_gra_x_min\", x_min)\n                    ModSettingSet(ModID .. \"player_gra_x_max\", x_max)\n					ModSettingSet(ModID .. \"player_gra_y_min\", y_min)\n                    ModSettingSet(ModID .. \"player_gra_y_max\", y_max)\n                    ComponentSetValue2(comp, \"velocity_min_x\", 0)\n                    ComponentSetValue2(comp, \"velocity_max_x\", 0)\n					ComponentSetValue2(comp, \"velocity_min_y\", 0)\n					ComponentSetValue2(comp, \"velocity_max_y\", 0)\n				end\n                LoadGameEffectEntityTo(player, \"mods/wand_editor/files/entity/no_knockback.xml\")\n            elseif not UI.GetPickerStatus(\"DisablePlayerGravity\") and EntityGetWithName(\"wand_editor_disable_player_gravity\") ~= 0 then\n				local player = GetPlayer()\n                local comp = EntityGetFirstComponentIncludingDisabled(player, \"CharacterPlatformingComponent\")\n				if comp ~= nil then\n					local x_min = ModSettingGet(ModID .. \"player_gra_x_min\") or 0\n					local x_max = ModSettingGet(ModID .. \"player_gra_x_max\") or 0\n					local y_min = ModSettingGet(ModID .. \"player_gra_y_min\") or 0\n                    local y_max = ModSettingGet(ModID .. \"player_gra_y_max\") or 0\n					ComponentSetValue2(comp, \"velocity_min_x\", x_min)\n                    ComponentSetValue2(comp, \"velocity_max_x\", x_max)\n					ComponentSetValue2(comp, \"velocity_min_y\", y_min)\n					ComponentSetValue2(comp, \"velocity_max_y\", y_max)\n				end\n				EntityKill(EntityGetWithName(\"wand_editor_disable_player_gravity\"))\n			end\n            if GameIsInventoryOpen() or (not UI.GetPickerStatus(\"MainButton\")) then --主按钮关闭时禁止下一步\n                return\n            end\n\n            if UI.GetPickerStatus(\"DamageInfo\") then\n                DrawDamageInfo()\n            end\n		end\n	end\n	UI.DispatchMessage()\nend\n"
_TWWE_VFS["mods/wand_editor/files/lang/lang.csv"] = "wand_editor_lang_id,en,ru,pt-br,es-es,de,fr-fr,it,pl,zh-cn,jp,ko,,NOTES – use \\n for newline,max length,,,,,,,,,,占位符，用于表示每一格对应的语言\nwand_editor_main_button,Wand Editor,,,,,,,,法杖编辑器,,,,,,,,,,,,,,,\nwand_editor_about_copy_link_tips,Press C to copy link,,,,,,,,按下C键去复制链接,,,,,,,,,,,,,,,\nwand_editor_picker_open,Open ,,,,,,,,打开,,,,,,,,,,,,,,,\nwand_editor_picker_close,Close ,,,,,,,,关闭,,,,,,,,,,,,,,,\nwand_editor_picker_desc,\"This is the moveable button, press shift+left mouse button to move\\nClick the left mouse button again to determine the position\\nRight mouse button to reset the position\",,,,,,,,这是可移动按钮，按shift+鼠标左键可以移动\\n再点击一次鼠标左键确定位置\\n鼠标右键重置位置,,,,,,,,,,,,,,,\nwand_editor_picker_more,Hold ctrl for more information,,,,,,,,按住ctrl查阅更多信息,,,,,,,,,,,,,,,\nwand_editor_lifetime,Lifetime,,,,,,,,存在时间,,,,,,,,,,,,,,,\nwand_editor_lifetime_limit,Lifetime limit,,,,,,,,最大存在时间限制,,,,,,,,,,,,,,,\nwand_editor_draw_many,Draw,,,,,,,,抽取数,,,,,,,,,,,,,,,\nwand_editor_max_uses,Uses,,,,,,,,使用次数,,,,,,,,,,,,,,,\nwand_editor_recoil_knockback,Recoil,,,,,,,,后坐力,,,,,,,,,,,,,,,\nwand_editor_timer_life_time,Timer Lifetime,,,,,,,,定时时间,,,,,,,,,,,,,,,\nwand_editor_added_spell, added to your inventory,,,,,,,,已添加到你的物品栏中,,,,,,,,,,,,,,,\nwand_editor_to, to ,,,,,,,,~,,,,,,,,,,,,,,,\nwand_editor_deg, DEG,,,,,,,,°,,,,,,,,,,,,,,,\nwand_editor_slot,Located in: $0 slot,,,,,,,,位于:$0格,,,,,,,,,,,,,,,\nwand_editor_always,Always cast:,,,,,,,,始终:,,,,,,,,,,,,,,,\nwand_editor_All_spells,All spells,,,,,,,,所有法术,,,,,,,,,,,,,,,\nwand_editor_search_info,\"This is the search box\\nThe downwards arrow and upwards arrow to switch the history of the search text.\\n@+mod ID to filter mod spells\\nRight click to clear the text\",,,,,,,,这是搜索框，方向键上下可切换历史搜索文本\\n支持拼音搜索，拼音声母搜索，拼音首字母搜索和三者混合搜索\\n@+模组ID筛选出模组法术\\n按下鼠标右键清空文本,,,,,,,,,,,,,,,\nwand_editor_search_setting,Search setting,,,,,,,,搜索设置栏,,,,,,,,,,,,,,,\nwand_editor_search_fuzzy_setting,Fuzzy search,,,,,,,,模糊搜索,,,,,,,,,,,,,,,\nwand_editor_search_fuzzy_setting_info,Enabling it will turn on fuzzy search,,,,,,,,启用后将开启模糊搜索,,,,,,,,,,,,,,,\nwand_editor_search_fuzzy_score_min_info,fuzzy match value,,,,,,,,模糊匹配值,,,,,,,,,,,,,,,\nwand_editor_search_id_setting,Search ID,,,,,,,,搜索ID,,,,,,,,,,,,,,,\nwand_editor_search_id_setting_info,When enabled it will append the search spell ID,,,,,,,,启用后会附加搜索法术ID,,,,,,,,,,,,,,,\nwand_editor_favorite,Favorite,,,,,,,,收藏,,,,,,,,,,,,,,,\nwand_editor_added_favorite_spell, added to your favorite,,,,,,,,已添加到你的收藏中,,,,,,,,,,,,,,,\nwand_editor_added_favorite_Already, already in your favorite,,,,,,,,已存在于你的收藏中,,,,,,,,,,,,,,,\nwand_editor_remove_favorite, has been removed from the favorites,,,,,,,,已被移除收藏,,,,,,,,,,,,,,,\nwand_editor_search_help,\"Help\\nCtrl+left click on a spell will put it directly into the inventory\\nShift+left click on a spell will put it into the held wand\\nWith a slot selected and only one slot selected, \\nshift+right click is to insert spells backwards to the specified position, \\nshift+z+right click is to insert spells forwards to the specified position\\nAlt+left click on a spell will put it into the favorite,\\nand if you perform this action in the favorite, you are deleting the spell from the favorite.\",,,,,,,,帮助\\n对一个法术按下ctrl+鼠标左键会直接放入背包\\n如果是shift+鼠标左键是放入手持法杖\\n在选择了一个格子并且只选择了一个格子的情况下，\\nshift+鼠标右键是向后插入法术到指定位置，\\nshift+z+鼠标右键是向前插入法术到指定位置\\n对一个法术按下alt+鼠标左键会放入收藏中，\\n如果在收藏中执行此操作则是在收藏中删除此法术,,,,,,,,,,,,,,,\nwand_editor_wand_spell_viewer_tip_close,Click to fix the current wand and window\\nShortcut ~/`(GRAVE) to fix current wand and window\\nHold ctrl for other information,,,,,,,,点击固定当前法杖和窗口\\n快捷键 ~ 固定法杖和窗口\\n按住Ctrl键查阅其他信息,,,,,,,,,,,,,,,\nwand_editor_wand_spell_viewer_tip_open,Click to unfix the wand and window\\nShortcut ~/`(GRAVE) to unfix current wand and window\\nHold ctrl for other information,,,,,,,,点击取消固定法杖和窗口\\n快捷键 ~ 取消固定法杖和窗口\\n按住Ctrl键查阅其他信息,,,,,,,,,,,,,,,\nwand_editor_spell_depot,Spell Backpack,,,,,,,,法术背包,,,,,,,,,,,,,,,\nwand_editor_spell_depot_open_tips,\"Right click will disable the spell placement on the ground feature, \\nwhich prevents accidental touches\",,,,,,,,右键将禁止法术放置在地上功能，\\n可防误触,,,,,,,,,,,,,,,\nwand_editor_spell_depot_close_tips,\"Right click will enable spell placement on the ground function\",,,,,,,,右键将开启法术放置在地上功能 ,,,,,,,,,,,,,,,\nwand_editor_wand_edit_box,Wand Edit Box,,,,,,,,法杖编辑栏,,,,,,,,,,,,,,,\nwand_editor_wand_edit_box_help,\"\\nHelp:\\nHold shift and left click on a grid to select\\nWhile holding shift down, left click on another grid to perform a box-select operation,\\nClick on one side of the highlight box while holding shift to deselect it,\\nCtrl+left click after selecting one or more squares allows you to move them.If it's ctrl + v then it will copy the,\\nIf it's ctrl+x/c it's a cut/copy spells, similarly pressing ctrl+v will paste spells.\\nBackspace to delete a spell\\nHold down alt and left click to promote spell to Always Cast\",,,,,,,,\\n帮助:\\n按住shift点击一个格子可以选择\\n按住shift的时候再点击另一个格子进行框选操作，\\n按住shift的时候点击框选格的一边取消选择，\\n选择了一个或多个格子之后按下ctrl键点击格子可以对其进行移动，如果是ctrl键+v键则会复制，\\n如果是ctrl键+x/c则是会剪切/复制法术，同理按下ctrl+v会粘贴法术。\\n退格键删除法术\\n按住alt键点击一个法术让其变成始终,,,,,,,,,,,,,,,\nwand_editor_wand_spawner,Wand Spawner,,,,,,,,法杖生成器,,,,,,,,,,,,,,,\nwand_editor_speed_multiplier,Speed multiplier,,,,,,,,初速度倍率,,,,,,,,,,,,,,,\nwand_editor_wand_builder_botton,[Spawn wand],,,,,,,,[生成法杖],,,,,,,,,,,,,,,\nwand_editor_wand_builder_held_botton,[Copy held wand],,,,,,,,[复制手持法杖],,,,,,,,,,,,,,,\nwand_editor_wand_builder_held_botton_tip,Shift+left click copy properties into the spawner\\nleft click to copy the wand to the player's position,,,,,,,,按住shift点击复制属性进生成器\\n直接点击复制法杖到玩家位置,,,,,,,,,,,,,,,\nwand_editor_wand_builder_update_botton,[Update held wand],,,,,,,,[更新手持法杖],,,,,,,,,,,,,,,\nwand_editor_wand_builder_slider_mode,[Slider],,,,,,,,[滑条],,,,,,,,,,,,,,,\nwand_editor_wand_builder_slider_mode_tips,\"Currently in slider mode, click to switch to input box mode\",,,,,,,,当前是滑条模式，点击切换为输入框模式,,,,,,,,,,,,,,,\nwand_editor_wand_builder_input_box_mode,[Input],,,,,,,,[输入框],,,,,,,,,,,,,,,\nwand_editor_wand_builder_input_box_mode_tips,\"Currently in input box mode, click to switch to slider mode\",,,,,,,,当前是输入框模式，点击切换为滑条模式,,,,,,,,,,,,,,,\nwand_editor_update_wand_image,Update image,,,,,,,,更新法杖外观,,,,,,,,,,,,,,,\nwand_editor_wand_depot,Wand Box\\nPress the right click to switch to historical editing data,,,,,,,,法杖仓库\\n按下右键切换为历史编辑数据,,,,,,,,,,,,,,,\nwand_editor_wand_depot_history,Wand History Edit\\nPress the right click to switch to Wand Box,,,,,,,,法杖历史编辑数据\\n按下右键切换为法杖仓库,,,,,,,,,,,,,,,\nwand_editor_wand_depot_history_clear,Clear History,,,,,,,,清空历史,,,,,,,,,,,,,,,\nwand_editor_wand_depot_history_clear_IKnowWhatImDoing,\"Sure you want to clear the history, it can't be recovered!\",,,,,,,,确定要清空历史吗，清空后无法恢复！,,,,,,,,,,,,,,,\nwand_editor_wand_depot_help,Help\\nAfter clicking on the highlight to select a wand \\nHold the ctrl to click on another wand to swap positions\\nWand with pin cannot be deleted\\nCross-page swap is not supported\\nWand History Edit does not support swapping and pin,,,,,,,,帮助\\n在点击高亮选择了一个格子之后\\n按住ctrl键点击另一个格子可以交换法杖位置\\n有图钉的法杖不能删除\\n不支持跨页交换\\n历史编辑数据不支持交换功能和图钉功能,,,,,,,,,,,,,,,\nwand_editor_wand_depot_limit,The current box limit has been reached and no new wand can be added,,,,,,,,当前仓库上限已达到，无法增加新法杖,,,,,,,,,,,,,,,\nwand_editor_wand_depot_isempty,as empty as anything...,,,,,,,,空空如也......,,,,,,,,,,,,,,,\nwand_editor_wand_depot_save,Save held wand,,,,,,,,保存当前手持法杖,,,,,,,,,,,,,,,\nwand_editor_wand_depot_delete,Delete selected wand,,,,,,,,删除选中法杖,,,,,,,,,,,,,,,\nwand_editor_wand_depot_delete_IKnowWhatImDoing,\"Sure you want to delete this wand, it can't be recovered!\",,,,,,,,确定要删除此法杖吗，删除后无法恢复！,,,,,,,,,,,,,,,\nwand_editor_wand_depot_delete_pin,Please remove the pin before deleting,,,,,,,,请移除图钉后才可删除,,,,,,,,,,,,,,,\nwand_editor_wand_depot_loadwand,Load selected wand into world,,,,,,,,加载选中法杖到自身位置,,,,,,,,,,,,,,,\nwand_editor_wand_depot_rewritewand,Load selected wand into held wand,,,,,,,,加载选中法杖替换掉当前手持法杖,,,,,,,,,,,,,,,\nwand_editor_wand_depot_wand_desc,Hold ctrl for other information,,,,,,,,按住Ctrl键查阅其他信息,,,,,,,,,,,,,,,\nwand_editor_wand_depot_newpage,New page\\nCtrl + Left Click will try to read the clipboard content to for create a new page\\nHold the Alt to create a new page will overwrite the current page,,,,,,,,新建页面\\nCtrl+鼠标左键将尝试读取剪切板内容用于新建页面\\n按下Alt键新建时会覆盖当前页面,,,,,,,,,,,,,,,\nwand_editor_wand_depot_deletepage,Delete this page,,,,,,,,删除此页面,,,,,,,,,,,,,,,\nwand_editor_wand_depot_copy_correctly,Successfully create a new page via clipboard,,,,,,,,成功通过剪切板新建页面,,,,,,,,,,,,,,,\nwand_editor_wand_depot_copy_error,\"The data in the clipboard is not legitimate, please make sure you copied the data correctly\",,,,,,,,剪切板中的数据不合法，请确认你是否正确的复制了数据,,,,,,,,,,,,,,,\nwand_editor_wand_depot_deletepage_IKnowWhatImDoing,\"Sure you want to delete this page, it can't be recovered!\",,,,,,,,确定要删除此页面吗，删除后无法恢复！,,,,,,,,,,,,,,,\nwand_editor_wand_depot_copy,Copy the data on this page to the clipboard,,,,,,,,复制此页面数据到剪切板,,,,,,,,,,,,,,,\nwand_editor_wand_depot_history_copy,Copy historical data to the clipboard,,,,,,,,复制历史数据到剪切板,,,,,,,,,,,,,,,\nwand_editor_wand_depot_wandlist_limit,\"Holy shit, you managed to create 99,999 pages. Is your computer okay? You can't create any more pages.\",,,,,,,,\"我草，你居然能创建99999个页面，你电脑还好吗？你不能再创建新的页面了\",,,,,,,,,,,,,,,\nwand_editor_toggle_options,Toggle Options & Misc,,,,,,,,切换选项栏与杂项,,,,,,,,,,,,,,,\nwand_editor_damage_info,Damage Info,,,,,,,,伤害信息,,,,,,,,,,,,,,,\nwand_editor_dps,Damage Per Second:,,,,,,,,每秒伤害:,,,,,,,,,,,,,,,\nwand_editor_total_damage,Total Damage:,,,,,,,,总计伤害:,,,,,,,,,,,,,,,\nwand_editor_total_proj_dmg,Total Projectile Damage:,,,,,,,,投射物伤害(当前帧):,,,,,,,,,,,,,,,\nwand_editor_total_proj,Total Projectiles:,,,,,,,,投射物总数(当前帧):,,,,,,,,,,,,,,,\nwand_editor_spawn_dummy,Target Dummy Options\\nPress the Backspace on the Target Dummy to remove it\\nRight click to spawn a dummy to the player's location.,,,,,,,,假人选项\\n对假人按下退格键即可移除\\n右键可生成假人到玩家位置,,,,,,,,,,,,,,,\nwand_editor_kill_dummy_tip,Removed a Target Dummy,,,,,,,,已移除一个假人,,,,,,,,,,,,,,,\nwand_editor_clear_proj,Clear Player Projectiles\\nHold the Ctrl and Click to Clear All Projectile,,,,,,,,清除场上玩家投射物\\n按下Ctrl键点击清除所有投射物,,,,,,,,,,,,,,,\nwand_editor_clear_wait,Clear Cast Delay / Recharge Time,,,,,,,,将延迟/充能 归零,,,,,,,,,,,,,,,\nwand_editor_protection_all,Protection from all,,,,,,,,无敌,,,,,,,,,,,,,,,\nwand_editor_protection_poly,Polymorph Immunity,,,,,,,,变形免疫,,,,,,,,,,,,,,,\nwand_editor_no_recoil,No Recoil,,,,,,,,无后坐力,,,,,,,,,,,,,,,\nwand_editor_lock_hp,Locked HP\\nAlso adds the Saving Grace effect\\nRight click to restore hp to full,,,,,,,,锁定血量\\n同时给予死里逃生效果\\n右键使血量恢复至满血,,,,,,,,,,,,,,,\nwand_editor_no_particles,No Spell Particles,,,,,,,,禁用法术粒子,,,,,,,,,,,,,,,\nwand_editor_no_proj,No Cast,,,,,,,,禁用施法,,,,,,,,,,,,,,,\nwand_editor_refresh_uses,Refresh Uses Remaining,,,,,,,,刷新使用次数,,,,,,,,,,,,,,,\nwand_editor_unlimited_spells,Unlimited Spells,,,,,,,,无限法术,,,,,,,,,,,,,,,\nwand_editor_always_draw_wand_edit_box,Always Draw Wand Edit Box\\nNeed to be opened in the spell backpack to use,,,,,,,,始终绘制法杖编辑栏\\n需在法术背包中打开才能使用,,,,,,,,,,,,,,,\nwand_editor_edit_wands_everywhere,Edit Wands Everywhere,,,,,,,,随时编辑,,,,,,,,,,,,,,,\nwand_editor_disable_spell_wobble,No Spell Wobble,,,,,,,,禁用法术摇摆,,,,,,,,,,,,,,,\nwand_editor_check_update,Check for updates,,,,,,,,检查更新,,,,,,,,,,,,,,,\nwand_editor_checking,Checking for updates,,,,,,,,检查更新中,,,,,,,,,,,,,,,\nwand_editor_no_checking,\"Not checking for updates, click to check for updates\",,,,,,,,未检查更新，点击检查,,,,,,,,,,,,,,,\nwand_editor_check_done_tip,Checking for updates is complete,,,,,,,,检查更新已完成,,,,,,,,,,,,,,,\nwand_editor_check_failed_tip,Check for updates failed,,,,,,,,检查更新失败,,,,,,,,,,,,,,,\nwand_editor_latest_ver,The current version is the latest version,,,,,,,,当前版本是最新版,,,,,,,,,,,,,,,\nwand_editor_new_ver,New version: $0\\nCurrent version: $1\\nClick to automatically download the new version of the zip,,,,,,,,新版本:$0\\n当前版本:$1\\n点击自动下载新版压缩包,,,,,,,,,,,,,,,\nwand_editor_new_ver_downloading,Downloaded: $0,,,,,,,,已下载:$0,,,,,,,\nwand_editor_new_ver_done_tip,The new version has been downloaded. You can go to the Check for updates button to copy the download path.,,,,,,,,新版本下载完成。可以去检查更新按钮复制下载路径,,,,,,,\nwand_editor_new_ver_failed_tip,The new version download failed. You can go to the Check for updates button to try downloading again,,,,,,,,新版本下载失败。可以前往检查更新按钮尝试重新下载,,,,,,,\nwand_editor_download_complete,The download is complete\\nPress C to copy the download path (default: noita/mods/wand_editor_new_ver.zip)\\nPlease close the game when unzipping the update mod,,,,,,,,下载完成\\n按下C键复制下载路径（默认在: noita/mods/wand_editor_new_ver.zip）\\n解压更新模组时请关闭游戏,,,,,,,\nwand_editor_new_ver_failed,\"Download failed, Click retry\\nIt may be caused by network problems.\",,,,,,,,下载失败，点击重试\\n可能是由于网络问题或者GFW造成的,,,,,,,\nwand_editor_connect_failed,\"Request connection failed\\nIt may be caused by network problems.\\nClick Recheck\",,,,,,,,\"请求失败\\n可能是由于网络问题或者GFW造成的\\n点击重新检查\",,,,,,,,,,,,,,,\nwand_editor_spell_lab_button_enter,Enter the laboratory,,,,,,,,进入实验室,,,,,,,\nwand_editor_spell_lab_button_leave,Leave the laboratory\\nRight click to reset the lab,,,,,,,,离开实验室\\n右键重置实验室,,,,,,,\nwand_editor_spell_lab_button_reset_error,You are not near the lab and cannot reset,,,,,,,,你不在实验室附近，不能重置,,,,,,,\nwand_editor_spell_lab_button_reset_done,Lab reset complete,,,,,,,,实验室重置完成,,,,,,,\nwand_editor_inf_fly,Unlimited flight,,,,,,,,无限飞行,,,,,,,\nwand_editor_tp,\"Teleport to cursor\\nPress the throw button (default right mouse button) to teleport, Hold to teleport continuously\\nWhen turned on, you cannot throw items. Pressing shift will temporarily turn off this function and allow throwing.\",,,,,,,,传送到光标\\n按下投掷键(默认鼠标右键)传送，长按连续传送\\n开启后无法投掷物品，按下shift会临时关闭此功能并允许投掷,,,,,,,\nwand_editor_protection_blindness,Blindness Immunity,,,,,,,,目盲免疫,,,,,,,\nwand_editor_disable_wand_history,\"Disable Wand Editing Historical Data Collection\\nCollection may cause lag, which can be alleviated by close\",,,,,,,,禁用法杖编辑历史数据收集\\n收集可能会造成卡顿，关闭会缓解,,,,,,,\nwand_editor_disable_player_gravity,\"Disable Player Move\\nThat is, the player cannot move, including downwards\",,,,,,,,禁用玩家移动\\n即玩家不能移动，包括向下移动,,,,,,,\nwand_editor_reload_spell_data,Reload Spell Data,,,,,,,,重载法术数据,,,,,,,\nwand_editor_dmg_proj,Projectile Dmg,,,,,,,,投射物伤害,,,,,,,\nwand_editor_dmg_expl,Explosion Dmg,,,,,,,,爆炸伤害,,,,,,,\nwand_editor_dmg_electric,Electricity Dmg,,,,,,,,雷电伤害,,,,,,,\nwand_editor_dmg_slice,Slice Dmg,,,,,,,,切割伤害,,,,,,,\nwand_editor_dmg_drill,Drill Dmg,,,,,,,,穿凿伤害,,,,,,,\nwand_editor_dmg_fire,Fire Dmg,,,,,,,,火焰伤害,,,,,,,\nwand_editor_dmg_ice,Ice Dmg,,,,,,,,寒冰伤害,,,,,,,\nwand_editor_dmg_melee,Melee Dmg,,,,,,,,近战伤害,,,,,,,\nwand_editor_dmg_holy,Holy Dmg,,,,,,,,神圣伤害,,,,,,,\nwand_editor_dmg_heal,Healing Dmg,,,,,,,,治疗伤害,,,,,,,\nwand_editor_dmg_physics_hit,Physics Hit Dmg,,,,,,,,物理伤害,,,,,,,\nwand_editor_dmg_curse,Curse Dmg,,,,,,,,诅咒伤害,,,,,,,\nwand_editor_dmg_toxic,Toxic Dmg,,,,,,,,绿毒伤害,,,,,,,\nwand_editor_dmg_poison,Poison Dmg,,,,,,,,紫毒伤害,,,,,,,\nwand_editor_options_spwan_dummy,[Spawn Dummy],,,,,,,,[生成假人],,,,,,,\nwand_editor_options_spwan_dummy_tips,Spawn a dummy at a location of the player’s choice according to the above settings\\nHold shift to spwan a default settings dummy\\nHold CTRL to fix the camera\\nIf it's a right-click it spawn a dummy directly to the player's position,,,,,,,,左键根据上述设置生成一个假人于玩家选择的位置\\n按住shift键生成一个默认配置假人\\n按住ALT键固定视角\\n如果是右键则直接生成假人到玩家位置,,,,,,,\nwand_editor_options_spwan_dummy_done_tips,Successfully spawn a dummy with the specified settings,,,,,,,,成功生成一个指定配置假人,,,,,,,\nwand_editor_options_spwan_dummy_done_tips_default,Successfully spawn a dummy with the default settings,,,,,,,,成功生成一个默认配置假人,,,,,,,\nwand_editor_options_del_dummy,[Remove All Dummy],,,,,,,,[移除所有假人],,,,,,,\nwand_editor_options_del_dummy_tips,Only the loaded Dummy will be removed,,,,,,,,只会移除已加载的假人,,,,,,,\nwand_editor_options_reset_options,[Reset All Settings],,,,,,,,[重置所有设置],,,,,,,\nwand_editor_pin_white,White,,,,,,,,白色,,,,,,,\nwand_editor_pin_black,Black,,,,,,,,黑色,,,,,,,\nwand_editor_pin_red,Red,,,,,,,,红色,,,,,,,\nwand_editor_pin_lime,Lime,,,,,,,,酸橙色,,,,,,,\nwand_editor_pin_blue,Blue,,,,,,,,蓝色,,,,,,,\nwand_editor_pin_yellow,Yellow,,,,,,,,黄色,,,,,,,\nwand_editor_pin_cyan,Cyan,,,,,,,,青色,,,,,,,\nwand_editor_pin_fuchsia,Fuchsia,,,,,,,,紫红色,,,,,,,\nwand_editor_pin_sliver,Sliver,,,,,,,,银色,,,,,,,\nwand_editor_pin_grey,Grey,,,,,,,,灰色,,,,,,,\nwand_editor_pin_maroon,Maroon,,,,,,,,深红色,,,,,,,\nwand_editor_pin_olive,Olive,,,,,,,,深黄色,,,,,,,\nwand_editor_pin_green,Green,,,,,,,,绿色,,,,,,,\nwand_editor_pin_purple,Purple,,,,,,,,紫色,,,,,,,\nwand_editor_pin_teal,Teal,,,,,,,,蓝绿色,,,,,,,\nwand_editor_pin_navy,Navy,,,,,,,,深蓝色,,,,,,,\nwand_editor_pin_select,Select ,,,,,,,,选择,,,,,,,\nwand_editor_pin_deselect,Deselect ,,,,,,,,取消选择,,,,,,,\nwand_editor_pin, Pin,,,,,,,,图钉,,,,,,,\nwand_editor_pin_add_tip,Right click to attach a $0 pin,,,,,,,,按下右键挂上$0图钉,,,,,,,\nwand_editor_pin_del_tip,Right click to remove $0 pin,,,,,,,,按下右键移除$0图钉,,,,,,,\nwand_editor_disable_spell_hover,Disable Edit Box Spell Hover Info,,,,,,,,禁止编辑框中法术悬浮信息,,,,,,,\nwand_editor_wand_builder_slider_tips,\"Press +/- or arrow keys left/right +1/-1, hold down for continuous execution.\\nHold shift to perform the above operation will multiply by ten.\",,,,,,,,按下 +/-或 方向键左/右键 +1/-1，长按会连续执行。\\n按住shift执行上述操作将乘以十。,,,,,,,\nwand_editor_reset_btn_pos,Reset all button positions,,,,,,,,重置所有按钮位置,,,,,,,\nwand_editor_reset_btn_pos_tip,Clicking on it will reset all the buttons to their default positions.,,,,,,,,点击将会重新设置所有的按钮位置到默认位置,,,,,,,\nwand_editor_reset_btn_pos_IKnowWhatImDoing,\"This action cannot be undone, click again to confirm\",,,,,,,,此操作不可撤销，再点击一次确认,,,,,,,\nwand_editor_no_spell_cache,Spell Data Cache,,,,,,,,法术数据缓存,,,,,,,\nwand_editor_no_spell_cache_tip,The generated spell data will no longer be cached after close,,,,,,,,关闭后将不再对生成的法术数据进行缓存操作,,,,,,,\nwand_editor_locked_target_pos,Fix Target Dummy position,,,,,,,,锁定假人位置,,,,,,,\nwand_editor_locked_target_pos_tip,Will fix the dummy to its spawn point to avoid accidental movement,,,,,,,,会把假人固定到其出生点，避免意外移动,,,,,,,\nwand_editor_remove_fog_of_war,Remove fog of war,,,,,,,,移除战争迷雾,,,,,,,\nwand_editor_remove_fog_of_war_tip,Turn on this setting and there will be no more fog of war underground.,,,,,,,,开启此选项，地下将不再会有战争迷雾,,,,,,,\nwand_editor_remove_lighting,Remove Lighting,,,,,,,,移除光照,,,,,,,\nwand_editor_remove_lighting_tip,Turn on this setting and there will not have lighting,,,,,,,,开启此选项，游戏将不会有光照,,,,,,,\nwand_editor_load_other_wand_box,Import other wand box data,,,,,,,,导入其他法杖仓库数据,,,,,,,\nwand_editor_load_spell_lab_wand_box,Import Spell Lab wand box data,,,,,,,,导入法术实验室仓库数据,,,,,,,\nwand_editor_load_spell_lab_wand_box_tip,Make sure you have the Spell Lab mod installed and enabled\\notherwise this feature won't work!,,,,,,,,请确保你有安装法术实验室模组并启用\\n不然本功能无法正常运行！,,,,,,,\nwand_editor_load_spell_lab_shug_wand_box,Import Spell Lab Shugged wand box data,,,,,,,,导入法术实验室Shugged仓库数据,,,,,,,\nwand_editor_load_spell_lab_shug_wand_box_tip,Make sure you have the Spell Lab Shugged mod installed and enabled\\notherwise this feature won't work!,,,,,,,,请确保你有安装法术实验室Shugged模组并启用\\n不然本功能无法正常运行！,,,,,,,\nwand_editor_load_wands_conn_wand_box,Import ECS Spell Lab wand box data,,,,,,,,导入ECS法术实验室仓库数据,,,,,,,\nwand_editor_load_wands_conn_wand_box_tip,Make sure you have the ECS Spell Lab mod installed and enabled\\notherwise this feature won't work!,,,,,,,,请确保你有安装ECS法术实验室模组并启用\\n不然本功能无法正常运行！,,,,,,,\nwand_editor_spell_lab_load_import_wand_box_error,Spell Lab Wand box import failed,,,,,,,,法术实验室的法杖仓库导入失败,,,,,,,\nwand_editor_wands_conn_load_import_wand_box_error,ECS Spell Lab Wand box import failed,,,,,,,,ECS法术实验室的法杖仓库导入失败,,,,,,,\nwand_editor_spell_lab_shugged_load_import_wand_box_error,Spell Lab Shugged Wand box import failed,,,,,,,,法术实验室Shugged的法杖仓库导入失败,,,,,,,\nwand_editor_load_spell_lab_wand_box_error,Probably because you don't have the Spell Lab mod enabled or you don't have a mod for it,,,,,,,,可能是由于你没有启用法术实验室模组或者没有模组导致的,,,,,,,\nwand_editor_load_wands_conn_wand_box_error,Probably because you don't have the ECS Spell Lab mod enabled or you don't have a mod for it,,,,,,,,可能是由于你没有启用ECS法术实验室模组或者没有模组导致的,,,,,,,\nwand_editor_load_spell_lab_shug_wand_box_error,Probably because you don't have the Spell Lab Shugged mod enabled or you don't have a mod for it,,,,,,,,可能是由于你没有启用法术实验室Shugged模组或者没有模组导致的,,,,,,,\nwand_editor_load_import_wand_box_done,Wand box import complete,,,,,,,,法杖仓库导入完成,,,,,,,\nwand_editor_yukimi_close,Right-click to close the Yukimi in the lower right corner,,,,,,,,右键关闭右下角雪美小人,,,,,,,\nwand_editor_yukimi_open,Right-click to open the Yukimi in the lower right corner,,,,,,,,右键开启右下角雪美小人,,,,,,,\nwand_editor_always_yukimi_open,shift+left click will make Yukimi always display,,,,,,,,shift+左键可以让雪美始终显示,,,,,,,\nwand_editor_always_yukimi_close,shift+left click to turn off the Yukimi always display,,,,,,,,shift+左键关闭雪美始终显示,,,,,,,\nwand_editor_spell_depot_history,Recently used spells in the spell backpack,,,,,,,,法术背包最近使用,,,,,,,\nwand_editor_remove_spell_depot_history,Clear recently used,,,,,,,,清空最近使用,,,,,,,\nwand_editor_remove_spell_depot_history_IKnowWhatImDoing,\"Sure you want to clear recently used, it can't be recovered!\",,,,,,,,确定要清空最近使用吗，清空后无法恢复！,,,,,,,\nwand_editor_split_search_text,Space Split Multi-Item Search,,,,,,,,空格分割多项目搜索,,,,,,,\nwand_editor_split_search_text_tip,Inserting spaces between text allows you to search for more than one thing at once.,,,,,,,,在文本之间插入空格可以同时搜索多个内容,,,,,,,\nwand_editor_spell_insert_error,\"Insertion failed, no slots remaining\",,,,,,,,插入失败，没有剩余的槽位,,,,,,,\nwand_editor_spell_inf_mana,Spells no longer cost mana,,,,,,,,法术不再耗蓝,,,,,,,\nwand_editor_real_unlimited_spells,Real Unlimited Spells,,,,,,,,真正的无限法术,,,,,,,\nwand_editor_real_unlimited_spells_tips,All spells will be unlimited,,,,,,,,所有法术都将是无限使用次数的,,,,,,,\nwand_editor_auto_update,Automatic Updates Mod (Experimental),,,,,,,,自动更新模组(实验性),,,,,,\nwand_editor_auto_update_tips,\"There is no guarantee that this feature will work stably at this time,\\n so turn it on with caution!\",,,,,,,,目前不能保证这个功能能稳定运行，谨慎开启,,,,,,\nwand_editor_auto_update_done, Restart the game to finish update,,,,,,,, 重启游戏以完成更新,,,,,,\nwand_editor_spell_mod_id_or_name,Spell affiliation mod display,,,,,,,,法术所属模组显示,,,,,,\nwand_editor_spell_mod_id_or_name_only_name,Mod name only,,,,,,,,只显示模组名字,,,,,,\nwand_editor_spell_mod_id_or_name_only_id,Mod id only,,,,,,,,只显示模组id,,,,,,\nwand_editor_spell_mod_id_or_name_all,Mod id and Mod name,,,,,,,,id和模组名字一起显示,,,,,,\nwand_editor_spell_name,Name,,,,,,,,名字,,,,,,\n"
_TWWE_VFS["mods/wand_editor/files/libs/EntityClass.lua"] = "---如果为空则返回v（默认值），不为空返回本身的函数\n---@param arg any\n---@param v any\n---@return any\nlocal function Default(arg, v)\n	if arg == nil then\n		return v\n	end\n	return arg\nend\n\n---移除前后空格，换行\n---@param s string\n---@return string\nlocal function strip(s)\n	if s == nil then\n		return ''\n	end\n	local result = s:gsub(\"^%s+\", \"\"):gsub(\"%s+$\", \"\"):gsub(\"%c\", \"\")\n	return result\nend\n\n---根据分隔符分割字符串\n---@param s string\n---@param delim string\n---@return table\nlocal function split(s, delim)\n	if string.find(s, delim) == nil then\n		return {\n			strip(s)\n		}\n	end\n	local result = {}\n	for ct in string.gmatch(s, '([^' .. delim .. ']+)') do\n		ct = strip(ct)\n		result[#result + 1] = ct\n	end\n	return result\nend\n\n---@class EntityComponent\n\n---以组件id返回一个组件封装\n---@param comp_id integer\n---@return EntityComponent\nfunction EntityComponentObj(comp_id)\n	---@class EntityComponent\n	local compobj = {\n		comp_id = comp_id,\n		---@type boolean\n		enable = nil,\n		attr = {}\n	}\n\n	---设置组件的值\n	---@param value_name string\n	---@param ... any\n	---@return EntityComponent self\n	function compobj:SetValue(value_name, ...)\n		ComponentSetValue2(self.comp_id, value_name, ...)\n		return self\n	end\n\n	---获取组件的值\n	---@param field_name string\n	---@return any?\n	function compobj:GetValue(field_name)\n		return ComponentGetValue2(self.comp_id, field_name)\n	end\n\n	---获得其对应实体\n	---@return number\n	function compobj:GetEntity()\n		return ComponentGetEntity(self.comp_id)\n	end\n\n	---获得其对应实体的封装对象\n	---@return NoitaEntity\n	function compobj:GetEntityObj()\n		return EntityObj(ComponentGetEntity(self.comp_id))\n	end\n\n	---获取组件启用状态\n	---@return boolean\n	function compobj:GetEnable()\n		return ComponentGetIsEnabled(self.comp_id)\n	end\n\n	---设置组件启用状态\n	---@param enable boolean\n	---@return EntityComponent self\n	function compobj:SetEnable(enable)\n		EntitySetComponentIsEnabled(compobj:GetEntity(), self.comp_id, enable)\n		return self\n	end\n\n	---给组件增加tag\n	---@param tag string\n	function compobj:AddTag(tag)\n		ComponentAddTag(self.comp_id, tag)\n		return self\n	end\n\n	---给组件移除tag\n	function compobj:RemoveTag(tag)\n		ComponentRemoveTag(self.comp_id, tag)\n		return self\n	end\n\n	---获取组件名称\n	---@return string\n	function compobj:GetName()\n		return ComponentGetTypeName(self.comp_id)\n	end\n\n	---获取组件Tag字符串\n	---@return string|nil\n	function compobj:GetTags()\n		return ComponentGetTags(self.comp_id)\n	end\n\n	---获取组件Tag列表\n	---@return string[]|nil\n	function compobj:GetTagList()\n		local tags = ComponentGetTags(self.comp_id)\n		if tags == nil then\n			return\n		end\n		return split(tags, \",\")\n	end\n\n	---获取组件的对象的指定值\n	---@param object_name string\n	---@param field_name string\n	function compobj:ObjGetValue(object_name, field_name)\n		return ComponentObjectGetValue2(self.comp_id, object_name, field_name)\n	end\n\n	---设置组件的对象的指定值\n	---@param object_name string\n	---@param field_name string\n	---@param ... any\n	---@return EntityComponent self\n	function compobj:ObjSetValue(object_name, field_name, ...)\n		ComponentObjectSetValue2(self.comp_id, object_name, field_name, ...)\n		return self\n	end\n\n	---返回向量大小\n	---@param array_member_name string\n	---@param type_stored_in_vector type_stored_in_vector\n	---@return number\n	function compobj:GetVecSize(array_member_name, type_stored_in_vector)\n		return ComponentGetVectorSize(self.comp_id, array_member_name, type_stored_in_vector)\n	end\n\n	---返回向量指定的值\n	---@param array_name string\n	---@param type_stored_in_vector type_stored_in_vector\n	---@param index number\n	---@return number|number|string|nil\n	function compobj:GetVecValue(array_name, type_stored_in_vector, index)\n		return ComponentGetVectorValue(self.comp_id, array_name, type_stored_in_vector, index)\n	end\n\n	---返回列表作为向量\n	---@param array_name string\n	---@param type_stored_in_vector type_stored_in_vector\n	---@return integer[]|number[]|string[]|nil\n	function compobj:GetVector(array_name, type_stored_in_vector)\n		return ComponentGetVector(self.comp_id, array_name, type_stored_in_vector)\n	end\n\n	---@return table<string, string>|nil\n	function compobj:GetMembers()\n		return ComponentGetMembers(self.comp_id)\n	end\n\n	---@param object_name string\n	---@return table<string, string>|nil\n	function compobj:GetObjMembers(object_name)\n		return ComponentObjectGetMembers(self.comp_id, object_name)\n	end\n\n	---属性\n	setmetatable(compobj.attr, {\n		__newindex = function(t, k, v)\n			rawset(t, k, nil)\n			compobj:SetValue(k, v)\n		end,\n		__index = function(t, k)\n			return compobj:GetValue(k)\n		end,\n	})\n\n	setmetatable(compobj, {\n		__newindex = function(t, k, v)\n			if k == \"enable\" then\n				rawset(t, k, nil)\n				compobj:SetEnable(v)\n			end\n		end,\n		__index = function(t, k)\n			if k == \"enable\" then\n				return compobj:GetEnable()\n			end\n        end,\n		__eq = function (t1, t2)\n            local t1ID = 0\n            if type(t1) == \"number\" then\n                t1ID = t1\n			elseif type(t1) == \"table\" and type(t1.comp_id) == \"number\" then\n				t1ID = t1.comp_id\n            end\n            local t2ID = 0\n            if type(t2) == \"number\" then\n                t2ID = t2\n            elseif type(t2) == \"table\" and type(t2.comp_id) == \"number\" then\n                t2ID = t2.comp_id\n            end\n			\n			return t1ID == t2ID\n		end\n	})\n\n	return compobj\nend\n\n---@class NoitaEntity\n\n---以实体id返回一个实体封装\n---@param entity_id integer\n---@return NoitaEntity\nfunction EntityObj(entity_id)\n	---@class NoitaEntity\n	local Entity = {\n		entity_id = entity_id,\n		---@type NoitaCompTo|table<string, EntityComponent[]>\n		comp = {}, --不包括被关闭的组件\n		---@type NoitaCompTo|table<string, EntityComponent[]>\n		comp_all = {}, --包括被关闭的组件\n		attr = {\n			---@type number\n			x = nil,\n			---@type number\n			y = nil,\n			---@type number\n			rotation = nil,\n			---@type number\n			scale_x = nil,\n			---@type number\n			scale_y = nil,\n\n			---@type boolean\n			is_alive = nil,\n			---@type string[]\n			tag = nil,\n			---@type string\n			name = nil\n		},\n    }\n    setmetatable(Entity, {\n		__eq = function (t1, t2)\n            local t1ID = 0\n            if type(t1) == \"number\" then\n                t1ID = t1\n			elseif type(t1) == \"table\" and type(t1.entity_id) == \"number\" then\n				t1ID = t1.entity_id\n            end\n            local t2ID = 0\n            if type(t2) == \"number\" then\n                t2ID = t2\n            elseif type(t2) == \"table\" and type(t2.entity_id) == \"number\" then\n                t2ID = t2.entity_id\n            end\n			\n			return t1ID == t2ID\n		end\n	})\n	setmetatable(Entity.comp, {\n		__newindex = function(t, k, v)\n			rawset(t, k, nil)\n			print_error(\"EntityObjError:Component attributes cannot be overridden\")\n		end,\n		__index = function(t, k)\n			return Entity:GetComp(k)\n		end\n	})\n	setmetatable(Entity.comp_all, {\n		__newindex = function(t, k, v)\n			rawset(t, k, nil)\n			print_error(\"EntityObjError:Component attributes cannot be overridden\")\n		end,\n		__index = function(t, k)\n			return Entity:GetComp(k, nil, true)\n		end\n	})\n	--其他属性\n	setmetatable(Entity.attr, {\n		__newindex = function(t, k, v)\n			if k == \"is_alive\" and v == false and Entity:IsAlive() then --为假就杀死生物\n				rawset(t, k, nil)\n				Entity:Kill()\n			elseif k == \"tag\" then --设置新Tag\n				rawset(t, k, nil)\n				for _, tv in ipairs(Entity:GetTagList() or {}) do\n					Entity:RemoveTag(tv)\n				end\n				for _, tv in ipairs(v or {}) do\n					Entity:AddTag(tv)\n				end\n			elseif k == \"name\" then\n				rawset(t, k, nil)\n				Entity:SetName(v)\n			elseif k == \"x\" then\n				rawset(t, k, nil)\n				Entity:SetX(v)\n			elseif k == \"y\" then\n				rawset(t, k, nil)\n				Entity:SetY(v)\n			elseif k == \"rotation\" then\n				rawset(t, k, nil)\n				Entity:SetRotation(v)\n			elseif k == \"scale_x\" then\n				rawset(t, k, nil)\n				Entity:SetScale_x(v)\n			elseif k == \"scale_y\" then\n				rawset(t, k, nil)\n				Entity:SetScale_y(v)\n			end\n		end,\n		__index = function(t, k)\n			if k == \"is_alive\" then\n				return Entity:IsAlive()\n			elseif k == \"tag\" then\n				return Entity:GetTagList()\n			elseif k == \"name\" then\n				return Entity:GetName()\n			elseif k == \"x\" then\n				return Entity:GetX()\n			elseif k == \"y\" then\n				return Entity:GetY()\n			elseif k == \"rotation\" then\n				return Entity:GetRotation()\n			elseif k == \"scale_x\" then\n				return Entity:GetScale_x()\n			elseif k == \"scale_y\" then\n				return Entity:GetScale_y()\n			end\n		end,\n	})\n\n	---实体是否存活\n	---@return boolean\n	function Entity:IsAlive()\n		return EntityGetIsAlive(self.entity_id)\n	end\n\n	---获取实体名字\n	---@return string\n	function Entity:GetName()\n		return EntityGetName(self.entity_id)\n	end\n\n	---设置实体名字\n	---@param name string\n	function Entity:SetName(name)\n		EntitySetName(self.entity_id, name)\n		return self\n	end\n\n	---获取实体Tag字符串\n	---@return string|nil\n	function Entity:GetTags()\n		return EntityGetTags(self.entity_id)\n	end\n\n	---获取实体Tag列表\n	---@return string[]|nil\n	function Entity:GetTagList()\n		local tags = EntityGetTags(self.entity_id)\n		if tags == nil then\n			return\n		end\n		return split(tags, \",\")\n	end\n\n	---是否存在tag\n	---@param tag string\n	---@return boolean\n	function Entity:HasTag(tag)\n		return EntityHasTag(self.entity_id, tag)\n	end\n\n	---增加实体Tag\n	---@param tag string\n	---@return NoitaEntity self\n	function Entity:AddTag(tag)\n		EntityAddTag(self.entity_id, tag)\n		return self\n	end\n\n	---移除实体Tag\n	---@param tag string\n	---@return NoitaEntity self\n	function Entity:RemoveTag(tag)\n		EntityRemoveTag(self.entity_id, tag)\n		return self\n	end\n\n	---注意EntityKill有滞后性\n	function Entity:Kill()\n		EntityKill(self.entity_id)\n	end\n\n	---@return number x, number y, number rotation, number scale_x, number scale_y\n	function Entity:GetTransform()\n		return EntityGetTransform(self.entity_id)\n	end\n\n	---@param x number\n	---@param y number? y = 0\n	---@param rotation number? rotation = 0\n	---@param scale_x number? scale_x = 1\n	---@param scale_y number? scale_y = 1\n	---@return NoitaEntity self\n	function Entity:SetTransform(x, y, rotation, scale_x, scale_y)\n		y = Default(y, 0)\n		rotation = Default(rotation, 0)\n		scale_x = Default(scale_x, 1)\n		scale_y = Default(scale_y, 1)\n		EntitySetTransform(self.entity_id, x, y, rotation, scale_x, scale_y)\n		return self\n	end\n\n	---@param x number\n	---@param y number? y = 0\n	---@param rotation number? rotation = 0\n	---@param scale_x number? scale_x = 1\n	---@param scale_y number? scale_y = 1\n	---@return NoitaEntity self\n	function Entity:ApplyTransform(x, y, rotation, scale_x, scale_y)\n		y = Default(y, 0)\n		rotation = Default(rotation, 0)\n		scale_x = Default(scale_x, 1)\n		scale_y = Default(scale_y, 1)\n		EntityApplyTransform(self.entity_id, x, y, rotation, scale_x, scale_y)\n		return self\n	end\n\n	---@param x number\n	---@return NoitaEntity self\n	function Entity:SetX(x)\n		local _, y, rotation, scale_x, scale_y = Entity:GetTransform()\n		Entity:SetTransform(x, y, rotation, scale_x, scale_y)\n		return self\n	end\n\n	---@param y number\n	---@return NoitaEntity self\n	function Entity:SetY(y)\n		local x, _, rotation, scale_x, scale_y = Entity:GetTransform()\n		Entity:SetTransform(x, y, rotation, scale_x, scale_y)\n		return self\n	end\n\n	---@param rotation number\n	---@return NoitaEntity self\n	function Entity:SetRotation(rotation)\n		local x, y, _, scale_x, scale_y = Entity:GetTransform()\n		Entity:SetTransform(x, y, rotation, scale_x, scale_y)\n		return self\n	end\n\n	---@param scale_x number\n	---@return NoitaEntity self\n	function Entity:SetScale_x(scale_x)\n		local x, y, rotation, _, scale_y = Entity:GetTransform()\n		Entity:SetTransform(x, y, rotation, scale_x, scale_y)\n		return self\n	end\n\n	---@param scale_y number\n	---@return NoitaEntity self\n	function Entity:SetScale_y(scale_y)\n		local x, y, rotation, scale_x, _ = Entity:GetTransform()\n		Entity:SetTransform(x, y, rotation, scale_x, scale_y)\n		return self\n	end\n\n	---@param x number\n	---@return NoitaEntity self\n	function Entity:ApplyX(x)\n		local _, y, rotation, scale_x, scale_y = Entity:GetTransform()\n		Entity:ApplyTransform(x, y, rotation, scale_x, scale_y)\n		return self\n	end\n\n	---@param y number\n	---@return NoitaEntity self\n	function Entity:ApplyY(y)\n		local x, _, rotation, scale_x, scale_y = Entity:GetTransform()\n		Entity:ApplyTransform(x, y, rotation, scale_x, scale_y)\n		return self\n	end\n\n	---@param rotation number\n	---@return NoitaEntity self\n	function Entity:ApplyRotation(rotation)\n		local x, y, _, scale_x, scale_y = Entity:GetTransform()\n		Entity:ApplyTransform(x, y, rotation, scale_x, scale_y)\n		return self\n	end\n\n	---@param scale_x number\n	---@return NoitaEntity self\n	function Entity:ApplyScale_x(scale_x)\n		local x, y, rotation, _, scale_y = Entity:GetTransform()\n		Entity:ApplyTransform(x, y, rotation, scale_x, scale_y)\n		return self\n	end\n\n	---@param scale_y number\n	---@return NoitaEntity self\n	function Entity:ApplyScale_y(scale_y)\n		local x, y, rotation, scale_x, _ = Entity:GetTransform()\n		Entity:ApplyTransform(x, y, rotation, scale_x, scale_y)\n		return self\n	end\n\n	---@return number\n	function Entity:GetX()\n		local x, y, rotation, scale_x, scale_y = Entity:GetTransform()\n		return x\n	end\n\n	---@return number\n	function Entity:GetY()\n		local x, y, rotation, scale_x, scale_y = Entity:GetTransform()\n		return y\n	end\n\n	---@return number\n	function Entity:GetRotation()\n		local x, y, rotation, scale_x, scale_y = Entity:GetTransform()\n		return rotation\n	end\n\n	---@return number\n	function Entity:GetScale_x()\n		local x, y, rotation, scale_x, scale_y = Entity:GetTransform()\n		return scale_x\n	end\n\n	---@return number\n	function Entity:GetScale_y()\n		local x, y, rotation, scale_x, scale_y = Entity:GetTransform()\n		return scale_y\n	end\n\n	---@return string\n	function Entity:GetFilename()\n		return EntityGetFilename(self.entity_id)\n	end\n\n	---增加子实体\n	---@param child integer|NoitaEntity\n	---@return NoitaEntity self\n	function Entity:AddChild(child)\n		if type(child) == \"number\" then\n			EntityAddChild(self.entity_id, child)\n		elseif type(child) == \"table\" and child.entity_id then\n			EntityAddChild(self.entity_id, child.entity_id)\n		end\n		return self\n	end\n\n	---载入新实体作为子实体\n	---@param filename string\n	---@return integer\n	function Entity:LoadChild(filename)\n		local x = Entity:GetX()\n		local y = Entity:GetY()\n		local child = EntityLoad(filename, x, y)\n		self:AddChild(child)\n		return child\n	end\n\n	---EntityLoadToEntity\n	---@param filename string\n	---@return NoitaEntity self\n	function Entity:LoadToEntity(filename)\n		EntityLoadToEntity(filename, self.entity_id)\n		return self\n	end\n\n	---Note: works only in dev builds.\n	---@param filename string\n	---@return NoitaEntity self\n	function Entity:Save(filename)\n		EntitySave(self.entity_id, filename)\n		return self\n	end\n\n	function Entity:RemoveFromParent()\n		EntityRemoveFromParent(self.entity_id)\n	end\n\n	function Entity:GetParent()\n		return EntityObj(EntityGetParent(self.entity_id))\n	end\n\n	function Entity:GetRoot()\n		return EntityObj(EntityGetRootEntity(self.entity_id))\n	end\n\n	---增加组件\n	---@param name string\n	---@param table_of_component_values table<string, any>? nil\n	---@return NoitaEntity self\n	function Entity:AddComp(name, table_of_component_values)\n		EntityAddComponent2(self.entity_id, name, table_of_component_values)\n		return self\n	end\n\n	---移除指定id组件\n	---@param id integer\n	---@return NoitaEntity self\n	function Entity:RemoveComp(id)\n		EntityRemoveComponent(self.entity_id, id)\n		return self\n	end\n\n	---获取第一个组件的id\n	---@param name string\n	---@param tag string? tag = \"\"\n	---@param including_disabled boolean? including_disabled = false\n	---@return integer|nil\n	function Entity:GetFristCompID(name, tag, including_disabled)\n		tag = Default(tag, \"\")\n		including_disabled = Default(including_disabled, false)\n		if including_disabled then\n			if tag and tag ~= \"\" then\n				return EntityGetFirstComponentIncludingDisabled(self.entity_id, name, tag)\n			else\n				return EntityGetFirstComponentIncludingDisabled(self.entity_id, name)\n			end\n		else\n			if tag and tag ~= \"\" then\n				return EntityGetFirstComponent(self.entity_id, name, tag)\n			else\n				return EntityGetFirstComponent(self.entity_id, name)\n			end\n		end\n	end\n\n	---获取指定名字的组件id列表\n	---@param name string\n	---@param tag string? tag = \"\"\n	---@param including_disabled boolean? including_disabled = false\n	---@return integer[]|nil\n	function Entity:GetCompID(name, tag, including_disabled)\n		tag = Default(tag, \"\")\n		including_disabled = Default(including_disabled, false)\n		if including_disabled then\n			if tag and tag ~= \"\" then\n				return EntityGetComponentIncludingDisabled(self.entity_id, name, tag)\n			else\n				return EntityGetComponentIncludingDisabled(self.entity_id, name)\n			end\n		else\n			if tag and tag ~= \"\" then\n				return EntityGetComponent(self.entity_id, name, tag)\n			else\n				return EntityGetComponent(self.entity_id, name)\n			end\n		end\n	end\n\n	---获取所有组件id\n	---@return integer[]\n	function Entity:GetAllCompID()\n		return EntityGetAllComponents(self.entity_id)\n	end\n\n	---获取第一个组件的封装对象\n	---@param name string\n	---@param tag string? tag = \"\"\n	---@param including_disabled boolean? including_disabled = false\n	---@return EntityComponent|nil\n	function Entity:GetFirstComp(name, tag, including_disabled)\n		local comp_id = Entity:GetFristCompID(name, tag, including_disabled)\n		if comp_id == nil then\n			return\n		end\n		return EntityComponentObj(comp_id)\n	end\n\n	---获取指定名字的组件封装列表\n	---@param name string\n	---@param tag string? tag = \"\"\n	---@param including_disabled boolean? including_disabled = false\n	---@return EntityComponent[]|nil\n	function Entity:GetComp(name, tag, including_disabled)\n		tag = Default(tag, \"\")\n		including_disabled = Default(including_disabled, false)\n		local list = Entity:GetCompID(name, tag, including_disabled)\n\n		if list == nil then --没有返回空\n			return\n		end\n\n		local result = {}\n		for i, v in ipairs(list) do\n			result[i] = EntityComponentObj(v)\n		end\n		return result\n	end\n\n	---获取所有组件id\n	---@return EntityComponent[]\n	function Entity:GetAllComp()\n		local result = {}\n		for i, v in ipairs(EntityGetAllComponents(self.entity_id)) do\n			result[i] = EntityComponentObj(v)\n		end\n		return result\n	end\n\n	---根据组件标签设置组件启用状态\n	---@param tag string\n	---@param enable boolean\n	function Entity:SetCompEnableWithTag(tag, enable)\n		EntitySetComponentsWithTagEnabled(self.entity_id, tag, enable)\n	end\n\n	---EntityRefreshSprite\n	---@param sprite_component integer|EntityComponent\n	---@return NoitaEntity self\n	function Entity:RefreshSprite(sprite_component)\n		if type(sprite_component) == \"number\" then\n			EntityRefreshSprite(self.entity_id, sprite_component)\n		elseif type(sprite_component) == \"table\" and sprite_component.comp_id then\n			EntityRefreshSprite(self.entity_id, sprite_component.comp_id)\n		end\n		return self\n	end\n\n	---模拟摄取材料\n	---@param material_type integer\n	---@param amount number\n	---@return NoitaEntity self\n	function Entity:IngestMaterial(material_type, amount)\n		EntityIngestMaterial(self.entity_id, material_type, amount)\n		return self\n	end\n\n	---移除沾湿状态\n	---@param status_type_id string\n	---@return NoitaEntity self\n	function Entity:RemoveIngestionEffect(status_type_id)\n		EntityRemoveIngestionStatusEffect(self.entity_id, status_type_id)\n		return self\n	end\n\n	---移除沾染状态\n	---@param status_type_id string\n	---@param status_cooldown number? 0\n	---@return NoitaEntity self\n	function Entity:RemoveStainEffect(status_type_id, status_cooldown)\n		status_cooldown = Default(status_cooldown, 0)\n		EntityRemoveStainStatusEffect(self.entity_id, status_type_id, status_cooldown)\n		return self\n	end\n\n	---EntityAddRandomStains\n	---@param material_type integer\n	---@param amount number\n	---@return NoitaEntity self\n	function Entity:AddRandomStains(material_type, amount)\n		EntityAddRandomStains(self.entity_id, material_type, amount)\n		return self\n	end\n\n	---设置材料伤害\n	---@param material_name string\n	---@param damage number\n	---@return NoitaEntity self\n	function Entity:SetMaterialDamage(material_name, damage)\n		EntitySetDamageFromMaterial(self.entity_id, material_name, damage)\n		return self\n	end\n\n	---EntityGetWandCapacity\n	---@return integer\n	function Entity:GetWandCapacity()\n		return EntityGetWandCapacity(self.entity_id)\n	end\n\n	---@param amount number\n	---@param damage_type noita_damage_type\n	---@param description string\n	---@param ragdoll_fx noita_ragdoll_fx\n	---@param impulse_x number\n	---@param impulse_y number\n	---@param entity_who_is_responsible number? 0\n	---@param world_pos_x number? entity_x\n	---@param world_pos_y number? entity_y\n	---@param knockback_force number? 0\n	---@return NoitaEntity self\n	function Entity:InflictDamage(amount, damage_type, description, ragdoll_fx, impulse_x, impulse_y,\n								  entity_who_is_responsible, world_pos_x, world_pos_y, knockback_force)\n		entity_who_is_responsible = Default(entity_who_is_responsible, 0)\n		world_pos_x = Default(world_pos_x, Entity:GetX())\n		world_pos_y = Default(world_pos_y, Entity:GetY())\n		knockback_force = Default(knockback_force, 0)\n		EntityInflictDamage(self.entity_id, amount, damage_type, description, ragdoll_fx, impulse_x, impulse_y,\n			entity_who_is_responsible, world_pos_x, world_pos_y, knockback_force)\n		return self\n	end\n\n	---@class DamageBuilder\n\n	---伤害建造者模式\n	---@return DamageBuilder\n	function Entity:DamageBuilder()\n		---@class DamageBuilder\n		local result = {\n			NoitaEntity = self,\n            amount = 0.04,\n			---@type noita_damage_type\n            damage_type = \"DAMAGE_PROJECTILE\",\n            description = \"\",\n			---@type noita_ragdoll_fx\n            ragdoll_fx = \"NONE\",\n			---@type number|nil\n            impulse_x = nil,\n			---@type number|nil\n            impulse_y = nil,\n            entity_who_is_responsible = 0,\n			---@type number|nil\n            world_pos_x = nil,\n			---@type number|nil\n            world_pos_y = nil,\n			knockback_force = 0,\n		}\n\n		---设置伤害量\n		---@param amount number\n		---@return DamageBuilder self\n		function result:SetAmount(amount)\n			self.amount = amount\n			return self\n		end\n\n		---设置伤害量，但是除以25\n		---@param amount number\n		---@return DamageBuilder self\n		function result:SetAmountDivided25(amount)\n			self.amount = amount / 25\n			return self\n		end\n\n		---设置伤害类型\n		---@param type noita_damage_type\n		---@return DamageBuilder self\n		function result:SetType(type)\n			self.damage_type = type\n			return self\n		end\n\n		---设置伤害描述\n		---@param description string\n		---@return DamageBuilder self\n		function result:SetDescription(description)\n            self.description = description\n			return self\n		end\n		\n		---设置ragdoll_fx\n		---@param ragdoll_fx noita_ragdoll_fx\n		---@return DamageBuilder self\n        function result:SetRagdoll_fx(ragdoll_fx)\n            self.ragdoll_fx = ragdoll_fx\n            return self\n        end\n\n		---设置impulse_x\n		---@param impulse_x number\n		---@return DamageBuilder self\n		function result:SetImpulse_x(impulse_x)\n            self.impulse_x = impulse_x\n			return self\n		end\n\n		---设置impulse_y\n		---@param impulse_y number\n		---@return DamageBuilder self\n		function result:SetImpulse_y(impulse_y)\n            self.impulse_y = impulse_y\n			return self\n		end\n\n		---设置entity_who_is_responsible\n		---@param entity_who_is_responsible number\n		---@return DamageBuilder self\n		function result:SetEntity_who_is_responsible(entity_who_is_responsible)\n            self.entity_who_is_responsible = entity_who_is_responsible\n			return self\n		end\n		\n		---设置world_pos_x\n		---@param world_pos_x number\n		---@return DamageBuilder self\n		function result:SetWorld_pos_x(world_pos_x)\n            self.world_pos_x = world_pos_x\n			return self\n		end\n\n		---设置world_pos_y\n		---@param world_pos_y number\n		---@return DamageBuilder self\n		function result:SetWorld_pos_y(world_pos_y)\n            self.world_pos_y = world_pos_y\n			return self\n		end\n\n		---设置knockback_force\n		---@param knockback_force number\n		---@return DamageBuilder self\n		function result:SetKnockback_force(knockback_force)\n            self.knockback_force = knockback_force\n			return self\n		end\n\n        ---应用伤害\n		---@return DamageBuilder self\n		function result:InflictDamage()\n			self.NoitaEntity:InflictDamage(self.amount, self.damage_type, self.description, self.ragdoll_fx,\n				self.impulse_x, self.impulse_y, self.entity_who_is_responsible, self.world_pos_x, self.world_pos_y,\n                self.knockback_force)\n			return self\n		end\n\n		return result\n	end\n\n	---EntityGetHotspot\n	---@param hotspot_tag string\n	---@param transformed boolean\n	---@param include_disabled_components boolean? false\n	---@return number x, number y\n	function Entity:GetHotspot(hotspot_tag, transformed, include_disabled_components)\n		include_disabled_components = Default(include_disabled_components, false)\n		return EntityGetHotspot(self.entity_id, hotspot_tag, transformed, include_disabled_components)\n	end\n\n	---GameGetVelocityCompVelocity\n	---@return number x, number y\n	function Entity:GetVelocityCompVelocity()\n		return GameGetVelocityCompVelocity(self.entity_id)\n	end\n\n	---GameGetGameEffect\n	---@param game_effect_name string\n	---@return integer component_id\n	function Entity:GetGameEffect(game_effect_name)\n		return GameGetGameEffect(self.entity_id, game_effect_name)\n	end\n\n	---GameGetGameEffectCount\n	---@param game_effect_name string\n	---@return integer\n	function Entity:GetGameEffectCount(game_effect_name)\n		return GameGetGameEffectCount(self.entity_id, game_effect_name)\n	end\n\n	---LoadGameEffectEntityTo\n	---@param game_effect_entity_file string\n	---@return number effect_entity_id\n	function Entity:LoadGameEffectEntityTo(game_effect_entity_file)\n		return LoadGameEffectEntityTo(self.entity_id, game_effect_entity_file)\n	end\n\n	---GetGameEffectLoadTo\n	---@param game_effect_name string\n	---@param always_load_new boolean\n	---@return number effect_component_id, number effect_entity_id\n	function Entity:GetGameEffectLoadTo(game_effect_name, always_load_new)\n		return GetGameEffectLoadTo(self.entity_id, game_effect_name, always_load_new)\n	end\n\n	---GameGetPotionColorUint\n	---@return integer\n	function Entity:GameGetPotionColorUint()\n		return GameGetPotionColorUint(self.entity_id)\n	end\n\n	---EntityGetFirstHitboxCenter\n	---@return number (x, number)|nil y\n	function Entity:GetFirstHitboxCenter()\n		return EntityGetFirstHitboxCenter(self.entity_id)\n	end\n\n	---IsPlayer\n	---@return boolean\n	function Entity:IsPlayer()\n		return IsPlayer(self.entity_id)\n	end\n\n	---IsInvisible\n	---@return boolean\n	function Entity:IsInvisible()\n		return IsInvisible(self.entity_id)\n	end\n\n	return Entity\nend\n\n---返回玩家实体封装\n---@return NoitaEntity|nil\nfunction GetPlayerObj()\n	local player = EntityGetWithTag(\"player_unit\")[1]\n	if player then\n		return EntityObj(player)\n	end\nend\n\n---EntityCreateNew\n---@param name string?\n---@return NoitaEntity\nfunction EntityObjCreateNew(name)\n	name = Default(name, \"\")\n	return EntityObj(EntityCreateNew(name))\nend\n\n---@param pos_x number\n---@param pos_y number\n---@param radius number\n---@param tag string?\n---@return NoitaEntity[]\nfunction EntityObjGetInRadius(pos_x, pos_y, radius, tag)\n	local result = {}\n	local list\n	if tag then\n		list = EntityGetInRadiusWithTag(pos_x, pos_y, radius, tag)\n	else\n		list = EntityGetInRadius(pos_x, pos_y, radius)\n	end\n\n	for i, v in ipairs(list) do\n		result[i] = EntityObj(v)\n	end\n	return result\nend\n\n---@param pos_x number\n---@param pos_y number\n---@param tag string?\n---@return NoitaEntity\nfunction EntityObjGetClosest(pos_x, pos_y, tag)\n	if tag then\n		return EntityObj(EntityGetClosestWithTag(pos_x, pos_y, tag))\n	else\n		return EntityObj(EntityGetClosest(pos_x, pos_y))\n	end\nend\n\n---@param filename string\n---@param pos_x number? 0\n---@param pos_y number? 0\n---@return NoitaEntity\nfunction EntityObjLoad(filename, pos_x, pos_y)\n	pos_x = Default(pos_x, 0)\n	pos_y = Default(pos_y, 0)\n	return EntityObj(EntityLoad(filename, pos_x, pos_y))\nend\n\n\n-----------------------------------------------------\n---@alias noita_effect_enum  \"NONE\" | \"ELECTROCUTION\" | \"FROZEN\" | \"ON_FIRE\" | \"POISON\" | \"BERSERK\" | \"CHARM\" | \"POLYMORPH\" | \"POLYMORPH_RANDOM\" | \"BLINDNESS\" | \"TELEPATHY\" | \"TELEPORTATION\" | \"REGENERATION\" | \"LEVITATION\" | \"MOVEMENT_SLOWER\" | \"FARTS\" | \"DRUNK\" | \"BREATH_UNDERWATER\" | \"RADIOACTIVE\" | \"WET\" | \"OILED\" | \"BLOODY\" | \"SLIMY\" | \"CRITICAL_HIT_BOOST\" | \"CONFUSION\" | \"MELEE_COUNTER\" | \"WORM_ATTRACTOR\" | \"WORM_DETRACTOR\" | \"FOOD_POISONING\" | \"FRIEND_THUNDERMAGE\" | \"FRIEND_FIREMAGE\" | \"INTERNAL_FIRE\" | \"INTERNAL_ICE\" | \"JARATE\" | \"KNOCKBACK\" | \"KNOCKBACK_IMMUNITY\" | \"MOVEMENT_SLOWER_2X\" | \"MOVEMENT_FASTER\" | \"STAINS_DROP_FASTER\" | \"SAVING_GRACE\" | \"DAMAGE_MULTIPLIER\" | \"HEALING_BLOOD\" | \"RESPAWN\" | \"PROTECTION_FIRE\" | \"PROTECTION_RADIOACTIVITY\" | \"PROTECTION_EXPLOSION\" | \"PROTECTION_MELEE\" | \"PROTECTION_ELECTRICITY\" | \"TELEPORTITIS\" | \"STAINLESS_ARMOUR\" | \"GLOBAL_GORE\" | \"EDIT_WANDS_EVERYWHERE\" | \"EXPLODING_CORPSE_SHOTS\" | \"EXPLODING_CORPSE\" | \"EXTRA_MONEY\" | \"EXTRA_MONEY_TRICK_KILL\" | \"HOVER_BOOST\" | \"PROJECTILE_HOMING\" | \"ABILITY_ACTIONS_MATERIALIZED\" | \"NO_DAMAGE_FLASH\" | \"NO_SLIME_SLOWDOWN\" | \"MOVEMENT_FASTER_2X\" | \"NO_WAND_EDITING\" | \"LOW_HP_DAMAGE_BOOST\" | \"FASTER_LEVITATION\" | \"STUN_PROTECTION_ELECTRICITY\" | \"STUN_PROTECTION_FREEZE\" | \"IRON_STOMACH\" | \"PROTECTION_ALL\" | \"INVISIBILITY\" | \"REMOVE_FOG_OF_WAR\" | \"MANA_REGENERATION\" | \"PROTECTION_DURING_TELEPORT\" | \"PROTECTION_POLYMORPH\" | \"PROTECTION_FREEZE\" | \"FROZEN_SPEED_UP\" | \"UNSTABLE_TELEPORTATION\" | \"POLYMORPH_UNSTABLE\" | \"CUSTOM\" | \"ALLERGY_RADIOACTIVE\" | \"RAINBOW_FARTS\"\n\n---@alias type_stored_in_vector \"int\" | \"float\" | \"string\"\n\n---@alias noita_damage_type '\"DAMAGE_MELEE\"' | '\"DAMAGE_PROJECTILE\"' | '\"DAMAGE_EXPLOSION\"' | '\"DAMAGE_BITE\"' | '\"DAMAGE_FIRE\"' | '\"DAMAGE_MATERIAL\"' | '\"DAMAGE_FALL\"' | '\"DAMAGE_ELECTRICITY\"' | '\"DAMAGE_DROWNING\"' | '\"DAMAGE_PHYSICS_BODY_DAMAGED\"' | '\"DAMAGE_DRILL\"' | '\"DAMAGE_SLICE\"' | '\"DAMAGE_ICE\"' | '\"DAMAGE_HEALING\"' | '\"DAMAGE_PHYSICS_HIT\"' | '\"DAMAGE_RADIOACTIVE\"' | '\"DAMAGE_POISON\"' | '\"DAMAGE_MATERIAL_WITH_FLASH\"' | '\"DAMAGE_OVEREATING\"' | '\"DAMAGE_CURSE\"' | '\"DAMAGE_HOLY\"'\n\n---@alias noita_ragdoll_fx '\"NONE\"' | '\"NORMAL\"' | '\"BLOOD_EXPLOSION\"' | '\"BLOOD_SPRAY\"' | '\"FROZEN\"' | '\"CONVERT_TO_MATERIAL\"' | '\"CUSTOM_RAGDOLL_ENTITY\"' | '\"DISINTEGRATED\"' | '\"NO_RAGDOLL_FILE\"' | '\"PLAYER_RAGDOLL_CAMERA\"'\n\n---@class unsupported unsupported type\n"
_TWWE_VFS["mods/wand_editor/files/libs/EntityClassTypeHint.lua"] = "---@class NoitaCompTo\n---@field AIAttackComponent AIAttackComponentClass[]\n---@field AIComponent AIComponentClass[]\n---@field AbilityComponent AbilityComponentClass[]\n---@field AdvancedFishAIComponent AdvancedFishAIComponentClass[]\n---@field AltarComponent AltarComponentClass[]\n---@field AnimalAIComponent AnimalAIComponentClass[]\n---@field ArcComponent ArcComponentClass[]\n---@field AreaDamageComponent AreaDamageComponentClass[]\n---@field AttachToEntityComponent AttachToEntityComponentClass[]\n---@field AudioComponent AudioComponentClass[]\n---@field AudioListenerComponent AudioListenerComponentClass[]\n---@field AudioLoopComponent AudioLoopComponentClass[]\n---@field BiomeTrackerComponent BiomeTrackerComponentClass[]\n---@field BlackHoleComponent BlackHoleComponentClass[]\n---@field BookComponent BookComponentClass[]\n---@field BossDragonComponent BossDragonComponentClass[]\n---@field BossHealthBarComponent BossHealthBarComponentClass[]\n---@field CameraBoundComponent CameraBoundComponentClass[]\n---@field CardinalMovementComponent CardinalMovementComponentClass[]\n---@field CellEaterComponent CellEaterComponentClass[]\n---@field CharacterCollisionComponent CharacterCollisionComponentClass[]\n---@field CharacterDataComponent CharacterDataComponentClass[]\n---@field CharacterPlatformingComponent CharacterPlatformingComponentClass[]\n---@field CharacterStatsComponent CharacterStatsComponentClass[]\n---@field CollisionTriggerComponent CollisionTriggerComponentClass[]\n---@field ConsumableTeleportComponent ConsumableTeleportComponentClass[]\n---@field ControllerGoombaAIComponent ControllerGoombaAIComponentClass[]\n---@field ControlsComponent ControlsComponentClass[]\n---@field CrawlerAnimalComponent CrawlerAnimalComponentClass[]\n---@field CutThroughWorldDoneHereComponent CutThroughWorldDoneHereComponentClass[]\n---@field DamageModelComponent DamageModelComponentClass[]\n---@field DamageNearbyEntitiesComponent DamageNearbyEntitiesComponentClass[]\n---@field DebugFollowMouseComponent DebugFollowMouseComponentClass[]\n---@field DebugLogMessagesComponent DebugLogMessagesComponentClass[]\n---@field DebugSpatialVisualizerComponent DebugSpatialVisualizerComponentClass[]\n---@field DieIfSpeedBelowComponent DieIfSpeedBelowComponentClass[]\n---@field DroneLauncherComponent DroneLauncherComponentClass[]\n---@field DrugEffectComponent DrugEffectComponentClass[]\n---@field DrugEffectModifierComponent DrugEffectModifierComponentClass[]\n---@field ElectricChargeComponent ElectricChargeComponentClass[]\n---@field ElectricityComponent ElectricityComponentClass[]\n---@field ElectricityReceiverComponent ElectricityReceiverComponentClass[]\n---@field ElectricitySourceComponent ElectricitySourceComponentClass[]\n---@field EndingMcGuffinComponent EndingMcGuffinComponentClass[]\n---@field EnergyShieldComponent EnergyShieldComponentClass[]\n---@field ExplodeOnDamageComponent ExplodeOnDamageComponentClass[]\n---@field ExplosionComponent ExplosionComponentClass[]\n---@field FishAIComponent FishAIComponentClass[]\n---@field FlyingComponent FlyingComponentClass[]\n---@field FogOfWarRadiusComponent FogOfWarRadiusComponentClass[]\n---@field FogOfWarRemoverComponent FogOfWarRemoverComponentClass[]\n---@field GameAreaEffectComponent GameAreaEffectComponentClass[]\n---@field GameEffectComponent GameEffectComponentClass[]\n---@field GameLogComponent GameLogComponentClass[]\n---@field GameStatsComponent GameStatsComponentClass[]\n---@field GasBubbleComponent GasBubbleComponentClass[]\n---@field GenomeDataComponent GenomeDataComponentClass[]\n---@field GhostComponent GhostComponentClass[]\n---@field GodInfoComponent GodInfoComponentClass[]\n---@field GunComponent GunComponentClass[]\n---@field HealthBarComponent HealthBarComponentClass[]\n---@field HitEffectComponent HitEffectComponentClass[]\n---@field HitboxComponent HitboxComponentClass[]\n---@field HomingComponent HomingComponentClass[]\n---@field HotspotComponent HotspotComponentClass[]\n---@field IKLimbAttackerComponent IKLimbAttackerComponentClass[]\n---@field IKLimbComponent IKLimbComponentClass[]\n---@field IKLimbWalkerComponent IKLimbWalkerComponentClass[]\n---@field IKLimbsAnimatorComponent IKLimbsAnimatorComponentClass[]\n---@field IngestionComponent IngestionComponentClass[]\n---@field InheritTransformComponent InheritTransformComponentClass[]\n---@field InteractableComponent InteractableComponentClass[]\n---@field Inventory2Component Inventory2ComponentClass[]\n---@field InventoryComponent InventoryComponentClass[]\n---@field InventoryGuiComponent InventoryGuiComponentClass[]\n---@field ItemAIKnowledgeComponent ItemAIKnowledgeComponentClass[]\n---@field ItemActionComponent ItemActionComponentClass[]\n---@field ItemAlchemyComponent ItemAlchemyComponentClass[]\n---@field ItemChestComponent ItemChestComponentClass[]\n---@field ItemComponent ItemComponentClass[]\n---@field ItemCostComponent ItemCostComponentClass[]\n---@field ItemPickUpperComponent ItemPickUpperComponentClass[]\n---@field ItemRechargeNearGroundComponent ItemRechargeNearGroundComponentClass[]\n---@field ItemStashComponent ItemStashComponentClass[]\n---@field KickComponent KickComponentClass[]\n---@field LaserEmitterComponent LaserEmitterComponentClass[]\n---@field LevitationComponent LevitationComponentClass[]\n---@field LifetimeComponent LifetimeComponentClass[]\n---@field LightComponent LightComponentClass[]\n---@field LightningComponent LightningComponentClass[]\n---@field LimbBossComponent LimbBossComponentClass[]\n---@field LiquidDisplacerComponent LiquidDisplacerComponentClass[]\n---@field LoadEntitiesComponent LoadEntitiesComponentClass[]\n---@field LocationMarkerComponent LocationMarkerComponentClass[]\n---@field LooseGroundComponent LooseGroundComponentClass[]\n---@field LuaComponent LuaComponentClass[]\n---@field MagicConvertMaterialComponent MagicConvertMaterialComponentClass[]\n---@field MagicXRayComponent MagicXRayComponentClass[]\n---@field ManaReloaderComponent ManaReloaderComponentClass[]\n---@field MaterialAreaCheckerComponent MaterialAreaCheckerComponentClass[]\n---@field MaterialInventoryComponent MaterialInventoryComponentClass[]\n---@field MaterialSeaSpawnerComponent MaterialSeaSpawnerComponentClass[]\n---@field MaterialSuckerComponent MaterialSuckerComponentClass[]\n---@field MoveToSurfaceOnCreateComponent MoveToSurfaceOnCreateComponentClass[]\n---@field MusicEnergyAffectorComponent MusicEnergyAffectorComponentClass[]\n---@field NinjaRopeComponent NinjaRopeComponentClass[]\n---@field NullDamageComponent NullDamageComponentClass[]\n---@field OrbComponent OrbComponentClass[]\n---@field ParticleEmitterComponent ParticleEmitterComponentClass[]\n---@field PathFindingComponent PathFindingComponentClass[]\n---@field PathFindingGridMarkerComponent PathFindingGridMarkerComponentClass[]\n---@field PhysicsAIComponent PhysicsAIComponentClass[]\n---@field PhysicsBody2Component PhysicsBody2ComponentClass[]\n---@field PhysicsBodyCollisionDamageComponent PhysicsBodyCollisionDamageComponentClass[]\n---@field PhysicsBodyComponent PhysicsBodyComponentClass[]\n---@field PhysicsImageShapeComponent PhysicsImageShapeComponentClass[]\n---@field PhysicsJoint2Component PhysicsJoint2ComponentClass[]\n---@field PhysicsJoint2MutatorComponent PhysicsJoint2MutatorComponentClass[]\n---@field PhysicsJointComponent PhysicsJointComponentClass[]\n---@field PhysicsKeepInWorldComponent PhysicsKeepInWorldComponentClass[]\n---@field PhysicsPickUpComponent PhysicsPickUpComponentClass[]\n---@field PhysicsRagdollComponent PhysicsRagdollComponentClass[]\n---@field PhysicsShapeComponent PhysicsShapeComponentClass[]\n---@field PhysicsThrowableComponent PhysicsThrowableComponentClass[]\n---@field PixelSceneComponent PixelSceneComponentClass[]\n---@field PixelSpriteComponent PixelSpriteComponentClass[]\n---@field PlatformShooterPlayerComponent PlatformShooterPlayerComponentClass[]\n---@field PlayerCollisionComponent PlayerCollisionComponentClass[]\n---@field PlayerStatsComponent PlayerStatsComponentClass[]\n---@field PositionSeedComponent PositionSeedComponentClass[]\n---@field PotionComponent PotionComponentClass[]\n---@field PressurePlateComponent PressurePlateComponentClass[]\n---@field ProjectileComponent ProjectileComponentClass[]\n---@field RotateTowardsComponent RotateTowardsComponentClass[]\n---@field SetLightAlphaFromVelocityComponent SetLightAlphaFromVelocityComponentClass[]\n---@field SetStartVelocityComponent SetStartVelocityComponentClass[]\n---@field ShotEffectComponent ShotEffectComponentClass[]\n---@field SimplePhysicsComponent SimplePhysicsComponentClass[]\n---@field SineWaveComponent SineWaveComponentClass[]\n---@field SpriteAnimatorComponent SpriteAnimatorComponentClass[]\n---@field SpriteComponent SpriteComponentClass[]\n---@field SpriteOffsetAnimatorComponent SpriteOffsetAnimatorComponentClass[]\n---@field SpriteParticleEmitterComponent SpriteParticleEmitterComponentClass[]\n---@field SpriteStainsComponent SpriteStainsComponentClass[]\n---@field StatusEffectDataComponent StatusEffectDataComponentClass[]\n---@field StreamingKeepAliveComponent StreamingKeepAliveComponentClass[]\n---@field TelekinesisComponent TelekinesisComponentClass[]\n---@field TeleportComponent TeleportComponentClass[]\n---@field TeleportProjectileComponent TeleportProjectileComponentClass[]\n---@field TextLogComponent TextLogComponentClass[]\n---@field TorchComponent TorchComponentClass[]\n---@field UIIconComponent UIIconComponentClass[]\n---@field UIInfoComponent UIInfoComponentClass[]\n---@field VariableStorageComponent VariableStorageComponentClass[]\n---@field VelocityComponent VelocityComponentClass[]\n---@field VerletPhysicsComponent VerletPhysicsComponentClass[]\n---@field VerletWeaponComponent VerletWeaponComponentClass[]\n---@field VerletWorldJointComponent VerletWorldJointComponentClass[]\n---@field WalletComponent WalletComponentClass[]\n---@field WalletValuableComponent WalletValuableComponentClass[]\n---@field WorldStateComponent WorldStateComponentClass[]\n---@field WormAIComponent WormAIComponentClass[]\n---@field WormAttractorComponent WormAttractorComponentClass[]\n---@field WormComponent WormComponentClass[]\n---@field WormPlayerComponent WormPlayerComponentClass[]\n\n---@class AIAttackComponentClass\n---@field comp_id integer\n---@field enable boolean\n---@field attr AIAttackComponent\n\n---@class AIAttackComponent\n---@field use_probability integer Members<br>---<br>The probability for using this attack if it's otherwise possible\n---@field min_distance number Members<br>---<br>The minimum distance from enemy at which we can perform this attack.\n---@field max_distance number Members<br>---<br>The maximum distance from enemy at which we can perform this attack.\n---@field angular_range_deg number Members<br>---<br>When looking for threats/prey this is our field of view around the X axis. 90 means we scan the whole 180 degrees around the X axis, to the left and right.\n---@field state_duration_frames integer Members<br>---<br>How long do we stay in the attack state, before other states are allowed?\n---@field frames_between integer Members<br>---<br>The minimum number of frames we wait between these attacks\n---@field frames_between_global integer Members<br>---<br>The minimum number of frames we wait after this attack before doing any other ranged attack\n---@field animation_name string Members<br>---<br>The animation to play when performing this attack\n---@field attack_landing_ranged_enabled boolean Members<br>---<br>If 1, we try to land before doing the attack, if there's ground near nearby under us\n---@field attack_ranged_action_frame integer Members<br>---<br>The frame of the 'attack_ranged' animation during which the ranged attack actually occurs\n---@field attack_ranged_offset_x number Members<br>---<br>'attack_ranged_entity_file' is created here when performing a ranged attack\n---@field attack_ranged_offset_y number Members<br>---<br>'attack_ranged_entity_file' is created here when performing a ranged attack\n---@field attack_ranged_root_offset_x number Members\n---@field attack_ranged_root_offset_y number Members\n---@field attack_ranged_use_message boolean Members<br>---<br>If 1, we do ranged attacks by sending a Message_UseItem\n---@field attack_ranged_predict boolean Members<br>---<br>If 1, we attempt to predict target movement and shoot accordingly\n---@field attack_ranged_entity_file string Members<br>---<br>File to projectile entity that is created when performing a ranged attack\n---@field attack_ranged_entity_count_min integer Members<br>---<br>Minimum number of projectiles shot when performing a ranged attack\n---@field attack_ranged_entity_count_max integer Members<br>---<br>Maximum number of projectiles shot when performing a ranged attack\n---@field attack_ranged_use_laser_sight boolean Members<br>---<br>If 1, we draw a laser sight to our target. Requires entity to have a sprite with tag 'laser_sight'\n---@field attack_ranged_aim_rotation_enabled boolean Members<br>---<br>If 1, we use a laser sight\n---@field attack_ranged_aim_rotation_speed number Members<br>---<br>How fast can we rotate our aim to track targets\n---@field attack_ranged_aim_rotation_shooting_ok_angle_deg number Members<br>---<br>If our aim is closer than this to the target we shoot\n---@field mRangedAttackCurrentAimAngle number Privates<br>---<br>which direction does our gun currently point at, physically saying?\n---@field mNextFrameUsable integer Privates\n\n---@class AIComponentClass\n---@field comp_id integer\n---@field enable boolean\n---@field attr AIComponent\n\n---@class AIComponent\n---@field TEMP_TEMP_TEMP number Members\n---@field data unsupported Privates\n\n---@class AbilityComponentClass\n---@field comp_id integer\n---@field enable boolean\n---@field attr AbilityComponent\n\n---@class AbilityComponent\n---@field cooldown_frames integer Members\n---@field entity_file string Members<br>---<br>the projectile entity file\n---@field sprite_file string Members\n---@field entity_count integer Members\n---@field never_reload boolean Members\n---@field reload_time_frames integer Members\n---@field mana number Members\n---@field mana_max number Members\n---@field mana_charge_speed number Members\n---@field rotate_in_hand boolean Members\n---@field rotate_in_hand_amount number Members<br>---<br>[0-1], how much does the item rotate related to the actual aiming angle\n---@field rotate_hand_amount number Members<br>---<br>[0-1], how much does hand sprite rotate related to the actual aiming angle\n---@field fast_projectile boolean Members<br>---<br>if 1, then the velocity of the bullet is increased quite a bit. Lightning requires this\n---@field swim_propel_amount number Members\n---@field max_charged_actions integer Members\n---@field charge_wait_frames integer Members\n---@field item_recoil_recovery_speed number Members<br>---<br>How quickly does the item return to resting state after getting recoil\n---@field item_recoil_max number Members<br>---<br>Maximum distance moved by recoil\n---@field item_recoil_offset_coeff number Members<br>---<br>Item distance moved by recoil = mItemRecoil * item_recoil_offset_coeff\n---@field item_recoil_rotation_coeff number Members<br>---<br>Item rotation by recoil = mItemRecoil * item_recoil_rotation_coeff\n---@field base_item_file string Members<br>---<br>when dropping / throwing the item, this is the base_item that we add the ability component to\n---@field use_entity_file_as_projectile_info_proxy boolean Members\n---@field click_to_use boolean Members\n---@field stat_times_player_has_shot integer Members<br>---<br>used to track how many times player has shot this 'ability'\n---@field stat_times_player_has_edited integer Members<br>---<br>used to track how many times this has been edited\n---@field shooting_reduces_amount_in_inventory boolean Members\n---@field throw_as_item boolean Members\n---@field simulate_throw_as_item boolean Members<br>---<br>If 1, the item will be work as normal ability, but throwing animation is played by the user\n---@field max_amount_in_inventory integer Members\n---@field amount_in_inventory integer Members\n---@field drop_as_item_on_death boolean Members\n---@field ui_name string Members<br>---<br>way to name the weapons\n---@field use_gun_script boolean Members<br>---<br>If 1, the default ability behaviour is replaced with one that uses the lua gun system.\n---@field is_petris_gun boolean Members<br>---<br>if 1, TODO( PETRI)\n---@field gun_level integer Members<br>---<br>the level of the wand, set in gun_procedural.lua\n---@field add_these_child_actions string Members<br>---<br>e.g. 'bullet,bullet,damage' ... actions are parsed into a string. These are added as actual entities when the item is initialized\n---@field current_slot_durability integer Members<br>---<br>After this many slots the last slot of the gun is removed. -1 means not initialized/infinite.\n---@field slot_consumption_function unsupported Members<br>---<br>Name of the lua function in 'gun.lua' that is called to calculate durability of the last slot in the gun\n---@field mNextFrameUsable integer Members<br>---<br>hax, don't touch!\n---@field mCastDelayStartFrame integer Members<br>---<br>hax, don't touch!\n---@field mReloadFramesLeft integer Members<br>---<br>hax, don't touch!\n---@field mReloadNextFrameUsable integer Members<br>---<br>hax, don't touch!\n---@field mChargeCount integer Members<br>---<br>hax, don't touch!\n---@field mIsInitialized boolean Members\n---@field gun_config unsupported Objects<br>---<br>Constants for gun script\n---@field gunaction_config unsupported Objects<br>---<br>Constants for gun script\n---@field mAmmoLeft integer Privates\n---@field mNextChargeFrame integer Privates\n---@field mItemRecoil number Privates\n\n---@class AdvancedFishAIComponentClass\n---@field comp_id integer\n---@field enable boolean\n---@field attr AdvancedFishAIComponent\n\n---@class AdvancedFishAIComponent\n---@field move_check_range_min number Members\n---@field move_check_range_max number Members\n---@field flock boolean Privates\n---@field avoid_predators boolean Privates\n---@field mHasTargetDirection boolean Privates\n---@field mTargetPos unsupported Privates\n---@field mTargetVec unsupported Privates\n---@field mLastFramesMovementAreaMin unsupported Privates\n---@field mLastFramesMovementAreaMax unsupported Privates\n---@field mNumFailedTargetSearches unsupported Privates\n---@field mNextFrameCheckAreWeStuck integer Privates\n---@field mNextFrameCheckFlockWants integer Privates\n---@field mNextFramePredatorAvoidance integer Privates\n---@field mScared number Privates\n---@field mWantsToBeInFlock boolean Privates\n\n---@class AltarComponentClass\n---@field comp_id integer\n---@field enable boolean\n---@field attr AltarComponent\n\n---@class AltarComponent\n---@field recognized_entity_tags string Members\n---@field uses_remaining integer Members\n---@field good_fx_material integer Custom data types<br>---<br>String name of material for particles emitted on successful sacrifice\n---@field neutral_fx_material integer Custom data types<br>---<br>String name of material for particles emitted on successful sacrifice\n---@field evil_fx_material integer Custom data types<br>---<br>String name of material for particles emitted on successful sacrifice\n---@field m_recognized_entity_tags unsupported Privates\n---@field m_recognized_entity_tags_count unsupported Privates\n---@field m_current_entity_tags unsupported Privates\n\n---@class AnimalAIComponentClass\n---@field comp_id integer\n---@field enable boolean\n---@field attr AnimalAIComponent\n\n---@class AnimalAIComponent\n---@field ai_state integer Members<br>---<br>Current state of ai, defines what the animal is doing\n---@field ai_state_timer integer Members<br>---<br>If not 0, then we wait till this frame to pop current state from our state stack\n---@field keep_state_alive_when_enabled boolean Members<br>---<br>if 1, will ensure state timer keeps current state alive for a while when Component is Enabled\n---@field preferred_job string Members<br>---<br>We always do this job, unless interrupted (i.e. by taking fire damage)\n---@field escape_if_damaged_probability integer Members<br>---<br>the chance of escaping if someone damages us. only works if 'can_fly = 0 '\n---@field attack_if_damaged_probability integer Members<br>---<br>the chance of counter-attacking if someone damages us, and we didn't escape\n---@field eye_offset_x integer Members<br>---<br>We cast rays from our position + eye_offset to check if we can see something\n---@field eye_offset_y integer Members<br>---<br>We cast rays from our position + eye_offset to check if we can see something\n---@field attack_only_if_attacked boolean Members<br>---<br>If 1, we never attack anyone unless attacked before by someone\n---@field dont_counter_attack_own_herd boolean Members<br>---<br>If 1, we don't attack members of our herd even if they accidentally attack us\n---@field creature_detection_range_x number Members<br>---<br>When looking for threats/prey this is the max distance from us on the X axis we scan\n---@field creature_detection_range_y number Members<br>---<br>When looking for threats/prey this is the max distance from us on the Y axis we scan\n---@field creature_detection_angular_range_deg number Members<br>---<br>When looking for threats/prey this is our field of view around the X axis. 90 means we scan the whole 180 degrees around the X axis, to the left and right\n---@field creature_detection_check_every_x_frames integer Members<br>---<br>Checks for threats/prey take place at least this many frames apart from each other\n---@field max_distance_to_cam_to_start_hunting number Members<br>---<br>JobDefault idles before we've been once at least this close to the camera\n---@field pathfinding_max_depth_no_target integer Members<br>---<br>The maximum depth (in nodes) path search use when we have not found prey yet\n---@field pathfinding_max_depth_has_target integer Members<br>---<br>The maximum depth (in nodes) path search use when we have found prey\n---@field aggressiveness_min number Members<br>---<br>what's the initial random aggressiveness of this creature\n---@field aggressiveness_max number Members<br>---<br>what's the initial random aggressiveness of this creature\n---@field tries_to_ranged_attack_friends boolean Members<br>---<br>if 1, the AI tries to attack whoever it considers a friend based on herd_ids, CHARMED and BERSERK status etc. useful e.g. for healers.\n---@field attack_melee_enabled boolean Members<br>---<br>If 1, and melee attack has been configured, we can perform melee attacks\n---@field attack_dash_enabled boolean Members<br>---<br>If 1, and dash attack has been configured, we can perform dash attacks (a long-distance melee attack where we dash towards the enemy)\n---@field attack_landing_ranged_enabled boolean Members<br>---<br>If 1, and ranged attack has been configured, we can perform ranged attacks\n---@field attack_ranged_enabled boolean Members<br>---<br>If 1, and ranged attack has been configured, we can perform ranged attacks\n---@field attack_knockback_multiplier number Members<br>---<br>If not 0, melee and dash attacks cause knockback to target\n---@field is_static_turret boolean Members<br>---<br>If 1, we can only attack in one fixed direction\n---@field attack_melee_max_distance integer Members<br>---<br>Maximum distance at which we can perform a melee attack\n---@field attack_melee_action_frame integer Members<br>---<br>The animation frame during which the melee attack damage is inflicted and visual effects are created\n---@field attack_melee_frames_between integer Members<br>---<br>The minimum number of frames we wait between melee attacks\n---@field attack_melee_damage_min number Members<br>---<br>Melee attack damage inclusive minimum amount. The damage is randomized between melee attack_damage_min and attack_melee_damage_max\n---@field attack_melee_damage_max number Members<br>---<br>Melee attack damage inclusive maximum amount. The damage is randomized between melee attack_damage_min and attack_melee_damage_max\n---@field attack_melee_impulse_vector_x number Members<br>---<br>The x component of the impulse that is applied to damaged entities\n---@field attack_melee_impulse_vector_y number Members<br>---<br>The y component of the impulse that is applied to damaged entities\n---@field attack_melee_impulse_multiplier number Members<br>---<br>A multiplier applied to attack_melee_impulse\n---@field attack_melee_offset_x number Members<br>---<br>Melee attack particle effects are created here\n---@field attack_melee_offset_y number Members<br>---<br>Melee attack particle effects are created here\n---@field attack_melee_finish_enabled boolean Members<br>---<br>If 1, we perform a finishing move when our attack would kill the target using the 'attack_finish' animation\n---@field attack_melee_finish_action_frame integer Members<br>---<br>The animation frame during which the melee attack finishing move damage is inflicted and visual effects are created\n---@field attack_dash_distance number Members<br>---<br>The maximum distance from enemy at which we can perform a dash attack. If a normal melee attack is possible we always do that instead\n---@field attack_dash_frames_between integer Members<br>---<br>The minimum number of frames we wait between dash attacks\n---@field attack_dash_damage number Members<br>---<br>The amount of damage inflicted by the dash attack\n---@field attack_dash_speed number Members<br>---<br>The speed at which we dash\n---@field attack_dash_lob number Members<br>---<br>The smaller this value is the more curved our dash attack trajectory is\n---@field attack_ranged_min_distance number Members<br>---<br>The minimum distance from enemy at which we can perform a ranged attack.\n---@field attack_ranged_max_distance number Members<br>---<br>The maximum distance from enemy at which we can perform a ranged attack.\n---@field attack_ranged_action_frame integer Members<br>---<br>The frame of the 'attack_ranged' animation during which the ranged attack actually occurs\n---@field attack_ranged_offset_x number Members<br>---<br>'attack_ranged_entity_file' is created here when performing a ranged attack\n---@field attack_ranged_offset_y number Members<br>---<br>'attack_ranged_entity_file' is created here when performing a ranged attack\n---@field attack_ranged_use_message boolean Members<br>---<br>If 1, we do ranged attacks by sending a Message_UseItem\n---@field attack_ranged_predict boolean Members<br>---<br>If 1, we attempt to predict target movement and shoot accordingly\n---@field attack_ranged_entity_file string Members<br>---<br>File to projectile entity that is created when performing a ranged attack\n---@field attack_ranged_entity_count_min integer Members<br>---<br>Minimum number of projectiles shot when performing a ranged attack\n---@field attack_ranged_entity_count_max integer Members<br>---<br>Maximum number of projectiles shot when performing a ranged attack\n---@field attack_ranged_use_laser_sight boolean Members<br>---<br>If 1, we draw a laser sight to our target. Requires entity to have a sprite with tag 'laser_sight'\n---@field attack_ranged_laser_sight_beam_kind boolean Members<br>---<br>0 = red, 1 = blue \n---@field attack_ranged_aim_rotation_enabled boolean Members\n---@field attack_ranged_aim_rotation_speed number Members\n---@field attack_ranged_aim_rotation_shooting_ok_angle_deg number Members\n---@field attack_ranged_state_duration_frames integer Members<br>---<br>How long do we stay in the attack state, before other states are allowed?\n---@field hide_from_prey boolean Members<br>---<br>If 1, we attempt to hide from our target after a succesful attack\n---@field hide_from_prey_target_distance number Members<br>---<br>The minimum distance from our target where we should move when hiding\n---@field hide_from_prey_time integer Members<br>---<br>The number of frames we spend hiding and staying hiding\n---@field food_eating_create_particles boolean Members<br>---<br>If 1, we replace eaten cells with particles made of this material\n---@field eating_area_radius_x integer Members<br>---<br>1/2 width of the area from which we eat food\n---@field eating_area_radius_y integer Members<br>---<br>1/2 height of the area from which we eat food\n---@field mouth_offset_x integer Members<br>---<br>The center of the area from which we eat food\n---@field mouth_offset_y integer Members<br>---<br>The center of the area from which we eat food\n---@field defecates_and_pees boolean Members<br>---<br>If 1, we occasionally take a leak or a dump\n---@field butt_offset_x integer Members<br>---<br>Bodily wastes are created here\n---@field butt_offset_y integer Members<br>---<br>Bodily wastes are created here\n---@field pee_velocity_x number Members<br>---<br>The velocity at which our piss gets shot\n---@field pee_velocity_y number Members<br>---<br>The velocity at which our piss gets shot\n---@field needs_food boolean Members<br>---<br>If 1, we stop to eat if we encounter 'food_material' cells\n---@field sense_creatures boolean Members<br>---<br>If 1, we occasionally search our surroundings for prey and threats\n---@field sense_creatures_through_walls boolean Members<br>---<br>If 1, will see creatures even if the wall raycast fails\n---@field can_fly boolean Members<br>---<br>If 1, we can fly. Please set 'PathFindingComponent.can_fly' to 1 as well if this is 1\n---@field can_walk boolean Members<br>---<br>If 1, we can walk. Please set 'PathFindingComponent.can_walk' to 1 as well if this is 1\n---@field path_distance_to_target_node_to_turn_around integer Members<br>---<br>If we're further than this from target path finding node on the X-axis we turn to face it\n---@field path_cleanup_explosion_radius number Members<br>---<br>If we get stuck on ground we create an explosion this big to clear our surroundings a bit\n---@field max_distance_to_move_from_home number Members\n---@field attack_melee_finish_config_explosion unsupported Objects<br>---<br>If we have explosion, it's the setup for it\n---@field attack_ranged_frames_between integer Custom data types<br>---<br>The minimum number of frames we wait between ranged attacks\n---@field food_material integer Custom data types<br>---<br>The cell material we eat if encountering said material and 'needs_food' is 1\n---@field food_particle_effect_material integer Custom data types<br>---<br>We create particles made of this material when eating if 'food_eating_create_particles' is 1\n---@field mAggression number Custom data types<br>---<br>the greater this value the more likely we're to attack creatures from other herds\n---@field mAiStateStack unsupported Privates<br>---<br>a stack of actions and times they take, we can push new actions to the front and pop them from there\n---@field mAiStateLastSwitchFrame integer Privates<br>---<br>when was the last time we switched a state\n---@field mAiStatePrev integer Privates<br>---<br>previous AI state\n---@field mCreatureDetectionNextCheck integer Privates<br>---<br>threat/prey check, next time we check for threat/prey\n---@field mGreatestThreat integer Privates<br>---<br>the entity we consider to be our greatest threat\n---@field mGreatestPrey integer Privates<br>---<br>the entity we consider to be our most important prey\n---@field mSelectedMultiAttack integer Privates<br>---<br>which AIAttackComponent attack are we using?\n---@field mHasFoundPrey boolean Privates<br>---<br>1, if we have ever found prey\n---@field mHasBeenAttackedByPlayer boolean Privates<br>---<br>1, if we have been ever attacked\n---@field mHasStartedAttacking boolean Privates<br>---<br>1, if we have ever started attacking anyone\n---@field mNearbyFoodCount integer Privates<br>---<br>amount of 'food_material' near us\n---@field mEatNextFrame integer Privates<br>---<br>next frame we can eat\n---@field mEatTime integer Privates<br>---<br>time we've been constantly eating\n---@field mFrameNextGiveUp integer Privates<br>---<br>next frame we consider ourselves to be stuck\n---@field mLastFramesMovementAreaMin unsupported Privates<br>---<br>AABB min of the area where we've been since the last time we got stuck\n---@field mLastFramesMovementAreaMax unsupported Privates<br>---<br>AABB max of the area where we've been since the last time we got stuck\n---@field mFoodMaterialId integer Privates<br>---<br>cached id of 'food_material'\n---@field mFoodParticleEffectMaterialId integer Privates<br>---<br>cached id of 'food_particle_effect_material'\n---@field mNextJumpLob number Privates<br>---<br>we use this for next jump\n---@field mNextJumpTarget unsupported Privates<br>---<br>we use this for next jump\n---@field mNextJumpHasVelocity boolean Privates<br>---<br>we use this for next jump\n---@field mLastFrameJumped integer Privates<br>---<br>previous frame we launched into a jump\n---@field mFramesWithoutTarget integer Privates\n---@field mLastFrameCanDamageOwnHerd integer Privates\n---@field mHomePosition unsupported Privates<br>---<br>where our home is located\n---@field mLastFrameAttackWasDone integer Privates<br>---<br>when was the last time we did an attack (not necessarily did damage to anyone though)\n---@field mNextFrameCanCallFriend integer Privates\n---@field mNextFrameRespondFriend integer Privates\n---@field mHasNoticedPlayer boolean Privates<br>---<br>if 1, we have noticed player or player projectile\n---@field mRangedAttackCurrentAimAngle number Privates<br>---<br>which direction does our gun currently point at, physically saying?\n---@field mRangedAttackNextFrame integer Privates<br>---<br>next frame we can perform a ranged attack\n---@field mMeleeAttackNextFrame integer Privates<br>---<br>next frame we can perform a melee attack\n---@field mNextMeleeAttackDamage number Privates<br>---<br>the amount of damage our next melee attack will cause. used by finishing move logic\n---@field mMeleeAttacking boolean Privates<br>---<br>1, if we're doing a melee attack\n---@field mMeleeAttackDashNextFrame integer Privates<br>---<br>the next frame we can perform a melee attack\n---@field mCurrentJob unsupported Privates<br>---<br>info about our current job. sorta legacy and could be simplified because the RTS logic is not used anywhere but doesn't have much overhead either.\n\n---@class ArcComponentClass\n---@field comp_id integer\n---@field enable boolean\n---@field attr ArcComponent\n\n---@class ArcComponent\n---@field lifetime integer Members<br>---<br>remaining number of frames the arc exists\n---@field type unsupported Custom data types<br>---<br>which implementation the arc should use\n---@field material integer Custom data types<br>---<br>string name for the material the arc is made of\n---@field mArcTarget integer Privates<br>---<br>if 'mArcTarget' points to an existing entity a lighting arc will be created between this entity and 'mArcTarget'\n\n---@class AreaDamageComponentClass\n---@field comp_id integer\n---@field enable boolean\n---@field attr AreaDamageComponent\n\n---@class AreaDamageComponent\n---@field circle_radius number Members<br>---<br>if > 0, will only damage entities inside the aabb rectangle which are closer than 'circle_radius' to the aabb center.\n---@field damage_per_frame number Members\n---@field update_every_n_frame integer Members\n---@field entity_responsible integer Members<br>---<br>if NULL, will try to figure out who to blame\n---@field death_cause string Members\n---@field entities_with_tag string Members<br>---<br>damage entities with this tag\n---@field aabb_min unsupported Custom data types\n---@field aabb_max unsupported Custom data types\n---@field damage_type unsupported Custom data types<br>---<br>the damage type\n\n---@class AttachToEntityComponentClass\n---@field comp_id integer\n---@field enable boolean\n---@field attr AttachToEntityComponent\n\n---@class AttachToEntityComponent\n---@field only_position boolean Members<br>---<br>if 1, we only inherit position. it is calculated as follows: target_position + target_offset * target_scale\n---@field target_hotspot_tag string Members<br>---<br>if set, we apply the offset of target HotSpot with this tag\n---@field target_sprite_id integer Members<br>---<br>if >= 0, the Nth sprite transform in target entity is inherited\n---@field rotate_based_on_x_scale boolean Members<br>---<br>if 1, the rotation is set to 0 deg if scale >= 0 else to 180 deg\n---@field destroy_component_when_target_is_gone boolean Members<br>---<br>should probably be on by default\n---@field Transform unsupported Custom data types\n---@field target integer Privates<br>---<br>EntityID of the entity we're attached to. This will fail after save/load, unfortunately\n---@field mUpdateFrame integer Privates\n\n---@class AudioComponentClass\n---@field comp_id integer\n---@field enable boolean\n---@field attr AudioComponent\n\n---@class AudioComponent\n---@field file string Members\n---@field event_root string Members\n---@field audio_physics_material string Members\n---@field set_latest_event_position boolean Members\n---@field remove_latest_event_on_destroyed boolean Members\n---@field send_message_on_event_dead boolean Members\n---@field play_only_if_visible boolean Members<br>---<br>plays sounds only if entity position is on screen and not covered by fog of war\n---@field m_audio_physics_material integer Privates\n---@field m_latest_source unsupported Privates\n\n---@class AudioListenerComponentClass\n---@field comp_id integer\n---@field enable boolean\n---@field attr AudioListenerComponent\n\n---@class AudioListenerComponent\n---@field z number Members\n\n---@class AudioLoopComponentClass\n---@field comp_id integer\n---@field enable boolean\n---@field attr AudioLoopComponent\n\n---@class AudioLoopComponent\n---@field file string Members\n---@field event_name string Members\n---@field auto_play boolean Members\n---@field auto_play_if_enabled boolean M