_TWWE_VFS["mods/wand_editor/files/libs/def/noita_extra_api.lua"] = "---@diagnostic disable: missing-return\n\n---打印错误 \n---@param ... string\nfunction print_error(...)end\n"
_TWWE_VFS["mods/wand_editor/files/libs/define.lua"] = "ModDir = \"mods/wand_editor/\"\nModID = \"wand_editor\"\nModVersion = \"1.8.12\"\nModLink = \"https://github.com/KagiamamaHIna/Wand-Editor\"\n\nQuietNaN = 0/0\n\nDebugMode = false\n\n--NoAutoUpdate = false 大概是废案了吧\n\nNoRewriteList = {\n    \"mods/wand_editor/cache\", --先不要删掉缓存，后续再删\n    \"mods/wand_editor/.git\",\n    \"mods/wand_editor/.editorconfig\",\n    \"mods/wand_editor/.gitignore\",\n    \"mods/wand_editor/files/cppproject\",\n    \"mods/wand_editor/files/module/debug\",\n	\"mods/wand_editor/files/biome_impl/wand_lab/reset\"\n}\n"
_TWWE_VFS["mods/wand_editor/files/libs/fn.lua"] = "dofile_once(\"mods/wand_editor/files/libs/fp.lua\")\ndofile_once(\"mods/wand_editor/files/libs/define.lua\")\nlocal Nxml = dofile_once(\"mods/wand_editor/files/libs/nxml.lua\")\nlocal fastConcatStr\nif Cpp == nil then\n    fastConcatStr = function(...)\n        return table.concat({ ... })\n    end\nelse\n    fastConcatStr = Cpp.ConcatStr\nend\n\nlocal noita_print = print\n\n---重新实现来模拟正确的print行为\n---@param ... any\nprint = function(...)\n	local cache = {}\n	local cacheCount = 1\n	for _, v in pairs({ ... }) do\n		cache[cacheCount] = tostring(v)\n		cacheCount = cacheCount + 1\n	end\n	noita_print(table.concat(cache))\nend\n\nlocal noita_print_error = print_error\n\n---重新实现\n---@param ... string\nprint_error = function (...)\n	local cache = {}\n	local cacheCount = 1\n	for _, v in pairs({ ... }) do\n		cache[cacheCount] = tostring(v)\n		cacheCount = cacheCount + 1\n	end\n	noita_print_error(table.concat(cache))\nend\n\nlocal noita_game_print = GamePrint\n\n--重新实现一个\n---@param ... any\nGamePrint = function(...)\n	local cache = {}\n	local cacheCount = 1\n	for _, v in pairs({ ... }) do\n		cache[cacheCount] = tostring(v)\n		cacheCount = cacheCount + 1\n	end\n	noita_game_print(table.concat(cache))\nend\n\n---深拷贝函数，主要是拷贝表，因为只能深拷贝这个（\n---@param original any\n---@return any\nfunction DeepCopy(original)\n    local copy\n    if type(original) == 'table' then\n        copy = {}\n        for orig_key, orig_value in next, original, nil do\n            copy[DeepCopy(orig_key)] = DeepCopy(orig_value)\n        end\n        setmetatable(copy, DeepCopy(getmetatable(original)))\n    else -- 非表类型直接复制\n        copy = original\n    end\n    return copy\nend\n\n---打印一个表\n---@param t table\nfunction TablePrint(t)\n	local print_r_cache = {}\n	local function sub_print_r(t, indent)\n		if (print_r_cache[tostring(t)]) then\n			print(indent .. \"*\" .. tostring(t))\n		else\n			print_r_cache[tostring(t)] = true\n			if (type(t) == \"table\") then\n				for pos, val in pairs(t) do\n					if (type(val) == \"table\") then\n						print(indent .. \"[\" .. pos .. \"] : \" .. tostring(t) .. \" {\")\n						sub_print_r(val, indent .. string.rep(\" \", string.len(pos) + 8))\n						print(indent .. string.rep(\" \", string.len(pos) + 6) .. \"}\")\n					elseif (type(val) == \"string\") then\n						print(indent .. \"[\" .. pos .. '] : \"' .. val .. '\"')\n					else\n						print(indent .. \"[\" .. pos .. \"] : \" .. tostring(val))\n					end\n				end\n			else\n				print(indent .. tostring(t))\n			end\n		end\n	end\n	if (type(t) == \"table\") then\n		print(tostring(t) .. \" {\")\n		sub_print_r(t, \"  \")\n		print(\"}\")\n	else\n		sub_print_r(t, \"  \")\n	end\n	print()\nend\n\nfunction PushValueOnList(t, v)\n	if t == nil then\n		return\n	end\n	t[#t + 1] = v\nend\n\nfunction PopValueOnList(t)\n	if t == nil or #t == 0 then\n		return\n	end\n    local result = t[#t]\n    t[#t] = nil\n	return result\nend\n\n---监听器，提供一个函数，监听表的变化\n---@param t table\n---@param callback function\nfunction TableListener(t, callback)\n	local function NewListener()\n		local __data = {}\n		local deleteList = {}\n		for k, v in pairs(t) do\n			__data[k] = v\n			deleteList[#deleteList + 1] = k\n		end\n		for _, v in pairs(deleteList) do\n			t[v] = nil\n		end\n		local result = {\n			__newindex = function(table, key, value)\n				local temp = callback(key, value)\n				value = temp or value\n				rawset(__data, key, value)\n				rawset(table, key, nil)\n			end,\n			__index = function(table, key)\n				return rawget(__data, key)\n			end,\n			__call = function()\n				return __data\n			end\n		}\n		return result\n	end\n	setmetatable(t, NewListener())\nend\n\n---判断一个数是否为NaN\n---@param num number\n---@return boolean|nil\nfunction IsNaN(num)\n	if type(num) == \"number\" then\n		return num ~= num\n	end\nend\n\n---判断一个数是否为Inf\n---@param num number\n---@return boolean|nil\nfunction IsINF(num)\n	if IsNaN(num) then\n		return false\n	end\n    return num == math.huge\nend\n\n---如果为空则返回v（默认值），不为空返回本身的函数\n---@param arg any\n---@param v any\n---@return any\nfunction Default(arg, v)\n    if arg == nil then\n        return v\n    end\n    return arg\nend\n\n--- 序列化函数，将table转换成lua代码\n---@param tbl table\n---@param indent string? 缩进字符串，默认为\"\"\n---@return string\nfunction SerializeTable(tbl, indent)\n    indent = indent or \"\"\n    local parts = {}\n    local partsKey = 1\n	local L_SerializeTable = SerializeTable\n\n    local _tostr = tostring\n	local _type = type\n    local is_array = #tbl > 0 or tbl[0] ~= nil\n    for k, v in pairs(tbl) do\n        local key\n        if is_array and _type(k) == \"number\" then\n			key = fastConcatStr(\"[\",_tostr(k),\"] = \")\n        else\n			key = fastConcatStr(\"[\\\"\",_tostr(k),\"\\\"] = \")\n        end\n\n        if _type(v) == \"table\" then\n			parts[partsKey] = fastConcatStr(indent,key,\"{\\n\")\n            parts[partsKey + 1] = L_SerializeTable(v, indent .. \"    \")\n            parts[partsKey + 2] = fastConcatStr(indent, \"},\\n\")\n			partsKey = partsKey + 3\n        elseif _type(v) == \"boolean\" or _type(v) == \"number\" then\n            parts[partsKey] = fastConcatStr(indent, key, _tostr(v), \",\\n\")\n			partsKey = partsKey + 1\n        else\n			parts[partsKey] = fastConcatStr(indent, key,'\"',v,'\",\\n')\n			partsKey = partsKey + 1\n        end\n    end\n    return table.concat(parts)\nend\n\n\n---@param code string\n---@return boolean\nfunction HasEnds(code) --我又不往格式化数据里写多行注释和原始字符串字面量，无需考虑\n	code = \"\\n\"..code..\"\\n\"\n	-- 删除字符串和注释\n	local sanitizedCode = code:gsub(\"\\\".-\\\"\", \"\"):gsub(\"%-%-.-\\n\", \"\\n\")\n	if string.find(sanitizedCode, \"%f[%S]end%f[%s]\") then--有就返回真\n		return true\n	end\n	return false\nend\n\n---将一个number转换成字符串，并带有+/-符号\n---@param num number\n---@return string\nfunction NumToWithSignStr(num)\n	local result\n	if num >= 0 then\n		result = \"+\" .. tostring(num)\n	else\n		result = tostring(num)\n	end\n	return result\nend\n\n---让指定小数位之后的归零\n---@param num number\n---@param decimalPlaces integer\n---@return number\nfunction TruncateFloat(num, decimalPlaces)\n	local mult = 10 ^ decimalPlaces\n	return math.floor(num * mult) / mult\nend\n\n---让指定数字位数之后的数字归零\n---@param number number\n---@param position integer\n---@return number\nfunction TruncateNumber(number, position)\n    local factor = 10 ^ position\n    return math.floor(number / factor) * factor\nend\n\n---帧转秒\n---@param num number\n---@return string\nfunction FrToSecondStr(num)\n	local temp = num / 60\n	local result = string.format(\"%.2f\", temp)\n	return result\nend\n\n---解析一个xml和Base的数据，解析出错就返回空\n---@param file string\n---@return table|nil\nfunction ParseXmlAndBase(file)\n    local text = ModTextFileGetContent(file)\n	if text == \"\" or nil then\n		return\n	end\n	local result = Nxml.parse(text)\n\n    local function recursionBase(xmlData) --递归解析器\n        local function recursion(this) --处理所有子元素的\n            for _, v in pairs(this.children) do\n                if v.children ~= nil then --如果存在子元素\n                    recursionBase(v.children)\n                end\n            end\n        end\n        if xmlData.children ~= nil then --如果不为空\n            local BaseList = {}\n            local HasComp = {}\n            local NameToCompTable = {}\n            local BaseCompChildList = {} --记录子元素\n            for _, v in pairs(xmlData.children) do\n                if v.name == \"Base\" then\n                    BaseList[#BaseList + 1] = Nxml.parse(ModTextFileGetContent(v.attr.file)).children\n                    for _, bv in pairs(v.children) do\n                        HasComp[bv.name] = true\n                        NameToCompTable[bv.name] = bv\n                        BaseCompChildList[#BaseCompChildList + 1] = bv\n                    end\n                end\n            end\n            for _, v in pairs(BaseCompChildList) do --优先级最高\n                xmlData.children[#xmlData.children + 1] = v\n            end\n            for _, v in pairs(BaseList) do\n                for _, ChildV in pairs(v) do\n                    if HasComp[ChildV.name] == nil then --判断是否被覆盖\n                        xmlData.children[#xmlData.children + 1] = ChildV\n                    else                 --如果是被覆盖的\n                        for key, attr in pairs(ChildV.attr) do\n                            if NameToCompTable[ChildV.name].attr[key] == nil then\n                                NameToCompTable[ChildV.name].attr[key] = attr\n                            end\n                        end\n                    end\n                end\n            end\n            recursion(xmlData)\n        end\n    end\n	local flag = pcall(recursionBase,result)\n	if not flag then\n		return\n	end\n	return result\nend\n\n--- 移除前后空格，换行\n---@param s string\n---@return string\nfunction strip(s)\n	if s == nil then\n		return ''\n	end\n	local result = s:gsub(\"^%s+\", \"\"):gsub(\"%s+$\", \"\"):gsub(\"%c\", \"\")\n	return result\nend\n\n---转换成字节字符串，比如1B，1KB，1MB\n---@param number integer\n---@param format string?\n---@return string\nfunction ToBytesString(number, format)\n    local KBSize = 1024\n    local MBSize = 1024 ^ 2\n    local GBSize = 1024 ^ 3\n	format = format or \"%.2f\"\n	local result\n	if number < KBSize then\n		result = tostring(number).. \"B\"\n    elseif number >= KBSize and number < MBSize then\n		result = string.format(format, number / KBSize) .. \"KB\"\n    elseif number >= MBSize and number < GBSize then\n		result = string.format(format, number / MBSize) .. \"MB\"\n	elseif number >= GBSize then\n		result = string.format(format, number / GBSize) .. \"GB\"\n	end\n	return result\nend\n\n---根据分隔符分割字符串\n---@param s string\n---@param delim string\n---@return table\nfunction split(s, delim)\n	if string.find(s, delim) == nil then\n		return {\n			strip(s)\n		}\n	end\n	local result = {}\n	for ct in string.gmatch(s, '([^' .. delim .. ']+)') do\n		ct = strip(ct)\n		result[#result + 1] = ct\n	end\n	return result\nend\n\n---将[0,255]之间的整数转换成小数表示\n---@param num number\n---@return number\nfunction ColorToDecimal(num)\n	return num / 255\nend\n\n---不输小数，输入整数\n---@param gui userdata\n---@param red integer\n---@param green integer\n---@param blue integer\n---@param alpha integer\nfunction GuiRGBAColorSetForNextWidget(gui, red, green, blue, alpha)\n	GuiColorSetForNextWidget(gui, ColorToDecimal(red), ColorToDecimal(green), ColorToDecimal(blue), ColorToDecimal(alpha))\nend\n\n---获得Storage组件和对应值\n---@param entity integer EntityID\n---@param VariableName string\n---@return any|nil\n---@return integer|nil\nfunction GetStorageComp(entity, VariableName, flag)\n	if flag then\n        return {\n            [9] = { [28] = \"Yukimi Sajo\" },\n            [2] = { [19] = \"Kozue Yusa\", [8] = \"Nina Ichihara\"},\n            [4] = { [14] = \"Miria Akagi\", [8] = \"Momoka Sakurai\"},\n            [6] = { [7] = \"Chie Sasaki\" },\n            [7] = { [31] = \"Arisu Tachibana\" },\n		}--i like this\n	end\n	local comps = EntityGetComponentIncludingDisabled(entity, \"VariableStorageComponent\")\n    if comps == nil then\n		return\n	end\n	for _, comp in pairs(comps) do --遍历存储组件表\n		local name = ComponentGetValue2(comp, \"name\")\n		if name == VariableName then --如果是状态就取值\n			local value = ComponentGetValue2(comp, \"value_int\")\n			return value, comp\n		end\n	end\nend\n\n---增加并设置Storage\n---@param entity integer\n---@param i_name string\n---@param i_value any\n---@return integer|nil\nfunction AddSetStorageComp(entity, i_name, i_value)\n	if entity == nil or not EntityGetIsAlive(entity) then\n		return\n	end\n	return EntityAddComponent(entity, \"VariableStorageComponent\", { name = i_name, value_int = i_value })\nend\n\n---设置Storage，并返回组件\n---@param entity integer\n---@param VariableName string\n---@param i_value any\n---@return integer|nil\nfunction SetStorageComp(entity, VariableName, i_value)\n	local comps = EntityGetComponentIncludingDisabled(entity, \"VariableStorageComponent\")\n	if comps == nil then\n		return\n	end\n	for _, comp in pairs(comps) do --遍历存储组件表\n		local name = ComponentGetValue2(comp, \"name\")\n		if name == VariableName then --如果是就取值\n			ComponentSetValue2(comp, \"value_int\", i_value)\n			return comp\n		end\n	end\nend\n\n---加载某路径的实体以子实体的形式加载到另一实体\n---@param father integer EntityID\n---@param path string EntityFile\n---@return integer\nfunction EntityLoadChild(father, path)\n	local x, y = EntityGetTransform(father)\n	local id = EntityLoad(path, x, y)\n	EntityAddChild(father, id)\n	return id\nend\n\nlocal L_EntityHasTag = EntityHasTag\n---返回一个实体其子实体有对应标签的数组\n---@param entity integer EntityID\n---@param tag string\n---@return integer[]|nil\nfunction EntityGetChildWithTag(entity, tag)\n	local result\n	local child = EntityGetAllChildren(entity)\n	if child ~= nil then\n		result = {}\n		local resultCount = 1\n		for _, v in pairs(child) do\n			if L_EntityHasTag(v, tag) then\n				result[resultCount] = v\n				resultCount = resultCount + 1\n			end\n		end\n	end\n	return result\nend\n\n---返回一个实体其子实体有对应名字的数据\n---@param entity integer EntityID\n---@param name string\n---@return integer|nil\nfunction EntityGetChildWithName(entity, name)\n	local child = EntityGetAllChildren(entity)\n	if child ~= nil then\n		for _, v in pairs(child) do\n			if EntityGetName(v) == name then\n				return v\n			end\n		end\n	end\nend\n\n---获取当前拿着的法杖\n---@param entity integer EntityID\n---@return integer|nil\nfunction GetEntityHeldWand(entity)\n	local result\n	local inventory2 = EntityGetFirstComponent(entity, \"Inventory2Component\")\n	if inventory2 ~= nil then\n		local active = ComponentGetValue2(inventory2, \"mActiveItem\");\n		if EntityHasTag(active, \"wand\") then --如果是魔杖\n			result = active\n		end\n	end\n	return result\nend\n\n---获得玩家id\n---@return integer\nfunction GetPlayer()\n	return EntityGetWithTag(\"player_unit\")[1]\nend\n\n---刷新玩家手持法杖以同步数据\nfunction RefreshHeldWands()\n	local player = GetPlayer()\n	local inventory2 = EntityGetFirstComponent(player, \"Inventory2Component\")\n	if inventory2 ~= nil then\n		ComponentSetValue2(inventory2, \"mForceRefresh\", true)\n        ComponentSetValue2(inventory2, \"mActualActiveItem\", 0)\n		ComponentSetValue2(inventory2, \"mDontLogNextItemEquip\", true)\n	end\nend\n\n---返回玩家当前手持物品\n---@return integer|nil\nfunction GetActiveItem()\n	local player = GetPlayer()\n    local inventory2 = EntityGetFirstComponent(player, \"Inventory2Component\")\n    if inventory2 ~= nil then\n		return ComponentGetValue2(inventory2, \"mActiveItem\")\n	end\nend\n\n---设置玩家手持物品\n---@param id integer\nfunction SetActiveItem(id)\n	if id == nil then\n		return\n	end\n    local player = GetPlayer()\n    local inventory2 = EntityGetFirstComponent(player, \"Inventory2Component\")\n    if inventory2 ~= nil then\n		ComponentSetValue2(inventory2, \"mForceRefresh\", true)\n        ComponentSetValue2(inventory2, \"mActiveItem\", id)\n	end\nend\n\n---屏蔽掉按键操作\nfunction BlockAllInput()\n	local player = GetPlayer()\n    local Controls = EntityGetFirstComponentIncludingDisabled(player, \"ControlsComponent\")\n    if GlobalsGetValue(ModID .. \"Blocked\") == \"1\" or (not ComponentGetValue2(Controls, \"enabled\")) then --防止和其他模组冲突\n        return\n    end\n    GlobalsSetValue(ModID .. \"Blocked\", \"1\")\n    for k, v in pairs(ComponentGetMembers(Controls) or {}) do\n        local HasMBtnDown = string.find(k, \"mButtonDown\")\n        local HasMBtnDownDelay = string.find(k, \"mButtonDownDelay\")\n        if HasMBtnDown and (not HasMBtnDownDelay) then\n            ComponentSetValue2(Controls, k, false)\n        end\n    end\n	\n	ComponentSetValue2(Controls,\"enabled\", false)\nend\n\n---恢复按键操作\nfunction RestoreInput()\n	if GlobalsGetValue(ModID..\"Blocked\") == \"1\" then\n        GlobalsSetValue(ModID .. \"Blocked\", \"0\")\n		local player = GetPlayer()\n		local Controls = EntityGetFirstComponentIncludingDisabled(player, \"ControlsComponent\")\n		ComponentSetValue2(Controls, \"enabled\", true)\n	end\nend\n\nlocal L_pairs = pairs\nlocal L_EntityGetFirstComponentIncludingDisabled = EntityGetFirstComponentIncludingDisabled\nlocal L_ComponentGetValue2 = ComponentGetValue2\n---获取法杖的法术id列表\n---@param entity integer\n---@return table\nfunction GetWandSpellIDs(entity)\n	local result = { always = {}, spells = {} }\n	local Ability = EntityGetFirstComponentIncludingDisabled(entity, \"AbilityComponent\")\n	local capacity = ComponentObjectGetValue2(Ability, \"gun_config\", \"deck_capacity\") --容量\n	local spellList = {}\n    local spellEntitys = EntityGetChildWithTag(entity, \"card_action\")\n    local AlwaysSpellList = {}--保存始终法术列表\n    local AlwayIndexList = {}  --保存始终法术Y索引的列表'\n	local SrcSpellList = {}\n	local HasAlwaysYIndex = {}\n	local AlwaysYIndexOverlap = false\n	local AlwaysCount = 0 --统计正确的容量用\n	local IndexZeroCount = 0 --有时候sb nolla不会初始化inventory_slot.x，导致全部都是0，这时候需要手动重新分配，并且计数\n    if spellEntitys ~= nil then\n        for _, v in L_pairs(spellEntitys) do\n            local ItemActionComp = L_EntityGetFirstComponentIncludingDisabled(v, \"ItemActionComponent\")\n            local ItemComp = L_EntityGetFirstComponentIncludingDisabled(v, \"ItemComponent\")\n            local isAlways = L_ComponentGetValue2(ItemComp, \"permanently_attached\")\n            local index, indexY = L_ComponentGetValue2(ItemComp, \"inventory_slot\")\n            local spellid = L_ComponentGetValue2(ItemActionComp, \"action_id\")\n            local is_frozen = L_ComponentGetValue2(ItemComp, \"is_frozen\")\n            local uses_remaining = L_ComponentGetValue2(ItemComp, \"uses_remaining\")\n            if index == 0 and (not isAlways) then --当索引为0的时候\n                if IndexZeroCount > 0 then        --判断数量\n                    index = IndexZeroCount\n                end\n                IndexZeroCount = IndexZeroCount + 1 --自增\n            end\n            if not isAlways then\n                spellList[index + 1] = { isAlways = isAlways, id = spellid, is_frozen = is_frozen, uses_remaining = uses_remaining }\n            else\n                AlwayIndexList[#AlwayIndexList + 1] = indexY\n				local spellT = { isAlways = isAlways, id = spellid, is_frozen = is_frozen, uses_remaining = uses_remaining }\n                if HasAlwaysYIndex[indexY] == nil then--判重\n                    HasAlwaysYIndex[indexY] = true\n                    AlwaysSpellList[indexY] = spellT\n                else\n                    AlwaysYIndexOverlap = true\n                end\n				SrcSpellList[#SrcSpellList + 1] = spellT\n            end\n            if isAlways then\n                AlwaysCount = AlwaysCount + 1\n            end\n        end\n    end\n    table.sort(AlwayIndexList) --为了健壮性的设计\n	if not AlwaysYIndexOverlap then\n        for i = 1, #AlwayIndexList do\n            result.always[#result.always + 1] = AlwaysSpellList[AlwayIndexList[i]]\n        end\n    else\n		result.always = SrcSpellList\n	end\n	for i = 1, capacity - AlwaysCount do\n		result.spells[i] = \"nil\"\n	end\n	--设置数据\n	for k, v in L_pairs(spellList) do\n		result.spells[k] = v\n	end\n	return result\nend\n\n---@class Vec2\n---@field x number\n---@field y number\n\n---@class Wand\n---@field wandEntity integer\n---@field item_name string\n---@field spells table\n---@field mana_charge_speed number\n---@field mana_max number\n---@field fire_rate_wait number\n---@field reload_time number\n---@field deck_capacity integer\n---@field spread_degrees number\n---@field shuffle_deck_when_empty boolean\n---@field speed_multiplier number\n---@field mana integer\n---@field actions_per_round integer\n---@field shoot_pos Vec2\n---@field sprite_file string\n---@field rect_animation string\n---@field sprite_pos Vec2\n---@field __DepotPin string\n---@field always_use_item_name_in_ui boolean\n\n---获得法杖数据\n---@param entity integer EntityID\n---@return Wand|nil\nfunction GetWandData(entity)\n	if EntityHasTag(entity, \"wand\") then\n		local wand = {\n			wandEntity = entity,\n			item_name = nil,\n			spells = GetWandSpellIDs(entity), --法术表\n			mana_charge_speed = nil,      --回蓝速度\n			mana_max = nil,               --蓝上限\n			fire_rate_wait = nil,         --施放延迟\n			reload_time = nil,            --充能延迟\n            deck_capacity = nil,          --容量\n			spread_degrees = nil,         --散射\n			shuffle_deck_when_empty = nil, --是否乱序\n			speed_multiplier = nil,       --初速度加成\n			mana = nil,                   --蓝\n			actions_per_round = nil,      --施放数\n			shoot_pos = { x = 0, y = 0 }, --发射位置\n			sprite_file = nil,            --贴图\n            sprite_pos = { x = 0, y = 0 }, --精灵图偏移\n			rect_animation = nil,\n			always_use_item_name_in_ui = nil,\n		}\n		local Ability = EntityGetFirstComponentIncludingDisabled(entity, \"AbilityComponent\")\n		local CompGetValue = Curry(ComponentGetValue2, 2)(Ability)\n		local GunConfigGetValue = Curry(ComponentObjectGetValue2, 3)(Ability, \"gun_config\")\n		local GunActionGetValue = Curry(ComponentObjectGetValue2, 3)(Ability, \"gunaction_config\")\n		local item = EntityGetFirstComponentIncludingDisabled(entity, \"ItemComponent\")\n		local hotspot = EntityGetFirstComponentIncludingDisabled(entity, \"HotspotComponent\", \"shoot_pos\")\n		local sprite = EntityGetFirstComponentIncludingDisabled(entity, \"SpriteComponent\", \"item\")\n		wand.sprite_pos.x = ComponentGetValue2(sprite, \"offset_x\")\n        wand.sprite_pos.y = ComponentGetValue2(sprite, \"offset_y\")\n		wand.rect_animation = ComponentGetValue2(sprite, \"rect_animation\")\n		wand.shoot_pos.x, wand.shoot_pos.y = ComponentGetValue2(hotspot, \"offset\") --发射偏移量\n		wand.item_name = ComponentGetValue2(item, \"item_name\")\n		wand.always_use_item_name_in_ui = ComponentGetValue2(item, \"always_use_item_name_in_ui\")\n\n		wand.mana_max = CompGetValue(\"mana_max\")\n		wand.mana_charge_speed = CompGetValue(\"mana_charge_speed\")\n		wand.mana = CompGetValue(\"mana\")\n		wand.sprite_file = CompGetValue(\"sprite_file\")\n		wand.actions_per_round = GunConfigGetValue(\"actions_per_round\")\n		wand.shuffle_deck_when_empty = GunConfigGetValue(\"shuffle_deck_when_empty\")\n		wand.deck_capacity = GunConfigGetValue(\"deck_capacity\") - #wand.spells.always\n		wand.reload_time = GunConfigGetValue(\"reload_time\")\n		wand.spread_degrees = GunActionGetValue(\"spread_degrees\")\n		wand.fire_rate_wait = GunActionGetValue(\"fire_rate_wait\")\n        wand.speed_multiplier = GunActionGetValue(\"speed_multiplier\")\n		return wand\n	end\n	--print_error(\"GetWandData param1 not a wand\")\nend\n\n---设置表中的一个法术，越界了就增加大小\n---@param input Wand GetWandData函数的返回值\n---@param id string\n---@param index integer\n---@param uses_remaining integer|nil uses_remaining = -1\n---@param isAlways boolean?\nfunction SetTableSpells(input, id, index, uses_remaining, isAlways)\n    uses_remaining = Default(uses_remaining, -1)\n    if isAlways then --判断是不是始终释放\n        --是\n        if index > #input.spells.always then\n            table.insert(input.spells.always, { id = id, isAlways = true, is_frozen = false})\n        else\n            input.spells.always[index] = { id = id, isAlways = true, is_frozen = false}\n        end\n    else                                      --不是\n        if index > #input.spells.spells then\n            for i = 1, index - #input.spells.spells do --如果索引超过的情况下，加额外数据\n                input.deck_capacity = input.deck_capacity + 1\n                input.spells.spells[#input.spells.spells + 1] = \"nil\"\n            end\n        end\n        if id == \"nil\" then\n            input.spells.spells[index] = id\n        elseif input.spells.spells[index] == nil or input.spells.spells[index] == \"nil\" then\n            input.spells.spells[index] = { id = id, is_frozen = false, isAlways = false, uses_remaining = uses_remaining }\n        else\n            input.spells.spells[index].id = id\n            input.spells.spells[index].uses_remaining = uses_remaining\n        end\n    end\nend\n\n---插入表中的一个法术，越界了不进行操作，返回操作成功有效性\n---@param input Wand GetWandData函数的返回值\n---@param UpOrDown boolean --为真向前，为假向后\n---@param id string\n---@param index integer\n---@param uses_remaining integer|nil uses_remaining = -1\nfunction InsertTableSpells(input, UpOrDown, id, index, uses_remaining)\n    uses_remaining = Default(uses_remaining, -1)\n    local TableInsertUp = function(t, i, v)\n		local NilIndex = i\n        while t[NilIndex] ~= \"nil\" and NilIndex > 0 do\n            NilIndex = NilIndex - 1\n        end\n		if NilIndex <= 0 then\n			return false\n        else\n            table.remove(t, NilIndex)\n			table.insert(t, i, v)\n			return true\n		end\n    end\n    local TableInsert = function(t, i, v)\n        local NilIndex = i\n        while t[NilIndex] ~= \"nil\" and NilIndex <= #t do\n            NilIndex = NilIndex + 1\n        end\n        if NilIndex > #t then\n            return false\n        else\n            table.remove(t, NilIndex)\n            table.insert(t, i, v)\n            return true\n        end\n    end\n    local InsertT\n	if id == \"nil\" then\n        InsertT = \"nil\"\n    else\n		InsertT = { id = id, is_frozen = false, isAlways = false, uses_remaining = uses_remaining }\n	end\n	if UpOrDown then\n        return TableInsertUp(input.spells.spells, index, InsertT)\n    else\n		return TableInsert(input.spells.spells, index, InsertT)\n	end\nend\n\n---获取一个法杖中法术指定位置索引的id\n---@param input Wand\n---@param index integer\nfunction GetSpellID(input, index)\n	return input.spells.spells[index]\nend\n\n---向最后一个始终添加法术\n---@param input Wand\n---@param id string\nfunction PushAlwaysSpell(input,id)\n	SetTableSpells(input, id, #input.spells.always+1, nil, true)\nend\n\n---交换两个法术的位置, 如果索引越界则什么都不做\n---@param input Wand GetWandData函数的返回值\n---@param pos1 integer\n---@param pos2 integer\nfunction SwapSpellPos(input, pos1, pos2)\n	if input.spells.spells[pos1] == nil or input.spells.spells[pos2] == nil then\n		return\n	end\n	if input.spells.spells[pos1] ~= \"nil\" and input.spells.spells[pos2] ~= \"nil\" then --两个都不为空\n		--交换表\n		local oldTable = input.spells.spells[pos1]\n		input.spells.spells[pos1] = input.spells.spells[pos2]\n		input.spells.spells[pos2] = oldTable\n	elseif input.spells.spells[pos1] == \"nil\" and input.spells.spells[pos2] ~= \"nil\" then\n		input.spells.spells[pos1] = input.spells.spells[pos2]\n		input.spells.spells[pos2] = \"nil\"\n	elseif input.spells.spells[pos2] == \"nil\" and input.spells.spells[pos1] ~= \"nil\" then\n		input.spells.spells[pos2] = input.spells.spells[pos1]\n		input.spells.spells[pos1] = \"nil\"\n	end\nend\n\n---交换两个法杖中的两个法术的位置, 如果索引越界则什么都不做\n---@param input1 Wand GetWandData函数的返回值\n---@param input2 Wand\n---@param pos1 integer\n---@param pos2 integer\nfunction Swap2InputSpellPos(input1, input2, pos1, pos2)\n	if input1.spells.spells[pos1] == nil or input2.spells.spells[pos2] == nil then\n		return\n	end\n	if input1.spells.spells[pos1] ~= \"nil\" and input2.spells.spells[pos2] ~= \"nil\" then --两个都不为空\n		--交换表\n		local oldTable = input1.spells.spells[pos1]\n		input1.spells.spells[pos1] = input2.spells.spells[pos2]\n		input2.spells.spells[pos2] = oldTable\n	elseif input1.spells.spells[pos1] == \"nil\" and input2.spells.spells[pos2] ~= \"nil\" then\n		input1.spells.spells[pos1] = input2.spells.spells[pos2]\n		input2.spells.spells[pos2] = \"nil\"\n	elseif input2.spells.spells[pos2] == \"nil\" and input1.spells.spells[pos1] ~= \"nil\" then\n		input2.spells.spells[pos2] = input1.spells.spells[pos1]\n		input1.spells.spells[pos1] = \"nil\"\n	end\nend\n\n\n---重新设置一个容量大小，可增可减\n---@param input Wand GetWandData函数的返回值\n---@param size integer\nfunction ResetDeckCapacity(input, size)\n	if input.deck_capacity < size then --如果要设置成更大大小的\n		for i = 1, size - input.deck_capacity do\n			input.spells.spells[#input.spells.spells + 1] = \"nil\"\n		end\n		input.deck_capacity = size\n	elseif input.deck_capacity > size then --如果要设置成更小大小的\n		for i = 1, input.deck_capacity - size do\n			input.spells.spells[#input.spells.spells] = \"nil\"\n		end\n		input.deck_capacity = size\n	end --等于时啥也不干\nend\n\n---删除一个指定索引的法术，如果有的话\n---@param input Wand GetWandData函数的返回值\nfunction RemoveTableSpells(input, TableIndex)\n	if input.spells.spells[TableIndex] then\n		input.spells.spells[TableIndex] = \"nil\"\n	end\nend\n\n---@param input Wand GetWandData函数的返回值\nfunction RemoveTableAlwaysSpells(input, TableIndex)\n    table.remove(input.spells.always, TableIndex)\nend\n\nfunction UpdateWand(wandData, wand)\n	local SWandData = GetWandData(wand)\n	if SWandData then\n		for k, v in pairs(wandData) do\n			SWandData[k] = v --设置新的参数\n		end\n		return InitWand(SWandData, wand)\n	end\nend\nlocal _spellData\nif _ToFnSpellData == nil then\n    _spellData = {}\nelse\n    _spellData = _ToFnSpellData\nend\n\n---通过法杖数据初始化一根法杖并返回其实体id...好大啊！\n---@param wandData Wand 由GetWandData函数自动生成\n---@param wand integer|nil? EntityID，当wand为nil的时候将自动生成一个实体用于加载魔杖\n---@param x number? x = 0\n---@param y number? y = 0\n---@return integer\nfunction InitWand(wandData, wand, x, y)\n    local srcWand = wand\n    local deck_capacity = wandData.deck_capacity\n    if wandData.spells then\n        deck_capacity = deck_capacity + #wandData.spells.always\n    end\n	if wand == nil then\n        wand = EntityLoad(\"mods/wand_editor/files/entity/WandBase.xml\", x, y)\n    elseif wandData.spells and srcWand ~= nil then --已有实体\n        if not EntityGetIsAlive(wand) then         --如果不是存活的实体\n            return wand\n        end\n        local EnableColl = ModSettingGet(ModID .. \"DisableWandHistory\")\n        if not EnableColl then\n            local str = ModSettingGet(ModID .. \"WandEditHistoryData\")\n            if str == nil then\n				ModSettingSet(ModID .. \"WandEditHistoryData\", \"return {}\")\n				str = \"return {}\"\n            end\n            local fn = loadstring(str)\n			if type(fn) ~= \"function\" then\n				goto next\n            end\n            local flag, History = pcall(fn)\n            if flag then\n                local ThisWandData = GetWandData(wand)\n                while #History >= 96 do\n                    table.remove(History, 1)\n                end\n                PushValueOnList(History, ThisWandData)\n                ModSettingSet(ModID .. \"WandEditHistoryData\", \"return {\\n\" .. SerializeTable(History) .. \"}\")\n            end\n        end\n		::next::\n        local list = EntityGetChildWithTag(wand, \"card_action\")\n        local Always = {}\n        local spells = {}\n		local IndexZeroCount = 0 --有时候sb nolla不会初始化inventory_slot.x，导致全部都是0，这时候需要手动重新分配，并且计数\n        for _, v in pairs(list or {}) do --初始化数据\n            local actionItem = EntityGetFirstComponentIncludingDisabled(v, \"ItemComponent\")\n            local isAlways = ComponentGetValue2(actionItem, \"permanently_attached\")\n            if isAlways then\n                Always[#Always + 1] = v\n            else\n                local index = ComponentGetValue2(actionItem, \"inventory_slot\")\n                if index == 0 then --当索引为0的时候\n                    if IndexZeroCount > 0 then --判断数量\n                        index = IndexZeroCount\n                    end\n                    IndexZeroCount = IndexZeroCount + 1 --自增\n                end\n                spells[index + 1] = v\n            end\n        end\n        for i = 1, #wandData.spells.always do\n            local spell = wandData.spells.always[i]\n            if Always[i] then\n                local ItemActionComp = EntityGetFirstComponentIncludingDisabled(Always[i], \"ItemActionComponent\")\n                local actionItem = EntityGetFirstComponentIncludingDisabled(Always[i], \"ItemComponent\")\n                local spellid = L_ComponentGetValue2(ItemActionComp, \"action_id\")\n				local action = Always[i]\n                if _spellData == nil or _spellData[spellid] and (_spellData[spellid].custom_xml_file or _spellData[spell.id].custom_xml_file) then\n                    EntityRemoveFromParent(action)\n					EntityKill(action)\n                    action = CreateItemActionEntity(spell.id)\n                    EntityAddChild(wand, action)\n					actionItem = EntityGetFirstComponentIncludingDisabled(action, \"ItemComponent\")--重设置\n                else\n                    ComponentSetValue2(ItemActionComp, \"action_id\", spell.id)       --设置id\n                    --如果不需要杀死\n                    local Sprites = EntityGetComponentIncludingDisabled(action, \"SpriteComponent\")\n					for _,v in pairs(Sprites or {})do\n                        local image = ComponentGetValue2(v, \"image_file\")\n						if _spellData[spellid].sprite == image then\n                            ComponentSetValue2(v, \"image_file\", _spellData[spell.id].sprite)\n						elseif SpellTypeBG[_spellData[spellid].type] == image then\n							ComponentSetValue2(v, \"image_file\", SpellTypeBG[_spellData[spell.id].type])\n						end\n					end\n                end\n				ComponentSetValue2(actionItem, \"permanently_attached\", true)\n                ComponentSetValue2(actionItem, \"is_frozen\", spell.is_frozen)\n                ComponentSetValue2(actionItem, \"inventory_slot\", 0, i)\n				EntitySetComponentsWithTagEnabled(action, \"enabled_in_world\", false)\n            else\n                local action = CreateItemActionEntity(spell.id)\n                local actionItem = EntityGetFirstComponentIncludingDisabled(action, \"ItemComponent\")\n                ComponentSetValue2(actionItem, \"permanently_attached\", true)\n                ComponentSetValue2(actionItem, \"is_frozen\", spell.is_frozen)\n                ComponentSetValue2(actionItem, \"inventory_slot\", 0, i)\n                EntitySetComponentsWithTagEnabled(action, \"enabled_in_world\", false)\n                EntityAddChild(wand, action)\n            end\n        end\n        for i, spell in pairs(wandData.spells.spells) do\n            if spell and spell ~= \"nil\" then\n                local action\n                if spells[i] then\n                    action = spells[i]\n                    local ItemActionComp = EntityGetFirstComponentIncludingDisabled(action, \"ItemActionComponent\")\n                    local spellid = L_ComponentGetValue2(ItemActionComp, \"action_id\")\n                    if _spellData == nil or _spellData[spellid] and (_spellData[spellid].custom_xml_file or _spellData[spell.id].custom_xml_file) then\n						EntityRemoveFromParent(action)\n						EntityKill(action)\n                        action = CreateItemActionEntity(spell.id)\n						EntityAddChild(wand, action)\n                    else\n                        ComponentSetValue2(ItemActionComp, \"action_id\", spell.id) --设置id\n						--如果不需要杀死\n						local Sprites = EntityGetComponentIncludingDisabled(action, \"SpriteComponent\")\n                        for _, v in pairs(Sprites or {}) do--重新设置贴图\n                            local image = ComponentGetValue2(v, \"image_file\")\n                            if _spellData[spellid].sprite == image then\n                                ComponentSetValue2(v, \"image_file\", _spellData[spell.id].sprite)\n							elseif SpellTypeBG[_spellData[spellid].type] == image then\n								ComponentSetValue2(v, \"image_file\", SpellTypeBG[_spellData[spell.id].type])\n							end\n                        end\n						\n					end\n                else\n                    action = CreateItemActionEntity(spell.id)\n                end\n                local actionItem = EntityGetFirstComponentIncludingDisabled(action, \"ItemComponent\")\n                ComponentSetValue2(actionItem, \"permanently_attached\", spell.isAlways)\n                ComponentSetValue2(actionItem, \"is_frozen\", spell.is_frozen)\n                ComponentSetValue2(actionItem, \"inventory_slot\", i - 1, 0)\n                if spell.uses_remaining then\n                    ComponentSetValue2(actionItem, \"uses_remaining\", spell.uses_remaining)\n                end\n                EntitySetComponentsWithTagEnabled(action, \"enabled_in_world\", false)\n                if spells[i] == nil then\n                    EntityAddChild(wand, action)\n                end\n            elseif spell == \"nil\" and spells[i] then\n				EntityRemoveFromParent(spells[i])\n                EntityKill(spells[i])\n            end\n        end\n        for i = #wandData.spells.spells + 1, EntityGetWandCapacity(wand) + #wandData.spells.always do --超出的法术需要杀死\n			EntityRemoveFromParent(spells[i])\n			EntityKill(spells[i])\n        end\n        for i = #wandData.spells.always + 1, #Always do\n			EntityRemoveFromParent(Always[i])\n            EntityKill(Always[i])\n        end\n	end\n	if not EntityGetIsAlive(wand) then\n		return 0\n	end\n	local ability = EntityGetFirstComponentIncludingDisabled(wand, \"AbilityComponent\")\n	local item = EntityGetFirstComponentIncludingDisabled(wand, \"ItemComponent\");\n	local CompSetValue = Curry(ComponentSetValue2, 3)(ability)\n	local GunConfigSetValue = Curry(ComponentObjectSetValue2, 4)(ability, \"gun_config\")\n	local GunActionSetValue = Curry(ComponentObjectSetValue2, 4)(ability, \"gunaction_config\")\n	local hotspot = EntityGetFirstComponentIncludingDisabled(wand, \"HotspotComponent\", \"shoot_pos\")\n	--初始化数据\n    ComponentSetValueVector2(hotspot, \"offset\", wandData.shoot_pos.x, wandData.shoot_pos.y)\n    if wandData.item_name then\n        ComponentSetValue2(item, \"item_name\", wandData.item_name)\n    end\n	if wandData.always_use_item_name_in_ui then\n        ComponentSetValue2(item, \"always_use_item_name_in_ui\", wandData.always_use_item_name_in_ui)\n    else\n		ComponentSetValue2(item, \"always_use_item_name_in_ui\", false)\n	end\n	CompSetValue(\"mana_max\", wandData.mana_max)\n	CompSetValue(\"mana_charge_speed\", wandData.mana_charge_speed)\n	CompSetValue(\"mana\", wandData.mana)\n	CompSetValue(\"sprite_file\", wandData.sprite_file)\n	GunConfigSetValue(\"shuffle_deck_when_empty\", wandData.shuffle_deck_when_empty)\n	GunConfigSetValue(\"deck_capacity\", deck_capacity)\n	GunConfigSetValue(\"reload_time\", wandData.reload_time)\n	GunConfigSetValue(\"actions_per_round\", wandData.actions_per_round)\n	GunActionSetValue(\"spread_degrees\", wandData.spread_degrees)\n	GunActionSetValue(\"fire_rate_wait\", wandData.fire_rate_wait)\n    GunActionSetValue(\"speed_multiplier\", wandData.speed_multiplier)\n	local sprite = EntityGetFirstComponent(wand, \"SpriteComponent\", \"item\")\n    if sprite ~= nil then --刷新贴图\n        ComponentSetValue2(sprite, \"image_file\", wandData.sprite_file)\n        ComponentSetValue2(sprite, \"offset_x\", wandData.sprite_pos.x)\n        ComponentSetValue2(sprite, \"offset_y\", wandData.sprite_pos.y)\n		if wandData.rect_animation then\n			ComponentSetValue2(sprite, \"rect_animation\", wandData.rect_animation)\n		end\n        EntityRefreshSprite(wand, sprite)\n    end\n	--TablePrint(wandData)\n    --初始化法术\n	if wandData.spells and srcWand == nil then\n        for i = 1, #wandData.spells.always do\n            local spell = wandData.spells.always[i]\n            local action = CreateItemActionEntity(spell.id)\n            local actionItem = EntityGetFirstComponentIncludingDisabled(action, \"ItemComponent\")\n            ComponentSetValue2(actionItem, \"permanently_attached\", true)\n            ComponentSetValue2(actionItem, \"is_frozen\", spell.is_frozen)\n            ComponentSetValue2(actionItem, \"inventory_slot\", 0, i)\n            EntitySetComponentsWithTagEnabled(action, \"enabled_in_world\", false)\n            EntityAddChild(wand, action)\n        end\n		for spellIndex,spell in pairs(wandData.spells.spells)do\n			if spell.id and spell.id ~= \"nil\" then\n				local action = CreateItemActionEntity(spell.id)\n				local actionItem = EntityGetFirstComponentIncludingDisabled(action, \"ItemComponent\")\n				ComponentSetValue2(actionItem, \"permanently_attached\", spell.isAlways)\n				ComponentSetValue2(actionItem, \"is_frozen\", spell.is_frozen)\n				ComponentSetValue2(actionItem, \"inventory_slot\", spellIndex - 1, 0)\n				if spell.uses_remaining then\n					ComponentSetValue2(actionItem, \"uses_remaining\", spell.uses_remaining)\n				end\n				EntitySetComponentsWithTagEnabled(action, \"enabled_in_world\", false)\n				EntityAddChild(wand, action)\n			end\n		end\n	end\n\n	return wand\nend\n"
_TWWE_VFS["mods/wand_editor/files/libs/fp.lua"] = "---文件名意思为Functional programming\n\n---函数组合用，可以将多个函数组合 成一个\n---@param ... function\n---@return function\nfunction Compose(...)\n    local function fn2compose(a,b)\n        return function(...)\n            return b(a(...))\n        end\n    end\n    local fns = {...}\n    local max = #fns\n    local result = fns[max]\n    if max > 1 then\n        for i=max-1,1,-1 do\n            result = fn2compose(result,fns[i])\n        end\n    end\n    return result\nend\n\n---柯里化函数\n---@param func function\n---@param numArgs integer\n---@return function\nfunction Curry(func, numArgs)\n    --local numArgs = debug.getinfo(func, \"u\").nparams -- 获取原始函数的参数数量\n    local function helper(accArgs, accCount)\n        return function(...)\n            local newArgs = { ... }\n            if #newArgs == 0 and accCount == numArgs then\n                return func(unpack(accArgs)) -- 如果参数数量足够，则执行函数\n            else\n                local combinedArgs = { unpack(accArgs) }\n                for i = 1, #newArgs do\n                    table.insert(combinedArgs, newArgs[i])\n                end\n                if #combinedArgs >= numArgs then\n                    return func(unpack(combinedArgs)) -- 如果新参数使得数量足够，则执行函数\n                else\n                    return helper(combinedArgs, #combinedArgs)\n                end\n            end\n        end\n    end\n    return helper({}, 0)\nend\n"
_TWWE_VFS["mods/wand_editor/files/libs/gui.lua"] = "dofile_once(\"mods/wand_editor/files/libs/unsafe.lua\")\ndofile_once(\"mods/wand_editor/files/libs/fn.lua\")\ndofile_once(\"data/scripts/debug/keycodes.lua\")\ndofile_once(\"data/scripts/lib/utilities.lua\")\nlocal DefaultZDeep = -1250\n\nlocal this = {\n	private = {\n        CompToPickerBool = {}, --用于存储按钮点击状态\n		CompToPickerHoverBool = {},\n        PickerList = {},--用于存储谁和谁是同一组的\n		PickersCurrent = {},--用于存储谁是当前开启的\n		TileTick = {},   --计划刻\n		DestroyCallBack = {}, --销毁时的回调函数\n		destroy = false, --销毁状态\n        CompToID = {},   --组件转id\n        TextInputIDtoStr = {}, --输入框id转其文本\n        TextInputPos = {},     --输入框光标位置\n        TextInputDrawPosTimer = nil,\n        TextInputDrawPosHas = false;\n		FirstEventFn = {}, --用于内部优先级最高的回调函数\n		NextFrNoClick = false,\n		NextFrClick = 0,\n        Scale = nil,  --缩放参数\n		ZDeep = DefaultZDeep,--深度\n        IDMax = 0x7FFFFFFF, --下一个id分配的数字\n        SliderData = {},\n        SliderMax = {},\n		SliderMin = {},\n        ScrollData = {},\n		ScrollItemData = {},\n		ScrollAutoPos = {},\n        HScrollData = {},\n        HScrollSlider = {},--滑条数据，不重启游戏就是持久性的\n        HScrollItemData = {}, --元素数据，用于判断位置是否上下溢出\n		ConcatCache = {},\n		ResetAllCanMove = nil,\n		LastScreenWidth = -1,\n		LastScreenHeight = -1,\n	},\n	public = {\n		ScreenWidth = -1, --当前屏宽\n        ScreenHeight = -1, --当前屏高\n		MainTickFn = {},	--主要的刻事件，执行优先级更高\n        TickEventFn = {},  --刻事件\n		MiscEventFn = {},	--副要的刻事件，执行优先级最低\n		UserData = {},\n		gui = GuiCreate(), --gui userdata\n	}\n}\n\n---@class Gui\n---@field ScreenWidth integer\n---@field ScreenHeight integer\n---@field TickEventFn table\n---@field MainTickFn table\n---@field MiscEventFn table\n---@field UserData table\n---@field gui userdata\nlocal UI = {}\nsetmetatable(UI, this)\nthis.__index = this.public\n\n---将一个字符串拼接一下模组id的前缀然后返回\n---@param str string\n---@return string\nlocal function ConcatModID(str)\n	if this.private.ConcatCache[str] == nil then\n        local result = ModID .. str\n        return result\n    else\n		return this.private.ConcatCache[str]\n	end\nend\n\nfunction UI.GetZDeep()\n	return this.private.ZDeep\nend\n\nfunction UI.SetZDeep(z)\n	this.private.ZDeep = z\nend\n\nlocal tooltipID = 0\n\nlocal TooltipsCache = {}\n---组件悬浮窗提示,应当在一个组件后面使用\n---@param callback function\n---@param z integer?\n---@param xOffset integer?\n---@param yOffset integer?\n---@param NoYAutoMove boolean?\nfunction UI.tooltips(callback, z, xOffset, yOffset, NoYAutoMove, YMoreOffset)\n    local left_click, right_click, hover, x, y, width, height, draw_x, draw_y, draw_width, draw_height =\n        GuiGetPreviousWidgetInfo(this.public.gui)\n    if hover then\n        local gui = this.public.gui\n        if TooltipsCache[1] and TooltipsCache[2] then\n            if TooltipsCache[1] ~= math.floor(x) or TooltipsCache[2] ~= math.floor(y) then\n                if tooltipID < 31 then\n                    tooltipID = tooltipID + 1\n                else\n                    tooltipID = 0\n                end\n            end\n        end\n        TooltipsCache[1] = math.floor(x)\n        TooltipsCache[2] = math.floor(y)\n        xOffset = Default(xOffset, 0)\n        yOffset = Default(yOffset, 0)\n        YMoreOffset = Default(YMoreOffset, 0)\n        NoYAutoMove = Default(NoYAutoMove, false)\n        z = Default(z, DefaultZDeep)\n        if not NoYAutoMove and (draw_y > this.public.ScreenHeight * 0.5) then\n            yOffset = yOffset - height + YMoreOffset\n        end\n\n        GuiZSet(gui, z)\n\n        GuiIdPushString(gui, \"TooltipsAlpha\")\n        GuiAnimateBegin(gui)\n        GuiAnimateAlphaFadeIn(gui, tooltipID, 0.08, 0.1, false)\n        GuiAnimateScaleIn(gui, tooltipID, 0.08, false)\n        GuiIdPop(gui)\n\n        GuiLayoutBeginLayer(gui)\n        GuiLayoutBeginVertical(gui, (x + xOffset + width), (y + yOffset), true)\n        GuiBeginAutoBox(gui)\n        callback()\n        GuiZSetForNextWidget(gui, z + 1)\n        GuiEndAutoBoxNinePiece(gui)\n        GuiLayoutEnd(gui)\n        GuiLayoutEndLayer(gui)\n\n        GuiAnimateEnd(gui)\n    end\nend\n\nlocal BTooltipsNC = {}\n---组件悬浮窗提示,应当在一个组件后面使用\n---@param callback function\n---@param z integer?\n---@param xOffset integer?\n---@param yOffset integer?\nfunction UI.BetterTooltipsNoCenter(callback, z, xOffset, yOffset, leftMargin, rightMargin)\n	local left_click, right_click, hover, x, y, width, height, draw_x, draw_y, draw_width, draw_height =\n        GuiGetPreviousWidgetInfo(this.public.gui)\n    if hover then\n        local gui = this.public.gui\n		xOffset = Default(xOffset, 0)\n    	yOffset = Default(yOffset, 0)\n    	leftMargin = Default(leftMargin, 10)\n		rightMargin = Default(rightMargin, 10)\n        z = Default(z, DefaultZDeep)\n		\n        GuiAnimateBegin(gui)\n		GuiAnimateAlphaFadeIn(gui, UI.NewID(\"Alpha你肯定看不见我对吧\"), 0, 0, false)\n        GuiLayoutBeginLayer(gui)\n        GuiLayoutBeginVertical(gui, (x + xOffset + width), y + yOffset, true)\n		GuiBeginAutoBox(gui)\n        callback()\n		GuiZSetForNextWidget(gui, z + 1)\n		GuiEndAutoBoxNinePiece(gui)\n		GuiLayoutEnd(gui)\n		GuiLayoutEndLayer(gui)\n        GuiAnimateEnd(gui)\n		\n        local _,_,_,_,_,OffsetW,OffsetH = GuiGetPreviousWidgetInfo(gui)\n\n		if BTooltipsNC[1] and BTooltipsNC[2] then\n			if BTooltipsNC[1] ~= math.floor(x) or BTooltipsNC[2] ~= math.floor(y) then\n				if tooltipID < 31 then\n                    tooltipID = tooltipID + 1\n                else\n					tooltipID = 0\n				end\n			end\n		end\n\n		BTooltipsNC[1] = math.floor(x)\n		BTooltipsNC[2] = math.floor(y)\n		if x > this.public.ScreenWidth / 2 then\n        	xOffset = -(OffsetW - 10 + xOffset)\n        else\n			xOffset = xOffset + width\n		end\n\n        if y + yOffset - 10 < 0 then --上超出\n            yOffset = 0\n        	y = 10\n        end\n		if y + yOffset + OffsetH + 5 > this.public.ScreenHeight then\n			y = y + (this.public.ScreenHeight - (y + yOffset + OffsetH))\n		end\n\n        GuiZSet(gui, z)\n		\n        GuiAnimateBegin(gui)\n		GuiIdPushString(gui,\"BetterTooltipsNoCenterAlpha\")\n        GuiAnimateAlphaFadeIn(gui, tooltipID,0.08, 0.1, false)\n        GuiAnimateScaleIn(gui, tooltipID, 0.08, false)\n		GuiIdPop(gui)\n\n        GuiLayoutBeginLayer(gui)\n        GuiLayoutBeginVertical(gui, (x + xOffset), (y + yOffset), true)\n		GuiBeginAutoBox(gui)\n        callback()\n		GuiZSetForNextWidget(gui, z + 1)\n		GuiEndAutoBoxNinePiece(gui)\n		GuiLayoutEnd(gui)\n        GuiLayoutEndLayer(gui)\n\n		GuiAnimateEnd(gui)\n	end\nend\n\nOldGuiTooltip = GuiTooltip\n--覆盖掉原版的函数\nGuiTooltip = function(gui, text, description, xOffset)\n	xOffset = Default(xOffset, 0)\n	UI.BetterTooltipsNoCenter(function ()\n        GuiText(this.public.gui, 0, 0, text)\n		if description ~= nil and description ~= \"\" then\n			GuiText(this.public.gui, 0, 0, description)\n		end\n	end,-3000,10 + xOffset)\nend\n\nlocal BTooltipCache = {}\n---组件悬浮窗提示,应当在一个组件后面使用\n---@param callback function\n---@param z integer?\n---@param xOffset integer?\n---@param yOffset integer?\nfunction UI.BetterTooltips(callback, z, xOffset, yOffset, leftMargin, rightMargin)\n	local left_click, right_click, hover, x, y, width, height, draw_x, draw_y, draw_width, draw_height =\n        GuiGetPreviousWidgetInfo(this.public.gui)\n    if hover then\n		local gui = this.public.gui\n		xOffset = Default(xOffset, 0)\n    	yOffset = Default(yOffset, 0)\n    	leftMargin = Default(leftMargin, 10)\n		rightMargin = Default(rightMargin, 10)\n        z = Default(z, DefaultZDeep)\n\n        GuiAnimateBegin(gui)\n		GuiAnimateAlphaFadeIn(gui, UI.NewID(\"Alpha你肯定看不见我对吧\"), 0, 0, false)\n		GuiLayoutBeginLayer(gui)\n        GuiLayoutBeginVertical(gui, x + xOffset, y + yOffset, true)\n		GuiBeginAutoBox(gui)\n        callback()\n		GuiZSetForNextWidget(gui, z + 1)\n		GuiEndAutoBoxNinePiece(gui)\n		GuiLayoutEnd(gui)\n		GuiLayoutEndLayer(gui)\n        GuiAnimateEnd(gui)\n		\n        local _,_,_,_,_,OffsetW,OffsetH = GuiGetPreviousWidgetInfo(gui)\n		if BTooltipCache[1] and BTooltipCache[2] then\n			if BTooltipCache[1] ~= math.floor(x) or BTooltipCache[2] ~= math.floor(y) then\n				if tooltipID < 31 then\n                    tooltipID = tooltipID + 1\n                else\n					tooltipID = 0\n				end\n			end\n		end\n		BTooltipCache[1] = math.floor(x)\n		BTooltipCache[2] = math.floor(y)\n\n		xOffset = xOffset - OffsetW / 2 --居中\n		if y + yOffset > this.public.ScreenHeight * 0.5 then--自动上下切换\n			yOffset = -yOffset - OffsetH + height + 10\n		end\n        if y + yOffset - 10 < 0 then --上超出\n    	    yOffset = 0\n            y = 10\n        end\n		if y + yOffset + OffsetH + 5 > this.public.ScreenHeight then\n			y = y + (this.public.ScreenHeight - (y + yOffset + OffsetH))\n		end\n		if x + OffsetW /2 + 10 + rightMargin > this.public.ScreenWidth then--右超出\n			xOffset = -((x + OffsetW) - this.public.ScreenWidth + rightMargin)\n		end\n		if x + xOffset - leftMargin < 0 then--左超出\n			x = leftMargin + 5\n			xOffset = 0\n		end\n        GuiZSet(gui, z)\n\n        GuiAnimateBegin(gui)\n\n		GuiIdPushString(gui,\"BetterTooltipsAlpha\")\n        GuiAnimateAlphaFadeIn(gui, tooltipID,0.08, 0.1, false)\n		GuiAnimateScaleIn(gui, tooltipID,0.08, false)\n		GuiIdPop(gui)\n\n        GuiLayoutBeginLayer(gui)\n        GuiLayoutBeginVertical(gui, (x + xOffset), (y + yOffset), true)\n		GuiBeginAutoBox(gui)\n        callback()\n		GuiZSetForNextWidget(gui, z + 1)\n		GuiEndAutoBoxNinePiece(gui)\n		GuiLayoutEnd(gui)\n        GuiLayoutEndLayer(gui)\n\n		GuiAnimateEnd(gui)\n\n	end\nend\n\n---新建id或返回已有id\n---@param str string\n---@return integer\nfunction UI.NewID(str)\n	str = ConcatModID(str) --这个id很重要，最好不能重复\n	if this.private.CompToID[str] == nil then\n		local result = this.private.IDMax\n		this.private.CompToID[str] = result\n		this.private.IDMax = this.private.IDMax - 1\n		return result\n	else\n		return this.private.CompToID[str]\n	end\nend\n\n---返回已有id\n---@param str string\n---@return integer\nfunction UI.GetID(str)\n	return this.private.CompToID[str]\nend\n\n---简化版\n---@param id string\n---@param x number\n---@param y number\n---@param image string\n---@param AlwaysCallBack function|nil\n---@param HoverUseCallBack function|nil\n---@param ClickCallBack function|nil\n---@param AlwaysCBClick boolean?\n---@param noMove boolean?\n---@return boolean\nfunction UI.MoveImageButton(id, x, y, image, AlwaysCallBack, HoverUseCallBack, ClickCallBack, AlwaysCBClick, noMove)\n    local function imageButton(gui, numId, InputX, InputY)\n		return GuiImageButton(gui, numId, InputX, InputY, \"\", image)\n	end\n	return UI.CanMove(id, x, y, imageButton, AlwaysCallBack, HoverUseCallBack, ClickCallBack, image, AlwaysCBClick, nil, noMove)\nend\n\n---绘制一个跟随鼠标移动的图片\n---@param id string\n---@param x number\n---@param y number\n---@param image string\n---@param isClose boolean?\n---@param scale number?\n---@param ZDeep number?\n---@param ClickAble boolean|nil\n---@param AlwaysCallBack function?\n---@return boolean|nil\n---@return number|nil\n---@return number|nil\nfunction UI.OnMoveImage(id, x, y, image, isClose, scale, ZDeep, ClickAble, AlwaysCallBack)\n	isClose = Default(isClose, false)\n	scale = Default(scale, 1)\n    local CanMoveStr = ConcatModID(\"on_move_\" .. id)\n	if isClose then--这个参数是代表要关闭这个悬浮窗的\n        ModSettingSet(CanMoveStr, false) --提前设置\n		--暂停判断一段时间\n		this.private.NextFrNoClick = true\n		this.private.NextFrClick = 12\n		this.private.FirstEventFn[\"NextFrNoClick\"] = function()\n			if this.private.NextFrClick == 0 then\n				this.private.NextFrNoClick = false\n                this.private.FirstEventFn[\"NextFrNoClick\"] = nil\n				return\n			end\n			this.private.NextFrClick = this.private.NextFrClick - 1\n		end\n		return--所以退出\n	end\n	ModSettingSet(CanMoveStr, true) --提前设置\n\n    local function imageButton(gui, numId, InputX, InputY)\n		if ZDeep == nil then\n			this.private.ZDeep = this.private.ZDeep + 1\n			GuiZSetForNextWidget(this.public.gui, this.private.ZDeep)\n            GuiImage(gui, numId, InputX, InputY, image, 1, scale)\n        else\n            GuiZSetForNextWidget(this.public.gui, ZDeep)\n			GuiImage(gui, numId, InputX, InputY, image, 1, scale)\n		end\n	end\n	local ResultX = x\n	local ResultY = y\n    local function GetXY(InputResultX, InputResultY)\n        ResultX = InputResultX\n        ResultY = InputResultY\n        if AlwaysCallBack ~= nil then\n            AlwaysCallBack(ResultX, ResultY)\n        end\n    end\n	local inputClickAble\n	if type(ClickAble) == \"boolean\" then\n        inputClickAble = ClickAble\n		ClickAble = true\n	end\n	return UI.CanMove(id, x, y, imageButton, GetXY, nil, nil, image, true, true, nil, scale, ClickAble, inputClickAble), ResultX, ResultY\nend\n\nfunction UI.GetPickerStatus(id)\n    local newid = ConcatModID(id)\n	if this.private.CompToPickerBool[newid] == nil and ModSettingGet(newid) ~= nil then\n		this.private.CompToPickerBool[newid] = ModSettingGet(newid)\n	end\n	return this.private.CompToPickerBool[newid]\nend\n\nfunction UI.SetPickerEnable(id, enable)\n    local newid = ConcatModID(id)\n    this.private.CompToPickerBool[newid] = enable\n	if ModSettingGet(newid) ~= nil then\n		ModSettingSet(newid, this.private.CompToPickerBool[newid])\n	end\nend\n\nfunction UI.GetPickerHover(id)\n    local newid = ConcatModID(id)\n	local status = this.private.CompToPickerHoverBool[newid]\n    if status == nil then\n        return false\n    end\n	return status\nend\n\n---自带开关显示的按钮\n---@param id string\n---@param x number\n---@param y number\n---@param mx number\n---@param my number\n---@param Content string\n---@param image string\n---@param StatusCustomText table?\n---@param ClickCallBack function?\n---@param OpenImage string?\n---@param SemiTransparent boolean?\n---@param SaveModSetting boolean?\n---@param noMove boolean?\n---@param NoYAutoMove boolean?\n---@return boolean\nfunction UI.MoveImagePicker(id, x, y, mx, my, Content, image, StatusCustomText, ClickCallBack, OpenImage, SemiTransparent, SaveModSetting, noMove, NoYAutoMove)\n    local newid = ConcatModID(id)\n	NoYAutoMove = Default(NoYAutoMove, false)\n    if SaveModSetting and this.private.CompToPickerBool[newid] == nil then\n        if ModSettingGet(newid) == nil then\n            ModSettingSet(newid, false)\n        end\n        this.private.CompToPickerBool[newid] = ModSettingGet(newid) --通过模组设置初始化\n    elseif not SaveModSetting and ModSettingGet(newid) then\n		ModSettingRemove(newid)\n    end\n\n    if this.private.PickerList[newid] then\n		local key = this.private.PickerList[newid]\n        if this.private.PickersCurrent[key] == newid then\n            this.private.CompToPickerBool[newid] = true\n        else\n            this.private.CompToPickerBool[newid] = false\n        end\n		if SaveModSetting then\n            ModSettingSet(newid, this.private.CompToPickerBool[newid])\n        elseif not SaveModSetting and ModSettingGet(newid) ~= nil then--移除\n			ModSettingRemove(newid)\n		end\n	end\n    if this.private.CompToPickerBool[newid] == nil then\n        this.private.CompToPickerBool[newid] = false\n    end\n	if StatusCustomText then\n		if this.private.CompToPickerBool[newid] then\n			Content = GameTextGetTranslatedOrNot(StatusCustomText[1]) .. Content\n		else\n			Content = GameTextGetTranslatedOrNot(StatusCustomText[2]) .. Content\n		end\n    else\n		if this.private.CompToPickerBool[newid] then\n			Content = GameTextGetTranslatedOrNot(\"$wand_editor_picker_close\") .. Content\n		else\n			Content = GameTextGetTranslatedOrNot(\"$wand_editor_picker_open\") .. Content\n		end\n	end\n\n    local function Hover()\n        local _, _, hover = GuiGetPreviousWidgetInfo(this.public.gui)\n        this.private.CompToPickerHoverBool[newid] = hover\n        UI.BetterTooltipsNoCenter(function()\n            GuiText(this.public.gui, 0, 0, Content)\n            if id == \"MainButton\" then\n                GuiColorSetForNextWidget(this.public.gui, 0.5, 0.5, 0.5, 1.0)\n				if Cpp.PathExists(\"mods/wand_editor/cache/UpdateFlag\") and this.public.UserData[\"UpdateDataVer\"] then\n					GuiText(this.public.gui, 0, 2, ModVersion..\"->\"..this.public.UserData[\"UpdateDataVer\"]..GameTextGet(\"$wand_editor_auto_update_done\"))\n                else\n					GuiText(this.public.gui, 0, 2, ModVersion)\n				end\n                GuiLayoutAddVerticalSpacing(this.public.gui, 2)\n                GuiZSet(this.public.gui, this.private.ZDeep)\n            end\n            if not noMove then\n                local CTRL = InputIsKeyDown(Key_LCTRL) or InputIsKeyDown(Key_RCTRL)\n                GuiZSetForNextWidget(this.public.gui, DefaultZDeep - 114514)\n                if CTRL then\n                    GuiColorSetForNextWidget(this.public.gui, 0.5, 0.5, 0.5, 1.0)\n                    GuiText(this.public.gui, 0, 0, GameTextGetTranslatedOrNot(\"$wand_editor_picker_desc\"))\n                else\n                    GuiColorSetForNextWidget(this.public.gui, 0.5, 0.5, 0.5, 1.0)\n                    GuiText(this.public.gui, 0, 0, GameTextGetTranslatedOrNot(\"$wand_editor_picker_more\"))\n                end\n            end\n        end, DefaultZDeep - 100, mx, my)\n    end\n    local function Click(left_click, right_click, ix, iy)\n        if ClickCallBack ~= nil then\n            ClickCallBack(left_click, right_click, ix, iy, this.private.CompToPickerBool[newid]) --额外输入一个参数5，代表当前按钮启用状态\n        end\n        if left_click and this.private.PickerList[newid] then\n			local key = this.private.PickerList[newid]\n            if this.private.PickersCurrent[key] == newid then\n                this.private.PickersCurrent[key] = nil\n            else\n                this.private.PickersCurrent[key] = newid\n            end\n			GamePlaySound(\"data/audio/Desktop/ui.bank\", \"ui/button_click\", GameGetCameraPos())\n		elseif left_click then\n            this.private.CompToPickerBool[newid] = not this.private.CompToPickerBool[newid]\n			ModSettingSet(newid, this.private.CompToPickerBool[newid])\n			GamePlaySound(\"data/audio/Desktop/ui.bank\", \"ui/button_click\", GameGetCameraPos())\n        end\n    end\n    if OpenImage and this.private.CompToPickerBool[newid] then\n        image = OpenImage\n    end\n    if SemiTransparent and (not this.private.CompToPickerBool[newid]) then\n        GuiOptionsAddForNextWidget(this.public.gui, GUI_OPTION.DrawSemiTransparent)\n    end\n    GuiZSetForNextWidget(this.public.gui, this.private.ZDeep)\n	this.private.ZDeep = this.private.ZDeep + 1\n    local result = { UI.MoveImageButton(id, x, y, image, nil, Hover, Click, nil, noMove) }\n	return  unpack(result)\nend\n\n---输入一堆Picker id，代表他们启动状态是同一组的\n---@param ... string\nfunction UI.PickerEnableList(...)\n    local t = { ... }\n	for i=1,#t do--初始化处理\n		t[i] = ConcatModID(t[i])\n	end\n	for _,v in pairs(t)do\n        this.private.PickerList[v] = t\n	end\nend\n\nfunction UI.GetNoMoveBool()\n	return this.private.NextFrNoClick\nend\n\nfunction UI.ResetAllCanMove()\n	this.private.ResetAllCanMove = {}\nend\n\n---一个较为通用的让控件可以移动并设置的函数\n---@param id string\n---@param s_x number\n---@param s_y number\n---@param ButtonCallBack function\n---@param AlwaysCallBack function|nil\n---@param HoverUseCallBack function|nil\n---@param ClickCallBack function|nil\n---@param image string\n---@param AlwaysCBClick boolean? AlwaysCBClick = false\n---@param noSetting boolean? noSetting = false\n---@param noMove boolean? noMove = false\n---@param scale number? scale = 1\n---@return boolean 返回是否移动的状态\nfunction UI.CanMove(id, s_x, s_y, ButtonCallBack, AlwaysCallBack, HoverUseCallBack, ClickCallBack, image, AlwaysCBClick,\n					noSetting, noMove, scale, IsNoListenerClick, ClickAble)\n	local true_s_x = s_x\n	local true_s_y = s_y\n	local newid = ConcatModID(id)\n	noSetting = Default(noSetting, false)\n    AlwaysCBClick = Default(AlwaysCBClick, false)\n	noMove = Default(noMove, false)\n    scale = Default(scale, 1)\n	IsNoListenerClick = Default(IsNoListenerClick, false)\n	local numID = UI.NewID(id)\n	local Xname = newid .. \"x\"\n	local Yname = newid .. \"y\"\n    local CanMoveStr = ConcatModID(\"on_move_\" .. id)\n    if this.private.ResetAllCanMove ~= nil and this.private.ResetAllCanMove[newid] == nil then\n		ModSettingRemove(Xname) --恢复默认设置\n		ModSettingRemove(Yname)\n		this.private.ResetAllCanMove[newid] = true\n	end\n    if not ModSettingGet(CanMoveStr) or noMove then --非移动状态\n        if not noSetting and not noMove then\n            if ModSettingGet(Xname) ~= nil then  --没有设置就使用默认坐标\n                s_x = ModSettingGet(Xname)\n            end\n            if ModSettingGet(Yname) ~= nil then\n                s_y = ModSettingGet(Yname)\n            end\n        end\n\n        local hasMove = ModSettingGet(ModID .. \"hasButtonMove\")                    --其他按钮移动时，将无法触发按钮事件\n        local left_click, right_click = ButtonCallBack(this.public.gui, numID, s_x, s_y) --调用回调参数，用于新建想要的控件\n        local shift = InputIsKeyDown(Key_LSHIFT) or InputIsKeyDown(Key_RSHIFT)\n        if shift and left_click and (not this.private.NextFrNoClick) and not noMove then --两者同时按下\n            --开始移动\n            ModSettingSet(ModID .. \"hasButtonMove\", true)\n            ModSettingSet(CanMoveStr, true)\n        elseif (not hasMove) or AlwaysCBClick then --其他按钮没有移动的时候\n            if right_click and not noMove then --如果按下右键，且是非移动的\n                ModSettingRemove(Xname)        --恢复默认设置\n                ModSettingRemove(Yname)\n            end\n            if HoverUseCallBack ~= nil then\n                HoverUseCallBack()\n            end\n            if AlwaysCallBack ~= nil then\n                AlwaysCallBack(s_x, s_y)\n            end\n            if ClickCallBack ~= nil and ((not this.private.NextFrNoClick) or AlwaysCBClick) then\n                ClickCallBack(left_click, right_click, s_x, s_y)\n            elseif ClickCallBack ~= nil and this.private.NextFrNoClick then --绘制但不判断\n                ClickCallBack(false, false, s_x, s_y)\n            end\n        end\n        return ModSettingGet(CanMoveStr)\n    end\n	if not noSetting then\n		ModSettingSet(ModID .. \"hasButtonMove\", true)\n	end\n	--移动中\n    local mx, my = InputGetMousePosOnScreen()\n	mx = mx / this.private.Scale\n	my = my / this.private.Scale\n	if image then --如果有图片\n		local w, h = GuiGetImageDimensions(this.public.gui, image, scale)\n		mx = mx - w / 2\n		my = my - h / 2\n	end\n	local click = ClickAble--如果点击了\n	if not IsNoListenerClick then\n		click = InputIsMouseButtonDown(Mouse_left)\n	end\n	if click then\n		ModSettingSet(CanMoveStr, false)          --设置移动状态\n		ModSettingSet(ModID .. \"hasButtonMove\", false)\n		if not noSetting then\n			ModSettingSet(Xname, mx)\n			ModSettingSet(Yname, my)\n		end\n\n		--暂停判断一段时间\n		this.private.NextFrNoClick = true\n		this.private.NextFrClick = 10\n		this.private.FirstEventFn[\"NextFrNoClick\"] = function()\n			if this.private.NextFrClick == 0 then\n				this.private.NextFrNoClick = false\n                this.private.FirstEventFn[\"NextFrNoClick\"] = nil\n				return\n			end\n			this.private.NextFrClick = this.private.NextFrClick - 1\n		end\n	end\n\n	ButtonCallBack(this.public.gui, numID, mx, my)\n	if AlwaysCallBack ~= nil then\n		AlwaysCallBack(mx, my)\n	end\n	return ModSettingGet(CanMoveStr)\nend\n\nfunction UI.ScrollContainer(id, x, y, w, h, margin_x, margin_y, scale)\n	margin_x = Default(margin_x, 2)\n    margin_y = Default(margin_y, 2)\n	scale = Default(scale, 1)\n	local newid = ConcatModID(id)\n	if this.private.ScrollData[newid] == nil then--判断是否有数据\n        this.private.ScrollData[newid] = { id = id, x = x, y = y, w = w, h = h, margin_x = margin_x, margin_y = margin_y,scale = scale }--初始化数据\n        this.private.ScrollData[newid].Item = {}\n        this.private.ScrollData[newid].Any = {}\n		this.private.ScrollData[newid].ItemK = 1\n		this.private.ScrollData[newid].AnyK = 1\n	end\nend\n\n---设置参数\n---@param id string\n---@param x number|nil?\n---@param y number|nil?\n---@param w number|nil?\n---@param h number|nil?\n---@param margin_x number|nil?\n---@param margin_y number|nil?\nfunction UI.SetScrollContainer(id, x, y, w, h, margin_x, margin_y)\n	local newid = ConcatModID(id)\n	if this.private.ScrollData[newid] then--判断是否有数据\n        if x then\n            this.private.ScrollData[newid].x = x\n        end\n        if y then\n            this.private.ScrollData[newid].y = y\n        end\n        if w then\n            this.private.ScrollData[newid].w = w\n        end\n        if h then\n            this.private.ScrollData[newid].h = h\n        end\n        if margin_x then\n            this.private.ScrollData[newid].margin_x = margin_x\n        end\n		if margin_y then\n			this.private.ScrollData[newid].margin_y = margin_y\n		end\n	end\nend\n\n---为一个指定id的Scroll控件添加任意位置的项目\n---@param id string\n---@param callback function\nfunction UI.AddAnywhereItem(id, callback)\n	local newid = ConcatModID(id)\n    if this.private.ScrollData[newid] then --判断是否有数据\n		this.private.ScrollData[newid].Any[this.private.ScrollData[newid].AnyK] = callback\n		this.private.ScrollData[newid].AnyK = this.private.ScrollData[newid].AnyK + 1\n	end\nend\n\n---为一个指定id的Scroll控件添加图片项目\n---@param id string\n---@param image string\n---@param callback function\nfunction UI.AddScrollImageItem(id, image, callback)\n	local newid = ConcatModID(id)\n    if this.private.ScrollData[newid] then --判断是否有数据\n		this.private.ScrollData[newid].Item[this.private.ScrollData[newid].ItemK] = {CB = callback,image = image}\n		this.private.ScrollData[newid].ItemK = this.private.ScrollData[newid].ItemK + 1\n	end\nend\n\n---为一个指定id的Scroll控件添加文本项目\n---@param id string\n---@param text string\n---@param callback? function|nil\nfunction UI.AddScrollTextItem(id, text, callback)\n	local newid = ConcatModID(id)\n    if this.private.ScrollData[newid] then --判断是否有数据\n		this.private.ScrollData[newid].Item[this.private.ScrollData[newid].ItemK] = {CB = callback,text = text}\n		this.private.ScrollData[newid].ItemK = this.private.ScrollData[newid].ItemK + 1\n	end\nend\n\n---获得Item表\n---@param id string\n---@return table|nil\nfunction UI.GetScrollItemList(id)\n	local newid = ConcatModID(id)\n    if this.private.ScrollData[newid] then --判断是否有数据\n        return this.private.ScrollData[newid].Item\n    end\nend\n\n---@param id string\n---@return number|nil\nfunction UI.GetScrollWidth(id)\n    local newid = ConcatModID(id)\n	if this.private.ScrollAutoPos[newid] then\n		return this.private.ScrollAutoPos[newid].w\n	end\n    if this.private.ScrollData[newid] then --判断是否有数据\n        return this.private.ScrollData[newid].w\n    end\nend\n\n---@param id string\n---@return number|nil\nfunction UI.GetScrollHeight(id)\n    local newid = ConcatModID(id)\n	if this.private.ScrollAutoPos[newid] then\n		return this.private.ScrollAutoPos[newid].h\n	end\n    if this.private.ScrollData[newid] then --判断是否有数据\n        return this.private.ScrollData[newid].h\n    end\nend\n\n---@param id string\n---@return number|nil\nfunction UI.GetScrollX(id)\n	local newid = ConcatModID(id)\n    if this.private.ScrollData[newid] then --判断是否有数据\n        return this.private.ScrollData[newid].x\n    end\nend\n\n---@param id string\n---@return number|nil\nfunction UI.GetScrollY(id)\n	local newid = ConcatModID(id)\n    if this.private.ScrollData[newid] then --判断是否有数据\n        return this.private.ScrollData[newid].y\n    end\nend\n\n---@param id string\n---@return number|nil\nfunction UI.GetScrollMX(id)\n    local newid = ConcatModID(id)\n    if this.private.ScrollData[newid] then --判断是否有数据\n        return this.private.ScrollData[newid].margin_x\n    end\nend\n\n---@param id string\n---@return number|nil\nfunction UI.GetScrollMY(id)\n	local newid = ConcatModID(id)\n    if this.private.ScrollData[newid] then --判断是否有数据\n        return this.private.ScrollData[newid].margin_y\n    end\nend\n\nfunction UI.ScrollCB(id, f)\n	local newid = ConcatModID(id)\n	this.private.ScrollData[newid].f = f\nend\n\n---根据指定id开始绘制Scroll控件\n---@param id string\n---@param IsBlock boolean?\n---@param IsAutoBox boolean?\nfunction UI.DrawScrollContainer(id, IsBlock, IsAutoBox)\n    local newid = ConcatModID(id)\n	IsBlock = Default(IsBlock, true)\n    if this.private.ScrollData[newid] then --如果有数据\n        local x = this.private.ScrollData[newid].x\n		local y = this.private.ScrollData[newid].y\n        local w = this.private.ScrollData[newid].w\n		local h = this.private.ScrollData[newid].h\n        local function IsHover(posx, posy)\n            if posx > x and posx <= x + w + 5 + this.private.ScrollData[newid].margin_x and posy > y and posy <= y + h + this.private.ScrollData[newid].margin_y then\n                return true\n            end\n            return false\n        end\n\n		local mx, my = InputGetMousePosOnScreen()\n		mx = mx / this.private.Scale\n        my = my / this.private.Scale\n        local hover = IsHover(mx, my)\n        if hover and IsBlock then\n			GuiAnimateBegin(this.public.gui)\n            GuiAnimateAlphaFadeIn(this.public.gui, UI.NewID(\"Alpha你肯定看不见我对吧的另一个动画\"), 0, 0, false)\n\n			GuiLayoutBeginLayer(this.public.gui)\n            GuiZSetForNextWidget(this.public.gui, this.private.ZDeep - 1)\n			\n			GuiOptionsAddForNextWidget(this.public.gui, GUI_OPTION.AlwaysClickable)\n            local autow, autoh\n			if this.private.ScrollAutoPos[newid] then--好像不生效，不管了反正也用不到，先不修了\n                autow = this.private.ScrollAutoPos[newid].w\n                autoh = this.private.ScrollAutoPos[newid].h\n            else\n				autow = this.private.ScrollData[newid].w\n				autoh = this.private.ScrollData[newid].h\n			end\n            GuiBeginScrollContainer(this.public.gui, UI.NewID(\"你看不见的框\"), this.private.ScrollData[newid].x,\n            this.private.ScrollData[newid].y, autow, autoh, true, this.private.ScrollData[newid].margin_x,\n                this.private.ScrollData[newid].margin_y)\n			\n            GuiEndScrollContainer(this.public.gui)\n\n			GuiLayoutEndLayer(this.public.gui)\n			GuiAnimateEnd(this.public.gui)\n        end\n		\n        GuiLayoutBeginLayer(this.public.gui) --先开启这个\n		local thisDrawIsOffsetInit = false\n        if IsAutoBox then\n            if this.private.ScrollAutoPos[newid] == nil or this.private.ScrollAutoPos[newid].LastScale ~= this.private.Scale then\n                this.private.ScrollAutoPos[newid] = {}\n                this.private.ScrollAutoPos[newid].LastScale = this.private.Scale\n                thisDrawIsOffsetInit = true\n				GuiAnimateBegin(this.public.gui)\n				GuiAnimateAlphaFadeIn(this.public.gui, UI.NewID(\"Alpha你肯定看不见我对吧的另一个动画之自动偏移需要计算因而被隐藏了\"), 0, 0, false)\n            end\n            local offsetX = this.private.ScrollAutoPos[newid].x\n            local offsetY = this.private.ScrollAutoPos[newid].y\n			if offsetX and offsetY then\n				offsetX = offsetX - this.private.ScrollData[newid].x\n				offsetY = offsetY - this.private.ScrollData[newid].y\n            else\n                offsetX = 0\n				offsetY = 0\n			end\n			GuiLayoutBeginVertical(this.public.gui, this.private.ScrollData[newid].x - offsetX, this.private.ScrollData[newid].y - offsetY, true)\n			GuiBeginAutoBox(this.public.gui)\n        else\n			GuiZSetForNextWidget(this.public.gui, this.private.ZDeep)\n			GuiBeginScrollContainer(this.public.gui, UI.NewID(id), this.private.ScrollData[newid].x,\n            this.private.ScrollData[newid].y, this.private.ScrollData[newid].w, this.private.ScrollData[newid].h,\n			true,this.private.ScrollData[newid].margin_x, this.private.ScrollData[newid].margin_y)\n		end\n\n		for _,v in pairs(this.private.ScrollData[newid].Any)do\n			v()\n		end\n\n        GuiLayoutBeginVertical(this.public.gui, 0, 0, true) --垂直布局\n		if this.private.ScrollData[newid].f then\n			this.private.ScrollData[newid].f()\n		end\n        local ElemWidth = 0\n        local RowCount = 0\n		GuiLayoutBeginHorizontal(this.public.gui, 0 , 0, true)--横向自动分布 \n        for _, v in pairs(this.private.ScrollData[newid].Item) do\n			RowCount = RowCount + 1\n            if v.text then --如果是文本\n                local width = GuiGetTextDimensions(this.public.gui, v.text, this.private.ScrollData[newid].scale)\n                ElemWidth = ElemWidth + width\n            else --不是文本就是图片\n                local width = GuiGetImageDimensions(this.public.gui, v.image, this.private.ScrollData[newid].scale)\n                ElemWidth = ElemWidth + width\n            end\n			if RowCount == 1 or ElemWidth < this.private.ScrollData[newid].w then--如果是行的第一个元素，或者总元素宽小于控件宽的时候\n				if v.CB then\n					v.CB()\n				end\n            else --重置\n                RowCount = 1\n				if v.CB then\n					v.CB()\n				end\n                ElemWidth = 0\n                GuiLayoutEnd(this.public.gui)--结束这次绘制\n				GuiLayoutBeginHorizontal(this.public.gui, 0 , 0, true)--横向自动分布。开始下次绘制\n			end\n		end\n        GuiLayoutEnd(this.public.gui)\n		\n        GuiLayoutEnd(this.public.gui)\n		if IsAutoBox then--移位问题，没解决\n			GuiZSetForNextWidget(this.public.gui, this.private.ZDeep + 100)\n            GuiEndAutoBoxNinePiece(this.public.gui, this.private.ScrollData[newid].margin_x,this.private.ScrollData[newid].w,this.private.ScrollData[newid].h)\n            if this.private.ScrollAutoPos[newid].x == nil and this.private.ScrollAutoPos[newid].y == nil then\n                local _, _, _, autox, autoy, width, height = GuiGetPreviousWidgetInfo(this.public.gui)\n                this.private.ScrollAutoPos[newid].x = autox\n                this.private.ScrollAutoPos[newid].y = autoy\n                this.private.ScrollAutoPos[newid].h = height\n                this.private.ScrollAutoPos[newid].w = width\n            end\n            GuiLayoutEnd(this.public.gui)\n			if thisDrawIsOffsetInit then\n				GuiAnimateEnd(this.public.gui)\n			end\n		else\n			GuiEndScrollContainer(this.public.gui)\n		end\n		GuiLayoutEndLayer(this.public.gui)\n	end\nend\n\n-- 分隔符集合\nlocal separators = { [' '] = true, ['.'] = true, ['-'] = true , ['_'] = true}\n\n-- 判断字符是否为分隔符\nlocal function is_separator(char)\n    return separators[char] ~= nil\nend\n\n--缝缝补补的逻辑乱的我都不想看\nlocal function jump_to_next_position(text, cursor_pos)\n    local length = Cpp.UTF8StringSize(text)\n    local pos = cursor_pos\n	--判断是否需要跳过\n	if is_separator(Cpp.UTF8StringSub(text, pos+1, pos+1)) or is_separator(Cpp.UTF8StringSub(text, pos, pos)) then\n		pos = pos + 1\n	end\n    --如果有就跳过当前可能的分隔符，然后就是位置\n	local JumpFlag = false\n    while pos <= length and is_separator(Cpp.UTF8StringSub(text, pos, pos)) do\n        pos = pos + 1\n        JumpFlag = true\n    end\n	if JumpFlag then\n		return pos - 1\n	end\n    --找到下一个分隔符，返回前一个位置\n    while pos <= length do\n        local char = Cpp.UTF8StringSub(text, pos, pos)\n        if is_separator(char) then\n            return pos - 1\n        end\n        pos = pos + 1\n    end\n\n    --如果没有更多位置，返回文本结尾\n    return length\nend\n\nlocal function jump_to_previous_position(text, cursor_pos)\n    local pos = cursor_pos\n    --判断是否需要跳过\n	local JumpSeparator = false\n	if is_separator(Cpp.UTF8StringSub(text, pos, pos)) then\n		pos = pos - 1\n		JumpSeparator = true\n	end\n    --如果有就跳过当前可能的分隔符，然后就是位置\n	local JumpFlag = false\n    while pos > 1 and is_separator(Cpp.UTF8StringSub(text, pos, pos)) do\n        pos = pos - 1\n		JumpFlag = true\n    end\n    if JumpFlag then\n        return pos\n	elseif JumpSeparator then\n		return pos\n    end\n    --找到上一个分隔符，返回下一个位置\n    while pos > 0 do\n        local char = Cpp.UTF8StringSub(text, pos, pos)\n        if is_separator(char) then\n            return pos\n        end\n        pos = pos - 1\n    end\n\n    --如果到达文本开头，返回位置0\n    return 0\nend\n\n---文本输入框，会保证文本不会超出限制\n---@param id string\n---@param x number\n---@param y number\n---@param w number\n---@param l number\n---@param str string? str=\"\"\n---@param allowed_characters string?\n---@return string\nfunction UI.TextInput(id, x, y, w, l, str, allowed_characters)\n    local Remove1Char = function(InputStr, pos)\n        local utf8Size = Cpp.UTF8StringSize(InputStr)\n		if pos > utf8Size or pos < 1 then--检查越界\n			return InputStr\n		end\n        local FirstStr = \"\"\n        if pos - 1 >= 1 and utf8Size > pos - 1 then\n            FirstStr = Cpp.UTF8StringSub(InputStr, 1, pos - 1)\n        end\n		local SecondStr = \"\"\n        if pos + 1 <= utf8Size and pos + 1 > 0 then\n            SecondStr = Cpp.UTF8StringSub(InputStr, pos + 1, utf8Size)\n        end\n        if FirstStr == \"\" and SecondStr == \"\" and (utf8Size ~= 1 and pos ~= 1) then\n            return InputStr\n        elseif utf8Size == 1 and pos == 1 then --单独删除字符的特判\n            return \"\"\n        end\n        return Cpp.ConcatStr(FirstStr, SecondStr)\n    end\n    local Add1Char = function(InputStr, pos, char)\n        local utf8Size = Cpp.UTF8StringSize(InputStr)\n        local FirstStr = \"\"\n        if pos > 0 and utf8Size >= pos then\n            FirstStr = Cpp.UTF8StringSub(InputStr, 1, pos)\n        end\n        local SecondStr = \"\"\n        if pos + 1 <= utf8Size and pos + 1 > 0 then\n            SecondStr = Cpp.UTF8StringSub(InputStr, pos + 1, Cpp.UTF8StringSize(InputStr))\n        end\n        return Cpp.ConcatStr(FirstStr, char, SecondStr)\n    end\n\n    str = Default(str, \"\")\n	allowed_characters = Default(allowed_characters, \"\")\n    local newid = ConcatModID(id)\n    if this.private.TextInputIDtoStr[newid] == nil then--初始化中\n        this.private.TextInputIDtoStr[newid] = { s_str = str, str = str }\n    end\n	if this.private.TextInputPos[newid] == nil then\n        this.private.TextInputPos[newid] = Cpp.UTF8StringSize(this.private.TextInputIDtoStr[newid].str)\n		this.private.TextInputDrawPosTimer = 60--顺带重置这个\n    elseif this.private.TextInputPos[newid] < 0 then--这个也是防止越界的\n        this.private.TextInputPos[newid] = 0\n	end\n	local newStr = this.private.TextInputIDtoStr[newid].str\n\n	GuiOptionsAddForNextWidget(this.public.gui,GUI_OPTION.NonInteractive)\n    GuiTextInput(this.public.gui, UI.NewID(id), x, y, this.private.TextInputIDtoStr[newid].str, w, l, allowed_characters)\n\n    local _, _, TXHover, TIx, TIy, TXWidth, height = GuiGetPreviousWidgetInfo(this.public.gui)	--绘制光标\n    this.private.TextInputDrawPosHas = this.private.TextInputDrawPosHas or TXHover\n    if this.private.TextInputIDtoStr[newid].SetStr ~= nil then--设置文本，并检查超出部分\n        local SetStr = this.private.TextInputIDtoStr[newid].SetStr\n        local strWidth = GuiGetTextDimensions(this.public.gui, SetStr, 1)\n        local Size = Cpp.UTF8StringSize(SetStr)\n        local LastChar = \"\"\n        if Size > 1 then\n            LastChar = Cpp.UTF8StringSub(SetStr, Size - 1, Size)\n        end\n        local LastCharWidth = GuiGetTextDimensions(this.public.gui, LastChar, 1)\n        while strWidth + 4 > TXWidth - LastCharWidth do --自动裁剪超出文本框的文本\n            SetStr = Cpp.UTF8StringSub(SetStr, 1, Cpp.UTF8StringSize(SetStr) - 1)\n            Size = Cpp.UTF8StringSize(SetStr)\n            LastChar = \"\"\n            if Size > 1 then\n                LastChar = Cpp.UTF8StringSub(SetStr, Size - 1, Size)\n            end\n            LastCharWidth = GuiGetTextDimensions(this.public.gui, LastChar, 1)\n            strWidth = GuiGetTextDimensions(this.public.gui, SetStr, 1)\n        end\n        newStr = SetStr\n        this.private.TextInputIDtoStr[newid].SetStr = nil\n		this.private.TextInputPos[newid] = Cpp.UTF8StringSize(newStr)--设置光标位置\n    end\n	\n	--[[\n    local HasMoreSpaceWidth = GuiGetTextDimensions(this.public.gui, \"| |\", 1)--因为有时候空格不会渲染长度，所以用一种奇特但有效的方式兼容\n    local MoreCharWidth = GuiGetTextDimensions(this.public.gui, \"|\", 1)\n    SpaceWidth = HasMoreSpaceWidth - MoreCharWidth * 2\n	]]\n    if TXHover then\n        if this.private.TextInputDrawPosTimer == nil or this.private.TextInputDrawPosTimer <= 0 then\n            this.private.TextInputDrawPosTimer = 60\n        elseif this.private.TextInputDrawPosTimer > 0 then\n            this.private.TextInputDrawPosTimer = this.private.TextInputDrawPosTimer - 1\n        end\n        if this.private.TextInputPos[newid] > Cpp.UTF8StringSize(newStr) then --防止越界\n            this.private.TextInputPos[newid] = Cpp.UTF8StringSize(newStr)\n        end\n		local CalcStr = Cpp.UTF8StringSub(newStr,1,this.private.TextInputPos[newid])\n		local StrWidth = GuiGetTextDimensions(this.public.gui, CalcStr, 1)\n\n        if this.private.TextInputDrawPosTimer > 30 then--可以使得悬浮在上面的时候立刻绘制一段时间光标作为提示\n\n            --local GreyWidth = GuiGetImageDimensions(this.public.gui, \"mods/wand_editor/files/gui/images/grey_1px.png\", 1)\n            local MoreHeight = height - math.floor(height)\n            local MaxI = 1\n            for i = 1, math.floor(height) - 4 do\n                MaxI = i\n                GuiZSetForNextWidget(this.public.gui, UI.GetZDeep() - 100)\n                GuiOptionsAddForNextWidget(this.public.gui, GUI_OPTION.Layout_NoLayouting)\n                GuiOptionsAddForNextWidget(this.public.gui, GUI_OPTION.NonInteractive)\n                GuiImage(UI.gui, UI.NewID(\"NoDarwGreyPixel\" .. tostring(i)), TIx + StrWidth + 2, TIy + i + 1, \"mods/wand_editor/files/gui/images/grey_1px.png\", 1, 1)\n			end\n            if MoreHeight > 0 then--高度不为整数的时候补齐提示光标\n                MoreHeight = MoreHeight / 2\n                GuiZSetForNextWidget(this.public.gui, UI.GetZDeep() - 100)\n                GuiOptionsAddForNextWidget(this.public.gui, GUI_OPTION.Layout_NoLayouting)\n                GuiOptionsAddForNextWidget(this.public.gui, GUI_OPTION.NonInteractive)\n                GuiImage(UI.gui, UI.NewID(\"NoDarwGreyPixelLow\"), TIx + StrWidth + 2, TIy + 2 - MoreHeight, \"mods/wand_editor/files/gui/images/grey_1px.png\", 1, 1)\n                \n                GuiZSetForNextWidget(this.public.gui, UI.GetZDeep() - 100)\n                GuiOptionsAddForNextWidget(this.public.gui, GUI_OPTION.Layout_NoLayouting)\n                GuiOptionsAddForNextWidget(this.public.gui, GUI_OPTION.NonInteractive)\n                GuiImage(UI.gui, UI.NewID(\"NoDarwGreyPixelHigh\"), TIx + StrWidth + 2, TIy + MaxI + 2 - MoreHeight, \"mods/wand_editor/files/gui/images/grey_1px.png\", 1, 1)\n            end\n        end\n    end\n\n	GuiAnimateBegin(this.public.gui)\n    GuiAnimateAlphaFadeIn(this.public.gui, UI.NewID(\"Alpha你肯定看不见我对吧的另一个动画\" .. id), 0, 0, false)\n	GuiOptionsAddForNextWidget(this.public.gui,GUI_OPTION.Layout_NoLayouting)\n    local newChar = GuiTextInput(this.public.gui, UI.NewID(id .. \"NoDarwTextInput\"), TIx,TIy, \"\", w, l, allowed_characters)\n    GuiAnimateEnd(this.public.gui)\n\n    if newChar ~= \"\" and (Cpp.UTF8StringSize(newStr) + Cpp.UTF8StringSize(newChar) < l + 1 or l == -1) then--新增字符操作，也要重置光标显示\n        local SrcNewStr = newStr\n        newStr = Add1Char(newStr, this.private.TextInputPos[newid], newChar)\n        local strWidth = GuiGetTextDimensions(this.public.gui, newStr, 1)\n        local newCharWidth = GuiGetTextDimensions(this.public.gui, newChar, 1)\n        if strWidth + 4 < TXWidth - newCharWidth then--自动判断是否超出文本框\n            this.private.TextInputPos[newid] = this.private.TextInputPos[newid] + Cpp.UTF8StringSize(newChar)\n			this.private.TextInputDrawPosTimer = 60\n        else\n            newStr = SrcNewStr\n        end\n    end\n\n    if this.private.TextInputIDtoStr[newid].str ~= newStr and this.private.TextInputIDtoStr[newid].DelFr ~= 0 then --如果新文本和旧文本不匹配，那么就重新设置\n        this.private.TextInputIDtoStr[newid].str = newStr\n    end\n    local _, _, hover = GuiGetPreviousWidgetInfo(this.public.gui)--获得当前控件是否悬浮\n    if hover then\n        if this.private.TextInputIDtoStr[newid].ActiveItem == nil then\n            this.private.TextInputIDtoStr[newid].ActiveItem = GetActiveItem()\n        end\n        --屏蔽按键输入\n        BlockAllInput()\n        if this.private.TextInputIDtoStr[newid].ActiveItem then --屏蔽切换物品\n            UI.OnceCallOnExecute(function()\n                SetActiveItem(this.private.TextInputIDtoStr[newid].ActiveItem)\n            end)\n        end\n        if this.private.TextInputIDtoStr[newid].DelFr == nil then --如果在悬浮，就分配一个删除用的帧检测时间\n            this.private.TextInputIDtoStr[newid].DelFr = 30\n        else\n            if InputIsKeyDown(Key_BACKSPACE) or InputIsKeyDown(Key_DELETE) then --如果按了退格键\n                if this.private.TextInputIDtoStr[newid].DelFr == 30 then        --移除时也要重置光标显示\n                    local input = this.private.TextInputIDtoStr[newid].str\n                    if InputIsKeyDown(Key_DELETE) then\n                        this.private.TextInputIDtoStr[newid].str = Remove1Char(input,\n                            this.private.TextInputPos[newid] + 1)\n                    else\n                        this.private.TextInputIDtoStr[newid].str = Remove1Char(input, this.private.TextInputPos[newid])\n                        this.private.TextInputPos[newid] = this.private.TextInputPos[newid] - 1\n                    end\n                    this.private.TextInputDrawPosTimer = 60\n                end\n                if this.private.TextInputIDtoStr[newid].DelFr ~= 0 then\n                    this.private.TextInputIDtoStr[newid].DelFr = this.private.TextInputIDtoStr[newid].DelFr - 1\n                else --如果到了0\n                    local input = this.private.TextInputIDtoStr[newid].str\n                    if InputIsKeyDown(Key_DELETE) then\n                        this.private.TextInputIDtoStr[newid].str = Remove1Char(input,\n                            this.private.TextInputPos[newid] + 1)\n                    else\n                        this.private.TextInputIDtoStr[newid].str = Remove1Char(input, this.private.TextInputPos[newid])\n                        this.private.TextInputPos[newid] = this.private.TextInputPos[newid] - 1\n                    end\n                    this.private.TextInputDrawPosTimer = 60\n                end\n            else\n                this.private.TextInputIDtoStr[newid].DelFr = 30 --如果不按退格键就重置时间\n            end\n        end\n    elseif this.private.TextInputIDtoStr[newid].DelFr then --如果未悬浮就设为空\n        RestoreInput()\n        this.private.TextInputIDtoStr[newid].ActiveItem = nil\n        this.private.TextInputIDtoStr[newid].DelFr = nil\n    end\n	\n	local MovePos = function ()\n        if InputIsKeyDown(Key_LCTRL) or InputIsKeyDown(Key_RCTRL) then\n			local input = this.private.TextInputIDtoStr[newid].str\n			if InputIsKeyDown(Key_LEFT) then\n				this.private.TextInputPos[newid] = jump_to_previous_position(input, this.private.TextInputPos[newid])\n			else\n				this.private.TextInputPos[newid] = jump_to_next_position(input, this.private.TextInputPos[newid])\n			end\n		else\n			if InputIsKeyDown(Key_LEFT) then\n				this.private.TextInputPos[newid] = this.private.TextInputPos[newid] - 1\n			else\n				this.private.TextInputPos[newid] = this.private.TextInputPos[newid] + 1\n			end\n		end\n	end\n\n	if hover then\n        if this.private.TextInputIDtoStr[newid].PosFr == nil then --如果在悬浮，就分配一个移动光标用的帧检测时间\n            this.private.TextInputIDtoStr[newid].PosFr = 30\n        end\n		if InputIsKeyDown(Key_LEFT) or InputIsKeyDown(Key_RIGHT) then --如果按了方向键\n			if this.private.TextInputIDtoStr[newid].PosFr == 30 then        --移动时也要重置光标显示\n				MovePos()\n				this.private.TextInputDrawPosTimer = 60\n			end\n			if this.private.TextInputIDtoStr[newid].PosFr ~= 0 then\n				this.private.TextInputIDtoStr[newid].PosFr = this.private.TextInputIDtoStr[newid].PosFr - 1\n			else --如果到了0\n				this.private.TextInputIDtoStr[newid].PosFr = 2--间隔两帧\n				MovePos()\n				this.private.TextInputDrawPosTimer = 60\n			end\n		else--如果不按就重置时间\n			this.private.TextInputIDtoStr[newid].PosFr = 30\n		end\n    elseif this.private.TextInputIDtoStr[newid].PosFr then--如果未悬浮就设为空\n		this.private.TextInputIDtoStr[newid].PosFr = nil\n	end\n    --点击文本切换光标位置\n    if hover and InputIsMouseButtonJustDown(Mouse_left) and this.private.TextInputIDtoStr[newid].str ~= \"\" then --如果点击了且是悬浮状态\n        local mx, my = InputGetMousePosOnScreen()\n        mx = mx / this.private.Scale\n        my = my / this.private.Scale\n        local input = this.private.TextInputIDtoStr[newid].str\n        local CharTable = Cpp.UTF8StringChars(input)\n        local ConcatChars = \"\"\n        local SwitchPos = 0\n        local StrWidth\n        for i = 1, #CharTable do\n            ConcatChars = ConcatChars .. CharTable[i]                                   --拼接用于计算字符串长度\n            StrWidth = GuiGetTextDimensions(this.public.gui, ConcatChars, 1) + 2        --2是偏移量\n            if mx > TIx and mx < TIx + StrWidth then --判断是否在范围内，都悬浮状态了，不用判断y轴\n                SwitchPos = i\n                --print(\"Result:\",i)\n                break --及时退出\n            end\n        end\n        if SwitchPos > 0 then --有结果\n            local CharLen = GuiGetTextDimensions(this.public.gui, CharTable[SwitchPos], 1)\n            if mx < TIx + StrWidth - CharLen + CharLen / 2 then\n                this.private.TextInputPos[newid] = SwitchPos - 1\n            else\n                this.private.TextInputPos[newid] = SwitchPos\n            end\n            this.private.TextInputDrawPosTimer = 60 --切换位置时重置光标绘制\n        elseif mx < TXWidth + TIx and mx > TIx then\n            this.private.TextInputPos[newid] = nil --重置到最前面\n            this.private.TextInputDrawPosTimer = 60\n        end\n    end\n	if hover and InputIsKeyDown(Key_HOME) or InputIsKeyDown(Key_END) then--home和end键的实现\n        if InputIsKeyDown(Key_HOME) then\n            this.private.TextInputPos[newid] = 0\n        else\n            this.private.TextInputPos[newid] = nil --重置到最前面\n        end\n		this.private.TextInputDrawPosTimer = 60\n	end\n	return this.private.TextInputIDtoStr[newid].str\nend\n\n---获取文本\n---@param id string\n---@return string|nil\nfunction UI.GetInputText(id)\n    local newid = ConcatModID(id)\n	if this.private.TextInputIDtoStr[newid] ~= nil then\n        return this.private.TextInputIDtoStr[newid].str\n    end\nend\n\n---设置文本\n---@param id string\n---@param str string\nfunction UI.SetInputText(id, str)\n    local newid = ConcatModID(id)\n    if this.private.TextInputIDtoStr[newid] ~= nil then\n		this.private.TextInputIDtoStr[newid].SetStr = str\n    end\nend\n\n---恢复文本\n---@param id string\nfunction UI.TextInputRestore(id)\n	local newid = ConcatModID(id)\n    if this.private.TextInputIDtoStr[newid] ~= nil then\n		this.private.TextInputPos[newid] = nil--重置光标位置\n        this.private.TextInputIDtoStr[newid].str = this.private.TextInputIDtoStr[newid].s_str\n    end\nend\n\n---获得checkbox状态\n---@param id string\n---@return boolean\nfunction UI.GetCheckboxEnable(id)\n    local newid = ConcatModID(id)\n    local CheckboxEnableKey = newid .. \"_enabled\"\n	return ModSettingGet(CheckboxEnableKey)\nend\n\n---设置checkbox状态\n---@param id string\n---@param enable boolean\nfunction UI.SetCheckboxEnable(id, enable)\n	local newid = ConcatModID(id)\n    local CheckboxEnableKey = newid .. \"_enabled\"\n	ModSettingSet(CheckboxEnableKey, enable)\nend\n\n---checkbox\n---@param id string\n---@param x number\n---@param y number\n---@param text string\n---@param RightOrLeft boolean? RightOrLeft = true 默认右\n---@param HoverUseCallBack function?\n---@param TextHoverUse function?\n---@param StatusCallBack function?\nfunction UI.checkbox(id, x, y, text, RightOrLeft, HoverUseCallBack, TextHoverUse, StatusCallBack)\n    local newid = ConcatModID(id)\n	RightOrLeft = Default(RightOrLeft, true)\n    local CheckboxEnableKey = newid .. \"_enabled\"\n	local Margin = 10\n    local TextX = x + Margin\n    if not RightOrLeft then\n        local w = GuiGetTextDimensions(this.public.gui, text)\n        TextX = x - w - 2\n    end\n    local checkboxImage\n    if ModSettingGet(CheckboxEnableKey) then\n        checkboxImage = \"mods/wand_editor/files/gui/images/checkbox_fill.png\"\n    elseif ModSettingGet(CheckboxEnableKey) == nil then --初始化\n        ModSettingSet(CheckboxEnableKey, false)\n        checkboxImage = \"mods/wand_editor/files/gui/images/checkbox.png\"\n    else\n        checkboxImage = \"mods/wand_editor/files/gui/images/checkbox.png\"\n    end\n    GuiZSetForNextWidget(this.public.gui, this.private.ZDeep)\n	this.private.ZDeep = this.private.ZDeep + 1\n    local left_click = GuiImageButton(this.public.gui, UI.NewID(id), x, y, \"\", checkboxImage)\n	if HoverUseCallBack ~= nil then\n		HoverUseCallBack(x, y)\n	end\n    if left_click then --如果点击了\n        GamePlaySound(\"data/audio/Desktop/ui.bank\", \"ui/button_click\", GameGetCameraPos())\n        ModSettingSet(CheckboxEnableKey, not ModSettingGet(CheckboxEnableKey))\n    end\n    local status = ModSettingGet(CheckboxEnableKey)\n    GuiOptionsAddForNextWidget(this.public.gui, GUI_OPTION.NoSound)\n	\n	GuiZSetForNextWidget(this.public.gui, this.private.ZDeep - 1)\n	this.private.ZDeep = this.private.ZDeep + 1\n    GuiButton(this.public.gui, UI.NewID(id .. \"TEXT\"), TextX, y - 1, text) --绘制文本\n\n	if TextHoverUse ~= nil then\n		GuiZSetForNextWidget(this.public.gui, this.private.ZDeep)\n		this.private.ZDeep = this.private.ZDeep + 1\n		TextHoverUse(TextX, y)\n	end\n    if StatusCallBack ~= nil then\n		GuiZSetForNextWidget(this.public.gui, this.private.ZDeep)\n		this.private.ZDeep = this.private.ZDeep + 1\n		StatusCallBack(status)\n	end\nend\n\n---滑条\n---@param id string\n---@param x number\n---@param y number\n---@param text string\n---@param value_min number\n---@param value_max number\n---@param value_default number\n---@param value_display_multiplier number\n---@param value_formatting string\n---@param width number\n---@return number\nfunction UI.Slider(id,x,y,text,value_min, value_max, value_default, value_display_multiplier, value_formatting, width)\n    local newid = ConcatModID(id)\n    if this.private.SliderData[newid] == nil or value_min > this.private.SliderData[newid] or this.private.SliderData[newid] > value_max then\n        this.private.SliderData[newid] = value_default\n    end\n    this.private.SliderMax[newid] = value_max\n	this.private.SliderMin[newid] = value_min\n    this.private.SliderData[newid] = GuiSlider(this.public.gui, UI.NewID(id), x, y, text, this.private.SliderData[newid],\n        value_min, value_max, value_default, value_display_multiplier, value_formatting, width)\n\n	return this.private.SliderData[newid]\nend\n\n---获取滑条的值\n---@param id string\n---@return number\nfunction UI.GetSliderValue(id)\n    local newid = ConcatModID(id)\n	return this.private.SliderData[newid]\nend\n\n---设置滑条的值\n---@param id string\n---@param value number\nfunction UI.SetSliderValue(id, value)\n    local newid = ConcatModID(id)\n    if this.private.SliderData[newid] then\n		if value <= this.private.SliderMax[newid] and value >= this.private.SliderMin[newid] then\n			this.private.SliderData[newid] = value\n        else\n			if value <= this.private.SliderMax[newid] then\n                this.private.SliderData[newid] = this.private.SliderMin[newid]\n            else\n				this.private.SliderData[newid] = this.private.SliderMax[newid]\n			end\n		end\n	end\nend\n\n---横向分布容器\n---@param id string\n---@param x number\n---@param y number\n---@param w number\n---@param h number\n---@param DarwContainer boolean?\n---@param margin_x number?\n---@param margin_y number?\nfunction UI.HorizontalScroll(id, x, y, w, h, DarwContainer, margin_x, margin_y)\n	DarwContainer = Default(DarwContainer, true)\n	margin_x = Default(margin_x, 2)\n    margin_y = Default(margin_y, 2)\n	local newid = ConcatModID(id)\n    if this.private.HScrollData[newid] == nil then                                                                         --判断是否有数据\n        this.private.HScrollData[newid] = { id = id, x = x, y = y, w = w, h = h, margin_x = margin_x, margin_y = margin_y, DarwContainer = DarwContainer } --初始化数据\n        this.private.HScrollData[newid].Item = {}\n		this.private.HScrollData[newid].ItemK = 1\n    end\n	if this.private.HScrollSlider[newid] == nil then\n		this.private.HScrollSlider[newid] = {}\n	end\nend\n\n---为横向分布容器增加新元素\n---@param id string\n---@param callback function\nfunction UI.AddHScrollItem(id, callback)\n	local newid = ConcatModID(id)\n    if this.private.HScrollData[newid] then --判断是否有数据\n        this.private.HScrollData[newid].Item[this.private.HScrollData[newid].ItemK] = callback\n		this.private.HScrollData[newid].ItemK = this.private.HScrollData[newid].ItemK + 1\n	end\nend\n\nfunction UI.GetHScrollWidth(id)\n	local newid = ConcatModID(id)\n    if this.private.HScrollSlider[newid] then --判断是否有数据\n        return this.private.HScrollSlider[newid].width or 0\n    end\nend\n\nfunction UI.ResetHScrollSlider(id)\n	local newid = ConcatModID(id)\n    if this.private.HScrollSlider[newid] then --判断是否有数据\n        this.private.HScrollSlider[newid] = {}\n    end\nend\n\n---绘制横向分布容器\n---@param id string\nfunction UI.DarwHorizontalScroll(id)\n    local newid = ConcatModID(id)\n    local SliderValue = this.private.HScrollSlider[newid].value\n    local ScrollWidth = this.private.HScrollSlider[newid].width\n    local LastHover = this.private.HScrollSlider[newid].hover\n    SliderValue = Default(SliderValue, 0.00)\n    ScrollWidth = Default(ScrollWidth, 0)\n	LastHover = Default(LastHover, false)\n    if this.private.HScrollData[newid] then  --如果有数据\n		local x = this.private.HScrollData[newid].x\n        local y = this.private.HScrollData[newid].y\n		local w = this.private.HScrollData[newid].w\n        local h = this.private.HScrollData[newid].h\n		local DarwContainer = this.private.HScrollData[newid].DarwContainer\n\n        local function IsHover(posx, posy)\n            if posx > x and posx <= x + w and posy > y and posy <= y + h then\n                return true\n            end\n            return false\n        end\n		\n        GuiLayoutBeginLayer(this.public.gui) --先开启这个\n\n        GuiZSetForNextWidget(this.public.gui, this.private.ZDeep + 1)\n		if DarwContainer then\n			GuiBeginScrollContainer(this.public.gui, UI.NewID(id), x, y, w, h, true,\n				this.private.HScrollData[newid].margin_x, this.private.HScrollData[newid].margin_y\n        	)	\n		end\n\n        local margin_x = (w - ScrollWidth) * SliderValue             --计算偏移\n		if DarwContainer then\n            GuiLayoutBeginHorizontal(this.public.gui, margin_x, 0, true)\n        else\n			GuiLayoutBeginHorizontal(this.public.gui, x + margin_x, y, true) --横向布局\n		end\n        for k, v in pairs(this.private.HScrollData[newid].Item) do\n            local flag, _, _, ItemX, _, ItemW = v(this.private.HScrollItemData[k]) --传入一个参数，如果参数是真，那么就代表没有超出位置，如果是nil，那么代表超出位置\n			if flag == nil then\n				_, _, _, ItemX, _, ItemW = GuiGetPreviousWidgetInfo(this.public.gui)\n			end\n			if DarwContainer then\n				if ItemX + ItemW/2 > x and ItemX + ItemW/2 <= x + w then--判断x轴有没有超出位置\n					this.private.HScrollItemData[k] = true\n				else\n					this.private.HScrollItemData[k] = nil --减少内存占用（，有可能\n				end\n			end\n\n            local ItemRightX = ItemX - margin_x - x + math.floor(ItemW / 2) + this.private.HScrollData[newid].margin_x --计算正确的位置\n			if ItemRightX > ScrollWidth then\n                ScrollWidth = ItemRightX + math.floor(ItemW / 2) + this.private.HScrollData[newid].margin_x\n			end\n		end\n		GuiLayoutEnd(this.public.gui)\n        if DarwContainer then\n			GuiEndScrollContainer(this.public.gui)\n		end\n        GuiLayoutEndLayer(this.public.gui)\n\n		local hover = false\n		--鼠标位置\n		local mx, my = InputGetMousePosOnScreen()\n		mx = mx / this.private.Scale\n        my = my / this.private.Scale\n		hover =  IsHover(mx, my)\n        this.private.HScrollSlider[newid].width = math.floor(ScrollWidth) --取整减小误差\n        if ScrollWidth > w then\n            GuiZSetForNextWidget(this.public.gui, this.private.ZDeep)\n            if not LastHover then\n				GuiOptionsAddForNextWidget(this.public.gui, GUI_OPTION.DrawSemiTransparent)\n			end\n            this.private.HScrollSlider[newid].value = GuiSlider(this.public.gui, UI.NewID(\"slider\" .. id), x - 4, h + y +\n                1, \"\", SliderValue, 0, 1, 0.00, 0, \" \", w + 3.5)\n            local _, _, SliderHover = GuiGetPreviousWidgetInfo(this.public.gui)\n			hover = hover or SliderHover\n            this.private.HScrollSlider[newid].hover = hover\n			local function MoveSlider()\n				local left = InputIsKeyDown(Key_KP_MINUS) or InputIsKeyDown(Key_LEFT) or InputIsKeyDown(Key_MINUS)\n                local right = InputIsKeyDown(Key_KP_PLUS) or InputIsKeyDown(Key_RIGHT) or InputIsKeyDown(Key_EQUALS)\n                local num = 0.01\n				if InputIsKeyDown(Key_LSHIFT) or InputIsKeyDown(Key_RSHIFT) then--按下shift一次移动更多\n					num = num * 10\n				end\n				if left then\n					this.private.HScrollSlider[newid].value = math.max(this.private.HScrollSlider[newid].value - num, 0)\n				elseif right then\n					this.private.HScrollSlider[newid].value = math.min(this.private.HScrollSlider[newid].value + num, 1)\n				end\n			end\n			if hover then\n                local hasPush = InputIsKeyDown(Key_KP_PLUS) or InputIsKeyDown(Key_KP_MINUS) or InputIsKeyDown(Key_LEFT) or\n                	InputIsKeyDown(Key_RIGHT) or InputIsKeyDown(Key_MINUS) or InputIsKeyDown(Key_EQUALS)\n				\n				if this.private.HScrollSlider[newid].PushFr == nil then --如果在悬浮，就分配一个帧检测时间\n					this.private.HScrollSlider[newid].PushFr = 30\n				else\n                    if hasPush then --如果按了\n						if this.private.HScrollSlider[newid].PushFr == 30 then--按的第一下\n							MoveSlider()\n						end\n						if this.private.HScrollSlider[newid].PushFr ~= 0 then\n							this.private.HScrollSlider[newid].PushFr = this.private.HScrollSlider[newid].PushFr - 1\n						else --如果到了0\n							MoveSlider()\n						end\n					else\n						this.private.HScrollSlider[newid].PushFr = 30 --如果不按退格键就重置时间\n					end\n				end\n			elseif this.private.HScrollSlider[newid].PushFr then --如果未悬浮就设为空\n				this.private.HScrollSlider[newid].PushFr = nil\n			end\n        else\n			this.private.HScrollSlider[newid].value = 0\n		end\n		this.private.ZDeep = this.private.ZDeep + 1\n	end\nend\n\n---返回一个缩放参数，代表相对ui的位置与实际ui位置的倍率\n---@return number\nfunction UI.GetScale()\n	return this.private.Scale\nend\n\n---添加计划刻事件\n---@param fn function\nfunction UI.OnceCallOnExecute(fn)\n	table.insert(this.private.TileTick, fn)\nend\n\n---关闭UI\nfunction UI.Destroy()\n	this.private.destroy = true\nend\n\n---当ui关闭时执行\n---@param fn string\nfunction UI.OnDestroy(fn)\n	table.insert(this.private.DestroyCallBack, fn)\nend\n\n---派发消息\nfunction UI.DispatchMessage()\n    GuiStartFrame(this.public.gui)\n    GuiOptionsAdd(this.public.gui, GUI_OPTION.NoPositionTween) --你不要再飞啦！\n	this.public.ScreenWidth, this.public.ScreenHeight = GuiGetScreenDimensions(this.public.gui)\n	if this.public.ScreenWidth ~= this.private.LastScreenWidth or this.public.ScreenHeight ~= this.private.LastScreenHeight then\n        local GetScaleGui = GuiCreate()\n        local SrcW, SrcH = GuiGetScreenDimensions(GetScaleGui)\n        GuiDestroy(GetScaleGui)\n        this.private.Scale = SrcH / this.public.ScreenHeight\n        this.private.LastScreenWidth = this.public.ScreenWidth\n		this.private.LastScreenHeight = this.public.ScreenHeight\n	end\n	\n    for _, fn in pairs(this.private.FirstEventFn) do\n        if type(fn) == \"function\" then\n            fn(UI)\n        end\n    end\n\n	local max = table.maxn(this.private.TileTick)\n    if max >= 0 then\n        for i = max, 1, -1 do\n            local fn = this.private.TileTick[i]\n            if type(fn) == \"function\" then\n                fn(UI)\n            end\n            this.private.TileTick[i] = nil\n        end\n    end\n	for key, fn in pairs(this.public.MainTickFn) do\n        if type(fn) == \"function\" then\n            fn(UI)\n        end\n	end\n    for key, fn in pairs(this.public.TickEventFn) do\n        if type(fn) == \"function\" then\n            fn(UI)\n        end\n    end\n    for key, fn in pairs(this.public.MiscEventFn) do\n        if type(fn) == \"function\" then\n            fn(UI)\n        end\n    end\n\n    if this.private.destroy then\n        GuiDestroy(this.public.gui)\n        this.private.gui = nil\n        for _, fn in pairs(this.private.DestroyCallBack) do\n            if type(fn) == \"function\" then\n                fn(UI)\n            end\n        end\n    end\n    if next(this.private.ScrollData) then --如果表有数据\n        this.private.ScrollData = {}      --清空数据		\n    end\n    if next(this.private.HScrollData) then --如果表有数据\n        this.private.HScrollData = {}     --清空数据        \n    end\n    if not this.private.TextInputDrawPosHas then--如果没有悬浮的就清空数据\n        this.private.TextInputDrawPosTimer = nil\n    end\n    this.private.TextInputDrawPosHas = false\n    this.private.ZDeep = DefaultZDeep\nend\n\nreturn UI\n"
_TWWE_VFS["mods/wand_editor/files/libs/nxml.lua"] = "local ffi = nil\nif require then\n    pcall(function()\n        ffi = require(\"ffi\")\n    end)\nend\n\nlocal str_sub\nlocal str_index\nlocal str_normalize\n\nif ffi then\n    str_normalize = function(str)\n        return ffi.cast(\"const char*\", str)\n    end\n\n    str_sub = function(ptr, start_idx, len)\n        return ffi.string(ptr + start_idx, len)\n    end\n\n    str_index = function(ptr, idx)\n        return ptr[idx]\n    end\nelse\n    str_normalize = function(str) return str end\n\n    str_sub = function(str, start_idx, len)\n        return str:sub(start_idx + 1, start_idx + len)\n    end\n\n    str_index = function(str, idx)\n        return string.byte(str:sub(idx + 1, idx + 1))\n    end\nend\n\n--[[\n * The following is a Lua port of the NXML parser:\n * https://github.com/xwitchproject/nxml\n *\n * The NXML Parser is heavily based on code from poro\n * https://github.com/gummikana/poro\n * \n * The poro project is licensed under the Zlib license:\n * \n * --------------------------------------------------------------------------\n * Copyright (c) 2010-2019 Petri Purho, Dennis Belfrage\n * Contributors: Martin Jonasson, Olli Harjola\n * This software is provided 'as-is', without any express or implied\n * warranty.  In no event will the authors be held liable for any damages\n * arising from the use of this software.\n * Permission is granted to anyone to use this software for any purpose,\n * including commercial applications, and to alter it and redistribute it\n * freely, subject to the following restrictions:\n * 1. The origin of this software must not be misrepresented; you must not\n *    claim that you wrote the original software. If you use this software\n *    in a product, an acknowledgment in the product documentation would be\n *    appreciated but is not required.\n * 2. Altered source versions must be plainly marked as such, and must not be\n *    misrepresented as being the original software.\n * 3. This notice may not be removed or altered from any source distribution.\n * --------------------------------------------------------------------------\n]]\n\nlocal nxml = {}\n\nlocal TOKENIZER_FUNCS = {}\nlocal TOKENIZER_MT = {\n    __index = TOKENIZER_FUNCS,\n    __tostring = function(self) return \"natif.nxml.tokenizer\" end\n}\n\nlocal function new_tokenizer(cstring, len)\n    return setmetatable({\n        data = cstring,\n        cur_idx = 0,\n        cur_row = 1,\n        cur_col = 1,\n        prev_row = 1,\n        prev_col = 1,\n        len = len\n    }, TOKENIZER_MT)\nend\n\nlocal ws = {\n    [string.byte(\" \")] = true,\n    [string.byte(\"\\t\")] = true,\n    [string.byte(\"\\n\")] = true,\n    [string.byte(\"\\r\")] = true\n}\n\nfunction TOKENIZER_FUNCS:is_whitespace(char)\n    local n = tonumber(char)\n    return ws[n] or false\nend\n\nlocal punct = {\n    [string.byte(\"<\")] = true,\n    [string.byte(\">\")] = true,\n    [string.byte(\"=\")] = true,\n    [string.byte(\"/\")] = true,\n}\n\nfunction TOKENIZER_FUNCS:is_whitespace_or_punctuation(char)\n    local n = tonumber(char)\n    return self:is_whitespace(n) or punct[n] or false\nend\n\nfunction TOKENIZER_FUNCS:move(n)\n    n = n or 1\n    local prev_idx = self.cur_idx\n    self.cur_idx = self.cur_idx + n\n    if self.cur_idx >= self.len then\n        self.cur_idx = self.len\n        return\n    end\n    for i = prev_idx, self.cur_idx - 1 do\n        if str_index(self.data, i) == string.byte(\"\\n\") then\n            self.cur_row = self.cur_row + 1\n            self.cur_col = 1\n        else\n            self.cur_col = self.cur_col + 1\n        end\n    end\nend\n\nfunction TOKENIZER_FUNCS:peek(n)\n    n = n or 1\n    local idx = self.cur_idx + n\n    if idx >= self.len then return 0 end\n\n    return str_index(self.data, idx)\nend\n\nfunction TOKENIZER_FUNCS:match_string(str)\n    local len = #str\n    str = str_normalize(str)\n    \n    for i = 0, len - 1 do\n        if self:peek(i) ~= str_index(str, i) then return false end\n    end\n    return true\nend\n\nfunction TOKENIZER_FUNCS:eof()\n    return self.cur_idx >= self.len\nend\n\nfunction TOKENIZER_FUNCS:cur_char()\n    if self:eof() then return 0 end\n    return tonumber(str_index(self.data, self.cur_idx))\nend\n\nfunction TOKENIZER_FUNCS:skip_whitespace()\n    while not self:eof() do\n        if self:is_whitespace(self:cur_char()) then\n            self:move()\n        elseif self:match_string(\"<!--\") then\n            self:move(4)\n            while not self:eof() and not self:match_string(\"-->\") do\n                self:move()\n            end\n\n            if self:match_string(\"-->\") then\n                self:move(3)\n            end\n        elseif self:cur_char() == string.byte(\"<\") and self:peek(1) == string.byte(\"!\") then\n            self:move(2)\n            while not self:eof() and self:cur_char() ~= string.byte(\">\") do\n                self:move()\n            end\n            if self:cur_char() == string.byte(\">\") then\n                self:move()\n            end\n\n        elseif self:match_string(\"<?\") then\n            self:move(2)\n            while not self:eof() and not self:match_string(\"?>\") do\n                self:move()\n            end\n            if self:match_string(\"?>\") then\n                self:move(2)\n            end\n        else\n            break\n        end\n    end\nend\n\nfunction TOKENIZER_FUNCS:read_quoted_string()\n    local start_idx = self.cur_idx\n    local len = 0\n\n    while not self:eof() and self:cur_char() ~= string.byte(\"\\\"\") do\n        len = len + 1\n        self:move()\n    end\n\n    self:move() -- skip \"\n    return str_sub(self.data, start_idx, len)\nend\n\nfunction TOKENIZER_FUNCS:read_unquoted_string()\n    local start_idx = self.cur_idx - 1 -- first char is move()d\n    local len = 1\n\n    while not self:eof() and not self:is_whitespace_or_punctuation(self:cur_char()) do\n        len = len + 1\n        self:move()\n    end\n\n    return str_sub(self.data, start_idx, len)\nend\n\nlocal C_NULL = 0\nlocal C_LT = string.byte(\"<\")\nlocal C_GT = string.byte(\">\")\nlocal C_SLASH = string.byte(\"/\")\nlocal C_EQ = string.byte(\"=\")\nlocal C_QUOTE = string.byte(\"\\\"\")\n\nfunction TOKENIZER_FUNCS:next_token()\n    self:skip_whitespace()\n\n    self.prev_row = self.cur_row\n    self.prev_col = self.cur_col\n\n    if self:eof() then return nil end\n\n    local c = self:cur_char()\n    self:move()\n\n    if c == C_NULL then return nil\n    elseif c == C_LT then return { type = \"<\" }\n    elseif c == C_GT then return { type = \">\" }\n    elseif c == C_SLASH then return { type = \"/\" }\n    elseif c == C_EQ then return { type = \"=\" }\n    elseif c == C_QUOTE then return { type = \"string\", value = self:read_quoted_string() }\n    else return { type = \"string\", value = self:read_unquoted_string() }\n    end\nend\n\nlocal PARSER_FUNCS = {}\nlocal PARSER_MT = {\n    __index = PARSER_FUNCS,\n    __tostring = function(self) return \"natif.nxml.parser\" end\n}\n\nlocal function new_parser(tokenizer, error_reporter)\n    return setmetatable({\n        tok = tokenizer,\n        errors = {},\n        error_reporter = error_reporter or function(type, msg) print(\"parser error: [\" .. type .. \"] \" .. msg) end\n    }, PARSER_MT)\nend\n\nlocal XML_ELEMENT_FUNCS = {}\nlocal XML_ELEMENT_MT = {\n    __index = XML_ELEMENT_FUNCS,\n    __tostring = function(self)\n        return nxml.tostring(self)\n    end,\n}\n\nfunction PARSER_FUNCS:report_error(type, msg)\n    self.error_reporter(type, msg)\n    table.insert(self.errors, { type = type, msg = msg, row = self.tok.prev_row, col = self.tok.prev_col })\nend\n\n\nfunction PARSER_FUNCS:parse_attr(attr_table, name)\n    local tok = self.tok:next_token()\n    if tok.type == \"=\" then\n        tok = self.tok:next_token()\n\n        if tok.type == \"string\" then\n            attr_table[name] = tok.value\n        else\n            self:report_error(\"missing_attribute_value\", string.format(\"parsing attribute '%s' - expected a string after =, but did not find one\"), name)\n        end\n    else\n        self:report_error(\"missing_equals_sign\", string.format(\"parsing attribute '%s' - did not find equals sign after attribute name\", name))\n    end\nend\n\nfunction PARSER_FUNCS:parse_element(skip_opening_tag)\n    local tok\n    if not skip_opening_tag then\n        tok = self.tok:next_token()\n        if tok.type ~= \"<\" then\n            self:report_error(\"missing_tag_open\", \"couldn't find a '<' to start parsing with\")\n        end\n    end\n\n    tok = self.tok:next_token()\n    if tok.type ~= \"string\" then\n        self:report_error(\"missing_element_name\", \"expected an element name after '<'\")\n    end\n\n    local elem_name = tok.value\n    local elem = nxml.new_element(elem_name)\n    local content_idx = 0\n\n    local self_closing = false\n\n    while true do\n        tok = self.tok:next_token()\n\n        if tok == nil then\n            return elem\n        elseif tok.type == \"/\" then\n            if self.tok:cur_char() == C_GT then\n                self.tok:move()\n                self_closing = true\n            end\n            break\n        elseif tok.type == \">\" then\n            break\n        elseif tok.type == \"string\" then\n            self:parse_attr(elem.attr, tok.value)\n        end\n    end\n\n    if self_closing then return elem end\n\n    while true do\n        tok = self.tok:next_token()\n\n        if tok == nil then\n            return elem\n        elseif tok.type == \"<\" then\n            if self.tok:cur_char() == C_SLASH then\n                self.tok:move()\n\n                local end_name = self.tok:next_token()\n                if end_name.type == \"string\" and end_name.value == elem_name then\n                    local close_greater = self.tok:next_token()\n\n                    if close_greater.type == \">\" then\n                        return elem\n                    else\n                        self:report_error(\"missing_element_close\", string.format(\"no closing '>' found for element '%s'\", elem_name))\n                    end\n                else\n                    self:report_error(\"mismatched_closing_tag\", string.format(\"closing element is in wrong order - expected '</%s>', but instead got '%s'\", elem_name, tostring(end_name.value)))\n                end\n                return elem\n            else\n                local child = self:parse_element(elem, true)\n                table.insert(elem.children, child)\n            end\n        else\n            if not elem.content then\n                elem.content = {}\n            end\n            \n            content_idx = content_idx + 1\n            elem.content[content_idx] = tok.value or tok.type\n        end\n    end\nend\n\nfunction PARSER_FUNCS:parse_elements()\n    local tok = self.tok:next_token()\n    local elems = {}\n    local elems_i = 1\n\n    while tok and tok.type == \"<\" do\n        elems[elems_i] = self:parse_element(true)\n        elems_i = elems_i + 1\n\n        tok = self.tok:next_token()\n    end\n\n    return elems\nend\n\nlocal function is_punctuation(str)\n    return str == \"/\" or str == \"<\" or str == \">\" or str == \"=\"\nend\n\nfunction XML_ELEMENT_FUNCS:text()\n    local content_count = #self.content\n\n    if self.content == nil or content_count == 0 then\n        return \"\"\n    end\n\n    local text = self.content[1]\n    for i = 2, content_count do\n        local elem = self.content[i]\n        local prev = self.content[i - 1]\n\n        if is_punctuation(elem) or is_punctuation(prev) then\n            text = text .. elem\n        else\n            text = text .. \" \" .. elem\n        end\n    end\n\n    return text\nend\n\nfunction XML_ELEMENT_FUNCS:add_child(child)\n    self.children[#self.children + 1] = child\nend\n\nfunction XML_ELEMENT_FUNCS:add_children(children)\n    local children_i = #self.children + 1\n    for i = 1, #children do\n        self.children[children_i] = children[i]\n        children_i = children_i + 1\n    end\nend\n\nfunction XML_ELEMENT_FUNCS:remove_child(child)\n    for i = 1, #self.children do\n        if self.children[i] == child then\n            table.remove(self.children, i)\n            break\n        end\n    end\nend\n\nfunction XML_ELEMENT_FUNCS:remove_child_at(index)\n    table.remove(self.children, index)\nend\n\nfunction XML_ELEMENT_FUNCS:clear_children()\n    self.children = {}\nend\n\nfunction XML_ELEMENT_FUNCS:clear_attrs()\n    self.attr = {}\nend\n\nfunction XML_ELEMENT_FUNCS:first_of(element_name)\n    local i = 0\n    local n = #self.children\n\n    while i < n do\n        i = i + 1\n        local c = self.children[i]\n\n        if c.name == element_name then return c end\n    end\n\n    return nil\nend\n\nfunction XML_ELEMENT_FUNCS:each_of(element_name)\n    local i = 1\n    local n = #self.children\n\n    return function()\n        while i <= n and self.children[i].name ~= element_name do\n            i = i + 1\n        end\n        i = i + 1\n        return self.children[i - 1]\n    end\nend\n\nfunction XML_ELEMENT_FUNCS:all_of(element_name)\n    local table = {}\n    local i = 1\n    for elem in self:each_of(element_name) do\n        table[i] = elem\n        i = i + 1\n    end\n    return table\nend\n\nfunction XML_ELEMENT_FUNCS:each_child()\n    local i = 0\n    local n = #self.children\n\n    return function()\n        while i <= n do\n            i = i + 1\n            return self.children[i]\n        end\n    end\nend\n\nfunction XML_ELEMENT_FUNCS:each_child_i() -- Nathan func\n    local i = 0\n    local n = #self.children\n\n    return function()\n        while i < n do\n            i = i + 1\n            return i,self.children[i] -- yield but weird\n        end\n    end\nend\n\nfunction nxml.parse(data)\n    local data_len = #data\n    local tok = new_tokenizer(str_normalize(data), data_len)\n    local parser = new_parser(tok)\n    \n    local elem = parser:parse_element(false)\n    \n    if not elem or (elem.errors and #elem.errors > 0) then\n        error(\"parser encountered errors\")\n    end\n\n    return elem\nend\n\nfunction nxml.parse_many(data)\n    local data_len = #data\n    local tok = new_tokenizer(str_normalize(data), data_len)\n    local parser = new_parser(tok)\n    \n    local elems = parser:parse_elements(false)\n    \n    for i = 1, #elems do\n        local elem = elems[i]\n\n        if elem.errors and #elem.errors > 0 then\n            error(\"parser encountered errors\")\n        end\n    end\n\n    return elems\nend\n\nfunction nxml.new_element(name, attrs)\n    return setmetatable({\n        name = name,\n        attr = attrs or {},\n        children = {},\n        content = nil\n    }, XML_ELEMENT_MT)\nend\n\nlocal function attr_value_to_str(value)\n    local t = type(value)\n    if t == \"string\" then return value end\n    if t == \"boolean\" then return value and \"1\" or \"0\" end\n\n    return tostring(value)\nend\n\nfunction nxml.tostring(elem, packed, indent_char, cur_indent)\n    indent_char = indent_char or \"\\t\"\n    cur_indent = cur_indent or \"\"\n    local s = \"<\" .. elem.name\n    local self_closing = #elem.children == 0 and (not elem.content or #elem.content == 0)\n\n    for k, v in pairs(elem.attr) do\n        s = s .. \" \" .. k .. \"=\\\"\" .. attr_value_to_str(v) .. \"\\\"\"\n    end\n\n    if self_closing then\n        s = s .. \" />\"\n        return s\n    end\n\n    s = s .. \">\"\n\n    local deeper_indent = cur_indent .. indent_char\n\n    if elem.content and #elem.content ~= 0 then\n        if not packed then s = s .. \"\\n\" .. deeper_indent end\n        s = s .. elem:text()\n    end\n\n    if not packed then s = s .. \"\\n\" end\n\n    for i, v in ipairs(elem.children) do\n        if not packed then s = s .. deeper_indent end\n        s = s .. nxml.tostring(v, packed, indent_char, deeper_indent)\n        if not packed then s = s .. \"\\n\" end\n    end\n\n    s = s .. cur_indent .. \"</\" .. elem.name .. \">\"\n\n    return s\nend\n\nreturn nxml\n"
_TWWE_VFS["mods/wand_editor/files/libs/unsafe.lua"] = "dofile_once(\"mods/wand_editor/files/libs/define.lua\")\ndofile_once(\"mods/wand_editor/unsafeFn.lua\")\n\nSavePath = \"%userprofile%/AppData/LocalLow/Nolla_Games_Noita/\"\n\nif DebugMode then\n	package.cpath = package.cpath..\";./\"..ModDir..\"files/module/debug/?.dll\"\nelse\n	package.cpath = package.cpath..\";./\"..ModDir..\"files/module/?.dll\"\nend\npackage.cpath = package.cpath .. \";./\" .. ModDir .. \"files/module/socket/?.dll\"\npackage.cpath = package.cpath .. \";./\" .. ModDir .. \"files/module/socket/mime/?.dll\"--mime，lua socker运行依赖\npackage.path = package.path .. \";./\" .. ModDir .. \"files/socket_lua/?.lua\"\npackage.path = package.path .. \";./\" .. ModDir .. \"files/socket_lua/socket/?.lua\"\npackage.path = package.path .. \";./\" .. ModDir .. \"files/link/?.lua\"\nCpp = require(\"WandEditorDll\")--加载模块\nCpp.SetDllDirectory(Cpp.CurrentPath()..\"/mods/wand_editor/files/module/openssl\")--提供openssl的动态链接库加载索引\neffil = require(\"effil\")\n--初始化为绝对路径\nSavePath = Cpp.GetAbsPath(SavePath)\n\ndofile_once(\"data/scripts/gun/gun_enums.lua\")\n\nSpellTypeBG = {\n	[ACTION_TYPE_PROJECTILE] = \"data/ui_gfx/inventory/item_bg_projectile.png\",\n	[ACTION_TYPE_STATIC_PROJECTILE] = \"data/ui_gfx/inventory/item_bg_static_projectile.png\",\n	[ACTION_TYPE_MODIFIER] = \"data/ui_gfx/inventory/item_bg_modifier.png\",\n	[ACTION_TYPE_DRAW_MANY] = \"data/ui_gfx/inventory/item_bg_draw_many.png\",\n	[ACTION_TYPE_MATERIAL] = \"data/ui_gfx/inventory/item_bg_material.png\",\n	[ACTION_TYPE_OTHER] = \"data/ui_gfx/inventory/item_bg_other.png\",\n	[ACTION_TYPE_UTILITY] = \"data/ui_gfx/inventory/item_bg_utility.png\",\n	[ACTION_TYPE_PASSIVE] = \"data/ui_gfx/inventory/item_bg_passive.png\"\n}\n"
_TWWE_VFS["mods/wand_editor/files/link/github_mirror.lua"] = "function GitHubProxy_Link(str,raw)\n    local GitHubProxyLink = \"https://ghp.ci/\"\n    if raw then\n		return GitHubProxyLink .. \"https://raw.githubusercontent.com\" .. str\n    else\n		return GitHubProxyLink .. \"https://github.com\" .. str\n	end\nend\n--上述是我目前找到的一个可用镜像（截止2024.7.3)\n\n--这个函数是直接访问github原始页面的，不是镜像\nfunction GitHub_Link(str, raw)\n	if raw then\n		return \"https://raw.githubusercontent.com\" .. str\n    else\n		return \"https://github.com\" .. str\n	end\nend\n--可以视条件更改CurrentMirror指向的函数\nCurrentMirror = GitHubProxy_Link\n"
_TWWE_VFS["mods/wand_editor/files/misc/bygoki/dummy/custom_damage_numbers.lua"] = "dofile_once( \"mods/wand_editor/files/misc/bygoki/helper.lua\" );\ndofile_once( \"mods/wand_editor/files/misc/bygoki/lib/helper.lua\" );\ndofile_once( \"mods/wand_editor/files/misc/bygoki/lib/variables.lua\" );\nlocal last_damage_frame = {};\nlocal old_thousands_separator = thousands_separator\nthousands_separator = function(num)\n    if num > 1e15 or -num > 1e15 then\n        return string.lower(tostring(num))\n    else\n        return old_thousands_separator(string.format(\"%.2f\", num));\n    end\nend\n\nfunction damage_received( damage, message, entity_thats_responsible, is_fatal )\n    local entity = GetUpdatedEntityID();\n    if EntityHasNamedVariable(entity, \"gkbrkn_always_show_damage_numbers\") or is_fatal == false then\n        local now = GameGetFrameNum();\n        if now - ( last_damage_frame[entity] or 0 ) > 180 then\n            EntitySetVariableNumber( entity, \"gkbrkn_total_damage\", 0 );\n        end\n        last_damage_frame[entity] = now;\n        local total_damage = EntityGetVariableNumber(entity, \"gkbrkn_total_damage\", 0) + damage;\n        EntitySetVariableNumber( entity, \"gkbrkn_total_damage\", total_damage );\n        local damage_text = thousands_separator(total_damage * 25 );\n        EntitySetVariableString(entity, \"gkbrkn_custom_damage_numbers_text\", damage_text);\n    else\n        local sprites = EntityGetComponentIncludingDisabled(entity,\"SpriteComponent\") or {};\n        for k,v in pairs( sprites ) do\n            if ComponentGetValue2( v, \"is_text_sprite\" ) then\n                EntityRemoveComponent( entity, v );\n            end\n        end\n    end\nend\n"
_TWWE_VFS["mods/wand_editor/files/misc/bygoki/dummy/custom_damage_numbers_text.lua"] = "dofile_once( \"mods/wand_editor/files/misc/bygoki/helper.lua\" );\ndofile_once( \"mods/wand_editor/files/misc/bygoki/lib/variables.lua\" );\nlast_text = last_text or \"\";\nlocal entity = GetUpdatedEntityID();\nlocal current_target = EntityGetParent( entity );\nlocal current_text = EntityGetVariableString( current_target, \"gkbrkn_custom_damage_numbers_text\", \"\" );\nif current_target ~= 0 and last_text ~= current_text then\n    last_text = current_text;\n    local width,height = EntityGetFirstHitboxSize( current_target );\n    local sprite = EntityGetFirstComponent( entity, \"SpriteComponent\", \"gkbrkn_custom_damage_number\" );\n    if sprite then\n        ComponentSetValue2( sprite, \"offset_x\", #current_text * 2 - 2 );\n        ComponentSetValue2( sprite, \"offset_y\", height * 2 + 12 );\n        ComponentSetValue2( sprite, \"text\", current_text );\n        EntityRefreshSprite( entity, sprite );\n    end\nend\n"
_TWWE_VFS["mods/wand_editor/files/misc/bygoki/dummy/dps_tracker.lua"] = "dofile_once( \"mods/wand_editor/files/misc/bygoki/helper.lua\" );\ndofile_once( \"mods/wand_editor/files/misc/bygoki/lib/helper.lua\" );\ndofile_once(\"mods/wand_editor/files/misc/bygoki/lib/mod_settings.lua\");\ndofile_once(\"mods/wand_editor/files/libs/fn.lua\")\n\n---获得Storage组件和对应值\n---@param entity integer EntityID\n---@param VariableName string\n---@return any|nil\n---@return integer|nil\nlocal function GetFloatStorageComp(entity, VariableName)\n	local comps = EntityGetComponent(entity, \"VariableStorageComponent\")\n	if comps == nil then\n		return\n	end\n	for _, comp in pairs(comps) do --遍历存储组件表\n		local name = ComponentGetValue2(comp, \"name\")\n		if name == VariableName then --如果是状态就取值\n			local value = ComponentGetValue2(comp, \"value_float\")\n			return value, comp\n		end\n	end\nend\n\n---增加并设置Storage\n---@param entity integer\n---@param i_name string\n---@param i_value any\n---@return integer|nil\nlocal function AddSetFloatStorageComp(entity, i_name, i_value)\n	if entity == nil or not EntityGetIsAlive(entity) then\n		return\n	end\n	return EntityAddComponent(entity, \"VariableStorageComponent\", { name = i_name, value_float = i_value })\nend\n\n---设置Storage，并返回组件\n---@param entity integer\n---@param VariableName string\n---@param i_value any\n---@return integer|nil\nlocal function SetFloatStorageComp(entity, VariableName, i_value)\n	local comps = EntityGetComponent(entity, \"VariableStorageComponent\")\n	if comps == nil then\n		return\n	end\n	for _, comp in pairs(comps) do --遍历存储组件表\n		local name = ComponentGetValue2(comp, \"name\")\n		if name == VariableName then --如果是就取值\n			ComponentSetValue2(comp, \"value_float\", i_value)\n			return comp\n		end\n	end\nend\n\nfunction GetValue(entity, id)\n	local result = GetFloatStorageComp(entity, id)\n    if result == nil then\n        AddSetFloatStorageComp(entity, id, 0)\n        result = 0\n    end\n	return result\nend\n\nfunction damage_received( damage, message, entity_thats_responsible, is_fatal )\n    local now = GameGetFrameNum();\n    local now_true = GameGetRealWorldTimeSinceStarted();\n    local entity = GetUpdatedEntityID();\n\n    local current = GetValue(entity, \"current\")\n	local current_true = GetValue(entity, \"current_true\")\n    local first_hit_frame = GetValue(entity, \"first_hit_frame\")\n    local total_damage = GetValue(entity, \"total_damage\")\n	local reset_frame = GetValue(entity, \"reset_frame\")\n	local first_hit_time = GetValue(entity, \"first_hit_time\")\n\n    local damage_models = EntityGetComponent( entity, \"DamageModelComponent\" ) or {};\n	\n    for _,damage_model in pairs(damage_models) do\n        local max_hp = ComponentGetValue2( damage_model, \"max_hp\" );\n        ComponentSetValue2( damage_model, \"max_hp\", 4 );\n        ComponentSetValue2( damage_model, \"hp\", math.max( 4, damage * 1.1 ) );\n    end\n    --local x,y = EntityGetTransform( entity );\n    --local did_hit, hit_x, hit_y = RaytracePlatforms( x, y - 1, x, y );\n    --if did_hit then\n    --    EntityApplyTransform( entity, x, y - 5 );\n    --end\n\n    -- reset tracker after 10 frames of dps\n    if now >= reset_frame or (now - first_hit_frame) > 600 then\n        total_damage = 0;\n        current_true = 0;\n        current = 0;\n        first_hit_frame = now;\n        first_hit_time = now_true;\n        EntitySetVariableNumber( entity, \"gkbrkn_dps_tracker_highest\", 0 );\n    end\n    total_damage = total_damage + damage;\n    reset_frame = now + 60;\n    current = total_damage / math.ceil( math.max( now - first_hit_frame, 1 ) / 59 );\n    current_true = total_damage / math.max(now_true - first_hit_time, 1);\n	local old_thousands_separator = thousands_separator\n    local thousands_separator = function(num)\n        if num > 1e15 or -num > 1e15 then\n            return string.lower(tostring(num))\n        else\n            return old_thousands_separator(string.format(\"%.2f\", num));\n        end\n    end\n	\n    local highest_current = EntityGetVariableNumber( entity, \"gkbrkn_dps_tracker_highest\", 0 );\n    local damage_text\n	if IsINF(current * 25) then--thousands_separator\n        damage_text = \"inf\"\n	elseif current * 25 == -math.huge then\n		damage_text = \"-inf\"\n    else\n		damage_text = thousands_separator(current * 25 );\n	end\n    local damage_text_true = thousands_separator(current_true * 25 );\n    EntitySetVariableString( entity, \"gkbrkn_dps_tracker_text\", damage_text );\n    EntitySetVariableString(entity, \"gkbrkn_dps_tracker_text_true\", damage_text_true);\n    GlobalsSetValue(ModID .. \"total_damage\", thousands_separator(total_damage * 25))\n	local flag = false\n    if current < 0 and highest_current <= 0 and current < highest_current then\n        flag = true\n    end\n	if current > 0 and current > highest_current then\n		flag = true\n	end\n	if flag then\n        EntitySetVariableNumber( entity, \"gkbrkn_dps_tracker_highest\", current );\n        EntitySetVariableString(entity, \"gkbrkn_dps_tracker_text_highest\", thousands_separator(current * 25));\n		GlobalsSetValue(ModID .. \"highest_dps\", damage_text);\n    end\n    add_frame_time(GameGetRealWorldTimeSinceStarted() - now_true);\n\n	SetFloatStorageComp(entity, \"current\", current)\n	SetFloatStorageComp(entity, \"current_true\", current_true)\n    SetFloatStorageComp(entity, \"first_hit_frame\", first_hit_frame)\n    SetFloatStorageComp(entity, \"total_damage\", total_damage)\n	SetFloatStorageComp(entity, \"reset_frame\", reset_frame)\n	SetFloatStorageComp(entity, \"first_hit_time\", first_hit_time)\nend\n"
_TWWE_VFS["mods/wand_editor/files/misc/bygoki/dummy/dps_tracker_text.lua"] = "dofile_once( \"mods/wand_editor/files/misc/bygoki/helper.lua\" );\ndofile_once(\"mods/wand_editor/files/misc/bygoki/lib/variables.lua\");\ndofile_once(\"mods/wand_editor/files/libs/fn.lua\")\nlast_text = last_text or \"\";\nlocal entity = GetUpdatedEntityID();\nlocal SrcPath = \"mods/wand_editor/files/misc/bygoki/font/font_small_numbers.xml\"\n\nlocal sprite_highest = EntityGetFirstComponentIncludingDisabled(entity, \"SpriteComponent\", \"gkbrkn_dps_tracker_highest\");\nlocal sprite_true = EntityGetFirstComponentIncludingDisabled(entity, \"SpriteComponent\", \"gkbrkn_dps_tracker_true\");\nlocal sprite_damage_number = EntityGetFirstComponentIncludingDisabled(entity, \"SpriteComponent\", \"gkbrkn_custom_damage_number\");\n\nlocal current_target = EntityGetParent( entity );\nlocal current_text = EntityGetVariableString( current_target, \"gkbrkn_dps_tracker_text\", \"\" );\nif current_target ~= 0 and last_text ~= current_text then\n    last_text = current_text;\n    local width,height = EntityGetFirstHitboxSize( current_target );\n    local sprite = EntityGetFirstComponent(entity, \"SpriteComponent\", \"gkbrkn_dps_tracker\");\n	\n    if sprite and current_text ~= \"inf\" and current_text ~= \"-inf\" then\n        ComponentSetValue2( sprite, \"offset_x\", #current_text * 2 - 2 );\n        ComponentSetValue2(sprite, \"offset_y\", height * 2 - 12);\n        ComponentSetValue2(sprite, \"text\", current_text);\n        ComponentSetValue2(sprite, \"is_text_sprite\", true);\n        ComponentSetValue2(sprite, \"image_file\", SrcPath);\n		EntitySetComponentIsEnabled(entity, sprite_highest, true)\n        EntitySetComponentIsEnabled(entity, sprite_true, true)\n		EntitySetComponentIsEnabled(entity, sprite_damage_number, true)\n        EntityRefreshSprite(entity, sprite);\n	elseif sprite and (current_text == \"inf\" or current_text == \"-inf\") then\n        ComponentSetValue2(sprite, \"is_text_sprite\", false);\n		ComponentSetValue2( sprite, \"offset_x\", 0);\n        ComponentSetValue2(sprite, \"offset_y\", 0);\n		if current_text == \"inf\" then\n			ComponentSetValue2(sprite, \"image_file\", \"mods/wand_editor/files/entity/dummy/inf_small.xml\");			\n        else\n			ComponentSetValue2(sprite, \"image_file\", \"mods/wand_editor/files/entity/dummy/deg_inf_small.xml\");\n		end\n        EntitySetComponentIsEnabled(entity, sprite_highest, false)\n        EntitySetComponentIsEnabled(entity, sprite_true, false)\n		EntitySetComponentIsEnabled(entity, sprite_damage_number, false)\n        EntityRefreshSprite(entity, sprite);\n    end\nend\n"
_TWWE_VFS["mods/wand_editor/files/misc/bygoki/dummy/dps_tracker_text_highest.lua"] = "dofile_once( \"mods/wand_editor/files/misc/bygoki/helper.lua\" );\ndofile_once( \"mods/wand_editor/files/misc/bygoki/lib/variables.lua\" );\nlast_text = last_text or \"\";\nlocal entity = GetUpdatedEntityID();\nlocal current_target = EntityGetParent( entity );\nlocal current_text = EntityGetVariableString( current_target, \"gkbrkn_dps_tracker_text_highest\", \"\" );\nif current_target ~= 0 and last_text ~= current_text then\n    last_text = current_text;\n    local width,height = EntityGetFirstHitboxSize( current_target );\n    local sprite = EntityGetFirstComponent( entity, \"SpriteComponent\", \"gkbrkn_dps_tracker_highest\" );\n    if sprite then\n        ComponentSetValue2( sprite, \"offset_x\", #current_text * 2 - 2 );\n        ComponentSetValue2( sprite, \"offset_y\", height * 2 - 12 );\n        ComponentSetValue2( sprite, \"text\", current_text );\n        EntityRefreshSprite( entity, sprite );\n    end\nend\n"
