_TWWE_VFS["mods/wand_editor/files/misc/bygoki/helper.lua"] = "dofile_once(\"data/scripts/gun/procedural/gun_action_utils.lua\");\n\nfunction ShootProjectile( who_shot, entity_file, x, y, vx, vy, send_message )\n    local entity = EntityLoad( entity_file, x, y );\n    local genome = EntityGetFirstComponent( who_shot, \"GenomeDataComponent\" );\n    -- this is the herd id string\n    --local herd_id = ComponentGetValue2( genome, \"herd_id\" );\n    local herd_id = ComponentGetValueInt( genome, \"herd_id\" );\n    if send_message == nil then send_message = true end\n\n	GameShootProjectile( who_shot, x, y, x+vx, y+vy, entity, send_message );\n\n    local projectile = EntityGetFirstComponent( entity, \"ProjectileComponent\" );\n    if projectile ~= nil then\n        ComponentSetValue2( projectile, \"mWhoShot\", who_shot );\n        -- NOTE the returned herd id actually breaks the herd logic, so don't bother\n        --ComponentSetValue2( projectile, \"mShooterHerdId\", herd_id );\n    end\n\n    local velocity = EntityGetFirstComponent( entity, \"VelocityComponent\" );\n    if velocity ~= nil then\n	    ComponentSetValue2( velocity, \"mVelocity\", vx, vy )\n    end\n\n	return entity;\nend\n\nfunction WandGetActive( entity )\n    local chosen_wand = nil;\n    local wands = {};\n    local children = EntityGetAllChildren( entity )  or {};\n    for key, child in pairs( children ) do\n        if EntityGetName( child ) == \"inventory_quick\" then\n            wands = EntityGetChildrenWithTag( child, \"wand\" );\n            break;\n        end\n    end\n    if #wands > 0 then\n        local inventory2 = EntityGetFirstComponent( entity, \"Inventory2Component\" );\n        local active_item = ComponentGetValue2( inventory2, \"mActiveItem\" );\n        for _,wand in pairs( wands ) do\n            if wand == active_item then\n                chosen_wand = wand;\n                break;\n            end\n        end\n        return chosen_wand;\n    end\nend\n\nfunction WandGetActiveOrRandom( entity )\n    local chosen_wand = nil;\n    local wands = {};\n    local children = EntityGetAllChildren( entity )  or {};\n    for key, child in pairs( children ) do\n        if EntityGetName( child ) == \"inventory_quick\" then\n            wands = EntityGetChildrenWithTag( child, \"wand\" );\n            break;\n        end\n    end\n    if #wands > 0 then\n        local inventory2 = EntityGetFirstComponent( entity, \"Inventory2Component\" );\n        local active_item = ComponentGetValue2( inventory2, \"mActiveItem\" );\n        for _,wand in pairs( wands ) do\n            if wand == active_item then\n                chosen_wand = wand;\n                break;\n            end\n        end\n        if chosen_wand == nil then\n            chosen_wand =  random_from_array( wands );\n        end\n        return chosen_wand;\n    end\nend\n\nfunction benchmark( callback, iterations )\n    if iterations == nil then\n        iterations = 1;\n    end\n    local t = GameGetRealWorldTimeSinceStarted();\n    for i=1,iterations do\n        callback();\n    end\n    return GameGetRealWorldTimeSinceStarted() - t;\nend\n\nfunction map(func, array)\n    local new_array = {};\n    for i,v in ipairs(array) do\n      new_array[i] = func(v);\n    end\n    return new_array;\n  end\n\nfunction DoFileEnvironment( filepath, environment )\n    if environment == nil then environment = {} end\n    local f = loadfile( filepath );\n    local set_f = setfenv( f, setmetatable( environment, { __index = _G } ) );\n    local status,result = pcall( set_f );\n    if status == false then print_error( \"do file environment for \"..filepath..\": \"..result ); end\n    return environment;\nend\n\nfunction ModTextFileAppend( left, right )\n    ModTextFileSetContent( left, (ModTextFileGetContent( left ) or \"\") .. \"\\r\\n\" .. (ModTextFileGetContent( right ) or \"\") );\nend\n\nfunction ModTextFilePrepend( left, right )\n    ModTextFileSetContent( left, (ModTextFileGetContent( right ) or \"\") .. \"\\r\\n\" .. (ModTextFileGetContent( left ) or \"\") );\nend\n\nfunction PackString( separator, ... )\n	local string = {};\n	for n=1,select( '#' , ... ) do\n		local j = select( n, ... );\n		local text = nil;\n		if type(j) == \"boolean\" then\n			if j then\n			   text = \"true\";\n			else\n				text = \"false\";\n			end\n        else\n            if type(j) == \"string\" and #j == 0 then\n                text = \"\\\"\\\"\";\n            else\n                text = tostring( j ) or \"nil\";\n            end\n        end\n		string[n] = text;\n	end\n	return table.concat( string, separator or \"\" );\nend\n\nfunction Log( ... )\n    print( PackString(\" \", ... ) );\nend\n\nfunction LogCompact( ... )\n    local length = 0;\n    local log = {};\n    for k,v in pairs( {...} ) do\n        table.insert( log, v );\n        length = length + #v;\n        if length > 80 then\n            table.insert(log,\"\\n\");\n            length = 0;\n        end\n    end\n    Log( unpack( log ) );\nend\n\nlocal screen_log_queue = {};\nlocal screen_log_max = 20;\nlocal screen_log_interval = 0.333;\nfunction LogScreen( ... )\n    table.insert( screen_log_queue, PackString( \" \", ... ) );\nend\n\nfunction RenderLog( gui )\n    local start_index = math.floor(GameGetRealWorldTimeSinceStarted()/screen_log_interval);\n    for i=1,screen_log_max do\n        local adjusted_index = (i + start_index) % #screen_log_queue;\n        if screen_log_queue[adjusted_index] ~= nil then\n            GuiText( gui, 0,0, tostring(screen_log_queue[adjusted_index]) );\n        end\n        GuiLayoutAddVerticalSpacing( gui );\n    end\n    screen_log_queue = {};\nend\n\nfunction LogTable( t )\n    if type(t) == \"table\" then\n        for k,v in pairs ( t ) do\n            Log( k,v );\n        end\n    else\n        Log( t );\n    end\nend\n\nfunction LogTableCompact( t, show_keys )\n    if type(t) == \"table\" then\n        local length = 0;\n        local log = {};\n        for k,v in pairs( t ) do\n            local join = PackString( \"=\", k, v );\n            table.insert( log, join );\n            length = length + #join;\n            if length > 80 then\n                table.insert(log,\"\\n\");\n                length = 0;\n            end\n        end\n        Log( unpack( log ) );\n    else\n        Log( t );\n    end\nend\n\nfunction ExploreGlobals()\n    local g = {};\n    for k,v in pairs(_G) do\n        if type(v) ~= \"function\" then\n            g[k] = v;\n        end\n    end\n    LogTable(g);\nend\n\nfunction ListEntityComponents( entity )\n    local components = EntityGetAllComponents( entity );\n    for i, component_id in ipairs( components ) do\n        Log( i, component_id );\n    end\nend\n\nfunction ListEntityComponentObjects( entity, component_type_name, component_object_name )\n    local component = EntityGetFirstComponent( entity, component_type_name );\n    local members = ComponentObjectGetMembers( component, component_object_name );\n    for member in pairs(members) do\n        Log( member, ComponentObjectGetValue2( component, component_object_name, member ) );\n    end\nend\n\nfunction CopyEntityComponentList( component_type_name, base_entity, copy_entity, keys )\n    local base_component = EntityGetFirstComponent( base_entity, component_type_name );\n    local copy_component = EntityGetFirstComponent( copy_entity, component_type_name );\n    if base_component ~= nil and copy_component ~= nil then\n        for index,key in pairs( keys ) do\n            ComponentSetValue2( copy_component, key, ComponentGetValue2( base_component, key ) );\n        end\n    end\nend\n\nfunction CopyComponentMembers( base_component, copy_component )\n    if base_component ~= nil and copy_component ~= nil then\n        for key,value in pairs( ComponentGetMembers( base_component ) ) do\n            ComponentSetValue2( copy_component, key, ComponentGetValue2( copy_component, key, value ) );\n        end\n    end\nend\n\nfunction CopyListedComponentMembers( base_component, copy_component, ... )\n    if base_component ~= nil and copy_component ~= nil then\n        for index,key in pairs( {...} ) do\n            ComponentSetValue2( copy_component, key, ComponentGetValue2( base_component, key ) );\n        end\n    end\nend\n\nfunction CopyComponentObjectMembers( base_component, copy_component, component_object_name )\n    if base_component ~= nil and copy_component ~= nil then\n        for object_key in pairs( ComponentObjectGetMembers( base_component, component_object_name ) ) do\n            ComponentObjectSetValue2( copy_component, component_object_name, object_key, ComponentObjectGetValue2( base_component, component_object_name, object_key ) );\n        end\n    end\nend\n\nfunction CopyEntityComponent( component_type_name, base_entity, copy_entity )\n    local base_component = EntityGetFirstComponent( base_entity, component_type_name );\n    local copy_component = EntityGetFirstComponent( copy_entity, component_type_name );\n    CopyComponentMembers( base_component, copy_component );\nend\n\nfunction WandGetAbilityComponent( wand )\n    local components = EntityGetAllComponents( wand ) or {};\n    for _, component in pairs( components ) do\n        if ComponentGetTypeName( component ) == \"AbilityComponent\" then\n            return component;\n        end\n    end\nend\n\nfunction EnableWandAbilityComponent(wand_id)\n    local components = EntityGetAllComponents( wand_id );\n    for i, component_id in ipairs( components ) do\n        for k, v2 in pairs( ComponentGetMembers( component_id ) ) do\n            if k == \"mItemRecoil\" then\n                EntitySetComponentIsEnabled( wand_id, component_id, true );\n                break;\n            end\n        end\n    end\nend\n\nfunction EntityComponentGetValue( entity_id, component_type_name, component_key, default_value )\n    local component = EntityGetFirstComponent( entity_id, component_type_name );\n    if component ~= nil then return ComponentGetValue2( component, component_key ); end\n    return default_value;\nend\n\nfunction EntityGetNamedChild( entity_id, name )\n    local children = EntityGetAllChildren( entity_id ) or {};\n	if children ~= nil then\n		for index,child_entity in pairs( children ) do\n			local child_entity_name = EntityGetName( child_entity );\n			\n			if child_entity_name == name then\n				return child_entity;\n            end\n        end\n    end\nend\n\nfunction EntityGetChildrenWithTag( entity_id, tag )\n    local valid_children = {};\n    local children = EntityGetAllChildren( entity_id ) or {};\n    for index, child in pairs( children ) do\n        if EntityHasTag( child, tag ) then\n            table.insert( valid_children, child );\n        end\n    end\n    return valid_children;\nend\n\n\n\nfunction FindComponentByType( entity_id, component_type_name )\n    local components = EntityGetAllComponents( entity_id ) or {};\n    local valid_components = {};\n    for _,component in pairs( components ) do\n        if ComponentGetTypeName( component ) == component_type_name then\n            table.insert( valid_components, component );\n        end\n    end\n    return valid_components;\nend\n\nfunction FindComponentThroughTags( entity_id, ... )\n    local matching_components = EntityGetAllComponents( entity_id ) or {};\n    local valid_components = {};\n    for _,tag in pairs( {...} ) do\n        for index,component in pairs( matching_components ) do\n            if ComponentGetValue2( component, tag ) ~= \"\" and ComponentGetValue2( component, tag ) ~= nil then\n                table.insert( valid_components, component );\n            end\n        end\n        matching_components = valid_components;\n        valid_components = {};\n    end\n    return matching_components;\nend\n\nfunction FindFirstComponentThroughTags( entity_id, ... )\n    return FindComponentThroughTags( entity_id, ...)[1];\nend\n\nfunction ComponentGetValueDefault( component_id, key, default )\n    local value = ComponentGetValue2( component_id, key );\n    if value ~= nil then\n        return value;\n    end\n    return default;\nend\n\nfunction GetEntityCustomVariable( entity_id, variable_storage_tag, key, default )\n   local variable_storage = EntityGetFirstComponent( entity_id, \"VariableStorage\", variable_storage_tag );\n   if variable_storage ~= nil then\n        return ComponentGetValue2( variable_storage, \"value_string\" );\n   end\n   return default;\nend\n\nfunction SetEntityCustomVariable( entity_id, variable_storage_tag, variable_name, value )\n    local variable_storage = EntityGetFirstComponent( entity_id, \"VariableStorage\", variable_storage_tag );\n    if variable_storage == nil then\n        EntityAddComponent( entity_id, \"VariableStorage\", {\n            _tags=tag,\n            name=variable_name,\n            value_string=tostring(value),\n        });\n    else\n        ComponentSetValue2( variable_storage, \"value_string\", tostring(value) );\n    end\nend\n\nfunction GetWandActions( wand )\n    local actions = {};\n    local children = EntityGetAllChildren( wand ) or {};\n    for i,v in ipairs( children ) do\n        local item = EntityGetFirstComponentIncludingDisabled( v, \"ItemComponent\" );\n        local item_action = EntityGetFirstComponentIncludingDisabled( v, \"ItemActionComponent\" );\n        if item and item_action then\n            local action_id = ComponentGetValue2( item_action, \"action_id\" );\n            local permanent = ComponentGetValue2( item, \"permanently_attached\" );\n            local x, y = ComponentGetValue2( item, \"inventory_slot\" );\n            if action_id ~= nil then\n                table.insert( actions, { action_id = action_id, permanent = permanent, x = x, y = y } );\n            end\n        end\n    end\n    return actions;\nend\n\nfunction CopyWandActions( base_wand, copy_wand )\n    local actions = GetWandActions( base_wand );\n    for index,action_data in pairs( actions ) do\n        local action_entity = CreateItemActionEntity( action_data.action_id );\n        local item = EntityGetFirstComponentIncludingDisabled( action_entity, \"ItemComponent\" );\n        if action_data.permanent then\n            ComponentSetValue2( item, \"permanently_attached\", true );\n        end\n        if ComponentSetValue2 and action_data.x ~= nil and action_data.y ~= nil then\n            ComponentSetValue2( item, \"inventory_slot\", action_data.x, action_data.y );\n        end\n        EntitySetComponentsWithTagEnabled( action_entity, \"enabled_in_world\", false );\n        EntityAddChild( copy_wand, action_entity );\n    --[[\n        if action_data.permanent ~= \"1\" then\n            AddGunAction( copy_wand, action_data.action_id );\n        else\n            AddGunActionPermanent( copy_wand, action_data.action_id );\n        end\n        ]]\n    end\nend\n\nfunction FindEntityInInventory( inventory, entity )\n    local inventory_items = EntityGetAllChildren( inventory )  or {};\n		\n    -- remove default items\n    if inventory_items ~= nil then\n        for i,item_entity in ipairs( inventory_items ) do\n            --Log( i, item_entity );\n        end\n        --    GameKillInventoryItem( player_entity, item_entity )\n        --end\n    end\nend\n\nfunction TryGivePerk( player_entity_id, ... )\n    for index,perk_id in pairs( {...} ) do\n        local perk_entity = perk_spawn( x, y, perk_id );\n        if perk_entity ~= nil then\n            perk_pickup( perk_entity, player_entity_id, EntityGetName( perk_entity ), false, false );\n        end\n    end\nend\n\nfunction TryAdjustDamageMultipliers( entity, resistances )\n    local damage_models = EntityGetComponent( entity, \"DamageModelComponent\" );\n    if damage_models ~= nil then\n        for index,damage_model in pairs( damage_models ) do\n            for damage_type,multiplier in pairs( resistances ) do\n                local resistance = ComponentObjectGetValue2( damage_model, \"damage_multipliers\", damage_type );\n                resistance = resistance * multiplier;\n                ComponentObjectSetValue2( damage_model, \"damage_multipliers\", damage_type, resistance );\n            end\n        end\n    end\nend\n\n\n--[[\n    ice\n    electricity\n    radioactive\n    slice\n    projectile\n    healing\n    physics_hit\n    explosion\n    poison\n    melee\n    drill\n    fire\n]]\n\nfunction TryAdjustMaxHealth( entity, callback )\n    local damage_models = EntityGetComponent( entity, \"DamageModelComponent\" );\n    if damage_models ~= nil then\n        for index,damage_model in pairs( damage_models ) do\n            local current_hp = ComponentGetValue2( damage_model, \"hp\" );\n            local max_hp = ComponentGetValue2( damage_model, \"max_hp\" );\n            local new_max = callback( max_hp, current_hp );\n            local regained = new_max - current_hp;\n            ComponentSetValue2( damage_model, \"max_hp\", new_max );\n            ComponentSetValue2( damage_model, \"hp\", current_hp + regained );\n        end\n    end\nend\n\nfunction GetInventoryQuickActiveItem( entity )\n    if entity ~= nil then\n        local component = EntityGetFirstComponent( entity, \"Inventory2Component\" );\n        if component ~= nil then\n            return ComponentGetValue2( component, \"mActiveItem\" );\n        end\n    end\nend\n\nfunction CreateWand( x, y, ... )\n    local wand = EntityLoad(\"mods/gkbrkn_noita/files/gkbrkn/placeholder_wand.xml\", x, y);\n    for _,action in pairs( {...} ) do\n        AddGunAction( wand, action );\n    end\n    return wand;\nend\n\nfunction adjust_material_damage( damage_model, callback )\n    local materials_that_damage = ComponentGetValue2( damage_model, \"materials_that_damage\" );\n    local materials = {};\n    for word in string.gmatch( materials_that_damage, '([^,]+)' ) do\n        table.insert( materials, word );\n    end\n\n    local materials_how_much_damage = ComponentGetValue2( damage_model, \"materials_how_much_damage\" );\n    local materials_damage = {};\n    for word in string.gmatch( materials_how_much_damage, '([^,]+)' ) do\n        table.insert( materials_damage, tonumber(word) );\n    end\n\n    local new_materials, new_materials_damage = callback( materials, materials_damage );\n\n    local new_materials_that_damage = \"\";\n    for _,word in pairs( new_materials ) do\n        new_materials_that_damage = new_materials_that_damage..word..\",\";\n    end\n    ComponentSetValue2( damage_model, \"materials_that_damage\", new_materials_that_damage );\n\n    local new_materials_how_much_damage = \"\";\n    for _,word in pairs( new_materials_damage ) do\n        new_materials_how_much_damage = new_materials_how_much_damage..tostring(word)..\",\";\n    end\n    ComponentSetValue2( damage_model, \"materials_how_much_damage\", new_materials_how_much_damage );\nend\n\nfunction EntityIterateComponentsByType( entity, component_type_name, callback )\n    local matched_components = {};\n    local components = EntityGetAllComponents( entity ) or {};\n    for _,component in pairs(components) do\n        if ComponentGetTypeName( component ) == component_type_name then\n            table.insert( matched_components, component );\n        end\n    end\n    if callback ~= nil then\n        for _,component in pairs(matched_components) do\n            callback( component );\n        end\n    end\n    return matched_components;\nend\n\nfunction EntityGetHitboxCenter( entity )\n    local tx, ty = EntityGetTransform( entity );\n    local hitbox = EntityGetFirstComponent( entity, \"HitboxComponent\" );\n    if hitbox ~= nil then\n        local width = ComponentGetValue2( hitbox, \"aabb_max_x\" ) - ComponentGetValue2( hitbox, \"aabb_min_x\" );\n        local height = ComponentGetValue2( hitbox, \"aabb_max_y\" ) - ComponentGetValue2( hitbox, \"aabb_min_y\" );\n        tx = tx + ComponentGetValue2( hitbox, \"aabb_min_x\" ) + width * 0.5;\n        ty = ty + ComponentGetValue2( hitbox, \"aabb_min_y\" ) + height * 0.5;\n    end\n    return tx, ty;\nend\n\nfunction EntityGetFirstHitboxSize( entity, fallbackWidth, fallbackHeight )\n    local hitbox = EntityGetFirstComponent( entity, \"HitboxComponent\" );\n\n    local width = fallbackWidth or 0;\n    local height = fallbackHeight or 0;\n    if hitbox ~= nil then\n        width =  ComponentGetValue2( hitbox, \"aabb_max_x\" ) - ComponentGetValue2( hitbox, \"aabb_min_x\" );\n        height =  ComponentGetValue2( hitbox, \"aabb_max_y\" ) - ComponentGetValue2( hitbox, \"aabb_min_y\" );\n    end\n    return width, height;\nend\n\nfunction EntitySetVelocity( entity, x, y )\n    EntityIterateComponentsByType( entity, \"VelocityComponent\", function( component )\n        ComponentSetValue2( component, \"mVelocity\", x, y );\n    end );\nend\n\n\nfunction EaseAngle( angle, target_angle, easing )\n    local dir = (angle - target_angle) / (math.pi*2);\n    dir = dir - math.floor(dir + 0.5);\n    dir = dir * (math.pi*2);\n    return angle - dir * easing;\nend\n\nfunction WeightedRandom( items, weights, sum )\n    if weights == nil  then\n        weights = {};\n        for k,v in pairs( items ) do \n            weights[k] = 1;\n        end\n        sum = items.length;\n    end\n    if sum == nil then\n        sum = 0;\n        for k,v in pairs( weights ) do\n            sum = sum + v;\n        end\n    end\n    if sum <= 0 then\n        return nil;\n    end\n    local random = Random() * sum;\n    for k,v in pairs(items) do\n        local weight = weights[k];\n        if random <= weight then\n            return items[k];\n        end\n        random = random - weight;\n    end\nend\n\nfunction WeightedRandomTable( entries )\n    local sum = 0;\n    for k,v in pairs( entries ) do\n        sum = sum + v;\n    end\n    if sum <= 0 then\n        return nil;\n    end\n    local random = Random() * sum;\n    for k,v in pairs( entries ) do\n        if random <= v then\n            return k;\n        end\n        random = random - v;\n    end\nend\n\nfunction EntityHasScript( entity, filepath, script_type )\n    if script_type == nil then\n        script_type = \"script_source_file\";\n    end\n    for _,lua_component in pairs( EntityGetComponentIncludingDisabled(entity,\"LuaComponent\") or {}) do\n        if ComponentGetValue2( lua_component, script_type ) == filepath then\n            return true;\n        end\n    end\n    return false;\nend"
_TWWE_VFS["mods/wand_editor/files/misc/bygoki/lib/action_data.lua"] = "dofile_once( \"data/scripts/gun/gun_enums.lua\" );\ndofile_once( \"data/scripts/gun/gun_actions.lua\" );\n\nreturn function( include_locked )\n    local action_data = {};\n    for k,action in pairs( actions ) do\n        if ( include_locked == true or is_action_unlocked( action ) ) then\n            action_data[action.id] = action;\n            action_data[action.id].enabled = true;\n        end\n    end\n    for k,action in pairs( actions_cache ) do\n        if action_data[action.id] == nil then\n            if ( include_locked == true or is_action_unlocked( action ) ) then\n                action_data[action.id] = action;\n                action_data[action.id].enabled = false;\n            end\n        end\n    end\n    return action_data;\nend"
_TWWE_VFS["mods/wand_editor/files/misc/bygoki/lib/constants.lua"] = "GKBRKN_PROJECTILE_CAPTURE = {\n    None = 0,\n    SpellMerge = 1,\n    ProjectileGravityWell = 2,\n    ProjectileOrbit = 4,\n    LinkShot = 8,\n    FormationStack = 16,\n    TrailingShot = 32,\n}"
_TWWE_VFS["mods/wand_editor/files/misc/bygoki/lib/flags.lua"] = "FLAGS = {\n    SpellShopsOnly = \"gkbrkn_spell_shops_only\",\n    WandShopsOnly = \"gkbrkn_wand_shops_only\",\n    RemoveGenericWands = \"gkbrkn_remove_generic_wands\",\n    NoWandGeneration = \"gkbrkn_no_wand_generation\",\n    GooMode = \"gkbrkn_goo_mode\",\n    HotGooMode = \"gkbrkn_hot_goo_mode\",\n    KillerGooMode = \"gkbrkn_killer_goo_mode\",\n    AltKillerGooMode = \"gkbrkn_alt_killer_goo_mode\",\n    PolyGooMode = \"gkbrkn_poly_goo_mode\",\n    NoWandEditing = \"gkbrkn_no_wand_editing\",\n    NoHit = \"gkbrkn_no_hit\",\n    LimitedAmmo = \"gkbrkn_limited_ammo\",\n    UnlimitedAmmo = \"gkbrkn_unlimited_ammo\",\n    ShuffleWandsOnly = \"gkbrkn_shuffle_wands_only\",\n    OrderWandsOnly = \"gkbrkn_order_wands_only\",\n    GuaranteedAlwaysCast = \"gkbrkn_guaranteed_always_cast\",\n    FreeShops = \"gkbrkn_free_shops\",\n    InfiniteFlight = \"gkbrkn_infinite_flight\",\n    FloorIsLava = \"gkbrkn_floor_is_lava\",\n    DisintegrateCorpses = \"gkbrkn_disintegrate_corpses\",\n    KeepMoving = \"gkbrkn_keep_moving\",\n    DebugMode = \"gkbrkn_debug_mode\",\n    ShowDeprecatedContent = \"gkbrkn_show_deprecated_content\",\n    AngryGods = \"gkbrkn_angry_gods\",\n    CalmGods = \"gkbrkn_calm_gods\",\n    HitsTeleportToLastHolyMountain = \"gkbrkn_no_hit_lite\",\n    ConfigMenuOpen = \"gkbrkn_config_menu_open\",\n    KickSpellsOffWands = \"gkbrkn_kick_spells_off_wands\",\n    KickSpellsAround = \"gkbrkn_kick_spells_around\",\n    EnemyInvincibilityFrames = \"gkbrkn_enemy_invincibility_frames\",\n    EnemyIntangibilityFrames = \"gkbrkn_enemy_intangibility_frames\",\n    SkipGokiLoadouts = \"gkbrkn_skip_goki_loadouts\",\n    FixLoadoutIntegration = \"gkbrkn_fix_loadout_integration\",\n    DelayInit = \"gkbrkn_delay_init\",\n    DisableRandomSpells = \"gkbrkn_game_modifier_disable_random_spells\",\n    GenerateRandomSpellbooks = \"gkbrkn_game_modifier_generate_random_spellbooks\",\n    RebalanceShops = \"gkbrkn_rebalance_shops\",\n    UberBoss = \"gkbrkn_uber_boss\",\n    UberBossCount = \"gkbrkn_uber_boss_count\",\n    PolymorphImmunity = \"gkbrkn_polymorph_immunity\",\n    ShowHitboxes = \"gkbrkn_show_hitboxes\",\n    EnableLogging = \"gkbrkn_enable_logging\",\n    DisableNewContent = \"gkbrkn_disable_new_content\",\n    ShowWhileInInventory = \"gkbrkn_show_while_in_inventory\",\n    ShowSpellProgress = \"gkbrkn_show_spell_progress\",\n    ShowSpellBorders = \"gkbrkn_show_spell_borders\",\n    ShowSpellDescriptions = \"gkbrkn_show_spell_descriptions\",\n    SpellSortMethod = \"gkbrkn_spell_sort_method\",\n    NoDamageFlashing = \"gkbrkn_no_damage_flashing\",\n    NoLowHealthWarning = \"gkbrkn_no_low_health_warning\",\n    TargetDummyShowRealTimeDPS = \"gkbrkn_target_dummy_real_time_dps\",\n    TargetDummyShowHighestDPS = \"gkbrkn_target_dummy_highest_dps\",\n}"
_TWWE_VFS["mods/wand_editor/files/misc/bygoki/lib/gokiui.lua"] = "return function( gui, gui_id, mod_settings_id, z_index )\n    local full_screen_width, full_screen_height = GuiGetScreenDimensions( gui );\n    GuiStartFrame( gui );\n    local screen_width, screen_height = GuiGetScreenDimensions( gui );\n    local id_offset = 0;\n    local current_tab = nil;\n    local mod_settings = nil;\n    local z_index = z_index or 0;\n     \n    local function previous_data( gui )\n        local left_click,right_click,hover,x,y,width,height,draw_x,draw_y = GuiGetPreviousWidgetInfo( gui );\n        if left_click == 1 then left_click = true; elseif left_click == 0 then left_click = false; end\n        if right_click == 1 then right_click = true; elseif right_click == 0 then right_click = false; end\n        if hover == 1 then hover = true; elseif hover == 0 then hover = false; end\n        return left_click,right_click,hover,x,y,width,height,draw_x,draw_y;\n    end\n\n    local function word_wrap( str, wrap_size )\n        if str then\n            if wrap_size == nil then wrap_size = 60; end\n            local last_space_index = 1;\n            local last_wrap_index = 0;\n            for i=1,#str do\n                if str:sub(i,i) == \" \" then\n                    last_space_index = i;\n                end\n                if str:sub(i,i) == \"\\n\" then\n                    last_space_index = i;\n                    last_wrap_index = i;\n                end\n                if i - last_wrap_index > wrap_size then\n                    str = str:sub(1,last_space_index-1) .. \"\\n\" .. str:sub(last_space_index + 1);\n                    last_wrap_index = i;\n                end\n            end\n            return str;\n        end\n        return \"\";\n    end\n\n    local function reset_id()\n        id_offset = 1;\n    end\n\n    local function next_id( amount )\n        if amount == nil then amount = 1; end\n        local current_id = id_offset + 1;\n        id_offset = id_offset + amount;\n        return gui_id + current_id;\n    end\n\n    local function iterate_settings( callback, settings )\n        if settings == nil then settings = mod_settings; end\n        for _,setting in pairs( settings or {} ) do\n            if setting then\n                if setting.settings ~= nil then\n                    iterate_settings( callback, setting.settings );\n                else\n                    callback( setting );\n                end\n            end\n        end\n    end\n\n    local function refresh_settings()\n        iterate_settings( function( setting )\n            setting.current = ModSettingGet( mod_settings_id..\".\"..setting.key );\n        end );\n    end\n\n    local is_panel_open = false;\n    local has_been_parsed = false;\n    local function parse_mod_settings( parse_mod_settings, disable_new_settings )\n        mod_settings = parse_mod_settings;\n        if not has_been_parsed then\n            has_been_parsed = true;\n            local function parse_setting( setting )\n                if setting.group_label ~= nil or setting.tab_label ~= nil then\n                    for k,v in pairs( setting.settings ) do\n                        parse_setting( v );\n                    end\n                else\n                    if setting.default ~= nil then\n                        if ModSettingGet( mod_settings_id..\".\"..setting.key ) == nil then\n                            if disable_new_settings == true then\n                                ModSettingSet( mod_settings_id..\".\"..setting.key, setting.disable );\n                            else\n                                ModSettingSet( mod_settings_id..\".\"..setting.key, setting.default );\n                            end\n                        end\n                        setting.current = ModSettingGet( mod_settings_id..\".\"..setting.key );\n                        --for k,v in pairs( setting ) do\n                        --    print( \"setting \"..k..\"/\"..tostring(v))\n                        --end\n                    end\n                end\n            end\n            for _,setting in ipairs( mod_settings ) do\n                parse_setting( setting );\n            end\n        end\n    end\n\n    local function do_boolean( gui, id, setting_key, x, y, label, value, tooltip )\n        GuiLayoutBeginHorizontal( gui, x, y );\n            local left_click, right_click = GuiImageButton( gui, id, 0, 1, \"\", \"mods/gkbrkn_noita/files/gkbrkn/gui/checkbox\" .. (value == true and \"_fill\" or \"\") .. \".png\" );\n            if value == false then\n                GuiColorSetForNextWidget( gui, 0.60, 0.60, 0.60, 1.0 );\n            end\n            if GuiButton( gui, next_id(), 0, 0,  GameTextGetTranslatedOrNot( label ) ) then\n                left_click = true;\n            end\n            if left_click == true then\n                ModSettingSet( setting_key, not value );\n            end\n            if tooltip then\n                GuiTooltip( gui, word_wrap( GameTextGetTranslatedOrNot( tooltip ) ), \"\");\n            end\n        GuiLayoutEnd( gui );\n    end\n\n    local function do_range( gui, id, setting_key, x, y, label, value, default, min, max, value_callback, text_callback, tooltip )\n        GuiLayoutBeginHorizontal( gui, x, y );\n            if value == default then GuiColorSetForNextWidget( gui, 0.60, 0.60, 0.60, 1.0 ); end\n            GuiText( gui, 0, 0, label );\n            if tooltip then GuiTooltip( gui, word_wrap( GameTextGetTranslatedOrNot( tooltip ) ), \"\"); end\n            local new_value = GuiSlider( gui, id, -2, 1, \"\", value, min, max, default, 1.0, \" \", 100 );\n            if value_callback ~= nil then\n                new_value = value_callback( new_value );\n            end\n            if value ~= new_value then\n                value = new_value;\n                ModSettingSet( setting_key, value );\n            end\n            if value == default then GuiColorSetForNextWidget( gui, 0.60, 0.60, 0.60, 1.0 ); end\n            if text_callback then\n                GuiText( gui, 2, 0, text_callback( value ) );\n            else\n                GuiText( gui, 2, 0, tostring( value ) );\n            end\n            GuiLayoutAddVerticalSpacing( gui, 20 );\n        GuiLayoutEnd( gui );\n    end\n\n    local gui_functions = {\n        button = function( setting )\n            if setting.type_data.click_callback then\n                setting.type_data.click_callback( GuiButton( gui, next_id(), 0, 0, setting.label ) );\n                if setting.tooltip then GuiTooltip( gui, word_wrap( GameTextGetTranslatedOrNot( setting.tooltip ) ), \"\"); end\n            end\n        end,\n        boolean = function( setting )\n            local toggle = false;\n            if GuiImageButton( gui, next_id(), 0, 1, \"\", \"mods/gkbrkn_noita/files/gkbrkn/gui/checkbox\" .. (setting.current == true and \"_fill\" or \"\") .. \".png\" ) then toggle = true; end\n            if setting.current == false then GuiColorSetForNextWidget( gui, 0.60, 0.60, 0.60, 1.0 ); end\n            if GuiButton( gui, next_id(), 0, 0, setting.label ) then toggle = true; end\n            if setting.tooltip then GuiTooltip( gui, word_wrap( GameTextGetTranslatedOrNot( setting.tooltip ) ), \"\"); end\n            if toggle == true then\n                setting.current = not setting.current;\n                ModSettingSet( mod_settings_id..\".\"..setting.key, setting.current );\n            end\n        end,\n        range = function( setting )\n            if setting.current == setting.default then GuiColorSetForNextWidget( gui, 0.60, 0.60, 0.60, 1.0 ); end\n            GuiText( gui, 0, 0, setting.label );\n            if setting.tooltip then GuiTooltip( gui, word_wrap( GameTextGetTranslatedOrNot( setting.tooltip ) ), \"\"); end\n            local new_value = GuiSlider( gui, next_id(), -2, 1, \"\", setting.current, setting.type_data.min, setting.type_data.max, setting.default, 1.0, \" \", 100 );\n            if setting.type_data.value_callback ~= nil then\n                new_value = setting.type_data.value_callback( new_value );\n            end\n            if setting.current ~= new_value then\n                setting.current = new_value;\n                ModSettingSet( mod_settings_id..\".\"..setting.key, setting.current );\n            end\n            if setting.current == setting.default then GuiColorSetForNextWidget( gui, 0.60, 0.60, 0.60, 1.0 ); end\n            if setting.type_data.text_callback then\n                GuiText( gui, 2, 0, setting.type_data.text_callback( setting.current ) );\n            else\n                GuiText( gui, 2, 0, tostring( setting.current ) );\n            end\n            GuiLayoutAddVerticalSpacing( gui, 20 );\n        end,\n        input = function( setting )\n            GuiText( gui, 0, 0, setting.label );\n            if setting.tooltip then GuiTooltip( gui, word_wrap( GameTextGetTranslatedOrNot( setting.tooltip ) ), \"\"); end\n            local new_value = GuiTextInput( gui, next_id(), 0, 0, setting.current, 200, 100 );\n            if setting.current ~= new_value then\n                setting.current = new_value;\n                ModSettingSet( mod_settings_id..\".\"..setting.key, setting.current );\n            end\n        end\n    }\n\n    function do_custom_tooltip( callback, z, x_offset, y_offset )\n        if z == nil then z = -12; end\n        local left_click,right_click,hover,x,y,width,height,draw_x,draw_y,draw_width,draw_height = previous_data( gui );\n        local screen_width,screen_height = GuiGetScreenDimensions( gui );\n        if x_offset == nil then x_offset = 0; end\n        if y_offset == nil then y_offset = 0; end\n        if draw_y > screen_height * 0.5 then\n            y_offset = y_offset - height;\n        end\n        if hover then\n            local screen_width, screen_height = GuiGetScreenDimensions( gui );\n            GuiZSet( gui, z );\n            GuiLayoutBeginLayer( gui );\n                GuiLayoutBeginVertical( gui, ( x + x_offset + width * 2 ) / screen_width * 100, ( y + y_offset ) / screen_height * 100 );\n                    GuiBeginAutoBox( gui );\n                        if callback ~= nil then callback(); end\n                        GuiZSetForNextWidget( gui, z + 1 );\n                    GuiEndAutoBoxNinePiece( gui );\n                GuiLayoutEnd( gui );\n            GuiLayoutEndLayer( gui );\n        end\n    end\n\n    local function do_setting( setting )\n        if setting.hidden ~= true then\n            if setting.tab_key ~= nil then\n                -- Individual Tabs\n                GuiLayoutBeginHorizontal( gui, 0, 0 );\n                    GuiLayoutBeginVertical( gui, 0, 0 );\n                        local settings_sum = 0;\n                        for g,v in ipairs( setting.settings ) do\n                            settings_sum = settings_sum + #v.settings;\n                        end\n                        local setting_index = 0;\n                        for g,v in ipairs( setting.settings ) do\n                            do_setting( v );\n                            setting_index = setting_index + #v.settings;\n                            if setting_index > settings_sum / setting.columns then\n                                setting_index = setting_index - settings_sum / setting.columns;\n                                GuiLayoutEnd( gui );\n                                GuiLayoutBeginVertical( gui, 33, 0 );\n                            end\n                        end\n                    GuiLayoutEnd( gui );\n                GuiLayoutEnd( gui );\n            elseif setting.group_label ~= nil then\n                -- Individual Groups\n                if setting.custom_callback ~= nil then\n                    setting:custom_callback();\n                else\n                    GuiColorSetForNextWidget( gui, 1.0, 0.75, 0.5, 1.0 );\n                    GuiText( gui, 0, 0, setting.group_label );\n                    GuiLayoutAddVerticalSpacing( gui, 2 );\n                    for k,v in pairs( setting.settings ) do\n                        do_setting( v );\n                    end\n                    GuiLayoutAddVerticalSpacing( gui, 5 );\n                end\n            else\n                -- Individual Settings\n                GuiLayoutBeginHorizontal( gui, 1, 0 );\n                    if gui_functions[setting.type] then\n                        gui_functions[setting.type]( setting );\n                        if setting.validation_callback then\n                            local result = setting.validation_callback( setting.current );\n                            if result ~= true then\n                                GuiTooltip( gui, word_wrap( result ), \"\" );\n                            end\n                        end\n                    else\n                        print( \"[gokiui] missing gui function \"..setting.type );\n                    end\n                GuiLayoutEnd( gui );\n                if setting.type == \"range\" then\n                    --GuiLayoutAddVerticalSpacing( gui, -2 );\n                elseif setting.type == \"input\" then\n                    GuiLayoutAddVerticalSpacing( gui, -2 );\n                end\n            end\n        end\n    end\n\n    local function do_gui()\n        if GlobalsGetValue(\"gkbrkn_force_settings_refresh\",\"0\") == \"1\" then\n            refresh_settings();\n            GlobalsSetValue(\"gkbrkn_force_settings_refresh\",\"0\");\n        end\n        local current_tab_index = 0;\n        local scroll_container_ids = next_id( #mod_settings );\n        GuiLayoutBeginVertical( gui, 0, 0 );\n            GuiLayoutBeginHorizontal( gui, 0, 0 );\n                for i,setting in ipairs( mod_settings ) do\n                    if current_tab == nil and setting.tab_key then\n                        current_tab = current_tab or setting.tab_key;\n                    end\n                    GuiBeginAutoBox( gui );\n                        local was_selected = false;\n                        if current_tab == setting.tab_key then\n                            GuiZSetForNextWidget( gui, z_index - 2 );\n                            current_tab_index = i;\n                            was_selected = true;\n                        else\n                            GuiZSetForNextWidget( gui, z_index );\n                            GuiColorSetForNextWidget( gui, 0.5, 0.5, 0.5, 1.0 );\n                        end\n                        if GuiButton( gui, next_id(), 0, 0, \" \"..GameTextGetTranslatedOrNot( setting.tab_label )..\" \" ) then\n                            current_tab = setting.tab_key;\n                            current_tab_index = i;\n                        end\n                        GuiLayoutAddHorizontalSpacing( gui, 0 );\n                        if was_selected then\n                            GuiZSetForNextWidget( gui, z_index - 1 );\n                        else\n                            GuiZSetForNextWidget( gui, z_index + 10 );\n                        end\n                    GuiEndAutoBoxNinePiece( gui, 0, nil, nil, nil, nil, \"mods/gkbrkn_noita/files/gkbrkn/gui/9piece_tab.png\", \"mods/gkbrkn_noita/files/gkbrkn/gui/9piece_tab.png\" );\n                end\n            GuiLayoutEnd( gui );\n\n            GuiZSetForNextWidget( gui, z_index + 2 );\n            GuiBeginScrollContainer( gui, scroll_container_ids + (current_tab_index - 1), 0, 0, screen_width - screen_width * 0.12, screen_height - screen_height * 0.30, false );\n                do_setting( mod_settings[current_tab_index] );\n            GuiEndScrollContainer( gui );\n            -- keep the other scroll containers drawing so their scroll position is maintained (doesn't really look that good anyway)\n            --[[\n            for i=1,#mod_settings do\n                if i ~= current_tab_index then\n                    GuiOptionsAddForNextWidget( gui, GUI_OPTION.Layout_NoLayouting );\n                    GuiBeginScrollContainer( gui, scroll_container_ids + (i - 1), 0, 0, -1000, -1000, false );\n                    GuiEndScrollContainer( gui );\n                end\n            end\n            ]]\n        GuiLayoutEnd( gui );\n    end\n\n    return {\n        do_boolean = do_boolean,\n        do_range = do_range,\n        do_setting = do_setting,\n        do_custom_tooltip = do_custom_tooltip,\n        reset_id = reset_id,\n        next_id = next_id,\n        parse_mod_settings = parse_mod_settings,\n        do_gui = do_gui,\n        gui_functions = gui_functions,\n        iterate_settings = iterate_settings,\n        refresh_settings = refresh_settings,\n    }\nend"
_TWWE_VFS["mods/wand_editor/files/misc/bygoki/lib/helper.lua"] = "local MISC = dofile_once(\"mods/wand_editor/files/misc/bygoki/lib/options.lua\");\ndofile_once(\"mods/wand_editor/files/misc/bygoki/lib/variables.lua\");\n--[[\n#define ENUM_DAMAGE_TYPES(_)                  \n    _(DAMAGE_MELEE,                  1 << 0 ) \n    _(DAMAGE_PROJECTILE,             1 << 1 ) \n    _(DAMAGE_EXPLOSION,              1 << 2 ) \n    _(DAMAGE_BITE,                   1 << 3 ) \n    _(DAMAGE_FIRE,                   1 << 4 ) \n    _(DAMAGE_MATERIAL,               1 << 5 ) \n    _(DAMAGE_FALL,                   1 << 6 ) \n    _(DAMAGE_ELECTRICITY,            1 << 7 ) \n    _(DAMAGE_DROWNING,               1 << 8 ) \n    _(DAMAGE_PHYSICS_BODY_DAMAGED,   1 << 9 ) \n    _(DAMAGE_DRILL,                  1 << 10 )\n    _(DAMAGE_SLICE,                  1 << 11 )\n    _(DAMAGE_ICE,                    1 << 12 )\n    _(DAMAGE_HEALING,                1 << 13 )\n    _(DAMAGE_PHYSICS_HIT,            1 << 14 )\n    _(DAMAGE_RADIOACTIVE,            1 << 15 )\n    _(DAMAGE_POISON,                 1 << 16 )\n    _(DAMAGE_MATERIAL_WITH_FLASH,    1 << 17 )\n    _(DAMAGE_OVEREATING,             1 << 18 )\n\n#define ENUM_RAGDOLL_FX(_)\n    _(NONE,                     0)\n    _(NORMAL,                   1)\n    _(BLOOD_EXPLOSION,          2)\n    _(BLOOD_SPRAY,              3)\n    _(FROZEN,                   4)\n    _(CONVERT_TO_MATERIAL,      5)\n    _(CUSTOM_RAGDOLL_ENTITY,    6)\n    _(DISINTEGRATED,            7)\n    _(NO_RAGDOLL_FILE,          8)\n    _(PLAYER_RAGDOLL_CAMERA,    9)\n]]\n\nfunction load_dynamic_badge ( key, append_bool_table )\n    local badge_image = \"ui_icon_image_\"..key;\n    local badge_name = \"ui_icon_name_\"..key;\n    local badge_description = \"ui_icon_description_\"..key;\n    if append_bool_table ~= nil then\n        for _,pair in ipairs(append_bool_table) do\n            for append,bool in pairs(pair) do\n                if bool then\n                    badge_image = badge_image .. append;\n                    badge_name = badge_name .. append;\n                    badge_description = badge_description .. append;\n                end\n            end\n        end\n    end\n    local badge = EntityLoad( \"mods/gkbrkn_noita/files/gkbrkn/badges/badge.xml\" );\n    if badge ~= nil then\n        local ui_icon = EntityGetFirstComponent( badge, \"UIIconComponent\" );\n        if ui_icon ~= nil then\n            ComponentSetValue2( ui_icon, \"icon_sprite_file\", GameTextGetTranslatedOrNot(\"$\"..badge_image) );\n            ComponentSetValue2( ui_icon, \"name\", GameTextGetTranslatedOrNot(\"$\"..badge_name) );\n            ComponentSetValue2( ui_icon, \"description\", GameTextGetTranslatedOrNot(\"$\"..badge_description) );\n            ComponentSetValue2( ui_icon, \"is_perk\", true );\n        end\n    end\n    return badge;\nend\n\nfunction get_update_time( ) return tonumber( GlobalsGetValue( \"gkbrkn_update_time\" ) ) or 0; end\nfunction reset_update_time( ) GlobalsSetValue( \"gkbrkn_update_time\", 0 ); end\nfunction get_frame_time( ) return tonumber( GlobalsGetValue( \"gkbrkn_frame_time\" ) ) or 0; end\nfunction reset_frame_time( ) GlobalsSetValue( \"gkbrkn_frame_time\", 0 ); end\nfunction add_update_time( amount ) GlobalsSetValue( \"gkbrkn_update_time\", get_update_time() + amount ); end\nfunction add_frame_time( amount ) GlobalsSetValue( \"gkbrkn_frame_time\", get_frame_time() + amount ); end\n\nfunction generate_perk_entry( perk_id, key, usable_by_enemies, pickup_function, deprecated, author, stackable )\n    if stackable == nil then\n        stackable = true;\n    end\n    return {\n        id                  = perk_id,\n        ui_name             = \"$perk_name_gkbrkn_\"..key,\n        ui_description      = \"$perk_desc_gkbrkn_\"..key,\n        ui_icon             = \"mods/gkbrkn_noita/files/gkbrkn/perks/\"..key..\"/icon_ui.png\",\n        perk_icon           = \"mods/gkbrkn_noita/files/gkbrkn/perks/\"..key..\"/icon_ig.png\",\n        usable_by_enemies   = usable_by_enemies,\n        func                = pickup_function,\n        deprecated          = deprecated,\n        author              = author or \"goki_dev\",\n        local_content       = true,\n        stackable           = stackable\n    };\nend\n\nfunction generate_action_entry( action_id, key, action_type, spawn_level, spawn_probability, price, mana, max_uses, custom_xml, action_function, deprecated, icon_path, author, related_projectiles, enabled_by_default )\n    return {\n        id = action_id,\n        name 		        = \"$action_name_gkbrkn_\"..key,\n        description         = \"$action_desc_gkbrkn_\"..key,\n        sprite 		        = icon_path or \"mods/gkbrkn_noita/files/gkbrkn/actions/\"..key..\"/icon.png\",\n        sprite_unidentified = icon_path or \"mods/gkbrkn_noita/files/gkbrkn/actions/\"..key..\"/icon.png\",\n        type 		        = action_type,\n        spawn_level         = spawn_level,\n        spawn_probability   = spawn_probability,\n        price               = price,\n        mana                = mana,\n        max_uses            = max_uses,\n        custom_xml_file     = custom_xml,\n        action              = action_function,\n        deprecated          = deprecated,\n        author              = author or \"goki_dev\",\n        related_projectiles = related_projectiles,\n        local_content       = true,\n        enabled_by_default  = enabled_by_default\n    };\nend\n\nfunction spawn_gold_nuggets( gold_value, x, y, blood_money )\n    local sizes = { 10000, 1000, 200, 50, 10 };\n    local world_entity_id = GameGetWorldStateEntity();\n    local world_state = EntityGetFirstComponent( world_entity_id, \"WorldStateComponent\" );\n    local is_gold_forever = false;\n    if world_state ~= nil then\n        is_gold_forever = ComponentGetValue2( world_state, \"perk_gold_is_forever\" );\n    end\n    for _,size in pairs(sizes) do\n        while gold_value >= size do\n            gold_value = gold_value - size;\n            local gold_nugget = EntityLoad( \"data/entities/items/pickup/goldnugget_\"..size..\".xml\", x, y );\n            if is_gold_forever then\n                EntityRemoveComponent( gold_nugget, EntityGetFirstComponent( gold_nugget, \"LifetimeComponent\" ) );\n            end\n        end\n    end\nend\n\nfunction does_entity_drop_gold( entity )\n    local drops_gold = false;\n    for _,component in pairs( EntityGetComponent( entity, \"LuaComponent\" ) or {} ) do\n        if ComponentGetValue2( component, \"script_death\" ) == \"data/scripts/items/drop_money.lua\" then\n            drops_gold = true;\n            break;\n        end\n    end\n    if drops_gold == true then\n        if EntityGetFirstComponent( entity, \"VariableStorageComponent\", \"no_drop_gold\" ) ~= nil then\n            drops_gold = false;\n        end\n    end\n    return drops_gold;\nend\n\nfunction script_wait_frames_fixed( entity_id, frames )\n	local now = GameGetFrameNum();\n	local last_execution = ComponentGetValueInt( GetUpdatedComponentID(), \"mLastExecutionFrame\" );\n\n	if now - last_execution < frames then return true; end\n	return false;\nend\n\nfunction set_lost_treasure( gold_nugget_entity )\n    EntityAddComponent( gold_nugget_entity, \"LuaComponent\", {\n        execute_every_n_frame = \"-1\",\n        script_item_picked_up = \"mods/gkbrkn_noita/files/gkbrkn/perks/lost_treasure/gold_pickup.lua\",\n    });\n    local removal_lua = EntityAddComponent( gold_nugget_entity, \"LuaComponent\", {\n        _tags=\"gkbrkn_lost_treasure\",\n        execute_on_removed=\"1\",\n        execute_every_n_frame=\"-1\",\n        script_source_file = \"mods/gkbrkn_noita/files/gkbrkn/perks/lost_treasure/gold_removed.lua\",\n    });\nend\n\nfunction clear_lost_treasure( gold_nugget_entity )\n    local lost_treasure_script = EntityGetFirstComponent( gold_nugget_entity, \"LuaComponent\", \"gkbrkn_lost_treasure\" );\n    if lost_treasure_script ~= nil then\n        EntityRemoveComponent( gold_nugget_entity, lost_treasure_script );\n    end\nend\n\nfunction is_lost_treasure( gold_nugget_entity )\n    return EntityGetFirstComponent( gold_nugget_entity, \"LuaComponent\", \"gkbrkn_lost_treasure\" ) ~= nil;\nend\n\n\nfunction is_gold_decay( gold_nugget_entity )\n    return EntityGetFirstComponent( gold_nugget_entity, \"LuaComponent\", \"gkbrkn_gold_decay\" ) ~= nil;\nend\n\nfunction set_gold_decay( gold_nugget_entity )\n    EntityAddComponent( gold_nugget_entity, \"LuaComponent\", {\n        execute_every_n_frame = \"-1\",\n        remove_after_executed = \"1\",\n        script_item_picked_up = \"mods/gkbrkn_noita/files/gkbrkn/misc/gold_decay/gold_pickup.lua\",\n    });\n    EntityAddComponent( gold_nugget_entity, \"LuaComponent\", {\n        _tags=\"gkbrkn_gold_decay\",\n        execute_on_removed=\"1\",\n        execute_every_n_frame=\"-1\",\n        script_source_file = \"mods/gkbrkn_noita/files/gkbrkn/misc/gold_decay/gold_removed.lua\",\n    });\nend\n\nfunction clear_gold_decay( gold_nugget_entity )\n    local script = EntityGetFirstComponent( gold_nugget_entity, \"LuaComponent\", \"gkbrkn_gold_decay\" );\n    if script ~= nil then\n        EntityRemoveComponent( gold_nugget_entity, script );\n    end\nend\n\nfunction limit_to_every_n_frames( entity, variable_name, n, callback )\n    local now = GameGetFrameNum();\n	if now - EntityGetVariableNumber( entity, variable_name, 0 ) >= n then\n        EntitySetVariableNumber( entity, variable_name, now );\n        callback();\n    end\nend\n\nfunction trend_towards_range( value, divisor, min, max )\n    return min + (max - min) * ( value / ( value + divisor ) );\nend\n\nfunction get_projectile_root_shooter( entity )\n    local root_shooter = entity;\n    local projectile = EntityGetFirstComponent( entity, \"ProjectileComponent\" );\n    if projectile ~= nil then\n        local shooter = ComponentGetValue2( projectile, \"mWhoShot\" );\n        while shooter ~= nil and shooter ~= 0 do\n            root_shooter = shooter;\n            local shooter_projectile = EntityGetFirstComponent( shooter, \"ProjectileComponent\" );\n            if shooter_projectile == nil then\n                break;\n            end\n            shooter = ComponentGetValue2( shooter_projectile, \"mWhoShot\" );\n        end\n    end\n    return root_shooter;\nend\n\nfunction make_projectile_not_damage_shooter( entity, force_shooter )\n    local projectile = EntityGetFirstComponent( entity, \"ProjectileComponent\" );\n    if projectile ~= nil then\n        ComponentSetValue2( projectile, \"explosion_dont_damage_shooter\", true );\n        ComponentSetValue2( projectile, \"friendly_fire\", false );\n        local shooter = force_shooter or get_projectile_root_shooter( entity );\n        if shooter ~= nil and shooter ~= 0 then\n            ComponentObjectSetValue( projectile, \"config_explosion\", \"dont_damage_this\", tostring( shooter ) );\n            EntityIterateComponentsByType( entity, \"AreaDamageComponent\", function(component)\n                if EntityHasTag( shooter, \"player_unit\" ) then\n                    ComponentSetValue2( component, \"entities_with_tag\", \"enemy\" );\n                else\n                    ComponentSetValue2( component, \"entities_with_tag\", \"player_unit\" );\n                end\n            end );\n\n            local lightning = EntityGetFirstComponent( entity, \"LightningComponent\" );\n            if lightning ~= nil then\n                ComponentObjectSetValue( lightning, \"config_explosion\", \"dont_damage_this\", tostring( shooter ) );\n            end\n        end\n    end\nend\n\n-- TODO this doesn't handle all damage components and doesn't handle multiple components of the same type\nfunction adjust_entity_damage( entity, projectile_damage_callback, typed_damage_callback, explosive_damage_callback, lightning_damage_callback, area_damage_callback )\n    local projectile = EntityGetFirstComponent( entity, \"ProjectileComponent\" );\n    local lightning = EntityGetFirstComponent( entity, \"LightningComponent\" );\n\n    if projectile ~= nil then\n        if projectile_damage_callback ~= nil then\n            local current_damage = ComponentGetValue2( projectile, \"damage\" );\n            local new_damage = projectile_damage_callback( current_damage );\n            if current_damage ~= new_damage then\n                ComponentSetValue2( projectile, \"damage\", new_damage );\n            end\n            if typed_damage_callback ~= nil then\n                local damage_by_types = ComponentObjectGetMembers( projectile, \"damage_by_type\" ) or {};\n                local damage_by_types_fixed = {};\n                for type,_ in pairs( damage_by_types ) do\n                    damage_by_types_fixed[type] = ComponentObjectGetValue2( projectile, \"damage_by_type\", type );\n                end\n                local damage_by_types_adjusted = typed_damage_callback( damage_by_types_fixed );\n                for type,amount in pairs( damage_by_types_adjusted ) do\n                    if amount ~= nil then\n                        ComponentObjectSetValue2( projectile, \"damage_by_type\", type, amount or damage_by_types_fixed[type] or 0 );\n                    end\n                end\n            end\n            if explosive_damage_callback ~= nil then\n                local current_damage = ComponentObjectGetValue2( projectile, \"config_explosion\", \"damage\" );\n                local new_damage = explosive_damage_callback( current_damage );\n                if current_damage ~= new_damage then\n                    ComponentObjectSetValue2( projectile, \"config_explosion\", \"damage\", new_damage );\n                end\n            end\n        end\n        if lightning_damage_callback ~= nil then\n            local lightning = EntityGetFirstComponent( entity, \"LightningComponent\" );\n            if lightning ~= nil then\n                local current_damage = tonumber( ComponentObjectGetValue2( lightning, \"config_explosion\", \"damage\" ) );\n                local new_damage = lightning_damage_callback( current_damage );\n                if current_damage ~= new_damage then\n                    ComponentObjectSetValue2( lightning, \"config_explosion\", \"damage\", new_damage );\n                end\n            end\n        end\n        if area_damage_callback ~= nil then\n            local area_damage = EntityGetFirstComponent( entity, \"AreaDamageComponent\" );\n            if area_damage ~= nil then\n                local current_damage = ComponentGetValue2( area_damage, \"damage_per_frame\" );\n                local new_damage = area_damage_callback( current_damage );\n                if current_damage ~= new_damage then\n                    ComponentSetValue2( area_damage, \"damage_per_frame\", new_damage );\n                end\n            end\n        end\n    end\nend\n\nfunction adjust_all_entity_damage( entity, callback )\n    adjust_entity_damage( entity,\n        function( current_damage ) return callback( current_damage ); end,\n        function( current_damages )\n            for type,current_damage in pairs( current_damages ) do\n                if current_damage ~= 0 then\n                    current_damages[type] = callback( current_damage );\n                end\n            end\n            return current_damages;\n        end,\n        function( current_damage ) return callback( current_damage ); end,\n        function( current_damage ) return callback( current_damage ); end,\n        function( current_damage ) return callback( current_damage ); end\n    );\nend\n\nfunction add_entity_mini_health_bar( entity )\n    EntityAddComponent( entity, \"HealthBarComponent\" );\n    EntityAddComponent( entity, \"SpriteComponent\", { \n        _tags=\"health_bar,ui,no_hitbox\",\n        alpha=\"1\",\n        has_special_scale=\"1\",\n        image_file=\"mods/gkbrkn_noita/files/gkbrkn/misc/health_bar.png\",\n        never_ragdollify_on_death=\"1\",\n        is_text_sprite=\"0\",\n        next_rect_animation=\"\",\n        offset_x=\"11\",\n        offset_y=\"-8\",\n        rect_animation=\"\",\n        special_scale_x=\"0.2\",\n        special_scale_y=\"0.6\",\n        ui_is_parent=\"0\",\n        update_transform=\"1\",\n        update_transform_rotation=\"0\",\n        visible=\"1\",\n        z_index=\"-9000\",\n    } );\nend\n\nfunction entity_adjust_health( entity, callback )\n    local damage_models = EntityGetComponent( entity, \"DamageModelComponent\" );\n    if damage_models ~= nil then\n        for _,damage_model in pairs( damage_models ) do\n            local hp = ComponentGetValue2( damage_model, \"hp\" );\n            local max_hp = ComponentGetValue2( damage_model, \"max_hp\" );\n            local new_max_hp, new_hp = callback( max_hp, hp );\n            ComponentSetValue2( damage_model, \"hp\", new_hp or hp );\n            ComponentSetValue2( damage_model, \"max_hp\", new_max_hp or max_hp );\n        end\n    end\nend\n\nfunction entity_get_health_ratio( entity )\n    local current_hp = 0;\n    local current_max_hp = 0;\n    local damage_models = EntityGetComponent( entity, \"DamageModelComponent\" ) or {};\n    for _,damage_model in pairs( damage_models ) do\n        local hp = ComponentGetValue2( damage_model, \"hp\" );\n        if hp > current_hp then\n            current_hp = hp;\n        end\n        local max_hp = ComponentGetValue2( damage_model, \"max_hp\" );\n        if max_hp > current_max_hp then\n            current_max_hp = max_hp;\n        end\n    end\n    local ratio = current_hp / current_max_hp;\n    if ratio ~= ratio then\n        return 0;\n    end\n    return ratio;\nend\n\nfunction entity_draw_health_bar( entity, frames )\n    local health_ratio = entity_get_health_ratio( entity );\n    if health_ratio < 1 then\n        local x, y = EntityGetTransform( entity );\n        local health_bar_image = 11 - math.ceil( health_ratio * 10 );\n        local sprite = \"mods/gkbrkn_noita/files/gkbrkn/misc/health_bars/health_bar\"..health_bar_image..\".png\";\n        local w,h = EntityGetFirstHitboxSize( entity );\n        if w == nil or h == nil then\n            GameCreateSpriteForXFrames( sprite, x, y + 8, true, 0, 0, frames );\n        else\n            GameCreateSpriteForXFrames( sprite, x, y + h / 2 + 2, true, 0, 0, frames );\n        end\n    end\nend\n\nfunction string_trim( s )\n   local from = s:match\"^%s*()\"\n   return from > #s and \"\" or s:match(\".*%S\", from)\nend\n\nfunction string_split( s, splitter )\n    local words = {};\n    for word in string.gmatch( s, '([^'..splitter..']+)') do\n        table.insert( words, word );\n    end\n    return words;\nend\n\nfunction reduce_particles( entity, disable )\n    local particle_emitters = EntityGetComponent( entity, \"ParticleEmitterComponent\" ) or {};\n    local sprite_particle_emitters = EntityGetComponent( entity, \"SpriteParticleEmitterComponent\" ) or {};\n    local projectile = EntityGetFirstComponent( entity, \"ProjectileComponent\" );\n    if not disable then\n        for _,emitter in pairs( particle_emitters ) do\n            if ComponentGetValue2( emitter, \"emit_cosmetic_particles\" ) == true and ComponentGetValue2( emitter, \"create_real_particles\" ) == false and ComponentGetValue2( emitter, \"emit_real_particles\" ) == false then\n                ComponentSetValue2( emitter, \"count_min\", 1 );\n                ComponentSetValue2( emitter, \"count_max\", 1 );\n                ComponentSetValue2( emitter, \"collide_with_grid\", false );\n                ComponentSetValue2( emitter, \"is_trail\", false );\n                local lifetime_min = tonumber( ComponentGetValue2( emitter, \"lifetime_min\" ) );\n                ComponentSetValue2( emitter, \"lifetime_min\", math.min( lifetime_min * 0.5, 0.1 ) );\n                local lifetime_max = tonumber( ComponentGetValue2( emitter, \"lifetime_max\" ) );\n                ComponentSetValue2( emitter, \"lifetime_max\", math.min( lifetime_max * 0.5, 0.5 ) );\n            end\n        end\n        for _,emitter in pairs( sprite_particle_emitters ) do\n            if ComponentGetValue2( emitter, \"entity_file\" ) == \"\" then\n                ComponentSetValue2( emitter, \"count_max\", 1 );\n                ComponentSetValue2( emitter, \"emission_interval_min_frames\", math.ceil( ComponentGetValue2( emitter, \"emission_interval_min_frames\" ) * 2 ) );\n                ComponentSetValue2( emitter, \"emission_interval_max_frames\", math.ceil( ComponentGetValue2( emitter, \"emission_interval_max_frames\" ) * 2 ) );\n            end\n        end\n        if projectile ~= nil then\n            ComponentObjectAdjustValues( projectile, \"config_explosion\", {\n                sparks_count_min=function( value ) return math.min( value, 1 ); end,\n                sparks_count_max=function( value ) return math.min( value, 2 ); end,\n            });\n        end\n    else\n        for _,emitter in pairs( particle_emitters ) do\n            if ComponentGetValue2( emitter, \"emit_cosmetic_particles\" ) == true and ComponentGetValue2( emitter, \"create_real_particles\" ) == false and ComponentGetValue2( emitter, \"emit_real_particles\" ) == false then\n                EntitySetComponentIsEnabled( entity, emitter, false );\n            end\n        end\n        for _,emitter in pairs( sprite_particle_emitters ) do\n            EntitySetComponentIsEnabled( entity, emitter, false );\n        end\n        if projectile ~= nil then\n            ComponentObjectSetValues( projectile, \"config_explosion\", {\n                sparks_enabled=false,\n                particle_effect=false\n            });\n        end\n    end\nend\n\nfunction remove_explosion_stains( entity )\n    local projectile = EntityGetFirstComponent( entity, \"ProjectileComponent\" );\n    if projectile ~= nil then\n        ComponentObjectAdjustValues( projectile, \"config_explosion\", {\n            stains_enabled=function( value ) return false; end,\n        });\n    end\nend\n\n\nfunction find_polymorphed_players()\n    local nearby_polymorph = EntityGetWithTag( \"polymorphed\" ) or {};\n    local polymorphed_players = {};\n    for _,entity in pairs( nearby_polymorph ) do\n        local game_stats = EntityGetFirstComponent( entity, \"GameStatsComponent\" );\n        if game_stats ~= nil then\n            if ComponentGetValue2( game_stats, \"is_player\" ) == true then\n                table.insert( polymorphed_players, entity );\n            end\n        end\n    end\n    return polymorphed_players;\nend\n\nfunction normalize( value, start_value, end_value )\n    width       = end_value - start_value;\n    offsetValue = value - start_value ;\n    return ( offsetValue - ( math.floor( offsetValue / width ) * width ) ) + start_value;\nend\n\n-- TODO fix\nfunction wrap_angle(angle)\n    local PI = math.pi;\n    local TWO_PI = math.pi * 2;\n	if angle > 0 then\n		angle = angle % TWO_PI\n	else\n		angle = -(math.abs(angle)%TWO_PI)\n	end\n	if angle > PI then\n		angle = angle - TWO_PI\n	elseif angle < -PI then\n		angle = angle + TWO_PI\n	end\n	return angle\nend\n\nfunction ease_angle( angle, target_angle, easing )\n    local dir = (angle - target_angle) / (math.pi*2);\n    dir = dir - math.floor(dir + 0.5);\n    dir = dir * (math.pi*2);\n    return angle - dir * easing;\nend\n\nfunction angle_difference( target_angle, starting_angle )\n    return math.atan2( math.sin( target_angle - starting_angle ), math.cos( target_angle - starting_angle ) );\nend\n\nfunction projectile_change_particle_colors( projectile_entity, color )\n    local r = bit.band( 0xFF, color );\n    local g = bit.rshift( bit.band( 0xFF00, color ), 8 );\n    local b = bit.rshift( bit.band( 0xFF0000, color ), 16 );\n    local particle_emitters = EntityGetComponent( projectile_entity, \"ParticleEmitterComponent\" ) or {};\n    for _,particle_emitter in pairs( particle_emitters ) do\n        --for k,v in pairs( ComponentGetMembers( particle_emitter ) or {} ) do\n        --    print( k..\"/\"..tostring(v));\n        --end\n        if ComponentGetValue2( particle_emitter, \"emit_real_particles\" ) == false then\n            ComponentSetValue2( particle_emitter, \"color\", color );\n        end\n    end\n    local sprite_particle_emitters = EntityGetComponent( projectile_entity, \"SpriteParticleEmitterComponent\" ) or {};\n    for _,sprite_particle_emitter in pairs( sprite_particle_emitters ) do\n        local color = {ComponentGetValue2( sprite_particle_emitter, \"color\" )};\n        local color_change = {ComponentGetValue2( sprite_particle_emitter, \"color_change\" )};\n        local ratio_r = r / 255;\n        local ratio_g = g / 255;\n        local ratio_b = b / 255;\n        ComponentSetValue2( sprite_particle_emitter, \"color\", ratio_r, ratio_g, ratio_b, color[4] );\n    end\nend\n\nfunction distance_to_entity( x, y, entity )\n    local tx, ty = EntityGetFirstHitboxCenter( entity );\n    if tx == nil or ty == nil then\n        tx, ty = EntityGetTransform( entity );\n    end\n    return math.sqrt( math.pow( tx - x, 2 ) + math.pow( ty - y, 2 ) );\nend\n\nfunction get_protagonist_bonus( entity )\n    local multiplier = 1.0;\n    local health_ratio = 1;\n    local damage_models = EntityGetComponent( entity, \"DamageModelComponent\" );\n    if damage_models ~= nil then\n        for i,damage_model in ipairs( damage_models ) do\n            local current_hp = ComponentGetValue2( damage_model, \"hp\" );\n            local max_hp = ComponentGetValue2( damage_model, \"max_hp\" );\n            local ratio = current_hp / max_hp;\n            if ratio < health_ratio then\n                health_ratio = ratio;\n            end\n        end\n    end\n    if entity ~= nil then\n        local current_protagonist_bonus = EntityGetVariableNumber( entity, \"gkbrkn_low_health_damage_bonus\", 0.0 );\n        local adjuted_ratio = ( 1 - health_ratio ) ^ 1.5;\n        multiplier = 1.0 + current_protagonist_bonus * adjuted_ratio;\n    end\n    return multiplier;\nend\n\nfunction append_translations( filepath, translation_file )\n    if translation_file == nil then\n        translation_file = \"data/translations/common.csv\";\n    end\n    local translations = ModTextFileGetContent( translation_file );\n    if translations ~= nil then\n        while translations:find(\"\\r\\n\\r\\n\") do\n            translations = translations:gsub(\"\\r\\n\\r\\n\",\"\\r\\n\");\n        end\n        local new_translations = ModTextFileGetContent( filepath );\n        translations = translations .. new_translations;\n        ModTextFileSetContent( translation_file, translations );\n    end\nend\n\nfunction thousands_separator(amount)\n    local formatted = amount;\n    while true do  \n        formatted, k = string.gsub(formatted, \"^(-?%d+)(%d%d%d)\", '%1,%2')\n            if (k==0) then\n            break\n        end\n    end\n    return formatted;\nend\n\nfunction decimal_format( amount, decimals )\n    if decimals == nil then decimals = 0; end\n    return thousands_separator( string.format( \"%.\"..decimals..\"f\", amount ) );\nend\n\n\nfunction copy_component( left, right )\n    for k,v in pairs( ComponentGetMembers( left ) ) do\n        ComponentSetValue2( right, k, ComponentGetValue2( left, k ) )\n    end\nend\n\nfunction sort_keyed_table( keyed_table, sort_function )\n    local h = {};\n    for k,v in pairs( keyed_table ) do\n        table.insert( h, { key=k, value=v })\n    end\n    table.sort( h, sort_function );\n    return h;\nend\n\nfunction get_magic_focus_multiplier( last_calibration_shot_frame, last_calibration_percent )\n    local multiplier = 1.0;\n    local current_frame = GameGetFrameNum();\n    local difference = current_frame - last_calibration_shot_frame;\n    if difference < MISC.PerkOptions.MagicFocus.DecayFrames then\n        return ( 1 - (difference / MISC.PerkOptions.MagicFocus.DecayFrames) ) * last_calibration_percent;\n    else\n        return math.min( 1, (difference - MISC.PerkOptions.MagicFocus.DecayFrames) / MISC.PerkOptions.MagicFocus.ChargeFrames);\n    end\nend\n\nfunction get_entity_held_or_random_wand( entity, or_random )\n    if or_random == nil then or_random = true; end\n    local base_wand = nil;\n    local wands = {};\n    local children = EntityGetAllChildren( entity ) or {};\n    for key,child in pairs( children ) do\n        if EntityGetName( child ) == \"inventory_quick\" then\n            wands = EntityGetChildrenWithTag( child, \"wand\" );\n            break;\n        end\n    end\n    if #wands > 0 then\n        local inventory2 = EntityGetFirstComponent( entity, \"Inventory2Component\" );\n        local active_item = ComponentGetValue2( inventory2, \"mActiveItem\" );\n        for _,wand in pairs( wands ) do\n            if wand == active_item then\n                base_wand = wand;\n                break;\n            end\n        end\n        if base_wand == nil and or_random then\n            SetRandomSeed( EntityGetTransform( entity ) );\n            base_wand =  Random( 1, #wands );\n        end\n    end\n    return base_wand;\nend\n\nfunction entity_get_inventory_wands( entity )\n    local wands = {};\n    local inventory2 = EntityGetFirstComponent( entity, \"Inventory2Component\" );\n    if inventory2 ~= nil then\n        for key, child in pairs( EntityGetAllChildren( entity ) or {} ) do\n            if EntityGetName( child ) == \"inventory_quick\" then\n                wands = EntityGetChildrenWithTag( child, \"wand\" ) or {};\n                break;\n            end\n        end\n    end\n    return wands;\nend\n\nfunction log_table( t ) for k,v in pairs(t) do print(k..\": \"..tostring(v)) end; end\n\nfunction change_materials_that_damage( entity, data )\n    for material,damage in pairs( data ) do\n        EntitySetDamageFromMaterial( entity, material, damage );\n    end\nend\n\nfunction parse_custom_world_seed( seed )\n    seed = seed:gsub( \"%a\", function( value )\n        return tostring( value:byte( 1 ) );\n    end );\n    return tonumber( seed ) % (2 ^ 32);\nend\n\nfunction nexp( value, exponent ) return ( ( math.abs( value ^ 2 ) ) ^ exponent ) / value; end\n"
_TWWE_VFS["mods/wand_editor/files/misc/bygoki/lib/inventories.lua"] = "dofile_once( \"mods/wand_editor/files/misc/bygoki/lib/variables.lua\" );\n\nfunction get_active_item_inventory( player_entity )\n    local inventory = nil;\n    local player_inventories = EntityGetAllChildren( player_entity );\n    for k,v in pairs( player_inventories ) do\n        if EntityGetName( v ) == \"inventory_quick\" then\n            inventory = v;\n            break;\n        end\n    end\n    return inventory;\nend\n\nfunction is_item_active_item( player_entity, item )\n    local inventory = EntityGetFirstComponent( player_entity, \"Inventory2Component\" );\n    if inventory then\n        if ComponentGetValue2( inventory, \"mActiveItem\" ) == item then return true; end\n        if ComponentGetValue2( inventory, \"mActualActiveItem\" ) == item then return true; end\n    end\n    return false;\nend\n\nfunction get_item_inventory( player_entity, index )\n    local inventory_entities = EntityGetWithTag( \"gkbrkn_inventory\" ) or {};\n    local inventory = nil;\n    for k,inventory_entity in pairs( inventory_entities ) do\n        if EntityHasNamedVariable( inventory_entity, \"gkbrkn_item_inventory_\"..index ) then\n            inventory = inventory_entity;\n            break;\n        end\n    end\n    if inventory == nil then\n        local entity = EntityLoad( \"mods/gkbrkn_noita/files/gkbrkn/misc/serialize_entity.xml\" );\n        EntityAddNamedVariable( entity, \"gkbrkn_item_inventory_\"..index );\n        EntityAddTag( entity, \"gkbrkn_inventory\" );\n        EntityAddChild( player_entity, entity );\n        inventory = entity;\n    end\n    return inventory;\nend\n\nfunction swap_item_inventories( left, right )\n    local left_inventory_entities = EntityGetAllChildren( left ) or {};\n    local right_inventory_entities = EntityGetAllChildren( right ) or {};\n    for _,child in pairs(left_inventory_entities) do EntityRemoveFromParent( child ); end\n    for _,child in pairs(right_inventory_entities) do EntityRemoveFromParent( child ); end\n    for _,child in pairs(left_inventory_entities) do EntityAddChild( right, child ); end\n    for _,child in pairs(right_inventory_entities) do EntityAddChild( left, child ); end\n    left_inventory_entities = EntityGetAllChildren( left ) or {};\n    right_inventory_entities = EntityGetAllChildren( right ) or {};\nend\n\nfunction change_item_inventory( player_entity, index )\n    local current_item_inventory_index = tonumber( GlobalsGetValue( \"gkbrkn_current_item_inventory_index\", \"0\" ) );\n    if current_item_inventory_index ~= index then\n        local inventory_entities = EntityGetWithTag( \"gkbrkn_inventory\" ) or {};\n        local current_item_inventory_entity = get_item_inventory( player_entity, current_item_inventory_index );\n        local next_item_inventory_entity = get_item_inventory( player_entity, index );\n\n        if current_item_inventory_entity and next_item_inventory_entity then\n            swap_item_inventories( get_active_item_inventory( player_entity ), current_item_inventory_entity );\n            for k,v in pairs( EntityGetAllChildren( current_item_inventory_entity ) or {} ) do\n                if not is_item_active_item( player_entity, v ) then\n                    EntitySetComponentsWithTagEnabled( v, \"enabled_in_world\", false );\n                    EntitySetComponentsWithTagEnabled( v, \"enabled_in_hand\", false );\n                end\n            end\n            swap_item_inventories( get_active_item_inventory( player_entity ), next_item_inventory_entity );\n            GlobalsSetValue( \"gkbrkn_current_item_inventory_index\", index );\n        end\n    end\nend\n\nfunction next_item_inventory( player_entity, change )\n    local current_item_inventory_index = tonumber( GlobalsGetValue( \"gkbrkn_current_item_inventory_index\", \"0\" ) );\n    local next_index = math.max( 0, current_item_inventory_index + change );\n    if current_item_inventory_index ~= next_index then\n        local current_inventory = get_item_inventory( player_entity, current_item_inventory_index );\n        local next_inventory = get_item_inventory( player_entity, next_index );\n        change_item_inventory( player_entity, next_index );\n        GamePrint( \"Swapped to inventory \"..( next_index + 1 ) );\n    end\nend\n\n\n\n\n\nfunction get_active_spell_inventory( player_entity )\n    local inventory = nil;\n    local player_inventories = EntityGetAllChildren( player_entity );\n    for k,v in pairs( player_inventories ) do\n        if EntityGetName( v ) == \"inventory_full\" then\n            inventory = v;\n            break;\n        end\n    end\n    return inventory;\nend\n\nfunction get_spell_inventory( player_entity, index )\n    local inventory_entities = EntityGetWithTag( \"gkbrkn_inventory\" ) or {};\n    local inventory = nil;\n    for k,inventory_entity in pairs( inventory_entities ) do\n        if EntityHasNamedVariable( inventory_entity, \"gkbrkn_spell_inventory_\"..index ) then\n            inventory = inventory_entity;\n            break;\n        end\n    end\n    if inventory == nil then\n        local entity = EntityCreateNew();\n        EntityAddNamedVariable( entity, \"gkbrkn_spell_inventory_\"..index );\n        EntityAddTag( entity, \"gkbrkn_inventory\" );\n        EntityAddChild( player_entity, entity );\n        inventory = entity;\n    end\n    return inventory;\nend\n\nfunction swap_spell_inventories( left, right )\n    local left_inventory_entities = EntityGetAllChildren( left ) or {};\n    local right_inventory_entities = EntityGetAllChildren( right ) or {};\n    for _,child in pairs(left_inventory_entities) do EntityRemoveFromParent( child ); end\n    for _,child in pairs(right_inventory_entities) do EntityRemoveFromParent( child ); end\n    for _,child in pairs(left_inventory_entities) do EntityAddChild( right, child ); end\n    for _,child in pairs(right_inventory_entities) do EntityAddChild( left, child ); end\n    left_inventory_entities = EntityGetAllChildren( left ) or {};\n    right_inventory_entities = EntityGetAllChildren( right ) or {};\nend\n\nfunction change_spell_inventory( player_entity, index )\n    local current_spell_inventory_index = tonumber( GlobalsGetValue( \"gkbrkn_current_spell_inventory_index\", \"0\" ) );\n    if current_spell_inventory_index ~= index then\n        local inventory_entities = EntityGetWithTag( \"gkbrkn_inventory\" ) or {};\n        local current_spell_inventory_entity = get_spell_inventory( player_entity, current_spell_inventory_index );\n        local next_spell_inventory_entity = get_spell_inventory( player_entity, index );\n\n        if current_spell_inventory_entity and next_spell_inventory_entity then\n            swap_spell_inventories( get_active_spell_inventory( player_entity ), current_spell_inventory_entity );\n            for k,v in pairs( EntityGetAllChildren( current_spell_inventory_entity ) or {} ) do\n                EntitySetComponentsWithTagEnabled( v, \"enabled_in_world\", false );\n                EntitySetComponentsWithTagEnabled( v, \"enabled_in_hand\", false );\n            end\n            swap_spell_inventories( get_active_spell_inventory( player_entity ), next_spell_inventory_entity );\n            GlobalsSetValue( \"gkbrkn_current_spell_inventory_index\", index );\n        end\n    end\nend\n\nfunction next_spell_inventory( player_entity, change )\n    local current_spell_inventory_index = tonumber( GlobalsGetValue( \"gkbrkn_current_spell_inventory_index\", \"0\" ) );\n    local next_index = math.max( 0, current_spell_inventory_index + change );\n    if current_spell_inventory_index ~= next_index then\n        local current_inventory = get_spell_inventory( player_entity, current_spell_inventory_index );\n        local next_inventory = get_spell_inventory( player_entity, next_index );\n        change_spell_inventory( player_entity, next_index );\n        GamePrint( \"Swapped to inventory \"..( next_index + 1 ) );\n    end\nend\n"
_TWWE_VFS["mods/wand_editor/files/misc/bygoki/lib/mod_settings.lua"] = "dofile_once(\"mods/wand_editor/files/libs/define.lua\")\nfunction setting_get( key ) return ModSettingGet( ModID..key ); end\nfunction setting_set( key, value ) if value ~= nil then return ModSettingSet( ModID..key, value ); end end\nfunction setting_clear( key ) return ModSettingRemove(ModID..key ); end\n"
_TWWE_VFS["mods/wand_editor/files/misc/bygoki/lib/options.lua"] = "local options = {\n    GoldPickupTracker = {\n        TrackDuration = 180, -- in game frames\n        ShowMessageFlag = \"gkbrkn_gold_tracking_message\",\n        ShowTrackerFlag = \"gkbrkn_gold_tracking_in_world\",\n    },\n    --CharmNerf = {\n    --    Enabled = \"gkbrkn_charm_nerf\",\n    --},\n    InvincibilityFrames = {\n        Duration = \"gkbrkn_invincibility_frames_duration\",\n        EnabledFlag = \"gkbrkn_invincibility_frames\",\n        FlashingFlag = \"gkbrkn_invincibility_frames_flashing\",\n    },\n    HealOnMaxHealthUp = {\n        RangeFlag = \"gkbrkn_max_health_heal_range\",\n        EnabledFlag = \"gkbrkn_max_health_heal\",\n        FullHealFlag = \"gkbrkn_max_health_heal_full\",\n    },\n    InfiniteInventory = { EnabledFlag = \"gkbrkn_infinite_inventory\", },\n    LooseSpellGeneration = { EnabledFlag = \"gkbrkn_loose_spell_generation\", },\n    ChampionEnemies = {\n        EnabledFlag = \"gkbrkn_champion_enemies\",\n        SuperChampionsFlag = \"gkbrkn_champion_enemies_super\",\n        AlwaysChampionsFlag = \"gkbrkn_champion_enemies_always\",\n        MiniBossesFlag = \"gkbrkn_champion_enemies_mini_bosses\",\n        ValourFlag = \"gkbrkn_champion_enemies_valour\",\n        ShowIconsFlag = \"gkbrkn_champion_enemies_show_icons\",\n        ChampionChance = 0.20,\n        MiniBossChance = 0.10, -- rolled after champion chance only if mini boss kill threshold has been met\n        MiniBossThreshold = 50, -- the amount of enemies that must be killed before a miniboss can spawn\n        ExtraTypeChance = 0.05,\n        ValourBonus = 3,\n    },\n    QuickSwap = { EnabledFlag = \"gkbrkn_quick_swap\", },\n    SeededRuns = {\n        UseSeedNextRunFlag = \"gkbrkn_seeded_runs_use_seed_next_run\",\n        SeedFlag = \"gkbrkn_seeded_runs_seed\",\n        CopySeedButtonFlag = \"gkbrkn_seeded_runs_copy_seed\",\n    },\n    LessParticles = {\n        PlayerProjectilesFlag = \"gkbrkn_less_particles_player\",\n        OtherStuffFlag = \"gkbrkn_less_particles_other_stuff\",\n        ExplosionStainsFlag = \"gkbrkn_less_particles_explosion_stains\",\n        DisableCosmeticsFlag = \"gkbrkn_less_particles_disable_cosmetic\"\n    },\n    RainbowProjectiles = { EnabledFlag = \"gkbrkn_rainbow_projectiles\" },\n    RandomStart = {\n        RandomWandsFlag = \"gkbrkn_random_start_random_wands\",\n        RandomPrimaryWandFlag = \"gkbrkn_random_start_primary_wand\",\n        RandomSecondaryWandFlag = \"gkbrkn_random_start_secondary_wand\",\n        RandomExtraWandFlag = \"gkbrkn_random_start_extra_wand\",\n        RandomHealthFlag = \"gkbrkn_random_start_random_health\",\n        MinimumHP = 50,\n        MaximumHP = 150,\n        CustomWandGenerationFlag = \"gkbrkn_random_start_custom_wands\",\n        RandomCapeColorFlag = \"gkbrkn_random_start_random_cape\",\n        RandomFlaskFlag = \"gkbrkn_random_start_random_flask\",\n        RandomPerkFlag = \"gkbrkn_random_start_random_perk\",\n        RandomPerksFlag = \"gkbrkn_random_start_random_perks\",\n    },\n    LegendaryWands = {\n        EnabledFlag = \"gkbrkn_legendary_wands\",\n        SpawnWeighting = 0.03,\n    },\n    ExtendedWandGeneration = { EnabledFlag = \"gkbrkn_extended_wand_generation\", },\n    ChaoticWandGeneration = { EnabledFlag = \"gkbrkn_chaotic_wand_generation\", },\n    AlternativeWandGeneration = { EnabledFlag = \"gkbrkn_alternative_wand_generation\", },\n    ShowFPS = { EnabledFlag = \"gkbrkn_show_fps\", },\n    HealthBars = {\n        RangeFlag = \"gkbrkn_health_bars_range\",\n        EnabledFlag = \"gkbrkn_health_bars\",\n        PrettyHealthBarsFlag = \"gkbrkn_health_bars_pretty\",\n    },\n    PackShops = {\n        EnabledFlag = \"gkbrkn_pack_shops\",\n        RandomCardsPerPack = 1,\n        CardsPerPack = 4,\n    },\n    GoldDecay = { EnabledFlag = \"gkbrkn_gold_decay\",},\n    GoldLifetime = { EnabledFlag = \"gkbrkn_gold_lifetime_multiplier\", },\n    PersistentGold = { EnabledFlag = \"gkbrkn_persistent_gold\", },\n    AutoPickupGold = { EnabledFlag = \"gkbrkn_auto_pickup_gold\", },\n    CombineGold = {\n        EnabledFlag = \"gkbrkn_combine_gold\",\n        Radius = 48,\n    },\n    PassiveRecharge = {\n        EnabledFlag = \"gkbrkn_passive_recharge\",\n        Speed = 1\n    },\n    TargetDummy = {\n        EnabledFlag = \"gkbrkn_target_dummy\",\n        AllowEnvironmentalDamage = \"gkbrkn_target_dummy_environmental\"\n    },\n    SlotMachine = { EnabledFlag = \"gkbrkn_slot_machine\", },\n    ShopReroll = { EnabledFlag = \"gkbrkn_shop_reroll\", },\n    Loadouts = {\n        ManageFlag = \"gkbrkn_loadouts_manage\",\n        EnabledFlag = \"gkbrkn_loadouts_enabled\",\n        UnlockLoadouts = \"gkbrkn_unlock_loadouts\",\n        CapeColorFlag = \"gkbrkn_loadouts_cape_color\",\n        PlayerSpritesFlag = \"gkbrkn_loadouts_player_sprites\",\n        ClassyFrameworkIntegrationFlag = \"gkbrkn_classy_framework_integration\",\n        SelectableClassesIntegrationFlag = \"gkbrkn_selectable_classes_integration\",\n    },\n    HeroMode = {\n        EnabledFlag = \"gkbrkn_hero_mode\",\n        OrbsDifficultyFlag = \"gkbrkn_hero_mode_orb_scale\",\n        DistanceDifficultyFlag = \"gkbrkn_hero_mode_distance_scale\",\n        CarnageDifficultyFlag = \"gkbrkn_hero_mode_carnage\",\n    },\n    NoPregenWands = { EnabledFlag = \"gkbrkn_no_pregen_wands\", },\n    ChestsContainPerks = {\n        EnabledFlag = \"gkbrkn_chests_contain_perks\",\n        Chance=0.12,\n        SuperChance=0.25,\n        RemovePerkTag=false, -- this makes it so that picking up other perks doesn't kill this perk. might have side effects!!!\n        DontKillOtherPerks=true,\n    },\n    ManageExternalContent = { EnabledFlag = \"gkbrkn_manage_external_content\", },\n    ShowModTips = {\n        EnabledFlag = \"gkbrkn_mod_tips\",\n        Tips = {\n            \"$mod_tips_gkbrkn_tip_1\",\n            \"$mod_tips_gkbrkn_tip_2\",\n            \"$mod_tips_gkbrkn_tip_3\",\n            \"$mod_tips_gkbrkn_tip_4\",\n            \"$mod_tips_gkbrkn_tip_5\",\n            \"$mod_tips_gkbrkn_tip_6\",\n            \"$mod_tips_gkbrkn_tip_7\",\n            \"$mod_tips_gkbrkn_tip_8\",\n            \"$mod_tips_gkbrkn_tip_9\",\n            \"$mod_tips_gkbrkn_tip_10\",\n        }\n    },\n    Badges = { EnabledFlag = \"gkbrkn_show_badges\", },\n    ShowEntityNames = { EnabledFlag = \"gkbrkn_show_entity_names\", },\n    ShowPerkDescriptions = { EnabledFlag = \"gkbrkn_show_perk_descriptions\", },\n    ShowDamageNumbers = { EnabledFlag = \"gkbrkn_show_damage_numbers\", },\n    FixedCamera = { EnabledFlag = \"gkbrkn_fixed_camera\", OldBehaviourFlag = \"gkbrkn_fixed_camera_old\" },\n    Events = { EnabledFlag = \"gkbrkn_events\", },\n    AutoHide = { EnabledFlag = \"gkbrkn_auto_hide\", },\n    RemoveEditPrompt = { EnabledFlag = \"gkbrkn_remove_edit_prompt\", },\n    PerkOptions = {\n        MagicFocus = {\n            DecayFrames = 60,\n            ChargeFrames = 240,\n        },\n        BloodMagic = {\n            BloodToManaRatio = 1,\n            FreeAlwaysCasts = true,\n            DamageMultiplier = 5,\n        },\n        Resilience = { \n            Resistances = {\n                fire=0.33,\n                radioactive=0.33,\n                poison=0.33,\n                electricity=0.33,\n            }\n        },\n        ManaEfficiency = {\n            Discount = 0.33\n        },\n        SpellEfficiency = {\n            RetainChance = 0.33\n        },\n        LivingWand = {\n            TeleportDistance = 128\n        }\n    },\n    TweakOptions = {\n        BloodAmountMultiplier = 0.98\n    },\n    PerkRewrite = {\n        StackableChangesFlag = \"gkbrkn_new_perk_stackables\",\n        NewLogicFlag = \"gkbrkn_new_perk_logic\",\n        ShowBarGraphFlag = \"gkbrkn_new_perk_bar_graph\",\n    }\n}\n--# intercept this line\nreturn options"
_TWWE_VFS["mods/wand_editor/files/misc/bygoki/lib/perk_data.lua"] = "dofile_once( \"data/scripts/perks/perk.lua\" );\ndofile_once( \"data/scripts/perks/perk_list.lua\" );\nlocal available_perks = {};\nfor k,v in pairs( perk_get_spawn_order() or {} ) do\n    available_perks[v] = true;\nend\n\nreturn function()\n    local perk_data = {};\n    for k,perk in pairs( perk_list ) do\n        perk_data[perk.id] = perk;\n        perk_data[perk.id].missing = available_perks[perk.id] == nil;\n        perk_data[perk.id].not_in_pool = perk.not_in_default_perk_pool;\n        perk_data[perk.id].stackable = perk_is_stackable( perk );\n        perk_data[perk.id].enabled = true;\n    end\n    for k,perk in pairs( perk_list_cache ) do\n        if perk_data[perk.id] == nil then\n            perk_data[perk.id] = perk;\n            perk_data[perk.id].missing = available_perks[perk.id] == nil;\n            perk_data[perk.id].not_in_pool = perk.not_in_default_perk_pool;\n            perk_data[perk.id].stackable = perk_is_stackable( perk );\n            perk_data[perk.id].enabled = false;\n        end\n    end\n    return perk_data;\nend"
_TWWE_VFS["mods/wand_editor/files/misc/bygoki/lib/variables.lua"] = "function EntityClearVariable( entity, variable_tag, value )\n    local variable = EntityGetFirstComponent( entity, \"VariableStorageComponent\", variable_tag );\n    if variable ~= nil then\n        EntityRemoveComponent( entity, variable );\n    end\nend\n\nfunction EntityGetVariableString( entity, variable_tag, default )\n    local variable = EntityGetFirstComponent( entity, \"VariableStorageComponent\", variable_tag );\n    if variable ~= nil then\n        return ComponentGetValue2( variable, \"value_string\" );\n    end\n    return default;\nend\n\nfunction EntitySetVariableString( entity, variable_tag, value )\n    local current_variable = EntityGetFirstComponent( entity, \"VariableStorageComponent\", variable_tag );\n    if current_variable == nil then\n        EntityAddComponent( entity, \"VariableStorageComponent\", {\n            _tags=variable_tag..\",enabled_in_world,enabled_in_hand,enabled_in_inventory\",\n            value_string=tostring(value)\n        } );\n    else\n        ComponentSetValue2( current_variable, \"value_string\", value );\n    end\nend\n\nfunction EntityGetNamedVariable( entity, name )\n    for k,component in pairs( EntityGetComponent( entity, \"VariableStorageComponent\" ) or {} ) do\n        if ComponentGetValue2( component, \"name\") == name then\n            return component;\n        end\n    end\nend\n\nfunction EntityHasNamedVariable( entity, name )\n    for k,component in pairs( EntityGetComponent( entity, \"VariableStorageComponent\" ) or {} ) do\n        if ComponentGetValue2( component, \"name\") == name then\n            return true;\n        end\n    end\n    return false;\nend\n\nfunction EntityAddNamedVariable( entity, name )\n    local c = EntityAddComponent2( entity, \"VariableStorageComponent\", { name=name } );\nend\n\nfunction EntityRemoveNamedVariable( entity, name )\n    for k,component in pairs( EntityGetComponent( entity, \"VariableStorageComponent\" ) or {} ) do\n        if ComponentGetValue2( component, \"name\") == name then\n            EntityRemoveComponent( entity, component );\n        end\n    end\nend\n\nfunction EntityGetVariableNumber( entity, variable_tag, default )\n    return tonumber( EntityGetVariableString( entity, variable_tag, default ) );\nend\n\nfunction EntitySetVariableNumber( entity, variable_tag, value )\n    return EntitySetVariableString( entity, variable_tag, value );\nend\n\nfunction EntityAdjustVariableNumber( entity, variable_tag, default, callback )\n    local new_value = callback( EntityGetVariableNumber( entity, variable_tag, default ) );\n    EntitySetVariableNumber( entity, variable_tag, tostring( new_value ) );\n    return new_value;\nend\n\nfunction ComponentAdjustValue( component, member, callback )\n    local new_value = callback( ComponentGetValue2( component, member ) );\n    ComponentSetValue2( component, member, new_value );\n    return new_value;\nend\n\nfunction ComponentSetValues( component, member_value_table )\n    for member,new_value in pairs(member_value_table) do\n        ComponentSetValue2( component, member, new_value );\n    end\nend\n\nfunction ComponentAdjustValues( component, member_callback_table )\n    for member,callback in pairs( member_callback_table ) do\n        ComponentSetValue2( component, member, callback( ComponentGetValue2( component, member ) ) );\n    end\nend\n\nfunction ComponentObjectSetValues( component, object, member_value_table )\n    for member,new_value in pairs(member_value_table) do\n        ComponentObjectSetValue2( component, object, member, new_value );\n    end\nend\n\nfunction ComponentObjectAdjustValues( component, object, member_callback_table )\n    for member,callback in pairs(member_callback_table) do\n        ComponentObjectSetValue2( component, object, member, callback( ComponentObjectGetValue2( component, object, member ) ) );\n    end\nend\n\nfunction ComponentSetValues( component, member_value_table )\n    for member,new_value in pairs(member_value_table) do\n        ComponentSetValue2( component, member, new_value );\n    end\nend\n\nfunction ComponentAdjustMetaCustoms( component, member_callback_table )\n    for member,callback in pairs(member_callback_table) do\n        local current_value = ComponentGetValue2( component, member );\n        local new_value = callback( current_value );\n        ComponentSetValue2( component, member, new_value );\n    end\nend\n"
_TWWE_VFS["mods/wand_editor/files/misc/bygoki/lib/wands.lua"] = "dofile_once( \"data/scripts/gun/procedural/gun_procedural.lua\" );\ndofile_once( \"mods/wand_editor/files/misc/bygoki/helper.lua\" );\ndofile_once( \"mods/wand_editor/files/misc/bygoki/lib/variables.lua\" );\nlocal MISC = dofile_once( \"mods/wand_editor/files/misc/bygoki/lib/options.lua\" );\ndofile_once( \"mods/wand_editor/files/misc/bygoki/lib/mod_settings.lua\" );\n\nlocal WAND_STAT_SETTER = {\n    Direct = 1,\n    Gun = 2,\n    GunAction = 3\n}\n\nlocal WAND_STAT_SETTERS = {\n    shuffle_deck_when_empty = WAND_STAT_SETTER.Gun,\n    actions_per_round = WAND_STAT_SETTER.Gun,\n    speed_multiplier = WAND_STAT_SETTER.GunAction,\n    deck_capacity = WAND_STAT_SETTER.Gun,\n    reload_time = WAND_STAT_SETTER.Gun,\n    fire_rate_wait = WAND_STAT_SETTER.GunAction,\n    spread_degrees = WAND_STAT_SETTER.GunAction,\n    mana_charge_speed = WAND_STAT_SETTER.Direct,\n    mana_max = WAND_STAT_SETTER.Direct,\n    mana = WAND_STAT_SETTER.Direct,\n}\n\nfunction wand_get_actions( wand )\n    local actions = {};\n    local children = EntityGetAllChildren( wand ) or {};\n    for i,v in ipairs( children ) do\n        local item = EntityGetFirstComponentIncludingDisabled( v, \"ItemComponent\" );\n        local item_action = EntityGetFirstComponentIncludingDisabled( v, \"ItemActionComponent\" );\n        if item and item_action then\n            local action_id = ComponentGetValue2( item_action, \"action_id\" );\n            local permanent = ComponentGetValue2( item, \"permanently_attached\" );\n            local x, y = ComponentGetValue2( item, \"inventory_slot\" );\n            if action_id ~= nil then\n                table.insert( actions, { action_id = action_id, permanent = permanent, x = x, y = y } );\n            end\n        end\n    end\n    return actions;\nend\n\nfunction wand_remove_actions( wand )\n    local actions = {};\n    local children = EntityGetAllChildren( wand ) or {};\n    for i,v in ipairs( children ) do\n        local item = EntityGetFirstComponentIncludingDisabled( v, \"ItemComponent\" );\n        local item_action = EntityGetFirstComponentIncludingDisabled( v, \"ItemActionComponent\" );\n        if item and item_action then\n            EntityRemoveFromParent( v );\n        end\n    end\n    return actions;\nend\n\nfunction wand_shuffle_actions( wand )\n    local actions = {};\n    local actions_data = {};\n    local children = EntityGetAllChildren( wand ) or {};\n    for i,v in ipairs( children ) do\n        local item = EntityGetFirstComponentIncludingDisabled( v, \"ItemComponent\" );\n        local item_action = EntityGetFirstComponentIncludingDisabled( v, \"ItemActionComponent\" );\n        if item and item_action then\n            local action_id = ComponentGetValue2( item_action, \"action_id\" );\n            local permanent = ComponentGetValue2( item, \"permanently_attached\" );\n            local locked = ComponentGetValue2( item, \"is_frozen\" );\n            local x, y = ComponentGetValue2( item, \"inventory_slot\" );\n            if action_id ~= nil and permanent ~= true and locked ~= true then\n                table.insert( actions, { action_entity = v, item = item } );\n                table.insert( actions_data, { x = x, y = y } );\n            end\n        end\n    end\n    local wx, wy = EntityGetTransform( wand );\n    SetRandomSeed( GameGetFrameNum(), wx + wy );\n    local actions_data_shuffled = {};\n    for i, v in ipairs(actions_data) do\n        local pos = Random( 1, #actions_data_shuffled + 1 );\n        table.insert( actions_data_shuffled, pos, v )\n    end\n    for i=1,#actions do\n        local action = actions[i];\n        local action_data = actions_data_shuffled[i];\n        ComponentSetValue2( action.item, \"inventory_slot\", action_data.x, action_data.y );\n    end\nend\n\nfunction wand_copy_actions( base_wand, copy_wand )\n    local actions = wand_get_actions( base_wand );\n    for index,action_data in pairs( actions ) do\n        local action_entity = CreateItemActionEntity( action_data.action_id );\n        local item = EntityGetFirstComponentIncludingDisabled( action_entity, \"ItemComponent\" );\n        if action_data.permanent then\n            ComponentSetValue2( item, \"permanently_attached\", true );\n        end\n        if ComponentSetValue2 and action_data.x ~= nil and action_data.y ~= nil then\n            ComponentSetValue2( item, \"inventory_slot\", action_data.x, action_data.y );\n        end\n        EntitySetComponentsWithTagEnabled( action_entity, \"enabled_in_world\", false );\n        EntityAddChild( copy_wand, action_entity );\n    end\nend\n\nfunction wand_copy_stats( base_wand, copy_wand )\n    local base_ability = EntityGetFirstComponentIncludingDisabled( base_wand, \"AbilityComponent\" );\n    local target_ability = EntityGetFirstComponentIncludingDisabled( copy_wand, \"AbilityComponent\" );\n    if base_ability and target_ability then\n        for stat,stat_type in pairs( WAND_STAT_SETTERS ) do\n            ability_component_set_stat( target_ability, stat, ability_component_get_stat( base_ability, stat ) );\n        end\n    end\nend\n\nfunction wand_copy( base_wand, copy_wand, copy_sprite, copy_actions )\n    wand_copy_stats( base_wand, copy_wand );\n    if copy_sprite ~= false then\n        local base_ability = EntityGetFirstComponentIncludingDisabled( base_wand, \"AbilityComponent\" );\n        local target_ability = EntityGetFirstComponentIncludingDisabled( copy_wand, \"AbilityComponent\" );\n        ComponentSetValue2( target_ability, \"sprite_file\", ComponentGetValue2( base_ability, \"sprite_file\" ) );\n        local base_sprite = EntityGetFirstComponentIncludingDisabled( base_wand, \"SpriteComponent\" )\n        local copy_sprite = EntityGetFirstComponentIncludingDisabled( copy_wand, \"SpriteComponent\" )\n        CopyListedComponentMembers( base_sprite, copy_sprite, \"image_file\",\"offset_x\",\"offset_y\");\n        local base_hotspot = EntityGetFirstComponentIncludingDisabled( base_wand, \"HotspotComponent\", \"shoot_pos\" );\n        local copy_hotspot = EntityGetFirstComponentIncludingDisabled( copy_wand, \"HotspotComponent\", \"shoot_pos\" );\n        CopyComponentMembers( base_hotspot, copy_hotspot );\n        local base_hotspot_x, base_hotspot_y = ComponentGetValue2( base_hotspot, \"offset\" );\n        ComponentSetValue2( copy_hotspot, \"offset\", base_hotspot_x, base_hotspot_y );\n    end\n    if copy_actions ~= false then\n        wand_remove_actions( copy_wand );\n        wand_copy_actions( base_wand, copy_wand );\n    end\nend\n\nfunction ability_component_get_stat( ability, stat )\n    local setter = WAND_STAT_SETTERS[stat];\n    if setter ~= nil then\n        if setter == WAND_STAT_SETTER.Direct then\n            return ComponentGetValue2( ability, stat );\n        elseif setter == WAND_STAT_SETTER.Gun then\n            return ComponentObjectGetValue2( ability, \"gun_config\", stat );\n        elseif setter == WAND_STAT_SETTER.GunAction then\n            return ComponentObjectGetValue2( ability, \"gunaction_config\", stat );\n        end\n    end\nend\n\nfunction ability_component_set_stat( ability, stat, value )\n    local setter = WAND_STAT_SETTERS[stat];\n    if setter ~= nil then\n        if setter == WAND_STAT_SETTER.Direct then\n            ComponentSetValue2( ability, stat, value );\n        elseif setter == WAND_STAT_SETTER.Gun then\n            ComponentObjectSetValue2( ability, \"gun_config\", stat, value );\n        elseif setter == WAND_STAT_SETTER.GunAction then\n            ComponentObjectSetValue2( ability, \"gunaction_config\", stat, value );\n        end\n    end\nend\n\nfunction ability_component_adjust_stat( ability, stat, callback )\n    local setter = WAND_STAT_SETTERS[stat];\n    if setter ~= nil then\n        local current_value = nil;\n        if setter == WAND_STAT_SETTER.Direct then\n            current_value = ComponentGetValue2( ability, stat );\n        elseif setter == WAND_STAT_SETTER.Gun then\n            current_value = ComponentObjectGetValue2( ability, \"gun_config\", stat );\n        elseif setter == WAND_STAT_SETTER.GunAction then\n            current_value = ComponentObjectGetValue2( ability, \"gunaction_config\", stat );\n        end\n        local new_value = callback( current_value );\n        if setter == WAND_STAT_SETTER.Direct then\n            ComponentSetValue2( ability, stat, new_value );\n        elseif setter == WAND_STAT_SETTER.Gun then\n            ComponentObjectSetValue2( ability, \"gun_config\", stat, new_value );\n        elseif setter == WAND_STAT_SETTER.GunAction then\n            ComponentObjectSetValue2( ability, \"gunaction_config\", stat, new_value );\n        end\n    end\nend\n\nfunction ability_component_get_stats( ability, stat )\n    local stats = {};\n    for k,v in pairs( WAND_STAT_SETTERS ) do\n        stats[k] = ability_component_get_stat( ability, k );\n    end\n    return stats;\nend\n\nfunction ability_component_set_stats( ability, stat_value_table )\n    for stat,value in pairs(stat_value_table) do\n        ability_component_set_stat( ability, stat, value );\n    end\nend\n\nfunction ability_component_adjust_stats( ability, stat_callback_table )\n    for stat,callback in pairs(stat_callback_table) do\n        ability_component_adjust_stat( ability, stat, callback );\n    end\nend\n\nfunction initialize_wand( wand, wand_data )\n    local ability = EntityGetFirstComponentIncludingDisabled( wand, \"AbilityComponent\" );\n    local item = EntityGetFirstComponent( wand, \"ItemComponent\" );\n    if wand_data.name ~= nil then\n        ComponentSetValue2( ability, \"ui_name\", wand_data.name );\n        if item ~= nil then\n            ComponentSetValue2( item, \"item_name\", wand_data.name );\n            ComponentSetValue2( item, \"always_use_item_name_in_ui\", true );\n        end\n    end\n\n    for stat,value in pairs( wand_data.stats or {} ) do\n        ability_component_set_stat( ability, stat, value );\n    end\n\n    for stat,range in pairs( wand_data.stat_ranges or {} ) do\n        ability_component_set_stat( ability, stat, Random( range[1], range[2] ) );\n    end\n\n    for stat,random_values in pairs( wand_data.stat_randoms or {} ) do\n        ability_component_set_stat( ability, stat, random_values[ Random( 1, #random_values ) ] );\n    end\n\n    ability_component_set_stat( ability, \"mana\", ability_component_get_stat( ability, \"mana_max\" ) );\n\n    for _,actions in pairs( wand_data.permanent_actions or {} ) do\n        local random_action = actions[ Random( 1, #actions ) ];\n        if random_action ~= nil then\n            AddGunActionPermanent( wand, random_action );\n        end\n    end\n\n    --for _,actions in pairs( wand_data.actions or {} ) do\n    if wand_data.actions then\n        for action_index=1,#wand_data.actions,1 do\n            local actions = wand_data.actions[action_index];\n            if actions ~= nil then\n                local random_action = actions[ Random( 1, #actions ) ];\n                if random_action ~= nil then\n                    if type( random_action ) == \"table\" then\n                        local amount = random_action.amount or 1;\n                        for _=1,amount,1 do\n                            local action_entity = CreateItemActionEntity( random_action.action_id or random_action.action );\n                            if action_entity then\n                                local item = EntityGetFirstComponentIncludingDisabled( action_entity, \"ItemComponent\" );\n                                if setting_get( MISC.Loadouts.UnlockLoadouts ) ~= true and random_action.locked == true then\n                                    ComponentSetValue2( item, \"is_frozen\", true );\n                                end\n                                if random_action.permanent == true then\n                                    ComponentSetValue2( item, \"permanently_attached\", true );\n                                end\n                                ComponentSetValue2( item, \"inventory_slot\", action_index - 1, 0 );\n                                EntitySetComponentsWithTagEnabled( action_entity, \"enabled_in_world\", false );\n                                EntityAddChild( wand, action_entity );\n                            end\n                        end\n                    else\n                        local action_entity = CreateItemActionEntity( random_action );\n                        if action_entity then\n                            local item = EntityGetFirstComponentIncludingDisabled( action_entity, \"ItemComponent\" );\n                            if item ~= nil then\n                                ComponentSetValue2( item, \"inventory_slot\", action_index - 1, 0 );\n                            end\n                            EntitySetComponentsWithTagEnabled( action_entity, \"enabled_in_world\", false );\n                            EntityAddChild( wand, action_entity );\n                            --AddGunAction( wand, random_action );\n                        end\n                    end\n                end\n            end\n        end\n    end\n    \n    if wand_data.sprite ~= nil then\n        if wand_data.sprite.file ~= nil then\n            ComponentSetValue2( ability, \"sprite_file\", wand_data.sprite.file );\n            -- TODO this takes a second to apply, probably worth fixing, but for now just prefer using custom file\n            local sprite = EntityGetFirstComponent( wand, \"SpriteComponent\", \"item\" );\n            if sprite ~= nil then\n                ComponentSetValue2( sprite, \"image_file\", wand_data.sprite.file );\n                EntityRefreshSprite( wand, sprite );\n            end\n        end\n        if wand_data.sprite.hotspot ~= nil then\n            local hotspot = EntityGetFirstComponent( wand, \"HotspotComponent\", \"shoot_pos\" );\n            if hotspot ~= nil then\n                ComponentSetValue2( hotspot, \"offset\", wand_data.sprite.hotspot.x, wand_data.sprite.hotspot.y );\n            end\n        end\n    else\n        local gun = {\n            deck_capacity               = ability_component_get_stat( ability, \"deck_capacity\" ),\n            actions_per_round           = ability_component_get_stat( ability, \"actions_per_round\" ),\n            reload_time                 = ability_component_get_stat( ability, \"reload_time\" ),\n            shuffle_deck_when_empty     = ability_component_get_stat( ability, \"shuffle_deck_when_empty\" ) and 1 or 0,\n            fire_rate_wait              = ability_component_get_stat( ability, \"fire_rate_wait\" ),\n            spread_degrees              = ability_component_get_stat( ability, \"spread_degrees\" ),\n            speed_multiplier            = ability_component_get_stat( ability, \"speed_multiplier\" ),\n            mana_charge_speed           = ability_component_get_stat( ability, \"mana_charge_speed\" ),\n            mana_max                    = ability_component_get_stat( ability, \"mana_max\" ),\n        };\n        local dynamic_wand = GetWand( gun );\n        SetWandSprite( wand, ability, dynamic_wand.file, dynamic_wand.grip_x, dynamic_wand.grip_y, ( dynamic_wand.tip_x - dynamic_wand.grip_x ), ( dynamic_wand.tip_y - dynamic_wand.grip_y ) );\n        EntityRefreshSprite( wand, EntityGetFirstComponent( wand, \"SpriteComponent\", \"item\" ) );\n    end\n\n    if wand_data.callback ~= nil then\n        wand_data.callback( wand, ability );\n    end\nend\n\nfunction wand_explode_random_action( wand, include_permanent_actions, include_frozen_actions, ox, oy )\n    local x, y = EntityGetTransform( wand );\n    local actions = {};\n    local children = EntityGetAllChildren( wand ) or {};\n    for i,action in ipairs( children ) do\n        local item_action = EntityGetFirstComponentIncludingDisabled( action, \"ItemActionComponent\" );\n        if item_action ~= nil then\n            local item = EntityGetFirstComponentIncludingDisabled( action, \"ItemComponent\" );\n            if item ~= nil then\n                local action_id = ComponentGetValue2( item_action, \"action_id\" );\n                if action_id ~= nil then\n                    if include_permanent_actions == true or ComponentGetValue2( item, \"permanently_attached\" ) == false then\n                        if include_frozen_actions == true or ComponentGetValue2( item, \"is_frozen\" ) == false then\n                            table.insert( actions, { action_id=action_id, permanent=permanent, entity=action } );\n                        end\n                    end\n                end\n            end\n        end\n    end\n    if #actions > 0 then\n        local r = math.ceil( math.random() * #actions );\n        local action_to_remove = actions[ r ];\n        local card = CreateItemActionEntity( action_to_remove.action_id, ox or x, oy or y );\n        ComponentSetValue2( EntityGetFirstComponent( card, \"VelocityComponent\" ), \"mVelocity\", Random( -150, 150 ), Random( -250, -100 ) );\n        EntityRemoveFromParent( action_to_remove.entity );\n        return action_to_remove;\n    end\nend\n\nfunction wand_remove_first_action( wand, include_permanent_actions, include_frozen_actions )\n    local x, y = EntityGetTransform( wand );\n    local actions = {};\n    local children = EntityGetAllChildren( wand ) or {};\n    for _,action in pairs( children ) do\n        local item_action = EntityGetFirstComponentIncludingDisabled( action, \"ItemActionComponent\" );\n        if item_action ~= nil then\n            local item = EntityGetFirstComponentIncludingDisabled( action, \"ItemComponent\" );\n            if item ~= nil then\n                if include_permanent_actions == true or ComponentGetValue2( item, \"permanently_attached\" ) == false then\n                    if include_frozen_actions == true or ComponentGetValue2( item, \"is_frozen\" ) == false then\n                        EntityRemoveFromParent( action );\n                        EntitySetComponentsWithTagEnabled( action,  \"enabled_in_world\", true );\n                        EntitySetComponentsWithTagEnabled( action,  \"enabled_in_hand\", false );\n                        EntitySetComponentsWithTagEnabled( action,  \"enabled_in_inventory\", false );\n                        EntitySetComponentsWithTagEnabled( action,  \"item_unidentified\", false );\n                        EntitySetTransform( action, x, y );\n                        return action;\n                    end\n                end\n            end\n        end\n    end\nend\n\nfunction wand_lock( wand, lock_spells, lock_wand )\n    if lock_spells == nil then lock_spells = true; end\n    if lock_wand == nil then lock_wand = true; end\n    if lock_spells then\n        local children = EntityGetAllChildren( wand ) or {};\n        for i,action in ipairs( children ) do\n            local item = EntityGetFirstComponentIncludingDisabled( action, \"ItemComponent\" );\n            if item ~= nil then\n                ComponentSetValue2( item, \"is_frozen\", true );\n            end\n        end\n    end\n    if lock_wand then\n        local item = EntityGetFirstComponentIncludingDisabled( wand, \"ItemComponent\" );\n        if item ~= nil then\n            ComponentSetValue2( item, \"is_frozen\", true );\n        end\n    end\nend\n\nfunction wand_attach_action( wand, action, permanent, locked )\n    EntityAddChild( wand, action );\n    local item_action = EntityGetFirstComponentIncludingDisabled( action, \"ItemActionComponent\" );\n    if item_action ~= nil then\n        EntitySetComponentsWithTagEnabled( action,  \"enabled_in_world\", false );\n        EntitySetComponentsWithTagEnabled( action,  \"enabled_in_hand\", false );\n        EntitySetComponentsWithTagEnabled( action,  \"enabled_in_inventory\", false );\n    end\nend\n\nfunction wand_is_special( wand )\n    if EntityGetVariableNumber( wand, \"gkbrkn_challenge_wand\", 0 ) == 1\n    or EntityGetVariableNumber( wand, \"gkbrkn_duplicate_wand\", 0 ) == 1\n    or EntityGetVariableNumber( wand, \"gkbrkn_legendary_wand\", 0 ) == 1\n    or EntityGetVariableNumber( wand, \"gkbrkn_loadout_wand\", 0 ) == 1\n    or EntityGetVariableNumber( wand, \"gkbrkn_merge_wand\", 0 ) == 1\n    then\n        return true;\n    end\nend\n\nfunction wand_is_always_cast_valid( wand )\n    local children = EntityGetAllChildren( wand ) or {};\n    for i,v in ipairs( children ) do\n        local items = EntityGetComponentIncludingDisabled( v, \"ItemComponent\" )\n        local has_a_valid_spell = false;\n        for _,item in pairs( items or {}) do\n            if ComponentGetValue2( item, \"permanently_attached\" ) == false then\n                has_a_valid_spell = true;\n                break;\n            end\n        end\n        if has_a_valid_spell then\n            return true;\n        end\n    end\n    return false;\nend\n\nfunction force_always_cast( wand, amount )\n    if amount == nil then amount = 1 end\n    local children = EntityGetAllChildren( wand ) or {};\n    local always_cast_count = 0;\n    for _,child in pairs( children ) do\n        local item_component = EntityGetFirstComponentIncludingDisabled( child, \"ItemComponent\" );\n        if item_component then\n            if ComponentGetValue2( item_component, \"permanently_attached\" ) == true then\n                always_cast_count = always_cast_count + 1;\n                break;\n            end\n        end\n    end\n    while always_cast_count < amount do\n        local random_child = children[ Random( 1,#children ) ];\n        local item_component = EntityGetFirstComponentIncludingDisabled( random_child, \"ItemComponent\" );\n        if item_component and ComponentGetValue2( item_component, \"permanently_attached\" ) ~= true then\n            ComponentSetValue2( item_component, \"permanently_attached\", true );\n            always_cast_count = always_cast_count + 1;\n        end\n    end\nend\n\nfunction initialize_legendary_wand( base_wand, x, y, level, force )\n    dofile( \"mods/gkbrkn_noita/files/gkbrkn/content/legendary_wands.lua\" );\n    for _,child in pairs( EntityGetAllChildren( base_wand ) or {} ) do\n        EntityRemoveFromParent( child );\n    end\n    local shine = EntityLoad( \"mods/gkbrkn_noita/files/gkbrkn/misc/legendary_wands/legendary_wand_shine.xml\" );\n    if shine ~= nil then\n        EntityAddChild( base_wand, shine );\n    end\n    SetRandomSeed( GameGetFrameNum(), x + y );\n    local valid_wands = {};\n    local chosen_wand = force;\n    local content_data = nil;\n    if chosen_wand == nil then\n        for index,content in pairs( legendary_wands ) do\n            if (level == nil or ( level >= content.min_level or 0 and level <= content.max_level or 99 ) ) then\n                table.insert( valid_wands, index );\n            end\n        end\n        chosen_wand = valid_wands[Random( 1, #valid_wands )];\n    end\n    content_data = force or legendary_wands[chosen_wand];\n    content_data.wand.name = content_data.wand.name or GameTextGetTranslatedOrNot( content_data.name );\n    if content_data == nil then print(\"[goki's things] legendary wand error: no wand data found\"); return; end\n    initialize_wand( base_wand, content_data.wand );\nend\n"
_TWWE_VFS["mods/wand_editor/files/misc/self/FixedTarget.lua"] = "dofile_once(\"mods/wand_editor/files/libs/fn.lua\")\nlocal entity = GetUpdatedEntityID()\nlocal x = GetStorageComp(entity, \"fix_pos_x\")\nlocal y\nif x == nil then--初始化\n	x, y = EntityGetTransform(entity)\n	AddSetStorageComp(entity, \"fix_pos_x\", x)\n	AddSetStorageComp(entity, \"fix_pos_y\", y)\nend\nif ModSettingGet(ModID..\".locked_target_pos\") then--假设没有模组更改\n    y = GetStorageComp(entity, \"fix_pos_y\")\n	EntitySetTransform(entity, x, y)\nend\n"
_TWWE_VFS["mods/wand_editor/files/misc/self/Restore.lua"] = "if not ModIsEnabled(\"wand_editor\") then\n    dofile_once(\"mods/wand_editor/files/libs/fn.lua\")\n    RestoreInput() --恢复可能的按键操作\n    local player = GetUpdatedEntityID()\n	if GlobalsGetValue(ModID..\"CameraLocked\") == \"1\" then\n		local PSPComp = EntityGetFirstComponentIncludingDisabled(player, \"PlatformShooterPlayerComponent\")\n		if PSPComp then\n			local center_camera_on_this_entity = ComponentGetValue2(PSPComp, \"center_camera_on_this_entity\")\n			if not center_camera_on_this_entity then\n				ComponentSetValue2(PSPComp, \"center_camera_on_this_entity\", true)\n			end\n		end\n	end\nend\n"
_TWWE_VFS["mods/wand_editor/files/misc/self/editWandEffect.lua"] = "dofile_once(\"mods/wand_editor/files/libs/fn.lua\")\nlocal player = GetPlayer()\nlocal entity = GetUpdatedEntityID()\nif player == 0 or not EntityGetIsAlive(player) then\n	return\nend\n--通过计算来动态删增需要的随编buff\nlocal NoEditCount = GameGetGameEffectCount(player, \"NO_WAND_EDITING\")\nlocal EditCount = GameGetGameEffectCount(player, \"EDIT_WANDS_EVERYWHERE\")\n\nif EditCount <= NoEditCount then\n    for _ = EditCount, NoEditCount do\n        EntityAddComponent2(entity, \"GameEffectComponent\", { effect = \"EDIT_WANDS_EVERYWHERE\", frames = -1 })\n    end\nelseif (EditCount - 1) > NoEditCount then\n    local list = EntityGetComponent(entity, \"GameEffectComponent\")\n	if list == nil then--为空就退出\n		return\n	end\n    for i = NoEditCount, EditCount do\n        local id = list[i]\n		if id == nil then--越界了就退出\n			return\n		end\n        EntityRemoveComponent(entity, id)\n    end\nend\n"
_TWWE_VFS["mods/wand_editor/files/misc/self/player_shot.lua"] = "dofile_once(\"mods/wand_editor/files/misc/bygoki/lib/helper.lua\")\n\nfunction shot( projectile_entity )\n    if ModSettingGet(\"wand_editor\"..\"DisableParticles\") == true then\n        reduce_particles( projectile_entity, true )\n    end\n    EntityAddTag( projectile_entity, \"projectile_player\" )\nend\n"
_TWWE_VFS["mods/wand_editor/files/misc/self/yukimi.lua"] = "return {\n	\"京都の温泉……千秋と入れて……よかった……。今日は……いい日……\",\n	\"別のお仕事……でも、泊まるところは一緒……。こういうのも、素敵……\",\n	\"おっきなお風呂……気持ちいい……。空も見えて……ごくらく気分……\",\n	\"……ふふっ……いつもより……おしゃべりになってる……かも……\",\n	\"おそろいの浴衣なら……もっと姉妹に見える……？……千秋おねえちゃん\",\n	\"プロデューサー……ペロと……何してるかな……。おひるね……？\",\n	\"うん……かゆいところは……ないよ……。千秋……上手……\",\n	\"泡……もこもこで……猫の耳みたいになってる……？ふふ……にゃー……\",\n	\"優しい手……好き……。私の髪……素敵にしてくれるの……わかる……\",\n	\"んん。……大丈夫。目に……泡が入りそうになっただけ……。セーフ……\",\n	\"終わったら、交代……。千秋の洗いかた……覚えたから……まかせて\",\n	\"温泉のあと……手……つないだら……ぽかぽか……伝わる……かな……？\",\n	\"お肌……すべすべ……。温泉の効能と……スキンケア……すごい……\",\n	\"ペロ……お風呂は……ちいさいのがいいって……。お湯は……ぬるめで\",\n	\"シャンプーハットは……してないけど……便利なのは……知ってる……\",\n	\"お仕事でお泊まり……わくわく……。みんなと一緒だと……もっと……\",\n	\"お風呂あがりは……イチゴミルク……。プロデューサーは……？\",\n	\"畳で……ごろーんってしてた……プロデューサー……かわいかった\",\n	\"千秋から……クールニウム……もらったから……オトナに見える……？\",\n	\"ふふ……おだんご……かわいい……。千秋がやってくれたの……ふふ……\",\n	\"浴衣……似合う……？帯も……自分で……結んだの……。こだわり……\",\n	\"旅館のお料理……ごうか……。ジュースも……ビンに……入ってる……\",\n	\"髪……さらさら……。さわって、みる……？なでなでも……いいよ……\",\n	\"プロデューサーの浴衣……めずらしい……。また……見たい……\",\n	\"私……ひとりでできること……増えてきた……。それは……うれしい……けど……ひとりだと……楽しくなるの……むずかしい……。\",\n	\"ペロ……パパ、ママ……お友だち……おねえさんたち……それに……プロデューサーがいるから……楽しい……。一緒にいると……にこにこ……。\",\n	\"不思議……。はじめてのお店……なのに……おちつく……ふんいき……\",\n	\"ちく……たく……ちく……たく……。時計のおと……やわらかい……\",\n	\"ここに座って……お話したり……外を見るの……。私のお気に入り……\",\n	\"ペロも……お店……気に入ったみたい……。センス……合うって……\",\n	\"見て……窓の外……。きれいな夕日……。……私も……きれい……？\",\n	\"プロデューサーと……一緒にいる時間……とっても……大切……\",\n	\"京都のお仕事……だから……ちょっと……はんなり……おねえさん……\",\n	\"マスター……いつもの……。どう……本当の常連さんに……見える……？\",\n	\"お店のオススメは……プリン・ア・ラ・モード……。食べていい……？\",\n	\"この衣装……おしゃれで……かわいくて……和風で……好き、だよ……\",\n	\"ふたりの写真……撮ってもらおう……？私だけの……宝物にする……\",\n	\"ただ……見つめられるのも……いい……。プロデューサーなら……\",\n	\"ここにいるときは……お仕事も……レッスンも……ひとやすみ……\",\n	\"観光の撮影……きれいなところ……たくさん見られて……好き……\",\n	\"喫茶店は……オトナ……。音楽も……メニューも……知らない世界……\",\n	\"レトロモダン……ハイカラ……エモい……。私……どれ……？全部……？\",\n	\"忙しいときも……気にしてくれる……。だから……私も……気にする……\",\n	\"一番の……お気に入りは……プロデューサーの隣……ふふっ……\",\n	\"みんなが……おねえさんに見えるって……。私も……そう思う……ふふ\",\n	\"髪の写真……撮って……。自分で……できるように……覚えたい……\",\n	\"喫茶店の人……やさしかった……。次は……お休みの日に……いこう……\",\n	\"手をつなぐときは……手袋……しない……。ちゃんと……つなぎたい……\",\n	\"この衣装と……お似合いの服……持ってない……？買いにいく……？\",\n	\"プロデューサー……ドキッとするの……どんなとき……？\",\n	\"プロデューサー……ドキッと……した……？ふふ……よかった……。だって…………してる、から……。……ドキッとするような……笑顔……。\",\n	\"私のこと……プロデューサーは……ちゃんと……見てくれている……。だから……安心……がんばれる……。\",\n}\n"
