rs. We intend this dedication to be an\novert act of relinquishment in perpetuity of all present and future rights to\nthis software under copyright law.\nTHE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR\nIMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,\nFITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE\nAUTHORS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN\nACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION\nWITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n"
_TWWE_VFS["mods/wand_editor/mod.xml"] = "<Mod\n	name=\"wand editor\"\n	description=\"Build,edit and learn about wands.\"\n	request_no_api_restrictions=\"1\" \n> \n</Mod>\n"
_TWWE_VFS["mods/wand_editor/proxied_init.lua"] = "dofile_once(\"mods/wand_editor/files/libs/unsafe.lua\")\ndofile_once(\"mods/wand_editor/files/libs/fn.lua\")\ndofile_once(\"mods/wand_editor/files/gui/update.lua\")\ndofile_once(\"data/scripts/lib/utilities.lua\")\n\nif DebugGetIsDevBuild() then\n	Cpp.System(\"chcp 65001\")\nend\n\nModLuaFileAppend(\"data/scripts/gun/gun.lua\", \"mods/wand_editor/files/append/gun.lua\")\nif ModSettingGet(\"wand_editor.real_unlimited_spells\") then\n	ModLuaFileAppend(\"data/scripts/gun/gun_actions.lua\", \"mods/wand_editor/files/append/gun_actions.lua\")\nend\n\nlocal SrcCsv = ModTextFileGetContent(\"data/translations/common.csv\")--设置新语言文件\nlocal AddCsv = ModTextFileGetContent(\"mods/wand_editor/files/lang/lang.csv\")\nModTextFileSetContent(\"data/translations/common.csv\", SrcCsv .. AddCsv)\n--[[测试用，删去注释后每次启动游戏都将删除所有的法杖仓库\nModSettingRemove(ModID..\"WandDepotSize\")\n]]\nif ModSettingGet(ModID .. \"WandDepotSize\") == nil then\n    ModSettingSet(ModID .. \"WandDepotSize\", 0)\nend\n\nif ModSettingGet(ModID .. \".remove_fog_of_war\") then\n    local src = ModTextFileGetContent(\"data/shaders/post_final.vert\")\n    ModTextFileSetContent(\"data/shaders/post_final.vert\",string.gsub(src, \"const float FOG_PIXEL_SIZE = 32.0;\", \"const float FOG_PIXEL_SIZE = 0.0;\"))\nend\n\nlocal AppendPostFinalFrag = [[\n	uniform sampler2D tex_bg;\n	uniform vec4 WandEditor_ENABLE_LIGHTING = vec4(0.0,0.0,0.0,0.0);\n]]\nlocal TempPostFinalFrag = string.gsub(ModTextFileGetContent(\"data/shaders/post_final.frag\"),\"uniform sampler2D tex_bg;\",AppendPostFinalFrag)\n\nlocal _, _, version = string.find(TempPostFinalFrag, \"#version%s(%d+)\")--拉高版本，更好的实现\nif (tonumber(version) < 120) then\n    TempPostFinalFrag = string.gsub(TempPostFinalFrag, \"#version \" .. version, \"#version 120\")\nend\n\nModTextFileSetContent(\"data/shaders/post_final.frag\", string.gsub(TempPostFinalFrag,\"const bool ENABLE_LIGHTING	    		= 1>0;\",\"bool ENABLE_LIGHTING	    		= 1>WandEditor_ENABLE_LIGHTING.x;\"))\n\nlocal cachePath = Cpp.CurrentPath() .. \"/mods/wand_editor/cache\"\nif not Cpp.PathExists(cachePath) then\n    Cpp.CreateDir(cachePath)\nend\n\nif not Cpp.PathExists(cachePath..\"/yukimi\") then\n	Cpp.CreateDir(cachePath..\"/yukimi\")\nend\n\nfunction OnPlayerSpawned(player)\n    RestoreInput() --防止笨蛋在一些情况下重启游戏\n	if GlobalsGetValue(ModID..\"CameraLocked\") == \"1\" then\n		local PSPComp = EntityGetFirstComponentIncludingDisabled(player, \"PlatformShooterPlayerComponent\")\n		if PSPComp then\n			local center_camera_on_this_entity = ComponentGetValue2(PSPComp, \"center_camera_on_this_entity\")\n			if not center_camera_on_this_entity then\n				ComponentSetValue2(PSPComp, \"center_camera_on_this_entity\", true)\n			end\n		end\n	end\n	ModSettingSet(ModID .. \"hasButtonMove\", false)\n    if not GameHasFlagRun(\"wand_editor_init\") then\n        GameAddFlagRun(\"wand_editor_init\")\n        EntityLoadChild(player, \"mods/wand_editor/files/entity/Restore.xml\")\n        EntityAddComponent2(player, \"LuaComponent\", { script_shot = \"mods/wand_editor/files/misc/self/player_shot.lua\" })\n        EntityLoad(\"mods/wand_editor/files/biome_impl/wand_lab/wand_lab.xml\", 12200, -5900)\n        ModSettingSet(ModID .. \"SpellLab\", false)\n		--初始化关于重置实验室的东西\n		if Cpp.PathExists(\"mods/wand_editor/files/biome_impl/wand_lab/reset\") then\n			local t = Cpp.GetDirectoryPath(\"mods/wand_editor/files/biome_impl/wand_lab/reset\")\n            Cpp.Rename(t.File[1], \"mods/wand_editor/files/biome_impl/wand_lab/reset/0\")\n        else\n            Cpp.CreateDir(\"mods/wand_editor/files/biome_impl/wand_lab/reset\")\n            local png = io.open(\"mods/wand_editor/files/biome_impl/wand_lab/wang.png\", \"rb\")\n			io.input(png)\n			local file = io.open(\"mods/wand_editor/files/biome_impl/wand_lab/reset/0\", \"wb\") --将新内容写进文件中\n			file:write(io.read(\"*a\"))\n            file:close()\n			io.close(png)\n		end\n		if Cpp.PathExists(\"mods/wand_editor/files/biome_impl/wand_lab/reset_xml\") then\n			local t = Cpp.GetDirectoryPath(\"mods/wand_editor/files/biome_impl/wand_lab/reset_xml\")\n			Cpp.Rename(t.File[1], \"mods/wand_editor/files/biome_impl/wand_lab/reset_xml/0\")\n        else\n			Cpp.CreateDir(\"mods/wand_editor/files/biome_impl/wand_lab/reset_xml\")\n            local str = ReadFileAll(\"mods/wand_editor/files/biome_impl/wand_lab/overwrite.xml\")\n			local file = io.open(\"mods/wand_editor/files/biome_impl/wand_lab/reset_xml/0\", \"w\") --将新内容写进文件中\n			file:write(str)\n			file:close()\n		end\n\n    end\nend\n\n--GUI绘制\nfunction OnWorldPostUpdate()\n    GUIUpdate()\nend\n"
_TWWE_VFS["mods/wand_editor/settings.lua"] = "dofile(\"data/scripts/lib/mod_settings.lua\")\n\nfunction mod_setting_bool_custom( mod_id, gui, in_main_menu, im_id, setting )\n	local value = ModSettingGetNextValue( mod_setting_get_id(mod_id,setting) )\n	local text = setting.ui_name .. \" - \" .. GameTextGet( value and \"$option_on\" or \"$option_off\" )\n\n	if GuiButton( gui, im_id, mod_setting_group_x_offset, 0, text ) then\n		ModSettingSetNextValue( mod_setting_get_id(mod_id,setting), not value, false )\n	end\n\n	mod_setting_tooltip( mod_id, gui, in_main_menu, setting )\nend\n\nfunction mod_setting_change_callback(mod_id, gui, in_main_menu, setting, old_value, new_value)\n    print(tostring(new_value))\nend\nlocal csv = dofile_once(\"mods/wand_editor/files/libs/csv.lua\")\n\nlocal currentLang = csv(ModTextFileGetContent(\"mods/wand_editor/files/lang/lang.csv\"))\nlocal gameLang = csv(ModTextFileGetContent(\"data/translations/common.csv\"))\nlocal CurrentMap = {}\nfor v,_ in pairs(gameLang.rowHeads) do--构建一个关联表用来查询键值\n	if v ~= \"\" then\n		local tempKey = gameLang.get(\"current_language\",v)\n		CurrentMap[tempKey] = v\n	end\nend\nlocal function GetText(key) --获取文本\n	if key == \"\" then\n		return key\n	end\n	local GameKey\n    local GameTextLangGet = GameTextGet(\"$current_language\")\n	GameKey = CurrentMap[GameTextLangGet]\n    if GameKey == nil then\n        GameKey = \"en\"\n    end\n    local result = currentLang.get(key, GameKey) or \"\"\n	result = string.gsub(result, [[\\n]], \"\\n\")\n	if result == nil or result == \"\" then\n        result = currentLang.get(key, \"en\")\n	end\n	return result\nend\n\n---监听访问\n---@param t table\n---@param callback function\nlocal function TableListener(t, callback)\n    local function NewListener()\n        local __data = {}\n        local deleteList = {}\n        for k, v in pairs(t) do\n            __data[k] = v\n            deleteList[#deleteList + 1] = k\n        end\n        for _, v in pairs(deleteList) do\n            t[v] = nil\n        end\n        local result = {\n            __newindex = function(table, key, value)\n                local temp = callback(key, value)\n                value = temp or value\n                rawset(__data, key, value)\n                rawset(table, key, nil)\n            end,\n            __index = function(table, key)\n                local temp = callback(key, rawget(__data, key))\n				if temp == nil then\n					return rawget(__data, key)\n                else\n					return temp\n				end\n            end,\n            __call = function()\n                return __data\n            end\n        }\n        return result\n    end\n	setmetatable(t, NewListener())\nend\n\nlocal function Setting(t)\n    TableListener(t, function(key, value)\n        if key == \"ui_name\" or key == \"ui_description\" then\n            local result = GetText(value)\n            return result\n        end\n    end)\n    return t\nend\n\nlocal function GetTextOrKey(key)\n    local result = GetText(key)\n    return result or key\nend\n\nlocal function ValueListInit(t)\n    TableListener(t, function(key, value)\n        return GetTextOrKey(value)\n    end)\n    return t\nend\n\nlocal function ValueList(t)\n	for k,v in pairs(t)do\n		t[k] = ValueListInit(v)\n	end\n	return t\nend\n\nlocal IKnowWhatImDoing_wand_editor_reset_btn_pos = false\n\nlocal mod_id = \"wand_editor\"\nlocal ModID = mod_id\nmod_settings_version = 1\nmod_settings = \n{\n	Setting({\n        id = \"auto_update\",\n		ui_name = \"wand_editor_auto_update\",\n		ui_description = \"wand_editor_auto_update_tips\",\n		value_default = false,\n        scope = MOD_SETTING_SCOPE_RUNTIME,\n    }),\n	Setting({\n        id = \"spell_mod_id_or_name\",\n		ui_name = \"wand_editor_spell_mod_id_or_name\",\n        value_default = \"name\",\n        values = ValueList({\n            { \"name\", \"wand_editor_spell_mod_id_or_name_only_name\" },\n            { \"id\", \"wand_editor_spell_mod_id_or_name_only_id\" },\n            { \"all\", \"wand_editor_spell_mod_id_or_name_all\" },\n		}),\n        scope = MOD_SETTING_SCOPE_RUNTIME,\n    }),\n	Setting({\n        id = \"cache_spell_data\",\n		ui_name = \"wand_editor_no_spell_cache\",\n		ui_description = \"wand_editor_no_spell_cache_tip\",\n		value_default = true,\n        scope = MOD_SETTING_SCOPE_RUNTIME,\n    }),\n	Setting({\n        id = \"locked_target_pos\",\n		ui_name = \"wand_editor_locked_target_pos\",\n		ui_description = \"wand_editor_locked_target_pos_tip\",\n		value_default = true,\n        scope = MOD_SETTING_SCOPE_RUNTIME,\n    }),\n	Setting({\n        id = \"split_search_text\",\n		ui_name = \"wand_editor_split_search_text\",\n		ui_description = \"wand_editor_split_search_text_tip\",\n		value_default = false,\n        scope = MOD_SETTING_SCOPE_RUNTIME,\n    }),\n	Setting({\n        id = \"real_unlimited_spells\",\n		ui_name = \"wand_editor_real_unlimited_spells\",\n		ui_description = \"wand_editor_real_unlimited_spells_tips\",\n		value_default = false,\n        scope = MOD_SETTING_SCOPE_RUNTIME_RESTART,\n    }),\n	Setting({\n        id = \"remove_fog_of_war\",\n		ui_name = \"wand_editor_remove_fog_of_war\",\n		ui_description = \"wand_editor_remove_fog_of_war_tip\",\n		value_default = false,\n        scope = MOD_SETTING_SCOPE_RUNTIME_RESTART,\n    }),\n    Setting({\n        id = \"reset_all_btn_in_setting\",\n		ui_name = \"\",\n		ui_description = \"\",\n        ui_fn = function(mod_id, gui, in_main_menu, im_id, setting)\n			GuiIdPushString(gui,\"wand_editor\")\n            local click = GuiButton(gui, 1, 0, 0, GetTextOrKey(\"wand_editor_reset_btn_pos\"))\n            local _, _, hover = GuiGetPreviousWidgetInfo(gui)\n			if not hover and IKnowWhatImDoing_wand_editor_reset_btn_pos then\n				IKnowWhatImDoing_wand_editor_reset_btn_pos = false\n			end\n            if click and not ModSettingGet(\"wand_editor.reset_all_btn\") and not IKnowWhatImDoing_wand_editor_reset_btn_pos then\n                IKnowWhatImDoing_wand_editor_reset_btn_pos = true\n			elseif click and IKnowWhatImDoing_wand_editor_reset_btn_pos then\n                ModSettingSet(\"wand_editor.reset_all_btn\", true)\n				IKnowWhatImDoing_wand_editor_reset_btn_pos = false\n            end\n			if IKnowWhatImDoing_wand_editor_reset_btn_pos then\n				GuiTooltip(gui,GetTextOrKey(\"wand_editor_reset_btn_pos_IKnowWhatImDoing\"),\"\")\n            else\n				GuiTooltip(gui,GetTextOrKey(\"wand_editor_reset_btn_pos_tip\"),\"\")\n			end\n			GuiIdPop(gui)\n		end\n    }),\n	Setting({\n        category_id = \"load_other_wand_box_btns\",\n		ui_name = \"wand_editor_load_other_wand_box\",\n        ui_description = \"\",\n		foldable = true,\n		settings = {\n			Setting({\n				id = \"load_spell_lab\",\n				ui_name = \"\",\n				ui_description = \"\",\n				ui_fn = function(mod_id, gui, in_main_menu, im_id, setting)\n					GuiIdPushString(gui,\"wand_editor\")\n                    local click = GuiButton(gui, 2, 0, 0, GetTextOrKey(\"wand_editor_load_spell_lab_wand_box\"))\n					GuiTooltip(gui,GetTextOrKey(\"wand_editor_load_spell_lab_wand_box_tip\"),\"\")\n					if click then\n						ModSettingSet(ModID..\"LoadSpellLab\", true)\n					end\n					GuiIdPop(gui)\n				end,\n            }),\n			Setting({\n				id = \"load_wands_conn\",\n				ui_name = \"\",\n				ui_description = \"\",\n				ui_fn = function(mod_id, gui, in_main_menu, im_id, setting)\n                    GuiIdPushString(gui, \"wand_editor\")\n					local click = GuiButton(gui, 3, 0, 0, GetTextOrKey(\"wand_editor_load_wands_conn_wand_box\"))\n                    GuiTooltip(gui, GetTextOrKey(\"wand_editor_load_wands_conn_wand_box_tip\"), \"\")\n					if click then\n						ModSettingSet(ModID..\"LoadECSSpellLab\", true)\n					end\n					GuiIdPop(gui)\n				end,\n            }),\n			Setting({\n				id = \"load_spell_lab_shug\",\n				ui_name = \"\",\n				ui_description = \"\",\n				ui_fn = function(mod_id, gui, in_main_menu, im_id, setting)\n					GuiIdPushString(gui,\"wand_editor\")\n					local click = GuiButton(gui, 4, 0, 0, GetTextOrKey(\"wand_editor_load_spell_lab_shug_wand_box\"))\n                    GuiTooltip(gui, GetTextOrKey(\"wand_editor_load_spell_lab_shug_wand_box_tip\"), \"\")\n					if click then\n						ModSettingSet(ModID..\"LoadSpellLabShug\", true)\n					end\n					GuiIdPop(gui)\n				end,\n			})\n		}\n    }),\n}\n\nfunction ModSettingsUpdate( init_scope )\n	local old_version = mod_settings_get_version( mod_id )\n	mod_settings_update( mod_id, mod_settings, init_scope )\nend\n\nfunction ModSettingsGuiCount()\n	return mod_settings_gui_count( mod_id, mod_settings )\nend\n\nfunction ModSettingsGui( gui, in_main_menu )\n	mod_settings_gui( mod_id, mod_settings, gui, in_main_menu )\nend\n"
_TWWE_VFS["mods/wand_editor/unsafeFn.lua"] = "--这个文件大概率不会更新了\n\n---读取整个文件\n---@param path string\n---@return string\nfunction ReadFileAll(path)\n    local resultCache = {}\n	local cacheCount = 1\n    for v in io.lines(path) do\n        resultCache[cacheCount] = v\n        resultCache[cacheCount + 1] = '\\n'\n        cacheCount = cacheCount + 2\n    end\n    return table.concat(resultCache)\nend\n\n---参数1是被覆写的文件路径，参数2是用于覆写的文件路径\n---@param filePath string\n---@param path string\nfunction RewriteBinFile(filePath, path)\n    local GetPathFile = io.open(path, \"rb\")\n    local allData = GetPathFile:read(\"*a\")\n    local file = io.open(filePath, \"wb\")\n	file:write(allData)\n    GetPathFile:close()\n	file:close()\nend\n"
_TWWE_VFS["mods/wand_sync/init.lua"] = "-- wand_sync/init.lua\nlocal WAND_EDITOR_PATH = \"mods/wand_editor/\"\nfunction ws_log(msg) print(\"[WandSync] \" .. tostring(msg)) end\n\npackage.cpath = package.cpath .. \";./\" .. WAND_EDITOR_PATH .. \"files/module/?.dll;./\" .. WAND_EDITOR_PATH .. \"files/module/socket/?.dll\"\npackage.path = package.path .. \";./\" .. WAND_EDITOR_PATH .. \"files/socket_lua/?.lua;./\" .. WAND_EDITOR_PATH .. \"files/socket_lua/socket/?.lua\"\n\nlocal effil = require(\"effil\")\nlocal Cpp = nil\npcall(function() Cpp = require(\"WandEditorDll\") end)\n\nlocal game_root = \".\"\nif Cpp and Cpp.CurrentPath then game_root = Cpp.CurrentPath() end\nws_log(\"Game root identified: \" .. game_root)\n\nlocal sync_channel = effil.channel()\nlocal response_channel = effil.channel()\n\nlocal function table_to_json(t)\n    if t == nil then return \"null\" end\n    if type(t) == \"number\" or type(t) == \"boolean\" then return tostring(t) end\n    if type(t) == \"string\" then \n        return '\"' .. t:gsub('\\\\', '\\\\\\\\'):gsub('\"', '\\\\\"'):gsub(\"\\n\", \"\\\\n\"):gsub(\"\\r\", \"\\\\r\"):gsub(\"\\t\", \"\\\\t\") .. '\"' \n    end\n    local parts = {}\n    local is_arr = false\n    if t[1] ~= nil then is_arr = true end\n    if is_arr then\n        for i=1, #t do table.insert(parts, table_to_json(t[i])) end\n        return \"[\" .. table.concat(parts, \",\") .. \"]\"\n    else\n        for k, v in pairs(t) do \n            table.insert(parts, '\"' .. tostring(k) .. '\":' .. table_to_json(v)) \n        end\n        return \"{\" .. table.concat(parts, \",\") .. \"}\"\n    end\nend\n\nlocal function parse_json(s)\n    if not s or s == \"\" then return nil end\n    local p = s:gsub('null', 'nil'):gsub('%[', '{'):gsub('%]', '}'):gsub('\"([^\"]-)\":', '[\"%1\"]=')\n    local f = loadstring(\"return \" .. p)\n    if f then \n        local ok, res = pcall(f)\n        if ok then return res end\n    end\n    return nil\nend\n\nlocal function server_thread_func(chan, resp_chan, pkg_path, pkg_cpath, root_path)\n    package.path = pkg_path; package.cpath = pkg_cpath\n    local socket = require(\"socket\")\n    local server = socket.tcp()\n    server:setoption(\"reuseaddr\", true)\n    if not server:bind(\"127.0.0.1\", 12345) then return end\n    server:listen(5); server:settimeout(0)\n    local function safe_send(client, data)\n        local total = #data\n        local sent = 0\n        while sent < total do\n            local s, err, last = client:send(data, sent + 1)\n            if s then\n                sent = s\n            elseif err == \"timeout\" then\n                sent = last\n            else\n                return false, err\n            end\n        end\n        return true\n    end\n\n    while true do\n        local client = server:accept()\n        if client then\n            client:settimeout(5) -- 增加超时时间到 5s\n            local line = client:receive(\"*l\")\n            if line == \"GET_ALL_WANDS\" then\n                chan:push(\"REQUEST_FETCH\")\n                safe_send(client, (resp_chan:pop(2) or \"{}\") .. \"\\n\")\n            elseif line == \"GET_WAND_EDITOR_DATA\" then\n                chan:push(\"REQUEST_WAND_EDITOR\")\n                safe_send(client, (resp_chan:pop(2) or \"{}\") .. \"\\n\")\n            elseif line == \"GET_SPELL_LAB_DATA\" then\n                chan:push(\"REQUEST_SPELL_LAB\")\n                safe_send(client, (resp_chan:pop(2) or \"{}\") .. \"\\n\")\n            elseif line == \"GET_ALL_SPELLS\" then\n                chan:push(\"REQUEST_ALL_SPELLS\")\n                safe_send(client, (resp_chan:pop(15) or \"[]\") .. \"\\n\")\n            elseif line == \"GET_MOD_APPENDS\" then\n                chan:push(\"REQUEST_MOD_APPENDS\")\n                safe_send(client, (resp_chan:pop(15) or \"{}\") .. \"\\n\")\n            elseif line == \"GET_ACTIVE_MODS\" then\n                chan:push(\"REQUEST_ACTIVE_MODS\")\n                safe_send(client, (resp_chan:pop(2) or \"[]\") .. \"\\n\")\n            elseif line == \"GET_GAME_INFO\" then\n                safe_send(client, '{\"root\":\"' .. root_path:gsub(\"\\\\\", \"/\") .. '\"}\\n')\n            elseif line then\n                chan:push(\"DATA:\" .. line)\n                safe_send(client, \"OK\\n\")\n            end\n            client:close()\n        end\n        require(\"effil\").sleep(0.05)\n    end\nend\neffil.thread(server_thread_func)(sync_channel, response_channel, package.path, package.cpath, game_root)\n\nlocal function GetWandAtSlot(slot)\n    local p = EntityGetWithTag(\"player_unit\")[1]\n    if not p then return nil end\n    local inv = nil\n    for _, c in ipairs(EntityGetAllChildren(p) or {}) do if EntityGetName(c) == \"inventory_quick\" then inv = c break end end\n    if not inv then return nil end\n    for _, item in ipairs(EntityGetAllChildren(inv) or {}) do\n        local ic = EntityGetFirstComponentIncludingDisabled(item, \"ItemComponent\")\n        if ic and ComponentGetValue2(ic, \"inventory_slot\") == (slot - 1) then return item end\n    end\n    return nil\nend\n\nlocal function serialize_wand(w)\n    local ab = EntityGetFirstComponentIncludingDisabled(w, \"AbilityComponent\")\n    if not ab then return nil end\n\n    local appearance = {}\n    local sprite_file = ComponentGetValue2(ab, \"sprite_file\")\n    appearance.sprite = sprite_file\n\n    local item_comp = EntityGetFirstComponentIncludingDisabled(w, \"ItemComponent\")\n    if item_comp then\n        appearance.name = ComponentGetValue2(item_comp, \"item_name\")\n    end\n\n    -- 尝试获取 SpriteComponent (tag=\"item\") 上的 image_file (PNG 路径)\n    -- 这比 AbilityComponent.sprite_file (XML) 更适合直接在前端显示\n    local all_sprites = EntityGetComponentIncludingDisabled(w, \"SpriteComponent\") or {}\n    for _, sc in ipairs(all_sprites) do\n        local tags = ComponentGetTags(sc)\n        if tags and string.find(tags, \"item\") then\n            local img = ComponentGetValue2(sc, \"image_file\")\n            if img and img ~= \"\" then\n                appearance.item_sprite = img\n            end\n            break\n        end\n    end\n\n    local data = {\n        mana_max = ComponentGetValue2(ab, \"mana_max\"),\n        mana_charge_speed = ComponentGetValue2(ab, \"mana_charge_speed\"),\n        reload_time = ComponentObjectGetValue2(ab, \"gun_config\", \"reload_time\"),\n        fire_rate_wait = ComponentObjectGetValue2(ab, \"gunaction_config\", \"fire_rate_wait\"),\n        deck_capacity = ComponentObjectGetValue2(ab, \"gun_config\", \"deck_capacity\"),\n        shuffle_deck_when_empty = ComponentObjectGetValue2(ab, \"gun_config\", \"shuffle_deck_when_empty\"),\n        spread_degrees = ComponentObjectGetValue2(ab, \"gunaction_config\", \"spread_degrees\"),\n        speed_multiplier = ComponentObjectGetValue2(ab, \"gunaction_config\", \"speed_multiplier\"),\n        actions_per_round = ComponentObjectGetValue2(ab, \"gun_config\", \"actions_per_round\") or 1,\n        spells = {}, always_cast = {}\n    }\n    data.appearance = appearance\n\n    for _, c in ipairs(EntityGetAllChildren(w) or {}) do\n        local ac = EntityGetFirstComponentIncludingDisabled(c, \"ItemActionComponent\")\n        local ic = EntityGetFirstComponentIncludingDisabled(c, \"ItemComponent\")\n        if ac and ic then\n            local id = ComponentGetValue2(ac, \"action_id\")\n            if ComponentGetValue2(ic, \"permanently_attached\") then table.insert(data.always_cast, id)\n            else local x, y = ComponentGetValue2(ic, \"inventory_slot\"); data.spells[tostring(x+1)] = id end\n        end\n    end\n    return data\nend\n\nlocal function ApplyFullWand(w, data)\n    local ab = EntityGetFirstComponentIncludingDisabled(w, \"AbilityComponent\")\n    if not ab then return end\n    if data.mana_max then ComponentSetValue2(ab, \"mana_max\", tonumber(data.mana_max)) ComponentSetValue2(ab, \"mana\", tonumber(data.mana_max)) end\n    if data.mana_charge_speed then ComponentSetValue2(ab, \"mana_charge_speed\", tonumber(data.mana_charge_speed)) end\n    if data.reload_time then ComponentObjectSetValue2(ab, \"gun_config\", \"reload_time\", tonumber(data.reload_time)) end\n    if data.fire_rate_wait then ComponentObjectSetValue2(ab, \"gunaction_config\", \"fire_rate_wait\", tonumber(data.fire_rate_wait)) end\n    if data.deck_capacity then ComponentObjectSetValue2(ab, \"gun_config\", \"deck_capacity\", tonumber(data.deck_capacity)) end\n    if data.shuffle_deck_when_empty ~= nil then ComponentObjectSetValue2(ab, \"gun_config\", \"shuffle_deck_when_empty\", data.shuffle_deck_when_empty) end\n    if data.spread_degrees then ComponentObjectSetValue2(ab, \"gunaction_config\", \"spread_degrees\", tonumber(data.spread_degrees)) end\n    if data.speed_multiplier then ComponentObjectSetValue2(ab, \"gunaction_config\", \"speed_multiplier\", tonumber(data.speed_multiplier)) end\n    if data.actions_per_round then ComponentObjectSetValue2(ab, \"gun_config\", \"actions_per_round\", tonumber(data.actions_per_round)) end\n    \n    if data.appearance then\n        local app = data.appearance\n        if app.sprite then\n            ComponentSetValue2(ab, \"sprite_file\", app.sprite)\n        end\n        if app.name then\n            local ic = EntityGetFirstComponentIncludingDisabled(w, \"ItemComponent\")\n            if ic then\n                ComponentSetValue2(ic, \"item_name\", app.name)\n                ComponentSetValue2(ic, \"always_use_item_name_in_ui\", true)\n            end\n        end\n        if app.item_sprite then\n            local sc = EntityGetFirstComponentIncludingDisabled(w, \"SpriteComponent\", \"item\")\n            if sc then\n                ComponentSetValue2(sc, \"image_file\", app.item_sprite)\n            end\n        end\n        EntityRefreshSprite(w, EntityGetFirstComponentIncludingDisabled(w, \"SpriteComponent\", \"item\"))\n    end\n\n    if data.spells or data.always_cast then\n        for _, c in ipairs(EntityGetAllChildren(w) or {}) do if EntityHasTag(c, \"card_action\") then EntityKill(c) end end\n        if data.always_cast then\n            for i, id in ipairs(data.always_cast) do\n                local s = CreateItemActionEntity(id)\n                if s then\n                    local ic = EntityGetFirstComponentIncludingDisabled(s, \"ItemComponent\")\n                    ComponentSetValue2(ic, \"permanently_attached\", true); ComponentSetValue2(ic, \"inventory_slot\", 0, i)\n                    EntityAddChild(w, s)\n                end\n            end\n        end\n        if data.spells then\n            for i, id in pairs(data.spells) do\n                if id and id ~= \"null\" then\n                    local s = CreateItemActionEntity(id)\n                    if s then\n                        local ic = EntityGetFirstComponentIncludingDisabled(s, \"ItemComponent\")\n                        ComponentSetValue2(ic, \"inventory_slot\", tonumber(i)-1, 0)\n                        EntityAddChild(w, s)\n                    end\n                end\n            end\n        end\n    end\n    local p = EntityGetWithTag(\"player_unit\")[1]\n    if p then local i2 = EntityGetFirstComponent(p, \"Inventory2Component\"); if i2 then ComponentSetValue2(i2, \"mForceRefresh\", true) end end\nend\n\nfunction OnWorldPostUpdate()\n    local msg = sync_channel:pop(0)\n    if msg == \"REQUEST_FETCH\" then\n        local all = {}\n        for i=1, 4 do local w = GetWandAtSlot(i); if w then all[tostring(i)] = serialize_wand(w) end end\n        response_channel:push(table_to_json(all))\n    elseif msg == \"REQUEST_WAND_EDITOR\" then\n        local pages = {}\n        local idx = 1\n        while true do\n            -- Try both with and without mod prefix\n            local val = ModSettingGet(\"wand_editor.wand_editorWandDepot\" .. tostring(idx)) or ModSettingGet(\"wand_editorWandDepot\" .. tostring(idx))\n            if val then\n                table.insert(pages, val)\n                idx = idx + 1\n            else\n                break\n            end\n        end\n        response_channel:push(table_to_json(pages))\n    elseif msg == \"REQUEST_SPELL_LAB\" then\n        local data = {}\n        -- Spell Lab Shugged\n        local max_idx = ModSettingGet(\"spell_lab_shugged.spell_lab_shugged.wand_box_page_max_index\") or ModSettingGet(\"spell_lab_shugged.wand_box_page_max_index\")\n        if max_idx then\n            data.shugged = {}\n            for i = 1, max_idx do\n                local val = ModSettingGet(\"spell_lab_shugged.spell_lab_shugged.wand_box_page_\" .. tostring(i)) or ModSettingGet(\"spell_lab_shugged.wand_box_page_\" .. tostring(i))\n                if val then table.insert(data.shugged, val) end\n            end\n        end\n        -- Original Spell Lab\n        local orig = ModSettingGet(\"spell_lab.spell_lab_saved_wands\") or ModSettingGet(\"spell_lab_saved_wands\")\n        if orig then data.original = orig end\n        \n        response_channel:push(table_to_json(data))\n    elseif msg == \"REQUEST_ALL_SPELLS\" then\n        ws_log(\"Processing REQUEST_ALL_SPELLS with deep analysis...\")\n        if not actions then\n            dofile(\"data/scripts/gun/gun_enums.lua\")\n            dofile(\"data/scripts/gun/gun_actions.lua\")\n        end\n\n        -- 模拟 wand_editor 的环境抓取法术属性\n        local dummy_c = {}\n        local function reset_c()\n            dummy_c = {\n                fire_rate_wait = 0,\n                reload_time = 0,\n                spread_degrees = 0,\n                speed_multiplier = 1,\n                mana_max = 0,\n                mana_charge_speed = 0,\n                extra_entities = \"\",\n            }\n        end\n        \n        -- 临时替换全局变量和危险函数以防同步时触发法术效果\n        local old_c = c\n        local old_shot_effects = shot_effects\n        local old_GlobalsSetValue = GlobalsSetValue\n        local old_StartReload = StartReload\n        local old_GamePrint = GamePrint\n        local old_GamePrintImportant = GamePrintImportant\n        local old_GameScreenshake = GameScreenshake\n        local old_PlaySound = PlaySound\n        local old_reflecting = reflecting\n        \n        -- 劫持所有可能产生实体的底层 API\n        local old_EntityLoad = EntityLoad\n        local old_EntityLoadCameraBound = EntityLoadCameraBound\n        local old_EntityLoadToEntity = EntityLoadToEntity\n        local old_EntityLoadEndGameItem = EntityLoadEndGameItem\n        local old_EntityCreateNew = EntityCreateNew\n        local old_EntityAddChild = EntityAddChild\n        local old_EntityAddComponent = EntityAddChild\n        local old_EntityInflictDamage = EntityInflictDamage\n        local old_add_projectile = add_projectile\n        local old_add_projectile_trigger_timer = add_projectile_trigger_timer\n        local old_add_projectile_trigger_hit_world = add_projectile_trigger_hit_world\n        local old_add_projectile_trigger_death = add_projectile_trigger_death\n        local old_GameShootProjectile = GameShootProjectile\n        local old_CreateItemActionEntity = CreateItemActionEntity\n\n        -- 定义更聪明的 Stub 函数\n        local function dummy_id() return 12345678 end\n        local function dummy_table() return {12345678} end\n        local dummy_fn = function() end\n        \n        -- 核心环境隔离\n        c = dummy_c\n        shot_effects = {}\n        reflecting = true \n        WAND_EDITOR_RELEFCTING = true -- 很多 Mod 识别这个\n        \n        -- 全局屏蔽\n        GlobalsSetValue = dummy_fn\n        GamePrint = dummy_fn\n        GamePrintImportant = dummy_fn\n        GameScreenshake = dummy_fn\n        PlaySound = dummy_fn\n        \n        -- 实体操作屏蔽（返回假 ID 避免脚本报错）\n        EntityLoad = dummy_id\n        EntityLoadCameraBound = dummy_id\n        EntityLoadToEntity = dummy_id\n        EntityLoadEndGameItem = dummy_id\n        EntityCreateNew = dummy_id\n        EntityAddChild = dummy_id\n        EntityAddComponent = dummy_id\n        EntityInflictDamage = dummy_fn\n        add_projectile = dummy_fn\n        add_projectile_trigger_timer = dummy_fn\n        add_projectile_trigger_hit_world = dummy_fn\n        add_projectile_trigger_death = dummy_fn\n        GameShootProjectile = dummy_fn\n        CreateItemActionEntity = dummy_id\n        \n        -- 抓取 StartReload\n        local temp_reload = 0\n        StartReload = function(reload_time)\n            temp_reload = reload_time\n        end\n\n        local old_draw_actions = draw_actions\n        draw_actions = dummy_fn\n\n        local function get_mod_id_from_path(path)\n            if type(path) ~= \"string\" then return nil end\n            if path:sub(1, 5) ~= \"mods/\" then return nil end\n            local next_slash = path:find(\"/\", 6)\n            if not next_slash then return nil end\n            return path:sub(6, next_slash - 1)\n        end\n\n        local function detect_mod_id(action)\n            if not action then return nil end\n            if action.action and type(action.action) == \"function\" and debug and debug.getinfo then\n                local info = debug.getinfo(action.action, \"S\")\n                if info and type(info.source) == \"string\" then\n                    local src = info.source\n                    if src:sub(1, 1) == \"@\" then src = src:sub(2) end\n                    local mod_id = get_mod_id_from_path(src)\n                    if mod_id then return mod_id end\n                end\n            end\n            return get_mod_id_from_path(action.custom_xml_file) or get_mod_id_from_path(action.sprite)\n        end\n\n        -- 预读取 Mod Appends，并从脚本中推断覆盖的法术 ID\n        local appends = ModLuaFileGetAppends(\"data/scripts/gun/gun_actions.lua\") or {}\n        local append_data = {}\n        local override_map = {}\n        local function mark_override(mod_id, spell_id)\n            if not mod_id or not spell_id or spell_id == \"\" then return end\n            override_map[spell_id] = mod_id\n        end\n\n        for _, path in ipairs(appends) do\n            local content = ModTextFileGetContent(path) or \"\"\n            append_data[path] = content\n            local mod_id = get_mod_id_from_path(path)\n            if mod_id and content ~= \"\" then\n                for id in content:gmatch('actions%[%s*\"([%w_]+)\"%s*%]') do\n                    mark_override(mod_id, id)\n                end\n                for id in content:gmatch(\"actions%[%s*'([%w_]+)'%s*%]\") do\n                    mark_override(mod_id, id)\n                end\n                for id in content:gmatch('%[%s*\"([%w_]+)\"%s*%]%s*=%s*{') do\n                    mark_override(mod_id, id)\n                end\n                for id in content:gmatch(\"%[%s*'([%w_]+)'%s*%]%s*=%s*{\") do\n                    mark_override(mod_id, id)\n                end\n                for id in content:gmatch('id%s*=%s*\"([%w_]+)\"') do\n                    mark_override(mod_id, id)\n                end\n                for id in content:gmatch(\"id%s*=%s*'([%w_]+)'\") do\n                    mark_override(mod_id, id)\n                end\n            end\n        end\n        \n        local all_actions = {}\n        for _, a in ipairs(actions or {}) do\n            if a and a.id then\n                reset_c()\n                temp_reload = 0\n                -- 执行 action\n                if a.action and type(a.action) == \"function\" then\n                    -- 给 action 传入一个假的卡牌对象，模仿游戏内的调用\n                    local dummy_card = { \n                        id = a.id, \n                        custom_xml_file = a.custom_xml_file,\n                        mana = a.mana,\n                        action = a.action\n                    }\n                    pcall(a.action, dummy_card)\n                end\n\n                local mod_id = detect_mod_id(a) or override_map[a.id]\n                table.insert(all_actions, {\n                    id = a.id,\n                    name = GameTextGetTranslatedOrNot(a.name or \"\"),\n                    sprite = a.sprite or \"\",\n                    type = a.type or 0,\n                    max_uses = a.max_uses or -1,\n                    mana = a.mana or 0,\n                    fire_rate_wait = dummy_c.fire_rate_wait,\n                    reload_time = dummy_c.reload_time ~= 0 and dummy_c.reload_time or temp_reload,\n                    spread_degrees = dummy_c.spread_degrees,\n                    speed_multiplier = dummy_c.speed_multiplier,\n                    custom_xml_file = a.custom_xml_file,\n                    never_unlimited = a.never_unlimited or false,\n                    mod_id = mod_id\n                })\n            end\n        end\n        \n        -- 彻底还原\n        c = old_c\n        shot_effects = old_shot_effects\n        reflecting = old_reflecting\n        WAND_EDITOR_RELEFCTING = nil\n        GlobalsSetValue = old_GlobalsSetValue\n        StartReload = old_StartReload\n        GamePrint = old_GamePrint\n        GamePrintImportant = old_GamePrintImportant\n        GameScreenshake = old_GameScreenshake\n        PlaySound = old_PlaySound\n        \n        EntityLoad = old_EntityLoad\n        EntityLoadCameraBound = old_EntityLoadCameraBound\n        EntityLoadToEntity = old_EntityLoadToEntity\n        EntityLoadEndGameItem = old_EntityLoadEndGameItem\n        EntityCreateNew = old_EntityCreateNew\n        EntityAddChild = old_EntityAddChild\n        EntityAddComponent = old_EntityAddComponent\n        EntityInflictDamage = old_EntityInflictDamage\n        add_projectile = old_add_projectile\n        add_projectile_trigger_timer = old_add_projectile_trigger_timer\n        add_projectile_trigger_hit_world = old_add_projectile_trigger_hit_world\n        add_projectile_trigger_death = old_add_projectile_trigger_death\n        GameShootProjectile = old_GameShootProjectile\n        CreateItemActionEntity = old_CreateItemActionEntity\n        draw_actions = old_draw_actions\n        \n        local response = {\n            spells = all_actions,\n            appends = append_data,\n            active_mods = ModGetActiveModIDs() or {}\n        }\n        \n        ws_log(\"Encoding \" .. #all_actions .. \" spells and \" .. #appends .. \" appends...\")\n        response_channel:push(table_to_json(response))\n    elseif msg == \"REQUEST_MOD_APPENDS\" then\n        local appends = ModLuaFileGetAppends(\"data/scripts/gun/gun_actions.lua\") or {}\n        local data = {}\n        for _, path in ipairs(appends) do\n            data[path] = ModTextFileGetContent(path)\n        end\n        response_channel:push(table_to_json(data))\n    elseif msg == \"REQUEST_ACTIVE_MODS\" then\n        response_channel:push(table_to_json(ModGetActiveModIDs() or {}))\n    elseif msg and msg:sub(1,5) == \"DATA:\" then\n        local data = parse_json(msg:sub(6))\n        if data and not data.ping then\n            local slot = tonumber(data.slot) or 1\n            local w = GetWandAtSlot(slot)\n            \n            if data.delete then\n                if w then EntityKill(w) end\n            else\n                if not w and slot <= 4 then\n                    -- Try to spawn a new wand if it doesn't exist in the slot\n                    local player = EntityGetWithTag(\"player_unit\")[1]\n                    if player then\n                        local x, y = EntityGetTransform(player)\n                        w = EntityLoad(\"data/entities/items/wand_level_01.xml\", x, y)\n                        \n                        -- CRITICAL: Disable physics and sprites that cause \"ghosts\" at 0,0\n                        local components = EntityGetAllComponents(w) or {}\n                        for _, c in ipairs(components) do\n                            local type_name = ComponentGetTypeName(c)\n                            -- These components cause world-space rendering or physics bobbing\n                            if type_name == \"SpriteOffsetAnimComponent\" or \n                               type_name == \"VelocityComponent\" or \n                               type_name == \"SimplePhysicsComponent\" or\n                               type_name == \"PhysicsBodyComponent\" or\n                               type_name == \"LuaComponent\" then\n                                EntityRemoveComponent(w, c)\n                            end\n                        end\n\n                        local ic = EntityGetFirstComponentIncludingDisabled(w, \"ItemComponent\")\n                        if ic then\n                            ComponentSetValue2(ic, \"inventory_slot\", slot - 1, 0)\n                            ComponentSetValue2(ic, \"is_on_floor\", false)\n                            ComponentSetValue2(ic, \"is_pickable\", false)\n                            ComponentSetValue2(ic, \"mItemIsInventoryItem\", true)\n                        end\n\n                        -- Find quick inventory and force child attachment\n                        local inv = nil\n                        for _, c in ipairs(EntityGetAllChildren(player) or {}) do \n                            if EntityGetName(c) == \"inventory_quick\" then inv = c break end \n                        end\n                        if inv then \n                            EntityAddChild(inv, w)\n                            EntitySetTransform(w, 0, 0) \n                        end\n\n                        -- Force refresh inventory UI\n                        local i2 = EntityGetFirstComponent(player, \"Inventory2Component\")\n                        if i2 then\n                            ComponentSetValue2(i2, \"mForceRefresh\", true)\n                        end\n                    end\n                end\n                \n                if w then ApplyFullWand(w, data) end\n            end\n        end\n    end\nend\nws_log(\"WandSync Ready!\")\n"
_TWWE_VFS["mods/wand_sync/mod.xml"] = "<Mod\n	name=\"Wand Sync (External Editor)\"\n	description=\"Syncs wand data from an external editor via Socket. Requires wand_editor.\"\n	request_no_api_restrictions=\"1\"\n>\n</Mod>"
_TWWE_VFS["mods/x3inventory/compatibility.xml"] = "<Mod _format_version=\"0\" version_built_with=\"7\" >\n\n</Mod>\n\n"
_TWWE_VFS["mods/x3inventory/init.lua"] = "local LOAD_KEY = \"INVENTORY_X3_LOAD_DONE\"\n\nfunction OnPlayerSpawned( player_entity )\n\n	if GlobalsGetValue(LOAD_KEY, \"0\") == \"1\" then\n		return\n	end\n	GlobalsSetValue(LOAD_KEY, \"1\")\n\n	local inventorycomponents = EntityGetFirstComponent( player_entity, \"Inventory2Component\" )\n	if(inventorycomponents ~= nil) then\n		local inventorysize = tonumber(ComponentGetValue( inventorycomponents, \"full_inventory_slots_y\" )) + 2\n		ComponentSetValue( inventorycomponents, \"full_inventory_slots_y\", inventorysize )\n	end\n\nend \n"
_TWWE_VFS["mods/x3inventory/mod.xml"] = "<Mod\n	name=\"x3 Inventory\"\n	description=\"Add spell inventory slots\"\n>\n</Mod>\n"
_TWWE_VFS["mods/x3inventory/mod_id.txt"] = "x3inventory"
_TWWE_VFS["mods/x3inventory/version.txt"] = "1.0.0\n"
_TWWE_VFS["mods/twwe_mock/gen_0.lua"] = "local function table_insert_all (new_actions)\r\n	for i,v in ipairs(new_actions) do\r\n		table.insert (actions, v)\r\n	end\r\nend\r\n\r\nlocal new_actions = {\r\n	\r\n	--* MODIFIERS \r\n	\r\n	{\r\n		id          = \"FOLLOW_CURSOR\",\r\n		name 		= \"Cursor following\",\r\n		description = \"Makes a projectile follow your crosshair\",\r\n		sprite 		= \"mods/nobys_things/mod_data/images/ui_gfx/cursor_follow.png\",\r\n		sprite_unidentified = \"data/ui_gfx/gun_actions/sinewave_unidentified.png\",\r\n		related_extra_entities = \"mods/nobys_things/mod_data/entities/misc/cursor_follow.xml\",\r\n		type 		= ACTION_TYPE_MODIFIER,\r\n		spawn_level                       = \"1,2,3,4,5,6\", -- HOMING\r\n		spawn_probability                 = \"0.1,0.4,0.4,0.4,0.4,0.4\", -- HOMING\r\n		price = 220,\r\n		mana = 40,\r\n		action 		= function()\r\n			c.extra_entities = c.extra_entities .. \"mods/nobys_things/mod_data/entities/misc/cursor_follow.xml,\"\r\n			draw_actions( 1, true )\r\n		end,\r\n	},\r\n	{\r\n		id          = \"HOMING_CURSOR_REAL\",\r\n		name 		= \"Cursor homing\",\r\n		description = \"Makes a projectile accelerate towards your crosshair\",\r\n		sprite 		= \"mods/nobys_things/mod_data/images/ui_gfx/cursor_homing.png\",\r\n		sprite_unidentified = \"data/ui_gfx/gun_actions/sinewave_unidentified.png\",\r\n		related_extra_entities = \"mods/nobys_things/mod_data/entities/misc/cursor_homing.xml\",\r\n		type 		= ACTION_TYPE_MODIFIER,\r\n		spawn_level                       = \"1,2,3,4,5,6\", -- HOMING\r\n		spawn_probability                 = \"0.1,0.4,0.4,0.4,0.4,0.4\", -- HOMING\r\n		price = 220,\r\n		mana = 60,\r\n		action 		= function()\r\n			c.extra_entities = c.extra_entities .. \"mods/nobys_things/mod_data/entities/misc/cursor_homing.xml,\"\r\n			draw_actions( 1, true )\r\n		end,\r\n	},\r\n	{\r\n		id          = \"GRAVITY_DISABLE\",\r\n		name 		= \"Disable gravity\",\r\n		description = \"Makes projectile unaffected by gravity\",\r\n		spri